#!/usr/bin/env bash
STACK_MANAGER_VERSION="1.0.43"
# =====================================================================
# stack-manager.sh вЂ” СѓРїСЂР°РІР»РµРЅРёРµ SNI-СЃС‚РµРєРѕРј (3x-ui/LucX + AdGuard)
#   - РЈСЃС‚Р°РЅРѕРІРєР° AdGuard Home (РµСЃР»Рё РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ)
#   - РЈСЃС‚Р°РЅРѕРІРєР° РїР°РЅРµР»Рё LucX UI (РµСЃР»Рё РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°)
#   - РЎРѕР·РґР°РЅРёРµ РёРЅР±Р°СѓРЅРґРѕРІ С‡РµСЂРµР· СЃРєСЂРёРїС‚ (Р°РІС‚РѕРѕРїСЂРµРґРµР»РµРЅРёРµ СЃС…РµРјС‹ Р‘Р”)
#   - SNI-СЂРѕСѓС‚РµСЂ РЅР° 443
#   - Decoy: РїР°РЅРµР»СЊ (stub / AdGuard+DoH), Reality
#   - fail2ban, UFW, Р±СЌРєР°РїС‹, СЃРµСЂС‚РёС„РёРєР°С‚С‹, DNS Xray
# =====================================================================
set -o pipefail

G=$'\033[0;32m'; R=$'\033[0;31m'; Y=$'\033[1;33m'; B=$'\033[0;36m'; N=$'\033[0m'
# ANSI-С†РІРµС‚Р° С‚РѕР»СЊРєРѕ РІ РёРЅС‚РµСЂР°РєС‚РёРІРЅРѕРј С‚РµСЂРјРёРЅР°Р»Рµ: РїР°Р№РїС‹/Р±РѕС‚С‹/Р»РѕРі-С„Р°Р№Р»С‹ РїРѕР»СѓС‡Р°СЋС‚ С‡РёСЃС‚С‹Р№ С‚РµРєСЃС‚
[[ -t 1 ]] || { G=""; R=""; Y=""; B=""; N=""; }
log()  { echo -e "${G}[+]${N} $*"; }
warn() { echo -e "${Y}[!]${N} $*"; }
# Р›СЋР±Р°СЏ РѕС€РёР±РєР° РІ РёРЅС‚РµСЂР°РєС‚РёРІРЅРѕРј СЂРµР¶РёРјРµ РґРѕР»Р¶РЅР° Р±С‹С‚СЊ Р·Р°РјРµС‡РµРЅР° РїРѕР»СЊР·РѕРІР°С‚РµР»РµРј:
# РїРµС‡Р°С‚Р°РµРј РєРѕСЂРѕС‚РєСѓСЋ СЂРµРєРѕРјРµРЅРґР°С†РёСЋ Рё Р¶РґС‘Рј Enter. Р­С‚Рѕ Р·Р°С‰РёС‰Р°РµС‚ РѕС‚ СЃРёС‚СѓР°С†РёРё,
# РєРѕРіРґР° РІР°Р¶РЅС‹Р№ РѕС‚РєР°Р· РїСЂРѕРєСЂСѓС‡РёРІР°РµС‚СЃСЏ СЃР»РµРґСѓСЋС‰РёРјРё СЃРѕРѕР±С‰РµРЅРёСЏРјРё.
ERROR_PAUSED=0
error_recommendation() {
  local __m="$*" __r="РџСЂРѕРІРµСЂСЊС‚Рµ РїСЂРёС‡РёРЅСѓ РІС‹С€Рµ; РёСЃРїСЂР°РІСЊС‚Рµ РµС‘ Рё РїРѕРІС‚РѕСЂРёС‚Рµ СЌС‚РѕС‚ РїСѓРЅРєС‚."
  case "$__m" in
    *СЃРµСЂС‚РёС„РёРєР°С‚*|*СЃРµСЂС‚*|*certbot*|*CERT*)
      __r="РџСЂРѕРІРµСЂСЊС‚Рµ DNS A/AAAA, РґРѕСЃС‚СѓРїРЅРѕСЃС‚СЊ РїРѕСЂС‚Р° 80 Рё Р»РёРјРёС‚С‹ Let's Encrypt; Р·Р°С‚РµРј РїРѕРІС‚РѕСЂРёС‚Рµ РІС‹РїСѓСЃРє СЃРµСЂС‚РёС„РёРєР°С‚Р°." ;;
    *DNS*|*dns*|*СЂРµР·РѕР»РІ*|*СЂР°Р·СЂРµС€*)
      __r="РџСЂРѕРІРµСЂСЊС‚Рµ A/AAAA-Р·Р°РїРёСЃСЊ РґРѕРјРµРЅР°: РѕРЅР° РґРѕР»Р¶РЅР° СѓРєР°Р·С‹РІР°С‚СЊ РЅР° СЌС‚РѕС‚ СЃРµСЂРІРµСЂ; РїРѕСЃР»Рµ РѕР±РЅРѕРІР»РµРЅРёСЏ DNS РїРѕРІС‚РѕСЂРёС‚Рµ РѕРїРµСЂР°С†РёСЋ." ;;
    *РїРѕСЂС‚*|*Port*|*listen*|*Р·Р°РЅСЏС‚*)
      __r="РџСЂРѕРІРµСЂСЊС‚Рµ, РєР°РєРѕРµ РїСЂРёР»РѕР¶РµРЅРёРµ Р·Р°РЅСЏР»Рѕ РїРѕСЂС‚ (ss -lntup); РІС‹Р±РµСЂРёС‚Рµ СЃРІРѕР±РѕРґРЅС‹Р№ РїРѕСЂС‚ РёР»Рё РѕСЃС‚Р°РЅРѕРІРёС‚Рµ РєРѕРЅС„Р»РёРєС‚СѓСЋС‰СѓСЋ СЃР»СѓР¶Р±Сѓ." ;;
    *nginx*|*Nginx*)
      __r="РџСЂРѕРІРµСЂСЊС‚Рµ РєРѕРЅС„РёРіСѓСЂР°С†РёСЋ РєРѕРјР°РЅРґРѕР№ nginx -t Рё Р¶СѓСЂРЅР°Р» systemctl status nginx; РїРѕСЃР»Рµ РёСЃРїСЂР°РІР»РµРЅРёСЏ РїРѕРІС‚РѕСЂРёС‚Рµ." ;;
    *UFW*|*С„Р°РµСЂРІРѕР»*|*firewall*)
      __r="РџСЂРѕРІРµСЂСЊС‚Рµ РїСЂР°РІРёР»Р° UFW Рё РІСЂРµРјРµРЅРЅРѕ СЂР°Р·СЂРµС€РёС‚Рµ С‚РѕР»СЊРєРѕ РЅРµРѕР±С…РѕРґРёРјС‹Р№ РїРѕСЂС‚; Р·Р°С‚РµРј РїРѕРІС‚РѕСЂРёС‚Рµ РѕРїРµСЂР°С†РёСЋ." ;;
    *x-ui*|*Xray*|*РёРЅР±Р°СѓРЅРґ*)
      __r="РџСЂРѕРІРµСЂСЊС‚Рµ СЃРѕСЃС‚РѕСЏРЅРёРµ x-ui/Xray Рё Р¶СѓСЂРЅР°Р» journalctl -u x-ui; РёСЃРїСЂР°РІСЊС‚Рµ РїСЂРёС‡РёРЅСѓ Рё РїРѕРІС‚РѕСЂРёС‚Рµ РЅР°СЃС‚СЂРѕР№РєСѓ РёРЅР±Р°СѓРЅРґР°." ;;
  esac
  echo -e "${Y}[>] Р РµРєРѕРјРµРЅРґР°С†РёСЏ: ${__r}${N}" >&2
}
err() {
  echo -e "${R}[x]${N} $*" >&2
  error_recommendation "$*"
  # Р’ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРѕРј/РЅРµ-TTY Р·Р°РїСѓСЃРєРµ РЅРµ Р±Р»РѕРєРёСЂСѓРµРј РїР°Р№РїР»Р°Р№РЅ.
  if [[ -t 0 ]]; then
    ERROR_PAUSED=1
    pause
  fi
}
ok()   { echo -e "${G}[вњ“]${N} $*"; }
line() { echo -e "${B}в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ${N}"; }

# РђСѓРґРёС‚ РґРµР№СЃС‚РІРёР№: РєР°Р¶РґР°СЏ РѕРїРµСЂР°С†РёСЏ, РјРµРЅСЏСЋС‰Р°СЏ СЃРёСЃС‚РµРјСѓ, вЂ” СЃС‚СЂРѕРєР° РІ Р¶СѓСЂРЅР°Р».
audit() {
  local f="${ACTION_LOG:-/root/stack-actions.log}"
  printf '%s root%s | %s\n' "$(date '+%F %T')" "${SUDO_USER:+ (sudo:$SUDO_USER)}" "$*" >> "$f" 2>/dev/null || true
}

# РЎРёРіРЅР°С‚СѓСЂР° html-С„Р°Р№Р»РѕРІ РєР°С‚Р°Р»РѕРіР° С€Р°Р±Р»РѕРЅРѕРІ вЂ” С‡С‚РѕР±С‹ РёРЅРёС‚С‹ РїРµС‡Р°С‚Р°Р»Рё В«РіРѕС‚РѕРІРѕВ»
# С‚РѕР»СЊРєРѕ РєРѕРіРґР° СЂРµР°Р»СЊРЅРѕ С‡С‚Рѕ-С‚Рѕ СЃРѕР·РґР°Р»Рё, Р° РЅРµ РїСЂРё РєР°Р¶РґРѕРј Р·Р°РїСѓСЃРєРµ.
dir_sig() {
  find "$1" -maxdepth 1 -type f -name '*.html' -print0 2>/dev/null \
    | sort -z | xargs -0 -r md5sum 2>/dev/null | md5sum | awk '{print $1}'
}

[[ $EUID -eq 0 ]] || { err "Р—Р°РїСѓСЃС‚РёС‚Рµ РѕС‚ root (sudo $0)"; exit 1; }
export DEBIAN_FRONTEND=noninteractive
# РЎС‚Р°Р±РёР»СЊРЅС‹Р№ EN-РІС‹РІРѕРґ subprocess (ufw/systemctl/certbot): RU-Р»РѕРєР°Р»СЊ РґР°С‘С‚
# В«РЎС‚Р°С‚СѓСЃ: Р°РєС‚РёРІРµРЅВ» Рё Р»РѕРјР°РµС‚ РїР°СЂСЃРёРЅРі. РЎРѕР±СЃС‚РІРµРЅРЅС‹Рµ RU-СЃРѕРѕР±С‰РµРЅРёСЏ СЃРєСЂРёРїС‚Р° РЅРµ СЃС‚СЂР°РґР°СЋС‚.
# UTF-8 РѕР±СЏР·Р°С‚РµР»РµРЅ РґР»СЏ РєРѕСЂСЂРµРєС‚РЅРѕРіРѕ Backspace РІ Bash Readline.
export LC_ALL=C.UTF-8 LANG=C.UTF-8
read_safe() {
  local __prompt="$1" __var="$2"
  builtin read -e -r -p "$__prompt" "$__var"
}

BACKUP_DIR="/root/stack-backups"
# Р”Рѕ СЏРІРЅРѕР№ РЅР°СЃС‚СЂРѕР№РєРё С‡РµСЂРµР· РјРµРЅСЋ СЃРєСЂРёРїС‚ СЂР°Р±РѕС‚Р°РµС‚ С‚РѕР»СЊРєРѕ РІ СЂРµР¶РёРјРµ С‡С‚РµРЅРёСЏ.
# Р­С‚РѕС‚ РјР°СЂРєРµСЂ СЃРѕР·РґР°С‘С‚СЃСЏ С‚РѕР»СЊРєРѕ РїРѕСЃР»Рµ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ РЅР°СЃС‚СЂРѕР№РєРё РїРѕР»СЊР·РѕРІР°С‚РµР»РµРј.
STACK_CONFIGURED_FILE="/root/stack-backups/.stack-configured"
FW_STATE_DIR="/root/stack-backups/firewall-state"
ACTION_LOG="/root/stack-actions.log"

# РЎС‚Р°СЂС‹Рµ РІРµСЂСЃРёРё РЅРµ РІСЃРµРіРґР° СЃРѕР·РґР°РІР°Р»Рё .stack-configured. Р•СЃР»Рё СЃС‚РµРє СѓР¶Рµ Р±С‹Р»
# СѓСЃС‚Р°РЅРѕРІР»РµРЅ/РїРѕРґРЅСЏС‚ СЃР°РјРёРј stack-manager, СЂР°СЃРїРѕР·РЅР°С‘Рј РµРіРѕ РїРѕ legacy-РјР°СЂРєРµСЂСѓ
# Р·Р°РїСѓСЃРєР° Рё СЂРµР°Р»СЊРЅРѕ СЃРѕР·РґР°РЅРЅС‹Рј Р°СЂС‚РµС„Р°РєС‚Р°Рј. Р­С‚Рѕ РІР°Р¶РЅРѕ РїРѕСЃР»Рµ РѕР±РЅРѕРІР»РµРЅРёСЏ СЃС‚Р°СЂРѕР№
# РІРµСЂСЃРёРё: СЃСѓС‰РµСЃС‚РІСѓСЋС‰СѓСЋ СЂР°Р±РѕС‡СѓСЋ СѓСЃС‚Р°РЅРѕРІРєСѓ РЅРµР»СЊР·СЏ РѕС€РёР±РѕС‡РЅРѕ СЃС‡РёС‚Р°С‚СЊ В«РїРµСЂРІС‹Рј
# Р·Р°РїСѓСЃРєРѕРјВ» Рё Р·Р°РєСЂС‹РІР°С‚СЊ РїРѕР»СЊР·РѕРІР°С‚РµР»СЋ СЂР°Р·РґРµР»С‹ РјРµРЅСЋ.
stack_legacy_installed() {
  [[ -f "$BACKUP_DIR/.stack-ever-ran" ]] || return 1
  [[ -n "${XUI_DB:-}" && -f "$XUI_DB" ]] || return 1
  [[ -f "$STACK_CONF" ]] || return 1
  [[ -f /etc/nginx/streams-available/sni-router.conf || -f "$SNI_CONF" ]] || return 1
  return 0
}
stack_is_configured() {
  [[ -f "$STACK_CONFIGURED_FILE" ]] && return 0
  # РњРёРіСЂР°С†РёСЏ legacy-СѓСЃС‚Р°РЅРѕРІРєРё: РјР°СЂРєРµСЂ СЃРѕР·РґР°С‘С‚СЃСЏ С‚РѕР»СЊРєРѕ РїСЂРё РЅР°Р»РёС‡РёРё РІСЃРµС…
  # РѕСЃРЅРѕРІРЅС‹С… Р°СЂС‚РµС„Р°РєС‚РѕРІ, Р° РЅРµ РїСЂРѕСЃС‚Рѕ РёР·-Р·Р° СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕР№ РїР°РЅРµР»Рё.
  stack_legacy_installed || return 1
  stack_mark_configured
}
stack_mark_configured() {
  mkdir -p "$BACKUP_DIR" 2>/dev/null || return 1
  printf '%s\n' "configured=$(date '+%F %T')" > "$STACK_CONFIGURED_FILE" 2>/dev/null
}

# Wildcard-СЃРµСЂС‚РёС„РёРєР°С‚ Cloudflare (РѕРґРёРЅ РЅР° РІСЃРµ РїРѕРґРґРѕРјРµРЅС‹ Р±Р°Р·РѕРІРѕРіРѕ РґРѕРјРµРЅР°)
WILDCARD_DOMAIN=""
WILDCARD_STATE="/root/stack-backups/wildcard-domain"
CF_CREDS="/root/.secrets/cloudflare.ini"
CERT_DOMAINS_FILE="/etc/letsencrypt/stack-domains.txt"
# Р РµР¶РёРј РІС‹РїСѓСЃРєР° СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ (A/B): С„Р°Р№Р» + РїРµСЂРµРјРµРЅРЅР°СЏ (СЃРј. cert_mode_*)
CERT_MODE=""
CERT_MODE_FILE="/root/stack-backups/cert-mode"
# Р¤Р°Р№Р»С‹ Р»РёРЅРёР№ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ (РґР»СЏ СЂРµР¶РёРјР° B вЂ” РЅРµСЃРєРѕР»СЊРєРѕ Р»РёРЅРёР№)
#   /root/stack-backups/cert-lines.txt              в†’ СЃРїРёСЃРѕРє РёРјС‘РЅ Р»РёРЅРёР№
#   /root/stack-backups/cert-line-<РёРјСЏ>.domains     в†’ SAN СЌС‚РѕР№ Р»РёРЅРёРё (РїРѕ СЃС‚СЂРѕРєРµ)
CERT_LINES_FILE="/root/stack-backups/cert-lines.txt"
CERT_LINE_FILE_PREFIX="/root/stack-backups/cert-line-"
# Р–СѓСЂРЅР°Р» РѕС‚РєР°С‚Р°: С‡С‚Рѕ СЃРєСЂРёРїС‚ РїРѕРјРµРЅСЏР» РІ РїР°РЅРµР»Рё вЂ” С‚Рѕ Рё РІРѕР·РІСЂР°С‰Р°РµС‚
PANEL_JOURNAL="/root/stack-backups/panel-journal.tsv"
LISTEN_JOURNAL="/root/stack-backups/inbound-listen.tsv"
ROWS_JOURNAL="/root/stack-backups/rows-journal.tsv"   # РїРѕР»РЅС‹Рµ СЃС‚СЂРѕРєРё inbounds/hosts
JOURNAL_MARK="/root/stack-backups/.panel-journal-started"
DB_BIN="/usr/bin/sqlite3"
# =====================================================================
# CDN-СЂРµР¶РёРј XHTTP (СЃРј. xhttp_cdn_setup): РёРЅР±Р°СѓРЅРґ Р»СЋР±РѕРіРѕ РїСЂРѕС‚РѕРєРѕР»Р° СЃ
# С‚СЂР°РЅСЃРїРѕСЂС‚РѕРј xhttp РїРµСЂРµРІРѕРґРёС‚СЃСЏ РІ security=none (РіРѕР»С‹Р№ HTTP РЅР° loopback),
# TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx. Р•РґРёРЅС‹Р№ Р»РѕРєР°Р»СЊРЅС‹Р№ SSL-С„СЂРѕРЅС‚РµРЅРґ + tsv-РїСЂРѕС„РёР»Рё.
# =====================================================================
CDN_FE_PORT=47443                                        # Р»РѕРєР°Р»СЊРЅС‹Р№ ssl-С„СЂРѕРЅС‚РµРЅРґ nginx (http{})
CDN_PROFILES="/root/stack-backups/cdn-profiles.tsv"      # id|proto|origin|cdn|path|tpl|decoy_port|provider
CDN_FORCE_IDS=""                                         # РёРЅР±Р°СѓРЅРґС‹, РІС‹Р±СЂР°РЅРЅС‹Рµ РјР°СЃС‚РµСЂРѕРј РєР°Рє CDN
declare -a CERT_LINES=()
CERT_MULTI_NAME=""           # РґРёРЅР°РјРёС‡РµСЃРєРё = РґРѕРјРµРЅ РїР°РЅРµР»Рё (cert_multi_name_resolve)
CERT_DEFER=0
CERT_BATCH_ENABLED=1
declare -a CERT_DOMAINS=()

# РЎРѕС…СЂР°РЅРµРЅРёРµ email Let's Encrypt (РїРµСЂРµР¶РёРІР°РµС‚ РїРµСЂРµР·Р°РїСѓСЃРєРё СЃРєСЂРёРїС‚Р°)
LE_EMAIL_FILE="/root/stack-backups/le-email"


NGINX_STREAM_DIR="/etc/nginx/streams-enabled"
NGINX_SITES_DIR="/etc/nginx/sites-enabled"
NGINX_SITES_AVAIL="/etc/nginx/sites-available"
STACK_CONF="$NGINX_SITES_AVAIL/stack.conf"     # РµРґРёРЅС‹Р№ http-РєРѕРЅС„РёРі: ACME :80 + РїР°РЅРµР»СЊ :4443 + РІСЃРµ decoy
STACK_LINK="$NGINX_SITES_DIR/stack.conf"       # СЃРёРјР»РёРЅРє РІ sites-enabled
SNI_CONF="$NGINX_STREAM_DIR/sni-router.conf"
PANEL_DECOY_DIR="/var/www/panel-decoy"
DECOY_TPL_DIR="/var/www/decoy-templates"
DECOY_LOGIN_DIR="/var/www/decoy-login"
DECOY_LOG_ACCESS="/var/log/nginx/decoy-access.log"
# Р’РЅРµС€РЅРёРµ С‚Р°СЂРіРµС‚С‹ РґР»СЏ Reality Р‘Р•Р— СЃРІРѕРµРіРѕ SNI: dest = <С…РѕСЃС‚>:443, serverNames = [С…РѕСЃС‚].
# РЎРїРёСЃРѕРє вЂ” РєР°Рє В«РЅР°Р№С‚Рё С†РµР»РёВ» РІ РїР°РЅРµР»Рё (РєСЂСѓРїРЅС‹Рµ РїР»РѕС‰Р°РґРєРё СЃРѕ СЃС‚Р°Р±РёР»СЊРЅС‹Рј TLS 1.3 + h2).
REALITY_TARGETS=(
  "www.cloudflare.com"
  "dl.google.com"
  "www.amazon.com"
  "aws.amazon.com"
  "www.amd.com"
  "www.microsoft.com"
  "www.nvidia.com"
  "www.samsung.com"
  "www.intel.com"
  "www.sony.com"
)
# РџРµС‡Р°С‚Р°РµС‚ С…РѕСЃС‚-С‚Р°СЂРіРµС‚ РґР»СЏ РёРЅР±Р°СѓРЅРґР° Р±РµР· СЃРІРѕРµРіРѕ SNI (СЃРёРґ = id РёРЅР±Р°СѓРЅРґР°, РґРµС‚РµСЂРјРёРЅРёСЂРѕРІР°РЅРЅРѕ)
reality_pick_target() {
  local n=${#REALITY_TARGETS[@]}
  printf '%s' "${REALITY_TARGETS[$(( (${1:-0} + RANDOM) % n ))]}"
}

# РњРµРЅСЋ В«РЅР°Р№С‚Рё С†РµР»РёВ» СЃ Р¶РёРІРѕР№ РїСЂРѕРІРµСЂРєРѕР№ (TLS 1.3 + h2) вЂ” РєР°Рє РєРЅРѕРїРєР° РІ РїР°РЅРµР»Рё.
#   $1 = РїРµСЂРµРјРµРЅРЅР°СЏ СЂРµР·СѓР»СЊС‚Р°С‚Р°, $2 = РёРјСЏ РёРЅР±Р°СѓРЅРґР° (РґР»СЏ Р·Р°РіРѕР»РѕРІРєР°)
reality_target_menu() {
  local __v="$1" cname="${2:-reality}" _i=1 _c _st _out rt=""
  echo >&2
  echo -e "${B}Reality В«РЅР°Р№С‚Рё С†РµР»РёВ» вЂ” РєР°РЅРґРёРґР°С‚С‹ (РЅСѓР¶РµРЅ TLS 1.3 + h2):${N}" >&2
  for _c in "${REALITY_TARGETS[@]}"; do
    _out=$(timeout 4 openssl s_client -connect "$_c:443" -servername "$_c" -alpn h2 </dev/null 2>/dev/null || true)
    if grep -q "TLSv1.3" <<<"$_out" && grep -q "ALPN protocol: h2" <<<"$_out"; then
      _st="вњ“ TLS1.3+h2"
    else
      _st="вњ— РЅРµ РѕС‚РІРµС‡Р°РµС‚"
    fi
    printf "  %2d) %-22s %s\n" "$_i" "$_c" "$_st" >&2; _i=$((_i+1))
  done
  if [[ ! -t 0 ]]; then
    printf -v "$__v" '%s' "$(reality_find_target 1)"
    return 0
  fi
  ask rt "Р¦РµР»СЊ РґР»СЏ В«$cnameВ» (1-${#REALITY_TARGETS[@]})" "1" '^[0-9]+$'
  if (( rt >= 1 && rt <= ${#REALITY_TARGETS[@]} )); then
    printf -v "$__v" '%s' "${REALITY_TARGETS[$((rt-1))]}"
  else
    printf -v "$__v" '%s' "$(reality_find_target 1)"
  fi
  return 0
}

# В«РќР°Р№С‚Рё С†РµР»РёВ» РєР°Рє РєРЅРѕРїРєР° РІ РїР°РЅРµР»Рё: РїРµСЂРµР±РёСЂР°РµРј РєР°РЅРґРёРґР°С‚РѕРІ Рё Р±РµСЂС‘Рј РїРµСЂРІС‹Р№, РєС‚Рѕ
# РѕС‚РІРµС‡Р°РµС‚ TLS 1.3 + ALPN h2 (РёРјРµРЅРЅРѕ СЌС‚Рѕ Reality С‚СЂРµР±СѓРµС‚ РѕС‚ РІРЅРµС€РЅРµРіРѕ С‚Р°СЂРіРµС‚Р°).
# РљРµС€ вЂ” РІ С„Р°Р№Р»: С„СѓРЅРєС†РёСЏ РІС‹Р·С‹РІР°РµС‚СЃСЏ С‡РµСЂРµР· $(вЂ¦) Рё РіР»РѕР±Р°Р»СЊРЅС‹Рµ РїРµСЂРµРјРµРЅРЅС‹Рµ РЅРµ РїРµСЂРµР¶РёРІР°СЋС‚ subshell.
reality_find_target() {
  local cf="/tmp/.reality-found-target"
  [[ -s "$cf" ]] && { printf '%s' "$(cat "$cf" 2>/dev/null)"; return 0; }
  local c out
  for c in "${REALITY_TARGETS[@]}"; do
    out=$(timeout 6 openssl s_client -connect "$c:443" -servername "$c" -alpn h2 </dev/null 2>/dev/null || true)
    if grep -q "TLSv1.3" <<<"$out" && grep -q "ALPN protocol: h2" <<<"$out"; then
      printf '%s' "$c" > "$cf" 2>/dev/null || true
      printf '%s' "$c"
      return 0
    fi
  done
  # РЅРё РѕРґРёРЅ РЅРµ РїСЂРѕС€С‘Р» Р¶РёРІСѓСЋ РїСЂРѕРІРµСЂРєСѓ вЂ” fallback РЅР° РІС‹Р±РѕСЂ РёР· СЃРїРёСЃРєР°
  reality_pick_target "${1:-0}"
}
