# =====================================================================
# Р’Р’РћР”
# =====================================================================
ask() {
  # РІРЅСѓС‚СЂРµРЅРЅРёРµ РёРјРµРЅР° СЃ __: РµСЃР»Рё С†РµР»РµРІР°СЏ РїРµСЂРµРјРµРЅРЅР°СЏ С‚РѕР¶Рµ РЅР°Р·С‹РІР°РµС‚СЃСЏ d/in/p/r,
  # printf -v РїРѕРїР°РґР°Р» РІ Р»РѕРєР°Р»СЊРЅСѓСЋ ask, Р° РЅРµ РІ РІС‹Р·С‹РІР°СЋС‰СѓСЋ С„СѓРЅРєС†РёСЋ (РїРѕС‚РµСЂСЏ РІРІРѕРґР°)
  local __v="$1" __p="$2" __d="$3" __r="${4:-}" __in
  while :; do
    # Р•РґРёРЅС‹Р№ read РґР»СЏ РѕР±РµРёС… РІРµС‚РѕРє: EOF-Р·Р°С‰РёС‚Р° РѕР±СЏР·Р°С‚РµР»СЊРЅР° РІ РћР‘Р•РРҐ. Р Р°РЅСЊС€Рµ
    # РІРµС‚РєР° Р±РµР· РґРµС„РѕР»С‚Р° РєСЂСѓС‚РёР»Р°СЃСЊ РІРµС‡РЅРѕ: EOF в†’ РїСѓСЃС‚РѕР№ РѕС‚РІРµС‚ в†’ regex РјРёРјРѕ в†’
    # В«РќРµРєРѕСЂСЂРµРєС‚РЅРѕВ» в†’ СЃРЅРѕРІР° read (90k РѕС€РёР±РѕРє РІ Р°РІС‚Рѕ-СѓСЃС‚Р°РЅРѕРІРєРµ 28.10).
    if ! read_safe "? ${__p}${__d:+ [${__d}]}: " __in; then
      if [[ -n "$__d" ]]; then
        warn "Р’РІРѕРґ Р·Р°РІРµСЂС€С‘РЅ (EOF) вЂ” РїСЂРёРЅСЏС‚Рѕ Р·РЅР°С‡РµРЅРёРµ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ: $__d"
        __in="$__d"
      elif [[ ! -t 0 ]]; then
        warn "Р’РІРѕРґ Р·Р°РІРµСЂС€С‘РЅ (EOF, Р°РІС‚Рѕ-РѕС‚РІРµС‚С‹) вЂ” РїСѓСЃС‚РѕР№ РѕС‚РІРµС‚"
        __in=""
      else
        warn "Р’РІРѕРґ Р·Р°РІРµСЂС€С‘РЅ (EOF) вЂ” РІРѕР·РІСЂР°С‚ РІ РјРµРЅСЋ"
        exit 42
      fi
    fi
    # РЈР±РёСЂР°РµРј CR РѕС‚ Windows/РІСЃС‚Р°РІРєРё Рё РїСЂРѕР±РµР»С‹ РІРѕРєСЂСѓРі РѕС‚РІРµС‚Р°.
    __in="${__in//$'\r'/}"
    __in="${__in#"${__in%%[![:space:]]*}"}"
    __in="${__in%"${__in##*[![:space:]]}"}"
    [[ -z "$__in" && -n "$__d" ]] && __in="$__d"
    case "${__in,,}" in
      q|quit|exit|РІС‹С…РѕРґ)
        warn "РџСЂРµСЂРІР°РЅРѕ вЂ” РІРѕР·РІСЂР°С‚ РІ РјРµРЅСЋ"
        exit 42 ;;          # РїРѕРґ-РѕР±РѕР»РѕС‡РєР° РїСѓРЅРєС‚Р° РјРµРЅСЋ Р»РѕРІРёС‚ 42 в†’ РЅР°Р·Р°Рґ РІ РјРµРЅСЋ
    esac
    [[ -z "$__r" || "$__in" =~ $__r ]] && { printf -v "$__v" '%s' "$__in"; return; }
    if [[ ! -t 0 ]]; then
      # РђРІС‚Рѕ-РѕС‚РІРµС‚С‹ (С„Р°Р№Р»/РїР°Р№Рї): РїРѕРІС‚РѕСЂРЅС‹Р№ read Р±РµСЃРїРѕР»РµР·РµРЅ вЂ” РІРµСЂРЅС‘С‚СЃСЏ С‚Рѕ Р¶Рµ
      # СЃР°РјРѕРµ. РџСЂРёРЅРёРјР°РµРј РєР°Рє РµСЃС‚СЊ, С‡С‚РѕР±С‹ СЂР°СЃСЃРёРЅС…СЂРѕРЅ Р°РЅРєРµС‚С‹ РЅРµ РїСЂРµРІСЂР°С‰Р°Р»СЃСЏ
      # РІ Р±РµСЃРєРѕРЅРµС‡РЅС‹Р№ СЃРїРёРЅ В«РќРµРєРѕСЂСЂРµРєС‚РЅРѕВ».
      warn "РђРІС‚Рѕ-РѕС‚РІРµС‚ РЅРµ РїСЂРѕС€С‘Р» РїСЂРѕРІРµСЂРєСѓ (${__p}) вЂ” РїСЂРёРЅСЏС‚Рѕ РєР°Рє РµСЃС‚СЊ: ${__in:-<РїСѓСЃС‚Рѕ>}"
      printf -v "$__v" '%s' "$__in"
      return
    fi
    err "РќРµРєРѕСЂСЂРµРєС‚РЅРѕ."
  done
}

askyn() {
  local __v="$1" __p="$2" __d="$3" __in
  while :; do
    # РќРµ Р·Р°С†РёРєР»РёРІР°С‚СЊСЃСЏ РїСЂРё stdin Р±РµР· TTY/EOF (РЅР°РїСЂРёРјРµСЂ, Р·Р°РїСѓСЃРє С‡РµСЂРµР· tee):
    # РІ СЌС‚РѕРј СЃР»СѓС‡Р°Рµ Р±РµР·РѕРїР°СЃРЅРѕ РїСЂРёРЅСЏС‚СЊ Р·РЅР°С‡РµРЅРёРµ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ.
    if ! read_safe "? ${__p} [${__d}]: " __in; then
      warn "Р’РІРѕРґ РЅРµРґРѕСЃС‚СѓРїРµРЅ (EOF) вЂ” РїСЂРёРЅСЏС‚Рѕ Р·РЅР°С‡РµРЅРёРµ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ: $__d"
      __in="$__d"
    fi
    # РЈР±РёСЂР°РµРј CR РѕС‚ Windows/РІСЃС‚Р°РІРєРё Рё РїСЂРѕР±РµР»С‹ РІРѕРєСЂСѓРі РѕС‚РІРµС‚Р°.
    __in="${__in//$'\r'/}"
    __in="${__in#"${__in%%[![:space:]]*}"}"
    __in="${__in%"${__in##*[![:space:]]}"}"
    __in="${__in:-$__d}"
    case "${__in,,}" in
      q|quit|exit|РІС‹С…РѕРґ)
        warn "РџСЂРµСЂРІР°РЅРѕ вЂ” РІРѕР·РІСЂР°С‚ РІ РјРµРЅСЋ"
        exit 42 ;;
      y|yes|Рґ|РґР°) printf -v "$__v" 'true'; return;;
      n|no|РЅ|РЅРµС‚) printf -v "$__v" 'false'; return;;
    esac
    if [[ ! -t 0 ]]; then
      # РђРІС‚Рѕ-РѕС‚РІРµС‚С‹: РїРѕРІС‚РѕСЂ Р±РµСЃРїРѕР»РµР·РµРЅ вЂ” Р±РµСЂС‘Рј РґРµС„РѕР»С‚, РЅРµ РєСЂСѓС‚РёРј В«y/nВ».
      if [[ "${__d:0:1}" == "y" || "${__d:0:1}" == "Рґ" ]]; then
        warn "РђРІС‚Рѕ-РѕС‚РІРµС‚ РЅРµ СЂР°СЃРїРѕР·РЅР°РЅ (${__p}) вЂ” РїСЂРёРЅСЏС‚Рѕ Р·РЅР°С‡РµРЅРёРµ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ: $__d"
        printf -v "$__v" 'true'
      else
        warn "РђРІС‚Рѕ-РѕС‚РІРµС‚ РЅРµ СЂР°СЃРїРѕР·РЅР°РЅ (${__p}) вЂ” РїСЂРёРЅСЏС‚Рѕ Р·РЅР°С‡РµРЅРёРµ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ: ${__d:-n}"
        printf -v "$__v" 'false'
      fi
      return
    fi
    err "y/n"
  done
}

pause() { read_safe "РќР°Р¶РјРёС‚Рµ Enter" _; }
# РћС€РёР±РєР° СЃРµСЂС‚РёС„РёРєР°С‚Р° РЅРµ РґРѕР»Р¶РЅР° РёСЃС‡РµР·Р°С‚СЊ СЃСЂРµРґРё РїРѕСЃР»РµРґСѓСЋС‰РёС… СЃРѕРѕР±С‰РµРЅРёР№.
# Р’ РёРЅС‚РµСЂР°РєС‚РёРІРЅРѕРј РјР°СЃС‚РµСЂРµ РѕР±СЏР·Р°С‚РµР»СЊРЅРѕ Р¶РґС‘Рј Enter; РІ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРѕРј Р·Р°РїСѓСЃРєРµ
# РЅРµ Р±Р»РѕРєРёСЂСѓРµРј stdin, РЅРѕ РїРѕР»РЅС‹Р№ С‚РµРєСЃС‚ РѕС€РёР±РєРё РІСЃС‘ СЂР°РІРЅРѕ РѕСЃС‚Р°С‘С‚СЃСЏ РІ Р»РѕРіРµ.
# STACK_AUTOPILOT=1 (РґРёРЅР°РјРёС‡РµСЃРєР°СЏ РѕР±Р»Р°СЃС‚СЊ stack_check_fix) вЂ” Р°РІС‚РѕРїРѕС‚РѕРє
# В«РїСЂРѕРІРµСЂРёС‚СЊ Рё РїРѕС‡РёРЅРёС‚СЊВ» РЅРёРєРѕРіРґР° РЅРµ РѕСЃС‚Р°РЅР°РІР»РёРІР°РµС‚СЃСЏ РґРѕ Enter (28.10).
cert_error_pause() {
  if [[ -t 0 && "${ERROR_PAUSED:-0}" != 1 && "${STACK_AUTOPILOT:-0}" != 1 ]]; then
    pause
  fi
  ERROR_PAUSED=0
}

# =====================================================================
# РџР РћР’Р•Р РљРђ РћРЎ
# =====================================================================
check_os() {
  if [[ -f /etc/os-release ]]; then
    # shellcheck disable=SC1091
    . /etc/os-release
    case "${ID:-}" in
      ubuntu) [[ "$VERSION_ID" == "24.04" || "$VERSION_ID" == "26.04" ]] && return 0 ;;
      debian) [[ "$VERSION_ID" == "12" || "$VERSION_ID" == "13" ]] && return 0 ;;
    esac
    warn "РћРЎ ${PRETTY_NAME:-РЅРµРёР·РІРµСЃС‚РЅР°} РЅРµ РІ СЃРїРёСЃРєРµ РїРѕРґРґРµСЂР¶РёРІР°РµРјС‹С…"
    sleep 2
  fi
  return 0
}

# =====================================================================
# РЈРўРР›РРўР«
# =====================================================================
# Р•РґРёРЅС‹Рµ РїСЂРѕРІРµСЂРєРё СЃРѕСЃС‚РѕСЏРЅРёСЏ СЃС‚РµРєР° вЂ” РЅРµ РґСѓР±Р»РёСЂРѕРІР°С‚СЊ РїСЂРѕРІРµСЂРєРё РїСѓС‚РµР№ РїРѕ РјРµРЅСЋ.
sni_router_present() {
  [[ -f "$SNI_CONF" || -f /etc/nginx/streams-enabled/sni-router.conf || -f /etc/nginx/streams-available/sni-router.conf ]]
}
stack_heal_present() {
  [[ -f /etc/systemd/system/stack-heal.timer || -f /etc/systemd/system/stack-heal.service ]] || \
    systemctl is-enabled --quiet stack-heal.timer 2>/dev/null || \
    systemctl is-active --quiet stack-heal.timer 2>/dev/null
}
nginx_ready() {
  command -v nginx >/dev/null 2>&1 && [[ -f /etc/nginx/nginx.conf ]]
}

# Р‘РµР·РѕРїР°СЃРЅРѕРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ СЃРІСЏР·РєРё SNI-С„Р°Р№Р»РѕРІ Р±РµР· РїРµСЂРµСЃРѕР·РґР°РЅРёСЏ РёРЅР±Р°СѓРЅРґРѕРІ.
# РќРёС‡РµРіРѕ РЅРµ РјРµРЅСЏРµС‚ РІ Р‘Р” Рё РЅРµ РіРµРЅРµСЂРёСЂСѓРµС‚ РЅРѕРІС‹Рµ РјР°СЂС€СЂСѓС‚С‹.

# РџРµСЂРµСЃР±РѕСЂРєР° SNI-РєР°СЂС‚С‹ РёР· С‚РµРєСѓС‰РµР№ Р‘Р”, Р±РµР· РёР·РјРµРЅРµРЅРёР№ Р‘Р” Рё СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ.
rebuild_sni_from_db() {
  line; echo -e "${B}   РџР•Р Р•РЎР‘РћР РљРђ SNI РР— РўР•РљРЈР©Р•Р™ Р‘Р”${N}"; line
  nginx_ready || { err "nginx РёР»Рё nginx.conf РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚"; pause; return 1; }
  [[ -f "$XUI_DB" && -f "$SNI_CONF" ]] || { err "РќСѓР¶РЅС‹ x-ui.db Рё СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ SNI-РєРѕРЅС„РёРі"; pause; return 1; }
  local pd="${PANEL_DOMAIN:-}"; [[ -z "$pd" ]] && pd=$(xui_get webDomain 2>/dev/null || true)
  [[ "$pd" =~ ^[A-Za-z0-9.-]+$ ]] || { err "РќРµРєРѕСЂСЂРµРєС‚РЅС‹Р№ РґРѕРјРµРЅ РїР°РЅРµР»Рё"; pause; return 1; }
  local tmp bak rows count=0 id proto port dom backend sec dest
  tmp=$(mktemp "${SNI_CONF}.rebuild.XXXXXX") || { err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕР·РґР°С‚СЊ РІСЂРµРјРµРЅРЅС‹Р№ SNI-РєРѕРЅС„РёРі"; pause; return 1; }
  if ! rows=$(python3 - "$XUI_DB" <<'PY'
import sqlite3,json,sys,re
con=sqlite3.connect(sys.argv[1]); con.row_factory=sqlite3.Row
skip={'wireguard','amnezia','amneziawg','awg','qwdtt','csqtt','csqdt','mtproto','tun'}
for r in con.execute("SELECT id,protocol,port,settings,stream_settings FROM inbounds WHERE enable=1 AND port>0 ORDER BY id"):
    try: s=json.loads(r['settings'] or '{}'); t=json.loads(r['stream_settings'] or '{}')
    except Exception: continue
    net=(t.get('network') or '').lower(); proto=(r['protocol'] or '').lower()
    if proto in skip or net in ('udp','quic'): continue
    dom=s.get('domain') or s.get('hostname') or s.get('sni')
    tls=t.get('tlsSettings') or {}; dom=dom or tls.get('serverName')
    rs=t.get('realitySettings') or {}; names=rs.get('serverNames') or []
    dom=dom or (names[0] if names else '')
    if not isinstance(dom,str) or not re.fullmatch(r'[A-Za-z0-9.-]+',dom): continue
    dest=rs.get('dest') or rs.get('target') or ''
    backend='tproxy' if proto=='tproxy' else f'inb_{r["id"]}_backend'
    port=11443 if proto=='tproxy' else int(r['port'])
    print(f'{r["id"]}|{proto}|{port}|{dom}|{backend}|{dest}')
PY
); then
    rm -f "$tmp"
    err "РќРµ СѓРґР°Р»РѕСЃСЊ РїСЂРѕС‡РёС‚Р°С‚СЊ Р‘Р” РїСЂРё РїРµСЂРµСЃР±РѕСЂРєРµ SNI"
    pause; return 1
  fi
  {
    echo 'map $ssl_preread_server_name $backend {'
    echo '    default                       panel_backend;'
    printf '    %-30s panel_backend;\n' "$pd"
    while IFS='|' read -r id proto port dom backend sec dest; do
      [[ -n "$dom" ]] || continue
      printf '    %-30s %s;\n' "$dom" "$backend"
      count=$((count+1))
    done <<<"$rows"
    # РЎРѕС…СЂР°РЅСЏРµРј СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ AdGuard SNI-РјР°СЂС€СЂСѓС‚, РµСЃР»Рё РѕРЅ Р±С‹Р».
    awk '/^[[:space:]]+[A-Za-z0-9.-]+[[:space:]]+agh_backend;/{print}' "$SNI_CONF" 2>/dev/null
    # CDN-РїСЂРѕС„РёР»Рё: SNI origin/cdn в†’ РµРґРёРЅС‹Р№ Р»РѕРєР°Р»СЊРЅС‹Р№ TLS-С„СЂРѕРЅС‚РµРЅРґ nginx
    cdn_profiles_load
    local _cp_row _cp_origin _cp_cdn
    while IFS='|' read -r _cp_row; do
      _cp_origin=$(printf '%s' "$_cp_row" | cut -d'|' -f3)
      _cp_cdn=$(printf '%s' "$_cp_row" | cut -d'|' -f4)
      [[ -n "$_cp_origin" ]] && { printf '    %-30s cdn_frontend;\n' "$_cp_origin"; count=$((count+1)); }
      [[ -n "$_cp_cdn" ]] && printf '    %-30s cdn_frontend;\n' "$_cp_cdn"
    done < <(cat "$CDN_PROFILES" 2>/dev/null)
    echo '}'
    echo
    echo 'upstream panel_backend { server 127.0.0.1:4443; }'
    # cdn_frontend вЂ” С‚РѕР»СЊРєРѕ РµСЃР»Рё РµСЃС‚СЊ С…РѕС‚СЏ Р±С‹ РѕРґРёРЅ CDN-РїСЂРѕС„РёР»СЊ
    if [[ -s "$CDN_PROFILES" ]]; then
      echo "upstream cdn_frontend { server 127.0.0.1:$CDN_FE_PORT; }"
    fi
    while IFS='|' read -r id proto port dom backend sec dest; do
      [[ -n "$backend" ]] || continue
      printf 'upstream %s { server 127.0.0.1:%s; }\n' "$backend" "$port"
    done <<<"$rows"
    if grep -q '^upstream agh_backend[[:space:]]*{' "$SNI_CONF" 2>/dev/null; then
      awk '/^upstream agh_backend[[:space:]]*\{/{p=1} p{print} p&&/^}/{exit}' "$SNI_CONF"
    fi
    echo
    echo 'server {'
    echo '    listen 443;'
    echo '    proxy_pass $backend;'
    echo '    ssl_preread on;'
    echo '    proxy_connect_timeout 5s;'
    echo '    proxy_timeout 10m;'
    echo '}'
  } > "$tmp" || { rm -f "$tmp"; err "РќРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РїРёСЃР°С‚СЊ РІСЂРµРјРµРЅРЅС‹Р№ SNI-РєРѕРЅС„РёРі"; pause; return 1; }
  bak="${SNI_CONF}.bak-rebuild-$(date +%Y%m%d-%H%M%S)"
  cp -a "$SNI_CONF" "$bak" || { rm -f "$tmp"; err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕС…СЂР°РЅРёС‚СЊ СЂРµР·РµСЂРІРЅСѓСЋ РєРѕРїРёСЋ SNI"; pause; return 1; }
  mv -f "$tmp" "$SNI_CONF" || { rm -f "$tmp"; err "РќРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РјРµРЅРёС‚СЊ SNI-РєРѕРЅС„РёРі"; pause; return 1; }
  if ! nginx -t 2>/dev/null; then
    mv -f "$bak" "$SNI_CONF"; err "nginx -t РЅРµ РїСЂРѕС€С‘Р» вЂ” РёСЃС…РѕРґРЅС‹Р№ SNI РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"; nginx -t 2>&1 | tail -6; pause; return 1
  fi
  mkdir -p /etc/nginx/streams-available 2>/dev/null || true
  rm -f /etc/nginx/streams-available/sni-router.conf 2>/dev/null || true
  ln -s "$SNI_CONF" /etc/nginx/streams-available/sni-router.conf 2>/dev/null || cp -f "$SNI_CONF" /etc/nginx/streams-available/sni-router.conf 2>/dev/null || true
  nginx_reload || { mv -f "$bak" "$SNI_CONF"; nginx_reload >/dev/null 2>&1 || true; err "SNI Р·Р°РјРµРЅС‘РЅ, РЅРѕ nginx РЅРµ РїРµСЂРµР·Р°РіСЂСѓР·РёР»СЃСЏ вЂ” РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ СЃС‚Р°СЂС‹Р№"; pause; return 1; }
  log "SNI РїРµСЂРµСЃРѕР±СЂР°РЅ РёР· Р‘Р”: РјР°СЂС€СЂСѓС‚РѕРІ $count; Р‘Р” Рё СЃРµСЂС‚РёС„РёРєР°С‚С‹ РЅРµ РјРµРЅСЏР»РёСЃСЊ."
  pause
}

ensure_deps() {  local missing=() t
  for t in sqlite3 jq curl ss nginx certbot openssl dig ufw fail2ban-client nc xxd; do
    command -v "$t" >/dev/null 2>&1 && continue
    case "$t" in
      sqlite3) missing+=(sqlite3);;
      jq) missing+=(jq);;
      curl) missing+=(curl);;
      ss) missing+=(iproute2);;
      nginx) missing+=(nginx);;
      certbot) missing+=(certbot);;
      openssl) missing+=(openssl);;
      dig) missing+=(dnsutils);;
      ufw) missing+=(ufw);;
      fail2ban-client) missing+=(fail2ban);;
      nc) missing+=(netcat-openbsd);;
      xxd) missing+=(xxd);;
    esac
  done
  dpkg -s libnginx-mod-stream >/dev/null 2>&1 || missing+=(libnginx-mod-stream)
  if [[ ${#missing[@]} -gt 0 ]]; then
    log "РЈСЃС‚Р°РЅРѕРІРєР°: ${missing[*]}"
    apt-get update -y >/dev/null 2>&1 || { err "apt-get update РЅРµ СѓРґР°Р»СЃСЏ вЂ” Р·Р°РІРёСЃРёРјРѕСЃС‚Рё РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅС‹"; return 1; }
    apt-get install -y "${missing[@]}" >/dev/null 2>&1 || { err "apt-get install РЅРµ СѓРґР°Р»СЃСЏ: ${missing[*]}"; return 1; }
  fi
  local _need _miss_after=()
  for _need in sqlite3 jq curl ss nginx certbot openssl dig ufw fail2ban-client nc xxd; do
    command -v "$_need" >/dev/null 2>&1 || _miss_after+=("$_need")
  done
  dpkg -s libnginx-mod-stream >/dev/null 2>&1 || _miss_after+=(libnginx-mod-stream)
  if [[ ${#_miss_after[@]} -gt 0 ]]; then
    err "РџРѕСЃР»Рµ СѓСЃС‚Р°РЅРѕРІРєРё РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‚ Р·Р°РІРёСЃРёРјРѕСЃС‚Рё: ${_miss_after[*]}"
    return 1
  fi
  # nginx С‡РёСЃР»РёС‚СЃСЏ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Рј, РЅРѕ РєРѕРЅС„РёРіРѕРІ /etc/nginx РЅРµС‚ РР›Р РЅР°Р±РѕСЂ СѓСЃРµС‡С‘РЅ
  # (РїРѕСЃР»Рµ РѕС‚РєР°С‚Р°/РґРµРјРѕРЅС‚Р°Р¶Р° apt РЅРµ РІРѕР·РІСЂР°С‰Р°РµС‚ conffiles вЂ” СЃС‡РёС‚Р°РµС‚ РёС… В«СѓРґР°Р»С‘РЅРЅС‹РјРё
  # Р°РґРјРёРЅРёСЃС‚СЂР°С‚РѕСЂРѕРјВ»). РџСЂРѕРІРµСЂСЏРµРј РЅРµ С‚РѕР»СЊРєРѕ nginx.conf: Р±РµР· mime.types/snippets
  # nginx РІРѕРѕР±С‰Рµ РЅРµ СЃС‚Р°СЂС‚СѓРµС‚, Р° Р±РµР· modules-enabled РґРёРЅР°РјРёС‡РµСЃРєРёР№ РјРѕРґСѓР»СЊ stream РЅРµ
  # РїРѕРґРєР»СЋС‡Р°РµС‚СЃСЏ Рё РґРёСЂРµРєС‚РёРІР° stream СЃС‚Р°РЅРѕРІРёС‚СЃСЏ В«unknown directiveВ».
  local _ngx_missing=() _ngxf
  [[ -f /etc/nginx/nginx.conf ]] || _ngx_missing+=(nginx.conf)
  for _ngxf in mime.types fastcgi_params uwsgi_params scgi_params \
               snippets/fastcgi-php.conf snippets/snakeoil.conf; do
    [[ -f "/etc/nginx/$_ngxf" ]] || _ngx_missing+=("$_ngxf")
  done
  if dpkg -s nginx >/dev/null 2>&1 && [[ ${#_ngx_missing[@]} -gt 0 ]]; then
    log "nginx: РЅРµ С…РІР°С‚Р°РµС‚ С„Р°Р№Р»РѕРІ РєРѕРЅС„РёРіСѓСЂР°С†РёРё (${_ngx_missing[*]}) вЂ” РїРµСЂРµСѓСЃС‚Р°РЅР°РІР»РёРІР°СЋ РїР°РєРµС‚С‹ (conffiles)"
    local _ngx_pkgs
    _ngx_pkgs=$(dpkg -l 2>/dev/null | awk '/^ii/ && $2 ~ /nginx/ {print $2}' | tr '\n' ' ')
    [[ -z "$_ngx_pkgs" ]] && _ngx_pkgs="nginx nginx-common nginx-full"
    local -a _ngx_pkgs_arr=()
    read -r -a _ngx_pkgs_arr <<< "$_ngx_pkgs"
    apt-get install -y --reinstall -o Dpkg::Options::=--force-confmiss "${_ngx_pkgs_arr[@]}" >/dev/null 2>&1 || true
    if [[ ! -f /etc/nginx/nginx.conf ]]; then
      # nginx.conf Рё Р±Р°Р·РѕРІС‹Рµ РєР°С‚Р°Р»РѕРіРё РїСЂРёРЅР°РґР»РµР¶Р°С‚ nginx-common, Р° РЅРµ РІСЃРµРіРґР°
      # РїР°РєРµС‚Сѓ nginx. force-confmiss РЅСѓР¶РµРЅ РґР»СЏ conffile, СѓРґР°Р»С‘РЅРЅРѕРіРѕ РІСЂСѓС‡РЅСѓСЋ.
      apt-get install -y --reinstall -o Dpkg::Options::=--force-confmiss \
        nginx nginx-common nginx-core nginx-full >/dev/null 2>&1 || true
    fi
    if [[ ! -f /etc/nginx/nginx.conf ]]; then
      mkdir -p /etc/nginx/{sites-available,sites-enabled,streams-available,streams-enabled,snippets,conf.d} 2>/dev/null || true
      # РџРѕСЃР»Рµ СЂСѓС‡РЅРѕРіРѕ rm -rf dpkg РёРЅРѕРіРґР° СЃС‡РёС‚Р°РµС‚ nginx.conf В«СѓРґР°Р»С‘РЅРЅС‹Рј
      # Р°РґРјРёРЅРёСЃС‚СЂР°С‚РѕСЂРѕРјВ» Рё РЅРµ РІРѕР·РІСЂР°С‰Р°РµС‚ conffile РґР°Р¶Рµ СЃ reinstall. Р’ СЌС‚РѕРј
      # СЃР»СѓС‡Р°Рµ Р±РµСЂС‘Рј С€С‚Р°С‚РЅС‹Р№ РєРѕРЅС„РёРі РЅРµРїРѕСЃСЂРµРґСЃС‚РІРµРЅРЅРѕ РёР· deb-РїР°РєРµС‚Р°.
      local _ngx_tmp="" _got=""
      _ngx_tmp=$(mktemp -d /tmp/nginx-common.XXXXXX 2>/dev/null || true)
      if [[ -n "$_ngx_tmp" ]] && (cd "$_ngx_tmp" && apt-get download nginx-common >/dev/null 2>&1); then
        _got=$(ls -1t "$_ngx_tmp"/nginx-common_*.deb 2>/dev/null | head -1 || true)
        if [[ -n "$_got" ]]; then
          dpkg-deb --fsys-tarfile "$_got" 2>/dev/null | tar -xOf - ./etc/nginx/nginx.conf > /etc/nginx/nginx.conf 2>/dev/null || true
        fi
      fi
      rm -rf "$_ngx_tmp" 2>/dev/null || true
    fi
    # РџРѕСЃР»РµРґРЅРёР№ fallback: РјРёРЅРёРјР°Р»СЊРЅС‹Р№ СЂР°Р±РѕС‡РёР№ РєРѕРЅС„РёРі. РћРЅ РґРѕСЃС‚Р°С‚РѕС‡РµРЅ РґР»СЏ
    # РїРѕСЃР»РµРґСѓСЋС‰РµР№ СЃР±РѕСЂРєРё stack.conf Рё SNI-router; РїР°РєРµС‚РЅС‹Р№ conffile РјРѕРі Р±С‹С‚СЊ
    # РЅРµРґРѕСЃС‚СѓРїРµРЅ РёР·-Р·Р° DNS/СЂРµРїРѕР·РёС‚РѕСЂРёСЏ РёР»Рё РЅРµСЃС‚Р°РЅРґР°СЂС‚РЅРѕРіРѕ СЃРѕСЃС‚РѕСЏРЅРёСЏ dpkg.
    if [[ ! -f /etc/nginx/nginx.conf ]]; then
      cat > /etc/nginx/nginx.conf <<'NGINXCFG'
# Р—Р°РіСЂСѓР¶Р°РµРј stream-РјРѕРґСѓР»СЊ РґРѕ events (РЅСѓР¶РµРЅ РґР»СЏ SNI РЅР° 443).
load_module /usr/lib/nginx/modules/ngx_stream_module.so;
user www-data;
worker_processes auto;
worker_rlimit_nofile 65535;
pid /run/nginx.pid;
error_log /var/log/nginx/error.log;
events { worker_connections 4096; }
stream { include /etc/nginx/streams-enabled/*.conf; }
http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    access_log /var/log/nginx/access.log;
    sendfile on;
    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
NGINXCFG
      [[ -f /etc/nginx/nginx.conf ]] && log "  СЃРѕР·РґР°РЅ РјРёРЅРёРјР°Р»СЊРЅС‹Р№ Р±Р°Р·РѕРІС‹Р№ /etc/nginx/nginx.conf"
    fi
    if [[ ! -f /etc/nginx/nginx.conf ]]; then
      err "  nginx.conf РЅРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ: РїСЂРѕРІРµСЂСЊ СЃРѕСЃС‚РѕСЏРЅРёРµ nginx-РїР°РєРµС‚РѕРІ Рё DNS СЂРµРїРѕР·РёС‚РѕСЂРёСЏ"
      err "  Р’С‹РїРѕР»РЅРё: apt-get update && apt-get install -y --reinstall nginx nginx-common"
      return 1
    else
      log "  /etc/nginx РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
    fi
  fi
  # РњРѕРґСѓР»СЊ stream (443/SNI): РїРѕРґРєР»СЋС‡Р°РµРј СЃСЂР°Р·Сѓ, РёРЅР°С‡Рµ СЃР±РѕСЂРєР° СЃ --with-stream=dynamic
  # РЅРµ Р·РЅР°РµС‚ РґРёСЂРµРєС‚РёРІСѓ stream Рё Р»СЋР±РѕР№ stream-Р±Р»РѕРє Р»РѕРјР°РµС‚ РєРѕРЅС„РёРі С†РµР»РёРєРѕРј.
  if ! nginx_stream_module_enable; then
    warn "nginx: РјРѕРґСѓР»СЊ stream РЅРµ РїРѕРґРєР»СЋС‡РёР»СЃСЏ вЂ” 443/SNI СЂР°Р±РѕС‚Р°С‚СЊ РЅРµ Р±СѓРґРµС‚ (РїСЂРѕРІРµСЂСЊ РїР°РєРµС‚ libnginx-mod-stream)"
  fi
  nginx_tune_limits
}

# nginx РґРµСЂР¶РёС‚ РїРѕРґ SNI-СЂРѕСѓС‚РёРЅРіРѕРј Р’РЎР• РєР»РёРµРЅС‚СЃРєРёРµ СЃРѕРµРґРёРЅРµРЅРёСЏ РЅР° 443. Р”РµС„РѕР»С‚РѕРІ
# Debian/Ubuntu (worker_connections 768, rlimit 1024) РЅРµ С…РІР°С‚Р°РµС‚: РЅР° РїРёРєРµ
# connections nginx РїРёС€РµС‚ РІ error.log В«768 worker_connections are not enoughВ»,
# РїРµСЂРµСЃС‚Р°С‘С‚ РїСЂРёРЅРёРјР°С‚СЊ РЅРѕРІС‹Рµ РєРѕРЅРЅРµРєС‚С‹ Рё 443 В«Р·Р°Р»РёРїР°РµС‚В» РґРѕ РїРµСЂРµР·Р°РїСѓСЃРєР° xray вЂ”
# СЂРѕРІРЅРѕ С‚РѕС‚ СЃРёРјРїС‚РѕРј, РєРѕРіРґР° В«РїРѕСЃР»Рµ РїРµСЂРµР·Р°РїСѓСЃРєР° РёРЅР±Р°СѓРЅРґР° СЃРЅРѕРІР° СЂР°Р±РѕС‚Р°РµС‚В».
# РџРѕРґРЅРёРјР°РµРј Р»РёРјРёС‚С‹ РёРґРµРјРїРѕС‚РµРЅС‚РЅРѕ: РїСЂР°РІРёРј С‚РѕР»СЊРєРѕ РєРѕРіРґР° Р·РЅР°С‡РµРЅРёРµ РЅРµ РЅР°С€Рµ.
nginx_tune_limits() {
  local conf=${NGINX_CONF:-/etc/nginx/nginx.conf}
  [[ -f "$conf" ]] || return 0
  local want_conn=4096 want_no=65535 cur_conn="" cur_no=""
  cur_conn=$(sed -nE 's/.*worker_connections[[:space:]]+([0-9]+).*/\1/p' "$conf" | head -1)
  cur_no=$(sed -nE 's/^[[:space:]]*worker_rlimit_nofile[[:space:]]+([0-9]+).*/\1/p' "$conf" | head -1)
  if [[ "$cur_conn" == "$want_conn" && "$cur_no" == "$want_no" ]]; then
    return 0
  fi
  local bak
  bak="${conf}.bak-limits-$(date +%Y%m%d-%H%M%S)"
  cp -a "$conf" "$bak" 2>/dev/null || true
  if [[ -z "$cur_no" ]]; then
    if grep -qE '^[[:space:]]*worker_processes' "$conf"; then
      sed -i -E "0,/^[[:space:]]*worker_processes[^;]*;/s//worker_rlimit_nofile ${want_no};\n&/" "$conf"
    elif grep -qE '^[[:space:]]*user[[:space:]]' "$conf"; then
      sed -i -E "0,/^[[:space:]]*user[^;]*;/s//&\nworker_rlimit_nofile ${want_no};/" "$conf"
    else
      sed -i "1i worker_rlimit_nofile ${want_no};" "$conf"
    fi
  elif [[ "$cur_no" != "$want_no" ]]; then
    sed -i -E "s/^([[:space:]]*worker_rlimit_nofile[[:space:]]+)[0-9]+/\1${want_no}/" "$conf"
  fi
  if grep -q 'worker_connections' "$conf"; then
    sed -i -E "s/worker_connections[[:space:]]+[0-9]+/worker_connections ${want_conn}/g" "$conf"
  elif grep -qE '^[[:space:]]*events[[:space:]]*\{' "$conf"; then
    sed -i -E "0,/^[[:space:]]*events[[:space:]]*\{/s//events {\n    worker_connections ${want_conn};/" "$conf"
  else
    # Р‘Р»РѕРєР° events РЅРµС‚ РІРѕРІСЃРµ вЂ” РґРѕРїРёСЃС‹РІР°РµРј РµРіРѕ РІ РєРѕРЅРµС† С„Р°Р№Р»Р° (СѓСЂРѕРІРµРЅСЊ main).
    printf 'events {\n    worker_connections %s;\n}\n' "$want_conn" >> "$conf"
  fi
  if ! nginx -t >/dev/null 2>&1; then
    err "nginx: Р»РёРјРёС‚С‹ СЃРѕРµРґРёРЅРµРЅРёР№ РЅРµ РїСЂРёРјРµРЅРёР»РёСЃСЊ (nginx -t) вЂ” РІРѕР·РІСЂР°С‰Р°СЋ РїСЂРµР¶РЅРёР№ nginx.conf"
    [[ -f "$bak" ]] && cp -a "$bak" "$conf" 2>/dev/null || true
    return 0
  fi
  log "nginx: Р»РёРјРёС‚С‹ СЃРѕРµРґРёРЅРµРЅРёР№ РїРѕРґРЅСЏС‚С‹ (worker_connections ${want_conn}, worker_rlimit_nofile ${want_no})"
  nginx_reload >/dev/null 2>&1 || warn "nginx: РєРѕРЅС„РёРі СЃ РЅРѕРІС‹РјРё Р»РёРјРёС‚Р°РјРё Р·Р°РїРёСЃР°РЅ, РЅРѕ reload РЅРµ СѓРґР°Р»СЃСЏ"
  rm -f "$bak" 2>/dev/null || true
  return 0
}

get_random_port() { echo $(( ((RANDOM<<15)|RANDOM) % 49152 + 10000 )); }
gen_random_string() { head -c 4096 /dev/urandom | tr -dc 'a-zA-Z0-9' | head -c "$1"; }

port_in_use() {
  local p="$1"
  ss -Hltn "sport = :$p" 2>/dev/null | grep -q . && return 0
  ss -Huln "sport = :$p" 2>/dev/null | grep -q . && return 0
  command -v nc >/dev/null 2>&1 && { timeout 1 nc -w 1 -z 127.0.0.1 "$p" &>/dev/null; return $?; }
  return 1
}

is_port_reserved() {
  local p="$1"
  case "$p" in
    22|53|80|443|3000|4443|5432|6060|8080|8443) return 0 ;;
  esac
  (( p >= 4444 && p <= 4600 )) && return 0   # decoy-РїРѕСЂС‚С‹ 4444+
  [[ "$p" == "$SSH_PORT" ]] && return 0
  [[ -n "${PANEL_PORT:-}" && "$p" == "$PANEL_PORT" ]] && return 0
  [[ -n "${SUB_PORT:-}"   && "$p" == "$SUB_PORT"   ]] && return 0
  return 1
}

make_port() {
  local p tries=0
  while (( tries < 200 )); do
    p=$(get_random_port)
    if ! port_in_use "$p" && ! is_port_reserved "$p"; then
      echo "$p"; return 0
    fi
    tries=$((tries+1))
  done
  echo "$p"
}

# =====================================================================
# РЈРќРРљРђР›Р¬РќРћРЎРўР¬ SNI-Р”РћРњР•РќРћР’
#   SNI_USED[РґРѕРјРµРЅ] = backend вЂ” РґРѕРјРµРЅС‹, Р·Р°РЅСЏС‚С‹Рµ РїР°РЅРµР»СЊСЋ/РёРЅР±Р°СѓРЅРґР°РјРё
# =====================================================================
declare -A SNI_USED=()

sni_used_load() {
  SNI_USED=()
  [[ -f "$SNI_CONF" ]] || return 0
  local line dom be
  local _re='^[[:space:]]+([A-Za-z0-9.-]+)[[:space:]]+([A-Za-z0-9_-]+);'
  while IFS= read -r line; do
    [[ "$line" =~ $_re ]] || continue
    dom="${BASH_REMATCH[1]}"; be="${BASH_REMATCH[2]}"
    [[ "$dom" == "default" ]] && continue
    SNI_USED["$dom"]="$be"
  done < "$SNI_CONF"
  return 0
}

# РџРµС‡Р°С‚Р°РµС‚ backend, РєРѕС‚РѕСЂС‹Р№ СѓР¶Рµ Р·Р°РЅРёРјР°РµС‚ РґРѕРјРµРЅ $1 (РєСЂРѕРјРµ РёРЅР±Р°СѓРЅРґР° $2), РёРЅР°С‡Рµ РїСѓСЃС‚Рѕ
sni_domain_owner() {
  local dom="$1" self="${2:-}" be=""
  [[ -z "$dom" ]] && { echo ""; return; }
  be="${SNI_USED[$dom]:-}"
  if [[ -z "$be" && -f "$SNI_CONF" ]]; then
    be=$(grep -E "^[[:space:]]+${dom//./\\.}[[:space:]]+[A-Za-z0-9_-]+;" "$SNI_CONF" 2>/dev/null | head -1 | awk '{print $2}' | tr -d ';' || true)
    [[ -n "$be" ]] && SNI_USED["$dom"]="$be"
  fi
  [[ -n "$self" && "$be" == "inb_${self}_backend" ]] && be=""
  [[ -n "$self" && "$be" == "hysteria_${self}_web" ]] && be=""
  # РњС‘СЂС‚РІС‹Рµ Р·Р°РїРёСЃРё (РёРЅР±Р°СѓРЅРґ СѓРґР°Р»С‘РЅ РІ РїР°РЅРµР»Рё, SNI-РјР°СЂС€СЂСѓС‚ РѕСЃС‚Р°Р»СЃСЏ) РЅРµ В«Р·Р°РЅРёРјР°СЋС‚В»
  # РґРѕРјРµРЅ вЂ” РёРЅР°С‡Рµ СЃРѕР·РґР°РЅРёРµ РЅРѕРІРѕРіРѕ РёРЅР±Р°СѓРЅРґР° РЅР° С‚РѕС‚ Р¶Рµ РґРѕРјРµРЅ Р»РѕР¶РЅРѕ РїР°РґР°Р»Рѕ
  # В«Р”РѕРјРµРЅ X СѓР¶Рµ Р·Р°РЅСЏС‚В». Р‘Р” РЅРµ РѕС‚РІРµС‚РёР»Р° (Р±Р»РѕРєРёСЂРѕРІРєР°) вЂ” СЃС‡РёС‚Р°РµРј Р·Р°РЅСЏС‚С‹Рј:
  # РїРµСЂРµСЃС‚СЂР°С…РѕРІРєР° РѕС‚ Р»РѕР¶РЅРѕРіРѕ В«СЃРІРѕР±РѕРґРЅРѕВ» РЅР° РїСѓСЃС‚РѕРј РѕС‚РІРµС‚Рµ sqlite.
  #
  # Р’РђР–РќРћ: РїСЂРѕРІРµСЂРєР° РѕС…РІР°С‚С‹РІР°РµС‚ РћР‘Рђ РІРёРґР° backend'РѕРІ СЃ РёРґРµРЅС‚РёС„РёРєР°С‚РѕСЂРѕРј РёРЅР±Р°СѓРЅРґР°:
  #   вЂў inb_<id>_backend        вЂ” vless/trojan/naive/anytls/trusttunnel...
  #   вЂў hysteria_<id>_web       вЂ” Hysteria2. Р Р°РЅСЊС€Рµ РѕС…РІР°С‚С‹РІР°Р»СЃСЏ С‚РѕР»СЊРєРѕ РїРµСЂРІС‹Р№,
  #     Рё РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ Hysteria2 РјР°СЂС€СЂСѓС‚ В«РґРѕРјРµРЅ в†’ hysteria_N_webВ» РЅР°РІСЃРµРіРґР°
  #     Р±Р»РѕРєРёСЂРѕРІР°Р» РїРѕРІС‚РѕСЂРЅРѕРµ РёСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ РµРіРѕ РґРѕРјРµРЅР° (В«СѓР¶Рµ Р·Р°РЅСЏС‚В»).
  local __sid=""
  if [[ "$be" =~ ^inb_([0-9]+)_backend$ ]]; then
    __sid="${BASH_REMATCH[1]}"
  elif [[ "$be" =~ ^hysteria_([0-9]+)_web$ ]]; then
    __sid="${BASH_REMATCH[1]}"
  fi
  if [[ -n "$__sid" && -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local _cnt=""
    _cnt=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
           "SELECT COUNT(*) FROM inbounds WHERE id=$__sid;" 2>/dev/null | tr -d '[:space:]') || true
    [[ "$_cnt" == "0" ]] && be=""
  fi
  # tg web proxy: backend Р±РµР· id РІ РёРјРµРЅРё (tproxy / tg_backend). РњР°СЂС€СЂСѓС‚ РІР°Р»РёРґРµРЅ,
  # РїРѕРєР° РµСЃС‚СЊ Р¶РёРІРѕР№ tproxy-РёРЅР±Р°СѓРЅРґ; РёРЅР°С‡Рµ Р·Р°РїРёСЃСЊ РјС‘СЂС‚РІР°СЏ Рё РґРѕРјРµРЅ СЃРІРѕР±РѕРґРµРЅ.
  if [[ ( "$be" == "tproxy" || "$be" == "tg_backend" ) && -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local _tcount=""
    _tcount=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
              "SELECT COUNT(*) FROM inbounds WHERE protocol='tproxy';" 2>/dev/null | tr -d '[:space:]') || true
    [[ "$_tcount" == "0" ]] && be=""
  fi
  echo "$be"
}

# РњС‘СЂС‚РІС‹Рµ SNI-Р·Р°РїРёСЃРё: СЃС‚СЂРѕРєРё В«РґРѕРјРµРЅ|backend|idВ», Сѓ РєРѕС‚РѕСЂС‹С… РёРЅР±Р°СѓРЅРґР° id СѓР¶Рµ РЅРµС‚
# РІ Р‘Р” (СѓРґР°Р»С‘РЅ РІ РїР°РЅРµР»Рё, Р° РјР°СЂС€СЂСѓС‚ РѕСЃС‚Р°Р»СЃСЏ). РўРёС…Рѕ, Р±РµР· РІС‹РІРѕРґР° Рё РјРµРЅСЋ;
# Р‘Р” РЅРµ РѕС‚РІРµС‚РёР»Р° (Р±Р»РѕРєРёСЂРѕРІРєР°) вЂ” Р·Р°РїРёСЃСЊ СЃС‡РёС‚Р°РµС‚СЃСЏ Р¶РёРІРѕР№ (РїРµСЂРµСЃС‚СЂР°С…РѕРІРєР°).
# Р—Р°РІРёСЃРёРјРѕСЃС‚Рё (sni_map_domains/sni_map_remove/sni_upstream_remove/nginx_reload/
# stack_del_decoy) РѕРїСЂРµРґРµР»РµРЅС‹ РІ РґСЂСѓРіРёС… РјРѕРґСѓР»СЏС… Рё РґРѕСЃС‚СѓРїРЅС‹ РІ СЂР°РЅС‚Р°Р№РјРµ.
sni_stale_list() {
  [[ -f "$SNI_CONF" && -n "$XUI_DB" && -f "$XUI_DB" ]] || return 0
  local dom be iid cnt
  while IFS='|' read -r dom be iid; do
    [[ "$iid" =~ ^[0-9]+$ ]] || continue
    cnt=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
          "SELECT COUNT(*) FROM inbounds WHERE id=$iid;" 2>/dev/null | tr -d '[:space:]') || true
    [[ "$cnt" == "0" ]] && echo "$dom|$be|$iid"
  done < <(sni_map_domains)
}

# РўРёС…Р°СЏ Р°РІС‚Рѕ-С‡РёСЃС‚РєР° РјС‘СЂС‚РІС‹С… SNI-Р·Р°РїРёСЃРµР№ (РёРЅР±Р°СѓРЅРґ СѓРґР°Р»С‘РЅ РІ РїР°РЅРµР»Рё):
# map-СЃС‚СЂРѕРєР° + РѕСЃРёСЂРѕС‚РµРІС€РёР№ upstream + decoy-Р±Р»РѕРє + hosts-С„Р»Р°РіРё Р‘Р”.
# Р’С‹Р·С‹РІР°РµС‚СЃСЏ РўРћР›Р¬РљРћ РІ СЏРІРЅС‹С… РїРѕС‚РѕРєР°С… РЅР°СЃС‚СЂРѕР№РєРё/СЃРѕР·РґР°РЅРёСЏ РёРЅР±Р°СѓРЅРґРѕРІ вЂ” РґРѕ
# РїСЂРѕРІРµСЂРєРё В«РґРѕРјРµРЅ Р·Р°РЅСЏС‚В», С‡С‚РѕР±С‹ С…РІРѕСЃС‚ СѓРґР°Р»С‘РЅРЅРѕРіРѕ РёРЅР±Р°СѓРЅРґР° РЅРµ Р±Р»РѕРєРёСЂРѕРІР°Р»
# РїРѕРІС‚РѕСЂРЅРѕРµ РёСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ РµРіРѕ РґРѕРјРµРЅР°. РРґРµРјРїРѕС‚РµРЅС‚РЅР°; РїРµС‡Р°С‚Р°РµС‚ РєР°Р¶РґРѕРµ СѓРґР°Р»РµРЅРёРµ.
sni_stale_purge_quiet() {
  local -a dead=()
  local row dom be iid
  while IFS= read -r row; do
    [[ -n "$row" ]] && dead+=("$row")
  done < <(sni_stale_list)
  [[ ${#dead[@]} -eq 0 ]] && return 0
  for row in "${dead[@]}"; do
    IFS='|' read -r dom be iid <<<"$row"
    sni_map_remove "$dom"
    [[ -n "$be" && "$be" != "panel_backend" ]] && sni_upstream_remove "$be"
    unset "SNI_USED[$dom]" 2>/dev/null || true
    stack_del_decoy "$dom"
    sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE inbound_id=$iid AND port=443;" 2>/dev/null || true
    sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE sni='$dom';" 2>/dev/null || true
    log "РђРІС‚Рѕ-С‡РёСЃС‚РєР° SNI: \"$dom\" в†’ $be (РёРЅР±Р°СѓРЅРґР° #$iid Р±РѕР»СЊС€Рµ РЅРµС‚ вЂ” СѓРґР°Р»С‘РЅ РІ РїР°РЅРµР»Рё)"
  done
  nginx_reload || true
  sni_used_load 2>/dev/null || true
  return 0
}

# РЎРїСЂРѕСЃРёС‚СЊ SNI-РґРѕРјРµРЅ РґР»СЏ РёРЅР±Р°СѓРЅРґР°: РЅРµРїСѓСЃС‚РѕР№, СЃРёРЅС‚Р°РєСЃРёС‡РµСЃРєРё РІР°Р»РёРґРЅС‹Р№, РЅРµ Р·Р°РЅСЏС‚С‹Р№
# РґСЂСѓРіРёРј РёРЅР±Р°СѓРЅРґРѕРј/РїР°РЅРµР»СЊСЋ. Р—Р°РЅСЏС‚С‹Р№ РґРѕРјРµРЅ Р·Р°РїРёСЃС‹РІР°РµС‚СЃСЏ РІ SNI_USED.
#   $1 = РёРјСЏ РїРµСЂРµРјРµРЅРЅРѕР№ СЂРµР·СѓР»СЊС‚Р°С‚Р°, $2 = id РёРЅР±Р°СѓРЅРґР°, $3 = Р·РЅР°С‡РµРЅРёРµ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ,
#   $4 = РїРѕРґРїРёСЃСЊ РІРѕРїСЂРѕСЃР° (РѕРїС†РёРѕРЅР°Р»СЊРЅРѕ).
# Р’РѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРѕ РїРѕСЃР»Рµ РѕС€РёР±РѕС‡РЅРѕРіРѕ СѓРґР°Р»РµРЅРёСЏ РІ 1.0.23: РІС‹Р·РѕРІС‹ РѕСЃС‚Р°Р»РёСЃСЊ РІ
# cdn/initial-setup/inbound-ops, Рё Р±РµР· РѕРїСЂРµРґРµР»РµРЅРёСЏ РїРѕС‚РѕРє СЃРѕР·РґР°РЅРёСЏ РёРЅР±Р°СѓРЅРґР°
# РїР°РґР°Р» В«command not foundВ».
ask_sni_domain() {
  local __v="$1" __id="$2" __def="$3" d_val owner
  local __label="${4:-SNI-РґРѕРјРµРЅ РґР»СЏ #${__id}}"
  while :; do
    d_val=""
    ask d_val "$__label" "$__def" '^[a-zA-Z0-9.-]+$'
    # РќРµ-TTY: РїСѓСЃС‚РѕР№ РѕС‚РІРµС‚ в†’ РґРµС„РѕР»С‚ (EOF-РїРµС‚Р»СЏ РЅРµРІРѕР·РјРѕР¶РЅР°).
    [[ -z "$d_val" && ! -t 0 ]] && d_val="$__def"
    [[ -z "$d_val" ]] && { err "РџСѓСЃС‚РѕР№ РґРѕРјРµРЅ."; continue; }
    owner=$(sni_domain_owner "$d_val" "$__id")
    if [[ -n "$owner" ]]; then
      if [[ ! -t 0 ]]; then
        # РќРµ-TTY: РїРµСЂРµСЃРїСЂР°С€РёРІР°РЅРёРµ Р±РµСЃРїРѕР»РµР·РЅРѕ вЂ” EOF РєР°Р¶РґС‹Р№ СЂР°Р· РІРµСЂРЅС‘С‚ С‚РѕС‚ Р¶Рµ
        # РґРµС„РѕР»С‚, Рё РІР°Р»РёРґР°С†РёСЏ Р·Р°С†РёРєР»РёС‚СЃСЏ (В«СѓР¶Рµ Р·Р°РЅСЏС‚В» РґРѕ Р±РµСЃРєРѕРЅРµС‡РЅРѕСЃС‚Рё).
        # РџРѕРґР±РёСЂР°РµРј СЃРІРѕР±РѕРґРЅС‹Р№ РІР°СЂРёР°РЅС‚ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё (СЃСѓС„С„РёРєСЃ 2,3,вЂ¦).
        local __base="${d_val%%.*}" __rest="${d_val#*.}" __n=2
        while [[ -n "$(sni_domain_owner "${__base}${__n}.${__rest}" "$__id")" && "$__n" -le 50 ]]; do
          __n=$((__n+1))
        done
        d_val="${__base}${__n}.${__rest}"
        warn "РќРµ-TTY: РґРѕРјРµРЅ Р·Р°РЅСЏС‚ ($owner) вЂ” РїРѕРґРѕР±СЂР°РЅ СЃРІРѕР±РѕРґРЅС‹Р№: $d_val"
      else
        err "Р”РѕРјРµРЅ $d_val СѓР¶Рµ Р·Р°РЅСЏС‚ ($owner). РЈРєР°Р¶РёС‚Рµ РґСЂСѓРіРѕР№ SNI-РґРѕРјРµРЅ вЂ” Сѓ РґРІСѓС… РёРЅР±Р°СѓРЅРґРѕРІ РЅРµ РјРѕР¶РµС‚ Р±С‹С‚СЊ РѕРґРёРЅ SNI."
        continue
      fi
    fi
    printf -v "$__v" '%s' "$d_val"
    SNI_USED["$d_val"]="inb_${__id}_backend"
    return 0
  done
}


check_domain_points_to_server() {
  local domain="$1" server_ip="${2:-}"
  [[ -z "$server_ip" ]] && server_ip=$(curl -s --max-time 5 ifconfig.me 2>/dev/null || true)
  [[ -z "$server_ip" ]] && return 0
  local resolved=""
  resolved=$(dig +short "$domain" @1.1.1.1 2>/dev/null | grep -E '^[0-9.]+$' | tail -1 || true)
  [[ -z "$resolved" ]] && resolved=$(dig +short "$domain" @8.8.8.8 2>/dev/null | grep -E '^[0-9.]+$' | tail -1 || true)
  [[ -z "$resolved" ]] && { warn "Р”РѕРјРµРЅ $domain РЅРµ СЂРµР·РѕР»РІРёС‚СЃСЏ"; return 1; }
  [[ "$resolved" != "$server_ip" ]] && { warn "DNS mismatch: $domain=$resolved, server=$server_ip"; return 1; }
  log "DNS OK: $domain -> $resolved"
  return 0
}

# РћРїСЂРµРґРµР»СЏРµРј РІР°СЂРёР°РЅС‚ РїР°РЅРµР»Рё: LucX-С„РѕСЂРє vs РѕСЂРёРіРёРЅР°Р»СЊРЅС‹Р№ 3x-ui.
#   РњР°СЂРєРµСЂС‹ РІ Р‘Р”: С‚СЂРёРіРіРµСЂС‹ lucx_shareonly_*, С‚Р°Р±Р»РёС†Р° client_inbounds,
#   С„РёРєСЃ-С‚РµРіРё sidecar-РёРЅР±Р°СѓРЅРґРѕРІ (inbound-qwdtt/csqtt/tproxy).
#   РњР°СЂРєРµСЂС‹ СЃР°РјРѕР№ СѓСЃС‚Р°РЅРѕРІРєРё: СЃС‚СЂРѕРєР° В«lucxВ» РІ Р±РёРЅР°СЂРЅРёРєРµ РїР°РЅРµР»Рё Рё РІ РµС‘
#   РјРµРЅРµРґР¶РµСЂ-СЃРєСЂРёРїС‚Рµ x-ui.sh (Сѓ РѕСЂРёРіРёРЅР°Р»СЊРЅРѕРіРѕ 3x-ui С‚Р°РєРёС… СЃС‚СЂРѕРє РЅРµС‚).
#   РћРЅРё РЅСѓР¶РЅС‹ РґР»СЏ СЃРІРµР¶РµР№ СѓСЃС‚Р°РЅРѕРІРєРё LucX, РіРґРµ РІ Р‘Р” РµС‰С‘ РЅРµС‚ РЅРё РѕРґРЅРѕРіРѕ РјР°СЂРєРµСЂР°:
#   С‚СЂРёРіРіРµСЂС‹/С‚Р°Р±Р»РёС†С‹ СЃРѕР·РґР°СЋС‚СЃСЏ РјРёРіСЂР°С†РёСЏРјРё РїР°РЅРµР»Рё, Р° sqlite3 РїСЂРё РїРµСЂРІРѕРј Р·Р°РїСѓСЃРєРµ
#   СЃРєСЂРёРїС‚Р° РјРѕР¶РµС‚ Р±С‹С‚СЊ РµС‰С‘ РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” Р±РµР· РЅРёС… РјР°СЃС‚РµСЂ РїРѕРєР°Р·С‹РІР°Р»
#   В«РѕСЂРёРіРёРЅР°Р»СЊРЅС‹Р№ 3x-uiВ» Рё РЅРµ РїСЂРµРґР»Р°РіР°Р» LucX-РїСЂРѕС‚РѕРєРѕР»С‹.
#   XUI_BIN вЂ” С‚РµСЃС‚РѕРІР°СЏ С‚РѕС‡РєР° РїРѕРґРјРµРЅС‹ РїСѓС‚Рё Р±РёРЅР°СЂРЅРёРєР° (РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РїСѓС‚СЊ
#   ExecStart СЋРЅРёС‚Р° x-ui, Р·Р°С‚РµРј /usr/local/x-ui/x-ui).
# Р•СЃР»Рё РЅРё РѕРґРЅРѕРіРѕ РјР°СЂРєРµСЂР° РЅРµС‚ вЂ” СЃС‡РёС‚Р°РµРј РѕСЂРёРіРёРЅР°Р»СЊРЅС‹Рј 3x-ui.
# РџРµС‡Р°С‚Р°РµС‚: lucx | 3x-ui | none
detect_panel_flavor() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { echo "none"; return 0; }
  local v=""
  v=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT name FROM sqlite_master WHERE type='trigger' AND name LIKE 'lucx_shareonly_%' LIMIT 1;" 2>/dev/null || true)
  [[ -n "$v" ]] && { echo "lucx"; return 0; }
  v=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT name FROM sqlite_master WHERE type='table' AND name='client_inbounds' LIMIT 1;" 2>/dev/null || true)
  [[ -n "$v" ]] && { echo "lucx"; return 0; }
  v=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT 1 FROM inbounds WHERE tag IN ('inbound-qwdtt','inbound-csqtt','inbound-tproxy') LIMIT 1;" 2>/dev/null || true)
  [[ "$v" == "1" ]] && { echo "lucx"; return 0; }
  # Р’ Р‘Р” РјР°СЂРєРµСЂРѕРІ РЅРµС‚ вЂ” СЃРјРѕС‚СЂРёРј СЃР°РјСѓ СѓСЃС‚Р°РЅРѕРІРєСѓ РїР°РЅРµР»Рё. Р Р°Р±РѕС‚Р°РµС‚ Рё С‚РѕРіРґР°,
  # РєРѕРіРґР° sqlite3 РЅРµРґРѕСЃС‚СѓРїРµРЅ: grep Р±РёРЅР°СЂРЅРёРєР° РѕС‚ РЅРµРіРѕ РЅРµ Р·Р°РІРёСЃРёС‚.
  local bin="${XUI_BIN:-}" sh=""
  if [[ -z "$bin" ]]; then
    bin=$(systemctl show x-ui -p ExecStart --no-pager 2>/dev/null | sed -n 's/.*path=\([^ ;]*\).*/\1/p' | head -1 || true)
  fi
  [[ -z "$bin" || ! -f "$bin" ]] && bin="/usr/local/x-ui/x-ui"
  if [[ -f "$bin" ]] && grep -aqi lucx "$bin" 2>/dev/null; then
    echo "lucx"; return 0
  fi
  for sh in "$(dirname "$bin")/x-ui.sh" "/usr/local/x-ui/x-ui.sh"; do
    if [[ -f "$sh" ]] && grep -aqi lucx "$sh" 2>/dev/null; then
      echo "lucx"; return 0
    fi
  done
  echo "3x-ui"
}

detect_env() {
  XUI_DB=""
  local db
  for db in /etc/x-ui/x-ui.db /usr/local/x-ui/x-ui.db /opt/x-ui/x-ui.db; do
    [[ -f "$db" ]] && { XUI_DB="$db"; break; }
  done
  # РєР°РєРѕР№ РїР°РЅРµР»Рё РїСЂРёРЅР°РґР»РµР¶РёС‚ РЅР°Р№РґРµРЅРЅР°СЏ Р‘Р”: lucx | 3x-ui | none
  PANEL_FLAVOR=$(detect_panel_flavor)

  ADG_PRESENT=false; ADG_SERVICE=""; ADG_CONFIG=""
  local svc cfg
  for svc in AdGuardHome adguard-home adguardhome; do
    if [[ -f "/etc/systemd/system/${svc}.service" ]] || \
       systemctl list-unit-files "${svc}.service" 2>/dev/null | grep -qE "^${svc}\.service"; then
      ADG_SERVICE="$svc"; ADG_PRESENT=true; break
    fi
  done
  for cfg in /opt/AdGuardHome/AdGuardHome.yaml /root/AdGuardHome/AdGuardHome.yaml \
             /etc/AdGuardHome.yaml /etc/adguardhome/AdGuardHome.yaml; do
    [[ -f "$cfg" ]] && { ADG_CONFIG="$cfg"; ADG_PRESENT=true; break; }
  done
  if [[ "$ADG_PRESENT" == true && -z "$ADG_SERVICE" ]]; then
    local found
    found=$(systemctl list-unit-files 2>/dev/null | grep -iE 'adguard' | awk '{print $1}' | head -1 || true)
    [[ -n "$found" ]] && ADG_SERVICE="${found%.service}"
  fi

  SSH_PORT=""
  if [[ -f /etc/ssh/sshd_config ]]; then
    SSH_PORT=$(grep -E '^[[:space:]]*Port[[:space:]]+[0-9]+' /etc/ssh/sshd_config 2>/dev/null | awk '{print $2}' | head -1 || true)
  fi
  SSH_PORT="${SSH_PORT:-22}"

  find_xray_bin || true
  PANEL_FLAVOR=$(detect_panel_flavor)
}

xui_get() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  sqlite3 "$XUI_DB" "SELECT value FROM settings WHERE key='$1' LIMIT 1;" 2>/dev/null | tr -d '"' || true
}

# UPSERT РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё (UPDATE, РµСЃР»Рё РєР»СЋС‡ РµСЃС‚СЊ; INSERT вЂ” РµСЃР»Рё РЅРµС‚)
xui_set_setting() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  local k="$1" v="$2"
  sqlite3 "$XUI_DB" "UPDATE settings SET value='$v' WHERE key='$k';" 2>/dev/null || true
  sqlite3 "$XUI_DB" "INSERT INTO settings (key, value) SELECT '$k','$v' WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key='$k');" 2>/dev/null || true
}

# URL РїРѕРґРїРёСЃРєРё (РѕР±СЂР°С‚РЅС‹Р№ РїСЂРѕРєСЃРё): https://<РґРѕРјРµРЅ><subPath> вЂ” Р±РµР· ":443",
# 443 Рё С‚Р°Рє РґРµС„РѕР»С‚РЅС‹Р№ РґР»СЏ https; Р»РёС€РЅРёР№ РїРѕСЂС‚ РІ URL РЅРµ РЅСѓР¶РµРЅ.
# subPath РћР‘РЇР—РђРўР•Р›Р¬РќРћ СЃ РІРµРґСѓС‰РёРј Рё С…РІРѕСЃС‚РѕРІС‹Рј "/" вЂ” РёРЅР°С‡Рµ LucX РєР»РµРёС‚ С‚РѕРєРµРЅ
# РІРїР»РѕС‚РЅСѓСЋ Рє РґРѕРјРµРЅСѓ: https://domTOKEN РІРјРµСЃС‚Рѕ https://dom/РїСѓС‚СЊ/TOKEN
suburi_build() {
  local dom="$1" sp="${2:-}"
  [[ -z "$sp" ]] && sp=$(xui_get subPath 2>/dev/null || true)
  sp="/${sp#/}"; sp="${sp%/}/"
  [[ "$sp" == "/" ]] && sp=""
  printf 'https://%s%s' "$dom" "$sp"
}

# РљРѕРЅСЃРµСЂРІР°С‚РёРІРЅРѕ РѕРїСЂРµРґРµР»СЏРµС‚ РІРЅРµС€РЅРёР№ Reality РїРѕ С„Р°РєС‚РёС‡РµСЃРєРѕРјСѓ dest/target,
# Р° РЅРµ РїРѕ Р·Р°РєСЂС‹С‚РѕРјСѓ СЃРїРёСЃРєСѓ REALITY_TARGETS.
reality_external_dest() {
  local id="$1" d=""
  d=$(sqlite3 "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),json_extract(stream_settings,'\$.realitySettings.target'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  d="${d%%:*}"
  [[ -n "$d" && "$d" != "127.0.0.1" && "$d" != "::1" && "$d" != "localhost" ]]
}

# Р•РґРёРЅР°СЏ read-only РєР»Р°СЃСЃРёС„РёРєР°С†РёСЏ decoy-РїРѕР»РёС‚РёРєРё РґР»СЏ inbound.
decoy_policy_classify() {
  local id="$1" proto="$2" stream="${3:-}"
  [[ "$proto" == "tproxy" ]] && { echo tproxy; return 0; }
  if grep -qi '"security"[[:space:]]*:[[:space:]]*"reality"' <<<"$stream"; then
    if reality_external_dest "$id"; then echo reality-external; else echo reality-local; fi
    return 0
  fi
  case "$proto" in
    openflux|open-flux)
      echo no-decoy ;;
    naive|anytls|trusttunnel|trust-tunnel|hysteria|hysteria2|qwdtt|csqtt|csqdtt|wireguard|amnezia|amneziawg|awg|mtproto|tun)
      echo unsupported ;;
    *) echo no-decoy ;;
  esac
}

is_udp_proto() {
  case "$1" in
    hysteria|hysteria2|wireguard|amnezia|amneziawg|awg|qwdtt|csqdtt|csqtt|kroute|krout|krw) return 0 ;;
    *) return 1 ;;
  esac
}

# РџРѕСЂС‚С‹ UDP-РёРЅР±Р°СѓРЅРґРѕРІ РёР· Р‘Р” РїР°РЅРµР»Рё вЂ” Р•Р”РРќРЎРўР’Р•РќРќР«Р™ РёСЃС‚РѕС‡РЅРёРє РїСЂР°РІРґС‹ РґР»СЏ С„Р°Р№СЂРІРѕР»Р°.
# РЎРѕРєРµС‚-СЃРєР°РЅРёСЂРѕРІР°РЅРёРµ UDP РЅРµ РіРѕРґРёС‚СЃСЏ: xray Рё СЂРµР·РѕР»РІРµСЂС‹ РїР»РѕРґСЏС‚ РЅРµСЃРІСЏР·Р°РЅРЅС‹Рµ
# sendto()-СЃРѕРєРµС‚С‹ РЅР° ephemeral-РїРѕСЂС‚Р°С…, РЅРµРѕС‚Р»РёС‡РёРјС‹Рµ РїРѕ peer РѕС‚ СЃР»СѓС€Р°С‚РµР»РµР№.
udp_inbound_ports() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  sqlite3 "$XUI_DB" "SELECT id, protocol, port FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null |
  while IFS='|' read -r _id _pr _pt; do
    [[ -z "$_pt" ]] && continue
    is_udp_proto "$_pr" && echo "$_pt"
  done | sort -un
}

# Р—Р°РјРѕСЂРѕР·РєР° СЃР°РјРѕР»РµС‡РµРЅРёСЏ Рё Р·Р°С‰РёС‚Р° Р‘Р” РІС‹РІРµРґРµРЅС‹ РёР· Р°СЂС…РёС‚РµРєС‚СѓСЂС‹: РѕС‚РєР»РѕРЅРµРЅРёСЏ
# С‡РёРЅСЏС‚СЃСЏ РІСЂСѓС‡РЅСѓСЋ С‡РµСЂРµР· РјРµРЅСЋ. db_protect_on/off/remove вЂ” no-op Р·Р°РіР»СѓС€РєРё,
# РѕСЃС‚Р°РІР»РµРЅРЅС‹Рµ РїРѕРґ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёРµ РІС‹Р·РѕРІС‹; РѕС‚РґРµР»СЊРЅРѕРіРѕ СЃРѕСЃС‚РѕСЏРЅРёСЏ Р·Р°С‰РёС‚С‹ РЅРµС‚.
db_protect_on() { return 0; }
db_protect_off() { return 0; }

# Р”Р»СЏ С„СѓРЅРєС†РёР№ СЃРєСЂРёРїС‚Р°, РѕСЃРѕР·РЅР°РЅРЅРѕ РјРµРЅСЏСЋС‰РёС… Р·Р°С‰РёС‰С‘РЅРЅС‹Рµ РєР»СЋС‡Рё (dest/target,
# Р»РёС‚РµСЂР°Р»С‹ СЃРµСЂС‚РѕРІ, certFile/keyFile/hostname).
#
# Р’РђР–РќРћ (РёСЃРїСЂР°РІР»РµРЅРёРµ): СЂР°РЅСЊС€Рµ Р·РґРµСЃСЊ СЃС‚РѕСЏР»Р° RETURN-Р»РѕРІСѓС€РєР°
# (`trap 'db_protect_on' RETURN`), РЅРѕ bash РІС‹РїРѕР»РЅСЏРµС‚ RETURN-Р»РѕРІСѓС€РєСѓ РЎР РђР—РЈ РїСЂРё
# РІРѕР·РІСЂР°С‚Рµ РёР· СЃР°РјРѕР№ db_protect_suspend вЂ” С‚СЂРёРіРіРµСЂС‹ РІРѕР·РІСЂР°С‰Р°Р»РёСЃСЊ Р”Рћ РїСЂР°РІРєРё, Рё
# РєР°Р¶РґР°СЏ Р·Р°РїРёСЃСЊ dest/СЃРµСЂС‚РѕРІ РјРѕР»С‡Р° РѕС‚РєР°С‚С‹РІР°Р»Р°СЃСЊ С‚СЂРёРіРіРµСЂРѕРј, С…РѕС‚СЏ СЃРєСЂРёРїС‚ РїРёСЃР°Р»
# В«Reality dest в†’ вЂ¦В». РћС‚СЃСЋРґР° РІРµС‡РЅС‹Р№ С†РёРєР» В«Р°РІС‚РѕРїРѕС‡РёРЅРєРёВ» РєР°Р¶РґС‹Рµ 2 РјРёРЅСѓС‚С‹ Рё
# СЂР°СЃС…РѕР¶РґРµРЅРёРµ РєРѕРЅС„РёРіР° СЃ СЂР°Р±РѕС‚Р°СЋС‰РёРј nginx.
#
# РўРµРїРµСЂСЊ С‚СЂРёРіРіРµСЂС‹ РЅРµ СЂРѕРЅСЏСЋС‚СЃСЏ: СЃС‚Р°РІРёС‚СЃСЏ В«Р°СЂРµРЅРґР°В» (СЃС‚СЂРѕРєР° РІ sm_protect_off), РїСЂРё
# РєРѕС‚РѕСЂРѕР№ sm_prot_inb РЅРµ РІРјРµС€РёРІР°РµС‚СЃСЏ. РђСЂРµРЅРґР° СЃРЅРёРјР°РµС‚СЃСЏ СЏРІРЅРѕ
# (db_protect_resume) Р»РёР±Рѕ РёСЃС‚РµРєР°РµС‚ СЃР°РјР° С‡РµСЂРµР· 15 РјРёРЅСѓС‚ вЂ” Р·Р°С‰РёС‚Р° РЅРµ РѕСЃС‚Р°С‘С‚СЃСЏ
# РІС‹РєР»СЋС‡РµРЅРЅРѕР№ РЅР°РІСЃРµРіРґР°.
DB_PROTECT_SUSPENDED=0
db_protect_suspend() { return 0; }
db_protect_resume() { return 0; }

# =====================================================================
# РџРћР›РќР«Р™ РЎРќРРњРћРљ РЎРўР РћРљР РџР•Р Р•Р” РР—РњР•РќР•РќРР•Рњ (РґР»СЏ РѕС‚РєР°С‚Р° В«СЂРѕРІРЅРѕ РєР°Рє Р±С‹Р»РѕВ»)
#   settings РєРѕРїРёСЂСѓРµС‚СЃСЏ РїРѕ Р·РЅР°С‡РµРЅРёСЏРј (panel-journal.tsv), Р° inbounds/hosts
#   РїСЂР°РІСЏС‚СЃСЏ РІРЅСѓС‚СЂРё JSON-РїРѕР»РµР№ Рё СЃС‚СЂРѕРє вЂ” С‚Р°Рј СЃРЅРёРјР°РµРј Р’РЎР® СЃС‚СЂРѕРєСѓ С†РµР»РёРєРѕРј Рё
#   РїСЂРё РѕС‚РєР°С‚Рµ РІРѕР·РІСЂР°С‰Р°РµРј РµС‘ РґРѕСЃР»РѕРІРЅРѕ (СЃС‚РѕР»Р±С†С‹ С‡РёС‚Р°СЋС‚СЃСЏ РёР· СЃС…РµРјС‹ РІ РјРѕРјРµРЅС‚
#   РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ, РїРѕСЌС‚РѕРјСѓ СЃРЅРёРјРѕРє РЅРµ Р·Р°РІРёСЃРёС‚ РѕС‚ РІРµСЂСЃРёРё СЃС…РµРјС‹ РїР°РЅРµР»Рё).
# =====================================================================
panel_journal_capture_row() {
  # $1 = inbounds|hosts, $2 = id
  local kind="$1" id="$2" out="" rc=0
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" || -z "$id" ]] && return 0
  [[ -f "$JOURNAL_MARK" ]] || return 0
  case "$kind" in inbounds|hosts) ;; *) return 0 ;; esac
  mkdir -p "$BACKUP_DIR" 2>/dev/null || return 0
  [[ -s "$ROWS_JOURNAL" ]] && grep -q "^${kind}	${id}	" "$ROWS_JOURNAL" 2>/dev/null && return 0
  local has=0
  has=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
        "SELECT COUNT(*) FROM $kind WHERE id=$id;" 2>/dev/null || echo 0)
  if [[ "$has" == "0" ]]; then
    printf '%s\t%s\t0\t{}\t%s\n' "$kind" "$id" "$XUI_DB" >> "$ROWS_JOURNAL" 2>/dev/null || true
    return 0
  fi
  out=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
        "SELECT json_object($(inbounds_json_pairs "$kind" "$id")) FROM $kind WHERE id=$id;")
  rc=$?
  if [[ $rc -ne 0 || -z "$out" ]]; then
    # РјРѕР»С‡Р° С‚РµСЂСЏС‚СЊ СЃРЅРёРјРѕРє РЅРµР»СЊР·СЏ: Р±РµР· РЅРµРіРѕ РѕС‚РєР°С‚ РЅРµ РІРµСЂРЅС‘С‚ СЃС‚СЂРѕРєСѓ
    warn "journal: РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРЅСЏС‚СЊ СЃРЅРёРјРѕРє СЃС‚СЂРѕРєРё $kind#$id (РєРѕРґ $rc) вЂ” РѕС‚РєР°С‚ РµС‘ РЅРµ РІРѕСЃСЃС‚Р°РЅРѕРІРёС‚"
    return 1
  fi
  if ! printf '%s\t%s\t1\t%s\t%s\n' "$kind" "$id" "$out" "$XUI_DB" >> "$ROWS_JOURNAL" 2>/dev/null; then
    warn "journal: РЅРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РїРёСЃР°С‚СЊ СЃРЅРёРјРѕРє $kind#$id"; return 1
  fi
  return 0
}

# "РёРјСЏ", <Р·РЅР°С‡РµРЅРёРµ СЃС‚РѕР»Р±С†Р° РєР°Рє JSON> РґР»СЏ РІСЃРµС… СЃС‚РѕР»Р±С†РѕРІ С‚Р°Р±Р»РёС†С‹.
#   json_extract(col,'$') РѕС‚РґР°С‘С‚ Р·РЅР°С‡РµРЅРёРµ СЃ СЃРѕС…СЂР°РЅРµРЅРёРµРј С‚РёРїР° (JSON РѕСЃС‚Р°С‘С‚СЃСЏ
#   СЃС‚СЂСѓРєС‚СѓСЂРѕР№, Р° РЅРµ СЃС‚СЂРѕРєРѕР№); РґР»СЏ СЃРєР°Р»СЏСЂРѕРІ (id/port) extra-РєР»Р°СѓР·Р° CASE РїСЂРѕСЃС‚Рѕ
#   РѕС‚РґР°С‘С‚ Р·РЅР°С‡РµРЅРёРµ РєР°Рє РµСЃС‚СЊ. Р’РђР–РќРћ: РїСѓС‚СЊ РёРјРµРЅРЅРѕ '$', Р° РЅРµ '$.РёРјСЏ' вЂ” СЃС‚РѕР»Р±РµС†
#   СЃР°Рј СЏРІР»СЏРµС‚СЃСЏ JSON-РґРѕРєСѓРјРµРЅС‚РѕРј, Р° РЅРµ РѕР±СЉРµРєС‚РѕРј СЃ РєР»СЋС‡РѕРј-РёРјРµРЅРµРј СЃС‚РѕР»Р±С†Р°.
inbounds_json_pairs() {
  local kind="$1" col parts=""
  while IFS= read -r col; do
    [[ -z "$col" ]] && continue
    [[ -n "$parts" ]] && parts+=","
    parts+="'$col',(CASE WHEN json_valid(\"$col\") THEN json_extract(\"$col\",'\$') ELSE \"$col\" END)"
  done < <(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "PRAGMA table_info($kind);" 2>/dev/null | awk -F'|' '{print $2}')
  [[ -z "$parts" ]] && { printf "'' , NULL"; return 0; }
  printf '%s' "$parts"
}

# РћР±РЅРѕРІР»РµРЅРёРµ СЃС‚СЂРѕРєРё inbounds СЃ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРёРј СЃРЅРёРјРєРѕРј РґР»СЏ РѕС‚РєР°С‚Р°

# РЎРјРµРЅРёС‚СЊ listen РёРЅР±Р°СѓРЅРґР° РЅР°РїСЂСЏРјСѓСЋ РІ Р‘Р”, РїСЂРё mode=journal вЂ” СЃ Р·Р°РїРёСЃСЊСЋ РїСЂРµР¶РЅРµРіРѕ
# Р·РЅР°С‡РµРЅРёСЏ РІ LISTEN_JOURNAL (С„РѕСЂРјР°С‚ С‡РёС‚Р°С‚РµР»СЏ panel_journal_apply:
# id<TAB>Р·РЅР°С‡РµРЅРёРµ_РґР»СЏ_РѕС‚РєР°С‚Р°<TAB>db, СЃРїРµС†Р·РЅР°С‡РµРЅРёСЏ __NULL__/__EMPTY__).
#   $1 = id, $2 = РЅРѕРІРѕРµ Р·РЅР°С‡РµРЅРёРµ ('' | 127.0.0.1 | 0.0.0.0 | С‡С‚Рѕ СѓРіРѕРґРЅРѕ),
#   $3 = journal|direct (РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ journal)
# РџРµСЂРІРѕРµ РёР·РјРµРЅРµРЅРёРµ РґР»СЏ id вЂ” РїСЂРёРѕСЂРёС‚РµС‚РЅРѕРµ: РѕС‚РєР°С‚ РІРѕР·РІСЂР°С‰Р°РµС‚ РёСЃС…РѕРґРЅС‹Р№ listen,
# Р° РЅРµ РїСЂРѕРјРµР¶СѓС‚РѕС‡РЅС‹Р№. Р’РѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРѕ СЃР°РјРѕРґРѕСЃС‚Р°С‚РѕС‡РЅРѕ: РІ v1.0.15 С„СѓРЅРєС†РёСЋ СѓРґР°Р»РёР»Рё
# РІРјРµСЃС‚Рµ СЃРѕ СЃС‚Р°СЂС‹РјРё journal-С…РµР»РїРµСЂР°РјРё, Р° РІС‹Р·РѕРІС‹ (cdn-РїСЂРѕС„РёР»СЊ, РїРѕР»РЅС‹Р№ РѕС‚РєР°С‚)
# РѕСЃС‚Р°Р»РёСЃСЊ вЂ” СЃР»СѓС€Р°С‚РµР»СЊ РјРѕР»С‡Р° РЅРµ РїРµСЂРµРєР»СЋС‡Р°Р»СЃСЏ, В«command not foundВ» РіР°СЃРёР»СЃСЏ || true.
db_set_listen() {
  local id="$1" want="$2" mode="${3:-journal}"
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" || -z "$id" ]] && return 1
  # Р—РЅР°С‡РµРЅРёРµ РЅРµ РѕРіСЂР°РЅРёС‡РёРІР°РµРј СЃРїРёСЃРєРѕРј: РІ РїРѕР»Рµ РјРѕР¶РµС‚ Р»РµР¶Р°С‚СЊ С‡С‚Рѕ СѓРіРѕРґРЅРѕ (РІ С‚.С‡.
  # РІРїРёСЃР°РЅРЅРѕРµ СЂСѓРєР°РјРё), Рё РѕС‚РєР°С‚ РѕР±СЏР·Р°РЅ РІРµСЂРЅСѓС‚СЊ РёРјРµРЅРЅРѕ РµРіРѕ. РўСЂРµР±РѕРІР°РЅРёРµ РѕРґРЅРѕ вЂ”
  # Р±РµР· РєР°РІС‹С‡РµРє Рё РїРµСЂРµРІРѕРґРѕРІ СЃС‚СЂРѕРє, РёРЅР°С‡Рµ Р»РѕРјР°РµС‚СЃСЏ SQL-Р»РёС‚РµСЂР°Р».
  if [[ "$want" == *"'"* || "$want" == *$'\n'* ]]; then
    err "db_set_listen: Р·РЅР°С‡РµРЅРёРµ listen СЃРѕРґРµСЂР¶РёС‚ РєР°РІС‹С‡РєСѓ/РїРµСЂРµРІРѕРґ СЃС‚СЂРѕРєРё вЂ” Р·Р°РїРёСЃСЊ РЅРµРІРѕР·РјРѕР¶РЅР°"
    return 1
  fi
  if [[ "$mode" == "journal" ]]; then
    panel_journal_capture_row inbounds "$id" 2>/dev/null || true
    if ! awk -F'\t' -v i="$id" '$1==i{f=1} END{exit !f}' "$LISTEN_JOURNAL" 2>/dev/null; then
      local old enc
      old=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
            "SELECT CASE WHEN listen IS NULL THEN '__NULL__' WHEN listen='' THEN '__EMPTY__' ELSE listen END FROM inbounds WHERE id=$id;" 2>/dev/null || true)
      enc="${old:-__EMPTY__}"
      mkdir -p "$BACKUP_DIR" 2>/dev/null || true
      printf '%s\t%s\t%s\n' "$id" "$enc" "$XUI_DB" >> "$LISTEN_JOURNAL" 2>/dev/null || true
    fi
  fi
  local sq; sq=$(sql_escape "$want")
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "UPDATE inbounds SET listen='$sq' WHERE id=$id AND COALESCE(listen,'') <> '$sq';" 2>/dev/null || true
  return 0
}

# РЎС‚СЂРѕРєР° hosts/РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РІСЃРµР№ СЃС‚СЂРѕРєРё вЂ” С‚Р° Р¶Рµ Р»РѕРіРёРєР° РґР»СЏ С‚Р°Р±Р»РёС†С‹ hosts



# РџСЂРёРјРµРЅРёС‚СЊ Р¶СѓСЂРЅР°Р» РІ РѕР±СЂР°С‚РЅРѕРј РїРѕСЂСЏРґРєРµ: РІРµСЂРЅСѓС‚СЊ СЃС‚Р°СЂС‹Рµ Р·РЅР°С‡РµРЅРёСЏ.
# $1 = 1 вЂ” С‚РёС…Рѕ (Р¶СѓСЂРЅР°Р» РѕС‚РєР°С‚Р°, Р±РµР· РёРЅС‚РµСЂР°РєС‚РёРІР°)
panel_journal_apply() {
  local quiet="${1:-0}" n_set=0 n_listen=0 n_rows=0 skipped=0
  local key val db id set_clause
  if [[ -s "$PANEL_JOURNAL" ]]; then
    db_protect_off
    while IFS=$'\t' read -r _kind key val db; do
      [[ -z "$key" || -z "$db" || ! -f "$db" ]] && { skipped=$((skipped+1)); continue; }
      case "$val" in
        __NULL__)
          "$DB_BIN" "$db" "DELETE FROM settings WHERE key='$key';" >/dev/null 2>&1 \
            && n_set=$((n_set+1)) || skipped=$((skipped+1)) ;;
        *)
          local sq=""
          if [[ "$val" == "__EMPTY__" ]]; then sq=""; else sq=$(sql_escape "$val"); fi
          "$DB_BIN" "$db" "UPDATE settings SET value='$sq' WHERE key='$key';" >/dev/null 2>&1 \
            && n_set=$((n_set+1)) || skipped=$((skipped+1)) ;;
      esac
    done < "$PANEL_JOURNAL"
  fi
  if [[ -s "$ROWS_JOURNAL" ]]; then
    db_protect_off
    local rf="" rsql=""
    rf=$(mktemp /tmp/stack-rows.XXXXXX 2>/dev/null || true)
    if [[ -n "$rf" ]]; then
      rsql="$rf.sql"
      # Р“РѕС‚РѕРІРёРј SQL РїРѕ СЃРЅРёРјРєР°Рј СЃС‚СЂРѕРє. РџРёС€РµРј РІРѕ Р¤РђР™Р› СЏРІРЅС‹Рј utf-8: С‡РµСЂРµР·
      # sys.stdout РЅРµР»СЊР·СЏ вЂ” СЃРєСЂРёРїС‚ РІС‹СЃС‚Р°РІР»СЏРµС‚ LC_ALL=C, Рё РєРёСЂРёР»Р»РёС†Р° РІ Р·РЅР°С‡РµРЅРёСЏС…
      # СЂРѕРЅСЏРµС‚ python СЃ UnicodeEncodeError (РѕС‚РєР°С‚ РїСЂРё СЌС‚РѕРј РјРѕР»С‡Р° РЅРёС‡РµРіРѕ РЅРµ РґРµР»Р°Р»).
      # Р—РЅР°С‡РµРЅРёСЏ СЌРєСЂР°РЅРёСЂСѓСЋС‚СЃСЏ РєР°Рє JSON-СЃС‚СЂРѕРєРё, РїРѕСЌС‚РѕРјСѓ РІРѕР·РІСЂР°С‚ РґРѕСЃР»РѕРІРЅС‹Р№.
      command -v python3 >/dev/null 2>&1 && python3 - "$ROWS_JOURNAL" "$rsql" >/dev/null 2>"$rf.err" <<'PYROWS'
import json, os, sqlite3, sys

path, outpath = sys.argv[1], sys.argv[2]

def lit(v):
    # Р’ SQL-Р»РёС‚РµСЂР°Р» СЃС‚СЂРѕРєСѓ РѕС‚РґР°С‘Рј Р’ РћР”РРќРђР РќР«РҐ РєР°РІС‹С‡РєР°С…: json.dumps РґР°С‘С‚ РґРІРѕР№РЅС‹Рµ,
    # Р° SQLite СЃС‡РёС‚Р°РµС‚ "..." РёРґРµРЅС‚РёС„РёРєР°С‚РѕСЂРѕРј Рё РїР°РґР°РµС‚ В«unrecognized tokenВ».
    # РћРґРёРЅР°СЂРЅС‹Рµ РєР°РІС‹С‡РєРё РІРЅСѓС‚СЂРё Р·РЅР°С‡РµРЅРёСЏ СѓРґРІР°РёРІР°РµРј вЂ” С‚Р°Рє С‚СЂРµР±СѓРµС‚ SQL.
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "1" if v else "0"
    if isinstance(v, (int, float)):
        return json.dumps(v)
    if isinstance(v, (dict, list)):
        # json.loads СЂР°Р·РѕР±СЂР°Р» JSON-РєРѕР»РѕРЅРєСѓ РІ РѕР±СЉРµРєС‚ вЂ” РЅР°Р·Р°Рґ РІ JSON, Р° РќР• С‡РµСЂРµР·
        # str(): str(dict) РґР°С‘С‚ РѕРґРёРЅР°СЂРЅС‹Рµ РєР°РІС‹С‡РєРё Рё РїРёС€РµС‚ РІ Р‘Р” РјСѓСЃРѕСЂ РІРјРµСЃС‚Рѕ JSON
        return "'" + json.dumps(v, ensure_ascii=False).replace("'", "''") + "'"
    return "'" + str(v).replace("'", "''") + "'"

stmts = []
with open(path, encoding="utf-8", errors="replace") as fh:
    lines = [l.rstrip("\n") for l in fh if l.strip()]
# РѕР±СЂР°С‚РЅС‹Р№ РїРѕСЂСЏРґРѕРє: РїРѕСЃР»РµРґРЅСЏСЏ Р·Р°С„РёРєСЃРёСЂРѕРІР°РЅРЅР°СЏ СЃС‚СЂРѕРєР° РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµС‚СЃСЏ РїРµСЂРІРѕР№
for ln in reversed(lines):
    parts = ln.split("\t")
    if len(parts) < 4:
        continue
    kind, rid, existed, js = parts[0], parts[1], parts[2], parts[3]
    db = parts[4] if len(parts) > 4 else ""
    # РРЅР±Р°СѓРЅРґС‹ РЅРёРєРѕРіРґР° РЅРµ РѕС‚РєР°С‚С‹РІР°РµРј Рё РЅРµ СѓРґР°Р»СЏРµРј: РѕРЅРё РґРѕР»Р¶РЅС‹ РѕСЃС‚Р°С‚СЊСЃСЏ.
    if kind not in ("hosts",) or not db or not os.path.exists(db):
        continue
    try:
        data = json.loads(js) if js else {}
    except Exception:
        data = {}
    if existed != "1" or not data:
        stmts.append("DELETE FROM %s WHERE id=%s;" % (kind, rid))
        continue
    try:
        con = sqlite3.connect(db, timeout=10)
        cols = [r[1] for r in con.execute("PRAGMA table_info(%s)" % kind).fetchall()]
        con.close()
    except Exception:
        continue
    use = [c for c in cols if c in data]
    if not use:
        continue
    col_sql = ",".join('"%s"' % c.replace('"', '""') for c in use)
    vals = ",".join(lit(data[c]) for c in use)
    stmts.append("INSERT OR REPLACE INTO %s (%s) VALUES (%s);" % (kind, col_sql, vals))
with open(outpath, "w", encoding="utf-8", errors="replace") as fo:
    fo.write("\n".join(stmts) + ("\n" if stmts else ""))
PYROWS
      if [[ -s "$rsql" ]]; then
        # РѕРґРёРЅ РІС‹Р·РѕРІ sqlite3 РЅР° РІСЃРµ СЃС‚СЂРѕРєРё: Р±С‹СЃС‚СЂРµРµ Рё РЅРµ С‚РµСЂСЏРµС‚ РѕС€РёР±РєРё РїРѕ РѕРґРЅРѕР№
        if sqlite3 -cmd ".timeout 3000" "$XUI_DB" < "$rsql" >/dev/null 2>&1; then
          n_rows=$(grep -c . "$rsql" 2>/dev/null || echo 0)
        else
          warn "journal: SQL РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ СЃС‚СЂРѕРє РЅРµ РІС‹РїРѕР»РЅРёР»СЃСЏ С†РµР»РёРєРѕРј (СЃРј. РІС‹РІРѕРґ sqlite3 РІСЂСѓС‡РЅСѓСЋ)"
          skipped=$((skipped+1))
        fi
      elif [[ -s "$rf.err" ]]; then
        # РјРѕР»С‡Р°С‚СЊ РЅРµР»СЊР·СЏ: СЌС‚Рѕ СЂРѕРІРЅРѕ С‚РѕС‚ СЃР»СѓС‡Р°Р№, РєРѕРіРґР° РѕС‚РєР°С‚ В«РїСЂРѕС€С‘Р»В», Р° СЃС‚СЂРѕРєРё РЅРµ РІРµСЂРЅСѓР»РёСЃСЊ
        warn "journal: РЅРµ СѓРґР°Р»РѕСЃСЊ РїРѕРґРіРѕС‚РѕРІРёС‚СЊ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ СЃС‚СЂРѕРє inbounds/hosts:"
        head -3 "$rf.err" 2>/dev/null | sed 's/^/    /'
        skipped=$((skipped+1))
      fi
      rm -f "$rf" "$rsql" "$rf.err" 2>/dev/null || true
    fi
  fi
  if [[ -s "$LISTEN_JOURNAL" ]]; then
    db_protect_off
    while IFS=$'\t' read -r id val db; do
      [[ -z "$id" || -z "$db" || ! -f "$db" ]] && { skipped=$((skipped+1)); continue; }
      case "$val" in
        __NULL__)  set_clause="listen=NULL" ;;
        __EMPTY__) set_clause="listen=''" ;;
        *)         set_clause="listen='$(sql_escape "$val")'" ;;
      esac
      "$DB_BIN" "$db" "UPDATE inbounds SET $set_clause WHERE id=$id;" >/dev/null 2>&1 \
        && n_listen=$((n_listen+1)) || skipped=$((skipped+1))
    done < "$LISTEN_JOURNAL"
    unset set_clause
  fi
  if [[ "$quiet" != "1" ]]; then
    log "Р–СѓСЂРЅР°Р» РѕС‚РєР°С‚Р°: РЅР°СЃС‚СЂРѕРµРє РїР°РЅРµР»Рё РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРѕ $n_set, listen РёРЅР±Р°СѓРЅРґРѕРІ $n_listen, СЃС‚СЂРѕРє inbounds/hosts $n_rows${skipped:+, РїСЂРѕРїСѓС‰РµРЅРѕ: $skipped}"
  fi
  [[ "$n_set" -gt 0 || "$n_listen" -gt 0 || "$n_rows" -gt 0 || "$skipped" -gt 0 ]]
}

panel_journal_clear() {
  rm -f "$PANEL_JOURNAL" "$LISTEN_JOURNAL" "$ROWS_JOURNAL" "$JOURNAL_MARK" 2>/dev/null || true
}

# РџР°РЅРµР»СЊ РґРµСЂР¶РёС‚ СЃРѕСЃС‚РѕСЏРЅРёРµ РІ РїР°РјСЏС‚Рё вЂ” РЅР°СЃС‚СЂРѕР№РєРё РїРёС€РµРј С‚РѕР»СЊРєРѕ РїСЂРё РѕСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕР№
# РїР°РЅРµР»Рё, РёРЅР°С‡Рµ РїСЂРё СЂРµСЃС‚Р°СЂС‚Рµ РїР°РЅРµР»СЊ РїРµСЂРµС‚СЂС‘С‚ РїСЂР°РІРєСѓ СЃРІРѕРёРј СЃРѕСЃС‚РѕСЏРЅРёРµРј.
stop_xui_for_edit() {
  if systemctl is-active --quiet x-ui 2>/dev/null; then
    systemctl stop x-ui >/dev/null 2>&1 || true
    sleep 1
  fi
}

proto_remark() {
  local proto="$1" stream="${2:-}"
  case "$proto" in
    vless) grep -q '"security": *"reality"' <<<"$stream" && echo "reality" || echo "vless" ;;
    trusttunnel|trust-tunnel) echo "trusttunnel" ;;
    naive|naiveproxy) echo "naive" ;;
    mtproto) echo "mtproto" ;;
    hysteria|hysteria2) echo "hysteria2" ;;
    qwdtt) echo "qwdtt" ;;
    csqtt|csqdtt) echo "csqtt" ;;
    tproxy) echo "webproxy" ;;
    awg|amneziawg|wireguard) echo "awg" ;;
    *) echo "$proto" ;;
  esac
}

# РќР°Р·РІР°РЅРёРµ РёРЅР±Р°СѓРЅРґР° РґР»СЏ remark. РЎС‚СЂР°РЅР° РѕРїСЂРµРґРµР»СЏРµС‚СЃСЏ РѕРґРёРЅ СЂР°Р· РїРѕ РІРЅРµС€РЅРµРјСѓ IPv4
# СЃРµСЂРІРµСЂР° Рё РєСЌС€РёСЂСѓРµС‚СЃСЏ: СЌС‚Рѕ РЅРµ Р·Р°РІРёСЃРёС‚ РѕС‚ SNI/РґРѕРјРµРЅР° Рё РЅРµ С‚СЂРµР±СѓРµС‚ СЂСѓС‡РЅРѕРіРѕ РІРІРѕРґР°.
# РџСЂРёРјРµСЂ: В«рџ‡©рџ‡Є VLESS TCP RealityВ», В«рџ‡©рџ‡Є NaiveВ», В«рџ‡©рџ‡Є VLESS TCP Reality в„–2В».
SERVER_COUNTRY_CACHE="/root/stack-backups/server-country-code"
server_country_code() {
  local cc=""
  if [[ -s "$SERVER_COUNTRY_CACHE" ]]; then
    cc=$(tr -d '[:space:]' < "$SERVER_COUNTRY_CACHE" 2>/dev/null || true)
  fi
  if [[ ! "$cc" =~ ^[A-Z]{2}$ ]]; then
    cc=$(curl -4 -fsS --connect-timeout 3 --max-time 6 https://ipapi.co/country/ 2>/dev/null | tr -d '[:space:]' | tr '[:lower:]' '[:upper:]' || true)
    [[ "$cc" =~ ^[A-Z]{2}$ ]] && { mkdir -p "$(dirname "$SERVER_COUNTRY_CACHE")" 2>/dev/null || true; printf '%s\n' "$cc" > "$SERVER_COUNTRY_CACHE" 2>/dev/null || true; }
  fi
  printf '%s' "$cc"
}
country_flag() {
  # Р¤Р»Р°Рі С…СЂР°РЅРёС‚СЃСЏ РІ remark РєР°Рє РЅР°СЃС‚РѕСЏС‰РёР№ Unicode emoji (РґРІРµ regional
  # indicator-Р±СѓРєРІС‹), Р° РЅРµ РєР°Рє С‚РµРєСЃС‚РѕРІР°СЏ Р·Р°РјРµРЅР° [SE]. РџРµС‡Р°С‚Р°РµРј РµРіРѕ С‡РµСЂРµР·
  # Python, С‡С‚РѕР±С‹ РЅРµ Р·Р°РІРёСЃРµС‚СЊ РѕС‚ РѕСЃРѕР±РµРЅРЅРѕСЃС‚РµР№ printf/Р»РѕРєР°Р»Рё Bash.
  local cc="${1^^}"
  [[ "$cc" =~ ^[A-Z]{2}$ ]] || return 0
  python3 - "$cc" <<'PYFLAG'
import sys
cc = sys.argv[1].upper()
if len(cc) == 2 and cc.isascii() and cc.isalpha():
    print(''.join(chr(127397 + ord(c)) for c in cc), end='')
PYFLAG
}
inbound_remark_base() {
  local proto="$1" transport="$2" security="$3" label=""
  case "$proto:$transport:$security" in
    vless:tcp:reality) label="VLESS TCP Reality" ;;
    vless:tcp:tls)     label="VLESS TCP TLS" ;;
    vless:xhttp:reality) label="VLESS XHTTP Reality" ;;
    vless:xhttp:tls)   label="VLESS XHTTP TLS" ;;
    vless:xhttp:*)     label="VLESS XHTTP" ;;
    vless:*)           label="VLESS" ;;
    naive:* )          label="Naive" ;;
    trusttunnel:*|trust-tunnel:*) label="TrustTunnel" ;;
    anytls:*)          label="AnyTLS" ;;
    trojan:*)          label="Trojan" ;;
    shadowsocks:*)     label="Shadowsocks" ;;
    hysteria:*|hysteria2:*) label="Hysteria2" ;;
    qwdtt:*)           label="QWDT" ;;
    csqtt:*)           label="CSQTT" ;;
    tproxy:*)          label="TG Web Proxy" ;;
    # AWG: РІРµСЂСЃРёСЏ Р±РµСЂС‘Рј РёР· transport (awg31/awg20) вЂ” РёРјСЏ РёРЅР±Р°СѓРЅРґР° РѕР±СЏР·Р°РЅРѕ
    # РїРѕРєР°Р·С‹РІР°С‚СЊ РІРµСЂСЃРёСЋ AmneziaWG, Р° РЅРµ РїСЂРѕСЃС‚Рѕ В«AwgВ».
    awg:awg31:*)       label="AmneziaWG 3.1" ;;
    awg:awg20:*)       label="AmneziaWG 2.0" ;;
    awg:*)             label="AmneziaWG" ;;
    *)                 label="${proto^}" ;;
  esac
  printf '%s' "$label"
}
# Р”РѕР±Р°РІР»СЏРµС‚ С„Р»Р°Рі СЃС‚СЂР°РЅС‹ Рє СѓР¶Рµ СЃРѕР·РґР°РЅРЅС‹Рј СЃС‚Р°РЅРґР°СЂС‚РЅС‹Рј РёРјРµРЅР°Рј РёРЅР±Р°СѓРЅРґРѕРІ.
# РќСѓР¶РµРЅ РґР»СЏ РјРёРіСЂР°С†РёРё: СЃС‚Р°СЂС‹Рµ Р·Р°РїРёСЃРё РјРѕРіР»Рё Р±С‹С‚СЊ СЃРѕР·РґР°РЅС‹, РєРѕРіРґР° geo-API Р±С‹Р»
# РІСЂРµРјРµРЅРЅРѕ РЅРµРґРѕСЃС‚СѓРїРµРЅ, РїРѕСЌС‚РѕРјСѓ Сѓ РЅРёС… remark РѕСЃС‚Р°Р»СЃСЏ Р±РµР· С„Р»Р°РіР°.
backfill_country_remarks() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  local cc flag id proto stream remark transport security base new suffix
  cc=$(server_country_code)
  flag=$(country_flag "$cc")
  [[ -n "$flag" ]] || return 0
  while IFS='|' read -r id proto stream remark; do
    [[ -n "$id" && -n "$remark" && "$remark" != "$flag"* ]] || continue
    transport=$(grep -oE '"network"[[:space:]]*:[[:space:]]*"[^"]+' <<<"$stream" | head -1 | sed 's/.*"//')
    security=$(grep -oE '"security"[[:space:]]*:[[:space:]]*"[^"]+' <<<"$stream" | head -1 | sed 's/.*"//')
    [[ -n "$transport" ]] || transport="tcp"
    [[ -n "$security" ]] || security="none"
    base=$(inbound_remark_base "$proto" "$transport" "$security")
    if [[ "$remark" == "$base" ]]; then
      new="$flag $remark"
    elif [[ "$remark" =~ ^${base//\/\\}[^0-9]*в„–[0-9]+$ ]]; then
      suffix="${remark#"$base"}"
      new="$flag $base$suffix"
    elif [[ "$remark" == *"$base"* ]]; then
      # Р’ СЃС‚Р°СЂС‹С… РІРµСЂСЃРёСЏС… emoji-С„Р»Р°Рі РјРѕРі СЃРѕС…СЂР°РЅРёС‚СЊСЃСЏ РєР°Рє В«пїЅпїЅпїЅпїЅВ».
      # Р’РѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј РёРјСЏ РїРѕ РїСЂРѕС‚РѕРєРѕР»Сѓ Рё РѕСЃС‚Р°РІР»СЏРµРј РІРѕР·РјРѕР¶РЅС‹Р№ в„–N.
      suffix="${remark#*"$base"}"
      new="$flag $base$suffix"
    else
      continue
    fi
    sqlite3 "$XUI_DB" "UPDATE inbounds SET remark='$(sql_escape "$new")' WHERE id=$id;" 2>/dev/null || true
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,COALESCE(stream_settings,''),COALESCE(remark,'') FROM inbounds WHERE enable=1;" 2>/dev/null || true)
}

# Р’РѕР·РІСЂР°С‰Р°РµС‚ remark СЃ РїРѕСЂСЏРґРєРѕРІС‹Рј РЅРѕРјРµСЂРѕРј С‚РѕР»СЊРєРѕ РїСЂРё РїРѕРІС‚РѕСЂРµ С‚РѕРіРѕ Р¶Рµ С‚РёРїР°.
inbound_remark_next() {
  local proto="$1" transport="$2" security="$3" base flag prefix n=1 max=0 r suffix
  base=$(inbound_remark_base "$proto" "$transport" "$security")
  flag=$(country_flag "$(server_country_code)")
  prefix="${flag:+$flag }$base"
  while IFS= read -r r; do
    [[ "$r" == "$prefix" ]] && (( max < 1 )) && max=1
    local re="^${prefix//\/\\} в„–([0-9]+)$"
    if [[ "$r" =~ $re ]]; then
      n="${BASH_REMATCH[1]}"; (( n > max )) && max=$n
    fi
  done < <(sqlite3 "$XUI_DB" "SELECT COALESCE(remark,'') FROM inbounds WHERE remark IS NOT NULL;" 2>/dev/null || true)
  (( max > 0 )) && printf '%s в„–%d' "$prefix" "$((max+1))" || printf '%s' "$prefix"
}

# IP СЃРµСЂРІРµСЂР° (IPv4) вЂ” РґР»СЏ subHost Сѓ tunnel-РїСЂРѕС‚РѕРєРѕР»РѕРІ
server_ip4() {
  local ip=""
  ip=$(curl -4 -s --connect-timeout 4 --max-time 8 ifconfig.me 2>/dev/null | tr -d '[:space:]')
  [[ -z "$ip" ]] && ip=$(hostname -I 2>/dev/null | awk '{print $1}')
  echo "$ip"
}

# РўСЂРёРіРіРµСЂС‹ СЃРёРЅС…СЂРѕРЅРёР·Р°С†РёРё РєР»РёРµРЅС‚РѕРІ qwdtt/csqtt/tproxy (РєР°Рє РІ lucx-ui-pro):
# РєР»РёРµРЅС‚С‹ С…СЂР°РЅСЏС‚СЃСЏ РІ clients+client_inbounds, Р° inbounds.settings[].clients Р·РµСЂРєР°Р»РёС‚СЃСЏ
ensure_shareonly_triggers() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  sqlite3 "$XUI_DB" <<'SQL' 2>/dev/null || true
UPDATE inbounds
SET settings = json_set(
  CASE WHEN json_valid(settings) THEN settings ELSE '{}' END,
  '$.clients',
  CASE WHEN json_type(json_extract(settings, '$.clients')) = 'array'
       THEN json_extract(settings, '$.clients')
       ELSE json('[]') END
)
WHERE protocol IN ('qwdtt','csqtt','tproxy','awg');
DROP TRIGGER IF EXISTS lucx_shareonly_clients_ins;
DROP TRIGGER IF EXISTS lucx_shareonly_clients_del;
CREATE TRIGGER lucx_shareonly_clients_ins
AFTER INSERT ON client_inbounds
WHEN EXISTS (SELECT 1 FROM inbounds WHERE id = NEW.inbound_id AND protocol IN ('qwdtt','csqtt','tproxy','awg'))
BEGIN
  UPDATE inbounds SET settings = json_insert(
    json_set(
      settings,
      '$.clients',
      CASE WHEN json_type(json_extract(settings, '$.clients')) = 'array'
           THEN json_extract(settings, '$.clients')
           ELSE json('[]') END
    ),
    '$.clients[#]',
    json_object(
      'email', COALESCE((SELECT email FROM clients WHERE id = NEW.client_id), ''),
      'enable', json('true')
    )
  )
  WHERE id = NEW.inbound_id
    AND COALESCE((SELECT email FROM clients WHERE id = NEW.client_id), '') != ''
    AND NOT EXISTS (
      SELECT 1 FROM json_each(
        CASE WHEN json_type(json_extract(inbounds.settings, '$.clients')) = 'array'
             THEN json_extract(inbounds.settings, '$.clients')
             ELSE json('[]') END
      )
      WHERE json_extract(value, '$.email') = (SELECT email FROM clients WHERE id = NEW.client_id)
    );
END;
CREATE TRIGGER lucx_shareonly_clients_del
AFTER DELETE ON client_inbounds
WHEN EXISTS (SELECT 1 FROM inbounds WHERE id = OLD.inbound_id AND protocol IN ('qwdtt','csqtt','tproxy','awg'))
BEGIN
  UPDATE inbounds SET settings = json_set(
    settings,
    '$.clients',
    (
      SELECT json_group_array(json(value))
      FROM json_each(
        CASE WHEN json_type(json_extract(inbounds.settings, '$.clients')) = 'array'
             THEN json_extract(inbounds.settings, '$.clients')
             ELSE json('[]') END
      )
      WHERE json_extract(value, '$.email') != (SELECT email FROM clients WHERE id = OLD.client_id)
         OR (SELECT email FROM clients WHERE id = OLD.client_id) IS NULL
    )
  )
  WHERE id = OLD.inbound_id;
END;
SQL
}

# РљР°РјСѓС„Р»СЏР¶-СЃР°Р№С‚ РґР»СЏ tproxy: РќР•Р™РўР РђР›Р¬РќРђРЇ Р·Р°РіР»СѓС€РєР° (blog), РќР• СЃРІСЏР·Р°РЅРЅР°СЏ СЃ Telegram вЂ”
# РјРёРјРёРєСЂРёСЏ РїРѕРґ Telegram РЅР° tg-РґРѕРјРµРЅРµ = РїСЂСЏРјР°СЏ РїРѕРґСЃРєР°Р·РєР°, С‡С‚Рѕ Р·Р° РЅРёРј tg-РїСЂРѕРєСЃРё.
ensure_tproxy_site() {
  mkdir -p /var/www/html 2>/dev/null || true
  rm -f /var/www/html/telegram.html 2>/dev/null || true   # СЃР»РµРґ РїСЂРѕС€Р»РѕР№ РІРµСЂСЃРёРё
  # РїРµСЂРµР·Р°РїРёСЃС‹РІР°РµРј Р’РЎР•Р“Р”Рђ: РїСѓСЃС‚С‹С€РєР°/СЃС‚Р°СЂС‹Р№ index = Р±РµР»С‹Р№ Р»РёСЃС‚ РґР»СЏ РїРѕСЃС‚РѕСЂРѕРЅРЅРёС…
  if [[ -n "$DECOY_TPL_DIR" && -f "$DECOY_TPL_DIR/blog.html" ]]; then
    cp -f "$DECOY_TPL_DIR/blog.html" /var/www/html/index.html 2>/dev/null || true
  elif [[ ! -s /var/www/html/index.html ]]; then
    printf '%s\n' \
      '<!DOCTYPE html><html><head><meta charset="utf-8"><title></title></head><body></body></html>' \
      > /var/www/html/index.html
  fi
  chmod 644 /var/www/html/index.html 2>/dev/null || true
}

# РѕС‚РєСЂС‹С‚СЊ UDP-РїРѕСЂС‚С‹ РІ UFW, РµСЃР»Рё РѕРЅ Р°РєС‚РёРІРµРЅ
ufwd_allow_udp() {
  command -v ufw >/dev/null 2>&1 || return 0
  ufw status 2>/dev/null | grep -q "Status: active" || return 0
  local p
  for p in "$@"; do ufw allow "$p/udp" >/dev/null 2>&1 || true; done
}

# =====================================================================
# ADGUARD HOME
# =====================================================================
# СЃРІРѕР±РѕРґРЅС‹Р№ РїРѕСЂС‚ РґР»СЏ web-UI AdGuard: 3000, РµСЃР»Рё Р·Р°РЅСЏС‚ вЂ” РїРµСЂРІС‹Р№ СЃРІРѕР±РѕРґРЅС‹Р№ РёР· 3001..3099
adg_pick_port() {
  local p="$ADG_WEB_PORT" i
  if port_in_use "$p"; then
    for i in $(seq 3001 3099); do
      port_in_use "$i" || { p=$i; break; }
    done
  fi
  ADG_WEB_PORT="$p"
}

# bcrypt-С…СЌС€ РґР»СЏ AdGuard (Go bcrypt РїРѕРЅРёРјР°РµС‚ $2a/$2b/$2y): python3 в†’ htpasswd
adg_bcrypt() {
  local pw="$1" h=""
  if command -v python3 >/dev/null 2>&1; then
    # 1) pip-РјРѕРґСѓР»СЊ bcrypt (РѕСЃРЅРѕРІРЅРѕР№; РјРѕРґСѓР»СЊ crypt РЈР”РђР›РЃРќ РёР· Python 3.13+)
    h=$(python3 -c 'import sys
try:
    import bcrypt
    sys.stdout.write(bcrypt.hashpw(sys.argv[1].encode(), bcrypt.gensalt(10)).decode())
except Exception:
    sys.exit(1)' "$pw" 2>/dev/null || true)
    [[ "$h" == \$2* ]] && { echo "$h"; return 0; }
    # 2) stdlib crypt (Python < 3.13)
    h=$(python3 -c 'import sys
try:
    import crypt
    sys.stdout.write(crypt.crypt(sys.argv[1], crypt.mksalt(crypt.METHOD_BLOWFISH)))
except Exception:
    sys.exit(1)' "$pw" 2>/dev/null || true)
    [[ "$h" == \$2* ]] && { echo "$h"; return 0; }
  fi
  # 3) htpasswd (СЃС‚Р°РІРёРј apache2-utils РїСЂРё РЅРµРѕР±С…РѕРґРёРјРѕСЃС‚Рё)
  command -v htpasswd >/dev/null 2>&1 || apt-get install -y apache2-utils >/dev/null 2>&1 || true
  if command -v htpasswd >/dev/null 2>&1; then
    h=$(htpasswd -bnBC 10 "" "$pw" 2>/dev/null | tr -d ':\n' || true)
    [[ "$h" == \$2* ]] && { echo "$h"; return 0; }
  fi
  return 1
}

# Р·Р°РїРёСЃР°С‚СЊ Р°РґРјРёРЅР° AdGuard (Р·Р°РјРµРЅСЏРµС‚ РІСЃРµС… РїРѕР»СЊР·РѕРІР°С‚РµР»РµР№; РїСЂРѕРїСѓСЃРєР°РµС‚ РІРёР·Р°СЂРґ РїРµСЂРІРѕРіРѕ Р·Р°РїСѓСЃРєР°)
adg_set_admin() {
  local cfg="$ADG_CONFIG" user="$1" pass="$2"
  if [[ -z "$cfg" || ! -f "$cfg" ]]; then
    local c2
    for c2 in /opt/AdGuardHome/AdGuardHome.yaml /root/AdGuardHome/AdGuardHome.yaml \
              /etc/AdGuardHome.yaml /etc/adguardhome/AdGuardHome.yaml; do
      [[ -f "$c2" ]] && { cfg="$c2"; ADG_CONFIG="$c2"; break; }
    done
  fi
  [[ -z "$cfg" || ! -f "$cfg" ]] && { err "adg_set_admin: AdGuardHome.yaml РЅРµ РЅР°Р№РґРµРЅ (ADG_CONFIG='$ADG_CONFIG')"; return 1; }
  local hash
  hash=$(adg_bcrypt "$pass") || { err "adg_set_admin: РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРѕР·РґР°С‚СЊ bcrypt-С…СЌС€ (РЅРµС‚ python3-bcrypt Рё htpasswd)"; return 1; }
  local svc="${ADG_SERVICE:-AdGuardHome}"
  systemctl stop "$svc" 2>/dev/null || true
  if grep -q '^users:' "$cfg"; then
    # Р·Р°РјРµРЅСЏРµРј Р’Р•РЎР¬ Р±Р»РѕРє users (РґРѕ СЃР»РµРґСѓСЋС‰РµР№ СЃС‚СЂРѕРєРё РІРµСЂС…РЅРµРіРѕ СѓСЂРѕРІРЅСЏ) вЂ” РёРЅР°С‡Рµ
    # СЃС‚Р°СЂС‹Р№ РІР»РѕР¶РµРЅРЅС‹Р№ password: РѕСЃС‚Р°С‘С‚СЃСЏ СЂСЏРґРѕРј СЃ РЅРѕРІС‹Рј в†’ yaml РЅРµ РїР°СЂСЃРёС‚СЃСЏ
    awk -v n="  - name: $user" -v p="    password: $hash" '
      /^users:/ { print; print n; print p; inu=1; next }
      inu && /^[^ #]/ { inu=0 }
      inu { next }
      { print }
    ' "$cfg" > "$cfg.new" && mv "$cfg.new" "$cfg"
  else
    printf 'users:\n  - name: %s\n    password: %s\n' "$user" "$hash" >> "$cfg"
  fi
  systemctl start "$svc" 2>/dev/null || true
  sleep 1
  return 0
}

# bootstrap РєРѕРЅС„РёРіР° AdGuard РїСЂРё Р§РРЎРўРћР™ СѓСЃС‚Р°РЅРѕРІРєРµ: Р±РµР· yaml СЃРµСЂРІРёСЃ РІРёСЃРёС‚
# РІ СЂРµР¶РёРјРµ РІРёР·Р°СЂРґР° РЅР° 0.0.0.0:3000. РљРѕРЅС„РёРі РќР• РїРёС€РµРј СЂСѓРєР°РјРё (СЃС…РµРјР° РјРµРЅСЏРµС‚СЃСЏ
# РјРµР¶РґСѓ РІРµСЂСЃРёСЏРјРё) вЂ” РїСЂРѕС…РѕРґРёРј РѕС„РёС†РёР°Р»СЊРЅС‹Р№ РІРёР·Р°СЂРґ С‡РµСЂРµР· РµРіРѕ API: AdGuard СЃР°Рј
# РіРµРЅРµСЂРёСЂСѓРµС‚ СЂРѕРґРЅРѕР№ AdGuardHome.yaml (web 127.0.0.1, DNS bind 127.0.0.1:53).
adg_bootstrap_config() {
  local admin_pass="$1"
  local cfg="${ADG_CONFIG:-/opt/AdGuardHome/AdGuardHome.yaml}"
  local dir; dir=$(dirname "$cfg")
  mkdir -p "$dir/data" "$dir/filters" 2>/dev/null || true
  systemctl start "$ADG_SERVICE" 2>/dev/null || true
  sleep 2
  local code=""
  code=$(curl -s -o /tmp/.agh-install.json -w '%{http_code}' --max-time 20 \
    -X POST http://127.0.0.1:3000/control/install/configure \
    -H 'Content-Type: application/json' \
    -d "{\"web\":{\"ip\":\"127.0.0.1\",\"port\":$ADG_WEB_PORT},\"dns\":{\"ip\":\"127.0.0.1\",\"port\":53},\"username\":\"admin\",\"password\":\"$admin_pass\"}" 2>/dev/null) || true
  if [[ "$code" != "200" ]]; then
    err "AdGuard wizard API РЅРµ РѕС‚РІРµС‚РёР» 200 (got: $code)"
    head -c 300 /tmp/.agh-install.json 2>/dev/null; echo
    return 1
  fi
  # СЃРµСЂРІРёСЃ РїРµСЂРµР·Р°РїСѓСЃРєР°РµС‚СЃСЏ СЃР°Рј вЂ” Р¶РґС‘Рј РЅРѕРІС‹Р№ РїРѕСЂС‚
  local i
  for i in 1 2 3 4 5 6; do
    ss -tlnH "sport = :$ADG_WEB_PORT" 2>/dev/null | grep -q . && break
    sleep 2
  done
  if ! ss -tlnH "sport = :$ADG_WEB_PORT" 2>/dev/null | grep -q .; then
    err "AdGuard РЅРµ РїРѕРґРЅСЏР»СЃСЏ РЅР° 127.0.0.1:$ADG_WEB_PORT РїРѕСЃР»Рµ РІРёР·Р°СЂРґР°"
    return 1
  fi
  ADG_CONFIG="$cfg"
  # upstream'С‹ в†’ Cloudflare/Google (РґРµС„РѕР»С‚ РІРёР·Р°СЂРґР° вЂ” quad9)
  curl -s -o /dev/null --max-time 10 -u "admin:$admin_pass" \
    -X POST "http://127.0.0.1:$ADG_WEB_PORT/control/dns_config" \
    -H 'Content-Type: application/json' \
    -d '{"upstream_dns":["https://dns.cloudflare.com/dns-query","8.8.8.8"],"bootstrap_dns":["1.1.1.1","8.8.8.8"]}' 2>/dev/null || true
  log "AdGuard: РєРѕРЅС„РёРі СЃРѕР·РґР°РЅ РІРёР·Р°СЂРґ-API (web 127.0.0.1:$ADG_WEB_PORT В· DNS 127.0.0.1:53 В· admin/admin_pass)"
  return 0
}

# С„Р°РєС‚РёС‡РµСЃРєРёР№ web-РїРѕСЂС‚ AdGuard: РїСЂРё РІРєР»СЋС‡С‘РЅРЅРѕРј TLS вЂ” tls.port_https (UI+DoH),
# РёРЅР°С‡Рµ вЂ” РїРѕСЂС‚ РёР· http.address
adg_config_port() {
  local cfg="$ADG_CONFIG"
  if [[ -z "$cfg" || ! -f "$cfg" ]]; then echo "$ADG_WEB_PORT"; return; fi
  local tls_en="" p=""
  tls_en=$(awk '/^tls:/{f=1;next} /^[^ ]/{f=0} f && /^  enabled:/{print $2; exit}' "$cfg" 2>/dev/null | tr -d '"')
  if [[ "$tls_en" == "true" ]]; then
    p=$(awk '/^tls:/{f=1;next} /^[^ ]/{f=0} f && /^  port_https:/{print $2; exit}' "$cfg" 2>/dev/null)
    if [[ -n "$p" && "$p" != "0" ]]; then echo "$p"; return; fi
  fi
  p=$(awk '/^http:/{f=1;next} /^[^ ]/{f=0} f && /^  address:/{n=split($2,a,":"); print a[n]; exit}' "$cfg" 2>/dev/null | tr -d '"')
  echo "${p:-$ADG_WEB_PORT}"
}

install_adguard_home() {
  line; echo -e "${B}   РЈРЎРўРђРќРћР’РљРђ ADGUARD HOME${N}"; line
  detect_env
  [[ "$ADG_PRESENT" == true ]] && { log "AdGuard Home СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ"; return 0; }
  warn "AdGuard Home РЅРµ РЅР°Р№РґРµРЅ вЂ” СѓСЃС‚Р°РЅР°РІР»РёРІР°СЋ (РІРѕРїСЂРѕСЃ Р·Р°РґР°С‘С‚СЃСЏ РѕРґРёРЅ СЂР°Р·, РІ РЅР°С‡Р°Р»Рµ СЃРєСЂРёРїС‚Р°)."

  log "Р—Р°РїСѓСЃРє СѓСЃС‚Р°РЅРѕРІС‰РёРєР° AdGuard Home..."
  if ! curl -s -S -L "$ADG_INSTALL_URL" | sh -s -- -v; then
    err "РћС€РёР±РєР° СѓСЃС‚Р°РЅРѕРІРєРё AdGuard Home"; return 1
  fi
  sleep 3
  detect_env
  [[ "$ADG_PRESENT" != true ]] && { err "AdGuardHome.service РЅРµ РЅР°Р№РґРµРЅ"; return 1; }

  log "AdGuard Home СѓСЃС‚Р°РЅРѕРІР»РµРЅ: $ADG_SERVICE"
  adg_pick_port
  local adg_user="${U_ADG_USER:-admin}" adg_pass=""
  adg_pass=$(openssl rand -base64 18 2>/dev/null | tr -dc 'a-zA-Z0-9' | head -c 16)
  [[ -z "$adg_pass" ]] && adg_pass="AdG$(date +%s)"
  # С‡РёСЃС‚Р°СЏ СѓСЃС‚Р°РЅРѕРІРєР°: РєРѕРЅС„РёРіР° РЅРµС‚ (СЂРµР¶РёРј РІРёР·Р°СЂРґР°) в†’ СЃРѕР·РґР°С‘Рј С‡РµСЂРµР· wizard-API
  if [[ -z "$ADG_CONFIG" || ! -f "$ADG_CONFIG" ]]; then
    adg_bootstrap_config "$adg_pass" || warn "Bootstrap AdGuardHome.yaml РЅРµ СѓРґР°Р»СЃСЏ вЂ” РЅР°СЃС‚СЂРѕР№С‚Рµ РІСЂСѓС‡РЅСѓСЋ"
  fi
  configure_adguard_local || warn "РќР°СЃС‚СЂРѕР№С‚Рµ bind РІСЂСѓС‡РЅСѓСЋ"

  # Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРёРµ СѓС‡С‘С‚РЅС‹Рµ РґР°РЅРЅС‹Рµ Р°РґРјРёРЅР° вЂ” РІРёР·Р°СЂРґ РЅРµ РЅСѓР¶РµРЅ
  adg_user="${U_ADG_USER:-admin}" adg_pass=""
  adg_pass=$(openssl rand -base64 18 2>/dev/null | tr -dc 'a-zA-Z0-9' | head -c 16)
  [[ -z "$adg_pass" ]] && adg_pass="AdG$(date +%s)"
  if adg_set_admin "$adg_user" "$adg_pass"; then
    {
      echo "AdGuard Home вЂ” $(date '+%F %T')"
      echo "  URL:    https://<РґРѕРјРµРЅ-РїР°РЅРµР»Рё>/          (РїРѕСЃР»Рµ Рї.1, decoy=adguard)"
      echo "  DoH:    https://<РґРѕРјРµРЅ-РїР°РЅРµР»Рё>/dns-query"
      echo "  Р›РѕРіРёРЅ:  $adg_user"
      echo "  РџР°СЂРѕР»СЊ: $adg_pass"
    } > /root/adguard-credentials.txt 2>/dev/null || true
    chmod 600 /root/adguard-credentials.txt 2>/dev/null || true
  fi

  # РЎР•Р Рў РґР»СЏ AdGuard: РїСЂРёРѕСЂРёС‚РµС‚ вЂ” СЃРµСЂС‚, РІРїРёСЃР°РЅРЅС‹Р№ РІ x-ui (РІ С‚.С‡. РёР· РјРµРЅСЋ x-ui),
  # Р·Р°С‚РµРј subDomain/wildcard С‡РµСЂРµР· cert_paths; Р±РµР· РІСЃРµРіРѕ вЂ” СЃР°РјРѕРїРѕРґРїРёСЃР°РЅРЅС‹Р№ fallback.
  local _adg_cert="" _adg_key="" _adg_cp="" _adg_dom="" _adg_pline=""
  _adg_pline=$(panel_cert_from_db) || true
  if [[ -n "$_adg_pline" ]]; then
    _adg_cert="${_adg_pline%% *}"; _adg_key=$(echo "$_adg_pline" | awk '{print $2}')
  else
    _adg_dom=$(xui_get subDomain 2>/dev/null || true)
    [[ -n "$_adg_dom" ]] && _adg_cp=$(cert_paths "$_adg_dom" 2>/dev/null || true)
    if [[ -z "$_adg_cp" && -f "$WILDCARD_STATE" ]]; then
      _adg_dom=$(head -n 1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]')
      [[ -n "$_adg_dom" ]] && _adg_cp=$(cert_paths "adg.$_adg_dom" 2>/dev/null || true)
    fi
    [[ -n "$_adg_cp" ]] && { _adg_cert="${_adg_cp%% *}"; _adg_key="${_adg_cp##* }"; }
  fi

  configure_adguard_doh "" "$_adg_cert" "$_adg_key" || warn "DoH-РЅР°СЃС‚СЂРѕР№РєР° AdGuardHome.yaml РЅРµ РїСЂРёРјРµРЅРµРЅР° Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё"

  echo
  line
  log "AdGuard Home СѓСЃС‚Р°РЅРѕРІР»РµРЅ Рё РЅР°СЃС‚СЂРѕРµРЅ:"
  echo "   web:     127.0.0.1:$ADG_WEB_PORT (СЃРЅР°СЂСѓР¶Рё вЂ” С‚РѕР»СЊРєРѕ https://<РґРѕРјРµРЅ-РїР°РЅРµР»Рё>/)"
  echo "   DoH:     https://<РґРѕРјРµРЅ-РїР°РЅРµР»Рё>/dns-query"
  echo "   Р»РѕРіРёРЅ:   $adg_user"
  echo "   РїР°СЂРѕР»СЊ:  $adg_pass"
  echo "   в†’ СЃРѕС…СЂР°РЅРµРЅРѕ РІ /root/adguard-credentials.txt"
  line

  # SNI-СЃС‚РµРє СѓР¶Рµ РїРѕРґРЅСЏС‚? РЎСЂР°Р·Сѓ РІРµС€Р°РµРј AdGuard Р·Р° РґРѕРјРµРЅ РїР°РЅРµР»Рё вЂ” РёРЅР°С‡Рµ
  # nginx-РїСЂР°РІРёР»Р° РїРѕСЏРІРёР»РёСЃСЊ Р±С‹ С‚РѕР»СЊРєРѕ РїРѕСЃР»Рµ РїРµСЂРµР·Р°РїСѓСЃРєР° Рї.1 Рё СЃР°Р№С‚ В«РЅРµ РѕС‚РєСЂС‹РІР°Р»СЃСЏВ».
  if grep -q "listen 127.0.0.1:4443" "$STACK_CONF" 2>/dev/null; then
    panel_decoy_apply adguard || warn "nginx-Р»РѕРєР°С†РёСЏ AdGuard РЅРµ РїСЂРёРјРµРЅРёР»Р°СЃСЊ вЂ” РїРµСЂРµР·Р°РїСѓСЃС‚Рё Рї.1 В«РџРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР°В»"
  fi
}
# AdGuard + DoH Р·Р° nginx (v0.107.79+): plain DoH (allow_unencrypted_doh) Р±РѕР»СЊС€Рµ
# РЅРµ РїРѕРґРґРµСЂР¶РёРІР°РµС‚СЃСЏ вЂ” РІРєР»СЋС‡Р°РµРј РІ AdGuard Р РћР”РќРћР™ HTTPS РЅР° 127.0.0.1:$ADG_WEB_PORT
# (web UI + /dns-query РЅР° РѕРґРЅРѕРј РїРѕСЂС‚Сѓ) СЃ wildcard/РїР°РЅРµР»СЊРЅС‹Рј СЃРµСЂС‚РёС„РёРєР°С‚РѕРј.
# nginx Р·Р°С‚РµРј РїСЂРѕРєСЃРёСЂСѓРµС‚ location / в†’ https://127.0.0.1:$ADG_WEB_PORT.
#   dns.bind_hosts в†’ 127.0.0.1 (plain DNS С‚РѕР»СЊРєРѕ РґР»СЏ СЃР°РјРѕРіРѕ СЃРµСЂРІРµСЂР°)
# РђСЂРіСѓРјРµРЅС‚С‹: configure_adguard_doh [admin_pass] [cert] [key]
#   Р±РµР· СЃРµСЂС‚Р° вЂ” СЃР°РјРѕРїРѕРґРїРёСЃР°РЅРЅС‹Р№ (nginx РІСЃС‘ СЂР°РІРЅРѕ С‚РµСЂРјРёРЅРёСЂСѓРµС‚ TLS СЃ verify off)
configure_adguard_doh() {
  local adg_pass="${1:-}" cert="${2:-}" key="${3:-}"
  local cfg="$ADG_CONFIG"
  [[ -z "$cfg" || ! -f "$cfg" ]] && return 1

  # С„Р°РєС‚РёС‡РµСЃРєРёР№ РїРѕСЂС‚ РёР· http.address РєРѕРЅС„РёРіР° (РґРµС„РѕР»С‚ ADG_WEB_PORT РјРѕР¶РµС‚ РІСЂР°С‚СЊ)
  local cfg_port=""
  cfg_port=$(awk '/^http:/{f=1;next} /^[^ ]/{f=0} f && /^  address:/{n=split($2,a,":"); print a[n]; exit}' "$cfg" 2>/dev/null | tr -d '"')
  [[ -n "$cfg_port" && "$cfg_port" != "null" ]] && ADG_WEB_PORT="$cfg_port"

  # СЃРµСЂС‚РёС„РёРєР°С‚: РїР°РЅРµР»СЊРЅС‹Р№/wildcard РёР»Рё СЃР°РјРѕРїРѕРґРїРёСЃР°РЅРЅС‹Р№ fallback
  if [[ -z "$cert" || ! -f "$cert" || -z "$key" || ! -f "$key" ]]; then
    local tdir="/etc/nginx/adguard-tls"
    mkdir -p "$tdir" 2>/dev/null || true
    if [[ ! -f "$tdir/adguard.crt" || ! -f "$tdir/adguard.key" ]]; then
      openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 \
        -keyout "$tdir/adguard.key" -out "$tdir/adguard.crt" -days 3650 -nodes \
        -subj "/CN=adguard.local" 2>/dev/null || true
    fi
    [[ -f "$tdir/adguard.crt" ]] && { cert="$tdir/adguard.crt"; key="$tdir/adguard.key"; }
  fi

  systemctl stop "$ADG_SERVICE" 2>/dev/null || true
  sleep 1
  cp "$cfg" "$cfg.bak.$(date +%s)" 2>/dev/null || true

  # dns.bind_hosts в†’ 127.0.0.1
  awk '
    /^dns:/  { in_dns=1; print; next }
    /^[^ ]/ && !/^dns:/ { in_dns=0 }
    in_dns && /^  bind_hosts:/ {
      print "  bind_hosts:"
      print "    - 127.0.0.1"
      skip_list=1
      next
    }
    skip_list && /^    - / { next }
    skip_list && !/^    - / { skip_list=0 }
    { print }
  ' "$cfg" > "$cfg.new" && mv "$cfg.new" "$cfg"

  # plain-http (Р°РґРјРёРЅРєР°) СѓРІРѕРґРёРј РЅР° СЃРѕСЃРµРґРЅРёР№ РїРѕСЂС‚: РґСѓР±Р»РёРєР°С‚ РїРѕСЂС‚Р° СЃ https Р·Р°РїСЂРµС‰С‘РЅ
  local plain_port=""
  local cand=$((ADG_WEB_PORT + 1)) j
  for j in 1 2 3 4 5; do
    if ! port_in_use "$cand"; then plain_port=$cand; break; fi
    cand=$((cand + 1))
  done
  [[ -z "$plain_port" ]] && plain_port=$((ADG_WEB_PORT + 1))
  awk -v pp="$plain_port" '
    /^http:/ { f=1; print; next }
    /^[^ ]/ && !/^http:/ { f=0 }
    f && /^  address:/ { print "  address: 127.0.0.1:" pp; next }
    { print }
  ' "$cfg" > "$cfg.new" && mv "$cfg.new" "$cfg"

  # tls: в†’ enabled + РїРѕСЂС‚ https = web РїРѕСЂС‚ (UI Рё DoH РЅР° РѕРґРЅРѕРј РїРѕСЂС‚Сѓ, TLS РЅР° AdGuard)
  # Р’РђР–РќРћ: РІ РЅРѕРІС‹С… РІРµСЂСЃРёСЏС… (schema 34+) РїСѓС‚Рё СЃРµСЂС‚Р° вЂ” certificate_path/private_key_path
  # (certificate_chain/private_key вЂ” СЌС‚Рѕ РЎРђРњРћ PEM-СЃРѕРґРµСЂР¶РёРјРѕРµ).
  if grep -q "^tls:" "$cfg"; then
    awk -v ph="$ADG_WEB_PORT" -v sn="${ADG_SNI:-$PANEL_DOMAIN}" -v crt="$cert" -v key="$key" '
      /^tls:/ { in_tls=1; print; next }
      /^[^ ]/ && !/^tls:/ { in_tls=0 }
      in_tls && /^  enabled:/               { print "  enabled: true"; next }
      in_tls && /^  server_name:/           { print "  server_name: \"" sn "\""; next }
      in_tls && /^  force_https:/           { print "  force_https: false"; next }
      in_tls && /^  port_https:/            { print "  port_https: " ph; next }
      in_tls && /^  port_dns_over_tls:/     { print "  port_dns_over_tls: 0"; next }
      in_tls && /^  port_dns_over_quic:/    { print "  port_dns_over_quic: 0"; next }
      in_tls && /^  port_privileged_https:/ { print "  port_privileged_https: 0"; next }
      in_tls && /^  port_dnscrypt:/         { print "  port_dnscrypt: 0"; next }
      in_tls && /^  certificate_chain:/     { print "  certificate_chain: \"\""; next }
      in_tls && /^  private_key:/           { print "  private_key: \"\""; next }
      in_tls && /^  certificate_path:/      { print "  certificate_path: " crt; next }
      in_tls && /^  private_key_path:/      { print "  private_key_path: " key; next }
      { print }
    ' "$cfg" > "$cfg.new" && mv "$cfg.new" "$cfg"
    # РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РёРµ РєР»СЋС‡Рё вЂ” РІСЃС‚Р°РІР»СЏРµРј РїРѕСЃР»Рµ ^tls:
    local kv k
    for kv in "  enabled: true" "  port_https: $ADG_WEB_PORT" "  port_dns_over_tls: 0" "  port_dns_over_quic: 0" "  port_dnscrypt: 0" "  certificate_path: $cert" "  private_key_path: $key"; do
      k="${kv%%:*}"
      grep -q "^${k}:" "$cfg" || sed -i "s/^tls:/tls:\n${kv}/" "$cfg"
    done
  else
    {
      echo ""
      echo "tls:"
      echo "  enabled: true"
      echo "  server_name: \"${ADG_SNI:-$PANEL_DOMAIN}\""
      echo "  force_https: false"
      echo "  port_https: $ADG_WEB_PORT"
      echo "  port_dns_over_tls: 0"
      echo "  port_dns_over_quic: 0"
      echo "  port_dnscrypt: 0"
      echo "  certificate_path: $cert"
      echo "  private_key_path: $key"
    } >> "$cfg"
  fi

  systemctl start "$ADG_SERVICE" 2>/dev/null || true
  sleep 3
  if ! ss -tlnH "sport = :$ADG_WEB_PORT" 2>/dev/null | grep -q .; then
    warn "AdGuard РЅРµ РїРѕРґРЅСЏР»СЃСЏ РЅР° 127.0.0.1:$ADG_WEB_PORT"
    return 1
  fi
  # DoH РґРѕР»Р¶РµРЅ РѕС‚РІРµС‡Р°С‚СЊ РїРѕ https (403/200/4xx РѕС‚ С…РµРЅРґР»РµСЂР°, РќР• 404)
  local code=""
  code=$(curl -sk -o /dev/null -w '%{http_code}' --max-time 8 \
    -H "accept: application/dns-message" \
    "https://127.0.0.1:$ADG_WEB_PORT/dns-query?dns=q80BAAABAAAAAAAAA3d3dwZnb29nbGUDY29tAAABAAE" 2>/dev/null) || true
  if [[ "$code" == "404" ]]; then
    warn "DoH /dns-query РЅРµ РѕС‚РІРµС‡Р°РµС‚ (HTTP $code)"
    return 1
  fi
  log "AdGuard: https://127.0.0.1:$ADG_WEB_PORT (UI+DoH, TLS РЅР° AdGuard) В· plain http 127.0.0.1:$plain_port В· DNS=127.0.0.1:53 В· DoH /dns-query: HTTP $code"
  return 0
}

# AdGuard РЅР° РћРўР”Р•Р›Р¬РќРћРњ SNI-РґРѕРјРµРЅРµ (adguard.<Р±Р°Р·Р° РїР°РЅРµР»Рё>): СЃРµСЂС‚ (С‚РѕС‡РЅС‹Р№ РёР»Рё
# wildcard), СЂРѕРґРЅРѕР№ TLS AdGuard РЅР° 127.0.0.1:3002, РјР°СЂС€СЂСѓС‚ SNI-СЂРѕСѓС‚РµСЂР°
# <РґРѕРјРµРЅ> в†’ agh_backend. UI + DoH Р¶РёРІСѓС‚ РЅР° СЃРІРѕС‘Рј РґРѕРјРµРЅРµ, РїР°РЅРµР»СЊ вЂ” РЅР° СЃРІРѕС‘Рј РєРѕСЂРЅРµ.
adg_setup_sni_domain() {
  local dom="$1"
  [[ -z "$dom" ]] && return 1
  if [[ "$ADG_PRESENT" != true || -z "$ADG_SERVICE" ]]; then
    warn "AdGuard РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” РѕС‚РґРµР»СЊРЅС‹Р№ РґРѕРјРµРЅ $dom РїСЂРѕРїСѓС‰РµРЅ"
    return 1
  fi
  log "AdGuard в†’ РѕС‚РґРµР»СЊРЅС‹Р№ РґРѕРјРµРЅ $dom: СЃРµСЂС‚ + TLS + SNI-РјР°СЂС€СЂСѓС‚вЂ¦"
  cert_issue "$dom" || warn "СЃРµСЂС‚ $dom РќР• РІС‹РїСѓС‰РµРЅ вЂ” РїСЂРѕРІРµСЂСЊ DNS; РїРѕСЃР»Рµ РІС‹РїСѓСЃРєР° РїРµСЂРµР·Р°РїСѓСЃС‚Рё Рї.1 (РёР»Рё С‚Р°Р№РјРµСЂ СЃР°РјРѕР»РµС‡РµРЅРёСЏ РґРѕРґРµР»Р°РµС‚)"
  local cline cert="" key=""
  cline=$(cert_lineage_for "$dom")
  if [[ -n "$cline" ]]; then
    cert="${cline%% *}"; key="${cline##* }"
  else
    cert="/etc/letsencrypt/live/$dom/fullchain.pem"; key="/etc/letsencrypt/live/$dom/privkey.pem"
  fi
  ADG_WEB_PORT=3002
  port_in_use "$ADG_WEB_PORT" && ADG_WEB_PORT=13002
  ADG_SNI="$dom"
  configure_adguard_doh "" "$cert" "$key" || warn "TLS AdGuard РґР»СЏ $dom РЅРµ РїСЂРёРјРµРЅРёР»СЃСЏ (СЃРјРѕС‚СЂРё yaml)"
  sni_upstream_add agh_backend "$ADG_WEB_PORT"
  sni_map_add "$dom" "agh_backend"
  SNI_USED["$dom"]="agh_backend"
  nginx -t >/dev/null 2>&1 && nginx_reload || true
  log "AdGuard: https://$dom/ (UI + DoH /dns-query) вЂ” С‡РµСЂРµР· SNI-СЂРѕСѓС‚РµСЂ РЅР° 443"
  return 0
}

# РџСЂРёРјРµРЅРёС‚СЊ decoy/РїСЂРѕРєСЃРё РљРћР РќРЇ РґРѕРјРµРЅР° РїР°РЅРµР»Рё Рє РЈР–Р• СЃСѓС‰РµСЃС‚РІСѓСЋС‰РµРјСѓ 4443-Р±Р»РѕРєСѓ
# (Р±РµР· РїРµСЂРµРіРµРЅРµСЂР°С†РёРё stack.conf): adguard | stub | tpl:РРњРЇ.
# РќСѓР¶РЅР°, С‡С‚РѕР±С‹ AdGuard, СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Р№ РџРћРЎР›Р• РїРµСЂРІРёС‡РЅРѕР№ РЅР°СЃС‚СЂРѕР№РєРё, СЃСЂР°Р·Сѓ
# РѕС‚РєСЂС‹РІР°Р»СЃСЏ РїРѕ РґРѕРјРµРЅСѓ РїР°РЅРµР»Рё вЂ” Р° РЅРµ В«РїРѕСЃР»Рµ РїРµСЂРµР·Р°РїСѓСЃРєР° Рї.1В».
panel_decoy_apply() {
  local mode="$1" custom_path="${2:-}"
  [[ -f "$STACK_CONF" ]] || return 1
  grep -q "listen 127.0.0.1:4443" "$STACK_CONF" 2>/dev/null || return 1
  local adg_port="" panel_path="" panel_conf_bak=""
  panel_conf_bak=$(mktemp /tmp/stack-conf.XXXXXX 2>/dev/null || true)
  [[ -n "$panel_conf_bak" ]] && cp -f "$STACK_CONF" "$panel_conf_bak" 2>/dev/null || true
  adg_port=$(adg_config_port 2>/dev/null || true)
  [[ -z "$adg_port" ]] && adg_port="${ADG_WEB_PORT:-3000}"
  panel_path=$(xui_get webBasePath 2>/dev/null || true)
  panel_path="/${panel_path#/}"; panel_path="${panel_path%/}/"
  PD_MODE="$mode" PD_PORT="$adg_port" PD_DIR="$PANEL_DECOY_DIR" PD_CUSTOM="$custom_path" PD_PATH="$panel_path" python3 - "$STACK_CONF" <<'PYPDA'
import sys, os
mode, adg_port, pdir = os.environ["PD_MODE"], os.environ["PD_PORT"], os.environ["PD_DIR"]
custom = os.environ.get("PD_CUSTOM", "")
panel_path = os.environ.get("PD_PATH", "/")
path = sys.argv[1]
src = open(path).read()
if mode == "custom" and custom:
    block = (
        "    location / {\n"
        f"        root {custom};\n"
        "        try_files $uri $uri/ /index.html;\n"
        "    }"
    )
elif mode == "adguard":
    block = (
        "    location / {\n"
        f"        proxy_pass https://127.0.0.1:{adg_port};\n"
        "        proxy_ssl_verify off;\n"
        "        proxy_http_version 1.1;\n"
        "        proxy_set_header Host $host;\n"
        "        proxy_set_header X-Real-IP $remote_addr;\n"
        "        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n"
        "        proxy_set_header X-Forwarded-Proto https;\n"
        "        proxy_set_header Upgrade $http_upgrade;\n"
        '        proxy_set_header Connection "upgrade";\n'
        "        proxy_read_timeout 86400;\n"
        "    }"
    )
else:
    block = (
        "    location / {\n"
        f"        root {pdir};\n"
        "        try_files /index.html =404;\n"
        "    }"
    )
lines = src.split("\n")
out, i, done, in4443 = [], 0, False, False
while i < len(lines):
    l = lines[i]
    if "listen 127.0.0.1:4443" in l:
        in4443 = True
    # РњРµРЅСЏРµРј С‚РѕР»СЊРєРѕ РѕС‚РґРµР»СЊРЅС‹Р№ РєРѕСЂРЅРµРІРѕР№ location / вЂ” РЅРёРєРѕРіРґР° РЅРµ С‚СЂРѕРіР°РµРј
    # webBasePath РїР°РЅРµР»Рё Рё subPath РїРѕРґРїРёСЃРєРё.
    if in4443 and l.strip() == "location / {":
        j = i + 1
        depth = 1
        while j < len(lines):
            s = lines[j].strip()
            if s.endswith("{"): depth += 1
            if s == "}":
                depth -= 1
                if depth == 0: break
            j += 1
        if j >= len(lines):
            sys.exit(2)
        out.append(block)
        done = True
        i = j + 1
        continue
    out.append(l)
    i += 1
if not done:
    sys.exit(1)
open(path, "w").write("\n".join(out))
PYPDA
  local rc=$?
  if [[ $rc -eq 0 ]]; then
    if nginx -t >/dev/null 2>&1; then
      nginx_reload || true
      log "РљРѕСЂРµРЅСЊ РґРѕРјРµРЅР° РїР°РЅРµР»Рё в†’ $mode (nginx РїРµСЂРµР·Р°РіСЂСѓР¶РµРЅ)"
    else
      err "nginx -t РЅРµ РїСЂРѕС€С‘Р» РїРѕСЃР»Рµ СЃРјРµРЅС‹ РєРѕСЂРЅСЏ РїР°РЅРµР»Рё вЂ” РѕС‚РєР°С‚С‹РІР°СЋ stack.conf"
      if [[ -s "$panel_conf_bak" ]]; then
        cp -f "$panel_conf_bak" "$STACK_CONF" 2>/dev/null || true
        nginx -t 2>&1 | tail -4 | sed 's/^/    /'
      fi
      rc=1
    fi
  elif [[ -s "$panel_conf_bak" ]]; then
    # Python-СЂРµРґР°РєС‚РѕСЂ РЅРµ РґРѕР»Р¶РµРЅ РѕСЃС‚Р°РІР»СЏС‚СЊ С‡Р°СЃС‚РёС‡РЅРѕ РёР·РјРµРЅС‘РЅРЅС‹Р№ РєРѕРЅС„РёРі.
    cp -f "$panel_conf_bak" "$STACK_CONF" 2>/dev/null || true
  fi
  rm -f "$panel_conf_bak" 2>/dev/null || true
  return $rc
}

configure_adguard_local() {
  local cfg="$ADG_CONFIG"
  [[ -z "$cfg" || ! -f "$cfg" ]] && return 1
  systemctl stop "$ADG_SERVICE" 2>/dev/null || true
  sleep 1
  cp "$cfg" "$cfg.bak.$(date +%s)" 2>/dev/null || true
  awk -v web="  address: 127.0.0.1:$ADG_WEB_PORT" '
    /^http:/ { in_http=1; print; next }
    /^[^ ]/ && !/^http:/ { in_http=0 }
    in_http && /^  address:/ { print web; next }
    { print }
  ' "$cfg" > "$cfg.new" && mv "$cfg.new" "$cfg"
  systemctl start "$ADG_SERVICE" 2>/dev/null || true
  sleep 2
  ss -tlnH "sport = :$ADG_WEB_PORT" 2>/dev/null | grep -q . && { log "AdGuard СЃР»СѓС€Р°РµС‚ 127.0.0.1:$ADG_WEB_PORT"; return 0; }
  warn "AdGuard РЅРµ РїРѕРґРЅСЏР»СЃСЏ РЅР° $ADG_WEB_PORT"
  return 1
}

decoy_panel_choose() {
  local __result="$1"
  local no_adg="${2:-}"   # "1" = РІР°СЂРёР°РЅС‚ adguard РЅРµРґРѕСЃС‚СѓРїРµРЅ (РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ РѕС‚РєР°Р·Р°Р»СЃСЏ РѕС‚ РЅР°СЃС‚СЂРѕР№РєРё Р·Р° РїР°РЅРµР»СЊСЋ)
  echo
  echo -e "${B}Decoy РґР»СЏ РїР°РЅРµР»Рё (С‡С‚Рѕ РїРѕРєР°Р·С‹РІР°С‚СЊ РїРѕ РєРѕСЂРЅСЋ РґРѕРјРµРЅР° РїР°РЅРµР»Рё):${N}"
  echo "  1) stub     вЂ” СЃС‚Р°РЅРґР°СЂС‚РЅР°СЏ Р·Р°РіР»СѓС€РєР° nginx"
  if [[ "$no_adg" != "1" ]]; then
    echo "  2) adguard  вЂ” AdGuard Home web UI + DoH С‡РµСЂРµР· РґРѕРјРµРЅ РїР°РЅРµР»Рё"
    echo "  3) С€Р°Р±Р»РѕРЅ   вЂ” decoy-Р·Р°РіР»СѓС€РєР° РёР· РєР°С‚Р°Р»РѕРіР° (corporate, blog, docs, cloudflare, login-СЃС‚СЂР°РЅРёС†С‹...)"
    echo "  4) adguard+ вЂ” AdGuard РЅР° РћРўР”Р•Р›Р¬РќРћРњ SNI-РґРѕРјРµРЅРµ (adguard.<Р±Р°Р·Р° РїР°РЅРµР»Рё>)"
  else
    echo "  2) С€Р°Р±Р»РѕРЅ   вЂ” decoy-Р·Р°РіР»СѓС€РєР° РёР· РєР°С‚Р°Р»РѕРіР° (corporate, blog, docs, cloudflare, login-СЃС‚СЂР°РЅРёС†С‹...)"
  fi
  echo
  if [[ "$no_adg" != "1" && "$ADG_PRESENT" != true ]]; then
    warn "AdGuard Home РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” РІР°СЂРёР°РЅС‚С‹ 2 Рё 4 РїРѕС‚СЂРµР±СѓСЋС‚ СѓСЃС‚Р°РЅРѕРІРєРё."
  fi
  if [[ "$no_adg" == "1" ]]; then
    warn "РќР°СЃС‚СЂРѕР№РєР° AdGuard Р·Р° РїР°РЅРµР»СЊСЋ РѕС‚РєР»РѕРЅРµРЅР° вЂ” РґРѕСЃС‚СѓРїРµРЅ stub РёР»Рё С€Р°Р±Р»РѕРЅ."
  fi
  echo
  local choice=""
  if [[ "$no_adg" == "1" ]]; then
    ask choice "Р’С‹Р±РѕСЂ" "1" '^[12]$'
    [[ "$choice" == "2" ]] && choice=3
  else
    ask choice "Р’С‹Р±РѕСЂ" "1" '^[1234]$'
  fi
  if [[ "$choice" == "2" && "$ADG_PRESENT" != true ]]; then
    askyn do_install "AdGuard Home РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ. РЈСЃС‚Р°РЅРѕРІРёС‚СЊ СЃРµР№С‡Р°СЃ?" "y"
    # shellcheck disable=SC2154 # Р·Р°РґР°С‘С‚СЃСЏ askyn РІС‹С€Рµ
    if [[ "$do_install" == true ]]; then
      install_adguard_home || { warn "РќРµ СѓРґР°Р»РѕСЃСЊ вЂ” РїР°РґР°РµРј РЅР° stub"; choice=1; }
    else
      choice=1
    fi
  fi
  if [[ "$choice" == "4" ]]; then
    if [[ "$ADG_PRESENT" != true ]]; then
      askyn do_install4 "AdGuard Home РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ. РЈСЃС‚Р°РЅРѕРІРёС‚СЊ СЃРµР№С‡Р°СЃ?" "y"
      # shellcheck disable=SC2154 # Р·Р°РґР°С‘С‚СЃСЏ askyn РІС‹С€Рµ
      if [[ "$do_install4" == true ]]; then
        install_adguard_home || { warn "РќРµ СѓРґР°Р»РѕСЃСЊ вЂ” РїР°РґР°РµРј РЅР° stub"; choice=1; }
      else
        choice=1
      fi
    fi
    if [[ "$choice" == "4" ]]; then
      printf -v "$__result" '%s' "adguard-sni"
      return 0
    fi
  fi
  if [[ "$choice" == "3" ]]; then
    local tpl=""
    decoy_template_choose tpl "Decoy-С€Р°Р±Р»РѕРЅ РґР»СЏ РїР°РЅРµР»Рё" "corporate"
    printf -v "$__result" '%s' "tpl:$tpl"
    return 0
  fi
  [[ "$choice" == "2" ]] && printf -v "$__result" '%s' "adguard" || printf -v "$__result" '%s' "stub"
}

panel_decoy_stub_init() {
  mkdir -p "$PANEL_DECOY_DIR" 2>/dev/null || true
  cat > "$PANEL_DECOY_DIR/index.html" <<'HTML'
<!doctype html><html><head><meta charset="utf-8"><title>Welcome to nginx!</title>
<style>body{font-family:sans-serif;background:#f4f4f4;text-align:center;padding-top:80px;color:#333}
h1{color:#2b6cb0}p{color:#666}</style></head>
<body><h1>Welcome to nginx!</h1>
<p>If you see this page, the nginx web server is successfully installed and working.</p></body></html>
HTML
  chown -R www-data:www-data "$PANEL_DECOY_DIR" 2>/dev/null || true
}

# =====================================================================
# РЈРЎРўРђРќРћР’РљРђ РџРђРќР•Р›Р
# =====================================================================
# РЎР•Р Рў, Р’РџРРЎРђРќРќР«Р™ Р’ РќРђРЎРўР РћР™РљР x-ui (РІ С‚.С‡. РІС‹РїСѓС‰РµРЅРЅС‹Р№ С‡РµСЂРµР· РјРµРЅСЋ x-ui: x-ui setting
# -webCert/-webCertKey РёР»Рё acme-РјРѕРґСѓР»РµРј РїР°РЅРµР»Рё). РЎРєСЂРёРїС‚ РЎР§РРўР«Р’РђР•Рў РµРіРѕ Рё РїРѕР»СЊР·СѓРµС‚СЃСЏ РёРј,
# РЅРёС‡РµРіРѕ РЅРµ РїРµСЂРµРІС‹РїСѓСЃРєР°СЏ. РџРµС‡Р°С‚Р°РµС‚ "<cert> <key> [domain]"; РєРѕРґ 1 вЂ” Р¶РёРІРѕРіРѕ СЃРµСЂС‚Р° РЅРµС‚.
panel_cert_from_db() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 1
  local c k d end
  c=$(xui_get webCertFile)
  k=$(xui_get webKeyFile)
  d=$(xui_get webDomain)
  [[ -z "$c" || ! -f "$c" ]] && return 1
  [[ -z "$k" || ! -f "$k" ]] && k=$(xui_get subKeyFile)
  [[ -z "$k" || ! -f "$k" ]] && return 1
  openssl x509 -noout -in "$c" >/dev/null 2>&1 || return 1
  end=$(openssl x509 -noout -enddate -in "$c" 2>/dev/null | cut -d= -f2)
  [[ -z "$end" ]] && return 1
  [[ $(date -d "$end" +%s 2>/dev/null || echo 0) -lt $(date +%s) ]] && return 1
  # РґРѕРјРµРЅ: webDomain в†’ subDomain в†’ SAN/CN СЃР°РјРѕРіРѕ СЃРµСЂС‚Р° (x-ui РјРµРЅСЋ РјРѕРіР»Рѕ РЅРµ РІРїРёСЃР°С‚СЊ РґРѕРјРµРЅ)
  [[ -z "$d" ]] && d=$(xui_get subDomain)
  if [[ -z "$d" ]]; then
    d=$(openssl x509 -noout -ext subjectAltName -in "$c" 2>/dev/null \
        | grep -oE 'DNS:[^,]+' | head -1 | sed 's/DNS://; s/^\*\.//')
    [[ -z "$d" ]] && d=$(openssl x509 -noout -subject -in "$c" 2>/dev/null \
        | grep -oE 'CN ?= ?[^/,]+' | head -1 | sed 's/.*CN *= *//')
  fi
  echo "$c $k ${d}"
  return 0
}

# РђРІС‚РѕР±СЌРєР°Рї СЃРѕСЃС‚РѕСЏРЅРёСЏ СЃС‚РµРєР° РїСЂРё РєР°Р¶РґРѕРј СЃС‚Р°СЂС‚Рµ: x-ui.db + nginx-РєРѕРЅС„РёРіРё.
# Р”РµСЂР¶РёРј РїРѕСЃР»РµРґРЅРёРµ 5 РєРѕРїРёР№ РІ /root/stack-backups/auto-*
auto_backup_stack() {
  local bd="/root/stack-backups/auto-$(date +%Y%m%d-%H%M%S)"
  local saved=false
  mkdir -p "$bd" 2>/dev/null || return 0
  [[ -f "$XUI_DB" ]] && { cp -a "$XUI_DB" "$bd/" 2>/dev/null && saved=true; }
  for f in /etc/nginx/sites-available/stack.conf /etc/nginx/sites-enabled/stack.conf \
           /etc/nginx/streams-enabled/sni-router.conf /etc/nginx/streams-available/sni-router.conf; do
    [[ -f "$f" ]] && cp -a "$f" "$bd/" 2>/dev/null && saved=true
  done
  # РЎРѕС…СЂР°РЅСЏРµРј РёС‚РѕРіРѕРІС‹Р№ Xray-РєРѕРЅС„РёРі РєР°Рє РґРёР°РіРЅРѕСЃС‚РёС‡РµСЃРєРёР№ СЃРЅРёРјРѕРє. Р­С‚Рѕ РЅРµ РёСЃС‚РѕС‡РЅРёРє
  # РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ Рё РЅРµ Р·Р°РјРµРЅСЏРµС‚ templateSettings: СЃРЅРёРјРѕРє РЅСѓР¶РµРЅ РґР»СЏ СЃСЂР°РІРЅРµРЅРёСЏ
  # С‚РµРіРѕРІ api/blackhole Рё routing РїРѕСЃР»Рµ РѕР±РЅРѕРІР»РµРЅРёР№ РїР°РЅРµР»Рё.
  local xf
  for xf in /usr/local/x-ui/bin/config.json /usr/local/x-ui/config.json /etc/x-ui/config.json; do
    if [[ -f "$xf" ]]; then
      cp -a "$xf" "$bd/xray-config.json" 2>/dev/null || true
      sha256sum "$xf" 2>/dev/null | awk '{print $1}' > "$bd/xray-config.sha256" 2>/dev/null || true
      printf '%s\n' "$xf" > "$bd/xray-config.path"
      XRAY_SNAPSHOT_PATH="$xf" XRAY_SNAPSHOT_MANIFEST="$bd/xray-manifest.json" python3 - <<'PYXMAN' 2>/dev/null || true
import json, os, hashlib
from pathlib import Path
p=Path(os.environ['XRAY_SNAPSHOT_PATH']); raw=p.read_bytes(); c=json.loads(raw.decode('utf-8'))
obs=[x.get('tag') for x in c.get('outbounds',[]) if isinstance(x,dict) and isinstance(x.get('tag'),str)]
r=c.get('routing') if isinstance(c.get('routing'),dict) else {}
Path(os.environ['XRAY_SNAPSHOT_MANIFEST']).write_text(json.dumps({
  'schema':1,'source':str(p),'sha256':hashlib.sha256(raw).hexdigest(),
  'outboundTags':obs,'api':'api' in obs,'blackhole':'blackhole' in obs,
  'routingRules':len(r.get('rules',[])) if isinstance(r.get('rules'),list) else 0,
  'hasDns':isinstance(c.get('dns'),dict)
},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
PYXMAN
      # РљР°РЅРѕРЅРёС‡РµСЃРєРёР№ manifest РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РґР»СЏ СЃСЂР°РІРЅРµРЅРёСЏ СЃ С‚РµРєСѓС‰РёРј config.json.
      cp -f "$bd/xray-manifest.json" "$BACKUP_DIR/xray-manifest.json" 2>/dev/null || true
      saved=true
      break
    fi
  done
  [[ "$saved" == true ]] || { rmdir "$bd" 2>/dev/null; return 0; }
  echo "backup-ok" > "$bd/.ok"
  # СЂРµС‚РµРЅС€РµРЅ: РїРѕСЃР»РµРґРЅРёРµ 5
  ls -1dt /root/stack-backups/auto-* 2>/dev/null | tail -n +6 | xargs -r rm -rf 2>/dev/null || true
  return 0
}

# РҐРµР»РїРµСЂ РІС‹РїСѓСЃРєР° СЃРµСЂС‚Р° Р§Р•Р Р•Р— РњР•РќР® x-ui: acme.sh РїР°РЅРµР»Рё СЂР°Р±РѕС‚Р°РµС‚ standalone РЅР° :80,
# Р° :80 Сѓ РЅР°СЃ Р·Р°РЅРёРјР°РµС‚ nginx. Р’СЂРµРјРµРЅРЅРѕ РѕСЃРІРѕР±РѕР¶РґР°РµРј РўРћР›Р¬РљРћ 80 (443/SNI-СЂРѕСѓС‚РµСЂ Рё
# С‚СѓРЅРЅРµР»Рё РїСЂРѕРґРѕР»Р¶Р°СЋС‚ СЂР°Р±РѕС‚Р°С‚СЊ), РѕС‚РєСЂС‹РІР°РµРј 80 РІ UFW, Р¶РґС‘Рј, РІРѕР·РІСЂР°С‰Р°РµРј РІСЃС‘ РѕР±СЂР°С‚РЅРѕ
# Рё РїРѕРґС…РІР°С‚С‹РІР°РµРј РЅРѕРІС‹Р№ СЃРµСЂС‚ РїР°РЅРµР»Рё РІ nginx.
xui_cert_menu_helper() {
  line; echo -e "${B}   Р’Р«РџРЈРЎРљ РЎР•Р РўРђ Р§Р•Р Р•Р— РњР•РќР® x-ui${N}"; line
  echo "  РњРµРЅСЋ x-ui РІС‹РїСѓСЃРєР°РµС‚ СЃРµСЂС‚ standalone-СЂРµР¶РёРјРѕРј РЅР° :80, Р° С‚Р°Рј РІРёСЃРёС‚ nginx."
  echo "  Р­С‚РѕС‚ РїСѓРЅРєС‚ РІСЂРµРјРµРЅРЅРѕ РѕСЃРІРѕР±РѕР¶РґР°РµС‚ :80 (443 РЅРµ С‚СЂРѕРіР°РµС‚СЃСЏ), РѕС‚РєСЂС‹РІР°РµС‚ 80 РІ UFW,"
  echo "  Р·Р°С‚РµРј Р¶РґС‘С‚, РїРѕРєР° С‚С‹ РІС‹РїСѓСЃС‚РёС€СЊ СЃРµСЂС‚ РІ РїР°РЅРµР»Рё, Рё РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµС‚ РІСЃС‘ РѕР±СЂР°С‚РЅРѕ."
  echo
  local bak="/root/stack-backups/pre-xuicert-$(date +%Y%m%d-%H%M%S)"
  mkdir -p "$bak" 2>/dev/null || true
  cp -a /etc/nginx/sites-available/stack.conf /etc/nginx/sites-enabled/stack.conf \
        /etc/nginx/streams-enabled/sni-router.conf "$bak/" 2>/dev/null || true
  [[ -f "$XUI_DB" ]] && cp -a "$XUI_DB" "$bak/" 2>/dev/null || true

  # 1) Р·Р°РєРѕРјРјРµРЅС‚РёСЂРѕРІР°С‚СЊ listen :80 РІРѕ РІСЃРµС… РЅР°С€РёС… РєРѕРЅС„РёРіР°С… (РјР°СЂРєРµСЂ ACME80)
  local touched=()
  local f
  for f in /etc/nginx/sites-enabled/*.conf /etc/nginx/streams-enabled/*.conf /etc/nginx/sites-enabled/default; do
    [[ -f "$f" ]] || continue
    if grep -qE '^[[:space:]]*listen[[:space:]]+([^[:space:]]+:)?80[[:space:]]*;' "$f"; then
      sed -i -E 's/^([[:space:]]*listen[[:space:]]+([^[:space:]]+:)?80[[:space:]]*;)/#ACME80 \1/' "$f"
      touched+=("$f")
    fi
  done
  if [[ ${#touched[@]} -gt 0 ]]; then
    if nginx -t >/dev/null 2>&1; then
      nginx_reload || true
      log ":80 РѕСЃРІРѕР±РѕР¶РґС‘РЅ: ${touched[*]}"
    else
      local rf2
      for rf2 in "${touched[@]}"; do
        cp -a "$bak/$(basename "$rf2")" "$rf2" 2>/dev/null || sed -i 's/^#ACME80 //' "$rf2"
      done
      nginx -t >/dev/null 2>&1 && nginx_reload || true
      err "nginx -t РЅРµ РїСЂРѕС€С‘Р» РїРѕСЃР»Рµ РїСЂР°РІРєРё вЂ” РѕС‚РєР°С‚ РІС‹РїРѕР»РЅРµРЅ"
      return 1
    fi
  else
    log ":80 РІ nginx-РєРѕРЅС„РёРіР°С… РЅРµ РЅР°Р№РґРµРЅ вЂ” РѕСЃРІРѕР±РѕР¶РґР°С‚СЊ РЅРµС‡РµРіРѕ"
  fi

  # 2) UFW: РѕС‚РєСЂС‹С‚СЊ 80 (ACME СЃС‚СѓС‡РёС‚СЃСЏ РёР·РІРЅРµ)
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
    ufw allow 80/tcp comment "acme-temp" >/dev/null 2>&1 || true
    log "UFW: 80/tcp РѕС‚РєСЂС‹С‚"
  fi

  # 3) РљРўРћ РІС‹РїСѓСЃРєР°РµС‚: СЃРєСЂРёРїС‚ СЃР°Рј (acme.sh) РёР»Рё РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ РІ РїР°РЅРµР»Рё x-ui
  local cert_mode="" cert_dom="" cert_ok=false
  ask cert_mode "РљС‚Рѕ РІС‹РїСѓСЃРєР°РµС‚ СЃРµСЂС‚?  1) СЃРєСЂРёРїС‚ СЃР°Рј (acme.sh, Р°РІС‚Рѕ)  2) СЏ СЃР°Рј РІ РїР°РЅРµР»Рё x-ui" "1" '^[12]$'
  if [[ "$cert_mode" == "1" ]]; then
    local db_dom=""
    db_dom=$(xui_get webDomain 2>/dev/null || true)
    [[ -z "$db_dom" ]] && db_dom=$(xui_get subDomain 2>/dev/null || true)
    ask cert_dom "Р”РѕРјРµРЅ РґР»СЏ СЃРµСЂС‚РёС„РёРєР°С‚Р°" "${db_dom:-panel.example.com}" '^[a-zA-Z0-9.-]+$'
    [[ -z "$cert_dom" ]] && { err "Р”РѕРјРµРЅ РЅРµ СѓРєР°Р·Р°РЅ"; return 1; }
    # acme.sh СѓСЃС‚Р°РЅРѕРІР»РµРЅ РІРјРµСЃС‚Рµ СЃ x-ui; РµСЃР»Рё РЅРµС‚ вЂ” СЃС‚Р°РІРёРј
    if [[ ! -x ~/.acme.sh/acme.sh ]]; then
      log "acme.sh РЅРµ РЅР°Р№РґРµРЅ вЂ” СѓСЃС‚Р°РЅР°РІР»РёРІР°СЋвЂ¦"
      curl -s https://get.acme.sh | sh >/dev/null 2>&1 || true
      [[ -x ~/.acme.sh/acme.sh ]] || { err "acme.sh РЅРµ СѓСЃС‚Р°РЅРѕРІРёР»СЃСЏ"; return 1; }
    fi
    log "Р’С‹РїСѓСЃРє С‡РµСЂРµР· acme.sh (standalone, :80): $cert_dom"
    ~/.acme.sh/acme.sh --set-default-ca --server letsencrypt --force >/dev/null 2>&1 || true
    if ~/.acme.sh/acme.sh --issue -d "$cert_dom" --standalone --httpport 80 --force; then
      local cdir="/etc/letsencrypt/live/$cert_dom"
      mkdir -p "$cdir"
      ~/.acme.sh/acme.sh --installcert --force -d "$cert_dom" \
        --key-file "$cdir/privkey.pem" \
        --fullchain-file "$cdir/fullchain.pem" \
        --reloadcmd "true" >/dev/null 2>&1 || true
      if [[ -f "$cdir/fullchain.pem" && -f "$cdir/privkey.pem" ]]; then
        # РІРїРёСЃР°С‚СЊ СЃРµСЂС‚ РІ РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё (x-ui РїСЂРѕС‡РёС‚Р°РµС‚ РїСЂРё СЂРµСЃС‚Р°СЂС‚Рµ)
        xui_set_setting webDomain   "$cert_dom"
        xui_set_setting webCertFile "$cdir/fullchain.pem"
        xui_set_setting webKeyFile  "$cdir/privkey.pem"
        xui_set_setting subCertFile "$cdir/fullchain.pem"
        xui_set_setting subKeyFile  "$cdir/privkey.pem"
        xui_set_setting subDomain   "$cert_dom"
        xui_set_setting subURI      "$(suburi_build "$cert_dom")"
        systemctl restart x-ui 2>/dev/null || true
        cert_ok=true
        log "РЎРµСЂС‚ РІС‹РїСѓС‰РµРЅ Рё РІРїРёСЃР°РЅ РІ РїР°РЅРµР»СЊ: $cdir"
      else
        err "installcert РЅРµ СЃРѕР·РґР°Р» С„Р°Р№Р»С‹ РІ $cdir"
      fi
    else
      err "acme.sh РЅРµ СЃРјРѕРі РІС‹РїСѓСЃС‚РёС‚СЊ СЃРµСЂС‚ (РґРѕРјРµРЅ СЂРµР·РѕР»РІРёС‚СЃСЏ РЅР° СЌС‚РѕС‚ СЃРµСЂРІРµСЂ? 80 РѕС‚РєСЂС‹С‚ РІС‹С€Рµ)"
    fi
  else
    warn "РЎР•Р™Р§РђРЎ: Р·Р°Р№РґРё РІ РїР°РЅРµР»СЊ (РёР»Рё CLI x-ui) в†’ SSL-СЃРµСЂС‚РёС„РёРєР°С‚ в†’ РїРѕР»СѓС‡РёС‚СЊ СЃРµСЂС‚ (РїРѕСЂС‚ 80)."
    warn "РџРѕ Р·Р°РІРµСЂС€РµРЅРёРё (СѓСЃРїРµС… РёР»Рё РѕС€РёР±РєР° вЂ” РЅРµРІР°Р¶РЅРѕ) РІРµСЂРЅРёСЃСЊ СЃСЋРґР° Рё РЅР°Р¶РјРё Enter."
    read -rp "  Enter РґР»СЏ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ :80 вЂ¦ " _r || _r=""
  fi

  # 3) РІРµСЂРЅСѓС‚СЊ listen :80
  local rf
  for rf in /etc/nginx/sites-enabled/*.conf /etc/nginx/streams-enabled/*.conf /etc/nginx/sites-enabled/default; do
    [[ -f "$rf" ]] || continue
    grep -q '^#ACME80 ' "$rf" && sed -i 's/^#ACME80 //' "$rf"
  done
  nginx -t >/dev/null 2>&1 && nginx_reload || warn "nginx -t: РїСЂРѕРІРµСЂСЊ РєРѕРЅС„РёРі РІСЂСѓС‡РЅСѓСЋ"
  # 4) UFW Р·Р°РєСЂС‹С‚СЊ РѕР±СЂР°С‚РЅРѕ
  command -v ufw >/dev/null 2>&1 && ufw delete allow 80/tcp >/dev/null 2>&1 || true
  log "UFW: 80/tcp Р·Р°РєСЂС‹С‚ РѕР±СЂР°С‚РЅРѕ"
  nginx_reload >/dev/null 2>&1 || true

  # 5) РїРѕРґС…РІР°С‚РёС‚СЊ РЅРѕРІС‹Р№ СЃРµСЂС‚ РїР°РЅРµР»Рё РІ nginx (РµСЃР»Рё РїР°РЅРµР»СЊ РµРіРѕ РІРїРёСЃР°Р»Р°)
  local pline="" pcert pkey
  pline=$(panel_cert_from_db) || true
  if [[ -n "$pline" && -f /etc/nginx/sites-available/stack.conf ]]; then
    pcert="${pline%% *}"; pkey=$(echo "$pline" | awk '{print $2}')
    local old_cert
    old_cert=$(awk '/# >>> panel/,/# <<< panel/ {if (/ssl_certificate /) print $2}' /etc/nginx/sites-available/stack.conf | head -1)
    if [[ -n "$old_cert" && "$old_cert" != "$pcert" ]]; then
      sed -i "s|$old_cert|$pcert|g; $(echo "$old_cert" | sed 's|fullchain|privkey|')|$pkey|g" /etc/nginx/sites-available/stack.conf
      nginx_reload >/dev/null 2>&1 || true
      log "РќРѕРІС‹Р№ СЃРµСЂС‚ РїР°РЅРµР»Рё РІРїРёСЃР°РЅ РІ nginx: $pcert"
    else
      log "РЎРµСЂС‚ РїР°РЅРµР»Рё СѓР¶Рµ Р°РєС‚СѓР°Р»РµРЅ РІ nginx"
    fi
    log "РџР°РЅРµР»СЊ: ${pline##* } в†’ $pcert (РґРµР№СЃС‚РІСѓРµС‚ РґРѕ: $(openssl x509 -noout -enddate -in "$pcert" 2>/dev/null | cut -d= -f2))"
  else
    warn "РџР°РЅРµР»СЊ РЅРµ РІРїРёСЃР°Р»Р° СЃРµСЂС‚ РІ РЅР°СЃС‚СЂРѕР№РєРё вЂ” РїСЂРё СЃР»РµРґСѓСЋС‰РµРј Рї.1 РѕРЅ Р±СѓРґРµС‚ РїРѕРґС…РІР°С‡РµРЅ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё"
  fi
  log "Р“РѕС‚РѕРІРѕ. Р‘СЌРєР°Рї РєРѕРЅС„РёРіРѕРІ: $bak"
}

# =====================================================================
# Р”РћРњР•Рќ + РЎР•Р РўРР¤РРљРђРў РџРђРќР•Р›Р РЎР РђР—РЈ РџРћРЎР›Р• Р§РРЎРўРћР™ РЈРЎРўРђРќРћР’РљР
# =====================================================================
setup_panel_cert_domain() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }

  # СѓР¶Рµ РЅР°СЃС‚СЂРѕРµРЅРѕ вЂ” РЅРµ С‚СЂРѕРіР°РµРј, РЅРѕ СЃРµСЂС‚ РїРѕРґРїРёСЃРѕРє РїСЂРёРІРѕРґРёРј Рє РїР°РЅРµР»СЊРЅРѕРјСѓ
  local cur_dom="" cur_cert="" cur_subcert="" cur_key="" cur_end=""
  cur_dom=$(xui_get webDomain); cur_cert=$(xui_get webCertFile); cur_subcert=$(xui_get subCertFile)
  if [[ -n "$cur_cert" && -f "$cur_cert" ]] && openssl x509 -noout -in "$cur_cert" >/dev/null 2>&1; then
    # РЎР•Р Рў РЈР–Р• Р•РЎРўР¬ (РІ С‚.С‡. РІС‹РїСѓС‰РµРЅРЅС‹Р№ С‡РµСЂРµР· РјРµРЅСЋ x-ui) вЂ” СЃС‡РёС‚С‹РІР°РµРј Рё РїРѕР»СЊР·СѓРµРјСЃСЏ РёРј
    cur_end=$(openssl x509 -noout -enddate -in "$cur_cert" 2>/dev/null | cut -d= -f2)
    if [[ -z "$cur_dom" ]]; then
      # x-ui РјРµРЅСЋ РјРѕРіР»Рѕ РІРїРёСЃР°С‚СЊ СЃРµСЂС‚ Р±РµР· РґРѕРјРµРЅР° вЂ” РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј РёР· SAN/CN
      cur_dom=$(openssl x509 -noout -ext subjectAltName -in "$cur_cert" 2>/dev/null \
          | grep -oE 'DNS:[^,]+' | head -1 | sed 's/DNS://; s/^\*\.//')
      [[ -z "$cur_dom" ]] && cur_dom=$(openssl x509 -noout -subject -in "$cur_cert" 2>/dev/null \
          | grep -oE 'CN ?= ?[^/,]+' | head -1 | sed 's/.*CN *= *//')
      if [[ -n "$cur_dom" ]]; then
        xui_set_setting webDomain "$cur_dom"
        xui_set_setting subDomain "$cur_dom"
        xui_set_setting subURI "$(suburi_build "$cur_dom")"
        log "Р”РѕРјРµРЅ РїР°РЅРµР»Рё РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ РёР· СЃРµСЂС‚Р°: $cur_dom (РІРїРёСЃР°РЅ РІ webDomain/subDomain)"
      fi
    fi
    log "РЎС‡РёС‚Р°РЅ СЃРµСЂС‚ РїР°РЅРµР»Рё РёР· РЅР°СЃС‚СЂРѕРµРє x-ui: ${cur_dom:-РґРѕРјРµРЅ РЅРµ РѕРїСЂРµРґРµР»С‘РЅ} в†’ $cur_cert"
    [[ -n "$cur_end" ]] && log "  РґРµР№СЃС‚РІСѓРµС‚ РґРѕ: $cur_end"
    cur_key=$(xui_get webKeyFile)
    # РџРђРќР•Р›Р¬: РїСѓС‚Рё СЃРµСЂС‚Р° РґРѕР»Р¶РЅС‹ СѓРєР°Р·С‹РІР°С‚СЊ РІ /etc/letsencrypt/live/ (РµРґРёРЅРѕРµ РјРµСЃС‚Рѕ)
    if [[ "$cur_cert" != /etc/letsencrypt/live/* && -n "$cur_dom" ]]; then
      local mline=""
      mline=$(cert_mirror_to_certroot "$(dirname "$cur_cert")" "$cur_dom" 2>/dev/null || true)
      if [[ -n "$mline" ]]; then
        xui_set_setting webCertFile "${mline%% *}"
        xui_set_setting webKeyFile  "${mline##* }"
        xui_set_setting subCertFile "${mline%% *}"
        xui_set_setting subKeyFile  "${mline##* }"
        systemctl restart x-ui 2>/dev/null || true
        log "РЎРµСЂС‚ РїР°РЅРµР»Рё РїРµСЂРµРїСЂРёРІСЏР·Р°РЅ РЅР° ${mline%% *} (РµРґРёРЅРѕРµ РјРµСЃС‚Рѕ live/)"
      fi
    fi
    if [[ -z "$cur_subcert" || "$cur_subcert" != "$cur_cert" || ! -f "$cur_subcert" ]]; then
      warn "subCertFile ($cur_subcert) в‰  РїР°РЅРµР»СЊРЅРѕРјСѓ вЂ” Р·Р°РјРµРЅСЏСЋ РЅР° $cur_cert"
      xui_set_setting subCertFile "$cur_cert"
      xui_set_setting subKeyFile  "$cur_key"
      systemctl restart x-ui 2>/dev/null || true
      log "subCertFile/subKeyFile РѕР±РЅРѕРІР»РµРЅС‹: $cur_cert"
    fi
    PANEL_DOMAIN="${PANEL_DOMAIN:-$cur_dom}"
    return 0
  fi

  echo; line; echo -e "${B}   Р”РћРњР•Рќ Р РЎР•Р РўРР¤РРљРђРў РџРђРќР•Р›Р${N}"; line
  local pdomain="${PANEL_DOMAIN:-}"
  if [[ -z "$pdomain" ]]; then
    ask pdomain "Р”РѕРјРµРЅ РїР°РЅРµР»Рё (A-Р·Р°РїРёСЃСЊ в†’ СЌС‚РѕС‚ СЃРµСЂРІРµСЂ)" "panel.example.com" '^[a-zA-Z0-9.-]+$'
  fi
  [[ -z "$pdomain" ]] && { warn "Р”РѕРјРµРЅ РЅРµ СѓРєР°Р·Р°РЅ вЂ” РїР°РЅРµР»СЊ РѕСЃС‚Р°С‘С‚СЃСЏ РЅР° СЃР°РјРѕРїРѕРґРїРёСЃР°РЅРЅРѕРј СЃРµСЂС‚РёС„РёРєР°С‚Рµ"; return 1; }

  cert_issue "$pdomain" || { err "РЎРµСЂС‚РёС„РёРєР°С‚ $pdomain РЅРµ РІС‹РїСѓС‰РµРЅ"; return 1; }
  local cp_line="" pc="" pk=""
  cp_line=$(cert_paths "$pdomain") || true
  [[ -z "$cp_line" ]] && { err "cert_paths РїСѓСЃС‚ РґР»СЏ $pdomain"; return 1; }
  pc="${cp_line%% *}"; pk="${cp_line##* }"
  # РїСѓС‚Рё РїР°РЅРµР»Рё вЂ” РёР· /etc/letsencrypt/live/ (РµРґРёРЅРѕРµ РјРµСЃС‚Рѕ)
  local mline=""
  mline=$(cert_mirror_to_certroot "$(dirname "$pc")" "$pdomain" 2>/dev/null || true)
  [[ -n "$mline" ]] && { pc="${mline%% *}"; pk="${mline##* }"; }

  xui_set_setting webDomain   "$pdomain"
  xui_set_setting webCertFile "$pc"
  xui_set_setting webKeyFile  "$pk"
  xui_set_setting subCertFile "$pc"
  xui_set_setting subKeyFile  "$pk"
  xui_set_setting subDomain   "$pdomain"
  # URL РѕР±СЂР°С‚РЅРѕРіРѕ РїСЂРѕРєСЃРё РґР»СЏ РїРѕРґРїРёСЃРѕРє: РёРЅР°С‡Рµ share-СЃСЃС‹Р»РєРё РїРѕР»СѓС‡Р°СЋС‚ РїРѕСЂС‚ РїР°РЅРµР»Рё
  xui_set_setting subURI      "$(suburi_build "$pdomain")"

  systemctl restart x-ui 2>/dev/null || true
  sleep 2
  local chk=""
  chk=$(xui_get webCertFile)
  if [[ "$chk" == "$pc" ]]; then
    log "РџР°РЅРµР»СЊ: РґРѕРјРµРЅ $pdomain + СЃРµСЂС‚РёС„РёРєР°С‚ РІРїРёСЃР°РЅС‹ РІ РЅР°СЃС‚СЂРѕР№РєРё"
    PANEL_DOMAIN="$pdomain"
    SNI_USED["$pdomain"]="${SNI_USED[$pdomain]:-panel_backend}"
    return 0
  fi
  err "webCertFile РЅРµ РїСЂРёРјРµРЅРёР»СЃСЏ (chk='$chk')"
  return 1
}

install_lucx_panel() {
  line; echo -e "${B}   РЈРЎРўРђРќРћР’РљРђ РџРђРќР•Р›Р LUCX UI${N}"; line
  detect_env
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && { log "РџР°РЅРµР»СЊ СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°: $XUI_DB"; return 0; }
  warn "x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” СѓСЃС‚Р°РЅР°РІР»РёРІР°СЋ LucX UI (РІРѕРїСЂРѕСЃ Р·Р°РґР°С‘С‚СЃСЏ РѕРґРёРЅ СЂР°Р·, РІ РЅР°С‡Р°Р»Рµ СЃРєСЂРёРїС‚Р°)."

  local tmp_sh rc
  tmp_sh=$(mktemp /tmp/lucx-install.XXXXXX.sh 2>/dev/null) || { err "mktemp failed"; return 1; }
  log "РЎРєР°С‡РёРІР°РЅРёРµ СѓСЃС‚Р°РЅРѕРІС‰РёРєР° LucX UI..."
  if ! curl -fSL --retry 3 "$LUCX_INSTALL_URL" -o "$tmp_sh" || [[ ! -s "$tmp_sh" ]]; then
    rm -f "$tmp_sh"
    err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРєР°С‡Р°С‚СЊ СѓСЃС‚Р°РЅРѕРІС‰РёРє LucX UI ($LUCX_INSTALL_URL)"; return 1
  fi
  # Р–РЃРЎРўРљРР™ SKIP SSL РЈРЎРўРђРќРћР’Р©РРљРђ: РїР°РЅРµР»СЊ СЃС‚Р°РІРёС‚СЃСЏ Р‘Р•Р— SSL (reverse proxy = РЅР°С€ nginx).
  # XUI_NONINTERACTIVE=1 РѕР±СЏР·Р°С‚РµР»РµРЅ: С‚РѕР»СЊРєРѕ РІ СЌС‚РѕРј СЂРµР¶РёРјРµ СѓСЃС‚Р°РЅРѕРІС‰РёРє С‡РёС‚Р°РµС‚
  # XUI_SSL_MODE=none Рё РќР• РїРѕРєР°Р·С‹РІР°РµС‚ РјРµРЅСЋ В«1..4, default 2В» (РІ РёРЅС‚РµСЂР°РєС‚РёРІРµ РѕРЅРѕ
  # РїРѕРєР°Р·С‹РІР°РµС‚СЃСЏ РІСЃРµРіРґР° Рё РІРµРґС‘С‚ Рє РєРѕРЅС„Р»РёРєС‚Сѓ В«РїРѕСЂС‚ Р·Р°РЅСЏС‚ 80В»).
  # Р’СЃРµ РїР°СЂР°РјРµС‚СЂС‹ РїРµСЂРµРґР°С‘Рј С‡РµСЂРµР· env вЂ” РІРѕРїСЂРѕСЃРѕРІ РЅРѕР»СЊ. РЎРµСЂС‚ РїР°РЅРµР»Рё РІРїРёСЃС‹РІР°РµС‚СЃСЏ
  # СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ СѓСЃС‚Р°РЅРѕРІРєРё (setup_panel_cert_domain) РёР»Рё С‡РµСЂРµР· РЎР•Р РўРР¤РРљРђРўР« в†’ 5.
  # РїР°СЂРѕР»СЊ РїР°РЅРµР»Рё: Р·Р°РґР°РЅРЅС‹Р№ РїСЂРё Р°РІС‚Рѕ-СѓСЃС‚Р°РЅРѕРІРєРµ (U_PANEL_PASS) в†’ РёРЅС‚РµСЂР°РєС‚РёРІРЅС‹Р№
  # РІРѕРїСЂРѕСЃ (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№) в†’ СЃР»СѓС‡Р°Р№РЅС‹Р№; Р»РѕРіРёРЅ вЂ” U_PANEL_USER (Enter вЂ” admin)
  local lucx_user="${U_PANEL_USER:-admin}"
  local lucx_pass="${U_PANEL_PASS:-}"
  if [[ -z "$lucx_pass" ]]; then
    lucx_pass=$(openssl rand -base64 18 2>/dev/null | tr -dc 'a-zA-Z0-9' | head -c 16)
    [[ -z "$lucx_pass" ]] && lucx_pass="LucX$(date +%s)"
    if [[ -t 0 ]]; then
      ask lucx_pass "РџР°СЂРѕР»СЊ РїР°РЅРµР»Рё admin (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№)" "$lucx_pass" '^.{6,}$'
    fi
  fi
  # РџРѕСЂС‚/РїСѓС‚СЊ СѓСЃС‚Р°РЅРѕРІС‰РёРєСѓ: СЃРѕР±СЂР°РЅРЅС‹Рµ СЂР°РЅРµРµ РІ СЌС‚РѕР№ СЃРµСЃСЃРёРё (ask_panel_creds Р”Рћ
  # СѓСЃС‚Р°РЅРѕРІРєРё вЂ” РµРґРёРЅС‹Р№ РїСѓС‚СЊ РїРµСЂРІРѕРіРѕ Р·Р°РїСѓСЃРєР°), РёРЅР°С‡Рµ СЃР»СѓС‡Р°Р№РЅС‹Рµ. Р‘РµР· СЌС‚РѕРіРѕ
  # СѓСЃС‚Р°РЅРѕРІС‰РёРє СЃС‚Р°РІРёС‚ РїР°РЅРµР»СЊ РЅР° СЃРІРѕР№ СЃР»СѓС‡Р°Р№РЅС‹Р№ РїРѕСЂС‚/РїСѓС‚СЊ, Р° СЃРѕР±СЂР°РЅРЅС‹Рµ Р·РЅР°С‡РµРЅРёСЏ
  # В«РґРѕРіРѕРЅСЏСЋС‚В» С‚РѕР»СЊРєРѕ РІ СЃР°РјРѕРј РєРѕРЅС†Рµ (initial_setup) вЂ” РїР°РЅРµР»СЊ Р¶РёРІС‘С‚ РїРѕР»-СѓСЃС‚Р°РЅРѕРІРєРё
  # РЅРµ РЅР° С‚РѕРј Р°РґСЂРµСЃРµ. РЈСЃС‚Р°РЅРѕРІС‰РёРє LucX Р¶РґС‘С‚ РїСѓС‚СЊ Р‘Р•Р— СЃР»СЌС€РµР№ (U_PANEL_PATH = /РїСѓС‚СЊ/).
  lucx_port="${U_PANEL_PORT:-$(make_port)}"
  lucx_wbp="${U_PANEL_PATH:-/$(gen_random_string 12)/}"
  lucx_wbp="${lucx_wbp#/}"; lucx_wbp="${lucx_wbp%/}"
  log "Р—Р°РїСѓСЃРє СѓСЃС‚Р°РЅРѕРІС‰РёРєР° LucX UI (XUI_NONINTERACTIVE=1 + XUI_SSL_MODE=none вЂ” Р±РµР· РІРѕРїСЂРѕСЃРѕРІ Рё Р±РµР· SSL)..."
  XUI_NONINTERACTIVE=1 XUI_SSL_MODE=none XUI_DB_TYPE=sqlite \
    XUI_USERNAME="$lucx_user" XUI_PASSWORD="$lucx_pass" \
    XUI_PANEL_PORT="$lucx_port" XUI_WEB_BASE_PATH="$lucx_wbp" \
    bash "$tmp_sh"
  rc=$?
  rm -f "$tmp_sh"

  # РєСЂРµРґС‹ РїР°РЅРµР»Рё вЂ” С„РёРєСЃРёСЂСѓРµРј (СѓСЃС‚Р°РЅРѕРІС‰РёРє РІ РЅРµРёРЅС‚РµСЂР°РєС‚РёРІРµ Р±РµСЂС‘С‚ РёС… РёР· env)
  {
    echo "LucX UI РїР°РЅРµР»СЊ вЂ” $(date '+%F %T')"
    echo "  Р›РѕРіРёРЅ:  $lucx_user"
    echo "  РџР°СЂРѕР»СЊ: $lucx_pass"
  } > /root/panel-credentials.txt 2>/dev/null || true
  chmod 600 /root/panel-credentials.txt 2>/dev/null || true
  # Р·Р°РїРѕРјРЅРёС‚СЊ С„РёРЅР°Р»СЊРЅС‹Рµ РєСЂРµРґС‹ РіР»РѕР±Р°Р»СЊРЅРѕ вЂ” Р°РІС‚Рѕ-РїРѕС‚РѕРє РЅРµ СЃРїСЂР°С€РёРІР°РµС‚ РІС‚РѕСЂРѕР№ СЂР°Р·
  U_PANEL_PASS="$lucx_pass"
  U_PANEL_USER="$lucx_user"

  if [[ $rc -ne 0 ]]; then
    err "РћС€РёР±РєР° СѓСЃС‚Р°РЅРѕРІРєРё LucX UI"; return 1
  fi
  detect_env
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    log "РџР°РЅРµР»СЊ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°: $XUI_DB"
    # Р§РРЎРўРђРЇ СѓСЃС‚Р°РЅРѕРІРєР°: СЃС‚Р°СЂС‹Рµ SNI-Р·Р°РїРёСЃРё РїР°РЅРµР»Рё/decoy/AdGuard РЅРµРґРµР№СЃС‚РІРёС‚РµР»СЊРЅС‹
    # (РЅРѕРІС‹Рµ РїРѕСЂС‚С‹/РїСѓС‚Рё). РЎРЅРѕСЃРёРј sni-СЂРѕСѓС‚РµСЂ Рё stack.conf вЂ” Рї.1 СЃРѕР·РґР°СЃС‚ Р·Р°РЅРѕРІРѕ.
    rm -f /etc/nginx/streams-enabled/sni-router.conf 2>/dev/null || true
    rm -f /etc/nginx/sites-enabled/stack.conf /etc/nginx/sites-available/stack.conf 2>/dev/null || true
    nginx -t >/dev/null 2>&1 && nginx_reload || true
    log "РЎС‚Р°СЂС‹Рµ SNI-Р·Р°РїРёСЃРё РїР°РЅРµР»Рё/AdGuard РѕС‡РёС‰РµРЅС‹ (Рї.1 СЃРѕР·РґР°СЃС‚ РЅРѕРІС‹Рµ)"
    # nginx СЃС‚Р°РІРёС‚СЃСЏ Р·Р°РІРёСЃРёРјРѕСЃС‚СЊСЋ Рё РјРѕР¶РµС‚ Р±С‹С‚СЊ Р±РµР· Р°РІС‚РѕР·Р°РїСѓСЃРєР° вЂ” СЃС‚РµРє РѕР±СЏР·Р°РЅ РїРѕРґРЅРёРјР°С‚СЊСЃСЏ РїРѕСЃР»Рµ СЂРµР±СЂР°
    systemctl enable nginx >/dev/null 2>&1 || true
    # РЎР РђР—РЈ РїРѕСЃР»Рµ С‡РёСЃС‚РѕР№ СѓСЃС‚Р°РЅРѕРІРєРё: РґРѕРјРµРЅ + РЅР°СЃС‚РѕСЏС‰РёР№ СЃРµСЂС‚РёС„РёРєР°С‚ РїР°РЅРµР»Рё
    setup_panel_cert_domain || warn "Р”РѕРјРµРЅ/СЃРµСЂС‚РёС„РёРєР°С‚ РїР°РЅРµР»Рё РјРѕР¶РЅРѕ Р·Р°РґР°С‚СЊ РїРѕР·Р¶Рµ (Рї.1)"
    return 0
  fi
  err "РЈСЃС‚Р°РЅРѕРІРєР° РїСЂРѕС€Р»Р°, РЅРѕ x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1
}

# =====================================================================
# Р“Р•РќР•Р РђРўРћР Р«
# =====================================================================
gen_uuid() { cat /proc/sys/kernel/random/uuid 2>/dev/null || openssl rand -hex 16; }
gen_hex()  { openssl rand -hex "$1" 2>/dev/null || head -c "$1" /dev/urandom | xxd -p | head -c "$(( $1 * 2 ))"; }
gen_b64()  { openssl rand -base64 24 2>/dev/null | tr -d '/+=' | head -c 22; }
sql_escape() { echo "${1//\'/\'\'}"; }

gen_reality_keys() {
  local out="" priv="" pub=""
  if [[ -n "$XRAY_BIN" && -x "$XRAY_BIN" ]]; then
    out=$("$XRAY_BIN" x25519 2>/dev/null || true)
    priv=$(echo "$out" | grep -iE 'private' | awk '{print $NF}' | head -1)
    pub=$(echo "$out"  | grep -iE 'public'  | awk '{print $NF}' | head -1)
  fi
  if [[ -z "$priv" || -z "$pub" ]]; then
    priv=$(openssl rand -base64 32 | tr -d '/+=' | head -c 43)
    pub=$(openssl rand -base64 32 | tr -d '/+=' | head -c 43)
    warn "  xray РЅРµ РЅР°Р№РґРµРЅ вЂ” Reality-РєР»СЋС‡Рё СЃРіРµРЅРµСЂРёСЂРѕРІР°РЅС‹ openssl Рё РќР•Р’РђР›РР”РќР«! РЈСЃС‚Р°РЅРѕРІРёС‚Рµ РїР°РЅРµР»СЊ (Рї.14), Р·Р°С‚РµРј РїРµСЂРµСЃРѕР·РґР°Р№С‚Рµ РёРЅР±Р°СѓРЅРґ."
  fi
  echo "$priv|$pub"
}

# =====================================================================
# РЎРћР—Р”РђРќРР• РРќР‘РђРЈРќР”РћР’
# =====================================================================
inbounds_columns() {
  sqlite3 "$XUI_DB" "PRAGMA table_info(inbounds);" 2>/dev/null \
    | awk -F'|' '{print $2}' | tr '\n' ' '
}

create_inbound_db() {
  local proto="$1" transport="$2" security="$3" flow="$4" port="$5" remark="$6"
  local net="$7"            # tcp / udp
  local sn="${8:-}"         # SNI-РґРѕРјРµРЅ (РїРѕРґС‚СЏРіРёРІР°РµС‚СЃСЏ РІ serverNames/serverName)
  local vk="${9:-}"         # VK call hashes (С‚РѕР»СЊРєРѕ qwdtt/csqtt, С‡РµСЂРµР· Р·Р°РїСЏС‚СѓСЋ)
  local cemail="${10:-}"    # РёРјСЏ РєР»РёРµРЅС‚Р° (email); РїСѓСЃС‚Рѕ в†’ Р±РµР·Р»РёРєРёР№ user
  local cert="" key=""
  if [[ -n "$sn" ]]; then
    local cp_line=""
    cp_line=$(cert_paths "$sn") || true     # wildcard- РёР»Рё РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚РёС„РёРєР°С‚
    if [[ -z "$cp_line" && "${CERT_DEFER:-0}" == "1" ]]; then
      # РћС‚Р»РѕР¶РµРЅРЅС‹Р№ РІС‹РїСѓСЃРє (РјР°СЃС‚РµСЂ СѓСЃС‚Р°РЅРѕРІРєРё): СЃРµСЂС‚ РїРѕСЏРІРёС‚СЃСЏ РІ Р›РРќРР РїРѕСЃР»Рµ
      # РїР°С‡РєРё cert_batch_flush, Р° РїСѓС‚СЊ live/<Р»РёРЅРёСЏ>/ РґРµС‚РµСЂРјРёРЅРёСЂРѕРІР°РЅ вЂ” РІРїРёСЃС‹РІР°РµРј
      # РµРіРѕ СЃСЂР°Р·Сѓ, РёРЅР°С‡Рµ tunnel-РёРЅР±Р°СѓРЅРґС‹ СЃРѕР·РґР°СЋС‚СЃСЏ СЃ РїСѓСЃС‚С‹РјРё certFile/keyFile.
      cp_line=$(cert_line_paths_expect "$sn") || true
      if [[ -n "$cp_line" ]]; then
        cert="${cp_line%% *}"; key="${cp_line##* }"
        warn "  СЃРµСЂС‚ $sn РµС‰С‘ РЅРµ РІС‹РїСѓС‰РµРЅ (РїР°С‡РєР° РІ РєРѕРЅС†Рµ СѓСЃС‚Р°РЅРѕРІРєРё) вЂ” РІРїРёСЃР°РЅ РїСѓС‚СЊ Р»РёРЅРёРё"
      fi
    fi
    [[ -n "$cp_line" ]] && { cert="${cp_line%% *}"; key="${cp_line##* }"; }
  fi
  # xray-hysteria РќР• СЃС‚Р°СЂС‚СѓРµС‚ Р±РµР· TLS ("tls config is nil"). Self-signed СѓР±СЂР°РЅ вЂ”
  # Р±СЂР°СѓР·РµСЂС‹/РєР»РёРµРЅС‚С‹ РµРіРѕ РЅРµ РїСЂРёРЅРёРјР°СЋС‚. РќРµС‚ СЃРµСЂС‚Р° РЅР° РґРѕРјРµРЅ Рё РЅР° РїР°РЅРµР»СЊ в†’ РёРЅР±Р°СѓРЅРґ
  # РЅРµ СЃРѕР·РґР°С‘С‚СЃСЏ (РІС‹РїСѓСЃС‚Рё СЃРµСЂС‚ Рё РґРѕР±Р°РІСЊ Р·Р°РЅРѕРІРѕ).
  if [[ "$proto" == "hysteria" && ( -z "$cert" || -z "$key" ) ]]; then
    local fdom="${PANEL_DOMAIN:-$(xui_get webDomain 2>/dev/null || true)}"
    local fline=""
    [[ -n "$fdom" ]] && fline=$(cert_paths "$fdom" 2>/dev/null || true)
    if [[ -n "$fline" ]]; then
      cert="${fline%% *}"; key="${fline##* }"
      warn "  hysteria: СЃРµСЂС‚ $sn РЅРµ РЅР°Р№РґРµРЅ вЂ” РёСЃРїРѕР»СЊР·СѓСЋ СЃРµСЂС‚ $fdom (РєР»РёРµРЅС‚: insecure=true)"
      [[ -z "$sn" ]] && sn="$fdom"
    else
      err "  hysteria: РЅРµС‚ РЅРё СЃРµСЂС‚Р° $sn, РЅРё СЃРµСЂС‚Р° РїР°РЅРµР»Рё вЂ” РёРЅР±Р°СѓРЅРґ РќР• СЃРѕР·РґР°РЅ. Р’С‹РїСѓСЃС‚Рё СЃРµСЂС‚ (Wildcard/РЎРµСЂС‚РёС„РёРєР°С‚С‹) Рё РґРѕР±Р°РІСЊ РёРЅР±Р°СѓРЅРґ Р·Р°РЅРѕРІРѕ."
      echo ""; return 1
    fi
  fi

  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; echo ""; return 1; }

  local cols
  cols=$(inbounds_columns)
  local missing=()
  local need
  for need in port protocol settings stream_settings remark enable listen sniffing; do
    grep -qw "$need" <<<"$cols" || missing+=("$need")
  done
  if [[ ${#missing[@]} -gt 0 ]]; then
    err "Р’ С‚Р°Р±Р»РёС†Рµ inbounds РЅРµС‚ РєРѕР»РѕРЅРѕРє: ${missing[*]}"
    echo ""; return 1
  fi

  local uuid sub_id
  uuid=$(gen_uuid)
  sub_id=$(gen_hex 8)
  local salamander="" secret32="" ip4=""
  salamander=$(gen_b64 | tr '[:upper:]' '[:lower:]')
  secret32=$(gen_hex 16)
  ip4=$(server_ip4)

  # --- settings ---
  local settings_json
  case "$proto" in
    vless)
      settings_json=$(cat <<EOF
{"clients":[],"decryption":"none","fallbacks":[]}
EOF
)
      ;;
    anytls)
      # tunnel-РёРЅР±Р°СѓРЅРґ LucX (internal/lucx/tunnel/anytls_inbound.go):
      # РїР°РЅРµР»СЊ Р·Р°РїСѓСЃРєР°РµС‚ anytls-server, РїР°СЂРѕР»СЊ РѕР±С‰РёР№ РЅР° РїРѕСЂС‚
      settings_json=$(cat <<EOF
{"remark":"anytls-$port","enabled":true,"port":$port,"listen":"127.0.0.1","password":"$(gen_b64)","sni":"$sn","certFile":"$cert","keyFile":"$key"}
EOF
) ;;
    trusttunnel|trust-tunnel)
      # tunnel-РёРЅР±Р°СѓРЅРґ LucX (trusttunnel_inbound.go): hostname+cert РѕР±СЏР·Р°С‚РµР»СЊРЅС‹,
      # РєР»РёРµРЅС‚С‹ в†’ HMAC-РєСЂРµРґС‹ РёР· authSeed (РїР°РЅРµР»СЊ РїРѕРєР°Р¶РµС‚ РёС… Рё РІ share-СЃСЃС‹Р»РєР°С…)
      settings_json=$(cat <<EOF
{"remark":"trusttunnel-$port","hostname":"$sn","listen":"127.0.0.1","port":$port,"ipv6":false,"certFile":"$cert","keyFile":"$key","clientDns":"1.1.1.1","upstreamProtocol":"http2","routeThroughXray":false,"routeXrayPort":0,"outboundTag":"","metricsPort":0,"listenPreset":"fast","clientRandomPrefix":"$(gen_hex 4)/ffffffff","authSeed":"$(gen_hex 32)","clients":[]}
EOF
) ;;
    naive|naiveproxy)
      # tunnel-РёРЅР±Р°СѓРЅРґ LucX (naive_inbound.go): caddy forward_proxy Р·Р° nginx 443.
      # РЎР•Р Р’РРЎРќР«Р™ Р»РѕРіРёРЅ/РїР°СЂРѕР»СЊ РіРµРЅРµСЂРёСЂСѓРµРј СЃСЂР°Р·Сѓ + authSeed РґР»СЏ РєР»РёРµРЅС‚СЃРєРёС… РїР°СЂ.
      settings_json=$(cat <<EOF
{"remark":"naive-$port","listen":"127.0.0.1","port":$port,"domain":"$sn","useAcme":false,"acmeEmail":"","certFile":"$cert","keyFile":"$key","authUser":"$(gen_hex 4)","authPass":"$(gen_b64)","enableH3":false,"probeResistance":false,"logLevel":"WARN","extraArgs":"","routeThroughXray":false,"routeXrayPort":0,"outboundTag":"","useRawConfig":false,"rawConfig":"","behindCover":false,"hideOn443":false,"authSeed":"$(gen_hex 32)","clients":[{"email":"user","enable":true}]}
EOF
) ;;
    hysteria)
      # СЂРµС†РµРїС‚ lucx-ui-pro: hysteriaSettings v2 + salamander РІ finalmask
      settings_json='{"version":2,"clients":[]}' ;;
    qwdtt)
      # СЂРµС†РµРїС‚ lucx-ui-pro: tunnel-РїСЂРѕС‚РѕРєРѕР», РєР»РёРµРЅС‚С‹ РґРѕР±Р°РІР»СЏСЋС‚СЃСЏ РІ РїР°РЅРµР»Рё (share-only)
      settings_json=$(cat <<EOF
{"clients":[],"remark":"$remark","enabled":true,"listenAddr":"0.0.0.0:$port","wgPort":56001,"password":"$(gen_b64)","dns":"8.8.8.8","configDir":"","listenRaw":"0.0.0.0:56003","listenDirect":"","subHost":"$ip4:$port","vkHashes":"$vk","clientPort":9000,"workers":16,"routeThroughXray":true,"outboundTag":""}
EOF
) ;;
    csqtt)
      settings_json=$(cat <<EOF
{"clients":[],"remark":"$remark","enabled":true,"listenAddr":"0.0.0.0:$port","password":"$(gen_b64)","deviceId":"","webPass":"$(gen_b64)","subHost":"$ip4","vkHashes":"$vk","configDir":"","routeThroughXray":true,"outboundTag":""}
EOF
) ;;
    tproxy)
      # Telegram WEB-proxy LucX: СЃР»СѓС€Р°РµС‚ 127.0.0.1:11443, РЅР°СЂСѓР¶Сѓ С‡РµСЂРµР· nginx 443
      settings_json=$(cat <<EOF
{"clients":[],"port":11443,"hostname":"$sn","secret":"$secret32","siteSource":"dir","siteDir":"/var/www/html","siteUpstream":"","carrierMode":"https","certFile":"$cert","keyFile":"$key","externalTLS":false,"behindCover":false,"routeThroughXray":false,"outboundTag":"","routeXrayPort":0}
EOF
) ;;
    awg|amneziawg|wireguard)
      # LucX sidecar: settings РіРµРЅРµСЂРёСЂСѓРµС‚ awg_settings_json (РІРµСЂСЃРёСЏ РІ transport:
      # awg31 в†’ AmneziaWG 3.1, awg20 в†’ 2.0; РїСЂРѕС„РёР»СЊ РѕР±С„СѓСЃРєР°С†РёРё Amnezia Premium)
      settings_json=$(awg_settings_json "${transport#awg}" "$port") ;;
    *)
      settings_json="{\"clients\":[{\"id\":\"$uuid\",\"email\":\"user@$port\",\"enable\":true}]}" ;;
  esac

  # --- stream_settings ---
  local stream_json
  case "$transport" in
    tcp)
      if [[ "$security" == "reality" ]]; then
        local keys priv pub short_id
        keys=$(gen_reality_keys); priv="${keys%%|*}"; pub="${keys##*|}"
        short_id=$(gen_hex 8)
        local sn_show=""
        if [[ -n "${REALITY_EXT_TARGET:-}" ]]; then
          sn_show="$REALITY_EXT_TARGET"   # РІС‹Р±СЂР°РЅРЅС‹Р№ РїРѕР»СЊР·РѕРІР°С‚РµР»РµРј/Р°РІС‚Рѕ С‚Р°СЂРіРµС‚
        else
          sn_show=$(reality_find_target "${id:-0}")
        fi
        [[ -n "$sn" ]] && sn_show="$sn"
        local dest_show="$sn_show:443"
        [[ -n "$sn" ]] && dest_show="127.0.0.1:4444"   # Р»РѕРєР°Р»СЊРЅС‹Р№ decoy; С‚РѕС‡РЅС‹Р№ РїРѕСЂС‚ РїСЂРѕСЃС‚Р°РІРёС‚ configure_sni_for_inbound
        stream_json=$(cat <<EOF
{"network":"tcp","security":"reality","realitySettings":{"show":false,"xver":0,"dest":"$dest_show","target":"$dest_show","serverNames":["$sn_show"],"privateKey":"$priv","shortIds":["$short_id"],"settings":{"publicKey":"$pub","fingerprint":"firefox","serverName":"","spiderX":"/"},"fingerprint":"firefox"},"tcpSettings":{"acceptProxyProtocol":false,"header":{"type":"none"}}}
EOF
)
      elif [[ "$security" == "tls" ]]; then
        if [[ -n "$cert" && -n "$key" ]]; then
          stream_json="{\"network\":\"tcp\",\"security\":\"tls\",\"tlsSettings\":{\"serverName\":\"$sn\",\"minVersion\":\"1.2\",\"alpn\":[\"http/1.1\"],\"certificates\":[{\"certificateFile\":\"$cert\",\"keyFile\":\"$key\"}]},\"tcpSettings\":{\"acceptProxyProtocol\":false,\"header\":{\"type\":\"none\"}}}"
        else
          stream_json="{\"network\":\"tcp\",\"security\":\"tls\",\"tlsSettings\":{\"serverName\":\"$sn\",\"minVersion\":\"1.2\",\"alpn\":[\"http/1.1\"]},\"tcpSettings\":{\"acceptProxyProtocol\":false,\"header\":{\"type\":\"none\"}}}"
        fi
      else
        stream_json='{"network":"tcp","security":"none","tcpSettings":{"acceptProxyProtocol":false,"header":{"type":"none"}}}'
      fi
      ;;
    xhttp)
      if [[ "$security" == "reality" ]]; then
        local keys priv pub short_id
        keys=$(gen_reality_keys); priv="${keys%%|*}"; pub="${keys##*|}"
        short_id=$(gen_hex 8)
        local sn_show=""
        if [[ -n "${REALITY_EXT_TARGET:-}" ]]; then
          sn_show="$REALITY_EXT_TARGET"   # РІС‹Р±СЂР°РЅРЅС‹Р№ РїРѕР»СЊР·РѕРІР°С‚РµР»РµРј/Р°РІС‚Рѕ С‚Р°СЂРіРµС‚
        else
          sn_show=$(reality_find_target "${id:-0}")
        fi
        [[ -n "$sn" ]] && sn_show="$sn"
        local dest_show="$sn_show:443"
        [[ -n "$sn" ]] && dest_show="127.0.0.1:4444"   # Р»РѕРєР°Р»СЊРЅС‹Р№ decoy; С‚РѕС‡РЅС‹Р№ РїРѕСЂС‚ РїСЂРѕСЃС‚Р°РІРёС‚ configure_sni_for_inbound
        stream_json=$(cat <<EOF
{"network":"xhttp","security":"reality","realitySettings":{"show":false,"xver":0,"dest":"$dest_show","target":"$dest_show","serverNames":["$sn_show"],"privateKey":"$priv","shortIds":["$short_id"],"settings":{"publicKey":"$pub","fingerprint":"firefox","serverName":"","spiderX":"/"},"fingerprint":"firefox"},"xhttpSettings":{"path":"/$(gen_hex 6)","host":"","mode":"auto"}}
EOF
)
      elif [[ "$security" == "tls" ]]; then
        if [[ -n "$cert" && -n "$key" ]]; then
          stream_json="{\"network\":\"xhttp\",\"security\":\"tls\",\"tlsSettings\":{\"serverName\":\"$sn\",\"minVersion\":\"1.2\",\"certificates\":[{\"certificateFile\":\"$cert\",\"keyFile\":\"$key\"}]},\"xhttpSettings\":{\"path\":\"/$(gen_hex 6)\",\"host\":\"$sn\",\"mode\":\"auto\"}}"
        else
          stream_json="{\"network\":\"xhttp\",\"security\":\"tls\",\"tlsSettings\":{\"serverName\":\"$sn\",\"minVersion\":\"1.2\"},\"xhttpSettings\":{\"path\":\"/$(gen_hex 6)\",\"host\":\"$sn\",\"mode\":\"auto\"}}"
        fi
      else
        stream_json="{\"network\":\"xhttp\",\"security\":\"none\",\"xhttpSettings\":{\"path\":\"/$(gen_hex 6)\",\"host\":\"\",\"mode\":\"auto\"}}"
      fi
      ;;
    hysteria)
      # СЂРµС†РµРїС‚ lucx-ui-pro: TLS + hysteriaSettings + salamander РІ finalmask
      if [[ -n "$cert" && -n "$key" ]]; then
        stream_json=$(cat <<EOF
{"network":"hysteria","security":"tls","hysteriaSettings":{"version":2,"udpIdleTimeout":60},"tlsSettings":{"serverName":"$sn","minVersion":"1.2","maxVersion":"1.3","cipherSuites":"","rejectUnknownSni":false,"disableSystemRoot":false,"enableSessionResumption":false,"alpn":["h3"],"certificates":[{"useFile":true,"certificateFile":"$cert","keyFile":"$key","certificate":[],"key":[],"ocspStapling":0,"oneTimeLoading":false,"usage":"encipherment","buildChain":false}],"settings":{"fingerprint":"firefox","echConfigList":"","pinnedPeerCertSha256":[],"verifyPeerCertByName":""}},"finalmask":{"tcp":[],"udp":[{"type":"salamander","settings":{"password":"$salamander"}}]}}
EOF
)
      else
        stream_json='{"network":"hysteria","security":"none","hysteriaSettings":{"version":2,"udpIdleTimeout":60}}'
      fi
      ;;
    naive|anytls|trusttunnel|trust-tunnel)
      # tunnel-РёРЅР±Р°СѓРЅРґ LucX: stream РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ (РєРѕРЅС„РёРі Р¶РёРІС‘С‚ РІ settings)
      stream_json='{}'
      ;;
    qwdtt|csqtt|tproxy)
      # tunnel-РїСЂРѕС‚РѕРєРѕР»С‹ LucX: Р‘Р•Р— network-Р±Р»РѕРєР° (РёРЅР°С‡Рµ xray РїР°РґР°РµС‚ "unknown transport")
      stream_json='{"security":"none"}'
      ;;
    awg)
      # kernel-РёРЅР±Р°СѓРЅРґ РїР°РЅРµР»Рё: stream_settings РїСѓСЃС‚Р°СЏ СЃС‚СЂРѕРєР° (РєР°Рє Сѓ СЃРѕР·РґР°РЅРЅС‹С… РІ UI)
      stream_json=''
      ;;
    udp)
      stream_json='{"network":"udp","security":"none","udpSettings":{}}'
      ;;
    *)
      stream_json='{"network":"tcp","security":"none","tcpSettings":{"acceptProxyProtocol":false,"header":{"type":"none"}}}'
      ;;
  esac

  local sniffing_json='{"enabled":true,"destOverride":["http","tls","quic"],"routeOnly":false}'
  case "$proto" in
    qwdtt|csqtt|tproxy|hysteria)
      sniffing_json='{"enabled":true,"destOverride":["http","tls","quic","fakedns"],"metadataOnly":false,"routeOnly":false}' ;;
    awg)
      sniffing_json='' ;;   # kernel-РёРЅР±Р°СѓРЅРґ: Р±РµР· sniffing (РєР°Рє Сѓ СЃРѕР·РґР°РЅРЅС‹С… РІ UI)
  esac
  local listen
  case "$proto" in
    qwdtt|csqtt|hysteria) listen="" ;;          # РїРѕСЂС‚ Р¶РёРІС‘С‚ РІ settings.listenAddr
    tproxy)               listen="127.0.0.1" ;; # РЅР°СЂСѓР¶Сѓ С‚РѕР»СЊРєРѕ С‡РµСЂРµР· nginx 443
    awg)                  listen="" ;;          # РїРѕСЂС‚ Р¶РёРІС‘С‚ РІ settings (ListenPort РєРѕРЅС„РёРіР°)
    *) [[ "$net" == "udp" ]] && listen="0.0.0.0" || listen="127.0.0.1" ;;
  esac
  local tag_name="inbound-$port"
  case "$proto" in
    qwdtt) tag_name="inbound-qwdtt" ;;
    csqtt) tag_name="inbound-csqtt" ;;
    tproxy) tag_name="inbound-tproxy" ;;
    awg)   tag_name="in-$port-tcp" ;;   # РїР°РЅРµР»СЊ LucX РёРјРµРЅСѓРµС‚ С‚РµРіРё AWG С‚Р°Рє
  esac

  # --- СЌРєСЂР°РЅРёСЂСѓРµРј РѕРґРёРЅР°СЂРЅС‹Рµ РєР°РІС‹С‡РєРё ---
  settings_json=$(sql_escape "$settings_json")
  stream_json=$(sql_escape   "$stream_json")
  sniffing_json=$(sql_escape "$sniffing_json")
  remark=$(sql_escape "$remark")

  # --- СЃРѕР±РёСЂР°РµРј INSERT РїРѕ С„Р°РєС‚РёС‡РµСЃРєРѕР№ СЃС…РµРјРµ ---
  local field_list="port,protocol,settings,stream_settings,remark,enable,listen,sniffing"
  local value_list="$port,'$proto','$settings_json','$stream_json','$remark',1,'$listen','$sniffing_json'"

  grep -qw user_id     <<<"$cols" && { field_list+=",user_id";     value_list+=",1"; }
  grep -qw up          <<<"$cols" && { field_list+=",up";          value_list+=",0"; }
  grep -qw down        <<<"$cols" && { field_list+=",down";        value_list+=",0"; }
  grep -qw total       <<<"$cols" && { field_list+=",total";       value_list+=",0"; }
  grep -qw expiry_time <<<"$cols" && { field_list+=",expiry_time"; value_list+=",0"; }
  grep -qw tag         <<<"$cols" && { field_list+=",tag";         value_list+=",'$tag_name'"; }
  grep -qw allocate    <<<"$cols" && { field_list+=",allocate";    value_list+=",'{}'"; }

  local err_out
  # РїРѕРЅСЏС‚РЅР°СЏ РѕС€РёР±РєР° РІРјРµСЃС‚Рѕ SQL UNIQUE: LucX-sidecar С‚РµРіРё (inbound-qwdtt/csqtt/tproxy)
  # С„РёРєСЃРёСЂРѕРІР°РЅС‹ вЂ” РѕРґРёРЅ РёРЅР±Р°СѓРЅРґ С‚Р°РєРѕРіРѕ РїСЂРѕС‚РѕРєРѕР»Р° РЅР° СЃРµСЂРІРµСЂ
  if sqlite3 "$XUI_DB" "SELECT 1 FROM inbounds WHERE tag='$tag_name' LIMIT 1;" 2>/dev/null | grep -q 1; then
    err "  РўРµРі '$tag_name' СѓР¶Рµ Р·Р°РЅСЏС‚ (РёРЅР±Р°СѓРЅРґ id=$(sqlite3 "$XUI_DB" "SELECT id FROM inbounds WHERE tag='$tag_name';" 2>/dev/null)). Р”Р»СЏ sidecar-РїСЂРѕС‚РѕРєРѕР»РѕРІ LucX РґРѕРїСѓСЃРєР°РµС‚СЃСЏ С‚РѕР»СЊРєРѕ РѕРґРёРЅ СЌРєР·РµРјРїР»СЏСЂ."
    echo ""; return 1
  fi
  err_out=$(sqlite3 "$XUI_DB" "INSERT INTO inbounds ($field_list) VALUES ($value_list);" 2>&1) || {
    err "  SQL error: $err_out"
    echo ""; return 1
  }

  local new_id
  new_id=$(sqlite3 "$XUI_DB" "SELECT id FROM inbounds WHERE port=$port AND protocol='$proto' ORDER BY id DESC LIMIT 1;" 2>/dev/null || true)
  if [[ -z "$new_id" ]]; then
    err "  РРЅР±Р°СѓРЅРґ РЅРµ РЅР°Р№РґРµРЅ РїРѕСЃР»Рµ INSERT"
    echo ""; return 1
  fi
  if [[ "$proto" == "vless" && "$transport" == "xhttp" && "$security" == "tls" ]]; then
    XHTTP_TLS_CREATED_IDS="${XHTTP_TLS_CREATED_IDS:-} $new_id"
  fi

  # --- РїРѕСЃС‚-РґРµР№СЃС‚РІРёСЏ РїРѕ СЂРµС†РµРїС‚Р°Рј lucx-ui-pro ---
  # Р’РђР–РќРћ: РґР»СЏ hysteria HOSTS РІ РїР°РЅРµР»Рё РќР• СЃРѕР·РґР°СЋС‚СЃСЏ (UDP-РёРЅР±Р°СѓРЅРґ, РїРѕРґРїРёСЃРєР° Р±РµР· hosts)
  if [[ "$proto" == "tproxy" ]]; then
    umask 077
    cat > /root/.lucx-tg-web-proxy-info <<EOF2
TG_WEB_PROXY_DOMAIN=$sn
TG_WEB_PROXY_SECRET=$secret32
EOF2
    chmod 600 /root/.lucx-tg-web-proxy-info 2>/dev/null || true
    umask 022
    ensure_tproxy_site
  fi
  if [[ "$proto" == "naive" || "$proto" == "anytls" || "$proto" == "trusttunnel" ]]; then
    # РІС‹С‚Р°С‰РёС‚СЊ СЃРіРµРЅРµСЂРёСЂРѕРІР°РЅРЅС‹Рµ РєСЂРµРґС‹ РёР· settings вЂ” РІ С„Р°Р№Р» РїРѕР»СЊР·РѕРІР°С‚РµР»СЋ
    local svc_user="" svc_pass="" anytls_pw="" seed=""
    svc_user=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.authUser') FROM inbounds WHERE id=$new_id;" 2>/dev/null || true)
    svc_pass=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.authPass') FROM inbounds WHERE id=$new_id;" 2>/dev/null || true)
    anytls_pw=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.password') FROM inbounds WHERE id=$new_id;" 2>/dev/null || true)
    seed=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.authSeed') FROM inbounds WHERE id=$new_id;" 2>/dev/null || true)
    umask 077
    {
      echo "=== $proto #$new_id (LucX tunnel) ==="
      echo "Р”РѕРјРµРЅ (SNI): $sn"
      echo "РџРѕСЂС‚ РёРЅР±Р°СѓРЅРґР°: $port (РїР°РЅРµР»СЊ СЃР»СѓС€Р°РµС‚ 127.0.0.1:$port, СЃРЅР°СЂСѓР¶Рё вЂ” https://$sn:443 С‡РµСЂРµР· nginx)"
      if [[ "$proto" == "naive" ]]; then
        echo "РЎРµСЂРІРёСЃРЅС‹Р№ Р»РѕРіРёРЅ: $svc_user"
        echo "РЎРµСЂРІРёСЃРЅС‹Р№ РїР°СЂРѕР»СЊ: $svc_pass"
        echo "URL: naive+https://$svc_user:$svc_pass@$sn:443"
        echo "РљР»РёРµРЅС‚СЃРєРёРµ РїР°СЂС‹ (HMAC РѕС‚ authSeed) вЂ” РІ РїР°РЅРµР»Рё: РёРЅР±Р°СѓРЅРґ naive в†’ РєР»РёРµРЅС‚С‹/share"
      elif [[ "$proto" == "anytls" ]]; then
        echo "РџР°СЂРѕР»СЊ: $anytls_pw"
        echo "URL: anytls://$anytls_pw@$sn:443/?sni=$sn (РїРѕСЂС‚ 443 С‡РµСЂРµР· nginx)"
      else
        echo "РљР»РёРµРЅС‚: user вЂ” Р»РѕРіРёРЅ/РїР°СЂРѕР»СЊ РїР°РЅРµР»СЊ РіРµРЅРµСЂРёСЂСѓРµС‚ HMAC РѕС‚ authSeed,"
        echo "СЃРјРѕС‚СЂРёС‚Рµ РІ РїР°РЅРµР»Рё (РёРЅР±Р°СѓРЅРґ trusttunnel в†’ РєР»РёРµРЅС‚С‹, tt:// СЃСЃС‹Р»РєРё)"
      fi
      echo "authSeed: $seed"
    } > "/root/.lucx-$proto-info"
    chmod 600 "/root/.lucx-$proto-info" 2>/dev/null || true
    umask 022
  fi
  case "$proto" in
    qwdtt|csqtt|tproxy|awg) ensure_shareonly_triggers ;;
  esac

  echo "$new_id"
  return 0
}

create_inbounds_menu() {
  line; echo -e "${B}   РЎРћР—Р”РђРќРР• РРќР‘РђРЈРќР”РћР’${N}"; line

  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }

  local existing=0
  existing=$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE enable=1;" 2>/dev/null || echo 0)
  [[ "$existing" -gt 0 ]] && log "РђРєС‚РёРІРЅС‹С… РёРЅР±Р°СѓРЅРґРѕРІ: $existing вЂ” РІС‹Р±РёСЂР°Р№ С‚РёРї РЅРѕРІРѕРіРѕ."

  # Р±С‹СЃС‚СЂР°СЏ РїСЂРѕРІРµСЂРєР° СЃС…РµРјС‹
  local cols
  cols=$(inbounds_columns)
  [[ -z "$cols" ]] && { err "РќРµ СѓРґР°Р»РѕСЃСЊ РїРѕР»СѓС‡РёС‚СЊ СЃС…РµРјСѓ inbounds"; return 1; }
  local miss=() n
  for n in port protocol settings stream_settings remark enable listen sniffing; do
    grep -qw "$n" <<<"$cols" || miss+=("$n")
  done
  [[ ${#miss[@]} -gt 0 ]] && { err "Р’ С‚Р°Р±Р»РёС†Рµ РЅРµС‚ РєРѕР»РѕРЅРѕРє: ${miss[*]}"; return 1; }

  echo
  echo -e "${B}Р’С‹Р±РµСЂРёС‚Рµ РёРЅР±Р°СѓРЅРґС‹ РґР»СЏ СЃРѕР·РґР°РЅРёСЏ:${N}"
  echo
  # Р“РµР№С‚ РїРѕ С‚РёРїСѓ РїР°РЅРµР»Рё: РІ РѕСЂРёРіРёРЅР°Р»СЊРЅРѕРј 3x-ui РґРѕСЃС‚СѓРїРЅС‹ VLESS Рё Hysteria2.
  # QWDTT/CSQTT/tproxy/naive/anytls/trusttunnel/hysteria вЂ” СЂРµС†РµРїС‚С‹ LucX UI:
  # РїР°РЅРµР»СЊ LucX СЃР°РјР° РїРѕРґРЅРёРјР°РµС‚ sidecar'С‹ Рё РїРѕРЅРёРјР°РµС‚ СЃРІРѕРё С„РѕСЂРјР°С‚С‹ settings.
  local flavor="${PANEL_FLAVOR:-}"
  [[ -z "$flavor" ]] && flavor=$(detect_panel_flavor)
  case "$flavor" in
    lucx) echo "  РћР±РЅР°СЂСѓР¶РµРЅР° РїР°РЅРµР»СЊ: LucX UI вЂ” РґРѕСЃС‚СѓРїРЅС‹ LucX sidecar-РїСЂРѕС‚РѕРєРѕР»С‹." ;;
    3x-ui) echo "  РћР±РЅР°СЂСѓР¶РµРЅР° РїР°РЅРµР»СЊ: РѕСЂРёРіРёРЅР°Р»СЊРЅС‹Р№ 3x-ui вЂ” РґРѕСЃС‚СѓРїРЅС‹ С‚РѕР»СЊРєРѕ VLESS Рё Hysteria2." ;;
    *) echo "  РџР°РЅРµР»СЊ РЅРµ СЂР°СЃРїРѕР·РЅР°РЅР° вЂ” РґРѕСЃС‚СѓРїРЅС‹ С‚РѕР»СЊРєРѕ Р±Р°Р·РѕРІС‹Рµ РїСЂРѕС‚РѕРєРѕР»С‹ VLESS Рё Hysteria2." ;;
  esac
  if [[ "$flavor" != "lucx" ]]; then
    warn "РџР°РЅРµР»СЊ: ${flavor:-РЅРµРёР·РІРµСЃС‚РЅРѕ} вЂ” РїРѕРєР°Р·С‹РІР°СЋ С‚РѕР»СЊРєРѕ С‚Рѕ, С‡С‚Рѕ РѕРЅР° СѓРјРµРµС‚ Р·Р°РїСѓСЃРєР°С‚СЊ."
    [[ "$flavor" == "3x-ui" ]] && warn "QWDTT/CSQTT/tproxy/naive/anytls/trusttunnel вЂ” РґРѕСЃС‚СѓРїРЅС‹ С‚РѕР»СЊРєРѕ РІ LucX UI: Рї.7 в†’ В«РњРёРіСЂРёСЂРѕРІР°С‚СЊ 3x-ui в†’ LucX UIВ»."
  fi
  local i=1 entry name proto
  local -a NAMES=()
  for entry in "${RECOMMENDED_INBOUNDS[@]}"; do
    IFS='|' read -r _ proto _ <<<"$entry"
    [[ "$flavor" != "lucx" && "$proto" != "vless" && "$proto" != "hysteria" ]] && continue
    name="${entry%%|*}"
    printf "  %2d) %s\n" "$i" "$name"
    NAMES+=("$entry")
    i=$((i+1))
  done
  if [[ ${#NAMES[@]} -eq 0 ]]; then
    err "Р”Р»СЏ РїР°РЅРµР»Рё ${flavor:-РЅРµРёР·РІРµСЃС‚РЅРѕ} РґРѕСЃС‚СѓРїРЅС‹С… РїСЂРѕС‚РѕРєРѕР»РѕРІ РЅРµС‚ вЂ” РѕС‚РєСЂРѕР№ Рї.7 Рё РїСЂРѕРІРµСЂСЊ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅСѓСЋ РїР°РЅРµР»СЊ."
    return 1
  fi
  echo
  echo "  0) РћС‚РјРµРЅР°"
  echo
  if [[ "$flavor" == "lucx" ]]; then
    echo "РџСЂРёРјРµСЂ: 1 2    (VLESS TCP Reality, VLESS XHTTP Reality)"
  else
    echo "РџСЂРёРјРµСЂ: 1 2    (РёР· РїРѕРєР°Р·Р°РЅРЅС‹С… РїСЂРѕС‚РѕРєРѕР»РѕРІ VLESS РёР»Рё Hysteria2)"
  fi
  echo

  local choices=""
  ask choices "РќРѕРјРµСЂР° (С‡РµСЂРµР· РїСЂРѕР±РµР»)" "" '^[0-9 ]+$'
  [[ "$choices" == "0" || -z "$choices" ]] && return 0

  sni_stale_purge_quiet    # РёРЅР±Р°СѓРЅРґ РјРѕРіР»Рё СѓРґР°Р»РёС‚СЊ РІ РїР°РЅРµР»Рё вЂ” РµРіРѕ SNI-Р·Р°РїРёСЃСЊ РјРµС€Р°РµС‚
  sni_used_load            # Р·Р°РЅСЏС‚С‹Рµ SNI-РґРѕРјРµРЅС‹: РґР»СЏ РїСЂРѕРІРµСЂРєРё Р”Рћ СЃРѕР·РґР°РЅРёСЏ РёРЅР±Р°СѓРЅРґР°
  local panel_domain=""
  local -a used_ports=()
  local num
  for num in $choices; do
    (( num < 1 || num > ${#NAMES[@]} )) && { warn "РџСЂРѕРїСѓСЃРє: $num"; continue; }
    local entry="${NAMES[$((num-1))]}"
    IFS='|' read -r name proto transport security flow net <<<"$entry"

    # Р¤РёРєСЃРёСЂРѕРІР°РЅРЅС‹Р№ РїСѓРЅРєС‚ CDN РІ СЂСѓС‡РЅРѕРј РјР°СЃС‚РµСЂРµ С‚РѕР¶Рµ РґРѕР»Р¶РµРЅ РїСЂРѕР№С‚Рё РїРѕР»РЅС‹Р№
    # CDN-РїСЂРѕС„РёР»СЊ. Р Р°РЅСЊС€Рµ create_inbounds_menu СЃРѕР·РґР°РІР°Р» С‚РѕР»СЊРєРѕ РіРѕР»С‹Р№ XHTTP,
    # РїРѕС‚РѕРјСѓ С‡С‚Рѕ CDN-Р»РѕРіРёРєР° Р±С‹Р»Р° СЂРµР°Р»РёР·РѕРІР°РЅР° Р»РёС€СЊ РІ auto_full_setup.
    local _is_cdn=false
    CDN_PRE_ANSWER=""; CDN_PRE_CDN=""; CDN_PRE_ORIGIN=""; CDN_PRE_PATH=""; CDN_PRE_TPL=""; CDN_PRE_PROVIDER=""
    if [[ "$name" == "VLESS XHTTP (С‡РµСЂРµР· CDN)" ]]; then
      _is_cdn=true
      cdn_ask_profile "0" "$proto"
      CDN_PRE_ANSWER="true"
      CDN_PRE_CDN="$CDN_DOM"; CDN_PRE_ORIGIN="$CDN_ORIGIN"; CDN_PRE_PATH="$CDN_PATH"; CDN_PRE_TPL="$CDN_TPL"; CDN_PRE_PROVIDER="$CDN_PROVIDER"
      security="none"
    fi

    local port
    case "$proto" in
      tproxy) port=11443 ;;
      qwdtt)  port=56000; while port_in_use "$port"; do port=$((port+100)); done ;;
      csqtt)  port=46000; while port_in_use "$port"; do port=$((port+100)); done ;;
      awg)    port=$(awg_port_next); [[ -z "$port" ]] && port=$(make_port) ;;
      *)      port=$(make_port) ;;
    esac
    local remark
    remark=$(inbound_remark_next "$proto" "$transport" "$security")

    # Р”РѕРјРµРЅ РїР°РЅРµР»Рё РґР»СЏ hosts-Р·Р°РїРёСЃРё вЂ” СЂРµР·РѕР»РІРёРј Р”Рћ СЃРѕР·РґР°РЅРёСЏ РґР»СЏ Р›Р®Р‘РћР“Рћ С‚РёРїР°
    # (РёРЅР°С‡Рµ reality/tproxy СѓС…РѕРґСЏС‚ СЃ Р°РґСЂРµСЃРѕРј-С„РѕР»Р±СЌРєРѕРј, РІРїР»РѕС‚СЊ РґРѕ IP СЃРµСЂРІРµСЂР°).
    if [[ -z "$panel_domain" ]]; then
      panel_domain="${PANEL_DOMAIN:-}"
      [[ -z "$panel_domain" ]] && panel_domain=$(xui_get subDomain 2>/dev/null || true)
      if [[ -z "$panel_domain" && -t 0 ]]; then
        ask panel_domain "Р”РѕРјРµРЅ РїР°РЅРµР»Рё (Р°РґСЂРµСЃ РґР»СЏ hosts-Р·Р°РїРёСЃРё РёРЅР±Р°СѓРЅРґР°)" "panel.example.com" '^[a-zA-Z0-9.-]+$'
      fi
      [[ -n "$panel_domain" ]] && SNI_USED["$panel_domain"]="${SNI_USED[$panel_domain]:-panel_backend}"
    fi

    # --- Reality: СЃРІРѕР№/С‡СѓР¶РѕР№ вЂ” С‚РѕС‚ Р¶Рµ РІРѕРїСЂРѕСЃ, С‡С‚Рѕ Рё РІ Р°РІС‚Рѕ-СѓСЃС‚Р°РЅРѕРІРєРµ ---
    local rmode=""
    if [[ "$security" == "reality" ]]; then
      echo
      echo "  $name:"
      echo "   1) Р§СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё В«РЅР°Р№С‚Рё С†РµР»РёВ» вЂ” Р·Р° 443 РїРѕ SNI С†РµР»Рё, СЃРµСЂС‚ РќР• РЅСѓР¶РµРЅ"
      echo "   2) РЎРІРѕР№ SNI-РґРѕРјРµРЅ вЂ” РЅСѓР¶РµРЅ СЃРµСЂС‚ + decoy"
      ask rmode "Р’С‹Р±РѕСЂ [1/2]" "1" '^[12]$'
    fi

    # --- SNI-РґРѕРјРµРЅ/С†РµР»СЊ СЃРїСЂР°С€РёРІР°РµРј Рё РїСЂРѕРІРµСЂСЏРµРј РЅР° Р·Р°РЅСЏС‚РѕСЃС‚СЊ Р”Рћ СЃРѕР·РґР°РЅРёСЏ ---
    # Р’РѕРїСЂРѕСЃС‹ РќР• Р·Р°РІРёСЃСЏС‚ РѕС‚ РЅР°Р»РёС‡РёСЏ SNI_CONF (СЃРѕР·РґР°С‘С‚СЃСЏ/РїСЂРёРІСЏР·С‹РІР°РµС‚СЃСЏ РїРѕР·Р¶Рµ).
    local sni_domain="" rdtpl=""
    if [[ "$proto" == "qwdtt" || "$proto" == "csqtt" ]]; then
      sni_domain=""   # С‡РёСЃС‚С‹Р№ UDP, SNI РЅРµ РЅСѓР¶РµРЅ
    elif [[ "$security" == "reality" && "$rmode" == "1" ]]; then
      # С‡СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё: Р¶РёРІР°СЏ РїСЂРѕРІРµСЂРєР° РєР°РЅРґРёРґР°С‚РѕРІ + РІС‹Р±РѕСЂ С†РµР»Рё (РєР°Рє РІ РїР°РЅРµР»Рё)
      local tgt=""
      reality_target_menu tgt "$name"
      REALITY_EXT_TARGET="$tgt"
      printf '%s' "$tgt" > /tmp/.reality-found-target 2>/dev/null || true
      log "  $name: С†РµР»СЊ в†’ $tgt (dest+serverNames, Р·Р° 443 РїРѕ SNI С†РµР»Рё)"
    elif [[ "$proto" == "hysteria" || "$proto" == "tproxy" || "$proto" == "naive" || "$proto" == "anytls" || "$proto" == "trusttunnel" || "$proto" == "trust-tunnel" || "$security" == "reality" || ( "$security" == "tls" && ( "$proto" == "trojan" || "$proto" == "vless" ) && ! ( "$proto" == "vless" && "$transport" == "xhttp" && "$name" == "VLESS XHTTP (С‡РµСЂРµР· CDN)" ) ) ]]; then
      echo
      if [[ -z "$panel_domain" ]]; then
        panel_domain="${PANEL_DOMAIN:-}"
        [[ -z "$panel_domain" ]] && panel_domain=$(xui_get subDomain)
        [[ -z "$panel_domain" ]] && ask panel_domain "Р”РѕРјРµРЅ РїР°РЅРµР»Рё" "panel.example.com" '^[a-zA-Z0-9.-]+$'
        [[ -n "$panel_domain" ]] && SNI_USED["$panel_domain"]="${SNI_USED[$panel_domain]:-panel_backend}"
      fi
      local def2="h.example.com"
      case "$proto" in
        trojan) def2="t.example.com";;
        vless)
          if [[ "$transport" == "xhttp" ]]; then def2="x.example.com"; else def2="r.example.com"; fi ;;
        naive) def2="n.example.com";;
        anytls) def2="at.example.com";;
        trusttunnel|trust-tunnel) def2="tt.example.com";;
        tproxy) def2="tg.example.com";;
      esac
      local d_new="" owner2="" __dom_tries=0
      while :; do
        d_new=""
        ask d_new "Р”РѕРјРµРЅ РґР»СЏ $name (РЅСѓР¶РµРЅ СЃРµСЂС‚РёС„РёРєР°С‚ + decoy)" "$def2" '^[a-zA-Z0-9.-]+$'
        # EOF/Р·Р°Р»РёРїС€РёР№ РґРµС„РѕР»С‚ РЅРµ РґРѕР»Р¶РµРЅ РєСЂСѓС‚РёС‚СЊ РїРµС‚Р»СЋ: 3 РЅРµСѓРґР°С‡Рё РїРѕРґСЂСЏРґ вЂ”
        # РёРЅР±Р°СѓРЅРґ РїСЂРѕРїСѓСЃРєР°РµС‚СЃСЏ (РІ РЅРµ-TTY РїРѕРІС‚РѕСЂ Р±РµСЃРїРѕР»РµР·РµРЅ: РІРµСЂРЅС‘С‚СЃСЏ С‚РѕС‚ Р¶Рµ
        # РґРµС„РѕР»С‚-РїР»РµР№СЃС…РѕР»РґРµСЂ, Рё В«С€Р°Р±Р»РѕРЅ-РїР»РµР№СЃС…РѕР»РґРµСЂ в†’ continueВ» РІРµС‡РµРЅ).
        __dom_tries=$((__dom_tries+1))
        [[ "$__dom_tries" -ge 3 ]] && { d_new=""; break; }
        [[ -z "$d_new" ]] && continue
        if [[ "$d_new" == *.example.com ]]; then
          err "Р­С‚Рѕ С€Р°Р±Р»РѕРЅ-РїР»РµР№СЃС…РѕР»РґРµСЂ. Р’РІРµРґРё РќРђРЎРўРћРЇР©РР™ РґРѕРјРµРЅ (РїРѕРґРґРѕРјРµРЅ СЃРІРѕРµРіРѕ base-РґРѕРјРµРЅР°)"
          continue
        fi
        owner2=$(sni_domain_owner "$d_new" "")
        if [[ -n "$owner2" ]]; then
          err "Р”РѕРјРµРЅ $d_new СѓР¶Рµ Р·Р°РЅСЏС‚ ($owner2). РЈРєР°Р¶РёС‚Рµ РґСЂСѓРіРѕР№ вЂ” РёРЅР±Р°СѓРЅРґ РµС‰С‘ РЅРµ СЃРѕР·РґР°РЅ."
          continue
        fi
        break
      done
      if [[ -z "$d_new" ]]; then
        warn "$name РїСЂРѕРїСѓС‰РµРЅ вЂ” РІР°Р»РёРґРЅС‹Р№ SNI-РґРѕРјРµРЅ РЅРµ Р·Р°РґР°РЅ (EOF/РѕС‚РєР°Р·)"
        continue
      fi
      sni_domain="$d_new"
      if [[ "$security" == "reality" && "$rmode" != "1" ]]; then
        # РЎРІРѕР№ SNI Сѓ Reality РёСЃРїРѕР»СЊР·СѓРµС‚ С‚РѕР»СЊРєРѕ РЅР°СЃС‚СЂРѕР№РєРё Reality.
        :
      elif ! cert_issue "$sni_domain"; then
        local keep=""
        askyn keep "РЎРµСЂС‚ $sni_domain РќР• РІС‹РїСѓС‰РµРЅ (DNS/ACME). РЎРѕР·РґР°С‚СЊ РёРЅР±Р°СѓРЅРґ РІСЃС‘ СЂР°РІРЅРѕ? РЎРµСЂС‚ РјРѕР¶РЅРѕ РґРѕР·Р°РїСѓСЃС‚РёС‚СЊ РїРѕР·Р¶Рµ (РЎРµСЂС‚РёС„РёРєР°С‚С‹ в†’ РѕР±РЅРѕРІРёС‚СЊ)." "n"
        [[ "$keep" != true ]] && { warn "$name РїСЂРѕРїСѓС‰РµРЅ"; continue; }
        warn "$name СЃРѕР·РґР°С‘С‚СЃСЏ Р‘Р•Р— СЃРµСЂС‚РёС„РёРєР°С‚Р° вЂ” СЂР°Р±РѕС‚Р°С‚СЊ РЅР°С‡РЅС‘С‚ РїРѕСЃР»Рµ РІС‹РїСѓСЃРєР° СЃРµСЂС‚Р°"
      fi
    fi
    # (РїСЂРѕС‚РѕРєРѕР»С‹ Р±РµР· SNI вЂ” РЅР°РїСЂРёРјРµСЂ wireguard вЂ” СЃРѕР·РґР°СЋС‚СЃСЏ РєР°Рє РµСЃС‚СЊ)

    # --- РџРѕСЂС‚: Р·Р°РїСЂРµС‚ 443/80 + Р·Р°РЅСЏС‚РѕСЃС‚СЊ (РєР°Рє РІ Р°РІС‚Рѕ-СѓСЃС‚Р°РЅРѕРІРєРµ) ---
    local port_ok=false __port_tries=0
    while [[ "$port_ok" != true ]]; do
      # 3 РЅРµСѓРґР°С‡Рё РїРѕРґСЂСЏРґ (EOF/Ctrl+D РІРѕР·РІСЂР°С‰Р°РµС‚ С‚РѕС‚ Р¶Рµ РґРµС„РѕР»С‚) в†’ РІС‹С…РѕРґРёРј,
      # РёРЅР±Р°СѓРЅРґ Р±СѓРґРµС‚ РїСЂРѕРїСѓС‰РµРЅ РЅРёР¶Рµ вЂ” РїРµС‚Р»СЏ РЅРµРІРѕР·РјРѕР¶РЅР°.
      __port_tries=$((__port_tries+1))
      [[ "$__port_tries" -ge 3 ]] && break
      ask port "РџРѕСЂС‚ РґР»СЏ $name (Enter вЂ” $port)" "$port" '^[0-9]{2,5}$'
      if [[ "$port" == "443" ]]; then

        err "РџРѕСЂС‚ 443 Р·Р°РїСЂРµС‰С‘РЅ РґР»СЏ inbound вЂ” СЌС‚Рѕ С‚РѕР»СЊРєРѕ РІРЅРµС€РЅРёР№ SNI/nginx-РїРѕСЂС‚"

        continue

      fi

      if [[ "$port" == "80" ]]; then

        err "РџРѕСЂС‚ 80 Р·Р°РЅСЏС‚ ACME/nginx вЂ” РІС‹Р±РµСЂРё РґСЂСѓРіРѕР№"
        continue
      fi
      if [[ " ${used_ports[*]:-} " == *" $port "* ]]; then
        err "РџРѕСЂС‚ $port СѓР¶Рµ РЅР°Р·РЅР°С‡РµРЅ РґСЂСѓРіРѕРјСѓ РёРЅР±Р°СѓРЅРґСѓ РІ СЌС‚РѕР№ СѓСЃС‚Р°РЅРѕРІРєРµ"
        continue
      fi
      if [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && \
         [[ "$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE port=$port;" 2>/dev/null || echo 0)" != "0" ]]; then
        err "РџРѕСЂС‚ $port СѓР¶Рµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РёРЅР±Р°СѓРЅРґРѕРј РІ РїР°РЅРµР»Рё вЂ” РІС‹Р±РµСЂРё РґСЂСѓРіРѕР№"
        continue
      fi
      port_ok=true
    done
    if [[ "$port_ok" != true ]]; then
      warn "$name РїСЂРѕРїСѓС‰РµРЅ вЂ” РІР°Р»РёРґРЅС‹Р№ РїРѕСЂС‚ РЅРµ РїРѕРґРѕР±СЂР°РЅ (EOF/РѕС‚РєР°Р·)"
      continue
    fi
    used_ports+=("$port")

    echo
    # РљР»РёРµРЅС‚РѕРІ РќР• СЃРѕР·РґР°С‘Рј (РїРѕ СЂРµС€РµРЅРёСЋ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ) вЂ” РґРѕР±Р°РІР»СЏР№ СЃР°Рј РІ РїР°РЅРµР»Рё.
    # VK call hashes вЂ” С‚РѕР»СЊРєРѕ РґР»СЏ qwdtt/csqtt; РїСѓСЃС‚Рѕ в†’ РїРѕР»Рµ РѕСЃС‚Р°С‘С‚СЃСЏ РїСѓСЃС‚С‹Рј
    local vk=""
    if [[ "$proto" == "qwdtt" || "$proto" == "csqtt" ]]; then
      ask vk "VK call hashes (С‡РµСЂРµР· Р·Р°РїСЏС‚СѓСЋ, Р‘Р•Р— РїСЂРѕР±РµР»РѕРІ; Enter вЂ” РїСЂРѕРїСѓСЃС‚РёС‚СЊ)" "" '^[a-zA-Z0-9,_-]*$'
    fi
    log "РЎРѕР·РґР°СЋ: $name (proto=$proto, transport=$transport, sec=$security, port=$port, РєР»РёРµРЅС‚РѕРІ: 0)"
    local new_id
    new_id=$(create_inbound_db "$proto" "$transport" "$security" "$flow" "$port" "$remark" "$net" "$sni_domain" "$vk") || continue
    if [[ -n "$new_id" ]]; then
      case "$proto" in
        qwdtt|csqtt)
          log "  в†’ id=$new_id (UDP $port). РљР»РёРµРЅС‚С‹ РґРѕР±Р°РІР»СЏР№С‚Рµ РІ РїР°РЅРµР»Рё: РёРЅР±Р°СѓРЅРґ в†’ РєР»РёРµРЅС‚ (СЃРёРЅРє РЅР°СЃС‚СЂРѕРµРЅ)"
          ufwd_allow_udp 56000 56001 56003 46000
          ;;
        awg)
          # AmneziaWG (LucX sidecar): РїР°РЅРµР»СЊ СЃР°РјР° РЅР°РїРёС€РµС‚ /etc/amnezia/amneziawg/
          # awg<id>.conf Рё РїРѕРґРЅРёРјРµС‚ kernel-РёРЅС‚РµСЂС„РµР№СЃ РїСЂРё СЂРµСЃС‚Р°СЂС‚Рµ x-ui.
          log "  в†’ id=$new_id (UDP $port, AWG $([[ "$transport" == awg31 ]] && echo 3.1 || echo 2.0), Premium-РїСЂРѕС„РёР»СЊ)"
          fw_allow "$port" udp "AmneziaWG awg${new_id}"
          systemctl restart x-ui >/dev/null 2>&1 || true
          sleep 3
          if ip link show "awg${new_id}" >/dev/null 2>&1; then
            log "  в†’ РёРЅС‚РµСЂС„РµР№СЃ awg${new_id} РїРѕРґРЅСЏС‚, РєР»РёРµРЅС‚С‹: РїР°РЅРµР»СЊ в†’ РёРЅР±Р°СѓРЅРґ в†’ В«РЎРіРµРЅРµСЂРёСЂРѕРІР°С‚СЊВ»"
          else
            warn "  РёРЅС‚РµСЂС„РµР№СЃ awg${new_id} РµС‰С‘ РЅРµ РїРѕРґРЅСЏР»СЃСЏ вЂ” СЃРјРѕС‚СЂРё Р¶СѓСЂРЅР°Р» РїР°РЅРµР»Рё (РґРѕ 30 СЃ)"
          fi
          ;;
        hysteria)
          log "  в†’ id=$new_id (UDP $port, SNI $sni_domain)"
          SNI_USED["$sni_domain"]="hysteria_${new_id}_web"
          ufwd_allow_udp "$port"
          # UDP Hysteria РЅРµ РјРѕР¶РµС‚ РѕР±СЃР»СѓР¶РёС‚СЊ Р±СЂР°СѓР·РµСЂРЅС‹Р№ TCP/443. РЎРѕР·РґР°С‘Рј
          # РѕС‚РґРµР»СЊРЅС‹Р№ Р»РѕРєР°Р»СЊРЅС‹Р№ HTTPS-decoy СЃ С‚РµРј Р¶Рµ РґРѕРјРµРЅРѕРј Рё РјР°СЂС€СЂСѓС‚РѕРј SNI.
          local hdecoy_port=$((47000 + new_id)) hcp hcert hkey
          while ss -tlnH "sport = :$hdecoy_port" 2>/dev/null | grep -q .; do hdecoy_port=$((hdecoy_port+1)); done
          hcp=$(cert_paths "$sni_domain" 2>/dev/null || true)
          hcert="${hcp%% *}"; hkey="${hcp##* }"
          if [[ -n "$hcert" && -f "$hcert" && -f "$hkey" ]]; then
            local htpl=""
            decoy_template_choose_impl htpl "Decoy РґР»СЏ Hysteria #$new_id ($sni_domain)" "$(decoy_tpl_current "$sni_domain")"
            htpl="${htpl:-$(decoy_tpl_for "$sni_domain")}"
            decoy_tpl_store_set "$sni_domain" "$htpl" >/dev/null 2>&1 || true
            mk_decoy "$hdecoy_port" "$sni_domain" "$hcert" "$hkey" "/var/www/decoy-hysteria-$new_id" "$htpl"
            sni_upstream_add "hysteria_${new_id}_web" "$hdecoy_port"
            sni_map_add "$sni_domain" "hysteria_${new_id}_web"
            nginx_reload || true
            log "  в†’ TCP/443 РґР»СЏ $sni_domain РІРµРґС‘С‚ РІ 404-decoy (UDP Hysteria РЅРµ РёР·РјРµРЅС‘РЅ)"
          else
            warn "  РЎРµСЂС‚РёС„РёРєР°С‚ $sni_domain РЅРµ РЅР°Р№РґРµРЅ вЂ” TCP-decoy РЅРµ СЃРѕР·РґР°РЅ"
          fi
          ;;
        naive|anytls|trusttunnel|trust-tunnel)
          log "  в†’ id=$new_id (РїР°РЅРµР»СЊ Р·Р°РїСѓСЃС‚РёС‚ СЃРµСЂРІРёСЃ РЅР° 127.0.0.1:$port; СЃРЅР°СЂСѓР¶Рё https://$sni_domain:443)"
          sni_upstream_add "inb_${new_id}_backend" "$port"
          sni_map_add "$sni_domain" "inb_${new_id}_backend"
          SNI_USED["$sni_domain"]="inb_${new_id}_backend"
          hosts_upsert "$new_id" "${panel_domain:-$sni_domain}" "$sni_domain"   # Р°РґСЂРµСЃ=РїР°РЅРµР»СЊ, SNI=СЃРІРѕР№ РґРѕРјРµРЅ
          nginx_reload || true
          log "  Р›РѕРіРёРЅС‹/РїР°СЂРѕР»Рё: /root/.lucx-$proto-info (+ РІ РїР°РЅРµР»Рё Сѓ РёРЅР±Р°СѓРЅРґР°)"
          systemctl restart x-ui >/dev/null 2>&1 || true
          ;;
        tproxy)
          log "  в†’ id=$new_id (SNI $sni_domain в†’ 127.0.0.1:11443)"
          sni_upstream_add "tproxy" 11443
          sni_map_add "$sni_domain" "tproxy"
          SNI_USED["$sni_domain"]="tproxy"
          hosts_upsert "$new_id" "${panel_domain:-$sni_domain}" "$sni_domain"   # Р°РґСЂРµСЃ=РїР°РЅРµР»СЊ, SNI=tg-РґРѕРјРµРЅ
          nginx_reload || true
          log "  РЎРµРєСЂРµС‚ СЃРѕС…СЂР°РЅС‘РЅ: /root/.lucx-tg-web-proxy-info"
          ;;
        *)
           if [[ "${_is_cdn:-false}" == true ]]; then
             CDN_FORCE_IDS="${CDN_FORCE_IDS:-} $new_id"
             xhttp_cdn_setup "$new_id" "$proto" "$port" || warn "  CDN-РїСЂРѕС„РёР»СЊ РґР»СЏ #$new_id РЅРµ РїСЂРёРјРµРЅС‘РЅ"
           fi
          log "  в†’ id=$new_id, listen=$([[ "$net" == "udp" ]] && echo "0.0.0.0" || echo "127.0.0.1")"
          if [[ -n "$sni_domain" ]]; then
            SNI_USED["$sni_domain"]="inb_${new_id}_backend"
            configure_sni_for_inbound "$new_id" "$proto" "$port" "$panel_domain" "$sni_domain" "${rdtpl:-default}"
          elif [[ "$security" == "reality" ]]; then
            # РґРѕРєС‚СЂРёРЅР° В«РІСЃС‘ Р·Р° 443В»: С‡СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё РїСЂСЏС‡РµРј РїРѕ SNI С†РµР»Рё
            local ext_dom="${REALITY_EXT_TARGET:-$(reality_find_target "$new_id")}"
            reality_ext_hide "$new_id" "$ext_dom" "$port" || true
            systemctl restart x-ui >/dev/null 2>&1 || true
          fi
          ;;
      esac
    fi
  done

  # РџРµСЂРµР·Р°РїСѓСЃРєР°РµРј x-ui, С‡С‚РѕР±С‹ РїР°РЅРµР»СЊ СѓРІРёРґРµР»Р° РЅРѕРІС‹Рµ РёРЅР±Р°СѓРЅРґС‹
  systemctl restart x-ui >/dev/null 2>&1 || true
  sleep 2


  local final
  final=$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE enable=1;" 2>/dev/null || echo 0)
  log "РС‚РѕРіРѕ Р°РєС‚РёРІРЅС‹С… РёРЅР±Р°СѓРЅРґРѕРІ: $final"
  return 0
}

# =====================================================================
# =====================================================================
# AMNEZIAWG (LucX sidecar): РёРЅР±Р°СѓРЅРґС‹ РїСЂРѕС‚РѕРєРѕР»Р° 'awg' РІ РїР°РЅРµР»Рё.
# РџР°РЅРµР»СЊ LucX СЃР°РјР° РїРёС€РµС‚ /etc/amnezia/amneziawg/awg<id>.conf Рё РїРѕРґРЅРёРјР°РµС‚
# kernel-РёРЅС‚РµСЂС„РµР№СЃ (РјРѕРґСѓР»СЊ amneziawg 3.x) РїСЂРё СЂРµСЃС‚Р°СЂС‚Рµ. РЎРєСЂРёРїС‚ С‚РѕР»СЊРєРѕ
# СЃРѕР·РґР°С‘С‚ РёРЅР±Р°СѓРЅРґ РІ Р‘Р” СЃ РєРѕСЂСЂРµРєС‚РЅС‹Рј settings-JSON вЂ” В«РєРЅРѕРїРєР° РЎРіРµРЅРµСЂРёСЂРѕРІР°С‚СЊВ».
# Р”РІРµ РІРµСЂСЃРёРё (РїСЂРѕС„РёР»СЊ РѕР±С„СѓСЃРєР°С†РёРё Amnezia Premium, obfLevel=4, mimicry tls):
#   3.1 вЂ” header protection + content padding + С‚Р°Р№РјРµСЂС‹-РґРёР°РїР°Р·РѕРЅС‹, H1-H4 РЅРµ
#         РёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ (Р·Р°РіР»СѓС€РєРё 1..4), I1-РјР°СЃРєРёСЂРѕРІРєР° РїРѕРґ TLS ClientHello;
#   2.0 вЂ” H1-H4 РєР°Рє Р”РРђРџРђР—РћРќР«, S1-S4, I1; Р±РµР· header protection.
# I1-С€Р°Р±Р»РѕРЅС‹ РІР·СЏС‚С‹ РёР· СЂРµР°Р»СЊРЅС‹С… РёРЅР±Р°СѓРЅРґРѕРІ LucX (СЂРµРіРёРѕРЅ ru, browser chrome).
# =====================================================================

# Р“РµРЅРµСЂР°С‚РѕСЂ РєР»СЋС‡РµР№ AWG: <privateKey>|<publicKey>
awg_keypair() {
  local priv="" pub=""
  if command -v awg >/dev/null 2>&1; then
    priv=$(awg genkey 2>/dev/null) || true
    [[ -n "$priv" ]] && pub=$(printf '%s' "$priv" | awg pubkey 2>/dev/null) || true
  fi
  if [[ -z "$priv" || -z "$pub" ]]; then
    # fallback: С‡РёСЃС‚С‹Р№ wireguard-toolset С„РѕСЂРјР°С‚ (base64 32 Р±Р°Р№С‚Р°)
    priv=$(openssl rand -base64 32 2>/dev/null) || true
    pub=""
  fi
  [[ -z "$priv" ]] && { err "awg genkey РЅРµРґРѕСЃС‚СѓРїРµРЅ (РЅСѓР¶РµРЅ РїР°РєРµС‚ amneziawg-tools)"; return 1; }
  echo "${priv}|${pub}"
  return 0
}

# РЎР»СѓС‡Р°Р№РЅС‹Р№ РґРёР°РїР°Р·РѕРЅ "a-b" (РґР»СЏ H1-H4 2.0 Рё С‚Р°Р№РјРµСЂРѕРІ 3.1)
__awg_range() {   # <start_min> <start_max> <width_min> <width_max>
  local a=$(( (RANDOM % ($2 - $1 + 1)) + $1 ))
  local w=$(( (RANDOM % ($4 - $3 + 1)) + $3 ))
  echo "$a-$(( a + w ))"
}

# РЎР»РµРґСѓСЋС‰Р°СЏ СЃРІРѕР±РѕРґРЅР°СЏ РїРѕРґСЃРµС‚СЊ 10.2XX.0.1/24 (XX: 200..249) РїРѕ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёРј awg
awg_subnet_next() {
  local used="" a
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    while IFS= read -r a; do
      [[ "$a" =~ ^10\.([0-9]+)\.0\. ]] && used+=" ${BASH_REMATCH[1]} "
    done < <(sqlite3 -noheader "$XUI_DB" \
      "SELECT COALESCE(json_extract(settings,'\$.address'),'') FROM inbounds WHERE protocol='awg';" 2>/dev/null || true)
  fi
  local n
  for n in $(seq 200 249); do
    [[ " $used " != *" $n "* ]] && { echo "$n"; return 0; }
  done
  err "РџРѕРґСЃРµС‚Рё 10.200-10.249 РёСЃС‡РµСЂРїР°РЅС‹"
  return 1
}

# РЎРІРѕР±РѕРґРЅС‹Р№ UDP-РїРѕСЂС‚ РїРѕРґ AWG (20000-59999, РІРЅРµ Р‘Р” Рё СЃРѕРєРµС‚РѕРІ)
awg_port_next() {
  local p tries=0 in_db
  while (( tries < 40 )); do
    p=$(( (RANDOM % 40000) + 20000 ))
    in_db=0
    [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && \
      in_db=$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE port=$p;" 2>/dev/null || echo 1)
    if ! port_in_use "$p" && [[ "$in_db" == "0" ]]; then
      echo "$p"; return 0
    fi
    tries=$((tries+1))
  done
  echo ""
  return 1
}

# I1-РјР°СЃРєРёСЂРѕРІРѕС‡РЅС‹Р№ РїР°РєРµС‚: С€Р°Р±Р»РѕРЅ TLS ClientHello (Р»РµРіРёС‚РёРјРЅС‹Р№ SNI РІРЅСѓС‚СЂРё).
#   3.1 в†’ ozon-РїСЂРѕС„РёР»СЊ (РєР°Рє РІ РїР°РЅРµР»Рё LucX), 2.0 в†’ facebook-РїСЂРѕС„РёР»СЊ
awg_i1_for() {   # <31|20>
  case "$1" in
    31)
      echo '<b 0x1603010137010001330303><r 32><b 0x20><r 32><b >'
      ;;
    20)
      echo '<b 0x160301014b010001470303><r 32><b 0x20><r 32><b >'
      ;;
  esac
}

# settings-JSON РёРЅР±Р°СѓРЅРґР° awg. $1 = 31|20, $2 = UDP-РїРѕСЂС‚
awg_settings_json() {   # <31|20> <port>
  local ver="$1" port="$2"
  [[ "$ver" != "31" && "$ver" != "20" ]] && { err "AWG РІРµСЂСЃРёСЏ: 31 РёР»Рё 20"; return 1; }
  local kp priv pub
  kp=$(awg_keypair) || return 1
  priv="${kp%%|*}"; pub="${kp##*|}"
  [[ -z "$pub" ]] && { err "РЅРµ СѓРґР°Р»РѕСЃСЊ РїРѕР»СѓС‡РёС‚СЊ publicKey"; return 1; }

  local subnet; subnet=$(awg_subnet_next) || return 1
  # РџСЂРѕС„РёР»СЊ РѕР±С„СѓСЃРєР°С†РёРё Amnezia Premium (obfLevel=4): Р·РЅР°С‡РµРЅРёСЏ РєР°Рє РІ РїР°РЅРµР»Рё LucX
  local jc=5 jmin=10 jmax=80 s1=164 s2=528 s3=389 s4=12
  local i1; i1=$(awg_i1_for "$ver")
  local hpk="" h1 h2 h3 h4 cpa rkt rat kat mha rt dc
  if [[ "$ver" == "31" ]]; then
    hpk=$(awg genkey 2>/dev/null || openssl rand -base64 32)
    h1=1; h2=2; h3=3; h4=4                       # Р·Р°РіР»СѓС€РєРё: Р·Р°РіРѕР»РѕРІРєРё Р·Р°РєСЂС‹С‚С‹ HPK
    cpa="10-100"                                 # РєР°Рє РІ РїСЂРѕС„РёР»Рµ РїР°РЅРµР»Рё LucX
    rat="100-120"; rkt="4-8"; kat="7-13"; mha="13-15"
    rt="true"; dc="true"
  else
    h1=$(__awg_range 20000 60000 40000 90000)
    h2=$(__awg_range 100000 160000 40000 90000)
    h3=$(__awg_range 200000 260000 40000 90000)
    h4=$(__awg_range 300000 360000 40000 90000)
    cpa="0"; rat="0"; rkt="0"; kat="0"; mha="0"
    rt="false"; dc="false"
  fi
  # Р’РђР–РќРћ: json-СЃС‚СЂРѕРєРё Р±РµР· РїРµСЂРµРЅРѕСЃРѕРІ; I1 СѓР¶Рµ РѕРґРЅРѕСЃС‚СЂРѕС‡РЅС‹Р№
  cat <<EOF
{"privateKey":"$priv","publicKey":"$pub","address":"10.$subnet.0.1/24","mtu":1420,"dns":"1.1.1.1, 1.0.0.1","obfLevel":4,"mimicryProfile":"tls","browserProfile":"chrome","region":"ru","jc":$jc,"jmin":$jmin,"jmax":$jmax,"s1":$s1,"s2":$s2,"s3":$s3,"s4":$s4,"h1":"$h1","h2":"$h2","h3":"$h3","h4":"$h4","i1":"$i1","i2":"","i3":"","i4":"","i5":"","headerProtectionKey":"$hpk","contentPaddingAddition":"$cpa","rekeyAfterTime":"$rat","rekeyTimeout":"$rkt","rejectAfterTime":"$rat","keepaliveTimeout":"$kat","maxHandshakeAttempts":"$mha","randomTrailers":$rt,"disableCookies":$dc,"awgVersion":"$([[ "$ver" == 31 ]] && echo 3.1 || echo 2)","clients":[],"routeThroughXray":true,"xrayRoutingMode":"tun","tproxyPort":51453,"outboundTag":"","p2p":false}
EOF
  return 0
}

# РЎРїРёСЃРѕРє AWG-РёРЅР±Р°СѓРЅРґРѕРІ РїР°РЅРµР»Рё: id|РїРѕСЂС‚|РІРµСЂСЃРёСЏ|Р°РґСЂРµСЃ
awg_inbounds_list() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  sqlite3 -separator '|' "$XUI_DB" \
    "SELECT id, port, COALESCE(json_extract(settings,'\$.awgVersion'),'?'), COALESCE(json_extract(settings,'\$.address'),'') FROM inbounds WHERE protocol='awg' AND enable=1 ORDER BY id;" 2>/dev/null || true
}

# __awg_ufw_has <РїРѕСЂС‚> в†’ 0, РµСЃР»Рё РїСЂР°РІРёР»Рѕ UDP РµСЃС‚СЊ (Рё UFW Р°РєС‚РёРІРµРЅ); 1 вЂ” РЅРµС‚/РІС‹РєР»СЋС‡РµРЅ
__awg_ufw_has() {
  command -v ufw >/dev/null 2>&1 || return 1
  ufw status 2>/dev/null | grep -q "Status: active" || return 1
  ufw status 2>/dev/null | awk -v p="$1" \
    '$0 ~ ("(^|[[:space:]])" p "/udp([[:space:]]|$)") || $0 ~ ("(^|[[:space:]])" p "([[:space:]]|$)") {found=1} END{exit !found}'
}

# РЎРµРєС†РёСЏ Р°СѓРґРёС‚Р° РґР»СЏ stack_full_audit (Рї.4). Р§РёСЃР»Рѕ РїСЂРѕР±Р»РµРј вЂ” РІ $AWG_AUDIT_ISSUES.
awg_audit() {
  AWG_AUDIT_ISSUES=0
  local row id port ver addr n=0 cfg ifc
  while IFS='|' read -r id port ver addr; do
    [[ -z "$id" ]] && continue
    n=$((n+1))
    cfg="РЅРµС‚"; [[ -f "/etc/amnezia/amneziawg/awg${id}.conf" ]] && cfg="РґР°"
    ifc="РЅРµС‚"; ip link show "awg${id}" >/dev/null 2>&1 && ifc="РґР°"
    local msg="  #$id AWG v$ver UDP/$port $addr вЂ” РєРѕРЅС„РёРі: $cfg, РёРЅС‚РµСЂС„РµР№СЃ: $ifc"
    if [[ "$cfg" == "РЅРµС‚" || "$ifc" == "РЅРµС‚" ]]; then
      warn "$msg"; AWG_AUDIT_ISSUES=$((AWG_AUDIT_ISSUES+1))
    else
      log "$msg"
    fi
    if __awg_ufw_has "$port"; then
      log "  #$id: UFW UDP/$port вЂ” РµСЃС‚СЊ"
    elif command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
      warn "  #$id: UFW UDP/$port вЂ” РїСЂР°РІРёР»Р° РЅРµС‚"; AWG_AUDIT_ISSUES=$((AWG_AUDIT_ISSUES+1))
    fi   # UFW РІС‹РєР»СЋС‡РµРЅ вЂ” РЅРµ Р·Р°РјРµС‡Р°РЅРёРµ
  done < <(awg_inbounds_list)
  (( n == 0 )) && echo "  (AWG-РёРЅР±Р°СѓРЅРґРѕРІ РЅРµС‚)"
  return 0
}

# РџРѕС‡РёРЅРєР° AWG РґР»СЏ Рї.6.1: РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РёРµ UFW-РїСЂР°РІРёР»Р° + РЅРµ РїРѕРґРЅСЏС‚С‹Рµ РёРЅС‚РµСЂС„РµР№СЃС‹.
# РљРѕРЅС„РёРіРё awg<id>.conf РќР• РїРёС€РµРј вЂ” РёС… РіРµРЅРµСЂРёСЂСѓРµС‚ РїР°РЅРµР»СЊ; РµСЃР»Рё РёРЅС‚РµСЂС„РµР№СЃРѕРІ РЅРµС‚,
# СЂРµСЃС‚Р°СЂС‚ x-ui Р·Р°СЃС‚Р°РІР»СЏРµС‚ РїР°РЅРµР»СЊ РїРµСЂРµСЃРѕР·РґР°С‚СЊ РёС… РёР· Р‘Р”.
awg_repair() {
  local any=0 missing=0 id port ver addr
  while IFS='|' read -r id port ver addr; do
    [[ -z "$id" ]] && continue
    any=$((any+1))
    ip link show "awg${id}" >/dev/null 2>&1 || missing=$((missing+1))
    if ! __awg_ufw_has "$port"; then
      fw_allow "$port" udp "AmneziaWG awg${id}"
      log "  AWG #$id: UDP/$port РѕС‚РєСЂС‹С‚ РІ UFW"
    fi
  done < <(awg_inbounds_list)
  (( any == 0 )) && return 0
  if (( missing > 0 )); then
    warn "  AWG: РёРЅС‚РµСЂС„РµР№СЃРѕРІ РЅРµС‚ Сѓ $missing РёР· $any вЂ” СЂРµСЃС‚Р°СЂС‚ x-ui (РїР°РЅРµР»СЊ РїРѕРґРЅРёРјР°РµС‚ РёС… СЃР°РјР°)"
    systemctl restart x-ui >/dev/null 2>&1 || true
    sleep 4
    local still=0
    while IFS='|' read -r id port ver addr; do
      [[ -z "$id" ]] && continue
      if ! ip link show "awg${id}" >/dev/null 2>&1; then
        still=$((still+1))
        warn "  AWG #$id: РёРЅС‚РµСЂС„РµР№СЃ awg${id} РЅРµ РїРѕРґРЅСЏР»СЃСЏ вЂ” journalctl -u x-ui | tail -30"
      fi
    done < <(awg_inbounds_list)
    (( still == 0 )) && log "  AWG: РІСЃРµ РёРЅС‚РµСЂС„РµР№СЃС‹ РїРѕРґРЅСЏС‚С‹"
  fi
  return 0
}

# DECOY: РЎРўРђРўРР§Р•РЎРљРР• РЁРђР‘Р›РћРќР«
# =====================================================================
# Р·Р°РїРёСЃР°С‚СЊ С€Р°Р±Р»РѕРЅ, С‚РѕР»СЊРєРѕ РµСЃР»Рё РµРіРѕ РµС‰С‘ РЅРµС‚ вЂ” РїРѕРІС‚РѕСЂРЅС‹Рµ Р·Р°РїСѓСЃРєРё РЅРёС‡РµРіРѕ РЅРµ РїРµСЂРµР·Р°РїРёСЃС‹РІР°СЋС‚
tpl_write() {
  [[ -s "$1" ]] && return 0
  cat > "$1"
}

decoy_templates_init() {
  mkdir -p "$DECOY_TPL_DIR" 2>/dev/null || true
  local sig_before; sig_before=$(dir_sig "$DECOY_TPL_DIR")

  # honeypot-СЃСЃС‹Р»РєРё: РЅРµРІРёРґРёРјС‹ РґР»СЏ С‡РµР»РѕРІРµРєР°, РЅРѕ РёС… РїР°СЂСЃСЏС‚ Р±РѕС‚С‹ в†’ РїСѓС‚СЊ /admin,
  # /wp-login.php, /.env в†’ nginx РѕС‚РґР°С‘С‚ 404 РІ Р»РѕРі decoy-access в†’ fail2ban Р±Р°РЅРёС‚
  local honey='<a href="/admin" style="position:fixed;left:-9999px;top:-9999px" aria-hidden="true" tabindex="-1">admin</a>
