# DECOY: LOGIN-РЁРђР‘Р›РћРќР«
# =====================================================================
decoy_login_templates_init() {
  mkdir -p "$DECOY_LOGIN_DIR" 2>/dev/null || true
  local sig_before; sig_before=$(dir_sig "$DECOY_LOGIN_DIR")
  # СЂРµРїР»РёРєРё 1:1 (РѕРєС‚ 2026): РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РќР• СЃРЅРѕСЃРёРј вЂ” С€Р°Р±Р»РѕРЅС‹ РїРёС€СѓС‚СЃСЏ РѕРґРёРЅ СЂР°Р·
  # (СЂР°РЅРґРѕРјРЅР°СЏ РІРµСЂСЃРёСЏ РІ С„СѓС‚РµСЂРµ С„РёРєСЃРёСЂСѓРµС‚СЃСЏ РїСЂРё СѓСЃС‚Р°РЅРѕРІРєРµ; РїРµСЂРµРіРµРЅРµСЂР°С†РёСЏ РїСЂРё
  # РєР°Р¶РґРѕРј СЃС‚Р°СЂС‚Рµ С‚РѕР»СЊРєРѕ РјРµРЅСЏР»Р° Р±Р»РѕР±С‹ Рё С€СѓРјРµР»Р° РІ Р»РѕРіРµ). РџСЂРёРЅСѓРґРёС‚РµР»СЊРЅРѕ
  # РѕР±РЅРѕРІРёС‚СЊ СЂРµРїР»РёРєРё РёР· СЃРєСЂРёРїС‚Р°: SMG_FORCE_TPL=1 bash stack-manager.sh
  if [[ "${SMG_FORCE_TPL:-0}" == "1" ]]; then
    rm -f "$DECOY_LOGIN_DIR/adguard.html" "$DECOY_LOGIN_DIR/portainer.html" \
          "$DECOY_LOGIN_DIR/pihole.html" "$DECOY_LOGIN_DIR/omv.html" \
