    cert="${line%% *}"; key="${line##* }"
    # Р’РђР–РќРћ: sidecar-РёРЅР±Р°СѓРЅРґС‹ (naive) Р±РµСЂСѓС‚ СЃРµСЂС‚ РёР· settings.certFile,
    # xray-РёРЅР±Р°СѓРЅРґС‹ (trusttunnel/anytls/hysteria) вЂ” РёР· stream_settings.
    # РџРёС€РµРј РћР‘Рђ РјРµСЃС‚Р°, РёРЅР°С‡Рµ x-ui РїСЂРѕРїСѓСЃРєР°РµС‚ РёРЅР±Р°СѓРЅРґ Рё РѕРЅ РЅРµ СЃР»СѓС€Р°РµС‚ РїРѕСЂС‚.
    python3 - "$XUI_DB" "$id" "$proto" "$dom" "$cert" "$key" "$SNI_CONF" <<'PY' && cnt=$((cnt+1))
import sqlite3, json, sys, re
db, i, proto, dom, cert, key, sni_conf = sys.argv[1], int(sys.argv[2]), sys.argv[3], sys.argv[4], sys.argv[5], sys.argv[6], sys.argv[7]
con = sqlite3.connect(db)
def one(sql, *a):
    return con.execute(sql, a).fetchone()
changed = False
if proto == "hysteria":
    st = json.loads((one("SELECT stream_settings FROM inbounds WHERE id=?", i)[0] or "{}"))
    st["network"] = st.get("network") or "udp"
    st["security"] = "tls"
    tls = st.get("tlsSettings") or {}
    tls["serverName"] = dom
    tls["certificates"] = [{"certificateFile": cert, "keyFile": key}]
    st["tlsSettings"] = tls
    con.execute("UPDATE inbounds SET stream_settings=? WHERE id=?", (json.dumps(st), i))
    changed = True
else:
    try:
        s = json.loads((one("SELECT settings FROM inbounds WHERE id=?", i)[0] or "{}"))
    except Exception:
        s = {}
    # Р‘Р•Р—РЈРЎР›РћР’РќРћ: РєР»СЋС‡Р° certFile РјРѕР¶РµС‚ РЅРµ Р±С‹С‚СЊ (РїР°РЅРµР»СЊ РїРµСЂРµРіРµРЅРµСЂРёР»Р° settings) вЂ”
    # СЃРѕР·РґР°С‘Рј. РРЅР°С‡Рµ СЃР°РјРѕР»РµС‡РµРЅРёРµ Р·Р°С†РёРєР»РёРІР°РµС‚СЃСЏ: sync В«РІРїРёСЃР°Р»В», РїСЂРѕРІРµСЂРєР° РЅРµ РІРёРґРёС‚.
    s["certFile"] = cert; s["keyFile"] = key
    con.execute("UPDATE inbounds SET settings=? WHERE id=?", (json.dumps(s), i))
    changed = True
    # Tunnel-РєР»Р°СЃСЃ LucX С‡РёС‚Р°РµС‚ РїРѕСЂС‚ РёР· settings.port; РµСЃР»Рё РїР°РЅРµР»СЊ РµРіРѕ РїРѕС‚РµСЂСЏР»Р° вЂ”
    # СЃРµСЂРІРёСЃ РЅРµ Р±РёРЅРґРёС‚СЃСЏ. Р’РѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј РёР· SNI-РјР°СЂС€СЂСѓС‚Р° (upstream inb_<id>_backend).
    if proto in ("naive", "naiveproxy", "anytls", "trusttunnel", "trust-tunnel", "tproxy") and not s.get("port"):
        try:
            m = re.search(r"inb_%d_backend\s*\{[^}]*?server[^\d]*127\.0\.0\.1:(\d+)" % i,
                          open(sni_conf, encoding="utf-8", errors="ignore").read(), re.S)
            if m:
                s["port"] = int(m.group(1))
                con.execute("UPDATE inbounds SET settings=? WHERE id=?", (json.dumps(s), i))
                print(f"  #{i} ({proto}): РїРѕСЂС‚ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ РёР· SNI-РјР°СЂС€СЂСѓС‚Р° в†’ {s['port']}")
        except Exception:
            pass
    if proto in ("anytls", "trusttunnel", "trust-tunnel", "vless"):
        st2 = json.loads((one("SELECT stream_settings FROM inbounds WHERE id=?", i)[0] or "{}"))
        if st2.get("security") not in (None, "", "tls"):
            pass   # reality Рё РїСЂРѕС‡РёРµ вЂ” stream РЅРµ С‚СЂРѕРіР°РµРј
        else:
            st2["network"] = "tcp"; st2["security"] = "tls"
            st2["tlsSettings"] = {"serverName": dom, "certificates": [{"certificateFile": cert, "keyFile": key}]}
            con.execute("UPDATE inbounds SET stream_settings=? WHERE id=?", (json.dumps(st2), i))
con.commit()
if changed:
    print(f"  #{i} ({proto}): cert РІРїРёСЃР°РЅ ({dom} в†’ {cert})")
    sys.exit(0)
print(f"  #{i} ({proto}): РџР Р•Р”РЈРџР Р•Р–Р”Р•РќРР•: СЃРµСЂС‚ РЅРёРєСѓРґР° РЅРµ РІРїРёСЃР°РЅ вЂ” СЃС‚СЂСѓРєС‚СѓСЂР° РЅРµ СЂР°СЃРїРѕР·РЅР°РЅР°")
sys.exit(4)
PY
  done < <(python3 - "$XUI_DB" <<'PYROWS' 2>/dev/null
import sqlite3, json, sys
try:
    con = sqlite3.connect(f"file:{sys.argv[1]}?mode=ro", uri=True, timeout=5)
    rows = con.execute("SELECT id, protocol, settings, stream_settings FROM inbounds WHERE enable=1 AND port>0").fetchall()
except Exception:
    sys.exit(0)
for iid, proto, setts_s, stream_s in rows:
    try:    se = json.loads(setts_s or "{}")
    except Exception: se = {}
    try:    st = json.loads(stream_s or "{}")
    except Exception: st = {}
    rs = st.get("realitySettings") or {}
    dom = se.get("domain") or se.get("hostname") or se.get("sni") \
          or (st.get("tlsSettings") or {}).get("serverName") \
          or (rs.get("serverNames") or [None])[0]
    dom = str(dom or "")   # None в†’ РїСѓСЃС‚Р°СЏ СЃС‚СЂРѕРєР° (bash-С„РёР»СЊС‚СЂ РµС‘ РѕС‚Р±СЂРѕСЃРёС‚)
    # json.dumps вЂ” РіР°СЂР°РЅС‚РёСЂРѕРІР°РЅРЅРѕ РћР”РќРђ СЃС‚СЂРѕРєР°, РєР°РєРёРјРё Р±С‹ РєСЂРёРІС‹РјРё РЅРё Р±С‹Р»Рё РґР°РЅРЅС‹Рµ РІ Р‘Р”
    print(f"{iid}\x1f{proto}\x1f{dom}\x1f{json.dumps(st, ensure_ascii=False)}")
PYROWS
  )
  # hosts РёР· С‚РµРЅРё РќР• РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј: СЃС‚СЂРѕРєРё hosts вЂ” РіРµРЅРµСЂР°С‚РѕСЂ СЃСЃС‹Р»РѕРє РїРѕРґРїРёСЃРѕРє
  # Рё РЅР° РјР°СЂС€СЂСѓС‚РёР·Р°С†РёСЋ РЅРµ РІР»РёСЏСЋС‚. РњРѕРґРµР»СЊ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ вЂ” В«РјРёРЅРёРјСѓРј hostsВ»:
  # РІСЂСѓС‡РЅСѓСЋ СѓРґР°Р»С‘РЅРЅС‹Рµ СЃС‚СЂРѕРєРё РЅРµ РІРѕСЃРєСЂРµСЃР°РµРј. Р—Р°С‰РёС‚Р° Р‘Р”/С‚СЂРёРіРіРµСЂС‹ РІС‹РІРµРґРµРЅС‹
  # РёР· Р°СЂС…РёС‚РµРєС‚СѓСЂС‹ вЂ” СЌС‚Р° СЃС‚СЂР°С…РѕРІРєР° Р±РѕР»СЊС€Рµ РЅРµ РЅСѓР¶РЅР°.
  if [[ $cnt -gt 0 ]]; then
    systemctl start x-ui 2>/dev/null || true
    sleep 3
    # decoy-Р±Р»РѕРєРё Рё/РёР»Рё SNI-РєР°СЂС‚Р° РјРѕРіР»Рё РёР·РјРµРЅРёС‚СЊСЃСЏ вЂ” nginx РѕР±СЏР·Р°РЅ РїРѕРґС…РІР°С‚РёС‚СЊ
    # РєРѕРЅС„РёРі, РёРЅР°С‡Рµ РµРіРѕ СЃР»СѓС€Р°С‚РµР»Рё СЂР°Р·РѕР№РґСѓС‚СЃСЏ СЃ stack.conf (Р·Р°РіР»СѓС€РєРё В«РїСЂРѕРїР°РґР°СЋС‚В»,
    # reality-dest СЃРјРѕС‚СЂРёС‚ РІ РјС‘СЂС‚РІС‹Р№ РїРѕСЂС‚).
    nginx_reload || true
    log "РЎРµСЂС‚С‹ РІРїРёСЃР°РЅС‹ РІ $cnt РёРЅР±Р°СѓРЅРґ(РѕРІ), x-ui Р·Р°РїСѓС‰РµРЅ"
  else
    systemctl start x-ui 2>/dev/null || true
  fi
  # РґРµРґСѓРїР»РёРєР°С†РёСЏ: СЃРµСЂС‚С‹ С‚РѕР»СЊРєРѕ РІ /etc/letsencrypt/live/, Р·РµСЂРєР°Р»Р° /root/cert РЅРµС‚
  cert_dedup_migrate
  db_protect_resume   # РїСЂР°РІРєРё Р·Р°РєРѕРЅС‡РµРЅС‹ вЂ” Р·Р°С‰РёС‚Р° Р‘Р” РІРѕР·РІСЂР°С‰Р°РµС‚СЃСЏ
  return 0
}

# --- Р”РµРґСѓРїР»РёРєР°С†РёСЏ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ: live/ вЂ” РµРґРёРЅСЃС‚РІРµРЅРЅРѕРµ РјРµСЃС‚Рѕ -------------------
# Р Р°Р·РѕРІРѕ РїРµСЂРµРїСЂРёРІСЏР·С‹РІР°РµС‚ Р’РЎР• СЃСЃС‹Р»РєРё РЅР° Р·РµСЂРєР°Р»Рѕ /root/cert/ РЅР°
# /etc/letsencrypt/live/ (Р‘Р” РїР°РЅРµР»Рё вЂ” СЃС‚СЂРѕРіРѕ РїСЂРё РѕСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕРј x-ui, РєРѕРЅС„РёРіРё
# nginx, yaml AdGuard) Рё СѓРґР°Р»СЏРµС‚ СЃР°РјСѓ РїР°РїРєСѓ-РґСѓР±Р»СЊ. РРґРµРјРїРѕС‚РµРЅС‚РЅРѕ: Р±РµР· СЃСЃС‹Р»РѕРє
# Рё РїР°РїРєРё РЅРёС‡РµРіРѕ РЅРµ РґРµР»Р°РµС‚ вЂ” Р±РµР·РѕРїР°СЃРЅРѕ Р·РІР°С‚СЊ РёР· С‚Р°Р№РјРµСЂР° СЃР°РјРѕР»РµС‡РµРЅРёСЏ.
cert_dedup_migrate() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  local refs=0
  refs=$(sqlite3 "$XUI_DB" "SELECT (SELECT COUNT(*) FROM settings WHERE value LIKE '/root/cert/%') + (SELECT COUNT(*) FROM inbounds WHERE settings LIKE '%/root/cert/%' OR stream_settings LIKE '%/root/cert/%');" 2>/dev/null || echo 0)
  if [[ "${refs:-0}" -gt 0 ]]; then
    systemctl stop x-ui 2>/dev/null || true
    python3 - "$XUI_DB" <<'PYDEDUP'
import sqlite3, sys
con = sqlite3.connect(sys.argv[1])
cur = con.cursor()
n = 0
for k, v in cur.execute("SELECT key, value FROM settings WHERE value LIKE '/root/cert/%'").fetchall():
    cur.execute("UPDATE settings SET value=? WHERE key=?", (v.replace('/root/cert/', '/etc/letsencrypt/live/'), k)); n += 1
for iid, s, st in cur.execute("SELECT id, settings, stream_settings FROM inbounds WHERE settings LIKE '%/root/cert/%' OR stream_settings LIKE '%/root/cert/%'").fetchall():
    cur.execute("UPDATE inbounds SET settings=?, stream_settings=? WHERE id=?",
                ((s or '').replace('/root/cert/', '/etc/letsencrypt/live/'),
                 (st or '').replace('/root/cert/', '/etc/letsencrypt/live/'), iid)); n += 1
con.commit()
print(f"  РґРµРґСѓРї: РІ Р‘Р” РїР°РЅРµР»Рё РїРµСЂРµРїСЂРёРІСЏР·Р°РЅРѕ СЃСЃС‹Р»РѕРє: {n}")
PYDEDUP
    systemctl start x-ui 2>/dev/null || true
  fi
  local nf
  nf=$(grep -rl '/root/cert/' /etc/nginx/ 2>/dev/null | head -5)
  if [[ -n "$nf" ]]; then
    grep -rl '/root/cert/' /etc/nginx/ 2>/dev/null | while read -r f; do
      sed -i 's|/root/cert/|/etc/letsencrypt/live/|g' "$f" 2>/dev/null || true
      log "  РґРµРґСѓРї: nginx-РєРѕРЅС„РёРі РїРµСЂРµРІРµРґС‘РЅ РЅР° live: $(basename "$f")"
    done
    nginx -t >/dev/null 2>&1 && nginx_reload || true
  fi
  if [[ -f /opt/AdGuardHome/AdGuardHome.yaml ]] && grep -q '/root/cert/' /opt/AdGuardHome/AdGuardHome.yaml 2>/dev/null; then
    sed -i 's|/root/cert/|/etc/letsencrypt/live/|g' /opt/AdGuardHome/AdGuardHome.yaml 2>/dev/null || true
    systemctl restart AdGuardHome 2>/dev/null || systemctl restart adguardhome 2>/dev/null || true
    log "  РґРµРґСѓРї: AdGuard РїРµСЂРµРІРµРґС‘РЅ РЅР° live Рё РїРµСЂРµР·Р°РїСѓС‰РµРЅ"
  fi
  # РќРµ СѓРґР°Р»СЏРµРј /root/cert: СЌС‚Рѕ РјРѕР¶РµС‚ Р±С‹С‚СЊ СЂР°Р±РѕС‡РµРµ С…СЂР°РЅРёР»РёС‰Рµ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ,
  # СЃРѕР·РґР°РЅРЅРѕРµ РїР°РЅРµР»СЊСЋ РёР»Рё Р°РґРјРёРЅРёСЃС‚СЂР°С‚РѕСЂРѕРј. РџРµСЂРµРїСЂРёРІСЏР·РєР° СЃСЃС‹Р»РѕРє РІС‹С€Рµ Р±РµР·РѕРїР°СЃРЅР°,
  # РЅРѕ СѓРЅРёС‡С‚РѕР¶РµРЅРёРµ РєР°С‚Р°Р»РѕРіР° РїСЂРё РѕС‚РєР°С‚Рµ/СЃР°РјРѕР»РµС‡РµРЅРёРё РЅРµРґРѕРїСѓСЃС‚РёРјРѕ.
  if [[ -d /root/cert ]]; then
    log "  РґРµРґСѓРї: /root/cert СЃРѕС…СЂР°РЅС‘РЅ (СѓРґР°Р»РµРЅРёРµ РѕС‚РєР»СЋС‡РµРЅРѕ; РїР°РЅРµР»СЊРЅС‹Рµ СЃРµСЂС‚РёС„РёРєР°С‚С‹ РЅРµ С‚СЂРѕРіР°СЋС‚СЃСЏ)"
  fi
  return 0
}

# --- РЎР°РјРѕР»РµС‡РµРЅРёРµ РїРѕ С‚Р°Р№РјРµСЂСѓ СѓР±СЂР°РЅРѕ РёР· Р°СЂС…РёС‚РµРєС‚СѓСЂС‹ ----------------------------
# РўР°Р№РјРµСЂ stack-heal.timer Р±РѕР»СЊС€Рµ РЅРµ СЃСѓС‰РµСЃС‚РІСѓРµС‚: install_heal_timer()/heal_once()
# Рё РїСЂРѕРІРµСЂРєР° inbounds_need_heal() СѓРґР°Р»РµРЅС‹ РєР°Рє РјС‘СЂС‚РІС‹Р№ РєРѕРґ. РџСЂРё СѓСЃС‚Р°РЅРѕРІРєРµ Рё
# РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєРµ uninstall_heal_timer() РґРѕС‡РёС‰Р°РµС‚ РѕСЃС‚Р°С‚РєРё СЃС‚Р°СЂС‹С… СЋРЅРёС‚РѕРІ.
# РћС‚РєР»РѕРЅРµРЅРёСЏ С‡РёРЅСЏС‚СЃСЏ РІСЂСѓС‡РЅСѓСЋ (Рї.1/Рї.4).

uninstall_heal_timer() {
  systemctl disable --now stack-heal.timer 2>/dev/null || true
  rm -f /etc/systemd/system/stack-heal.service /etc/systemd/system/stack-heal.timer
  systemctl daemon-reload 2>/dev/null || true
}

# =====================================================================
# РњРЈР›Р¬РўРРЎР•Р Рў (РµРґРёРЅС‹Р№ СЃРµСЂС‚ РЅР° РІСЃРµ РґРѕРјРµРЅС‹ СЃС‚РµРєР°) + СЃРѕС…СЂР°РЅРµРЅРёРµ email LE
# =====================================================================
le_email_load() {
  [[ "$EMAIL" =~ ^[^@]+@[^@]+\.[^@]+$ ]] && return 0
  EMAIL=""
  [[ -s "$LE_EMAIL_FILE" ]] && EMAIL=$(head -n1 "$LE_EMAIL_FILE" 2>/dev/null | tr -d '[:space:]')
  [[ "$EMAIL" =~ ^[^@]+@[^@]+\.[^@]+$ ]] && return 0
  EMAIL=""
  return 1
}
le_email_save() {
  local e="${1:-$EMAIL}"
  [[ -z "$e" ]] && return 1
  mkdir -p "$(dirname "$LE_EMAIL_FILE")" 2>/dev/null || true
  printf '%s\n' "$e" > "$LE_EMAIL_FILE" 2>/dev/null || return 1
  chmod 600 "$LE_EMAIL_FILE" 2>/dev/null || true
  EMAIL="$e"
  return 0
}
le_email_forget() {
  rm -f "$LE_EMAIL_FILE" 2>/dev/null || true
  EMAIL=""
}

# --- Р РµР¶РёРј РІС‹РїСѓСЃРєР° СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ (A/B) -----------------------------------
#   A = РѕРґРЅР° Р»РёРЅРёСЏ РЅР° РІСЃС‘ (РёРјСЏ = РґРѕРјРµРЅ РїР°РЅРµР»Рё, SAN = РІСЃРµ РґРѕРјРµРЅС‹)
#   B = Р»РёРЅРёСЏ РЅР° Р±Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ (СЂР°Р·РЅС‹Рµ Р±Р°Р·РѕРІС‹Рµ в†’ СЂР°Р·РЅС‹Рµ Р»РёРЅРёРё all.<Р±Р°Р·Р°>)
# РћР±Рµ РІРµС‚РєРё СЂРµР°Р»РёР·РѕРІР°РЅС‹: СЂРѕСѓС‚РёРЅРі РґРѕРјРµРЅРѕРІ вЂ” cert_line_for/cert_domains_add,
# РІС‹РїСѓСЃРє вЂ” cert_batch_flush (РѕР±С…РѕРґ Р»РёРЅРёР№).
# РЎРѕРІРјРµСЃС‚РёРјРѕСЃС‚СЊ СЃРѕ СЃС‚Р°СЂС‹Рј РјСѓР»СЊС‚РёСЃРµСЂС‚РѕРј (live/stack-multi): РґРѕРјРµРЅС‹ в†’ stack-domains.txt
cert_multi_compat_migrate() {
  [[ -s "/root/stack-multi-cert-domains.txt" ]] || return 0
  local d
  while IFS= read -r d; do
    d="$(printf '%s' "$d" | tr -d '[:space:]')"
    [[ -z "$d" ]] && continue
    cert_domains_add "$d"
  done < "/root/stack-multi-cert-domains.txt"
  mv "/root/stack-multi-cert-domains.txt" "/root/stack-multi-cert-domains.txt.migrated" 2>/dev/null || true
  log "РЎС‚Р°СЂС‹Р№ РјСѓР»СЊС‚РёСЃРїРёСЃРѕРє РїРµСЂРµРЅРµСЃС‘РЅ РІ $CERT_DOMAINS_FILE (Р»РёРЅРёСЏ live/stack-multi РЅРµ С‚СЂРѕРЅСѓС‚Р° вЂ” СѓР±РµСЂС‘С‚ Рї.10.13)"
}

cert_mode_load() {
  CERT_MODE=""
  if [[ -f "$CERT_MODE_FILE" ]]; then
    CERT_MODE=$(head -n1 "$CERT_MODE_FILE" 2>/dev/null | tr -d '[:space:]')
    if [[ "$CERT_MODE" == "A" || "$CERT_MODE" == "B" ]]; then
      return 0
    fi
    CERT_MODE=""
  fi
  # РђРІС‚РѕРѕРїСЂРµРґРµР»РµРЅРёРµ РґР»СЏ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РµРіРѕ СЃС‚РµРєР°: РµСЃС‚СЊ stack-domains.txt в†’
  # Р·РЅР°С‡РёС‚ СЂР°Р±РѕС‚Р°Р»Р° РѕРґРЅР° Р»РёРЅРёСЏ в†’ СЂРµР¶РёРј A. РџРёС€РµРј РјРѕР»С‡Р°.
  if [[ -s "$CERT_DOMAINS_FILE" ]]; then
    CERT_MODE="A"
    mkdir -p "$(dirname "$CERT_MODE_FILE")" 2>/dev/null || true
    printf '%s\n' "$CERT_MODE" > "$CERT_MODE_FILE" 2>/dev/null || true
    chmod 600 "$CERT_MODE_FILE" 2>/dev/null || true
  fi
  cert_multi_compat_migrate
  return 0
}

cert_mode_save() {
  local m="${1:-$CERT_MODE}"
  [[ "$m" != "A" && "$m" != "B" ]] && return 1
  mkdir -p "$(dirname "$CERT_MODE_FILE")" 2>/dev/null || true
  printf '%s\n' "$m" > "$CERT_MODE_FILE" 2>/dev/null || return 1
  chmod 600 "$CERT_MODE_FILE" 2>/dev/null || true
  CERT_MODE="$m"
  return 0
}

# РљСЂР°С‚РєРѕРµ РѕРїРёСЃР°РЅРёРµ СЂРµР¶РёРјРѕРІ (РґР»СЏ РјРµРЅСЋ)
cert_mode_describe() {
  echo
  echo -e "${B}  A) РћРґРЅР° Р»РёРЅРёСЏ РЅР° РІСЃС‘${N}"
  echo "     РРјСЏ: <РґРѕРјРµРЅ РїР°РЅРµР»Рё>. SAN: РґРѕРјРµРЅ РїР°РЅРµР»Рё + Р’РЎР• РґРѕРјРµРЅС‹ РёРЅР±Р°СѓРЅРґРѕРІ."
  echo -e "     ${G}+${N} РџСЂРѕС‰Рµ: РѕРґРЅР° Р»РёРЅРёСЏ, РѕРґРёРЅ СЃРїРёСЃРѕРє"
  echo -e "     ${R}-${N} Р•СЃР»Рё РѕРґРёРЅ РґРѕРјРµРЅ РЅРµ РІР°Р»РёРґРёСЂСѓРµС‚СЃСЏ - Р’Р•РЎР¬ РїРµСЂРµРІС‹РїСѓСЃРє РїР°РґР°РµС‚"
  echo -e "     ${R}-${N} Р›РёРјРёС‚ 100 SAN РЅР° СЃРµСЂС‚"
  echo -e "     ${R}-${N} Р Р°Р·РЅС‹Рµ DNS-РїСЂРѕРІР°Р№РґРµСЂС‹ (Cloudflare + Route53) - СЃР»РѕР¶РЅРµРµ"
  echo
  echo -e "${B}  B) Р›РёРЅРёСЏ РЅР° Р±Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ${N} ${Y}(СЂРµРєРѕРјРµРЅРґСѓРµС‚СЃСЏ)${N}"
  echo "     РРјСЏ: <РґРѕРјРµРЅ РїР°РЅРµР»Рё> РґР»СЏ РґРѕРјРµРЅРѕРІ С‚РѕР№ Р¶Рµ Р±Р°Р·С‹."
  echo "     Р”РѕРјРµРЅС‹ РґСЂСѓРіРёС… Р±Р°Р· - РѕС‚РґРµР»СЊРЅС‹Рµ Р»РёРЅРёРё (РёРјСЏ = СЃР°Рј РґРѕРјРµРЅ)."
  echo -e "     ${G}+${N} РЈСЃС‚РѕР№С‡РёРІРѕ: Р±РёС‚С‹Р№ РґРѕРјРµРЅ РЅРµ РІР°Р»РёС‚ РѕСЃС‚Р°Р»СЊРЅС‹Рµ"
  echo -e "     ${G}+${N} Р Р°Р·РЅС‹Рµ DNS-РїСЂРѕРІР°Р№РґРµСЂС‹ - РµСЃС‚РµСЃС‚РІРµРЅРЅРѕ"
  echo -e "     ${G}+${N} РќРµС‚ СЂРёСЃРєР° СѓРїРµСЂРµС‚СЊСЃСЏ РІ Р»РёРјРёС‚ SAN"
  echo -e "     ${R}-${N} РЎР»РѕР¶РЅРµРµ: РЅРµСЃРєРѕР»СЊРєРѕ Р»РёРЅРёР№, СЂР°Р·РЅС‹Рµ СЃСЂРѕРєРё РѕР±РЅРѕРІР»РµРЅРёСЏ"
  echo
}

# РРЅС‚РµСЂР°РєС‚РёРІРЅС‹Р№ РІРѕРїСЂРѕСЃ РїСЂРѕ СЂРµР¶РёРј. Р’ РЅРµ-TTY СЃСЂР°Р·Сѓ РІС‹С…РѕРґРёС‚.
# $1 == "force" вЂ” СЃРїСЂР°С€РёРІР°С‚СЊ, РґР°Р¶Рµ РµСЃР»Рё СѓР¶Рµ Р·Р°РґР°РЅ.
cert_mode_ask() {
  local force="${1:-}"
  [[ -t 0 ]] || return 0
  cert_mode_load
  if [[ -n "$CERT_MODE" && "$force" != "force" ]]; then
    return 0
  fi
  echo
  echo -e "${B}+- Р›РѕРіРёРєР° РІС‹РїСѓСЃРєР° СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ -+${N}"
  cert_mode_describe
  local cur="${CERT_MODE:-B}"
  local m=""
  ask m "Р’С‹Р±РѕСЂ [A/B]" "$cur" '^[ABab]$'
  m="${m^^}"
  cert_mode_save "$m"
  log "Р РµР¶РёРј: $m"
  if [[ "$m" == "B" ]]; then
    log "Р РµР¶РёРј B: РґРѕРјРµРЅС‹ РІРЅРµ Р±Р°Р·С‹ РїР°РЅРµР»Рё РїРѕР№РґСѓС‚ РІ РѕС‚РґРµР»СЊРЅС‹Рµ Р»РёРЅРёРё all.<Р±Р°Р·Р°> (РїРµСЂРµСЃР±РѕСЂРєР° вЂ” Рї.10.9)"
  fi
  return 0
}

# Р РµР°Р»СЊРЅРѕРµ РЅР°Р»РёС‡РёРµ wildcard, Р° РЅРµ С‚РѕР»СЊРєРѕ С„Р»Р°Рі wildcard-domain.
cert_wildcard_valid() {
  local base="${1:-${WILDCARD_DOMAIN:-}}" pem
  [[ -n "$base" ]] || return 1
  pem="/etc/letsencrypt/live/$base/fullchain.pem"
  [[ -f "$pem" ]] || return 1
  openssl x509 -noout -ext subjectAltName -in "$pem" 2>/dev/null \
    | grep -qE "DNS:\*\.${base//./\\.}([,[:space:]]|$)"
}

# РЇРІРЅС‹Р№ С‚РёРї СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ РґР»СЏ РїРµСЂРІРѕРЅР°С‡Р°Р»СЊРЅРѕР№ СѓСЃС‚Р°РЅРѕРІРєРё/Рї.1.
# $1 == force вЂ” СЃРїСЂР°С€РёРІР°С‚СЊ Р·Р°РЅРѕРІРѕ РґР°Р¶Рµ РїСЂРё РІС‹Р±РѕСЂРµ РІ С‚РµРєСѓС‰РµРј shell.
cert_type_ask() {
  local force="${1:-}" cm=""
  [[ -t 0 ]] || { [[ -n "${CERT_MODE_CHOICE:-}" ]] || CERT_MODE_CHOICE="personal"; return 0; }
  if [[ -n "${CERT_MODE_CHOICE:-}" && "$force" != "force" ]]; then return 0; fi
  echo
  echo -e "${B}  РЎРµСЂС‚РёС„РёРєР°С‚С‹: С‚РёРї РІС‹РїСѓСЃРєР° Рё Р»РёРЅРёРё${N}"
  echo "  1) Wildcard Cloudflare DNS-01 + A: РѕРґРЅР° Р»РёРЅРёСЏ РЅР° РІСЃС‘"
  echo "  2) Wildcard Cloudflare DNS-01 + B: Р»РёРЅРёСЏ РЅР° Р±Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ"
  echo "  3) РџРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рµ HTTP-01 + A: РѕРґРЅР° Р»РёРЅРёСЏ РЅР° РІСЃС‘"
  echo "  4) РџРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рµ HTTP-01 + B: Р»РёРЅРёСЏ РЅР° Р±Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ"
  if [[ -n "${WILDCARD_DOMAIN:-}" ]]; then
    if cert_wildcard_valid "$WILDCARD_DOMAIN"; then
      echo -e "  ${G}вњ“ Р РµР°Р»СЊРЅС‹Р№ wildcard *.$WILDCARD_DOMAIN РЅР°Р№РґРµРЅ${N}"
    else
      echo -e "  ${Y}! Р¤Р»Р°Рі wildcard РµСЃС‚СЊ, РЅРѕ СЂРµР°Р»СЊРЅС‹Р№ cert *.$WILDCARD_DOMAIN РЅРµ РЅР°Р№РґРµРЅ${N}"
    fi
  fi
  ask cm "Р’С‹Р±РѕСЂ [1/4]" "2" '^[1-4]$'
  case "$cm" in
    1) CERT_MODE_CHOICE="wildcard"; cert_mode_save A ;;
    2) CERT_MODE_CHOICE="wildcard"; cert_mode_save B ;;
    3) CERT_MODE_CHOICE="personal"; cert_mode_save A ;;
    4) CERT_MODE_CHOICE="personal"; cert_mode_save B ;;
  esac
  if [[ "$CERT_MODE_CHOICE" == "wildcard" ]]; then
    log "РўРёРї СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ: wildcard Cloudflare DNS-01 (Р»РёРЅРёРё: $CERT_MODE)"
    if [[ -n "${WILDCARD_DOMAIN:-}" ]] && ! cert_wildcard_valid "$WILDCARD_DOMAIN"; then
      warn "Р’С‹Р±СЂР°РЅ wildcard, РЅРѕ СЂРµР°Р»СЊРЅРѕРіРѕ СЃРµСЂС‚РёС„РёРєР°С‚Р° *.$WILDCARD_DOMAIN РЅРµС‚."
      cert_wildcard_issue "$WILDCARD_DOMAIN" || warn "Wildcard РЅРµ РІС‹РїСѓС‰РµРЅ вЂ” РїСЂРёС‡РёРЅР° РїРѕРєР°Р·Р°РЅР° РІС‹С€Рµ; РІС‹Р±РѕСЂ СЃРѕС…СЂР°РЅС‘РЅ."
    elif [[ -z "${WILDCARD_DOMAIN:-}" ]]; then
      cert_wildcard_issue || warn "Wildcard РЅРµ РІС‹РїСѓС‰РµРЅ вЂ” РїСЂРёС‡РёРЅР° РїРѕРєР°Р·Р°РЅР° РІС‹С€Рµ; РІС‹Р±РѕСЂ СЃРѕС…СЂР°РЅС‘РЅ."
    fi
  else
    log "РўРёРї СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ: РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рµ HTTP-01 (Р»РёРЅРёРё: $CERT_MODE)"
  fi
}

cert_mode_menu() {
  cert_mode_load
  line; echo -e "${B}   Р›РћР“РРљРђ Р’Р«РџРЈРЎРљРђ РЎР•Р РўРР¤РРљРђРўРћР’${N}"; line
  echo "  РўРµРєСѓС‰РёР№ СЂРµР¶РёРј: ${CERT_MODE:-<РЅРµ Р·Р°РґР°РЅ>}"
  cert_mode_ask force
  echo
  echo "  РўРёРї СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ РІС‹Р±РёСЂР°РµС‚СЃСЏ РїСЂРё Р·Р°РїСѓСЃРєРµ Рї.1/РїРµСЂРІРѕРЅР°С‡Р°Р»СЊРЅРѕР№ СѓСЃС‚Р°РЅРѕРІРєРµ."
  pause
}

cert_multi_name_resolve() {
  [[ -n "$CERT_MULTI_NAME" ]] && return 0
  local pd="${PANEL_DOMAIN:-}"
  [[ -z "$pd" && -n "$XUI_DB" && -f "$XUI_DB" ]] && pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && return 1
  CERT_MULTI_NAME="$pd"
  return 0
}


# =====================================================================
# Р¤РђР™Р›Р« Р›РРќРР™ РЎР•Р РўРР¤РРљРђРўРћР’ (РґР»СЏ СЂРµР¶РёРјР° B вЂ” РЅРµСЃРєРѕР»СЊРєРѕ Р»РёРЅРёР№)
# =====================================================================
# Р’ СЂРµР¶РёРјРµ A вЂ” РѕРґРЅР° Р»РёРЅРёСЏ, РёРјСЏ = РґРѕРјРµРЅ РїР°РЅРµР»Рё, SAN = stack-domains.txt.
# Р’ СЂРµР¶РёРјРµ B вЂ” РЅРµСЃРєРѕР»СЊРєРѕ Р»РёРЅРёР№: cert-lines.txt (СЃРїРёСЃРѕРє РёРјС‘РЅ) + С„Р°Р№Р» РЅР° РєР°Р¶РґСѓСЋ.
# Р”Р»СЏ СЃРѕРІРјРµСЃС‚РёРјРѕСЃС‚Рё: cert_lines_load() РІ СЂРµР¶РёРјРµ A РІРѕР·РІСЂР°С‰Р°РµС‚ РѕРґРЅСѓ Р»РёРЅРёСЋ,
# С‡РёС‚Р°СЏ РґРѕРјРµРЅС‹ РёР· stack-domains.txt.

cert_line_file() {   # <line-name> в†’ РїСѓС‚СЊ Рє С„Р°Р№Р»Сѓ SAN СЌС‚РѕР№ Р»РёРЅРёРё
  printf '%s%s.domains' "$CERT_LINE_FILE_PREFIX" "$1"
}

# РІР°Р»РёРґРЅС‹Р№ РґРѕРјРµРЅ: >=2 РјРµС‚РєРё РёР· [a-z0-9-], Р±РµР· РІРµРґСѓС‰РёС…/С…РІРѕСЃС‚РѕРІС‹С… РґРµС„РёСЃРѕРІ.
# РћС‚СЃРµРєР°РµС‚ РјСѓСЃРѕСЂ РёР· С„Р°Р№Р»РѕРІ Р»РёРЅРёР№ (В«0В», РѕР±СЂРµР·РєРё), РєРѕС‚РѕСЂС‹Р№ СЂР°РЅСЊС€Рµ РґРѕРµР·Р¶Р°Р» РґРѕ ACME.
cert_domain_valid() {
  local d="$1"
  [[ "$d" =~ ^[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?)+$ ]]
}

# РІР°Р»РёРґРЅРѕРµ РёРјСЏ Р»РёРЅРёРё: РґРѕРјРµРЅ РР›Р all.<РґРѕРјРµРЅ>
cert_line_name_valid() {
  local n="$1"
  [[ "$n" == all.* ]] && n="${n#all.}"
  cert_domain_valid "$n"
}

# Р—Р°РіСЂСѓР·РєР° СЃРїРёСЃРєР° Р»РёРЅРёР№ РІ РјР°СЃСЃРёРІ CERT_LINES
cert_lines_load() {
  CERT_LINES=()
  cert_mode_load >/dev/null 2>&1 || true
  if [[ "${CERT_MODE:-A}" == "A" ]]; then
    # Р РµР¶РёРј A: РѕРґРЅР° Р»РёРЅРёСЏ (РёРјСЏ = РґРѕРјРµРЅ РїР°РЅРµР»Рё) вЂ” РІС‹С‡РёСЃР»СЏРµРј РїСЂРё РЅРµРѕР±С…РѕРґРёРјРѕСЃС‚Рё
    local nm=""
    nm=$(cert_multi_name_resolve >/dev/null 2>&1; printf '%s' "${CERT_MULTI_NAME:-}")
    [[ -z "$nm" ]] && nm=$(xui_get webDomain 2>/dev/null || true)
    [[ -n "$nm" && "$nm" != "null" ]] && CERT_LINES=("$nm")
    return 0
  fi
  # Р РµР¶РёРј B: СЃРїРёСЃРѕРє РёР· С„Р°Р№Р»Р°. Р•СЃР»Рё СЃРїРёСЃРѕРє Р»РёРЅРёР№ РїРѕС‚РµСЂСЏРЅ, РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј
  # РµРіРѕ РїРѕ cert-line-*.domains Рё РїРѕ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Рј certbot live-РєР°С‚Р°Р»РѕРіР°Рј.
  if [[ ! -f "$CERT_LINES_FILE" ]]; then
    local _lf _ln
    for _lf in "${CERT_LINE_FILE_PREFIX}"*.domains; do
      [[ -f "$_lf" ]] || continue
      _ln="${_lf#${CERT_LINE_FILE_PREFIX}}"; _ln="${_ln%.domains}"
      cert_line_name_valid "$_ln" && CERT_LINES+=("$_ln")
    done
    if [[ ${#CERT_LINES[@]} -gt 0 ]]; then
      cert_lines_save
      return 0
    fi
    # РЎС‚Р°СЂС‹Рµ СѓСЃС‚Р°РЅРѕРІРєРё СЂРµР¶РёРјР° B РјРѕРіР»Рё РЅРµ РёРјРµС‚СЊ СЃР»СѓР¶РµР±РЅС‹С… С„Р°Р№Р»РѕРІ Р»РёРЅРёР№:
    # РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј РёС… РїРѕ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёРј certbot live-РєР°С‚Р°Р»РѕРіР°Рј. Р’С‹Р±РѕСЂ В«4В»
    # РІ РјР°СЃС‚РµСЂРµ РѕР·РЅР°С‡Р°РµС‚ personal+B, Р° РЅРµ РЅРѕРјРµСЂ Р»РёРЅРёРё вЂ” Р»РёРЅРёРµР№ СЏРІР»СЏРµС‚СЃСЏ РёРјСЏ
    # СЃРµСЂС‚РёС„РёРєР°С‚Р° (РЅР°РїСЂРёРјРµСЂ example.net РёР»Рё all.example.net).
    local _lf _ln
    for _lf in /etc/letsencrypt/live/*/; do
      [[ -d "$_lf" ]] || continue
      _ln="$(basename "${_lf%/}")"
      [[ "$_ln" == "README" ]] && continue
      cert_line_name_valid "$_ln" || continue
      # Р РµР¶РёРј B: РїРµСЂСЃРѕРЅР°Р»СЊРЅР°СЏ Р»РёРЅРёСЏ live/<РґРѕРјРµРЅ> РєР°РЅРѕРЅРёР·РёСЂСѓРµС‚СЃСЏ РІ Р»РёРЅРёСЋ
      # РґРѕРјРµРЅР° (РїР°РЅРµР»СЊ/РІСЃРµ.<Р±Р°Р·Р°>) вЂ” В«РґРѕРјРµРЅ = Р»РёРЅРёСЏВ» РїР»РѕРґРёР» РґСѓР±Р»Рё.
      local _dom="$_ln"
      if [[ "${CERT_MODE:-A}" == "B" && "$_ln" != all.* ]]; then
        local _canon=""; _canon=$(cert_line_for "$_ln" 2>/dev/null || true)
        [[ -n "$_canon" && "$_canon" != "$_ln" ]] && _ln="$_canon"
      fi
      [[ " ${CERT_LINES[*]} " == *" $_ln "* ]] && continue
      CERT_LINES+=("$_ln")
      local _df; _df="$(cert_line_file "$_ln")"
      if [[ -s "$_df" ]]; then
        grep -qxF "$_dom" "$_df" 2>/dev/null || printf '%s\n' "$_dom" >> "$_df"
      else
        printf '%s\n' "$_dom" > "$_df"
      fi
    done
    # РўР°РєР¶Рµ РїРѕРґС…РІР°С‚С‹РІР°РµРј СЃС‚Р°СЂС‹Р№ РѕР±С‰РёР№ СЃРїРёСЃРѕРє (stack-domains.txt), РµСЃР»Рё
    # certbot-РєР°С‚Р°Р»РѕРіРё Р±С‹Р»Рё РїРµСЂРµРёРјРµРЅРѕРІР°РЅС‹ РёР»Рё РѕС‡РёС‰РµРЅС‹. Р’РђР–РќРћ: РґРѕРјРµРЅС‹
    # СЂР°СЃРїСЂРµРґРµР»СЏСЋС‚СЃСЏ РџРћ Р›РРќРРЇРњ (СЂРµР¶РёРј B вЂ” cert_line_for; СЂРµР¶РёРј A вЂ” РіР»Р°РІРЅР°СЏ
    # Р»РёРЅРёСЏ), Р° РќР• В«РґРѕРјРµРЅ = РѕС‚РґРµР»СЊРЅР°СЏ Р»РёРЅРёСЏВ», РєР°Рє РґРµР»Р°Р»Р° СЃС‚Р°СЂР°СЏ РјРёРіСЂР°С†РёСЏ вЂ”
    # РёРјРµРЅРЅРѕ РѕРЅР° РѕСЃС‚Р°РІР»СЏР»Р° В«РѕРґРёРЅ РґРѕРјРµРЅ РІ РґРІСѓС… Р»РёРЅРёСЏС…В» (rt/rx/tgвЂ¦).
    if [[ -s "$CERT_DOMAINS_FILE" ]]; then
      local _d _line
      while IFS= read -r _d; do
        _d="$(printf '%s' "$_d" | tr -d '[:space:]')"; [[ -z "$_d" ]] && continue
        cert_domain_valid "$_d" || continue
        if [[ "${CERT_MODE:-A}" == "B" ]]; then
          _line=$(cert_line_for "$_d" 2>/dev/null || true)
          [[ -z "$_line" ]] && continue
        else
          cert_multi_name_resolve >/dev/null 2>&1 || true
          _line="${CERT_MULTI_NAME:-}"
          [[ -z "$_line" ]] && _line="$_d"   # СЃРѕРІСЃРµРј Р±РµР· РґРѕРјРµРЅР° РїР°РЅРµР»Рё вЂ” РєР°Рє СЃСѓРјРµРµРј
        fi
        [[ " ${CERT_LINES[*]} " == *" $_line "* ]] || CERT_LINES+=("$_line")
        if [[ "${CERT_MODE:-A}" == "B" ]]; then
          local _df2; _df2="$(cert_line_file "$_line")"
          if [[ -s "$_df2" ]]; then
            grep -qxF "$_d" "$_df2" 2>/dev/null || printf '%s\n' "$_d" >> "$_df2"
          else
            printf '%s\n' "$_d" > "$_df2"
          fi
        fi
      done < "$CERT_DOMAINS_FILE"
    fi
    [[ ${#CERT_LINES[@]} -gt 0 ]] && cert_lines_save
    return 0
  fi
  local l
  while IFS= read -r l; do
    l="$(printf '%s' "$l" | tr -d '[:space:]')"
    [[ -z "$l" ]] && continue
    if ! cert_line_name_valid "$l"; then
      warn "cert-lines: РёРјСЏ Р»РёРЅРёРё В«$lВ» РЅРµ РїРѕС…РѕР¶Рµ РЅР° РґРѕРјРµРЅ вЂ” РїСЂРѕРїСѓСЃРє (РјСѓСЃРѕСЂ РІ $CERT_LINES_FILE)"
      continue
    fi
    [[ " ${CERT_LINES[*]} " == *" $l "* ]] && continue
    CERT_LINES+=("$l")
  done < "$CERT_LINES_FILE"
  return 0
}

cert_lines_save() {
  mkdir -p "$(dirname "$CERT_LINES_FILE")" 2>/dev/null || true
  if [[ ${#CERT_LINES[@]} -eq 0 ]]; then
    : > "$CERT_LINES_FILE"
    return 0
  fi
  printf '%s\n' "${CERT_LINES[@]}" > "$CERT_LINES_FILE" 2>/dev/null || true
  chmod 600 "$CERT_LINES_FILE" 2>/dev/null || true
}

cert_lines_add() {   # <line-name>
  local n="$1"
  [[ -z "$n" ]] && return 0
  cert_lines_load
  [[ " ${CERT_LINES[*]} " == *" $n "* ]] && return 0
  CERT_LINES+=("$n")
  cert_lines_save
}

cert_lines_remove() {   # <line-name>
  local n="$1"
  [[ -z "$n" ]] && return 0
  cert_lines_load
  local -a out=() x
  for x in "${CERT_LINES[@]}"; do
    [[ "$x" == "$n" ]] && continue
    out+=("$x")
  done
  if [[ ${#out[@]} -ne ${#CERT_LINES[@]} ]]; then
    CERT_LINES=("${out[@]}")
    cert_lines_save
  fi
  # РЈРґР°Р»СЏРµРј Рё С„Р°Р№Р» SAN СЌС‚РѕР№ Р»РёРЅРёРё
  rm -f "$(cert_line_file "$n")" 2>/dev/null || true
}

# Р—Р°РіСЂСѓР·РєР° SAN Р»РёРЅРёРё РІ РјР°СЃСЃРёРІ CERT_LINE_DOMAINS
# Р’ СЂРµР¶РёРјРµ A РґР»СЏ РіР»Р°РІРЅРѕР№ Р»РёРЅРёРё SAN = stack-domains.txt
declare -a CERT_LINE_DOMAINS=()
cert_line_domains_load() {   # <line-name>
  CERT_LINE_DOMAINS=()
  local n="$1"
  [[ -z "$n" ]] && return 0
  local f=""
  # Р РµР¶РёРј A: РіР»Р°РІРЅР°СЏ Р»РёРЅРёСЏ в†’ С‡РёС‚Р°РµРј stack-domains.txt
  if [[ "${CERT_MODE:-A}" == "A" ]]; then
    local pn=""
    pn=$(xui_get webDomain 2>/dev/null || true)
    if [[ -n "$pn" && "$n" == "$pn" && -f "$CERT_DOMAINS_FILE" ]]; then
      f="$CERT_DOMAINS_FILE"
    fi
  fi
  [[ -z "$f" ]] && f=$(cert_line_file "$n")
  [[ -f "$f" ]] || return 0
  local d
  while IFS= read -r d; do
    d="$(printf '%s' "$d" | tr -d '[:space:]')"
    [[ -z "$d" ]] && continue
    if ! cert_domain_valid "$d"; then
      warn "cert-line В«$nВ»: РґРѕРјРµРЅ В«$dВ» РЅРµ РїРѕС…РѕР¶ РЅР° РґРѕРјРµРЅ вЂ” РїСЂРѕРїСѓСЃРє (РјСѓСЃРѕСЂ РІ $f)"
      continue
    fi
    [[ " ${CERT_LINE_DOMAINS[*]} " == *" $d "* ]] && continue
    CERT_LINE_DOMAINS+=("$d")
  done < "$f"
  return 0
}

cert_line_domains_save() {   # <line-name>  (РёСЃРїРѕР»СЊР·СѓРµС‚ CERT_LINE_DOMAINS)
  local n="$1"
  [[ -z "$n" ]] && return 0
  # Р РµР¶РёРј A: РіР»Р°РІРЅР°СЏ Р»РёРЅРёСЏ в†’ СЃРѕС…СЂР°РЅСЏРµРј РІ stack-domains.txt
  if [[ "${CERT_MODE:-A}" == "A" ]]; then
    local pn=""
    pn=$(xui_get webDomain 2>/dev/null || true)
    if [[ -n "$pn" && "$n" == "$pn" ]]; then
      mkdir -p "$(dirname "$CERT_DOMAINS_FILE")" 2>/dev/null || true
      if [[ ${#CERT_LINE_DOMAINS[@]} -eq 0 ]]; then
        : > "$CERT_DOMAINS_FILE"
      else
        printf '%s\n' "${CERT_LINE_DOMAINS[@]}" > "$CERT_DOMAINS_FILE" 2>/dev/null || true
      fi
      return 0
    fi
  fi
  # Р РµР¶РёРј B / РѕР±С‹С‡РЅС‹Р№ СЃР»СѓС‡Р°Р№ в†’ РѕС‚РґРµР»СЊРЅС‹Р№ С„Р°Р№Р»
  local f; f=$(cert_line_file "$n")
  mkdir -p "$(dirname "$f")" 2>/dev/null || true
  if [[ ${#CERT_LINE_DOMAINS[@]} -eq 0 ]]; then
    : > "$f"
  else
    printf '%s\n' "${CERT_LINE_DOMAINS[@]}" > "$f" 2>/dev/null || true
  fi
  chmod 600 "$f" 2>/dev/null || true
}

cert_line_domains_add() {   # <line-name> <domain>
  local n="$1" d="$2"
  [[ -z "$n" || -z "$d" ]] && return 0
  cert_lines_add "$n"
  cert_line_domains_load "$n"
  [[ " ${CERT_LINE_DOMAINS[*]} " == *" $d "* ]] && return 0
  CERT_LINE_DOMAINS+=("$d")
  cert_line_domains_save "$n"
}

cert_line_domains_remove() {   # <line-name> <domain>
  local n="$1" d="$2"
  [[ -z "$n" || -z "$d" ]] && return 0
  cert_line_domains_load "$n"
  local -a out=() x
  for x in "${CERT_LINE_DOMAINS[@]}"; do
    [[ "$x" == "$d" ]] && continue
    out+=("$x")
  done
  if [[ ${#out[@]} -ne ${#CERT_LINE_DOMAINS[@]} ]]; then
    CERT_LINE_DOMAINS=("${out[@]}")
    cert_line_domains_save "$n"
  fi
}

# РћРїСЂРµРґРµР»СЏРµС‚ РёРјСЏ Р»РёРЅРёРё, РєРѕС‚РѕСЂР°СЏ РґРѕР»Р¶РЅР° СЃРѕРґРµСЂР¶Р°С‚СЊ РґРѕРјРµРЅ $1.
# Р’ СЂРµР¶РёРјРµ A: РІСЃРµРіРґР° РґРѕРјРµРЅ РїР°РЅРµР»Рё (РѕРґРЅР° Р»РёРЅРёСЏ).
# Р’ СЂРµР¶РёРјРµ B:
#   - РµСЃР»Рё РґРѕРјРµРЅ РІ Р·РѕРЅРµ Р±Р°Р·С‹ РїР°РЅРµР»Рё в†’ РёРјСЏ = РґРѕРјРµРЅ РїР°РЅРµР»Рё (РіР»Р°РІРЅР°СЏ Р»РёРЅРёСЏ);
#   - РµСЃР»Рё РґРѕРјРµРЅ РІРЅРµ Р·РѕРЅС‹ в†’ РёРјСЏ = all.<Р±Р°Р·РѕРІС‹Р№-РґРѕРјРµРЅ-РґРѕРјРµРЅР°> (РґРѕРї. Р»РёРЅРёСЏ);
#     РґР»СЏ РґРѕРјРµРЅРѕРІ РІРёРґР° a.b.c.com В«Р±Р°Р·Р°В» = b.c.com (РїРѕСЃР»РµРґРЅРёРµ РґРІРµ РјРµС‚РєРё? РЅРµС‚ вЂ”
#     Р±Р°Р·Р° = РґРІРµ РїРѕСЃР»РµРґРЅРёРµ РјРµС‚РєРё: c.com). Р”Р»СЏ РґРѕРјРµРЅРѕРІ РІРёРґР° panel.a.com в†’ a.com.
# РўРѕ РµСЃС‚СЊ: РіР»Р°РІРЅР°СЏ Р»РёРЅРёСЏ = РґРѕРјРµРЅ РїР°РЅРµР»Рё; РґРѕРї. Р»РёРЅРёРё РёРјРµРЅСѓСЋС‚СЃСЏ all.<base>,
# РіРґРµ base = РїРѕСЃР»РµРґРЅРёРµ РґРІРµ РјРµС‚РєРё РґРѕРјРµРЅР° (РёР»Рё РІРµСЃСЊ РґРѕРјРµРЅ, РµСЃР»Рё РјРµС‚РѕРє РјРµРЅСЊС€Рµ 3).
cert_line_for() {   # <domain> в†’ РїРµС‡Р°С‚Р°РµС‚ РёРјСЏ Р»РёРЅРёРё
  local d="$1"
  [[ -z "$d" ]] && return 1
  cert_mode_load >/dev/null 2>&1 || true
  local pd=""
  pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && pd="${PANEL_DOMAIN:-}"
  if [[ -z "$pd" ]]; then
    # РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµРёР·РІРµСЃС‚РµРЅ в†’ РіР»Р°РІРЅРѕР№ Р»РёРЅРёРё РЅРµС‚, РІС‹С‡РёСЃР»РёРј РїРѕ Р±Р°Р·Рµ РґРѕРјРµРЅР°
    cert_mode_line_base "$d"
    return 0
  fi
  if [[ "${CERT_MODE:-A}" == "A" ]]; then
    printf '%s' "$pd"
    return 0
  fi
  # Р РµР¶РёРј B. Р•СЃР»Рё РІРєР»СЋС‡С‘РЅ wildcard, РІСЃРµ РґРѕРјРµРЅС‹ РµРіРѕ Р·РѕРЅС‹ РґРѕР»Р¶РЅС‹ Р¶РёС‚СЊ
  # РІ РѕРґРЅРѕР№ Р»РёРЅРёРё wildcard, Р° РЅРµ РІ РѕС‚РґРµР»СЊРЅС‹С… Р»РёРЅРёСЏС… РїРѕРґРґРѕРјРµРЅРѕРІ.
  if [[ -z "${WILDCARD_DOMAIN:-}" && -f "$WILDCARD_STATE" ]]; then
    WILDCARD_DOMAIN=$(head -n 1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]' || true)
  fi
  if [[ -n "${WILDCARD_DOMAIN:-}" && ( "$d" == "$WILDCARD_DOMAIN" || "$d" == *."$WILDCARD_DOMAIN" ) ]]; then
    printf '%s' "$WILDCARD_DOMAIN"
    return 0
  fi
  local pbase="${pd#*.}"
  [[ "$pbase" != *.* ]] && pbase="$pd"
  # РґРѕРјРµРЅ РїР°РЅРµР»Рё СЃР°Рј (panel.exemple.xyz) в†’ Р±Р°Р·Р° exemple.xyz
  # РґРѕРјРµРЅ РІ Р±Р°Р·Рµ РїР°РЅРµР»Рё?
  if [[ "$d" == "$pd" || "$d" == "$pbase" || "$d" == *."$pbase" ]]; then
    printf '%s' "$pd"
    return 0
  fi
  # РІРЅРµ Р·РѕРЅС‹ РїР°РЅРµР»Рё в†’ РѕС‚РґРµР»СЊРЅР°СЏ Р»РёРЅРёСЏ all.<base>
  cert_mode_line_base "$d"
}

# Р’С‹С‡РёСЃР»СЏРµС‚ all.<base> РґР»СЏ РґРѕРјРµРЅР° (base = РїРѕСЃР»РµРґРЅРёРµ РґРІРµ РјРµС‚РєРё)
cert_mode_line_base() {   # <domain> в†’ РїРµС‡Р°С‚Р°РµС‚ all.<base>
  local d="$1"
  local IFS='.'
  local -a p
  read -r -a p <<<"$d"
  local n=${#p[@]}
  local base=""
  if (( n >= 3 )); then
    base="${p[n-2]}.${p[n-1]}"
  elif (( n == 2 )); then
    base="$d"
  else
    base="$d"
  fi
  printf 'all.%s' "$base"
}

# РњРёРіСЂР°С†РёСЏ: СЂР°Р·Р»РѕР¶РёС‚СЊ С‚РµРєСѓС‰РёР№ stack-domains.txt РїРѕ Р»РёРЅРёСЏРј (РґР»СЏ B).
# Р’ СЂРµР¶РёРјРµ A вЂ” РѕСЃС‚Р°РІР»СЏРµРј РєР°Рє РµСЃС‚СЊ.

# РљР°РЅРѕРЅРёР·Р°С†РёСЏ СЂРµРµСЃС‚СЂР° Р»РёРЅРёР№ (СЂРµР¶РёРј B): Р»РёРЅРёРё, РЅР°Р·РІР°РЅРЅС‹Рµ РґРѕРјРµРЅРѕРј, РєРѕС‚РѕСЂС‹Р№
# cert_line_for СѓРІРѕРґРёС‚ РІ Р”Р РЈР“РЈР® Р»РёРЅРёСЋ (РїР°РЅРµР»СЊ/wildcard-Р±Р°Р·Р°/all.<Р±Р°Р·Р°>) вЂ”
# РЅР°СЃР»РµРґРёРµ СЃС‚Р°СЂРѕР№ РјРёРіСЂР°С†РёРё В«РґРѕРјРµРЅ = Р»РёРЅРёСЏВ» Рё РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹С… РІС‹РїСѓСЃРєРѕРІ cert_issue.
# Р”РѕРјРµРЅС‹ С‚Р°РєРѕР№ Р»РёРЅРёРё РїРµСЂРµРЅРѕСЃСЏС‚СЃСЏ РІ РєР°РЅРѕРЅРёС‡РµСЃРєСѓСЋ, РїСѓСЃС‚Р°СЏ Р»РёРЅРёСЏ СѓРґР°Р»СЏРµС‚СЃСЏ
# РІРјРµСЃС‚Рµ СЃ РµС‘ SAN-С„Р°Р№Р»РѕРј. РРґРµРјРїРѕС‚РµРЅС‚РЅРѕ: РєР°РЅРѕРЅРёС‡РµСЃРєРёРµ РёРјРµРЅР° (РґРѕРјРµРЅ РїР°РЅРµР»Рё,
# wildcard-Р±Р°Р·Р°, all.*) РЅРµ РїРµСЂРµРєР»Р°СЃСЃРёС„РёС†РёСЂСѓСЋС‚СЃСЏ. РЎР•Р РўРР¤РРљРђРўР« РЅРµ С‚СЂРѕРіР°СЋС‚СЃСЏ вЂ”
# СЌС‚Рѕ РїСЂР°РІРєР° С‚РѕР»СЊРєРѕ СЂРµРµСЃС‚СЂР°; РІС‹РґР°С‡Сѓ РґРµР»Р°РµС‚ cert_batch_flush.
cert_lines_canon_migrate() {
  cert_mode_load >/dev/null 2>&1 || true
  [[ "${CERT_MODE:-A}" == "B" ]] || return 0
  cert_lines_load
  [[ ${#CERT_LINES[@]} -eq 0 ]] && return 0
  local pd=""
  pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && pd="${PANEL_DOMAIN:-}"
  if [[ -z "${WILDCARD_DOMAIN:-}" && -f "$WILDCARD_STATE" ]]; then
    WILDCARD_DOMAIN=$(head -n 1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]' || true)
  fi
  local -a bogus=() targets=()
  local ln target
  for ln in "${CERT_LINES[@]}"; do
    if [[ -n "$pd" && "$ln" == "$pd" ]] \
       || [[ -n "${WILDCARD_DOMAIN:-}" && "$ln" == "$WILDCARD_DOMAIN" ]] \
       || [[ "$ln" == all.* ]]; then
      continue   # РєР°РЅРѕРЅРёС‡РµСЃРєРѕРµ РёРјСЏ вЂ” РЅРµ С‚СЂРѕРіР°РµРј
    fi
    target=$(cert_line_for "$ln" 2>/dev/null || true)
    if [[ -z "$target" || "$target" == "$ln" ]]; then
      continue   # РјР°СЂС€СЂСѓС‚РёР·Р°С†РёСЏ РЅРµ РѕРїСЂРµРґРµР»РёР»Р°СЃСЊ вЂ” РѕСЃС‚Р°РІР»СЏРµРј РєР°Рє РµСЃС‚СЊ
    fi
    bogus+=("$ln"); targets+=("$target")
  done
  [[ ${#bogus[@]} -eq 0 ]] && return 0
  local i d n_moved=0
  for i in "${!bogus[@]}"; do
    ln="${bogus[$i]}"; target="${targets[$i]}"
    cert_line_domains_load "$ln"
    local -a doms=("${CERT_LINE_DOMAINS[@]}")
    for d in "${doms[@]}"; do
      cert_line_domains_add "$target" "$d"
    done
    n_moved=$((n_moved + ${#doms[@]}))
    cert_lines_remove "$ln"
    log "  РєР°РЅРѕРЅРёР·Р°С†РёСЏ Р»РёРЅРёР№: В«$lnВ» в†’ В«$targetВ» (${#doms[@]} РґРј.)"
  done
  [[ $n_moved -gt 0 ]] && log "Р РµРµСЃС‚СЂ Р»РёРЅРёР№ РєР°РЅРѕРЅРёР·РёСЂРѕРІР°РЅ: РїРµСЂРµРЅРµСЃРµРЅРѕ РґРѕРјРµРЅРѕРІ вЂ” $n_moved"
  return 0
}

# РџРѕРєР°Р·Р°С‚СЊ РІСЃРµ Р»РёРЅРёРё СЃ РёС… SAN (РґР»СЏ Р°СѓРґРёС‚Р°/РјРµРЅСЋ)

# =====================================================================
# Р”РћРњР•Рќ + РЎР•Р РўРР¤РРљРђРў РџРђРќР•Р›Р РЎР РђР—РЈ РџРћРЎР›Р• Р§РРЎРўРћР™ РЈРЎРўРђРќРћР’РљР
# =====================================================================
cert_domains_load() {
  CERT_DOMAINS=()
  [[ -f "$CERT_DOMAINS_FILE" ]] || return 0
  local d
  while IFS= read -r d; do
    d="$(printf '%s' "$d" | tr -d '[:space:]')"
    [[ -z "$d" ]] && continue
    [[ " ${CERT_DOMAINS[*]} " == *" $d "* ]] && continue
    CERT_DOMAINS+=("$d")
  done < "$CERT_DOMAINS_FILE"
}
cert_domains_save() {
  mkdir -p "$(dirname "$CERT_DOMAINS_FILE")" 2>/dev/null || true
  if [[ ${#CERT_DOMAINS[@]} -eq 0 ]]; then
    : > "$CERT_DOMAINS_FILE"
    return 0
  fi
  printf '%s\n' "${CERT_DOMAINS[@]}" > "$CERT_DOMAINS_FILE" 2>/dev/null || true
}
cert_domains_add() {
  local d="$1" force="${2:-0}"
  [[ -z "$d" ]] && return 0
  # CDN-С„СЂРѕРЅС‚ вЂ” РЅРµ РЅР°С€ РґРѕРјРµРЅ: СЃРµСЂС‚ РІС‹РґР°РµС‚ CDN, РІ SAN РѕРЅ РЅРµ РґРѕР±Р°РІР»СЏРµС‚СЃСЏ
  if cdn_front_domain_is "$d"; then
    warn "cert_domains_add: В«$dВ» вЂ” РґРѕРјРµРЅ CDN-С„СЂРѕРЅС‚Р°, РІ SAN РЅРµ РґРѕР±Р°РІР»СЏРµС‚СЃСЏ (TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ CDN)"
    return 0
  fi
  # wildcard РІ SAN-Р»РёРЅРёРё РЅРµ РЅСѓР¶РµРЅ: HTTP-01 РµРіРѕ РЅРµ РІС‹РїСѓСЃС‚РёС‚, Р° РїРѕРєСЂС‹С‚РёРµ
  # *.Р±Р°Р·Р° СѓР¶Рµ РґР°С‘С‚ СЃРµСЂС‚ Р»РёРЅРёРё/С„Р°Р№Р» РґРѕРјРµРЅРѕРІ вЂ” РЅРµ РїРѕСЂС‚РёРј РёРґРµРјРїРѕС‚РµРЅС‚РЅРѕСЃС‚СЊ
  if [[ "$d" == "*."* ]]; then
    warn "cert_domains_add: wildcard В«$dВ» РІ SAN-СЃРїРёСЃРѕРє РЅРµ РґРѕР±Р°РІР»СЏРµС‚СЃСЏ (РЅРµ РІС‹РїСѓСЃРєР°РµС‚СЃСЏ РїРѕ HTTP-01)"
    return 0
  fi
  cert_mode_load >/dev/null 2>&1 || true
  # в”Ђв”Ђ Р’ СЂРµР¶РёРјРµ B РґРѕР±Р°РІР»СЏРµРј РІ РїСЂР°РІРёР»СЊРЅСѓСЋ Р»РёРЅРёСЋ (Р°РІС‚РѕРѕРїСЂРµРґРµР»РµРЅРёРµ РїРѕ Р±Р°Р·Рµ) в”Ђв”Ђ
  if [[ "${CERT_MODE:-A}" == "B" ]]; then
    local _line=""
    _line=$(cert_line_for "$d")
    if [[ -z "$_line" ]]; then
      # РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµРёР·РІРµСЃС‚РµРЅ вЂ” РЅРµРєСѓРґР° РєР»Р°СЃС‚СЊ, РїРёС€РµРј РІ РѕР±С‰РёР№ (best effort)
      warn "cert_domains_add: РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµ РѕРїСЂРµРґРµР»С‘РЅ вЂ” В«$dВ» РЅРµ РїСЂРёРІСЏР·Р°РЅ Рє Р»РёРЅРёРё"
      return 1
    fi
    cert_line_domains_add "$_line" "$d"
    return 0
  fi
  # в”Ђв”Ђ Р РµР¶РёРј A вЂ” Р±РµР· С„РёР»СЊС‚СЂР°: РѕРґРЅР° Р»РёРЅРёСЏ (РёРјСЏ = РґРѕРјРµРЅ РїР°РЅРµР»Рё) в”Ђв”Ђ
  cert_domains_load
  [[ " ${CERT_DOMAINS[*]} " == *" $d "* ]] && return 0
  CERT_DOMAINS+=("$d")
  cert_domains_save
}
cert_domains_remove() {
  local d="$1"
  [[ -z "$d" ]] && return 0
  cert_mode_load >/dev/null 2>&1 || true
  # РїР°РЅРµР»СЊРЅС‹Р№ РґРѕРјРµРЅ = РёРјСЏ РіР»Р°РІРЅРѕР№ Р»РёРЅРёРё, РЅРµР»СЊР·СЏ СѓР±СЂР°С‚СЊ
  cert_multi_name_resolve >/dev/null 2>&1 || true
  [[ -n "$CERT_MULTI_NAME" && "$d" == "$CERT_MULTI_NAME" ]] && return 0
  # в”Ђв”Ђ Р’ СЂРµР¶РёРјРµ B СѓР±РёСЂР°РµРј РёР· С‚РѕР№ Р»РёРЅРёРё, РіРґРµ РѕРЅ Р»РµР¶РёС‚ в”Ђв”Ђ
  if [[ "${CERT_MODE:-A}" == "B" ]]; then
    local _line=""
    _line=$(cert_line_for "$d")
    [[ -z "$_line" ]] && return 0
    cert_line_domains_remove "$_line" "$d"
    # РµСЃР»Рё Р»РёРЅРёСЏ РѕРїСѓСЃС‚РµР»Р° Рё РѕРЅР° РќР• РіР»Р°РІРЅР°СЏ вЂ” СѓРґР°Р»РёС‚СЊ РµС‘
    local pd=""
    pd=$(xui_get webDomain 2>/dev/null || true)
    if [[ -n "$pd" && "$_line" != "$pd" ]]; then
      cert_line_domains_load "$_line"
      if [[ ${#CERT_LINE_DOMAINS[@]} -eq 0 ]]; then
        cert_lines_remove "$_line"
        log "  Р»РёРЅРёСЏ $_line СѓРґР°Р»РµРЅР° (РїСѓСЃС‚Р°СЏ)"
      fi
    fi
    return 0
  fi
  # в”Ђв”Ђ Р РµР¶РёРј A в”Ђв”Ђ
  cert_domains_load
  local -a newlist=() x
  for x in "${CERT_DOMAINS[@]}"; do
    [[ "$x" == "$d" ]] && continue
    newlist+=("$x")
  done
  if [[ ${#newlist[@]} -ne ${#CERT_DOMAINS[@]} ]]; then
    CERT_DOMAINS=("${newlist[@]}")
    cert_domains_save
  fi
}

# Р’С‹РїСѓСЃРє РµРґРёРЅРѕРіРѕ РјСѓР»СЊС‚РёСЃРµСЂС‚Р°: stack-multi РїРѕРєСЂС‹РІР°РµС‚ Р’РЎР• РґРѕРјРµРЅС‹ РёР·
# /etc/letsencrypt/stack-domains.txt. РџРµСЂРµРІС‹РїСѓСЃРє вЂ” С‚РѕР»СЊРєРѕ РїСЂРё РёР·РјРµРЅРµРЅРёРё SAN
# РёР»Рё РёСЃС‚РµС‡РµРЅРёРё в‰¤30 РґРЅ. Р¤Р°Р№Р»-СЃРїРёСЃРѕРє вЂ” РёСЃС‚РѕС‡РЅРёРє РёСЃС‚РёРЅС‹.
# РЈРЅРёРІРµСЂСЃР°Р»СЊРЅС‹Р№ РІС‹РїСѓСЃРє РѕРґРЅРѕР№ Р»РёРЅРёРё: cert_issue_line <line-name>
#   вЂў line = РёРјСЏ Р»РёРЅРёРё (РІ A СЃРѕРІРїР°РґР°РµС‚ СЃ РґРѕРјРµРЅРѕРј РїР°РЅРµР»Рё; РІ B РјРѕР¶РµС‚ Р±С‹С‚СЊ all.<base>)
#   вЂў Р”РѕРјРµРЅС‹ SAN Р±РµСЂСѓС‚СЃСЏ РёР· cert_line_domains_load (A: stack-domains.txt;
#     B: cert-line-<РёРјСЏ>.domains).
#   вЂў РџРµСЂРІС‹Р№ -d = CN. Р”Р»СЏ РіР»Р°РІРЅРѕР№ Р»РёРЅРёРё (РёРјСЏ == РґРѕРјРµРЅ РїР°РЅРµР»Рё) CN = РёРјСЏ Р»РёРЅРёРё.
#     Р”Р»СЏ РґРѕРї. Р»РёРЅРёР№ CN = РїРµСЂРІС‹Р№ РґРѕРјРµРЅ РёР· SAN (РёРјСЏ all.<base> РЅРµ СЏРІР»СЏРµС‚СЃСЏ РґРѕРјРµРЅРѕРј).
#   вЂў DNS-С„РёР»СЊС‚СЂ: РІ TTY РїСЂРё РЅРµРІР°Р»РёРґРЅРѕРј РґРѕРјРµРЅРµ вЂ” РѕС‚РєР°С‚ + СЃРѕРѕР±С‰РµРЅРёРµ + РѕР¶РёРґР°РЅРёРµ
#     Enter; РІ РЅРµ-TTY вЂ” РёСЃРєР»СЋС‡РµРЅРёРµ РЅРµРІР°Р»РёРґРЅС‹С… СЃ warn (РґР»СЏ С‚Р°Р№РјРµСЂРѕРІ).
#   вЂў РРґРµРјРїРѕС‚РµРЅС‚РЅРѕ: РµСЃР»Рё SAN СЃРѕРІРїР°РґР°РµС‚ Рё СЃСЂРѕРє > 30 РґРЅ вЂ” РІС‹РїСѓСЃРє РЅРµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ.
cert_issue_line() {
  local line="$1"
  [[ -z "$line" ]] && { err "cert_issue_line: РїСѓСЃС‚РѕРµ РёРјСЏ Р»РёРЅРёРё"; return 1; }

  cert_mode_load >/dev/null 2>&1 || true
  cert_line_domains_load "$line"
  [[ ${#CERT_LINE_DOMAINS[@]} -eq 0 ]] && { warn "Р›РёРЅРёСЏ $line РїСѓСЃС‚Р° вЂ” РІС‹РїСѓСЃРє РЅРµ РЅСѓР¶РµРЅ"; return 0; }

  # в”Ђв”Ђ Wildcard-Р·РѕРЅР°: Р»РёРЅРёСЏ Р±Р°Р·С‹ wildcard РІС‹РїСѓСЃРєР°РµС‚СЃСЏ С‡РµСЂРµР· DNS-01 СЃ *.<Р·РѕРЅР°> в”Ђв”Ђ
  # РњСѓР»СЊС‚Рё-SAN РїРµСЂРµРІС‹РїСѓСЃРє С‡РµСЂРµР· webroot Р·Р°С‚РёСЂР°Р» "*.Р·РѕРЅР°" РёР· SAN (HTTP-01 РЅРµ СѓРјРµРµС‚
  # wildcard) вЂ” Р»РёРЅРёСЏ РѕСЃС‚Р°РІР°Р»Р°СЃСЊ Р‘Р•Р— РїРѕРєСЂС‹С‚РёСЏ, С„Р»Р°Рі wildcard РїСЂРё СЌС‚РѕРј Р¶РёР», Рё
  # cert_paths СЂР°Р·РґР°РІР°Р» СЃРµСЂС‚, РЅРµ РїРѕРєСЂС‹РІР°СЋС‰РёР№ РЅРѕРІС‹Рµ РїРѕРґРґРѕРјРµРЅС‹. РўРµРїРµСЂСЊ Р»РёРЅРёСЏ
  # wildcard-Р·РѕРЅС‹ РІСЃРµРіРґР° СЃРѕРґРµСЂР¶РёС‚ -d "<Р·РѕРЅР°>" -d "*.<Р·РѕРЅР°>" Рё РёРґС‘С‚ С‡РµСЂРµР·
  # dns-cloudflare (РµСЃР»Рё С‚РѕРєРµРЅ СЃРѕС…СЂР°РЅС‘РЅ).
  local _wc_fix=false
  if [[ -z "$WILDCARD_DOMAIN" && -f "$WILDCARD_STATE" ]]; then
    WILDCARD_DOMAIN=$(head -n 1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]' || true)
  fi
  if [[ -n "$WILDCARD_DOMAIN" && "$line" == "$WILDCARD_DOMAIN" && -f "$CF_CREDS" ]] \
     && grep -q 'dns_cloudflare_api_token' "$CF_CREDS" 2>/dev/null; then
    _wc_fix=true
  fi

  # CN
  local cn="" pd=""
  pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && pd="${PANEL_DOMAIN:-}"
  if [[ -n "$pd" && "$line" == "$pd" ]]; then
    cn="$pd"
  else
    cn="${CERT_LINE_DOMAINS[0]}"
  fi

  # в”Ђв”Ђ DNS-С„РёР»СЊС‚СЂ в”Ђв”Ђ
  local -a _valid=() _invalid=()
  local _d2 _a4 _a6 _x
  for _d2 in "${CERT_LINE_DOMAINS[@]}"; do
    _a4=$(dig +short A "$_d2" @1.1.1.1 2>/dev/null | grep -E '^[0-9.]+$' | head -1 || true)
    [[ -z "$_a4" ]] && _a4=$(dig +short A "$_d2" @8.8.8.8 2>/dev/null | grep -E '^[0-9.]+$' | head -1 || true)
    _a6=$(dig +short AAAA "$_d2" @1.1.1.1 2>/dev/null | grep ':' | head -1 || true)
    if [[ -n "$_a4" || -n "$_a6" ]]; then
      _valid+=("$_d2")
    else
      _invalid+=("$_d2")
    fi
  done

  if [[ ${#_invalid[@]} -gt 0 ]]; then
    if [[ -t 0 ]]; then
      echo
      err "Р›РёРЅРёСЏ В«$lineВ»: СЃР»РµРґСѓСЋС‰РёРµ РґРѕРјРµРЅС‹ РќР• СЂРµР·РѕР»РІСЏС‚СЃСЏ (A/AAAA):"
      for _x in "${_invalid[@]}"; do
        err "  - $_x"
      done
      err "РџРµСЂРµРІС‹РїСѓСЃРє РћРўРњР•РќРЃРќ вЂ” РёСЃРїСЂР°РІСЊ DNS Рё Р·Р°РїСѓСЃС‚Рё СЃРЅРѕРІР°."
      read -rp "$(echo -e "${B}РќР°Р¶РјРёС‚Рµ Enter С‡С‚РѕР±С‹ РїСЂРѕРґРѕР»Р¶РёС‚СЊ${N}")" _ || true
      return 1
    fi
    warn "Р›РёРЅРёСЏ В«$lineВ»: РёСЃРєР»СЋС‡Р°СЋ РЅРµРІР°Р»РёРґРЅС‹Рµ РґРѕРјРµРЅС‹ (РЅРµ-TTY):"
    for _x in "${_invalid[@]}"; do warn "  - $_x"; done
    CERT_LINE_DOMAINS=("${_valid[@]}")
    cert_line_domains_save "$line"
  fi
  [[ ${#CERT_LINE_DOMAINS[@]} -eq 0 ]] && { warn "Р›РёРЅРёСЏ В«$lineВ»: РІСЃРµ РґРѕРјРµРЅС‹ РёСЃРєР»СЋС‡РµРЅС‹"; return 1; }

  # Email LE
  le_email_load || true
  if [[ -z "$EMAIL" ]]; then
    EMAIL=$(certbot show_account 2>/dev/null | grep -iE 'Email' | awk -F: '{print $2}' | tr -d ' ' | head -1 || true)
  fi
  if [[ -z "$EMAIL" && -t 0 ]]; then
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$'
    le_email_save "$EMAIL"
  fi
  if [[ -z "$EMAIL" ]]; then
    err "cert: email Let's Encrypt РЅРµ Р·Р°РґР°РЅ. РЈРєР°Р¶Рё EMAIL РёР»Рё Р·Р°РґР°Р№ РµРіРѕ РІ СЂР°Р·РґРµР»Рµ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ."
    return 1
  fi
  le_email_save "$EMAIL" || true

  # РРґРµРјРїРѕС‚РµРЅС‚РЅРѕСЃС‚СЊ: РµСЃР»Рё SAN СЃРѕРІРїР°РґР°РµС‚ Рё СЃСЂРѕРє > 30 РґРЅ вЂ” РЅРµ РІС‹РїСѓСЃРєР°РµРј
  local ldir="/etc/letsencrypt/live/$line"
  if [[ -f "$ldir/fullchain.pem" ]]; then
    local cur_san want_san left _wc_missing=false _cf_extra=false
    cur_san=$(openssl x509 -noout -ext subjectAltName -in "$ldir/fullchain.pem" 2>/dev/null \
              | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr -d ' ' | sort | tr '\n' ',')
    if [[ "$_wc_fix" == true && "$cur_san" != *"*.$WILDCARD_DOMAIN"* ]]; then
      _wc_missing=true
      warn "Р›РёРЅРёСЏ В«$lineВ»: wildcard *.$WILDCARD_DOMAIN РїРѕС‚РµСЂСЏРЅ РІ SAN вЂ” РїРµСЂРµРІС‹РїР»СѓСЃРєР°СЋ СЃ РЅРёРј"
    fi
    # CDN-С„СЂРѕРЅС‚ РІ SAN Р±С‹С‚СЊ РЅРµ РґРѕР»Р¶РЅРѕ (СЃРµСЂС‚ РІС‹РґР°РЅ РЅРµ РЅР°РјРё): РµСЃР»Рё РѕСЃС‚Р°Р»СЃСЏ РѕС‚
    # РїСЂРµР¶РЅРёС… РІРµСЂСЃРёР№ вЂ” РїРµСЂРµРІС‹РїСѓСЃРєР°РµРј Р»РёРЅРёСЋ Р±РµР· РЅРµРіРѕ, РёРЅР°С‡Рµ РѕРЅ С‚Р°Рј С‚Р°Рє Рё Р¶РёРІС‘С‚.
    if cert_san_has_cdn_front "$cur_san"; then
      _cf_extra=true
      warn "Р›РёРЅРёСЏ В«$lineВ»: РІ SAN РµСЃС‚СЊ CDN-РґРѕРјРµРЅ (TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ CDN) вЂ” РїРµСЂРµРІС‹РїСѓСЃРєР°СЋ Р±РµР· РЅРµРіРѕ"
    fi
    want_san=$(printf '%s\n' "${CERT_LINE_DOMAINS[@]}" | sort -u | tr '\n' ',')
    if [[ "$_wc_missing" == false && "$_cf_extra" == false && "${cur_san%,}" == "${want_san%,}" ]]; then
      left=$(( ($(date -d "$(openssl x509 -enddate -noout -in "$ldir/fullchain.pem" 2>/dev/null | cut -d= -f2)" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
      if (( left > 30 )); then
        : # СЂСѓС‚РёРЅР°: Р»РёРЅРёСЏ Р°РєС‚СѓР°Р»СЊРЅР° вЂ” РјРѕР»С‡Р°
        return 0
      fi
    elif [[ "$_cf_extra" == false ]] && cert_san_set_covers "$ldir/fullchain.pem" "${CERT_LINE_DOMAINS[@]}"; then
      left=$(( ($(date -d "$(openssl x509 -enddate -noout -in "$ldir/fullchain.pem" 2>/dev/null | cut -d= -f2)" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
      if (( left > 30 )); then
        : # СЂСѓС‚РёРЅР°: РїРѕРєСЂС‹С‚Р° С‚РµРєСѓС‰РёРј СЃРµСЂС‚РѕРј вЂ” РјРѕР»С‡Р°
        return 0
      fi
    fi
  fi

  # РџСЂРёРєСЂС‹С‚РёРµ wildcard/SAN: РµСЃР»Рё Р’РЎР• РґРѕРјРµРЅС‹ Р»РёРЅРёРё СѓР¶Рµ РїРѕРєСЂС‹С‚С‹ РѕРґРЅРёРј Р¶РёРІС‹Рј
  # (>30 РґРЅ) СЃРµСЂС‚РёС„РёРєР°С‚РѕРј вЂ” РЅР°РїСЂРёРјРµСЂ wildcard'РѕРј Р·РѕРЅС‹ вЂ” РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ РІС‹РїСѓСЃРє
  # РёР·Р±С‹С‚РѕС‡РµРЅ (РёСЃС‚РѕСЂРёСЏ 28.10: Р±Р°С‚С‡ РёР· СЃС‚Р°СЂРѕРіРѕ СЂРµРµСЃС‚СЂР° Р»РёРЅРёР№ РЅР°РІС‹РїСѓСЃРєР°Р»
  # РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рµ СЃРµСЂС‚С‹ РїРѕРІРµСЂС… wildcard). РџСЂРѕРїСѓСЃРєР°РµРј Рё РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј С„Р»Р°Рі.
  if [[ "${_wc_fix:-false}" != true && "${_cf_extra:-false}" != true && ${#CERT_LINE_DOMAINS[@]} -gt 0 ]]; then
    local _cover_hit="" _cover_cd _cover_ch
    for _cover_cd in "${CERT_LINE_DOMAINS[@]}"; do
      _cover_ch=$(cert_fresh_cover "$_cover_cd") || { _cover_hit=""; break; }
      if [[ -z "$_cover_hit" ]]; then
        _cover_hit="$_cover_ch"
      elif [[ "$_cover_ch" != "$_cover_hit" ]]; then
        _cover_hit=""; break   # РґРѕРјРµРЅС‹ РїРѕРєСЂС‹С‚С‹ Р РђР—РќР«РњР СЃРµСЂС‚Р°РјРё вЂ” РїСЂРёРєСЂС‹С‚РёРµРј РЅРµ СЃС‡РёС‚Р°РµРј
      fi
    done
    if [[ -n "$_cover_hit" ]]; then
      local _cover_dir="${_cover_hit%%|*}" _cover_base="${_cover_hit#*|}"
      if [[ "$_cover_dir" != "$ldir" ]]; then
        : # СЂСѓС‚РёРЅР°: РґРѕРјРµРЅС‹ СѓР¶Рµ РїРѕРєСЂС‹С‚С‹ С‡СѓР¶РёРј СЃРµСЂС‚РѕРј вЂ” РјРѕР»С‡Р°
        if [[ -n "$_cover_base" ]]; then
          printf '%s' "$_cover_base" > "$WILDCARD_STATE" 2>/dev/null || true
          WILDCARD_DOMAIN="$_cover_base"
          log "  С„Р»Р°Рі wildcard РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ: *.$_cover_base"
        fi
        return 0
      fi
    fi
  fi

  # РђСЂРіСѓРјРµРЅС‚С‹ -d: CN РїРµСЂРІС‹Рј
  local -a cargs=()
  cargs+=(-d "$cn")
  local d
  for d in "${CERT_LINE_DOMAINS[@]}"; do
    [[ "$d" == "$cn" ]] && continue
    cargs+=(-d "$d")
  done
  if [[ "$_wc_fix" == true ]]; then
    cargs+=(-d "$WILDCARD_DOMAIN" -d "*.$WILDCARD_DOMAIN")
  fi

  log "Р’С‹РїСѓСЃРє Р»РёРЅРёРё В«$lineВ» (CN=$cn, ${#CERT_LINE_DOMAINS[@]} РґРј.)вЂ¦"
  mkdir -p /var/www/html 2>/dev/null || true
  mkdir -p /var/www/html/.well-known/acme-challenge 2>/dev/null || true
  chown -R www-data:www-data /var/www/html/.well-known 2>/dev/null || true
  chmod 755 /var/www/html /var/www/html/.well-known /var/www/html/.well-known/acme-challenge 2>/dev/null || true

  local ufw_80=false
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
    if ! ufw status 2>/dev/null | grep -qE "^80/tcp[[:space:]]+ALLOW"; then
      ufw allow 80/tcp comment "acme-temp" >/dev/null 2>&1 || true
      ufw_80=true
    fi
  fi

  local out=""
  if [[ "$_wc_fix" == true ]]; then
    # wildcard РІРѕР·РјРѕР¶РµРЅ С‚РѕР»СЊРєРѕ С‡РµСЂРµР· DNS-01 Cloudflare
    out=$(certbot certonly --dns-cloudflare \
          --dns-cloudflare-credentials "$CF_CREDS" \
          --dns-cloudflare-propagation-seconds 30 \
          --non-interactive --agree-tos \
          --email "$EMAIL" --cert-name "$line" --force-renewal \
          "${cargs[@]}" 2>&1 || true)
  else
  out=$(certbot certonly --webroot -w /var/www/html --non-interactive --agree-tos \
        --email "$EMAIL" --cert-name "$line" --force-renewal \
        "${cargs[@]}" 2>&1 || true)
  fi

  if [[ ! -f "$ldir/fullchain.pem" || ! -f "$ldir/privkey.pem" ]]; then
    local nginx_was=""
    if systemctl is-active --quiet nginx 2>/dev/null; then
      nginx_was=1; systemctl stop nginx 2>/dev/null || true
    fi
    if [[ "$_wc_fix" == true ]]; then
      out="$out
$(certbot certonly --dns-cloudflare \
      --dns-cloudflare-credentials "$CF_CREDS" \
      --dns-cloudflare-propagation-seconds 30 \
      --non-interactive --agree-tos --email "$EMAIL" --cert-name "$line" \
      --force-renewal "${cargs[@]}" 2>&1 || true)"
    else
    out="$out
$(certbot certonly --standalone --non-interactive --agree-tos \
        --email "$EMAIL" --cert-name "$line" --force-renewal \
        "${cargs[@]}" 2>&1 || true)"
    fi
    [[ -n "$nginx_was" ]] && systemctl start nginx 2>/dev/null || true
  fi

  [[ "$ufw_80" == true ]] && ufw delete allow 80/tcp >/dev/null 2>&1 || true

  if [[ -f "$ldir/fullchain.pem" && -f "$ldir/privkey.pem" ]]; then
    log "Р›РёРЅРёСЏ В«$lineВ» РіРѕС‚РѕРІР°: $ldir"
    return 0
  fi
  err "Р›РёРЅРёСЏ В«$lineВ» РќР• РІС‹РїСѓС‰РµРЅР°:"
  echo "$out" | tail -10 | sed 's/^/    /'
  [[ -t 0 ]] && read -rp "$(echo -e "${B}РќР°Р¶РјРёС‚Рµ Enter${N}")" _ || true
  return 1
}

cert_multi_issue() {
  cert_mode_load >/dev/null 2>&1 || true

  # в”Ђв”Ђ Р РµР¶РёРј A: РѕРґРЅР° Р»РёРЅРёСЏ в”Ђв”Ђ
  if [[ "${CERT_MODE:-A}" == "A" ]]; then
    cert_multi_name_resolve || { err "cert_multi_issue: РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµРёР·РІРµСЃС‚РµРЅ"; return 1; }
    cert_domains_add "$CERT_MULTI_NAME"
    cert_domains_load
    [[ ${#CERT_DOMAINS[@]} -eq 0 ]] && return 0
    local -a _final=("$CERT_MULTI_NAME") _x
    for _x in "${CERT_DOMAINS[@]}"; do
      [[ "$_x" == "$CERT_MULTI_NAME" ]] && continue
      _final+=("$_x")
    done
    CERT_DOMAINS=("${_final[@]}")
    cert_domains_save
    cert_issue_line "$CERT_MULTI_NAME"
    return $?
  fi

  # в”Ђв”Ђ Р РµР¶РёРј B: РѕР±С…РѕРґ РІСЃРµС… Р»РёРЅРёР№ в”Ђв”Ђ
  local pd=""
  pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && pd="${PANEL_DOMAIN:-}"
  if [[ -n "$pd" ]]; then
    cert_lines_add "$pd"
    cert_line_domains_add "$pd" "$pd"
  fi
  cert_lines_load
  [[ ${#CERT_LINES[@]} -eq 0 ]] && { warn "cert_multi_issue: РЅРµС‚ Р»РёРЅРёР№"; return 0; }
  local rc=0 ln
  for ln in "${CERT_LINES[@]}"; do
    cert_issue_line "$ln" || rc=1
  done
  return $rc
}

# РРґРµРјРїРѕС‚РµРЅС‚РЅС‹Р№ РІС‹РїСѓСЃРє: РµСЃР»Рё SAN РјСѓР»СЊС‚РёСЃРµСЂС‚Р° СЃРѕРІРїР°РґР°РµС‚ СЃ С„Р°Р№Р»РѕРј РґРѕРјРµРЅРѕРІ Рё
# СЃСЂРѕРє > 30 РґРЅ вЂ” РЅРёС‡РµРіРѕ РЅРµ РґРµР»Р°РµС‚. Р‘РµР·РѕРїР°СЃРЅРѕ Р·РІР°С‚СЊ РІ РєРѕРЅС†Рµ Р»СЋР±РѕР№ РѕРїРµСЂР°С†РёРё.
# РЎРёРЅС…СЂРѕРЅРёР·Р°С†РёСЏ: РїСЂРѕР№С‚РёСЃСЊ РїРѕ SNI-РєР°СЂС‚Рµ Рё РґРѕР±Р°РІРёС‚СЊ РїСЂРѕРїСѓС‰РµРЅРЅС‹Рµ РґРѕРјРµРЅС‹
# РІ stack-domains.txt / РІ Р»РёРЅРёРё. РќСѓР¶РЅРѕ, РµСЃР»Рё РёРЅР±Р°СѓРЅРґ Р±С‹Р» РїСЂРёРІСЏР·Р°РЅ Рє SNI
# РЅР°РїСЂСЏРјСѓСЋ (РјРёРЅСѓСЏ cert_domains_add) вЂ” С‚РѕРіРґР° РґРѕРјРµРЅ РµСЃС‚СЊ РІ РєР°СЂС‚Рµ, РЅРѕ РЅРµ РІ СЃРїРёСЃРєРµ.
# Р‘РµР·РѕРїР°СЃРЅРѕ: С‡СѓР¶РёРµ С†РµР»Рё (REALITY_TARGETS), panel_backend Рё agh_backend РЅРµ С‚СЂРѕРіР°РµРј.
cert_domains_sync_from_sni() {
  [[ -f "$SNI_CONF" ]] || return 0
  cert_mode_load >/dev/null 2>&1 || true

  # РЎРѕР±РёСЂР°РµРј РґРѕРјРµРЅС‹ РёР· map-Р±Р»РѕРєР° СЃ РёС… backend
  local -a rows=()
  local ln
  while IFS= read -r ln; do
    [[ -z "$ln" ]] && continue
    rows+=("$ln")
  done < <(awk '
    /^map / { inmap=1; next }
    inmap && /^}/ { inmap=0 }
    inmap && /^[[:space:]]/ && NF >= 2 {
      dom = $1; sub(/;$/, "", dom); be = $2; sub(/;$/, "", be)
      if (dom != "" && dom != "default") print dom "|" be
    }
  ' "$SNI_CONF")

  [[ ${#rows[@]} -eq 0 ]] && return 0

  local -a added=()
  local row dom be t skip is_target
  for row in "${rows[@]}"; do
    IFS='|' read -r dom be <<<"$row"
    [[ -z "$dom" ]] && continue
    # РїСЂРѕРїСѓСЃРєР°РµРј СЃР»СѓР¶РµР±РЅС‹Рµ backend'С‹
    case "$be" in
      panel_backend|agh_backend) continue ;;
    esac
    # РїСЂРѕРїСѓСЃРєР°РµРј С‡СѓР¶РёРµ С†РµР»Рё reality
    is_target=0
    for t in "${REALITY_TARGETS[@]}"; do
      [[ "$dom" == "$t" ]] && { is_target=1; break; }
    done
    [[ "$is_target" == "1" ]] && continue
    # CDN-С„СЂРѕРЅС‚ (РґРѕРјРµРЅ, РїСЂРёРІСЏР·Р°РЅРЅС‹Р№ Рє РІРЅРµС€РЅРµРјСѓ CDN) РІ SAN РЅРµ РїРѕРїР°РґР°РµС‚: СЃРµСЂС‚ РµРјСѓ
    # РЅРµ РІС‹РґР°С‘С‚СЃСЏ, TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ CDN. ORIGIN С‚РѕР¶Рµ РІ РєР°СЂС‚Рµ (cdn_frontend) Рё
    # РґРѕР±Р°РІР»СЏРµС‚СЃСЏ РєР°Рє РѕР±С‹С‡РЅС‹Р№ РґРѕРјРµРЅ вЂ” РѕРЅ РЅР°С€.
    cdn_front_domain_is "$dom" && continue
    # СѓР¶Рµ РІ СЃРїРёСЃРєРµ?
    if [[ "${CERT_MODE:-A}" == "A" ]]; then
      cert_domains_load
      [[ " ${CERT_DOMAINS[*]} " == *" $dom "* ]] && continue
      cert_domains_add "$dom"
    else
      # СЂРµР¶РёРј B: РїСЂРѕРІРµСЂСЏРµРј РІ РїСЂР°РІРёР»СЊРЅРѕР№ Р»РёРЅРёРё
      local _line=""
      _line=$(cert_line_for "$dom")
      [[ -z "$_line" ]] && continue
      cert_line_domains_load "$_line"
      [[ " ${CERT_LINE_DOMAINS[*]} " == *" $dom "* ]] && continue
      cert_line_domains_add "$_line" "$dom"
    fi
    added+=("$dom")
  done

  if [[ ${#added[@]} -gt 0 ]]; then
    log "cert-domains-sync: РґРѕР±Р°РІР»РµРЅС‹ РІ СЃРїРёСЃРѕРє: ${added[*]}"
  fi
  return 0
}

# Р•СЃС‚СЊ Р»Рё РІ SAN (СЃС‚СЂРѕРєР° В«DNS:a,DNS:bВ», Р±РµР· РїСЂРѕР±РµР»РѕРІ) РґРѕРјРµРЅ CDN-С„СЂРѕРЅС‚Р°
cert_san_has_cdn_front() {   # <cur_san>
  local san="${1:-}" d
  [[ -n "$san" ]] || return 1
  while IFS= read -r d; do
    [[ -n "$d" ]] || continue
    case ",$san," in *",$d,"*) return 0 ;; esac
  done < <(cdn_front_domains)
  return 1
}

# РЈР±СЂР°С‚СЊ CDN-С„СЂРѕРЅС‚С‹ РёР· СЃРїРёСЃРєРѕРІ SAN: РѕРЅРё РЅРµ РЅР°С€Рё (TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ CDN), Р° РІ СЃРµСЂС‚
# РїРѕРїР°РґР°Р»Рё Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё С‡РµСЂРµР· SNI-РєР°СЂС‚Сѓ.
cert_drop_cdn_fronts() {
  cert_mode_load >/dev/null 2>&1 || true
  local d _line
  while IFS= read -r d; do
    [[ -n "$d" ]] || continue
    if [[ "${CERT_MODE:-A}" == "B" ]]; then
      _line=$(cert_line_for "$d" 2>/dev/null || true)
      [[ -n "$_line" ]] || continue
      cert_line_domains_load "$_line"
      [[ " ${CERT_LINE_DOMAINS[*]} " == *" $d "* ]] || continue
    else
      cert_domains_load
      [[ " ${CERT_DOMAINS[*]} " == *" $d "* ]] || continue
    fi
    cert_domains_remove "$d"
    log "  CDN-РґРѕРјРµРЅ $d РёСЃРєР»СЋС‡С‘РЅ РёР· SAN (СЃРµСЂС‚ РІС‹РґР°С‘С‚ CDN, РЅРµ РјС‹)"
  done < <(cdn_front_domains)
}

# РРґРµРјРїРѕС‚РµРЅС‚РЅР°СЏ РїРµСЂРµСЃР±РѕСЂРєР° СЃРµСЂС‚РѕРІ.
#   вЂў Р РµР¶РёРј A вЂ” РѕРґРЅР° Р»РёРЅРёСЏ (РёРјСЏ = РґРѕРјРµРЅ РїР°РЅРµР»Рё).
#   вЂў Р РµР¶РёРј B вЂ” РѕР±С…РѕРґ РІСЃРµС… Р»РёРЅРёР№ (РіР»Р°РІРЅР°СЏ + РґРѕРї. all.<base>).
#   вЂў Р•СЃР»Рё SAN СЃРѕРІРїР°РґР°РµС‚ Рё СЃСЂРѕРє > 30 РґРЅ вЂ” РїРµСЂРµРІС‹РїСѓСЃРє РЅРµ Р·Р°РїСѓСЃРєР°РµС‚СЃСЏ.
#   вЂў Р’С‹РІРѕРґРёС‚ СЃРѕСЃС‚РѕСЏРЅРёРµ РєР°Р¶РґРѕР№ Р»РёРЅРёРё.
# РџРѕРєСЂС‹РІР°РµС‚ Р»Рё SAN СЃРµСЂС‚Р° ($1) РІСЃРµ РїРµСЂРµС‡РёСЃР»РµРЅРЅС‹Рµ РґРѕРјРµРЅС‹ вЂ” С‚РѕС‡РЅРѕ РёР»Рё wildcard *.Р±Р°Р·Р°.
# Р—Р°С‰РёС‚Р° РѕС‚ РїРµСЂРµР·Р°С‚РёСЂР°РЅРёСЏ wildcard-СЃРµСЂС‚Р° SAN-РїРµСЂРµРІС‹РїСѓСЃРєРѕРј (Рї.10.9/СЃР°РјРѕР»РµС‡РµРЅРёРµ).
cert_san_set_covers() {
  local certf="$1"; shift
  local san dom
  [[ -f "$certf" ]] || return 1
  san=$(openssl x509 -noout -ext subjectAltName -in "$certf" 2>/dev/null \
        | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr -d ' ')
  [[ -n "$san" ]] || return 1
  for dom in "$@"; do
    grep -qx "$dom" <<<"$san" && continue
    local base="${dom#*.}"
    if [[ "$dom" == *.* && "$dom" != "$base" ]] && grep -qx "*.$base" <<<"$san"; then
      continue
    fi
    return 1
  done
  return 0
}

cert_batch_flush() {
  cert_mode_load >/dev/null 2>&1 || true
  # РџРµСЂРµРґ РїРµСЂРµРІС‹РїСѓСЃРєРѕРј вЂ” СЃРёРЅС…СЂРѕРЅРёР·РёСЂРѕРІР°С‚СЊ СЃРїРёСЃРѕРє СЃ SNI-РєР°СЂС‚РѕР№ (РјРѕРіСѓС‚ Р±С‹С‚СЊ
  # РїСЂРѕРїСѓС‰РµРЅРЅС‹Рµ РґРѕРјРµРЅС‹, РµСЃР»Рё РёРЅР±Р°СѓРЅРґ РєРѕРіРґР°-С‚Рѕ Р±С‹Р» РїСЂРёРІСЏР·Р°РЅ Рє SNI РЅР°РїСЂСЏРјСѓСЋ).
  cert_domains_sync_from_sni >/dev/null 2>&1 || true
  # CDN-С„СЂРѕРЅС‚С‹ (cdn.*) РІ SAN РЅРµ РЅСѓР¶РЅС‹: СЃРµСЂС‚ РЅР° РЅРёС… РЅРµ РІС‹РґР°С‘С‚СЃСЏ, TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚
  # CDN. Р•СЃР»Рё РѕРЅРё С‚Р°Рј РѕСЃС‚Р°Р»РёСЃСЊ РѕС‚ РїСЂРµР¶РЅРёС… РІРµСЂСЃРёР№ вЂ” РІС‹РєРёРґС‹РІР°РµРј РёР· СЃРїРёСЃРєР°; РµСЃР»Рё
  # РёР·-Р·Р° СЌС‚РѕРіРѕ SAN РёР·РјРµРЅРёР»СЃСЏ, cert_issue_line РїРµСЂРµРІС‹РїСѓСЃС‚РёС‚ Р»РёРЅРёСЋ Р±РµР· РЅРёС….
  cert_drop_cdn_fronts || true

  # в”Ђв”Ђ Р РµР¶РёРј A в”Ђв”Ђ
  if [[ "${CERT_MODE:-A}" == "A" ]]; then
    cert_multi_name_resolve || { warn "cert_batch_flush: РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµРёР·РІРµСЃС‚РµРЅ"; return 0; }
    cert_domains_load
    if [[ ${#CERT_DOMAINS[@]} -eq 0 ]]; then
      warn "РЎРїРёСЃРѕРє РґРѕРјРµРЅРѕРІ (stack-domains.txt) РїСѓСЃС‚ вЂ” РїРµСЂРµРІС‹РїСѓСЃРє РЅРµ С‚СЂРµР±СѓРµС‚СЃСЏ"
      return 0
    fi
    local ldir="/etc/letsencrypt/live/$CERT_MULTI_NAME"
    if [[ -f "$ldir/fullchain.pem" ]]; then
      local cur_san want_san left
      cur_san=$(openssl x509 -noout -ext subjectAltName -in "$ldir/fullchain.pem" 2>/dev/null \
                | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr -d ' ' | sort | tr '\n' ',')
      want_san=$(printf '%s\n' "${CERT_DOMAINS[@]}" | sort -u | tr '\n' ',')
      if [[ "${cur_san%,}" == "${want_san%,}" ]]; then
        left=$(( ($(date -d "$(openssl x509 -enddate -noout -in "$ldir/fullchain.pem" 2>/dev/null | cut -d= -f2)" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
        if (( left > 30 )); then
          : # СЂСѓС‚РёРЅР°: Р»РёРЅРёСЏ Р°РєС‚СѓР°Р»СЊРЅР° вЂ” РјРѕР»С‡Р°
          return 0
        fi
        warn "Р›РёРЅРёСЏ В«$CERT_MULTI_NAMEВ»: СЃСЂРѕРє ~$left РґРЅ (<=30) вЂ” РѕР±РЅРѕРІР»СЏСЋ"
      else
        if cert_san_has_cdn_front "$cur_san"; then
          warn "Р›РёРЅРёСЏ В«$CERT_MULTI_NAMEВ»: РІ SAN РµСЃС‚СЊ CDN-РґРѕРјРµРЅ (TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ CDN) вЂ” РїРµСЂРµРІС‹РїСѓСЃРєР°СЋ Р±РµР· РЅРµРіРѕ"
        elif cert_san_set_covers "$ldir/fullchain.pem" "${CERT_DOMAINS[@]}"; then
          left=$(( ($(date -d "$(openssl x509 -enddate -noout -in "$ldir/fullchain.pem" 2>/dev/null | cut -d= -f2)" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
          if (( left > 30 )); then
            : # СЂСѓС‚РёРЅР°: РїРѕР»РЅРѕСЃС‚СЊСЋ РїРѕРєСЂС‹С‚Р° С‚РµРєСѓС‰РёРј СЃРµСЂС‚РѕРј вЂ” РјРѕР»С‡Р°
            return 0
          fi
        fi
        warn "Р›РёРЅРёСЏ В«$CERT_MULTI_NAMEВ»: SAN РёР·РјРµРЅРёР»СЃСЏ"
        echo "      Р±С‹Р»Рѕ:  ${cur_san%,}"
        echo "      СЃС‚Р°Р»Рѕ: ${want_san%,}"
      fi
    else
      log "Р›РёРЅРёСЏ В«$CERT_MULTI_NAMEВ»: СЃРµСЂС‚Р° РЅРµС‚ вЂ” РІС‹РїСѓСЃРєР°СЋ"
      echo "      SAN: $(printf '%s\\n' "${CERT_DOMAINS[@]}" | sort -u | tr '\\n' ',')"
    fi
    cert_multi_issue
    return $?
  fi

  # в”Ђв”Ђ Р РµР¶РёРј B: РѕР±С…РѕРґ Р»РёРЅРёР№ в”Ђв”Ђ
  cert_lines_canon_migrate   # РЅР°СЃР»РµРґРёРµ В«РґРѕРјРµРЅ = Р»РёРЅРёСЏВ» в†’ РІ РєР°РЅРѕРЅРёС‡РµСЃРєРёРµ Р»РёРЅРёРё
  local pd=""
  pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && pd="${PANEL_DOMAIN:-}"
  if [[ -n "$pd" ]]; then
    cert_lines_add "$pd"
    cert_line_domains_add "$pd" "$pd"
  fi
  cert_lines_load
  if [[ ${#CERT_LINES[@]} -eq 0 ]]; then
    warn "cert_batch_flush: РЅРµС‚ Р»РёРЅРёР№ (СЂРµР¶РёРј B)"
    return 0
  fi
  log "Р РµР¶РёРј B: Р»РёРЅРёР№ вЂ” ${#CERT_LINES[@]}"
  local rc=0 ln d
  for ln in "${CERT_LINES[@]}"; do
    cert_line_domains_load "$ln"
    if [[ ${#CERT_LINE_DOMAINS[@]} -eq 0 ]]; then
      warn "  Р›РёРЅРёСЏ В«$lnВ» РїСѓСЃС‚Р° вЂ” РїСЂРѕРїСѓСЃРє"
      continue
    fi
    cert_issue_line "$ln" || rc=1
  done
  return $rc
}

# РџСЂРѕСЃРјРѕС‚СЂ: СЃРїРёСЃРѕРє РґРѕРјРµРЅРѕРІ + СЃРІРµРґРµРЅРёСЏ Рѕ СЃРµСЂС‚Р°С…
certs_view() {
  cert_mode_load >/dev/null 2>&1 || true
  cert_multi_name_resolve >/dev/null 2>&1 || true
  line; echo -e "${B}   РЎР•Р РўРР¤РРљРђРўР« вЂ” РћР‘Р—РћР ${N}"; line
  if [[ "${CERT_MODE:-A}" == "B" ]]; then
    echo "  Р РµР¶РёРј: B вЂ” РѕС‚РґРµР»СЊРЅС‹Рµ Р»РёРЅРёРё СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ РїРѕ Р±Р°Р·РѕРІС‹Рј РґРѕРјРµРЅР°Рј"
    echo -e "${B}в–ё Р¤Р°РєС‚РёС‡РµСЃРєРёРµ Р»РёРЅРёРё Рё РёС… СЃРµСЂС‚РёС„РёРєР°С‚С‹:${N}"
    cert_lines_load >/dev/null 2>&1 || true
    if [[ ${#CERT_LINES[@]} -gt 0 ]]; then
      local _ln _i=1 _d
      for _ln in "${CERT_LINES[@]}"; do
        echo "  Р›РёРЅРёСЏ $_i: $_ln"
        cert_line_domains_load "$_ln" >/dev/null 2>&1 || true
        if [[ ${#CERT_LINE_DOMAINS[@]} -eq 0 ]]; then
          echo "      (СЃРїРёСЃРѕРє РґРѕРјРµРЅРѕРІ РїСѓСЃС‚)"
        else
          for _d in "${CERT_LINE_DOMAINS[@]}"; do
            [[ -n "$_d" ]] && echo "      - $_d"
          done
        fi
        if [[ -f "/etc/letsencrypt/live/$_ln/fullchain.pem" ]]; then
          echo "      РЎРµСЂС‚РёС„РёРєР°С‚: СѓСЃС‚Р°РЅРѕРІР»РµРЅ"
        else
          echo "      РЎРµСЂС‚РёС„РёРєР°С‚: РЅРµ РІС‹РїСѓС‰РµРЅ"
        fi
        _i=$((_i+1))
      done
    else
      echo "  (Р»РёРЅРёРё РµС‰С‘ РЅРµ СЃС„РѕСЂРјРёСЂРѕРІР°РЅС‹)"
    fi
  else
    echo "  Р РµР¶РёРј: A вЂ” РѕРґРЅР° SAN-Р»РёРЅРёСЏ"
    echo "  РРјСЏ Р»РёРЅРёРё (= РґРѕРјРµРЅ РїР°РЅРµР»Рё): ${CERT_MULTI_NAME:-<РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµ Р·Р°РґР°РЅ>}"
    echo -e "${B}в–ё Р”РѕРјРµРЅС‹ РІ SAN-СЃРїРёСЃРєРµ ($CERT_DOMAINS_FILE):${N}"
    if [[ -s "$CERT_DOMAINS_FILE" ]]; then
      local i=1 d
      while IFS= read -r d; do
        d="$(printf '%s' "$d" | tr -d '[:space:]')"
        [[ -z "$d" ]] && continue
        printf "  %2d) %s\n" "$i" "$d"; i=$((i+1))
      done < "$CERT_DOMAINS_FILE"
    else
      echo "  (СЃРїРёСЃРѕРє SAN РµС‰С‘ РЅРµ СЃРѕР·РґР°РЅ)"
    fi
  fi
  echo
  local ldir="/etc/letsencrypt/live/$CERT_MULTI_NAME"
  if [[ -f "$ldir/fullchain.pem" ]]; then
    echo -e "${B}в–ё РЎРµСЂС‚РёС„РёРєР°С‚ РїР°РЅРµР»Рё / РјСѓР»СЊС‚РёСЃРµСЂС‚ В«$CERT_MULTI_NAMEВ»:${N}"
    echo "  РџСѓС‚СЊ:  $ldir"
    local subj end left
    subj=$(openssl x509 -noout -subject -in "$ldir/fullchain.pem" 2>/dev/null | sed 's/^subject= *//')
    end=$(openssl x509 -noout -enddate -in "$ldir/fullchain.pem" 2>/dev/null | cut -d= -f2)
    left=$(( ($(date -d "$end" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
    echo "  Subject: $subj"
    echo "  РСЃС‚РµРєР°РµС‚: $end (~$left РґРЅ)"
    echo "  SAN:"
    openssl x509 -noout -ext subjectAltName -in "$ldir/fullchain.pem" 2>/dev/null \
      | tail -n +2 | tr ',' '\n' | sed 's/^ */    /' || true
  else
    echo -e "${B}в–ё РњСѓР»СЊС‚РёСЃРµСЂС‚ $CERT_MULTI_NAME:${N}  РќР• РІС‹РїСѓС‰РµРЅ"
  fi
  echo
  echo -e "${B}в–ё Р’СЃРµ СЃРµСЂС‚РёС„РёРєР°С‚С‹ РІ /etc/letsencrypt/live/:${N}"
  certbot certificates 2>/dev/null | sed 's/^/  /' || true
  echo
  le_email_load || true
  echo -e "${B}в–ё Email Let's Encrypt:${N} ${EMAIL:-<РЅРµ Р·Р°РґР°РЅ>}   (С„Р°Р№Р»: $LE_EMAIL_FILE)"
  pause
}

cert_issue() {
  local d="$1"
  # РЅРµРІРёРґРёРјС‹Р№ С…РІРѕСЃС‚ (РїСЂРѕР±РµР»/CR РёР· Р‘Р” РёР»Рё ans-С„Р°Р№Р»Р°) Р»РѕРјР°РµС‚ РїСѓС‚Рё live/<РґРѕРјРµРЅ> вЂ”
  # certbot РЅРѕСЂРјР°Р»РёР·СѓРµС‚ РёРјСЏ, СЃРєСЂРёРїС‚ РёС‰РµС‚ С„Р°Р№Р»С‹ РїРѕ В«РіСЂСЏР·РЅРѕРјСѓВ» РїСѓС‚Рё Рё РЅРµ РЅР°С…РѕРґРёС‚
  d="$(printf '%s' "$d" | tr -d '[:space:]')"
  # Р–РЃРЎРўРљРР™ Р—РђРџР Р•Рў: С†РµР»Рё С‡СѓР¶РѕРіРѕ reality вЂ” РќР• РЅР°С€Рё РґРѕРјРµРЅС‹. Let's Encrypt СЃРµСЂС‚
  # РЅР° РЅРёС… РЅРµ РІС‹РґР°СЃС‚ (HTTP-01/DNS-01 РЅРµРґРѕСЃС‚СѓРїРЅС‹), Р° СЃРїСЂР°С€РёРІР°С‚СЊ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ
  # В«РєР°РєРѕР№ СЃРµСЂС‚РёС„РёРєР°С‚ РґР»СЏ www.samsung.comВ» вЂ” Р±Р°Рі, РєР°РєРёРјРё Р±С‹ РїСѓС‚СЏРјРё РґРѕРјРµРЅ
  # СЃСЋРґР° РЅРё РїСЂРёРµС…Р°Р» (СѓС‚С‘РєС€РёР№ serverNames РёР· СЃС‚Р°СЂРѕР№ Р‘Р” Рё С‚.Рї.).
  # Р”РѕРјРµРЅ, РїСЂРёРІСЏР·Р°РЅРЅС‹Р№ Рє РІРЅРµС€РЅРµРјСѓ CDN, С‚РѕР¶Рµ РЅРµ РЅР°С€: TLS РґР»СЏ CDN-С„СЂРѕРЅС‚Р°
  # Р·Р°РІРµСЂС€Р°РµС‚СЃСЏ РЅР° СЃС‚РѕСЂРѕРЅРµ CDN, РїРѕСЌС‚РѕРјСѓ СЃРµСЂС‚РёС„РёРєР°С‚ Let's Encrypt РЅР° РЅРµРіРѕ
  # РІС‹РїСѓСЃРєР°С‚СЊ РЅРµР»СЊР·СЏ. РЎРµСЂС‚РёС„РёРєР°С‚ РЅСѓР¶РµРЅ С‚РѕР»СЊРєРѕ РґР»СЏ ORIGIN-РґРѕРјРµРЅР°.
  if cdn_front_domain_is "$d"; then
    warn "cert_issue: В«$dВ» вЂ” CDN-РґРѕРјРµРЅ, TLS Р·Р°РІРµСЂС€Р°РµС‚ CDN; СЃРµСЂС‚РёС„РёРєР°С‚ РЅРµ РІС‹РїСѓСЃРєР°РµС‚СЃСЏ"
    return 1
  fi
  local _rt_x
  for _rt_x in "${REALITY_TARGETS[@]}"; do
    if [[ "$d" == "$_rt_x" ]]; then
      warn "cert_issue: В«$dВ» вЂ” С†РµР»СЊ С‡СѓР¶РѕРіРѕ reality, СЃРµСЂС‚ РЅРµ РЅСѓР¶РµРЅ Рё РЅРµРІРѕР·РјРѕР¶РµРЅ (РїСЂРѕРїСѓСЃРєР°СЋ)"
      return 1
    fi
  done

  local dir="/etc/letsencrypt/live/$d" arch="/etc/letsencrypt/archive/$d"

  # self-heal: С„Р»Р°Рі wildcard РјРѕРі РЅРµ Р·Р°РіСЂСѓР·РёС‚СЊСЃСЏ (source Р±РµР· С‚РѕС‡РєРё РІС…РѕРґР°)
  if [[ -z "$WILDCARD_DOMAIN" && -f "$WILDCARD_STATE" ]]; then
    WILDCARD_DOMAIN=$(head -n 1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]' || true)
  fi

  local in_wc_zone=false
  [[ -n "$WILDCARD_DOMAIN" && ( "$d" == "$WILDCARD_DOMAIN" || "$d" == *."$WILDCARD_DOMAIN" ) ]] && in_wc_zone=true

  # email РѕР±СЏР·Р°С‚РµР»РµРЅ: РїСѓСЃС‚РѕР№ --email РјРµРЅСЏРµС‚ РїР°СЂР°РјРµС‚СЂС‹ Р°РєРєР°СѓРЅС‚Р° вЂ” certbot РЅРµ
  # РїРµСЂРµРёСЃРїРѕР»СЊР·СѓРµС‚ СЃСѓС‰РµСЃС‚РІСѓСЋС‰СѓСЋ Р»РёРЅРёСЋ Рё РїР»РѕРґРёС‚ РґСѓР±Р»Рё (-0001, -0002вЂ¦)
  # Р’РђР–РќРћ: Р±Р°Р·Сѓ РѕС‚СЂРµР·Р°РµРј С‚РѕР»СЊРєРѕ РµСЃР»Рё РѕСЃС‚Р°С‘С‚СЃСЏ РµС‰С‘ С‚РѕС‡РєР° вЂ” РёРЅР°С‡Рµ РґР»СЏ РґРѕРјРµРЅР°
  # РІРёРґР° zone.ru (РґРІРµ РјРµС‚РєРё) РїРѕР»СѓС‡Р°РµРј admin@ru Рё РѕС‚РєР°Р· ACME-СЃРµСЂРІРµСЂР°.
  le_email_load || true
  if [[ -z "$EMAIL" && -t 0 && "${STACK_AUTOPILOT:-0}" != 1 ]]; then
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$'
    le_email_save "$EMAIL"
  fi
  [[ -n "$EMAIL" ]] || { err "  cert $d: email Let's Encrypt РЅРµ Р·Р°РґР°РЅ вЂ” СѓРєР°Р¶Рё EMAIL РёР»Рё Р·Р°РґР°Р№ РµРіРѕ РІ СЂР°Р·РґРµР»Рµ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ"; return 1; }
  le_email_save "$EMAIL" || true

  # --- РїСЂРѕРІРµСЂРєР°: СЃРµСЂС‚РёС„РёРєР°С‚ СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ в†’ РїРµСЂРµСѓСЃС‚Р°РЅР°РІР»РёРІР°С‚СЊ РЅРµ РЅСѓР¶РЅРѕ ---
  if [[ "$in_wc_zone" == true ]]; then
    local wdir="/etc/letsencrypt/live/$WILDCARD_DOMAIN"
    if [[ -f "$wdir/fullchain.pem" && -f "$wdir/privkey.pem" ]]; then
      : # СЂСѓС‚РёРЅР°: wildcard СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” РјРѕР»С‡Р°
      return 0
    fi
  fi
  # --- Р°РІС‚Рѕ-РїРѕРёСЃРє СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕРіРѕ СЃРµСЂС‚РёС„РёРєР°С‚Р° РїРѕ SAN (СЂР°Р±РѕС‚Р°РµС‚ РґР°Р¶Рµ Р±РµР· С„Р»Р°РіР° wildcard) ---
  # Р”РµР»Р°С‚СЊ РµРіРѕ Р”Рћ РїСЂРѕРІРµСЂРєРё РїРµСЂСЃРѕРЅР°Р»СЊРЅРѕР№ Р»РёРЅРёРё: wildcard РґРѕР»Р¶РµРЅ РёРјРµС‚СЊ РїСЂРёРѕСЂРёС‚РµС‚
  # РґР»СЏ РїРѕРґРґРѕРјРµРЅРѕРІ, РґР°Р¶Рµ РµСЃР»Рё СЂР°РЅРµРµ РїРѕ РѕС€РёР±РєРµ СѓР¶Рµ РІС‹РїСѓСЃС‚РёР»Рё РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ cert.
  local hit wcdir wcbase
  hit=$(find_covering_cert "$d") || hit=""
  if [[ -n "$hit" ]]; then
    wcdir="${hit%%|*}"; wcbase="${hit#*|}"
    : # СЂСѓС‚РёРЅР°: РЅР°Р№РґРµРЅ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Р№ СЃРµСЂС‚ РїРѕ SAN вЂ” РјРѕР»С‡Р°
    cert_mirror_to_certroot "$wcdir" "$d" >/dev/null 2>&1 || true
    if [[ -n "$wcbase" ]]; then
      echo "$wcbase" > "$WILDCARD_STATE" 2>/dev/null || true
      WILDCARD_DOMAIN="$wcbase"
      log "  С„Р»Р°Рі wildcard РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ: *.$wcbase"
    fi
    return 0
  fi
  if [[ -f "$dir/fullchain.pem" && -f "$dir/privkey.pem" ]]; then
    : # СЂСѓС‚РёРЅР°: РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚ СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” РјРѕР»С‡Р°
    return 0
  fi

  # --- РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РёР· archive/ (РµСЃР»Рё live-СЃСЃС‹Р»РєРё РїРѕС‚РµСЂСЏРЅС‹) ---
  if [[ -d "$arch" ]]; then
    log "  cert $d: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РёР· archive/"
    mkdir -p "$dir" 2>/dev/null || true
    local n=""
    n=$(ls -1 "$arch"/fullchain*.pem 2>/dev/null | sed -E 's/.*fullchain([0-9]+)\.pem/\1/' | sort -n | tail -1 || true)
    if [[ -n "$n" ]]; then
      local f
      for f in cert chain fullchain privkey; do
        [[ -f "$arch/$f$n.pem" ]] && ln -sf "../../archive/$d/$f$n.pem" "$dir/$f.pem"
      done
      chmod 700 "$dir" 2>/dev/null || true
      if [[ -f "$dir/fullchain.pem" && -f "$dir/privkey.pem" ]]; then
        log "  РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ (v$n)"
        # РїСѓС‚Рё вЂ” live/ (РµРґРёРЅРѕРµ РјРµСЃС‚Рѕ)
        cert_mirror_to_certroot "$dir" "$d" >/dev/null 2>&1 || true
        return 0
      fi
    fi
  fi

  # --- Р РµР¶РёРј Р»РёРЅРёР№ (A/B): РґРѕРјРµРЅ Р¶РёРІС‘С‚ РІ РћР”РќРћР™ Р»РёРЅРёРё ---------------------------
  # Р Р°РЅСЊС€Рµ cert_issue РІСЃРµРіРґР° РІС‹РїСѓСЃРєР°Р» РїРµСЂСЃРѕРЅР°Р»СЊРЅСѓСЋ Р»РёРЅРёСЋ live/<РґРѕРјРµРЅ>, РґР°Р¶Рµ
  # РєРѕРіРґР° СЂР°Р±РѕС‚Р°Р»Р° Р»РѕРіРёРєР° Р»РёРЅРёР№ (РІС‹Р±РѕСЂ В«4В» РІ РјР°СЃС‚РµСЂРµ = РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рµ + СЂРµР¶РёРј B).
  # Р”РѕРјРµРЅ РѕРєР°Р·С‹РІР°Р»СЃСЏ РІ Р”Р’РЈРҐ Р»РёРЅРёСЏС…: СЃРІРѕСЏ РїРµСЂСЃРѕРЅР°Р»СЊРЅР°СЏ + SAN Р»РёРЅРёРё Р±Р°Р·С‹, РєСѓРґР°
  # РµРіРѕ РІРѕР·РІСЂР°С‰Р°Р» cert_domains_sync_from_sni РїСЂРё РїРµСЂРІРѕРј РїРµСЂРµРІС‹РїСѓСЃРєРµ
  # (РєР»Р°СЃСЃРёС‡РµСЃРєРёР№ РїСЂРёРјРµСЂ вЂ” tg web proxy: live/tg.<Р±Р°Р·Р°> + tg.<Р±Р°Р·Р°> РІ SAN
  # Р»РёРЅРёРё РїР°РЅРµР»Рё). РўРµРїРµСЂСЊ РґРѕРјРµРЅ СЂРµРіРёСЃС‚СЂРёСЂСѓРµС‚СЃСЏ РІ СЃРІРѕРµР№ Р»РёРЅРёРё Рё РІС‹РїСѓСЃРєР°РµС‚СЃСЏ/
  # РѕР±РЅРѕРІР»СЏРµС‚СЃСЏ РЎРђРњРђ Р›РРќРРЇ (cert_issue_line РёРґРµРјРїРѕС‚РµРЅС‚РµРЅ). РџРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№
  # РІС‹РїСѓСЃРє РЅРёР¶Рµ вЂ” С„РѕР»Р±СЌРє (СЂРµР¶РёРј РЅРµ РѕРїСЂРµРґРµР»С‘РЅ/Р»РёРЅРёСЏ РЅРµ РІС‹С‡РёСЃР»РёР»Р°СЃСЊ/РѕС‚РєР°Р·).
  cert_mode_load >/dev/null 2>&1 || true
  local _cline=""
  if [[ -n "${CERT_MODE:-}" ]]; then
    if [[ "$CERT_MODE" == "A" ]]; then
      cert_multi_name_resolve >/dev/null 2>&1 && _cline="$CERT_MULTI_NAME"
    else
      _cline=$(cert_line_for "$d" 2>/dev/null || true)
    fi
  fi
  if [[ -n "$_cline" && "$_cline" != "$d" ]]; then
    if [[ "$CERT_MODE" == "A" ]]; then
      cert_domains_add "$d"
    else
      cert_line_domains_add "$_cline" "$d"
    fi
    if [[ "${CERT_DEFER:-0}" == "1" ]]; then
      log "  cert $d: Р·Р°РїРёСЃР°РЅ РІ Р»РёРЅРёСЋ $_cline вЂ” РІС‹РїСѓСЃРє РїР°С‡РєРѕР№ РІ РєРѕРЅС†Рµ СѓСЃС‚Р°РЅРѕРІРєРё"
      return 0
    fi
    if cert_issue_line "$_cline"; then
      # РЅРµ-TTY С„РёР»СЊС‚СЂ cert_issue_line РјРѕРі РёСЃРєР»СЋС‡РёС‚СЊ РЅРµСЂР°Р·СЂРµС€РёРјС‹Р№ РґРѕРјРµРЅ Рё
      # РІС‹РїСѓСЃС‚РёС‚СЊ Р»РёРЅРёСЋ Р‘Р•Р— РЅРµРіРѕ вЂ” С‚РѕРіРґР° СѓСЃРїРµС… Р·РґРµСЃСЊ Р±С‹Р» Р±С‹ Р»РѕР¶РЅС‹Рј
      if cert_san_set_covers "/etc/letsencrypt/live/$_cline/fullchain.pem" "$d"; then
        return 0
      fi
      warn "  cert $d: Р»РёРЅРёСЏ $_cline РІС‹РїСѓС‰РµРЅР° Р±РµР· $d (РЅРµ СЂРµР·РѕР»РІРёС‚СЃСЏ?) вЂ” С„РѕР»Р±СЌРє РЅР° РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№"
    else
      warn "  cert $d: РІС‹РїСѓСЃРє Р»РёРЅРёРё $_cline РЅРµ СѓРґР°Р»СЃСЏ вЂ” С„РѕР»Р±СЌРє РЅР° РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚"
    fi
  fi

  # --- РІС‹РїСѓСЃРє: РІС‹Р±РѕСЂ С‚РёРїР° СЃРµСЂС‚РёС„РёРєР°С‚Р° ---
  # CERT_MODE_CHOICE вЂ” РІС‹Р±РѕСЂ Р·Р°РїРѕРјРёРЅР°РµС‚СЃСЏ РЅР° СЃРµСЃСЃРёСЋ (1 РІРѕРїСЂРѕСЃ РЅР° СѓСЃС‚Р°РЅРѕРІРєСѓ,
  # Р° РЅРµ РЅР° РєР°Р¶РґС‹Р№ РёРЅР±Р°СѓРЅРґ). Р’ ans-Р°РІС‚РѕСѓСЃС‚Р°РЅРѕРІРєР°С… (stdin РЅРµ TTY) РІРѕРїСЂРѕСЃ
  # РЅРµ Р·Р°РґР°С‘С‚СЃСЏ вЂ” СЂРµР¶РёРј СѓР¶Рµ РІС‹Р±СЂР°РЅ РІРѕРїСЂРѕСЃРѕРј 2b.
  local mode="personal"
  local wbase="${d#*.}"
  [[ "$wbase" != *.* ]] && wbase="$d"   # d вЂ” СЃР°Рј Р±Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ
  if [[ -n "${CERT_MODE_CHOICE:-}" ]]; then
    mode="$CERT_MODE_CHOICE"
  elif [[ -t 0 && "${STACK_AUTOPILOT:-0}" != 1 && "$security" != "tls" ]]; then
    echo "  РљР°РєРѕР№ СЃРµСЂС‚РёС„РёРєР°С‚ РІС‹РїСѓСЃС‚РёС‚СЊ РґР»СЏ $d?"
    echo "   1) Wildcard *.$wbase вЂ” Cloudflare DNS-01, РїРѕРєСЂРѕРµС‚ $wbase Рё РІСЃРµ РїРѕРґРґРѕРјРµРЅС‹"
    echo "   2) РћР±С‹С‡РЅС‹Р№ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ вЂ” С‚РѕР»СЊРєРѕ $d (HTTP-01)"
    local cm=""
    ask cm "Р’С‹Р±РѕСЂ [1/2]" "2" '^[12]$'
    if [[ "$cm" == "1" ]]; then
      mode="wildcard"
      CERT_MODE_CHOICE="wildcard"
    else
      CERT_MODE_CHOICE="personal"
    fi
  fi

  if [[ "$mode" == "wildcard" ]]; then
    if cert_wildcard_issue "${WILDCARD_DOMAIN:-$wbase}"; then
      log "  cert $d: РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ wildcard *.${WILDCARD_DOMAIN:-$wbase}"
      return 0
    fi
    if [[ "${STACK_AUTOPILOT:-0}" == 1 ]]; then
      err "  РћРЁРР‘РљРђ: wildcard РґР»СЏ $d РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” С„РѕР»Р±СЌРє РЅР° РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№"
    else
      err "  РћРЁРР‘РљРђ: wildcard РґР»СЏ $d РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ. РќР°Р¶РјРёС‚Рµ Enter РґР»СЏ РїСЂРѕРґРѕР»Р¶РµРЅРёСЏ."
    fi
    cert_error_pause
    warn "  wildcard РќР• РІС‹РїСѓС‰РµРЅ (С‚РѕРєРµРЅ Cloudflare / DNS-01?) вЂ” РґР»СЏ $d РІС‹РїСѓСЃРєР°СЋ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№"
    warn "  Р’РђР–РќРћ: РѕСЃС‚Р°Р»СЊРЅС‹Рµ СЃРµСЂС‚С‹ СЌС‚РѕР№ СѓСЃС‚Р°РЅРѕРІРєРё С‚РѕР¶Рµ РїРѕР№РґСѓС‚ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹РјРё (С„РѕР»Р±СЌРє СЃРµСЃСЃРёРё)."
    warn "  Р’РµСЂРЅСѓС‚СЊ wildcard РїРѕС‚РѕРј: РјРµРЅСЋ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ в†’ Wildcard Cloudflare в†’ РІРєР»СЋС‡РёС‚СЊ,"
    warn "  Р·Р°С‚РµРј РїРµСЂРµРїСЂРёРІСЏР·Р°С‚СЊ РїСѓС‚Рё (Рї.10 вЂ” РїРµСЂРµСЃР±РѕСЂРєР°). РџСЂРёС‡РёРЅР° РѕС‚РєР°Р·Р° РІС‹С€Рµ РІ РІС‹РІРѕРґРµ."
    CERT_MODE_CHOICE="personal"
  fi

  # DNS-РїСЂРѕРІРµСЂРєР° (dual-stack): A-Р·Р°РїРёСЃСЊ СЃРІРµСЂСЏРµС‚СЃСЏ СЃ IPv4 СЃРµСЂРІРµСЂР°, AAAA вЂ” СЃ IPv6.
  # РЎРѕРІРїР°РґРµРЅРёРµ Р›Р®Р‘РћР™ РїР°СЂС‹ = OK (Р»РѕР¶РЅС‹Р№ mismatch СЂР°РЅСЊС€Рµ Р±С‹Р» РёР·-Р·Р° IPv6-РѕС‚РІРµС‚Р° ifconfig.me).
  local nA nAAAA
  nA=$(dig +short A "$d" @8.8.8.8 2>/dev/null | grep -cE '^[0-9]+(\.[0-9]+){3}$' || true)
  nAAAA=$(dig +short AAAA "$d" @8.8.8.8 2>/dev/null | grep -c ':' || true)
  [[ "${nA:-0}" -eq 0 && "${nAAAA:-0}" -eq 0 ]] && { err "  $d РЅРµ СЂРµР·РѕР»РІРёС‚СЃСЏ"; return 1; }

  local ip4_server="" ip6_server="" dns_ok=false
  ip4_server=$(curl -4 -s --max-time 5 ifconfig.me 2>/dev/null | tr -d '[:space:]' || true)
  ip6_server=$(curl -6 -s --max-time 5 ifconfig.me 2>/dev/null | tr -d '[:space:]' || true)
  if [[ -z "$ip4_server" && -z "$ip6_server" ]]; then
    warn "  РЅРµ СѓРґР°Р»РѕСЃСЊ РѕРїСЂРµРґРµР»РёС‚СЊ IP СЃРµСЂРІРµСЂР° вЂ” DNS-РїСЂРѕРІРµСЂРєР° РїСЂРѕРїСѓС‰РµРЅР°"
  else
    if [[ -n "$ip4_server" ]] && dig +short A "$d" @8.8.8.8 2>/dev/null | grep -Fqx -- "$ip4_server"; then
      dns_ok=true
    fi
    if [[ "$dns_ok" != true && -n "$ip6_server" ]] && dig +short AAAA "$d" @8.8.8.8 2>/dev/null | grep -Fxi -- "$ip6_server"; then
      dns_ok=true
    fi
    if [[ "$dns_ok" != true ]]; then
      warn "  DNS mismatch: $d"
      warn "    A ($nA):    $(dig +short A "$d" @8.8.8.8 2>/dev/null | tr '\n' ' ')"
      warn "    AAAA:      $(dig +short AAAA "$d" @8.8.8.8 2>/dev/null | tr '\n' ' ')"
      warn "    СЃРµСЂРІРµСЂ v4: $ip4_server"
      warn "    СЃРµСЂРІРµСЂ v6: $ip6_server"
      local continue_anyway
      askyn continue_anyway "РџСЂРѕРґРѕР»Р¶РёС‚СЊ РІС‹РїСѓСЃРє РЅРµСЃРјРѕС‚СЂСЏ РЅР° DNS?" "n"
      [[ "$continue_anyway" == true ]] || return 1
    fi
  fi

  log "  РІС‹РїСѓСЃРє cert РґР»СЏ $d..."
  local out="" nginx_was_active=false
  systemctl is-active --quiet nginx 2>/dev/null && nginx_was_active=true
  # 80 Р·Р°РєСЂС‹С‚ UFW (РЅР°С€ РїСЂРёРЅС†РёРї) вЂ” РЅРѕ ACME-СЃРµСЂРІРµСЂ СЃС‚СѓС‡РёС‚СЃСЏ СЃРЅР°СЂСѓР¶Рё. РћС‚РєСЂС‹РІР°РµРј
  # РІСЂРµРјРµРЅРЅРѕ Рё Р·Р°РєСЂС‹РІР°РµРј РїРѕСЃР»Рµ РІС‹РїСѓСЃРєР° (standalone Р webroot РѕР±Р° С‚СЂРµР±СѓСЋС‚ :80 РёР·РІРЅРµ).
  local ufw_80_temp=false
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
    if ! ufw status 2>/dev/null | grep -qE "^80/tcp[[:space:]]+ALLOW"; then
      ufw allow 80/tcp comment "acme-temp" >/dev/null 2>&1 || true
      ufw_80_temp=true
      log "  UFW: 80/tcp РІСЂРµРјРµРЅРЅРѕ РѕС‚РєСЂС‹С‚ РґР»СЏ ACME"
    fi
  fi
  mkdir -p /var/www/html 2>/dev/null || true

  if [[ "$nginx_was_active" == true ]]; then
    # nginx РґРµСЂР¶РёС‚ :80 вЂ” РёСЃРїРѕР»СЊР·СѓРµРј webroot (ACME-СЃРµСЂРІРµСЂ :80 РІ stack.conf РѕС‚РґР°С‘С‚ /.well-known/acme-challenge/)
    # --keep-until-expiring: РµСЃР»Рё РІР°Р»РёРґРЅС‹Р№ СЃРµСЂС‚ СЃ СЌС‚РёРјРё РґРѕРјРµРЅР°РјРё СѓР¶Рµ РµСЃС‚СЊ вЂ”
    # certbot РѕР±СЏР·Р°РЅ РїРµСЂРµРёСЃРїРѕР»СЊР·РѕРІР°С‚СЊ Р»РёРЅРёСЋ, Р° РЅРµ СЃРѕР·РґР°РІР°С‚СЊ РєРѕРїРёСЋ -0001
    out=$(certbot certonly --webroot -w /var/www/html --non-interactive --agree-tos --keep-until-expiring --email "$EMAIL" --cert-name "$d" -d "$d" 2>&1 || true)
    if [[ ! -f "$dir/fullchain.pem" || ! -f "$dir/privkey.pem" ]]; then
      warn "  webroot РЅРµ СЃСЂР°Р±РѕС‚Р°Р», РїСЂРѕР±СѓРµРј standalone (nginx РєСЂР°С‚РєРѕ РѕСЃС‚Р°РЅРѕРІРёРј)"
      systemctl stop nginx 2>/dev/null || true
      out="$out
$(certbot certonly --standalone --non-interactive --agree-tos --keep-until-expiring --email "$EMAIL" --cert-name "$d" -d "$d" 2>&1 || true)"
      systemctl start nginx 2>/dev/null || true
    fi
  else
    out=$(certbot certonly --standalone --non-interactive --agree-tos --keep-until-expiring --email "$EMAIL" --cert-name "$d" -d "$d" 2>&1 || true)
  fi
  if [[ "$ufw_80_temp" == true ]]; then
    ufw delete allow 80/tcp >/dev/null 2>&1 || true
    log "  UFW: 80/tcp Р·Р°РєСЂС‹С‚ РѕР±СЂР°С‚РЅРѕ"
  fi
  # certbot РјРѕРі СЃРѕР·РґР°С‚СЊ Р»РёРЅРёСЋ СЃ СЃСѓС„С„РёРєСЃРѕРј (-0001вЂ¦) вЂ” РїРѕРґС…РІР°С‚С‹РІР°РµРј С„Р°РєС‚РёС‡РµСЃРєСѓСЋ
  if [[ ! -f "$dir/fullchain.pem" || ! -f "$dir/privkey.pem" ]]; then
    local alt=""
    alt=$(ls -d /etc/letsencrypt/live/"$d"-* 2>/dev/null | sort | tail -1 || true)
    if [[ -n "$alt" && -f "$alt/fullchain.pem" && -f "$alt/privkey.pem" ]]; then
      dir="$alt"
      warn "  certbot СЃРѕР·РґР°Р» Р»РёРЅРёСЋ СЃ СЃСѓС„С„РёРєСЃРѕРј: $(basename "$alt") вЂ” РёСЃРїРѕР»СЊР·СѓСЋ РµС‘"
    fi
  fi
  # В«not yet due for renewalВ» = СЃРµСЂС‚ РЈР–Р• СЃСѓС‰РµСЃС‚РІСѓРµС‚ Рё РІР°Р»РёРґРµРЅ (certbot СЃР°Рј
  # РїСЂРѕРІРµСЂРёР») вЂ” СЌС‚Рѕ РЈРЎРџР•РҐ, Р° РЅРµ РѕС‚РєР°Р·: Р±РµСЂС‘Рј С„Р°РєС‚РёС‡РµСЃРєСѓСЋ Р»РёРЅРёСЋ Рё Р·РµСЂРєР°Р»РёРј.
  if grep -q "not yet due for renewal" <<<"$out"; then
    if [[ ! -f "$dir/fullchain.pem" ]]; then
      local alt2
      alt2=$(ls -d /etc/letsencrypt/live/"$d"-* 2>/dev/null | sort | tail -1 || true)
      [[ -n "$alt2" ]] && dir="$alt2"
    fi
    if [[ -f "$dir/fullchain.pem" && -f "$dir/privkey.pem" ]]; then
      log "  cert $d: СѓР¶Рµ РґРµР№СЃС‚РІСѓРµС‚ (certbot: not yet due for renewal) вЂ” РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєР° РЅРµ РЅСѓР¶РЅР°"
      local mline0=""
      mline0=$(cert_mirror_to_certroot "$dir" "$d" 2>/dev/null || true)
      [[ -n "$mline0" ]] && log "  OK (live: /etc/letsencrypt/live/$d/)" || log "  OK"
      return 0
    fi
  fi
  [[ -f "$dir/fullchain.pem" && -f "$dir/privkey.pem" ]] || {
    err "  certbot РѕС‚РєР°Р·Р°Р» РґР»СЏ $d:"
    echo "$out" | tail -8 | sed 's/^/    /'
    local rl
    rl=$(echo "$out" | grep -oE "retry after [0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2} UTC" | head -1 || true)
    [[ -n "$rl" ]] && err "  Р›РРњРРў LET'S ENCRYPT (5 СЃРµСЂС‚РѕРІ/168С‡): РїРѕРІС‚РѕСЂРёС‚СЊ РїРѕСЃР»Рµ $rl вЂ” СЌС‚Рѕ РќР• Р±Р°Рі СЃРєСЂРёРїС‚Р°"
    err "  РРўРћР“: СЃРµСЂС‚ $d РќР• РІС‹РїСѓС‰РµРЅ вЂ” РёРЅР±Р°СѓРЅРґ СЃ СЌС‚РёРј РґРѕРјРµРЅРѕРј РЅРµ РїРѕРґРЅРёРјРµС‚СЃСЏ"
    cert_error_pause
    return 1
  }

  # РїСѓС‚Рё вЂ” live/ (РµРґРёРЅРѕРµ РјРµСЃС‚Рѕ)
  local mline=""
  mline=$(cert_mirror_to_certroot "$dir" "$d" 2>/dev/null || true)
  [[ -n "$mline" ]] && log "  OK (live: /etc/letsencrypt/live/$d/)" || log "  OK"
  return 0
}

# =====================================================================
# WILDCART РЎР•Р РўРР¤РРљРђРў CLOUDFLARE (DNS-01, РѕРґРёРЅ РЅР° РІСЃРµ РїРѕРґРґРѕРјРµРЅС‹)
# =====================================================================
# РџРѕРёСЃРє РЈРЎРўРђРќРћР’Р›Р•РќРќРћР“Рћ СЃРµСЂС‚РёС„РёРєР°С‚Р°, РїРѕРєСЂС‹РІР°СЋС‰РµРіРѕ РґРѕРјРµРЅ, РїРѕ SAN РІСЃРµС… live-СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ.
# РќРµ Р·Р°РІРёСЃРёС‚ РѕС‚ С„Р»Р°РіР° WILDCARD_STATE. РџРµС‡Р°С‚Р°РµС‚: "<live-dir>|<wcbase>" (wcbase РїСѓСЃС‚, РµСЃР»Рё СЃРѕРІРїР°РґРµРЅРёРµ С‚РѕС‡РЅРѕРµ).
find_covering_cert() {
  local d="$1" ldir san entry base wcbase
  for ldir in /etc/letsencrypt/live/*/; do
    [[ -f "${ldir}fullchain.pem" && -f "${ldir}privkey.pem" ]] || continue
    san=$(openssl x509 -noout -ext subjectAltName -in "${ldir}cert.pem" 2>/dev/null | tail -n +2 | tr -d ' ' || true)
    [[ "$san" != *DNS:* ]] && continue
    wcbase=""
    while IFS= read -r entry; do
      entry="${entry#DNS:}"
      [[ -z "$entry" ]] && continue
      if [[ "$entry" == "$d" ]]; then
        echo "${ldir%/}|$wcbase"; return 0
      fi
      if [[ "$entry" == \** ]]; then
        base="${entry#\*.}"
        if [[ "$d" == *."$base" || "$d" == "$base" ]]; then
          wcbase="$base"
          echo "${ldir%/}|$wcbase"; return 0
        fi
      fi
    done < <(tr ',\n' '\n\n' <<<"$san")
  done
  return 1
}

# РЎРІРµР¶РёР№ (>30 РґРЅ) СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Р№ СЃРµСЂС‚РёС„РёРєР°С‚, РїРѕРєСЂС‹РІР°СЋС‰РёР№ РґРѕРјРµРЅ, вЂ” РґР»СЏ РїСЂРѕРїСѓСЃРєР°
# РёР·Р±С‹С‚РѕС‡РЅС‹С… РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹С… РІС‹РїСѓСЃРєРѕРІ РїСЂРё Р¶РёРІРѕРј wildcard/SAN. РџРµС‡Р°С‚Р°РµС‚ hit
# find_covering_cert ("<live-dir>|<wcbase>"); 1 вЂ” РµСЃР»Рё РЅРёС‡РµРіРѕ СЃРІРµР¶РµРіРѕ РЅРµС‚.
cert_fresh_cover() {
  local d="$1" hit dir
  hit=$(find_covering_cert "$d") || return 1
  dir="${hit%%|*}"
  openssl x509 -noout -checkend 2592000 -in "$dir/cert.pem" >/dev/null 2>&1 || return 1
  printf '%s' "$hit"
  return 0
}

# РџРµС‡Р°С‚Р°РµС‚ "fullchain privkey" РґР»СЏ РґРѕРјРµРЅР°: wildcard (РµСЃР»Рё РїРѕРєСЂС‹РІР°РµС‚) в†’ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№
cert_paths() {
  local d="$1"
  # self-heal: С„Р»Р°Рі wildcard РјРѕРі РЅРµ Р·Р°РіСЂСѓР·РёС‚СЊСЃСЏ (РЅР°РїСЂРёРјРµСЂ, РїСЂРё source Р±РµР· С‚РѕС‡РєРё РІС…РѕРґР°)
  if [[ -z "$WILDCARD_DOMAIN" && -f "$WILDCARD_STATE" ]]; then
    WILDCARD_DOMAIN=$(head -n 1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]' || true)
  fi
  if [[ -n "$WILDCARD_DOMAIN" && ( "$d" == "$WILDCARD_DOMAIN" || "$d" == *."$WILDCARD_DOMAIN" ) ]]; then
    local wd="/etc/letsencrypt/live/$WILDCARD_DOMAIN"
    [[ -f "$wd/fullchain.pem" && -f "$wd/privkey.pem" ]] && { echo "$wd/fullchain.pem $wd/privkey.pem"; return 0; }
  fi
  local pd="/etc/letsencrypt/live/$d"
  [[ -f "$pd/fullchain.pem" && -f "$pd/privkey.pem" ]] && { echo "$pd/fullchain.pem $pd/privkey.pem"; return 0; }
  # С„Р»Р°Рі РїРѕС‚РµСЂСЏРЅ вЂ” РёС‰РµРј РїРѕРєСЂС‹РІР°СЋС‰РёР№ СЃРµСЂС‚РёС„РёРєР°С‚ РїРѕ SAN
  local hit wcdir
  hit=$(find_covering_cert "$d") || return 1
  wcdir="${hit%%|*}"
  echo "$wcdir/fullchain.pem $wcdir/privkey.pem"
  return 0
}

# РћР¶РёРґР°РµРјС‹Рµ РїСѓС‚Рё Р»РёРЅРёРё РґР»СЏ РґРѕРјРµРЅР° (СЂРµР¶РёРј A/B), Р‘Р•Р— С‚СЂРµР±РѕРІР°РЅРёСЏ СЃСѓС‰РµСЃС‚РІРѕРІР°РЅРёСЏ.
# РќСѓР¶РµРЅ РїСЂРё РѕС‚Р»РѕР¶РµРЅРЅРѕРј РІС‹РїСѓСЃРєРµ (CERT_DEFER=1): РёРЅР±Р°СѓРЅРґ СЃРѕР·РґР°С‘С‚СЃСЏ СЂР°РЅСЊС€Рµ, С‡РµРј
# Р»РёРЅРёСЏ Р±СѓРґРµС‚ РІС‹РїСѓС‰РµРЅР° РїР°С‡РєРѕР№, Р° РїСѓС‚СЊ live/<Р»РёРЅРёСЏ>/ РґРµС‚РµСЂРјРёРЅРёСЂРѕРІР°РЅ вЂ” СЃРµСЂС‚
# РїРѕСЏРІРёС‚СЃСЏ С‚Р°Рј РїРѕСЃР»Рµ cert_batch_flush. Р’РѕР·РІСЂР°С‰Р°РµС‚ 1, РµСЃР»Рё СЂРµР¶РёРј/Р»РёРЅРёСЏ РЅРµРёР·РІРµСЃС‚РЅС‹.
cert_line_paths_expect() {
  local d="$1" ln=""
  [[ -n "${CERT_MODE:-}" ]] || return 1
  if [[ "$CERT_MODE" == "A" ]]; then
    cert_multi_name_resolve >/dev/null 2>&1 || return 1
    ln="$CERT_MULTI_NAME"
  else
    ln=$(cert_line_for "$d" 2>/dev/null || true)
  fi
  [[ -n "$ln" ]] || return 1
  printf '/etc/letsencrypt/live/%s/fullchain.pem /etc/letsencrypt/live/%s/privkey.pem' "$ln" "$ln"
}

# РЎС‚СЂРѕРіР°СЏ РїСЂРѕРІРµСЂРєР° СЃРµСЂС‚РёС„РёРєР°С‚Р° Рё РєР»СЋС‡Р° РґР»СЏ РєРѕРЅРєСЂРµС‚РЅРѕРіРѕ hostname.
# Р’РѕР·РІСЂР°С‰Р°РµС‚ 0 С‚РѕР»СЊРєРѕ РµСЃР»Рё СЃРµСЂС‚РёС„РёРєР°С‚ СЃСѓС‰РµСЃС‚РІСѓРµС‚, РЅРµ РёСЃС‚С‘Рє, РїРѕРєСЂС‹РІР°РµС‚ РґРѕРјРµРЅ
# Рё СЃРѕРѕС‚РІРµС‚СЃС‚РІСѓРµС‚ РїСЂРёРІР°С‚РЅРѕРјСѓ РєР»СЋС‡Сѓ.
cert_preflight() {
  local d="$1" pair cert key san_end
  [[ "$d" =~ ^[A-Za-z0-9.-]+$ ]] || return 1
  pair=$(cert_paths "$d" 2>/dev/null) || return 1
  cert="${pair%% *}"; key="${pair##* }"
  [[ -s "$cert" && -s "$key" ]] || return 1
  openssl x509 -noout -checkend 86400 -in "$cert" >/dev/null 2>&1 || return 1
  # РќРµ СЂР°Р·Р±РёСЂР°РµРј С‚РµРєСЃС‚ checkhost: РІ СЂР°Р·РЅС‹С… РІРµСЂСЃРёСЏС… OpenSSL СѓСЃРїРµС€РЅС‹Р№ РІС‹РІРѕРґ
  # РѕС‚Р»РёС‡Р°РµС‚СЃСЏ ("was found" РёР»Рё "does match"). РљРѕРґ РІРѕР·РІСЂР°С‚Р° вЂ” СЃС‚Р°Р±РёР»СЊРЅС‹Р№ API.
  openssl x509 -noout -checkhost "$d" -in "$cert" >/dev/null 2>&1 || return 1
  # РџРѕРґРґРµСЂР¶РёРІР°РµРј RSA Рё ECDSA: СЃСЂР°РІРЅРёРІР°РµРј DER РїСѓР±Р»РёС‡РЅС‹С… РєР»СЋС‡РµР№, Р° РЅРµ modulus.
  local cert_pub key_pub
  cert_pub=$(openssl x509 -in "$cert" -pubkey -noout 2>/dev/null | openssl pkey -pubin -outform DER 2>/dev/null | sha256sum | cut -d' ' -f1)
  key_pub=$(openssl pkey -in "$key" -pubout -outform DER 2>/dev/null | sha256sum | cut -d' ' -f1)
  [[ -n "$cert_pub" && "$cert_pub" != "$(printf '0%.0s' {1..64})" && "$cert_pub" == "$key_pub" ]] || return 1
  printf '%s %s\n' "$cert" "$key"
}

# --- РњРЈР›Р¬РўРРЎР•Р Рў (SAN): РѕРґРёРЅ СЃРµСЂС‚ РЅР° РЅРµСЃРєРѕР»СЊРєРѕ РґРѕРјРµРЅРѕРІ (РІ С‚.С‡. Р РђР—РќР«РҐ Р·РѕРЅ) ---
# РЎРѕСЃСѓС‰РµСЃС‚РІСѓРµС‚ СЃ wildcard: cert_paths/find_covering_cert СЃР°РјРё РІС‹Р±РµСЂСѓС‚ wildcard
# РґР»СЏ РµРіРѕ Р·РѕРЅС‹, Р° РґР»СЏ РѕСЃС‚Р°Р»СЊРЅС‹С… РґРѕРјРµРЅРѕРІ РЅР°Р№РґСѓС‚ SAN РІ Р»РёРЅРёРё stack-multi.
# cert_issue РїСЂРё РІРёРґРµ РґРѕРјРµРЅР° РёР· СЃРїРёСЃРєР° С‚РѕР¶Рµ РїРµСЂРµРёСЃРїРѕР»СЊР·СѓРµС‚ SAN (find_covering_cert).
# Р”РѕР±Р°РІРёС‚СЊ РґРѕРјРµРЅ РІ РјСѓР»СЊС‚РёСЃРїРёСЃРѕРє РІСЂСѓС‡РЅСѓСЋ
certs_domain_add_manual() {
  cert_mode_load >/dev/null 2>&1 || true
  local newd="" _line=""
  ask newd "Р”РѕРјРµРЅ РґР»СЏ РґРѕР±Р°РІР»РµРЅРёСЏ" "" '^[a-zA-Z0-9.-]+$'
  [[ -z "$newd" ]] && { warn "РћС‚РјРµРЅРµРЅРѕ"; return 0; }
  if [[ "${CERT_MODE:-A}" == "B" ]]; then
    _line=$(cert_line_for "$newd") || true
    [[ -z "$_line" ]] && { err "РќРµ СѓРґР°Р»РѕСЃСЊ РѕРїСЂРµРґРµР»РёС‚СЊ Р»РёРЅРёСЋ СЃРµСЂС‚РёС„РёРєР°С‚Р° РґР»СЏ $newd"; pause; return 1; }
    cert_line_domains_load "$_line"
    [[ " ${CERT_LINE_DOMAINS[*]} " == *" $newd "* ]] && { log "Р”РѕРјРµРЅ СѓР¶Рµ РІ Р»РёРЅРёРё $_line"; return 0; }
    cert_line_domains_add "$_line" "$newd"
    log "Р”РѕР±Р°РІР»РµРЅ РІ Р»РёРЅРёСЋ СЃРµСЂС‚РёС„РёРєР°С‚Р° $_line: $newd"
  else
    cert_domains_load
    [[ " ${CERT_DOMAINS[*]} " == *" $newd "* ]] && { log "Р”РѕРјРµРЅ $newd СѓР¶Рµ РІ СЃРїРёСЃРєРµ"; return 0; }
    cert_domains_add "$newd" 1
    log "Р”РѕР±Р°РІР»РµРЅ РІ РјСѓР»СЊС‚РёСЃРїРёСЃРѕРє: $newd"
  fi
  local r=""
  askyn r "РџРµСЂРµРІС‹РїСѓСЃС‚РёС‚СЊ РјСѓР»СЊС‚РёСЃРµСЂС‚ СЃРµР№С‡Р°СЃ?" "y"
  [[ "$r" == true ]] && { CERT_DEFER=0; cert_batch_flush; }
  pause
}

# Рџ.11 СѓРґР°Р»СЏРµС‚ РґРѕРјРµРЅ РёР· СЃРїРёСЃРєР° SAN, РЅРѕ РµСЃР»Рё РґРѕРјРµРЅ РѕСЃС‚Р°С‘С‚СЃСЏ РІ SNI-РєР°СЂС‚Рµ nginx,
# cert_domains_sync_from_sni (Рї.9 / РїРµСЂРµРІС‹РїСѓСЃРє) РїСЂРё СЃР»РµРґСѓСЋС‰РµРј Р±Р°С‚С‡Рµ РІРµСЂРЅС‘С‚ РµРіРѕ
# РІ СЃРїРёСЃРѕРє вЂ” В«СѓРґР°Р»С‘РЅРЅС‹Р№В» РґРѕРјРµРЅ СЃРЅРѕРІР° РѕРєР°Р¶РµС‚СЃСЏ РІ СЃРµСЂС‚РёС„РёРєР°С‚Рµ. РџРѕСЌС‚РѕРјСѓ РїСЂРё СЂСѓС‡РЅРѕРј
# СѓРґР°Р»РµРЅРёРё С‡РёСЃС‚РёРј Рё РјР°СЂС€СЂСѓС‚ (РёРЅР°С‡Рµ removal РЅРµ РёРјРµРµС‚ СЌС„С„РµРєС‚Р°).
cert_removed_domain_purge_sni() {   # <domain>
  local d="$1"
  [[ -z "$d" || ! -f "$SNI_CONF" ]] && return 0
  local be=""
  be=$(awk -v dom="$d" '
    /^[[:space:]]*map[[:space:]]/ { inmap=1; next }
    inmap && /^[[:space:]]*}/ { inmap=0; next }
    inmap && $1 == dom { be=$2; sub(/;$/, "", be); print be; exit }
  ' "$SNI_CONF" 2>/dev/null || true)
  [[ -z "$be" ]] && return 0
  # РЎР»СѓР¶РµР±РЅС‹Рµ РјР°СЂС€СЂСѓС‚С‹ РЅРµ С‚СЂРѕРіР°РµРј: РїР°РЅРµР»СЊ/AdGuard РЅСѓР¶РЅС‹ СЃР°РјРё РїРѕ СЃРµР±Рµ, Р° РёС…
  # РґРѕРјРµРЅС‹ РІСЃС‘ СЂР°РІРЅРѕ РІРµСЂРЅСѓС‚СЃСЏ РІ SAN РїСЂРё РїРµСЂРµРІС‹РїСѓСЃРєРµ вЂ” С‡РµСЃС‚РЅРѕ РїСЂРµРґСѓРїСЂРµР¶РґР°РµРј.
  if [[ "$be" == "panel_backend" || "$be" == "agh_backend" ]]; then
    warn "  $d РѕСЃС‚Р°С‘С‚СЃСЏ РІ SNI-РєР°СЂС‚Рµ (СЃР»СѓР¶РµР±РЅС‹Р№ РјР°СЂС€СЂСѓС‚ $be) вЂ” РІРµСЂРЅС‘С‚СЃСЏ РІ SAN РїСЂРё РїРµСЂРµРІС‹РїСѓСЃРєРµ"
    return 0
  fi
  local ans=""
  echo "  Р”РѕРјРµРЅ РЅР°Р№РґРµРЅ РІ SNI-РєР°СЂС‚Рµ nginx (РјР°СЂС€СЂСѓС‚: $be)."
  askyn ans "РЈРґР°Р»РёС‚СЊ Рё SNI-РјР°СЂС€СЂСѓС‚ $d? (РёРЅР°С‡Рµ РІРµСЂРЅС‘С‚СЃСЏ РІ SAN РїСЂРё РїРµСЂРµРІС‹РїСѓСЃРєРµ)" "y"
  if [[ "$ans" == true ]]; then
    sni_map_remove "$d"
    nginx_reload || true
    log "  SNI-РјР°СЂС€СЂСѓС‚ $d СѓРґР°Р»С‘РЅ РёР· РєР°СЂС‚С‹"
  else
    warn "  РњР°СЂС€СЂСѓС‚ РѕСЃС‚Р°РІР»РµРЅ: $d РІРµСЂРЅС‘С‚СЃСЏ РІ SAN РїСЂРё СЃР»РµРґСѓСЋС‰РµРј РїРµСЂРµРІС‹РїСѓСЃРєРµ (Рї.9)"
  fi
  return 0
}

# РЈРґР°Р»РёС‚СЊ РґРѕРјРµРЅ РёР· РјСѓР»СЊС‚РёСЃРїРёСЃРєР° РІСЂСѓС‡РЅСѓСЋ
certs_domain_remove_manual() {
  cert_mode_load >/dev/null 2>&1 || true
  if [[ "${CERT_MODE:-A}" == "B" ]]; then
    cert_lines_load
    local _all=() _ln _d
    for _ln in "${CERT_LINES[@]}"; do
      cert_line_domains_load "$_ln"
      for _d in "${CERT_LINE_DOMAINS[@]}"; do _all+=("$_ln|$_d"); done
    done
    [[ ${#_all[@]} -eq 0 ]] && { warn "Р›РёРЅРёРё СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ РїСѓСЃС‚С‹"; pause; return 0; }
    echo; echo "Р”РѕРјРµРЅС‹ Р»РёРЅРёР№ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ:"
    local i=1 d
    for d in "${_all[@]}"; do printf "  %2d) %s (Р»РёРЅРёСЏ %s)\n" "$i" "${d#*|}" "${d%%|*}"; i=$((i+1)); done
    local pick=""; ask pick "РќРѕРјРµСЂ РґР»СЏ СѓРґР°Р»РµРЅРёСЏ (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
    [[ "$pick" == "0" ]] && return 0
    (( pick < 1 || pick > ${#_all[@]} )) && { err "РќРµС‚ С‚Р°РєРѕРіРѕ РЅРѕРјРµСЂР°"; pause; return 1; }
    local target="${_all[$((pick-1))]}"; cert_line_domains_remove "${target%%|*}" "${target#*|}"
    cert_removed_domain_purge_sni "${target#*|}"
    cert_personal_lineage_drop_ask "${target#*|}"
    log "РЈРґР°Р»С‘РЅ РёР· Р»РёРЅРёРё ${target%%|*}: ${target#*|}"; pause; return 0
  fi
  cert_domains_load
  cert_multi_name_resolve >/dev/null 2>&1 || true
  [[ ${#CERT_DOMAINS[@]} -eq 0 ]] && { warn "РњСѓР»СЊС‚РёСЃРїРёСЃРѕРє РїСѓСЃС‚"; pause; return 0; }
  echo
  echo "Р”РѕРјРµРЅС‹ РІ РјСѓР»СЊС‚РёСЃРїРёСЃРєРµ:"
  local i=1 d
  for d in "${CERT_DOMAINS[@]}"; do
    local mark=""
    [[ -n "$CERT_MULTI_NAME" && "$d" == "$CERT_MULTI_NAME" ]] && mark=" [РґРѕРјРµРЅ РїР°РЅРµР»Рё вЂ” СѓРґР°Р»СЏС‚СЊ РЅРµР»СЊР·СЏ]"
    printf "  %2d) %s%s\n" "$i" "$d" "$mark"
    i=$((i+1))
  done
  echo
  local pick=""
  ask pick "РќРѕРјРµСЂ РґР»СЏ СѓРґР°Р»РµРЅРёСЏ (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
  [[ "$pick" == "0" ]] && return 0
  (( pick < 1 || pick > ${#CERT_DOMAINS[@]} )) && { err "РќРµС‚ С‚Р°РєРѕРіРѕ РЅРѕРјРµСЂР°"; pause; return 1; }
  local target="${CERT_DOMAINS[$((pick-1))]}"
  if [[ -n "$CERT_MULTI_NAME" && "$target" == "$CERT_MULTI_NAME" ]]; then
    err "Р­С‚Рѕ РґРѕРјРµРЅ РїР°РЅРµР»Рё (CN СЃРµСЂС‚Р°) вЂ” СѓРґР°Р»РёС‚СЊ РЅРµР»СЊР·СЏ. РЎРјРµРЅРё РґРѕРјРµРЅ РїР°РЅРµР»Рё РІ Рї.1."
    pause; return 1
  fi
  cert_domains_remove "$target"
  log "РЈРґР°Р»С‘РЅ РёР· РјСѓР»СЊС‚РёСЃРїРёСЃРєР°: $target"
  cert_removed_domain_purge_sni "$target"
  cert_personal_lineage_drop_ask "$target"
  local r=""
  askyn r "РџРµСЂРµРІС‹РїСѓСЃС‚РёС‚СЊ РјСѓР»СЊС‚РёСЃРµСЂС‚ СЃРµР№С‡Р°СЃ (Р±РµР· СѓРґР°Р»С‘РЅРЅРѕРіРѕ РґРѕРјРµРЅР°)?" "y"
  [[ "$r" == true ]] && { CERT_DEFER=0; cert_batch_flush; }
  pause
}


# =====================================================================
# РћР§РРЎРўРљРђ РЎРР РћРў Р Р”РЈР‘Р›Р•Р™ РЎР•Р РўРћР’
# =====================================================================

# Р’РѕР·РІСЂР°С‰Р°РµС‚ СЃРїРёСЃРѕРє В«РёР·РІРµСЃС‚РЅС‹С…В» Р»РёРЅРёР№ (РґР»СЏ РїСЂРѕРІРµСЂРєРё, С‡С‚Рѕ Р»РёРЅРёСЏ РІ live/
# РґРµР№СЃС‚РІРёС‚РµР»СЊРЅРѕ РЅСѓР¶РЅР°). РџРµС‡Р°С‚Р°РµС‚ РїРѕ СЃС‚СЂРѕРєРµ.
cert_known_lines() {
  cert_mode_load >/dev/null 2>&1 || true
  # Р“Р»Р°РІРЅР°СЏ Р»РёРЅРёСЏ (РґРѕРјРµРЅ РїР°РЅРµР»Рё)
  local pd=""
  pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && pd="${PANEL_DOMAIN:-}"
  [[ -n "$pd" ]] && echo "$pd"
  # Р›РёРЅРёРё РёР· cert-lines.txt (СЂРµР¶РёРј B)
  if [[ -f "$CERT_LINES_FILE" ]]; then
    local l
    while IFS= read -r l; do
      l="$(printf '%s' "$l" | tr -d '[:space:]')"
      [[ -n "$l" ]] && echo "$l"
    done < "$CERT_LINES_FILE"
  fi
  # Wildcard
  [[ -f "$WILDCARD_STATE" ]] && head -n1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]'
}

# РџСЂРѕРІРµСЂСЏРµС‚, РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ Р»Рё РёРјСЏ Р»РёРЅРёРё РіРґРµ-РЅРёР±СѓРґСЊ:
#   - РІ Р‘Р” x-ui (webCertFile / subCertFile / РІ РЅР°СЃС‚СЂРѕР№РєР°С… РёРЅР±Р°СѓРЅРґРѕРІ)
#   - РІ nginx (stack.conf, adguard-tls)
#   - РІ СЃРїРёСЃРєРµ РёР·РІРµСЃС‚РЅС‹С… Р»РёРЅРёР№ (cert_known_lines)
# Р’РѕР·РІСЂР°С‰Р°РµС‚ 0 РµСЃР»Рё РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ, РёРЅР°С‡Рµ 1.
cert_line_is_used() {
  local name="$1"
  [[ -z "$name" ]] && return 1
  # РР·РІРµСЃС‚РЅС‹Рµ Р»РёРЅРёРё
  if cert_known_lines | grep -qxF "$name"; then
    return 0
  fi
  # Р‘Р” x-ui
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local cnt
    cnt=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
      "SELECT COUNT(*) FROM settings WHERE value LIKE '%/live/$name/%';" 2>/dev/null || echo 0)
    [[ "$cnt" != "0" ]] && return 0
    cnt=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
      "SELECT COUNT(*) FROM inbounds WHERE settings LIKE '%/live/$name/%' OR stream_settings LIKE '%/live/$name/%';" 2>/dev/null || echo 0)
    [[ "$cnt" != "0" ]] && return 0
  fi
  # nginx
  if [[ -f "$STACK_CONF" ]] && grep -q "/live/$name/" "$STACK_CONF" 2>/dev/null; then
    return 0
  fi
  if [[ -f /opt/AdGuardHome/AdGuardHome.yaml ]] && grep -q "/live/$name/" /opt/AdGuardHome/AdGuardHome.yaml 2>/dev/null; then
    return 0
  fi
  return 1
}

# РћС‡РёСЃС‚РєР° РґСѓР±Р»РµР№ -0001 / -0002.
# Р•СЃР»Рё РµСЃС‚СЊ <base> Рё <base>-0001:
#   вЂў Р•СЃР»Рё <base> вЂ” Р¶РёРІР°СЏ Р»РёРЅРёСЏ (РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ) в†’ СѓРґР°Р»СЏРµРј <base>-0001.
#   вЂў Р•СЃР»Рё <base> РїСѓСЃС‚Р°СЏ (РЅРµС‚ fullchain.pem РёР»Рё РµРіРѕ symlink Р±РёС‚С‹Р№) в†’ СѓРґР°Р»СЏРµРј
#     <base>, РїРµСЂРµРёРјРµРЅРѕРІС‹РІР°РµРј <base>-0001 РІ <base> (С‡РµСЂРµР· certbot? РЅРµС‚ вЂ”
#     С‡РµСЂРµР· mv live/archive + РїСЂР°РІРєСѓ renewal.conf).
#   вЂў Р•СЃР»Рё РѕР±Рµ Р¶РёРІС‹Рµ Рё РЅРµ СЃРѕРІРїР°РґР°СЋС‚ SAN вЂ” РїРѕРєР°Р·Р°С‚СЊ, РЅРµ С‚СЂРѕРіР°С‚СЊ.
cert_dedup_0001() {
  line; echo -e "${B}   РћР§РРЎРўРљРђ Р”РЈР‘Р›Р•Р™ -0001${N}"; line
  local -a suffix_lines=()
  local ld name base
  for ld in /etc/letsencrypt/live/*/; do
    [[ -d "$ld" ]] || continue
    name=$(basename "$ld")
    [[ "$name" =~ -[0-9]{4}$ ]] && suffix_lines+=("$name")
  done
  if [[ ${#suffix_lines[@]} -eq 0 ]]; then
    log "Р”СѓР±Р»РµР№ -0001 РІ live/ РЅРµ РЅР°Р№РґРµРЅРѕ"
    pause; return 0
  fi
  echo "РќР°Р№РґРµРЅС‹ Р»РёРЅРёРё СЃ СЃСѓС„С„РёРєСЃРѕРј:"
  for name in "${suffix_lines[@]}"; do echo "  - $name"; done
  echo
  local did=0
  for name in "${suffix_lines[@]}"; do
    base="${name%-[0-9][0-9][0-9][0-9]}"
    local base_live="/etc/letsencrypt/live/$base"
    local suffix_live="/etc/letsencrypt/live/$name"

    # РЎР»СѓС‡Р°Р№ 1: <base> РЅРµ СЃСѓС‰РµСЃС‚РІСѓРµС‚ РёР»Рё РїСѓСЃС‚Р°СЏ в†’ РїРµСЂРµРёРјРµРЅРѕРІР°С‚СЊ <base>-NNNN РІ <base>
    if [[ ! -d "$base_live" ]] || [[ ! -f "$base_live/fullchain.pem" ]]; then
      echo "  в”Ђ $name: Р±Р°Р·РѕРІР°СЏ Р»РёРЅРёСЏ $base РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚ в†’ РїРµСЂРµРёРјРµРЅРѕРІС‹РІР°СЋ"
      local sure=""
      askyn sure "РџРµСЂРµРёРјРµРЅРѕРІР°С‚СЊ $name в†’ $base?" "y"
      if [[ "$sure" == true ]]; then
        # РџРµСЂРµРёРјРµРЅРѕРІР°С‚СЊ live/
        [[ -d "$base_live" ]] && rm -rf "$base_live"
        mv "$suffix_live" "$base_live" 2>/dev/null || true
        # РџРµСЂРµРёРјРµРЅРѕРІР°С‚СЊ archive/
        [[ -d "/etc/letsencrypt/archive/$base" ]] && rm -rf "/etc/letsencrypt/archive/$base"
        [[ -d "/etc/letsencrypt/archive/$name" ]] && mv "/etc/letsencrypt/archive/$name" "/etc/letsencrypt/archive/$base" 2>/dev/null || true
        # РџРѕРїСЂР°РІРёС‚СЊ renewal.conf
        local rf="/etc/letsencrypt/renewal/$name.conf"
        if [[ -f "$rf" ]]; then
          sed -i "s|/etc/letsencrypt/live/$name|/etc/letsencrypt/live/$base|g; s|/etc/letsencrypt/archive/$name|/etc/letsencrypt/archive/$base|g; s|cert = $name|cert = $base|; s|^archive_dir = .*$|archive_dir = /etc/letsencrypt/archive/$base|" "$rf" 2>/dev/null || true
          mv "$rf" "/etc/letsencrypt/renewal/$base.conf" 2>/dev/null || true
        fi
        log "    РїРµСЂРµРёРјРµРЅРѕРІР°РЅРѕ: $name в†’ $base"
        did=$((did+1))
      fi
      continue
    fi

    # РЎР»СѓС‡Р°Р№ 2: РѕР±Рµ Р»РёРЅРёРё Р¶РёРІС‹Рµ в†’ СЃСЂР°РІРЅРёС‚СЊ SAN
    local san_base san_suffix
    san_base=$(openssl x509 -noout -ext subjectAltName -in "$base_live/fullchain.pem" 2>/dev/null \
               | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr -d ' ' | sort | tr '\n' ',')
    san_suffix=$(openssl x509 -noout -ext subjectAltName -in "$suffix_live/fullchain.pem" 2>/dev/null \
                 | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr -d ' ' | sort | tr '\n' ',')
    echo "  в”Ђ $name"
    echo "      $base        SAN: ${san_base%,}"
    echo "      $name  SAN: ${san_suffix%,}"
    if [[ "${san_base%,}" == "${san_suffix%,}" ]]; then
      local sure=""
      askyn sure "SAN СЃРѕРІРїР°РґР°СЋС‚ вЂ” СѓРґР°Р»РёС‚СЊ РґСѓР±Р»СЊ $name?" "y"
      if [[ "$sure" == true ]]; then
        certbot delete --cert-name "$name" --non-interactive 2>/dev/null || true
        log "    СѓРґР°Р»РµРЅРѕ: $name"
        did=$((did+1))
      fi
    else
      warn "    SAN Р РђР—РќР«Р• вЂ” РЅРµ С‚СЂРѕРіР°СЋ (СЂР°Р·Р±РµСЂРёСЃСЊ РІСЂСѓС‡РЅСѓСЋ)"
    fi
  done
  [[ $did -eq 0 ]] && log "РќРёС‡РµРіРѕ РЅРµ РёР·РјРµРЅРµРЅРѕ."
  pause
}

# РџРµСЂСЃРѕРЅР°Р»СЊРЅР°СЏ Р»РёРЅРёСЏ РґРѕРјРµРЅР° РјРѕРіР»Р° РѕСЃС‚Р°С‚СЊСЃСЏ РѕС‚ РїСЂРµР¶РЅРёС… РІРµСЂСЃРёР№: cert_issue РґРѕ
# В«Р»РёРЅРµР№РЅРѕР№В» Р»РѕРіРёРєРё РІС‹РїСѓСЃРєР°Р» РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚ live/<РґРѕРјРµРЅ>, Р° РґРѕРјРµРЅ РїСЂРё СЌС‚РѕРј
# РµС‰С‘ Рё РїРѕРїР°РґР°Р» РІ SAN Р»РёРЅРёРё Р±Р°Р·С‹ (sync_from_sni) вЂ” В«РѕРґРёРЅ РґРѕРјРµРЅ РІ РґРІСѓС… Р»РёРЅРёСЏС…В».
# РџСЂРё СѓРґР°Р»РµРЅРёРё РґРѕРјРµРЅР° (Рї.11) РїСЂРµРґР»Р°РіР°СЋ СЃРЅРµСЃС‚Рё Рё РїРµСЂСЃРѕРЅР°Р»СЊРЅСѓСЋ Р»РёРЅРёСЋ.
cert_personal_lineage_drop_ask() {   # <domain>
  local d="$1"
  local pl="/etc/letsencrypt/live/$d"
  [[ -n "$d" && -f "$pl/fullchain.pem" ]] || return 0
  local ans=""
  echo "  РќР°Р№РґРµРЅ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚ $d (live/$d) вЂ” РґСѓР±Р»СЊ РїРѕРєСЂС‹С‚РёСЏ РѕС‚ РїСЂРµР¶РЅРёС… РІРµСЂСЃРёР№."
  askyn ans "РЈРґР°Р»РёС‚СЊ Рё РµРіРѕ? (РґРѕРјРµРЅ РёСЃС‡РµР·РЅРµС‚ РёР· Р’РЎР•РҐ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ)" "y"
  if [[ "$ans" == true ]]; then
    certbot delete --cert-name "$d" --non-interactive 2>&1 | tail -2 | sed 's/^/    /'
    log "  РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚ $d СѓРґР°Р»С‘РЅ"
  else
    warn "  РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚ $d РѕСЃС‚Р°РІР»РµРЅ вЂ” РѕРЅ РїСЂРѕРґРѕР»Р¶РёС‚ РїРѕРєСЂС‹РІР°С‚СЊ РґРѕРјРµРЅ Рё РїСЂРѕРґР»РµРІР°С‚СЊСЃСЏ"
  fi
  return 0
}

# в”Ђв”Ђв”Ђ Р”СѓР±Р»Рё РїРѕРєСЂС‹С‚РёСЏ: РґРѕРјРµРЅ РІ SAN Р»РёРЅРёРё + СЃРІРѕСЏ РїРµСЂСЃРѕРЅР°Р»СЊРЅР°СЏ Р»РёРЅРёСЏ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# РќР°СЃР»РµРґРёРµ РїСЂРµР¶РЅРµРіРѕ cert_issue: РґРѕРјРµРЅ РїРѕР»СѓС‡Р°Р» РїРµСЂСЃРѕРЅР°Р»СЊРЅСѓСЋ Р»РёРЅРёСЋ live/<РґРѕРјРµРЅ>
# Р РѕРґРЅРѕРІСЂРµРјРµРЅРЅРѕ РїРѕРїР°РґР°Р» РІ SAN Р»РёРЅРёРё Р±Р°Р·С‹ (cert_domains_sync_from_sni РїСЂРё
# РїРµСЂРµРІС‹РїСѓСЃРєРµ) вЂ” В«РѕРґРёРЅ РґРѕРјРµРЅ РІ РґРІСѓС… Р»РёРЅРёСЏС…В» (С‚РёРїРёС‡РЅС‹Р№ СЃР»СѓС‡Р°Р№ вЂ” tg web proxy).
# Р—РґРµСЃСЊ С‚Р°РєРёРµ РґРѕРјРµРЅС‹ РёС‰СѓС‚СЃСЏ РїРѕ SAN РІСЃРµС… live-Р»РёРЅРёР№; РїРµСЂСЃРѕРЅР°Р»СЊРЅР°СЏ Р»РёРЅРёСЏ
# СѓРґР°Р»СЏРµС‚СЃСЏ (РґРѕРјРµРЅ РѕСЃС‚Р°С‘С‚СЃСЏ РїРѕРєСЂС‹С‚ Р»РёРЅРёРµР№), Р° РІСЃРµ СЃСЃС‹Р»РєРё
# /etc/letsencrypt/live/<РґРѕРјРµРЅ>/ РїРµСЂРµРїСЂРёРІСЏР·С‹РІР°СЋС‚СЃСЏ РЅР° РїРѕРєСЂС‹РІР°СЋС‰СѓСЋ Р»РёРЅРёСЋ.
cert_cover_dedup() {
  line; echo -e "${B}   Р”РЈР‘Р›Р РџРћРљР Р«РўРРЇ РЎР•Р РўРР¤РРљРђРўРћР’${N}"; line
  [[ -d /etc/letsencrypt/live ]] || { warn "РќРµС‚ /etc/letsencrypt/live"; pause; return 0; }
  local pd=""
  pd=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pd" || "$pd" == "null" ]] && pd="${PANEL_DOMAIN:-}"
  local known=""
  known=$(cert_known_lines 2>/dev/null || true)

  local -a dups=() covers=()
  local ld name other_ld san2 entry2 base2 other found
  for ld in /etc/letsencrypt/live/*/; do
    [[ -d "$ld" ]] || continue
    name=$(basename "$ld")
    [[ "$name" =~ -[0-9]{4}$ ]] && continue       # СЃСѓС„С„РёРєСЃС‹ -0001 вЂ” СЌС‚Рѕ Рї.16
    [[ "$name" == all.* ]] && continue            # РёРјСЏ Р»РёРЅРёРё СЂРµР¶РёРјР° B, РЅРµ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ РґРѕРјРµРЅ
    cert_domain_valid "$name" || continue         # РјСѓСЃРѕСЂРЅС‹Рµ РёРјРµРЅР° РЅРµ С‚СЂРѕРіР°РµРј
    [[ -n "$pd" && "$name" == "$pd" ]] && continue # Р»РёРЅРёСЏ РїР°РЅРµР»Рё вЂ” СЃРІСЏС‰РµРЅРЅР°
    grep -qxF "$name" <<<"$known" && continue     # РёР·РІРµСЃС‚РЅР°СЏ Р»РёРЅРёСЏ вЂ” РЅРµ РґСѓР±Р»СЊ
    # РїРѕРєСЂС‹С‚ Р»Рё СЌС‚РѕС‚ РґРѕРјРµРЅ Р”Р РЈР“РћР™ Р»РёРЅРёРµР№ (С‚РѕС‡РЅРѕРµ РёРјСЏ РёР»Рё wildcard РµС‘ Р·РѕРЅС‹)?
    other=""
    for other_ld in /etc/letsencrypt/live/*/; do
      [[ "${other_ld%/}" == "${ld%/}" ]] && continue
      [[ -f "${other_ld}fullchain.pem" ]] || continue
      san2=$(openssl x509 -noout -ext subjectAltName -in "${other_ld}cert.pem" 2>/dev/null | tail -n +2 | tr -d ' ' || true)
      [[ "$san2" != *DNS:* ]] && continue
      found=""
      while IFS= read -r entry2; do
        entry2="${entry2#DNS:}"
        [[ -z "$entry2" ]] && continue
        if [[ "$entry2" == "$name" ]]; then found=1; break; fi
        if [[ "$entry2" == \** ]]; then
          base2="${entry2#\*.}"
          if [[ "$name" == *."$base2" || "$name" == "$base2" ]]; then found=1; break; fi
        fi
      done < <(tr ',\n' '\n\n' <<<"$san2")
      if [[ -n "$found" ]]; then other="${other_ld%/}"; break; fi
    done
    [[ -n "$other" ]] || continue
    dups+=("$name"); covers+=("$other")
  done

  if [[ ${#dups[@]} -eq 0 ]]; then
    log "Р”СѓР±Р»РµР№ РїРѕРєСЂС‹С‚РёСЏ РЅРµ РЅР°Р№РґРµРЅРѕ вЂ” Сѓ РєР°Р¶РґРѕРіРѕ РґРѕРјРµРЅР° РѕРґРЅР° Р»РёРЅРёСЏ"
    pause; return 0
  fi

  echo "Р”РѕРјРµРЅС‹, РїРѕРєСЂС‹С‚С‹Рµ РѕРґРЅРѕРІСЂРµРјРµРЅРЅРѕ РїРµСЂСЃРѕРЅР°Р»СЊРЅРѕР№ Р»РёРЅРёРµР№ Рё РґСЂСѓРіРѕР№ Р»РёРЅРёРµР№:"
  local i=0 dn cn
  for dn in "${dups[@]}"; do
    cn="${covers[$i]}"
    echo "  в”Ђ $dn"
    echo "      РїРµСЂСЃРѕРЅР°Р»СЊРЅР°СЏ: live/$dn  SAN: $(openssl x509 -noout -ext subjectAltName -in "/etc/letsencrypt/live/$dn/cert.pem" 2>/dev/null | tail -n +2 | tr -d ' ' | tr '\n' ',' | sed 's/,$//')"
    echo "      РїРѕРєСЂС‹С‚Р° С‚Р°РєР¶Рµ Р»РёРЅРёРµР№: $(basename "$cn")  SAN: $(openssl x509 -noout -ext subjectAltName -in "$cn/cert.pem" 2>/dev/null | tail -n +2 | tr -d ' ' | tr '\n' ',' | sed 's/,$//')"
    i=$((i+1))
  done
  echo
  echo "  1) РЈРґР°Р»РёС‚СЊ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рµ Р»РёРЅРёРё Р’РЎР•РҐ РЅР°Р№РґРµРЅРЅС‹С… РґРѕРјРµРЅРѕРІ (РїРµСЂРµРїСЂРёРІСЏР·Р°С‚СЊ СЃСЃС‹Р»РєРё)"
  echo "  2) Р’С‹Р±РёСЂР°С‚СЊ РїРѕ РѕРґРЅРѕРјСѓ"
  echo "  0) РћС‚РјРµРЅР°"
  local c=""
  read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
  case "$c" in
    1|2) ;;
    *) pause; return 0 ;;
  esac
  local i2=0 did=0 sure
  for dn in "${dups[@]}"; do
    local cn2="${covers[$i2]}"; i2=$((i2+1))
    if [[ "$c" == "2" ]]; then
      askyn sure "РЈРґР°Р»РёС‚СЊ РїРµСЂСЃРѕРЅР°Р»СЊРЅСѓСЋ Р»РёРЅРёСЋ В«$dnВ» (РїРѕРєСЂС‹С‚РёРµ РѕСЃС‚Р°РЅРµС‚СЃСЏ: $(basename "$cn2"))?" "y"
      [[ "$sure" == true ]] || continue
    fi
    # 1) РїРµСЂРµРїСЂРёРІСЏР·Р°С‚СЊ СЃСЃС‹Р»РєРё Р”Рћ СѓРґР°Р»РµРЅРёСЏ (РёРЅР°С‡Рµ С„Р°Р№Р»С‹ РёСЃС‡РµР·РЅСѓС‚ РёР·-РїРѕРґ РЅРѕРі)
    local old="/etc/letsencrypt/live/$dn/" new="$cn2/"
    if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
      systemctl stop x-ui 2>/dev/null || true
      CERTREBIND_OLD="$old" CERTREBIND_NEW="$new" CERTREBIND_DB="$XUI_DB" python3 - <<'PYRB'
import sqlite3, os
old, new, db = os.environ["CERTREBIND_OLD"], os.environ["CERTREBIND_NEW"], os.environ["CERTREBIND_DB"]
con = sqlite3.connect(db); cur = con.cursor(); n = 0
for k, v in cur.execute("SELECT key, value FROM settings WHERE value LIKE ?", (f"%{old}%",)).fetchall():
    cur.execute("UPDATE settings SET value=? WHERE key=?", (v.replace(old, new), k)); n += 1
for iid, s, st in cur.execute("SELECT id, settings, stream_settings FROM inbounds WHERE settings LIKE ? OR stream_settings LIKE ?", (f"%{old}%", f"%{old}%")).fetchall():
    cur.execute("UPDATE inbounds SET settings=?, stream_settings=? WHERE id=?",
                ((s or '').replace(old, new), (st or '').replace(old, new), iid)); n += 1
con.commit()
print(f"    РїРµСЂРµРїСЂРёРІСЏР·Р°РЅРѕ СЃСЃС‹Р»РѕРє РІ Р‘Р”: {n}")
PYRB
      systemctl start x-ui 2>/dev/null || true
    fi
    local nf
    nf=$(grep -rl "$old" /etc/nginx/ 2>/dev/null | head -10)
    if [[ -n "$nf" ]]; then
      grep -rl "$old" /etc/nginx/ 2>/dev/null | while read -r f; do
        sed -i "s|$old|$new|g" "$f" 2>/dev/null || true
      done
      log "    nginx-РєРѕРЅС„РёРіРё РїРµСЂРµРІСЏР·Р°РЅС‹ РЅР° Р»РёРЅРёСЋ"
    fi
    if [[ -f /opt/AdGuardHome/AdGuardHome.yaml ]] && grep -q "$old" /opt/AdGuardHome/AdGuardHome.yaml 2>/dev/null; then
      sed -i "s|$old|$new|g" /opt/AdGuardHome/AdGuardHome.yaml 2>/dev/null || true
      systemctl restart AdGuardHome 2>/dev/null || systemctl restart adguardhome 2>/dev/null || true
      log "    AdGuard РїРµСЂРµРІСЏР·Р°РЅ РЅР° Р»РёРЅРёСЋ"
    fi
    # 2) СѓРґР°Р»РёС‚СЊ РїРµСЂСЃРѕРЅР°Р»СЊРЅСѓСЋ Р»РёРЅРёСЋ
    if certbot delete --cert-name "$dn" --non-interactive 2>&1 | tail -2 | sed 's/^/    /'; then
      log "  СѓРґР°Р»РµРЅРѕ: $dn (РїРѕРєСЂС‹С‚РёРµ вЂ” Р»РёРЅРёСЏ $(basename "$cn2"))"
      did=$((did+1))
    else
      warn "  РЅРµ СѓРґР°Р»РѕСЃСЊ СѓРґР°Р»РёС‚СЊ $dn вЂ” СЃСЃС‹Р»РєРё СѓР¶Рµ РїРµСЂРµРІСЏР·Р°РЅС‹, СЃРЅРµСЃРё РІСЂСѓС‡РЅСѓСЋ: certbot delete --cert-name $dn"
    fi
  done
  if [[ $did -gt 0 ]]; then
    nginx -t >/dev/null 2>&1 && nginx_reload || true
    log "Р“РѕС‚РѕРІРѕ: РґСѓР±Р»РµР№ РїРѕРєСЂС‹С‚РёСЏ СѓСЃС‚СЂР°РЅРµРЅРѕ вЂ” $did"
  else
    log "РќРёС‡РµРіРѕ РЅРµ РёР·РјРµРЅРµРЅРѕ."
  fi
  pause
  return 0
}

# РђРІС‚РѕРѕС‡РёСЃС‚РєР° СЃРёСЂРѕС‚: Р»РёРЅРёРё РІ live/, РєРѕС‚РѕСЂС‹Рµ РЅРµ РёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ.
# РџРѕРєР°Р·С‹РІР°РµС‚ СЃРїРёСЃРѕРє, СЃРїСЂР°С€РёРІР°РµС‚ РїРѕ РєР°Р¶РґРѕР№, СѓРґР°Р»СЏРµС‚ РїРѕ certbot delete.
cert_lines_cleanup() {
  line; echo -e "${B}   РћР§РРЎРўРљРђ РЎРР РћРў (Р»РёРЅРёРё, РєРѕС‚РѕСЂС‹Рµ РЅРёРіРґРµ РЅРµ РёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ)${N}"; line
  [[ -d /etc/letsencrypt/live ]] || { warn "РќРµС‚ /etc/letsencrypt/live"; pause; return 0; }

  local -a orphans=()
  local ld name
  for ld in /etc/letsencrypt/live/*/; do
    [[ -d "$ld" ]] || continue
    name=$(basename "$ld")
    [[ "$name" =~ -[0-9]{4}$ ]] && continue   # -0001 РѕР±СЂР°Р±Р°С‚С‹РІР°РµС‚ cert_dedup_0001
    if ! cert_line_is_used "$name"; then
      orphans+=("$name")
    fi
  done

  if [[ ${#orphans[@]} -eq 0 ]]; then
    log "РЎРёСЂРѕС‚ РЅРµ РЅР°Р№РґРµРЅРѕ вЂ” РІСЃС‘ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ"
    pause; return 0
  fi

  echo "РќР°Р№РґРµРЅС‹ СЃРёСЂРѕС‚С‹ (РЅРµ РёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ РЅРёРіРґРµ):"
  local n=0
  for name in "${orphans[@]}"; do
    n=$((n+1))
    local fc="/etc/letsencrypt/live/$name/fullchain.pem"
    local san="вЂ”" exp="вЂ”"
    if [[ -f "$fc" ]]; then
      san=$(openssl x509 -noout -ext subjectAltName -in "$fc" 2>/dev/null \
            | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr -d ' ' | tr '\n' ',' | sed 's/,$//')
      exp=$(openssl x509 -noout -enddate -in "$fc" 2>/dev/null | cut -d= -f2)
    fi
    printf "  %2d) %s\n" "$n" "$name"
    echo "      SAN: $san"
    echo "      РСЃС‚РµРєР°РµС‚: $exp"
  done
  echo
  echo "  1) РЈРґР°Р»РёС‚СЊ Р’РЎР• РЅР°Р№РґРµРЅРЅС‹Рµ СЃРёСЂРѕС‚С‹ (СЃ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµРј)"
  echo "  2) Р’С‹Р±СЂР°С‚СЊ РїРѕ РѕРґРЅРѕР№"
  echo "  0) РћС‚РјРµРЅР°"
  line
  local c=""
  read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
  case "$c" in
    1)
      local sure=""
      ask sure "РЈРґР°Р»РёС‚СЊ Р’РЎР• СЃРёСЂРѕС‚С‹ (${#orphans[@]} С€С‚.)? Р’РІРµРґРё YES" "" '^YES$'
      [[ "$sure" == "YES" ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; pause; return 0; }
      for name in "${orphans[@]}"; do
        log "РЈРґР°Р»СЏСЋ $name вЂ¦"
        certbot delete --cert-name "$name" --non-interactive 2>&1 | tail -2 | sed 's/^/    /'
      done
      log "Р“РѕС‚РѕРІРѕ"
      ;;
    2)
      for name in "${orphans[@]}"; do
        local sure=""
        askyn sure "РЈРґР°Р»РёС‚СЊ В«$nameВ»?" "n"
        if [[ "$sure" == true ]]; then
          certbot delete --cert-name "$name" --non-interactive 2>&1 | tail -2 | sed 's/^/    /'
          log "  СѓРґР°Р»РµРЅРѕ"
        fi
      done
      ;;
    *) pause; return 0 ;;
  esac
  pause
}

# Р Р°СЃС€РёСЂРµРЅРЅС‹Р№ Р°СѓРґРёС‚ РґР»СЏ СЂРµР¶РёРјР° B: РїРѕРєР°Р·С‹РІР°РµС‚ РІСЃРµ Р»РёРЅРёРё + РёС… SAN + РёСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ.
cert_lines_audit() {
  line; echo -e "${B}   РђРЈР”РРў Р›РРќРР™ РЎР•Р РўРћР’${N}"; line
  cert_mode_load >/dev/null 2>&1 || true
  echo "  Р РµР¶РёРј: ${CERT_MODE:-A}"
  echo

  cert_lines_load
  if [[ ${#CERT_LINES[@]} -eq 0 ]]; then
    warn "Р›РёРЅРёРё РЅРµ РЅР°Р№РґРµРЅС‹"
    pause; return 0
  fi
  local ln d n
  for ln in "${CERT_LINES[@]}"; do
    cert_line_domains_load "$ln"
    n=${#CERT_LINE_DOMAINS[@]}
    echo "  в–ё Р›РёРЅРёСЏ В«$lnВ» ($n РґРѕРј.)"
    echo "      Р”РѕРјРµРЅС‹ SAN:"
    for d in "${CERT_LINE_DOMAINS[@]}"; do echo "        $d"; done
    local ldir="/etc/letsencrypt/live/$ln"
    if [[ -f "$ldir/fullchain.pem" ]]; then
      local end left
      end=$(openssl x509 -noout -enddate -in "$ldir/fullchain.pem" 2>/dev/null | cut -d= -f2)
      left=$(( ($(date -d "$end" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
      echo "      РЎРµСЂС‚: РµСЃС‚СЊ (~$left РґРЅ, РґРѕ $end)"
      # РџСЂРѕРІРµСЂРєР°: SAN СЃРµСЂС‚Р° == SAN РІ С„Р°Р№Р»Рµ?
      local cur_san want_san
      cur_san=$(openssl x509 -noout -ext subjectAltName -in "$ldir/fullchain.pem" 2>/dev/null \
                | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr -d ' ' | sort | tr '\n' ',')
      want_san=$(printf '%s\n' "${CERT_LINE_DOMAINS[@]}" | sort -u | tr '\n' ',')
      if [[ "${cur_san%,}" == "${want_san%,}" ]]; then
        echo "      SAN СЃРѕРІРїР°РґР°РµС‚: вњ“"
      else
        warn "      SAN Р РђРЎРҐРћР”РРўРЎРЇ:"
        echo "        СЃРµСЂС‚:  ${cur_san%,}"
        echo "        С„Р°Р№Р»:  ${want_san%,}"
      fi
    else
      warn "      РЎРµСЂС‚: РќР• РІС‹РїСѓС‰РµРЅ"
    fi
    echo
  done
  pause
}

# РђСѓРґРёС‚ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ: РєР°РєРёРµ Р»РёРЅРёРё РІ live/, РіРґРµ РёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ, РєР°РєРёРµ СЃРёСЂРѕС‚С‹.
# РќРёС‡РµРіРѕ РЅРµ СѓРґР°Р»СЏРµС‚ вЂ” С‚РѕР»СЊРєРѕ РїРѕРєР°Р·С‹РІР°РµС‚.
cert_audit() {
  line; echo -e "${B}   РђРЈР”РРў РЎР•Р РўРР¤РРљРђРўРћР’${N}"; line
  [[ -d /etc/letsencrypt/live ]] || { warn "РќРµС‚ /etc/letsencrypt/live"; pause; return 0; }

  # 1. РђРєС‚РёРІРЅС‹Рµ РґРѕРјРµРЅС‹ РёР· 3 РёСЃС‚РѕС‡РЅРёРєРѕРІ
  local active_domains=""
  # Р‘Р” x-ui
  local _wd _sd
  _wd=$(xui_get webDomain 2>/dev/null || true); _sd=$(xui_get subDomain 2>/dev/null || true)
  [[ -n "$_wd" && "$_wd" != "null" ]] && active_domains+=" $_wd"
  [[ -n "$_sd" && "$_sd" != "null" && "$_sd" != "$_wd" ]] && active_domains+=" $_sd"

  # stack-domains.txt
  if [[ -s "$CERT_DOMAINS_FILE" ]]; then
    local d
    while IFS= read -r d; do
      d="$(printf '%s' "$d" | tr -d '[:space:]')"
      [[ -n "$d" ]] && active_domains+=" $d"
    done < "$CERT_DOMAINS_FILE"
  fi

  # SNI-РєР°СЂС‚Р°: РґРѕРјРµРЅС‹ РёР· Р±Р»РѕРєР° map (С‚РѕР»СЊРєРѕ РїРµСЂРІРѕРµ РїРѕР»Рµ СЃС‚СЂРѕРє Р’РќРЈРўР Р map)
  if [[ -f "$SNI_CONF" ]]; then
    local sd
    while IFS= read -r sd; do
      [[ -n "$sd" && "$sd" != "default" && "$sd" != "_" ]] && active_domains+=" $sd"
    done < <(awk '
      /^map / { inmap=1; next }
      inmap && /^}/ { inmap=0 }
      inmap && /^[[:space:]]/ && NF >= 2 {
        dom = $1
        sub(/;$/, "", dom)
        if (dom != "" && dom != "default") print dom
      }
    ' "$SNI_CONF" 2>/dev/null | sort -u)
  fi

  # server_name РІ stack.conf
  if [[ -f "$STACK_CONF" ]]; then
    local sn
    while IFS= read -r sn; do
      [[ -n "$sn" && "$sn" != "_" ]] && active_domains+=" $sn"
    done < <(grep -oE '^\s*server_name\s+[^;]+;' "$STACK_CONF" 2>/dev/null | sed 's/server_name//; s/;//; s/^\s*//; s/\s*$//' | tr ' ' '\n' | sort -u)
  fi

  # РЈРЅРёРєР°Р»РёР·Р°С†РёСЏ
  active_domains=$(printf '%s\n' "$active_domains" | tr ' ' '\n' | sed '/^$/d' | sort -u | tr '\n' ' ')
  echo -e "${B}в–ё РђРєС‚РёРІРЅС‹Рµ РґРѕРјРµРЅС‹ СЃС‚РµРєР°:${N}"
  echo "  $active_domains"
  echo

  # 2. Р’СЃРµ Р»РёРЅРёРё РІ live/
  echo -e "${B}в–ё Р›РёРЅРёРё РІ /etc/letsencrypt/live/:${N}"
  local total=0 orphans=0
  local ld
  for ld in /etc/letsencrypt/live/*/; do
    [[ -d "$ld" ]] || continue
    local name
    name=$(basename "$ld")
    (( total++ ))
    local fc="$ld/fullchain.pem"
    [[ -f "$fc" ]] || { warn "  $name вЂ” РќР•Рў fullchain.pem (Р±РёС‚Р°СЏ Р»РёРЅРёСЏ)"; continue; }

    # SAN
    local san=""
    san=$(openssl x509 -noout -ext subjectAltName -in "$fc" 2>/dev/null \
          | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr '\n' ',' | sed 's/,$//')

    # РЎСЂРѕРє
    local end left
    end=$(openssl x509 -noout -enddate -in "$fc" 2>/dev/null | cut -d= -f2)
    left=$(( ($(date -d "$end" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))

    # РСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ
    local used_in=""
    local in_db=0 in_nginx=0 in_sni=0 in_domains=0

    # РІ Р‘Р”? РЎРµСЂС‚РёС„РёРєР°С‚С‹ sidecar-РёРЅР±Р°СѓРЅРґРѕРІ Р»РµР¶Р°С‚ РІ JSON settings,
    # РїРѕСЌС‚РѕРјСѓ РёС‰РµРј РЅРµ С‚РѕР»СЊРєРѕ РІ С‚Р°Р±Р»РёС†Рµ settings РїР°РЅРµР»Рё.
    local refs refs_json
    refs=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
      "SELECT COUNT(*) FROM settings WHERE value LIKE '%/live/$name/%';" 2>/dev/null || echo 0)
    refs_json=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
      "SELECT COUNT(*) FROM inbounds WHERE settings LIKE '%/live/$name/%' OR stream_settings LIKE '%/live/$name/%';" 2>/dev/null || echo 0)
    if [[ "$refs" != "0" || "$refs_json" != "0" ]]; then
      in_db=1; used_in+=" Р‘Р”"
    fi

    # РІ nginx?
    if [[ -f "$STACK_CONF" ]] && grep -q "/live/$name/" "$STACK_CONF" 2>/dev/null; then
      in_nginx=1; used_in+=" nginx"
    fi

    # РІ SNI-РєР°СЂС‚Рµ? (РїРѕ РёРјРµРЅРё РєР°Рє РґРѕРјРµРЅ). Р”Р»СЏ wildcard-РїСѓС‚Рё cert-name
    # РјРѕР¶РµС‚ РѕС‚Р»РёС‡Р°С‚СЊСЃСЏ РѕС‚ SNI-РґРѕРјРµРЅР°, РїРѕСЌС‚РѕРјСѓ JSON/Р‘Р” РїСЂРѕРІРµСЂСЏСЋС‚СЃСЏ РѕС‚РґРµР»СЊРЅРѕ.
    if [[ -f "$SNI_CONF" ]] && grep -qE "^[[:space:]]+${name}[[:space:]]+" "$SNI_CONF" 2>/dev/null; then
      in_sni=1; used_in+=" SNI"
    fi
    if [[ "$in_db" == 1 && "$used_in" != *"SNI"* ]]; then
      : # СѓР¶Рµ РѕС‚РјРµС‡РµРЅРѕ С‡РµСЂРµР· settings JSON
    fi

    # РІ stack-domains.txt?
    if [[ -s "$CERT_DOMAINS_FILE" ]] && grep -qxF "$name" "$CERT_DOMAINS_FILE" 2>/dev/null; then
      in_domains=1; used_in+=" domains.txt"
    fi

    # РЎР°РЅ СЃРѕРґРµСЂР¶РёС‚ Р»СЋР±РѕР№ Р°РєС‚РёРІРЅС‹Р№ РґРѕРјРµРЅ?
    local covers_active=0
    local ad
    for ad in $active_domains; do
      [[ -z "$ad" ]] && continue
      if grep -qE "(^|,)\s*$ad(\s*,|$)" <<<"$(tr ',' '\n' <<<"$san")" 2>/dev/null; then
        covers_active=1; break
      fi
      # wildcard-РїСЂРѕРІРµСЂРєР°
      if grep -qE "(^|,)\s*\*\.${ad#*.}(\s*,|$)" <<<"$(tr ',' '\n' <<<"$san")" 2>/dev/null; then
        covers_active=1; break
      fi
    done

    # Р’РµСЂРґРёРєС‚
    local verdict
    if [[ $((in_db + in_nginx + in_sni + in_domains)) -gt 0 ]]; then
      verdict="${G}вњ“ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ${N} (${used_in# })"
    elif [[ "$covers_active" == "1" ]]; then
      verdict="${Y}? РЅРµ РїСЂРёРІСЏР·Р°РЅ, РЅРѕ SAN РїРѕРєСЂС‹РІР°РµС‚ Р°РєС‚РёРІРЅС‹Р№ РґРѕРјРµРЅ${N}"
    else
      verdict="${R}вњ— РЎРР РћРўРђ (РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РЅРёРіРґРµ)${N}"
      (( orphans++ ))
    fi

    echo "  в”Ђ $name"
    echo "      SAN:     $san"
    echo "      РЎСЂРѕРє:    $end (~$left РґРЅ)"
    echo -e "      РЎС‚Р°С‚СѓСЃ:  $verdict"
  done

  echo
  echo "  Р’СЃРµРіРѕ Р»РёРЅРёР№: $total В· РЎРёСЂРѕС‚: $orphans"
  if [[ $orphans -gt 0 ]]; then
    warn "РЈРґР°Р»РёС‚СЊ СЃРёСЂРѕС‚ РјРѕР¶РЅРѕ С‡РµСЂРµР· Рї.10 в†’ 12 (РёР»Рё РІСЂСѓС‡РЅСѓСЋ: certbot delete --cert-name <name>)"
  fi
  line
  pause
}

# РРЅС‚РµСЂР°РєС‚РёРІРЅРѕРµ СѓРґР°Р»РµРЅРёРµ СЃРµСЂС‚РѕРІ. РџРѕРєР°Р·С‹РІР°РµС‚ СЃРїРёСЃРѕРє, РґР°С‘С‚ РІС‹Р±СЂР°С‚СЊ, С‚СЂРµР±СѓРµС‚
# РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РґР»СЏ РёСЃРїРѕР»СЊР·СѓРµРјС‹С…. Р—Р°С‰РёС‰Р°РµС‚ РѕС‚ СЃР»СѓС‡Р°Р№РЅРѕРіРѕ СѓРґР°Р»РµРЅРёСЏ.
cert_delete_menu() {
  line; echo -e "${B}   РЈР”РђР›Р•РќРР• РЎР•Р РўРђ${N}"; line
  [[ -d /etc/letsencrypt/live ]] || { warn "РќРµС‚ /etc/letsencrypt/live"; pause; return 0; }

  local -a lines=()
  local ld
  for ld in /etc/letsencrypt/live/*/; do
    [[ -d "$ld" ]] || continue
    lines+=("$(basename "$ld")")
  done

  [[ ${#lines[@]} -eq 0 ]] && { warn "РЎРµСЂС‚РѕРІ РЅРµС‚"; pause; return 0; }

  echo "Р”РѕСЃС‚СѓРїРЅС‹Рµ Р»РёРЅРёРё:"
  local i=1 name
  for name in "${lines[@]}"; do
    local fc="/etc/letsencrypt/live/$name/fullchain.pem"
    local san="" exp=""
    if [[ -f "$fc" ]]; then
      san=$(openssl x509 -noout -ext subjectAltName -in "$fc" 2>/dev/null | grep -oE 'DNS:[^,]+' | sed 's/DNS://g' | tr '\n' ',' | sed 's/,$//')
      exp=$(openssl x509 -noout -enddate -in "$fc" 2>/dev/null | cut -d= -f2)
    fi

    # РСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ
    local used=""
    local refs
    refs=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
      "SELECT COUNT(*) FROM settings WHERE value LIKE '%/live/$name/%';" 2>/dev/null || echo 0)
    [[ "$refs" != "0" ]] && used+=" Р‘Р”"
    [[ -f "$STACK_CONF" ]] && grep -q "/live/$name/" "$STACK_CONF" 2>/dev/null && used+=" nginx"

    local mark=""
    if [[ -n "$used" ]]; then mark="${R}[РРЎРџРћР›Р¬Р—РЈР•РўРЎРЇ:${used# }]${N}"; else mark="${G}[РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ]${N}"; fi

    printf "  %2d) %-30s %s\n" "$i" "$name" "$mark"
    printf "        SAN: %s\n" "${san:-вЂ”}"
    printf "        РЎСЂРѕРє: %s\n" "${exp:-вЂ”}"
    i=$((i+1))
  done
  echo
  local pick=""
  ask pick "РќРѕРјРµСЂ Р»РёРЅРёРё РґР»СЏ СѓРґР°Р»РµРЅРёСЏ (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
  [[ "$pick" == "0" ]] && return 0
  (( pick < 1 || pick > ${#lines[@]} )) && { err "РќРµС‚ С‚Р°РєРѕРіРѕ"; pause; return 1; }
  local target="${lines[$((pick-1))]}"

  # РџСЂРѕРІРµСЂРєР° РёСЃРїРѕР»СЊР·РѕРІР°РЅРёСЏ в†’ С‚СЂРµР±СѓРµС‚ YES
  local in_use=""
  local refs
  refs=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "SELECT COUNT(*) FROM settings WHERE value LIKE '%/live/$target/%';" 2>/dev/null || echo 0)
  [[ "$refs" != "0" ]] && in_use+=" Р‘Р”"
  [[ -f "$STACK_CONF" ]] && grep -q "/live/$target/" "$STACK_CONF" 2>/dev/null && in_use+=" nginx"

  echo
  if [[ -n "$in_use" ]]; then
    warn "вљ  Р›РёРЅРёСЏ В«$targetВ» РРЎРџРћР›Р¬Р—РЈР•РўРЎРЇ: ${in_use# }"
    warn "  РЈРґР°Р»РµРЅРёРµ СЃР»РѕРјР°РµС‚ TLS РґР»СЏ СЌС‚РёС… СЃРµСЂРІРёСЃРѕРІ!"
    local sure=""
    ask sure "Р”Р»СЏ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РІРІРµРґРё YES" "" '^YES$'
    [[ "$sure" == "YES" ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; pause; return 0; }
  else
    local sure=""
    askyn sure "РЈРґР°Р»РёС‚СЊ В«$targetВ»?" "n"
    [[ "$sure" == true ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; pause; return 0; }
  fi

  log "РЈРґР°Р»СЏСЋ $target вЂ¦"
  if certbot delete --cert-name "$target" --non-interactive 2>&1 | sed 's/^/    /'; then
    log "Р›РёРЅРёСЏ В«$targetВ» СѓРґР°Р»РµРЅР°"
  else
    err "certbot delete РІРµСЂРЅСѓР» РѕС€РёР±РєСѓ"
  fi
  pause
}

# СЃС‚Р°С‚РёСЃС‚РёРєР° decoy-РїРѕСЃРµС‰РµРЅРёР№ Р·Р° 24С‡ (РїР°СЂСЃРёРЅРі decoy_ext С‡РµСЂРµР· python3)
cert_wildcard_issue() {
  le_email_load || true
  if [[ -z "$EMAIL" ]]; then
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$'
    le_email_save "$EMAIL"
  fi
  local base="${1:-}"
  if [[ -z "$base" ]]; then
    ask base "Р‘Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ wildcard (РЅР°РїСЂ. example.com)" "${WILDCARD_DOMAIN:-}" '^[a-zA-Z0-9.-]+$'
  fi
  [[ -z "$base" ]] && return 1

  # --- РїСЂРѕРІРµСЂРєР°: wildcard СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ в†’ РїРµСЂРµСѓСЃС‚Р°РЅР°РІР»РёРІР°С‚СЊ РЅРµ РЅСѓР¶РЅРѕ ---
  local wdir="/etc/letsencrypt/live/$base"
  if [[ -f "$wdir/fullchain.pem" && -f "$wdir/privkey.pem" ]]; then
    local exp="" days_left=-1
    exp=$(openssl x509 -enddate -noout -in "$wdir/fullchain.pem" 2>/dev/null | cut -d= -f2 || true)
    [[ -n "$exp" ]] && days_left=$(( ( $(date -d "$exp" +%s 2>/dev/null || echo 0) - $(date +%s) ) / 86400 ))
    if [[ "$days_left" -gt 30 ]]; then
      echo "$base" > "$WILDCARD_STATE" 2>/dev/null || true
      WILDCARD_DOMAIN="$base"
      log "Wildcard *.$base СѓР¶Рµ РІС‹РїСѓС‰РµРЅ (РёСЃС‚РµРєР°РµС‚ С‡РµСЂРµР· $days_left РґРЅ.) вЂ” РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєР° РЅРµ РЅСѓР¶РЅР°"
      return 0
    fi
    warn "Wildcard *.$base РёСЃС‚РµРєР°РµС‚ С‡РµСЂРµР· $days_left РґРЅ. вЂ” РѕР±РЅРѕРІР»СЏСЋ"
  fi

  # РїР»Р°РіРёРЅ DNS-01 РґР»СЏ Cloudflare
  if ! certbot plugins 2>/dev/null | grep -q dns-cloudflare; then
    log "РЈСЃС‚Р°РЅРѕРІРєР° РїР»Р°РіРёРЅР° python3-certbot-dns-cloudflare..."
    apt-get update -y >/dev/null 2>&1 || true
    apt-get install -y python3-certbot-dns-cloudflare >/dev/null 2>&1 \
      || { err "РќРµ СѓРґР°Р»РѕСЃСЊ СѓСЃС‚Р°РЅРѕРІРёС‚СЊ python3-certbot-dns-cloudflare"; return 1; }
  fi

  # API Token (СЃРѕС…СЂР°РЅСЏРµС‚СЃСЏ РѕРґРёРЅ СЂР°Р·)
  local need_token=true
  if [[ -f "$CF_CREDS" ]] && grep -q 'dns_cloudflare_api_token' "$CF_CREDS" 2>/dev/null; then
    askyn reuse "РСЃРїРѕР»СЊР·РѕРІР°С‚СЊ СЃРѕС…СЂР°РЅС‘РЅРЅС‹Р№ Cloudflare API Token ($CF_CREDS)?" "y"
    # shellcheck disable=SC2154 # Р·Р°РґР°С‘С‚СЃСЏ askyn РІС‹С€Рµ
    [[ "$reuse" == true ]] && need_token=false
  fi
  if [[ "$need_token" == true ]]; then
    echo "РЎРѕР·РґР°Р№С‚Рµ С‚РѕРєРµРЅ: Cloudflare в†’ My Profile в†’ API Tokens в†’ 'Edit zone DNS'"
    echo "РџСЂР°РІР°: Zone / DNS / Edit РґР»СЏ Р·РѕРЅС‹ $base"
    local token=""
    ask token "Cloudflare API Token" "" '.+'
    mkdir -p "$(dirname "$CF_CREDS")" 2>/dev/null || true
    cat > "$CF_CREDS" <<EOF
# Cloudflare API Token (Zone:DNS:Edit) вЂ” РґР»СЏ wildcard-СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ
dns_cloudflare_api_token = $token
EOF
    chmod 600 "$CF_CREDS" 2>/dev/null || true
  fi

  log "Р’С‹РїСѓСЃРє wildcard: $base + *.$base (DNS-01 Cloudflare)..."
  local out=""
  out=$(certbot certonly \
    --dns-cloudflare \
    --dns-cloudflare-credentials "$CF_CREDS" \
    --dns-cloudflare-propagation-seconds 30 \
    --non-interactive --agree-tos --email "$EMAIL" \
    --cert-name "$base" \
    -d "$base" -d "*.$base" 2>&1 || true)

  local wdir="/etc/letsencrypt/live/$base"
  if [[ -f "$wdir/fullchain.pem" && -f "$wdir/privkey.pem" ]]; then
    # С…СѓРє РїРµСЂРµР·Р°РіСЂСѓР·РєРё nginx РїРѕСЃР»Рµ Р°РІС‚РѕРїСЂРѕРґР»РµРЅРёСЏ
    mkdir -p /etc/letsencrypt/renewal-hooks-deploy 2>/dev/null || true
    cat > /etc/letsencrypt/renewal-hooks-deploy/reload-nginx.sh <<'HOOK'
#!/bin/sh
systemctl reload nginx 2>/dev/null || true
HOOK
    chmod +x /etc/letsencrypt/renewal-hooks-deploy/reload-nginx.sh 2>/dev/null || true
    echo "$base" > "$WILDCARD_STATE" 2>/dev/null || true
    WILDCARD_DOMAIN="$base"
    log "Wildcard cert РіРѕС‚РѕРІ: $wdir"
    log "  РїРѕРєСЂС‹РІР°РµС‚: $base Рё *.$base вЂ” РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рµ СЃРµСЂС‚РёС„РёРєР°С‚С‹ Р±РѕР»СЊС€Рµ РЅРµ РЅСѓР¶РЅС‹"
    return 0
  fi
  err "  certbot РѕС‚РєР°Р·Р°Р»:"
  echo "$out" | tail -12 | sed 's/^/    /'
  err "  РРўРћР“: wildcard *.$base РќР• РІС‹РїСѓС‰РµРЅ вЂ” РґР°Р»СЊРЅРµР№С€Р°СЏ РЅР°СЃС‚СЂРѕР№РєР° РѕСЃС‚Р°РЅРѕРІР»РµРЅР°."
  cert_error_pause
  return 1
}

wildcard_toggle() {
  echo
  echo "в–ё Wildcard Cloudflare: ${WILDCARD_DOMAIN:-РІС‹РєР»СЋС‡РµРЅ}"
  if [[ -n "$WILDCARD_DOMAIN" ]]; then
    echo "  1) РѕС‚РєР»СЋС‡РёС‚СЊ (РІРµСЂРЅСѓС‚СЊ РїСЂРёРѕСЂРёС‚РµС‚ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Рј СЃРµСЂС‚РёС„РёРєР°С‚Р°Рј)"
    echo "  2) СЃРјРµРЅРёС‚СЊ Р±Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ / РїРµСЂРµРІС‹РїСѓСЃС‚РёС‚СЊ"
    echo "  0) РќР°Р·Р°Рґ"
    local c=""
    ask c "Р’С‹Р±РѕСЂ" "0" '^[0-9]$'
    case "$c" in
      1) rm -f "$WILDCARD_STATE" 2>/dev/null || true; WILDCARD_DOMAIN=""; log "Wildcard РѕС‚РєР»СЋС‡С‘РЅ" ;;
      2) cert_wildcard_issue ;;
    esac
  else
    local on=false
    askyn on "Р’РєР»СЋС‡РёС‚СЊ wildcard вЂ” РѕРґРёРЅ cert Cloudflare РЅР° РІСЃРµ РїРѕРґРґРѕРјРµРЅС‹?" "y"
    [[ "$on" == true ]] && cert_wildcard_issue
  fi
}

# =====================================================================
# NGINX РҐР•Р›РџР•Р Р«
# =====================================================================
sni_conf_ensure() {
  local d
  d=$(dirname "$SNI_CONF")
  mkdir -p "$d" /etc/nginx/streams-enabled /etc/nginx/streams-available 2>/dev/null || true
  # SNI_CONF СѓР¶Рµ РЅР°С…РѕРґРёС‚СЃСЏ РІ streams-enabled. РќРµР»СЊР·СЏ СЃРѕР·РґР°РІР°С‚СЊ СЃСЃС‹Р»РєСѓ
  # /streams-enabled/sni-router.conf -> СЃР°РјРѕРјСѓ СЃРµР±Рµ: СЌС‚Рѕ РґР°С‘С‚ ELOOP.
  if [[ -L "$SNI_CONF" ]]; then
    local _sni_target=""
    _sni_target=$(readlink -f "$SNI_CONF" 2>/dev/null || true)
    rm -f "$SNI_CONF" 2>/dev/null || true
    # Р•СЃР»Рё СЃС‚Р°СЂС‹Р№ self-link Р±С‹Р» РµРґРёРЅСЃС‚РІРµРЅРЅС‹Рј РѕР±СЉРµРєС‚РѕРј, СЃРѕР·РґР°С‘Рј РѕР±С‹С‡РЅС‹Р№ С„Р°Р№Р».
    [[ -n "$_sni_target" && -f "$_sni_target" && "$_sni_target" != "$SNI_CONF" ]] && cp -f "$_sni_target" "$SNI_CONF" 2>/dev/null || true
  fi
  if [[ ! -s "$SNI_CONF" ]]; then
    cat > "$SNI_CONF" <<'EOF'
map $ssl_preread_server_name $backend {
    default panel_backend;
}
upstream panel_backend { server 127.0.0.1:4443; }
server {
    listen 443;
    proxy_pass $backend;
    ssl_preread on;
    proxy_connect_timeout 5s;
    proxy_timeout 10m;
}
EOF
  fi
}
sni_upstream_add() {
  local name="$1" port="$2"
  sni_conf_ensure
  grep -q "upstream $name " "$SNI_CONF" 2>/dev/null && return 0
  if grep -q "^upstream panel_backend" "$SNI_CONF" 2>/dev/null; then
    sed -i "/^upstream panel_backend/i upstream $name { server 127.0.0.1:$port; }" "$SNI_CONF"
  else
    # РЅРµС‚ СЏРєРѕСЂСЏ panel_backend вЂ” РІСЃС‚Р°РІР»СЏРµРј РІ РЅР°С‡Р°Р»Рѕ С„Р°Р№Р»Р°
    sed -i "1i upstream $name { server 127.0.0.1:$port; }" "$SNI_CONF"
  fi
}
sni_upstream_remove() { sed -i "/^upstream $1 /d" "$SNI_CONF" 2>/dev/null || true; }

sni_conf_repair_map() {
  # РЈРґР°Р»СЏРµС‚ РёР· map РїРѕРІСЂРµР¶РґС‘РЅРЅС‹Рµ СЃС‚СЂРѕРєРё СЃ Р»РёС€РЅРёРјРё РїР°СЂР°РјРµС‚СЂР°РјРё. РўР°РєРёРµ СЃС‚СЂРѕРєРё
  # РІРѕР·РЅРёРєР°СЋС‚ РїРѕСЃР»Рµ СЃС‚Р°СЂС‹С…/РїСЂРµСЂРІР°РЅРЅС‹С… Р·Р°РїСѓСЃРєРѕРІ CDN Рё РґРµР»Р°СЋС‚ nginx -t С„Р°С‚Р°Р»СЊРЅС‹Рј.
  [[ -f "$SNI_CONF" && ! -L "$SNI_CONF" ]] || return 0
  awk '
    /^[[:space:]]*map[[:space:]]/ { inmap=1; print; next }
    inmap && /^[[:space:]]*}/ { inmap=0; print; next }
    inmap {
      line=$0; sub(/^[[:space:]]+/,"",line); sub(/[[:space:]]+$/, "", line)
      if (line == "" || line ~ /^#/) next
      n=split(line,a,/[[:space:]]+/)
      if (n == 2) {
        sub(/;$/, "", a[2])
        print "    " a[1] "    " a[2] ";"
      }
      next
    }
    { print }
  ' "$SNI_CONF" > "$SNI_CONF.tmp" && mv "$SNI_CONF.tmp" "$SNI_CONF"
}
sni_map_add() {
  local domain="$1" backend="$2"
  [[ "$domain" =~ ^[A-Za-z0-9._-]+$ && "$backend" =~ ^[A-Za-z0-9._-]+$ ]] || return 1
  sni_conf_ensure
  sni_conf_repair_map
  # Р’ map nginx РєР°Р¶РґС‹Р№ РґРѕРјРµРЅ РґРѕР»Р¶РµРЅ РІСЃС‚СЂРµС‡Р°С‚СЊСЃСЏ СЂРѕРІРЅРѕ РѕРґРёРЅ СЂР°Р·. Р•СЃР»Рё СЃС‚Р°СЂС‹Р№
  # Р·Р°РїСѓСЃРє РѕСЃС‚Р°РІРёР» РґСѓР±Р»РёРєР°С‚С‹, СѓРґР°Р»СЏРµРј РёС… РїРµСЂРµРґ РґРѕР±Р°РІР»РµРЅРёРµРј РЅРѕРІРѕРіРѕ РјР°СЂС€СЂСѓС‚Р°.
  awk -v dom="$domain" -v be="$backend" '
    BEGIN { inmap=0; kept=0 }
    /^[[:space:]]*map[[:space:]]/ { inmap=1; print; next }
    inmap && /^[[:space:]]*}/ { inmap=0; print; next }
    inmap && $1 == dom {
      if (!kept) { print "    " dom "    " be ";"; kept=1 }
      next
    }
    { print }
  ' "$SNI_CONF" > "$SNI_CONF.tmp" && mv "$SNI_CONF.tmp" "$SNI_CONF"
  if awk -v dom="$domain" '$1 == dom { found=1 } END { exit(found ? 0 : 1) }' "$SNI_CONF" 2>/dev/null; then
    awk -v dom="$domain" -v be="$backend" 'BEGIN{OFS=" "} $1 == dom {$0="    " dom "    " be ";"} {print}' "$SNI_CONF" > "$SNI_CONF.tmp" && mv "$SNI_CONF.tmp" "$SNI_CONF"
    return 0
  fi
  awk -v dom="$domain" -v be="$backend" '
    /^[[:space:]]*map[[:space:]]/ { inmap=1 }
    inmap && /^[[:space:]]*}/ && !done { print "    " dom "    " be ";"; done=1 }
    { print }
  ' "$SNI_CONF" > "$SNI_CONF.tmp" && mv "$SNI_CONF.tmp" "$SNI_CONF"
  sni_conf_repair_map
}
sni_map_remove() { sed -i "/^[[:space:]]*${1}[[:space:]]\+/d" "$SNI_CONF" 2>/dev/null || true; }
# РЈРґР°Р»РµРЅРёРµ РїРѕ backend РЅР°РґС‘Р¶РЅРµРµ РґРѕРјРµРЅРЅРѕРіРѕ РёРјРµРЅРё: С‡РёСЃС‚РёС‚ SNI РґР°Р¶Рµ РµСЃР»Рё СЃС‚СЂРѕРєР°
# Р±С‹Р»Р° РѕС‚С„РѕСЂРјР°С‚РёСЂРѕРІР°РЅР° РЅРµСЃС‚Р°РЅРґР°СЂС‚РЅРѕ РёР»Рё РґРѕРјРµРЅ РЅРµ РїСЂРѕС‡РёС‚Р°Р»СЃСЏ РёР· РєР°СЂС‚С‹.
sni_map_remove_backend() { sed -i "/^[[:space:]]*[A-Za-z0-9.-][A-Za-z0-9.-]*[[:space:]]\+${1};[[:space:]]*$/d" "$SNI_CONF" 2>/dev/null || true; }

nginx_reload() {
  if ! command -v nginx >/dev/null 2>&1; then
    warn "nginx РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” РїСЂРѕРІРµСЂРєР°/РїРµСЂРµР·Р°РіСЂСѓР·РєР° РїСЂРѕРїСѓС‰РµРЅР°"
    return 0
  fi
  # РЎРўР РРњ-РєРѕРЅС„РёРі (443/SNI) РѕР±СЏР·Р°РЅ Р±С‹С‚СЊ РїРѕРґРєР»СЋС‡С‘РЅ Р”Рћ СЃС‚Р°СЂС‚Р°/РїРµСЂРµР·Р°РіСЂСѓР·РєРё nginx:
  # РµСЃР»Рё nginx РїРѕРґРЅРёРјРµС‚СЃСЏ СЂР°РЅСЊС€Рµ, С‡РµРј РІ nginx.conf РїРѕСЏРІРёС‚СЃСЏ
  # `include /etc/nginx/streams-enabled/*.conf`, РїРѕСЂС‚ 443 РЅРµ РѕС‚РєСЂРѕРµС‚СЃСЏ РІРѕРѕР±С‰Рµ
  # (РІ Р»РѕРіРµ Р±СѓРґРµС‚ В«Nginx Р·Р°РїСѓС‰РµРЅВ», Р° РїР°РЅРµР»СЊ Рё РІСЃРµ РґРѕРјРµРЅС‹ СЃРЅР°СЂСѓР¶Рё РЅРµРґРѕСЃС‚СѓРїРЅС‹).
  # РЎРЅР°С‡Р°Р»Р° вЂ” РјРѕРґСѓР»СЊ stream: РІ СЃР±РѕСЂРєР°С… Ubuntu РѕРЅ РґРёРЅР°РјРёС‡РµСЃРєРёР№, Рё Р±РµР·
  # load_module РґРёСЂРµРєС‚РёРІР° stream РґРµР»Р°РµС‚ РєРѕРЅС„РёРі РЅРµРІР°Р»РёРґРЅС‹Рј С†РµР»РёРєРѕРј.
  nginx_stream_module_enable >/dev/null 2>&1 || true
  ensure_stream_include >/dev/null 2>&1 || true
  # РџРµСЂРµРґ РєР°Р¶РґРѕР№ РїСЂРѕРІРµСЂРєРѕР№ nginx РїРѕРІС‚РѕСЂРЅРѕ РЅРѕСЂРјР°Р»РёР·СѓРµРј map: СЌС‚Рѕ С‚Р°РєР¶Рµ С‡РёРЅРёС‚
  # СЃС‚Р°СЂС‹Рµ РїРѕРІСЂРµР¶РґС‘РЅРЅС‹Рµ Р·Р°РїРёСЃРё, СЃРѕР·РґР°РЅРЅС‹Рµ РґРѕ РѕР±РЅРѕРІР»РµРЅРёСЏ СЃРєСЂРёРїС‚Р°.
  sni_conf_repair_map >/dev/null 2>&1 || true
  if ! nginx -t 2>/dev/null; then
    err "Nginx test failed"; nginx -t 2>&1 | tail -5 | sed 's/^/  /'
    return 1
  fi
  if systemctl is-active --quiet nginx 2>/dev/null; then
    systemctl reload nginx 2>/dev/null && { log "Nginx РїРµСЂРµР·Р°РіСЂСѓР¶РµРЅ"; return 0; }
  fi
  systemctl start nginx 2>/dev/null && { log "Nginx Р·Р°РїСѓС‰РµРЅ"; return 0; }
  return 1
}

# в”Ђв”Ђ РњРѕРґСѓР»СЊ stream (SNI-СЂРѕСѓС‚РµСЂ РЅР° 443) в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# Р’ СЃР±РѕСЂРєР°С… Ubuntu/Debian stream СЃРѕР±СЂР°РЅ РєР°Рє Р”РРќРђРњРР§Р•РЎРљРР™ РјРѕРґСѓР»СЊ
# (--with-stream=dynamic) Рё РґРѕСЃС‚СѓРїРµРЅ С‚РѕР»СЊРєРѕ РїРѕСЃР»Рµ load_module. РћС‚РєР°С‚/РґРµРјРѕРЅС‚Р°Р¶
# С‡Р°СЃС‚Рѕ СѓРЅРѕСЃРёС‚ /etc/nginx/modules-enabled вЂ” С‚РѕРіРґР° Р±Р»РѕРє stream{} РІ nginx.conf
# РґРµР»Р°РµС‚ РєРѕРЅС„РёРі РЅРµРІР°Р»РёРґРЅС‹Рј (В«unknown directive "stream"В»), nginx РЅРµ СЃС‚Р°СЂС‚СѓРµС‚
# РІРѕРѕР±С‰Рµ, Р° РїР°РЅРµР»СЊ Рё РІСЃРµ РґРѕРјРµРЅС‹ СЃС‚Р°РЅРѕРІСЏС‚СЃСЏ РЅРµРґРѕСЃС‚СѓРїРЅС‹.
NGX_STREAM_SO="/usr/lib/nginx/modules/ngx_stream_module.so"

# РЎР±РѕСЂРєР° nginx РІРѕРѕР±С‰Рµ СѓРјРµРµС‚ stream?
nginx_stream_resolvable() {
  nginx -V 2>&1 | tr ' ' '\n' | grep -q '^--with-stream'
}

# Р”РёСЂРµРєС‚РёРІР° stream СЂРµР°Р»СЊРЅРѕ РґРѕСЃС‚СѓРїРЅР° СЌС‚РѕРјСѓ Р±РёРЅР°СЂСЋ.
#   вЂў СЃС‚Р°С‚РёС‡РµСЃРєР°СЏ СЃР±РѕСЂРєР° (--with-stream Р±РµР· =dynamic) вЂ” РјРѕРґСѓР»СЊ РІРЅСѓС‚СЂРё Р±РёРЅР°СЂСЏ;
#   вЂў РґРёРЅР°РјРёС‡РµСЃРєР°СЏ (--with-stream=dynamic) вЂ” РЅСѓР¶РµРЅ load_module, С‚Рѕ РµСЃС‚СЊ С„Р°Р№Р»
#     РІ /etc/nginx/modules-enabled, СЃСЃС‹Р»Р°СЋС‰РёР№СЃСЏ РЅР° ngx_stream_module.so.
# Р’РђР–РќРћ: РїР°РєРµС‚РЅС‹Р№ 50-mod-stream.conf вЂ” РЎРРњР›РРќРљ, Р° `grep -r` РїРѕ СЃРёРјР»РёРЅРєР°Рј РЅРµ
# С…РѕРґРёС‚ (РЅСѓР¶РµРЅ -R) вЂ” РёР·-Р·Р° СЌС‚РѕРіРѕ РґРµС‚РµРєС‚РѕСЂ РѕС€РёР±РѕС‡РЅРѕ СЃС‡РёС‚Р°Р» РјРѕРґСѓР»СЊ РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РёРј.
nginx_stream_loaded() {
  nginx_stream_resolvable || return 1
  nginx -V 2>&1 | grep -q -- '--with-stream=' || return 0
  [[ -f "$NGX_STREAM_SO" ]] || return 1
  local f
  for f in /etc/nginx/modules-enabled/*; do
    [[ -f "$f" ]] || continue          # -f РІРµСЂРµРЅ Рё РґР»СЏ СЂР°Р±РѕС‡РµРіРѕ СЃРёРјР»РёРЅРєР°
    grep -qs 'load_module.*stream' "$f" 2>/dev/null && return 0
  done
  return 1
}

# РџРѕРґРєР»СЋС‡РёС‚СЊ РјРѕРґСѓР»СЊ stream. 0 вЂ” РґРѕСЃС‚СѓРїРµРЅ, 1 вЂ” РїРѕРґРєР»СЋС‡РёС‚СЊ РЅРµ СѓРґР°Р»РѕСЃСЊ.
nginx_stream_module_enable() {
  nginx_stream_loaded && return 0
  nginx_stream_resolvable || return 1
  if [[ ! -f "$NGX_STREAM_SO" ]]; then
    # РїРѕСЃР»Рµ РѕС‚РєР°С‚Р° РїР°РєРµС‚ С‡РёСЃР»РёС‚СЃСЏ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Рј, Р° С„Р°Р№Р»С‹ РјРѕРіСѓС‚ Р±С‹С‚СЊ СЃРЅРµСЃРµРЅС‹:
    # СЃРЅР°С‡Р°Р»Р° РѕР±РЅРѕРІР»СЏРµРј СЃРїРёСЃРєРё, РїРѕС‚РѕРј РїРµСЂРµСѓСЃС‚Р°РЅР°РІР»РёРІР°РµРј РїР°РєРµС‚ С†РµР»РёРєРѕРј
    DEBIAN_FRONTEND=noninteractive apt-get update -y >/dev/null 2>&1 || true
    DEBIAN_FRONTEND=noninteractive apt-get install -y --reinstall libnginx-mod-stream >/dev/null 2>&1 || true
  fi
  [[ -f "$NGX_STREAM_SO" ]] || return 1
  mkdir -p /etc/nginx/modules-enabled 2>/dev/null || true
  local _mf="/etc/nginx/modules-enabled/50-mod-stream.conf"
  # Р Р°Р±РѕС‡РёР№ С„Р°Р№Р» РїР°РєРµС‚Р° (СЃРёРјР»РёРЅРє) РЅРµ С‚СЂРѕРіР°РµРј; Р±РёС‚С‹Р№/РїСѓСЃС‚РѕР№/С‡СѓР¶РѕР№ вЂ” Р·Р°РјРµРЅСЏРµРј
  # РѕР±С‹С‡РЅС‹Рј С„Р°Р№Р»РѕРј СЃ Р°Р±СЃРѕР»СЋС‚РЅС‹Рј РїСѓС‚С‘Рј Рє РјРѕРґСѓР»СЋ.
  if [[ -f "$_mf" ]] && grep -qs 'load_module.*stream' "$_mf" 2>/dev/null; then
    :
  else
    rm -f "$_mf" 2>/dev/null || true
    printf 'load_module %s;\n' "$NGX_STREAM_SO" > "$_mf" 2>/dev/null || true
  fi
  # nginx.conf РѕР±СЏР·Р°РЅ РїРѕРґРєР»СЋС‡Р°С‚СЊ modules-enabled вЂ” РїРѕСЃР»Рµ РїСЂР°РІРѕРє/РѕС‚РєР°С‚Р° СЃС‚СЂРѕРєР°
  # РјРѕРіР»Р° РёСЃС‡РµР·РЅСѓС‚СЊ, Рё С‚РѕРіРґР° load_module РЅРµ СЃСЂР°Р±РѕС‚Р°РµС‚
  if ! grep -q 'modules-enabled' /etc/nginx/nginx.conf 2>/dev/null; then
    sed -i '1i include /etc/nginx/modules-enabled/*.conf;' /etc/nginx/nginx.conf 2>/dev/null || true
  fi
  nginx_stream_loaded
}

ensure_stream_include() {
  grep -q "streams-enabled" /etc/nginx/nginx.conf 2>/dev/null && return 0
  # РЎРЅР°С‡Р°Р»Р° РјРѕРґСѓР»СЊ: Р±РµР· РЅРµРіРѕ stream{} вЂ” С„Р°С‚Р°Р»СЊРЅР°СЏ РѕС€РёР±РєР° РєРѕРЅС„РёРіР°, nginx РЅРµ
  # РїРѕРґРЅРёРјРµС‚СЃСЏ РІРѕРѕР±С‰Рµ. Р•СЃР»Рё РјРѕРґСѓР»СЊ РЅРµРґРѕСЃС‚СѓРїРµРЅ вЂ” Р±Р»РѕРє РќР• РїРёС€РµРј (443/SNI РЅРµ
  # РїРѕРґРЅСЏС‚СЊ, РЅРѕ РѕСЃС‚Р°Р»СЊРЅРѕР№ СЃС‚РµРє РѕСЃС‚Р°С‘С‚СЃСЏ СЂР°Р±РѕС‡РёРј).
  if ! nginx_stream_module_enable; then
    warn "nginx Р±РµР· РјРѕРґСѓР»СЏ stream (libnginx-mod-stream): SNI-СЂРѕСѓС‚РµСЂ (443) РЅРµ РїРѕРґРєР»СЋС‡РёС‚СЊ, stream-Р±Р»РѕРє РІ nginx.conf РЅРµ РґРѕР±Р°РІР»СЏСЋ вЂ” РёРЅР°С‡Рµ nginx РЅРµ СЃС‚Р°СЂС‚СѓРµС‚"
    return 1
  fi
  local _bak=""
  if [[ -f /etc/nginx/nginx.conf ]]; then
    _bak=$(mktemp /tmp/nginx.conf.bak.XXXXXX 2>/dev/null || true)
    [[ -n "$_bak" ]] && { cp -f /etc/nginx/nginx.conf "$_bak" 2>/dev/null || true; }
  fi
  if ! grep -qE '^\s*stream\s*\{' /etc/nginx/nginx.conf 2>/dev/null; then
    sed -i '/^\s*http\s*{/i stream {\n    include /etc/nginx/streams-enabled/*.conf;\n}\n' /etc/nginx/nginx.conf
  else
    sed -i '/^\s*stream\s*{/a \    include /etc/nginx/streams-enabled/*.conf;' /etc/nginx/nginx.conf
  fi
  # РљРѕРЅС‚СЂРѕР»СЊ: Р±РёС‚С‹Р№ РєРѕРЅС„РёРі РѕС‚РєР°С‚С‹РІР°РµРј, С‡С‚РѕР±С‹ nginx РѕСЃС‚Р°Р»СЃСЏ СЂР°Р±РѕС‡РёРј
  if ! nginx -t >/dev/null 2>&1; then
    if [[ -n "$_bak" && -f "$_bak" ]]; then
      cp -f "$_bak" /etc/nginx/nginx.conf 2>/dev/null || true
      warn "РїСЂР°РІРєР° nginx.conf (stream-Р±Р»РѕРє) РЅРµ РїСЂРѕС€Р»Р° nginx -t вЂ” РєРѕРЅС„РёРі РІРѕР·РІСЂР°С‰С‘РЅ РєР°Рє Р±С‹Р»"
    fi
    rm -f "$_bak" 2>/dev/null || true
    return 1
  fi
  rm -f "$_bak" 2>/dev/null || true
  return 0
}

# Р¤Р°РєС‚РёС‡РµСЃРєР°СЏ РїСЂРѕРІРµСЂРєР° 443/SNI: Р±РµР· РЅРµРіРѕ РїР°РЅРµР»СЊ Рё РІСЃРµ РґРѕРјРµРЅС‹ РЅРµРґРѕСЃС‚СѓРїРЅС‹ СЃРЅР°СЂСѓР¶Рё,
# РїРѕСЌС‚РѕРјСѓ В«Рї.1 Р·Р°РІРµСЂС€С‘РЅВ» РїСЂРё РјС‘СЂС‚РІРѕРј 443 вЂ” Р»РѕР¶СЊ. РџРµС‡Р°С‚Р°РµС‚ РїСЂРёС‡РёРЅСѓ Рё Р»РµС‡РµРЅРёРµ.
nginx_443_check() {   # [quiet]
  local q="${1:-0}" _i=0
  # РїРѕСЃР»Рµ reload РІРѕСЂРєРµСЂ Р±РёРЅРґРёС‚ 443 РЅРµ РјРіРЅРѕРІРµРЅРЅРѕ вЂ” РґР°С‘Рј РЅРµСЃРєРѕР»СЊРєРѕ СЃРµРєСѓРЅРґ
  while (( _i < 5 )); do
    if ss -tlnH 'sport = :443' 2>/dev/null | grep -q .; then
      (( q )) || log "443/SNI СЃР»СѓС€Р°РµС‚СЃСЏ вЂ” РїР°РЅРµР»СЊ Рё РґРѕРјРµРЅС‹ РґРѕСЃС‚СѓРїРЅС‹ СЃРЅР°СЂСѓР¶Рё"
      return 0
    fi
    sleep 1; _i=$((_i+1))
  done
  err "443/SNI РќР• СЃР»СѓС€Р°РµС‚СЃСЏ вЂ” РїР°РЅРµР»СЊ Рё РІСЃРµ РґРѕРјРµРЅС‹ РЅРµРґРѕСЃС‚СѓРїРЅС‹ СЃРЅР°СЂСѓР¶Рё!"
  if ! nginx_stream_resolvable; then
    err "  РїСЂРёС‡РёРЅР°: nginx СЃРѕР±СЂР°РЅ Р±РµР· РјРѕРґСѓР»СЏ stream вЂ” СѓСЃС‚Р°РЅРѕРІРё РїР°РєРµС‚ nginx СЃ РјРѕРґСѓР»РµРј stream"
  elif ! nginx_stream_loaded; then
    err "  РїСЂРёС‡РёРЅР°: РјРѕРґСѓР»СЊ stream РЅРµ РїРѕРґРєР»СЋС‡С‘РЅ. Р›РµС‡РµРЅРёРµ: apt-get update && apt-get install -y --reinstall libnginx-mod-stream, Р·Р°С‚РµРј РїРѕРІС‚РѕСЂРё Рї.1"
  elif ! grep -q 'streams-enabled' /etc/nginx/nginx.conf 2>/dev/null; then
    err "  РїСЂРёС‡РёРЅР°: РІ nginx.conf РЅРµС‚ РІРєР»СЋС‡РµРЅРёСЏ SNI-РєР°СЂС‚С‹ (streams-enabled) вЂ” РїРѕРІС‚РѕСЂРё Рї.1"
  elif ! nginx -t >/dev/null 2>&1; then
    err "  РїСЂРёС‡РёРЅР°: РєРѕРЅС„РёРі nginx РЅРµ РїСЂРѕС…РѕРґРёС‚ РїСЂРѕРІРµСЂРєСѓ вЂ” СЃРјРѕС‚СЂРё РІС‹РІРѕРґ nginx -t РІС‹С€Рµ"
  else
    err "  РїСЂРёС‡РёРЅР°: nginx РЅРµ Р·Р°РїСѓС‰РµРЅ РёР»Рё РЅРµ РїРµСЂРµС‡РёС‚Р°Р» РєРѕРЅС„РёРі вЂ” РїСЂРѕРІРµСЂСЊ systemctl status nginx"
  fi
  return 1
}

# =====================================================================
# Р¤РђР•Р Р’РћР›
# =====================================================================
save_firewall_state() {
  mkdir -p "$FW_STATE_DIR" 2>/dev/null || true
  if [[ -f "$FW_STATE_DIR/saved" ]]; then
    local _sdt
    _sdt=$(date -r "$FW_STATE_DIR/saved" '+%d.%m.%Y %H:%M' 2>/dev/null || true)
    warn "РЎРЅРёРјРѕРє СѓР¶Рµ РµСЃС‚СЊ (${_sdt:-РґР°С‚Р° РЅРµРёР·РІРµСЃС‚РЅР°}) вЂ” С…СЂР°РЅРёС‚ РёСЃС…РѕРґРЅРѕРµ СЃРѕСЃС‚РѕСЏРЅРёРµ В«РґРѕ СЃС‚РµРєР°В» Рё РЅРµ РїРµСЂРµР·Р°РїРёСЃС‹РІР°РµС‚СЃСЏ"
    return 0
  fi
  {
    if command -v ufw >/dev/null 2>&1; then
      echo 'UFW_WAS_INSTALLED=1'
      ufw status 2>/dev/null | grep -q '^Status: active' && echo 'UFW_WAS_ACTIVE=1' || echo 'UFW_WAS_ACTIVE=0'
    else
      echo 'UFW_WAS_INSTALLED=0'; echo 'UFW_WAS_ACTIVE=0'
    fi
  } > "$FW_STATE_DIR/state"
  tar -cpf "$FW_STATE_DIR/ufw-config.tar" /etc/ufw /etc/default/ufw 2>/dev/null || true
  iptables-save  > "$FW_STATE_DIR/iptables.v4" 2>/dev/null || true
  ip6tables-save > "$FW_STATE_DIR/iptables.v6" 2>/dev/null || true
  touch "$FW_STATE_DIR/saved"
  log "РЎРЅРёРјРѕРє: $FW_STATE_DIR"
}

restore_firewall_state() {
  line; echo -e "${B}   Р’РћРЎРЎРўРђРќРћР’Р›Р•РќРР• Р¤РђР•Р Р’РћР›Рђ${N}"; line
  [[ ! -f "$FW_STATE_DIR/saved" ]] && { warn "РЎРЅРёРјРѕРє РЅРµ РЅР°Р№РґРµРЅ"; pause; return 1; }
  askyn confirm "Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ?" "n"
  [[ "$confirm" == true ]] || return 0
  audit "firewall: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ СЃРѕСЃС‚РѕСЏРЅРёСЏ РёР· СЃРЅРёРјРєР°"
  # shellcheck disable=SC1090
  . "$FW_STATE_DIR/state" 2>/dev/null || true
  [[ -f "$FW_STATE_DIR/iptables.v4" ]] && iptables-restore  < "$FW_STATE_DIR/iptables.v4"  2>/dev/null || true
  [[ -f "$FW_STATE_DIR/iptables.v6" ]] && ip6tables-restore < "$FW_STATE_DIR/iptables.v6"  2>/dev/null || true
  if [[ "${UFW_WAS_INSTALLED:-0}" == "1" && -f "$FW_STATE_DIR/ufw-config.tar" ]]; then
    tar -xpf "$FW_STATE_DIR/ufw-config.tar" -C / 2>/dev/null || true
    if [[ "${UFW_WAS_ACTIVE:-0}" == "1" ]]; then
      ufw --force enable >/dev/null 2>&1 || true
    else
      ufw --force disable >/dev/null 2>&1 || true
    fi
  fi
  rm -f "$FW_STATE_DIR/saved"
  log "Р’РѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРѕ"; pause
}

# =====================================================================
# DECOY Р’Р«Р‘РћР 
# =====================================================================
# Р•Р”РРќР«Р™ РІС‹Р±СЂР°РЅРЅС‹Р№ С€Р°Р±Р»РѕРЅ decoy вЂ” SELECTED_DECOY_TPL.
# Р’С‹Р±РѕСЂ РґРµР»Р°РµС‚СЃСЏ РѕРґРёРЅ СЂР°Р· РІ Р°РЅРєРµС‚Рµ Рї.1 (Р·Р°РіР»СѓС€РєР° РїР°РЅРµР»Рё) Рё/РёР»Рё РІ РІРѕРїСЂРѕСЃР°С…
# CDN/Reality, Р° РїСЂРёРјРµРЅСЏРµС‚СЃСЏ РєРѕ Р’РЎР•Рњ РґРѕРјРµРЅР°Рј СЃС‚РµРєР°. Р Р°РЅСЊС€Рµ РґРѕРјРµРЅС‹, РґР»СЏ РєРѕС‚РѕСЂС‹С…
# С€Р°Р±Р»РѕРЅ РЅРµ СЃРїСЂР°С€РёРІР°Р»Рё (РёРЅР±Р°СѓРЅРґС‹, СѓР¶Рµ РїСЂРёРІСЏР·Р°РЅРЅС‹Рµ Рє SNI), РјРѕР»С‡Р° РїРѕР»СѓС‡Р°Р»Рё
# СЃС‚Р°РЅРґР°СЂС‚РЅСѓСЋ СЃС‚СЂР°РЅРёС†Сѓ nginx В«Welcome to nginx!В» вЂ” РІС‹Р±РѕСЂ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ
# РёРіРЅРѕСЂРёСЂРѕРІР°Р»СЃСЏ.
# Р—РЅР°С‡РµРЅРёРµ РїРµСЂРµР¶РёРІР°РµС‚ РїРµСЂРµР·Р°РїСѓСЃРє СЃРєСЂРёРїС‚Р° (С„Р°Р№Р» СЃРѕСЃС‚РѕСЏРЅРёСЏ), РЅРѕ РїСЂРёРјРµРЅСЏРµС‚СЃСЏ
# РўРћР›Р¬РљРћ С‚Р°Рј, РіРґРµ СЂР°РЅСЊС€Рµ СЃС‚РѕСЏР» Р¶С‘СЃС‚РєРёР№ "default": СЏРІРЅС‹Р№ РІС‹Р±РѕСЂ РІ РјРµРЅСЋ РіР»Р°РІРЅРµРµ.
# РџСѓСЃС‚Рѕ/РЅРµРІР°Р»РёРґРЅРѕ в†’ "default" (РїСЂРµР¶РЅРµРµ РїРѕРІРµРґРµРЅРёРµ, РїРѕР»РЅР°СЏ СЃРѕРІРјРµСЃС‚РёРјРѕСЃС‚СЊ).
DECOY_TPL_STATE="/root/stack-backups/selected-decoy-tpl"
SELECTED_DECOY_TPL="${SELECTED_DECOY_TPL:-}"

# РЁР°Р±Р»РѕРЅ СЂРµР°Р»СЊРЅРѕ РїСЂРёРјРµРЅРёРј? (С„Р°Р№Р» С€Р°Р±Р»РѕРЅР° СЃСѓС‰РµСЃС‚РІСѓРµС‚ / РїР°РїРєР° СЃРІРѕРµРіРѕ СЃР°Р№С‚Р° РµСЃС‚СЊ)
decoy_tpl_valid() {   # <С€Р°Р±Р»РѕРЅ>
  local t="${1:-}"
  [[ -z "$t" ]] && return 1
  if [[ "$t" == custom:* ]]; then
    [[ -d "${t#custom:}" ]] && return 0
    return 1
  fi
  [[ "$t" == "redirect" || "$t" == "locked" ]] && return 0
  [[ -f "$DECOY_TPL_DIR/$t.html" || -f "$DECOY_LOGIN_DIR/$t.html" ]] && return 0
  return 1
}

# Р—Р°РїРѕРјРЅРёС‚СЊ РІС‹Р±РѕСЂ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ РєР°Рє РѕР±С‰РёР№ С€Р°Р±Р»РѕРЅ РґР»СЏ РІСЃРµС… РґРѕРјРµРЅРѕРІ.
# Р—РЅР°С‡РµРЅРёСЏ-Р·Р°РіР»СѓС€РєРё (stub/adguard/default) РѕР±С‰РёР№ С€Р°Р±Р»РѕРЅ РЅРµ РјРµРЅСЏСЋС‚.
decoy_selected_set() {   # <С€Р°Р±Р»РѕРЅ|Р·РЅР°С‡РµРЅРёРµ PDECOY>
  local t="${1:-}"
  case "$t" in
    ""|stub|adguard|adguard-sni|default) return 0 ;;
    tpl:*) t="${t#tpl:}" ;;
  esac
  [[ "$t" == "default" ]] && return 0
  SELECTED_DECOY_TPL="$t"
  mkdir -p "$(dirname "$DECOY_TPL_STATE")" 2>/dev/null || true
  printf '%s\n' "$t" > "$DECOY_TPL_STATE" 2>/dev/null || true
  return 0
}

# РЁР°Р±Р»РѕРЅ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РґР»СЏ РґРѕРјРµРЅР°: РІС‹Р±СЂР°РЅРЅС‹Р№ РїРѕР»СЊР·РѕРІР°С‚РµР»РµРј, РёРЅР°С‡Рµ "default".
decoy_default_tpl() {
  if [[ -z "${SELECTED_DECOY_TPL:-}" && -s "$DECOY_TPL_STATE" ]]; then
    SELECTED_DECOY_TPL=$(head -n 1 "$DECOY_TPL_STATE" 2>/dev/null | tr -d '[:space:]') || true
  fi
  if decoy_tpl_valid "${SELECTED_DECOY_TPL:-}"; then
    printf '%s' "$SELECTED_DECOY_TPL"
  else
    printf 'default'
  fi
}

# в”Ђв”Ђ РЁР°Р±Р»РѕРЅС‹ decoy РџРћ Р”РћРњР•РќРђРњ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# РљР°Р¶РґРѕРјСѓ РґРѕРјРµРЅСѓ РјРѕР¶РЅРѕ Р·Р°РґР°С‚СЊ РЎР’РћР™ С€Р°Р±Р»РѕРЅ (РєР°С‚Р°Р»РѕР¶РЅС‹Р№ РёР»Рё СЃРІРѕР№ СЃР°Р№С‚
# custom:/РїСѓС‚СЊ) РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ РѕСЃС‚Р°Р»СЊРЅС‹С…: РґРѕРјРµРЅС‹ РјРѕРіСѓС‚ Р±С‹С‚СЊ РЅР°СЃС‚СЂРѕРµРЅС‹ РѕРґРёРЅР°РєРѕРІРѕ,
# РїРѕ-СЂР°Р·РЅРѕРјСѓ РёР»Рё РЅР° СЃРІРѕРё СЃР°Р№С‚С‹. РҐСЂР°РЅРёС‚СЃСЏ РІ С„Р°Р№Р»Рµ В«РґРѕРјРµРЅ<TAB>С€Р°Р±Р»РѕРЅВ».
# РџСЂРёРѕСЂРёС‚РµС‚: СЃРІРѕР№ С€Р°Р±Р»РѕРЅ РґРѕРјРµРЅР° в†’ tpl CDN-РїСЂРѕС„РёР»СЏ (РґР»СЏ origin) в†’ РѕР±С‰РёР№
# (SELECTED_DECOY_TPL) в†’ "default".
DECOY_TPL_MAP="/root/stack-backups/decoy-templates.tsv"

decoy_tpl_store_get() {   # <domain> в†’ С€Р°Р±Р»РѕРЅ (РїСѓСЃС‚Рѕ, РµСЃР»Рё РґРѕРјРµРЅСѓ РЅРµ Р·Р°РґР°РЅ)
  local d="${1:-}"
  [[ -n "$d" && -s "$DECOY_TPL_MAP" ]] || return 1
  awk -F'\t' -v d="$d" '$1==d {print $2; exit}' "$DECOY_TPL_MAP" 2>/dev/null
}

decoy_tpl_store_set() {   # <domain> <С€Р°Р±Р»РѕРЅ>
  local d="${1:-}" t="${2:-}"
  [[ -n "$d" && -n "$t" ]] || return 1
  mkdir -p "$(dirname "$DECOY_TPL_MAP")" 2>/dev/null || true
  local tmp; tmp=$(mktemp 2>/dev/null) || return 1
  [[ -s "$DECOY_TPL_MAP" ]] && awk -F'\t' -v d="$d" '$1!=d' "$DECOY_TPL_MAP" > "$tmp" 2>/dev/null || true
  printf '%s\t%s\n' "$d" "$t" >> "$tmp"
  mv -f "$tmp" "$DECOY_TPL_MAP" 2>/dev/null || { rm -f "$tmp"; return 1; }
  chmod 600 "$DECOY_TPL_MAP" 2>/dev/null || true
  return 0
}

# РЁР°Р±Р»РѕРЅ РёР· РґРµР№СЃС‚РІСѓСЋС‰РµРіРѕ decoy-Р±Р»РѕРєР° РґРѕРјРµРЅР° (РјР°СЂРєРµСЂ: tpl=вЂ¦ root=вЂ¦)
decoy_tpl_from_block() {   # <domain> в†’ С€Р°Р±Р»РѕРЅ (custom:/РїСѓС‚СЊ РґР»СЏ СЃРІРѕРµРіРѕ СЃР°Р№С‚Р°)
  local dom="${1:-}" line="" t="" r=""
  [[ -n "$dom" && -f "$STACK_CONF" ]] || return 1
  line=$(grep -m1 -E "# >>> decoy .*domain=${dom//./\\.}([[:space:]]|\$)" "$STACK_CONF" 2>/dev/null || true)
  [[ -n "$line" ]] || return 1
  t=$(grep -oE 'tpl=[^ ]+' <<<"$line" | head -1 | cut -d= -f2-)
  [[ -n "$t" ]] || return 1
  if [[ "$t" == "custom" ]]; then
    r=$(grep -oE 'root=[^ ]+' <<<"$line" | head -1 | cut -d= -f2-)
    [[ -n "$r" ]] && t="custom:$r"
  fi
  printf '%s' "$t"
}

# tpl CDN-ORIGIN РёР· CDN-РїСЂРѕС„РёР»СЏ (РїРѕР»Рµ 6): РґР»СЏ origin РѕРЅ РіР»Р°РІРЅРµРµ РѕР±С‰РµРіРѕ
cdn_profile_origin_tpl() {   # <domain>
  local d="${1:-}" row f3 f6
  [[ -n "$d" && -s "$CDN_PROFILES" ]] || return 1
  while IFS= read -r row; do
    [[ -n "$row" ]] || continue
    f3=$(printf '%s' "$row" | cut -d'|' -f3)
    [[ "$f3" == "$d" ]] || continue
    f6=$(printf '%s' "$row" | cut -d'|' -f6)
    [[ -n "$f6" ]] && { printf '%s' "$f6"; return 0; }
  done < "$CDN_PROFILES"
  return 1
}

# РС‚РѕРіРѕРІС‹Р№ С€Р°Р±Р»РѕРЅ РґР»СЏ РґРѕРјРµРЅР° (РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РІСЃРµРјРё РјРµСЃС‚Р°РјРё СЃРѕР·РґР°РЅРёСЏ decoy).
# РџСЂРёРѕСЂРёС‚РµС‚: СЃРѕС…СЂР°РЅС‘РЅРЅС‹Р№ РІС‹Р±РѕСЂ РґРѕРјРµРЅР° в†’ tpl CDN-РїСЂРѕС„РёР»СЏ (РґР»СЏ origin) в†’ С€Р°Р±Р»РѕРЅ
# РґРµР№СЃС‚РІСѓСЋС‰РµРіРѕ decoy-Р±Р»РѕРєР° (С‡С‚РѕР±С‹ СЃР°РјРѕР»РµС‡РµРЅРёРµ РЅРµ Р·Р°С‚РёСЂР°Р»Рѕ СѓР¶Рµ РЅР°СЃС‚СЂРѕРµРЅРЅС‹Р№ РґРѕРјРµРЅ
# РѕР±С‰РёРј С€Р°Р±Р»РѕРЅРѕРј) в†’ РѕР±С‰РёР№ в†’ default.
decoy_tpl_for() {   # <domain>
  local d="${1:-}" t=""
  t=$(decoy_tpl_store_get "$d" 2>/dev/null || true)
  [[ -n "$t" ]] && decoy_tpl_valid "$t" && { printf '%s' "$t"; return 0; }
  t=$(cdn_profile_origin_tpl "$d" 2>/dev/null || true)
  [[ -n "$t" ]] && decoy_tpl_valid "$t" && { printf '%s' "$t"; return 0; }
  t=$(decoy_tpl_from_block "$d" 2>/dev/null || true)
  [[ -n "$t" ]] && decoy_tpl_valid "$t" && { printf '%s' "$t"; return 0; }
  decoy_default_tpl
}

# Р§С‚Рѕ СЂРµР°Р»СЊРЅРѕ СЃС‚РѕРёС‚ РЅР° РґРѕРјРµРЅРµ СЃРµР№С‡Р°СЃ (РїРѕРґСЃРєР°Р·РєР° РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РІ РІРѕРїСЂРѕСЃР°С…)
decoy_tpl_current() {   # <domain>
  local d="${1:-}" t=""
  t=$(decoy_tpl_store_get "$d" 2>/dev/null || true)
  [[ -n "$t" ]] && decoy_tpl_valid "$t" && { printf '%s' "$t"; return 0; }
  t=$(decoy_tpl_from_block "$d" 2>/dev/null || true)
  [[ -n "$t" ]] && decoy_tpl_valid "$t" && { printf '%s' "$t"; return 0; }
  decoy_tpl_for "$d"
}

decoy_template_choose_impl() {
  local __result="$1" prompt="${2:-Р’С‹Р±РµСЂРёС‚Рµ decoy-С€Р°Р±Р»РѕРЅ}" default="${3:-default}"
  echo >&2; echo -e "${B}Р”РѕСЃС‚СѓРїРЅС‹Рµ decoy-С€Р°Р±Р»РѕРЅС‹ вЂ” СЃС‚СЂР°РЅРёС†Р°-Р—РђР“Р›РЈРЁРљРђ:${N}" >&2
  echo -e "   (РµС‘ СѓРІРёРґРёС‚ РїРѕСЃС‚РѕСЂРѕРЅРЅРёР№, РѕС‚РєСЂС‹РІ РґРѕРјРµРЅ РІ Р±СЂР°СѓР·РµСЂРµ; РЅР° СЂР°Р±РѕС‚Сѓ РїСЂРѕС‚РѕРєРѕР»Р° РЅРµ РІР»РёСЏРµС‚)" >&2
  local i=1
  local -a NAMES=()
  local __t
  for __t in "${DECOY_TEMPLATES[@]}"; do
    local __n="${__t%%|*}" __dsc="${__t##*|}"
    printf "  %2d) %-15s %s\n" "$i" "$__n" "$__dsc" >&2
    NAMES+=("$__n"); i=$((i+1))
  done
  local __custom_num=$i
  printf "  %2d) %-15s %s\n" "$__custom_num" "custom" "в–¶ РЎРІРѕР№ СЃР°Р№С‚ вЂ” РїР°РїРєР° СЃРѕ СЃС‚Р°С‚РёРєРѕР№ (index.html Рё С‚.Рґ.)" >&2
  echo >&2
  local __c=""
  while :; do
    if ! ask __c "$prompt" "$default" '^[0-9]+$|^[a-z:_/.-]+$'; then
      # EOF (Р°РЅСЃ-С„Р°Р№Р» РєРѕРЅС‡РёР»СЃСЏ): РІРѕР·РІСЂР°С‰Р°РµРј РґРµС„РѕР»С‚, РЅРѕ РµСЃР»Рё СЌС‚Рѕ РЅРµ РІР°Р»РёРґРЅРѕРµ
      # РёРјСЏ С€Р°Р±Р»РѕРЅР° Рё РЅРµ custom:* вЂ” РіР»РѕР±Р°Р»СЊРЅС‹Р№ РґРµС„РѕР»С‚РЅС‹Р№ С€Р°Р±Р»РѕРЅ, РёРЅР°С‡Рµ РЅРёР¶Рµ
      # РїРѕ РїРѕС‚РѕРєСѓ decoy РїСЂРёРјРµРЅРёС‚ РЅРµСЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ С€Р°Р±Р»РѕРЅ.
      local __eof_default="$default"
      if [[ "$__eof_default" != custom:* ]] && ! decoy_tpl_valid "$__eof_default"; then
        __eof_default="$(decoy_default_tpl)"
        warn "Р”РµС„РѕР»С‚ В«$defaultВ» РЅРµ РІР°Р»РёРґРµРЅ вЂ” РёСЃРїРѕР»СЊР·СѓСЋ С€Р°Р±Р»РѕРЅ В«$__eof_defaultВ»" >&2
      fi
      printf -v "$__result" '%s' "$__eof_default"
      return 0
    fi
    if [[ "$__c" =~ ^[0-9]+$ ]] && (( __c < 1 || __c > __custom_num )); then
      err "Р’С‹Р±РѕСЂ РІРЅРµ СЃРїРёСЃРєР°. РЈРєР°Р¶РёС‚Рµ РЅРѕРјРµСЂ РѕС‚ 1 РґРѕ $__custom_num."
      continue
    fi
    # РРјСЏ С€Р°Р±Р»РѕРЅР° (decoy_tpl_current/РґРµС„РѕР»С‚ РїСЂРё EOF вЂ” РІСЃРµРіРґР° РРњРЇ, РЅРµ РЅРѕРјРµСЂ):
    # РІР°Р»РёРґРЅРѕРµ РёРјСЏ РёР· СЃРїРёСЃРєР° РїСЂРёРЅРёРјР°РµРј СЃСЂР°Р·Сѓ, РёРЅР°С‡Рµ ask() РЅР° EOF РІРµСЂРЅС‘С‚ РґРµС„РѕР»С‚-
    # РёРјСЏ, РїСЂРѕРІРµСЂРєР° РЅРёР¶Рµ РµРіРѕ РѕС‚РІРµСЂРіРЅРµС‚ Рё С†РёРєР» В«EOF в†’ РёРјСЏ в†’ РІРЅРµ СЃРїРёСЃРєР°В» СЃС‚Р°РЅРµС‚
    # Р±РµСЃРєРѕРЅРµС‡РЅС‹Рј. Р—Р°РѕРґРЅРѕ С‡РёРЅРёС‚СЃСЏ Enter РЅР° РёРјРµРЅРё-РїРѕ-СѓРјРѕР»С‡Р°РЅРёСЋ РІ РёРЅС‚РµСЂР°РєС‚РёРІРµ.
    local __found=""
    local __k
    for __k in "${!NAMES[@]}"; do
      [[ "${NAMES[$__k]}" == "$__c" ]] && { __found=1; break; }
    done
    if [[ -n "$__found" ]]; then
      log "Р’С‹Р±СЂР°РЅ decoy-С€Р°Р±Р»РѕРЅ: $__c" >&2
      printf -v "$__result" '%s' "$__c"
      return 0
    fi
    if [[ "$__c" =~ ^[a-z:_/.-]+$ ]] && [[ "$__c" != custom && "$__c" != custom:* ]]; then
      err "Р’С‹Р±РѕСЂ РІРЅРµ СЃРїРёСЃРєР°. РЈРєР°Р¶РёС‚Рµ РЅРѕРјРµСЂ С€Р°Р±Р»РѕРЅР°, РµРіРѕ РёРјСЏ РёР»Рё custom."
      continue
    fi
    break
  done
  if [[ "$__c" == "custom" || "$__c" == "$__custom_num" || "$__c" == custom:* ]]; then
    local __path=""
    [[ "$__c" == custom:* ]] && __path="${__c#custom:}"
    if [[ -z "$__path" ]]; then
      # РќРµ-TTY: РїР°РїРєСѓ РІС‹Р±СЂР°С‚СЊ РЅРµС‡РµРј вЂ” EOF РІРµСЂРЅС‘С‚ РґРµС„РѕР»С‚ В«/var/www/mysiteВ»,
      # РєРѕС‚РѕСЂРѕРіРѕ РЅРµС‚ в†’ В«РџР°РїРєР° РЅРµ СЃСѓС‰РµСЃС‚РІСѓРµС‚ в†’ continueВ» РЅР°РІСЃРµРіРґР°.
      # Р’РѕР·РІСЂР°С‰Р°РµРј Р±РµР·РѕРїР°СЃРЅС‹Р№ С€Р°Р±Р»РѕРЅ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ.
      if [[ ! -t 0 ]]; then
        warn "РќРµ-TTY: custom-РїСѓС‚СЊ РЅРµРґРѕСЃС‚СѓРїРµРЅ вЂ” РёСЃРїРѕР»СЊР·СѓСЋ С€Р°Р±Р»РѕРЅ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ" >&2
        printf -v "$__result" '%s' "$(decoy_default_tpl)"
        return 0
      fi
      local __path_tries=0
      while :; do
        # 3 РЅРµСѓРґР°С‡Рё РїРѕРґСЂСЏРґ (Ctrl+D РІРѕР·РІСЂР°С‰Р°РµС‚ С‚РѕС‚ Р¶Рµ РґРµС„РѕР»С‚-РїСѓС‚СЊ) вЂ” РЅРµ РїРµС‚Р»РёРј.
        __path_tries=$((__path_tries+1))
        [[ "$__path_tries" -ge 3 ]] && {
          warn "РџСѓС‚СЊ РЅРµ РІС‹Р±СЂР°РЅ вЂ” РёСЃРїРѕР»СЊР·СѓСЋ С€Р°Р±Р»РѕРЅ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ" >&2
          printf -v "$__result" '%s' "$(decoy_default_tpl)"
          return 0
        }
        __path=""
        ask __path "РџСѓС‚СЊ Рє РїР°РїРєРµ СЃР°Р№С‚Р° (index.html РѕР±СЏР·Р°С‚РµР»РµРЅ)" "/var/www/mysite" '^/.+'
        [[ -d "$__path" ]] || { err "РџР°РїРєР° $__path РЅРµ СЃСѓС‰РµСЃС‚РІСѓРµС‚"; continue; }
        if [[ ! -f "$__path/index.html" ]]; then
          warn "Р’ $__path РЅРµС‚ index.html вЂ” nginx РѕС‚РґР°СЃС‚ 404"
          local __go=""
          askyn __go "РџСЂРѕРґРѕР»Р¶РёС‚СЊ РІСЃС‘ СЂР°РІРЅРѕ?" "n"
          [[ "$__go" == true ]] || continue
        fi
        break
      done
    fi
    if command -v sudo >/dev/null 2>&1 && ! sudo -u www-data test -r "$__path/index.html" 2>/dev/null; then
      warn "www-data РЅРµ РјРѕР¶РµС‚ С‡РёС‚Р°С‚СЊ $__path/index.html вЂ” nginx РѕС‚РґР°СЃС‚ 403"
      local __fix=""
      askyn __fix "РСЃРїСЂР°РІРёС‚СЊ РїСЂР°РІР° (chmod -R o+rX)?" "y"
      if [[ "$__fix" == true ]]; then
        chmod -R o+rX "$__path" 2>/dev/null || true
        log "РџСЂР°РІР° РёСЃРїСЂР°РІР»РµРЅС‹: $__path"
      fi
    fi
    printf -v "$__result" '%s' "custom:$__path"
    return 0
  fi
  if [[ "$__c" =~ ^[0-9]+$ ]]; then
    if (( __c >= 1 && __c <= ${#NAMES[@]} )); then
      log "Р’С‹Р±СЂР°РЅ decoy-С€Р°Р±Р»РѕРЅ: ${NAMES[$((__c-1))]}" >&2
      printf -v "$__result" '%s' "${NAMES[$((__c-1))]}"
    else
      log "Р’С‹Р±РѕСЂ decoy РІРЅРµ СЃРїРёСЃРєР° вЂ” РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ: $default" >&2
      printf -v "$__result" '%s' "$default"
    fi
  else
    log "Р’С‹Р±СЂР°РЅ decoy-С€Р°Р±Р»РѕРЅ: $__c" >&2
    printf -v "$__result" '%s' "$__c"
  fi
}

# РћР±С‘СЂС‚РєР°: Р»СЋР±РѕР№ СЏРІРЅС‹Р№ РІС‹Р±РѕСЂ С€Р°Р±Р»РѕРЅР° Р·Р°РїРѕРјРёРЅР°РµРј РєР°Рє РѕР±С‰РёР№ (SELECTED_DECOY_TPL),
# С‡С‚РѕР±С‹ РѕРЅ РїСЂРёРјРµРЅСЏР»СЃСЏ Рё Рє РґРѕРјРµРЅР°Рј, РґР»СЏ РєРѕС‚РѕСЂС‹С… РІРѕРїСЂРѕСЃ Р±РѕР»СЊС€Рµ РЅРµ Р·Р°РґР°С‘С‚СЃСЏ.
decoy_template_choose() {
  local __var="$1"
  decoy_template_choose_impl "$@"
  decoy_selected_set "${!__var:-}"
}

# =====================================================================
# Р•Р”РРќР«Р™ HTTP-РљРћРќР¤РР“ (sites-available/stack.conf)
#   ACME :80 + РїР°РЅРµР»СЊ :4443 + РІСЃРµ decoy-Р±Р»РѕРєРё вЂ” РІ РѕРґРЅРѕРј С„Р°Р№Р»Рµ.
#   Stream-С‡Р°СЃС‚СЊ (SNI-СЂРѕСѓС‚РµСЂ) РѕР±СЏР·Р°РЅР° Р¶РёС‚СЊ РІ streams-enabled/sni-router.conf:
#   РІ sites-available РјРѕР¶РЅРѕ РєР»Р°СЃС‚СЊ С‚РѕР»СЊРєРѕ http-РєРѕРЅС‚РµРєСЃС‚.
# =====================================================================
stack_ensure() {
  mkdir -p "$NGINX_SITES_AVAIL" "$NGINX_SITES_DIR" 2>/dev/null || true
  [[ -f "$STACK_CONF" ]] || printf '# stack-manager: РµРґРёРЅС‹Р№ РєРѕРЅС„РёРі (ACME :80, РїР°РЅРµР»СЊ :4443, decoy)\n' > "$STACK_CONF"
  # С„РѕСЂРјР°С‚ Р»РѕРіР° РґРµРєРѕС‘РІ: СЃ РґРѕРјРµРЅРѕРј (host=) вЂ” РЅСѓР¶РµРЅ РґР»СЏ СЃС‚Р°С‚РёСЃС‚РёРєРё Рё Р±Р°РЅР° СЃРјРѕС‚СЂРµРІС€РёС…
  if ! grep -q "log_format decoy_ext" "$STACK_CONF" 2>/dev/null; then
    sed -i "1i log_format decoy_ext '\$remote_addr [\$time_local] \"\$request\" \$status \"\$http_user_agent\" host=\$host';" "$STACK_CONF"
  fi
  [[ -e "$STACK_LINK" || -L "$STACK_LINK" ]] || ln -sf "$STACK_CONF" "$STACK_LINK"
  return 0
}

# СѓРґР°Р»РёС‚СЊ decoy-Р±Р»РѕРє РїРѕ РґРѕРјРµРЅСѓ (РјР°СЂРєРµСЂС‹ # >>> decoy ... domain=X)
stack_del_decoy() {
  local dom="$1" type="${2:-decoy}"   # type: decoy | fallback-plain | all
  [[ -f "$STACK_CONF" ]] || return 0
  local tmp
  tmp=$(mktemp)
  awk -v dom="$dom" -v mode="$type" '
    BEGIN {
      want1 = (mode == "decoy" || mode == "all")
      want2 = (mode == "fallback-plain" || mode == "all")
    }
    !skip && want1 && index($0, "# >>> decoy ") == 1 {
      tail = $0
      sub(/^.* domain=/, "", tail)
      if (tail == dom) { skip = 1; kind = 1; next }
    }
    !skip && want2 && index($0, "# >>> fallback-plain ") == 1 {
      tail = $0
      sub(/^.* domain=/, "", tail)
      if (tail == dom) { skip = 1; kind = 2; next }
    }
    skip && kind == 1 && index($0, "# <<< decoy ") == 1 { skip = 0; next }
    skip && kind == 2 && index($0, "# <<< fallback-plain ") == 1 { skip = 0; next }
    !skip { print }
  ' "$STACK_CONF" > "$tmp" 2>/dev/null && mv "$tmp" "$STACK_CONF"
}

# СѓРґР°Р»РёС‚СЊ Р’РЎР• decoy-Р±Р»РѕРєРё
stack_del_all_decoy() {
  [[ -f "$STACK_CONF" ]] || return 0
  local tmp
  tmp=$(mktemp)
  awk '
    index($0, "# >>> decoy ") == 1 || index($0, "# >>> fallback-plain ") == 1 { skip = 1; next }
    skip && (index($0, "# <<< decoy ") == 1 || index($0, "# <<< fallback-plain ") == 1) { skip = 0; next }
    !skip { print }
  ' "$STACK_CONF" > "$tmp" 2>/dev/null && mv "$tmp" "$STACK_CONF"
}

# РјРµС‚Р°РґР°РЅРЅС‹Рµ decoy РїРѕ РґРѕРјРµРЅСѓ:  port root cert key
stack_decoy_meta() {
  local dom="$1" line=""
  [[ -f "$STACK_CONF" ]] || return 1
  local esc="${dom//./\\.}"
  line=$(grep -m1 -E "# >>> decoy .*domain=${esc}([[:space:]]|\$)" "$STACK_CONF" 2>/dev/null || true)
  [[ -z "$line" ]] && return 1
  local port root cert key
  port=$(grep -oE 'port=[0-9]+'   <<<"$line" | head -1 | cut -d= -f2)
  root=$(grep -oE 'root=[^ ]+'    <<<"$line" | head -1 | cut -d= -f2-)
  cert=$(grep -oE 'cert=[^ ]+'    <<<"$line" | head -1 | cut -d= -f2-)
  key=$(grep -oE 'key=[^ ]+'      <<<"$line" | head -1 | cut -d= -f2-)
  echo "$port $root $cert $key"
}

mk_decoy() {
  # $1..$6 РєР°Рє СЂР°РЅСЊС€Рµ; $7 (РЅРµРѕР±СЏР·Р°С‚РµР»СЊРЅРѕ) вЂ” opts: "ua404=1 redir=https://..."
  local port="$1" dom="$2" cert="$3" key="$4" root="$5"
  local tpl="${6:-default}" opts="${7:-}"
  local opt_ua404=1 opt_redir="" opt_status404=0
  local _o _k _v
  for _o in $opts; do
    _k="${_o%%=*}"; _v="${_o#*=}"
    case "$_k" in
      ua404) opt_ua404="$_v" ;;
      redir) opt_redir="$_v" ;;
      status404) opt_status404="$_v" ;;
    esac
  done
  # custom:<path> вЂ” nginx Р±СѓРґРµС‚ СЃР»СѓР¶РёС‚СЊ РїСЂСЏРјРѕ РёР· СѓРєР°Р·Р°РЅРЅРѕР№ РїР°РїРєРё
  if [[ "$tpl" == custom:* ]]; then
    root="${tpl#custom:}"
    tpl="custom"
  fi
  mkdir -p "$root" 2>/dev/null || true

  # security-Р·Р°РіРѕР»РѕРІРєРё decoy: СЃРЅРёРїРїРµС‚ РґРѕР»Р¶РµРЅ СЃСѓС‰РµСЃС‚РІРѕРІР°С‚СЊ РґРѕ nginx -t
  mkdir -p /etc/nginx/snippets 2>/dev/null || true
  [[ -f /etc/nginx/snippets/decoy-headers.conf ]] || cat > /etc/nginx/snippets/decoy-headers.conf <<'EOF'
add_header X-Content-Type-Options "nosniff" always;
add_header X-Frame-Options "SAMEORIGIN" always;
add_header Referrer-Policy "no-referrer-when-downgrade" always;
EOF

  # index.html: login-СЂРµРїР»РёРєРё РёР· DECOY_LOGIN_DIR, СЃС‚Р°С‚РёРєР° РёР· DECOY_TPL_DIR
  if [[ "$tpl" != "custom" ]]; then
    local tpl_src="$DECOY_TPL_DIR/$tpl.html"
    is_login_template "$tpl" && tpl_src="$DECOY_LOGIN_DIR/$tpl.html"
    if [[ -f "$tpl_src" ]]; then
      # Р’СЃРµРіРґР° Р·Р°РјРµРЅСЏРµРј СЃС‚Р°СЂСѓСЋ СЃС‚СЂР°РЅРёС†Сѓ: РёРЅР°С‡Рµ РїСЂРё СЃРјРµРЅРµ С€Р°Р±Р»РѕРЅР°
      # СЃС‚Р°СЂС‹Р№ index.html РјРѕР¶РµС‚ РѕСЃС‚Р°С‚СЊСЃСЏ РЅРµР·Р°С‚СЂРѕРЅСѓС‚С‹Рј.
      rm -f "$root/index.html" 2>/dev/null || true
      if ! cp -f "$tpl_src" "$root/index.html" 2>/dev/null; then
        warn "РќРµ СѓРґР°Р»РѕСЃСЊ РїСЂРёРјРµРЅРёС‚СЊ decoy-С€Р°Р±Р»РѕРЅ $tpl Рє $root"
        return 1
      fi
    elif [[ "$tpl" != redirect && "$tpl" != locked ]]; then
      cp -f "$DECOY_TPL_DIR/default.html" "$root/index.html" 2>/dev/null || true
    fi
    chown www-data:www-data "$root/index.html" 2>/dev/null || true
  fi

  # РЁР°Р±Р»РѕРЅ РѕС‚РґР°С‘С‚СЃСЏ СЃ HTTP 404 С‡РµСЂРµР· РІРЅСѓС‚СЂРµРЅРЅРёР№ РїРµСЂРµС…РѕРґ: РїСЂСЏРјРѕР№
  # server-level return 404 Р·Р°С†РёРєР»РёРІР°РµС‚ error_page Рё РїРѕРєР°Р·С‹РІР°РµС‚ nginx 404.
  local extra=""
  [[ "$opt_status404" == "1" ]] && extra='    error_page 418 =404 @stack_decoy_404;
    return 418;
    location @stack_decoy_404 { try_files /index.html =404; }'
  case "$tpl" in
    redirect)
      [[ -z "$opt_redir" ]] && opt_redir="https://www.google.com/"
      extra="    return 302 $opt_redir;"
      ;;
    locked)
      extra='    add_header WWW-Authenticate "Basic realm=Restricted" always;
    return 401;'
      ;;
  esac

  # UA-СЃРІРёС‚С‡: СЃРєР°РЅРµСЂР°Рј/Р±РѕС‚Р°Рј вЂ” РїСѓСЃС‚Р°СЏ 404 (РІ Р»РѕРі РїРѕРїР°РґР°РµС‚ в†’ Р±Р°РЅРѕРІ РЅРµ РјРёРЅРѕРІР°С‚СЊ)
  local ua_block=""
  if [[ "$opt_ua404" == "1" && "$tpl" != "redirect" && "$tpl" != "locked" ]]; then
    ua_block='    if ($http_user_agent ~* (curl|wget|python|scrapy|httpclient|okhttp|go-http|libwww|zgrab|nikto|dirbuster|gobuster|wfuzz|nuclei|masscan|headless|bot|spider|crawler|scanner)) { return 404; }'
  fi

  # shellcheck disable=SC2154 # \$uri/\$args вЂ” РїРµСЂРµРјРµРЅРЅС‹Рµ nginx, РЅРµ bash
  local body
  body=$(cat <<EOF
server {
    listen 127.0.0.1:$port ssl;
    server_name $dom;
    ssl_certificate     $cert;
    ssl_certificate_key $key;
    include /etc/nginx/snippets/decoy-headers.conf;
    root $root;
    index index.html;
    access_log $DECOY_LOG_ACCESS decoy_ext;
    error_log  /var/log/nginx/decoy-error.log;
$extra
$ua_block
    location = /robots.txt { return 200 "User-agent: *\nDisallow: /\n"; }
    location ~ ^/(admin|wp-admin|wp-login\.php|\.env|\.git|api/debug|phpmyadmin|configuration\.php|actuator)(/|\$|\?) { return 404; }
    location / { try_files \$uri \$uri/ /index.html; }
    location = /login { limit_except POST { deny all; } return 401; }
}
EOF
)

  stack_ensure
  stack_del_decoy "$dom"   # Р·Р°РјРµРЅР° Р±Р»РѕРєР° С‚РѕРіРѕ Р¶Рµ РґРѕРјРµРЅР° (upsert)
  {
    # Р’РђР–РќРћ: domain= РґРµСЂР¶РёРј РџРћРЎР›Р•Р”РќРРњ РєР»СЋС‡РѕРј вЂ” РїР°СЂСЃРµСЂС‹ РјР°СЂРєРµСЂР° РЅР° СЌС‚Рѕ СЂР°СЃСЃС‡РёС‚Р°РЅС‹
    echo "# >>> decoy port=$port root=$root cert=$cert key=$key tpl=$tpl ua404=$opt_ua404 status404=$opt_status404 domain=$dom"
    echo "$body"
    echo "# <<< decoy port=$port domain=$dom"
  } >> "$STACK_CONF"
}

# Р”Р»СЏ Xray fallback РІС…РѕРґСЏС‰РёР№ TLS СѓР¶Рµ СЂР°СЃС€РёС„СЂРѕРІР°РЅ, РїРѕСЌС‚РѕРјСѓ dest РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ
# РѕР±С‹С‡РЅС‹Рј HTTP, Р° РЅРµ РІС‚РѕСЂС‹Рј TLS-СЃРѕРµРґРёРЅРµРЅРёРµРј. РРЅР°С‡Рµ Р±СЂР°СѓР·РµСЂ РїРѕР»СѓС‡Р°РµС‚
# ERR_HTTP2_PROTOCOL_ERROR/400. РЎРѕР·РґР°С‘Рј РѕС‚РґРµР»СЊРЅС‹Р№ plain listener СЃ С‚РµРј Р¶Рµ root.
mk_plain_fallback_decoy() {   # <port> <domain> <root>
  local port="$1" dom="$2" root="$3"
  [[ "$port" =~ ^[0-9]+$ && "$dom" && "$root" ]] || return 1
  stack_ensure
  stack_del_decoy "$dom" "fallback-plain" 2>/dev/null || true
  # shellcheck disable=SC2154 # \\$uri вЂ” РїРµСЂРµРјРµРЅРЅР°СЏ nginx РІ heredoc
  {
    echo "# >>> fallback-plain port=$port root=$root domain=$dom"
    cat <<EOF
server {
    listen 127.0.0.1:$port;
    server_name $dom;
    root $root;
    index index.html;
    include /etc/nginx/snippets/decoy-headers.conf;
    access_log $DECOY_LOG_ACCESS decoy_ext;
    error_log /var/log/nginx/decoy-error.log;
    location = /robots.txt { return 200 "User-agent: *\\nDisallow: /\\n"; }
    # Р›РѕРІСѓС€РєРё СЃРєР°РЅРµСЂРѕРІ вЂ” РєР°Рє РІ ssl-С€Р°Р±Р»РѕРЅРµ decoy (РїР°СЂРёС‚РµС‚ РѕС‚РІРµС‚РѕРІ 404)
    location ~ ^/(admin|wp-admin|wp-login\.php|\.env|\.git|api/debug|phpmyadmin|configuration\.php|actuator)(/|\$|\?) { return 404; }
    location / { try_files \$uri \$uri/ /index.html; }
    location = /login { limit_except POST { deny all; } return 401; }
}
EOF
    echo "# <<< fallback-plain port=$port domain=$dom"
  } >> "$STACK_CONF"
  nginx_reload
}

# =====================================================================
# SNI Р”Р›РЇ РРќР‘РђРЈРќР”Рђ
# =====================================================================
# РљР°РЅРѕРЅРёС‡РµСЃРєРёР№ РїРѕСЂС‚ decoy РґР»СЏ РёРЅР±Р°СѓРЅРґР°: 4444 + id.
# Р­С‚Рѕ Р¶Рµ РїСЂР°РІРёР»Рѕ РёСЃРїРѕР»СЊР·СѓСЋС‚ configure_sni_for_inbound, decoy_ensure_all Рё
# СЃР°РјРѕР»РµС‡РµРЅРёРµ (sync_inbound_needs). Р Р°РЅСЊС€Рµ Рї.1 РЅСѓРјРµСЂРѕРІР°Р»
# РїРѕСЂС‚С‹ РїРѕСЃР»РµРґРѕРІР°С‚РµР»СЊРЅРѕ (4444, 4445, 4446вЂ¦), РёР·-Р·Р° С‡РµРіРѕ СЃР°РјРѕР»РµС‡РµРЅРёРµ РєР°Р¶РґС‹Рµ
# 2 РјРёРЅСѓС‚С‹ СЃС‡РёС‚Р°Р»Рѕ reality-dest СЃР±РёС‚С‹Рј, РїРµСЂРµРїРёСЃС‹РІР°Р»Рѕ decoy-Р±Р»РѕРєРё РЅР° В«СЃРІРѕРёВ»
# РїРѕСЂС‚С‹ Рё РЅРµ РїРµСЂРµР·Р°РіСЂСѓР¶Р°Р»Рѕ nginx вЂ” РєРѕРЅС„РёРі СЂР°СЃС…РѕРґРёР»СЃСЏ СЃ СЂР°Р±РѕС‚Р°СЋС‰РёРј nginx,
# Рё Р·Р°РіР»СѓС€РєРё СЃС‚Р°РЅРѕРІРёР»РёСЃСЊ РЅРµРґРѕСЃС‚СѓРїРЅС‹.
decoy_port_for_id() {   # <inbound_id>
  local d="${1:-0}"
  [[ "$d" =~ ^[0-9]+$ ]] || d=0
  printf '%s' "$(( 4444 + d ))"
}

# РљР°РЅРѕРЅРёС‡РµСЃРєРёР№ РґРѕРјРµРЅ РёРЅР±Р°СѓРЅРґР° РїРѕ SNI-РєР°СЂС‚Рµ nginx: СЃС‚СЂРѕРєР°
# В«domain inb_<id>_backend;В» РІ sni-router.conf. Р­С‚Рѕ РµРґРёРЅСЃС‚РІРµРЅРЅС‹Р№ РёСЃС‚РѕС‡РЅРёРє,
# РѕС‚СЂР°Р¶Р°СЋС‰РёР№ С„Р°РєС‚РёС‡РµСЃРєСѓСЋ РјР°СЂС€СЂСѓС‚РёР·Р°С†РёСЋ 443: hosts.address РјРѕР¶РµС‚ РґРµСЂР¶Р°С‚СЊ
# РѕР±С‰РёР№/РїР°РЅРµР»СЊРЅС‹Р№ РґРѕРјРµРЅ, Р° serverNames РІ Р‘Р” вЂ” Р±С‹С‚СЊ РёСЃРїРѕСЂС‡РµРЅС‹ РїСЂРѕС€Р»РѕР№ РїРѕС‡РёРЅРєРѕР№.
sni_domain_for_inbound() {   # <inbound_id>
  [[ -n "$1" && -f "$SNI_CONF" ]] || return 1
  local d
  d=$(grep -E "^[[:space:]]+[^[:space:]]+[[:space:]]+inb_${1}_backend;" "$SNI_CONF" 2>/dev/null | awk '{print $1}' | head -1 || true)
  [[ -n "$d" ]] || return 1
  printf '%s' "$d"
}

# Reality dest в†’ Р»РѕРєР°Р»СЊРЅС‹Р№ decoy nginx (РІРЅСѓС‚СЂРµРЅРЅРёР№ IP:РїРѕСЂС‚ decoy-РєРѕРЅС„Р°)
# + СЃРёРЅС…СЂРѕРЅРёР·Р°С†РёСЏ serverNames СЃ РІС‹Р±СЂР°РЅРЅС‹Рј SNI-РґРѕРјРµРЅРѕРј.
# Р•СЃР»Рё РґРѕРјРµРЅ РїСѓСЃС‚РѕР№ РёР»Рё www.microsoft.com вЂ” РЅРёС‡РµРіРѕ РЅРµ РјРµРЅСЏРµРј (РѕСЃС‚Р°С‘С‚СЃСЏ microsoft).
reality_set_dest() {
  local id="$1" decoy_port="$2" dom="${3:-}" stream=""
  stream=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  grep -qi reality <<<"$stream" || return 0
  db_protect_suspend   # РѕСЃРѕР·РЅР°РЅРЅР°СЏ СЃРјРµРЅР° dest вЂ” С‚СЂРёРіРіРµСЂС‹ РІРµСЂРЅСѓС‚СЃСЏ РЅР° РІС‹С…РѕРґРµ
  local new_stream
  # РЅРѕРІС‹Рµ РїР°РЅРµР»Рё (xray 25+) С‡РёС‚Р°СЋС‚ В«Р¦РµР»СЊВ» РёР· target, СЃС‚Р°СЂС‹Рµ вЂ” РёР· dest: РїРёС€РµРј РћР‘Рђ РєР»СЋС‡Р°
  new_stream=$(sqlite3 "$XUI_DB" "SELECT json_set(stream_settings,'$.realitySettings.dest','127.0.0.1:$decoy_port','$.realitySettings.target','127.0.0.1:$decoy_port') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  # РїСЂРѕРІРµСЂСЏРµРј, С‡С‚Рѕ dest/target РґРµР№СЃС‚РІРёС‚РµР»СЊРЅРѕ Р·Р°РјРµРЅРµРЅС‹; РёРЅР°С‡Рµ fallback РЅР° sed
  if [[ -z "$new_stream" || "$new_stream" == "null" ]] || ! grep -Eq "\"(dest|target)\": ?\"127\.0\.0\.1:$decoy_port\"" <<<"$new_stream"; then
    new_stream=$(sed -E "s/\"(dest|target)\"([[:space:]]*:[[:space:]]*)\"[^\"]*\"/\"\1\"\2\"127.0.0.1:$decoy_port\"/g" <<<"$stream")
  fi
  # РµСЃР»Рё РєР°РєРѕРіРѕ-С‚Рѕ РёР· РєР»СЋС‡РµР№ РІРѕРѕР±С‰Рµ РЅРµ Р±С‹Р»Рѕ вЂ” РІСЃС‚Р°РІР»СЏРµРј РІРЅСѓС‚СЂСЊ realitySettings
  grep -Eq "\"dest\": ?\"127\.0\.0\.1:$decoy_port\"" <<<"$new_stream" \
    || new_stream=$(sed -E "s/\"realitySettings\": ?\{/\"realitySettings\":{\"dest\":\"127.0.0.1:$decoy_port\",/" <<<"$new_stream")
  grep -Eq "\"target\": ?\"127\.0\.0\.1:$decoy_port\"" <<<"$new_stream" \
    || new_stream=$(sed -E "s/\"realitySettings\": ?\{/\"realitySettings\":{\"target\":\"127.0.0.1:$decoy_port\",/" <<<"$new_stream")
  grep -Eq "\"(dest|target)\": ?\"127\.0\.0\.1:$decoy_port\"" <<<"$new_stream" || { warn "  РЅРµ СѓРґР°Р»РѕСЃСЊ РѕР±РЅРѕРІРёС‚СЊ reality dest (РёРЅР±Р°СѓРЅРґ #$id)"; return 1; }
  # serverNames в†’ РІС‹Р±СЂР°РЅРЅС‹Р№ SNI-РґРѕРјРµРЅ (РµСЃР»Рё РѕРЅ Р·Р°РґР°РЅ Рё РµС‰С‘ РЅРµ РІ СЃРїРёСЃРєРµ)
  if [[ -n "$dom" && "$dom" != "www.microsoft.com" ]] && ! grep -q "\"$dom\"" <<<"$new_stream"; then
    new_stream=$(sed -E "s/\"serverNames\"[[:space:]]*:[[:space:]]*\[[^]]*\]/\"serverNames\":[\"$dom\"]/" <<<"$new_stream")
  fi
  panel_journal_capture_row inbounds "$id"   # СЃРЅРёРјРѕРє СЃС‚СЂРѕРєРё РґР»СЏ РѕС‚РєР°С‚Р° (Рї.2/Рї.3)
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" "UPDATE inbounds SET stream_settings='$new_stream' WHERE id=$id;" 2>/dev/null || true
  # РљРћРќРўР РћР›Р¬: Р·РЅР°С‡РµРЅРёРµ РѕР±СЏР·Р°РЅРѕ СЂРµР°Р»СЊРЅРѕ Р»РµС‡СЊ РІ Р‘Р”. Р Р°РЅСЊС€Рµ С‚СЂРёРіРіРµСЂ Р·Р°С‰РёС‚С‹ РјРѕР»С‡Р°
  # РѕС‚РєР°С‚С‹РІР°Р» Р·Р°РїРёСЃСЊ, СЃРєСЂРёРїС‚ РїРёСЃР°Р» В«dest в†’ вЂ¦В», Р° РІ Р±Р°Р·Рµ РѕСЃС‚Р°РІР°Р»РѕСЃСЊ СЃС‚Р°СЂРѕРµ вЂ”
  # РѕС‚СЃСЋРґР° РІРµС‡РЅР°СЏ В«Р°РІС‚РѕРїРѕС‡РёРЅРєР°В» Рё СЂР°СЃС…РѕР¶РґРµРЅРёРµ decoy-Р±Р»РѕРєРѕРІ СЃ dest.
  local _stored=""
  _stored=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  if [[ "$_stored" != "127.0.0.1:$decoy_port" ]]; then
    warn "  Reality dest РќР• СѓРґРµСЂР¶Р°Р»СЃСЏ РІ Р‘Р” (#$id: РІ Р±Р°Р·Рµ '${_stored:-РїСѓСЃС‚Рѕ}', РѕР¶РёРґР°Р»РѕСЃСЊ 127.0.0.1:$decoy_port) вЂ” РїРµСЂРµРїСЂРѕРІРµСЂСЊ decoy-РїРѕСЂС‚ (Рї.2)"
  fi
  db_protect_resume
  log "  Reality dest в†’ 127.0.0.1:$decoy_port (decoy nginx)"
  return 0
}

# РЎР°РјРѕРїРѕС‡РёРЅРєР° Reality Р’ РџРћР”РљР›Р®Р§Р•РќРРЇРҐ: Сѓ Р»РѕРєР°Р»СЊРЅРѕРіРѕ Reality (dest=127.0.0.1:*)
# serverNames[0] РѕР±СЏР·Р°РЅ СЃРѕРІРїР°РґР°С‚СЊ СЃ РґРѕРјРµРЅРѕРј С…РѕСЃС‚Р° вЂ” РёРЅР°С‡Рµ РєР»РёРµРЅС‚СЃРєР°СЏ СЃСЃС‹Р»РєР°
# Р±СЊС‘С‚СЃСЏ РјРёРјРѕ (SNI РєР»РёРµРЅС‚Р° РЅРµ РІС…РѕРґРёС‚ РІ serverNames, xray СЂРІС‘С‚ handshake).
# РСЃС‚РѕСЂРёСЏ Р±РѕР»РµР·РЅРё: dest/decoy РїРѕС‡РёРЅРµРЅС‹, Р° serverNames РґРµСЂР¶РёС‚ СЃС‚Р°СЂС‹Р№/С‡СѓР¶РѕР№
# РґРѕРјРµРЅ вЂ” СЃР°РјРѕРїРѕС‡РёРЅРєР° СЌС‚Рѕ РїСЂРѕРїСѓСЃРєР°Р»Р°. Р’РЅРµС€РЅРёР№ Reality РЅРµ С‚СЂРѕРіР°РµРј.
reality_sni_repair() {
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || return 0
  local changed=0 id st dom cur
  while IFS='|' read -r id st; do
    [[ -n "$id" ]] || continue
    grep -Eqi '"security"[[:space:]]*:[[:space:]]*"reality"' <<<"$st" || continue
    reality_external_dest "$id" && continue
    # РљР°РЅРѕРЅРёС‡РµСЃРєРёР№ РґРѕРјРµРЅ С…РѕСЃС‚Р°: SNI-РєР°СЂС‚Р° nginx в†’ hosts.sni в†’ hosts.address в†’
    # С‚РµРєСѓС‰РёР№ serverNames[0]. SNI-РєР°СЂС‚Р° вЂ” РІС‹СЃС€РёР№ РїСЂРёРѕСЂРёС‚РµС‚: РѕРЅР° РѕС‚СЂР°Р¶Р°РµС‚
    # С„Р°РєС‚РёС‡РµСЃРєРёР№ РјР°СЂС€СЂСѓС‚ 443, С‚РѕРіРґР° РєР°Рє hosts.address Р±С‹РІР°РµС‚ РѕР±С‰РёР№/РїР°РЅРµР»СЊРЅС‹Р№
    # РґРѕРјРµРЅ вЂ” РїСЂРµР¶РЅСЏСЏ РїРѕС‡РёРЅРєР° РїРµСЂРµР·Р°РїРёСЃС‹РІР°Р»Р° serverNames РёРј Рё Р»РѕРјР°Р»Р° СЃСЃС‹Р»РєРё.
    dom=$(sni_domain_for_inbound "$id" 2>/dev/null || true)
    if [[ -z "$dom" ]]; then
      dom=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
        "SELECT COALESCE((SELECT sni FROM hosts WHERE inbound_id=$id AND port=443 AND COALESCE(sni,'')<>'' LIMIT 1),
                         (SELECT address FROM hosts WHERE inbound_id=$id AND port=443 AND COALESCE(address,'')<>'' LIMIT 1),
                         json_extract(stream_settings,'\$.realitySettings.serverNames[0]'),'')
         FROM inbounds WHERE id=$id;" 2>/dev/null | head -1 || true)
    fi
    [[ -n "$dom" && "$dom" != "www.microsoft.com" ]] || continue
    cur=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.serverNames[0]'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    [[ "$cur" == "$dom" ]] && continue
    if ! grep -Eq '"serverNames"[[:space:]]*:[[:space:]]*\[' <<<"$st"; then
      continue   # Р±РёС‚С‹Р№/РЅРµСЃС‚Р°РЅРґР°СЂС‚РЅС‹Р№ stream вЂ” РІСЃР»РµРїСѓСЋ РЅРµ РїСЂР°РІРёРј
    fi
    db_protect_suspend
    local new_stream
    new_stream=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT json_set(stream_settings,'\$.realitySettings.serverNames',json_array('$dom')) FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    if [[ -n "$new_stream" && "$new_stream" != "null" ]] && grep -q "\"$dom\"" <<<"$new_stream"; then
      panel_journal_capture_row inbounds "$id"
      sqlite3 -cmd ".timeout 3000" "$XUI_DB" "UPDATE inbounds SET stream_settings='$new_stream' WHERE id=$id;" 2>/dev/null || true
      # РєРѕРЅС‚СЂРѕР»СЊ: РѕР±СЏР·Р°РЅРѕ СѓРґРµСЂР¶Р°С‚СЊСЃСЏ РІ Р‘Р” (Р°РЅС‚Рё-В«РІРµС‡РЅР°СЏ РїРѕС‡РёРЅРєР°В»)
      local _stored=""
      _stored=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.serverNames[0]'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
      if [[ "$_stored" == "$dom" ]]; then
        log "  Reality #$id: serverNames '${cur:-РїСѓСЃС‚Рѕ}' в†’ '$dom' (СЃРІРµСЂРєР° СЃ С…РѕСЃС‚РѕРј)"
        changed=1
      else
        warn "  Reality #$id: serverNames РЅРµ СѓРґРµСЂР¶Р°Р»РёСЃСЊ РІ Р‘Р” (Р·Р°С‰РёС‚РЅС‹Р№ С‚СЂРёРіРіРµСЂ?)"
      fi
    fi
    db_protect_resume
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,COALESCE(stream_settings,'') FROM inbounds WHERE enable=1;" 2>/dev/null || true)
  if (( changed )); then
    systemctl restart x-ui 2>/dev/null || true
  fi
  return 0
}

# VLESS/Trojan TCP+TLS fallback в†’ Р»РѕРєР°Р»СЊРЅС‹Р№ HTTPS-decoy.
# XHTTP TLS С‚Р°РєР¶Рµ РѕР±СЃР»СѓР¶РёРІР°РµС‚СЃСЏ Р»РѕРєР°Р»СЊРЅС‹Рј nginx frontend: РїСѓС‚СЊ XHTTP СѓС…РѕРґРёС‚
# РІ Xray, РѕР±С‹С‡РЅС‹Р№ Р±СЂР°СѓР·РµСЂРЅС‹Р№ Р·Р°РїСЂРѕСЃ вЂ” РІ HTTPS-decoy.
tls_fallback_set() {   # <inbound_id> <decoy_port>
  local id="$1" decoy_port="$2" proto net sec st new_settings stored
  [[ "$id" =~ ^[0-9]+$ && "$decoy_port" =~ ^[0-9]+$ ]] || return 1
  proto=$(sqlite3 "$XUI_DB" "SELECT protocol FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  [[ "$proto" == "vless" || "$proto" == "trojan" ]] || return 1
  st=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'{}') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  net=$(grep -oE '"network"[[:space:]]*:[[:space:]]*"[^"]+' <<<"$st" | head -1 | sed 's/.*"//')
  sec=$(grep -oE '"security"[[:space:]]*:[[:space:]]*"[^"]+' <<<"$st" | head -1 | sed 's/.*"//')
  [[ "$sec" == "tls" && ( "$net" == "tcp" || "$net" == "xhttp" ) ]] || {
    warn "  #$id: fallback РЅРµ РІРєР»СЋС‡С‘РЅ (С‚СЂРµР±СѓРµС‚СЃСЏ TCP/XHTTP+TLS; РїРѕР»СѓС‡РµРЅРѕ ${net:-?}/${sec:-?})"
    return 2
  }
  db_protect_suspend
  new_settings=$(sqlite3 "$XUI_DB" "SELECT json_set(COALESCE(settings,'{}'),'\$.fallbacks',json('[{\"dest\":\"127.0.0.1:$decoy_port\"}]')) FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  [[ -n "$new_settings" && "$new_settings" != "null" ]] || { db_protect_resume; return 1; }
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" "UPDATE inbounds SET settings='$(sql_escape "$new_settings")' WHERE id=$id;" 2>/dev/null || { db_protect_resume; return 1; }
  stored=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.fallbacks[0].dest') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  db_protect_resume
  [[ "$stored" == "127.0.0.1:$decoy_port" ]] || { warn "  #$id: fallback РЅРµ СѓРґРµСЂР¶Р°Р»СЃСЏ РІ Р‘Р”"; return 1; }
  log "  #$id: TLS fallback в†’ 127.0.0.1:$decoy_port"
  return 0
}


# Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ HTTPS-Р·Р°РіР»СѓС€РєСѓ РґР»СЏ СѓР¶Рµ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РµРіРѕ SNI-РјР°СЂС€СЂСѓС‚Р°.
# Р’Р°Р¶РЅРѕ: configure_sni_for_inbound СЂР°РЅСЊС€Рµ СЃСЂР°Р·Сѓ РІС‹С…РѕРґРёР» РёР· existing_domain,
# РїРѕСЌС‚РѕРјСѓ РїРѕРІС‚РѕСЂРЅС‹Р№ Р·Р°РїСѓСЃРє В«РџРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґВ» РїСЂРѕРїСѓСЃРєР°Р» TLS decoy.
tls_decoy_ensure_existing() {   # <id> <domain>
  local id="$1" dom="$2" st proto net sec port cp cert key tpl dport path
  [[ "$id" =~ ^[0-9]+$ && -n "$dom" ]] || return 1
  st=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  proto=$(sqlite3 "$XUI_DB" "SELECT protocol FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  port=$(sqlite3 "$XUI_DB" "SELECT port FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  net=$(grep -oE '"network"[[:space:]]*:[[:space:]]*"[^" ]+' <<<"$st" | head -1 | sed 's/.*"//')
  sec=$(grep -oE '"security"[[:space:]]*:[[:space:]]*"[^" ]+' <<<"$st" | head -1 | sed 's/.*"//')
  [[ "$proto" == vless || "$proto" == trojan ]] || return 0
  [[ "$sec" == tls ]] || return 0
  # XHTTP TLS СЂР°Р±РѕС‚Р°РµС‚ РЅР°РїСЂСЏРјСѓСЋ РІ Xray С‡РµСЂРµР· SNI passthrough.
  # Р”Р»СЏ СЌС‚РѕРіРѕ СЂРµР¶РёРјР° decoy РЅРµ СЃРѕР·РґР°С‘Рј Рё С€Р°Р±Р»РѕРЅ РЅРµ Р·Р°РїСЂР°С€РёРІР°РµРј.
  [[ "$net" == xhttp ]] && return 0
  cp=$(cert_paths "$dom" 2>/dev/null || true)
  [[ -n "$cp" ]] || { cert_issue "$dom" >/dev/null 2>&1 || true; cp=$(cert_paths "$dom" 2>/dev/null || true); }
  [[ -n "$cp" ]] || { warn "  #$id: cert РґР»СЏ $dom РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  cert="${cp%% *}"; key="${cp##* }"; tpl="$(decoy_tpl_current "$dom")"; tpl="${tpl:-$(decoy_tpl_for "$dom")}"; decoy_tpl_store_set "$dom" "$tpl" >/dev/null 2>&1 || true
  dport=$(decoy_port_for_id "$id")
  while ss -tlnH "sport = :$dport" 2>/dev/null | grep -q .; do dport=$((dport+1)); done
  mk_decoy "$dport" "$dom" "$cert" "$key" "/var/www/decoy-tls-$id" "$tpl" || return 1
  if [[ "$net" == xhttp ]]; then
    path=$(sqlite3 "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.xhttpSettings.path'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    [[ -n "$path" ]] || return 1
    db_protect_suspend
    sqlite3 "$XUI_DB" "UPDATE inbounds SET stream_settings=json_remove(json_set(COALESCE(stream_settings,'{}'),'\$.security','none'),'\$.tlsSettings') WHERE id=$id;" >/dev/null 2>&1 || true
    db_protect_resume
    stack_cdn_upsert "$dom" "$dom" "$path" "$port" "$dport" "$cert" "$key"
    cdn_frontend_ensure "$dom" "$dom"
    log "  #$id: XHTTP TLS РїРµСЂРµРІРµРґС‘РЅ РЅР° nginx frontend, decoy в†’ 127.0.0.1:$dport"
  elif [[ "$net" == tcp ]]; then
    local pp=$((dport+1)); while ss -tlnH "sport = :$pp" 2>/dev/null | grep -q .; do pp=$((pp+1)); done
    mk_plain_fallback_decoy "$pp" "$dom" "/var/www/decoy-tls-$id" || return 1
    tls_fallback_set "$id" "$pp" || return 1
    log "  #$id: TCP TLS fallback в†’ 127.0.0.1:$pp, decoy в†’ 127.0.0.1:$dport"
  fi
  nginx_reload || true
  return 0
}

# Р’СЃС‚Р°РІРёС‚СЊ/РѕР±РЅРѕРІРёС‚СЊ Р·Р°РїРёСЃСЊ hosts РІ РїР°РЅРµР»Рё РґР»СЏ TCP-РёРЅР±Р°СѓРЅРґР° (Р°РґСЂРµСЃ=РґРѕРјРµРЅ, РїРѕСЂС‚ 443).
# РњРћР”Р•Р›Р¬ В«РћР”РРќ РҐРћРЎРўВ»: РѕРґРЅР° Р·Р°РїРёСЃСЊ РїР°РЅРµР»Рё вЂ” РјРЅРѕРіРѕ РІС…РѕРґСЏС‰РёС…. Р’ LucX СЌС‚Рѕ РЅРµСЃРєРѕР»СЊРєРѕ
# СЃС‚СЂРѕРє hosts СЃ РћР‘Р©РРњ group_id (РїР°РЅРµР»СЊ СЃРєР»РµРёРІР°РµС‚ РёС… РІ РѕРґРЅСѓ РєР°СЂС‚РѕС‡РєСѓ). РЎС‚СЂРѕРєР°
# РёРЅР±Р°СѓРЅРґР° РєР»Р°РґС‘С‚СЃСЏ РІ РѕР±С‰СѓСЋ РіСЂСѓРїРїСѓ; РµСЃР»Рё РіСЂСѓРїРїС‹ РµС‰С‘ РЅРµС‚ вЂ” СЃРѕР·РґР°С‘Рј
# (group_id = 16 СЃРёРјРІРѕР»РѕРІ [a-z0-9], РєР°Рє РіРµРЅРµСЂРёСЂСѓРµС‚ РїР°РЅРµР»СЊ).
# РќСѓР¶РЅР° Р’РЎР•Рњ TCP-РёРЅР±Р°СѓРЅРґР°Рј (vless, naive, anytls, trusttunnel, tproxyвЂ¦) вЂ” РёРЅР°С‡Рµ
# РІ РїРѕРґРїРёСЃРєР°С… РїР°РЅРµР»Рё РЅРµС‚ СЃСЃС‹Р»РѕРє С‡РµСЂРµР· 443. РўР°Р±Р»РёС†С‹ РјРѕР¶РµС‚ РЅРµ Р±С‹С‚СЊ вЂ” РїСЂРѕРїСѓСЃРєР°РµРј.
#   $1 = inbound_id, $2 = Р°РґСЂРµСЃ (РґРѕРјРµРЅ РїР°РЅРµР»Рё/IP), $3 = SNI (РЅРµРѕР±СЏР·Р°С‚РµР»РµРЅ:
#        РЅСѓР¶РµРЅ РўРћР›Р¬РљРћ С‡СѓР¶РѕРјСѓ reality вЂ” dest = РІРЅРµС€РЅСЏСЏ С†РµР»СЊ в‰  127.0.0.1; РІС‹С‡РёСЃР»СЏРµРј
#        СЃР°РјРё, С‚Р°РєР°СЏ СЃС‚СЂРѕРєР° Р¶РёРІС‘С‚ Р’РќР• РѕР±С‰РµР№ РіСЂСѓРїРїС‹). РЈ СЃРІРѕРµРіРѕ reality/decoy Рё
#        TLS РїРѕР»Рµ SNI РїСѓСЃС‚РѕРµ вЂ” РїР°РЅРµР»СЊ РЅР° Р·Р°РїРѕР»РЅРµРЅРЅРѕРµ СЂСѓРіР°РµС‚СЃСЏ.
# CDN-РёРЅР±Р°СѓРЅРґС‹ hosts РІРµРґС‘С‚ hosts_cdn_upsert (Р°РґСЂРµСЃ/SNI = CDN, security=tls).
# РЈС‡С‘С‚ РІР»Р°РґРµРЅРёСЏ hosts: sm_hosts_owned вЂ” СЂРµРµСЃС‚СЂ СЃС‚СЂРѕРє, СЃРѕР·РґР°РЅРЅС‹С… СЃРєСЂРёРїС‚РѕРј.
hosts_ownership_ensure() {
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || return 1
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" "CREATE TABLE IF NOT EXISTS sm_hosts_owned (inbound_id INTEGER NOT NULL, port INTEGER NOT NULL, address TEXT NOT NULL, sni TEXT NOT NULL DEFAULT '', PRIMARY KEY(inbound_id,port,address,sni));" 2>/dev/null
}
hosts_owned_delete() {
  local id="$1" port="${2:-443}"
  hosts_ownership_ensure || return 0
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" "DELETE FROM hosts WHERE inbound_id=$id AND port=$port AND EXISTS (SELECT 1 FROM sm_hosts_owned o WHERE o.inbound_id=hosts.inbound_id AND o.port=hosts.port AND o.address=COALESCE(hosts.address,'') AND o.sni=COALESCE(hosts.sni,'')); DELETE FROM sm_hosts_owned WHERE inbound_id=$id AND port=$port;" 2>/dev/null || true
}
hosts_group_pick() {   # <address> в†’ group_id СЃР°РјРѕР№ Р±РѕР»СЊС€РѕР№ РіСЂСѓРїРїС‹-С…РѕСЃС‚Р° | ''
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  local _d; _d=$(printf '%s' "$1" | sed "s/'/''/g")
  sqlite3 -cmd ".timeout 3000" -noheader "$XUI_DB" \
    "SELECT COALESCE(group_id,'') FROM hosts WHERE port=443 AND COALESCE(group_id,'')<>'' AND COALESCE(security,'same')='same' AND address='$_d' AND COALESCE(is_disabled,0)=0 GROUP BY group_id ORDER BY COUNT(*) DESC, MIN(id) ASC LIMIT 1;" 2>/dev/null | head -1 || true
}

hosts_upsert() {   # <inbound_id> <address> [sni]
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  local id="$1" dom="$2" sni="${3:-}"
  [[ -z "$id" || -z "$dom" || "$dom" == "null" ]] && return 0
  local has_hosts
  has_hosts=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT name FROM sqlite_master WHERE type='table' AND name='hosts';" 2>/dev/null || true)
  [[ -z "$has_hosts" ]] && return 0
  # Р§СѓР¶РѕР№ reality: SNI = РґРѕРјРµРЅ С†РµР»Рё РѕР±СЏР·Р°С‚РµР»РµРЅ, РёРЅР°С‡Рµ РїРѕРґРїРёСЃРєР° С‚РµСЂСЏРµС‚ serverName.
  # РћРїСЂРµРґРµР»СЏРµРј РїРѕ dest РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ С‚РѕРіРѕ, РїРµСЂРµРґР°Р»Рё Р»Рё С‚СЂРµС‚РёР№ Р°СЂРіСѓРјРµРЅС‚.
  local _dest=""
  _dest=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
          "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),'') FROM inbounds WHERE id=$id;" 2>/dev/null | tr -d '[:space:]') || true
  if [[ -n "$_dest" && "$_dest" != 127.0.0.1:* ]]; then
    sni="${sni:-${_dest%%:*}}"
  else
    sni=""   # СЃРІРѕС‘ reality (decoy) РёР»Рё РЅРµ-reality вЂ” SNI РѕСЃС‚Р°РІР»СЏРµРј РїСѓСЃС‚С‹Рј
  fi
  local cols
  cols=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "PRAGMA table_info(hosts);" 2>/dev/null | awk -F'|' '{print $2}' | tr '\n' ' ')
  db_protect_suspend   # С‚СЂРёРіРіРµСЂС‹ Р·Р°С‰РёС‚С‹ Р‘Р” (РµСЃР»Рё РІРєР»СЋС‡РµРЅС‹): РїРёС€РµРј РѕСЃРѕР·РЅР°РЅРЅРѕ
  hosts_ownership_ensure
  local _dqm; _dqm=$(printf '%s' "$dom" | sed "s/'/''/g")
  local _sqm; _sqm=$(printf '%s' "$sni" | sed "s/'/''/g")
  # Р“СЂСѓРїРїР°-С…РѕСЃС‚ С‚РѕР»СЊРєРѕ РґР»СЏ СЃС‚СЂРѕРє Р±РµР· СЃРѕР±СЃС‚РІРµРЅРЅРѕРіРѕ SNI (С‡СѓР¶РѕР№ reality вЂ” РІРЅРµ)
  local gid="" _gid_new=false
  if [[ -z "$sni" ]]; then
    gid=$(hosts_group_pick "$dom")
    if [[ -z "$gid" ]]; then
      gid=$(tr -dc 'a-z0-9' </dev/urandom 2>/dev/null | head -c 16)
      [[ -z "$gid" ]] && gid="grp$(date +%s)"
      _gid_new=true
    fi
  fi
  local _gqm; _gqm=$(printf '%s' "$gid" | sed "s/'/''/g")
  # РРґРµРјРїРѕС‚РµРЅС‚РЅРѕСЃС‚СЊ: СЃС‚СЂРѕРєР° СѓР¶Рµ РІ РЅСѓР¶РЅРѕРј РІРёРґРµ (РіСЂСѓРїРїР°/Р°РґСЂРµСЃ/SNI/same) вЂ” РЅРµ С‚СЂРѕРіР°РµРј
  local cur
  cur=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "SELECT COUNT(*) FROM hosts WHERE inbound_id=$id AND port=443 AND address='$_dqm' AND COALESCE(sni,'')='$_sqm' AND COALESCE(security,'same')='same' AND COALESCE(group_id,'')='$_gqm' AND COALESCE(is_disabled,0)=0;" 2>/dev/null || echo 0)
  if [[ "$cur" =~ ^[0-9]+$ ]] && (( cur >= 1 )); then
    : # СЂСѓС‚РёРЅР°: hosts-Р·Р°РїРёСЃСЊ СѓР¶Рµ РЅР° РјРµСЃС‚Рµ вЂ” РјРѕР»С‡Р°
    sqlite3 -cmd ".timeout 3000" "$XUI_DB" "INSERT OR REPLACE INTO sm_hosts_owned(inbound_id,port,address,sni) VALUES($id,443,'$_dqm','$_sqm');" 2>/dev/null || true
    return 0
  fi
  local remark
  remark=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT remark FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  # Р’ РѕР±С‰РµР№ РіСЂСѓРїРїРµ remark РµРґРёРЅС‹Р№ (РёРјСЏ В«С…РѕСЃС‚Р°В», РЅР°РїСЂ. В«443В») вЂ” РЅР°СЃР»РµРґСѓРµРј РѕС‚ РіСЂСѓРїРїС‹.
  # РќРћР’РђРЇ РіСЂСѓРїРїР°: РёРјСЏ С…РѕСЃС‚Р° вЂ” В«443В» (РІРЅРµС€РЅРёР№ РІС…РѕРґ СЃС‚РµРєР°), РќР• РёРјСЏ РїРµСЂРІРѕРіРѕ РёРЅР±Р°СѓРЅРґР°.
  if [[ -n "$gid" ]]; then
    if [[ "$_gid_new" == true ]]; then
      remark="443"
    else
      local _gremark
      _gremark=$(sqlite3 -cmd ".timeout 3000" -noheader "$XUI_DB" "SELECT COALESCE(remark,'') FROM hosts WHERE group_id='$_gqm' AND COALESCE(remark,'')<>'' ORDER BY id LIMIT 1;" 2>/dev/null | head -1)
      [[ -n "$_gremark" ]] && remark="$_gremark"
    fi
  fi
  panel_journal_capture_row hosts "$id"   # СЃРЅРёРјРѕРє СЃС‚СЂРѕРєРё РґР»СЏ РѕС‚РєР°С‚Р° (Рї.2/Рї.3)
  hosts_owned_delete "$id" 443
  # Р РѕРІРЅРѕ РѕРґРЅР° СЃС‚СЂРѕРєР° РЅР° РёРЅР±Р°СѓРЅРґ: РїСЂРµР¶РЅРёРµ (РІ С‚.С‡. РІРЅРµ РіСЂСѓРїРїС‹) Р·Р°РјРµРЅСЏРµРј
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" "DELETE FROM hosts WHERE inbound_id=$id AND port=443;" 2>/dev/null || true
  local fields="inbound_id,address,port" vals="$id,'$_dqm',443"
  grep -qw group_id    <<<"$cols" && [[ -n "$gid" ]] && { fields+=",group_id";    vals+=",'$_gqm'"; }
  grep -qw remark      <<<"$cols" && { fields+=",remark";      vals+=",'$(printf '%s' "$remark" | sed "s/'/''/g")'"; }
  grep -qw sni         <<<"$cols" && { fields+=",sni";         vals+=",'$_sqm'"; }
  grep -qw security    <<<"$cols" && { fields+=",security";    vals+=",'same'"; }
  grep -qw fingerprint <<<"$cols" && { fields+=",fingerprint"; vals+=",'firefox'"; }
  grep -qw alpn        <<<"$cols" && { fields+=",alpn";        vals+=",'[]'"; }
  grep -qw sort_order  <<<"$cols" && { fields+=",sort_order";  vals+=",0"; }
  grep -qw is_disabled <<<"$cols" && { fields+=",is_disabled"; vals+=",0"; }
  if sqlite3 -cmd ".timeout 3000" "$XUI_DB" "INSERT INTO hosts ($fields) VALUES ($vals);" 2>/dev/null; then
    sqlite3 -cmd ".timeout 3000" "$XUI_DB" "INSERT OR REPLACE INTO sm_hosts_owned(inbound_id,port,address,sni) VALUES($id,443,'$_dqm','$_sqm');" 2>/dev/null || true
    log "  hosts: #$id в†’ $dom:443 вњ“${gid:+ (РіСЂСѓРїРїР° $gid)}${sni:+, SNI=$sni (С‡СѓР¶РѕР№ reality)}"
  else
    warn "  hosts: РІСЃС‚Р°РІРєР° РґР»СЏ #$id РЅРµ РїСЂРѕС€Р»Р° вЂ” РїСЂРѕРІРµСЂСЊ СЃС…РµРјСѓ С‚Р°Р±Р»РёС†С‹ hosts"
  fi
  return 0
}

# РџРѕС‡РёРЅРєР° hosts (Рї.6.1): РєР°Р¶РґС‹Р№ РІРєР»СЋС‡С‘РЅРЅС‹Р№ TCP-РёРЅР±Р°СѓРЅРґ, РљР РћРњР• CDN-РїСЂРѕС„РёР»РµР№
# (РёС… РІРµРґС‘С‚ hosts_cdn_upsert С‡РµСЂРµР· cdn_repair), UDP (РїРѕРґРїРёСЃРєР° Р±РµР· hosts) Рё
# tproxy (РµРіРѕ hosts РІРµРґС‘С‚ setup_tproxy_web), РїРѕР»СѓС‡Р°РµС‚ СЃС‚СЂРѕРєСѓ РІ РѕР±С‰РµР№ РіСЂСѓРїРїРµ
# В«РѕРґРёРЅ С…РѕСЃС‚В» СЃ Р°РґСЂРµСЃРѕРј = РґРѕРјРµРЅ РїР°РЅРµР»Рё. РќРµС‚ РґРѕРјРµРЅР° РїР°РЅРµР»Рё вЂ” РїСЂРѕРїСѓСЃРє СЃ warn.
hosts_repair_stack() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  local has_hosts
  has_hosts=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT name FROM sqlite_master WHERE type='table' AND name='hosts';" 2>/dev/null || true)
  [[ -z "$has_hosts" ]] && return 0
  local pd="${PANEL_DOMAIN:-}"
  [[ -z "$pd" ]] && pd=$(xui_get subDomain 2>/dev/null || true)
  if [[ -z "$pd" ]]; then
    warn "  hosts: РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµРёР·РІРµСЃС‚РµРЅ вЂ” hosts-Р·Р°РїРёСЃРё РЅРµ РїСЂРѕРІРµСЂСЏР»"
    return 0
  fi
  cdn_profiles_load || true
  local id proto n=0
  while IFS='|' read -r id proto; do
    [[ -z "$id" || -z "$proto" ]] && continue
    is_udp_proto "$proto" && continue                            # UDP/hysteria
    [[ "$proto" == "tproxy" ]] && continue                       # tg web proxy
    [[ " ${CDN_PROFILE_IDS[*]:-} " == *" $id "* ]] && continue   # CDN вЂ” РѕС‚РґРµР»СЊРЅРѕ
    hosts_upsert "$id" "$pd" || true
    n=$((n+1))
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)
  (( n > 0 )) && log "  hosts: РїСЂРѕРІРµСЂРµРЅРѕ РёРЅР±Р°СѓРЅРґРѕРІ: $n (РѕР±С‰Р°СЏ РіСЂСѓРїРїР° В«РѕРґРёРЅ С…РѕСЃС‚В», CDN РёСЃРєР»СЋС‡С‘РЅ)"
  return 0
}

# Р§РЈР–РћР™ СЂРµР°Р»РёС‚Рё Р·Р° 443 (РґРѕРєС‚СЂРёРЅР° В«РІСЃС‘ Р·Р° 443В»): dest/serverNames = С†РµР»СЊ,
# SNI-СЂРѕСѓС‚РµСЂ РѕС‚РґР°С‘С‚ РёРјСЏ С†РµР»Рё РёРЅР±Р°СѓРЅРґСѓ, СЃР»СѓС€Р°РµРј 127.0.0.1 вЂ” tcp-РїРѕСЂС‚
# РёРЅР±Р°СѓРЅРґР° РЅР°СЂСѓР¶Сѓ РќР• РѕС‚РєСЂС‹РІР°РµРј. РђСЂРіСѓРјРµРЅС‚С‹: <inbound_id> <target> [port]
reality_ext_hide() {
  local id="$1" tdom="$2" port="${3:-}"
  [[ -z "$id" || -z "$tdom" ]] && return 1
  # Р’РђР–РќРћ: x-ui С…СЂР°РЅРёС‚ СЃРѕСЃС‚РѕСЏРЅРёРµ in-memory вЂ” РїСЂР°РІРєРё Р‘Р” С‚РѕР»СЊРєРѕ РїСЂРё РћРЎРўРђРќРћР’Р›Р•РќРќРћР™
  # РїР°РЅРµР»Рё, РёРЅР°С‡Рµ РїСЂРё СЂРµСЃС‚Р°СЂС‚Рµ panel state РїРµСЂРµС‚РёСЂР°РµС‚ dest/serverNames/listen
  local xui_was=""
  if systemctl is-active --quiet x-ui 2>/dev/null; then
    xui_was=1
    systemctl stop x-ui >/dev/null 2>&1 || true
    sleep 1
  fi
  local stream="" new_stream=""
  stream=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  if [[ -n "$stream" ]]; then
    new_stream=$(sed -E "s/\"(dest|target)\": ?\"[^\"]*\"/\"\\1\":\"$tdom:443\"/g; s/\"serverNames\"[[:space:]]*:[[:space:]]*\[[^]]*\]/\"serverNames\":[\"$tdom\"]/" <<<"$stream")
    sqlite3 "$XUI_DB" "UPDATE inbounds SET stream_settings='$new_stream' WHERE id=$id;" 2>/dev/null || true
  fi
  [[ -n "$port" ]] && sni_upstream_add "inb_${id}_backend" "$port"
  sni_map_add "$tdom" "inb_${id}_backend"
  SNI_USED["$tdom"]="inb_${id}_backend"
  # РєРµС€ С†РµР»Рё = С„Р°РєС‚РёС‡РµСЃРєР°СЏ С†РµР»СЊ: Р±СѓРґСѓС‰РёРµ СЃР±РѕСЂРєРё stream РІРѕР·СЊРјСѓС‚ С‚РѕС‚ Р¶Рµ РґРѕРјРµРЅ,
  # С‡С‚Рѕ Рё РІ nginx (РёРЅР°С‡Рµ РєР»РёРµРЅС‚ РїРѕР»СѓС‡РёС‚ РґСЂСѓРіРѕР№ serverNames в†’ С‚Р°Р№РјР°СѓС‚)
  printf '%s' "$tdom" > /tmp/.reality-found-target 2>/dev/null || true
  sqlite3 "$XUI_DB" "UPDATE inbounds SET listen='127.0.0.1' WHERE id=$id;" 2>/dev/null || true
  # РїРѕРґРїРёСЃРєРё: Р°РґСЂРµСЃ = РґРѕРјРµРЅ РїР°РЅРµР»Рё (РІР°Р»РёРґРЅС‹Р№ СЃРµСЂС‚), SNI = serverNames Р¦Р•Р›Р
  # (РёРЅР°С‡Рµ РІ hosts РїСЂРѕРїРёСЃС‹РІР°РµС‚СЃСЏ SNI РїР°РЅРµР»Рё в†’ РїРѕРґРєР»СЋС‡РµРЅРёРµ РЅРµ СЃС‚Р°СЂС‚СѓРµС‚).
  # Р”РѕРјРµРЅ РїР°РЅРµР»Рё: РіР»РѕР±Р°Р» в†’ subDomain РїР°РЅРµР»Рё в†’ РІРѕРїСЂРѕСЃ; IP вЂ” РїРѕСЃР»РµРґРЅРёР№ СЂСѓР±РµР¶.
  local _hp="${PANEL_DOMAIN:-}"
  [[ -z "$_hp" ]] && _hp=$(xui_get subDomain 2>/dev/null || true)
  if [[ -z "$_hp" && -t 0 ]]; then
    ask _hp "Р”РѕРјРµРЅ РїР°РЅРµР»Рё (Р°РґСЂРµСЃ РґР»СЏ hosts-Р·Р°РїРёСЃРё #$id)" "" '^[a-zA-Z0-9.-]+$'
  fi
  [[ -z "$_hp" ]] && _hp=$(curl -4 -s --max-time 6 ifconfig.me 2>/dev/null || true)
  [[ -z "$_hp" ]] && _hp="$tdom"
  hosts_upsert "$id" "$_hp" "$tdom"
  if [[ -n "$xui_was" ]]; then
    systemctl start x-ui >/dev/null 2>&1 || true
    sleep 2
  fi
  nginx_reload || true
  log "#$id: С‡СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё В«$tdomВ» СЃРїСЂСЏС‚Р°РЅ Р·Р° 443 вЂ” SNI в†’ inb_${id}_backend, СЃР»СѓС€Р°РµС‚ 127.0.0.1${port:+:$port} (tcp-РїРѕСЂС‚ РќР• РѕС‚РєСЂС‹С‚)"
  return 0
}

inbound_is_xhttp_tls() {   # <stream_json> в†’ 0, РµСЃР»Рё network=xhttp Рё security=tls
  local s="$1"
  [[ -z "$s" ]] && return 1
  grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"$s" || return 1
  grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$s" || return 1
  return 0
}

# hosts-Р·Р°РїРёСЃСЊ CDN-РїСЂРѕС„РёР»СЏ: Р°РґСЂРµСЃ/SNI/Host header = РґРѕРјРµРЅ CDN, security=tls,
# remark = "CDN_<РїСЂРѕС‚РѕРєРѕР»>" (РїРѕ РѕР±СЂР°Р·С†Сѓ hosts_upsert, РЅРѕ СЃ host_header Рё SNI=CDN)
hosts_cdn_upsert() {   # <inbound_id> <cdn_domain> [proto]
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && return 0
  local id="$1" cdn="$2" proto="${3:-}"
  [[ -z "$id" || -z "$cdn" ]] && return 0
  # Р·Р°С‰РёС‚Р° Р‘Р” РІРµСЂРЅСѓР»Р° Р±С‹ РїСЂРµР¶РЅСЋСЋ СЃС‚СЂРѕРєСѓ hosts РёР· С‚РµРЅРё вЂ” РЅР° РІСЂРµРјСЏ РїРµСЂРµР·Р°РїРёСЃРё off
  db_protect_suspend
  local has_hosts
  has_hosts=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT name FROM sqlite_master WHERE type='table' AND name='hosts';" 2>/dev/null || true)
  [[ -z "$has_hosts" ]] && return 0
  local cols
  cols=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "PRAGMA table_info(hosts);" 2>/dev/null | awk -F'|' '{print $2}' | tr '\n' ' ')
  panel_journal_capture_row hosts "$id"   # СЃРЅРёРјРѕРє СЃС‚СЂРѕРєРё РґР»СЏ РѕС‚РєР°С‚Р° (Рї.2/Рї.3)
  # Р”Р»СЏ РѕРґРЅРѕРіРѕ inbound РґРѕР»Р¶РЅР° СЃСѓС‰РµСЃС‚РІРѕРІР°С‚СЊ СЂРѕРІРЅРѕ РѕРґРЅР° СЃС‚СЂРѕРєР° hosts: CDN
  # Р·Р°РјРµРЅСЏРµС‚ РїСЂРµР¶РЅСЋСЋ РѕР±С‹С‡РЅСѓСЋ/SNI-Р·Р°РїРёСЃСЊ, РёРЅР°С‡Рµ РїР°РЅРµР»СЊ РІС‹РґР°С‘С‚ РґРІРµ СЃСЃС‹Р»РєРё.
  # РЈРґР°Р»СЏРµРј С‚РѕР»СЊРєРѕ СЃС‚СЂРѕРєРё СЌС‚РѕРіРѕ inbound РЅР° 443, С‡СѓР¶РёРµ inbounds РЅРµ С‚СЂРѕРіР°РµРј.
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "DELETE FROM hosts WHERE inbound_id=$id AND port=443;" 2>/dev/null || true
  hosts_owned_delete "$id" 443
  # Р’ СЂР°Р·РЅС‹С… РІРµСЂСЃРёСЏС… РїР°РЅРµР»Рё hosts РёРјРµРµС‚ РѕР±СЏР·Р°С‚РµР»СЊРЅС‹Рµ NOT NULL-РїРѕР»СЏ. РЎРЅР°С‡Р°Р»Р°
  # Р·Р°РїРѕР»РЅСЏРµРј РјРёРЅРёРјР°Р»СЊРЅСѓСЋ СЃРѕРІРјРµСЃС‚РёРјСѓСЋ СЃС‚СЂРѕРєСѓ, Р·Р°С‚РµРј РґРѕР±Р°РІР»СЏРµРј РѕРїС†РёРѕРЅР°Р»СЊРЅС‹Рµ.
  local _remark="CDN"
  [[ -n "$proto" ]] && _remark="CDN_${proto}"
  local fields="inbound_id,address,port" vals="$id,'$cdn',443"
  grep -qw remark      <<<"$cols" && { fields+=",remark";      vals+=",'$_remark'"; }
  grep -qw sni         <<<"$cols" && { fields+=",sni";         vals+=",'$cdn'"; }
  grep -qw host_header <<<"$cols" && { fields+=",host_header"; vals+=",'$cdn'"; }
  # Р’РђР–РќРћ: TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx-С„СЂРѕРЅС‚РµРЅРґ, РІ РёРЅР±Р°СѓРЅРґРµ security=none в†’ 'same'
  # СѓРЅР°СЃР»РµРґРѕРІР°Р» Р±С‹ none Рё РєР»РёРµРЅС‚ РїРѕС€С‘Р» Р±С‹ РіРѕР»С‹Рј HTTP РЅР° 443 (В«HEAD, РЅРµРёР·РІРµСЃС‚РЅР°СЏ
  # РІРµСЂСЃРёСЏВ»). РџРѕСЌС‚РѕРјСѓ Сѓ CDN-С…РѕСЃС‚Р° security=tls РЇР’РќРћ, РІ РѕС‚Р»РёС‡РёРµ РѕС‚ README
  # (С‚Р°Рј TLS РЅР° Xray Рё 'same' РЅР°СЃР»РµРґСѓРµС‚ tls).
  grep -qw security    <<<"$cols" && { fields+=",security";    vals+=",'tls'"; }
  grep -qw fingerprint <<<"$cols" && { fields+=",fingerprint"; vals+=",'firefox'"; }
  grep -qw is_disabled <<<"$cols" && { fields+=",is_disabled"; vals+=",0"; }
  grep -qw enable      <<<"$cols" && { fields+=",enable";      vals+=",1"; }
  if sqlite3 -cmd ".timeout 3000" "$XUI_DB" "INSERT INTO hosts ($fields) VALUES ($vals);" 2>/dev/null; then
    sqlite3 -cmd ".timeout 3000" "$XUI_DB" "INSERT OR REPLACE INTO sm_hosts_owned(inbound_id,port,address,sni) VALUES($id,443,'$(printf '%s' "$cdn" | sed "s/'/''/g")','$(printf '%s' "$cdn" | sed "s/'/''/g")');" 2>/dev/null || true
    log "  hosts: #$id в†’ $cdn:443 (Р°РґСЂРµСЃ/SNI/Host header = CDN, security=tls, remark=$_remark) вњ“"
  else
    warn "  hosts: CDN-РІСЃС‚Р°РІРєР° РґР»СЏ #$id РЅРµ РїСЂРѕС€Р»Р° вЂ” РїСЂРѕРІРµСЂСЊ СЃС…РµРјСѓ С‚Р°Р±Р»РёС†С‹ hosts"
  fi
  return 0
}

# =====================================================================
# CDN-Р Р•Р–РРњ XHTTP: РѕР±С‰Р°СЏ РјРµС…Р°РЅРёРєР° (РїСЂРѕС„РёР»Рё, nginx-С„СЂРѕРЅС‚РµРЅРґ, РјР°СЂС€СЂСѓС‚РёР·Р°С†РёСЏ)
# =====================================================================
# РљР°РЅРґРёРґР°С‚ РЅР° CDN: Р›Р®Р‘РћР™ РїСЂРѕС‚РѕРєРѕР» СЃ С‚СЂР°РЅСЃРїРѕСЂС‚РѕРј xhttp, Сѓ РєРѕС‚РѕСЂРѕРіРѕ
# security РЅРµС‚/none (РёРґРµР°Р»СЊРЅС‹Р№ РІС…РѕРґ) РёР»Рё tls (СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№, Р±СѓРґРµС‚ РїРµСЂРµРІРµРґС‘РЅ).
inbound_was_created_as_tls_xhttp() {   # <inbound_id>
  local id="$1" listed=" ${XHTTP_TLS_CREATED_IDS:-} "
  [[ " $listed " == *" $id "* ]]
}

# TLS/Reality XHTTP РЅРёРєРѕРіРґР° РЅРµ РїСЂРµРґР»Р°РіР°РµС‚ CDN. РџСЂРѕРІРµСЂСЏРµРј СЃРѕС…СЂР°РЅС‘РЅРЅСѓСЋ Р·Р°РїРёСЃСЊ,
# Р° РЅРµ С‚РѕР»СЊРєРѕ РІСЂРµРјРµРЅРЅС‹Р№ СЃРїРёСЃРѕРє ID, РєРѕС‚РѕСЂС‹Р№ С‚РµСЂСЏРµС‚СЃСЏ РїСЂРё РїРѕРІС‚РѕСЂРЅРѕРј Р·Р°РїСѓСЃРєРµ РјРµРЅСЋ.
inbound_xhttp_has_tls_or_reality() {   # <stream_json>
  local s="$1"
  grep -Eqi '"security"[[:space:]]*:[[:space:]]*"(tls|reality)"' <<<"$s"
}

inbound_is_xhttp_cdn_candidate() {   # <stream_json>
  local s="$1"
  [[ -z "$s" ]] && return 1
  grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"$s" || return 1
  if   grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$s"; then return 0; fi
  if   grep -Eqi '"security"[[:space:]]*:[[:space:]]*"none"' <<<"$s"; then return 0; fi
  grep -Eqi '"security"' <<<"$s" || return 0   # РєР»СЋС‡Р° РЅРµС‚ РІРѕРѕР±С‰Рµ = security none
  return 1
}

# В«exempleВ» РёР· origin-РґРѕРјРµРЅР°: ts.exemple.ru в†’ exemple; exemple.ru в†’ exemple
cdn_base_from_origin() {
  local o="${1%%.*}" rest="${1#*.}"
  if [[ "$rest" == *.* ]]; then
    printf '%s' "${rest%%.*}"          # в‰Ґ3 РјРµС‚РѕРє: Р±Р°Р·Р° = РІС‚РѕСЂР°СЏ РјРµС‚РєР°
  else
    printf '%s' "$o"                   # 2 РјРµС‚РєРё: Р±Р°Р·Р° = РїРµСЂРІР°СЏ
  fi
}
cdn_default_path() { printf '/api/stream/%s.m3u8' "$(cdn_base_from_origin "$1")"; }

# РџСЂРѕС„РёР»Рё CDN: id|proto|origin|cdn|path|tpl|decoy_port
cdn_profiles_load() {
  CDN_PROFILE_IDS=()
  [[ -s "$CDN_PROFILES" ]] || return 0
  local l id
  local -a _stale=()
  while IFS= read -r l; do
    id="${l%%|*}"
    [[ "$id" =~ ^[0-9]+$ ]] || continue
    if [[ -f "$XUI_DB" ]] && [[ "$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE id=$id;" 2>/dev/null || echo 0)" == "0" ]]; then
      _stale+=("$id")
    else
      CDN_PROFILE_IDS+=("$id")
    fi
  done < "$CDN_PROFILES"
  # РЈРґР°Р»СЏРµРј РѕСЃРёСЂРѕС‚РµРІС€РёРµ РїСЂРѕС„РёР»Рё РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ РёРЅР±Р°СѓРЅРґР°, С‡С‚РѕР±С‹ СЃС‚Р°СЂС‹Р№ ID
  # РЅРµ РїРѕСЏРІР»СЏР»СЃСЏ РІ РјРµРЅСЋ decoy Рё РЅРµ РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°Р»СЃСЏ Р°РІС‚РѕРїРѕС‡РёРЅРєРѕР№.
  local _sid _srow _sorigin _sdport _tmp
  for _sid in "${_stale[@]}"; do
    _srow=$(grep -m1 -E "^${_sid}\\|" "$CDN_PROFILES" 2>/dev/null || true)
    _sorigin=$(printf '%s' "$_srow" | cut -d'|' -f3)
    _sdport=$(printf '%s' "$_srow" | cut -d'|' -f7)
    [[ -n "$_sorigin" ]] && stack_cdn_del "$_sorigin" 2>/dev/null || true
    [[ "$_sdport" =~ ^[0-9]+$ && "$_sdport" != "0" ]] && stack_del_decoy "$_sorigin" 2>/dev/null || true
    sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE inbound_id=$_sid;" 2>/dev/null || true
    _tmp=$(mktemp)
    grep -vE "^${_sid}\\|" "$CDN_PROFILES" > "$_tmp" 2>/dev/null || true
    mv -f "$_tmp" "$CDN_PROFILES"
    warn "РЈРґР°Р»С‘РЅ РѕСЃРёСЂРѕС‚РµРІС€РёР№ CDN-РїСЂРѕС„РёР»СЊ #$_sid: РёРЅР±Р°СѓРЅРґ РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚"
  done
}
cdn_profile_get() {   # <id> в†’ РїРµС‡Р°С‚Р°РµС‚ СЃС‚СЂРѕРєСѓ РїСЂРѕС„РёР»СЏ (РїСѓСЃС‚Рѕ вЂ” РЅРµС‚)
  [[ -s "$CDN_PROFILES" ]] || return 1
  grep -m1 -E "^${1}\|" "$CDN_PROFILES" 2>/dev/null
}
cdn_profile_field() {   # <id> <РЅРѕРјРµСЂ РїРѕР»СЏ 1..8> в†’ Р·РЅР°С‡РµРЅРёРµ
  local row; row=$(cdn_profile_get "$1") || return 1
  printf '%s' "$row" | cut -d'|' -f"$2"
}
cdn_profile_provider() {   # <id> в†’ beget|yandex|other|"" (СЃС‚Р°СЂС‹Рµ РїСЂРѕС„РёР»Рё Р±РµР· РїРѕР»СЏ)
  local row; row=$(cdn_profile_get "$1") || return 1
  printf '%s' "$row" | cut -d'|' -f8
}
cdn_provider_label() {   # <РєРѕРґ> в†’ С‡РµР»РѕРІРµРєРѕС‡РёС‚Р°РµРјРѕРµ РёРјСЏ РїСЂРѕРІР°Р№РґРµСЂР°
  case "$1" in
    beget)  printf 'Beget' ;;
    yandex) printf 'Yandex Cloud' ;;
    other)  printf 'РЎРІРѕР№ CDN' ;;
    *)      printf 'РЅРµ СѓРєР°Р·Р°РЅ' ;;
  esac
}
cdn_profile_save_add() {   # <id> <proto> <origin> <cdn> <path> <tpl> <decoy_port> [provider]
  cdn_profile_remove "$1"
  mkdir -p "$(dirname "$CDN_PROFILES")" 2>/dev/null || true
  printf '%s|%s|%s|%s|%s|%s|%s|%s\n' "$1" "$2" "$3" "$4" "$5" "$6" "$7" "${8:-}" >> "$CDN_PROFILES"
}
cdn_profile_remove() {   # <id>
  [[ -s "$CDN_PROFILES" ]] || return 0
  local tmp; tmp=$(mktemp)
  grep -vE "^${1}\|" "$CDN_PROFILES" > "$tmp" 2>/dev/null || true
  mv -f "$tmp" "$CDN_PROFILES"
}

# Р”РѕРјРµРЅС‹ CDN-С„СЂРѕРЅС‚РѕРІ (РїРѕР»Рµ 4 РїСЂРѕС„РёР»РµР№: С‚Рѕ, С‡С‚Рѕ РїСЂРёРІСЏР·Р°РЅРѕ Рє РІРЅРµС€РЅРµРјСѓ CDN).
# Р­С‚Рѕ РќР• РЅР°С€Рё РґРѕРјРµРЅС‹: СЃРµСЂС‚ РЅР° РЅРёС… РЅРµ РІС‹РїСѓСЃРєР°РµС‚СЃСЏ (TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ CDN) Рё РІ SAN
# РѕРЅРё РЅРµ РІРєР»СЋС‡Р°СЋС‚СЃСЏ. ORIGIN (РїРѕР»Рµ 3) вЂ” РЅР°С€ РґРѕРјРµРЅ, РѕРЅ РІ SAN РёРґС‘С‚ РєР°Рє РѕР±С‹С‡РЅРѕ.
cdn_front_domains() {   # РґРѕРјРµРЅС‹-С„СЂРѕРЅС‚С‹ РёР· $CDN_PROFILES (4-Рµ РїРѕР»Рµ)
  local f="$CDN_PROFILES" row
  [[ -s "$f" ]] || return 0
  while IFS= read -r row; do
    [[ -n "$row" ]] || continue
    row="${row//$'\r'/}"
    printf '%s\n' "$(printf '%s' "$row" | cut -d'|' -f4)"
  done < "$f"
}

# РЇРІР»СЏРµС‚СЃСЏ Р»Рё РґРѕРјРµРЅ CDN-С„СЂРѕРЅС‚РѕРј (РёСЃРєР»СЋС‡Р°РµС‚СЃСЏ РёР· SAN)
cdn_front_domain_is() {   # <domain>
  local d="${1:-}" x
  [[ -n "$d" ]] || return 1
  while IFS= read -r x; do
    [[ -n "$x" && "$x" == "$d" ]] && return 0
  done < <(cdn_front_domains)
  return 1
}

# РЈРґР°Р»РёС‚СЊ cdn-Р±Р»РѕРє РїРѕ РґРѕРјРµРЅСѓ (РјР°СЂРєРµСЂС‹ # >>> cdn ... domain=X)
stack_cdn_del() {
  local dom="$1"
  [[ -f "$STACK_CONF" ]] || return 0
  local tmp
  tmp=$(mktemp)
  awk -v dom="$dom" '
    !skip && index($0, "# >>> cdn ") == 1 {
      tail = $0
      sub(/^.* domain=/, "", tail)
      if (tail == dom) { skip = 1; next }
    }
    skip && index($0, "# <<< cdn ") == 1 { skip = 0; next }
    !skip { print }
  ' "$STACK_CONF" > "$tmp" 2>/dev/null && mv "$tmp" "$STACK_CONF"
}

# Upsert cdn-Р±Р»РѕРєР°: TLS-С„СЂРѕРЅС‚РµРЅРґ РЅР° loopback, Р·Р°РїСЂРѕСЃС‹ СЃС‚СЂРѕРіРѕ РЅР° С‚СЂР°РЅСЃРїРѕСЂС‚РЅС‹Р№
# РїСѓС‚СЊ СѓС…РѕРґСЏС‚ РІ xray (РіРѕР»С‹Р№ xhttp), РІСЃС‘ РѕСЃС‚Р°Р»СЊРЅРѕРµ вЂ” РІ decoy ORIGIN-РґРѕРјРµРЅР°.
stack_cdn_upsert() {   # <origin> <cdn> <path> <inb_port> <decoy_port> <cert> <key>
  local origin="$1" cdn="$2" path="$3" inb_port="$4" decoy_port="$5" cert="$6" key="$7"
  # РџР°РЅРµР»СЊ/РїРѕРґРїРёСЃРєРё РЅР° С‚РѕРј Р¶Рµ РґРѕРјРµРЅРµ, С‡С‚Рѕ Рё CDN-origin: SNI-РєР°СЂС‚Р° РІРµРґС‘С‚ РґРѕРјРµРЅ
  # РїР°РЅРµР»Рё РЅР° cdn_frontend (СЌС‚РѕС‚ Р±Р»РѕРє), РїРѕСЌС‚РѕРјСѓ path-Р»РѕРєР°С†РёРё РїР°РЅРµР»Рё РћР‘РЇР—РђРќР«
  # Р¶РёС‚СЊ Р·РґРµСЃСЊ. Р•СЃР»Рё РёС… РѕСЃС‚Р°РІРёС‚СЊ С‚РѕР»СЊРєРѕ РІ panel-Р±Р»РѕРєРµ 4443, РїР°РЅРµР»СЊ СЃС‚Р°РЅРµС‚
  # РЅРµРґРѕСЃС‚РёР¶РёРјРѕР№ РїРѕ РёРјРµРЅРё вЂ” location / РѕС‚РґР°СЃС‚ decoy-Р·Р°РіР»СѓС€РєСѓ (Р±Р°Рі 28.10:
  # В«https://example.com/vladufqa/ РѕС‚РєСЂС‹Р»Р°СЃСЊ Р·Р°РіР»СѓС€РєР°В»).
  local _panel_locs=""
  if [[ -n "${PANEL_DOMAIN:-}" && "$origin" == "$PANEL_DOMAIN" && -n "${PANEL_PORT:-}" && -n "${PANEL_PATH:-}" ]]; then
    _panel_locs=$(cat <<PLOCEOF
    # --- РїР°РЅРµР»СЊ/РїРѕРґРїРёСЃРєРё: РїСѓС‚СЊ РїР°РЅРµР»Рё РЅР° CDN-origin (СЃРј. РєРѕРјРјРµРЅС‚Р°СЂРёР№ РІС‹С€Рµ) ---
    location ${PANEL_PATH} {
        proxy_pass https://127.0.0.1:${PANEL_PORT};
        proxy_ssl_verify off;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }
PLOCEOF
)
    if [[ -n "${SUB_PORT:-}" && -n "${SUB_PATH:-}" ]]; then
      _panel_locs+=$(cat <<SLOCEOF
    location ${SUB_PATH} {
        proxy_pass https://127.0.0.1:${SUB_PORT};
        proxy_ssl_verify off;
        proxy_ssl_server_name on;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }
SLOCEOF
)
    fi
  fi
  # РїСЂРµС„РёРєСЃ РґР»СЏ СЃРµСЃСЃРёРѕРЅРЅС‹С… Р·Р°РїСЂРѕСЃРѕРІ: xhttp РїСЂРё sessionIDPlacement=path РїСЂРѕСЃРёС‚
  # $path/<sessionID>?... вЂ” Р»РѕРІРёРј РїСЂРµС„РёРєСЃРѕРј, В«$path/В» Р±РµР· РґРѕР±Р°РІР»РµРЅРёСЏ, РµСЃР»Рё РїСѓС‚СЊ
  # СЃР°Рј Р·Р°РєР°РЅС‡РёРІР°РµС‚СЃСЏ РЅР° /
  local loc_prefix="$path/"
  [[ "$path" == */ ]] && loc_prefix="$path"
  stack_ensure
  stack_cdn_del "$origin"
  {
    echo "# >>> cdn origin=$origin cdn=$cdn path=$path inb=$inb_port decoy=$decoy_port domain=$origin"
    cat <<EOF
server {
    listen 127.0.0.1:$CDN_FE_PORT ssl;
    server_name $origin $cdn;
    ssl_certificate     $cert;
    ssl_certificate_key $key;
    include /etc/nginx/snippets/decoy-headers.conf;
    access_log $DECOY_LOG_ACCESS decoy_ext;
    error_log  /var/log/nginx/decoy-error.log;
    location = $path {
        # HEAD/GET Р±РµР· СЃРµСЃСЃРёРѕРЅРЅС‹С… РїСЂРёР·РЅР°РєРѕРІ вЂ” В«РїСЂРѕРІРµСЂРєР° РґРѕСЃС‚СѓРїРЅРѕСЃС‚РёВ» РєР»РёРµРЅС‚Р°:
        # РѕС‚РІРµС‡Р°РµРј 200 СЃР°РјРё (xray РЅР° РїСѓСЃС‚РѕР№ Р·Р°РїСЂРѕСЃ РґР°С‘С‚ 404, Рё РєР»РёРµРЅС‚
        # РїРѕРјРµС‡Р°РµС‚ РїСЂРѕС„РёР»СЊ В«HEAD error / РЅРµРёР·РІРµСЃС‚РЅР°СЏ РІРµСЂСЃРёСЏВ»)
        if (\$request_method = HEAD) { add_header Content-Type application/vnd.apple.mpegurl always; return 200 ""; }
        proxy_pass http://127.0.0.1:$inb_port;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 300s;
        proxy_send_timeout 300s;
    }
    # РЎР•РЎРЎРР xhttp: СЂРµР°Р»СЊРЅС‹Рµ Р·Р°РїСЂРѕСЃС‹ РёРґСѓС‚ РЅР° $path/<sessionID> (sessionIDPlacement=path).
    # РўРѕС‡РЅРѕРµ СЃРѕРІРїР°РґРµРЅРёРµ location= РёС… РЅРµ Р»РѕРІРёС‚ вЂ” Р±РµР· СЌС‚РѕРіРѕ Р±Р»РѕРєР° СЃРµСЃСЃРёРё РїР°РґР°Р»Рё
    # РІ decoy, РєР»РёРµРЅС‚ РїРѕР»СѓС‡Р°Р» HTML Рё СЂСѓРіР°Р»СЃСЏ В«unknown version: 60В» ('<'=60).
    location ^~ $loc_prefix {
        proxy_pass http://127.0.0.1:$inb_port;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 300s;
        proxy_send_timeout 300s;
    }
$_panel_locs
    location / {
        proxy_pass https://127.0.0.1:$decoy_port;
        proxy_ssl_verify off;
        proxy_set_header Host \$host;
    }
}
EOF
    echo "# <<< cdn domain=$origin"
  } >> "$STACK_CONF"
}

# Stream-СЂРѕСѓС‚РµСЂ: SNI origin Рё cdn в†’ РµРґРёРЅС‹Р№ Р»РѕРєР°Р»СЊРЅС‹Р№ cdn_frontend.
# Reality/TLS-РјР°СЂС€СЂСѓС‚С‹ РЅРµ С‚СЂРѕРіР°СЋС‚СЃСЏ; Р»РѕРіРёРєР° РѕР±СЂР°С‚РёРјРѕ РёРґРµРјРїРѕС‚РµРЅС‚РЅР°.
cdn_frontend_ensure() {
  sni_upstream_add "cdn_frontend" "$CDN_FE_PORT"
  local origin="$1" cdn="$2"
  sni_map_add "$origin" "cdn_frontend"
  [[ -n "$cdn" ]] && sni_map_add "$cdn" "cdn_frontend"
}

# РђСѓРґРёС‚ СЃРѕРіР»Р°СЃРѕРІР°РЅРЅРѕСЃС‚Рё CDN Р±РµР· РёСЃРїСЂР°РІР»РµРЅРёР№: Р±Р°Р·Р°, hosts, РїСЂРѕС„РёР»СЊ, nginx,
# decoy Рё СЃРµСЂС‚РёС„РёРєР°С‚. Р­С‚Рѕ read-only РїСЂРѕРІРµСЂРєР° РІ СЃС‚РёР»Рµ desired/runtime state.
cdn_audit_report() {
  line; echo -e "${B}   РђРЈР”РРў CDN Р DRIFT${N}"; line
  [[ -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  cdn_profiles_load
  if (( ! ${#CDN_PROFILE_IDS[@]} )); then
    log "CDN-РїСЂРѕС„РёР»РµР№ РЅРµС‚ вЂ” РїСЂРѕРІРµСЂСЏС‚СЊ РЅРµС‡РµРіРѕ"; return 0
  fi
  local id proto origin cdn path tpl dport port st host ipath haddr hsni hhost hsec blk cert key issues=0
  for id in "${CDN_PROFILE_IDS[@]}"; do
    proto=$(cdn_profile_field "$id" 2); origin=$(cdn_profile_field "$id" 3)
    cdn=$(cdn_profile_field "$id" 4); path=$(cdn_profile_field "$id" 5)
    tpl=$(cdn_profile_field "$id" 6); dport=$(cdn_profile_field "$id" 7)
    echo; echo "CDN #$id ($proto, РїСЂРѕРІР°Р№РґРµСЂ: $(cdn_provider_label "$(cdn_profile_field "$id" 8)")): origin=$origin cdn=$cdn path=$path"
    if ! sqlite3 "$XUI_DB" "SELECT 1 FROM inbounds WHERE id=$id AND enable=1;" 2>/dev/null | grep -q 1; then
      err "  DRIFT: inbound РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚ РёР»Рё РІС‹РєР»СЋС‡РµРЅ"; issues=$((issues+1)); continue
    fi
    read -r host ipath port st <<<"$(sqlite3 -separator ' ' "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.xhttpSettings.host'),''),COALESCE(json_extract(stream_settings,'\$.xhttpSettings.path'),''),port,COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)"
    [[ "$host" == "$origin" ]] && log "  DB host: OK" || { err "  DRIFT: DB host=$host (РѕР¶РёРґР°Р»СЃСЏ $origin)"; issues=$((issues+1)); }
    [[ "$ipath" == "$path" ]] && log "  DB path: OK" || { err "  DRIFT: DB path=$ipath (РѕР¶РёРґР°Р»СЃСЏ $path)"; issues=$((issues+1)); }
    IFS='|' read -r haddr hsni hhost hsec <<<"$(sqlite3 -separator '|' "$XUI_DB" "SELECT COALESCE(address,''),COALESCE(sni,''),COALESCE(host_header,''),COALESCE(security,'') FROM hosts WHERE inbound_id=$id AND port=443 LIMIT 1;" 2>/dev/null || true)"
    [[ "$haddr" == "$cdn" && "$hsni" == "$cdn" && "$hhost" == "$cdn" && "$hsec" == "tls" ]] && log "  hosts: OK" || { err "  DRIFT: hosts address/sni/host/security = $haddr/$hsni/$hhost/$hsec"; issues=$((issues+1)); }
    blk=$(sed -n "/# >>> cdn .*domain=${origin//./\.}/,/# <<< cdn/p" "$STACK_CONF" 2>/dev/null || true)
    [[ -n "$blk" && "$blk" == *"location ^~"* ]] && log "  nginx block: OK" || { err "  DRIFT: nginx CDN-Р±Р»РѕРє РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚ РёР»Рё РЅРµРїРѕР»РѕРЅ"; issues=$((issues+1)); }
    stack_decoy_meta "$origin" >/dev/null 2>&1 && log "  decoy $origin: OK" || { err "  DRIFT: decoy $origin РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚"; issues=$((issues+1)); }
    cert_preflight "$origin" >/dev/null 2>&1 && log "  certificate $origin: OK (domain/expiry/key)" || { err "  DRIFT: СЃРµСЂС‚РёС„РёРєР°С‚ $origin РЅРµ РїСЂРѕС€С‘Р» РїСЂРѕРІРµСЂРєСѓ РґРѕРјРµРЅР°/СЃСЂРѕРєР°/РєР»СЋС‡Р°"; issues=$((issues+1)); }
  done
  echo; if (( issues )); then err "РђСѓРґРёС‚ Р·Р°РІРµСЂС€С‘РЅ: РїСЂРѕР±Р»РµРј $issues"; return 1; fi
  log "РђСѓРґРёС‚ Р·Р°РІРµСЂС€С‘РЅ: CDN-РїСЂРѕС„РёР»Рё СЃРѕРіР»Р°СЃРѕРІР°РЅС‹"
}

# РџРѕР»РЅС‹Р№ read-only Р°СѓРґРёС‚ СЃС‚РµРєР°: inbound/hosts/SNI/CDN/decoy/certs/services/UFW.
stack_full_audit() {
  line; echo -e "${B}   РџРћР›РќР«Р™ РђРЈР”РРў РЎРўР•РљРђ (READ-ONLY)${N}"; line
  local issues=0 id proto port listen en st dom backend cert key exp svc _ss d _crt _left certn dbbad
  [[ -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  echo "[ Inbounds / hosts ]"
  while IFS='|' read -r id proto port listen en st; do
    [[ -n "$id" ]] || continue
    if [[ "$en" != 1 ]]; then warn "#${id} $proto:$port вЂ” disabled"; continue; fi
    [[ "$port" =~ ^[0-9]+$ && "$port" != 0 ]] || { err "#${id}: РЅРµРєРѕСЂСЂРµРєС‚РЅС‹Р№ РїРѕСЂС‚ $port"; issues=$((issues+1)); continue; }
    # РџСѓР±Р»РёС‡РЅС‹Рµ UDP-С‚СѓРЅРЅРµР»Рё (Hysteria, qwdtt/csqtt, Awg/WireGuard) РґРѕР»Р¶РЅС‹
    # РїСЂРёРЅРёРјР°С‚СЊ С‚СЂР°С„РёРє РЅРµ С‚РѕР»СЊРєРѕ СЃ loopback. Р”Р»СЏ РЅРёС… РІРЅРµС€РЅРёР№ listen вЂ” РЅРѕСЂРјР°.
    case "$proto" in
      hysteria|hysteria2|qwdtt|csqtt|awg|wireguard|amnezia|amneziawg) ;;
      # tproxy: caddy tg web proxy СЃР»СѓС€Р°РµС‚ *:11443 РџРћ Р”РР—РђР™РќРЈ; СЃРЅР°СЂСѓР¶Рё РїРѕСЂС‚
      # Р·Р°РєСЂС‹С‚ UFW (РґРѕРєС‚СЂРёРЅР° В«РІСЃС‘ Р·Р° 443В»), РІРЅСѓС‚СЂСЊ С…РѕРґРёС‚ nginx РїРѕ loopback вЂ”
      # РЅРµ Р·Р°РјРµС‡Р°РЅРёРµ (РёСЃС‚РѕСЂРёСЏ 28.10: С„Р°Р»СЊС€РёРІС‹Рµ В«СЃР»СѓС€Р°РµС‚ РЅРµ loopbackВ»).
      tproxy) ;;
      *)
        if [[ "$port" != 443 && "$listen" != 127.0.0.1 ]]; then
          warn "#${id} $proto:$port вЂ” СЃР»СѓС€Р°РµС‚ РЅРµ loopback"; issues=$((issues+1))
        fi
        ;;
    esac
    if grep -Eqi '"security"[[:space:]]*:[[:space:]]*"(tls|reality)"' <<<"$st"; then
      cert=$(grep -oE '"certificateFile"[[:space:]]*:[[:space:]]*"[^"]+"' <<<"$st" | head -1 | sed -E 's/.*"([^"]+)"/\1/')
      key=$(grep -oE '"keyFile"[[:space:]]*:[[:space:]]*"[^"]+"' <<<"$st" | head -1 | sed -E 's/.*"([^"]+)"/\1/')
      if [[ "$st" == *'"security":"tls"'* && ( -z "$cert" || ! -f "$cert" || -z "$key" || ! -f "$key" ) ]]; then
        warn "#${id}: TLS-СЃРµСЂС‚РёС„РёРєР°С‚/РєР»СЋС‡ РЅРµ РЅР°Р№РґРµРЅ"; issues=$((issues+1))
      fi
      if [[ "$st" == *'"security":"tls"'* ]]; then
        dom=$(grep -oE '"serverName"[[:space:]]*:[[:space:]]*"[^"]+"' <<<"$st" | head -1 | sed -E 's/.*"([^"]+)"/\1/')
        if [[ -n "$dom" ]] && ! cert_preflight "$dom" >/dev/null 2>&1; then
          warn "#${id}: СЃРµСЂС‚РёС„РёРєР°С‚ РЅРµ РїСЂРѕС€С‘Р» РїСЂРѕРІРµСЂРєСѓ РґРѕРјРµРЅР°/СЃСЂРѕРєР°/РєР»СЋС‡Р° ($dom)"; issues=$((issues+1))
        fi
      fi
    fi
    # hosts-СЃС‚СЂРѕРєРё РІ РїР°РЅРµР»Рё вЂ” РіРµРЅРµСЂР°С‚РѕСЂ СЃСЃС‹Р»РѕРє РїРѕРґРїРёСЃРѕРє, РќР• РјР°СЂС€СЂСѓС‚РёР·Р°С†РёСЏ
    # (РѕРЅР° Р¶РёРІС‘С‚ РІ sni-router.conf + stream_settings). РњРѕРґРµР»СЊ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ:
    # РјРёРЅРёРјСѓРј hosts (РѕРґРЅР° СЃС‚СЂРѕРєР°) вЂ” РѕС‚СЃСѓС‚СЃС‚РІРёРµ СЃС‚СЂРѕРєРё РёРЅР±Р°СѓРЅРґР° РЅРµ РїСЂРѕР±Р»РµРјР°.
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port,COALESCE(listen,''),enable,COALESCE(stream_settings,'') FROM inbounds ORDER BY id;" 2>/dev/null || true)
  echo "[ SNI / nginx ]"
  if command -v nginx >/dev/null 2>&1; then nginx -t >/dev/null 2>&1 && log "nginx -t: OK" || { err "nginx -t: FAIL"; issues=$((issues+1)); }; fi
  [[ -f "$SNI_CONF" ]] && log "SNI-РєРѕРЅС„РёРі: РЅР°Р№РґРµРЅ" || { warn "SNI-РєРѕРЅС„РёРі РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚"; issues=$((issues+1)); }
  echo "[ Services ]"
  for svc in nginx x-ui; do
    systemctl is-active --quiet "$svc" 2>/dev/null && log "$svc: active" || warn "$svc: РЅРµ active"
  done
  echo "[ Listening ports ]"
  while IFS='|' read -r id proto port listen en; do
    [[ "$en" == 1 && "$port" =~ ^[0-9]+$ && "$port" != 0 ]] || continue
    # ss -t РІРёРґРёС‚ С‚РѕР»СЊРєРѕ TCP: РґР»СЏ UDP-РїСЂРѕС‚РѕРєРѕР»РѕРІ СЃР»СѓС€Р°С‚РµР»СЏ РёС‰РµРј С‡РµСЂРµР· -u,
    # РёРЅР°С‡Рµ Р·РґРѕСЂРѕРІС‹Р№ UDP-РёРЅР±Р°СѓРЅРґ РїРѕРјРµС‡Р°РµС‚СЃСЏ В«РЅРµ СЃР»СѓС€Р°РµС‚В».
    _ss="-ltnup"; is_udp_proto "$proto" && _ss="-lnup"
    # Р”Рѕ 8 РїРѕРїС‹С‚РѕРє СЃ РїР°СѓР·РѕР№ 2 СЃ (РјР°РєСЃ. 16 СЃ) вЂ” РўРћР›Р¬РљРћ РґР»СЏ РїСЂРѕРІР°Р»РёРІС€РёС…СЃСЏ
    # РїРѕСЂС‚РѕРІ: Р·РґРѕСЂРѕРІС‹Р№ СЃР»СѓС€Р°С‚РµР»СЊ РЅР°С…РѕРґРёС‚СЃСЏ СЃ РїРµСЂРІРѕР№ РїРѕРїС‹С‚РєРё, РїСЂРѕРіРѕРЅС‹
    # РЅРµ Р·Р°РјРµРґР»СЏСЋС‚СЃСЏ. РџРѕСЃР»Рµ СЂРµСЃС‚Р°СЂС‚Р° x-ui LucX РІ СЃС‚Р°СЂС‚РѕРІРѕРј РѕРєРЅРµ РїРµСЂРµСЃРѕР·РґР°С‘С‚
    # С…РµРЅРґР»РµСЂС‹ РёРЅР±Р°СѓРЅРґРѕРІ: caddy-sidecar tproxy (11443) Рё TLS-РёРЅР±Р°СѓРЅРґС‹
    # РїСЂРёРІСЏР·С‹РІР°СЋС‚СЃСЏ РґРѕР»СЊС€Рµ 6 СЃ (РёСЃС‚РѕСЂРёСЏ 28.10: 3Г—2 СЃ Р»РѕРІРёР»Рё В«СЃРѕРєРµС‚ РЅРµ
    # СЃР»СѓС€Р°РµС‚В» РЅР° Р¶РёРІС‹С… РїРѕСЂС‚Р°С… 37039/11443; С„Р°РєС‚РёС‡РµСЃРєРё РѕР±Р° СЃР»СѓС€Р°Р»Рё).
    local _tries=0 _up=false
    while (( _tries < 8 )); do
      if ss "$_ss" 2>/dev/null | grep -Eq ":${port}[[:space:]]"; then _up=true; break; fi
      _tries=$((_tries+1))
      (( _tries == 1 )) && echo "  вЂ¦ #$id $proto:$port РїРѕРєР° РЅРµ РѕС‚РІРµС‡Р°РµС‚, РїРµСЂРµРїСЂРѕРІРµСЂСЏСЋ (РґРѕ 16 СЃ)вЂ¦"
      (( _tries < 8 )) && sleep 2
    done
    if [[ "$_up" != true ]]; then
      warn "#${id} $proto:$port вЂ” СЃРѕРєРµС‚ РЅРµ СЃР»СѓС€Р°РµС‚"; issues=$((issues+1))
    elif (( _tries > 0 )); then
      log "#${id} $proto:$port вЂ” socket OK (РїРѕРґРЅСЏР»СЃСЏ РїСЂРё РїРµСЂРµРїСЂРѕРІРµСЂРєРµ)"
    else
      log "#${id} $proto:$port вЂ” socket OK"
    fi
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port,COALESCE(listen,''),enable FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)
  echo "[ CDN ]"
  cdn_audit_report || issues=$((issues+1))
  echo "[ CDN profile orphans ]"
  if [[ -s "$CDN_PROFILES" ]]; then
    while IFS='|' read -r id proto origin cdn path tpl dport; do
      [[ "$id" =~ ^[0-9]+$ ]] || continue
      if ! sqlite3 "$XUI_DB" "SELECT 1 FROM inbounds WHERE id=$id;" 2>/dev/null | grep -q 1; then
        warn "orphan CDN profile #$id ($origin в†’ $cdn)"; issues=$((issues+1))
      fi
    done < "$CDN_PROFILES"
  fi
  echo "[ AmneziaWG ]"
  awg_audit
  (( ${AWG_AUDIT_ISSUES:-0} > 0 )) && issues=$((issues+AWG_AUDIT_ISSUES))
  echo "[ Certificates ]"
  if [[ -d /etc/letsencrypt/live ]]; then
    certn=0
    for d in /etc/letsencrypt/live/*; do
      [[ -d "$d" ]] || continue; certn=$((certn+1)); _crt="$d/fullchain.pem"
      [[ -f "$_crt" ]] || { err "$(basename "$d"): fullchain РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚"; issues=$((issues+1)); continue; }
      _left=$((($(date -d "$(openssl x509 -enddate -noout -in "$_crt" 2>/dev/null | cut -d= -f2)" +%s 2>/dev/null || echo 0)-$(date +%s))/86400))
      if (( _left < 0 )); then
        err "$(basename "$d"): СЃРµСЂС‚РёС„РёРєР°С‚ РїСЂРѕСЃСЂРѕС‡РµРЅ"; issues=$((issues+1))
      elif (( _left < 14 )); then
        warn "$(basename "$d"): РёСЃС‚РµРєР°РµС‚ С‡РµСЂРµР· $_left РґРЅ"
      else
        log "$(basename "$d"): $_left РґРЅ"
      fi
    done
    (( certn == 0 )) && warn "РЎРµСЂС‚РёС„РёРєР°С‚РѕРІ РЅРµС‚"
  else
    warn "/etc/letsencrypt/live РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚"
  fi
  echo "[ DB JSON ]"
  dbbad=$(sqlite3 -readonly -cmd '.timeout 3000' "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE enable=1 AND (port IS NULL OR port<=0 OR (COALESCE(settings,'') <> '' AND json_valid(settings)=0) OR (COALESCE(stream_settings,'') <> '' AND json_valid(stream_settings)=0));" 2>/dev/null || echo -1)
  if [[ "$dbbad" == 0 ]]; then
    log "JSON Рё РїРѕСЂС‚С‹ inbounds РІР°Р»РёРґРЅС‹"
  elif [[ "$dbbad" == "-1" ]]; then
    warn "РЅРµ СѓРґР°Р»РѕСЃСЊ РїСЂРѕРІРµСЂРёС‚СЊ JSON/РїРѕСЂС‚С‹ inbounds"; issues=$((issues+1))
  else
    err "РїСЂРѕР±Р»РµРјРЅС‹Рµ inbounds: $dbbad"; issues=$((issues+1))
  fi
  echo "[ UFW ]"
  if command -v ufw >/dev/null 2>&1; then ufw status | head -1; else warn "ufw РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ"; fi
  echo; if (( issues )); then err "РџРѕР»РЅС‹Р№ Р°СѓРґРёС‚: РїСЂРѕР±Р»РµРј $issues"; return 1; fi
  log "РџРѕР»РЅС‹Р№ Р°СѓРґРёС‚: РєСЂРёС‚РёС‡РµСЃРєРёС… РїСЂРѕР±Р»РµРј РЅРµ РЅР°Р№РґРµРЅРѕ"
}

# Р–РґС‘Рј, РїРѕРєР° Р’РЎР• РІРєР»СЋС‡С‘РЅРЅС‹Рµ РёРЅР±Р°СѓРЅРґС‹ РЅР°С‡РЅСѓС‚ СЃР»СѓС€Р°С‚СЊ (deadline СЃРµРє, РїРѕР»Р» 3 СЃ).
# Р’РѕР·РІСЂР°С‰Р°РµС‚ 0 вЂ” РІСЃС‘ СЃР»СѓС€Р°РµС‚, 1 вЂ” РґРµРґР»Р°Р№РЅ РёСЃС‚С‘Рє. РќСѓР¶РµРЅ РїРѕСЃР»Рµ СЂРµСЃС‚Р°СЂС‚Р° x-ui:
# РїРµСЂРµРїСЂРёРІСЏР·С‹РІР°СЋС‚СЃСЏ РЅРµ С‚РѕР»СЊРєРѕ В«РјС‘СЂС‚РІС‹РµВ» РїРѕСЂС‚С‹, РЅРѕ Рё Р¶РёРІС‹Рµ, РїРѕСЌС‚РѕРјСѓ СЃСЂР°Р·Сѓ
# РїРѕСЃР»Рµ СЂРµСЃС‚Р°СЂС‚Р° РєРѕРЅС‚СЂРѕР»СЊРЅС‹Р№ Р°СѓРґРёС‚ Р»РѕРІРёС‚ СЃРѕРєРµС‚С‹ РІ РјРѕРјРµРЅС‚Рµ.
stack_wait_ports() {   # [deadline_sec]
  # LucX РІ СЃС‚Р°СЂС‚РѕРІРѕРј РѕРєРЅРµ РїРµСЂРµСЃРѕР·РґР°С‘С‚ РѕР±СЂР°Р±РѕС‚С‡РёРєРё РёРЅР±Р°СѓРЅРґРѕРІ С‡РµСЂРµР· xray API:
  # РїРѕСЂС‚ РјРѕР¶РµС‚ РїРѕРґРЅСЏС‚СЊСЃСЏ Рё СЃРЅРѕРІР° РёСЃС‡РµР·РЅСѓС‚СЊ (СЏРґСЂРѕ xray РїСЂРё СЌС‚РѕРј РЅРµ СЂРµСЃС‚Р°СЂС‚СѓРµС‚,
  # РІ journal СЌС‚Рѕ РЅРµ РІРёРґРЅРѕ). РџРѕСЌС‚РѕРјСѓ СЃС…РѕРґРёРјРѕСЃС‚СЊ = Р”Р’Рђ С‡РёСЃС‚С‹С… РїСЂРѕС…РѕРґР° РџРћР”Р РЇР”.
  # Р‘С‹СЃС‚СЂРѕ: РїРѕР»Р» 1 СЃ, РѕРґРёРЅ РѕР±С‰РёР№ СЃРЅРёРјРѕРє ss РЅР° РїСЂРѕС…РѕРґ (РІРјРµСЃС‚Рѕ ss РЅР° РїРѕСЂС‚).
  local deadline="${1:-60}" waited=0 miss streak=0 _pid _proto _port _snap
  while :; do
    miss=0
    _snap="$(ss -ltnp 2>/dev/null; ss -lnup 2>/dev/null)"
    while IFS='|' read -r _pid _proto _port; do
      [[ -n "$_pid" ]] || continue
      [[ "$_port" =~ ^[0-9]+$ && "$_port" != 0 ]] || continue
      grep -Eq ":${_port}[[:space:]]" <<<"$_snap" || { miss=1; break; }
    done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)
    if (( miss == 0 )); then
      (( streak >= 1 )) && return 0
      streak=$((streak+1))
    else
      streak=0
    fi
    (( waited >= deadline )) && return 1
    # Р–РёРІРѕР№ РїСЂРѕРіСЂРµСЃСЃ: С‚РёС€РёРЅР° РґРѕ 60 СЃ РІС‹РіР»СЏРґРёС‚ РєР°Рє Р·Р°РІРёСЃР°РЅРёРµ (28.10).
    (( waited > 0 && waited % 10 == 0 )) && log "  вЂ¦ РІСЃС‘ РµС‰С‘ Р¶РґСѓ СЃС…РѕРґРёРјРѕСЃС‚Рё СЃРѕРєРµС‚РѕРІ (${waited}/${deadline} СЃ)вЂ¦"
    sleep 1; waited=$((waited+1))
  done
}

# вљЎ РџР РћР’Р•Р РљРђ Р РџРћР§РРќРљРђ РѕРґРЅРёРј РґРµР№СЃС‚РІРёРµРј: РїРѕР»РЅС‹Р№ read-only Р°СѓРґРёС‚ в†’ Р±РµР·РѕРїР°СЃРЅР°СЏ
# Р°РІС‚РѕРїРѕС‡РёРЅРєР° РЅР°Р№РґРµРЅРЅРѕРіРѕ в†’ РєРѕРЅС‚СЂРѕР»СЊРЅС‹Р№ Р°СѓРґРёС‚ СЃ РґРµР»СЊС‚РѕР№. РџСЂРёРЅС†РёРїС‹:
#   вЂў С‡РёРЅРёРј С‚РѕР»СЊРєРѕ РґРµС‚РµСЂРјРёРЅРёСЂРѕРІР°РЅРЅРѕРµ: СѓРїР°РІС€РёРµ СЃРµСЂРІРёСЃС‹, СЃРµСЂС‚С‹/decoy РёРЅР±Р°СѓРЅРґРѕРІ
#     (sync_inbound_certs), CDN-РґСЂРµР№С„ (cdn_repair), РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РёРµ UDP-РїСЂР°РІРёР»Р°
#     UFW, РїРµСЂРµСЃР±РѕСЂРєСѓ xray-РєРѕРЅС„РёРіР° (СЂРµСЃС‚Р°СЂС‚ x-ui) РґР»СЏ РјС‘СЂС‚РІС‹С… СЃРѕРєРµС‚РѕРІ;
#   вЂў РќР• РІС‹РїСѓСЃРєР°РµРј СЃРµСЂС‚РёС„РёРєР°С‚С‹ LE (РєРІРѕС‚С‹/DNS вЂ” СЂР°Р·РґРµР» 3) Рё РЅРµ РїСЂР°РІРёРј Р±РёС‚С‹Р№
#     nginx-РєРѕРЅС„РёРі РІСЃР»РµРїСѓСЋ вЂ” С‚РѕР»СЊРєРѕ РїРѕРєР°Р·С‹РІР°РµРј РїСЂРёС‡РёРЅСѓ.
stack_check_fix() {
  line; echo -e "${B}   РџР РћР’Р•Р РљРђ Р РџРћР§РРќРљРђ (РѕРґРЅРёРј РґРµР№СЃС‚РІРёРµРј)${N}"; line
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” РїСЂРѕРІРµСЂСЏС‚СЊ РЅРµС‡РµРіРѕ"; return 1; }
  local _a1 _a2 before after
  _a1="$(mktemp /tmp/stack-doctor.XXXXXX)"; _a2="$(mktemp /tmp/stack-doctor.XXXXXX)"
  log "Р­С‚Р°Рї 1/3: РїРѕР»РЅР°СЏ РїСЂРѕРІРµСЂРєР° СЃС‚РµРєР° (read-only)вЂ¦"
  stack_full_audit > "$_a1" 2>&1 || true
  cat "$_a1"
  # РСЃРєР»СЋС‡Р°РµРј РёС‚РѕРіРѕРІСѓСЋ СЃС‚СЂРѕРєСѓ Р°СѓРґРёС‚Р° В«[x] РџРѕР»РЅС‹Р№ Р°СѓРґРёС‚: РїСЂРѕР±Р»РµРј NВ» вЂ”
  # РёРЅР°С‡Рµ СЃС‡С‘С‚С‡РёРє Р·Р°РІС‹С€РµРЅ РЅР° 1 (В«Р±С‹Р»Рѕ 5 в†’ РѕСЃС‚Р°Р»РѕСЃСЊ 4В» РїСЂРё 4 СЂРµР°Р»СЊРЅС‹С…).
  before=$(grep -E '\[!\]|\[x\]' "$_a1" 2>/dev/null | grep -vc 'РџРѕР»РЅС‹Р№ Р°СѓРґРёС‚: РїСЂРѕР±Р»РµРј' || true)
  before="${before:-0}"
  if (( before == 0 )); then
    rm -f "$_a1" "$_a2"
    log "РџСЂРѕР±Р»РµРј РЅРµ РЅР°Р№РґРµРЅРѕ вЂ” РїРѕС‡РёРЅРєР° РЅРµ С‚СЂРµР±СѓРµС‚СЃСЏ"
    return 0
  fi
  echo
  # Р‘РµР· РїСЂРѕРјРµР¶СѓС‚РѕС‡РЅС‹С… РІРѕРїСЂРѕСЃРѕРІ: СЃР°Рј РїСѓРЅРєС‚ РјРµРЅСЋ РЅР°Р·С‹РІР°РµС‚СЃСЏ В«РїСЂРѕРІРµСЂРёС‚СЊ Рё РїРѕС‡РёРЅРёС‚СЊВ»,
  # РІС‹Р±РѕСЂ РїСѓРЅРєС‚Р° вЂ” СѓР¶Рµ СЃРѕРіР»Р°СЃРёРµ РЅР° Р±РµР·РѕРїР°СЃРЅСѓСЋ Р°РІС‚РѕРїРѕС‡РёРЅРєСѓ.
  log "РќР°Р№РґРµРЅРѕ Р·Р°РјРµС‡Р°РЅРёР№: $before вЂ” РїСЂРёРјРµРЅСЏСЋ Р±РµР·РѕРїР°СЃРЅСѓСЋ Р°РІС‚РѕРїРѕС‡РёРЅРєСѓ"

  log "Р­С‚Р°Рї 2/3: РїРѕС‡РёРЅРєР°вЂ¦"
  # РђРІС‚РѕРїРёР»РѕС‚ РЅР° РІСЂРµРјСЏ РїРѕС‡РёРЅРєРё (РґРёРЅР°РјРёС‡РµСЃРєР°СЏ РѕР±Р»Р°СЃС‚СЊ РІРёРґРёРјРѕСЃС‚Рё: РІРёРґСЏС‚ РІСЃРµ
  # РІС‹Р·С‹РІР°РµРјС‹Рµ С„СѓРЅРєС†РёРё, РЅР° РІС‹С…РѕРґРµ СЃРЅРёРјР°РµС‚СЃСЏ СЃР°Рј). Р“Р°СЂР°РЅС‚РёСЏ: РѕРґРЅРѕСЂР°Р·РѕРІС‹Р№ РїРѕС‚РѕРє
  # В«РїСЂРѕРІРµСЂРёС‚СЊ Рё РїРѕС‡РёРЅРёС‚СЊВ» РќРРљРћР“Р”Рђ РЅРµ РѕСЃС‚Р°РЅР°РІР»РёРІР°РµС‚СЃСЏ РІРѕРїСЂРѕСЃРѕРј/Enter вЂ”
  # certify-РїСѓС‚СЊ (cert_issue/cert_error_pause) РјРѕР»С‡Р° РґРµРіСЂР°РґРёСЂСѓРµС‚ РІ warn.
  local STACK_AUTOPILOT=1
  local svc id proto port row dports="" _ss waited=0 restarted=0
  # 1) РЈРїР°РІС€РёРµ СЃРµСЂРІРёСЃС‹
  for svc in nginx x-ui; do
    if ! systemctl is-active --quiet "$svc" 2>/dev/null; then
      systemctl start "$svc" 2>/dev/null || true
      if systemctl is-active --quiet "$svc" 2>/dev/null; then
        log "  СЃРµСЂРІРёСЃ $svc РїРѕРґРЅСЏС‚"
      else
        err "  СЃРµСЂРІРёСЃ $svc РЅРµ РїРѕРґРЅРёРјР°РµС‚СЃСЏ вЂ” СЃРјРѕС‚СЂРёС‚Рµ journalctl -u $svc -n 20"
      fi
    fi
  done
  # 2) РЎРµСЂС‚С‹/decoy РёРЅР±Р°СѓРЅРґРѕРІ (РјРѕР»С‡РёС‚, РµСЃР»Рё С‡РёРЅРёС‚СЊ РЅРµС‡РµРіРѕ)
  sync_inbound_certs || true
  # 3) CDN-РґСЂРµР№С„ (SNI-РјР°СЂС€СЂСѓС‚, http-Р±Р»РѕРє, hosts, РїСѓС‚СЊ; СЃР°Рј РґРµР»Р°РµС‚ reload);
  #    quiet=1 вЂ” Р±РµР· РёРЅС‚РµСЂР°РєС‚РёРІРЅС‹С… РІРѕРїСЂРѕСЃРѕРІ РІРЅСѓС‚СЂРё РѕРґРЅРѕСЂР°Р·РѕРІРѕР№ РїРѕС‡РёРЅРєРё
  cdn_repair 1 0 || true
  cdn_repair 1 0 || true
  # 3b) Reality РІ РїРѕРґРєР»СЋС‡РµРЅРёСЏС…: serverNames Р»РѕРєР°Р»СЊРЅРѕРіРѕ Reality СЃРІРµСЂСЏРµС‚СЃСЏ СЃ
  #     РґРѕРјРµРЅРѕРј С…РѕСЃС‚Р° (СЂР°СЃС…РѕР¶РґРµРЅРёРµ = Р±РёС‚С‹Рµ РєР»РёРµРЅС‚СЃРєРёРµ СЃСЃС‹Р»РєРё). Р’РЅРµС€РЅРёР№ вЂ” РјРёРјРѕ.
  reality_sni_repair || true
  # 4) UDP-РїРѕСЂС‚С‹ Р±РµР· РїСЂР°РІРёР» UFW
  while IFS='|' read -r id proto port; do
    [[ -n "$id" && "$port" =~ ^[0-9]+$ && "$port" != 0 ]] || continue
    is_udp_proto "$proto" || continue
    if ! ufw status 2>/dev/null | awk -v p="$port" '$0 ~ ("[[:space:]]" p "/udp([[:space:]]|$)") || $0 ~ ("[[:space:]]" p "([[:space:]]|$)") {found=1} END{exit !found}'; then
      fw_allow "$port" udp "udp-РёРЅР±Р°СѓРЅРґ #$id"
      log "  UDP/$port РѕС‚РєСЂС‹С‚ РІ UFW (РёРЅР±Р°СѓРЅРґ #$id $proto)"
    fi
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)
  # Р’РђР–РќРћ: ufw --force enable Р·РґРµСЃСЊ РЈР‘Р РђРќ. Р•СЃР»Рё UFW Р±С‹Р» РІС‹РєР»СЋС‡РµРЅ, enable
  # 5) РњС‘СЂС‚РІС‹Рµ СЃРѕРєРµС‚С‹ в†’ РїРµСЂРµСЃР±РѕСЂРєР° xray-РєРѕРЅС„РёРіР° (СЂРµСЃС‚Р°СЂС‚ x-ui), Р·Р°С‚РµРј РїРµСЂРµРїСЂРѕРІРµСЂРєР°
  local -a dead=() still=() pending=()
  while IFS='|' read -r id proto port; do
    [[ "$port" =~ ^[0-9]+$ && "$port" != 0 ]] || continue
    _ss="-ltnup"; is_udp_proto "$proto" && _ss="-lnup"
    ss "$_ss" 2>/dev/null | grep -Eq ":${port}[[:space:]]" || dead+=("$id|$proto|$port")
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)
  if (( ${#dead[@]} )); then
    for row in "${dead[@]}"; do dports+="${row##*|} "; done
    log "  РЅРµ СЃР»СѓС€Р°СЋС‚СЃСЏ РїРѕСЂС‚С‹: ${dports% } вЂ” РїРµСЂРµСЃРѕР±РёСЂР°СЋ РєРѕРЅС„РёРі xray (СЂРµСЃС‚Р°СЂС‚ x-ui)"
    restarted=1
    systemctl restart x-ui 2>/dev/null || true
    # xray СЃ Reality/С‚СѓРЅРЅРµР»СЏРјРё РїРѕРґРЅРёРјР°РµС‚ СЃРѕРєРµС‚С‹ РґРѕР»РіРѕ (trusttunnel вЂ” РґРѕ ~15 СЃ):
    # С„РёРєСЃРёСЂРѕРІР°РЅРЅС‹Р№ sleep 3 Р»РѕРІРёР» РјРѕРјРµРЅС‚ В«СЂР°Р·РґРµРІР°РЅРёСЏВ» Рё РґР°РІР°Р» Р»РѕР¶РЅС‹Рµ
    # В«СЃРѕРєРµС‚ РЅРµ СЃР»СѓС€Р°РµС‚В». Р–РґС‘Рј РґРѕ 60 СЃ.
    still=("${dead[@]}")
    while (( ${#still[@]} )) && (( waited < 60 )); do
      sleep 3; waited=$((waited+3))
      pending=()
      for row in "${still[@]}"; do
        IFS='|' read -r id proto port <<<"$row"
        _ss="-ltnup"; is_udp_proto "$proto" && _ss="-lnup"
        if ss "$_ss" 2>/dev/null | grep -Eq ":${port}[[:space:]]"; then
          log "  #$id $proto:$port вЂ” РїРѕРґРЅСЏР»СЃСЏ (С‡РµСЂРµР· ${waited}СЃ)"
        else
          pending+=("$row")
        fi
      done
      still=("${pending[@]}")
    done
    if (( ${#still[@]} )); then
      warn "  РЅРµ РїРѕРґРЅСЏР»РѕСЃСЊ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё (РїСЂРѕС‚РѕРєРѕР» РЅРµ РїРѕРґРґРµСЂР¶РёРІР°РµС‚СЃСЏ СЏРґСЂРѕРј РёР»Рё Р±РёС‚С‹Р№ РєРѕРЅС„РёРі):"
      for row in "${still[@]}"; do
        IFS='|' read -r id proto port <<<"$row"
        warn "    #$id $proto:$port вЂ” РїСЂРёС‡РёРЅС‹: journalctl -u x-ui | grep $port"
      done
    fi
  fi
  # 5b) Р РµСЃС‚Р°СЂС‚ РїРµСЂРµРєРёРґС‹РІР°РµС‚ Р’РЎР• СЃРѕРєРµС‚С‹, РІРєР»СЋС‡Р°СЏ Р¶РёРІС‹Рµ: Р¶РґС‘Рј СЃС…РѕРґРёРјРѕСЃС‚Рё РІСЃРµС…
  #     РІРєР»СЋС‡С‘РЅРЅС‹С… РїРѕСЂС‚РѕРІ, РёРЅР°С‡Рµ РєРѕРЅС‚СЂРѕР»СЊРЅС‹Р№ Р°СѓРґРёС‚ Р»РѕРІРёС‚ РїРѕСЂС‚ РІ РјРѕРјРµРЅС‚Рµ
  #     (В«С‚Рѕ СЃР»СѓС€Р°РµС‚, С‚Рѕ РЅРµ СЃР»СѓС€Р°РµС‚В» РјРµР¶РґСѓ СЃРѕСЃРµРґРЅРёРјРё РїСЂРѕРІРµСЂРєР°РјРё).
  if (( restarted )); then
    log "  Р¶РґСѓ СЃС…РѕРґРёРјРѕСЃС‚Рё РІСЃРµС… СЃРѕРєРµС‚РѕРІ (РґРѕ 60 СЃ, 2 СЃС‚Р°Р±РёР»СЊРЅС‹С… РїСЂРѕС…РѕРґР°)вЂ¦"
    stack_wait_ports 60 || warn "  С‡Р°СЃС‚СЊ СЃРѕРєРµС‚РѕРІ РЅРµ РїРѕРґРЅСЏР»Р°СЃСЊ Р·Р° 60 СЃ вЂ” СЃРј. РєРѕРЅС‚СЂРѕР»СЊРЅС‹Р№ Р°СѓРґРёС‚"
  fi
  # 5c) hosts (РєСЂРѕРјРµ CDN): РѕР±С‰Р°СЏ РіСЂСѓРїРїР° В«РѕРґРёРЅ С…РѕСЃС‚В» вЂ” СЃС‚СЂРѕРєР° РµСЃС‚СЊ Сѓ РєР°Р¶РґРѕРіРѕ
  #     TCP-РёРЅР±Р°СѓРЅРґР°; РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РёРµ/РѕС‚РѕСЂРІР°РЅРЅС‹Рµ РѕС‚ РіСЂСѓРїРїС‹ РїРµСЂРµСЃРѕР·РґР°СЋС‚СЃСЏ.
  #     CDN-СЃС‚СЂРѕРєРё РЅРµ С‚СЂРѕРіР°РµРј вЂ” РёС… СѓР¶Рµ РїРѕС‡РёРЅРёР» cdn_repair (С€Р°Рі 3).
  hosts_repair_stack || true
  # 5d) AmneziaWG: UFW-РїСЂР°РІРёР»Р° РїРѕСЂС‚РѕРІ; РЅРµ РїРѕРґРЅСЏС‚С‹Рµ kernel-РёРЅС‚РµСЂС„РµР№СЃС‹ awg<id>
  #     Р»РµС‡Р°С‚СЃСЏ СЂРµСЃС‚Р°СЂС‚РѕРј x-ui (РїР°РЅРµР»СЊ РїРµСЂРµСЃРѕР·РґР°С‘С‚ РёС… РёР· Р‘Р” СЃР°РјР°).
  awg_repair || true
  # 6) Р‘РёС‚С‹Р№ nginx-РєРѕРЅС„РёРі РЅРµ С‡РёРЅРёРј РІСЃР»РµРїСѓСЋ
  if ! nginx -t >/dev/null 2>&1; then
    err "  nginx -t: FAIL вЂ” РєРѕРЅС„РёРі Р±РёС‚С‹Р№, РїСЂР°РІРёС‚СЃСЏ РІСЂСѓС‡РЅСѓСЋ (nginx -T РїРѕРєР°Р¶РµС‚ РјРµСЃС‚Рѕ)"
  fi

  log "Р­С‚Р°Рї 3/3: РєРѕРЅС‚СЂРѕР»СЊРЅР°СЏ РїСЂРѕРІРµСЂРєР°вЂ¦"
  stack_full_audit > "$_a2" 2>&1 || true
  cat "$_a2"
  after=$(grep -E '\[!\]|\[x\]' "$_a2" 2>/dev/null | grep -vc 'РџРѕР»РЅС‹Р№ Р°СѓРґРёС‚: РїСЂРѕР±Р»РµРј' || true)
  after="${after:-0}"
  rm -f "$_a1" "$_a2"
  echo
  if (( after == 0 )); then
    log "Р“РѕС‚РѕРІРѕ: Р±С‹Р»Рѕ Р·Р°РјРµС‡Р°РЅРёР№ $before в†’ РѕСЃС‚Р°Р»РѕСЃСЊ 0"
  elif (( after < before )); then
    log "Р“РѕС‚РѕРІРѕ: Р±С‹Р»Рѕ Р·Р°РјРµС‡Р°РЅРёР№ $before в†’ РѕСЃС‚Р°Р»РѕСЃСЊ $after (РѕСЃС‚Р°С‚РѕРє СЂР°СЃС€РёС„СЂРѕРІР°РЅ РІС‹С€Рµ)"
  else
    warn "Р“РѕС‚РѕРІРѕ: Р±С‹Р»Рѕ Р·Р°РјРµС‡Р°РЅРёР№ $before в†’ РѕСЃС‚Р°Р»РѕСЃСЊ $after (Р°РІС‚РѕРїРѕС‡РёРЅРєР° Р·РґРµСЃСЊ РЅРµ РїРѕРјРѕРіР°РµС‚ вЂ” СЃРј. РІС‹С€Рµ)"
  fi
  (( after == 0 ))
}

# РџСЂРѕРІРµСЂРєР° Рё РїРѕС‡РёРЅРєР° CDN-РјР°СЂС€СЂСѓС‚РёР·Р°С†РёРё РїРѕ РїСЂРѕС„РёР»СЏРј: SNI-map, upstream,
# http-Р±Р»РѕРє, decoy. Р–РёРІРѕР№ С‚РµСЃС‚: РїСѓС‚СЊ в†’ xray (Р»СЋР±РѕР№ HTTP-РѕС‚РІРµС‚), РѕСЃС‚Р°Р»СЊРЅРѕРµ в†’ decoy.
#   quiet=1 вЂ” Р±РµР· РІРѕРїСЂРѕСЃРѕРІ/Р»РѕРіРѕРІ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ (РІС‹Р·РѕРІ РёР· Р°РІС‚РѕРїСѓС‚РµР№)
cdn_repair() {   # [quiet] [noreload]
  # quiet=1    вЂ” Р±РµР· РІРѕРїСЂРѕСЃРѕРІ/Р»РѕРіРѕРІ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ (РІС‹Р·РѕРІ РёР· Р°РІС‚РѕРїСѓС‚РµР№)
  # noreload=1 вЂ” С‚РѕР»СЊРєРѕ РєРѕРЅС„РёРіРё, Р‘Р•Р— СЃС‚Р°СЂС‚Р°/reload nginx (РІС‹Р·РѕРІ РёР· СЃРµСЂРµРґРёРЅС‹ Рї.1)
  local quiet="${1:-0}" noreload="${2:-0}"
  cdn_profiles_load
  (( ${#CDN_PROFILE_IDS[@]} )) || { (( quiet )) || log "CDN-РїСЂРѕС„РёР»РµР№ РЅРµС‚ вЂ” РїСЂРѕРІРµСЂСЏС‚СЊ РЅРµС‡РµРіРѕ"; return 0; }
  local fixed=0 id proto origin cdn path tpl dport port cp_line cert key code
  for id in "${CDN_PROFILE_IDS[@]}"; do
    proto=$(cdn_profile_field "$id" 2) ; origin=$(cdn_profile_field "$id" 3)
    cdn=$(cdn_profile_field "$id" 4)   ; path=$(cdn_profile_field "$id" 5)
    tpl=$(cdn_profile_field "$id" 6)   ; dport=$(cdn_profile_field "$id" 7)
    # 1) SNI-РјР°СЂС€СЂСѓС‚ origin/cdn в†’ cdn_frontend
    if ! grep -qE "^[[:space:]]+${origin//./\\.}[[:space:]]+cdn_frontend;" "$SNI_CONF" 2>/dev/null; then
      [[ -f "$SNI_CONF" ]] || { (( quiet )) || err "CDN #$id: РЅРµС‚ $SNI_CONF"; continue; }
      cdn_frontend_ensure "$origin" "$cdn"; fixed=1
      (( quiet )) || warn "  CDN #$id: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ SNI-РјР°СЂС€СЂСѓС‚ $origin в†’ cdn_frontend (РјР°СЂС€СЂСѓС‚ РѕС‚СЃСѓС‚СЃС‚РІРѕРІР°Р»!)"
    fi
    grep -q "^upstream cdn_frontend " "$SNI_CONF" 2>/dev/null || { sni_upstream_add "cdn_frontend" "$CDN_FE_PORT"; fixed=1; }
    # 2) http-Р±Р»РѕРє РІ stack.conf (+ РІ Р±Р»РѕРєРµ РѕР±СЏР·Р°С‚РµР»РµРЅ location ^~: СЃРµСЃСЃРёРё
    #    xhttp РёРґСѓС‚ РЅР° $path/<sessionID> Рё Р±РµР· РЅРµРіРѕ РїР°РґР°СЋС‚ РІ decoy)
    local _blk=""
    _blk=$(sed -n "/# >>> cdn .*domain=${origin//./\\.}/,/# <<< cdn/p" "$STACK_CONF" 2>/dev/null || true)
    if [[ -z "$_blk" || "$_blk" != *"location ^~"* ]]; then
      port=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT port FROM inbounds WHERE id=$id;" 2>/dev/null || true)
      cp_line=$(cert_paths "$origin") || true
      if [[ -z "$port" || -z "$cp_line" ]]; then
        if [[ -n "$_blk" ]]; then
          (( quiet )) || warn "  CDN #$id: Р±Р»РѕРє $origin СѓСЃС‚Р°СЂРµР» (РЅРµС‚ location ^~ вЂ” СЃРµСЃСЃРёРё РїР°РґР°Р»Рё РІ decoy), РЅРѕ РґР»СЏ РїРµСЂРµСЃР±РѕСЂРєРё РЅРµС‚ СЃРµСЂС‚Р° $origin РёР»Рё РїРѕСЂС‚Р° РёРЅР±Р°СѓРЅРґР°"
        else
          (( quiet )) || warn "  CDN #$id: http-Р±Р»РѕРє РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚, РЅРѕ РЅРµС‚ СЃРµСЂС‚Р° $origin РёР»Рё РїРѕСЂС‚Р° РёРЅР±Р°СѓРЅРґР° вЂ” Р·Р°РїРѕР»РЅРё Рё РїРѕРІС‚РѕСЂРё"
        fi
        continue
      fi
      cert="${cp_line%% *}"; key="${cp_line##* }"
      # decoy: Р¶РёРІРѕР№ Р±Р»РѕРє СѓР¶Рµ РµСЃС‚СЊ? РµСЃР»Рё РЅРµС‚ вЂ” РїРµСЂРµСЃРѕР·РґР°С‘Рј РїРѕ РїСЂРѕС„РёР»СЋ
      stack_decoy_meta "$origin" >/dev/null 2>&1 || {
        [[ "$dport" =~ ^[0-9]+$ ]] || dport=$((47000 + id))
        while ss -tlnH "sport = :$dport" 2>/dev/null | grep -q .; do dport=$((dport+1)); done
        mk_decoy "$dport" "$origin" "$cert" "$key" "/var/www/decoy-cdn-$id" "$(decoy_tpl_for "$origin")" >/dev/null 2>&1 || dport=0
      }
      stack_cdn_upsert "$origin" "$cdn" "$path" "$port" "${dport:-0}" "$cert" "$key"
      fixed=1
      if [[ -n "$_blk" ]]; then
        (( quiet )) || warn "  CDN #$id: Р±Р»РѕРє $origin РїРµСЂРµСЃРѕР±СЂР°РЅ (РґРѕР±Р°РІР»РµРЅ location ^~ вЂ” СЃРµСЃСЃРёРё xhttp РёРґСѓС‚ РІ xray, РЅРµ РІ decoy)"
      else
        (( quiet )) || warn "  CDN #$id: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ http-Р±Р»РѕРє $origin (РїСѓС‚СЊ $path в†’ 127.0.0.1:$port)"
      fi
      # РѕР±РЅРѕРІРёС‚СЊ РїСЂРѕС„РёР»СЊ Р°РєС‚СѓР°Р»СЊРЅС‹Рј decoy-РїРѕСЂС‚РѕРј
      cdn_profile_save_add "$id" "$proto" "$origin" "$cdn" "$path" "$tpl" "${dport:-0}" "$(cdn_profile_provider "$id")"
    fi
    # 3) hosts-СЃС‚СЂРѕРєР°: address/sni/host_header = CDN-РґРѕРјРµРЅ, security=tls СЏРІРЅРѕ
    #    (РІ РЅР°С€РµР№ СЃС…РµРјРµ TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx; 'same' СѓРЅР°СЃР»РµРґРѕРІР°Р» Р±С‹ none),
    #    remark = CDN_<proto>
    local _ha="" _hs="" _hh="" _hsec=""
    IFS='|' read -r _ha _hs _hh _hsec <<<"$(sqlite3 -cmd '.timeout 3000' -separator '|' "$XUI_DB" \
      "SELECT COALESCE(address,''),COALESCE(sni,''),COALESCE(host_header,''),COALESCE(security,'') FROM hosts WHERE inbound_id=$id AND port=443 ORDER BY id LIMIT 1;" 2>/dev/null || true)"
    if [[ "$_ha" != "$cdn" || "$_hs" != "$cdn" || "$_hh" != "$cdn" || "$_hsec" != "tls" ]]; then
      hosts_cdn_upsert "$id" "$cdn" "$proto"
      fixed=1
      (( quiet )) || warn "  CDN #$id: hosts-Р·Р°РїРёСЃСЊ РёСЃРїСЂР°РІР»РµРЅР° в†’ address/sni/host=$cdn, security=tls (Р±С‹Р»Рѕ: addr=${_ha:-РїСѓСЃС‚Рѕ}, sni=${_hs:-РїСѓСЃС‚Рѕ}, sec=${_hsec:-РЅР°СЃР»РµРґСѓРµС‚СЃСЏ})"
    fi
    # 4) РїСѓС‚СЊ/С…РѕСЃС‚ РёРЅР±Р°СѓРЅРґР° РѕР±СЏР·Р°РЅС‹ СЃРѕРІРїР°РґР°С‚СЊ СЃ РїСЂРѕС„РёР»РµРј: nginx-Р±Р»РѕРє РїСЂРѕРєСЃРёСЂСѓРµС‚
    #    СЂРѕРІРЅРѕ $path, Р° xray РѕС‚РІРµС‡Р°РµС‚ С‚РѕР»СЊРєРѕ РЅР° СЃРІРѕР№ transport-path
    local _ipath="" _ihost=""
    IFS='|' read -r _ipath _ihost <<<"$(sqlite3 -cmd '.timeout 3000' -separator '|' "$XUI_DB" \
      "SELECT COALESCE(json_extract(stream_settings,'\$.xhttpSettings.path'),''),COALESCE(json_extract(stream_settings,'\$.xhttpSettings.host'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)"
    if [[ "$_ipath" != "$path" || "$_ihost" != "$origin" ]]; then
      local _xw=1; systemctl is-active --quiet x-ui 2>/dev/null || _xw=0
      (( _xw )) && { systemctl stop x-ui >/dev/null 2>&1 || true; sleep 1; }
      sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
        "UPDATE inbounds SET stream_settings=json_set(COALESCE(stream_settings,'{}'),'\$.xhttpSettings.path','$(sql_escape "$path")','\$.xhttpSettings.host','$(sql_escape "$origin")') WHERE id=$id;" 2>/dev/null || true
      (( _xw )) && { systemctl start x-ui >/dev/null 2>&1 || true; sleep 2; }
      fixed=1
      (( quiet )) || warn "  CDN #$id: РїСѓС‚СЊ РёРЅР±Р°СѓРЅРґР° РїСЂРёРІРµРґС‘РЅ Рє РїСЂРѕС„РёР»СЋ (Р±С‹Р»Рѕ: path=${_ipath:-РїСѓСЃС‚Рѕ}, host=${_ihost:-РїСѓСЃС‚Рѕ} в†’ $path, $origin)"
    fi
    # 5) РёРЅР±Р°СѓРЅРґ РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ Р±РµР· security (TLS Сѓ nginx)
    if (( ! quiet )); then
      local _sec=""; _sec=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
        "SELECT COALESCE(json_extract(stream_settings,'\$.security'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
      if [[ -n "$_sec" && "$_sec" != "none" ]]; then
        warn "  CDN #$id: РІ РёРЅР±Р°СѓРЅРґРµ security=$_sec вЂ” CDN-СЂРµР¶РёРј С‚СЂРµР±СѓРµС‚ none/РїСѓСЃС‚Рѕ! TLS Сѓ nginx, xray РїСЂРёРЅРёРјР°РµС‚ РіРѕР»С‹Р№ HTTP."
        warn "     РСЃРїСЂР°РІСЊ: Рї.2 в†’ 2 (РїРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґ) РёР»Рё Р·Р°РЅРѕРІРѕ РѕС‚РІРµС‚СЊ РЅР° РІРѕРїСЂРѕСЃ CDN РІ Рї.1."
      fi
      local _ext=""; _ext=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
        "SELECT json_extract(stream_settings,'\$.externalProxy') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
      [[ -n "$_ext" && "$_ext" != "null" ]] && warn "  CDN #$id: РІ stream РµСЃС‚СЊ externalProxy вЂ” РѕРЅ СѓРІРѕРґРёС‚ С‚СЂР°С„РёРє РјРёРјРѕ nginx-РјР°СЂС€СЂСѓС‚Р°, РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ СѓРґР°Р»С‘РЅ"
    fi
    # 6) Р¶РёРІРѕР№ С‚РµСЃС‚ С‡РµСЂРµР· Р»РѕРєР°Р»СЊРЅС‹Р№ С„СЂРѕРЅС‚РµРЅРґ
    if (( ! quiet )); then
      code=$(curl -sk -o /dev/null -w '%{http_code}' --max-time 6 "https://127.0.0.1:$CDN_FE_PORT$path" -H "Host: $origin" 2>/dev/null || true)
      code="${code:-000}"
      if [[ "$code" == "000" || "$code" == "502" || "$code" == "503" ]]; then
        warn "  CDN #$id: РџРЈРўР¬ $path в†’ ${code} вЂ” xray РЅРµ РїСЂРёРЅСЏР» СЃРѕРµРґРёРЅРµРЅРёРµ. РџСЂРёС‡РёРЅС‹:"
        warn "     вЂў РІ РёРЅР±Р°СѓРЅРґРµ #$id РѕСЃС‚Р°Р»СЃСЏ security=tls (РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ none/РїСѓСЃС‚Рѕ) вЂ” РїСЂРѕРіРѕРЅРё Рї.2 в†’ 2 (РїРѕС‡РёРЅРёС‚СЊ) РёР»Рё РїСѓРЅРєС‚ 1"
        warn "     вЂў x-ui/xray РЅРµ Р°РєС‚РёРІРµРЅ, РёР»Рё РёРЅР±Р°СѓРЅРґ #$id РЅРµ СЃР»СѓС€Р°РµС‚ РїРѕСЂС‚"
      else
        : # СЂСѓС‚РёРЅР°: РїСѓС‚СЊ РѕС‚РІРµС‡Р°РµС‚ xray вЂ” РјРѕР»С‡Р°
      fi
      # Р“Р›РђР’РќР«Р™ С‚РµСЃС‚: СЃРµСЃСЃРёСЏ $path/<sid> РѕР±СЏР·Р°РЅР° СѓС…РѕРґРёС‚СЊ РІ xray, Р° РЅРµ РІ decoy.
      # Р•СЃР»Рё РІ РѕС‚РІРµС‚ HTML (РЅР°С‡РёРЅР°РµС‚СЃСЏ СЃ '<' = 60) вЂ” РєР»РёРµРЅС‚ СѓРІРёРґРёС‚ В«unknown version: 60В».
      local _sess_url="https://127.0.0.1:$CDN_FE_PORT${path%/}/sm-selfcheck-0000"
      local _sess_code="" _sess_head=""
      _sess_code=$(curl -sk -o /dev/null -w '%{http_code}' --max-time 6 "$_sess_url" -H "Host: $origin" 2>/dev/null || true)
      _sess_code="${_sess_code:-000}"
      _sess_head=$(curl -sk --max-time 6 "$_sess_url" -H "Host: $origin" 2>/dev/null | head -c 15 || true)
      if [[ "$_sess_code" == "200" && "$_sess_head" == "<"* ]]; then
        warn "  CDN #$id: Р·Р°РїСЂРѕСЃ РЎР•РЎРЎРР ($path/<sid>) РїРѕР»СѓС‡Р°РµС‚ HTML decoy вЂ” РќР• РґРѕС…РѕРґРёС‚ РґРѕ xray!"
        warn "     Р’ Р±Р»РѕРєРµ РЅРµС‚ location ^~ $path/ вЂ” РїСЂРѕРіРѕРЅРё В«РЎРІРµСЂРёС‚СЊ Рё РїРѕС‡РёРЅРёС‚СЊВ» (Рї.2 в†’ 4 в†’ 1)"
      elif [[ "$_sess_code" == "000" || "$_sess_code" == "502" || "$_sess_code" == "503" ]]; then
        warn "  CDN #$id: СЃРµСЃСЃРёСЏ $path/<sid> в†’ $_sess_code вЂ” xray РЅРµ РїСЂРёРЅСЏР» (РїСЂРѕРІРµСЂСЊ x-ui Рё РїРѕСЂС‚ РёРЅР±Р°СѓРЅРґР°)"
      else
        : # СЂСѓС‚РёРЅР°: СЃРµСЃСЃРёСЏ РґРѕС…РѕРґРёС‚ РґРѕ xray вЂ” РјРѕР»С‡Р°
      fi
      code=$(curl -sk -o /dev/null -w '%{http_code}' --max-time 6 "https://127.0.0.1:$CDN_FE_PORT/ne-pyt" -H "Host: $origin" 2>/dev/null || true)
      code="${code:-000}"
      # 404 РѕС‚ decoy вЂ” РЅРѕСЂРјР°: UA-Р±Р»РѕРє РѕС‚РґР°С‘С‚ РїСѓСЃС‚СѓСЋ 404 СЃРєР°РЅРµСЂР°Рј (curl/wget)
      if [[ "$code" == "200" || "$code" == "301" || "$code" == "302" || "$code" == "401" || "$code" == "403" || "$code" == "404" ]]; then
        : # СЂСѓС‚РёРЅР°: РїСЂРѕС‡РёРµ РїСѓС‚Рё СѓС…РѕРґСЏС‚ РІ decoy вЂ” РјРѕР»С‡Р°
      else
        warn "  CDN #$id: РїСЂРѕС‡РёРµ РїСѓС‚Рё в†’ $code (РѕР¶РёРґР°Р»СЃСЏ decoy) вЂ” РїСЂРѕРІРµСЂСЊ decoy-Р±Р»РѕРє $origin"
      fi
    fi
  done
  # noreload=1 вЂ” РІС‹Р·РѕРІ РёР· СЃРµСЂРµРґРёРЅС‹ Рї.1: nginx С‚Р°Рј РµС‰С‘ РѕСЃС‚Р°РЅРѕРІР»РµРЅ, Р° РїРѕРґРЅРёРјР°С‚СЊ РµРіРѕ
  # РѕР±СЏР·Р°РЅ С€С‚Р°С‚РЅС‹Р№ С€Р°Рі РџРћРЎР›Р• ensure_stream_include Рё РІСЃРµС… РїСЂР°РІРѕРє РєРѕРЅС„РёРіРѕРІ, РёРЅР°С‡Рµ
  # stream-СЃРµРєС†РёСЏ (443/SNI-СЂРѕСѓС‚РµСЂ) РЅРµ Р·Р°РіСЂСѓР·РёС‚СЃСЏ Рё СЃРЅР°СЂСѓР¶Рё РІСЃС‘ Р±СѓРґРµС‚ РЅРµРґРѕСЃС‚СѓРїРЅРѕ.
  if (( ! noreload )); then
    (( fixed )) && nginx_reload || true
  fi
  return 0
}

# РџСЂРѕРІРµСЂРёС‚СЊ, РЅРµ Р·Р°РЅСЏС‚ Р»Рё РґРѕРјРµРЅ ORIGIN СЃСѓС‰РµСЃС‚РІСѓСЋС‰РµР№ РЅР°СЃС‚СЂРѕР№РєРѕР№ РїР°РЅРµР»Рё:
# hosts-Р·Р°РїРёСЃСЏРјРё Рё SNI/host-РїРѕР»СЏРјРё Р°РєС‚РёРІРЅС‹С… РёРЅР±Р°СѓРЅРґРѕРІ. skip_id РЅСѓР¶РµРЅ
# РїСЂРё СЂРµРґР°РєС‚РёСЂРѕРІР°РЅРёРё С‚РµРєСѓС‰РµРіРѕ CDN-РёРЅР±Р°СѓРЅРґР°, С‡С‚РѕР±С‹ РѕРЅ РЅРµ РєРѕРЅС„Р»РёРєС‚РѕРІР°Р» СЃР°Рј СЃ СЃРѕР±РѕР№.
cdn_origin_in_panel() {   # <domain> [skip_inbound_id]
  local domain="${1,,}" skip_id="${2:-0}"
  [[ -n "$domain" && -f "$XUI_DB" ]] || return 1
  sqlite3 "$XUI_DB" "
    SELECT 1 FROM hosts
      WHERE lower(COALESCE(address,''))='$domain'
         OR lower(COALESCE(sni,''))='$domain'
         OR lower(COALESCE(host_header,''))='$domain'
    UNION ALL
    SELECT 1 FROM inbounds
      WHERE enable=1 AND id!=$skip_id AND (
        lower(COALESCE(json_extract(stream_settings,'$.tlsSettings.serverName'),''))='$domain'
        OR lower(COALESCE(json_extract(stream_settings,'$.xhttpSettings.host'),''))='$domain'
        OR EXISTS (SELECT 1 FROM json_each(COALESCE(json_extract(stream_settings,'$.realitySettings.serverNames'),'[]'))
                   WHERE lower(value)='$domain')
      ) LIMIT 1;" 2>/dev/null | grep -q 1
}

# Р’РѕРїСЂРѕСЃС‹ CDN-РїСЂРѕС„РёР»СЏ: РґРѕРјРµРЅС‹ + РїСѓС‚СЊ + С€Р°Р±Р»РѕРЅ decoy. Р—Р°РїРѕР»РЅСЏРµС‚ РіР»РѕР±Р°Р»СЊРЅС‹Рµ
# CDN_ORIGIN/CDN_DOM/CDN_PATH/CDN_TPL. РќРµ-TTY в†’ РґРµС‚РµСЂРјРёРЅРёСЂРѕРІР°РЅРЅС‹Рµ РґРµС„РѕР»С‚С‹.
# РџСЂРѕРІР°Р№РґРµСЂ CDN вЂ” РєС‚Рѕ С‚РµСЂРјРёРЅРёСЂСѓРµС‚ TLS РѕС‚ РєР»РёРµРЅС‚РѕРІ РїРµСЂРµРґ РЅР°С€РёРј nginx:
#   beget | yandex | other. Р’Р»РёСЏРµС‚ РЅР° РїРѕРґСЃРєР°Р·РєРё РЅР°СЃС‚СЂРѕР№РєРё Сѓ РїСЂРѕРІР°Р№РґРµСЂР°,
#   СЃРѕС…СЂР°РЅСЏРµС‚СЃСЏ 8-Рј РїРѕР»РµРј CDN-РїСЂРѕС„РёР»СЏ. CDN_PRE_PROVIDER Р·Р°РґР°С‘С‚ РѕС‚РІРµС‚ Р·Р°СЂР°РЅРµРµ
#   (РЅРµРёРЅС‚РµСЂР°РєС‚РёРІРЅС‹Рµ СЃС†РµРЅР°СЂРёРё), РїСѓСЃС‚Рѕ/РЅРµ-TTY в†’ other.
cdn_ask_provider() {   # в†’ CDN_PROVIDER
  if [[ -n "${CDN_PRE_PROVIDER:-}" ]]; then
    CDN_PROVIDER="$CDN_PRE_PROVIDER"
    return 0
  fi
  if [[ ! -t 0 ]]; then
    CDN_PROVIDER="other"
    return 0
  fi
  local pv=""
  echo
  echo "  РџСЂРѕРІР°Р№РґРµСЂ CDN (РєС‚Рѕ РїСЂРёРЅРёРјР°РµС‚ TLS РѕС‚ РєР»РёРµРЅС‚РѕРІ РїРµСЂРµРґ СЃРµСЂРІРµСЂРѕРј):"
  echo "   1) Beget"
  echo "   2) Yandex Cloud"
  echo "   3) Р”СЂСѓРіРѕР№ / СЃРІРѕР№"
  ask pv "Р’С‹Р±РѕСЂ [1/2/3]" "1" '^[123]$'
  case "$pv" in
    2) CDN_PROVIDER="yandex" ;;
    3) CDN_PROVIDER="other" ;;
    *) CDN_PROVIDER="beget" ;;
  esac
}

cdn_ask_profile() {   # <id> <proto>
  local id="$1" proto="$2" base="${PANEL_DOMAIN:-$(xui_get webDomain 2>/dev/null || true)}"
  [[ "$base" == *.example.* ]] && base="exemple.com"
  cdn_ask_provider
  case "$CDN_PROVIDER" in
    beget)
      echo "  Beget: РІ РїР°РЅРµР»Рё Beget РІРєР»СЋС‡Рё CDN РґР»СЏ cdn-РґРѕРјРµРЅР° (CNAME РЅР° РёС… edge),"
      echo "  origin = ORIGIN-РґРѕРјРµРЅ, HTTPS Рє origin РЅР° РїРѕСЂС‚ 443, РєСЌС€ РІС‹РєР»СЋС‡Рё"
      echo "  (РїСЂР°РІРёР»Рѕ В«РЅРµ РєСЌС€РёСЂРѕРІР°С‚СЊВ»), POST/uploads СЂР°Р·СЂРµС€РµРЅС‹ (packet-up)."
      ;;
    yandex)
      echo "  Yandex Cloud: СЃРѕР·РґР°Р№ CDN-СЂРµСЃСѓСЂСЃ вЂ” origin = ORIGIN-РґРѕРјРµРЅ (HTTPS, РїРѕСЂС‚ 443),"
      echo "  РґРѕРїРѕР»РЅРёС‚РµР»СЊРЅС‹Р№ РґРѕРјРµРЅ = cdn-РґРѕРјРµРЅ (CNAME в†’ *.edgecdn.ru), СЃРµСЂС‚РёС„РёРєР°С‚ РЅР° СЃС‚РѕСЂРѕРЅРµ"
      echo "  РЇРЅРґРµРєСЃР° (LE РѕС‚ РЇРЅРґРµРєСЃР° РёР»Рё СЃРІРѕР№), РєСЌС€ РІС‹РєР»СЋС‡Рё, Host/SNI Рє origin = ORIGIN."
      ;;
  esac
  if [[ -n "${CDN_PRE_CDN:-}" && -n "${CDN_PRE_ORIGIN:-}" ]]; then
    CDN_DOM="$CDN_PRE_CDN"; CDN_ORIGIN="$CDN_PRE_ORIGIN"
  else
    echo
    echo -e "${B}CDN-РїСЂРѕС„РёР»СЊ #$id ($proto, transport=xhttp):${N}"
    ask CDN_DOM   "Р”РѕРјРµРЅ, РїСЂРёРІСЏР·Р°РЅРЅС‹Р№ Рє CDN (РЅР°РїСЂРёРјРµСЂ cdn.$base)"  "cdn.$base"  '^[a-zA-Z0-9.-]+$'
    ask CDN_ORIGIN "ORIGIN-РґРѕРјРµРЅ (A-Р·Р°РїРёСЃСЊ в†’ СЌС‚РѕС‚ СЃРµСЂРІРµСЂ)"          "$base"   '^[a-zA-Z0-9.-]+$'
  fi
  # ORIGIN РЅРµ РґРѕР»Р¶РµРЅ СЃРѕРІРїР°РґР°С‚СЊ РЅРё СЃ РѕРґРЅРёРј РґРѕРјРµРЅРѕРј, СѓР¶Рµ Р·Р°РЅСЏС‚С‹Рј РїР°РЅРµР»СЊСЋ.
  if cdn_origin_in_panel "$CDN_ORIGIN"; then
    warn "ORIGIN $CDN_ORIGIN СѓР¶Рµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РІ РЅР°СЃС‚СЂРѕР№РєР°С… РїР°РЅРµР»Рё/РёРЅР±Р°СѓРЅРґРѕРІ. Р’С‹Р±РµСЂРё РѕС‚РґРµР»СЊРЅС‹Р№ СЃРІРѕР±РѕРґРЅС‹Р№ РґРѕРјРµРЅ, РёРЅР°С‡Рµ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ SNI/РјР°СЂС€СЂСѓС‚ РјРѕР¶РµС‚ СЃР»РѕРјР°С‚СЊСЃСЏ."
    return 1
  fi
  local def_path; def_path=$(cdn_default_path "$CDN_ORIGIN")
  if [[ -n "${CDN_PRE_PATH:-}" ]]; then
    CDN_PATH="$CDN_PRE_PATH"
  else
    local pm=""
    if [[ -t 0 ]]; then
      echo
      echo "  РџСѓС‚СЊ С‚СЂР°РЅСЃРїРѕСЂС‚Р° (СЃРµРєСЂРµС‚РЅС‹Р№ РјР°СЂС€СЂСѓС‚ xray):"
      echo "   1) РџРѕ РґРѕРјРµРЅСѓ: $def_path"
      echo "   2) РЎРіРµРЅРµСЂРёСЂРѕРІР°С‚СЊ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё"
      echo "   3) Р’РІРµСЃС‚Рё РІСЂСѓС‡РЅСѓСЋ"
      ask pm "Р’С‹Р±РѕСЂ [1/2/3]" "1" '^[123]$'
    else
      pm="1"
    fi
    case "$pm" in
      2) CDN_PATH="/api/stream/$(gen_hex 6).m3u8" ;;
      3) ask CDN_PATH "РџСѓС‚СЊ (РЅР°С‡РёРЅР°РµС‚СЃСЏ СЃ /)" "$def_path" '^/[A-Za-z0-9._/-]+$' ;;
      *) CDN_PATH="$def_path" ;;
    esac
  fi
  CDN_TPL="${CDN_PRE_TPL:-${SELECTED_DECOY_TPL:-corporate}}"
  if [[ -t 0 && -z "${CDN_PRE_TPL:-}" ]]; then
    # РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РїСЂРµРґР»Р°РіР°РµРј РѕР±С‰РёР№ С€Р°Р±Р»РѕРЅ, РІС‹Р±СЂР°РЅРЅС‹Р№ СЂР°РЅРµРµ РІ Р°РЅРєРµС‚Рµ Рї.1
    decoy_template_choose CDN_TPL "Decoy РґР»СЏ ORIGIN $CDN_ORIGIN (РІСЃС‘, РєСЂРѕРјРµ РїСѓС‚Рё С‚СЂР°РЅСЃРїРѕСЂС‚Р°)" "${SELECTED_DECOY_TPL:-corporate}"
  fi
}

# Р’РѕРїСЂРѕСЃ РїСЂРѕ CDN + РЅР°СЃС‚СЂРѕР№РєР° CDN-РїСЂРѕС„РёР»СЏ. Р’РѕР·РІСЂР°С‰Р°РµС‚:
#   0 вЂ” РёРЅР±Р°СѓРЅРґ РЅР°СЃС‚СЂРѕРµРЅ РєР°Рє CDN (РІС‹Р·РІР°РІС€РµРјСѓ РїСѓРЅРєС‚Сѓ РґР°Р»СЊС€Рµ РЅРёС‡РµРіРѕ РґРµР»Р°С‚СЊ РЅРµ РЅР°РґРѕ)
#   1 вЂ” РЅРµ xhttp-РєР°РЅРґРёРґР°С‚ РёР»Рё РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ РѕС‚РІРµС‚РёР» В«РЅРµС‚В» (РїСЂРѕРґРѕР»Р¶РёС‚СЊ РѕР±С‹С‡РЅСѓСЋ Р»РѕРіРёРєСѓ)
# CDN-РІР°СЂРёР°РЅС‚ СЃРѕР·РґР°С‘С‚СЃСЏ РєР°Рє VLESS+XHTTP СЃ security=none (HTTP Рє Xray Р·Р° nginx).
# XHTTP+TLS Рё XHTTP+Reality РѕСЃС‚Р°СЋС‚СЃСЏ РѕС‚РґРµР»СЊРЅС‹РјРё СЂРµР¶РёРјР°РјРё.
xhttp_cdn_setup() {   # <inbound_id> <proto> <port>
  local id="$1" proto="$2" port="$3"
  [[ "$proto" != "vless" ]] && return 1
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" || -z "$id" ]] && return 1
  local stream=""
  stream=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  inbound_is_xhttp_cdn_candidate "$stream" || return 1
  # Р—Р°С‰РёС‚РЅР°СЏ РїСЂРѕРІРµСЂРєР° Р”Рћ РјРµРЅСЋ: TLS/Reality РЅРµ РїРµСЂРµРІРѕРґРёРј РІ CDN/plain.
  inbound_xhttp_has_tls_or_reality "$stream" && return 1
  inbound_was_created_as_tls_xhttp "$id" && return 1
  # Р›СЋР±РѕР№ СЂРµР°Р»СЊРЅС‹Р№ TLS/Reality РІ stream_settings РёСЃРєР»СЋС‡Р°РµС‚ CDN-РІРѕРїСЂРѕСЃ.
  # РСЃРєР»СЋС‡РµРЅРёРµ РїРѕ РІСЂРµРјРµРЅРЅРѕРјСѓ ID РЅСѓР¶РЅРѕ РґР»СЏ TLS-РєРѕРЅС„РёРіСѓСЂР°С†РёР№ LucX, РіРґРµ security
  # РјРѕР¶РµС‚ РЅРµ СЃРµСЂРёР°Р»РёР·РѕРІР°С‚СЊСЃСЏ РєР°Рє РѕР¶РёРґР°РµС‚СЃСЏ СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ СЃРѕР·РґР°РЅРёСЏ.
  inbound_xhttp_has_tls_or_reality "$stream" && return 1
  inbound_was_created_as_tls_xhttp "$id" && return 1
  local _was_tls=false
  # XHTTP TLS вЂ” РѕС‚РґРµР»СЊРЅС‹Р№ СЂРµР¶РёРј. CDN РґР»СЏ РЅРµРіРѕ РЅРµ РїСЂРµРґР»Р°РіР°РµРј Рё РЅРµ РїРµСЂРµРІРѕРґРёРј
  # security=tls РІ security=none: TLS РґРѕР»Р¶РµРЅ РѕСЃС‚Р°РІР°С‚СЊСЃСЏ РЅР° Xray.
  [[ "$_was_tls" == true ]] && return 1
  echo
  echo -e "${B}РРЅР±Р°СѓРЅРґ #$id ($proto): transport=xhttp${N}"
  local use_cdn=""
  if [[ -n "${CDN_PRE_ANSWER:-}" ]]; then
    use_cdn="$CDN_PRE_ANSWER"
  elif [[ "$_was_tls" == true && -t 0 ]]; then
    warn "  РЎРµР№С‡Р°СЃ РІ РёРЅР±Р°СѓРЅРґРµ security=tls (TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ Xray)."
    warn "  CDN-СЂРµР¶РёРј РїРµСЂРµРІРµРґС‘С‚ РµРіРѕ РІ security=none: TLS Р±СѓРґРµС‚ С‚РµСЂРјРёРЅРёСЂРѕРІР°С‚СЊ nginx,"
    warn "  xray РѕСЃС‚Р°РЅРµС‚СЃСЏ РіРѕР»С‹Рј РЅР° 127.0.0.1 вЂ” РєР»РёРµРЅС‚С‹, Сѓ РєРѕС‚РѕСЂС‹С… РїСЂРѕС€Р»Р°СЏ СЃСЃС‹Р»РєР°,"
    warn "  РїРѕСЃР»Рµ СЌС‚РѕРіРѕ РїРѕРґРєР»СЋС‡Р°СЋС‚СЃСЏ С‚РѕР»СЊРєРѕ С‡РµСЂРµР· nginx/CDN-РјР°СЂС€СЂСѓС‚."
    askyn use_cdn "Р­С‚Рѕ СЃРѕРµРґРёРЅРµРЅРёРµ Р±СѓРґРµС‚ СЂР°Р±РѕС‚Р°С‚СЊ С‡РµСЂРµР· CDN?" "n"
  else
    askyn use_cdn "Р­С‚Рѕ СЃРѕРµРґРёРЅРµРЅРёРµ Р±СѓРґРµС‚ СЂР°Р±РѕС‚Р°С‚СЊ С‡РµСЂРµР· CDN?" "n"
  fi
  if [[ "$use_cdn" != true ]]; then
    log "  CDN РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ вЂ” РѕР±С‹С‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° (Р°РґСЂРµСЃ/SNI = SNI-РґРѕРјРµРЅ)"
    return 1
  fi

  # --- РІРѕРїСЂРѕСЃС‹: CDN/ORIGIN-РґРѕРјРµРЅС‹, РїСѓС‚СЊ С‚СЂР°РЅСЃРїРѕСЂС‚Р°, С€Р°Р±Р»РѕРЅ decoy ---
  cdn_ask_profile "$id" "$proto"
  local cdn_dom="$CDN_DOM" origin_dom="$CDN_ORIGIN" new_path="$CDN_PATH" _cdn_tpl="$CDN_TPL"

  # --- СЃРµСЂС‚ РґР»СЏ ORIGIN: TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx ---
  local cp_line="" cert="" key=""
  cp_line=$(cert_paths "$origin_dom") || true
  # Р”Р»СЏ ORIGIN=РґРѕРјРµРЅР° РїР°РЅРµР»Рё РёСЃРїРѕР»СЊР·СѓРµРј СѓР¶Рµ РЅР°СЃС‚СЂРѕРµРЅРЅС‹Р№ СЃРµСЂС‚РёС„РёРєР°С‚ РїР°РЅРµР»Рё.
  # cert_paths РјРѕР¶РµС‚ РЅРµ РІРёРґРµС‚СЊ РµРіРѕ РёР·-Р·Р° СЂР°Р·РЅС‹С… Р·Р°РїРёСЃРµР№ РІ LucX, РїРѕСЌС‚РѕРјСѓ
  # Р±РµСЂС‘Рј РїР°СЂСѓ РїСѓС‚РµР№ РЅРµРїРѕСЃСЂРµРґСЃС‚РІРµРЅРЅРѕ РёР· webDomain/settings.
  local _panel_dom="${PANEL_DOMAIN:-}"
  [[ -z "$_panel_dom" ]] && _panel_dom=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$_panel_dom" ]] && _panel_dom=$(xui_get subDomain 2>/dev/null || true)
  if [[ -z "$cp_line" && -n "$_panel_dom" && "$origin_dom" == "$_panel_dom" ]]; then
    cert=$(xui_get webCertFile 2>/dev/null || true)
    key=$(xui_get webKeyFile 2>/dev/null || true)
    [[ -z "$key" ]] && key=$(xui_get subKeyFile 2>/dev/null || true)
    [[ -f "$cert" && -f "$key" ]] && cp_line="$cert $key"
  fi
  if [[ -z "$cp_line" ]]; then
    cert_issue "$origin_dom" >/dev/null 2>&1 || true
    cp_line=$(cert_paths "$origin_dom") || true
  fi
  if [[ -z "$cp_line" ]]; then
    warn "  СЃРµСЂС‚ РґР»СЏ $origin_dom РЅРµ РІС‹РїСѓС‰РµРЅ вЂ” nginx-С„СЂРѕРЅС‚РµРЅРґ РЅРµ РЅР°СЃС‚СЂР°РёРІР°СЋ."
    warn "  Р’С‹РїРёС€Рё СЃРµСЂС‚ (РЎРµСЂС‚РёС„РёРєР°С‚С‹ в†’ РѕР±РЅРѕРІРёС‚СЊ) Рё РїРѕРІС‚РѕСЂРё РїСѓРЅРєС‚; РёРЅР±Р°СѓРЅРґ РЅРµ РјРµРЅСЏР»СЃСЏ."
    return 1
  fi
  if ! cert_preflight "$origin_dom" >/dev/null 2>&1 && [[ "$origin_dom" != "$_panel_dom" ]]; then
    warn "  СЃРµСЂС‚РёС„РёРєР°С‚ ORIGIN $origin_dom РЅРµ РїСЂРѕС€С‘Р» СЃС‚СЂРѕРіСѓСЋ РїСЂРѕРІРµСЂРєСѓ вЂ” CDN РЅРµ РїСЂРёРјРµРЅС‘РЅ"
    return 1
  fi
  [[ -z "$cert" ]] && cert="${cp_line%% *}"
  [[ -z "$key" ]] && key="${cp_line##* }"
  cert="${cp_line%% *}"; key="${cp_line##* }"

  # --- РїСЂР°РІРєРё Р‘Р” вЂ” С‚РѕР»СЊРєРѕ РїСЂРё РѕСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕР№ РїР°РЅРµР»Рё ---
  local xui_was=""
  if systemctl is-active --quiet x-ui 2>/dev/null; then
    xui_was=1
    systemctl stop x-ui >/dev/null 2>&1 || true
    sleep 1
  fi
  panel_journal_capture_row inbounds "$id"   # СЃРЅРёРјРѕРє СЃС‚СЂРѕРєРё РґР»СЏ РѕС‚РєР°С‚Р° (Рї.2/Рї.3)
  audit "cdn:inbound=$id proto=$proto origin=$origin_dom cdn=$cdn_dom path=$new_path"
  db_protect_suspend   # РѕСЃРѕР·РЅР°РЅРЅС‹Р№ РїРµСЂРµРІРѕРґ РёРЅР±Р°СѓРЅРґР° РІ CDN-СЂРµР¶РёРј
  # 1) security в†’ none, tlsSettings/externalProxy в†’ СѓРґР°Р»РёС‚СЊ (TLS С‚РµРїРµСЂСЊ Сѓ nginx,
  #    externalProxy СѓРІС‘Р» Р±С‹ С‚СЂР°С„РёРє РјРёРјРѕ nginx-РјР°СЂС€СЂСѓС‚Р°), xhttp-РїР°СЂР°РјРµС‚СЂС‹ вЂ” РїРѕ README CDN:
  # РЈРІРµРґРѕРјР»РµРЅРёРµ Рѕ СѓРґР°Р»РµРЅРёРё externalProxy, РµСЃР»Рё РѕРЅРѕ Р±С‹Р»Рѕ
  if grep -q 'externalProxy' <<<""; then
    warn "  CDN #: externalProxy СѓРґР°Р»С‘РЅ РёР· stream settings (С‚СЂРµР±СѓРµС‚СЃСЏ РґР»СЏ CDN-СЂРµР¶РёРјР°, С‡С‚РѕР±С‹ С‚СЂР°С„РёРє С€С‘Р» С‡РµСЂРµР· nginx)."
  fi
  # РЈРІРµРґРѕРјР»РµРЅРёРµ Рѕ СѓРґР°Р»РµРЅРёРё externalProxy, РµСЃР»Рё РѕРЅРѕ Р±С‹Р»Рѕ
  if grep -q ""externalProxy"" <<<""; then
    warn "  CDN #: externalProxy СѓРґР°Р»С‘РЅ РёР· stream settings (С‚СЂРµР±СѓРµС‚СЃСЏ РґР»СЏ CDN-СЂРµР¶РёРјР°, С‡С‚РѕР±С‹ С‚СЂР°С„РёРє С€С‘Р» С‡РµСЂРµР· nginx)."
  fi
  local sql="UPDATE inbounds SET stream_settings=json_set(json_remove(stream_settings,'\$.security','\$.tlsSettings','\$.externalProxy'),"
  sql+="'\$.security','none',"
  sql+="'\$.xhttpSettings.host','$origin_dom',"
  sql+="'\$.xhttpSettings.path','$new_path',"
  sql+="'\$.xhttpSettings.mode','packet-up',"
  sql+="'\$.xhttpSettings.uplinkHTTPMethod','GET',"
  sql+="'\$.xhttpSettings.uplinkChunkSize',2048,"
  sql+="'\$.xhttpSettings.uplinkDataPlacement','header',"
  sql+="'\$.xhttpSettings.uplinkDataKey','X-Data',"
  sql+="'\$.xhttpSettings.xPaddingBytes','100-1000',"
  sql+="'\$.xhttpSettings.xPaddingPlacement','queryInHeader',"
  sql+="'\$.xhttpSettings.xPaddingHeader','X-Cache',"
  sql+="'\$.xhttpSettings.xPaddingKey','_dc',"
  sql+="'\$.xhttpSettings.xPaddingMethod','tokenish',"
  sql+="'\$.xhttpSettings.xPaddingObfsMode',json('true'),"
  sql+="'\$.xhttpSettings.xmux',json('{\"maxConnections\":2,\"hKeepAliveMs\":30000,\"h2KeepAliveIdleMs\":1000,\"h2KeepAliveIntervalMs\":1000}'),"
  sql+="'\$.xhttpSettings.scMaxBufferedPosts',30)"
  sql+=" WHERE id=$id;"
  local err_out
  err_out=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "$sql" 2>&1) || {
    err "SQL: $err_out"; [[ "$xui_was" == 1 ]] && systemctl start x-ui >/dev/null 2>&1; return 1;
  }
  db_set_listen "$id" '127.0.0.1' direct 2>/dev/null || true
  db_protect_resume   # Р·Р°С‰РёС‰С‘РЅРЅС‹Рµ РєР»СЋС‡Рё (security/dest/xhttp-РїСѓС‚СЊ) Р·Р°РїРёСЃР°РЅС‹ вЂ” РІРµСЂРЅСѓС‚СЊ Р·Р°С‰РёС‚Сѓ

  # 2) decoy ORIGIN-РґРѕРјРµРЅР°: РІСЃС‘, С‡С‚Рѕ РЅРµ С‚СЂР°РЅСЃРїРѕСЂС‚РЅС‹Р№ РїСѓС‚СЊ, вЂ” СЃСЋРґР°
  local _cdn_decoy_port=$((47000 + id))
  while ss -tlnH "sport = :$_cdn_decoy_port" 2>/dev/null | grep -q .; do _cdn_decoy_port=$((_cdn_decoy_port+1)); done
  mk_decoy "$_cdn_decoy_port" "$origin_dom" "$cert" "$key" "/var/www/decoy-cdn-$id" "$_cdn_tpl" >/dev/null 2>&1 || _cdn_decoy_port=""
  if [[ -z "$_cdn_decoy_port" ]]; then
    warn "  decoy $origin_dom РЅРµ СЃРѕР·РґР°Р»СЃСЏ вЂ” РІРµСЃСЊ С‚СЂР°С„РёРє origin РїРѕР№РґС‘С‚ РІ xray-РјР°СЂС€СЂСѓС‚ (РїСѓС‚СЊ) РёР»Рё 404"
  fi

  # 3) nginx: РµРґРёРЅС‹Р№ TLS-С„СЂРѕРЅС‚РµРЅРґ + cdn-Р±Р»РѕРє (РїСѓС‚СЊ в†’ xray, РѕСЃС‚Р°Р»СЊРЅРѕРµ в†’ decoy)
  cdn_frontend_ensure "$origin_dom" "$cdn_dom"
  stack_cdn_upsert "$origin_dom" "$cdn_dom" "$new_path" "$port" "${_cdn_decoy_port:-0}" "$cert" "$key"

  # 4) СЃС‚Р°СЂР°СЏ SNI-РїСЂРёРІСЏР·РєР° РёРЅР±Р°СѓРЅРґР° Р±РѕР»СЊС€Рµ РЅРµ РЅСѓР¶РЅР°: РІС…РѕРґ С‚РѕР»СЊРєРѕ С‡РµСЂРµР· cdn_frontend
  sed -i "/^upstream inb_${id}_backend /d" "$SNI_CONF" 2>/dev/null || true
  sed -i "/^\s*[^[:space:]]\+[[:space:]]\+inb_${id}_backend;/d" "$SNI_CONF" 2>/dev/null || true
  unset "SNI_USED[inb_${id}_backend]" 2>/dev/null || true

  # 5) hosts: Р°РґСЂРµСЃ/SNI/Host header = CDN, security=tls (РґР»СЏ РєР»РёРµРЅС‚Р° В«TLS РµСЃС‚СЊВ»)
  hosts_cdn_upsert "$id" "$cdn_dom" "$proto"
  cdn_profile_save_add "$id" "$proto" "$origin_dom" "$cdn_dom" "$new_path" "$_cdn_tpl" "${_cdn_decoy_port:-0}" "$CDN_PROVIDER"

  [[ "$xui_was" == 1 ]] && { systemctl start x-ui >/dev/null 2>&1 || true; sleep 2; }
  nginx_reload || true
  # 6) СЃР°РјРѕРїСЂРѕРІРµСЂРєР° РјР°СЂС€СЂСѓС‚РёР·Р°С†РёРё (map/Р±Р»РѕРє/decoy + Р¶РёРІРѕР№ curl)
  cdn_repair
  echo
  log "CDN-РїСЂРѕС„РёР»СЊ РёРЅР±Р°СѓРЅРґР° #$id ($proto) РЅР°СЃС‚СЂРѕРµРЅ:"
  log "  ORIGIN: $origin_dom вЂ” nginx TLS (СЃРµСЂС‚ origin) в†’ РїСѓС‚СЊ $new_path РІ xray, РѕСЃС‚Р°Р»СЊРЅРѕРµ в†’ decoy ($_cdn_tpl)"
  log "  CDN:    $cdn_dom вЂ” hosts: Р°РґСЂРµСЃ/SNI/Host header = CDN, security=tls"
  log "  РРЅР±Р°СѓРЅРґ: security=none, listen=127.0.0.1:$port, mode=packet-up, GET+X-Data"
  log "  hosts: Р°РґСЂРµСЃ/SNI/Host header = $cdn_dom, security=tls"
  return 0
}

# РЎРЅСЏС‚СЊ CDN-СЂРµР¶РёРј СЃ РёРЅР±Р°СѓРЅРґР°: nginx-Р±Р»РѕРє, decoy, SNI-РјР°СЂС€СЂСѓС‚С‹ origin/cdn,
# hosts-Р·Р°РїРёСЃСЊ, РїСЂРѕС„РёР»СЊ. РЎР°Рј РёРЅР±Р°СѓРЅРґ РѕСЃС‚Р°С‘С‚СЃСЏ (security=none вЂ” РґР»СЏ РѕР±С‹С‡РЅРѕРіРѕ
# SNI-СЂРµР¶РёРјР° РїРѕС‚РѕРј РїСЂРѕРіРЅР°С‚СЊ В«РџРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґВ»).
cdn_disable_for_inbound() {   # <id>
  local id="$1"
  local row; row=$(cdn_profile_get "$id" 2>/dev/null)
  [[ -z "$row" ]] && { warn "РЈ РёРЅР±Р°СѓРЅРґР° #$id РЅРµС‚ CDN-РїСЂРѕС„РёР»СЏ"; return 1; }
  local origin cdn dport
  origin=$(printf '%s' "$row" | cut -d'|' -f3)
  cdn=$(printf '%s' "$row" | cut -d'|' -f4)
  dport=$(printf '%s' "$row" | cut -d'|' -f7)
  stack_cdn_del "$origin"
  [[ "$dport" =~ ^[0-9]+$ && "$dport" != "0" ]] && stack_del_decoy "$origin"
  sni_map_remove "$origin"
  [[ -n "$cdn" && "$cdn" != "$origin" ]] && sni_map_remove "$cdn"
  cdn_profile_remove "$id"
  if [[ ! -s "$CDN_PROFILES" ]]; then
    sed -i "/^upstream cdn_frontend /d" "$SNI_CONF" 2>/dev/null || true
  fi
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" "DELETE FROM hosts WHERE inbound_id=$id AND port=443;" 2>/dev/null || true
  hosts_owned_delete "$id" 443
  nginx_reload || true
  audit "cdn:removed inbound=$id origin=$origin cdn=$cdn"
  log "CDN-СЂРµР¶РёРј СЃРЅСЏС‚ СЃ #$id (origin=$origin, cdn=$cdn)"
  warn "РРЅР±Р°СѓРЅРґ #$id РѕСЃС‚Р°Р»СЃСЏ СЃ security=none вЂ” РґР»СЏ РѕР±С‹С‡РЅРѕРіРѕ SNI-СЂРµР¶РёРјР° РїСЂРѕРіРѕРЅРё В«РџРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґВ» (Рї.2 в†’ 4)."
  return 0
}

# РЎРјРµРЅРёС‚СЊ decoy CDN ORIGIN Р±РµР· РёР·РјРµРЅРµРЅРёСЏ CDN-РґРѕРјРµРЅРѕРІ Рё РїСѓС‚Рё.
cdn_change_decoy() {   # <id>
  local id="$1" row proto origin cdn path oldtpl dport port tpl cp cert key ndport
  row=$(cdn_profile_get "$id" 2>/dev/null) || return 1
  [[ -n "$row" ]] || { err "РЈ #$id РЅРµС‚ CDN-РїСЂРѕС„РёР»СЏ"; return 1; }
  proto=$(printf '%s' "$row" | cut -d'|' -f2); origin=$(printf '%s' "$row" | cut -d'|' -f3)
  cdn=$(printf '%s' "$row" | cut -d'|' -f4); path=$(printf '%s' "$row" | cut -d'|' -f5)
  oldtpl=$(printf '%s' "$row" | cut -d'|' -f6); dport=$(printf '%s' "$row" | cut -d'|' -f7)
  port=$(sqlite3 -noheader "$XUI_DB" "SELECT port FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  decoy_template_choose_impl tpl "Decoy РґР»СЏ ORIGIN $origin" "$oldtpl" || return 1
  tpl="${tpl:-$oldtpl}"
  cp=$(cert_paths "$origin" 2>/dev/null || true)
  [[ -z "$cp" && "$origin" == "$(xui_get webDomain 2>/dev/null || true)" ]] && cp="$(xui_get webCertFile) $(xui_get webKeyFile)"
  cert="${cp%% *}"; key="${cp##* }"
  [[ -f "$cert" && -f "$key" ]] || { err "РЎРµСЂС‚ ORIGIN $origin РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  [[ "$dport" =~ ^[0-9]+$ ]] || dport=$((47000 + id))
  ndport="$dport"
  while ss -tlnH "sport = :$ndport" 2>/dev/null | grep -q .; do ndport=$((ndport+1)); done
  [[ "$ndport" != "$dport" ]] && dport="$ndport"
  mk_decoy "$dport" "$origin" "$cert" "$key" "/var/www/decoy-cdn-$id" "$tpl" || return 1
  stack_cdn_upsert "$origin" "$cdn" "$path" "$port" "$dport" "$cert" "$key"
  cdn_profile_save_add "$id" "$proto" "$origin" "$cdn" "$path" "$tpl" "$dport" "$(printf '%s' "$row" | cut -d'|' -f8)"
  nginx_reload || true
  log "CDN ORIGIN $origin: decoy РѕР±РЅРѕРІР»С‘РЅ ($tpl)"
}

# РњРёРЅРё-РјРµРЅСЋ РґР»СЏ РёРЅР±Р°СѓРЅРґР°, Сѓ РєРѕС‚РѕСЂРѕРіРѕ CDN-РїСЂРѕС„РёР»СЊ СѓР¶Рµ РµСЃС‚СЊ.
cdn_existing_menu() {   # <id>
  local id="$1"
  log "РРЅР±Р°СѓРЅРґ #$id СѓР¶Рµ РІ CDN-СЂРµР¶РёРјРµ ($(cdn_provider_label "$(cdn_profile_provider "$id")")): $(cdn_profile_field "$id" 3) в†’ $(cdn_profile_field "$id" 4)"
  echo "   1) РЎРІРµСЂРёС‚СЊ Рё РїРѕС‡РёРЅРёС‚СЊ (РјР°СЂС€СЂСѓС‚/Р±Р»РѕРє/hosts/РїСѓС‚СЊ)"
  echo "   2) РџРµСЂРµРЅР°СЃС‚СЂРѕРёС‚СЊ (РґРѕРјРµРЅС‹/РїСѓС‚СЊ/С€Р°Р±Р»РѕРЅ decoy)"
  echo "   3) РЎРЅСЏС‚СЊ CDN-СЂРµР¶РёРј (РёРЅР±Р°СѓРЅРґ РѕСЃС‚Р°РЅРµС‚СЃСЏ)"
  echo "   0) РќРёС‡РµРіРѕ РЅРµ РґРµР»Р°С‚СЊ"
  local a=""
  ask a "Р’С‹Р±РѕСЂ" "1" '^[0-3]$'
  case "$a" in
    1) cdn_repair ;;
    2) cdn_change_profile "$id" ;;
    3) cdn_disable_for_inbound "$id" ;;
  esac
  return 0
}

# РџРµСЂРµРЅР°СЃС‚СЂРѕР№РєР° СЃСѓС‰РµСЃС‚РІСѓСЋС‰РµРіРѕ CDN-РїСЂРѕС„РёР»СЏ: РґРѕРјРµРЅС‹/РїСѓС‚СЊ/С€Р°Р±Р»РѕРЅ. РРЅР±Р°СѓРЅРґ С‚РѕС‚ Р¶Рµ,
# РєР»РёРµРЅС‚С‹ РїРѕР»СѓС‡Р°СЋС‚ РЅРѕРІСѓСЋ СЃСЃС‹Р»РєСѓ РёР· hosts (Р°РґСЂРµСЃ = CDN-РґРѕРјРµРЅ).
cdn_change_profile() {   # <id>
  local id="$1"
  local row; row=$(cdn_profile_get "$id" 2>/dev/null)
  [[ -z "$row" ]] && { err "РЈ РёРЅР±Р°СѓРЅРґР° #$id РЅРµС‚ CDN-РїСЂРѕС„РёР»СЏ"; return 1; }
  local proto origin cdn path tpl dport port
  proto=$(printf '%s' "$row" | cut -d'|' -f2)
  origin=$(printf '%s' "$row" | cut -d'|' -f3)
  cdn=$(printf '%s' "$row" | cut -d'|' -f4)
  path=$(printf '%s' "$row" | cut -d'|' -f5)
  tpl=$(printf '%s' "$row" | cut -d'|' -f6)
  dport=$(printf '%s' "$row" | cut -d'|' -f7)
  port=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT port FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  echo "  РџСЂРѕС„РёР»СЊ #$id: $proto В· origin=$origin В· cdn=$cdn В· РїСѓС‚СЊ=$path В· decoy=${dport:-0} В· С€Р°Р±Р»РѕРЅ=$tpl В· РїСЂРѕРІР°Р№РґРµСЂ=$(cdn_provider_label "$(printf '%s' "$row" | cut -d'|' -f8)")"
  echo
  echo "   1) РЎРјРµРЅРёС‚СЊ РґРѕРјРµРЅС‹ (CDN Рё/РёР»Рё origin)"
  echo "   2) РЎРјРµРЅРёС‚СЊ РїСѓС‚СЊ"
  echo "   3) РЎРјРµРЅРёС‚СЊ С€Р°Р±Р»РѕРЅ decoy"
  echo "   4) Р’СЃС‘ Р·Р°РЅРѕРІРѕ (РїРѕР»РЅС‹Рµ РІРѕРїСЂРѕСЃС‹)"
  echo "   0) РћС‚РјРµРЅР°"
  local a=""
  ask a "Р’С‹Р±РѕСЂ" "0" '^[0-4]$'
  [[ "$a" == "0" ]] && return 0
  local n_origin="$origin" n_cdn="$cdn" n_path="$path" n_tpl="$tpl"
  local n_prov; n_prov=$(printf '%s' "$row" | cut -d'|' -f8)
  case "$a" in
    1)
      ask n_cdn    "РќРѕРІС‹Р№ РґРѕРјРµРЅ, РїСЂРёРІСЏР·Р°РЅРЅС‹Р№ Рє CDN" "$cdn" '^[a-zA-Z0-9.-]+$'
      ask n_origin "РќРѕРІС‹Р№ ORIGIN-РґРѕРјРµРЅ (A-Р·Р°РїРёСЃСЊ в†’ СЌС‚РѕС‚ СЃРµСЂРІРµСЂ)" "$origin" '^[a-zA-Z0-9.-]+$'
      ;;
    2)
      ask n_path "РќРѕРІС‹Р№ РїСѓС‚СЊ (РЅР°С‡РёРЅР°РµС‚СЃСЏ СЃ /)" "$(cdn_default_path "$(cdn_base_from_origin "$origin")")" '^/[A-Za-z0-9._/-]+$'
      ;;
    3)
      ask n_tpl "РЁР°Р±Р»РѕРЅ decoy (РёРјСЏ РєР°С‚Р°Р»РѕРіР° РёР»Рё custom:/РїСѓС‚СЊ/Рє/СЃР°Р№С‚Сѓ)" "$tpl" '.+'
      ;;
    4)
      CDN_PRE_CDN=""; CDN_PRE_ORIGIN=""; CDN_PRE_ANSWER=""
      cdn_ask_profile "$id" "$proto"
      n_cdn="$CDN_DOM"; n_origin="$CDN_ORIGIN"; n_path="$CDN_PATH"; n_tpl="$CDN_TPL"; n_prov="$CDN_PROVIDER"
      ;;
  esac
  # РџСЂРё СЂРµРґР°РєС‚РёСЂРѕРІР°РЅРёРё СЂР°Р·СЂРµС€Р°РµРј СЃРѕС…СЂР°РЅРёС‚СЊ С‚РµРєСѓС‰РёР№ ORIGIN СЌС‚РѕРіРѕ РїСЂРѕС„РёР»СЏ,
  # РЅРѕ Р±Р»РѕРєРёСЂСѓРµРј РґРѕРјРµРЅС‹, РёСЃРїРѕР»СЊР·СѓРµРјС‹Рµ Р»СЋР±С‹РјРё РґСЂСѓРіРёРјРё panel/inbound-РЅР°СЃС‚СЂРѕР№РєР°РјРё.
  if cdn_origin_in_panel "$n_origin" "$id"; then
    err "ORIGIN $n_origin СѓР¶Рµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РЅР°СЃС‚СЂРѕР№РєР°РјРё РїР°РЅРµР»Рё/РґСЂСѓРіРѕРіРѕ РёРЅР±Р°СѓРЅРґР°. РЈРєР°Р¶Рё СЃРІРѕР±РѕРґРЅС‹Р№ РѕС‚РґРµР»СЊРЅС‹Р№ РґРѕРјРµРЅ, С‡С‚РѕР±С‹ РЅРµ РЅР°СЂСѓС€РёС‚СЊ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ SNI/РјР°СЂС€СЂСѓС‚."
    return 1
  fi
  [[ "$n_origin" == "$origin" && "$n_cdn" == "$cdn" && "$n_path" == "$path" && "$n_tpl" == "$tpl" ]] && {
    warn "РќРёС‡РµРіРѕ РЅРµ РёР·РјРµРЅРёР»РѕСЃСЊ"; return 0; }

  # СЃРµСЂС‚С‹ РїРѕРґ РЅРѕРІС‹Р№ origin
  if [[ "$n_origin" != "$origin" ]] && ! cert_paths "$n_origin" >/dev/null 2>&1; then
    log "РЎС‘СЂС‚Р° РґР»СЏ $n_origin РЅРµС‚ вЂ” РІС‹РїСѓСЃРєР°СЋ (certbot)"
    cert_issue "$n_origin" || { err "РЎРµСЂС‚ $n_origin РЅРµ РІС‹РїСѓС‰РµРЅ вЂ” CDN-Р±Р»РѕРє РЅРµ СЃРѕР±СЂР°С‚СЊ"; return 1; }
  fi
  local cp_line cert="" key=""
  cp_line=$(cert_paths "$n_origin") || true
  [[ -n "$cp_line" ]] && { cert="${cp_line%% *}"; key="${cp_line##* }"; }
  [[ -z "$cert" ]] && { err "РќРµС‚ СЃРµСЂС‚Р° РґР»СЏ $n_origin вЂ” РІС‹РїСѓСЃС‚Рё С‡РµСЂРµР· Рї.10 Рё РїРѕРІС‚РѕСЂРё"; return 1; }

  echo "  РџР»Р°РЅ: $origin/$cdn в†’ $n_origin/$n_cdn В· РїСѓС‚СЊ в†’ $n_path В· decoy в†’ $n_tpl"
  local go=""
  askyn go "РџСЂРёРјРµРЅРёС‚СЊ? (РїР°РЅРµР»СЊ РєСЂР°С‚РєРѕ РѕСЃС‚Р°РЅРѕРІРёС‚СЃСЏ)" "y"
  [[ "$go" == true ]] || return 0
  auto_backup_stack >/dev/null 2>&1 || true

  # 1) СЃРЅСЏС‚СЊ СЃС‚Р°СЂСѓСЋ nginx-РѕР±РІСЏР·РєСѓ
  stack_cdn_del "$origin"
  [[ "$dport" =~ ^[0-9]+$ && "$dport" != "0" ]] && stack_del_decoy "$origin"
  sni_map_remove "$origin"
  [[ "$cdn" != "$n_cdn" ]] && sni_map_remove "$cdn"

  # 2) РїСѓС‚СЊ/С…РѕСЃС‚ РІ РёРЅР±Р°СѓРЅРґРµ (РїР°РЅРµР»СЊ СЃС‚РѕРї)
  local xui_was=1
  systemctl is-active --quiet x-ui 2>/dev/null || xui_was=0
  (( xui_was )) && { systemctl stop x-ui >/dev/null 2>&1 || true; sleep 1; }
  sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "UPDATE inbounds SET stream_settings=json_set(COALESCE(stream_settings,'{}'),'\$.xhttpSettings.path','$(sql_escape "$n_path")','\$.xhttpSettings.host','$(sql_escape "$n_origin")') WHERE id=$id;" 2>/dev/null || true
  (( xui_was )) && { systemctl start x-ui >/dev/null 2>&1 || true; sleep 2; }

  # 3) decoy РїРѕРґ РЅРѕРІС‹Р№ origin (РµСЃР»Рё Р¶РёРІРѕРіРѕ РЅРµС‚)
  if ! stack_decoy_meta "$n_origin" >/dev/null 2>&1; then
    local ndport="$dport"
    [[ "$ndport" =~ ^[0-9]+$ ]] || ndport=$((47000 + id))
    while ss -tlnH "sport = :$ndport" 2>/dev/null | grep -q .; do ndport=$((ndport+1)); done
    mk_decoy "$ndport" "$n_origin" "$cert" "$key" "/var/www/decoy-cdn-$id" "$n_tpl" >/dev/null 2>&1 || ndport=0
    dport="$ndport"
  fi

  # 4) Р±Р»РѕРє + РјР°СЂС€СЂСѓС‚ + hosts + РїСЂРѕС„РёР»СЊ
  cdn_frontend_ensure "$n_origin" "$n_cdn"
  stack_cdn_upsert "$n_origin" "$n_cdn" "$n_path" "$port" "${dport:-0}" "$cert" "$key"
  hosts_cdn_upsert "$id" "$n_cdn" "$proto"
  cdn_profile_save_add "$id" "$proto" "$n_origin" "$n_cdn" "$n_path" "$n_tpl" "${dport:-0}" "$n_prov"
  nginx_reload || true
  audit "cdn:reprofiled inbound=$id: $origin/$cdn в†’ $n_origin/$n_cdn path=$n_path"
  log "CDN-РїСЂРѕС„РёР»СЊ #$id РїРµСЂРµРЅР°СЃС‚СЂРѕРµРЅ: $n_origin в†’ $n_cdn, РїСѓС‚СЊ $n_path"
  cdn_repair   # Р¶РёРІР°СЏ РїСЂРѕРІРµСЂРєР°
  return 0
}

configure_sni_for_inbound() {
  local id="$1" proto="$2" port="$3" panel_domain="$4" pre_domain="${5:-}" pre_tpl="${6:-}"
  is_udp_proto "$proto" && { warn "UDP ($proto) РЅРµ РјР°СЂС€СЂСѓС‚РёР·РёСЂСѓРµС‚СЃСЏ С‡РµСЂРµР· SNI."; return 0; }
  [[ ! -f "$SNI_CONF" ]] && { err "$SNI_CONF РЅРµ РЅР°Р№РґРµРЅ вЂ” СЃРЅР°С‡Р°Р»Р° РІС‹РїРѕР»РЅРёС‚Рµ 'РџРµСЂРІРёС‡РЅСѓСЋ РЅР°СЃС‚СЂРѕР№РєСѓ SNI-СЂРѕСѓС‚РµСЂР°' (РїСѓРЅРєС‚ 1)."; return 1; }
  sni_used_load
  [[ -n "$panel_domain" ]] && SNI_USED["$panel_domain"]="${SNI_USED[$panel_domain]:-panel_backend}"

  # === VLESS XHTTP Р±РµР· security: РµРґРёРЅСЃС‚РІРµРЅРЅС‹Р№ СЂРµР¶РёРј СЃ РїСЂРµРґР»РѕР¶РµРЅРёРµРј CDN.
  # Р•СЃР»Рё РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ РѕС‚РІРµС‚РёР» В«РґР°В» вЂ” РёРЅР±Р°СѓРЅРґ РїРѕР»РЅРѕСЃС‚СЊСЋ РЅР°СЃС‚СЂРѕРµРЅ РєР°Рє CDN-РїСЂРѕС„РёР»СЊ
  # (nginx TLS-С„СЂРѕРЅС‚РµРЅРґ, hosts СЃ РґРѕРјРµРЅРѕРј CDN) Рё РѕР±С‹С‡РЅР°СЏ Р»РѕРіРёРєР° РЅРµ РЅСѓР¶РЅР°.
  # РЈР¶Рµ РЅР°СЃС‚СЂРѕРµРЅРЅС‹Р№ CDN-РїСЂРѕС„РёР»СЊ РїРѕРІС‚РѕСЂРЅРѕ РЅРµ СЃРїСЂР°С€РёРІР°РµРј Рё РЅРµ Р»РѕРјР°РµРј,
  # РЅРѕ РїСЂРµРґР»Р°РіР°РµРј СЃРІРµСЂРєСѓ/РїРµСЂРµРЅР°СЃС‚СЂРѕР№РєСѓ/СЃРЅСЏС‚РёРµ.
  if [[ -n "$(cdn_profile_get "$id" 2>/dev/null)" ]]; then
    cdn_existing_menu "$id"
    return 0
  fi
  # РўРѕР»СЊРєРѕ VLESS+XHTTP Р±РµР· TLS/Reality РјРѕР¶РµС‚ РїРѕР»СѓС‡РёС‚СЊ РїСЂРµРґР»РѕР¶РµРЅРёРµ CDN.
  # Р’С‹Р±СЂР°РЅРЅС‹Р№ РІР°СЂРёР°РЅС‚ В«VLESS XHTTP TLSВ» РІСЃРµРіРґР° СЃРѕС…СЂР°РЅСЏРµС‚ TLS РЅР° Xray.
  # Р­С‚РѕС‚ С„Р»Р°Р¶РѕРє РЅСѓР¶РµРЅ, РїРѕС‚РѕРјСѓ С‡С‚Рѕ РїРѕСЃР»Рµ РІСЃС‚Р°РІРєРё Р·Р°РїРёСЃРё РІ SQLite РёСЃС…РѕРґРЅР°СЏ
  # РїРµСЂРµРјРµРЅРЅР°СЏ security Р±РѕР»СЊС€Рµ РЅРµ РїРµСЂРµРґР°С‘С‚СЃСЏ РІ configure_sni_for_inbound.
  local _skip_xhttp_cdn_prompt=false
  inbound_was_created_as_tls_xhttp "$id" && _skip_xhttp_cdn_prompt=true
  # CDN СЃРїСЂР°С€РёРІР°РµРј С‚РѕР»СЊРєРѕ Сѓ XHTTP Р±РµР· TLS: СЌС‚Рѕ РѕС‚РґРµР»СЊРЅС‹Р№ CDN-СЂРµР¶РёРј.
  # XHTTP+TLS РёР· РјРµРЅСЋ вЂ” РѕР±С‹С‡РЅС‹Р№ TLS-РёРЅР±Р°СѓРЅРґ Рё РЅРµ РґРѕР»Р¶РµРЅ РЅРµРѕР¶РёРґР°РЅРЅРѕ
  # РїСЂРµРґР»Р°РіР°С‚СЊ CDN; CDN-РІР°СЂРёР°РЅС‚ РІС‹Р±РёСЂР°РµС‚СЃСЏ РѕС‚РґРµР»СЊРЅС‹Рј РїСѓРЅРєС‚РѕРј.
  local _xhttp_stream=""
  _xhttp_stream=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  if [[ "$proto" == "vless" && "$_skip_xhttp_cdn_prompt" != true ]] && \
     grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"$_xhttp_stream" && \
     grep -Eqi '"security"[[:space:]]*:[[:space:]]*"none"' <<<"$_xhttp_stream"; then
    if xhttp_cdn_setup "$id" "$proto" "$port"; then
      return 0
    fi
  fi
  # РџСЂРё СЂСѓС‡РЅРѕР№ РЅР°СЃС‚СЂРѕР№РєРµ РЅРµ-CDN XHTTP+TLS РїСЂРѕРґРѕР»Р¶Р°РµРј РѕР±С‹С‡РЅСѓСЋ РІРµС‚РєСѓ,
  # С‡С‚РѕР±С‹ СЃРїСЂРѕСЃРёС‚СЊ SNI Рё С€Р°Р±Р»РѕРЅ decoy, Р° РЅРµ Р·Р°РІРµСЂС€Р°С‚СЊ РЅР°СЃС‚СЂРѕР№РєСѓ РјРѕР»С‡Р°.

  local existing_domain=""
  existing_domain=$(grep -E "^\s+\S+\s+inb_${id}_backend" "$SNI_CONF" 2>/dev/null | awk '{print $1}' || true)
  if [[ -n "$existing_domain" ]]; then
    log "РРЅР±Р°СѓРЅРґ #$id СѓР¶Рµ РІ SNI: $existing_domain"
    grep -qE "^upstream inb_${id}_backend" "$SNI_CONF" 2>/dev/null || { sni_upstream_add "inb_${id}_backend" "$port"; nginx_reload || true; }

    # РµСЃР»Рё СЌС‚Рѕ Reality СЃ С‡СѓР¶РёРј/РїСѓСЃС‚С‹Рј dest (РЅРµ 127.0.0.1:*) вЂ” С‡РёРЅРёРј Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё:
    # СЃРѕР·РґР°С‘Рј decoy Рё РїСЂРѕСЃС‚Р°РІР»СЏРµРј dest = 127.0.0.1:<РїРѕСЂС‚ decoy>
    local stream_chk=""
    stream_chk=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    local _policy=""
    _policy=$(decoy_policy_classify "$id" "$proto" "$stream_chk")
    if [[ "$_policy" == reality-external ]]; then
      log "  Reality (#$id) РёРјРµРµС‚ РІРЅРµС€РЅРёР№ dest вЂ” РЅРµ С‚СЂРѕРіР°СЋ"
      return 0
    fi
    if [[ "$_policy" == reality-local ]] && ! grep -Eq "\"dest\": ?\"127\.0\.0\.1:" <<<"$stream_chk"; then
      # Р§СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё (dest = РІРЅРµС€РЅСЏСЏ С†РµР»СЊ РёР· СЃРїРёСЃРєР°) вЂ” СЌС‚Рѕ РќР• РїРѕР»РѕРјРєР°:
      # РёРЅР±Р°СѓРЅРґ СЃРїСЂСЏС‚Р°РЅ Р·Р° 443 РїРѕ SNI С†РµР»Рё, decoy/СЃРµСЂС‚ РµРјСѓ РЅРµ РЅСѓР¶РЅС‹
      warn "  Reality dest Р»РѕРєР°Р»СЊРЅС‹Р№/РїСѓСЃС‚РѕР№ вЂ” С‡РёРЅСЋ (decoy + dest)"
      local tls_port=$(( 4444 + id ))
      while ss -tlnH "sport = :$tls_port" 2>/dev/null | grep -q .; do tls_port=$((tls_port+1)); done
      local cp_line="" c="" k=""
      cp_line=$(cert_paths "$existing_domain") || true
      if [[ -z "$cp_line" ]]; then
        cert_issue "$existing_domain" || true
        cp_line=$(cert_paths "$existing_domain") || true
      fi
      if [[ -n "$cp_line" ]]; then
        c="${cp_line%% *}"; k="${cp_line##* }"
        local _dtpl=""
        [[ -t 0 ]] && decoy_template_choose_impl _dtpl "Decoy-Р·Р°РіР»СѓС€РєР° РґР»СЏ $existing_domain (СЃС‚СЂР°РЅРёС†Р° СЌС‚РѕРіРѕ РґРѕРјРµРЅР°)" "$(decoy_tpl_current "$existing_domain")"
        _dtpl="${_dtpl:-$(decoy_tpl_for "$existing_domain")}"
        decoy_tpl_store_set "$existing_domain" "$_dtpl" >/dev/null 2>&1 || true
        mk_decoy "$tls_port" "$existing_domain" "$c" "$k" "/var/www/decoy-$id" "$_dtpl"
        reality_set_dest "$id" "$tls_port" "$existing_domain"
        nginx_reload || true
        systemctl restart x-ui >/dev/null 2>&1 || true
        log "  Reality dest (#$id) РёСЃРїСЂР°РІР»РµРЅ в†’ 127.0.0.1:$tls_port"
      else
        warn "  cert РґР»СЏ $existing_domain РЅРµРґРѕСЃС‚СѓРїРµРЅ вЂ” Reality dest РЅРµ РѕР±РЅРѕРІР»С‘РЅ"
      fi
    fi
    # Existing SNI РЅРµ РѕР·РЅР°С‡Р°РµС‚, С‡С‚Рѕ decoy/fallback РґРµР№СЃС‚РІРёС‚РµР»СЊРЅРѕ РµСЃС‚СЊ.
    # РџРѕРІС‚РѕСЂРЅС‹Р№ Р·Р°РїСѓСЃРє РґРѕР»Р¶РµРЅ РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°С‚СЊ РёС… РёРґРµРјРїРѕС‚РµРЅС‚РЅРѕ.
    if [[ "$proto" == vless || "$proto" == trojan ]]; then
      tls_decoy_ensure_existing "$id" "$existing_domain" || warn "  #$id: TLS decoy РЅРµ СѓРґР°Р»РѕСЃСЊ РІРѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ"
    fi
    return 0
  fi

  local def="svc-$id.example.com"
  case "$proto" in
    vless) def="r.example.com";;
    anytls) def="at.example.com";;
    mtproto) def="tg.example.com";;
  esac
  local domain="$existing_domain" HIDE_EXT_443=false
  if [[ -n "$pre_domain" ]]; then
    # РґРѕРјРµРЅ РІС‹Р±СЂР°РЅ РґРѕ СЃРѕР·РґР°РЅРёСЏ РёРЅР±Р°СѓРЅРґР° вЂ” РїСЂРѕРІРµСЂСЏРµРј Рё РёСЃРїРѕР»СЊР·СѓРµРј Р±РµР· РїРѕРІС‚РѕСЂРЅРѕРіРѕ РІРѕРїСЂРѕСЃР°
    local pre_owner=""
    pre_owner=$(sni_domain_owner "$pre_domain" "$id")
    if [[ -n "$pre_owner" ]]; then
      err "Р”РѕРјРµРЅ $pre_domain СѓР¶Рµ Р·Р°РЅСЏС‚ ($pre_owner) вЂ” SNI РґР»СЏ #$id РЅРµ РЅР°СЃС‚СЂРѕРµРЅ."
      return 1
    fi
    domain="$pre_domain"
    SNI_USED["$domain"]="inb_${id}_backend"
  else
    # Reality: В«РЅР°Р№С‚Рё С†РµР»РёВ» (РєР°Рє РєРЅРѕРїРєР° РІ РїР°РЅРµР»Рё) РёР»Рё СЃРІРѕР№ SNI-РґРѕРјРµРЅ
    local stream_pre=""
    stream_pre=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    if grep -qi '"security": *"reality"' <<<"$stream_pre" || grep -qi '"security":"reality"' <<<"$stream_pre"; then
      echo
      echo -e "${B}Reality В«РЅР°Р№С‚Рё С†РµР»РёВ» вЂ” РєР°РЅРґРёРґР°С‚С‹ (РЅСѓР¶РµРЅ TLS 1.3 + h2):${N}"
      local _i=1 _c
      for _c in "${REALITY_TARGETS[@]}"; do
        printf "  %2d) %s\n" "$_i" "$_c"; _i=$((_i+1))
      done
      printf "  %2d) РЎРІРѕР№ SNI-РґРѕРјРµРЅ (РЅСѓР¶РµРЅ СЃРµСЂС‚РёС„РёРєР°С‚ + decoy)\n" "$_i"
      local rt=""
      ask rt "Р’С‹Р±РѕСЂ С‚Р°СЂРіРµС‚Р° (1-$_i)" "1" '^[0-9]+$'
      if (( rt >= 1 && rt <= ${#REALITY_TARGETS[@]} )); then
        REALITY_EXT_TARGET="${REALITY_TARGETS[$((rt-1))]}"
        printf '%s' "$REALITY_EXT_TARGET" > /tmp/.reality-found-target 2>/dev/null || true
        log "  #$id: РІРЅРµС€РЅРёР№ С‚Р°СЂРіРµС‚ в†’ $REALITY_EXT_TARGET (СЃРїСЂСЏС‡Сѓ Р·Р° 443 РїРѕ SNI С†РµР»Рё, tcp-РїРѕСЂС‚ РЅРµ РѕС‚РєСЂС‹РІР°СЋ)"
      else
        ask_sni_domain domain "$id" "$def"
      fi
    else
      ask_sni_domain domain "$id" "$def"
    fi
  fi

  # РњСѓСЃРѕСЂ РёР· СЃС‚Р°СЂРѕР№ СѓСЃС‚Р°РЅРѕРІРєРё: В«СЃРІРѕР№В» РґРѕРјРµРЅ РѕРєР°Р·Р°Р»СЃСЏ С†РµР»СЊСЋ С‡СѓР¶РѕРіРѕ reality вЂ”
  # SNI-РјР°СЂС€СЂСѓС‚/СЃРµСЂС‚/decoy РЅР° С‡СѓР¶РѕР№ РґРѕРјРµРЅ СЃС‚СЂРѕРёС‚СЊ РЅРµР»СЊР·СЏ
  local _rt_y
  for _rt_y in "${REALITY_TARGETS[@]}"; do
    if [[ "$domain" == "$_rt_y" ]]; then
      warn "  В«$domainВ» вЂ” С†РµР»СЊ С‡СѓР¶РѕРіРѕ reality, Р° РЅРµ С‚РІРѕР№ РґРѕРјРµРЅ (Р°СЂС‚РµС„Р°РєС‚ СЃС‚Р°СЂРѕР№ СѓСЃС‚Р°РЅРѕРІРєРё)."
      warn "  РРЅР±Р°СѓРЅРґ #$id РїРµСЂРµСЃРѕР·РґР°Р№: РїР°РЅРµР»СЊ в†’ СѓРґР°Р»РёС‚СЊ в†’ СЃРѕР·РґР°С‚СЊ Р·Р°РЅРѕРІРѕ СЃ РЅРѕСЂРјР°Р»СЊРЅС‹Рј РґРѕРјРµРЅРѕРј."
      return 1
    fi
  done

  # Р’РЅРµС€РЅРёР№ С‚Р°СЂРіРµС‚ В«РЅР°Р№С‚Рё С†РµР»РёВ» вЂ” РґРѕРєС‚СЂРёРЅР° В«РІСЃС‘ Р·Р° 443В»: С‡СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё РїСЂСЏС‡РµРј
  # РїРѕ SNI С†РµР»Рё, СЃР»СѓС€Р°РµРј 127.0.0.1, tcp-РїРѕСЂС‚ РёРЅР±Р°СѓРЅРґР° РќР• РѕС‚РєСЂС‹РІР°РµРј.
  if [[ -z "$domain" ]]; then
    local ext_dom="${REALITY_EXT_TARGET:-$(reality_find_target "$id")}"
    reality_ext_hide "$id" "$ext_dom" "$port" || warn "  РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРїСЂСЏС‚Р°С‚СЊ #$id Р·Р° 443"
    systemctl restart x-ui >/dev/null 2>&1 || true
    return 0
  fi

  sni_upstream_add "inb_${id}_backend" "$port"
  sni_map_add "$domain" "inb_${id}_backend"

  hosts_upsert "$id" "${panel_domain:-$domain}" "$domain"   # Р°РґСЂРµСЃ=РїР°РЅРµР»СЊ, SNI=СЃРІРѕР№ РґРѕРјРµРЅ
  systemctl restart x-ui >/dev/null 2>&1 || true

  local is_reality=false stream=""
  stream=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  [[ "$proto" == "vless" || "$proto" == "trojan" ]] && grep -q '"security": *"reality"' <<<"$stream" && is_reality=true

  if [[ "$is_reality" == true ]]; then
    cert_issue "$domain" || return 1
    local cp_line="" cert="" key=""
    cp_line=$(cert_paths "$domain") || true
    if [[ -n "$cp_line" ]]; then
      cert="${cp_line%% *}"; key="${cp_line##* }"
    else
      cert="/etc/letsencrypt/live/$domain/fullchain.pem"
      key="/etc/letsencrypt/live/$domain/privkey.pem"
    fi
    local tls_port=$(( 4444 + id ))
    while ss -tlnH "sport = :$tls_port" 2>/dev/null | grep -q .; do tls_port=$((tls_port+1)); done
    if [[ -z "$pre_tpl" && -t 0 ]]; then
      decoy_template_choose_impl pre_tpl "Decoy-Р·Р°РіР»СѓС€РєР° РґР»СЏ $domain (СЃС‚СЂР°РЅРёС†Р° РЅР° СЌС‚РѕРј РґРѕРјРµРЅРµ)" "$(decoy_tpl_current "$domain")"
    fi
    pre_tpl="${pre_tpl:-$(decoy_tpl_for "$domain")}"; decoy_tpl_store_set "$domain" "$pre_tpl" >/dev/null 2>&1 || true
    mk_decoy "$tls_port" "$domain" "$cert" "$key" "/var/www/decoy-$id" "$pre_tpl"
    reality_set_dest "$id" "$tls_port" "$domain"
    systemctl restart x-ui >/dev/null 2>&1 || true
    log "  + decoy (Reality) РЅР° РїРѕСЂС‚Сѓ $tls_port ($pre_tpl)"
  elif [[ "$proto" == "vless" || "$proto" == "trojan" ]] && grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$stream"; then
    # Р”Р»СЏ VLESS/Trojan TCP+TLS, РІРєР»СЋС‡Р°СЏ XHTTP+TLS, HTTPS-Р·Р°РіР»СѓС€РєР° РѕР±СЏР·Р°С‚РµР»СЊРЅР°.
    # Р”Р»СЏ VLESS TLS РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ РґРѕР»Р¶РµРЅ РёРјРµС‚СЊ С‚Р°РєРѕР№ Р¶Рµ СЏРІРЅС‹Р№ РІС‹Р±РѕСЂ С€Р°Р±Р»РѕРЅР°,
    # РєР°Рє Рё РґР»СЏ СЃРѕР±СЃС‚РІРµРЅРЅРѕРіРѕ Reality. Р’ РЅРµРёРЅС‚РµСЂР°РєС‚РёРІРЅРѕРј СЂРµР¶РёРјРµ РёСЃРїРѕР»СЊР·СѓРµРј
    # СЃРѕС…СЂР°РЅС‘РЅРЅС‹Р№/Р±РµР·РѕРїР°СЃРЅС‹Р№ С€Р°Р±Р»РѕРЅ Р±РµР· РѕСЃС‚Р°РЅРѕРІРєРё Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРѕР№ СѓСЃС‚Р°РЅРѕРІРєРё.
    local cp_line="" cert="" key="" tls_port tpl
    cp_line=$(cert_paths "$domain" 2>/dev/null || true)
    [[ -z "$cp_line" ]] && cert_issue "$domain" >/dev/null 2>&1 || true
    cp_line=$(cert_paths "$domain" 2>/dev/null || true)
    cert="${cp_line%% *}"; key="${cp_line##* }"
    tpl="$(decoy_tpl_current "$domain")"
    if [[ -t 0 ]]; then
      decoy_template_choose_impl tpl "Decoy-Р·Р°РіР»СѓС€РєР° РґР»СЏ $domain (СЃС‚СЂР°РЅРёС†Р° РЅР° СЌС‚РѕРј РґРѕРјРµРЅРµ)" "$tpl"
      tpl="${tpl:-$(decoy_tpl_for "$domain")}"
      decoy_tpl_store_set "$domain" "$tpl" >/dev/null 2>&1 || true
    fi
    if [[ -f "$cert" && -f "$key" ]]; then
      tls_port=$((47000 + id)); while ss -tlnH "sport = :$tls_port" 2>/dev/null | grep -q .; do tls_port=$((tls_port+1)); done
      mk_decoy "$tls_port" "$domain" "$cert" "$key" "/var/www/decoy-tls-$id" "$tpl" >/dev/null 2>&1 || true
      log "  + HTTPS-decoy РґР»СЏ TLS СЃРѕР·РґР°РЅ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё"
    fi
  fi

  nginx_reload || true
  log "SNI РЅР°СЃС‚СЂРѕРµРЅ: $domain -> inb_${id}_backend"
}

# =====================================================================
# РџР•Р Р’РР§РќРђРЇ РќРђРЎРўР РћР™РљРђ
# =====================================================================
initial_setup() {
  # РЎРѕС…СЂР°РЅСЏРµРј РїРѕР»РЅС‹Р№ РІС‹РІРѕРґ Рї.1, С‡С‚РѕР±С‹ РѕС€РёР±РєР° РЅРµ РёСЃС‡РµР·Р°Р»Р° РїСЂРё РІРѕР·РІСЂР°С‚Рµ РІ РјРµРЅСЋ.
  local _setup_log="/tmp/stack-initial-setup.log"
  : > "$_setup_log" 2>/dev/null || true
  exec 3>&1 4>&2
  # Р›РѕРіРёСЂРѕРІР°РЅРёРµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ РІС‹Р·С‹РІР°СЋС‰РёРј РјРµРЅСЋ С‡РµСЂРµР· tee; Р·РґРµСЃСЊ СЃРѕС…СЂР°РЅСЏРµРј РјР°СЂРєРµСЂ.
  line; echo -e "${B}   РџР•Р Р’РР§РќРђРЇ РќРђРЎРўР РћР™РљРђ SNI-Р РћРЈРўР•Р Рђ${N}"; line
  # РћС‚РєР°С‚/РґРµРјРѕРЅС‚Р°Р¶ РјРѕРі РІС‹РїРѕР»РЅРёС‚СЊСЃСЏ РІ СЌС‚РѕРј Р¶Рµ РїСЂРѕС†РµСЃСЃРµ РјРµРЅСЋ Рё СѓРґР°Р»РёС‚СЊ nginx
  # СѓР¶Рµ РїРѕСЃР»Рµ СЃС‚Р°СЂС‚РѕРІРѕР№ РїСЂРѕРІРµСЂРєРё Р·Р°РІРёСЃРёРјРѕСЃС‚РµР№. РџРµСЂРµРґ Рї.1 РїСЂРѕРІРµСЂСЏРµРј РїРѕРІС‚РѕСЂРЅРѕ,
  # РёРЅР°С‡Рµ СЃР±РѕСЂРєР° SNI РїСЂРѕРґРѕР»Р¶Р°РµС‚СЃСЏ Р±РµР· nginx Рё РІС‹РіР»СЏРґРёС‚ РєР°Рє В«Рї.1 РЅРёС‡РµРіРѕ РЅРµ СЃРґРµР»Р°Р»В».
  ensure_deps
  if ! command -v nginx >/dev/null 2>&1 || [[ ! -f /etc/nginx/nginx.conf ]]; then
    err "nginx РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ РёР»Рё /etc/nginx/nginx.conf РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚ вЂ” Рї.1 РѕСЃС‚Р°РЅРѕРІР»РµРЅ"
    err "РџСЂРѕРІРµСЂСЊ apt-get install nginx Рё Р·Р°РїСѓСЃС‚Рё Рї.1 РїРѕРІС‚РѕСЂРЅРѕ"
    pause
    return 1
  fi
  # РџСЂРµРґРѕС…СЂР°РЅРёС‚РµР»СЊ: СЃС‚РµРє СѓР¶Рµ СЃРѕР±СЂР°РЅ? РџРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РјРѕР¶РµС‚ РїРµСЂРµР·Р°РїРёСЃР°С‚СЊ
  # СЂР°Р±РѕС‚Р°СЋС‰РёРµ РЅР°СЃС‚СЂРѕР№РєРё вЂ” РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РѕС‚РєР°Р·С‹РІР°РµРјСЃСЏ.
  if [[ -f "$STACK_CONF" ]] && { [[ -f /etc/nginx/streams-available/sni-router.conf ]] || [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; }; then
    # С„Р°Р№Р»С‹ РјРѕРіР»Рё РїРµСЂРµСЃРѕР·РґР°С‚СЊСЃСЏ РїСЂРё РїРѕР»Сѓ-СЃР±РѕСЂРєРµ (РЅР°РїСЂРёРјРµСЂ РїРѕСЃР»Рµ РѕС‚РєР°С‚Р° РєР°СЂС‚Р°
    # РїСѓСЃС‚Р°СЏ) вЂ” fuse РѕР±СЏР·Р°РЅ СЌС‚Рѕ СѓРІРёРґРµС‚СЊ Рё РЅРµ РїСѓРіР°С‚СЊ Р»РѕР¶РЅС‹Рј В«СѓР¶Рµ РІС‹РїРѕР»РЅРµРЅРѕВ»
    local _map_n=0 _fuse_dflt="n"
    _map_n=$(grep -cE '^[[:space:]]+[^[:space:]]+[[:space:]]+[a-z][a-z0-9_]*_backend;' /etc/nginx/streams-available/sni-router.conf 2>/dev/null || true)
    _map_n=${_map_n:-0}
    if (( _map_n == 0 )); then
      warn "РќРћ: SNI-РєР°СЂС‚Р° РїСѓСЃС‚Р° (РјР°СЂС€СЂСѓС‚РѕРІ РЅРµС‚) вЂ” РёРЅР±Р°СѓРЅРґС‹ РЅРµ РїСЂРёРІСЏР·Р°РЅС‹ Рє 443, СЃС‚РµРє РїРѕР»Сѓ-СЃРѕР±СЂР°РЅРЅС‹Р№."
      _fuse_dflt="y"
    fi
    warn "РџРѕС…РѕР¶Рµ, РїРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° СѓР¶Рµ РІС‹РїРѕР»РЅРµРЅР°:"
    echo "    вњ“ $STACK_CONF"
    echo "    вњ“ SNI-СЂРѕСѓС‚РµСЂ (:443, streams-available/sni-router.conf)"
    [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && echo "    вњ“ РїР°РЅРµР»СЊ СѓСЃС‚Р°РЅРѕРІР»РµРЅР° (x-ui.db)"
    echo "  РўРѕС‡РµС‡РЅС‹Рµ РёР·РјРµРЅРµРЅРёСЏ вЂ” С‡РµСЂРµР· Рї.2/Рї.4 (РёРЅР±Р°СѓРЅРґС‹, decoy), Рї.11 (С„Р°Р№СЂРІРѕР»), Рї.21 (РіРёРіРёРµРЅР°)."
    local rerun=""
    # Р’ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРѕРј РІС‹Р·РѕРІРµ РѕС‚РІРµС‚С‹ СѓР¶Рµ РїРѕРґРіРѕС‚РѕРІР»РµРЅС‹ РІС‹Р·С‹РІР°СЋС‰РёРј РјР°СЃС‚РµСЂРѕРј.
    # РќРµР»СЊР·СЏ РґРѕР±Р°РІР»СЏС‚СЊ СЃСЋРґР° РІРѕРїСЂРѕСЃ: РѕРЅ СЃРґРІРёРіР°РµС‚ РїРѕС‚РѕРє РѕС‚РІРµС‚РѕРІ (email
    # СЃС‚Р°РЅРѕРІРёС‚СЃСЏ РѕС‚РІРµС‚РѕРј y/n, Р° Р·Р°С‚РµРј Reality РїРѕР»СѓС‡Р°РµС‚ EOF).
    if [[ ! -t 0 ]]; then
      rerun=true
      log "РђРІС‚РѕРјР°С‚РёС‡РµСЃРєРёР№ СЂРµР¶РёРј: РїРѕРІС‚РѕСЂРЅР°СЏ РїРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° СЂР°Р·СЂРµС€РµРЅР°"
    else
      askyn rerun "Р’СЃС‘ СЂР°РІРЅРѕ Р·Р°РїСѓСЃС‚РёС‚СЊ РїРµСЂРІРёС‡РЅСѓСЋ РЅР°СЃС‚СЂРѕР№РєСѓ Р·Р°РЅРѕРІРѕ?" "$_fuse_dflt"
    fi
    [[ "$rerun" == true ]] || { log "РћС‚РјРµРЅРµРЅРѕ вЂ” РєРѕРЅС„РёРіСѓСЂР°С†РёСЏ РЅРµ С‚СЂРѕРЅСѓС‚Р°."; return 0; }
    warn "РџРѕРІС‚РѕСЂРЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР°: РѕС‚РІРµС‚С‹ РЅР° РІРѕРїСЂРѕСЃС‹ РЅСѓР¶РЅРѕ Р±СѓРґРµС‚ РґР°С‚СЊ Р·Р°РЅРѕРІРѕ."
  fi
  # РџР•Р Р•РЈРЎРўРђРќРћР’РљРђ (Рї.17 в†’ СЃСЋРґР°): С‚Р°Р№РјРµСЂ СЃР°РјРѕР»РµС‡РµРЅРёСЏ Р»РµР·РµС‚ РІ x-ui РєР°Р¶РґС‹Рµ 2 РјРёРЅ
  # Рё СЂСѓС€РёС‚ СЃС…РµРјСѓ В«СЃС‚РѕРї в†’ РїСЂР°РІРєР° Р‘Р” в†’ СЃС‚Р°СЂС‚В». Р“Р°СЃРёРј РґРѕ РЅР°С‡Р°Р»Р°, РІРµСЂРЅС‘Рј РІ РєРѕРЅС†Рµ.
  # === Р¤РђР—Рђ Рђ: Р°РЅРєРµС‚Р° Рё РїР»Р°РЅ вЂ” РќРРљРђРљРРҐ РёР·РјРµРЅРµРЅРёР№ РґРѕ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ ===
  local PLAN_INSTALL=true PLAN_CREATE=true PLAN_FW=true
  local PLAN_EMAIL_DONE=0 PLAN_CREDS_DONE=0 PLAN_ADG_DONE=0
  if [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]]; then
    if [[ -z "$PANEL_DOMAIN" || "$PANEL_DOMAIN" == "panel.example.com" ]]; then
      # РџРµСЂРµРµР·Рґ РЅР° РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ: РґРѕРјРµРЅ РѕР±С‹С‡РЅРѕ СѓР¶Рµ Р»РµР¶РёС‚ РІ Р±СЌРєР°РїРµ СЃС‚РµРєР° вЂ”
      # РїСЂРµРґР»Р°РіР°РµРј РµРіРѕ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ (Enter = РїСЂРёРЅСЏС‚СЊ). РЎРїСЂР°С€РёРІР°РµРј С‚РѕР»СЊРєРѕ
      # РµСЃР»Рё Р±СЌРєР°РїР° РЅР° СЃРµСЂРІРµСЂРµ РЅРµС‚.
      local bk_dom=""
      bk_dom=$(backup_peek_panel_domain) || bk_dom=""
      [[ -n "$bk_dom" ]] && log "РќР°Р№РґРµРЅ Р±СЌРєР°Рї СЃС‚РµРєР° вЂ” РґРѕРјРµРЅ РїР°РЅРµР»Рё РёР· Р±СЌРєР°РїР°: $bk_dom (Enter вЂ” РїСЂРёРЅСЏС‚СЊ)"
      local pd0=""
      ask pd0 "Р”РѕРјРµРЅ РїР°РЅРµР»Рё (A-Р·Р°РїРёСЃСЊ в†’ СЌС‚РѕС‚ СЃРµСЂРІРµСЂ)" "${bk_dom:-${PANEL_DOMAIN:-panel.example.com}}" '^[a-zA-Z0-9.-]+$'
      PANEL_DOMAIN="$pd0"
    fi
    askyn PLAN_INSTALL "РЎС‚Р°РІРёС‚СЊ РїР°РЅРµР»СЊ LucX UI СЃРµР№С‡Р°СЃ?" "y"
    if [[ "$PLAN_INSTALL" != true ]]; then
      err "Р‘РµР· РїР°РЅРµР»Рё СЃС‚РµРє РЅРµ СЃРѕР±РёСЂР°РµС‚СЃСЏ вЂ” РѕС‚РјРµРЅР°."
      return 1
    fi
  fi
  le_email_load || true
  [[ "$EMAIL" == "none" || ! "$EMAIL" =~ ^[^@]+@[^@]+\.[^@]+$ ]] && EMAIL=""
  if [[ ! -t 0 ]]; then
    # РђРІС‚Рѕ-СЂРµР¶РёРј (Р·Р°РїСѓСЃРє СЃ С„Р°Р№Р»РѕРј Р°РІС‚РѕРѕС‚РІРµС‚РѕРІ): СЂРѕРІРЅРѕ РћР”РќРђ СЃС‚СЂРѕРєР° Р°РЅРєРµС‚С‹ вЂ”
    # email. РЎРѕС…СЂР°РЅС‘РЅРЅС‹Р№ email вЂ” Р·РЅР°С‡РµРЅРёРµ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ. Р Р°РЅСЊС€Рµ РїСЂРё РЅР°Р»РёС‡РёРё
    # СЃРѕС…СЂР°РЅС‘РЅРЅРѕРіРѕ email СЃРїРµСЂРІР° СЃРїСЂР°С€РёРІР°Р»СЃСЏ В«РСЃРїРѕР»СЊР·РѕРІР°С‚СЊ СЃРѕС…СЂР°РЅС‘РЅРЅС‹Р№?В» (y/n),
    # С‡С‚Рѕ СЃРґРІРёРіР°Р»Рѕ РІСЃРµ Р°РІС‚Рѕ-РѕС‚РІРµС‚С‹ РЅР° РѕРґРЅСѓ СЃС‚СЂРѕРєСѓ Рё Р»РѕРјР°Р»Рѕ РІСЃСЋ Р°РЅРєРµС‚Сѓ.
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "$EMAIL" '^[^@]+@[^@]+\.[^@]+$'
    le_email_save "$EMAIL"
  elif [[ -n "$EMAIL" ]]; then
    local _keep_le_email=false
    askyn _keep_le_email "РСЃРїРѕР»СЊР·РѕРІР°С‚СЊ СЃРѕС…СЂР°РЅС‘РЅРЅС‹Р№ email Let's Encrypt: $EMAIL? (n вЂ” СѓРєР°Р·Р°С‚СЊ РґСЂСѓРіРѕР№)" "y"
    if [[ "$_keep_le_email" != true ]]; then
      ask EMAIL "РќРѕРІС‹Р№ email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$'
      le_email_save "$EMAIL"
    fi
  else
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$'
    le_email_save "$EMAIL"
  fi
  PLAN_EMAIL_DONE=1
  # РўРёРї СЃРµСЂС‚РёС„РёРєР°С‚Р° РІС‹Р±РёСЂР°РµС‚СЃСЏ СЏРІРЅРѕ РІ Р°РЅРєРµС‚Рµ Рї.1, РґРѕ СЃРѕР·РґР°РЅРёСЏ РёРЅР±Р°СѓРЅРґРѕРІ.
  # Р‘РµР· force: auto_full_setup СѓР¶Рµ СЃРїСЂРѕСЃРёР» РµРіРѕ РїРµСЂРµРґ РІС‹Р·РѕРІРѕРј Рї.1.
  cert_type_ask
  if [[ -t 0 ]]; then
    ask_panel_creds || return 1
    PLAN_CREDS_DONE=1
  fi
  ask_adguard_and_decoy               # AdGuard РґР°/РЅРµС‚ в†’ РїР°СЂРѕР»СЊ в†’ РіРґРµ в†’ Р·Р°РіР»СѓС€РєР°
  PLAN_ADG_DONE=1
  if [[ ! -t 0 ]]; then
    # РђРІС‚Рѕ-СЂРµР¶РёРј: РІС‹Р·С‹РІР°СЋС‰РёР№ РјР°СЃС‚РµСЂ СѓР¶Рµ СЃРѕР·РґР°Р» РёРЅР±Р°СѓРЅРґС‹ СЃР°Рј Рё СЃР°Рј РїСЂРёРјРµРЅРёС‚
    # С„Р°Р№СЂРІРѕР» (firewall_apply). Р­С‚Рё РІРѕРїСЂРѕСЃС‹ РІ Р°РЅРєРµС‚Рµ РќР• СѓС‡Р°СЃС‚РІСѓСЋС‚ вЂ” РёРЅР°С‡Рµ
    # РїРѕР·РёС†РёРё Р°РІС‚Рѕ-РѕС‚РІРµС‚РѕРІ СЃРґРІРёРіР°СЋС‚СЃСЏ.
    PLAN_CREATE=false; PLAN_FW=false
    log "РђРІС‚Рѕ-СЂРµР¶РёРј: РёРЅР±Р°СѓРЅРґС‹/С„Р°Р№СЂРІРѕР» вЂ” РЅР° СЃС‚РѕСЂРѕРЅРµ РІС‹Р·С‹РІР°СЋС‰РµРіРѕ РјР°СЃС‚РµСЂР°"
  else
    askyn PLAN_CREATE "Р’ РєРѕРЅС†Рµ СЃРѕР·РґР°С‚СЊ РёРЅР±Р°СѓРЅРґС‹ (РјР°СЃС‚РµСЂ СЃРѕР·РґР°РЅРёСЏ)?" "y"
    askyn PLAN_FW "Р’ РєРѕРЅС†Рµ РЅР°СЃС‚СЂРѕРёС‚СЊ С„Р°Р№СЂРІРѕР» (С‚РѕР»СЊРєРѕ РЅСѓР¶РЅС‹Рµ РїРѕСЂС‚С‹)?" "y"
  fi
  echo
  line
  echo -e "${B}   РџР›РђРќ РќРђРЎРўР РћР™РљР${N}"; line
  local _pan_state="СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°"
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && _pan_state="Р±СѓРґРµС‚ СѓСЃС‚Р°РЅРѕРІР»РµРЅР° (LucX UI)"
  echo "  вЂў РїР°РЅРµР»СЊ: $PANEL_DOMAIN вЂ” $_pan_state"
  echo "  вЂў email LE: ${EMAIL:-<РЅРµ Р·Р°РґР°РЅ>}"
  echo "  вЂў AdGuard: ${ADG_PRESENT:-false} В· СЂР°Р·РјРµС‰РµРЅРёРµ: ${ADG_PLACEMENT:--} В· decoy РїР°РЅРµР»Рё: ${PDECOY:--}"
  echo "  вЂў РёРЅР±Р°СѓРЅРґС‹ РІ РєРѕРЅС†Рµ: $([[ "$PLAN_CREATE" == true ]] && echo РґР° || echo РЅРµС‚)"
  echo "  вЂў С„Р°Р№СЂРІРѕР» РІ РєРѕРЅС†Рµ: $([[ "$PLAN_FW" == true ]] && echo РґР° || echo РЅРµС‚)"
  line
  local go_apply=""
  if [[ ! -t 0 ]]; then
    go_apply=true   # Р°РІС‚Рѕ-СЂРµР¶РёРј: РІС‹Р·С‹РІР°СЋС‰РёР№ РјР°СЃС‚РµСЂ СѓР¶Рµ РїРѕР»СѓС‡РёР» СЃРѕРіР»Р°СЃРёРµ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ
  else
    askyn go_apply "РџР»Р°РЅ РІРµСЂРЅС‹Р№ вЂ” РїСЂРёРјРµРЅСЏС‚СЊ?" "y"
    [[ "$go_apply" == true ]] || { warn "РћС‚РјРµРЅРµРЅРѕ вЂ” РЅРёС‡РµРіРѕ РЅРµ РёР·РјРµРЅРµРЅРѕ"; return 0; }
  fi
  # === Р¤РђР—Рђ Р‘: РїСЂРёРјРµРЅРµРЅРёРµ (РІРѕРїСЂРѕСЃС‹ РІС‹С€Рµ РїСЂРѕРїСѓСЃРєР°СЋС‚СЃСЏ РїРѕ PLAN_*-С„Р»Р°РіР°Рј) ===
  # РЁР°Р±Р»РѕРЅС‹ РґРѕР»Р¶РЅС‹ Р±С‹С‚СЊ РіРѕС‚РѕРІС‹ Р”Рћ СЃРѕР·РґР°РЅРёСЏ РїРµСЂРІС‹С… decoy РІ СЌС‚РѕР№ Р¶Рµ РїРµСЂРІРёС‡РЅРѕР№
  # СѓСЃС‚Р°РЅРѕРІРєРµ. Р Р°РЅСЊС€Рµ РѕРЅРё РёРЅРёС†РёР°Р»РёР·РёСЂРѕРІР°Р»РёСЃСЊ С‚РѕР»СЊРєРѕ РїРѕР·РґРЅРёРјРё РїСѓРЅРєС‚Р°РјРё РјРµРЅСЋ,
  # РїРѕСЌС‚РѕРјСѓ Рї.1 РјРѕРі РІС‹Р±СЂР°С‚СЊ С€Р°Р±Р»РѕРЅ, РЅРѕ mk_decoy РЅРµ РЅР°С…РѕРґРёР» РµРіРѕ; РїРѕСЃР»Рµ Рї.2
  # С€Р°Р±Р»РѕРЅС‹ СѓР¶Рµ СЃСѓС‰РµСЃС‚РІРѕРІР°Р»Рё Рё РІСЃС‘ РІРЅРµР·Р°РїРЅРѕ РЅР°С‡РёРЅР°Р»Рѕ СЂР°Р±РѕС‚Р°С‚СЊ.
  decoy_templates_init || true
  decoy_login_templates_init || true
  systemctl stop stack-heal.timer 2>/dev/null || true
  systemctl disable stack-heal.timer 2>/dev/null || true
  # РџР°РЅРµР»Рё РЅРµС‚? РќР• РІР°Р»РёРјСЃСЏ вЂ” СЃС‚Р°РІРёРј РїСЂСЏРјРѕ Р·РґРµСЃСЊ (РїРµСЂРІРѕРЅР°С‡Р°Р»СЊРЅР°СЏ СѓСЃС‚Р°РЅРѕРІРєР°
  # РґРѕР»Р¶РЅР° СЂР°Р±РѕС‚Р°С‚СЊ Рё РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ РїР°РЅРµР»Рё С‡РµСЂРµР· Рї.17).
  if [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]]; then
    warn "РџР°РЅРµР»СЊ LucX UI РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР° (x-ui.db РЅРµ РЅР°Р№РґРµРЅ)."
    if [[ -z "$PANEL_DOMAIN" || "$PANEL_DOMAIN" == "panel.example.com" ]]; then
      local bk_dom2=""
      bk_dom2=$(backup_peek_panel_domain) || bk_dom2=""
      [[ -n "$bk_dom2" ]] && log "РќР°Р№РґРµРЅ Р±СЌРєР°Рї СЃС‚РµРєР° вЂ” РґРѕРјРµРЅ РїР°РЅРµР»Рё РёР· Р±СЌРєР°РїР°: $bk_dom2 (Enter вЂ” РїСЂРёРЅСЏС‚СЊ)"
      local pd_ask=""
      ask pd_ask "Р”РѕРјРµРЅ РїР°РЅРµР»Рё (A-Р·Р°РїРёСЃСЊ в†’ СЌС‚РѕС‚ СЃРµСЂРІРµСЂ)" "${bk_dom2:-${PANEL_DOMAIN:-panel.example.com}}" '^[a-zA-Z0-9.-]+$'
      PANEL_DOMAIN="$pd_ask"
    fi
    install_now=false
    [[ "$PLAN_INSTALL" == true ]] && install_now=true
    if [[ "$install_now" != true ]]; then
      err "Р‘РµР· РїР°РЅРµР»Рё СЂР°Р±РѕС‚Р° РЅРµРІРѕР·РјРѕР¶РЅР°."
      return 1
    fi
    install_lucx_panel || { err "РќРµ СѓРґР°Р»РѕСЃСЊ СѓСЃС‚Р°РЅРѕРІРёС‚СЊ РїР°РЅРµР»СЊ LucX UI."; return 1; }
  fi

  local inb_count=0
  inb_count=$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE enable=1;" 2>/dev/null || echo 0)
  if [[ "$inb_count" -eq 0 ]]; then
    warn "РќРµС‚ Р°РєС‚РёРІРЅС‹С… РёРЅР±Р°СѓРЅРґРѕРІ вЂ” СЃРѕР·РґР°РґРёРј РёС… РІ РљРћРќР¦Р• Рї.1, РєРѕРіРґР° SNI-СЃС‚РµРє СѓР¶Рµ СЃРѕР±СЂР°РЅ (РёРЅР°С‡Рµ РЅРµС‚ РЅРё SNI_CONF, РЅРё СЃРµСЂС‚РѕРІ, РЅРё РґРѕРјРµРЅР°)."
  fi

  local panel_port panel_path sub_port sub_path
  local PANEL_PORT PANEL_PATH SUB_PORT SUB_PATH
  panel_port=$(xui_get webPort); panel_port="${panel_port:-2053}"
  panel_path=$(xui_get webBasePath); panel_path="/${panel_path#/}"; panel_path="${panel_path%/}/"
  sub_port=$(xui_get subPort); sub_port="${sub_port:-2096}"
  sub_path=$(xui_get subPath); sub_path="/${sub_path#/}"; sub_path="${sub_path%/}/"

  if [[ "${PLAN_EMAIL_DONE:-0}" == 1 ]]; then
    log "Email РґР»СЏ Let's Encrypt: $EMAIL (РёР· Р°РЅРєРµС‚С‹)"
  else
  le_email_load || true
  if [[ -n "$EMAIL" ]]; then
    log "Email РґР»СЏ Let's Encrypt: $EMAIL (СЃРѕС…СЂР°РЅС‘РЅ)"
    if [[ -t 0 ]]; then
      local _keep_email=""
      askyn _keep_email "РћСЃС‚Р°РІРёС‚СЊ СЌС‚РѕС‚ email? (n вЂ” СѓРєР°Р·Р°С‚СЊ РЅРѕРІС‹Р№)" "y"
      if [[ "$_keep_email" != true ]]; then
        ask EMAIL "РќРѕРІС‹Р№ Email РґР»СЏ Let's Encrypt" "$EMAIL" '^[^@]+@[^@]+\.[^@]+$'
        le_email_save "$EMAIL"
      fi
    fi
  else
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$'
    le_email_save "$EMAIL"
  fi
  fi
  # Р•СЃР»Рё РїР°РЅРµР»СЊ СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°, СЃРЅР°С‡Р°Р»Р° Р±РµСЂС‘Рј РµС‘ С„Р°РєС‚РёС‡РµСЃРєРёР№ РґРѕРјРµРЅ РёР· Р‘Р”.
  # webDomain РїСЂРёРѕСЂРёС‚РµС‚РЅРµРµ subDomain; РІРѕРїСЂРѕСЃ РїРѕРєР°Р·С‹РІР°РµРј С‚РѕР»СЊРєРѕ РµСЃР»Рё РѕР±Р° РїСѓСЃС‚С‹.
  if [[ -z "$PANEL_DOMAIN" || "$PANEL_DOMAIN" == "panel.example.com" ]]; then
    local _existing_panel_domain=""
    _existing_panel_domain=$(xui_get webDomain 2>/dev/null || true)
    [[ -z "$_existing_panel_domain" || "$_existing_panel_domain" == "null" ]] && \
      _existing_panel_domain=$(xui_get subDomain 2>/dev/null || true)
    if [[ "$_existing_panel_domain" =~ ^[a-zA-Z0-9.-]+$ && "$_existing_panel_domain" != "panel.example.com" ]]; then
      PANEL_DOMAIN="$_existing_panel_domain"
      log "Р”РѕРјРµРЅ РїР°РЅРµР»Рё РІР·СЏС‚ РёР· СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕР№ РїР°РЅРµР»Рё: $PANEL_DOMAIN"
    else
      local bk_dom3=""
      bk_dom3=$(backup_peek_panel_domain) || bk_dom3=""
      ask PANEL_DOMAIN "Р”РѕРјРµРЅ РїР°РЅРµР»Рё" "${bk_dom3:-panel.example.com}" '^[a-zA-Z0-9.-]+$'
    fi
  else
    log "Р”РѕРјРµРЅ РїР°РЅРµР»Рё: $PANEL_DOMAIN (Р·Р°РґР°РЅ СЂР°РЅРµРµ)"
  fi
  sni_used_load
  SNI_USED["$PANEL_DOMAIN"]="panel_backend"   # РґРѕРјРµРЅ РїР°РЅРµР»Рё С‚РѕР¶Рµ Р·Р°РЅСЏС‚ вЂ” РёРЅР±Р°СѓРЅРґС‹ РЅРµ РјРѕРіСѓС‚ РµРіРѕ РёСЃРїРѕР»СЊР·РѕРІР°С‚СЊ

  # Р•Р”РРќР«Р™ РџРЈРўР¬ (С‚РѕС‚ Р¶Рµ, С‡С‚Рѕ РІ Р°РІС‚Рѕ-РїРѕРґСЉС‘РјРµ):
  # РїР°СЂРѕР»СЊ+РїРѕСЂС‚С‹ вЂ” С‚РѕР»СЊРєРѕ РІ TTY; РІ ans-СЂРµР¶РёРјРµ РІСЃС‘ СѓР¶Рµ РІ РіР»РѕР±Р°Р»СЊРЅС‹С… (U_*)
  if [[ "${PLAN_CREDS_DONE:-0}" != 1 ]]; then
    if [[ -t 0 ]]; then
      ask_panel_creds || return 1
    fi
  fi
  if [[ "${PLAN_ADG_DONE:-0}" != 1 ]]; then
    ask_adguard_and_decoy               # AdGuard РґР°/РЅРµС‚ в†’ РїР°СЂРѕР»СЊ в†’ РіРґРµ в†’ Р·Р°РіР»СѓС€РєР°
  fi
  local panel_decoy="$PDECOY"
  if [[ "$ADG_PRESENT" == true && "$ADG_PLACEMENT" == "panel" ]]; then
    panel_decoy="adguard"
    log "AdGuard Р±СѓРґРµС‚ РЅР°СЃС‚СЂРѕРµРЅ Р·Р° РїР°РЅРµР»СЊСЋ: TLS+СЃРµСЂС‚ РїР°РЅРµР»Рё, РїРѕСЂС‚, nginx-Р»РѕРєР°С†РёСЏ"
    # СЃС‚РѕСЂРѕРЅРЅРёР№ AdGuard РјРѕРі СЃР»СѓС€Р°С‚СЊ :80/:443 вЂ” nginx РЅРµ СЃРјРѕР¶РµС‚ Р·Р°Р±РёРЅРґРёС‚СЊСЃСЏ
    local p80_owner=""
    p80_owner=$(ss -tlnpH "sport = :80" 2>/dev/null | grep -oE '\("[^"]+"' | head -1 | tr -d '("')
    if [[ -n "$p80_owner" && "$p80_owner" != "nginx" ]]; then
      warn ":80 Р·Р°РЅСЏС‚ РїСЂРѕС†РµСЃСЃРѕРј '$p80_owner' вЂ” nginx РЅРµ СЃРјРѕР¶РµС‚ СЃР»СѓС€Р°С‚СЊ 80 (РЅСѓР¶РµРЅ РґР»СЏ ACME webroot)."
      warn "РћСЃРІРѕР±РѕРґРё РїРѕСЂС‚ РёР»Рё РїРµСЂРµРІРµРґРё С‚РѕС‚ СЃРµСЂРІРёСЃ (AdGuard) РЅР° РґСЂСѓРіРѕР№ РїРѕСЂС‚ РїРµСЂРµРґ Рї.1."
    fi
  fi
  if [[ "$ADG_PLACEMENT" == "sni" ]]; then
    local abase="${PANEL_DOMAIN#*.}"
    [[ "$abase" != *.* ]] && abase="$PANEL_DOMAIN"
    ADG_MODE_SNI_DOM="adguard.${abase:-example.com}"
    panel_decoy="stub"
    log "AdGuard: РѕС‚РґРµР»СЊРЅС‹Р№ РґРѕРјРµРЅ $ADG_MODE_SNI_DOM (РЅР°СЃС‚СЂРѕСЋ СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ SNI-СЂРѕСѓС‚РµСЂР°)"
  fi
  log "Decoy РїР°РЅРµР»Рё: $panel_decoy"

  if [[ -n "$U_PANEL_PORT$U_SUB_PORT$U_PANEL_PATH$U_SUB_PATH" ]]; then
    PANEL_PORT="$U_PANEL_PORT"; PANEL_PATH="$U_PANEL_PATH"
    SUB_PORT="$U_SUB_PORT";     SUB_PATH="$U_SUB_PATH"
    log "РџРѕСЂС‚С‹/РїСѓС‚Рё: РїР°РЅРµР»СЊ $PANEL_PORT $PANEL_PATH В· РїРѕРґРїРёСЃРєРё $SUB_PORT $SUB_PATH"
  else
    PANEL_PORT=$(make_port); PANEL_PATH="/$(gen_random_string 12)/"
    SUB_PORT=$(make_port);   SUB_PATH="/$(gen_random_string 10)/"
    log "РђРІС‚РѕРіРµРЅРµСЂР°С†РёСЏ: РїР°РЅРµР»СЊ $PANEL_PORT $PANEL_PATH В· РїРѕРґРїРёСЃРєРё $SUB_PORT $SUB_PATH"
  fi

  if [[ "$PANEL_PORT" == "$SUB_PORT" ]]; then
    err "РџРѕСЂС‚ РїР°РЅРµР»Рё Рё РїРѕСЂС‚ РїРѕРґРїРёСЃРѕРє СЃРѕРІРїР°РґР°СЋС‚ ($PANEL_PORT) вЂ” СѓРєР°Р¶РёС‚Рµ СЂР°Р·РЅС‹Рµ."
    return 1
  fi

  declare -A INB_PROTO INB_PORT INB_STREAM
  local -a INB_IDS=()
  local id proto port stream
  while IFS='|' read -r id proto port stream; do
    [[ -z "$id" ]] && continue
    INB_IDS+=("$id")
    INB_PROTO[$id]="$proto"; INB_PORT[$id]="$port"; INB_STREAM[$id]="$stream"
  done < <(sqlite3 "$XUI_DB" "SELECT id, protocol, port, COALESCE(stream_settings,'') FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)

  declare -A DOMAIN HIDE TLS_PORT DECOY_TPL REALITY_EXT_TARGET_BYID
  for id in "${INB_IDS[@]}"; do
    proto="${INB_PROTO[$id]}"; port="${INB_PORT[$id]}"
    if is_udp_proto "$proto"; then
      : # UDP РїСЂСЏС‡РµС‚СЃСЏ СЃРІРѕРёРј РјРµС…Р°РЅРёР·РјРѕРј вЂ” РјРѕР»С‡Р° (РЅРµ РІРѕРїСЂРѕСЃ, Р° РєРѕРЅСЃС‚Р°С‚Р°С†РёСЏ)
      HIDE[$id]=false; continue
    fi
    if [[ "$proto" == "tproxy" ]]; then
      # tg web proxy РїСЂСЏС‡РµС‚СЃСЏ РЎР’РћРРњ РјРµС…Р°РЅРёР·РјРѕРј (hosts: address=РїР°РЅРµР»СЊ, sni=tg-РґРѕРјРµРЅ;
      # РјР°СЂС€СЂСѓС‚ РІ SNI_CONF РІРµРґС‘С‚ setup_tproxy_web СЃ Р±СЌРєРµРЅРґРѕРј tg_backend) вЂ”
      # РІРѕРїСЂРѕСЃС‹ В«РЎРєСЂС‹С‚СЊ/SNI-РґРѕРјРµРЅВ» Рє РЅРµРјСѓ РЅРµ РѕС‚РЅРѕСЃСЏС‚СЃСЏ
      log "#$id tproxy ($port) вЂ” РїСЂСЏС‡РµС‚СЃСЏ СЃРІРѕРёРј РјРµС…Р°РЅРёР·РјРѕРј (tg web proxy Р·Р° 443), РїРѕРІС‚РѕСЂРЅРѕ РЅРµ СЃРїСЂР°С€РёРІР°СЋ"
      HIDE[$id]=false; continue
    fi

    # CDN-РїСЂРѕС„РёР»Рё РѕР±СЃР»СѓР¶РёРІР°СЋС‚СЃСЏ С‚РѕР»СЊРєРѕ РґР»СЏ VLESS+XHTTP Р±РµР· Р±РµР·РѕРїР°СЃРЅРѕСЃС‚Рё.
    if [[ "$proto" == "vless" ]] && grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"${INB_STREAM[$id]}"; then
      if [[ -n "$(cdn_profile_get "$id" 2>/dev/null)" ]]; then
        log "#$id ($proto) СѓР¶Рµ РІ CDN-СЂРµР¶РёРјРµ ($(cdn_profile_field "$id" 3)) вЂ” СЃРІРµСЂСЏСЋ CDN-РЅР°СЃС‚СЂРѕР№РєСѓ"
      fi
      if inbound_is_xhttp_cdn_candidate "${INB_STREAM[$id]}"; then
        if xhttp_cdn_setup "$id" "$proto" "$port"; then
          HIDE[$id]=true
          continue
        fi
      fi
    fi

    # СѓР¶Рµ РїСЂРёРІСЏР·Р°РЅ Рє SNI (СЃРѕР·РґР°РЅ РІ Рї.2/Рї.16 РёР»Рё СЂР°РЅРµРµ) вЂ” РќР• СЃРїСЂР°С€РёРІР°РµРј РІС‚РѕСЂРѕР№ СЂР°Р·
    local existing_dom=""
    existing_dom=$(grep -E "^\s+\S+\s+inb_${id}_backend" "$SNI_CONF" 2>/dev/null | awk '{print $1}' | head -1 || true)
    if [[ -n "$existing_dom" ]]; then
      log "#$id ($proto/$port) СѓР¶Рµ РІ SNI: $existing_dom вЂ” РїРѕРІС‚РѕСЂРЅРѕ РЅРµ СЃРїСЂР°С€РёРІР°СЋ"
      HIDE[$id]=true
      DOMAIN[$id]="$existing_dom"
      local meta=""
      meta=$(stack_decoy_meta "$existing_dom") || true
      # РџРѕСЂС‚ decoy вЂ” РєР°РЅРѕРЅРёС‡РµСЃРєРёР№ (4444 + id), СЃРј. decoy_port_for_id. Р•СЃР»Рё Р±Р»РѕРє
      # СѓР¶Рµ СЃС‚РѕСЏР» РЅР° РґСЂСѓРіРѕРј РїРѕСЂС‚Сѓ, РѕРЅ Р±СѓРґРµС‚ РїРµСЂРµСЃРѕР·РґР°РЅ РЅР° РєР°РЅРѕРЅРёС‡РµСЃРєРѕРј: С‚РѕР»СЊРєРѕ
      # С‚Р°Рє СЃРѕРІРїР°РґР°СЋС‚ decoy-Р±Р»РѕРє, reality-dest Рё РѕР¶РёРґР°РЅРёСЏ СЃР°РјРѕР»РµС‡РµРЅРёСЏ.
      TLS_PORT[$id]=$(decoy_port_for_id "$id")
      if [[ -n "$meta" && "${meta%% *}" != "${TLS_PORT[$id]}" ]]; then
        warn "  #$id: decoy $existing_dom РїРµСЂРµРЅРѕСЃРёС‚СЃСЏ РЅР° РєР°РЅРѕРЅРёС‡РµСЃРєРёР№ РїРѕСЂС‚ ${TLS_PORT[$id]} (Р±С‹Р» ${meta%% *})"
      fi
      local is_reality=false
      grep -qi reality <<<"${INB_STREAM[$id]}" && is_reality=true
      if [[ "$is_reality" == true ]]; then
        # РЁР°Р±Р»РѕРЅ РґРѕРјРµРЅР°: РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ вЂ” С‚РѕС‚, С‡С‚Рѕ СЃС‚РѕРёС‚ СЃРµР№С‡Р°СЃ (РёР· decoy-Р±Р»РѕРєР°
        # РёР»Рё СЃРѕС…СЂР°РЅС‘РЅРЅРѕРіРѕ РІС‹Р±РѕСЂР°), РїРѕСЌС‚РѕРјСѓ Enter РЅРёС‡РµРіРѕ РЅРµ РјРµРЅСЏРµС‚, РЅРѕ РґРѕРјРµРЅ
        # РјРѕР¶РЅРѕ РїРµСЂРµРІРµСЃС‚Рё РЅР° СЃРІРѕР№/РґСЂСѓРіРѕР№ С€Р°Р±Р»РѕРЅ РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ РѕСЃС‚Р°Р»СЊРЅС‹С….
        local _cur="" _dt=""
        _cur=$(decoy_tpl_current "$existing_dom")
        if [[ -t 0 ]]; then
          decoy_template_choose_impl _dt "Decoy РґР»СЏ $existing_dom (СЃС‚СЂР°РЅРёС†Р° СЌС‚РѕРіРѕ РґРѕРјРµРЅР°)" "$_cur"
          _dt="${_dt:-$_cur}"
        else
          _dt="$_cur"
        fi
        DECOY_TPL[$id]="$_dt"
        decoy_tpl_store_set "$existing_dom" "$_dt" >/dev/null 2>&1 || true
      else
        DECOY_TPL[$id]=""
      fi
      continue
    fi

    echo; echo -e "${Y}в”Ђв”Ђ #$id $proto РЅР° $port в”Ђв”Ђ${N}"
    local h_hide=""
    local _auto_ans=false
    if [[ -t 0 ]]; then
      askyn h_hide "РЎРєСЂС‹С‚СЊ Р·Р° 443?" "y"
    else
      # РќРµ-TTY (Р°РІС‚РѕРїРѕРґСЉС‘Рј в†’ initial_setup < ansf): РќР• С‡РёС‚Р°РµРј РїРѕР·РёС†РёРё Р°РЅСЃ-С„Р°Р№Р»Р°.
      # РџРѕР·РёС†РёРѕРЅРЅС‹Р№ С„Р°Р№Р» СЂР°Р·СЉРµР·Р¶Р°РµС‚СЃСЏ СЃ С„Р°РєС‚РёС‡РµСЃРєРёРјРё РІРѕРїСЂРѕСЃР°РјРё (РјР°СЃС‚РµСЂ Рё Р·РґРµСЃСЊ
      # СЃРїСЂР°С€РёРІР°СЋС‚ СЂР°Р·РЅРѕРµ: СЂРµР¶РёРј Reality, decoy) вЂ” Р»РёРЅРёРё СЃРґРІРёРіР°СЋС‚СЃСЏ, РєР°СЃРєР°Рґ
      # В«РђРІС‚Рѕ-РѕС‚РІРµС‚ РЅРµ СЂР°СЃРїРѕР·РЅР°РЅВ» Рё РІРµС‡РЅС‹Р№ EOF-С†РёРєР» РЅР° decoy-РІС‹Р±РѕСЂРµ. РњР°СЃС‚РµСЂ СѓР¶Рµ
      # СЃРѕР±СЂР°Р» РѕС‚РІРµС‚С‹ РІ A_DOM/REALITY_DECOY_TPL_BYID вЂ” Р±РµСЂС‘Рј РёС….
      if [[ -n "${A_DOM[$id]:-}" ]]; then h_hide=true; else h_hide=false; fi
      _auto_ans=true
      log "  Р°РІС‚Рѕ: СЃРєСЂС‹С‚СЊ=$h_hide${A_DOM[$id]:+ РґРѕРјРµРЅ=${A_DOM[$id]}}"
    fi
    HIDE[$id]="$h_hide"
    [[ "${HIDE[$id]}" == true ]] || continue

    # РђРІС‚Рѕ-РѕС‚РІРµС‚ РјР°СЃС‚РµСЂР°: РґРѕРјРµРЅ СѓР¶Рµ РІС‹Р±СЂР°РЅ в†’ СЃРІРѕР№ SNI (РґР»СЏ Reality вЂ” СЂРµР¶РёРј 2),
    # decoy-С€Р°Р±Р»РѕРЅ С‚РѕР¶Рµ РёР· РІС‹Р±РѕСЂР° РјР°СЃС‚РµСЂР°. Р’РѕРїСЂРѕСЃС‹ Р·РґРµСЃСЊ РЅРµ Р·Р°РґР°С‘Рј РІРѕРІСЃРµ.
    if [[ "$_auto_ans" == true ]]; then
      DOMAIN[$id]="${A_DOM[$id]}"
      local _m_is_rel=false
      grep -qi '"security"[[:space:]]*:[[:space:]]*"reality"' <<<"${INB_STREAM[$id]}" && _m_is_rel=true
      if [[ "$_m_is_rel" == true ]]; then
        REALITY_MODE["$id"]="2"
        local _m_tpl="${REALITY_DECOY_TPL_BYID[$id]:-$(decoy_tpl_current "${A_DOM[$id]}")}"
        DECOY_TPL[$id]="$_m_tpl"
        decoy_tpl_store_set "${A_DOM[$id]}" "$_m_tpl" >/dev/null 2>&1 || true
        TLS_PORT[$id]=$(decoy_port_for_id "$id")   # РєР°РЅРѕРЅРёС‡РµСЃРєРёР№ РїРѕСЂС‚ decoy
      else
        DECOY_TPL[$id]=""
        TLS_PORT[$id]=""
      fi
      continue
    fi

    local def="svc-$id.example.com"
    local is_reality=false
    grep -qi '"security"[[:space:]]*:[[:space:]]*"reality"' <<<"${INB_STREAM[$id]}" && is_reality=true
    case "$proto" in
      anytls) def="at.example.com";;
      trusttunnel|trust-tunnel) def="tt.example.com";;
      naive|naiveproxy) def="n.example.com";;
      mtproto) def="tg.example.com";;
      vless) def="r.example.com";;
    esac
    local d_new=""
    if [[ "$is_reality" == true ]]; then
      echo "  Reality #$id:"
      echo "   1) РќР°Р№С‚Рё РІРЅРµС€РЅСЋСЋ С†РµР»СЊ (Р±РµР· СЃРІРѕРµРіРѕ СЃРµСЂС‚РёС„РёРєР°С‚Р°/decoy)"
      echo "   2) РЈРєР°Р·Р°С‚СЊ СЃРІРѕР№ SNI-РґРѕРјРµРЅ (СЃРµСЂС‚РёС„РёРєР°С‚ + decoy)"
      local rmode_new=""
      ask rmode_new "Р РµР¶РёРј Reality [1/2]" "2" '^[12]$'
      if [[ "$rmode_new" == "1" ]]; then
        local tgt_new=""
        reality_target_menu tgt_new "#$id"
        # Р’ СЌС‚РѕРј С†РёРєР»Рµ transport РЅРµ Р·Р°РїРѕР»РЅСЏРµС‚СЃСЏ: РєР»СЋС‡СѓРµРј СЂРµР¶РёРј РїРѕ ID,
        # РёРЅР°С‡Рµ Bash РІРѕСЃРїСЂРёРЅРёРјР°РµС‚ vless- РєР°Рє Р°СЂРёС„РјРµС‚РёС‡РµСЃРєРѕРµ РІС‹СЂР°Р¶РµРЅРёРµ.
        REALITY_MODE["$id"]="1"
        REALITY_EXT_TARGET_BYID["$id"]="$tgt_new"
        # Р”Р»СЏ РіРµРЅРµСЂР°С†РёРё map РЅСѓР¶РµРЅ СЃР°Рј РІРЅРµС€РЅРёР№ SNI-РґРѕРјРµРЅ. Decoy РЅРµ СЃРѕР·РґР°С‘С‚СЃСЏ,
        # РЅРѕ РјР°СЂС€СЂСѓС‚ РїРѕ СЌС‚РѕРјСѓ РёРјРµРЅРё РґРѕР»Р¶РµРЅ РїРѕРїР°СЃС‚СЊ РІ SNI-РєР°СЂС‚Сѓ.
        DOMAIN[$id]="$tgt_new"
        HIDE[$id]=true
        DECOY_TPL[$id]=""
        continue
      fi
      ask_sni_domain d_new "$id" "$def" "SNI-РґРѕРјРµРЅ РґР»СЏ Reality #$id (РґРѕРјРµРЅ Р±СѓРґРµС‚ РёСЃРїРѕР»СЊР·РѕРІР°С‚СЊСЃСЏ РєР»РёРµРЅС‚РѕРј)"
    else
      ask_sni_domain d_new "$id" "$def"
    fi
    DOMAIN[$id]="$d_new"

    # Р”Р»СЏ Reality СЏРІРЅРѕ РІС‹Р±РёСЂР°РµРј СЃС‚СЂР°РЅРёС†Сѓ, РєРѕС‚РѕСЂР°СЏ Р±СѓРґРµС‚ РїРѕРєР°Р·Р°РЅР° РїСЂРё
    # РѕС‚РєСЂС‹С‚РёРё SNI РІ Р±СЂР°СѓР·РµСЂРµ; СЌС‚Рѕ РѕС‚РґРµР»СЊРЅР°СЏ decoy-Р·Р°РіР»СѓС€РєР°, РЅРµ РїСЂРѕС‚РѕРєРѕР».
    if [[ "$is_reality" == true ]]; then
      local dtpl="" _dom_new="${DOMAIN[$id]}"
      decoy_template_choose_impl dtpl "Decoy-Р·Р°РіР»СѓС€РєР° РґР»СЏ $_dom_new (СЃС‚СЂР°РЅРёС†Р° РЅР° СЌС‚РѕРј РґРѕРјРµРЅРµ)" "$(decoy_tpl_current "$_dom_new")"
      DECOY_TPL[$id]="${dtpl:-$(decoy_tpl_for "$_dom_new")}"
      decoy_tpl_store_set "$_dom_new" "${DECOY_TPL[$id]}" >/dev/null 2>&1 || true
      TLS_PORT[$id]=$(decoy_port_for_id "$id")   # РєР°РЅРѕРЅРёС‡РµСЃРєРёР№ РїРѕСЂС‚ (СЃРј. decoy_port_for_id)
    else
      DECOY_TPL[$id]=""
      TLS_PORT[$id]=""
    fi
  done


  local nginx_was_running=false xui_was_running=false adg_was_running=false
  systemctl is-active --quiet nginx 2>/dev/null && { nginx_was_running=true; systemctl stop nginx 2>/dev/null || true; }
  systemctl is-active --quiet x-ui  2>/dev/null && { xui_was_running=true;   systemctl stop x-ui  2>/dev/null || true; }
  if [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]] && systemctl is-active --quiet "$ADG_SERVICE" 2>/dev/null; then
    adg_was_running=true; systemctl stop "$ADG_SERVICE" 2>/dev/null || true
  fi
  sleep 2

  restore_running_services() {
    [[ "$xui_was_running" == true ]] && systemctl start x-ui 2>/dev/null || true
    [[ "$adg_was_running" == true && -n "$ADG_SERVICE" ]] && systemctl start "$ADG_SERVICE" 2>/dev/null || true
    [[ "$nginx_was_running" == true ]] && systemctl start nginx 2>/dev/null || true
  }

  local pc="" pk="" cp_line="" db_line=""
  # РџР РРћР РРўР•Рў в„–1: СЃРµСЂС‚, Р’РџРРЎРђРќРќР«Р™ РІ РЅР°СЃС‚СЂРѕР№РєРё x-ui (РІ С‚.С‡. РІС‹РїСѓС‰РµРЅРЅС‹Р№ С‡РµСЂРµР· РјРµРЅСЋ x-ui)
  db_line=$(panel_cert_from_db) || true
  if [[ -n "$db_line" ]]; then
    pc="${db_line%% *}"; pk=$(echo "$db_line" | awk '{print $2}')
    log "РџР°РЅРµР»СЊ: РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РІРїРёСЃР°РЅРЅС‹Р№ СЃРµСЂС‚ x-ui в†’ $pc"
  fi
  # РџСЂРёРѕСЂРёС‚РµС‚ в„–2: cert_paths (wildcard/РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ РїРѕ РґРѕРјРµРЅСѓ)
  if [[ -z "$pc" ]]; then
    cp_line=$(cert_paths "$PANEL_DOMAIN") || true
    [[ -n "$cp_line" ]] && { pc="${cp_line%% *}"; pk="${cp_line##* }"; }
  fi
  if [[ -z "$pc" ]]; then
    log "Р’С‹РїСѓСЃРє СЃРµСЂС‚РёС„РёРєР°С‚Р° РїР°РЅРµР»Рё: $PANEL_DOMAIN"
    if ! cert_issue "$PANEL_DOMAIN"; then
      err "РќРµ СѓРґР°Р»РѕСЃСЊ РІС‹РїСѓСЃС‚РёС‚СЊ cert"; restore_running_services; return 1
    fi
    cp_line=$(cert_paths "$PANEL_DOMAIN") || true
    if [[ -n "$cp_line" ]]; then pc="${cp_line%% *}"; pk="${cp_line##* }"; fi
  fi
  if [[ -z "$pc" || ! -f "$pc" || ! -f "$pk" ]]; then
    err "РЎРµСЂС‚РёС„РёРєР°С‚ РїР°РЅРµР»Рё РЅРµ РЅР°Р№РґРµРЅ"; restore_running_services; return 1
  fi

  # РЎР•Р Рў РџРђРќР•Р›Р РћР‘РЇР—РђРќ Р‘Р«РўР¬ Р’РџРРЎРђРќ Р’ РќРђРЎРўР РћР™РљР x-ui: Р±РµР· РЅРµРіРѕ РїР°РЅРµР»СЊ СЃР»СѓС€Р°РµС‚
  # HTTP, Р° nginx РїСЂРѕРєСЃРёСЂСѓРµС‚ РїРѕ https в†’ 502 Bad Gateway. Р’РїРёСЃС‹РІР°РµРј РІСЃРµРіРґР°,
  # РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ С‚РѕРіРѕ, РѕС‚РєСѓРґР° РїСЂРёС€С‘Р» СЃРµСЂС‚ (x-ui РјРµРЅСЋ / cert_paths / РІС‹РїСѓСЃРє).
  # РџРЈРўР вЂ” РёР· /etc/letsencrypt/live/<РґРѕРјРµРЅ>/ (РµРґРёРЅРѕРµ РјРµСЃС‚Рѕ, Р±РµР· Р·РµСЂРєР°Р»Р°).
  local cr_line=""
  cr_line=$(cert_mirror_to_certroot "$(dirname "$pc")" "$PANEL_DOMAIN" 2>/dev/null || true)
  [[ -n "$cr_line" ]] && { pc="${cr_line%% *}"; pk="${cr_line##* }"; }
  xui_set_setting webDomain   "$PANEL_DOMAIN"
  xui_set_setting webCertFile "$pc"
  xui_set_setting webKeyFile  "$pk"
  xui_set_setting subCertFile "$pc"
  xui_set_setting subKeyFile  "$pk"
  xui_set_setting subDomain   "$PANEL_DOMAIN"
  xui_set_setting subURI      "$(suburi_build "$PANEL_DOMAIN")"
  log "РЎРµСЂС‚ РїР°РЅРµР»Рё РІРїРёСЃР°РЅ РІ РЅР°СЃС‚СЂРѕР№РєРё x-ui (HTTPS-СЂРµР¶РёРј): $pc"

  # РЎРµСЂС‚С‹ РёРЅР±Р°СѓРЅРґРѕРІ/CDN-РѕСЂРёРґР¶РёРЅРѕРІ РїСЂРё СЂРµР¶РёРјРµ Р»РёРЅРёР№ (A/B) РќР• РІС‹РїСѓСЃРєР°РµРј РїРѕ
  # РѕРґРЅРѕРјСѓ: cert_issue Р»РёС€СЊ СЂРµРіРёСЃС‚СЂРёСЂСѓРµС‚ РґРѕРјРµРЅ РІ РµРіРѕ Р»РёРЅРёРё (CERT_DEFER=1),
  # Р° РІС‹РїСѓСЃРєР°РµС‚ Р»РёРЅРёРё РѕРґРЅРѕР№ РїР°С‡РєРѕР№ cert_batch_flush РЅРёР¶Рµ вЂ” РёРЅР°С‡Рµ РєР°Р¶РґС‹Р№
  # TLS-РёРЅР±Р°СѓРЅРґ РїРµСЂРµРёСЃРїСѓСЃРєР°Р» Р±С‹ Р»РёРЅРёСЋ Р·Р°РЅРѕРІРѕ (Р»РёРјРёС‚ LE 5 СЃРµСЂС‚РѕРІ/РЅРµРґРµР»СЋ).
  # РЎРµСЂС‚ РїР°РЅРµР»Рё РІС‹С€Рµ РІС‹РїСѓС‰РµРЅ СЃСЂР°Р·Сѓ вЂ” РѕРЅ РЅСѓР¶РµРЅ РґР»СЏ webCertFile/stack.conf.
  CERT_DEFER=1
  for id in "${INB_IDS[@]}"; do
    [[ "${HIDE[$id]}" == true ]] || continue
    [[ -z "${DECOY_TPL[$id]}" ]] && continue
    local _cert_proto="${INB_PROTO[$id]:-unknown}"
    cert_issue "${DOMAIN[$id]}" || warn "  РРўРћР“: СЃРµСЂС‚ ${DOMAIN[$id]} РќР• РІС‹РїСѓС‰РµРЅ вЂ” #$id ($_cert_proto) РЅРµ РїРѕРґРЅРёРјРµС‚СЃСЏ (РїСЂРёС‡РёРЅР° РІС‹С€Рµ)"
  done

  # CDN: ORIGIN-РґРѕРјРµРЅСѓ СЃРµСЂС‚ РЅСѓР¶РµРЅ СЂРѕРІРЅРѕ С‚Р°Рє Р¶Рµ, РєР°Рє РґРѕРјРµРЅР°Рј РёРЅР±Р°СѓРЅРґРѕРІ (TLS
  # С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx) вЂ” РѕР±СЂР°Р±Р°С‚С‹РІР°РµРј Рё РїРµС‡Р°С‚Р°РµРј РµРіРѕ РІ С‚РѕРј Р¶Рµ РІРёРґРµ, С‡С‚РѕР±С‹ РІ Р»РѕРіРµ
  # Р±С‹Р»Рѕ РІРёРґРЅРѕ РµРіРѕ СЃРѕСЃС‚РѕСЏРЅРёРµ, Р° РЅРµ В«С‚РёС€РёРЅР°В». Р”РѕРјРµРЅ CDN-С„СЂРѕРЅС‚Р° (cdn.*) РІ SAN РќР•
  # РІС…РѕРґРёС‚: РѕРЅ РїСЂРёРЅР°РґР»РµР¶РёС‚ РІРЅРµС€РЅРµРјСѓ CDN, СЃРµСЂС‚ С‚Р°Рј С‚РµСЂРјРёРЅРёСЂСѓРµС‚СЃСЏ СЃР°РјРёРј CDN.
  cdn_profiles_load
  local _cid _corigin
  for _cid in "${CDN_PROFILE_IDS[@]}"; do
    _corigin=$(cdn_profile_field "$_cid" 3) || continue
    [[ -n "$_corigin" ]] || continue
    cert_issue "$_corigin" || warn "  РРўРћР“: СЃРµСЂС‚ ${_corigin} РќР• РІС‹РїСѓС‰РµРЅ вЂ” CDN-ORIGIN #$_cid РЅРµ РїРѕРґРЅРёРјРµС‚СЃСЏ (РїСЂРёС‡РёРЅР° РІС‹С€Рµ)"
  done
  CERT_DEFER=0
  if (( ${#CDN_PROFILE_IDS[@]} > 0 )); then
    local _cfr=""
    _cfr=$(cdn_front_domains | tr '\n' ' ')
    [[ -n "${_cfr// /}" ]] && log "CDN-РґРѕРјРµРЅС‹ РІРЅРµ SAN (СЃРµСЂС‚ РІС‹РґР°С‘С‚ CDN, РЅРµ РјС‹): ${_cfr% }"
  fi
  # РїСѓС‚Рё СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ в†’ РІ settings РёРЅР±Р°СѓРЅРґРѕРІ (naive/anytls/trusttunnel/tproxy/hysteria)
  # СЂРµР¶РёРј РІС‹РїСѓСЃРєР° СЃРµСЂС‚РѕРІ (A/B) + РјСѓР»СЊС‚РёСЃРµСЂС‚ РїРѕ РІСЃРµРј РґРѕРјРµРЅР°Рј СЃС‚РµРєР°
  cert_mode_ask
  # Р”Рѕ СЌС‚РѕРіРѕ РјРµСЃС‚Р° SNI-РєР°СЂС‚Р° РµС‰С‘ РЅРµ Р·Р°РїРёСЃР°РЅР°, РїРѕСЌС‚РѕРјСѓ РѕРґРЅРѕР№ СЃРёРЅС…СЂРѕРЅРёР·Р°С†РёРё
  # cert_domains_sync_from_sni РЅРµРґРѕСЃС‚Р°С‚РѕС‡РЅРѕ: РїСЂРё РїРµСЂРІРѕР№ СѓСЃС‚Р°РЅРѕРІРєРµ РґРѕРјРµРЅС‹ РёР·
  # Р°РЅРєРµС‚С‹ РЅР°С…РѕРґСЏС‚СЃСЏ С‚РѕР»СЊРєРѕ РІ РјР°СЃСЃРёРІРµ DOMAIN[]. Р РµРіРёСЃС‚СЂРёСЂСѓРµРј РёС… РІ Р»РёРЅРёСЏС…
  # Р·Р°СЂР°РЅРµРµ, РёРЅР°С‡Рµ СЂРµР¶РёРј B СЃРѕР·РґР°С‘С‚ С‚РѕР»СЊРєРѕ РїР°РЅРµР»СЊРЅСѓСЋ Р»РёРЅРёСЋ, Р° РґР»СЏ РѕСЃС‚Р°Р»СЊРЅС‹С…
  # РїРѕР·Р¶Рµ РїС‹С‚Р°РµС‚СЃСЏ РЅР°Р№С‚Рё РЅРµСЃСѓС‰РµСЃС‚РІСѓСЋС‰СѓСЋ all.<Р±Р°Р·Р°>.
  local _setup_id _setup_dom _setup_line
  for _setup_id in "${INB_IDS[@]}"; do
    [[ "${HIDE[$_setup_id]}" == true ]] || continue
    _setup_dom="${DOMAIN[$_setup_id]:-}"
    [[ -n "$_setup_dom" ]] || continue
    # Р’РЅРµС€РЅРёР№ Reality РёСЃРїРѕР»СЊР·СѓРµС‚ SNI-С†РµР»СЊ С‚СЂРµС‚СЊРµР№ СЃС‚РѕСЂРѕРЅС‹ вЂ” СЃРµСЂС‚РёС„РёРєР°С‚ РґР»СЏ
    # РЅРµС‘ РЅРµ РІС‹РїСѓСЃРєР°РµРј. Р”Р»СЏ РІСЃРµС… РѕСЃС‚Р°Р»СЊРЅС‹С… СЃРєСЂС‹С‚С‹С… РёРЅР±Р°СѓРЅРґРѕРІ (РІРєР»СЋС‡Р°СЏ
    # VLESS TCP/XHTTP TLS Р±РµР· РІС‹Р±СЂР°РЅРЅРѕРіРѕ С€Р°Р±Р»РѕРЅР°) РґРѕРјРµРЅ РґРѕР»Р¶РµРЅ РїРѕРїР°СЃС‚СЊ РІ Р»РёРЅРёСЋ.
    [[ "${REALITY_MODE[$_setup_id]:-}" == "1" ]] && continue
    if [[ "${CERT_MODE:-A}" == "B" ]]; then
      _setup_line=$(cert_line_for "$_setup_dom" 2>/dev/null || true)
      [[ -n "$_setup_line" ]] && cert_line_domains_add "$_setup_line" "$_setup_dom"
    else
      cert_domains_add "$_setup_dom"
    fi
  done
  # ORIGIN CDN вЂ” РЅР°С€ РґРѕРјРµРЅ, РµРјСѓ С‚РѕР¶Рµ РЅСѓР¶РЅР° Р·Р°РїРёСЃСЊ РІ SAN-Р»РёРЅРёРё.
  cdn_profiles_load
  local _setup_cid _setup_origin
  for _setup_cid in "${CDN_PROFILE_IDS[@]}"; do
    _setup_origin=$(cdn_profile_field "$_setup_cid" 3 2>/dev/null || true)
    [[ -n "$_setup_origin" ]] || continue
    if [[ "${CERT_MODE:-A}" == "B" ]]; then
      _setup_line=$(cert_line_for "$_setup_origin" 2>/dev/null || true)
      [[ -n "$_setup_line" ]] && cert_line_domains_add "$_setup_line" "$_setup_origin"
    else
      cert_domains_add "$_setup_origin"
    fi
  done
  CERT_DEFER=0
  cert_batch_flush || warn "РњСѓР»СЊС‚РёСЃРµСЂС‚ РЅРµ РІС‹РїСѓС‰РµРЅ вЂ” С‡Р°СЃС‚СЊ РґРѕРјРµРЅРѕРІ РјРѕР¶РµС‚ РЅРµ СЂР°Р±РѕС‚Р°С‚СЊ (РїСЂРѕРІРµСЂСЊ DNS Рё Рї.10)"

  mkdir -p "$NGINX_STREAM_DIR" /etc/nginx/streams-available 2>/dev/null || true
  {
    echo "map \$ssl_preread_server_name \$backend {"
    echo "    default                       panel_backend;"
    # РћРґРёРЅ SNI РІ nginx stream map РјРѕР¶РµС‚ РёРјРµС‚СЊ С‚РѕР»СЊРєРѕ РѕРґРЅРѕ Р·РЅР°С‡РµРЅРёРµ. РЎРЅР°С‡Р°Р»Р°
    # СЂРµР·РµСЂРІРёСЂСѓРµРј РґРѕРјРµРЅ РїР°РЅРµР»Рё: РµСЃР»Рё СЃС‚Р°СЂС‹Р№/РїРѕРІС‚РѕСЂРЅС‹Р№ Р·Р°РїСѓСЃРє СЃР»СѓС‡Р°Р№РЅРѕ РІС‹РґР°Р»
    # РµРіРѕ РёРЅР±Р°СѓРЅРґСѓ, РїР°РЅРµР»СЊРЅС‹Р№ РјР°СЂС€СЂСѓС‚ СЃРѕС…СЂР°РЅСЏРµС‚СЃСЏ, Р° РґСѓР±Р»РёРєР°С‚ РЅРµ РїРµС‡Р°С‚Р°РµС‚СЃСЏ.
    local -A _sni_emitted=()
    if [[ -n "${PANEL_DOMAIN:-}" ]]; then
      echo "    $PANEL_DOMAIN                 panel_backend;"
      _sni_emitted["$PANEL_DOMAIN"]="panel_backend"
    fi
    for id in "${INB_IDS[@]}"; do
      # РќРµ РІС‹РІРѕРґРёРј РїСѓСЃС‚РѕР№ SNI: РёРЅР°С‡Рµ РїРѕР»СѓС‡Р°РµС‚СЃСЏ СЃС‚СЂРѕРєР° С‚РѕР»СЊРєРѕ СЃ backend,
      # Рё nginx СЃРѕРѕР±С‰Р°РµС‚ В«invalid number of the map parametersВ».
      local _sni_dom="${DOMAIN[$id]:-}"
      [[ "${HIDE[$id]}" == true && -n "$_sni_dom" ]] || continue
      if [[ -n "${_sni_emitted[$_sni_dom]+x}" ]]; then
        warn "SNI $_sni_dom СѓР¶Рµ Р·Р°РЅСЏС‚ (${_sni_emitted[$_sni_dom]}) вЂ” РјР°СЂС€СЂСѓС‚ inb_${id}_backend РЅРµ РґРѕР±Р°РІР»РµРЅ"
        continue
      fi
      echo "    $_sni_dom    inb_${id}_backend;"
      _sni_emitted["$_sni_dom"]="inb_${id}_backend"
    done
    # CDN-РїСЂРѕС„РёР»Рё: SNI origin/cdn в†’ Р»РѕРєР°Р»СЊРЅС‹Р№ TLS-С„СЂРѕРЅС‚РµРЅРґ (xhttp-РёРЅР±Р°СѓРЅРґС‹
    # Р±РµР· security РІС…РѕРґСЏС‚ С‡РµСЂРµР· nginx). РљР°СЂС‚Р° РїРµСЂРµРіРµРЅРµСЂРёСЂСѓРµС‚СЃСЏ вЂ” РјР°СЂС€СЂСѓС‚С‹ РґРµСЂР¶РёРј Р·РґРµСЃСЊ.
    cdn_profiles_load
    local _cp_row _cp_origin _cp_cdn
    while IFS= read -r _cp_row; do
      _cp_origin=$(printf '%s' "$_cp_row" | cut -d'|' -f3)
      _cp_cdn=$(printf '%s' "$_cp_row" | cut -d'|' -f4)
      if [[ -n "$_cp_origin" ]]; then
        if [[ -z "${_sni_emitted[$_cp_origin]+x}" ]]; then
          echo "    $_cp_origin    cdn_frontend;"
          _sni_emitted["$_cp_origin"]="cdn_frontend"
        else
          warn "SNI $_cp_origin СѓР¶Рµ Р·Р°РЅСЏС‚ (${_sni_emitted[$_cp_origin]}) вЂ” CDN origin РЅРµ РґРѕР±Р°РІР»РµРЅ"
        fi
      fi
      if [[ -n "$_cp_cdn" ]]; then
        if [[ -z "${_sni_emitted[$_cp_cdn]+x}" ]]; then
          echo "    $_cp_cdn    cdn_frontend;"
          _sni_emitted["$_cp_cdn"]="cdn_frontend"
        else
          warn "SNI $_cp_cdn СѓР¶Рµ Р·Р°РЅСЏС‚ (${_sni_emitted[$_cp_cdn]}) вЂ” CDN domain РЅРµ РґРѕР±Р°РІР»РµРЅ"
        fi
      fi
    done < "$CDN_PROFILES" 2>/dev/null || true
    echo "}"
    echo
    echo "upstream panel_backend { server 127.0.0.1:4443; }"
    if [[ -s "$CDN_PROFILES" ]]; then
      echo "upstream cdn_frontend { server 127.0.0.1:$CDN_FE_PORT; }"
    fi
    for id in "${INB_IDS[@]}"; do
      [[ "${HIDE[$id]}" == true ]] && echo "upstream inb_${id}_backend { server 127.0.0.1:${INB_PORT[$id]}; }"
    done
    echo
    echo "server {"
    echo "    listen 443;"
    echo "    proxy_pass \$backend;"
    echo "    ssl_preread on;"
    echo "    proxy_connect_timeout 5s;"
    echo "    proxy_timeout 10m;"
    echo "}"
  } > "$SNI_CONF"
  # Р•РґРёРЅС‹Р№ РёСЃС‚РѕС‡РЅРёРє РёСЃС‚РёРЅС‹: РґРѕСЃС‚СѓРїРЅС‹Р№ С„Р°Р№Р» вЂ” СЃСЃС‹Р»РєР° РЅР° СЂРµР°Р»СЊРЅРѕ РІРєР»СЋС‡С‘РЅРЅС‹Р№.
  # РўР°Рє fuse/status/rollback Рё nginx СЃРјРѕС‚СЂСЏС‚ РЅР° РѕРґРЅСѓ Рё С‚Сѓ Р¶Рµ РєР°СЂС‚Сѓ.
  mkdir -p /etc/nginx/streams-available 2>/dev/null || true
  rm -f /etc/nginx/streams-available/sni-router.conf 2>/dev/null || true
  ln -s "$SNI_CONF" /etc/nginx/streams-available/sni-router.conf 2>/dev/null || \
    cp -f "$SNI_CONF" /etc/nginx/streams-available/sni-router.conf 2>/dev/null || true

  # РџР РћР’Р•Р РљРђ: SNI-Р·Р°РїРёСЃРё РґРѕРјРµРЅР° РїР°РЅРµР»Рё РІ nginx вЂ” Р±РµР· РЅРµС‘ decoy РїР°РЅРµР»Рё (4443)
  # РЅРµРґРѕСЃС‚РёР¶РёРј РїРѕ РґРѕРјРµРЅСѓ (СЃСЂР°Р±РѕС‚Р°РµС‚ С‚РѕР»СЊРєРѕ default). РЎР°РјРѕР»РµС‡РµРЅРёРµ РїСЂРё РЅР°Р»РёС‡РёРё.
  if grep -qE "^[[:space:]]*${PANEL_DOMAIN//./\\.}[[:space:]]+panel_backend;" "$SNI_CONF" 2>/dev/null; then
    log "SNI-Р·Р°РїРёСЃСЊ РїР°РЅРµР»Рё РІ nginx: $PANEL_DOMAIN в†’ panel_backend вњ“"
  else
    sed -i "0,/^[[:space:]]*default[[:space:]]\+panel_backend;/s||    $PANEL_DOMAIN                 panel_backend;\n&|" "$SNI_CONF" 2>/dev/null || true
    if grep -qE "^[[:space:]]*${PANEL_DOMAIN//./\\.}[[:space:]]+panel_backend;" "$SNI_CONF"; then
      warn "SNI-Р·Р°РїРёСЃСЊ РїР°РЅРµР»Рё РѕС‚СЃСѓС‚СЃС‚РІРѕРІР°Р»Р° вЂ” РґРѕР±Р°РІР»РµРЅР°: $PANEL_DOMAIN в†’ panel_backend"
    else
      err "РќРµ СѓРґР°Р»РѕСЃСЊ РґРѕР±Р°РІРёС‚СЊ SNI-Р·Р°РїРёСЃСЊ РїР°РЅРµР»Рё РІ $SNI_CONF вЂ” РїСЂРѕРІРµСЂСЊ РІСЂСѓС‡РЅСѓСЋ"
    fi
  fi

  # AdGuard РЅР° РћРўР”Р•Р›Р¬РќРћРњ SNI-РґРѕРјРµРЅРµ (СЂРµР¶РёРј 2): СЃРµСЂС‚ + TLS 3002 + РјР°СЂС€СЂСѓС‚.
  # nginx СЃРµР№С‡Р°СЃ РѕСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” РєР°СЂС‚Р° РїРѕРґС…РІР°С‚РёС‚СЃСЏ С„РёРЅР°Р»СЊРЅС‹Рј СЃС‚Р°СЂС‚РѕРј nginx.
  if [[ -n "${ADG_MODE_SNI_DOM:-}" ]]; then
    adg_setup_sni_domain "$ADG_MODE_SNI_DOM" || warn "AdGuard SNI-РґРѕРјРµРЅ РЅРµ РЅР°СЃС‚СЂРѕРёР»СЃСЏ вЂ” РїРµСЂРµР·Р°РїСѓСЃС‚Рё Рї.1"
  fi

  mkdir -p "$NGINX_SITES_DIR" 2>/dev/null || true
  rm -f "$NGINX_SITES_DIR"/default 2>/dev/null || true
  # РјРёРіСЂР°С†РёСЏ: СЃС‚Р°СЂС‹Рµ РѕС‚РґРµР»СЊРЅС‹Рµ РєРѕРЅС„РёРіРё Р±РѕР»СЊС€Рµ РЅРµ РЅСѓР¶РЅС‹ вЂ” РІСЃС‘ Р±СѓРґРµС‚ РІ stack.conf
  rm -f "$NGINX_SITES_DIR"/decoy-*.conf 2>/dev/null || true
  rm -f "$NGINX_SITES_DIR"/panel.conf "$NGINX_SITES_DIR"/http80.conf 2>/dev/null || true
  stack_ensure
  stack_del_all_decoy
  printf '# stack-manager: РµРґРёРЅС‹Р№ РєРѕРЅС„РёРі (ACME :80, РїР°РЅРµР»СЊ :4443, decoy)\n' > "$STACK_CONF"

  local decoy_block=""
  if [[ "$panel_decoy" == "adguard" ]]; then
    [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]] && { systemctl start "$ADG_SERVICE" 2>/dev/null || true; sleep 1; }
    # С„Р°РєС‚РёС‡РµСЃРєРёР№ РїРѕСЂС‚ AdGuard (РїРѕСЃР»Рµ configure РјРѕР¶РµС‚ РёР·РјРµРЅРёС‚СЊСЃСЏ вЂ” СЃРєРѕСЂСЂРµРєС‚РёСЂСѓРµРј РЅРёР¶Рµ)
    local adg_port_build=""
    adg_port_build=$(adg_config_port)
    ADG_WEB_PORT="$adg_port_build"
    decoy_block=$(cat <<EOF
    location / {
        proxy_pass https://127.0.0.1:$ADG_WEB_PORT;
        proxy_ssl_verify off;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }
EOF
)
  else
    local panel_try='try_files /index.html =404;'
    if [[ "$panel_decoy" == tpl:custom:* ]]; then
      local custom_path="${panel_decoy#tpl:custom:}"
      if [[ -d "$custom_path" ]]; then
        PANEL_DECOY_DIR="$custom_path"
        panel_try='try_files $uri $uri/ /index.html;'
        log "Decoy РїР°РЅРµР»Рё: СЃРІРѕР№ СЃР°Р№С‚ РёР· $custom_path"
      else
        warn "РџР°РїРєР° $custom_path РЅРµ РЅР°Р№РґРµРЅР° вЂ” СЃС‚Р°РЅРґР°СЂС‚РЅР°СЏ Р·Р°РіР»СѓС€РєР°"
        panel_decoy_stub_init
      fi
    else
      panel_decoy_stub_init
      # decoy-С€Р°Р±Р»РѕРЅ РёР· РєР°С‚Р°Р»РѕРіР° (tpl:РРњРЇ) вЂ” РєР»Р°РґС‘Рј РµРіРѕ РєР°Рє index.html РїР°РЅРµР»Рё
      if [[ "$panel_decoy" == tpl:* ]]; then
        local tpl_name="${panel_decoy#tpl:}"
        local tpl_src="$DECOY_TPL_DIR/$tpl_name.html"
        is_login_template "$tpl_name" && tpl_src="$DECOY_LOGIN_DIR/$tpl_name.html"
        if [[ -f "$tpl_src" ]]; then
          cp -f "$tpl_src" "$PANEL_DECOY_DIR/index.html" 2>/dev/null || true
          chown www-data:www-data "$PANEL_DECOY_DIR/index.html" 2>/dev/null || true
          log "Decoy РїР°РЅРµР»Рё: С€Р°Р±Р»РѕРЅ В«$tpl_nameВ»"
        else
          warn "РЁР°Р±Р»РѕРЅ В«$tpl_nameВ» РЅРµ РЅР°Р№РґРµРЅ вЂ” РѕСЃС‚Р°С‘С‚СЃСЏ СЃС‚Р°РЅРґР°СЂС‚РЅР°СЏ Р·Р°РіР»СѓС€РєР°"
        fi
      fi
    fi
    decoy_block=$(cat <<EOF
    location / {
        root $PANEL_DECOY_DIR;
        $panel_try
    }
EOF
)
  fi

  { cat >> "$STACK_CONF" <<EOF
server {
    listen 127.0.0.1:4443 ssl;
    server_name $PANEL_DOMAIN;
    ssl_certificate     $pc;
    ssl_certificate_key $pk;
    set_real_ip_from 127.0.0.1;

    location $PANEL_PATH {
        proxy_pass https://127.0.0.1:$PANEL_PORT;
        proxy_ssl_verify off;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }

    location $SUB_PATH {
        proxy_pass https://127.0.0.1:$SUB_PORT;
        proxy_ssl_verify off;
        proxy_ssl_server_name on;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }

$decoy_block
}
EOF
  }

  { cat >> "$STACK_CONF" <<'EOF'
server {
    listen 80 default_server;
    server_name _;
    location /.well-known/acme-challenge/ { root /var/www/html; }
    location / { return 302 https://$host$request_uri; }
}
EOF
  }

  for id in "${INB_IDS[@]}"; do
    [[ "${HIDE[$id]}" == true ]] || continue
    if [[ -n "${REALITY_EXT_TARGET_BYID[$id]:-}" ]]; then
      reality_ext_hide "$id" "${REALITY_EXT_TARGET_BYID[$id]}" "${INB_PORT[$id]}" || warn "  #$id: РІРЅРµС€РЅРёР№ Reality РЅРµ СЃРїСЂСЏС‚Р°РЅ Р·Р° 443"
      continue
    fi
    [[ -z "${DECOY_TPL[$id]}" ]] && continue
    local dom="${DOMAIN[$id]}" cp_line="" c="" k=""
    cp_line=$(cert_paths "$dom") || true
    if [[ -n "$cp_line" ]]; then
      c="${cp_line%% *}"; k="${cp_line##* }"
      local _dpl="${DECOY_TPL[$id]:-$(decoy_tpl_for "$dom")}"
      mk_decoy "${TLS_PORT[$id]}" "$dom" "$c" "$k" "/var/www/decoy-$id" "$_dpl"
      decoy_tpl_store_set "$dom" "$_dpl" >/dev/null 2>&1 || true
      reality_set_dest "$id" "${TLS_PORT[$id]}" "$dom"   # dest = РІРЅСѓС‚СЂРµРЅРЅРёР№ IP decoy nginx + serverNames = РґРѕРјРµРЅ
    else
      warn "  cert РґР»СЏ $dom РЅРµ РЅР°Р№РґРµРЅ вЂ” decoy РїСЂРѕРїСѓС‰РµРЅ"
    fi
  done

  # CDN: РІС‹С€Рµ stack.conf РїРµСЂРµСЃРѕР±СЂР°РЅ СЃ РЅСѓР»СЏ (stack_del_all_decoy + РїРµСЂРµР·Р°РїРёСЃСЊ),
  # РїРѕСЌС‚РѕРјСѓ http-Р±Р»РѕРєРё cdn_frontend (listen 127.0.0.1:$CDN_FE_PORT) СЃРЅРµСЃРµРЅС‹.
  # Р’РѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј РёС… РЎР РђР—РЈ вЂ” РґРѕ nginx -t Рё С€С‚Р°С‚РЅРѕРіРѕ СЃС‚Р°СЂС‚Р° nginx; РёРЅР°С‡Рµ
  # CDN-СЃРѕРµРґРёРЅРµРЅРёРµ РѕР¶РёРІР°РµС‚ С‚РѕР»СЊРєРѕ СЃРѕ РІС‚РѕСЂРѕРіРѕ РїСЂРѕРіРѕРЅР° В«РџРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґВ».
  # noreload=1: nginx РїРѕРґРЅРёРјР°РµС‚ С€С‚Р°С‚РЅС‹Р№ С€Р°Рі РЅРёР¶Рµ, СѓР¶Рµ РїРѕСЃР»Рµ ensure_stream_include.
  cdn_repair 1 1

  cp -n "$XUI_DB" "${XUI_DB}.bak.$(date +%s)" 2>/dev/null || true

  xui_set_setting webListen   '127.0.0.1'
  xui_set_setting webPort     "$PANEL_PORT"
  xui_set_setting webBasePath "$PANEL_PATH"
  xui_set_setting subListen   '127.0.0.1'
  xui_set_setting subPort     "$SUB_PORT"
  xui_set_setting subPath     "$SUB_PATH"
  xui_set_setting subDomain   "$PANEL_DOMAIN"
  # URL РѕР±СЂР°С‚РЅРѕРіРѕ РїСЂРѕРєСЃРё РґР»СЏ РїРѕРґРїРёСЃРѕРє: РёРЅР°С‡Рµ share-СЃСЃС‹Р»РєРё РїРѕР»СѓС‡Р°СЋС‚ РїРѕСЂС‚ РїР°РЅРµР»Рё
  xui_set_setting subURI      "$(suburi_build "$PANEL_DOMAIN" "$SUB_PATH")"

  # СЃР°РјРѕРїСЂРѕРІРµСЂРєР°: СѓРєР°Р·Р°РЅРЅС‹Рµ РїРѕСЂС‚С‹ РѕР±СЏР·Р°РЅС‹ Р»РµС‡СЊ РІ 3x-ui (РїР°РЅРµР»СЊ РѕСЃС‚Р°РЅРѕРІР»РµРЅР° вЂ”
  # Р·Р°РїРёСЃСЊ РїСЂРѕР№РґС‘С‚; СЃРЅР°СЂСѓР¶Рё РІСЃС‘ Р·Р°РєСЂС‹РІР°РµС‚СЃСЏ nginx'РѕРј РЅР° 443)
  local _chk_p _chk_s
  _chk_p=$(xui_get webPort); _chk_s=$(xui_get subPort)
  if [[ "$_chk_p" == "$PANEL_PORT" && "$_chk_s" == "$SUB_PORT" ]]; then
    log "РџРѕСЂС‚С‹ РїСЂРёРјРµРЅРµРЅС‹ РІ 3x-ui: РїР°РЅРµР»СЊ $PANEL_PORT, РїРѕРґРїРёСЃРєРё $SUB_PORT (СЃР»СѓС€Р°СЋС‚ 127.0.0.1, РЅР°СЂСѓР¶Сѓ вЂ” С‚РѕР»СЊРєРѕ 443 С‡РµСЂРµР· nginx)"
  else
    err "РџРѕСЂС‚С‹ РќР• РїСЂРёРјРµРЅРёР»РёСЃСЊ РІ 3x-ui (РІ Р±Р°Р·Рµ panel=$_chk_p sub=$_chk_s, РѕР¶РёРґР°Р»РѕСЃСЊ $PANEL_PORT/$SUB_PORT)"
  fi

  local _id _proto _sec _dest
  while IFS='|' read -r _id _proto _sec _dest; do
    [[ -z "$_id" || -z "$_proto" ]] && continue
    # tproxy вЂ” РїСЂСЏРјРѕР№ С‚СѓРЅРЅРµР»СЊ Р±РµР· SNI-СЃРєСЂС‹С‚РёСЏ: РІСЃРµРіРґР° 0.0.0.0
    if is_udp_proto "$_proto" || [[ "$_proto" == "tproxy" ]]; then
      sqlite3 "$XUI_DB" "UPDATE inbounds SET listen='0.0.0.0' WHERE id=$_id;" 2>/dev/null || true
    elif [[ "$_proto" == "vless" && "$_sec" == "reality" && "$_dest" != 127.0.0.1:* ]]; then
      # Reality СЃ РІРЅРµС€РЅРёРј С‚Р°СЂРіРµС‚РѕРј (В«РЅР°Р№С‚Рё С†РµР»РёВ»): РґРѕРєС‚СЂРёРЅР° В«РІСЃС‘ Р·Р° 443В» вЂ”
      # РјР°СЂС€СЂСѓС‚ РїРѕ SNI С†РµР»Рё + hosts, СЃР»СѓС€Р°РµРј 127.0.0.1, tcp-РїРѕСЂС‚ РќР• РѕС‚РєСЂС‹РІР°РµРј
      local _dt="${_dest%%:*}"
      if [[ -n "$_dt" && "$_dt" != "127.0.0.1" ]]; then
        local _p_rt=""
        _p_rt=$(sqlite3 "$XUI_DB" "SELECT port FROM inbounds WHERE id=$_id;" 2>/dev/null || true)
        reality_ext_hide "$_id" "$_dt" "$_p_rt" || warn "  #$_id: РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРїСЂСЏС‚Р°С‚СЊ Р·Р° 443"
      else
        sqlite3 "$XUI_DB" "UPDATE inbounds SET listen='127.0.0.1' WHERE id=$_id;" 2>/dev/null || true
      fi
    else
      sqlite3 "$XUI_DB" "UPDATE inbounds SET listen='127.0.0.1' WHERE id=$_id;" 2>/dev/null || true
    fi
  done < <(sqlite3 "$XUI_DB" "SELECT id, protocol, COALESCE(json_extract(stream_settings,'\$.security'),''), COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),'') FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)

  local has_hosts=""
  has_hosts=$(sqlite3 "$XUI_DB" "SELECT name FROM sqlite_master WHERE type='table' AND name='hosts';" 2>/dev/null || true)
  if [[ -n "$has_hosts" ]]; then
    cdn_profiles_load   # CDN-РёРЅР±Р°СѓРЅРґС‹ РёСЃРєР»СЋС‡Р°СЋС‚СЃСЏ РёР· СЃС‚Р°РЅРґР°СЂС‚РЅРѕР№ РїРµСЂРµР·Р°РїРёСЃРё hosts
    # SNI РЅРµ Р·Р°РЅСЏС‚ РёРЅР±Р°СѓРЅРґРѕРј (РЅРµ СЃРєСЂС‹РІР°РµРј Р·Р° 443) вЂ” hosts-Р·Р°РїРёСЃСЊ (В«SNI РІРєР»СЋС‡С‘РЅВ») РЅРµ РЅСѓР¶РЅР°
    for id in "${INB_IDS[@]}"; do
      [[ "${HIDE[$id]}" == true ]] && continue
      [[ "${INB_PROTO[$id]}" == "tproxy" ]] && continue   # tg web proxy: hosts РІРµРґС‘С‚ setup_tproxy_web
      # СЃРїСЂСЏС‚Р°РЅ Р·Р° 443 (СЃРІРѕР№ РґРѕРјРµРЅ РР›Р С‡СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё РїРѕ SNI С†РµР»Рё) вЂ” hosts РЅРµ С‚СЂРѕРіР°РµРј
      grep -qE "^upstream inb_${id}_backend" "$SNI_CONF" 2>/dev/null && continue
      hosts_owned_delete "$id" 443
    done
    for id in "${INB_IDS[@]}"; do
      [[ "${HIDE[$id]}" == true ]] || continue
      # CDN-РёРЅР±Р°СѓРЅРґ: hosts РІРµРґС‘С‚ hosts_cdn_upsert (Р°РґСЂРµСЃ/SNI = CDN-РґРѕРјРµРЅ,
      # security=tls) вЂ” СЃС‚Р°РЅРґР°СЂС‚РЅР°СЏ Р·Р°РїРёСЃСЊ РїР°РЅРµР»Рё Р·Р°С‚С‘СЂР»Р° Р±С‹ РµРіРѕ
      [[ " ${CDN_PROFILE_IDS[*]:-} " == *" $id "* ]] && continue
      # РѕР±С‰Р°СЏ РіСЂСѓРїРїР° В«РѕРґРёРЅ С…РѕСЃС‚В»: Р°РґСЂРµСЃ = РґРѕРјРµРЅ РїР°РЅРµР»Рё, security=same
      hosts_upsert "$id" "$PANEL_DOMAIN"
    done
  fi

  ensure_stream_include
  if ! nginx -t 2>/dev/null; then
    err "nginx -t СѓРїР°Р»:"; nginx -t 2>&1 | tail -5 | sed 's/^/  /'
    restore_running_services
    return 1
  fi

  if [[ "$panel_decoy" == "adguard" && -n "$ADG_SERVICE" ]]; then
    local adg_cred_pass=""
    adg_cred_pass=$(grep "РџР°СЂРѕР»СЊ" /root/adguard-credentials.txt 2>/dev/null | awk '{print $2}' | head -1 || true)
    if configure_adguard_doh "$adg_cred_pass" "$pc" "$pk"; then
      log "AdGuard Home РґРѕР±Р°РІР»РµРЅ РІ SNI-РјР°СЂС€СЂСѓС‚: https://$PANEL_DOMAIN/ (UI Р±РµР· РїСѓС‚Рё) + /dns-query (DoH)"
    else
      warn "РќРµ СѓРґР°Р»РѕСЃСЊ РЅР°СЃС‚СЂРѕРёС‚СЊ AdGuardHome.yaml РґР»СЏ DoH"
    fi
    # configure РјРѕРі СЃРјРµРЅРёС‚СЊ РїРѕСЂС‚ AdGuard вЂ” РєРѕСЂСЂРµРєС‚РёСЂСѓРµРј proxy_pass РІ stack.conf
    local adg_port_now=""
    adg_port_now=$(adg_config_port)
    if [[ -n "$adg_port_now" && "$adg_port_now" != "$adg_port_build" ]]; then
      sed -i "s|proxy_pass https://127.0.0.1:$adg_port_build;|proxy_pass https://127.0.0.1:$adg_port_now;|" "$STACK_CONF" 2>/dev/null || true
      nginx_reload || true
      log "AdGuard РїРѕСЂС‚ СЃРєРѕСЂСЂРµРєС‚РёСЂРѕРІР°РЅ РІ nginx: $adg_port_build в†’ $adg_port_now"
    fi
    # РІРёР·Р°СЂРґ РЅРµ РїСЂРѕР№РґРµРЅ (users РїСѓСЃС‚) вЂ” СЃРѕР·РґР°С‘Рј Р°РґРјРёРЅР° Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё Рё РїРѕРєР°Р·С‹РІР°РµРј РїР°СЂРѕР»СЊ
    if grep -qE '^users: ?\[\]?' "$ADG_CONFIG" 2>/dev/null; then
      local adg_user="${U_ADG_USER:-admin}" adg_pass=""
      if [[ -n "${U_ADG_PASS:-}" ]]; then
        adg_pass="$U_ADG_PASS"   # РїР°СЂРѕР»СЊ Р·Р°РґР°РЅ РїСЂРё СѓСЃС‚Р°РЅРѕРІРєРµ
      else
        adg_pass=$(openssl rand -base64 18 2>/dev/null | tr -dc 'a-zA-Z0-9' | head -c 16)
        [[ -z "$adg_pass" ]] && adg_pass="AdG$(date +%s)"
      fi
      if adg_set_admin "$adg_user" "$adg_pass"; then
        {
          echo "AdGuard Home вЂ” $(date '+%F %T')"
          echo "  URL:    https://$PANEL_DOMAIN/"
          echo "  DoH:    https://$PANEL_DOMAIN/dns-query"
          echo "  Р›РѕРіРёРЅ:  $adg_user"
          echo "  РџР°СЂРѕР»СЊ: $adg_pass"
        } > /root/adguard-credentials.txt 2>/dev/null || true
        chmod 600 /root/adguard-credentials.txt 2>/dev/null || true
        echo
        log "AdGuard UI:    https://$PANEL_DOMAIN/"
        log "AdGuard Р»РѕРіРёРЅ: $adg_user   РїР°СЂРѕР»СЊ: $adg_pass  (СЃРѕС…СЂР°РЅРµРЅРѕ РІ /root/adguard-credentials.txt)"
      fi
    fi
  fi

  systemctl start x-ui 2>/dev/null || true
  systemctl start nginx 2>/dev/null || true
  # 443/SNI РѕР±СЏР·Р°РЅ СЂРµР°Р»СЊРЅРѕ СЃР»СѓС€Р°С‚СЊСЃСЏ: Р±РµР· РЅРµРіРѕ РїР°РЅРµР»СЊ Рё РґРѕРјРµРЅС‹ РЅРµРґРѕСЃС‚СѓРїРЅС‹
  # СЃРЅР°СЂСѓР¶Рё, Рё В«Рї.1 Р·Р°РІРµСЂС€С‘РЅВ» Р±С‹Р»Рѕ Р±С‹ Р»РѕР¶СЊСЋ. Р•СЃР»Рё РјРѕРґСѓР»СЊ stream РЅРµ Р±С‹Р»
  # РїРѕРґРєР»СЋС‡С‘РЅ вЂ” РїС‹С‚Р°РµРјСЃСЏ РїРѕРґРєР»СЋС‡РёС‚СЊ Рё РїРµСЂРµР·Р°РїСѓСЃС‚РёС‚СЊ nginx РїСЂСЏРјРѕ Р·РґРµСЃСЊ.
  if ! nginx_443_check 1; then
    if nginx_stream_module_enable; then
      ensure_stream_include >/dev/null 2>&1 || true
      nginx_reload >/dev/null 2>&1 || true
    fi
    nginx_443_check
  fi
  [[ "$adg_was_running" == true && -n "$ADG_SERVICE" ]] && systemctl start "$ADG_SERVICE" 2>/dev/null || true
  udp_inbound_firewall_check

  # tg web proxy: РґРѕРІРѕРґРёРј tproxy-РёРЅР±Р°СѓРЅРґ РґРѕ СЂР°Р±РѕС‡РµРіРѕ (hostname+СЃРµСЂС‚+СЃР°Р№С‚+РјР°СЂС€СЂСѓС‚)
  setup_tproxy_web

  # --- РРЅР±Р°СѓРЅРґС‹ РЅР° С‡РёСЃС‚РѕР№ СѓСЃС‚Р°РЅРѕРІРєРµ: СЃРѕР·РґР°С‘Рј РџРћРЎР›Р• СЃР±РѕСЂРєРё СЃС‚РµРєР°.
  #     SNI_CONF РіРѕС‚РѕРІ, РґРѕРјРµРЅ РїР°РЅРµР»Рё/email РёР·РІРµСЃС‚РЅС‹ вЂ” РІРѕРїСЂРѕСЃС‹ РІ С‚РѕРј Р¶Рµ РІРёРґРµ,
  #     С‡С‚Рѕ Рё РІ Р°РІС‚Рѕ-РїРѕРґСЉС‘РјРµ (reality: СЃРІРѕР№/С‡СѓР¶РѕР№ в†’ С†РµР»СЊ/РґРѕРјРµРЅ в†’ РїРѕСЂС‚).
  inb_count=$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || echo 0)
  if [[ "$inb_count" -eq 0 ]]; then
    local do_create=false
    [[ "$PLAN_CREATE" == true ]] && do_create=true
    if [[ "$do_create" == true ]]; then
      echo
      line; echo -e "${B}   РЎРћР—Р”РђРќРР• РРќР‘РђРЈРќР”РћР’${N}"; line
      echo "  РђРєС‚РёРІРЅС‹С… РїРѕР»СЊР·РѕРІР°С‚РµР»СЊСЃРєРёС… inbounds РЅРµС‚ вЂ” Р·Р°РїСѓСЃРєР°СЋ РјР°СЃС‚РµСЂ СЃРѕР·РґР°РЅРёСЏ."
      create_inbounds_menu
    fi
  elif [[ "$PLAN_CREATE" == true ]]; then
    log "РђРєС‚РёРІРЅС‹Рµ РёРЅР±Р°СѓРЅРґС‹ СѓР¶Рµ РµСЃС‚СЊ ($inb_count) вЂ” СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёРµ РЅРµ С‚СЂРѕРіР°СЋ."
    if [[ -t 0 ]]; then
      local add_more=false
      askyn add_more "Р—Р°РїСѓСЃС‚РёС‚СЊ РјР°СЃС‚РµСЂ Рё РґРѕР±Р°РІРёС‚СЊ РЅРѕРІС‹Рµ РёРЅР±Р°СѓРЅРґС‹?" "n"
      [[ "$add_more" == true ]] && create_inbounds_menu
    else
      log "Р”РѕР±Р°РІРёС‚СЊ РЅРѕРІС‹Рµ РјРѕР¶РЅРѕ С‡РµСЂРµР· СЂР°Р·РґРµР» 1 в†’ СѓРїСЂР°РІР»РµРЅРёРµ РёРЅР±Р°СѓРЅРґР°РјРё."
    fi
  fi

  # --- РЎС‚РµР»СЃ-РєРѕРЅС‚СЂРѕР»СЊ Рї.1: TCP-РёРЅР±Р°СѓРЅРґС‹, РЅРµ РїРѕРїР°РІС€РёРµ Р·Р° 443 ---
  # РџРѕСЃР»Рµ РѕС‚РєР°С‚Р°/РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ РёРЅР±Р°СѓРЅРґС‹ РѕСЃС‚Р°СЋС‚СЃСЏ РІ Р‘Р”, Р° Рї.1 СЃРѕР·РґР°С‘С‚ СЃРІРѕРё
  # С‚РѕР»СЊРєРѕ РїСЂРё РїСѓСЃС‚РѕР№ Р‘Р” (РЅРµ С‚СЂРѕРіР°С‚СЊ Р±РѕРµРІС‹Рµ). Р§РµСЃС‚РЅРѕ РїРѕРєР°Р·Р°С‚СЊ РЅРµРїСЂСЏС‚Р°РЅРЅС‹Рµ
  # Рё РїСЂРµРґР»РѕР¶РёС‚СЊ РїРѕС‡РёРЅРєСѓ СЃСЂР°Р·Сѓ вЂ” РёРЅР°С‡Рµ СЌС‚Рѕ РІСЃРїР»С‹РІС‘С‚ С‚РѕР»СЊРєРѕ РІ Рї.15.
  local _hid _proto _port _remark _miss=()
  while IFS='|' read -r _hid _proto _port _remark; do
    [[ -z "$_hid" ]] && continue
    is_udp_proto "$_proto" && continue
    # CDN-РёРЅР±Р°СѓРЅРґ: TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx (SNI origin/cdn в†’ cdn_frontend), СЃР°Рј
    # xray СЃР»СѓС€Р°РµС‚ 127.0.0.1 вЂ” Р·Р°РїРёСЃРё inb_<id>_backend РІ SNI-РєР°СЂС‚Рµ РµРјСѓ РќР• РЅСѓР¶РЅС‹.
    # Р‘РµР· СЌС‚РѕР№ РїСЂРѕРІРµСЂРєРё CDN-РёРЅР±Р°СѓРЅРґ РїРѕРїР°РґР°Р» РІ В«РЅРµРїСЂСЏС‚Р°РЅРЅС‹РµВ» Рё С‚СЏРЅСѓР» Р·Р° СЃРѕР±РѕР№
    # Р»РѕР¶РЅС‹Р№ РїСЂРѕРіРѕРЅ В«РџРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґВ» СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ Рї.1.
    [[ -n "$(cdn_profile_get "$_hid" 2>/dev/null)" ]] && continue
    if [[ "$_proto" == "tproxy" ]]; then
      # СЃРїРµС†-Р±СЌРєРµРЅРґС‹ tproxy: tg_backend (setup_tproxy_web) / "tproxy" (РјРµРЅСЋ)
      grep -qE '^\s+\S+\s+(tproxy|tg_backend);' "$SNI_CONF" 2>/dev/null && continue
      _miss+=("${_hid}|${_proto}|${_port}|${_remark}")
      continue
    fi
    # CDN/XHTTP СЃС‡РёС‚Р°РµС‚СЃСЏ СЃРєСЂС‹С‚С‹Рј РїРѕ ORIGIN-РјР°СЂС€СЂСѓС‚Сѓ РґР°Р¶Рµ РµСЃР»Рё hosts
    # СЃРѕРґРµСЂР¶РёС‚ CDN-РґРѕРјРµРЅ, Р° РЅРµ РѕС‚РґРµР»СЊРЅС‹Р№ РѕР±С‹С‡РЅС‹Р№ SNI.
    local _ist=""
    _ist=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$_hid;" 2>/dev/null || true)
    if inbound_is_xhttp_tls "$_ist" && grep -qE "^[[:space:]]+[^[:space:]]+[[:space:]]+inb_${_hid}_backend;" "$SNI_CONF" 2>/dev/null; then
      continue
    fi
    grep -qE "inb_${_hid}_backend;" "$SNI_CONF" 2>/dev/null && continue
    _miss+=("${_hid}|${_proto}|${_port}|${_remark}")
  done < <(sqlite3 "$XUI_DB" "SELECT id, protocol, port, remark FROM inbounds WHERE enable=1;" 2>/dev/null || true)
  if [[ ${#_miss[@]} -gt 0 ]]; then
    echo
    warn "TCP-РёРЅР±Р°СѓРЅРґС‹ РќР• Р·Р° 443 (РІ SNI-РєР°СЂС‚Рµ РёС… РЅРµС‚ вЂ” СЃРЅР°СЂСѓР¶Рё РїСЂРё Р·Р°РєСЂС‹С‚РѕРј UFW РЅРµ СЂР°Р±РѕС‚Р°СЋС‚):"
    local _r
    for _r in "${_miss[@]}"; do
      IFS='|' read -r _hid _proto _port _remark <<<"$_r"
      echo "    вЂў #$_hid ${_remark:-Р±РµР·-РёРјРµРЅРё} $_proto:$_port"
    done
    if [[ -t 0 ]]; then
      local _fix=false
      askyn _fix "РџСЂРѕРіРЅР°С‚СЊ В«РџРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґВ» РґР»СЏ РєР°Р¶РґРѕРіРѕ СЃРµР№С‡Р°СЃ?" "y"
      if [[ "$_fix" == true ]]; then
        for _r in "${_miss[@]}"; do
          IFS='|' read -r _hid _proto _port _remark <<<"$_r"
          if [[ "$_proto" == "tproxy" ]]; then
            setup_tproxy_web   # Сѓ tproxy СЃРІРѕСЏ РІРµС‚РєР°: hostname+СЃРµСЂС‚+СЃР°Р№С‚+РјР°СЂС€СЂСѓС‚
          else
            fix_inbound "$_hid"
          fi
        done
      fi
    else
      warn "  (РЅРµ-РёРЅС‚РµСЂР°РєС‚РёРІРЅС‹Р№ СЂРµР¶РёРј) СЃРїСЂСЏС‡СЊС‚Рµ РІСЂСѓС‡РЅСѓСЋ: Рї.19 в†’ РёРЅР±Р°СѓРЅРґ в†’ В«РџРѕС‡РёРЅРёС‚СЊВ», Р·Р°С‚РµРј Рї.11 Р·Р°РЅРѕРІРѕ"
    fi
  fi

  log "РџРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° Р·Р°РІРµСЂС€РµРЅР°."
  if [[ "$panel_decoy" == "adguard" ]]; then
    echo
    log "DoH РґРѕСЃС‚СѓРїРµРЅ:  https://$PANEL_DOMAIN/dns-query"
    log "AdGuard UI:    https://$PANEL_DOMAIN/"
  fi
  echo
  # РџРµСЂРµСѓСЃС‚Р°РЅРѕРІРєР°: СЃР±СЂРѕСЃ СЃС‚Р°СЂС‹С… РїСЂР°РІРёР» РїСЂРѕС€Р»РѕР№ СѓСЃС‚Р°РЅРѕРІРєРё (Р»РёС€РЅРёРµ TCP-РїРѕСЂС‚С‹)
  local fw_now=false
  [[ "$PLAN_FW" == true ]] && fw_now=true
  [[ "$fw_now" == true ]] && firewall_apply
  # РџРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° РїРµСЂРµСЃРѕР·РґР°Р»Р° SNI-РєР°СЂС‚Сѓ Рё stack.conf СЃ РЅСѓР»СЏ вЂ” CDN-РјР°СЂС€СЂСѓС‚С‹,
  # http-Р±Р»РѕРєРё, hosts-Р·Р°РїРёСЃРё Рё РїСѓС‚СЊ РёРЅР±Р°СѓРЅРґР° РїСЂРёРІРѕРґРёРј Рє РїСЂРѕС„РёР»СЋ. Р­С‚Рѕ РўРђ Р–Р•
  # В«РЎРІРµСЂРёС‚СЊ Рё РїРѕС‡РёРЅРёС‚СЊВ» (Рї.2 в†’ 4 в†’ 1), РЅРѕ РІС‹РїРѕР»РЅРµРЅРЅР°СЏ Р’РќРЈРўР Р Рї.1 Рё СЃ Р¶РёРІС‹РјРё
  # РїСЂРѕРІРµСЂРєР°РјРё (РїСѓС‚СЊ/СЃРµСЃСЃРёСЏ/decoy) вЂ” РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РѕР±СЂР°Р±РѕС‚С‡РёРєР° РЅРµ РЅСѓР¶РµРЅ.
  # РРґРµРјРїРѕС‚РµРЅС‚РЅРѕ: РїСЂРё РІРµСЂРЅРѕРј СЃРѕСЃС‚РѕСЏРЅРёРё РЅРёС‡РµРіРѕ РЅРµ РјРµРЅСЏРµС‚СЃСЏ, nginx РЅРµ РїРµСЂРµР·Р°РіСЂСѓР¶Р°РµС‚СЃСЏ.
  cdn_repair
}

# =====================================================================
# Р—РђРџРћР›РќР•РќРР• tunnel-РёРЅР±Р°СѓРЅРґР° (naive/anytls/trusttunnel): РґРѕРјРµРЅ + РєР»СЋС‡Рё + РєСЂРµРґС‹
# =====================================================================
tunnel_inbound_fill() {
  local id="$1" proto="$2" port="$3"
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }

  # СЃРЅСѓРїРµС‚-РїРѕР»Рµ РЅР°СЃС‚СЂРѕРµРє РїРѕРґ РїСЂРѕС‚РѕРєРѕР»
  local sn_col="domain"
  [[ "$proto" == "anytls" ]] && sn_col="sni"
  [[ "$proto" == "trusttunnel" || "$proto" == "trust-tunnel" ]] && sn_col="hostname"

  # РґРѕРјРµРЅ: РёР· РЅР°СЃС‚СЂРѕРµРє в†’ РёР· РјР°СЂС€СЂСѓС‚Р° nginx в†’ СЃРїСЂРѕСЃРёС‚СЊ
  local domain=""
  domain=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.${sn_col}') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  [[ -z "$domain" || "$domain" == "null" ]] && domain=""
  if [[ -z "$domain" ]]; then
    domain=$(grep -E "^\s+\S+\s+inb_${id}_backend" "$SNI_CONF" 2>/dev/null | awk '{print $1}' | head -1 || true)
  fi
  if [[ -z "$domain" ]]; then
    local def="n.example.com"
    [[ "$proto" == "anytls" ]] && def="at.example.com"
    [[ "$proto" == "trusttunnel" || "$proto" == "trust-tunnel" ]] && def="tt.example.com"
    ask_sni_domain domain "$id" "$def"
  fi
  [[ -z "$domain" || "$domain" == "null" ]] && { err "Р”РѕРјРµРЅ РЅРµ СѓРєР°Р·Р°РЅ"; return 1; }
  local owner=""
  owner=$(sni_domain_owner "$domain" "$id") || true
  [[ -n "$owner" ]] && { err "Р”РѕРјРµРЅ $domain Р·Р°РЅСЏС‚ ($owner)"; return 1; }

  sni_upstream_add "inb_${id}_backend" "$port"
  sni_map_add "$domain" "inb_${id}_backend"
  SNI_USED["$domain"]="inb_${id}_backend"

  # СЃРµСЂС‚РёС„РёРєР°С‚
  cert_issue "$domain" || return 1
  local cp_line="" cert="" key=""
  cp_line=$(cert_paths "$domain") || true
  [[ -z "$cp_line" ]] && { err "cert РґР»СЏ $domain РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  cert="${cp_line%% *}"; key="${cp_line##* }"

  # С‚РµРєСѓС‰РёРµ Р·РЅР°С‡РµРЅРёСЏ вЂ” РіРµРЅРµСЂРёСЂСѓРµРј С‚РѕР»СЊРєРѕ РїСѓСЃС‚С‹Рµ
  local cur_user="" cur_pass="" cur_seed="" cur_pw="" cur_prefix="" cur_clients=""
  # Sidecar-РёРЅР±Р°СѓРЅРґС‹ СЃР»СѓС€Р°СЋС‚ С‚РѕР»СЊРєРѕ Р»РѕРєР°Р»СЊРЅС‹Р№ backend: СЃРЅР°СЂСѓР¶Рё РґРѕСЃС‚СѓРїРЅС‹
  # С‡РµСЂРµР· nginx SNI РЅР° 443. РќРµ РѕСЃС‚Р°РІР»СЏРµРј СЃС‚Р°СЂС‹Р№/РїСѓР±Р»РёС‡РЅС‹Р№ listen вЂ” РёРЅР°С‡Рµ
  # РїР°РЅРµР»СЊ РјРѕР¶РµС‚ Р·Р°РЅСЏС‚СЊ РІРЅРµС€РЅРёР№ РїРѕСЂС‚ РёР»Рё Р·Р°РєСЂС‹РІР°С‚СЊ TLS-СЃРѕРµРґРёРЅРµРЅРёРµ.
  sqlite3 "$XUI_DB" "UPDATE inbounds SET listen='127.0.0.1', enable=1 WHERE id=$id;" 2>/dev/null || true
  cur_user=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.authUser') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  cur_pass=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.authPass') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  cur_seed=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.authSeed') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  cur_pw=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.password') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  cur_prefix=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.clientRandomPrefix') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  cur_clients=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.clients') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  [[ -z "$cur_user" || "$cur_user" == "null" ]] && cur_user=$(gen_hex 4)
  [[ -z "$cur_pass" || "$cur_pass" == "null" ]] && cur_pass=$(gen_b64)
  [[ -z "$cur_seed" || "$cur_seed" == "null" ]] && cur_seed=$(gen_hex 32)
  [[ -z "$cur_pw" || "$cur_pw" == "null" ]] && cur_pw=$(gen_b64)
  [[ -z "$cur_prefix" || "$cur_prefix" == "null" ]] && cur_prefix="$(gen_hex 4)/ffffffff"

  # --- json_set РїРѕРІРµСЂС… С‚РµРєСѓС‰РµРіРѕ settings (РЅРёС‡РµРіРѕ РЅРµ Р·Р°С‚РёСЂР°РµРј) ---
  local upd="UPDATE inbounds SET settings=json_set(CASE WHEN json_valid(settings) THEN settings ELSE '{}' END,
    '\$.${sn_col}','$domain','\$.certFile','$cert','\$.keyFile','$key','\$.authSeed','$cur_seed'"
  local new_settings
  case "$proto" in
    naive)
      upd+=",'\$.authUser','$cur_user','\$.authPass','$cur_pass','\$.port',$port,'\$.useAcme',json('false'),'\$.behindCover',json('false'),'\$.hideOn443',json('false'),'\$.routeThroughXray',json('false')"
      [[ -z "$cur_clients" || "$cur_clients" == "null" ]] && upd+=",'\$.clients',json('[{\"email\":\"user\",\"enable\":true}]')"
      ;;
    anytls)
      upd+=",'\$.password','$cur_pw','\$.enabled',json('true'),'\$.port',$port"
      ;;
    trusttunnel|trust-tunnel)
      upd+=",'\$.port',$port,'\$.clientRandomPrefix','$cur_prefix','\$.upstreamProtocol','http2','\$.listenPreset','fast','\$.clientDns',COALESCE(json_extract(settings,'\$.clientDns'),'1.1.1.1'),'\$.routeThroughXray',json('false')"
      [[ -z "$cur_clients" || "$cur_clients" == "null" ]] && upd+=",'\$.clients',json('[{\"email\":\"user\",\"enable\":true}]')"
      ;;
  esac
  upd+=") , listen=CASE WHEN COALESCE(listen,'')='' THEN '127.0.0.1' ELSE listen END WHERE id=$id;"
  local err_out
  err_out=$(sqlite3 "$XUI_DB" "$upd" 2>&1) || { err "SQL: $err_out"; return 1; }

  # cred-С„Р°Р№Р» РїРѕР»СЊР·РѕРІР°С‚РµР»СЋ
  umask 077
  {
    echo "=== $proto #$id вЂ” Р—РђРџРћР›РќР•РќРћ ==="
    echo "Р”РѕРјРµРЅ (SNI): $domain"
    echo "РџРѕСЂС‚: $port (РїР°РЅРµР»СЊ СЃР»СѓС€Р°РµС‚ 127.0.0.1:$port, СЃРЅР°СЂСѓР¶Рё https://$domain:443)"
    if [[ "$proto" == "naive" ]]; then
      echo "РЎРµСЂРІРёСЃРЅС‹Р№ Р»РѕРіРёРЅ: $cur_user"
      echo "РЎРµСЂРІРёСЃРЅС‹Р№ РїР°СЂРѕР»СЊ: $cur_pass"
      echo "URL: naive+https://$cur_user:$cur_pass@$domain:443"
    elif [[ "$proto" == "anytls" ]]; then
      echo "РџР°СЂРѕР»СЊ: $cur_pw"
      echo "URL: anytls://$cur_pw@$domain:443/?sni=$domain"
    else
      echo "РљР»РёРµРЅС‚СЃРєРёРµ tt:// СЃСЃС‹Р»РєРё СЃ Р»РѕРіРёРЅРѕРј/РїР°СЂРѕР»РµРј вЂ” РІ РїР°РЅРµР»Рё (РёРЅР±Р°СѓРЅРґ в†’ share)"
    fi
    echo "authSeed: $cur_seed"
  } > "/root/.lucx-$proto-info"
  chmod 600 "/root/.lucx-$proto-info" 2>/dev/null || true
  umask 022

  # РїСЂРѕРІРµСЂРєР° РёР· Р‘Р”
  local chk_dom
  chk_dom=$(sqlite3 "$XUI_DB" "SELECT json_extract(settings,'\$.${sn_col}') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  if [[ "$chk_dom" == "$domain" ]]; then
    log "Р—Р°РїРѕР»РЅРµРЅРѕ: $proto #$id в†’ $domain, РєР»СЋС‡Рё РёР· wildcard, РєСЂРµРґС‹ РІ /root/.lucx-$proto-info"
  else
    err "РџСЂРѕРІРµСЂРєР° РЅРµ РїСЂРѕС€Р»Р°: settings.$sn_col = '$chk_dom'"
  fi
  nginx_reload || true
  systemctl restart x-ui >/dev/null 2>&1 || true
  log "РџР°РЅРµР»СЊ РїРµСЂРµР·Р°РїСѓС‰РµРЅР° вЂ” СЃРµСЂРІРёСЃ $proto РґРѕР»Р¶РµРЅ РїРѕРґРЅСЏС‚СЊСЃСЏ (СЃРјРѕС‚СЂРёС‚Рµ journalctl -u x-ui | grep tunnel)"
  return 0
}

# =====================================================================
# РџРћР§РРќРљРђ РРќР‘РђРЈРќР”Рђ: SNI + СЃРµСЂС‚РёС„РёРєР°С‚ + Reality dest (РєР°РЅРѕРЅРёС‡РµСЃРєР°СЏ РїРµСЂРµР·Р°РїРёСЃСЊ)
# =====================================================================
fix_inbound() {
  # $1 (РЅРµРѕР±СЏР·Р°С‚РµР»СЊРЅРѕ) вЂ” ID РёРЅР±Р°СѓРЅРґР°; Р±РµР· Р°СЂРіСѓРјРµРЅС‚Р° СЃРїСЂР°С€РёРІР°РµС‚
  local _arg_id="${1:-}"
  line; echo -e "${B}   РџРћР§РРќРРўР¬ РРќР‘РђРЈРќР” (SNI + CERT + DEST)${N}"; line
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  [[ ! -f "$SNI_CONF" ]] && { err "РќРµС‚ $SNI_CONF вЂ” СЃРЅР°С‡Р°Р»Р° РІС‹РїРѕР»РЅРёС‚Рµ Рї.1"; return 1; }
  db_protect_suspend
  sqlite3 -header -column "$XUI_DB" "SELECT id, protocol, port, remark FROM inbounds WHERE enable=1;" 2>/dev/null || true
  echo
  local id=""
  if [[ -n "$_arg_id" ]]; then
    id="$_arg_id"
    log "РРЅР±Р°СѓРЅРґ: #$id"
  else
    ask id "ID РёРЅР±Р°СѓРЅРґР°" "" '^[0-9]+$'
  fi
  local proto="" port="" stream=""
  while IFS='|' read -r p po st; do proto="$p"; port="$po"; stream="$st"; done \
    < <(sqlite3 "$XUI_DB" "SELECT protocol, port, COALESCE(stream_settings,'') FROM inbounds WHERE id=$id AND enable=1;" 2>/dev/null || true)
  [[ -z "$proto" ]] && { err "РРЅР±Р°СѓРЅРґ #$id РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  # --- С‚РёРїС‹, СЃ РєРѕС‚РѕСЂС‹РјРё СЃРєСЂРёРїС‚ РЅРµ СЂР°Р±РѕС‚Р°РµС‚ / РєРѕС‚РѕСЂС‹Рµ РЅРµ РЅСѓР¶РЅРѕ С‚СЂРѕРіР°С‚СЊ ---
  if is_udp_proto "$proto"; then
    warn "РЎ РґР°РЅРЅС‹Рј С‚РёРїРѕРј РїРѕРґРєР»СЋС‡РµРЅРёСЏ СЃРєСЂРёРїС‚ РЅРµ СЂР°Р±РѕС‚Р°РµС‚: #$id вЂ” $proto (UDP). SNI-СЃРєСЂС‹С‚РёРµ Р·Р° 443 РїСЂРёРјРµРЅРёРјРѕ С‚РѕР»СЊРєРѕ Рє TCP (TLS/Reality)."
    return 0
  fi
  if [[ "$proto" == "tproxy" ]]; then
    warn "#$id tproxy вЂ” СЌС‚Рѕ tg web proxy: Р·Р° 443 РІРµРґС‘С‚ СЃРІРѕР№ РјР°СЂС€СЂСѓС‚ (setup_tproxy_web), РѕС‚РґРµР»СЊРЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° РЅРµ РЅСѓР¶РЅР°."
    return 0
  fi
  # VLESS XHTTP Р±РµР· security вЂ” РєР°РЅРґРёРґР°С‚ РЅР° CDN:
  # РІРѕРїСЂРѕСЃ Р·Р°РґР°С‘С‚СЃСЏ РЅРёР¶Рµ, РѕС‚РєР°Р· РѕС‚ CDN СЃ РіРѕР»С‹Рј xhttp РІСЃС‘ СЂР°РІРЅРѕ РЅРµ СЃРїСЂСЏС‚Р°С‚СЊ Р·Р° SNI
  if [[ "$proto" != "vless" ]] && ! grep -Eqi '"security": ?"tls"|"security":"tls"|reality' <<<"$stream" \
     && [[ "$proto" != naive* && "$proto" != "anytls" && "$proto" != trust* ]]; then
    if ! grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"$stream"; then
      warn "РЎ РґР°РЅРЅС‹Рј С‚РёРїРѕРј РїРѕРґРєР»СЋС‡РµРЅРёСЏ СЃРєСЂРёРїС‚ РЅРµ СЂР°Р±РѕС‚Р°РµС‚: #$id ($proto, TLS/Reality РЅРµ РЅР°Р№РґРµРЅС‹ РІ stream_settings)."
      return 0
    fi
    warn "#$id ($proto) вЂ” xhttp Р±РµР· security: Р·Р° SNI-СЂРѕСѓС‚РµСЂ РЅР°РїСЂСЏРјСѓСЋ РЅРµ РїСЂСЏС‡РµС‚СЃСЏ, С‚РѕР»СЊРєРѕ CDN-СЂРµР¶РёРј (nginx TLS)."
  fi

  # === VLESS XHTTP Р±РµР· security: РµРґРёРЅСЃС‚РІРµРЅРЅС‹Р№ СЂРµР¶РёРј СЃ РїСЂРµРґР»РѕР¶РµРЅРёРµРј CDN.
  # Р’Р°Р¶РЅРѕ: Р±РµР· СЌС‚РѕРіРѕ С…СѓРєР° РІРµС‚РєР° TLS РЅРёР¶Рµ РїРµСЂРµРїРёСЃР°Р»Р° Р±С‹ xhttp-РёРЅР±Р°СѓРЅРґ РІ РіРѕР»С‹Р№ tcp.
  if [[ "$proto" == "vless" ]] && grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"$stream"; then
    if [[ -n "$(cdn_profile_get "$id" 2>/dev/null)" ]]; then
      cdn_existing_menu "$id"
      pause
      return 0
    fi
  fi
  if xhttp_cdn_setup "$id" "$proto" "$port"; then
    pause
    return 0
  fi

  # tunnel-РёРЅР±Р°СѓРЅРґС‹ LucX: Р·Р°РїРѕР»РЅСЏРµРј settings (РґРѕРјРµРЅ, РєР»СЋС‡Рё, РєСЂРµРґС‹), РЅРµ stream
  case "$proto" in
    naive|anytls|trusttunnel|trust-tunnel)
      tunnel_inbound_fill "$id" "$proto" "$port"
      return $?
      ;;
  esac

  sni_stale_purge_quiet    # РёРЅР±Р°СѓРЅРґ РјРѕРіР»Рё СѓРґР°Р»РёС‚СЊ РІ РїР°РЅРµР»Рё вЂ” С‡РёСЃС‚РёРј С…РІРѕСЃС‚С‹ SNI
  sni_used_load 2>/dev/null || true
  local panel_domain="${PANEL_DOMAIN:-}"
  [[ -z "$panel_domain" ]] && panel_domain=$(xui_get subDomain)
  [[ -z "$panel_domain" ]] && ask panel_domain "Р”РѕРјРµРЅ РїР°РЅРµР»Рё" "panel.example.com" '^[a-zA-Z0-9.-]+$'
  [[ -n "$panel_domain" ]] && SNI_USED["$panel_domain"]="panel_backend"

  # --- vless reality: РІС‹Р±РёСЂР°РµРј СЂРµР¶РёРј РљРђРљ РїСЂРё СЃРѕР·РґР°РЅРёРё (СЃРІРѕР№/С‡СѓР¶РѕР№) ---
  local is_reality=false
  if [[ "$proto" == "vless" ]] && { grep -qi '"security": *"reality"' <<<"$stream" || grep -qi '"security":"reality"' <<<"$stream"; }; then
    is_reality=true
  fi
  if [[ "$is_reality" == true ]]; then
    local cur_dest="" cur_sni=""
    cur_dest=$(sqlite3 "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    cur_sni=$(sqlite3 "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.serverNames[0]'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    echo
    echo "  #$id vless reality вЂ” С‚РµРєСѓС‰Р°СЏ С†РµР»СЊ: ${cur_sni:-РЅРµ Р·Р°РґР°РЅР°}, dest: ${cur_dest:-РЅРµС‚}"
    echo "   1) Р§СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё В«РЅР°Р№С‚Рё С†РµР»РёВ» вЂ” Р·Р° 443 РїРѕ SNI С†РµР»Рё, СЃРµСЂС‚ РќР• РЅСѓР¶РµРЅ"
    echo "   2) РЎРІРѕР№ SNI-РґРѕРјРµРЅ вЂ” РЅСѓР¶РµРЅ СЃРµСЂС‚ + decoy"
    local rmode=""
    local def_mode="2"
    [[ -n "$cur_dest" && "$cur_dest" != 127.0.0.1:* ]] && def_mode="1"
    ask rmode "Р’С‹Р±РѕСЂ [1/2]" "$def_mode" '^[12]$'
    if [[ "$rmode" == "1" ]]; then
      local tgt=""
      reality_target_menu tgt "#$id"
      REALITY_EXT_TARGET="$tgt"
      reality_ext_hide "$id" "$tgt" "$port" || warn "  РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРїСЂСЏС‚Р°С‚СЊ #$id Р·Р° 443 РїРѕ С†РµР»Рё"
      systemctl restart x-ui >/dev/null 2>&1 || true
      nginx_reload || true
      return 0
    fi
  fi

  # РґРѕРјРµРЅ: РёР· СЃСѓС‰РµСЃС‚РІСѓСЋС‰РµРіРѕ РјР°СЂС€СЂСѓС‚Р°, РёРЅР°С‡Рµ СЃРїСЂРѕСЃРёС‚СЊ
  local domain=""
  domain=$(grep -E "^\s+\S+\s+inb_${id}_backend" "$SNI_CONF" 2>/dev/null | awk '{print $1}' | head -1 || true)
  if [[ -z "$domain" ]]; then
    local def="r.example.com"; [[ "$proto" == "anytls" ]] && def="at.example.com"
    ask_sni_domain domain "$id" "$def"
  fi
  local owner=""
  owner=$(sni_domain_owner "$domain" "$id") || true
  [[ -n "$owner" ]] && { err "Р”РѕРјРµРЅ $domain Р·Р°РЅСЏС‚ ($owner)"; return 1; }
  SNI_USED["$domain"]="inb_${id}_backend"

  sni_upstream_add "inb_${id}_backend" "$port"
  sni_map_add "$domain" "inb_${id}_backend"

  # СЃРµСЂС‚РёС„РёРєР°С‚
  cert_issue "$domain" || return 1
  local cp_line="" cert="" key=""
  cp_line=$(cert_paths "$domain") || true
  [[ -z "$cp_line" ]] && { err "cert РґР»СЏ $domain РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  cert="${cp_line%% *}"; key="${cp_line##* }"

  # Reality Рё VLESS/Trojan TCP TLS РїРѕР»СѓС‡Р°СЋС‚ Р±СЂР°СѓР·РµСЂРЅСѓСЋ decoy-СЃС‚СЂР°РЅРёС†Сѓ.
  # XHTTP TLS РЅР°РјРµСЂРµРЅРЅРѕ РёСЃРєР»СЋС‡С‘РЅ: РѕРЅ СЂР°Р±РѕС‚Р°РµС‚ РЅР°РїСЂСЏРјСѓСЋ РІ Xray.
  local tls_port="" rdtpl="default"
  if grep -qi reality <<<"$stream" || \
     { [[ "$proto" == "vless" || "$proto" == "trojan" ]] && grep -Eqi '"network"[[:space:]]*:[[:space:]]*"tcp"' <<<"$stream" && grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$stream"; }; then
    decoy_template_choose_impl rdtpl "Decoy-Р·Р°РіР»СѓС€РєР° РґР»СЏ $domain (СЃС‚СЂР°РЅРёС†Р° РЅР° СЌС‚РѕРј РґРѕРјРµРЅРµ)" "$(decoy_tpl_current "$domain")"
    rdtpl="${rdtpl:-$(decoy_tpl_for "$domain")}"
    decoy_tpl_store_set "$domain" "$rdtpl" >/dev/null 2>&1 || true
    tls_port=$(( 4444 + id ))
    while ss -tlnH "sport = :$tls_port" 2>/dev/null | grep -q .; do tls_port=$((tls_port+1)); done
    mk_decoy "$tls_port" "$domain" "$cert" "$key" "/var/www/decoy-$id" "$rdtpl"
     if grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$stream" && grep -Eqi '"network"[[:space:]]*:[[:space:]]*"tcp"' <<<"$stream"; then
       local plain_port=$((tls_port + 1))
        while ss -tlnH "sport = :$plain_port" 2>/dev/null | grep -q .; do plain_port=$((plain_port+1)); done
        mk_plain_fallback_decoy "$plain_port" "$domain" "/var/www/decoy-$id" || warn "  #$id: plain fallback-decoy РЅРµ СЃРѕР·РґР°РЅ"
        tls_fallback_set "$id" "$plain_port" || warn "  #$id: fallback РЅРµ РІРєР»СЋС‡С‘РЅ"
     fi
     log "  + decoy (TLS fallback/Reality) РЅР° РїРѕСЂС‚Сѓ $tls_port ($rdtpl)"
  else
    log "  decoy РЅРµ РЅСѓР¶РµРЅ ($proto вЂ” РЅРµ Reality)"
  fi
   # XHTTP TLS РѕСЃС‚Р°С‘С‚СЃСЏ TLS passthrough С‡РµСЂРµР· SNI РІ Xray.
   # HTTP-frontend Рё decoy РґР»СЏ СЌС‚РѕРіРѕ СЂРµР¶РёРјР° РЅРµ СЃРѕР·РґР°СЋС‚СЃСЏ.

   # hosts (РїРѕРґРїРёСЃРєРё): СЃС‚СЂРѕРєР° РІ РѕР±С‰РµР№ РіСЂСѓРїРїРµ В«РѕРґРёРЅ С…РѕСЃС‚В» (Р°РґСЂРµСЃ=РґРѕРјРµРЅ РїР°РЅРµР»Рё).
   # hosts_upsert СЃР°Рј РѕРїСЂРµРґРµР»СЏРµС‚ РіСЂСѓРїРїСѓ/SNI (С‡СѓР¶РѕР№ reality) Рё РёРґРµРјРїРѕС‚РµРЅС‚РµРЅ.
  hosts_upsert "$id" "$panel_domain"

  # --- РєР°РЅРѕРЅРёС‡РµСЃРєР°СЏ РїРµСЂРµР·Р°РїРёСЃСЊ stream_settings ---
  local new_stream=""
  if grep -qi reality <<<"$stream"; then
    local priv pub short_id keys xh_path transport="tcp" tr_settings=""
    priv=$(sqlite3 "$XUI_DB" "SELECT json_extract(stream_settings,'\$.realitySettings.privateKey') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    pub=$(sqlite3 "$XUI_DB" "SELECT json_extract(stream_settings,'\$.realitySettings.settings.publicKey') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    short_id=$(sqlite3 "$XUI_DB" "SELECT json_extract(stream_settings,'\$.realitySettings.shortIds[0]') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    xh_path=$(sqlite3 "$XUI_DB" "SELECT json_extract(stream_settings,'\$.xhttpSettings.path') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    if [[ -z "$priv" || "$priv" == "null" ]]; then
      keys=$(gen_reality_keys); priv="${keys%%|*}"; pub="${keys##*|}"
    fi
    [[ -z "$pub" || "$pub" == "null" ]] && pub=""
    [[ -z "$short_id" || "$short_id" == "null" ]] && short_id=$(gen_hex 8)
    if grep -qi '"network": *"xhttp"' <<<"$stream" || grep -qi '"network":"xhttp"' <<<"$stream"; then
      transport="xhttp"
      [[ -z "$xh_path" || "$xh_path" == "null" ]] && xh_path="/$(gen_hex 6)"
      tr_settings="\"xhttpSettings\":{\"path\":\"$xh_path\",\"host\":\"\",\"mode\":\"auto\"}"
    else
      tr_settings="\"tcpSettings\":{\"acceptProxyProtocol\":false,\"header\":{\"type\":\"none\"}}"
    fi
    new_stream="{\"network\":\"$transport\",\"security\":\"reality\",\"realitySettings\":{\"show\":false,\"xver\":0,\"dest\":\"127.0.0.1:$tls_port\",\"target\":\"127.0.0.1:$tls_port\",\"serverNames\":[\"$domain\"],\"privateKey\":\"$priv\",\"shortIds\":[\"$short_id\"],\"settings\":{\"publicKey\":\"$pub\",\"fingerprint\":\"firefox\",\"serverName\":\"\",\"spiderX\":\"/\"},\"fingerprint\":\"firefox\"},$tr_settings}"
  elif grep -Eq '"security": ?"tls"' <<<"$stream" || [[ "$proto" == naive* || "$proto" == "anytls" || "$proto" == trust* ]]; then
    new_stream="{\"network\":\"tcp\",\"security\":\"tls\",\"tlsSettings\":{\"serverName\":\"$domain\",\"minVersion\":\"1.2\",\"certificates\":[{\"certificateFile\":\"$cert\",\"keyFile\":\"$key\"}]},\"tcpSettings\":{\"acceptProxyProtocol\":false,\"header\":{\"type\":\"none\"}}}"
  else
    warn "РРЅР±Р°СѓРЅРґ #$id РЅРµ Reality/TLS вЂ” stream_settings РЅРµ РјРµРЅСЏР» (SNI/decoy/hosts РѕР±РЅРѕРІР»РµРЅС‹)"
  fi

  [[ -n "$new_stream" ]] && sqlite3 "$XUI_DB" "UPDATE inbounds SET stream_settings='$new_stream' WHERE id=$id;" 2>/dev/null || true

  # --- РїСЂРѕРІРµСЂРєР° СЂРµР·СѓР»СЊС‚Р°С‚Р° РїСЂСЏРјРѕ РёР· Р‘Р” ---
  local chk="" ok=false
  chk=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  grep -Eq "\"dest\": ?\"127\.0\.0\.1:$tls_port\"" <<<"$chk" && ok=true
  grep -q "certificateFile\":\"$cert\"" <<<"$chk" && ok=true
  echo
  if [[ "$ok" == true ]]; then
    log "Р“РѕС‚РѕРІРѕ вЂ” РёРЅР±Р°СѓРЅРґ #$id Р·Р°РїРёСЃР°РЅ:"
  else
    err "РџСЂРѕРІРµСЂРєР° РЅРµ РїСЂРѕС€Р»Р° вЂ” СЃС‚СЂРѕРєР° stream_settings:"
  fi
  echo "  ${chk:0:600}"
  nginx_reload || true
  systemctl restart x-ui >/dev/null 2>&1 || true
  log "Р’ РїР°РЅРµР»Рё: Р¦РµР»СЊ (dest) = 127.0.0.1:$tls_port В· SNI = $domain В· uTLS = firefox"
  pause
}

# =====================================================================
# Р”РћР‘РђР’РРўР¬ / РџР РћР’Р•Р РРўР¬ INBOUND
# =====================================================================
add_inbound() {
  line; echo -e "${B}   Р”РћР‘РђР’РРўР¬ / РџР РћР’Р•Р РРўР¬ INBOUND${N}"; line
  sqlite3 -header -column "$XUI_DB" "SELECT id, protocol, port, enable, remark FROM inbounds WHERE enable=1;" 2>/dev/null || true
  echo

  # РђРІС‚РѕРґРµС‚РµРєС‚: TCP-РёРЅР±Р°СѓРЅРґС‹, СЃРѕР·РґР°РЅРЅС‹Рµ СЂСѓРєР°РјРё РІ РїР°РЅРµР»Рё Рё РќР• СЃРїСЂСЏС‚Р°РЅРЅС‹Рµ Р·Р° 443.
  # РџСЂРё Р°РєС‚РёРІРЅРѕРј С„Р°Р№СЂРІРѕР»Рµ (allowlist) РёС… РїРѕСЂС‚ СЃРЅР°СЂСѓР¶Рё Р·Р°РєСЂС‹С‚ вЂ” РѕРЅРё РЅРµ СЂР°Р±РѕС‚Р°СЋС‚.
  local -a UNHID=()
  local _id _proto _port _st
  while IFS='|' read -r _id _proto _port; do
    [[ -z "$_id" || -z "$_proto" ]] && continue
    is_udp_proto "$_proto" && continue
    if [[ "$_proto" == "tproxy" ]]; then
      # tproxy РїСЂСЏС‡РµС‚СЃСЏ С‡РµСЂРµР· СЃРїРµС†-Р±СЌРєРµРЅРґС‹ (tg_backend РѕС‚ setup_tproxy_web
      # РёР»Рё "tproxy"), Р° РЅРµ inb_<id>_backend вЂ” РїСЂРѕРІРµСЂСЏРµРј РёС…, РёРЅР°С‡Рµ
      # СЃРїСЂСЏС‚Р°РЅРЅС‹Р№ tproxy РІРµС‡РЅРѕ РїРѕРїР°РґР°РµС‚ РІ В«РЅРµРїСЂСЏС‚Р°РЅРЅС‹РµВ»
      grep -qE '^\s+\S+\s+(tproxy|tg_backend);' "$SNI_CONF" 2>/dev/null && continue
      UNHID+=("$_id|$_proto|$_port")
      continue
    fi
    grep -qE "^[[:space:]]+[^[:space:]]+[[:space:]]+inb_${_id}_backend;[[:space:]]*$" "$SNI_CONF" 2>/dev/null && continue
    # LucX sidecar-РёРЅР±Р°СѓРЅРґС‹ РґРѕР»Р¶РЅС‹ СЃРєСЂС‹РІР°С‚СЊСЃСЏ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ
    # СЃРѕР·РґР°РЅРёСЏ: РЅРµ РїРѕРєР°Р·С‹РІР°РµРј РїРѕР»СЊР·РѕРІР°С‚РµР»СЋ РїРѕРІС‚РѕСЂРЅРѕРµ РѕРєРЅРѕ В«РЎРїСЂСЏС‚Р°С‚СЊ Р·Р° 443?В».
    if [[ "$_proto" == "naive" || "$_proto" == "anytls" || "$_proto" == "trusttunnel" || "$_proto" == "trust-tunnel" ]]; then
      local _side_pd="${PANEL_DOMAIN:-$(xui_get subDomain 2>/dev/null || true)}"
      configure_sni_for_inbound "$_id" "$_proto" "$_port" "$_side_pd" >/dev/null 2>&1 || true
      grep -qE "^[[:space:]]+[^[:space:]]+[[:space:]]+inb_${_id}_backend;[[:space:]]*$" "$SNI_CONF" 2>/dev/null && continue
    fi
    # CDN-РёРЅР±Р°СѓРЅРґ СЃРїСЂСЏС‚Р°РЅ С‡РµСЂРµР· cdn_frontend (nginx TLS), Р° РЅРµ inb_N вЂ” РЅРµ В«РЅРµРїСЂСЏС‚Р°РЅРЅС‹Р№В»
    cdn_profiles_load
    [[ " ${CDN_PROFILE_IDS[*]:-} " == *" $_id "* ]] && continue
    # С‡СѓР¶РѕР№ reality (dest = РІРЅРµС€РЅСЏСЏ С†РµР»СЊ) СѓР¶Рµ СЃРїСЂСЏС‚Р°РЅ Р·Р° 443 РїРѕ SNI С†РµР»Рё
    _st=$(sqlite3 "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$_id;" 2>/dev/null || true)
    grep -qi '"security": *"reality"' <<<"$_st" && ! grep -Eq '"dest": *"127\.0\.0\.1:' <<<"$_st" && continue
    UNHID+=("$_id|$_proto|$_port")
  done < <(sqlite3 "$XUI_DB" "SELECT id, protocol, port FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)
  if [[ ${#UNHID[@]} -gt 0 ]]; then
    warn "TCP-РёРЅР±Р°СѓРЅРґС‹ РќР• Р·Р° 443 вЂ” РїСЂРё РІРєР»СЋС‡С‘РЅРЅРѕРј С„Р°Р№СЂРІРѕР»Рµ СЃРЅР°СЂСѓР¶Рё РѕРЅРё РќР• СЂР°Р±РѕС‚Р°СЋС‚:"
    local _u
    for _u in "${UNHID[@]}"; do echo "    вЂў #${_u%%|*} ${_u#*|}"; done
    echo "    (UDP-РёРЅР±Р°СѓРЅРґС‹ Р·Р° 443 РЅРµ РїСЂСЏС‡СѓС‚СЃСЏ вЂ” РїРѕСЃР»Рµ СЃРѕР·РґР°РЅРёСЏ РїСЂРёРјРµРЅРё Рї.11 Р·Р°РЅРѕРІРѕ)"
    local hide_all=""
    askyn hide_all "РЎРїСЂСЏС‚Р°С‚СЊ РёС… Р·Р° 443 (РїРѕ РѕС‡РµСЂРµРґРё СЃРїСЂРѕСЃРёС‚ РґРѕРјРµРЅ)?" "y"
    if [[ "$hide_all" == true ]]; then
      local pd0="${PANEL_DOMAIN:-$(xui_get subDomain 2>/dev/null || true)}"
      for _u in "${UNHID[@]}"; do
        IFS='|' read -r _id _proto _port <<<"$_u"
        configure_sni_for_inbound "$_id" "$_proto" "$_port" "$pd0" || warn "  #$_id: РЅРµ СѓРґР°Р»РѕСЃСЊ вЂ” СЃРј. Рї.2 в†’ 2"
      done
      return 0
    fi
  fi

  echo "  1) РџСЂРѕРІРµСЂРёС‚СЊ РІСЃРµ РёРЅР±Р°СѓРЅРґС‹ РІ SNI"
  echo "  2) РќР°СЃС‚СЂРѕРёС‚СЊ РєРѕРЅРєСЂРµС‚РЅС‹Р№ РёРЅР±Р°СѓРЅРґ"
  echo "  3) РЎРѕР·РґР°С‚СЊ РЅРѕРІС‹Р№ РёРЅР±Р°СѓРЅРґ (VLESS Reality/TLS, anytls, naive, AWG...)"
  echo "  4) РџРѕС‡РёРЅРёС‚СЊ/Р·Р°РїРѕР»РЅРёС‚СЊ РёРЅР±Р°СѓРЅРґ (РґРѕРјРµРЅ+РєР»СЋС‡Рё+РєСЂРµРґС‹; Reality dest)"
  echo "  0) РќР°Р·Р°Рґ"
  local mode=""
  ask mode "Р’С‹Р±РѕСЂ" "1" '^[0-9]$'
  [[ "$mode" == "0" ]] && return 0
  if [[ "$mode" == "3" ]]; then
    create_inbounds_menu
    return 0
  fi
  if [[ "$mode" == "4" ]]; then
    fix_inbound
    return 0
  fi

  local panel_domain="${PANEL_DOMAIN:-}"
  [[ -z "$panel_domain" ]] && panel_domain=$(xui_get subDomain)
  [[ -z "$panel_domain" ]] && ask panel_domain "Р”РѕРјРµРЅ РїР°РЅРµР»Рё" "panel.example.com" '^[a-zA-Z0-9.-]+$'

  if [[ "$mode" == "1" ]]; then
    local id proto port stream count=0
    while IFS='|' read -r id proto port stream; do
      [[ -z "$id" || -z "$proto" ]] && continue
      is_udp_proto "$proto" && continue
      local existing=""
      existing=$(grep -E "^\s+\S+\s+inb_${id}_backend" "$SNI_CONF" 2>/dev/null | awk '{print $1}' || true)
      if [[ -n "$existing" ]]; then
         # Р”Р»СЏ Р»СЋР±РѕРіРѕ XHTTP Р±РµР· TLS РїСЂРµРґР»РѕР¶РёС‚СЊ CDN С‚Р°Рє Р¶Рµ, РєР°Рє РїСЂРё СЃРѕР·РґР°РЅРёРё VLESS XHTTP.
         if [[ "$proto" == "vless" ]] && inbound_is_xhttp_cdn_candidate "$stream" && [[ -z "$(cdn_profile_get "$id" 2>/dev/null)" ]]; then
           xhttp_cdn_setup "$id" "$proto" "$port" || true
         fi
        log "#$id ($proto/$port) в†’ SNI: $existing вњ“"
        # hosts-СЃС‚СЂРѕРєСѓ РќР• СЃРѕР·РґР°С‘Рј: РјРѕРґРµР»СЊ В«РјРёРЅРёРјСѓРј hostsВ» вЂ” СЃС‚СЂРѕРєРё РЅСѓР¶РЅС‹
        # С‚РѕР»СЊРєРѕ РіРµРЅРµСЂР°С‚РѕСЂСѓ СЃСЃС‹Р»РѕРє РїРѕРґРїРёСЃРѕРє, РЅР° РјР°СЂС€СЂСѓС‚РёР·Р°С†РёСЋ РЅРµ РІР»РёСЏСЋС‚
      else
        warn "#$id ($proto/$port) в†’ РќР• РІ SNI"
        askyn do_it "РќР°СЃС‚СЂРѕРёС‚СЊ #$id СЃРµР№С‡Р°СЃ?" "y"
        # shellcheck disable=SC2154 # Р·Р°РґР°С‘С‚СЃСЏ askyn РІС‹С€Рµ
        [[ "$do_it" == true ]] && configure_sni_for_inbound "$id" "$proto" "$port" "$panel_domain"
      fi
      count=$((count+1))
    done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id, protocol, port, COALESCE(stream_settings,'') FROM inbounds WHERE enable=1 AND port>0;" 2>/dev/null || true)
    # hosts-СЃС‚СЂРѕРєРё, СЃСЃС‹Р»Р°СЋС‰РёРµСЃСЏ РЅР° РЅРµСЃСѓС‰РµСЃС‚РІСѓСЋС‰РёРµ/РІС‹РєР»СЋС‡РµРЅРЅС‹Рµ РёРЅР±Р°СѓРЅРґС‹, вЂ” РјСѓСЃРѕСЂ
    # (РЅР°РїСЂРёРјРµСЂ, РѕС‚ СЃС‚Р°СЂРѕРіРѕ vless СЃ РЅРµРІРµСЂРЅРѕР№ РєРѕРЅРµС‡РЅРѕР№ С‚РѕС‡РєРѕР№). Р§РёСЃС‚РёРј.
    sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE inbound_id NOT IN (SELECT id FROM inbounds WHERE enable=1);" 2>/dev/null || true
    log "РџСЂРѕРІРµСЂРµРЅРѕ: $count"
    sni_cleanup_stale   # СѓР±СЂР°С‚СЊ SNI-Р·Р°РїРёСЃРё, РЅРµ Р·Р°РЅСЏС‚С‹Рµ РёРЅР±Р°СѓРЅРґР°РјРё
    return 0
  fi

  local id=""
  ask id "ID РёРЅР±Р°СѓРЅРґР°" "" '^[0-9]+$'
  local proto="" port=""
  while IFS='|' read -r p po; do proto="$p"; port="$po"; done < <(sqlite3 "$XUI_DB" "SELECT protocol, port FROM inbounds WHERE id=$id AND enable=1;" 2>/dev/null || true)
  [[ -z "$proto" ]] && { err "РРЅР±Р°СѓРЅРґ #$id РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  configure_sni_for_inbound "$id" "$proto" "$port" "$panel_domain"
}

# =====================================================================
# РЈР”РђР›РРўР¬ INBOUND
# =====================================================================
remove_inbound() {
  line; echo -e "${B}   РЈР”РђР›РРўР¬ INBOUND${N}"; line
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  sni_used_load 2>/dev/null || true

  # СЃРїРёСЃРѕРє: Р’РЎР• РёРЅР±Р°СѓРЅРґС‹ РїР°РЅРµР»Рё (Рё UDP С‚РѕР¶Рµ); SNI-РїСЂРёРІСЏР·РєР° вЂ” РїРѕРјРµС‚РєРѕР№,
  # РґРѕРјРµРЅ РїР°РЅРµР»Рё РїРѕРјРµС‡РµРЅ РєР°Рє РЅРµСѓРґР°Р»СЏРµРјС‹Р№ Р·РґРµСЃСЊ
  local -A SNI_BY_ID=()
  while IFS='|' read -r dom be iid; do
    [[ -n "$iid" ]] && SNI_BY_ID["$iid"]="$dom|$be"
  done < <(sni_map_domains)

  local iid proto port found=0 dom be
  while IFS='|' read -r iid proto port; do
    [[ -z "$iid" ]] && continue
    dom=""; be=""
    [[ -n "${SNI_BY_ID[$iid]:-}" ]] && IFS='|' read -r dom be <<<"${SNI_BY_ID[$iid]}"
    if [[ "$be" == "panel_backend" ]]; then
      printf "  #%-3s %-10s РїРѕСЂС‚ %-6s %s вЂ” РґРѕРјРµРЅ РџРђРќР•Р›Р (Р·РґРµСЃСЊ РЅРµ СѓРґР°Р»СЏС‚СЊ)\n" "$iid" "${proto:-?}" "${port:-?}" "$dom"
    else
      printf "  #%-3s %-10s РїРѕСЂС‚ %-6s %s\n" "$iid" "${proto:-?}" "${port:-?}" "${dom:+[SNI: $dom]}"
    fi
    found=$((found+1))
  done < <(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT id, protocol, port FROM inbounds ORDER BY id;" 2>/dev/null || true)
  [[ $found -eq 0 ]] && warn "РРЅР±Р°СѓРЅРґРѕРІ РІ РїР°РЅРµР»Рё РЅРµС‚"

  echo
  local id=""
  ask id "ID РёРЅР±Р°СѓРЅРґР°" "" '^[0-9]+$'

  local dom="" be=""
  while IFS='|' read -r d b i; do
    [[ "$i" == "$id" ]] && { dom="$d"; be="$b"; }
  done < <(sni_map_domains)

  local exists
  exists=$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE id=$id;" 2>/dev/null || echo 0)
  [[ "$exists" == "0" && -z "$dom" ]] && { err "РРЅР±Р°СѓРЅРґ #$id РЅРµ РЅР°Р№РґРµРЅ РЅРё РІ SNI, РЅРё РІ РїР°РЅРµР»Рё"; return 1; }

  # Р·Р°С‰РёС‚Р°: РґРѕРјРµРЅ РїР°РЅРµР»Рё СѓРґР°Р»СЏС‚СЊ РЅРµР»СЊР·СЏ
  if [[ "$be" == "panel_backend" ]]; then
    err "В«$domВ» вЂ” РґРѕРјРµРЅ РџРђРќР•Р›Р. РЈРґР°Р»СЏС‚СЊ РµРіРѕ Р·РґРµСЃСЊ РЅРµР»СЊР·СЏ (Рї.17 СѓР±РёСЂР°РµС‚ С‚РѕР»СЊРєРѕ СѓСЃС‚Р°СЂРµРІС€РёРµ Р·Р°РїРёСЃРё РїР°РЅРµР»Рё)."
    return 1
  fi

  # Р§С‚Рѕ РґРѕСЃС‚СѓРїРЅРѕ: SNI-РїСЂРёРІСЏР·РєР° / СЃР°Рј РёРЅР±Р°СѓРЅРґ / (РґР»СЏ CDN вЂ” СЃРЅСЏС‚РёРµ CDN-СЂРµР¶РёРјР°)
  local has_sni=false has_inb=false has_cdn=false
  [[ -n "$dom" ]] && has_sni=true
  [[ "$exists" != "0" ]] && has_inb=true
  [[ -n "$(cdn_profile_get "$id" 2>/dev/null)" ]] && has_cdn=true
  # tproxy (tg web proxy) РЅРёРєРѕРіРґР° РЅРµ Р±С‹РІР°РµС‚ РІ CDN-СЂРµР¶РёРјРµ: РЅРµ РїСЂРµРґР»Р°РіР°РµРј
  # В«СЃРЅСЏС‚СЊ С‚РѕР»СЊРєРѕ CDN-СЂРµР¶РёРјВ» Рё РЅРµ СѓРїРѕРјРёРЅР°РµРј CDN РІ РІРѕРїСЂРѕСЃРµ/РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРё
  local _rm_proto=""
  _rm_proto=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT protocol FROM inbounds WHERE id=$id;" 2>/dev/null | tr -d '[:space:]') || true
  [[ "$_rm_proto" == "tproxy" ]] && has_cdn=false

  echo
  echo "  Р§С‚Рѕ РґРµР»Р°С‚СЊ СЃ #$id${dom:+ (SNI: $dom)}${has_cdn:+ (CDN-СЂРµР¶РёРј)}?"
  local a_sni="" a_inb="" a_cdn="" n=0
  if [[ "$has_cdn" == true ]]; then
    n=$((n+1)); a_cdn="$n"
    echo "   $n) РЎРЅСЏС‚СЊ РўРћР›Р¬РљРћ CDN-СЂРµР¶РёРј (nginx-Р±Р»РѕРє/decoy/SNI/hosts/РїСЂРѕС„РёР»СЊ; РёРЅР±Р°СѓРЅРґ РѕСЃС‚Р°С‘С‚СЃСЏ)"
  fi
  if [[ "$has_sni" == true ]]; then
    n=$((n+1)); a_sni="$n"
    echo "   $n) РЈРґР°Р»РёС‚СЊ РўРћР›Р¬РљРћ SNI-РїСЂРёРІСЏР·РєСѓ (РёРЅР±Р°СѓРЅРґ РѕСЃС‚Р°С‘С‚СЃСЏ, СѓС…РѕРґРёС‚ СЃ 443)"
  fi
  if [[ "$has_inb" == true ]]; then
    n=$((n+1)); a_inb="$n"
    if [[ "$has_sni" == true ]]; then
      echo "   $n) РЈРґР°Р»РёС‚СЊ РёРЅР±Р°СѓРЅРґ РёР· РїР°РЅРµР»Рё + РµРіРѕ SNI-РїСЂРёРІСЏР·РєСѓ"
    else
      echo "   $n) РЈРґР°Р»РёС‚СЊ РёРЅР±Р°СѓРЅРґ РёР· РїР°РЅРµР»Рё"
    fi
  fi
  echo "   0) РћС‚РјРµРЅР°"
  line
  local action=""
  ask action "Р’С‹Р±РѕСЂ" "0" '^[0-9]+$'
  [[ "$action" == "0" ]] && return 0

  local do_sni=false do_inb=false do_cdn=false
  [[ -n "$a_sni" && "$a_sni" == "$action" ]] && do_sni=true
  [[ -n "$a_inb" && "$a_inb" == "$action" ]] && { do_inb=true; do_sni=true; }
  [[ -n "$a_cdn" && "$a_cdn" == "$action" ]] && do_cdn=true
  [[ "$do_sni" == false && "$do_inb" == false && "$do_cdn" == false ]] && { err "РќРµС‚ С‚Р°РєРѕРіРѕ РІС‹Р±РѕСЂР°"; return 1; }

  # РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ
  local what=""
  if [[ "$do_inb" == false && "$do_cdn" == true ]]; then
    what="С‚РѕР»СЊРєРѕ CDN-СЂРµР¶РёРј #$id (nginx-Р±Р»РѕРє/decoy/SNI-РјР°СЂС€СЂСѓС‚С‹/hosts/РїСЂРѕС„РёР»СЊ) вЂ” РёРЅР±Р°СѓРЅРґ РѕСЃС‚Р°РЅРµС‚СЃСЏ СЃ security=none"
  elif [[ "$do_inb" == false && "$do_sni" == true ]]; then
    what="SNI-РїСЂРёРІСЏР·РєСѓ ($dom) РґР»СЏ #$id вЂ” РёРЅР±Р°СѓРЅРґ РѕСЃС‚Р°РЅРµС‚СЃСЏ, РЅРѕ tcp-РїРѕСЂС‚ СѓР№РґС‘С‚ СЃ 443"
  elif [[ "$do_inb" == true && "$do_sni" == true && -n "$dom" ]]; then
    what="SNI-РїСЂРёРІСЏР·РєСѓ${dom:+ ($dom)} Р СЃР°Рј РёРЅР±Р°СѓРЅРґ #$id РёР· РїР°РЅРµР»Рё"
  else
    what="РёРЅР±Р°СѓРЅРґ #$id РёР· РїР°РЅРµР»Рё"
  fi
  # CDN-РїСЂРѕС„РёР»СЊ РёРЅР±Р°СѓРЅРґР° СѓРґР°Р»СЏРµС‚СЃСЏ РІРјРµСЃС‚Рµ СЃ Р»СЋР±С‹Рј РёР· РґРµР№СЃС‚РІРёР№
  local _cdn_row=""
  [[ "$do_cdn" == true || "$do_inb" == true ]] && _cdn_row=$(cdn_profile_get "$id" 2>/dev/null || true)
  if [[ -n "$_cdn_row" ]]; then
    local _o _c; _o=$(printf '%s' "$_cdn_row" | cut -d'|' -f3); _c=$(printf '%s' "$_cdn_row" | cut -d'|' -f4)
    what="CDN-РїСЂРѕС„РёР»СЊ #${id} (${_o}/${_c}) Рё ${what/#Рё /}"
  fi
  local confirm=""
  askyn confirm "РЈРґР°Р»РёС‚СЊ $what?" "y"
  [[ "$confirm" == true ]] || return 0

  # 0) CDN-РѕС‡РёСЃС‚РєР°: nginx-Р±Р»РѕРє, decoy, SNI-РјР°СЂС€СЂСѓС‚С‹, hosts, РїСЂРѕС„РёР»СЊ
  if [[ -n "$_cdn_row" ]]; then
    cdn_disable_for_inbound "$id"
  fi

  # 1) SNI-РїСЂРёРІСЏР·РєР°
  if [[ "$do_sni" == true ]]; then
    [[ -n "$dom" ]] && sni_map_remove "$dom"
    [[ -n "$be" && "$be" != "panel_backend" ]] && { sni_map_remove_backend "$be"; sni_upstream_remove "$be"; }
    unset "SNI_USED[$dom]" 2>/dev/null || true
    stack_del_decoy "$dom"   # decoy-Р±Р»РѕРє РІ stack.conf
    local _qd; _qd=$(sql_escape "$dom")
    sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE sni='$_qd' OR (inbound_id=$id AND port=443 AND (COALESCE(sni,'')='' OR sni='$_qd'));" 2>/dev/null || true
    log "SNI-РїСЂРёРІСЏР·РєР° СЃРЅСЏС‚Р°: $dom в†’ #$id"
  fi

  # 2) СЃР°Рј РёРЅР±Р°СѓРЅРґ. РџР°РЅРµР»СЊ РґРµСЂР¶РёС‚ in-memory reconcile, Р° Р·Р°С‰РёС‚Р° Р‘Р” РјРѕР¶РµС‚
  # РІРµСЂРЅСѓС‚СЊ СЃС‚СЂРѕРєСѓ РїСЂРё СЂР°Р±РѕС‚Р°СЋС‰РµРј x-ui. РџРѕСЌС‚РѕРјСѓ РѕСЃС‚Р°РЅР°РІР»РёРІР°РµРј РїР°РЅРµР»СЊ,
  # РІСЂРµРјРµРЅРЅРѕ РїСЂРёРѕСЃС‚Р°РЅР°РІР»РёРІР°РµРј Р·Р°С‰РёС‚РЅС‹Рµ С‚СЂРёРіРіРµСЂС‹ Рё СѓРґР°Р»СЏРµРј СЃРІСЏР·Р°РЅРЅС‹Рµ СЃС‚СЂРѕРєРё.
  if [[ "$do_inb" == true && "$exists" != "0" ]]; then
    cp -n "$XUI_DB" "${XUI_DB}.bak.$(date +%Y%m%d%H%M%S)" 2>/dev/null || true
    local _xui_was=false
    systemctl is-active --quiet x-ui 2>/dev/null && { _xui_was=true; systemctl stop x-ui >/dev/null 2>&1 || true; sleep 1; }
    db_protect_suspend >/dev/null 2>&1 || true
    sqlite3 -cmd ".timeout 3000" "$XUI_DB" "
      DELETE FROM client_inbounds WHERE inbound_id=$id;
      DELETE FROM hosts WHERE inbound_id=$id;
      DELETE FROM inbounds WHERE id=$id;
    " 2>/dev/null || true
    db_protect_resume >/dev/null 2>&1 || true
    local _left
    _left=$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE id=$id;" 2>/dev/null || echo 0)
    if [[ "$_left" == "0" ]]; then
      log "РРЅР±Р°СѓРЅРґ #$id СѓРґР°Р»С‘РЅ РёР· РїР°РЅРµР»Рё (x-ui.db)"
    else
      err "РРЅР±Р°СѓРЅРґ #$id РЅРµ СѓРґР°Р»РёР»СЃСЏ РёР· x-ui.db вЂ” РїСЂРѕРІРµСЂСЊ РїСЂР°РІР°/Р·Р°С‰РёС‚Сѓ Р‘Р”"
    fi
    [[ "$_xui_was" == true ]] && systemctl start x-ui >/dev/null 2>&1 || true
  fi

  nginx_reload || true
  # РџСЂРё СѓРґР°Р»РµРЅРёРё inbound x-ui СѓР¶Рµ Р±С‹Р» РѕСЃС‚Р°РЅРѕРІР»РµРЅ Рё Р·Р°РїСѓС‰РµРЅ РІС‹С€Рµ.
  # РџРѕРІС‚РѕСЂРЅС‹Р№ РЅРµРјРµРґР»РµРЅРЅС‹Р№ restart СЃРѕР·РґР°С‘С‚ РіРѕРЅРєСѓ СЃ РµРіРѕ РґРѕС‡РµСЂРЅРёРјРё tunnel-РїСЂРѕС†РµСЃСЃР°РјРё
  # Рё РјРѕР¶РµС‚ РїСЂРёРІРµСЃС‚Рё Рє failed/start-limit-hit. Р”Р»СЏ РѕСЃС‚Р°Р»СЊРЅС‹С… РґРµР№СЃС‚РІРёР№ restart РЅСѓР¶РµРЅ.
  if [[ "${do_inb:-false}" != true ]]; then
    systemctl restart x-ui >/dev/null 2>&1 || true
  fi
  log "Р“РѕС‚РѕРІРѕ."
}

# =====================================================================
# РћР§РРЎРўРљРђ SNI: РѕСЃС‚Р°РІР»СЏРµРј С‚РѕР»СЊРєРѕ Р·Р°РїРёСЃРё, Р·Р°РЅСЏС‚С‹Рµ РёРЅР±Р°СѓРЅРґР°РјРё
# =====================================================================
sni_map_domains() {
  [[ -f "$SNI_CONF" ]] || return 0
  local line
  local _re='^[[:space:]]+([A-Za-z0-9.-]+)[[:space:]]+inb_([0-9]+)_backend;'
  # Hysteria2 SNI-РјР°СЂС€СЂСѓС‚ В«РґРѕРјРµРЅ в†’ hysteria_N_webВ»: СЂР°РЅСЊС€Рµ С‚Р°РєРёРµ СЃС‚СЂРѕРєРё РЅРµ
  # РїР°СЂСЃРёР»РёСЃСЊ в†’ РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ РёРЅР±Р°СѓРЅРґР° Р·Р°РїРёСЃСЊ РІ РєР°СЂС‚Рµ РѕСЃС‚Р°РІР°Р»Р°СЃСЊ Рё
  # В«Р”РѕРјРµРЅ X СѓР¶Рµ Р·Р°РЅСЏС‚В» Р±Р»РѕРєРёСЂРѕРІР°Р» РїРѕРІС‚РѕСЂРЅРѕРµ РёСЃРїРѕР»СЊР·РѕРІР°РЅРёРµ РґРѕРјРµРЅР°.
  local _re_h='^[[:space:]]+([A-Za-z0-9.-]+)[[:space:]]+hysteria_([0-9]+)_web;'
  # tg web proxy: backend РЅР°Р·С‹РІР°РµС‚СЃСЏ В«tproxyВ» (Рї.3 СЃРѕР·РґР°РЅРёРµ) РёР»Рё В«tg_backendВ»
  # (setup_tproxy_web). Р Р°РЅСЊС€Рµ С‚Р°РєРёРµ СЃС‚СЂРѕРєРё РЅРµ РїР°СЂСЃРёР»РёСЃСЊ в†’ РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ
  # tg-РёРЅР±Р°СѓРЅРґР° Р·Р°РїРёСЃСЊ РѕСЃС‚Р°РІР°Р»Р°СЃСЊ РІ nginx-РєРѕРЅС„Рµ Рё РЅРµ СѓРґР°Р»СЏР»Р°СЃСЊ.
  local _re_tg='^[[:space:]]+([A-Za-z0-9.-]+)[[:space:]]+(tg_backend|tproxy);'
  while IFS= read -r line; do
    if [[ "$line" =~ $_re ]]; then
      echo "${BASH_REMATCH[1]}|inb_${BASH_REMATCH[2]}_backend|${BASH_REMATCH[2]}"
    elif [[ "$line" =~ $_re_h ]]; then
      echo "${BASH_REMATCH[1]}|hysteria_${BASH_REMATCH[2]}_web|${BASH_REMATCH[2]}"
    elif [[ "$line" =~ $_re_tg ]]; then
      # Р’РђР–РќРћ: Р·Р°С…РІР°С‚С‹РІР°РµРј РіСЂСѓРїРїС‹ РЎР РђР—РЈ вЂ” Р»СЋР±Р°СЏ РїСЂРѕРІРµСЂРєР° РІРёРґР° [[ =~ ]]
      # РјРµР¶РґСѓ РјР°С‚С‡РµРј Рё echo Р·Р°С‚РёСЂР°РµС‚ BASH_REMATCH (regex Р±РµР· СЃРєРѕР±РѕРє
      # РѕСЃС‚Р°РІР»СЏРµС‚ [1]/[2] РїСѓСЃС‚С‹РјРё), Рё РґРѕРјРµРЅ С‚РµСЂСЏР»СЃСЏ в†’ СЃС‚СЂРѕРєР° РЅРµ СѓРґР°Р»СЏР»Р°СЃСЊ.
      local tdom="${BASH_REMATCH[1]}" tbe="${BASH_REMATCH[2]}"
      # id РїСЂРёРІСЏР·С‹РІР°РµРј Рє Р¶РёРІРѕРјСѓ tproxy-РёРЅР±Р°СѓРЅРґСѓ РёР· Р‘Р”; В«0В» вЂ” РёРЅР±Р°СѓРЅРґР° РЅРµС‚
      # (Р·Р°РїРёСЃСЊ СЃС‡РёС‚Р°РµС‚СЃСЏ РјС‘СЂС‚РІРѕР№ Рё СѓС…РѕРґРёС‚ РІ РѕС‡РёСЃС‚РєСѓ); РїСѓСЃС‚Рѕ вЂ” Р‘Р” РЅРµРґРѕСЃС‚СѓРїРЅР°
      # (РїРµСЂРµСЃС‚СЂР°С…РѕРІРєР°: Р·Р°РїРёСЃСЊ РЅРµ С‚СЂРѕРіР°РµРј).
      local _tid=""
      if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
        _tid=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
               "SELECT COALESCE((SELECT id FROM inbounds WHERE protocol='tproxy' ORDER BY id LIMIT 1),0);" 2>/dev/null | tr -d '[:space:]') || _tid=""
      fi
      [[ "$_tid" =~ ^[0-9]+$ ]] || _tid=""
      echo "${tdom}|${tbe}|${_tid}"
    fi
  done < "$SNI_CONF"
}

sni_cleanup_stale() {
  line; echo -e "${B}   РћР§РРЎРўРљРђ SNI вЂ” РћРЎРўРђР’РРўР¬ РўРћР›Р¬РљРћ Р—РђРќРЇРўРћР•${N}"; line
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  [[ ! -f "$SNI_CONF" ]] && { warn "$SNI_CONF РЅРµ РЅР°Р№РґРµРЅ вЂ” С‡РёСЃС‚РёС‚СЊ РЅРµС‡РµРіРѕ"; return 0; }

  local -a dead_map=() dead_hosts=() dead_upstreams=()
  local tg_route_broken=0
  local row dom be iid cnt decoy pdom cur_panel uline uname
  cur_panel=$(xui_get subDomain)

  # 1) SNI-Р·Р°РїРёСЃРё (map), Р·Р° РєРѕС‚РѕСЂС‹РјРё РЅРµС‚ Р¶РёРІРѕРіРѕ РёРЅР±Р°СѓРЅРґР°
  while IFS='|' read -r dom be iid; do
    [[ -z "$dom" ]] && continue
    # Р Р°Р·Р±РѕСЂ id РЅРµ СѓРґР°Р»СЃСЏ вЂ” РїРµСЂРµСЃС‚СЂР°С…РѕРІРєР°: Р·Р°РїРёСЃСЊ РЅРµ С‚СЂРѕРіР°РµРј
    [[ ! "$iid" =~ ^[0-9]+$ ]] && continue
    # Р§РёС‚Р°РµРј Р‘Р” СЃ С‚Р°Р№РјР°СѓС‚РѕРј: x-ui РїРµСЂРёРѕРґРёС‡РµСЃРєРё РґРµСЂР¶РёС‚ Р±Р»РѕРєРёСЂРѕРІРєСѓ (С‚СЂР°С„РёРє-СЃС‚Р°С‚С‹),
    # Р±РµР· .timeout С‡С‚РµРЅРёРµ РїР°РґР°РµС‚ СЃ В«database is lockedВ» Рё РґР°С‘С‚ РџРЈРЎРўРћР™ РѕС‚РІРµС‚,
    # РєРѕС‚РѕСЂС‹Р№ СЂР°РЅСЊС€Рµ С‚СЂР°РєС‚РѕРІР°Р»СЃСЏ РєР°Рє В«РёРЅР±Р°СѓРЅРґР° РЅРµС‚В» в†’ Р»РѕР¶РЅРѕРµ СѓРґР°Р»РµРЅРёРµ.
    local cnt=""
    cnt=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
          "SELECT COUNT(*) FROM inbounds WHERE id=$iid;" 2>/dev/null | tr -d '[:space:]') || true
    if [[ -z "$cnt" ]]; then
      warn "  #$iid: Р‘Р” РЅРµ РѕС‚РІРµС‚РёР»Р° (Р±Р»РѕРєРёСЂРѕРІРєР°?) вЂ” SNI-Р·Р°РїРёСЃСЊ В«$domВ» СЃРѕС…СЂР°РЅСЏСЋ (РїРµСЂРµСЃС‚СЂР°С…РѕРІРєР°)"
      continue
    fi
    if [[ "$cnt" == "0" ]]; then
      warn "  #$iid: РІ $XUI_DB РёРЅР±Р°СѓРЅРґР° РЅРµС‚ вЂ” SNI-Р·Р°РїРёСЃСЊ В«$domВ» РЅР° СѓРґР°Р»РµРЅРёРµ"
      dead_map+=("$dom|$be|$iid")
      continue
    fi
    # РёРЅР±Р°СѓРЅРґ РµСЃС‚СЊ; РІС‹РєР»СЋС‡РµРЅРЅС‹Р№ (enable=0) вЂ” С‚РѕР¶Рµ В«РµСЃС‚СЊВ»: Р·Р°РїРёСЃСЊ СЃРѕС…СЂР°РЅСЏРµРј
    local en=""
    en=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
         "SELECT COALESCE(enable,'1') FROM inbounds WHERE id=$iid;" 2>/dev/null | tr -d '[:space:]') || true
    if [[ "$en" == "0" ]]; then
      log "  #$iid: РёРЅР±Р°СѓРЅРґ РІС‹РєР»СЋС‡РµРЅ (enable=0) вЂ” SNI-Р·Р°РїРёСЃСЊ В«$domВ» СЃРѕС…СЂР°РЅСЏСЋ (РІРєР»СЋС‡РёС€СЊ вЂ” Р·Р°СЂР°Р±РѕС‚Р°РµС‚ СЃСЂР°Р·Сѓ)"
      continue
    fi
    # tproxy (tg web proxy) РѕР±СЃР»СѓР¶РёРІР°РµС‚СЃСЏ РўРћР›Р¬РљРћ С‡РµСЂРµР· tg_backend (setup_tproxy_web).
    # Р›СЋР±С‹Рµ В«РґРѕРјРµРЅ в†’ inb_<id>_backendВ» РґР»СЏ РЅРµРіРѕ вЂ” РјСѓСЃРѕСЂ РїСЂРѕС€Р»С‹С… Р±Р°РіРѕРІ (svc-N.example.com).
    local tproto=""
    tproto=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
             "SELECT protocol FROM inbounds WHERE id=$iid;" 2>/dev/null | tr -d '[:space:]') || true
    if [[ "$tproto" == "tproxy" && "$be" != "tg_backend" && "$be" != "tproxy" ]]; then
      warn "  #$iid tproxy: РјР°СЂС€СЂСѓС‚ В«$dom в†’ $beВ» Р»РёС€РЅРёР№ (tg РІРµРґС‘С‚ tg_backend/tproxy) вЂ” РЅР° СѓРґР°Р»РµРЅРёРµ"
      tg_route_broken=1
      dead_map+=("$dom|$be|$iid")
      continue
    fi
    # Р§СѓР¶РѕР№ С‚Р°СЂРіРµС‚ reality, РєРѕС‚РѕСЂС‹Р№ РёРЅР±Р°СѓРЅРґ РЈР–Р• РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚ в†’ Р»РёС€РЅРёР№ SNI:
    # РєР»РёРµРЅС‚ Р±РµСЂС‘С‚ serverNames РёР· РёРЅР±Р°СѓРЅРґР°, РґРѕРјРµРЅ РІ nginx РґРѕР»Р¶РµРЅ РЎРћР’РџРђР”РђРўР¬,
    # РёРЅР°С‡Рµ СЃРѕРµРґРёРЅРµРЅРёРµ СѓС…РѕРґРёС‚ РІ default Рё РІРёСЃРЅРµС‚ РїРѕ С‚Р°Р№РјР°СѓС‚Сѓ.
    local t tgt="" dst=""
    for t in "${REALITY_TARGETS[@]}"; do [[ "$dom" == "$t" ]] && { tgt=1; break; }; done
    if [[ -n "$tgt" ]]; then
      dst=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),'') FROM inbounds WHERE id=$iid;" 2>/dev/null || true)
      dst="${dst%%:*}"
      dst="$(printf '%s' "$dst" | tr -d '[:space:]')"
      if [[ -z "$dst" ]]; then
        warn "  #$iid: РЅРµ СЃРјРѕРі СЃРІРµСЂРёС‚СЊ dest РёР· Р‘Р” вЂ” SNI-Р·Р°РїРёСЃСЊ В«$domВ» СЃРѕС…СЂР°РЅСЏСЋ (РїРµСЂРµСЃС‚СЂР°С…РѕРІРєР°)"
      elif [[ "$dst" != "$dom" ]]; then
        dead_map+=("$dom|$be|$iid")
      fi
    fi
  done < <(sni_map_domains)

  # 2) СЃС‚Р°СЂС‹Рµ РґРѕРјРµРЅС‹ РїР°РЅРµР»Рё РІ map (РЅРµ СЃРѕРІРїР°РґР°СЋС‚ СЃ С‚РµРєСѓС‰РёРј subDomain РїР°РЅРµР»Рё)
  local _pre='^[[:space:]]+([A-Za-z0-9.-]+)[[:space:]]+panel_backend;'
  while IFS= read -r pdom; do
    [[ -z "$pdom" ]] && continue
    [[ "$pdom" == "default" ]] && continue
    [[ -z "$cur_panel" ]] && continue            # РЅРµ Р·РЅР°РµРј Р°РєС‚СѓР°Р»СЊРЅС‹Р№ РґРѕРјРµРЅ вЂ” РЅРµ С‚СЂРѕРіР°РµРј
    [[ "$pdom" == "$cur_panel" ]] && continue
    dead_map+=("$pdom|panel_backend|")
  done < <(grep -E "$_pre" "$SNI_CONF" 2>/dev/null | awk '{print $1}' || true)

  # 3) hosts-Р·Р°РїРёСЃРё (РїРѕСЂС‚ 443 = В«SNI РІРєР»СЋС‡С‘РЅВ») Сѓ РёРЅР±Р°СѓРЅРґРѕРІ, РєРѕС‚РѕСЂС‹С… РЅРµС‚ РІ SNI
  cdn_profiles_load
  while IFS='|' read -r iid dom; do
    [[ -z "$iid" ]] && continue
    # CDN-РёРЅР±Р°СѓРЅРґ: РµРіРѕ hosts (sni=CDN-РґРѕРјРµРЅ) Р¶РёРІС‘С‚ С‡РµСЂРµР· cdn_frontend, РЅРµ inb_N
    [[ " ${CDN_PROFILE_IDS[*]:-} " == *" $iid "* ]] && continue
    grep -qE "^[[:space:]]+[A-Za-z0-9.-]+[[:space:]]+inb_${iid}_backend;" "$SNI_CONF" 2>/dev/null || dead_hosts+=("$iid|$dom")
  done < <(sqlite3 "$XUI_DB" "SELECT inbound_id, COALESCE(sni,'') FROM hosts WHERE port=443;" 2>/dev/null || true)

  # 4) upstream-С‹, РЅР° РєРѕС‚РѕСЂС‹Рµ РЅРµ СЃСЃС‹Р»Р°РµС‚СЃСЏ РЅРё РѕРґРЅР° map-Р·Р°РїРёСЃСЊ
  local _ure='^upstream ([A-Za-z0-9_-]+) \{'
  while IFS= read -r uline; do
    [[ "$uline" =~ $_ure ]] || continue
    uname="${BASH_REMATCH[1]}"
    [[ "$uname" == "panel_backend" ]] && continue
    # cdn_frontend РЅСѓР¶РµРЅ, РїРѕРєР° РµСЃС‚СЊ С…РѕС‚СЏ Р±С‹ РѕРґРёРЅ CDN-РїСЂРѕС„РёР»СЊ (РґР°Р¶Рµ Р±РµР· map вЂ” РїРѕС‡РёРЅРёС‚ cdn_repair)
    [[ "$uname" == "cdn_frontend" && ${#CDN_PROFILE_IDS[@]} -gt 0 ]] && continue
    grep -qE "[[:space:]]${uname};" "$SNI_CONF" 2>/dev/null || dead_upstreams+=("$uname")
  done < <(grep -E '^upstream ' "$SNI_CONF" 2>/dev/null || true)

  if [[ ${#dead_map[@]} -eq 0 && ${#dead_hosts[@]} -eq 0 && ${#dead_upstreams[@]} -eq 0 ]]; then
    log "Р’СЃРµ SNI-Р·Р°РїРёСЃРё Р·Р°РЅСЏС‚С‹ РёРЅР±Р°СѓРЅРґР°РјРё вЂ” С‡РёСЃС‚РёС‚СЊ РЅРµС‡РµРіРѕ."
    return 0
  fi

  echo "в–ё Р‘СѓРґРµС‚ СѓРґР°Р»РµРЅРѕ (РЅРµ Р·Р°РЅСЏС‚Рѕ РёРЅР±Р°СѓРЅРґР°РјРё / РЅРµР°РєС‚СѓР°Р»СЊРЅРѕ):"
  for row in "${dead_map[@]}"; do
    IFS='|' read -r dom be iid <<<"$row"
    if [[ -n "$iid" ]]; then
      if [[ "$be" == "inb_${iid}_backend" ]]; then
        echo "  map/upstream: $dom в†’ $be (РёРЅР±Р°СѓРЅРґР° #$iid РЅРµС‚)"
      elif [[ "$be" == "hysteria_${iid}_web" ]]; then
        echo "  map/upstream: $dom в†’ $be (РёРЅР±Р°СѓРЅРґР° #$iid РЅРµС‚)"
      elif [[ "$be" == "tg_backend" || "$be" == "tproxy" ]]; then
        echo "  map/upstream: $dom в†’ $be (tg-РёРЅР±Р°СѓРЅРґР° #$iid РЅРµС‚)"
      else
        echo "  map: $dom в†’ $be (Сѓ tproxy #$iid РґРѕР»Р¶РµРЅ РёСЃРїРѕР»СЊР·РѕРІР°С‚СЊСЃСЏ tg_backend/tproxy)"
      fi
    else
      echo "  map: $dom в†’ $be (РЅРµ С‚РµРєСѓС‰РёР№ РґРѕРјРµРЅ РїР°РЅРµР»Рё${cur_panel:+, СЃРµР№С‡Р°СЃ: $cur_panel})"
    fi
  done
  for row in "${dead_hosts[@]}"; do
    IFS='|' read -r iid dom <<<"$row"
    echo "  hosts (SNI-С„Р»Р°Рі): РёРЅР±Р°СѓРЅРґ #$iid, РґРѕРјРµРЅ ${dom:-вЂ”}"
  done
  for uname in "${dead_upstreams[@]}"; do
    echo "  upstream: $uname (РЅРµС‚ СЃСЃС‹Р»РѕРє РІ map)"
  done
  echo
  askyn confirm "РЈРґР°Р»РёС‚СЊ?" "y"
  [[ "$confirm" == true ]] || return 0

  for row in "${dead_map[@]}"; do
    IFS='|' read -r dom be iid <<<"$row"
    sni_map_remove "$dom"
    [[ -n "$be" && "$be" != "panel_backend" ]] && sni_upstream_remove "$be"
    unset "SNI_USED[$dom]" 2>/dev/null || true
    if [[ -n "$iid" ]]; then
      stack_del_decoy "$dom"
      sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE inbound_id=$iid AND port=443;" 2>/dev/null || true
      sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE sni='$dom';" 2>/dev/null || true
    fi
    log "РЈРґР°Р»РµРЅРѕ РёР· SNI: $dom"
  done
  for row in "${dead_hosts[@]}"; do
    IFS='|' read -r iid dom <<<"$row"
    sqlite3 "$XUI_DB" "DELETE FROM hosts WHERE inbound_id=$iid AND port=443;" 2>/dev/null || true
    log "РћС‡РёС‰РµРЅ SNI-С„Р»Р°Рі hosts: РёРЅР±Р°СѓРЅРґ #$iid"
  done
  for uname in "${dead_upstreams[@]}"; do
    sni_upstream_remove "$uname"
    log "РЈРґР°Р»С‘РЅ upstream: $uname"
  done

  # Р•СЃР»Рё СѓРґР°Р»СЏР»Рё Р»РёС€РЅРёР№ tproxy-РјР°СЂС€СЂСѓС‚ вЂ” РєР°РЅРѕРЅРёС‡РµСЃРєРёР№ tg-РјР°Рї РјРѕРі РѕС‚СЃСѓС‚СЃС‚РІРѕРІР°С‚СЊ
  # (РЅР°СЂСѓС€РµРЅРёРµ = tg Р±РµР· РјР°СЂС€СЂСѓС‚Р°). РџРµСЂРµСЃРѕР±РёСЂР°РµРј: setup_tproxy_web РёРґРµРјРїРѕС‚РµРЅС‚РµРЅ,
  # РІРµСЂРЅС‘С‚ upstream tg_backend + В«tg-РґРѕРјРµРЅ в†’ tg_backendВ».
  if [[ "$tg_route_broken" == 1 ]]; then
    log "Р’РѕСЃСЃС‚Р°РЅР°РІР»РёРІР°СЋ tg-РјР°СЂС€СЂСѓС‚ (tg_backend + РґРѕРјРµРЅ tproxy)вЂ¦"
    setup_tproxy_web || warn "  РїРµСЂРµСЃР±РѕСЂРєР° tg-РјР°СЂС€СЂСѓС‚Р° РЅРµ РїСЂРѕС€Р»Р° вЂ” Р·Р°РїСѓСЃС‚Рё setup_tproxy_web РІСЂСѓС‡РЅСѓСЋ"
  fi

  nginx_reload || true
  systemctl restart x-ui >/dev/null 2>&1 || true
  log "Р“РѕС‚РѕРІРѕ вЂ” РѕСЃС‚Р°Р»РёСЃСЊ С‚РѕР»СЊРєРѕ Р·Р°РїРёСЃРё, Р·Р°РЅСЏС‚С‹Рµ РёРЅР±Р°СѓРЅРґР°РјРё."
}

# =====================================================================
# РЎРњР•РќРђ DECOY
# =====================================================================
# в”Ђв”Ђ Р Р°Р·РґР°С‚СЊ decoy РІСЃРµРј SNI-РёРЅР±Р°СѓРЅРґР°Рј (РєСЂРѕРјРµ TG WEB-PROXY) в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
#   РЎРІРѕР№ Reality   в†’ nginx-РґРµРєРѕР№ (РјР°СЂРєРµСЂ stack.conf) + dest=127.0.0.1:<РїРѕСЂС‚>
#   VLESS+TLS (tcp)в†’ fallback в†’ 127.0.0.1:80 (Р±СЂР°СѓР·РµСЂ РІРёРґРёС‚ Р·Р°РіР»СѓС€РєСѓ)
#   TG WEB-PROXY   в†’ РїСЂРѕРїСѓСЃРє: СЃР°Рј РїСЂРѕРєСЃРёСЂСѓРµС‚ Р¶РёРІСѓСЋ С†РµР»СЊ
#   Р§СѓР¶РѕР№ Reality  в†’ РїСЂРѕРїСѓСЃРє: СЃРїСЂСЏС‚Р°РЅ Р·Р° SNI С†РµР»Рё, РґРµРєРѕР№ РЅРµ РЅСѓР¶РµРЅ
decoy_ensure_all() {
  line; echo -e "${B}   DECOY: Р РђР—Р”РђРўР¬ Р’РЎР•Рњ SNI-РРќР‘РђРЈРќР”РђРњ${N}"; line
  stack_ensure
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; pause; return 1; }
  local used_ports
  used_ports=$(grep -oE 'port=[0-9]+' "$STACK_CONF" 2>/dev/null | cut -d= -f2 | sort -u)
  local tls_cur=8443 _free=0
  while (( _free < 1 )); do
    if grep -qx "$tls_cur" <<<"$used_ports" || port_in_use "$tls_cur"; then tls_cur=$((tls_cur+1)); else _free=1; fi
  done
  local id dom be proto dest dport line_ok=0
  local hport hmeta hcp hc hk hroot
  local -a done_ids=()
  while IFS='|' read -r dom be; do
    if [[ "$be" =~ ^inb_([0-9]+)_backend$ || "$be" =~ ^hysteria_([0-9]+)_web$ ]]; then
      id="${BASH_REMATCH[1]}"
      [[ -z "$id" ]] && id="${BASH_REMATCH[2]}"
    else
      continue
    fi
    [[ " ${done_ids[*]} " == *" $id "* ]] && continue
    done_ids+=("$id")
    proto=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT protocol FROM inbounds WHERE id=$id AND enable=1;" 2>/dev/null || true)
    [[ -z "$proto" ]] && continue
    if [[ "$proto" == "tproxy" ]]; then
      echo "  #$id $dom вЂ” TG WEB-PROXY: РїСЂРѕРїСѓСЃРє (Р¶РёРІР°СЏ С†РµР»СЊ, РґРµРєРѕР№ РЅРµ РЅСѓР¶РµРЅ)"
      continue
    fi
    local st
    st=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    dest=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
      "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),json_extract(stream_settings,'\$.realitySettings.target'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    dest="${dest%%:*}"
    if [[ "$proto" == "hysteria" || "$proto" == "hysteria2" ]]; then
      hmeta=$(stack_decoy_meta "$dom" 2>/dev/null || true)
      if [[ -z "$hmeta" ]]; then
        hcp=$(cert_paths "$dom" 2>/dev/null || true)
        if [[ -n "$hcp" ]]; then
          hc="${hcp%% *}"; hk="${hcp##* }"; hport=$((47000 + id))
          while ss -tlnH "sport = :$hport" 2>/dev/null | grep -q .; do hport=$((hport+1)); done
          mk_decoy "$hport" "$dom" "$hc" "$hk" "/var/www/decoy-hysteria-$id" "$(decoy_tpl_for "$dom")" || continue
          sni_upstream_add "hysteria_${id}_web" "$hport"
          sni_map_add "$dom" "hysteria_${id}_web"
          line_ok=1
        else
          warn "  #$id $dom вЂ” СЃРµСЂС‚РёС„РёРєР°С‚ РЅРµ РЅР°Р№РґРµРЅ, TCP-decoy РѕС‚Р»РѕР¶РµРЅ"
        fi
      fi
      continue
    fi
    local policy=""
    policy=$(decoy_policy_classify "$id" "$proto" "$st")
    if [[ "$policy" == reality-external ]]; then
      echo "  #$id $dom вЂ” РІРЅРµС€РЅРёР№ Reality: РїСЂРѕРїСѓСЃРє (decoy РЅРµ РїСЂРёРјРµРЅСЏРµС‚СЃСЏ)"
      continue
    fi
    if [[ "$policy" == reality-local ]]; then
      local meta="" cp_line c="" k=""
      meta=$(stack_decoy_meta "$dom" 2>/dev/null || true)
      if [[ -n "$meta" ]]; then
        dport="${meta%% *}"
      else
        cp_line=$(cert_paths "$dom") || true
        if [[ -z "$cp_line" ]]; then
          warn "  #$id $dom вЂ” СЃРµСЂС‚Р° РЅРµС‚, РґРµРєРѕР№ РѕС‚Р»РѕР¶РµРЅ (Рї.10 в†’ РїРµСЂРµСЃР±РѕСЂРєР°, Р·Р°С‚РµРј РїРѕРІС‚РѕСЂРёС‚СЊ)"
          continue
        fi
        c="${cp_line%% *}"; k="${cp_line##* }"
        dport="$tls_cur"; tls_cur=$((tls_cur+1))
        mk_decoy "$dport" "$dom" "$c" "$k" "/var/www/decoy-$id" "$(decoy_tpl_for "$dom")"
      fi
      db_protect_suspend
      reality_set_dest "$id" "$dport" "$dom"
      log "  #$id $dom вЂ” РґРµРєРѕР№ РЅР° 127.0.0.1:$dport, Reality dest РІС‹СЃС‚Р°РІР»РµРЅ"
      line_ok=1
      continue
    fi
    # VLESS/Trojan TCP TLS РїРѕР»СѓС‡Р°СЋС‚ С‚РѕС‚ Р¶Рµ HTTPS-decoy С‡РµСЂРµР· Xray fallback.
    if [[ "$proto" == "vless" || "$proto" == "trojan" ]] && grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$st" && grep -Eqi '"network"[[:space:]]*:[[:space:]]*"(tcp|xhttp)"' <<<"$st"; then
      local tmeta tcp cpk tc tk trt
      tmeta=$(stack_decoy_meta "$dom" 2>/dev/null || true)
      if [[ -n "$tmeta" ]]; then
        tcp="${tmeta%% *}"
        local plain_tcp=$((tcp + 1))
        while ss -tlnH "sport = :$plain_tcp" 2>/dev/null | grep -q .; do plain_tcp=$((plain_tcp+1)); done
        mk_plain_fallback_decoy "$plain_tcp" "$dom" "/var/www/decoy-$id" || true
        tls_fallback_set "$id" "$plain_tcp" && line_ok=1
        echo "  #$id $dom вЂ” TLS fallback в†’ 127.0.0.1:$tcp"
      else
        cpk=$(cert_paths "$dom" 2>/dev/null || true)
        if [[ -n "$cpk" ]]; then
          tc="${cpk%% *}"; tk="${cpk##* }"; tcp=$(decoy_port_for_id "$id"); trt=$(decoy_tpl_for "$dom")
          mk_decoy "$tcp" "$dom" "$tc" "$tk" "/var/www/decoy-$id" "$trt" && mk_plain_fallback_decoy "$((tcp + 1))" "$dom" "/var/www/decoy-$id" && tls_fallback_set "$id" "$((tcp + 1))" && line_ok=1
          echo "  #$id $dom вЂ” HTTPS-decoy + TLS fallback РЅР° $tcp"
        else
          warn "  #$id $dom вЂ” СЃРµСЂС‚РёС„РёРєР°С‚ РЅРµ РЅР°Р№РґРµРЅ, TLS fallback РѕС‚Р»РѕР¶РµРЅ"
        fi
      fi
    else
      echo "  #$id $dom ($proto) вЂ” decoy РЅРµ РЅР°Р·РЅР°С‡Р°РµС‚СЃСЏ"
    fi
  done < <(awk '
    /^map / { inmap=1; next }
    inmap && /^}/ { inmap=0 }
    inmap && /^[[:space:]]/ && NF >= 2 {
      dom = $1; sub(/;$/, "", dom); be = $2; sub(/;$/, "", be)
      if (dom != "" && dom != "default" && ((be ~ /_backend$/ && be !~ /^(panel|agh)_backend$/) || be ~ /^hysteria_[0-9]+_web$/)) print dom "|" be
    }' "$SNI_CONF" 2>/dev/null)
  if (( line_ok )); then
    nginx_reload || true
  fi
  log "Р“РѕС‚РѕРІРѕ: РґРµРєРѕР№ РіР°СЂР°РЅС‚РёСЂРѕРІР°РЅ РґР»СЏ РІСЃРµС… РїСЂРёРјРµРЅРёРјС‹С… SNI-РёРЅР±Р°СѓРЅРґРѕРІ (TG WEB-PROXY РёСЃРєР»СЋС‡С‘РЅ)."
  pause
}

# в”Ђв”Ђ Р’С‹Р±РѕСЂРѕС‡РЅС‹Р№ decoy: РІС‹Р±СЂР°С‚СЊ SNI-РёРЅР±Р°СѓРЅРґ в†’ РµРіРѕ Р·Р°РіР»СѓС€РєР° в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
#   РЎРІРѕР№ Reality     в†’ РІС‹Р±РѕСЂ С€Р°Р±Р»РѕРЅР° (СЃРѕР·РґР°С‚СЊ/СЃРјРµРЅРёС‚СЊ), dest РѕР±РЅРѕРІРёС‚СЃСЏ
#   VLESS/Trojan+TLS в†’ РІРєР»/РІС‹РєР» fallback РЅР° 127.0.0.1:80
#   TG WEB-PROXY     в†’ РѕС‚РєР°Р· (РёРЅР±Р°СѓРЅРґ СЃР°Рј РїСЂРѕРєСЃРёСЂСѓРµС‚ Р¶РёРІСѓСЋ С†РµР»СЊ)
#   Р§СѓР¶РѕР№ Reality    в†’ РѕС‚РєР°Р· (СЃРїСЂСЏС‚Р°РЅ Р·Р° SNI С†РµР»Рё)
#   naive/anytls/trusttunnel  в†’ РѕС‚РєР°Р·: TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ sidecar LucX,
#       nginx-РґРµРєРѕР№ РІ С†РµРїРѕС‡РєСѓ РЅРµ РІСЃС‚Р°РІРёС‚СЊ (СЃР»РѕРјР°РµС‚ РїСЂРѕС‚РѕРєРѕР»)
decoy_pick_inbound() {
  stack_ensure
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; pause; return 1; }
  local -a L=()
  local dom be id proto port mark
  local preset_id="${1:-}" preset_dom="${2:-}" preset_port=""
  if [[ -n "$preset_id" ]]; then
    id="$preset_id"; dom="$preset_dom"
    proto=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT protocol FROM inbounds WHERE id=$id AND enable=1;" 2>/dev/null || true)
    preset_port=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT port FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  else
  echo
  echo -e "${B}в–ё SNI-РёРЅР±Р°СѓРЅРґС‹:${N}"
  while IFS='|' read -r dom be; do
    if [[ "$be" =~ ^inb_([0-9]+)_backend$ ]]; then
      id="${BASH_REMATCH[1]}"
    elif [[ "$be" =~ ^hysteria_([0-9]+)_web$ ]]; then
      id="${BASH_REMATCH[1]}"
    else
      continue
    fi
    proto=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT protocol FROM inbounds WHERE id=$id AND enable=1;" 2>/dev/null || true)
    [[ -z "$proto" ]] && continue
    st=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    # Р’ РјРµРЅСЋ СЃРјРµРЅС‹ decoy РїРѕРєР°Р·С‹РІР°РµРј СЃРѕР±СЃС‚РІРµРЅРЅС‹Р№ Reality Рё Hysteria TCP-decoy.
    port=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT port FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    if [[ "$proto" == "hysteria" || "$proto" == "hysteria2" ]]; then
      L+=("$dom|$id|$proto|$port")
      mark="РґРµРєРѕР№ РµСЃС‚СЊ"
      stack_decoy_meta "$dom" >/dev/null 2>&1 || mark="РґРµРєРѕСЏ РЅРµС‚"
      printf "  %2d) #%-3s %-30s %-9s :%-5s %s\n" "${#L[@]}" "$id" "$dom" "$proto" "$port" "$mark"
      continue
    fi
    [[ "$proto" == "vless" ]] || continue
    grep -qi '"security": *"reality"' <<<"$st" || continue
    port=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT port FROM inbounds WHERE id=$id;" 2>/dev/null || true)
    mark="РґРµРєРѕСЏ РЅРµС‚"
    stack_decoy_meta "$dom" >/dev/null 2>&1 && mark="РґРµРєРѕР№ РµСЃС‚СЊ"
    L+=("$dom|$id|$proto|$port")
    printf "  %2d) #%-3s %-30s %-9s :%-5s %s\n" "${#L[@]}" "$id" "$dom" "$proto" "$port" "$mark"
  done < <(awk '
    /^map / { inmap=1; next }
    inmap && /^}/ { inmap=0 }
    inmap && /^[[:space:]]/ && NF >= 2 {
      dom = $1; sub(/;$/, "", dom); be = $2; sub(/;$/, "", be)
      if (dom != "" && dom != "default" && ((be ~ /_backend$/ && be !~ /^(panel|agh)_backend$/) || be ~ /^hysteria_[0-9]+_web$/)) print dom "|" be
    }' "$SNI_CONF" 2>/dev/null)
    # Р”РѕР±Р°РІР»СЏРµРј Hysteria РґР°Р¶Рµ РїСЂРё СЃС‚Р°СЂРѕРј/РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РµРј SNI-map.
    while IFS='|' read -r hid hproto hport hdom; do
      [[ -n "$hid" ]] || continue
      [[ -z "$hdom" ]] && hdom="__missing_sni__"
      local already=false item
      for item in "${L[@]}"; do [[ "${item%%|*}" == "$hdom" ]] && already=true; done
      [[ "$already" == true ]] && continue
      L+=("$hdom|$hid|$hproto|$hport")
      mark="РґРµРєРѕСЏ РЅРµС‚"; stack_decoy_meta "$hdom" >/dev/null 2>&1 && mark="РґРµРєРѕР№ РµСЃС‚СЊ"
      printf "  %2d) #%-3s %-30s %-9s :%-5s %s\n" "${#L[@]}" "$hid" "$hdom" "$hproto" "$hport" "$mark"
    done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port FROM inbounds WHERE port>0 AND lower(protocol) LIKE '%hysteria%' ORDER BY id;" 2>/dev/null | while IFS='|' read -r hid hproto hport; do
      [[ -n "$hid" ]] || continue
      hdom=$(sqlite3 -noheader "$XUI_DB" "SELECT COALESCE((SELECT sni FROM hosts WHERE inbound_id=$hid AND port=443 LIMIT 1),(SELECT address FROM hosts WHERE inbound_id=$hid AND port=443 LIMIT 1),json_extract(stream_settings,'\$.tlsSettings.serverName'),json_extract(settings,'\$.tlsSettings.serverName'),json_extract(stream_settings,'\$.serverName'),json_extract(settings,'\$.serverName'),json_extract(stream_settings,'\$.hysteriaSettings.serverName'),json_extract(settings,'\$.hysteriaSettings.serverName'),json_extract(stream_settings,'\$.realitySettings.serverNames[0]'),'') FROM inbounds WHERE id=$hid;" 2>/dev/null | head -1 || true)
      [[ -z "$hdom" || "$hdom" == "null" ]] && hdom="__missing_sni__"
      printf '%s|%s|%s|%s\n' "$hid" "$hproto" "$hport" "$hdom"
    done)
  fi
  if [[ -n "$preset_id" ]]; then
    L=("$dom|$id|$proto|$preset_port")
  fi
  [[ ${#L[@]} -eq 0 ]] && { warn "РЎРѕР±СЃС‚РІРµРЅРЅС‹С… Reality-РёРЅР±Р°СѓРЅРґРѕРІ РЅРµ РЅР°Р№РґРµРЅРѕ"; pause; return 1; }
  local pick=""
  if [[ -n "$preset_id" ]]; then
    pick=1
  else
    echo
    ask pick "РќРѕРјРµСЂ Reality-РёРЅР±Р°СѓРЅРґР° (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
    [[ "$pick" == "0" ]] && return 0
  fi
  (( pick > ${#L[@]} )) && { err "РќРµС‚ С‚Р°РєРѕРіРѕ РЅРѕРјРµСЂР°"; pause; return 1; }
  IFS='|' read -r dom id proto port <<<"${L[$((pick-1))]}"
  local st
  st=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  local dest
  dest=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),json_extract(stream_settings,'\$.realitySettings.target'),'') FROM inbounds WHERE id=$id;" 2>/dev/null || true)
  dest="${dest%%:*}"
  if [[ "$proto" == "tproxy" ]]; then
    warn "TG WEB-PROXY ($dom): decoy РЅРµ СЃС‚Р°РІРёС‚СЃСЏ вЂ” РёРЅР±Р°СѓРЅРґ СЃР°Рј РїСЂРѕРєСЃРёСЂСѓРµС‚ Р¶РёРІСѓСЋ С†РµР»СЊ."
    pause; return 0
  fi
  if [[ -n "$dest" && "$dest" != "127.0.0.1" ]]; then
    warn "Р§СѓР¶РѕР№ Reality ($dom в†’ $dest): decoy РЅРµ РЅСѓР¶РµРЅ вЂ” РґРѕРјРµРЅ СЃРїСЂСЏС‚Р°РЅ Р·Р° SNI С†РµР»Рё."
    pause; return 0
  fi
  if [[ "$proto" == "hysteria" || "$proto" == "hysteria2" ]]; then
    local tpl="" meta dport="" c="" k="" root="" hcp hport
    decoy_template_choose_impl tpl "Decoy РґР»СЏ Hysteria #$id ($dom)" "$(decoy_tpl_current "$dom")"
    tpl="${tpl:-$(decoy_tpl_for "$dom")}"
    decoy_tpl_store_set "$dom" "$tpl" >/dev/null 2>&1 || true
    hcp=$(cert_paths "$dom" 2>/dev/null || true)
    if [[ -z "$hcp" && "$dom" != "__missing_sni__" ]]; then
      # Wildcard РјРѕР¶РµС‚ РёСЃРїРѕР»СЊР·РѕРІР°С‚СЊСЃСЏ РїР°РЅРµР»СЊСЋ, РґР°Р¶Рµ РµСЃР»Рё РјР°СЂРєРµСЂ wildcard
      # СЃРєСЂРёРїС‚Р° РїРѕС‚РµСЂСЏРЅ РїРѕСЃР»Рµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ backup. Р‘РµСЂС‘Рј С„Р°РєС‚РёС‡РµСЃРєРёРµ РїСѓС‚Рё
      # СЃРµСЂС‚РёС„РёРєР°С‚Р° РїР°РЅРµР»Рё Рё РїСЂРѕРІРµСЂСЏРµРј РёС… РЅР°Р»РёС‡РёРµ вЂ” РЅРѕРІС‹Р№ ACME-СЃРµСЂС‚ РЅРµ РЅСѓР¶РµРЅ.
      local _wc _wk
      _wc=$(xui_get webCertFile 2>/dev/null || true)
      _wk=$(xui_get webKeyFile 2>/dev/null || true)
      if [[ -f "$_wc" && -f "$_wk" ]]; then
        hcp="$_wc $_wk"
        log "РСЃРїРѕР»СЊР·СѓСЋ РґРµР№СЃС‚РІСѓСЋС‰РёР№ СЃРµСЂС‚РёС„РёРєР°С‚ РїР°РЅРµР»Рё РґР»СЏ $dom (РІРєР»СЋС‡Р°СЏ wildcard)"
      fi
    fi
    if [[ -z "$hcp" && "$dom" != "__missing_sni__" ]]; then
      warn "РЎРµСЂС‚РёС„РёРєР°С‚ $dom РЅРµ РЅР°Р№РґРµРЅ вЂ” РїС‹С‚Р°СЋСЃСЊ РІС‹РїСѓСЃС‚РёС‚СЊ РµРіРѕ РґР»СЏ HTTPS-decoy"
      cert_issue "$dom" || true
      hcp=$(cert_paths "$dom" 2>/dev/null || true)
    fi
    [[ -z "$hcp" ]] && { err "РЎРµСЂС‚Р° $dom РЅРµС‚ вЂ” decoy РѕС‚Р»РѕР¶РµРЅ; СЃРЅР°С‡Р°Р»Р° РІС‹РїСѓСЃС‚Рё СЃРµСЂС‚РёС„РёРєР°С‚ РІ СЂР°Р·РґРµР»Рµ В«РЎРµСЂС‚РёС„РёРєР°С‚С‹В»"; pause; return 1; }
    c="${hcp%% *}"; k="${hcp##* }"
    meta=$(stack_decoy_meta "$dom" 2>/dev/null || true)
    if [[ -n "$meta" ]]; then read -r dport root _ _ <<<"$meta"; else
      dport=$((47000 + id)); while ss -tlnH "sport = :$dport" 2>/dev/null | grep -q .; do dport=$((dport+1)); done
      root="/var/www/decoy-hysteria-$id"
    fi
    mk_decoy "$dport" "$dom" "$c" "$k" "$root" "$tpl"
    sni_upstream_add "hysteria_${id}_web" "$dport"
    sni_map_add "$dom" "hysteria_${id}_web"
    nginx_reload || true
    log "Hysteria #$id: TCP-decoy РѕР±РЅРѕРІР»С‘РЅ, UDP-РёРЅР±Р°СѓРЅРґ РЅРµ РёР·РјРµРЅС‘РЅ"
    pause; return 0
  fi
  if grep -qi '"security"[[:space:]]*:[[:space:]]*"reality"' <<<"$st" || \
     { [[ "$proto" == "vless" || "$proto" == "trojan" ]] && grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$st"; }; then
    local tpl="" meta dport="" c="" k="" root=""
    decoy_template_choose_impl tpl "Decoy РґР»СЏ #$id ($dom)" "$(decoy_tpl_current "$dom")"
    tpl="${tpl:-$(decoy_tpl_for "$dom")}"
    decoy_tpl_store_set "$dom" "$tpl" >/dev/null 2>&1 || true
    meta=$(stack_decoy_meta "$dom" 2>/dev/null || true)
    if [[ -n "$meta" ]]; then
      read -r dport root c k <<<"$meta"
      mk_decoy "$dport" "$dom" "$c" "$k" "$root" "$tpl"
    else
      local cp_line
      cp_line=$(cert_paths "$dom") || true
      [[ -z "$cp_line" ]] && { cert_issue "$dom" || true; cp_line=$(cert_paths "$dom") || true; }
      [[ -z "$cp_line" ]] && { err "РЎРµСЂС‚Р° $dom РЅРµС‚ вЂ” decoy РѕС‚Р»РѕР¶РµРЅ (Рї.10, Р·Р°С‚РµРј РїРѕРІС‚РѕСЂРёС‚СЊ)"; pause; return 1; }
      c="${cp_line%% *}"; k="${cp_line##* }"
      dport=$(( 4444 + id ))
      while ss -tlnH "sport = :$dport" 2>/dev/null | grep -q .; do dport=$((dport+1)); done
      mk_decoy "$dport" "$dom" "$c" "$k" "/var/www/decoy-$id" "$tpl"
    fi
    if grep -Eqi '"security"[[:space:]]*:[[:space:]]*"reality"' <<<"$st"; then
      db_protect_suspend
      reality_set_dest "$id" "$dport" "$dom" || { err "РќРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РїРёСЃР°С‚СЊ Reality dest РґР»СЏ #$id"; pause; return 1; }
    fi
    nginx_reload || { err "Decoy СЃРѕР·РґР°РЅ, РЅРѕ nginx РЅРµ РїРµСЂРµР·Р°РіСЂСѓР·РёР»СЃСЏ"; pause; return 1; }
    log "Decoy #$id ($dom): В«$tplВ» РЅР° 127.0.0.1:$dport"
    pause; return 0
  fi
  # РћР±С‹С‡РЅС‹Р№ TLS/С‚СѓРЅРЅРµР»СЊРЅС‹Р№ РёРЅР±Р°СѓРЅРґ Р±РµР· РїРѕРґРґРµСЂР¶РёРІР°РµРјРѕРіРѕ decoy РЅРµ РїРѕРїР°РґР°РµС‚ РІ СЃРїРёСЃРѕРє.
  # РЁС‚Р°С‚РЅР°СЏ СЃС…РµРјР° РјРµРЅСЋ вЂ” С‚РѕР»СЊРєРѕ СЃРѕР±СЃС‚РІРµРЅРЅС‹Р№ Reality Рё РїР°РЅРµР»СЊ.
  case "$proto" in
    naive|anytls|trusttunnel|trust-tunnel|hy2|hysteria)
      warn "$proto ($dom): TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ sidecar LucX вЂ” nginx-РґРµРєРѕР№ РІ С†РµРїРѕС‡РєСѓ РЅРµ РІСЃС‚Р°РІРёС‚СЊ (СЃР»РѕРјР°РµС‚ РїСЂРѕС‚РѕРєРѕР»)."
      warn "РџРѕСЃС‚РѕСЂРѕРЅРЅРёР№ РІРёРґ СѓР¶Рµ РґР°С‘С‚ СЃР°Рј sidecar (РѕС‚РІРµС‡Р°РµС‚, Р° РЅРµ РјРѕР»С‡РёС‚)."
      ;;
    *)
      warn "$proto ($dom): decoy-РјРµС…Р°РЅРёРєР° РґР»СЏ СЌС‚РѕРіРѕ РїСЂРѕС‚РѕРєРѕР»Р° РЅРµ РїСЂРёРјРµРЅСЏРµС‚СЃСЏ."
      ;;
  esac
  pause; return 0
}

# в”Ђв”Ђ РЈР±СЂР°С‚СЊ decoy РёРЅР±Р°СѓРЅРґРѕРІ: РІРµСЂРЅСѓС‚СЊ РєР°Рє РёР·РЅР°С‡Р°Р»СЊРЅРѕ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
#   РСЃС…РѕРґРЅР°СЏ РґРѕРєС‚СЂРёРЅР°: decoy-РІС…РѕСЃС‚ С‚РѕР»СЊРєРѕ Сѓ Reality-РёРЅР±Р°СѓРЅРґРѕРІ Рё РїР°РЅРµР»Рё.
#   Рџ.4.1 РјРѕРі СЂР°Р·РґР°С‚СЊ decoy РІСЃРµРј вЂ” Р·РґРµСЃСЊ СЃРЅРёРјР°РµС‚СЃСЏ РІСЃС‘ В«Р»РёС€РЅРµРµВ»:
#     вЂў decoy-Р±Р»РѕРєРё stack.conf Сѓ РЅРµ-Reality SNI-РґРѕРјРµРЅРѕРІ СѓРґР°Р»СЏСЋС‚СЃСЏ
#     вЂў vless/trojan+TLS: decoy-fallback (dest = 127.0.0.1:80 РёР»Рё 80)
#       СЃРЅРёРјР°РµС‚СЃСЏ С†РµР»РёРєРѕРј; Р±РѕРµРІРѕР№ fallback (РґСЂСѓРіРѕР№ dest) РЅРµ С‚СЂРѕРіР°РµС‚СЃСЏ
#     вЂў СЃРІРѕР№ Reality вЂ” decoy РѕСЃС‚Р°С‘С‚СЃСЏ (Р·Р°РіР»СѓС€РєР° РѕР±СЏР·Р°С‚РµР»СЊРЅР°)
#     вЂў TG WEB-PROXY вЂ” РїСЂРѕРїСѓСЃРє (decoy РµРјСѓ РЅРµ СЃС‚Р°РІРёС‚СЃСЏ)

# в”Ђв”Ђ РЁР°Р±Р»РѕРЅС‹ decoy РїРѕ РґРѕРјРµРЅР°Рј: СЃРІРѕР№ С€Р°Р±Р»РѕРЅ (РёР»Рё СЃРІРѕР№ СЃР°Р№С‚) РєР°Р¶РґРѕРјСѓ РґРѕРјРµРЅСѓ в”Ђв”Ђ
# РњРµРЅСЋ: Р·Р°РґР°С‚СЊ С€Р°Р±Р»РѕРЅ РєР°Р¶РґРѕРјСѓ РґРѕРјРµРЅСѓ (РёР»Рё РѕРґРёРЅ РЅР° РІСЃРµС…), СЃР±СЂРѕСЃРёС‚СЊ Рє РѕР±С‰РµРјСѓ.

change_decoy() {
  line; echo -e "${B}   DECOY: Р”РћРЎРўРЈРџРќР«Р• РћР‘РЄР•РљРўР« Р”Р›РЇ РЎРњР•РќР«${N}"; line
  # change_decoy РјРѕР¶РµС‚ РІС‹Р·С‹РІР°С‚СЊСЃСЏ РёР· РіР»Р°РІРЅРѕРіРѕ РјРµРЅСЋ Р±РµР· РїСЂРµРґРІР°СЂРёС‚РµР»СЊРЅРѕРіРѕ
  # detect_env; Р±РµР· РЅРµРіРѕ XUI_DB РїСѓСЃС‚ Рё fallback-РїРѕРёСЃРє Hysteria РЅРµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ.
  detect_env
  stack_ensure
  local panel_dom=""
  panel_dom=$(xui_get subDomain 2>/dev/null || true)
  [[ -z "$panel_dom" || "$panel_dom" == "null" ]] && panel_dom=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$panel_dom" || "$panel_dom" == "null" ]] && { err "Р”РѕРјРµРЅ РїР°РЅРµР»Рё РЅРµ РЅР°Р№РґРµРЅ вЂ” СЃРЅР°С‡Р°Р»Р° Рї.1"; pause; return 1; }
  echo "  Р”РѕСЃС‚СѓРїРЅС‹Рµ РѕР±СЉРµРєС‚С‹:"
  local _panel_tpl=""
  _panel_tpl=$(decoy_tpl_current "$panel_dom" 2>/dev/null || true)
  [[ -z "$_panel_tpl" ]] && _panel_tpl="default"
  printf "   1) РџР°РЅРµР»СЊ вЂ” %-30s (decoy=%s)\n" "$panel_dom" "$_panel_tpl"
  local -a _decoy_rows=() _decoy_row
  # Hysteria РІС‹РІРѕРґРёС‚СЃСЏ РЅР°РїСЂСЏРјСѓСЋ РёР· Р‘Р” РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ РЅР°Р»РёС‡РёСЏ SNI-map.
  # Р­С‚Рѕ РІР°Р¶РЅРѕ РїРѕСЃР»Рµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ СЃС‚Р°СЂРѕРіРѕ Р±СЌРєР°РїР°: nginx-РєРѕРЅС„РёРіРѕРІ РјРѕР¶РµС‚ РЅРµ Р±С‹С‚СЊ.
  local _hid _hproto _hport _hjson _hdom
  while IFS='|' read -r _hid _hproto _hport _hjson; do
    [[ -n "$_hid" ]] || continue
    _hdom=$(grep -oE '"serverName"[[:space:]]*:[[:space:]]*"[^" ]+"' <<<"$_hjson" | head -1 | sed -E 's/.*"serverName"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/' || true)
    [[ -z "$_hdom" ]] && _hdom="__missing_sni__"
    _decoy_rows+=("$_hdom|$_hid|$_hport")
    _decoy_row="${#_decoy_rows[@]}"
    local _h_tpl="$(decoy_tpl_current "$_hdom" 2>/dev/null || true)"; [[ -z "$_h_tpl" ]] && _h_tpl="default"
    printf "   %s) Hysteria #%-3s вЂ” %-30s :%s (decoy=%s)\n" "$((_decoy_row+1))" "$_hid" "$_hdom" "$_hport" "$_h_tpl"
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port,COALESCE(stream_settings,'') FROM inbounds WHERE port>0 AND lower(protocol) LIKE '%hysteria%' ORDER BY id;" 2>/dev/null || true)
  local _d_dom _d_be _d_id _d_proto _d_st _d_port
  while IFS='|' read -r _d_dom _d_be; do
    [[ "$_d_be" =~ ^inb_([0-9]+)_backend$ ]] || continue
    _d_id="${BASH_REMATCH[1]}"
    _d_proto=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT protocol FROM inbounds WHERE id=$_d_id AND enable=1;" 2>/dev/null || true)
    _d_st=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$_d_id;" 2>/dev/null || true)
    # РўРѕР»СЊРєРѕ XHTTP+TLS РЅРµ РёРјРµРµС‚ decoy. XHTTP+Reality, РЅР°РїСЂРѕС‚РёРІ, РѕСЃС‚Р°РІР»СЏРµРј:
    # РґР»СЏ Reality decoy СЏРІР»СЏРµС‚СЃСЏ dest Рё РµРіРѕ РјРѕР¶РЅРѕ РјРµРЅСЏС‚СЊ.
    if grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"$_d_st" && \
       grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$_d_st"; then
      continue
    fi
    # Р’ СЃРїРёСЃРѕРє РїРѕРїР°РґР°СЋС‚ С‚РѕР»СЊРєРѕ СЂРµР°Р»СЊРЅРѕ РїРѕРґРґРµСЂР¶РёРІР°РµРјС‹Рµ РѕР±СЉРµРєС‚С‹:
    # СЃРѕР±СЃС‚РІРµРЅРЅС‹Р№ Reality, VLESS/Trojan TCP+TLS Рё Hysteria TCP-decoy.
    # Р§СѓР¶РѕР№ Reality (РІРЅРµС€РЅРёР№ dest) РёСЃРєР»СЋС‡Р°РµРј: Сѓ РЅРµРіРѕ decoy РЅРµ РїСЂРёРјРµРЅСЏРµС‚СЃСЏ.
    [[ "$_d_proto" == "vless" || "$_d_proto" == "trojan" ]] || continue
    local _d_is_reality=false _d_is_tls=false _d_dest=""
    grep -Eqi '"security"[[:space:]]*:[[:space:]]*"reality"' <<<"$_d_st" && _d_is_reality=true
    grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$_d_st" && _d_is_tls=true
    if [[ "$_d_is_reality" == true ]]; then
      _d_dest=$(sqlite3 -noheader "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),json_extract(stream_settings,'\$.realitySettings.target'),'') FROM inbounds WHERE id=$_d_id;" 2>/dev/null || true)
      _d_dest="${_d_dest%%:*}"
      [[ -n "$_d_dest" && "$_d_dest" != "127.0.0.1" ]] && continue
    elif [[ "$_d_is_tls" != true ]]; then
      continue
    fi
    _d_port=$(sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT port FROM inbounds WHERE id=$_d_id;" 2>/dev/null || true)
    _decoy_rows+=("$_d_dom|$_d_id|$_d_port")
    _decoy_row="${#_decoy_rows[@]}"
    local _d_tpl="$(decoy_tpl_current "$_d_dom" 2>/dev/null || true)"; [[ -z "$_d_tpl" ]] && _d_tpl="default"
    if [[ "$_d_is_tls" == true ]]; then
      printf "   %s) %s TLS #%-3s вЂ” %-30s :%s (decoy=%s)\n" "$((_decoy_row+1))" "${_d_proto^^}" "$_d_id" "$_d_dom" "$_d_port" "$_d_tpl"
    else
      printf "   %s) Reality #%-3s вЂ” %-30s :%s (decoy=%s)\n" "$((_decoy_row+1))" "$_d_id" "$_d_dom" "$_d_port" "$_d_tpl"
    fi
  done < <(awk '
    /^map / { inmap=1; next }
    inmap && /^}/ { inmap=0 }
    inmap && /^[[:space:]]/ && NF >= 2 {
      dom=$1; sub(/;$/, "", dom); be=$2; sub(/;$/, "", be)
      if (dom != "" && dom != "default" && (be ~ /^inb_[0-9]+_backend$/ || be ~ /^hysteria_[0-9]+_web$/)) print dom "|" be
    }' "$SNI_CONF" 2>/dev/null)
  # Р’РѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РёР· Р‘Р” РґР»СЏ TCP/TLS РјРѕР¶РµС‚ РїРѕРЅР°РґРѕР±РёС‚СЊСЃСЏ РїРѕСЃР»Рµ СЃС‚Р°СЂРѕРіРѕ backup;
  # XHTTP+TLS Р·РґРµСЃСЊ РЅР°РјРµСЂРµРЅРЅРѕ РЅРµ РїРѕРєР°Р·С‹РІР°РµС‚СЃСЏ вЂ” Сѓ РЅРµРіРѕ РЅРµС‚ decoy.
  while IFS='|' read -r _tid _tproto _tport _tst; do
    [[ "$_tproto" == "vless" || "$_tproto" == "trojan" ]] || continue
    grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$_tst" || continue
    # РСЃРєР»СЋС‡Р°РµРј С‚РѕР»СЊРєРѕ XHTTP+TLS; XHTTP+Reality РёРјРµРµС‚ decoy С‡РµСЂРµР· Reality dest.
    if grep -Eqi '"network"[[:space:]]*:[[:space:]]*"xhttp"' <<<"$_tst" && \
       grep -Eqi '"security"[[:space:]]*:[[:space:]]*"tls"' <<<"$_tst"; then
      continue
    fi
    _tdom=$(sqlite3 -noheader "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.tlsSettings.serverName'),json_extract(settings,'\$.tlsSettings.serverName'),'') FROM inbounds WHERE id=$_tid;" 2>/dev/null | head -1 || true)
    [[ -z "$_tdom" || "$_tdom" == "null" ]] && continue
    local _tid_seen=false _trow
    for _trow in "${_decoy_rows[@]}"; do
      [[ "${_trow#*|}" == "$_tid|"* ]] && _tid_seen=true
    done
    [[ "$_tid_seen" == true ]] && continue
    _decoy_rows+=("$_tdom|$_tid|$_tport")
    _decoy_row="${#_decoy_rows[@]}"
    local _t_tpl="$(decoy_tpl_current "$_tdom" 2>/dev/null || true)"; [[ -z "$_t_tpl" ]] && _t_tpl="default"
    printf "   %s) %s TLS #%-3s вЂ” %-30s :%s (decoy=%s)\\n" "$((_decoy_row+1))" "${_tproto^^}" "$_tid" "$_tdom" "$_tport" "$_t_tpl"
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port,COALESCE(stream_settings,'') FROM inbounds WHERE enable=1 AND port>0 AND (protocol='vless' OR protocol='trojan') ORDER BY id;" 2>/dev/null || true)
  # Hysteria РјРѕР¶РµС‚ Р±С‹С‚СЊ РІ Р‘Р”, РЅРѕ РµС‰С‘ РЅРµ РёРјРµС‚СЊ SNI-map (РЅР°РїСЂРёРјРµСЂ, РїРѕСЃР»Рµ
  # РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ СЃС‚Р°СЂРѕРіРѕ Р±СЌРєР°РїР°). Р”РѕР±Р°РІР»СЏРµРј РµС‘ РЅР°РїСЂСЏРјСѓСЋ РёР· stream_settings.
  while IFS='|' read -r _hid _hproto _hport; do
    [[ -n "$_hid" ]] || continue
    _d_dom=$(sqlite3 -noheader "$XUI_DB" "SELECT COALESCE(json_extract(stream_settings,'\$.tlsSettings.serverName'),json_extract(settings,'\$.tlsSettings.serverName'),'') FROM inbounds WHERE id=$_hid;" 2>/dev/null | head -1 || true)
    if [[ -z "$_d_dom" || "$_d_dom" == "null" ]]; then
      _d_dom=$(sqlite3 -noheader "$XUI_DB" "SELECT COALESCE(stream_settings,'') FROM inbounds WHERE id=$_hid;" 2>/dev/null | grep -oE '"serverName"[[:space:]]*:[[:space:]]*"[^"]+"' | head -1 | sed -E 's/.*"serverName"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/' || true)
    fi
    [[ -z "$_d_dom" || "$_d_dom" == "null" ]] && _d_dom="__missing_sni__"
    local _seen=false _row
    for _row in "${_decoy_rows[@]}"; do [[ "${_row%%|*}" == "$_d_dom" ]] && _seen=true; done
    [[ "$_seen" == true ]] && continue
    _decoy_rows+=("$_d_dom|$_hid|$_hport")
    _decoy_row="${#_decoy_rows[@]}"
    local _hm_tpl="$(decoy_tpl_current "$_d_dom" 2>/dev/null || true)"; [[ -z "$_hm_tpl" ]] && _hm_tpl="default"
    printf "   %s) Hysteria #%-3s вЂ” %-30s :%s (decoy=%s)\n" "$((_decoy_row+1))" "$_hid" "$_d_dom" "$_hport" "$_hm_tpl"
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT id,protocol,port FROM inbounds WHERE port>0 AND lower(protocol) LIKE '%hysteria%' ORDER BY id;" 2>/dev/null || true)
  # CDN-РёРЅР±Р°СѓРЅРґ РЅРµ РїРѕРїР°РґР°РµС‚ РІ SNI-map: РµРіРѕ decoy РѕР±СЃР»СѓР¶РёРІР°РµС‚СЃСЏ ORIGIN-РґРѕРјРµРЅРѕРј
  # С‡РµСЂРµР· nginx CDN-С„СЂРѕРЅС‚РµРЅРґ. РџРѕРєР°Р·С‹РІР°РµРј ORIGIN РІ СЌС‚РѕРј РјРµРЅСЋ РѕС‚РґРµР»СЊРЅРѕ.
  local -a _cdn_decoy_ids=()
  local _cid _cproto _corigin _ccdn _cpath _ctpl _cdport
  cdn_profiles_load
  while IFS='|' read -r _cid _cproto _corigin _ccdn _cpath _ctpl _cdport; do
    [[ -n "$_cid" && -n "$_corigin" ]] || continue
    _decoy_rows+=("$_corigin|$_cid|${_cdport:-0}")
    _cdn_decoy_ids+=("$_cid")
    _decoy_row="${#_decoy_rows[@]}"
    local _cdn_tpl="${_ctpl:-$(decoy_tpl_current "$_corigin" 2>/dev/null || true)}"; [[ -z "$_cdn_tpl" ]] && _cdn_tpl="default"
    printf "   %s) CDN ORIGIN #%-3s вЂ” %-30s :%s (decoy=%s)\n" "$((_decoy_row+1))" "$_cid" "$_corigin" "${_cdport:-0}" "$_cdn_tpl"
  done < <(cat "$CDN_PROFILES" 2>/dev/null)
  echo "   0) РќР°Р·Р°Рґ"
  local m=""
  ask m "РћР±СЉРµРєС‚" "1" '^[0-9]+$'
  [[ "$m" == "0" ]] && return 0
  if (( m > 1 )); then
    local _ri=$((m-2))
    (( _ri >= 0 && _ri < ${#_decoy_rows[@]} )) || { err "РќРµС‚ С‚Р°РєРѕРіРѕ РѕР±СЉРµРєС‚Р°"; pause; return 1; }
    IFS='|' read -r _pick_dom _pick_id _pick_port <<<"${_decoy_rows[$_ri]}"
    if [[ -n "$(cdn_profile_get "$_pick_id" 2>/dev/null)" ]]; then
      cdn_change_decoy "$_pick_id"
      return $?
    fi
    decoy_pick_inbound "$_pick_id" "$_pick_dom"
    return $?
  fi
  # в”Ђв”Ђ 1) decoy РґРѕРјРµРЅР° РїР°РЅРµР»Рё в”Ђв”Ђ
  local panel_conf="$STACK_CONF"
  local panel_dom=""
  panel_dom=$(xui_get subDomain 2>/dev/null || true)
  [[ -z "$panel_dom" || "$panel_dom" == "null" ]] && panel_dom=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$panel_dom" || "$panel_dom" == "null" ]] && { err "Р”РѕРјРµРЅ РїР°РЅРµР»Рё РЅРµ РЅР°Р№РґРµРЅ вЂ” СЃРЅР°С‡Р°Р»Р° Рї.1"; pause; return 1; }
  local domain="$panel_dom"
  log "Р”РѕРјРµРЅ РїР°РЅРµР»Рё: $domain"

  # РљРѕСЂРµРЅСЊ РїР°РЅРµР»Рё = РїСЂРѕРєСЃРё РЅР° AdGuard? РЎРјРµРЅСѓ decoy Р—РђРџР Р•Р©РђР•Рњ:
  # С€Р°Р±Р»РѕРЅ Р·Р°РјРµРЅРёС‚ РїСЂРѕРєСЃРё Рё СЃР»РѕРјР°РµС‚ AdGuard UI/DoH.
  # РџСЂРѕРІРµСЂСЏРµРј С„Р°РєС‚РёС‡РµСЃРєРёР№ proxy_pass Рё СЃРѕС…СЂР°РЅС‘РЅРЅС‹Р№ СЂРµР¶РёРј СѓСЃС‚Р°РЅРѕРІРєРё.
  local pd_any="" adg_port_now="" adg_panel_root=false
  pd_any=$(sed -n '/listen 127\.0\.0\.1:4443/,/^}/p' "$panel_conf" 2>/dev/null \
           | grep -oE 'proxy_pass https://127\.0\.0\.1:[0-9]+' || true)
  adg_port_now=$(adg_config_port 2>/dev/null || true)
  if [[ -n "$adg_port_now" ]] && grep -q ":$adg_port_now$" <<<"$pd_any"; then
    adg_panel_root=true
  fi
  if [[ "${ADG_PLACEMENT:-}" == "panel" ]] && [[ "${ADG_PRESENT:-false}" == true ]]; then
    adg_panel_root=true
  fi
  if [[ "$adg_panel_root" == true ]]; then
    warn "РљРѕСЂРµРЅСЊ РґРѕРјРµРЅР° РїР°РЅРµР»Рё РѕР±СЃР»СѓР¶РёРІР°РµС‚ AdGuard Home."
    warn "РЎРјРµРЅР° decoy Р—РђРџР Р•Р©Р•РќРђ: Р±СѓРґРµС‚ СЃР»РѕРјР°РЅ AdGuard UI/DoH."
    warn "РЎРЅР°С‡Р°Р»Р° РїРµСЂРµРЅРµСЃРё AdGuard С‡РµСЂРµР· Рї.1 РЅР° РѕС‚РґРµР»СЊРЅС‹Р№ SNI-РґРѕРјРµРЅ РёР»Рё РІ Р»РѕРєР°Р»СЊРЅС‹Р№ СЂРµР¶РёРј."
    pause; return 0
  fi
    local tpl=""
    decoy_template_choose tpl "РќРѕРІС‹Р№ decoy РїР°РЅРµР»Рё" "corporate"
    if [[ "$tpl" == custom:* ]]; then
      local custom_path="${tpl#custom:}"
      if [[ -d "$custom_path" ]]; then
        if panel_decoy_apply custom "$custom_path"; then
          log "Decoy РїР°РЅРµР»Рё: СЃРІРѕР№ СЃР°Р№С‚ РёР· $custom_path"
        else
          warn "РќРµ СѓРґР°Р»РѕСЃСЊ РѕР±РЅРѕРІРёС‚СЊ stack.conf вЂ” СЃРјРѕС‚СЂРё РѕС€РёР±РєРё РІС‹С€Рµ"
        fi
      else
        err "РџР°РїРєР° $custom_path РЅРµ РЅР°Р№РґРµРЅР°"
      fi
      pause; return 0
    fi
    # РµСЃР»Рё СЃРµР№С‡Р°СЃ PANEL_DECOY_DIR вЂ” symlink/РєР°С‚Р°Р»РѕРі РѕС‚ РїСЂРѕС€Р»РѕРіРѕ custom, РїРµСЂРµСЃРѕР·РґР°С‘Рј
    if [[ -L "$PANEL_DECOY_DIR" ]]; then
      rm -f "$PANEL_DECOY_DIR"
      panel_decoy_apply stub >/dev/null 2>&1 || true
    fi
    mkdir -p "$PANEL_DECOY_DIR" 2>/dev/null || true
    local tpl_src="$DECOY_TPL_DIR/$tpl.html"
    is_login_template "$tpl" && tpl_src="$DECOY_LOGIN_DIR/$tpl.html"
    if [[ -f "$tpl_src" ]]; then
      cp -f "$tpl_src" "$PANEL_DECOY_DIR/index.html" 2>/dev/null || true
      chown www-data:www-data "$PANEL_DECOY_DIR/index.html" 2>/dev/null || true
      # РћРґРЅРѕР№ Р·Р°РјРµРЅС‹ index.html РЅРµРґРѕСЃС‚Р°С‚РѕС‡РЅРѕ: РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ AdGuard РёР»Рё
      # РїСЂРµР¶РЅРµР№ СЃРјРµРЅС‹ decoy РІ stack.conf РјРѕРі РѕСЃС‚Р°С‚СЊСЃСЏ return 302 /404.html.
      # РџРµСЂРµСЃРѕР±РёСЂР°РµРј С‚РѕР»СЊРєРѕ РєРѕСЂРЅРµРІРѕР№ location РїР°РЅРµР»Рё, СЃРѕС…СЂР°РЅСЏСЏ webBasePath
      # Рё subPath РїРѕРґРїРёСЃРєРё.
      panel_decoy_apply stub "$PANEL_DECOY_DIR" || {
        warn "РќРµ СѓРґР°Р»РѕСЃСЊ РїСЂРёРјРµРЅРёС‚СЊ РєРѕСЂРЅРµРІРѕР№ location decoy РїР°РЅРµР»Рё"
        return 1
      }
      nginx_reload || true
      log "Decoy РїР°РЅРµР»Рё СЃРјРµРЅС‘РЅ РЅР° В«$tplВ»"
    else
      err "РЁР°Р±Р»РѕРЅ В«$tplВ» РЅРµ РЅР°Р№РґРµРЅ (РёС‰Сѓ $tpl_src). Р”РѕСЃС‚СѓРїРЅС‹:"
      ls -1 "$DECOY_TPL_DIR" 2>/dev/null | sed 's/^/    /'
    fi
    pause; return 0
}

# =====================================================================
# РЎРўРђРўРЈРЎ
# =====================================================================
show_status() {
  line; echo -e "${B}   РЎРўРђРўРЈРЎ${N}"; line
  echo "  nginx:    $(systemctl is-active nginx 2>/dev/null || echo unknown)"
  echo "  x-ui:     $(systemctl is-active x-ui 2>/dev/null || echo unknown)"
  [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]] && echo "  $ADG_SERVICE: $(systemctl is-active "$ADG_SERVICE" 2>/dev/null || echo unknown)"
  echo "  fail2ban: $(systemctl is-active fail2ban 2>/dev/null || echo unknown)"
  echo "  xray bin: ${XRAY_BIN:-РЅРµ РЅР°Р№РґРµРЅ}"

  # в”Ђв”Ђ Р”РѕСЃС‚СѓРїС‹: URL РїР°РЅРµР»Рё / AdGuard / DoH + Р»РѕРіРёРЅС‹-РїР°СЂРѕР»Рё РёР· cred-С„Р°Р№Р»РѕРІ
  local pdom="" ppath="" adg_url="" doh_url=""
  pdom=$(xui_get webDomain 2>/dev/null || true)
  [[ -z "$pdom" || "$pdom" == "null" ]] && pdom="${PANEL_DOMAIN:-}"
  ppath=$(xui_get webBasePath 2>/dev/null || true)
  [[ "$ppath" == "null" ]] && ppath=""
  echo; echo "в–ё Р”РѕСЃС‚СѓРїС‹:"
  if [[ -n "$pdom" ]]; then
    echo "  РџР°РЅРµР»СЊ:  https://$pdom$ppath"
  else
    echo "  РџР°РЅРµР»СЊ:  РґРѕРјРµРЅ РЅРµ Р·Р°РґР°РЅ"
  fi
  if [[ "$ADG_PRESENT" == true ]]; then
    # РЎРµСЂРІРёСЃ С‡РёСЃР»РёС‚СЃСЏ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Рј, РЅРѕ РЅРµ Р°РєС‚РёРІРµРЅ вЂ” С‡РµСЃС‚РЅРѕ РіРѕРІРѕСЂРёРј РѕР± СЌС‚РѕРј,
    # Р° РЅРµ СЂРёСЃСѓРµРј URL, РїРѕ РєРѕС‚РѕСЂРѕРјСѓ РІСЃС‘ СЂР°РІРЅРѕ 502.
    if [[ -n "$ADG_SERVICE" ]] && ! systemctl is-active --quiet "$ADG_SERVICE" 2>/dev/null; then
      echo "  AdGuard: СЃРµСЂРІРёСЃ '$ADG_SERVICE' РЅРµ Р°РєС‚РёРІРµРЅ (РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєР° вЂ” СЂР°Р·РґРµР» 7-2)"
    else
    # СЂРµР¶РёРј AdGuard: Р·Р° РїР°РЅРµР»СЊСЋ (РїСЂРѕРєСЃРё РІ 4443-Р±Р»РѕРєРµ) / РѕС‚РґРµР»СЊРЅС‹Р№ SNI-РґРѕРјРµРЅ / Р»РѕРєР°Р»СЊРЅРѕ
    if grep -q "listen 127.0.0.1:4443" "$STACK_CONF" 2>/dev/null && \
       sed -n '/listen 127\.0\.0\.1:4443/,/^}/p' "$STACK_CONF" 2>/dev/null | grep -q "proxy_pass https://127.0.0.1:"; then
      adg_url="https://$pdom/"
    elif grep -qE "^[[:space:]]+[A-Za-z0-9.-]+[[:space:]]+agh_backend;" "$SNI_CONF" 2>/dev/null; then
      local adom=""
      adom=$(grep -E "^[[:space:]]+[A-Za-z0-9.-]+[[:space:]]+agh_backend;" "$SNI_CONF" 2>/dev/null | awk '{print $1}' | head -1)
      [[ -n "$adom" ]] && adg_url="https://$adom/"
    fi
    if [[ -n "$adg_url" ]]; then
      doh_url="${adg_url}dns-query"
    else
      local aport=""
      aport=$(adg_config_port 2>/dev/null || true)
      adg_url="http://127.0.0.1:${aport:-3000} (Р»РѕРєР°Р»СЊРЅРѕ, SSH-С‚СѓРЅРЅРµР»СЊ)"
      doh_url="вЂ” (AdGuard Р»РѕРєР°Р»СЊРЅРѕ)"
    fi
    echo "  AdGuard: $adg_url"
    echo "  DoH:     $doh_url"
    fi
  fi
  # в”Ђв”Ђ РљСЂРµРґС‹: cred-С„Р°Р№Р»С‹ вЂ” СЌС‚Рѕ РЎРќРРњРћРљ РїР°СЂРѕР»СЏ РЅР° РјРѕРјРµРЅС‚ СѓСЃС‚Р°РЅРѕРІРєРё/СЃРјРµРЅС‹,
  # Р° РЅРµ Р¶РёРІС‹Рµ РґР°РЅРЅС‹Рµ: РїР°СЂРѕР»СЊ С‡Р°СЃС‚Рѕ РјРµРЅСЏСЋС‚ РїРѕР·Р¶Рµ, Рё РґР°РјРї СЃРѕРґРµСЂР¶РёРјРѕРіРѕ
  # РІРІРѕРґРёС‚ РІ Р·Р°Р±Р»СѓР¶РґРµРЅРёРµ. РџРѕРєР°Р·С‹РІР°РµРј РїСѓС‚СЊ Рё РґР°С‚Сѓ СЃРЅРёРјРєР°, РЅРµ СЃР°Рј РїР°СЂРѕР»СЊ.
  local cf cdate
  cf=/root/panel-credentials.txt
  if [[ -f "$cf" ]]; then
    cdate=$(grep -m1 -oE '[0-9]{4}-[0-9]{2}-[0-9]{2}' "$cf" 2>/dev/null || true)
    echo "  РљСЂРµРґС‹ РїР°РЅРµР»Рё:  $cf (СЃРЅРёРјРѕРє ${cdate:-Р±РµР· РґР°С‚С‹}; РїР°СЂРѕР»СЊ РјРµРЅСЏР»Рё вЂ” РёСЃРїРѕР»СЊР·СѓР№С‚Рµ СЃРІРѕР№)"
  fi
  if [[ "$ADG_PRESENT" == true && -f /root/adguard-credentials.txt ]]; then
    cdate=$(grep -m1 -oE '[0-9]{4}-[0-9]{2}-[0-9]{2}' /root/adguard-credentials.txt 2>/dev/null || true)
    echo "  РљСЂРµРґС‹ AdGuard: /root/adguard-credentials.txt (СЃРЅРёРјРѕРє ${cdate:-Р±РµР· РґР°С‚С‹})"
  fi

  echo; echo "в–ё SNI:"
  grep -E '^\s+[a-zA-Z0-9.-]+\.|^upstream' "$SNI_CONF" 2>/dev/null | sed 's/^/  /' || true
  echo; echo "в–ё Inbounds:"
  sqlite3 -header -column "$XUI_DB" "SELECT id, protocol, port, listen, enable, remark FROM inbounds ORDER BY id;" 2>/dev/null || true
  # Р±Р°РЅС‹: РІ С€Р°РїРєРµ РјРµРЅСЋ вЂ” СЃСѓРјРјР° РїРѕ РІСЃРµРј jail'Р°Рј, РґРµС‚Р°Р»Рё вЂ” РІ Рї.7; Р·РґРµСЃСЊ РЅРµ РґСѓР±Р»РёСЂСѓРµРј
  pause
}


# =====================================================================
# в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# рџ¤– TG-Р‘РћРў вЂ” Р’Р«РҐРћР” Р’ TELEGRAM Р РЈРџР РђР’Р›Р•РќРР• Р‘РћРўРћРњ
# Р‘РѕС‚ РІСЃС‚СЂРѕРµРЅ РІ stack-manager (СЂРµР¶РёРј --bot), РѕС‚РґРµР»СЊРЅРѕРіРѕ tg-stack-bot.sh Р±РѕР»СЊС€Рµ РЅРµС‚.
# РњРµРЅСЋ В«TG-РІС‹С…РѕРґВ» РёР· Р±РѕС‚Р° СѓР±СЂР°РЅРѕ: СЂРµР¶РёРј РІРµРґС‘С‚СЃСЏ РўРћР›Р¬РљРћ РѕС‚СЃСЋРґР° (SSH).
# State: /root/.tg-stack-bot-out.env вЂ” Р±РѕС‚ С‡РёС‚Р°РµС‚ РµРіРѕ РЅР° Р»РµС‚Сѓ (РїРѕ mtime,
# СЂРµСЃС‚Р°СЂС‚ Р±РѕС‚Р° РЅРµ РЅСѓР¶РµРЅ). РџСЂР°РІРєРё РґРµР»Р°СЋС‚СЃСЏ РІ xrayTemplateConfig (РїРµСЂРµР¶РёРІР°СЋС‚
# РїРµСЂРµСЃР±РѕСЂРєСѓ config.json РїР°РЅРµР»СЊСЋ): Р»РѕРєР°Р»СЊРЅС‹Р№ socks-РёРЅР±Р°СѓРЅРґ tgbot-in РЅР°
# 127.0.0.1:<РїРѕСЂС‚> + РїСЂР°РІРёР»Рѕ СЂРѕСѓС‚РёРЅРіР° РЅР° РІС‹Р±СЂР°РЅРЅС‹Р№ Р°СѓС‚Р±Р°СѓРЅРґ. РџРµСЂРµРґ РєР°Р¶РґРѕР№
# РїСЂР°РІРєРѕР№ вЂ” Р±СЌРєР°Рї config.json Рё Р‘Р” РІ /root/stack-backups. Р’РєР»СЋС‡РµРЅРёРµ вЂ” С‚РѕР»СЊРєРѕ
# РїРѕСЃР»Рµ Р¶РёРІРѕР№ РїСЂРѕРІРµСЂРєРё (HTTP 204 С‡РµСЂРµР· Р»РѕРєР°Р»СЊРЅС‹Р№ socks), РёРЅР°С‡Рµ РїРѕР»РЅС‹Р№ РѕС‚РєР°С‚.
# в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
BOT_OUT_FILE="/root/.tg-stack-bot-out.env"
BOT_ENV_FILE="/root/.tg-stack-bot.env"   # env-С„Р°Р№Р» СЋРЅРёС‚Р° Р±РѕС‚Р°: BOT_TOKEN/ADMIN_CHAT_ID (EnvironmentFile)
BOT_SVC="tg-stack-bot"
BOT_SM="/root/stack-manager.sh"           # Р±РѕС‚ РІСЃС‚СЂРѕРµРЅ: СЋРЅРёС‚ Р·Р°РїСѓСЃРєР°РµС‚ СЌС‚РѕС‚ СЃРєСЂРёРїС‚ РІ СЂРµР¶РёРјРµ --bot
BOT_SOCKS_IN="tgbot-in"
BOT_SOCKS_OUT="tgbot-out"
BOT_XRAY_CFG="/usr/local/x-ui/bin/config.json"

botout_state_load() { # state Р±РѕС‚Р° в†’ BO_MODE/BO_TAG/BO_PORT/BO_SOCKS/BO_OURS
  BO_MODE="direct"; BO_TAG=""; BO_PORT=""; BO_SOCKS=""; BO_OURS=0
  [[ -f "$BOT_OUT_FILE" ]] || return 0
  BO_MODE=$(grep -a '^TG_OUT_MODE=' "$BOT_OUT_FILE" | tail -1 | cut -d= -f2-)
  BO_TAG=$(grep -a '^TG_OUT_TAG=' "$BOT_OUT_FILE" | tail -1 | cut -d= -f2-)
  BO_PORT=$(grep -a '^TG_OUT_PORT=' "$BOT_OUT_FILE" | tail -1 | cut -d= -f2-)
  BO_SOCKS=$(grep -a '^TG_SOCKS_B64=' "$BOT_OUT_FILE" | tail -1 | cut -d= -f2-)
  BO_OURS=$(grep -a '^TG_OURS=' "$BOT_OUT_FILE" | tail -1 | cut -d= -f2-)
  [[ "$BO_MODE" =~ ^(direct|socks|outbound)$ ]] || BO_MODE="direct"
  [[ "$BO_OURS" =~ ^[01]$ ]] || BO_OURS=0
}
botout_state_write() { # Р°С‚РѕРјР°СЂРЅРѕ, 600 вЂ” Р±РѕС‚ РїРѕРґС…РІР°С‚РёС‚ РїРѕ mtime Р±РµР· СЂРµСЃС‚Р°СЂС‚Р°
  local tmp="${BOT_OUT_FILE}.tmp"
  printf 'TG_OUT_MODE=%s\nTG_OUT_TAG=%s\nTG_OUT_PORT=%s\nTG_SOCKS_B64=%s\nTG_OURS=%s\n' \
    "$BO_MODE" "$BO_TAG" "$BO_PORT" "$BO_SOCKS" "$BO_OURS" > "$tmp"
  chmod 600 "$tmp" 2>/dev/null || true
  mv "$tmp" "$BOT_OUT_FILE"
}
botout_tpl_get() { # С€Р°Р±Р»РѕРЅ РёР· Р‘Р” вЂ” РџР•Р Р’РђРЇ СЃС‚СЂРѕРєР° РєР»СЋС‡Р° (РїР°РЅРµР»СЊ С‡РёС‚Р°РµС‚ РµС‘ С‡РµСЂРµР· GORM First()); РґСѓР±Р»РёРєР°С‚С‹ РєР»СЋС‡Р° РёРіРЅРѕСЂРёСЂСѓРµРј
  [[ -n "${XUI_DB:-}" && -f "$XUI_DB" ]] || detect_env >/dev/null 2>&1 || true
  [[ -n "${XUI_DB:-}" && -f "$XUI_DB" ]] || { err "Р‘Р” РїР°РЅРµР»Рё (x-ui.db) РЅРµ РЅР°Р№РґРµРЅР°"; return 1; }
  local t v
  t=$(sqlite3 -cmd ".timeout 1000" "$XUI_DB" "SELECT value FROM settings WHERE key='xrayTemplateConfig' ORDER BY id ASC LIMIT 1;" 2>/dev/null)
  if [[ -z "$t" ]]; then
    warn "xrayTemplateConfig РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚ вЂ” СЃРѕР·РґР°СЋ РёР· СЂР°Р±РѕС‡РµРіРѕ config.json (РёРЅР±Р°СѓРЅРґС‹ РёР· Р‘Р” СѓР±РёСЂР°СЋС‚СЃСЏ, api РѕСЃС‚Р°С‘С‚СЃСЏ)"
    t=$(jq -c '.inbounds = [.inbounds[] | select(.tag=="api")]' "$BOT_XRAY_CFG" 2>/dev/null) || { err "РЅРµ СѓРґР°Р»РѕСЃСЊ РїСЂРѕС‡РёС‚Р°С‚СЊ $BOT_XRAY_CFG"; return 1; }
    [[ -n "$t" ]] || { err "РїСѓСЃС‚РѕР№ С€Р°Р±Р»РѕРЅ РёР· config.json"; return 1; }
    v=$(printf '%s' "$t" | sed "s/'/''/g")
    sqlite3 -cmd ".timeout 2000" "$XUI_DB" "INSERT OR REPLACE INTO settings (key,value) VALUES ('xrayTemplateConfig','$v');" 2>/dev/null \
      || { err "РЅРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РїРёСЃР°С‚СЊ СЃРѕР·РґР°РЅРЅС‹Р№ С€Р°Р±Р»РѕРЅ РІ Р‘Р”"; return 1; }
    log "xrayTemplateConfig СЃРѕР·РґР°РЅ РёР· С‚РµРєСѓС‰РµРіРѕ РєРѕРЅС„РёРіР°"
  fi
  printf '%s' "$t"
}
botout_backup() { # Р±СЌРєР°Рї РєРѕРЅС„РёРіР° Рё Р‘Р” РїРµСЂРµРґ РїСЂР°РІРєРѕР№ С€Р°Р±Р»РѕРЅР°
  local ts; ts=$(date +%Y%m%d-%H%M%S)
  mkdir -p "$BACKUP_DIR" 2>/dev/null || true
  cp -a "$BOT_XRAY_CFG" "$BACKUP_DIR/xray-config.pre-botout-$ts.json" || return 1
  [[ -n "${XUI_DB:-}" && -f "$XUI_DB" ]] && cp -a "$XUI_DB" "$BACKUP_DIR/x-ui.pre-botout-$ts.db"
  return 0
}
botout_free_port() { # РїРµСЂРІС‹Р№ СЃРІРѕР±РѕРґРЅС‹Р№ РёР· 10808-10810 в†’ stdout
  local p
  for p in 10808 10809 10810; do
    if ! ss -ltn 2>/dev/null | awk '{print $4}' | grep -qE ":${p}$"; then printf '%s' "$p"; return 0; fi
  done
  return 1
}
botout_apply() { # $1=add|remove $2=tag $3=port(add) $4=ours $5=outboundJSON(""=СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ С‚РµРі)
  local op=$1 tag=$2 port=$3 ours=${4:-0} objson=${5:-} newc v obArgs=(--argjson ob null)
  botout_backup || { err "РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРґРµР»Р°С‚СЊ Р±СЌРєР°Рї РїРµСЂРµРґ РїСЂР°РІРєРѕР№ вЂ” РѕС‚РјРµРЅСЏСЋ"; return 1; }
  [[ -n "$objson" ]] && obArgs=(--argjson ob "$objson")
  if [[ "$op" == "add" ]]; then
    newc=$(botout_tpl_get | jq -c --arg inb "$BOT_SOCKS_IN" --arg out "$tag" --argjson port "$port" "${obArgs[@]}" '
      del(.inbounds[] | select(.tag == $inb))
      | .routing.rules = ((.routing.rules // []) | map(select(((.inboundTag // []) | index($inb)) | not)))
      | if $ob != null then
          .outbounds = (((.outbounds // []) | map(select(.tag != $out))) + [($ob | .tag = $out)])
        else . end
      | .inbounds += [{listen:"127.0.0.1", port:$port, protocol:"socks", tag:$inb, settings:{auth:"noauth", udp:false}}]
      | .routing.rules = ([{type:"field", inboundTag:[$inb], outboundTag:$out}] + .routing.rules)
    ') || { err "jq РЅРµ СЃРјРѕРі РёР·РјРµРЅРёС‚СЊ С€Р°Р±Р»РѕРЅ"; return 1; }
  else
    if [[ "$ours" == "1" && -n "$tag" ]]; then
      newc=$(botout_tpl_get | jq -c --arg inb "$BOT_SOCKS_IN" --arg out "$tag" '
        del(.inbounds[] | select(.tag == $inb))
        | del(.outbounds[] | select(.tag == $out))
        | .routing.rules = ((.routing.rules // []) | map(select(((.inboundTag // []) | index($inb)) | not)))
      ') || { err "jq РЅРµ СЃРјРѕРі РёР·РјРµРЅРёС‚СЊ С€Р°Р±Р»РѕРЅ"; return 1; }
    else
      newc=$(botout_tpl_get | jq -c --arg inb "$BOT_SOCKS_IN" '
        del(.inbounds[] | select(.tag == $inb))
        | .routing.rules = ((.routing.rules // []) | map(select(((.inboundTag // []) | index($inb)) | not)))
      ') || { err "jq РЅРµ СЃРјРѕРі РёР·РјРµРЅРёС‚СЊ С€Р°Р±Р»РѕРЅ"; return 1; }
    fi
  fi
  [[ -n "$newc" ]] || { err "РїСѓСЃС‚РѕР№ СЂРµР·СѓР»СЊС‚Р°С‚ РїРѕСЃР»Рµ РїСЂР°РІРєРё С€Р°Р±Р»РѕРЅР° вЂ” Р‘Р” РЅРµ РјРµРЅСЏР»"; return 1; }
  printf '%s\n' "$newc" | jq -e '.inbounds and .outbounds and .routing' >/dev/null 2>&1 \
    || { err "РЅРµРІР°Р»РёРґРЅС‹Р№ С€Р°Р±Р»РѕРЅ РїРѕСЃР»Рµ РїСЂР°РІРєРё вЂ” Р‘Р” РЅРµ РјРµРЅСЏР»"; return 1; }
  v=$(printf '%s' "$newc" | sed "s/'/''/g")
  # РџРёС€РµРј Р’ РџР•Р Р’РЈР® СЃС‚СЂРѕРєСѓ РєР»СЋС‡Р° (РµС‘ С‡РёС‚Р°РµС‚ РїР°РЅРµР»СЊ вЂ” GORM First()) Рё РІС‹С‡РёС‰Р°РµРј
  # РґСѓР±Р»РёРєР°С‚С‹: СЃС‚Р°СЂС‹Р№ Р±РѕС‚-РєРѕРґ РґРµР»Р°Р» INSERT OR REPLACE Р±РµР· UNIQUE РїРѕ key Рё РЅР°РґСѓРІР°Р»
  # РєР»СЋС‡ В«СЃРєР»РµР№РєР°РјРёВ» С€Р°Р±Р»РѕРЅРѕРІ; РѕРґРЅР° СЃС‚СЂРѕРєР° СЃС…РѕРґРёС‚СЃСЏ РїСЂРё Р»СЋР±РѕР№ СЃРµРјР°РЅС‚РёРєРµ С‡С‚РµРЅРёСЏ.
  local chg dup
  chg=$(sqlite3 -cmd ".timeout 2000" "$XUI_DB" \
    "UPDATE settings SET value='$v' WHERE id=(SELECT MIN(id) FROM settings WHERE key='xrayTemplateConfig'); SELECT changes();" 2>/dev/null | tail -1)
  if [[ "$chg" == "0" ]]; then
    sqlite3 -cmd ".timeout 2000" "$XUI_DB" "INSERT INTO settings (key,value) VALUES ('xrayTemplateConfig','$v');" >/dev/null 2>&1 \
      || { err "РќРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РїРёСЃР°С‚СЊ С€Р°Р±Р»РѕРЅ РІ Р‘Р”"; return 1; }
  fi
  dup=$(sqlite3 -cmd ".timeout 2000" "$XUI_DB" \
    "DELETE FROM settings WHERE key='xrayTemplateConfig' AND id > (SELECT MIN(id) FROM settings WHERE key='xrayTemplateConfig'); SELECT changes();" 2>/dev/null | tail -1)
  [[ "${dup:-0}" =~ ^[0-9]+$ && "$dup" != "0" ]] && log "Р’С‹С‡РёС‰РµРЅРѕ РґСѓР±Р»РёРєР°С‚РѕРІ xrayTemplateConfig: $dup (РїР°РЅРµР»СЊ СЂР°Р±РѕС‚Р°РµС‚ СЃ РѕРґРЅРѕР№ СЃС‚СЂРѕРєРѕР№)"
  log "РџРµСЂРµР·Р°РїСѓСЃРєР°СЋ x-ui (Xray РїРµСЂРµСЃРѕР±РµСЂС‘С‚ РєРѕРЅС„РёРі РёР· С€Р°Р±Р»РѕРЅР°)вЂ¦"
  systemctl restart x-ui >/dev/null 2>&1 || true
  sleep 3
  return 0
}
botout_verify() { # $1=port в†’ 0, РµСЃР»Рё socks СЃР»СѓС€Р°РµС‚СЃСЏ Рё С‡РµСЂРµР· РЅРµРіРѕ РµСЃС‚СЊ РІС‹С…РѕРґ (204); РґРѕ 3 РїРѕРїС‹С‚РѕРє
  local port=$1 code try
  for try in 1 2 3; do
    if ss -ltn 2>/dev/null | awk '{print $4}' | grep -qE ":${port}$"; then
      code=$(curl -sk -m 12 --proxy "socks5h://127.0.0.1:${port}" -o /dev/null -w '%{http_code}' "https://www.google.com/generate_204" 2>/dev/null)
      [[ "$code" == "204" ]] && return 0
    fi
    sleep 3
  done
  return 1
}
botout_bot_note() { # Р±РѕС‚ Р·Р°Р±РёСЂР°РµС‚ state СЃР°Рј (mtime); СЃРѕРѕР±С‰Р°РµРј С‚РѕР»СЊРєРѕ Рѕ РЅРµСЃС‚Р°РЅРґР°СЂС‚РЅС‹С… СЃР»СѓС‡Р°СЏС…
  if systemctl is-active --quiet "$BOT_SVC" 2>/dev/null; then
    log "Р‘РѕС‚ РїРѕРґС…РІР°С‚РёС‚ РІС‹С…РѕРґ РЅР° Р»РµС‚Сѓ (state $BOT_OUT_FILE), СЂРµСЃС‚Р°СЂС‚ РЅРµ РЅСѓР¶РµРЅ"
  else
    warn "Р‘РѕС‚ ($BOT_SVC) СЃРµР№С‡Р°СЃ РЅРµ Р·Р°РїСѓС‰РµРЅ вЂ” РїСЂРёРјРµРЅРёС‚ СЂРµР¶РёРј РїСЂРё СЃС‚Р°СЂС‚Рµ"
  fi
}
bot_svc_installed() { systemctl cat "$BOT_SVC" >/dev/null 2>&1; }
bot_unit_migrate() { # СЃС‚Р°СЂС‹Р№ СЋРЅРёС‚ (РѕС‚РґРµР»СЊРЅС‹Р№ tg-stack-bot.sh / Restart=on-failure) в†’ РІСЃС‚СЂРѕРµРЅРЅС‹Р№ СЂРµР¶РёРј (stack-manager --bot, Restart=always); СЃ Р±СЌРєР°РїРѕРј
  local uf="/etc/systemd/system/${BOT_SVC}.service" ts changed=0
  ts=$(date +%Y%m%d-%H%M%S); mkdir -p /root/stack-backups
  cp -a "$uf" "/root/stack-backups/${BOT_SVC}.unit.pre-embed-$ts"
  if grep -q '^Restart=on-failure' "$uf" 2>/dev/null; then
    sed -i -e 's/^Restart=on-failure/Restart=always/' -e 's/^RestartSec=5/RestartSec=3/' "$uf"
    grep -q '^StartLimitIntervalSec=' "$uf" || sed -i '/^After=network-online.target/a StartLimitIntervalSec=0' "$uf"
    changed=1
  fi
  if grep -q 'ExecStart=.*tg-stack-bot\.sh' "$uf" 2>/dev/null; then
    sed -i "s|^ExecStart=.*|ExecStart=/usr/bin/env bash ${BOT_SM} --bot|" "$uf"
    log "РЎС‚Р°СЂС‹Р№ /root/tg-stack-bot.sh Р±РѕР»СЊС€Рµ РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ вЂ” РјРѕР¶РЅРѕ СѓРґР°Р»РёС‚СЊ"
    changed=1
  fi
  [[ "$changed" == 1 ]] || { log "Р®РЅРёС‚ $BOT_SVC СѓР¶Рµ Р°РєС‚СѓР°Р»РµРЅ вЂ” РЅРµ С‚СЂРѕРіР°СЋ"; rm -f "/root/stack-backups/${BOT_SVC}.unit.pre-embed-$ts"; return 0; }
  systemctl daemon-reload
  ok "Р®РЅРёС‚ $BOT_SVC РѕР±РЅРѕРІР»С‘РЅ: ${BOT_SM} --bot + Restart=always/3СЃ (Р±СЌРєР°Рї: /root/stack-backups/${BOT_SVC}.unit.pre-embed-$ts)"
}
bot_install() { # СѓСЃС‚Р°РЅРѕРІРєР° Р±РѕС‚Р°: СЋРЅРёС‚ Р·Р°РїСѓСЃРєР°РµС‚ Р­РўРћРў Р–Р• СЃРєСЂРёРїС‚ РІ СЂРµР¶РёРјРµ --bot; РєР°С‡Р°С‚СЊ РЅРёС‡РµРіРѕ РЅРµ РЅСѓР¶РЅРѕ
  local yn="n"
  askyn yn "Р®РЅРёС‚Р° $BOT_SVC РЅРµС‚ РЅР° СЌС‚РѕРј СЃРµСЂРІРµСЂРµ. РЈСЃС‚Р°РЅРѕРІРёС‚СЊ Р±РѕС‚Р°? (systemd-СЋРЅРёС‚ в†’ РїСѓСЃС‚РѕР№ env; Р±РѕС‚ РІСЃС‚СЂРѕРµРЅ РІ stack-manager, С‚РѕРєРµРЅ Р·Р°С‚РµРј РІРІРѕРґРёС‚СЃСЏ РІ Рї.6)" "y"
  [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ вЂ” Р±РѕС‚ РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ"; return 1; }
  if ! systemctl cat "$BOT_SVC" >/dev/null 2>&1; then
    cat > "/etc/systemd/system/${BOT_SVC}.service" <<UNIT
[Unit]
Description=Stack Manager TG bot (embedded)
After=network-online.target
StartLimitIntervalSec=0

[Service]
ExecStart=/usr/bin/env bash ${BOT_SM} --bot
EnvironmentFile=${BOT_ENV_FILE}
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload
    ok "Р®РЅРёС‚ /etc/systemd/system/${BOT_SVC}.service СЃРѕР·РґР°РЅ (Restart=always; Р·Р°РїСѓСЃРєР°РµС‚ ${BOT_SM} --bot)"
  else
    bot_unit_migrate
  fi
  if [[ ! -f "$BOT_ENV_FILE" ]]; then
    : > "$BOT_ENV_FILE"
    chmod 600 "$BOT_ENV_FILE"
    log "РЎРѕР·РґР°РЅ РїСѓСЃС‚РѕР№ $BOT_ENV_FILE (600) вЂ” Р±РµР· С‚РѕРєРµРЅР° Р±РѕС‚ РІ Telegram РЅРµ РїРёС€РµС‚"
  fi
  ok "Р‘РѕС‚ СѓСЃС‚Р°РЅРѕРІР»РµРЅ. Р”Р°Р»СЊС€Рµ: Рї.6 вЂ” С‚РѕРєРµРЅ Рё ID РІР»Р°РґРµР»СЊС†Р°, Р·Р°С‚РµРј Рї.5 вЂ” РІРєР»СЋС‡РёС‚СЊ"
  return 0
}
bot_toggle() { # РІРєР»/РІС‹РєР» СЃР°РјРѕРіРѕ Р±РѕС‚Р°: enable --now / disable --now; Р±РµР· СЋРЅРёС‚Р° вЂ” РїСЂРµРґР»РѕР¶РµРЅРёРµ СѓСЃС‚Р°РЅРѕРІРєРё
  if ! bot_svc_installed; then
    err "Р®РЅРёС‚ $BOT_SVC.service РЅРµ РЅР°Р№РґРµРЅ вЂ” Р±РѕС‚ РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ"
    bot_install || return 1
  fi
  local yn="n"
  if systemctl is-active --quiet "$BOT_SVC" 2>/dev/null; then
    askyn yn "Р’С‹РєР»СЋС‡РёС‚СЊ Р±РѕС‚Р°? (systemctl disable --now $BOT_SVC вЂ” РѕСЃС‚Р°РЅРѕРІ СЃРµР№С‡Р°СЃ + Р±РµР· Р°РІС‚РѕР·Р°РїСѓСЃРєР° РїСЂРё СЂРµР±СѓС‚Рµ; СЂРµР¶РёРј TG-РІС‹С…РѕРґР° СЃРѕС…СЂР°РЅРёС‚СЃСЏ)" "n"
    [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ вЂ” Р±РѕС‚ РїСЂРѕРґРѕР»Р¶Р°РµС‚ СЂР°Р±РѕС‚Р°С‚СЊ"; return 1; }
    if systemctl disable --now "$BOT_SVC" >/dev/null 2>&1; then
      ok "Р‘РѕС‚ РІС‹РєР»СЋС‡РµРЅ (stop + disable). State $BOT_OUT_FILE РЅРµ С‚СЂРѕРЅСѓС‚ вЂ” РІРєР»СЋС‡РёС€СЊ С‡РµСЂРµР· СЌС‚РѕС‚ Р¶Рµ РїСѓРЅРєС‚"
    else
      err "РќРµ СѓРґР°Р»РѕСЃСЊ РѕСЃС‚Р°РЅРѕРІРёС‚СЊ $BOT_SVC вЂ” СЃРјРѕС‚СЂРё journalctl -u $BOT_SVC"
      return 1
    fi
  else
    botenv_load
    if [[ -z "$BE_TOK" ]]; then
      askyn yn "РўРѕРєРµРЅ Р±РѕС‚Р° РЅРµ Р·Р°РґР°РЅ (Рї.6 В«РўРѕРєРµРЅ Рё ID РІР»Р°РґРµР»СЊС†Р°В»). Р’СЃС‘ СЂР°РІРЅРѕ РІРєР»СЋС‡РёС‚СЊ? (Р±РµР· С‚РѕРєРµРЅР° Р±РѕС‚ РЅРµ СЃРјРѕР¶РµС‚ СЂР°Р±РѕС‚Р°С‚СЊ СЃ Telegram)" "n"
      [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ вЂ” Р·Р°РґР°Р№ С‚РѕРєРµРЅ РІ Рї.6 Рё РІРєР»СЋС‡Р°Р№ СЃРЅРѕРІР°"; return 1; }
    fi
    askyn yn "Р’РєР»СЋС‡РёС‚СЊ Р±РѕС‚Р°? (systemctl enable --now $BOT_SVC вЂ” СЃС‚Р°СЂС‚ СЃРµР№С‡Р°СЃ + Р°РІС‚РѕР·Р°РїСѓСЃРє РїСЂРё СЂРµР±СѓС‚Рµ)" "n"
    [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ вЂ” Р±РѕС‚ РѕСЃС‚Р°С‘С‚СЃСЏ РІС‹РєР»СЋС‡РµРЅРЅС‹Рј"; return 1; }
    bot_unit_migrate
    if ! systemctl enable --now "$BOT_SVC" >/dev/null 2>&1; then
      err "РќРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РїСѓСЃС‚РёС‚СЊ $BOT_SVC вЂ” РїРѕСЃР»РµРґРЅРёРµ СЃС‚СЂРѕРєРё Р¶СѓСЂРЅР°Р»Р°:"
      journalctl -u "$BOT_SVC" -n 10 --no-pager 2>/dev/null | sed 's/^/    /'
      return 1
    fi
    local i
    for i in 1 2 3 4 5; do systemctl is-active --quiet "$BOT_SVC" 2>/dev/null && break; sleep 1; done
    if systemctl is-active --quiet "$BOT_SVC" 2>/dev/null; then
      ok "Р‘РѕС‚ Р·Р°РїСѓС‰РµРЅ (start + enable)"
      botenv_test_msg || true
      botout_bot_note
    else
      warn "Р®РЅРёС‚ СЃС‚Р°СЂС‚РѕРІР°Р» Рё СЃСЂР°Р·Сѓ СѓРїР°Р» вЂ” РїРѕСЃР»РµРґРЅРёРµ СЃС‚СЂРѕРєРё Р¶СѓСЂРЅР°Р»Р°:"
      journalctl -u "$BOT_SVC" -n 10 --no-pager 2>/dev/null | sed 's/^/    /'
      return 1
    fi
  fi
}
# в”Ђв”Ђ РўРѕРєРµРЅ Р±РѕС‚Р° Рё ID РІР»Р°РґРµР»СЊС†Р° в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# Р®РЅРёС‚ Р±РѕС‚Р° С‡РёС‚Р°РµС‚ BOT_TOKEN/ADMIN_CHAT_ID РёР· EnvironmentFile=/root/.tg-stack-bot.env
# С‚РѕР»СЊРєРѕ РїСЂРё СЃС‚Р°СЂС‚Рµ, РїРѕСЌС‚РѕРјСѓ РїРѕСЃР»Рµ Р·Р°РїРёСЃРё РЅСѓР¶РµРЅ СЂРµСЃС‚Р°СЂС‚ Р±РѕС‚Р°. РўРѕРєРµРЅ РїСЂРѕРІРµСЂСЏРµС‚СЃСЏ
# Р¶РёРІС‹Рј getMe С‡РµСЂРµР· С‚РѕС‚ Р¶Рµ TG-РІС‹С…РѕРґ, С‡С‚Рѕ РёСЃРїРѕР»СЊР·СѓРµС‚ Р±РѕС‚ (state BOT_OUT_FILE);
# РЅР° СЌРєСЂР°РЅ С‚РѕРєРµРЅ РїРѕРєР°Р·С‹РІР°РµС‚СЃСЏ Р·Р°РјР°СЃРєРёСЂРѕРІР°РЅРЅС‹Рј, РІ Р±СЌРєР°РїР°С… вЂ” С‚РѕР»СЊРєРѕ РґРѕ РїСЂР°РІРєРё.
botenv_load() { # BE_TOK/BE_CHAT РёР· env-С„Р°Р№Р»Р° СЋРЅРёС‚Р°
  BE_TOK=""; BE_CHAT=""
  [[ -f "$BOT_ENV_FILE" ]] || return 0
  BE_TOK=$(grep -a '^BOT_TOKEN=' "$BOT_ENV_FILE" | tail -1 | cut -d= -f2-)
  BE_CHAT=$(grep -a '^ADMIN_CHAT_ID=' "$BOT_ENV_FILE" | tail -1 | cut -d= -f2-)
}
botenv_mask_tok() { # 123456789:AAвЂўвЂўвЂўвЂўx4yz вЂ” РїРѕР»РЅС‹Р№ С‚РѕРєРµРЅ РЅР°СЂСѓР¶Сѓ РЅРµ РїРµС‡Р°С‚Р°РµРј
  local t=$1 id sfx
  [[ -z "$t" ]] && { printf '<РЅРµ Р·Р°РґР°РЅ>'; return; }
  id=${t%%:*}; sfx=${t#*:}
  (( ${#sfx} > 6 )) && sfx="вЂўвЂўвЂўвЂў${sfx: -4}" || sfx="вЂўвЂўвЂўвЂў"
  printf '%s:%s' "$id" "$sfx"
}
botenv_tg_api() { # curl Рє api.telegram.org С‡РµСЂРµР· С‚РµРєСѓС‰РёР№ TG-РІС‹С…РѕРґ Р±РѕС‚Р° (РєР°Рє Сѓ СЃР°РјРѕРіРѕ Р±РѕС‚Р°)
  local pa=() u
  botout_state_load
  case "$BO_MODE" in
    outbound) [[ -n "$BO_PORT" ]] && pa=(--proxy "socks5h://127.0.0.1:${BO_PORT}") ;;
    socks)    u=$(printf '%s' "$BO_SOCKS" | base64 -d 2>/dev/null); [[ -n "$u" ]] && pa=(--proxy "$u") ;;
  esac
  curl -s --max-time 14 "${pa[@]}" "$@"
}
botenv_write() { # Р°С‚РѕРјР°СЂРЅРѕ, 600; С‡СѓР¶РёРµ СЃС‚СЂРѕРєРё/РєРѕРјРјРµРЅС‚Р°СЂРёРё СЃРѕС…СЂР°РЅСЏРµРј, С‚РѕРєРµРЅ/ID РїРµСЂРµРїРёСЃС‹РІР°РµРј
  local tok=$1 chat=$2 tmp="${BOT_ENV_FILE}.tmp" line k
  : > "$tmp"
  if [[ -f "$BOT_ENV_FILE" ]]; then
    while IFS= read -r line || [[ -n "$line" ]]; do
      k=${line%%=*}
      [[ "$k" == "BOT_TOKEN" || "$k" == "ADMIN_CHAT_ID" ]] && continue
      printf '%s\n' "$line" >> "$tmp"
    done < "$BOT_ENV_FILE"
  fi
  [[ -n "$tok" ]]  && printf 'BOT_TOKEN=%s\n' "$tok" >> "$tmp"
  [[ -n "$chat" ]] && printf 'ADMIN_CHAT_ID=%s\n' "$chat" >> "$tmp"
  chmod 600 "$tmp" 2>/dev/null || true
  mv "$tmp" "$BOT_ENV_FILE"
}
botenv_restart_note() { # env С‡РёС‚Р°РµС‚СЃСЏ С‚РѕР»СЊРєРѕ РїСЂРё СЃС‚Р°СЂС‚Рµ вЂ” РїСЂРµРґР»РѕР¶РёС‚СЊ СЂРµСЃС‚Р°СЂС‚
  systemctl is-active --quiet "$BOT_SVC" 2>/dev/null || return 0
  local yn="n" i
  askyn yn "РџРµСЂРµР·Р°РїСѓСЃС‚РёС‚СЊ Р±РѕС‚Р° СЃРµР№С‡Р°СЃ, С‡С‚РѕР±С‹ РѕРЅ РїСЂРѕС‡РёС‚Р°Р» РЅРѕРІС‹Рµ Р·РЅР°С‡РµРЅРёСЏ? (env СЋРЅРёС‚Р° РїСЂРёРјРµРЅСЏРµС‚СЃСЏ С‚РѕР»СЊРєРѕ РїСЂРё СЃС‚Р°СЂС‚Рµ)" "y"
  [[ "$yn" == "true" ]] || { warn "Р‘РѕС‚ СЂР°Р±РѕС‚Р°РµС‚ СЃРѕ СЃС‚Р°СЂС‹РјРё Р·РЅР°С‡РµРЅРёСЏРјРё РґРѕ СЃР»РµРґСѓСЋС‰РµРіРѕ СЂРµСЃС‚Р°СЂС‚Р°"; return 0; }
  systemctl restart "$BOT_SVC" >/dev/null 2>&1 || true
  for i in 1 2 3 4 5; do systemctl is-active --quiet "$BOT_SVC" 2>/dev/null && break; sleep 1; done
  if systemctl is-active --quiet "$BOT_SVC" 2>/dev/null; then
    ok "Р‘РѕС‚ РїРµСЂРµР·Р°РїСѓС‰РµРЅ СЃ РЅРѕРІС‹РјРё Р·РЅР°С‡РµРЅРёСЏРјРё"
  else
    warn "Р‘РѕС‚ РЅРµ РїРѕРґРЅСЏР»СЃСЏ вЂ” РїРѕСЃР»РµРґРЅРёРµ СЃС‚СЂРѕРєРё Р¶СѓСЂРЅР°Р»Р°:"
    journalctl -u "$BOT_SVC" -n 10 --no-pager 2>/dev/null | sed 's/^/    /'
  fi
}
botenv_test_msg() { # С‚РµСЃС‚РѕРІРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ РІР»Р°РґРµР»СЊС†Сѓ (creds РёР· env СЋРЅРёС‚Р°) вЂ” РІС‹Р·С‹РІР°РµС‚СЃСЏ РїРѕСЃР»Рµ РІРєР»СЋС‡РµРЅРёСЏ Р±РѕС‚Р°
  local r desc
  botenv_load
  if [[ -z "$BE_TOK" || -z "$BE_CHAT" ]]; then
    warn "РўРѕРєРµРЅ/ID РІР»Р°РґРµР»СЊС†Р° РЅРµ Р·Р°РґР°РЅС‹ вЂ” С‚РµСЃС‚ РЅРµ РѕС‚РїСЂР°РІР»РµРЅ (РЅР°СЃС‚СЂРѕР№ РІ Рї.6 В«РўРѕРєРµРЅ Рё ID РІР»Р°РґРµР»СЊС†Р°В»)"
    return 1
  fi
  r=$(botenv_tg_api "https://api.telegram.org/bot${BE_TOK}/sendMessage" \
    --data-urlencode "chat_id=${BE_CHAT}" \
    --data-urlencode "text=вњ… tg-stack-bot Р·Р°РїСѓС‰РµРЅ вЂ” С‚РµСЃС‚РѕРІРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ РёР· stack-manager") || r=""
  if printf '%s' "$r" | jq -e '.ok == true' >/dev/null 2>&1; then
    ok "РўРµСЃС‚РѕРІРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ РґРѕСЃС‚Р°РІР»РµРЅРѕ РІР»Р°РґРµР»СЊС†Сѓ (${BE_CHAT})"
  else
    desc=$(printf '%s' "$r" | jq -r '.description // "РЅРµС‚ РѕС‚РІРµС‚Р°"' 2>/dev/null)
    warn "РўРµСЃС‚ РЅРµ РґРѕСЃС‚Р°РІР»РµРЅ (${desc}). Р§Р°СЃС‚Р°СЏ РїСЂРёС‡РёРЅР°: РІР»Р°РґРµР»РµС† РЅРµ РЅР°Р¶Р°Р» /start Сѓ Р±РѕС‚Р° РёР»Рё РЅРµ Р·Р°РґР°РЅ ID"
    return 1
  fi
}
botenv_creds_set() { # РїСЂРѕСЃРјРѕС‚СЂ/РІРІРѕРґ С‚РѕРєРµРЅР° Р±РѕС‚Р° Рё ID РІР»Р°РґРµР»СЊС†Р°
  local newtok="" newchat="" r desc bname yn="n" fin_tok fin_chat ts
  botenv_load
  echo
  echo -e "${B}РўРµРєСѓС‰РёРµ Р·РЅР°С‡РµРЅРёСЏ (${BOT_ENV_FILE}):${N}"
  echo "  РўРѕРєРµРЅ Р±РѕС‚Р°:    $(botenv_mask_tok "$BE_TOK")"
  echo "  ID РІР»Р°РґРµР»СЊС†Р°:  ${BE_CHAT:-<РЅРµ Р·Р°РґР°РЅ вЂ” Р±РѕС‚ РІ СЂРµР¶РёРјРµ РѕР±СѓС‡РµРЅРёСЏ>}"
  echo
  echo "Р’СЃС‚Р°РІСЊ РЅРѕРІРѕРµ Р·РЅР°С‡РµРЅРёРµ РёР»Рё РїСЂРѕСЃС‚Рѕ Enter вЂ” РѕСЃС‚Р°РІРёС‚СЊ РєР°Рє РµСЃС‚СЊ."
  ask newtok "РўРѕРєРµРЅ Р±РѕС‚Р° (РІРёРґР° 123456789:AAвЂ¦)" "" ''
  if [[ -n "$newtok" ]]; then
    [[ "$newtok" =~ ^[0-9]{6,12}:[A-Za-z0-9_-]{30,}$ ]] \
      || { err "РќРµ РїРѕС…РѕР¶Рµ РЅР° С‚РѕРєРµРЅ (С†РёС„СЂС‹, РґРІРѕРµС‚РѕС‡РёРµ, ~35 СЃРёРјРІРѕР»РѕРІ) вЂ” РѕС‚РјРµРЅР°"; return 1; }
    log "РџСЂРѕРІРµСЂСЏСЋ С‚РѕРєРµРЅ С‡РµСЂРµР· Telegram (getMe, С‚РµРј Р¶Рµ РІС‹С…РѕРґРѕРј, С‡С‚Рѕ Рё Р±РѕС‚)вЂ¦"
    r=$(botenv_tg_api "https://api.telegram.org/bot${newtok}/getMe") || r=""
    if printf '%s' "$r" | jq -e '.ok == true' >/dev/null 2>&1; then
      bname=$(printf '%s' "$r" | jq -r '.result.username // "?"' 2>/dev/null)
      ok "РўРѕРєРµРЅ РІР°Р»РёРґРµРЅ вЂ” СЌС‚Рѕ Р±РѕС‚ @${bname}"
    elif printf '%s' "$r" | grep -q '"ok":false'; then
      desc=$(printf '%s' "$r" | jq -r '.description // "РѕС‚РєР»РѕРЅС‘РЅ"' 2>/dev/null)
      askyn yn "Telegram РѕС‚РєР»РѕРЅРёР» С‚РѕРєРµРЅ (${desc}). Р’СЃС‘ СЂР°РІРЅРѕ СЃРѕС…СЂР°РЅРёС‚СЊ?" "n"
      [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ"; return 1; }
    else
      askyn yn "Р”Рѕ Telegram РЅРµ РґРѕСЃС‚СѓС‡Р°Р»РёСЃСЊ (СЃРµС‚СЊ/РІС‹С…РѕРґ Р±РѕС‚Р°). РЎРѕС…СЂР°РЅРёС‚СЊ Р±РµР· РїСЂРѕРІРµСЂРєРё?" "n"
      [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ"; return 1; }
    fi
  fi
  while :; do
    ask newchat "ID РІР»Р°РґРµР»СЊС†Р° (С‡РёСЃР»Рѕ, СѓР·РЅР°С‚СЊ: @userinfobot; Enter вЂ” РѕСЃС‚Р°РІРёС‚СЊ)" "" ''
    [[ -z "$newchat" || "$newchat" =~ ^[0-9]{3,}$ ]] && break
    err "ID РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ С‡РёСЃР»РѕРј (РЅР°РїСЂРёРјРµСЂ 123456789)"
  done
  [[ -z "$newtok" && -z "$newchat" ]] && { warn "РќРёС‡РµРіРѕ РЅРµ РјРµРЅСЏР»"; return 0; }
  fin_tok=${newtok:-$BE_TOK}; fin_chat=${newchat:-$BE_CHAT}
  if [[ -n "$fin_tok" && -n "$fin_chat" ]]; then
    askyn yn "РћС‚РїСЂР°РІРёС‚СЊ С‚РµСЃС‚РѕРІРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ РІР»Р°РґРµР»СЊС†Сѓ? (РЅСѓР¶РЅРѕ, С‡С‚РѕР±С‹ РІР»Р°РґРµР»РµС† РЅР°Р¶Р°Р» /start Сѓ Р±РѕС‚Р°)" "y"
    if [[ "$yn" == "true" ]]; then
      r=$(botenv_tg_api "https://api.telegram.org/bot${fin_tok}/sendMessage" \
        --data-urlencode "chat_id=${fin_chat}" \
        --data-urlencode "text=вњ… РџСЂРѕРІРµСЂРєР° СЃРІСЏР·Рё РёР· stack-manager: С‚РѕРєРµРЅ Рё ID РІР»Р°РґРµР»СЊС†Р° РїСЂРёРјРµРЅРµРЅС‹.") || r=""
      if printf '%s' "$r" | jq -e '.ok == true' >/dev/null 2>&1; then
        ok "РўРµСЃС‚РѕРІРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ РґРѕСЃС‚Р°РІР»РµРЅРѕ"
      else
        desc=$(printf '%s' "$r" | jq -r '.description // "РЅРµС‚ РѕС‚РІРµС‚Р°"' 2>/dev/null)
        warn "РќРµ РґРѕСЃС‚Р°РІР»РµРЅРѕ (${desc}). Р§Р°СЃС‚Р°СЏ РїСЂРёС‡РёРЅР°: РІР»Р°РґРµР»РµС† РЅРµ РЅР°Р¶Р°Р» /start вЂ” Р·РЅР°С‡РµРЅРёСЏ РІСЃС‘ СЂР°РІРЅРѕ СЃРѕС…СЂР°РЅСЏС‚СЃСЏ"
      fi
    fi
  fi
  askyn yn "Р—Р°РїРёСЃР°С‚СЊ РІ ${BOT_ENV_FILE}? (С‚РµРєСѓС‰РёР№ С„Р°Р№Р» Р±СѓРґРµС‚ Р·Р°Р±СЌРєР°РїР»РµРЅ РІ ${BACKUP_DIR})" "y"
  [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ вЂ” РЅРёС‡РµРіРѕ РЅРµ Р·Р°РїРёСЃР°РЅРѕ"; return 1; }
  ts=$(date +%Y%m%d-%H%M%S)
  mkdir -p "$BACKUP_DIR" 2>/dev/null || true
  [[ -f "$BOT_ENV_FILE" ]] && cp -a "$BOT_ENV_FILE" "$BACKUP_DIR/tg-bot-env.pre-creds-$ts"
  botenv_write "$fin_tok" "$fin_chat"
  ok "РЎРѕС…СЂР°РЅРµРЅРѕ: С‚РѕРєРµРЅ $(botenv_mask_tok "$fin_tok"), ID ${fin_chat:-РЅРµ Р·Р°РґР°РЅ}"
  botenv_restart_note
}
botout_enable_outbound() { # $1=tag $2=outboundJSON(""=СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ С‚РµРі) вЂ” РІРєР» С‚РѕР»СЊРєРѕ РїРѕСЃР»Рµ РїСЂРѕРІРµСЂРєРё 204
  local tag=$1 ob=${2:-} port
  port=$(botout_free_port) || { err "РЅРµС‚ СЃРІРѕР±РѕРґРЅРѕРіРѕ Р»РѕРєР°Р»СЊРЅРѕРіРѕ РїРѕСЂС‚Р° (10808-10810)"; return 1; }
  botout_apply add "$tag" "$port" 1 "$ob" || { err "РїСЂР°РІРєР° С€Р°Р±Р»РѕРЅР° РЅРµ РїСЂРѕС€Р»Р° вЂ” РІС‹С…РѕРґ РЅРµ РёР·РјРµРЅС‘РЅ"; return 1; }
  if botout_verify "$port"; then
    BO_MODE="outbound"; BO_TAG="$tag"; BO_PORT="$port"; BO_SOCKS=""
    [[ "$tag" == "$BOT_SOCKS_OUT" ]] && BO_OURS=1 || BO_OURS=0
    botout_state_write
    ok "TG-РІС‹С…РѕРґ: Р°СѓС‚Р±Р°СѓРЅРґ В«$tagВ» (Р»РѕРєР°Р»СЊРЅС‹Р№ socks 127.0.0.1:$port), РїСЂРѕРІРµСЂРєР° 204 РїСЂРѕР№РґРµРЅР°"
    botout_bot_note
    return 0
  fi
  warn "Р§РµСЂРµР· Р°СѓС‚Р±Р°СѓРЅРґ РІС‹С…РѕРґР° РІ РёРЅС‚РµСЂРЅРµС‚ РЅРµС‚ (РїСЂРѕРІРµСЂРєР° 204 РЅРµ РїСЂРѕС€Р»Р°) вЂ” РѕС‚РєР°С‚С‹РІР°СЋ РїСЂР°РІРєРё"
  botout_apply remove "$tag" "" 1 "" >/dev/null 2>&1 || true
  err "Р’С‹С…РѕРґ РЅРµ РёР·РјРµРЅС‘РЅ вЂ” Р±РѕС‚ СЂР°Р±РѕС‚Р°РµС‚ РєР°Рє СЂР°Р±РѕС‚Р°Р». РџСЂРѕРІРµСЂСЊ Р°СѓС‚Р±Р°СѓРЅРґ: Р°РґСЂРµСЃ, РїРѕСЂС‚, UUID, TLS/SNI"
  return 1
}
botout_disable() { # СѓР±СЂР°С‚СЊ РЅР°С€Рё РїСЂР°РІРєРё РёР· С€Р°Р±Р»РѕРЅР° (РµСЃР»Рё Р±С‹Р»Рё) Рё РІРµСЂРЅСѓС‚СЊ РїСЂСЏРјРѕР№
  botout_state_load
  if [[ "$BO_MODE" == "outbound" || "$BO_OURS" == "1" ]]; then
    botout_apply remove "$BO_TAG" "" "$BO_OURS" "" || { err "РїСЂР°РІРєРё РЅРµ СѓР±СЂР°РЅС‹ вЂ” state РЅРµ РјРµРЅСЏР»"; return 1; }
  fi
  BO_MODE="direct"; BO_TAG=""; BO_PORT=""; BO_SOCKS=""; BO_OURS=0
  botout_state_write
  ok "TG-РІС‹С…РѕРґ: РїСЂСЏРјРѕР№ (РЅР°С€Рё РїСЂР°РІРєРё РёР· Xray СѓР±СЂР°РЅС‹)"
  botout_bot_note
}
botout_set_socks() { # СЃРІРѕР№ SOCKS вЂ” РІРєР»СЋС‡Р°РµС‚СЃСЏ С‚РѕР»СЊРєРѕ РїРѕСЃР»Рµ Р¶РёРІРѕР№ РїСЂРѕРІРµСЂРєРё
  local u="" code
  ask u "URL РїСЂРѕРєСЃРё (socks5h://user:pass@Р·Р°СЂСѓР±РµР¶РЅС‹Р№-СЃРµСЂРІРµСЂ:1080)" "" '^(socks5h?|https?)://[^[:space:]]+$'
  code=$(curl -sk -m 12 --proxy "$u" -o /dev/null -w '%{http_code}' "https://www.google.com/generate_204" 2>/dev/null)
  if [[ "$code" == "204" ]]; then
    BO_MODE="socks"; BO_SOCKS=$(printf '%s' "$u" | base64 -w0 2>/dev/null || printf '%s' "$u" | base64)
    BO_TAG=""; BO_PORT=""; BO_OURS=0
    botout_state_write
    ok "TG-РІС‹С…РѕРґ: SOCKS $u вЂ” РїСЂРѕРІРµСЂРєР° 204 РїСЂРѕР№РґРµРЅР°"
    botout_bot_note
  else
    err "Р§РµСЂРµР· СЌС‚РѕС‚ SOCKS РІС‹С…РѕРґР° РЅРµС‚ (РєРѕРґ: ${code:-РЅРµС‚ РѕС‚РІРµС‚Р°}) вЂ” СЂРµР¶РёРј РЅРµ РёР·РјРµРЅС‘РЅ"
  fi
}
botout_pick_existing() { # СЃРїРёСЃРѕРє Р°СѓС‚Р±Р°СѓРЅРґРѕРІ РёР· С€Р°Р±Р»РѕРЅР° (РєСЂРѕРјРµ freedom/blackhole) в†’ OUT_TAG
  local t tag proto i=1
  declare -a _btags=() _bprotos=()
  t=$(botout_tpl_get) || return 1
  echo
  echo -e "${B}РђСѓС‚Р±Р°СѓРЅРґС‹ РІ РєРѕРЅС„РёРіРµ Xray:${N}"
  while IFS=$'\t' read -r tag proto; do
    [[ -z "$tag" ]] && continue
    [[ "$proto" == "freedom" || "$proto" == "blackhole" ]] && continue
    _btags+=("$tag"); _bprotos+=("$proto")
    printf '  %2d) %-24s (%s)\n' "$i" "$tag" "$proto"; i=$((i+1))
  done < <(printf '%s' "$t" | jq -r '.outbounds[]? | [(.tag // ""), (.protocol // "")] | @tsv' 2>/dev/null)
  if (( ${#_btags[@]} == 0 )); then
    warn "РџРѕРґС…РѕРґСЏС‰РёС… Р°СѓС‚Р±Р°СѓРЅРґРѕРІ РЅРµС‚ (С‚РѕР»СЊРєРѕ freedom/blackhole) вЂ” РґРѕР±Р°РІСЊ СЃРІРѕР№ С‡РµСЂРµР· Рї.2"
    return 1
  fi
  local c=""; ask c "Р§РµСЂРµР· РєР°РєРѕР№ Р°СѓС‚Р±Р°СѓРЅРґ РЅР°РїСЂР°РІРёС‚СЊ Р±РѕС‚Р°" "1" '^[0-9]+$'
  (( c >= 1 && c <= ${#_btags[@]} )) || { err "РќРµС‚ С‚Р°РєРѕРіРѕ РїСѓРЅРєС‚Р°"; return 1; }
  OUT_TAG="${_btags[$((c-1))]}"
}
botout_add_json() { # СЃРІРѕР№ Р°СѓС‚Р±Р°СѓРЅРґ РёР· JSON (С‚РµРі СЃС‚Р°РЅРµС‚ tgbot-out)
  local src="" ob="" ojt yn="n"
  echo "Р’СЃС‚Р°РІСЊ JSON Р°СѓС‚Р±Р°СѓРЅРґР° РћР”РќРћР™ СЃС‚СЂРѕРєРѕР№ РёР»Рё СѓРєР°Р¶Рё РїСѓС‚СЊ Рє С„Р°Р№Р»Сѓ (/root/out.json)."
  ask src "JSON РёР»Рё РїСѓС‚СЊ Рє С„Р°Р№Р»Сѓ" "" ''
  [[ -z "$src" ]] && { warn "РџСѓСЃС‚Рѕ вЂ” РѕС‚РјРµРЅР°"; return 1; }
  if [[ -f "$src" ]]; then
    ob=$(cat "$src")
    log "Р§РёС‚Р°СЋ JSON РёР· С„Р°Р№Р»Р° $src"
  else
    ob="$src"
  fi
  printf '%s' "$ob" | jq -e '.tag and .protocol and .settings' >/dev/null 2>&1 \
    || { err "Р­С‚Рѕ РЅРµ РІР°Р»РёРґРЅС‹Р№ JSON Р°СѓС‚Р±Р°СѓРЅРґР° (РЅСѓР¶РЅС‹ tag, protocol, settings)"; return 1; }
  ojt=$(printf '%s' "$ob" | jq -r '.tag')
  echo "РўРµРі В«$ojtВ» Р±СѓРґРµС‚ Р·Р°РјРµРЅС‘РЅ РЅР° $BOT_SOCKS_OUT; РґРѕР±Р°РІРёС‚СЃСЏ Р»РѕРєР°Р»СЊРЅС‹Р№ socks 127.0.0.1:<РїРѕСЂС‚> Рё РїСЂР°РІРёР»Рѕ СЂРѕСѓС‚РёРЅРіР°."
  askyn yn "РџСЂРѕРґРѕР»Р¶РёС‚СЊ? (Р±СЌРєР°Рї в†’ РїСЂР°РІРєР° С€Р°Р±Р»РѕРЅР° в†’ СЂРµСЃС‚Р°СЂС‚ x-ui в†’ РїСЂРѕРІРµСЂРєР° 204)" "n"
  [[ "$yn" == "true" ]] || { warn "РћС‚РјРµРЅРµРЅРѕ"; return 1; }
  botout_enable_outbound "$BOT_SOCKS_OUT" "$ob"
}
botout_status() { # РѕРґРЅРѕСЃС‚СЂРѕС‡РЅС‹Р№ СЃС‚Р°С‚СѓСЃ + СЃРѕСЃС‚РѕСЏРЅРёРµ СЃРµСЂРІРёСЃР° Р±РѕС‚Р°
  botout_state_load
  local m
  case "$BO_MODE" in
    outbound) m="рџ“Ў Р°СѓС‚Р±Р°СѓРЅРґ В«$BO_TAGВ» В· Р»РѕРєР°Р»СЊРЅС‹Р№ socks 127.0.0.1:$BO_PORT" ;;
    socks)    m="рџ”Њ СЃРІРѕР№ SOCKS $(printf '%s' "$BO_SOCKS" | base64 -d 2>/dev/null)" ;;
    *)        m="вњ… РїСЂСЏРјРѕР№ (Р±РµР· РїСЂРѕРєСЃРё)" ;;
  esac
  echo "Р РµР¶РёРј: $m"
  if systemctl is-active --quiet "$BOT_SVC" 2>/dev/null; then
    echo "Р‘РѕС‚: рџџў Р·Р°РїСѓС‰РµРЅ (РїСЂР°РІРєРё РїРѕРґС…РІР°С‚С‹РІР°РµС‚ РЅР° Р»РµС‚Сѓ)"
  else
    echo "Р‘РѕС‚: рџ”ґ РЅРµ Р·Р°РїСѓС‰РµРЅ"
  fi
}
bot_out_menu() {
  while :; do
    line; echo -e "${B}   рџ¤– TG-Р‘РћРў вЂ” Р’Р«РҐРћР” Р’ TELEGRAM${N}"; line
    botout_status
    echo
    echo "  1) Р§РµСЂРµР· СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ Р°СѓС‚Р±Р°СѓРЅРґ (СЃРїРёСЃРѕРє РёР· РєРѕРЅС„РёРіР°)"
    echo "  2) Р”РѕР±Р°РІРёС‚СЊ СЃРІРѕР№ Р°СѓС‚Р±Р°СѓРЅРґ (JSON)"
    echo "  3) РЎРІРѕР№ SOCKS-РїСЂРѕРєСЃРё (URL)"
    echo "  4) РќР°РїСЂСЏРјСѓСЋ (СѓР±СЂР°С‚СЊ РїСЂР°РІРєРё РёР· Xray)"
    if systemctl is-active --quiet "$BOT_SVC" 2>/dev/null; then
      echo "  5) рџ”ґ Р’С‹РєР»СЋС‡РёС‚СЊ Р±РѕС‚Р° (stop + disable)"
    else
      echo "  5) рџџў Р’РєР»СЋС‡РёС‚СЊ Р±РѕС‚Р° (start + enable)"
    fi
    echo "  6) рџ”‘ РўРѕРєРµРЅ Р±РѕС‚Р° Рё ID РІР»Р°РґРµР»СЊС†Р° (РІРІРѕРґ/СЃРјРµРЅР°)"
    echo "  0) РќР°Р·Р°Рґ"
    local c=""; ask c "Р’С‹Р±РѕСЂ" "1" '^[0-6]$'
    case "$c" in
      1)
        if botout_pick_existing; then
          local t="$OUT_TAG" yn="n"
          askyn yn "РќР°РїСЂР°РІРёС‚СЊ Telegram-С‚СЂР°С„РёРє Р±РѕС‚Р° С‡РµСЂРµР· В«$tВ»? (Р±СЌРєР°Рї в†’ РїСЂР°РІРєР° С€Р°Р±Р»РѕРЅР° в†’ СЂРµСЃС‚Р°СЂС‚ x-ui, РєСЂР°С‚РєРѕ; РєР»РёРµРЅС‚С‹ РїРµСЂРµРїРѕРґРєР»СЋС‡Р°С‚СЃСЏ)" "n"
          [[ "$yn" == "true" ]] && botout_enable_outbound "$t" ""
        fi
        pause ;;
      2) botout_add_json; pause ;;
      3) botout_set_socks; pause ;;
      4)
        local yn="n"
        askyn yn "РЈР±СЂР°С‚СЊ Р»РѕРєР°Р»СЊРЅС‹Р№ socks-РёРЅР±Р°СѓРЅРґ Рё РїСЂР°РІРєРё РёР· С€Р°Р±Р»РѕРЅР° Xray, РІРµСЂРЅСѓС‚СЊ РїСЂСЏРјРѕР№ РІС‹С…РѕРґ?" "n"
        [[ "$yn" == "true" ]] && botout_disable
        pause ;;
      5) bot_toggle; pause ;;
      6) botenv_creds_set; pause ;;
      0) return 0 ;;
    esac
  done
}

# в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
# рџ¤– TG-Р‘РћРў вЂ” РґРІРёР¶РѕРє, РІСЃС‚СЂРѕРµРЅРЅС‹Р№ РІ stack-manager (СЂРµР¶РёРј Р·Р°РїСѓСЃРєР° --bot)
# РћС‚РґРµР»СЊРЅРѕРіРѕ С„Р°Р№Р»Р° tg-stack-bot.sh Р±РѕР»СЊС€Рµ РЅРµС‚: СЋРЅРёС‚ tg-stack-bot.service
# Р·Р°РїСѓСЃРєР°РµС‚ СЌС‚РѕС‚ Р¶Рµ СЃРєСЂРёРїС‚: ExecStart=/usr/bin/env bash /root/stack-manager.sh --bot
# BOT_TOKEN/ADMIN_CHAT_ID вЂ” РёР· EnvironmentFile=/root/.tg-stack-bot.env.
# В«TG-РІС‹С…РѕРґВ» вЂ” state /root/.tg-stack-bot-out.env (РїРёС€РµС‚ Рї.7 в†’ рџ¤– TG-Р±РѕС‚),
# Р±РѕС‚ РїРѕРґС…РІР°С‚С‹РІР°РµС‚ РїСЂР°РІРєРё РЅР° Р»РµС‚Сѓ (РїРѕ mtime), РјРµРЅСЋ РІ Р±РѕС‚Рµ РЅРµС‚.
# РџРµСЂРµРёРјРµРЅРѕРІР°РЅРѕ РѕС‚РЅРѕСЃРёС‚РµР»СЊРЅРѕ СЃС‚Р°СЂРѕРіРѕ tg-stack-bot.sh: log в†’ bot_log,
# fmt_bytes в†’ bot_fmt_bytes (РЅРµ РїРµСЂРµСЃРµРєР°С‚СЊСЃСЏ СЃ С„СѓРЅРєС†РёСЏРјРё stack-manager).
# в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
bot_log() { echo "[$(date '+%F %T')] $*"; } # Р¶СѓСЂРЅР°Р» Р±РѕС‚Р° (РІ СЃС‚Р°СЂРѕРј tg-stack-bot.sh РЅР°Р·С‹РІР°Р»РѕСЃСЊ log())
bot_init() { # РєРѕРЅС„РёРі, РїСЂРѕРІРµСЂРєРё Рё СЃРёРЅРіР»С‚РѕРЅ вЂ” РўРћР›Р¬РљРћ РІ СЂРµР¶РёРјРµ --bot
BOT_TOKEN="${BOT_TOKEN:-}"
ADMIN_CHAT_ID="${ADMIN_CHAT_ID:-}"
STACK_SCRIPT="$(readlink -f "$0")"  # Р±РѕС‚ РІСЃС‚СЂРѕРµРЅ: РёСЃС‚РѕС‡РЅРёРє = СЌС‚РѕС‚ Р¶Рµ СЃРєСЂРёРїС‚
XUI_DB="/etc/x-ui/x-ui.db"
API="https://api.telegram.org/bot${BOT_TOKEN}"
TG_PROXY="${TG_PROXY:-}"   # legacy: СЃС‚Р°С‚РёС‡РµСЃРєРёР№ SOCKS РёР· env (РµСЃР»Рё state РЅРµ Р·Р°РґР°РЅ вЂ” РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РѕРЅ)
TG_PROXY_CUR="${TG_PROXY:-}" # С„Р°РєС‚РёС‡РµСЃРєРёР№ РІС‹С…РѕРґ Р±РѕС‚Р° (state-С„Р°Р№Р» РІРµРґС‘С‚ stack-manager.sh, Рї.7 в†’ TG-РІС‹С…РѕРґ)
tgc() { # curl РґР»СЏ Telegram API: С‡РµСЂРµР· TG_PROXY_CUR, РµСЃР»Рё Р·Р°РґР°РЅ; Р»РѕРєР°Р»СЊРЅС‹Рµ РІС‹Р·РѕРІС‹ (РїР°РЅРµР»СЊ, nginx) РёРґСѓС‚ РЅР°РїСЂСЏРјСѓСЋ
  if [[ -n "$TG_PROXY_CUR" ]]; then curl --proxy "$TG_PROXY_CUR" "$@"; else curl "$@"; fi
}
PENDING=""; PENDING_TS=0
OFFSET=0
WINDOW_MID=""; CUR_MENU="main"
CARD_FLAG="/run/tg-stack-card.flag"
CARD_PID=""
API_TOKEN_FILE="/root/.tg-api-token"
OUT_FILE="/root/.tg-stack-bot-out.env"   # state В«TG-РІС‹С…РѕРґВ»: TG_OUT_MODE/TG_OUT_TAG/TG_OUT_PORT/TG_SOCKS_B64/TG_OURS вЂ” РїРёС€РµС‚ stack-manager.sh, Р±РѕС‚ С‚РѕР»СЊРєРѕ С‡РёС‚Р°РµС‚
TG_OUT_MODE="direct"; TG_OUT_TAG=""; TG_OUT_PORT=""; TG_SOCKS_B64=""; TG_OURS=0
OUT_MTIME="0"                             # mtime state-С„Р°Р№Р»Р°: Р±РѕС‚ РїРѕРґС…РІР°С‚С‹РІР°РµС‚ РїСЂР°РІРєРё РёР· SSH-СЃРєСЂРёРїС‚Р° Р±РµР· СЂРµСЃС‚Р°СЂС‚Р°
WIZ_STATE="/run/tg-stack-bot-wiz.env"
WIZ_MID=""; NEW_STEP=""; NEW_IN=""; NEW_GB=-1; NEW_DAYS=0; NEW_EMAIL=""; NEW_SUBID=""
E_EMAIL=""; E_STEP=""; E_IN=""; E_MID=""   # РєР°СЂС‚РѕС‡РєР° РєР»РёРµРЅС‚Р° (РїСЂРѕСЃРјРѕС‚СЂ/РїСЂР°РІРєР°)
CL_PAGE=1; CL_PER=10  # РїР°РіРёРЅР°С†РёСЏ СЃРїРёСЃРєР° РєР»РёРµРЅС‚РѕРІ (СЃС‚СЂР°РЅРёС†Р° / РєР»РёРµРЅС‚РѕРІ РЅР° СЃС‚СЂР°РЅРёС†Рµ)

set -o errtrace
trap '[[ "$BASH_COMMAND" == *jq* ]] && bot_log "DEBUG: jq СѓРїР°Р» РЅР° СЃС‚СЂРѕРєРµ $LINENO: $(awk "NR==$LINENO" "$0" 2>/dev/null | head -c 120)"' ERR
[[ -n "$BOT_TOKEN" ]] || { bot_log "BOT_TOKEN РЅРµ Р·Р°РґР°РЅ вЂ” РІС‹С…РѕРґРёРј"; exit 0; }
command -v jq >/dev/null || { bot_log "jq РЅРµ РЅР°Р№РґРµРЅ"; exit 1; }
command -v flock >/dev/null || { bot_log "flock РЅРµ РЅР°Р№РґРµРЅ (util-linux)"; exit 1; }

# в”Ђв”Ђ РѕС‚РєР°Р·РѕСѓСЃС‚РѕР№С‡РёРІРѕСЃС‚СЊ: РѕРґРёРЅ СЌРєР·РµРјРїР»СЏСЂ + РєСѓСЂСЃРѕСЂ Р°РїРґРµР№С‚РѕРІ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
exec 9>/run/tg-stack-bot.lock   # СЃРёРЅРіР»С‚РѕРЅ: РґРІР° СЌРєР·РµРјРїР»СЏСЂР° Р»РѕРІСЏС‚ 409 Conflict Сѓ Telegram
flock -n 9 || { bot_log "Р±РѕС‚ СѓР¶Рµ Р·Р°РїСѓС‰РµРЅ (lock /run/tg-stack-bot.lock) вЂ” РІС‚РѕСЂРѕР№ СЌРєР·РµРјРїР»СЏСЂ РЅРµ РЅСѓР¶РµРЅ"; exit 0; }
OFFSET_FILE="/run/tg-stack-bot.offset"  # РєСѓСЂСЃРѕСЂ getUpdates РїРµСЂРµР¶РёРІР°РµС‚ СЂРµСЃС‚Р°СЂС‚ вЂ” СЃС‚Р°СЂС‹Рµ РЅР°Р¶Р°С‚РёСЏ РєРЅРѕРїРѕРє РЅРµ РїРµСЂРµРёРіСЂС‹РІР°СЋС‚СЃСЏ
}
offset_save() { printf '%s' "$OFFSET" > "${OFFSET_FILE}.tmp" 2>/dev/null && mv -f "${OFFSET_FILE}.tmp" "$OFFSET_FILE" 2>/dev/null; }

# в”Ђв”Ђ Р±Р°Р·РѕРІР°СЏ РѕС‚РїСЂР°РІРєР° в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
tg_send() { # $1=chat $2=text вЂ” СЃР»СѓР¶РµР±РЅРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ, РІСЃРµРіРґР° СЃ РєРЅРѕРїРєРѕР№ В«рџ—‘ РЎРєСЂС‹С‚СЊВ»
  local text="${2:-}" json
  (( ${#text} > 3500 )) && text="вЂ¦${text: -3500}"
  json=$(jq -n --arg c "$1" --arg t "$text" --argjson kb "$KB_HIDE" \
    '{chat_id:$c,text:$t,reply_markup:{inline_keyboard:$kb}}')
  tgc -s --max-time 40 -X POST "$API/sendMessage" -H 'Content-Type: application/json' -d "$json" >/dev/null
}
tg_send_kb() { # $1=chat $2=text $3=inline_keyboard вЂ” РІРѕР·РІСЂР°С‰Р°РµС‚ message_id (РїСѓСЃС‚Рѕ РїСЂРё РѕС€РёР±РєРµ)
  local json resp
  json=$(jq -n --arg c "$1" --arg t "$2" --argjson kb "$3" \
    '{chat_id:$c,text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
  resp=$(tgc -s --max-time 40 -X POST "$API/sendMessage" -H 'Content-Type: application/json' -d "$json")
  jq -r '.result.message_id // empty' <<<"$resp" 2>/dev/null
}
tg_edit() { # $1=chat $2=mid $3=text(HTML) $4=inline_keyboard в†’ 0/1 (not modified = СѓСЃРїРµС…)
  local json resp desc
  json=$(jq -n --arg c "$1" --arg m "$2" --arg t "$3" --argjson kb "$4" \
    '{chat_id:$c,message_id:($m|tonumber),text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
  resp=$(tgc -s --max-time 40 -X POST "$API/editMessageText" -H 'Content-Type: application/json' -d "$json")
  [[ "$(jq -r '.ok // false' <<<"$resp" 2>/dev/null)" == "true" ]] && return 0
  desc=$(jq -r '.description // ""' <<<"$resp" 2>/dev/null)
  [[ "$desc" == *"not modified"* ]]
}
tg_confirm() { # $1=action $2=chat $3=question
  local json
  json=$(jq -n --arg c "$2" --arg t "вљ  $3" \
    '{chat_id:$c,text:$t,reply_markup:{inline_keyboard:[[
      {text:"вњ… РџРѕРґС‚РІРµСЂРґРёС‚СЊ",callback_data:("confirm:"+$a)},
      {text:"вќЊ РћС‚РјРµРЅР°",callback_data:"cancel"}],
      [{"text":"рџ—‘ РЎРєСЂС‹С‚СЊ","callback_data":"hide"}]]}}' --arg a "$1")
  tgc -s --max-time 40 -X POST "$API/sendMessage" -H 'Content-Type: application/json' -d "$json" >/dev/null
}
tg_answer_cb() { tgc -s --max-time 15 "$API/answerCallbackQuery" -d "callback_query_id=$1" >/dev/null; }
tg_del() { tgc -s --max-time 15 "$API/deleteMessage" -d "chat_id=$1" -d "message_id=$2" >/dev/null; }
KB_HIDE='[[{"text":"рџ—‘ РЎРєСЂС‹С‚СЊ","callback_data":"hide"}]]'
hesc() { sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g' <<<"$1"; }

# в”Ђв”Ђ РёСЃС‚РѕС‡РЅРёРє РёСЃС‚РёРЅС‹: stack-manager в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
strip_ansi() { sed -r 's/\x1b\[[0-9;]*[A-Za-z]//g; s/\r//g'; } # Telegram РЅРµ РїРѕРЅРёРјР°РµС‚ ANSI РёР· stack-manager
run_stack() { timeout 300 bash -c "source '$STACK_SCRIPT'; detect_env; $1" 2>&1 | strip_ansi; }
run_check()  { timeout 300 bash "$STACK_SCRIPT" --check 2>&1 | strip_ansi; }

# в”Ђв”Ђ С„РѕСЂРјР°С‚РёСЂРѕРІР°РЅРёРµ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
bot_fmt_bytes() { awk -v b="${1:-0}" 'BEGIN{u=b;s="Р‘";if(b>=1073741824){u=b/1073741824;s="Р“Р‘"}else if(b>=1048576){u=b/1048576;s="РњР‘"}else if(b>=1024){u=b/1024;s="РљР‘"}printf "%.1f %s",u,s}'; }
fmt_age() { local s=${1:-0}
  if (( s < 90 )); then printf '%sСЃ' "$s"
  elif (( s < 5400 )); then printf '%sРј' $(( s/60 ))
  elif (( s < 172800 )); then printf '%sС‡' $(( s/3600 ))
  else printf '%sРґ' $(( s/86400 )); fi; }

# в”Ђв”Ђ РґР°РЅРЅС‹Рµ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
panel_domain() { local d; d=$(sqlite3 "$XUI_DB" "SELECT value FROM settings WHERE key='subDomain';" 2>/dev/null); [[ -z "$d" ]] && d=$(hostname -f 2>/dev/null); printf '%s' "$d"; }
panel_base() { local p; p=$(sqlite3 "$XUI_DB" "SELECT value FROM settings WHERE key='webBasePath';" 2>/dev/null); printf '%s' "${p:-/vladufqa/}"; }
api_call() { # $1=method $2=path $3=json_body в†’ С‚РµР»Рѕ РѕС‚РІРµС‚Р°
  local tok dom bp url
  tok=$(cat "$API_TOKEN_FILE" 2>/dev/null)
  dom=$(panel_domain); bp=$(panel_base); bp=${bp%/}
  url="https://127.0.0.1:2904$bp$2"
  if [[ -n "${3:-}" ]]; then
    curl -sk --max-time 30 -X "$1" -H "Host: $dom" -H "Authorization: Bearer $tok" -H "Content-Type: application/json" -d "$3" "$url"
  else
    curl -sk --max-time 30 -X "$1" -H "Host: $dom" -H "Authorization: Bearer $tok" "$url"
  fi
}

render_card() {
  local xui="рџ”ґ" ngx="рџ”ґ" up l1 l2 l3 cores ram_u ram_t ram_p du dt dp conns awg="" ifc hs now age rx tx dom tgp
  systemctl is-active -q x-ui  2>/dev/null && xui="рџџў"
  systemctl is-active -q nginx 2>/dev/null && ngx="рџџў"
  up=$(uptime -p 2>/dev/null | sed 's/^up //;s/^ *//')
  read -r l1 l2 l3 _ < /proc/loadavg 2>/dev/null
  cores=$(nproc 2>/dev/null); cores=${cores:-1}
  read -r _ ram_t ram_u _ < <(free -m 2>/dev/null | awk '/^Mem:/')
  if [[ "${ram_t:-0}" -gt 0 ]]; then ram_p=$(( ram_u*100/ram_t )); else ram_p=0; fi
  read -r du dt < <(df -BM / 2>/dev/null | awk 'NR==2{gsub(/M/,"",$3);gsub(/M/,"",$2);print $3,$2}')
  if [[ "${dt:-0}" -gt 0 ]]; then dp=$(( du*100/dt )); else dp=0; fi
  conns=$(ss -tnH 'sport = :443' 2>/dev/null | grep -c .); conns=${conns:-0}
  now=$(date +%s)
  while read -r ifc; do
    hs=$(awg show "$ifc" latest-handshakes 2>/dev/null | awk '{print $2}' | sort -nr | head -1)
    if [[ -n "$hs" && "$hs" != "0" ]]; then age=$(( now - hs )); (( age < 0 )) && age=0; awg+="${awg:+ В· }<code>$ifc</code>рџ‘‹$(fmt_age $age)"
    else awg+="${awg:+ В· }<code>$ifc</code>рџ‘‹вЂ”"; fi
  done < <(awg show 2>/dev/null | awk '/^interface:/{print $2}')
  [[ -z "$awg" ]] && awg="РЅРµС‚ РёРЅС‚РµСЂС„РµР№СЃРѕРІ"
  read -r rx tx < <(awk 'NR>2 && $1!~/lo:/ {rx+=$2; tx+=$10} END{print rx+0, tx+0}' /proc/net/dev 2>/dev/null)
  dom=$(hostname -f 2>/dev/null); dom=${dom:-$(hostname)}
  tgp="РїСЂСЏРјРѕР№"; [[ -n "$TG_PROXY_CUR" ]] && tgp="РїСЂРѕРєСЃРё <code>$(hesc "$TG_PROXY_CUR")</code>"
  printf 'рџ–Ґ <b>%s</b> вЂ” СЃРµСЂРІРµСЂ\n%s x-ui   %s nginx\nвЏ± Р°РїС‚Р°Р№Рј: %s\nрџ“Љ load: <code>%s %s %s</code> (%s СЏРґРµСЂ)\nрџ§  RAM: <code>%s/%s РњР‘ (%s%%)</code>\nрџ’ѕ Р”РёСЃРє: <code>%sM/%sM (%s%%)</code>\nрџЊђ 443: <code>%s</code> Р°РєС‚РёРІРЅС‹С… СЃРѕРµРґРёРЅРµРЅРёР№\nрџ“Ў AWG: %s\nрџ“Ґ RX: <code>%s</code> В· рџ“¤ TX: <code>%s</code> (СЃ Р·Р°РіСЂСѓР·РєРё)\nрџ“¤ TG-РІС‹С…РѕРґ: %s\nрџ”„ %s В· Р°РІС‚РѕРѕР±РЅРѕРІР»РµРЅРёРµ 10СЃ' \
    "$dom" "$xui" "$ngx" "${up:-?}" "${l1:-?}" "${l2:-?}" "${l3:-?}" "$cores" "${ram_u:-?}" "${ram_t:-?}" "$ram_p" "${du:-?}" "${dt:-?}" "$dp" "$conns" "$awg" "$(bot_fmt_bytes "${rx:-0}")" "$(bot_fmt_bytes "${tx:-0}")" "$tgp" "$(date '+%H:%M:%S')"
}

render_main() {
  local xui="рџ”ґ" ngx="рџ”ґ" nc in_n dom pb
  systemctl is-active -q x-ui  2>/dev/null && xui="рџџў"
  systemctl is-active -q nginx 2>/dev/null && ngx="рџџў"
  nc=$(sqlite3 "$XUI_DB" 'SELECT count(*) FROM clients;' 2>/dev/null); nc=${nc:-0}
  in_n=$(sqlite3 "$XUI_DB" 'SELECT count(*) FROM inbounds;' 2>/dev/null); in_n=${in_n:-0}
  dom=$(panel_domain); pb=$(panel_base)
  printf 'рџ–Ґ <b>РџР°РЅРµР»СЊ СЃС‚РµРєР°</b> вЂє Р“Р»Р°РІРЅРѕРµ\nрџ”— С…РѕСЃС‚: <a href="https://%s%s">%s</a>\n%s x-ui   %s nginx\nрџ‘Ґ РєР»РёРµРЅС‚РѕРІ: %s В· рџ“Ў РРЅР±Р°СѓРЅРґС‹: %s\nР’С‹Р±РµСЂРё СЂР°Р·РґРµР»:' "$dom" "$pb" "$dom" "$xui" "$ngx" "$nc" "$in_n"
}

render_clients() { # С‚РѕР»СЊРєРѕ Р·Р°РіРѕР»РѕРІРѕРє: РєР»РёРµРЅС‚С‹ вЂ” РєРЅРѕРїРєРё РІ РєР»Р°РІРёР°С‚СѓСЂРµ (kb_clients)
  local tot pages
  tot=$(sqlite3 "$XUI_DB" 'SELECT count(*) FROM clients;' 2>/dev/null); tot=${tot:-0}
  if (( tot == 0 )); then CL_PAGE=1; printf 'рџ‘Ґ <b>РљР»РёРµРЅС‚С‹</b>\nР’ РїР°РЅРµР»Рё РЅРµС‚ РєР»РёРµРЅС‚РѕРІ.'; return 0; fi
  pages=$(( (tot + CL_PER - 1) / CL_PER )); (( pages < 1 )) && pages=1
  (( CL_PAGE > pages )) && CL_PAGE=$pages; (( CL_PAGE < 1 )) && CL_PAGE=1
  printf 'рџ‘Ґ <b>РљР»РёРµРЅС‚С‹</b> В· РІСЃРµРіРѕ %s В· СЃС‚СЂ %s/%s\nРќР°Р¶РјРё РєР»РёРµРЅС‚Р° вЂ” РѕС‚РєСЂРѕРµС‚СЃСЏ РєР°СЂС‚РѕС‡РєР° (РїРѕРґРїРёСЃРєР°, QR, Р»РёРјРёС‚С‹, РёРЅР±Р°СѓРЅРґС‹).' "$tot" "$CL_PAGE" "$pages"
}

render_traffic() {
  local rows email up down tot out="" dom rx tx sum_u=0 sum_d=0
  read -r rx tx < <(awk 'NR>2 && $1!~/lo:/ {rx+=$2; tx+=$10} END{print rx+0, tx+0}' /proc/net/dev 2>/dev/null)
  rows=$(sqlite3 -separator '|' "$XUI_DB" \
    "SELECT COALESCE(email,''),COALESCE(up,0),COALESCE(down,0),COALESCE(total,0)
     FROM client_traffics ORDER BY id;" 2>/dev/null)
  if [[ -n "$rows" ]]; then
    while IFS='|' read -r email up down tot; do
      sum_u=$((sum_u+up)); sum_d=$((sum_d+down))
      local lim=""
      (( tot > 0 )) && lim=" / Р»РёРјРёС‚ $(bot_fmt_bytes "$tot")"
      out="${out}<code>$(hesc "$email")</code> в†‘$(bot_fmt_bytes "${up:-0}") в†“$(bot_fmt_bytes "${down:-0}")${lim}"$'\n'
    done <<<"$rows"
    out="${out}"$'\n'"РС‚РѕРіРѕ РїРѕ РєР»РёРµРЅС‚Р°Рј: в†‘$(bot_fmt_bytes $sum_u) в†“$(bot_fmt_bytes $sum_d)"$'\n'
  fi
  printf 'рџљ¦ <b>РўСЂР°С„РёРє</b>\nрџ“Ґ RX: <code>%s</code> В· рџ“¤ TX: <code>%s</code> (СЃ Р·Р°РіСЂСѓР·РєРё СЃРµСЂРІРµСЂР°)\n\n%s' \
    "$(bot_fmt_bytes "${rx:-0}")" "$(bot_fmt_bytes "${tx:-0}")" "${out:-РџРѕ РєР»РёРµРЅС‚Р°Рј РґР°РЅРЅС‹С… РЅРµС‚.}"
}

render_maint() {
  printf 'рџ›  <b>РћР±СЃР»СѓР¶РёРІР°РЅРёРµ</b>\nР”РµР№СЃС‚РІРёСЏ РІС‹РїРѕР»РЅСЏСЋС‚СЃСЏ РїРѕСЃР»Рµ вњ… РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ.\nРђСѓРґРёС‚ Рё РёРЅР±Р°СѓРЅРґС‹ РїСЂРёС…РѕРґСЏС‚ РѕС‚РґРµР»СЊРЅС‹Рј СЃРѕРѕР±С‰РµРЅРёРµРј.'
}

render_bksched() {
  local cal next mon ivm
  cal=$(systemctl cat xui-db-backup.timer 2>/dev/null | grep '^OnCalendar=' | head -1 | cut -d= -f2-)
  next=$(systemctl list-timers xui-db-backup.timer --no-pager 2>/dev/null | awk 'NR==2{printf "%s %s",$1,$2}')
  ivm=$(( MON_IV / 60 )); (( ivm < 1 )) && ivm=1
  mon="рџ”ґ РІС‹РєР»СЋС‡РµРЅ"; (( MON_ON == 1 )) && mon="рџџў РІРєР»СЋС‡С‘РЅ В· РєР°Р¶РґС‹Рµ ${ivm} РјРёРЅ"
  printf 'вЏ° <b>Р Р°СЃРїРёСЃР°РЅРёРµ</b>\n\nрџ’ѕ <b>Р‘СЌРєР°Рї Р‘Р”</b>\nРўРµРєСѓС‰РµРµ: <code>%s</code>\nРЎР»РµРґСѓСЋС‰РёР№ Р·Р°РїСѓСЃРє: %s\nР‘СЌРєР°Рї РїСЂРёСЃС‹Р»Р°РµС‚СЃСЏ РґРѕРєСѓРјРµРЅС‚РѕРј РІ СЌС‚РѕС‚ С‡Р°С‚.\n\nрџ•µпёЏ <b>РњРѕРЅРёС‚РѕСЂРёРЅРі</b>: %s\nРђР»РµСЂС‚С‹ РїСЂРёС…РѕРґСЏС‚ РІ СЌС‚РѕС‚ С‡Р°С‚.\nвњ…/вќЊ РЅР° РєРЅРѕРїРєРµ = СЃРѕР±С‹С‚РёРµ РІРєР»/РІС‹РєР» (Сѓ CPU/RAM РїРѕРІС‚РѕСЂРЅРѕРµ РЅР°Р¶Р°С‚РёРµ РјРµРЅСЏРµС‚ РїРѕСЂРѕРі):' \
    "${cal:-вЂ”}" "${next:-РІС‹РєР»СЋС‡РµРЅ}" "$mon"
}

# в”Ђв”Ђ РєР»Р°РІРёР°С‚СѓСЂС‹ СЌРєСЂР°РЅРѕРІ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
kb_main='[[{"text":"рџ–Ґ РЎРµСЂРІРµСЂ","callback_data":"nav:server"},{"text":"рџ‘Ґ РљР»РёРµРЅС‚С‹","callback_data":"nav:clients"}],[{"text":"рџљ¦ РўСЂР°С„РёРє","callback_data":"nav:traffic"},{"text":"рџ›  РћР±СЃР»СѓР¶РёРІР°РЅРёРµ","callback_data":"nav:maint"}],[{"text":"рџ”„ РћР±РЅРѕРІРёС‚СЊ","callback_data":"refresh"}]]'
kb_server='[[{"text":"рџ”„ РћР±РЅРѕРІРёС‚СЊ","callback_data":"refresh"},{"text":"вЏЇ РђРІС‚Рѕ","callback_data":"auto"}],[{"text":"в¬…пёЏ РњРµРЅСЋ","callback_data":"nav:main"}]]'
kb_traffic='[[{"text":"рџ”„ РћР±РЅРѕРІРёС‚СЊ","callback_data":"refresh"}],[{"text":"в¬…пёЏ РњРµРЅСЋ","callback_data":"nav:main"}]]'
kb_maint_fn() { # РґРёРЅР°РјРёС‡РµСЃРєРѕРµ РјРµРЅСЋ РѕР±СЃР»СѓР¶РёРІР°РЅРёСЏ: AdGuard вЂ” С‚РѕР»СЊРєРѕ РµСЃР»Рё СЋРЅРёС‚ РµСЃС‚СЊ; РєРЅРѕРїРєРё Р¶СѓСЂРЅР°Р»РѕРІ РѕС€РёР±РѕРє
  # Р·Р°РїСЏС‚С‹Рµ Р’РљР›Р®Р§Р•РќР« РІ РІСЃС‚Р°РІРєРё (РІРµРґСѓС‰Р°СЏ Сѓ СЂСЏРґР°, Сѓ РєРЅРѕРїРєРё вЂ” РІРµРґСѓС‰Р°СЏ), С‡С‚РѕР±С‹ РїСѓСЃС‚РѕР№ AdGuard РЅРµ Р»РѕРјР°Р» JSON
  local adg_row="," adg_err=""
  if systemctl cat AdGuardHome.service >/dev/null 2>&1; then
    adg_row=',[{"text":"рџ”Ѓ РџРµСЂРµР·Р°РіСЂСѓР·РёС‚СЊ AdGuard","callback_data":"askrestart:AdGuardHome"}]'
    adg_err=',{"text":"рџ“њ adg","callback_data":"err:adg"}'
  fi
  printf '[[{"text":"вљЎ РџРѕС‡РёРЅРёС‚СЊ","callback_data":"askfix"},{"text":"рџ”Ћ РђСѓРґРёС‚","callback_data":"doaudit"}],[{"text":"рџ”Ѓ РџРµСЂРµР·Р°РіСЂСѓР·РёС‚СЊ AWG","callback_data":"askawg"},{"text":"рџ”Ѓ РџРµСЂРµР·Р°РіСЂСѓР·РёС‚СЊ X-ui","callback_data":"askrestart:x-ui"}],[{"text":"рџ”Ѓ РџРµСЂРµР·Р°РіСЂСѓР·РёС‚СЊ Nginx","callback_data":"askrestart:nginx"},{"text":"рџ”Ѓ РџРµСЂРµР·Р°РіСЂСѓР·РёС‚СЊ Xray","callback_data":"askrestart:xray"}]%s[{"text":"рџ“Ў РРЅР±Р°СѓРЅРґС‹","callback_data":"doinb"},{"text":"рџ’ѕ Р‘СЌРєР°Рї Р‘Р”","callback_data":"askbackup"}],[{"text":"рџ“њ РћС€РёР±РєРё x-ui","callback_data":"err:xui"},{"text":"nginx","callback_data":"err:nginx"},{"text":"f2b","callback_data":"err:f2b"}%s],[{"text":"вЏ° Р Р°СЃРїРёСЃР°РЅРёРµ","callback_data":"nav:bksched"}],[{"text":"в¬…пёЏ РњРµРЅСЋ","callback_data":"nav:main"}]]' \
    "$adg_row" "$adg_err"
}
kb_sched() { # РґРёРЅР°РјРёС‡РµСЃРєР°СЏ РєР»Р°РІРёР°С‚СѓСЂР° СЂР°СЃРїРёСЃР°РЅРёСЏ (РјРѕРЅРёС‚РѕСЂРёРЅРі: вњ…/вќЊ РїРѕ СЃРѕСЃС‚РѕСЏРЅРёСЋ)
  local o ou xr nd nu c r l sw
  (( EV_OUT   == 1 )) && o="вњ… "   || o="вќЊ "
  (( EV_OUTUP == 1 )) && ou="вњ… "  || ou="вќЊ "
  (( EV_XRAY  == 1 )) && xr="вњ… "  || xr="вќЊ "
  (( EV_NODE  == 1 )) && nd="вњ… "  || nd="вќЊ "
  (( EV_NODEUP== 1 )) && nu="вњ… "  || nu="вќЊ "
  (( EV_CPU   == 1 )) && c="вњ… "   || c="вќЊ "
  (( EV_RAM   == 1 )) && r="вњ… "   || r="вќЊ "
  (( EV_LOGIN == 1 )) && l="вњ… "   || l="вќЊ "
  sw="в–¶пёЏ Р’РєР»СЋС‡РёС‚СЊ РјРѕРЅРёС‚РѕСЂРёРЅРі"; (( MON_ON == 1 )) && sw="вЏё Р’С‹РєР»СЋС‡РёС‚СЊ РјРѕРЅРёС‚РѕСЂРёРЅРі"
  local n2="вќЊ " a2="вќЊ " d2="вќЊ " ce="вќЊ " bf="вќЊ "
  (( EV_NGINX == 1 )) && n2="вњ… "
  (( EV_ADG   == 1 )) && a2="вњ… "
  (( EV_DISK  == 1 )) && d2="вњ… "
  (( EV_CERT  == 1 )) && ce="вњ… "
  (( EV_BKFAIL== 1 )) && bf="вњ… "
  printf '[[{"text":"вЏ° Р‘СЌРєР°Рї: РєР°Р¶РґС‹Р№ С‡Р°СЃ","callback_data":"bkset:hourly"},{"text":"РљР°Р¶РґС‹Рµ 6С‡","callback_data":"bkset:6h"}],[{"text":"РљР°Р¶РґС‹Рµ 12С‡","callback_data":"bkset:12h"},{"text":"Р Р°Р· РІ РґРµРЅСЊ (04:00)","callback_data":"bkset:daily"}],[{"text":"вЏё Р‘СЌРєР°Рї РІС‹РєР»СЋС‡РёС‚СЊ","callback_data":"bkset:off"}],[{"text":"%s","callback_data":"mon:sw"}],[{"text":"вЏ± 1 РјРёРЅ","callback_data":"moniv:60"},{"text":"вЏ± 5 РјРёРЅ","callback_data":"moniv:300"},{"text":"вЏ± 15 РјРёРЅ","callback_data":"moniv:900"}],[{"text":"%sРСЃС…РѕРґСЏС‰РёРµ в›”","callback_data":"mon:out"},{"text":"%sРСЃС…РѕРґСЏС‰РёРµ в†©пёЏ","callback_data":"mon:outup"}],[{"text":"%sРЎР±РѕР№ Xray","callback_data":"mon:xray"}],[{"text":"%sРЈР·РµР» РЅРµРґРѕСЃС‚СѓРїРµРЅ","callback_data":"mon:node"},{"text":"%sРЈР·РµР» в†©пёЏ","callback_data":"mon:nodeup"}],[{"text":"%sCPU в‰Ґ%s%%","callback_data":"mon:cpu"},{"text":"%sRAM в‰Ґ%s%%","callback_data":"mon:ram"}],[{"text":"%sNginx СѓРїР°Р»","callback_data":"mon:nginx"},{"text":"%sAdGuard СѓРїР°Р»","callback_data":"mon:adg"}],[{"text":"%sР”РёСЃРє в‰Ґ%s%%","callback_data":"mon:disk"},{"text":"%sРЎРµСЂС‚С‹ в‰¤7Рґ","callback_data":"mon:cert"},{"text":"%sР‘СЌРєР°Рї СѓРїР°Р»","callback_data":"mon:bkfail"}],[{"text":"%sРџРѕРїС‹С‚РєР° РІС…РѕРґР°","callback_data":"mon:login"}],[{"text":"в¬…пёЏ РћР±СЃР»СѓР¶РёРІР°РЅРёРµ","callback_data":"nav:maint"}]]' \
    "$sw" "$o" "$ou" "$xr" "$nd" "$nu" "$c" "$CPU_TH" "$r" "$RAM_TH" "$n2" "$a2" "$d2" "$DISK_TH" "$ce" "$bf" "$l"
}

kb_clients() { # РєРЅРѕРїРєРё РєР»РёРµРЅС‚РѕРІ РўР•РљРЈР©Р•Р™ СЃС‚СЂР°РЅРёС†С‹ (РѕРґРёРЅ РєР»РёРµРЅС‚ вЂ” РѕРґРёРЅ СЂСЏРґ) + РїР°РіРёРЅР°С†РёСЏ + РґРµР№СЃС‚РІРёСЏ
  # Р’РђР–РќРћ: СЂСЏРґС‹ РєРЅРѕРїРѕРє РёРґСѓС‚ РІРµСЂС…РЅРёРј СѓСЂРѕРІРЅРµРј РјР°СЃСЃРёРІР° rows вЂ” РІР»РѕР¶РµРЅРЅС‹Р№ РјР°СЃСЃРёРІ РІ СЂСЏРґСѓ
  # Telegram РЅРµ СЂРµРЅРґРµСЂРёС‚ (Р±С‹Р»Р° РєРЅРѕРїРєР°-В«вЂ¦В» РЅР° РІРµСЃСЊ СЂСЏРґ).
  local total pages start n email sep="" rows=""
  total=$(sqlite3 "$XUI_DB" 'SELECT count(*) FROM clients;' 2>/dev/null); total=${total:-0}
  if (( total == 0 )); then
    printf '[[{"text":"вћ• РЎРѕР·РґР°С‚СЊ","callback_data":"new:start"}],[{"text":"в¬…пёЏ РњРµРЅСЋ","callback_data":"nav:main"}]]'
    return 0
  fi
  pages=$(( (total + CL_PER - 1) / CL_PER ))
  (( CL_PAGE > pages )) && CL_PAGE=$pages; (( CL_PAGE < 1 )) && CL_PAGE=1
  start=$(( (CL_PAGE - 1) * CL_PER ))
  n=$start
  while IFS='|' read -r email st; do
    n=$((n+1))
    rows+="${sep}[$(jq -n --arg e "$email" --arg st "$st" --arg n "$n" '{text:($st+" "+$e),callback_data:("copen:"+$n)}')]"; sep=","
  done < <(sqlite3 -separator '|' "$XUI_DB" "SELECT COALESCE(c.email,'РєР»РёРµРЅС‚'),CASE c.enable WHEN 1 THEN 'вњ…' ELSE 'в›”' END FROM clients c ORDER BY c.id LIMIT ${CL_PER} OFFSET ${start};" 2>/dev/null)
  local pg=""
  if (( pages > 1 )); then
    pg="[{\"text\":\"в—ЂпёЏ\",\"callback_data\":\"clpage:$((CL_PAGE-1))\"},{\"text\":\"$CL_PAGE / $pages\",\"callback_data\":\"clpage:$CL_PAGE\"},{\"text\":\"в–¶пёЏ\",\"callback_data\":\"clpage:$((CL_PAGE+1))\"}],"
  fi
  # РїР°РіРёРЅР°С†РёСЏ вЂ” Р’РќРР—РЈ СЃРїРёСЃРєР° (РїРѕСЃР»Рµ РєР»РёРµРЅС‚РѕРІ), РґРµР№СЃС‚РІРёСЏ вЂ” РІ СЃР°РјРѕРј РЅРёР·Сѓ
  printf '[%s%s%s[{"text":"вћ• РЎРѕР·РґР°С‚СЊ","callback_data":"new:start"},{"text":"рџ“‹ Р’СЃРµ СЃСЃС‹Р»РєРё","callback_data":"subsall"}],[{"text":"в¬…пёЏ РњРµРЅСЋ","callback_data":"nav:main"}]]' "$rows" "${rows:+,}" "$pg"
}

screen_text() { # $1=menu в†’ С‚РµРєСЃС‚ СЌРєСЂР°РЅР° (HTML)
  case "$1" in
    server)  render_card ;;
    clients) render_clients ;;
    traffic) render_traffic ;;
    maint)   render_maint ;;
    bksched) render_bksched ;;
    client)  client_card_render ;;
    *)       render_main ;;
  esac
}
screen_kb() { # $1=menu в†’ inline_keyboard JSON
  case "$1" in
    server)  printf '%s' "$kb_server" ;;
    clients) kb_clients ;;
    traffic) printf '%s' "$kb_traffic" ;;
    maint)   kb_maint_fn ;;
    bksched) printf '%s' "$(kb_sched)" ;;
    client)  kb_client_card ;;
    *)       printf '%s' "$kb_main" ;;
  esac
}

# в”Ђв”Ђ РѕРєРЅРѕ: РїРѕРєР°Р·Р°С‚СЊ/РѕР±РЅРѕРІРёС‚СЊ СЌРєСЂР°РЅ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
start_autoloop() { # С†РёРєР» Р°РІС‚РѕРѕР±РЅРѕРІР»РµРЅРёСЏ, РµСЃР»Рё РµС‰С‘ РЅРµ Р¶РёРІС‘С‚
  if ! kill -0 "$CARD_PID" 2>/dev/null; then
    window_loop "$ADMIN_CHAT_ID" "$WINDOW_MID" &
    CARD_PID=$!
  fi
}
show_screen() { # $1=chat $2=menu
  local chat=$1 menu=$2 text kb
  CUR_MENU=$menu
  text=$(screen_text "$menu"); kb=$(screen_kb "$menu")
  if [[ -n "$WINDOW_MID" ]] && tg_edit "$chat" "$WINDOW_MID" "$text" "$kb"; then
    : # РѕРєРЅРѕ РѕР±РЅРѕРІРёР»РѕСЃСЊ РЅР° РјРµСЃС‚Рµ
  else
    WINDOW_MID=$(tg_send_kb "$chat" "$text" "$kb")
  fi
  if [[ "$menu" == "server" ]]; then
    printf '%s server' "$WINDOW_MID" > "$CARD_FLAG"; start_autoloop
  else
    rm -f "$CARD_FLAG"
  fi
}

window_loop() { # $1=chat $2=mid вЂ” С„РѕРЅРѕРј, РїРѕРєР° РѕРєРЅРѕ=server Рё Р¶РёРІ CARD_FLAG
  local chat=$1 mid=$2 i m
  for (( i=0; i<60; i++ )); do
    sleep 10
    [[ -f "$CARD_FLAG" ]] || return 0
    read -r m menu < "$CARD_FLAG"
    [[ "$m" != "$mid" ]] && return 0
    [[ "${menu:-}" == "server" ]] || continue
    tg_edit "$chat" "$mid" "$(render_card)" "$kb_server" || return 0
  done
  rm -f "$CARD_FLAG"
}

# в”Ђв”Ђ РґРµР№СЃС‚РІРёСЏ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
cmd_inbounds() {
  sqlite3 -separator ' | ' "$XUI_DB" \
    "SELECT id,COALESCE(remark,''),listen,CASE enable WHEN 1 THEN 'on' ELSE 'OFF' END
     FROM inbounds ORDER BY enable DESC, id;" 2>/dev/null
}
cmd_subs() {
  local dom rows out="" email sid en
  dom=$(panel_domain)
  rows=$(sqlite3 -separator '|' "$XUI_DB" \
    "SELECT COALESCE(email,''),COALESCE(sub_id,''),CASE enable WHEN 1 THEN 'on' ELSE 'OFF' END
     FROM clients ORDER BY id;" 2>/dev/null)
  [[ -z "$rows" ]] && { printf 'РљР»РёРµРЅС‚РѕРІ РІ РїР°РЅРµР»Рё РЅРµС‚.'; return 0; }
  while IFS='|' read -r email sid en; do
    [[ -z "$sid" ]] && continue
    out="${out}$en $(hesc "$email")"$'\n'"https://${dom}/podpiska/${sid}"$'\n\n'
  done <<<"$rows"
  [[ -z "$out" ]] && out="РЈ РєР»РёРµРЅС‚РѕРІ РЅРµС‚ sub_id."
  printf '%s' "$out"
}
sub_url_for() { # $1=email_or_n в†’ url
  local dom rows email sid n=0
  dom=$(panel_domain)
  rows=$(sqlite3 -separator '|' "$XUI_DB" \
    "SELECT COALESCE(email,''),COALESCE(sub_id,'') FROM clients ORDER BY id;" 2>/dev/null)
  while IFS='|' read -r email sid; do
    n=$((n+1))
    if [[ "$1" == "$email" || "$1" == "$n" ]]; then
      [[ -z "$sid" ]] && return 1
      printf 'https://%s/podpiska/%s' "$dom" "$sid"; return 0
    fi
  done <<<"$rows"
  return 1
}
send_client_pack() { # $1=chat $2=n вЂ” СЃСЃС‹Р»РєР° + QR РєР»РёРµРЅС‚Р° (РѕР±Рµ СЃ РєРЅРѕРїРєРѕР№ рџ—‘)
  local url png="/tmp/tg-stack-qr.png" email
  email=$(sqlite3 "$XUI_DB" "SELECT COALESCE(email,'РєР»РёРµРЅС‚') FROM clients ORDER BY id LIMIT 1 OFFSET $(( $2 - 1 ));" 2>/dev/null)
  url=$(sub_url_for "$2") || { tg_send "$1" "РЈ РєР»РёРµРЅС‚Р° ${email} РЅРµС‚ sub_id."; return 0; }
  qrencode -o "$png" -s 10 -m 2 "$url" 2>/dev/null
  tgc -s --max-time 40 -F "chat_id=$1" -F "photo=@${png}" -F "reply_markup={\"inline_keyboard\":$KB_HIDE}" "$API/sendPhoto" >/dev/null
  rm -f "$png"
  tg_send_kb "$1" "рџ”— ${email}"$'\n'"$url" "$KB_HIDE" >/dev/null
}
cmd_awg_restart() {
  local ifaces if_ out=""
  mapfile -t ifaces < <(awg show 2>/dev/null | grep '^interface:' | awk '{print $2}')
  if (( ${#ifaces[@]} == 0 )); then printf 'AWG РёРЅС‚РµСЂС„РµР№СЃРѕРІ РЅРµС‚.'; return 0; fi
  for if_ in "${ifaces[@]}"; do
    awg-quick down "$if_" >/dev/null 2>&1
    if awg-quick up "$if_" >/dev/null 2>&1; then out="${out}$if_: РїРµСЂРµР·Р°РїСѓС‰РµРЅ вњ“"$'\n'
    else out="${out}$if_: РћРЁРР‘РљРђ РїРѕРґСЉС‘РјР° (awg-quick up)"$'\n'; fi
  done
  printf '%s' "$out"
}
# в”Ђв”Ђ РјР°СЃС‚РµСЂ СЃРѕР·РґР°РЅРёСЏ РєР»РёРµРЅС‚Р° (API РїР°РЅРµР»Рё, РїР°РЅРµР»СЊ СЃР°РјР° РіРµРЅРµСЂРёС‚ РєСЂРµРґС‹) в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
wiz_reset() { NEW_STEP=""; NEW_IN=""; NEW_GB=-1; NEW_DAYS=0; NEW_EMAIL=""; NEW_SUBID=""; WIZ_MID=""; wiz_save; }
wiz_save() { # СЃРѕС…СЂР°РЅРёС‚СЊ СЃРµСЃСЃРёСЋ РјР°СЃС‚РµСЂР° вЂ” РїРµСЂРµР¶РёРІР°РµС‚ СЂРµСЃС‚Р°СЂС‚ Р±РѕС‚Р°
  [[ -d /run ]] || return 0
  printf 'WIZ_MID=%s\nNEW_STEP=%s\nNEW_IN=%s\nNEW_GB=%s\nNEW_DAYS=%s\nNEW_EMAIL=%s\nNEW_SUBID=%s\n' \
    "$WIZ_MID" "$NEW_STEP" "$NEW_IN" "$NEW_GB" "$NEW_DAYS" "$NEW_EMAIL" "$NEW_SUBID" \
    > "$WIZ_STATE" 2>/dev/null || true
}
wiz_load() { # РІРѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ СЃРµСЃСЃРёСЋ РјР°СЃС‚РµСЂР° РїРѕСЃР»Рµ СЂРµСЃС‚Р°СЂС‚Р°
  [[ -s "$WIZ_STATE" ]] || return 0
  local k v
  while IFS='=' read -r k v; do
    case "$k" in
      WIZ_MID) WIZ_MID="$v" ;; NEW_STEP) NEW_STEP="$v" ;; NEW_IN) NEW_IN="$v" ;;
      NEW_GB) NEW_GB="$v" ;; NEW_DAYS) NEW_DAYS="$v" ;;
      NEW_EMAIL) NEW_EMAIL="$v" ;; NEW_SUBID) NEW_SUBID="$v" ;;
    esac
  done < "$WIZ_STATE"
}
wiz_render() {
  local ib iname
  case "$NEW_STEP" in
    wait_in)
      printf 'вћ• <b>РќРѕРІС‹Р№ РєР»РёРµРЅС‚</b> вЂ” С€Р°Рі 1/4\nР’С‹Р±РµСЂРё РёРЅР±Р°СѓРЅРґС‹ (РјРѕР¶РЅРѕ РЅРµСЃРєРѕР»СЊРєРѕ вЂ” РїРѕРІС‚РѕСЂРЅРѕРµ РЅР°Р¶Р°С‚РёРµ СЃРЅРёРјР°РµС‚):' ;;
    gb)
      ib=$(sqlite3 "$XUI_DB" "SELECT group_concat(COALESCE(remark,'?'), ', ') FROM inbounds WHERE id IN ($NEW_IN);" 2>/dev/null)
      printf 'вћ• <b>РќРѕРІС‹Р№ РєР»РёРµРЅС‚</b> вЂ” С€Р°Рі 2/4\nРРЅР±Р°СѓРЅРґ: <b>%s</b>\nР›РёРјРёС‚ С‚СЂР°С„РёРєР°:' "$(hesc "$ib")" ;;
    days)
      printf 'вћ• <b>РќРѕРІС‹Р№ РєР»РёРµРЅС‚</b> вЂ” С€Р°Рі 3/4\nРўСЂР°С„РёРє: %s\nРЎСЂРѕРє РґРµР№СЃС‚РІРёСЏ:' "$([[ $NEW_GB -ge 0 ]] && printf '%s Р“Р‘' "$NEW_GB" || printf 'в€ћ Р±РµР·Р»РёРјРёС‚')" ;;
    email)
      printf 'вћ• <b>РќРѕРІС‹Р№ РєР»РёРµРЅС‚</b> вЂ” С€Р°Рі 4/4\nРўСЂР°С„РёРє: %s В· РЎСЂРѕРє: %s\nРРјСЏ РєР»РёРµРЅС‚Р° (email):' \
        "$([[ $NEW_GB -ge 0 ]] && printf '%s Р“Р‘' "$NEW_GB" || printf 'в€ћ')" \
        "$([[ $NEW_DAYS -gt 0 ]] && printf '%s РґРЅ' "$NEW_DAYS" || printf 'в€ћ')" ;;
    confirm)
      ib=$(sqlite3 "$XUI_DB" "SELECT group_concat(COALESCE(remark,'?'), ', ') FROM inbounds WHERE id IN ($NEW_IN);" 2>/dev/null)
      printf 'вњ… <b>РџРѕРґС‚РІРµСЂРґРё СЃРѕР·РґР°РЅРёРµ</b>\nРРјСЏ: <code>%s</code>\nРРЅР±Р°СѓРЅРґ: <b>%s</b>\nРўСЂР°С„РёРє: %s\nРЎСЂРѕРє: %s' \
        "$(hesc "$NEW_EMAIL")" "$(hesc "$ib")" \
        "$([[ $NEW_GB -ge 0 ]] && printf '%s Р“Р‘' "$NEW_GB" || printf 'в€ћ Р±РµР·Р»РёРјРёС‚')" \
        "$([[ $NEW_DAYS -gt 0 ]] && printf '%s РґРЅРµР№' "$NEW_DAYS" || printf 'в€ћ Р±РµСЃСЃСЂРѕС‡РЅРѕ')" ;;
    *) printf 'РњР°СЃС‚РµСЂ СЃРѕР·РґР°РЅРёСЏ РєР»РёРµРЅС‚Р°.' ;;
  esac
}
wiz_kb() {
  local btn rows id rem port mark
  case "$NEW_STEP" in
    wait_in)
      rows=""
      while IFS='|' read -r id rem port; do
        [[ ",$NEW_IN," == *",$id,"* ]] && mark="вњ… " || mark=""
        rows+="[$(jq -n --arg t "$mark$rem" --arg id "$id" '{text:$t,callback_data:("new:in:"+$id)}')],"
      done < <(sqlite3 -separator '|' "$XUI_DB" \
        "SELECT id,COALESCE(remark,'?'),port FROM inbounds WHERE enable=1 ORDER BY id;" 2>/dev/null)
      if [[ -z "$rows" ]]; then
        printf '[[{"text":"РќРµС‚ Р°РєС‚РёРІРЅС‹С… РёРЅР±Р°СѓРЅРґРѕРІ","callback_data":"noop"}],[{"text":"вќЊ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]'
      elif [[ -n "$NEW_IN" ]]; then
        printf '[%s[{"text":"Р”Р°Р»РµРµ вћЎпёЏ","callback_data":"new:indone"},{"text":"вќЊ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]' "$rows"
      else
        printf '[%s[{"text":"вќЊ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]' "$rows"
      fi ;;
    gb)      printf '[[{"text":"в€ћ Р±РµР·Р»РёРјРёС‚","callback_data":"new:gb:0"},{"text":"10 Р“Р‘","callback_data":"new:gb:10"},{"text":"50 Р“Р‘","callback_data":"new:gb:50"}],[{"text":"100 Р“Р‘","callback_data":"new:gb:100"},{"text":"500 Р“Р‘","callback_data":"new:gb:500"},{"text":"вњЏпёЏ РЎРІРѕР№ Р“Р‘","callback_data":"new:gbtxt"}],[{"text":"в¬…пёЏ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]' ;;
    gb_txt)  printf '[[{"text":"в¬…пёЏ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]' ;;
    days)    printf '[[{"text":"в€ћ Р±РµСЃСЃСЂРѕС‡РЅРѕ","callback_data":"new:days:0"},{"text":"7 РґРЅРµР№","callback_data":"new:days:7"},{"text":"30 РґРЅРµР№","callback_data":"new:days:30"}],[{"text":"90 РґРЅРµР№","callback_data":"new:days:90"},{"text":"вњЏпёЏ РЎРІРѕР№ СЃСЂРѕРє","callback_data":"new:daystxt"}],[{"text":"в¬…пёЏ РќР°Р·Р°Рґ","callback_data":"new:backgb"}]]' ;;
    days_txt) printf '[[{"text":"в¬…пёЏ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]' ;;
    email)   printf '[[{"text":"рџЋІ РђРІС‚РѕРёРјСЏ","callback_data":"new:emauto"},{"text":"вњЏпёЏ Р’РІРµСЃС‚Рё РёРјСЏ","callback_data":"new:emtxt"}],[{"text":"в¬…пёЏ РќР°Р·Р°Рґ","callback_data":"new:backdays"}]]' ;;
    email_txt) printf '[[{"text":"в¬…пёЏ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]' ;;
    confirm) printf '[[{"text":"вњ… РЎРѕР·РґР°С‚СЊ","callback_data":"new:go"}],[{"text":"вќЊ РћС‚РјРµРЅРёС‚СЊ","callback_data":"new:abort"}]]' ;;
    done)    printf '[[{"text":"вћ• Р•С‰С‘ РєР»РёРµРЅС‚","callback_data":"new:start"}],[{"text":"Р—Р°РєСЂС‹С‚СЊ","callback_data":"new:close"}]]' ;;
    *)       printf '[[{"text":"в¬…пёЏ РњРµРЅСЋ","callback_data":"nav:main"}]]' ;;
  esac
}
show_wizard() { # $1=chat вЂ” СЃРѕР·РґР°С‚СЊ/РѕР±РЅРѕРІРёС‚СЊ РєР°СЂС‚РѕС‡РєСѓ РјР°СЃС‚РµСЂР°
  local chat=$1 text kb json resp
  wiz_save
  text=$(wiz_render); kb=$(wiz_kb)
  json=$(jq -n --arg c "$chat" --arg t "$text" --argjson kb "$kb" \
    '{chat_id:$c,text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
  if [[ -n "$WIZ_MID" ]]; then
    json=$(jq -n --arg c "$chat" --arg m "$WIZ_MID" --arg t "$text" --argjson kb "$kb" \
      '{chat_id:$c,message_id:($m|tonumber),text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
    resp=$(tgc -s --max-time 40 -X POST "$API/editMessageText" -H 'Content-Type: application/json' -d "$json")
    if jq -re '.ok == true' <<<"$resp" >/dev/null 2>&1 || grep -q "not modified" <<<"$resp"; then return 0; fi
    bot_log "WIZ: edit msg $WIZ_MID РЅРµ СѓРґР°Р»СЃСЏ: $(head -c 200 <<<"$resp")"
  fi
  resp=$(tgc -s --max-time 40 -X POST "$API/sendMessage" -H 'Content-Type: application/json' -d "$json")
  WIZ_MID=$(jq -r '.result.message_id // empty' <<<"$resp" 2>/dev/null)
  [[ -z "$WIZ_MID" ]] && bot_log "WIZ: sendMessage РЅРµ СѓРґР°Р»СЃСЏ: $(head -c 200 <<<"$resp")"
  wiz_save
}
wiz_done() { # $1=chat $2=text вЂ” Р·Р°РІРµСЂС€РёС‚СЊ РјР°СЃС‚РµСЂ
  NEW_STEP="done"
  local text kb json
  wiz_save
  text="$2"; kb=$(wiz_kb)
  json=$(jq -n --arg c "$1" --arg t "$text" --argjson kb "$kb" \
    '{chat_id:$c,text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
  if [[ -n "$WIZ_MID" ]]; then
    local j2; j2=$(jq -n --arg c "$1" --arg m "$WIZ_MID" --arg t "$text" --argjson kb "$kb" \
      '{chat_id:$c,message_id:($m|tonumber),text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
    tgc -s --max-time 40 -X POST "$API/editMessageText" -H 'Content-Type: application/json' -d "$j2" >/dev/null
  else
    tgc -s --max-time 40 -X POST "$API/sendMessage" -H 'Content-Type: application/json' -d "$json" >/dev/null
  fi
}
api_create_client() { # в†’ "OK" РёР»Рё С‚РµРєСЃС‚ РѕС€РёР±РєРё
  [[ -z "$NEW_IN" || -z "$NEW_EMAIL" ]] && { printf 'СЃРµСЃСЃРёСЏ РјР°СЃС‚РµСЂР° РїРѕС‚РµСЂСЏРЅР°'; return 0; }
  local ms=0 gb=0
  (( NEW_DAYS > 0 )) && ms=$(( ($(date +%s) + NEW_DAYS * 86400) * 1000 ))
  (( NEW_GB > 0 )) && gb=$(( NEW_GB * 1024 * 1024 * 1024 ))
  local payload resp msg
  payload=$(jq -nc --arg e "$NEW_EMAIL" --arg s "$NEW_SUBID" --argjson gb "$gb" --argjson ms "$ms" --argjson in "[$NEW_IN]" \
    '{client:{email:$e,enable:true,limitIp:0,totalGB:$gb,expiryTime:$ms,subId:$s},inboundIds:$in}')
  resp=$(api_call POST /panel/api/clients/add "$payload")
  if jq -re '.success == true' <<<"${resp:-}" >/dev/null 2>&1; then
    printf 'OK'
  else
    msg=$(jq -r '.msg // "РѕС€РёР±РєР° API"' <<<"${resp:-}" 2>/dev/null)
    printf '%s' "$msg"
  fi
}
new_client_send_links() { # $1=chat $2=email $3=subId вЂ” СЃСЃС‹Р»РєР°+QR СЃРІРµР¶РµСЃРѕР·РґР°РЅРЅРѕРіРѕ РєР»РёРµРЅС‚Р° (РѕР±Рµ СЃ РєРЅРѕРїРєРѕР№ рџ—‘)
  local dom url png="/tmp/tg-stack-qr.png"
  dom=$(panel_domain)
  url="https://${dom}/podpiska/${3}"
  qrencode -o "$png" -s 10 -m 2 "$url" 2>/dev/null
  tgc -s --max-time 40 -F "chat_id=$1" -F "photo=@${png}" -F "reply_markup={\"inline_keyboard\":$KB_HIDE}" "$API/sendPhoto" >/dev/null
  rm -f "$png"
  tg_send_kb "$1" "рџ”— ${2}"$'\n'"$url" "$KB_HIDE" >/dev/null
}

# в”Ђв”Ђ РєР°СЂС‚РѕС‡РєР° РєР»РёРµРЅС‚Р°: РїРѕРґРїРёСЃРєР° / QR / РёРЅР±Р°СѓРЅРґС‹ / Р»РёРјРёС‚С‹ / СѓРґР°Р»РµРЅРёРµ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
em_ok() { [[ "$1" =~ ^[A-Za-z0-9_.-]{1,40}$ ]]; }
client_exists() { sqlite3 "$XUI_DB" "SELECT 1 FROM clients WHERE email='$1';" 2>/dev/null | grep -q 1; }
client_in_csv() { # $1=email в†’ csv inbound_id РєР»РёРµРЅС‚Р°
  sqlite3 "$XUI_DB" "SELECT COALESCE(group_concat(ci.inbound_id),'') FROM client_inbounds ci JOIN clients c ON c.id=ci.client_id WHERE c.email='$1';" 2>/dev/null
}
csv_diff() { # $1=A $2=B в†’ СЌР»РµРјРµРЅС‚С‹ A, РєРѕС‚РѕСЂС‹С… РЅРµС‚ РІ B (csv)
  local out="" x
  [[ -z "$1" ]] && return 0
  while IFS= read -r x; do
    [[ -z "$x" ]] && continue
    [[ ",$2," == *",$x,"* ]] || out="${out}${out:+,}$x"
  done < <(tr ',' '\n' <<<"$1")
  printf '%s' "$out"
}
api_client_get() { # $1=email в†’ JSON РєР»РёРµРЅС‚Р° (id СЃС‚СЂРѕРєРѕР№, allowedIPs РјР°СЃСЃРёРІРѕРј) РёР»Рё ""
  local r
  r=$(api_call GET "/panel/api/clients/get/$1")
  jq -re '.success == true' <<<"${r:-}" >/dev/null 2>&1 || { printf ''; return 0; }
  jq -c '.obj.client | .id=(.id|tostring) | .allowedIPs=(if (.allowedIPs|type)=="string" and .allowedIPs!="" then [.allowedIPs] elif (.allowedIPs|type)=="array" then . else [] end)' <<<"$r" 2>/dev/null
}
api_client_update() { # $1=email $2=JSON-РёР·РјРµРЅРµРЅРёСЏ (camelCase) в†’ "OK" | С‚РµРєСЃС‚ РѕС€РёР±РєРё
  local c payload resp ch="$2"
  c=$(api_client_get "$1")
  [[ -z "$c" ]] && { printf 'РєР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ С‡РµСЂРµР· API'; return 0; }
  payload=$(jq -c '. + $ch' --argjson ch "$ch" <<<"$c" 2>/dev/null)
  [[ -z "$payload" ]] && { printf 'РѕС€РёР±РєР° СЃР±РѕСЂРєРё payload'; return 0; }
  resp=$(api_call POST "/panel/api/clients/update/$1" "$payload")
  if jq -re '.success == true' <<<"${resp:-}" >/dev/null 2>&1; then printf 'OK'
  else jq -r '.msg // "РѕС€РёР±РєР° API"' <<<"${resp:-}" 2>/dev/null | head -c 200; fi
}
api_client_ids() { # $1=email $2=attach|detach $3=csv ids в†’ "OK" | С‚РµРєСЃС‚ РѕС€РёР±РєРё
  local arr payload resp
  arr=$(jq -nc --arg c "$3" '[$c | split(",") | map(select(length>0) | tonumber)]' 2>/dev/null)
  [[ -z "$arr" ]] && { printf 'РѕС€РёР±РєР° СЃРїРёСЃРєР° РёРЅР±Р°СѓРґРѕРІ'; return 0; }
  payload=$(jq -nc --argjson i "$arr" '{inboundIds:$i}')
  resp=$(api_call POST "/panel/api/clients/$1/$2" "$payload")
  if jq -re '.success == true' <<<"${resp:-}" >/dev/null 2>&1; then printf 'OK'
  else jq -r '.msg // "РѕС€РёР±РєР° API"' <<<"${resp:-}" 2>/dev/null | head -c 200; fi
}
api_client_del() { # $1=email в†’ "OK" | С‚РµРєСЃС‚ РѕС€РёР±РєРё
  local resp
  resp=$(api_call POST "/panel/api/clients/del/$1")
  if jq -re '.success == true' <<<"${resp:-}" >/dev/null 2>&1; then printf 'OK'
  else jq -r '.msg // "РѕС€РёР±РєР° API"' <<<"${resp:-}" 2>/dev/null | head -c 200; fi
}
send_qr_msg() { # $1=chat $2=url вЂ” QR-С„РѕС‚Рѕ СЃ РєРЅРѕРїРєРѕР№ рџ—‘
  local png="/tmp/tg-stack-qr.png"
  qrencode -o "$png" -s 10 -m 2 "$2" 2>/dev/null
  tgc -s --max-time 40 -F "chat_id=$1" -F "photo=@${png}" -F "reply_markup={\"inline_keyboard\":$KB_HIDE}" "$API/sendPhoto" >/dev/null
  rm -f "$png"
}
client_card_render() { # РїРѕ E_EMAIL
  local row email sid en lip tgb exp inb used st lim till
  row=$(sqlite3 -separator '|' "$XUI_DB" \
    "SELECT COALESCE(email,''),COALESCE(sub_id,''),enable,COALESCE(limit_ip,0),COALESCE(total_gb,0),COALESCE(expiry_time,0)
     FROM clients WHERE email='$E_EMAIL';" 2>/dev/null)
  [[ -z "$row" ]] && { printf 'рџ‘¤ РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ (СѓРґР°Р»С‘РЅ?).'; return 0; }
  IFS='|' read -r email sid en lip tgb exp <<<"$row"
  inb=$(sqlite3 "$XUI_DB" "SELECT COALESCE(group_concat(COALESCE(i.remark,'?'),', '),'') FROM client_inbounds ci JOIN inbounds i ON i.id=ci.inbound_id JOIN clients c ON c.id=ci.client_id WHERE c.email='$E_EMAIL';" 2>/dev/null)
  used=$(sqlite3 "$XUI_DB" "SELECT COALESCE(SUM(up+down),0) FROM client_traffics WHERE email='$E_EMAIL';" 2>/dev/null); used=${used:-0}
  st="рџ”ґ OFF"; [[ "$en" == "1" ]] && st="рџџў on"
  lim="в€ћ Р±РµР·Р»РёРјРёС‚"; (( tgb > 0 )) && lim="$(bot_fmt_bytes "$tgb")"
  till="в€ћ Р±РµСЃСЃСЂРѕС‡РЅРѕ"
  if (( exp > 0 )); then
    till="РґРѕ $(date -d "@$(( exp / 1000 ))" '+%d.%m.%Y' 2>/dev/null)"
    (( exp < $(date +%s) * 1000 )) && till+=" (РёСЃС‚С‘Рє)"
  fi
  printf 'рџ‘¤ <b>%s</b> %s\nрџ“Ў РРЅР±Р°СѓРЅРґС‹: %s\nрџ“Љ РўСЂР°С„РёРє: %s РёР· %s\nвЏі РЎСЂРѕРє: %s\nрџ”’ IP-Р»РёРјРёС‚: %s' \
    "$(hesc "$email")" "$st" "${inb:-РЅРµС‚}" "$(bot_fmt_bytes "$used")" "$lim" "$till" \
    "$( [[ $lip -gt 0 ]] && printf '%s IP' "$lip" || printf 'РЅРµС‚' )"
}
kb_client_card() {
  local e="$E_EMAIL" en tog
  en=$(sqlite3 "$XUI_DB" "SELECT COALESCE(enable,0) FROM clients WHERE email='$e';" 2>/dev/null); en=${en:-0}
  if [[ "$en" == "1" ]]; then tog='в›” Р’С‹РєР»СЋС‡РёС‚СЊ'; else tog='вњ… Р’РєР»СЋС‡РёС‚СЊ'; fi
  printf '[[{"text":"рџ”— РџРѕРґРїРёСЃРєР°","callback_data":"csub:%s"},{"text":"рџ“± QR","callback_data":"cqr:%s"}],[{"text":"рџ“Ў РРЅР±Р°СѓРЅРґС‹","callback_data":"cin:%s"},{"text":"рџ“Љ Р›РёРјРёС‚ Р“Р‘","callback_data":"cgb:%s"}],[{"text":"вЏі РЎСЂРѕРє","callback_data":"cdays:%s"},{"text":"рџ—‘ РЈРґР°Р»РёС‚СЊ","callback_data":"askdel:%s"}],[{"text":"%s","callback_data":"ctgl:%s"}],[{"text":"в¬…пёЏ РљР»РёРµРЅС‚С‹","callback_data":"nav:clients"}]]' \
    "$e" "$e" "$e" "$e" "$e" "$e" "$tog" "$e"
}
ecard_render() {
  case "$E_STEP" in
    in)       printf 'рџ“Ў <b>РРЅР±Р°СѓРЅРґС‹ РєР»РёРµРЅС‚Р° %s</b>\nРћС‚РјРµС‚СЊ РЅСѓР¶РЅС‹Рµ (вњ… = Р±СѓРґРµС‚ РїСЂРёРІСЏР·Р°РЅ), Р·Р°С‚РµРј В«РЎРѕС…СЂР°РЅРёС‚СЊВ».' "$(hesc "$E_EMAIL")" ;;
    gb)       printf 'рџ“Љ <b>Р›РёРјРёС‚ С‚СЂР°С„РёРєР° %s</b>\nР’С‹Р±РµСЂРё РЅРѕРІС‹Р№ Р»РёРјРёС‚:' "$(hesc "$E_EMAIL")" ;;
    days)     printf 'вЏі <b>РЎСЂРѕРє РґРµР№СЃС‚РІРёСЏ %s</b>\nР’С‹Р±РµСЂРё РЅРѕРІС‹Р№ СЃСЂРѕРє (РѕС‚СЃС‡С‘С‚ СЃ СЃРµРіРѕРґРЅСЏ):' "$(hesc "$E_EMAIL")" ;;
    gb_txt)   printf 'рџ“Љ Р›РёРјРёС‚ %s: РїСЂРёС€Р»Рё С‡РёСЃР»Рѕ Р“Р‘ (РЅР°РїСЂРёРјРµСЂ 200).' "$(hesc "$E_EMAIL")" ;;
    days_txt) printf 'вЏі РЎСЂРѕРє %s: РїСЂРёС€Р»Рё С‡РёСЃР»Рѕ РґРЅРµР№ (РЅР°РїСЂРёРјРµСЂ 30).' "$(hesc "$E_EMAIL")" ;;
    *)        client_card_render ;;
  esac
}
ecard_kb() {
  local rows id rem port mark
  case "$E_STEP" in
    in)
      rows=""
      while IFS='|' read -r id rem port; do
        [[ ",$E_IN," == *",$id,"* ]] && mark="вњ… " || mark="вћ• "
        rows+="[$(jq -n --arg t "$mark$rem" --arg e "$E_EMAIL" --arg id "$id" '{text:$t,callback_data:("cinb:"+$e+":"+$id)}')],"
      done < <(sqlite3 -separator '|' "$XUI_DB" \
        "SELECT id,COALESCE(remark,'?'),port FROM inbounds WHERE enable=1 ORDER BY id;" 2>/dev/null)
      if [[ -z "$rows" ]]; then
        printf '[[{"text":"РќРµС‚ Р°РєС‚РёРІРЅС‹С… РёРЅР±Р°СѓРґРѕРІ","callback_data":"noop"}],[{"text":"в¬…пёЏ РћС‚РјРµРЅР°","callback_data":"cback"}]]'
      else
        printf '[%s[{"text":"рџ’ѕ РЎРѕС…СЂР°РЅРёС‚СЊ","callback_data":"cinok:%s"},{"text":"в¬…пёЏ РћС‚РјРµРЅР°","callback_data":"cback"}]]' "$rows" "$E_EMAIL"
      fi ;;
    gb)    printf '[[{"text":"в€ћ Р±РµР·Р»РёРјРёС‚","callback_data":"cgbset:%s:0"},{"text":"10 Р“Р‘","callback_data":"cgbset:%s:10"},{"text":"50 Р“Р‘","callback_data":"cgbset:%s:50"}],[{"text":"100 Р“Р‘","callback_data":"cgbset:%s:100"},{"text":"500 Р“Р‘","callback_data":"cgbset:%s:500"},{"text":"вњЏпёЏ РЎРІРѕР№ Р“Р‘","callback_data":"cgbtxt:%s"}],[{"text":"в¬…пёЏ РћС‚РјРµРЅР°","callback_data":"cback"}]]' "$E_EMAIL" "$E_EMAIL" "$E_EMAIL" "$E_EMAIL" "$E_EMAIL" "$E_EMAIL" ;;
    days)  printf '[[{"text":"в€ћ Р±РµСЃСЃСЂРѕС‡РЅРѕ","callback_data":"cdset:%s:0"},{"text":"7 РґРЅРµР№","callback_data":"cdset:%s:7"},{"text":"30 РґРЅРµР№","callback_data":"cdset:%s:30"}],[{"text":"90 РґРЅРµР№","callback_data":"cdset:%s:90"},{"text":"вњЏпёЏ РЎРІРѕР№ СЃСЂРѕРє","callback_data":"cdtxt:%s"}],[{"text":"в¬…пёЏ РћС‚РјРµРЅР°","callback_data":"cback"}]]' "$E_EMAIL" "$E_EMAIL" "$E_EMAIL" "$E_EMAIL" "$E_EMAIL" ;;
    gb_txt|days_txt) printf '[[{"text":"в¬…пёЏ РћС‚РјРµРЅР°","callback_data":"cback"}]]' ;;
    *)     kb_client_card ;;
  esac
}
show_ecard() { # $1=chat вЂ” СЌРєСЂР°РЅ РїСЂР°РІРєРё РєР»РёРµРЅС‚Р° (РѕС‚РґРµР»СЊРЅРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ E_MID)
  local chat=$1 text kb json resp
  text=$(ecard_render); kb=$(ecard_kb)
  if [[ -n "$E_MID" ]]; then
    json=$(jq -n --arg c "$chat" --arg m "$E_MID" --arg t "$text" --argjson kb "$kb" \
      '{chat_id:$c,message_id:($m|tonumber),text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
    resp=$(tgc -s --max-time 40 -X POST "$API/editMessageText" -H 'Content-Type: application/json' -d "$json")
    if jq -re '.ok == true' <<<"$resp" >/dev/null 2>&1 || grep -q "not modified" <<<"$resp"; then return 0; fi
    E_MID=""
  fi
  json=$(jq -n --arg c "$chat" --arg t "$text" --argjson kb "$kb" \
    '{chat_id:$c,text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
  resp=$(tgc -s --max-time 40 -X POST "$API/sendMessage" -H 'Content-Type: application/json' -d "$json")
  E_MID=$(jq -r '.result.message_id // empty' <<<"$resp" 2>/dev/null)
}
ecard_close() { # $1=chat вЂ” СѓР±СЂР°С‚СЊ СЌРєСЂР°РЅ РїСЂР°РІРєРё
  [[ -n "$E_MID" ]] && tg_del "$1" "$E_MID"
  E_MID=""; E_STEP=""
}
ecard_client_view() { # $1=chat вЂ” РІРµСЂРЅСѓС‚СЊСЃСЏ Рє РєР°СЂС‚РѕС‡РєРµ РєР»РёРµРЅС‚Р° РІ РіР»Р°РІРЅРѕРј РѕРєРЅРµ
  ecard_close "$1"; show_screen "$1" "client"
}

do_confirmed() { # $1=chat $2=action (fix|awg|restart-xui|restart-nginx|restart-adg|restart-xray)
  case "$2" in
    fix)           tg_send "$1" "вљЎ РђРІС‚РѕРїРѕС‡РёРЅРєР° Р·Р°РїСѓС‰РµРЅР° (РґРѕ 5 РјРёРЅ)вЂ¦"; tg_send_kb "$1" "$(run_stack stack_check_fix | tail -60)" "$KB_HIDE" >/dev/null ;;
    awg)           tg_send "$1" "рџ”Ѓ РџРµСЂРµР·Р°РїСѓСЃРє AWGвЂ¦"; tg_send_kb "$1" "$(cmd_awg_restart)" "$KB_HIDE" >/dev/null ;;
    restart-xui)   systemctl restart x-ui && sleep 2 && tg_send "$1" "x-ui: $(systemctl is-active x-ui)" ;;
    restart-nginx) systemctl restart nginx && sleep 2 && tg_send "$1" "nginx: $(systemctl is-active nginx)" ;;
    restart-adg)   systemctl restart AdGuardHome && sleep 2 && tg_send "$1" "AdGuardHome: $(systemctl is-active AdGuardHome 2>/dev/null)" ;;
    restart-xray)
      local res; res=$(api_call POST /panel/api/server/restartXrayService)
      if jq -re '.success == true' <<<"$res" >/dev/null 2>&1; then tg_send "$1" "xray: РїРµСЂРµР·Р°РїСѓС‰РµРЅ вњ“"
      else tg_send "$1" "xray: РѕС€РёР±РєР° вЂ” $(jq -r '.msg // "РЅРµС‚ РѕС‚РІРµС‚Р° РїР°РЅРµР»Рё"' <<<"$res")"; fi ;;
  esac
}

# в”Ђв”Ђ Р¶СѓСЂРЅР°Р» РѕС€РёР±РѕРє СЃРµСЂРІРёСЃРѕРІ (/err Рё РєРЅРѕРїРєРё рџ“њ РІ РѕР±СЃР»СѓР¶РёРІР°РЅРёРё) в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
err_unit() { # $1=Р°Р»РёР°СЃ (xui|nginx|adg|f2b|bot) РёР»Рё РёРјСЏ СЋРЅРёС‚Р° в†’ РёРјСЏ СЋРЅРёС‚Р°
  local pair
  for pair in xui:x-ui nginx:nginx adg:AdGuardHome f2b:fail2ban bot:tg-stack-bot; do
    [[ "${pair%%:*}" == "$1" ]] && { printf '%s' "${pair#*:}"; return 0; }
  done
  [[ "$1" =~ ^[A-Za-z0-9_.@-]+$ ]] && { printf '%s' "$1"; return 0; }
  return 1
}
err_tail() { # $1=СЋРЅРёС‚ в†’ РїРѕСЃР»РµРґРЅРёРµ РѕС€РёР±РєРё Р¶СѓСЂРЅР°Р»Р° (HTML); РЅРµС‚ РѕС€РёР±РѕРє вЂ” РїСЂРѕСЃС‚Рѕ С…РІРѕСЃС‚
  local u=$1 out
  out=$(journalctl -u "$u" -n 200 --no-pager 2>/dev/null | grep -iaE "error|fail|fatal|crit|panic" | tail -10)
  [[ -z "$out" ]] && out=$(journalctl -u "$u" -n 10 --no-pager 2>/dev/null)
  [[ -z "$out" ]] && { printf 'рџ“њ <b>%s</b>: Р¶СѓСЂРЅР°Р» РїСѓСЃС‚ РёР»Рё СЋРЅРёС‚ РЅРµ РЅР°Р№РґРµРЅ.' "$(hesc "$u")"; return 0; }
  printf 'рџ“њ <b>%s</b> вЂ” РїРѕСЃР»РµРґРЅРёРµ РѕС€РёР±РєРё:\n<pre>%s</pre>' "$(hesc "$u")" "$(hesc "$(printf '%s' "$out" | head -c 2800)")"
}

bk_set_schedule() { # $1=РїСЂРµСЃРµС‚ в†’ С‚РµРєСЃС‚ СЂРµР·СѓР»СЊС‚Р°С‚Р°
  local cal name
  case "$1" in
    hourly) cal='*-*-* *:00:00';        name='РєР°Р¶РґС‹Р№ С‡Р°СЃ' ;;
    6h)     cal='*-*-* 00,06,12,18:00:00'; name='РєР°Р¶РґС‹Рµ 6 С‡Р°СЃРѕРІ' ;;
    12h)    cal='*-*-* 00,12:00:00';    name='РєР°Р¶РґС‹Рµ 12 С‡Р°СЃРѕРІ' ;;
    daily)  cal='*-*-* 04:00:00';       name='СЂР°Р· РІ РґРµРЅСЊ РІ 04:00' ;;
    off)
      systemctl disable --now xui-db-backup.timer >/dev/null 2>&1
      printf 'вЏ№ Р Р°СЃРїРёСЃР°РЅРёРµ Р±СЌРєР°РїР° РІС‹РєР»СЋС‡РµРЅРѕ (СЂСѓС‡РЅРѕР№ вЂ” РєРЅРѕРїРєРѕР№ рџ’ѕ Р‘СЌРєР°Рї Р‘Р”).'; return 0 ;;
    *) printf 'РќРµРёР·РІРµСЃС‚РЅС‹Р№ РїСЂРµСЃРµС‚.'; return 0 ;;
  esac
  cat > /etc/systemd/system/xui-db-backup.timer <<EOF
[Unit]
Description=x-ui DB backup schedule
[Timer]
OnCalendar=$cal
Persistent=true
[Install]
WantedBy=timers.target
EOF
  systemctl daemon-reload
  systemctl enable --now xui-db-backup.timer >/dev/null 2>&1
  printf 'вњ… Р‘СЌРєР°Рї: %s (OnCalendar=%s). Р”РѕРєСѓРјРµРЅС‚ Р±СѓРґРµС‚ РїСЂРёС…РѕРґРёС‚СЊ РІ СЌС‚РѕС‚ С‡Р°С‚.' "$name" "$cal"
}

# в”Ђв”Ђ РјРѕРЅРёС‚РѕСЂРёРЅРі (Р Р°СЃРїРёСЃР°РЅРёРµ в†’ Р°Р»РµСЂС‚С‹ РїРѕ СЃРѕР±С‹С‚РёСЏРј РїР°РЅРµР»Рё) в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
MON_FILE="/root/.tg-stack-bot-mon.env"
MON_ON=1; MON_IV=300
EV_OUT=1; OUT_FAILS=3; EV_OUTUP=0      # РСЃС…РѕРґСЏС‰РёРµ в›” / в†©пёЏ (РєР°Рє РІ РїР°РЅРµР»Рё)
EV_XRAY=1                              # РЎР±РѕР№ Xray
EV_NODE=1; NODE_FAILS=1; EV_NODEUP=0   # РЈР·РµР» в›” / в†©пёЏ
EV_CPU=0; CPU_TH=90; EV_RAM=0; RAM_TH=90  # РЎРёСЃС‚РµРјР° (РІ РїР°РЅРµР»Рё РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РІС‹РєР»)
EV_LOGIN=1                             # РџРѕРїС‹С‚РєР° РІС…РѕРґР°
EV_NGINX=1; EV_ADG=1; EV_DISK=0; DISK_TH=85; EV_CERT=1; EV_BKFAIL=1  # nginx/adguard СѓРїР°Р», РґРёСЃРє, СЃРµСЂС‚С‹ в‰¤7Рґ, Р±СЌРєР°Рї СѓРїР°Р»
OUT_CNT=0; OUT_BAD=0; XRAY_BAD=0; XRAY_LAST=0
NODE_CNT=0; NODE_BAD=0; NODE_LAST=0
CPU_LAST=0; RAM_LAST=0
NGX_BAD=0; NGX_LAST=0; ADG_BAD=0; ADG_LAST=0; DISK_LAST=0; CERT_LAST=0; CERT_CHK=-3600; BKF_LAST=0
LOG_POS=0; LAST_MON=-1

mon_load() {
  [[ -r "$MON_FILE" ]] || return 0
  local k v
  while IFS='=' read -r k v; do
    [[ "$k" =~ ^[A-Z_]+$ ]] || continue
    case "$k" in
      MON_ON) MON_ON=$v ;; MON_IV) MON_IV=$v ;;
      EV_OUT) EV_OUT=$v ;; OUT_FAILS) OUT_FAILS=$v ;; EV_OUTUP) EV_OUTUP=$v ;;
      EV_XRAY) EV_XRAY=$v ;;
      EV_NODE) EV_NODE=$v ;; NODE_FAILS) NODE_FAILS=$v ;; EV_NODEUP) EV_NODEUP=$v ;;
      EV_CPU) EV_CPU=$v ;; CPU_TH) CPU_TH=$v ;; EV_RAM) EV_RAM=$v ;; RAM_TH) RAM_TH=$v ;;
      EV_LOGIN) EV_LOGIN=$v ;;
      EV_NGINX) EV_NGINX=$v ;; EV_ADG) EV_ADG=$v ;; EV_DISK) EV_DISK=$v ;; DISK_TH) DISK_TH=$v ;;
      EV_CERT) EV_CERT=$v ;; EV_BKFAIL) EV_BKFAIL=$v ;;
      OUT_CNT) OUT_CNT=$v ;; OUT_BAD) OUT_BAD=$v ;; XRAY_BAD) XRAY_BAD=$v ;; XRAY_LAST) XRAY_LAST=$v ;;
      NODE_CNT) NODE_CNT=$v ;; NODE_BAD) NODE_BAD=$v ;; NODE_LAST) NODE_LAST=$v ;;
      CPU_LAST) CPU_LAST=$v ;; RAM_LAST) RAM_LAST=$v ;;
      LOG_POS) LOG_POS=$v ;;
    esac
  done < "$MON_FILE"
}

mon_save() {
  local tmp="$MON_FILE.tmp" um
  um=$(umask); umask 077
  cat > "$tmp" <<EOF
MON_ON=$MON_ON
MON_IV=$MON_IV
EV_OUT=$EV_OUT
OUT_FAILS=$OUT_FAILS
EV_OUTUP=$EV_OUTUP
EV_XRAY=$EV_XRAY
EV_NODE=$EV_NODE
NODE_FAILS=$NODE_FAILS
EV_NODEUP=$EV_NODEUP
EV_CPU=$EV_CPU
CPU_TH=$CPU_TH
EV_RAM=$EV_RAM
RAM_TH=$RAM_TH
EV_LOGIN=$EV_LOGIN
EV_NGINX=$EV_NGINX
EV_ADG=$EV_ADG
EV_DISK=$EV_DISK
DISK_TH=$DISK_TH
EV_CERT=$EV_CERT
EV_BKFAIL=$EV_BKFAIL
NGX_BAD=$NGX_BAD
NGX_LAST=$NGX_LAST
ADG_BAD=$ADG_BAD
ADG_LAST=$ADG_LAST
DISK_LAST=$DISK_LAST
CERT_LAST=$CERT_LAST
CERT_CHK=$CERT_CHK
BKF_LAST=$BKF_LAST
OUT_CNT=$OUT_CNT
OUT_BAD=$OUT_BAD
XRAY_BAD=$XRAY_BAD
XRAY_LAST=$XRAY_LAST
NODE_CNT=$NODE_CNT
NODE_BAD=$NODE_BAD
NODE_LAST=$NODE_LAST
CPU_LAST=$CPU_LAST
RAM_LAST=$RAM_LAST
LOG_POS=$LOG_POS
EOF
  mv "$tmp" "$MON_FILE"
  umask "$um"
}

mon_alert() { # $1=text (HTML) вЂ” Р°Р»РµСЂС‚ РІ С‡Р°С‚ Р°РґРјРёРЅР° (СЃ РєРЅРѕРїРєРѕР№ В«рџ—‘ РЎРєСЂС‹С‚СЊВ») + Р»РѕРі СЂРµР·СѓР»СЊС‚Р°С‚Р° РІ Р¶СѓСЂРЅР°Р»
  [[ -n "${ADMIN_CHAT_ID:-}" ]] || return 0
  local json resp
  json=$(jq -n --arg c "$ADMIN_CHAT_ID" --arg t "$1" --argjson kb "$KB_HIDE" \
    '{chat_id:$c,text:$t,parse_mode:"HTML",reply_markup:{inline_keyboard:$kb}}')
  resp=$(tgc -s --max-time 30 -X POST "$API/sendMessage" -H 'Content-Type: application/json' -d "$json")
  bot_log "РјРѕРЅРёС‚РѕСЂРёРЅРі: ok=$(jq -r '.ok // false' <<<"${resp:-}") $(jq -r '.description // ""' <<<"${resp:-}") :: ${1:0:60}"
}

mon_tick() { # РїРµСЂРёРѕРґРёС‡РµСЃРєР°СЏ РїСЂРѕРІРµСЂРєР° (РІС‹Р·С‹РІР°РµС‚СЃСЏ РёР· РіР»Р°РІРЅРѕРіРѕ С†РёРєР»Р°)
  (( MON_ON == 1 )) || return 0
  local now=$SECONDS
  (( LAST_MON >= 0 && now - LAST_MON < MON_IV )) && return 0
  LAST_MON=$now
  mon_load   # РѕР±С‰РёР№ С„Р°Р№Р» СЃРѕСЃС‚РѕСЏРЅРёСЏ: РґСЂСѓРіРѕР№ СЌРєР·РµРјРїР»СЏСЂ РјРѕРі РїРµСЂРµРєР»СЋС‡РёС‚СЊ СЃРѕР±С‹С‚РёСЏ/РїРѕСЂРѕРі вЂ” РїРѕРґС‚СЏРіРёРІР°РµРј РґРѕ РїСЂРѕРІРµСЂРѕРє
  local st cpu_pct mem_pct xr code pct bp logf sz endd left bad cf
  bp=$(panel_base)

  # СЃС‚Р°С‚СѓСЃ РїР°РЅРµР»Рё: CPU / RAM / Xray
  st=$(api_call GET /panel/api/server/status 2>/dev/null)
  if jq -re '.success == true and (.obj != null)' <<<"${st:-}" >/dev/null 2>&1; then
    cpu_pct=$(jq -r '.obj.cpu // 0' <<<"$st")
    mem_pct=$(jq -r '((.obj.mem.current // 0) * 100 / (.obj.mem.total // 1))' <<<"$st" | cut -d. -f1)
    xr=$(jq -r '.obj.xray.state // "?"' <<<"$st")

    if (( EV_XRAY == 1 )) && [[ "$xr" != "running" ]]; then
      if (( now - XRAY_LAST >= 1800 )); then
        mon_alert "вўпёЏ <b>РЎР±РѕР№ Xray</b>: СЃРѕСЃС‚РѕСЏРЅРёРµ <code>$xr</code>"; XRAY_LAST=$now
      fi
      XRAY_BAD=1
    elif [[ "$xr" == "running" ]]; then
      XRAY_BAD=0
    fi

    pct=${cpu_pct%%.*}; [[ -z "$pct" ]] && pct=0
    if (( EV_CPU == 1 && pct >= CPU_TH && now - CPU_LAST >= 900 )); then
      mon_alert "рџ”Ґ <b>CPU</b>: ${pct}% (РїРѕСЂРѕРі ${CPU_TH}%)"; CPU_LAST=$now
    fi
    if (( EV_RAM == 1 && mem_pct >= RAM_TH && now - RAM_LAST >= 900 )); then
      mon_alert "рџ§  <b>RAM</b>: ${mem_pct}% (РїРѕСЂРѕРі ${RAM_TH}%)"; RAM_LAST=$now
    fi
  fi

  # СѓР·РµР»: nginx РѕС‚РІРµС‡Р°РµС‚ РЅР° 443
  code=$(curl -sk -m 6 -o /dev/null -w '%{http_code}' -H "Host: $(panel_domain)" "https://127.0.0.1${bp}" 2>/dev/null)
  if [[ "$code" =~ ^[1-5][0-9][0-9]$ ]]; then
    NODE_CNT=0
    if (( NODE_BAD == 1 )); then
      NODE_BAD=0
      (( EV_NODEUP == 1 )) && mon_alert "рџџў <b>РЈР·РµР» РІ СЃРµС‚Рё</b> (443 РѕС‚РІРµС‡Р°РµС‚)"
    fi
  else
    NODE_CNT=$((NODE_CNT+1))
    if (( EV_NODE == 1 && NODE_CNT >= NODE_FAILS && now - NODE_LAST >= 1800 )); then
      mon_alert "рџ–Ґ <b>РЈР·РµР» РЅРµРґРѕСЃС‚СѓРїРµРЅ</b>: РЅРµС‚ РѕС‚РІРµС‚Р° РЅР° 443 (${NODE_CNT} РїСЂРѕРІРµСЂ. РїРѕРґСЂСЏРґ)"; NODE_LAST=$now
    fi
  fi

  # РёСЃС…РѕРґСЏС‰РёРµ: РёРЅС‚РµСЂРЅРµС‚ СЃ СЃРµСЂРІРµСЂР° (С‡РµСЂРµР· TG-РІС‹С…РѕРґ, РµСЃР»Рё РѕРЅ Р·Р°РґР°РЅ вЂ” СЌС‚Рѕ Рё РµСЃС‚СЊ В«Р·Р°СЂСѓР±РµР¶РЅС‹Р№ РІС‹С…РѕРґВ»)
  code=$(curl -sk -m 6 ${TG_PROXY_CUR:+--proxy $TG_PROXY_CUR} -o /dev/null -w '%{http_code}' "https://www.google.com/generate_204" 2>/dev/null)
  if [[ "$code" == "204" ]]; then
    OUT_CNT=0
    if (( OUT_BAD == 1 )); then
      OUT_BAD=0
      (( EV_OUTUP == 1 )) && mon_alert "вњ… <b>РСЃС…РѕРґСЏС‰РёРµ СЃРЅРѕРІР° СЂР°Р±РѕС‚Р°СЋС‚</b>"
    fi
  else
    OUT_CNT=$((OUT_CNT+1))
    if (( EV_OUT == 1 && OUT_CNT >= OUT_FAILS && OUT_BAD == 0 )); then
      mon_alert "в›” <b>РСЃС…РѕРґСЏС‰РёРµ РЅРµРґРѕСЃС‚СѓРїРЅС‹</b>: ${OUT_CNT} РЅРµСѓРґР°С‡РЅС‹С… РїСЂРѕРІРµСЂРѕРє РїРѕРґСЂСЏРґ"; OUT_BAD=1
    fi
  fi

  # СЃРµСЂРІРёСЃС‹: nginx / AdGuardHome
  if (( EV_NGINX == 1 )); then
    st=$(systemctl is-active nginx 2>/dev/null)
    if [[ "$st" == "active" ]]; then
      if (( NGX_BAD == 1 )); then NGX_BAD=0; mon_alert "рџџў <b>nginx СЃРЅРѕРІР° СЂР°Р±РѕС‚Р°РµС‚</b>"; fi
    else
      NGX_BAD=1
      if (( now - NGX_LAST >= 1800 )); then
        mon_alert "рџЊђ <b>nginx РЅРµ СЂР°Р±РѕС‚Р°РµС‚</b>: СЃРѕСЃС‚РѕСЏРЅРёРµ <code>${st:-unknown}</code>"; NGX_LAST=$now
      fi
    fi
  fi
  if (( EV_ADG == 1 )) && systemctl cat AdGuardHome.service >/dev/null 2>&1; then
    st=$(systemctl is-active AdGuardHome 2>/dev/null)
    if [[ "$st" == "active" ]]; then
      if (( ADG_BAD == 1 )); then ADG_BAD=0; mon_alert "рџџў <b>AdGuardHome СЃРЅРѕРІР° СЂР°Р±РѕС‚Р°РµС‚</b>"; fi
    else
      ADG_BAD=1
      if (( now - ADG_LAST >= 1800 )); then
        mon_alert "рџ›Ў <b>AdGuardHome РЅРµ СЂР°Р±РѕС‚Р°РµС‚</b>: СЃРѕСЃС‚РѕСЏРЅРёРµ <code>${st:-unknown}</code>"; ADG_LAST=$now
      fi
    fi
  fi

  # РґРёСЃРє: Р·Р°РЅСЏС‚Рѕ в‰Ґ DISK_TH% (Р°Р»РµСЂС‚ РЅРµ С‡Р°С‰Рµ СЂР°Р·Р° РІ 6С‡)
  if (( EV_DISK == 1 )); then
    pct=$(df -P / | awk 'NR==2{gsub("%","",$5);print $5+0}')
    if (( pct >= DISK_TH && now - DISK_LAST >= 21600 )); then
      mon_alert "рџ’Ѕ <b>Р”РёСЃРє</b>: Р·Р°РЅСЏС‚Рѕ ${pct}% (РїРѕСЂРѕРі ${DISK_TH}%)"; DISK_LAST=$now
    fi
  fi

  # СЃРµСЂС‚С‹: certificateFile РёР· TLS-РёРЅР±Р°СѓРЅРґРѕРІ (РїСЂРѕРІРµСЂРєР° СЂР°Р· РІ С‡Р°СЃ, Р°Р»РµСЂС‚ СЂР°Р· РІ 12С‡)
  if (( EV_CERT == 1 && now - CERT_CHK >= 3600 )); then
    CERT_CHK=$now
    bad=""
    while IFS= read -r cf; do
      [[ -r "$cf" ]] || continue
      endd=$(openssl x509 -in "$cf" -noout -enddate 2>/dev/null | cut -d= -f2)
      [[ -z "$endd" ]] && continue
      left=$(( ( $(date -d "$endd" +%s 2>/dev/null || printf '0') - $(date +%s) ) / 86400 ))
      if (( left <= 7 )); then bad+="вЂў $(basename "$(dirname "$cf")"): РѕСЃС‚Р°Р»РѕСЃСЊ ${left} РґРЅ"$'\n'; fi
    done < <(sqlite3 "$XUI_DB" "SELECT stream_settings FROM inbounds;" 2>/dev/null \
      | jq -r '.tlsSettings.certificates[]?.certificateFile // empty' 2>/dev/null | sort -u)
    if [[ -n "$bad" ]] && (( now - CERT_LAST >= 43200 )); then
      mon_alert "рџ”ђ <b>РЎРµСЂС‚С‹ РёСЃС‚РµРєР°СЋС‚ (в‰¤7 РґРЅ)</b>:
${bad}РџРµСЂРµРІС‹РїСѓСЃС‚Рё С‡РµСЂРµР· stack-manager вЂє СЃРµСЂС‚С‹."
      CERT_LAST=$now
    fi
  fi

  # Р±СЌРєР°Рї Р‘Р” СѓРїР°Р» (Р°Р»РµСЂС‚ РЅРµ С‡Р°С‰Рµ СЂР°Р·Р° РІ 6С‡, РїРѕРєР° РЅРµ РїРѕС‡РёРЅСЏС‚)
  if (( EV_BKFAIL == 1 )); then
    st=$(systemctl is-failed xui-db-backup.service 2>/dev/null)
    if [[ "$st" == "failed" ]] && (( now - BKF_LAST >= 21600 )); then
      mon_alert "рџ’ѕ <b>Р‘СЌРєР°Рї Р‘Р” СѓРїР°Р»</b> вЂ” РґРµС‚Р°Р»Рё: journalctl -u xui-db-backup"; BKF_LAST=$now
    fi
  fi
  mon_save
}

mon_login_check() { # РІС…РѕРґС‹ РІ РїР°РЅРµР»СЊ: РёСЃС‚РѕС‡РЅРёРє РёСЃС‚РёРЅС‹ вЂ” Р¶СѓСЂРЅР°Р» x-ui (200 РїР°РЅРµР»СЊ С€Р»С‘С‚ Рё РЅР° РЅРµРІРµСЂРЅС‹Р№ РїР°СЂРѕР»СЊ!),
  # С„РѕР»Р±СЌРє РґР»СЏ СЃС‚Р°СЂС‹С… РїР°РЅРµР»РµР№ Р±РµР· СЌС‚РёС… СЃС‚СЂРѕРє вЂ” access.bot_log (РєР°Рє СЂР°РЅСЊС€Рµ)
  (( MON_ON == 1 )) || return 0
  local cf="/root/.tg-stack-bot-login.cursor" out line res un ip rsn extra jrc
  if [[ ! -s "$cf" ]]; then
    # РёРЅРёС†РёР°Р»РёР·Р°С†РёСЏ: Р·Р°РїРѕРјРёРЅР°РµРј В«С‚РµРєСѓС‰СѓСЋ РїРѕР·РёС†РёСЋВ», СЃС‚Р°СЂСѓСЋ РёСЃС‚РѕСЂРёСЋ РЅРµ Р°Р»РµСЂС‚РёРј
    journalctl -q -u x-ui -n 1 --cursor-file="$cf" >/dev/null 2>&1
    return 0
  fi
  out=$(journalctl -q -u x-ui -o cat --cursor-file="$cf" 2>/dev/null); jrc=$?
  if (( jrc == 0 )); then
    out=$(grep -aE 'logged in successfully: username=|failed login: username=' <<<"$out" || true)
    [[ -n "$out" ]] || return 0
    while IFS= read -r line; do
      [[ -z "$line" ]] && continue
      if [[ "$line" == *"logged in successfully"* ]]; then res="вњ… СѓСЃРїРµС…"; else res="вќЊ РЅРµСѓРґР°С‡Р°"; fi
      un=$(sed -nE 's/.*username="([^"]*)".*/\1/p' <<<"$line")
      ip=$(sed -nE 's/.*IP="([^"]*)".*/\1/p' <<<"$line")
      extra=""
      [[ -n "$un" ]] && extra+=" В· ${un}"
      [[ -n "$ip" && "$ip" != "127.0.0.1" ]] && extra+=" В· IP ${ip}"
      if [[ "$res" == "вќЊ РЅРµСѓРґР°С‡Р°" ]]; then
        rsn=$(sed -nE 's/.*reason="([^"]*)".*/\1/p' <<<"$line")
        [[ -z "$rsn" ]] && rsn="РЅРµРІРµСЂРЅС‹Р№ Р»РѕРіРёРЅ РёР»Рё РїР°СЂРѕР»СЊ"
        extra+=" В· ${rsn}"
      fi
      mon_alert "рџ”‘ <b>Р’С…РѕРґ РІ РїР°РЅРµР»СЊ</b>: ${res}${extra}"
    done <<<"$out"
    return 0
  fi
  local bp logf="/var/bot_log/nginx/access.bot_log" sz
  bp=$(panel_base)
  sz=$(stat -c %s "$logf" 2>/dev/null || printf 0)
  if (( LOG_POS == 0 )); then
    LOG_POS=$sz
  elif (( sz < LOG_POS )); then
    LOG_POS=0
  elif (( sz > LOG_POS )); then
    local newl="" n=0 lastline="" codeL ip res extra
    newl=$(tail -c +"$((LOG_POS+1))" "$logf" 2>/dev/null | grep -F "POST ${bp}login " || true)
    LOG_POS=$sz
    if [[ -n "$newl" && "$EV_LOGIN" == "1" ]]; then
      while IFS= read -r lastline; do
        [[ -n "$lastline" ]] && n=$((n+1))
      done <<<"$newl"
      lastline=$(tail -1 <<<"$newl")
      codeL=$(awk '{print $9}' <<<"$lastline")
      ip=$(awk '{print $1}' <<<"$lastline")
      res="РЅРµСѓРґР°С‡Р° (${codeL:-?})"; [[ "$codeL" == "200" ]] && res="СѓСЃРїРµС…"
      extra=""
      [[ "$ip" != "127.0.0.1" && -n "$ip" ]] && extra=" В· IP ${ip}"
      (( n > 1 )) && extra+=" В· РІСЃРµРіРѕ РїРѕРїС‹С‚РѕРє: ${n}"
      mon_alert "рџ”‘ <b>Р’С…РѕРґ РІ РїР°РЅРµР»СЊ</b>: ${res}${extra}"
    fi
  fi
  mon_save
}

# в”Ђв”Ђ TG-РІС‹С…РѕРґ Р±РѕС‚Р°: С‚РѕР»СЊРєРѕ Р§РўР•РќРР• state (РІРµРґС‘С‚ stack-manager.sh, Рї.7 в†’ TG-Р±РѕС‚) в”Ђ
out_load() {
  [[ -f "$OUT_FILE" ]] || return 0
  TG_OUT_MODE=$(grep -a '^TG_OUT_MODE=' "$OUT_FILE" | tail -1 | cut -d= -f2-)
  TG_OUT_TAG=$(grep -a '^TG_OUT_TAG=' "$OUT_FILE" | tail -1 | cut -d= -f2-)
  TG_OUT_PORT=$(grep -a '^TG_OUT_PORT=' "$OUT_FILE" | tail -1 | cut -d= -f2-)
  TG_SOCKS_B64=$(grep -a '^TG_SOCKS_B64=' "$OUT_FILE" | tail -1 | cut -d= -f2-)
  TG_OURS=$(grep -a '^TG_OURS=' "$OUT_FILE" | tail -1 | cut -d= -f2-)
  [[ "$TG_OUT_MODE" =~ ^(direct|socks|outbound)$ ]] || TG_OUT_MODE="direct"
  [[ "$TG_OURS" =~ ^[01]$ ]] || TG_OURS=0
}
tgout_cur_recalc() {
  case "$TG_OUT_MODE" in
    outbound) [[ -n "$TG_OUT_PORT" ]] && TG_PROXY_CUR="socks5h://127.0.0.1:${TG_OUT_PORT}" || TG_PROXY_CUR="" ;;
    socks)    TG_PROXY_CUR=$(printf '%s' "$TG_SOCKS_B64" | base64 -d 2>/dev/null) ;;
    *)        TG_PROXY_CUR="$TG_PROXY" ;;
  esac
}
out_check_reload() { # РїСЂР°РІРєРё РёР· SSH-СЃРєСЂРёРїС‚Р° РїРѕРґС…РІР°С‚С‹РІР°СЋС‚СЃСЏ РЅР° Р»РµС‚Сѓ (РїРѕ mtime state-С„Р°Р№Р»Р°)
  local m; m=$(stat -c %Y "$OUT_FILE" 2>/dev/null || printf '0')
  [[ "$m" == "$OUT_MTIME" ]] && return 0
  OUT_MTIME="$m"
  local prev="$TG_OUT_MODE/$TG_OUT_TAG/$TG_OUT_PORT"
  out_load; tgout_cur_recalc
  [[ "$prev" != "$TG_OUT_MODE/$TG_OUT_TAG/$TG_OUT_PORT" ]] && bot_log "tg-РІС‹С…РѕРґ РёР·РјРµРЅС‘РЅ stack-manager.sh в†’ $TG_OUT_MODE ${TG_OUT_TAG:+($TG_OUT_TAG)}${TG_OUT_PORT:+ :$TG_OUT_PORT}"
}

# в”Ђв”Ђ РґРёСЃРїРµС‚С‡РµСЂ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
dispatch() { # $1=chat $2=text $3=callback_data $4=cb_id $5=cb_message_id
  local chat="$1" text="$2" cbdata="$3" cbid="$4" cbmid="$5"
  if [[ -n "$cbdata" ]]; then
    tg_answer_cb "$cbid"
    [[ "$chat" != "$ADMIN_CHAT_ID" ]] && return 0
    bot_log "DEBUG: cb=$cbdata (step=$NEW_STEP in=$NEW_IN gb=$NEW_GB days=$NEW_DAYS email=$NEW_EMAIL)"
    case "$cbdata" in
      nav:*) show_screen "$chat" "${cbdata#nav:}" ;;
      clpage:*)
        local p="${cbdata#clpage:}"
        if [[ "$p" =~ ^[0-9]+$ ]]; then CL_PAGE=$((10#$p)); show_screen "$chat" "clients"; fi ;;
      err:*)
        local eu; eu=$(err_unit "${cbdata#err:}") || eu=""
        if [[ -z "$eu" ]]; then tg_send "$chat" "РќРµ Р·РЅР°СЋ С‚Р°РєРѕР№ СЃРµСЂРІРёСЃ. Р”РѕСЃС‚СѓРїРЅС‹: xui, nginx, adg, f2b, bot."
        else tg_send_kb "$chat" "$(err_tail "$eu")" "$KB_HIDE" >/dev/null; fi ;;
      hide)
        tg_del "$chat" "$cbmid"
        [[ "$cbmid" == "$WINDOW_MID" ]] && WINDOW_MID=""
        if [[ "$cbmid" == "$WIZ_MID" ]]; then WIZ_MID=""; wiz_save; fi
        if [[ "$cbmid" == "$E_MID" ]]; then E_MID=""; E_STEP=""; fi
        rm -f "$CARD_FLAG" ;;
      refresh) show_screen "$chat" "$CUR_MENU" ;;
      auto)
        if [[ -f "$CARD_FLAG" ]]; then rm -f "$CARD_FLAG"; tg_send "$chat" "вЏ№ РђРІС‚РѕРѕР±РЅРѕРІР»РµРЅРёРµ РѕСЃС‚Р°РЅРѕРІР»РµРЅРѕ."
        else printf '%s server' "$WINDOW_MID" > "$CARD_FLAG"; start_autoloop; tg_send "$chat" "в–¶пёЏ РђРІС‚РѕРѕР±РЅРѕРІР»РµРЅРёРµ 10СЃ РІРєР»СЋС‡РµРЅРѕ."; fi ;;
      client:*) send_client_pack "$chat" "${cbdata#client:}" ;;
      copen:*)
        local n="${cbdata#copen:}" em
        [[ "$n" =~ ^[0-9]+$ ]] || return 0
        em=$(sqlite3 "$XUI_DB" "SELECT COALESCE(email,'') FROM clients ORDER BY id LIMIT 1 OFFSET $(( n - 1 ));" 2>/dev/null)
        # Р±РµР· em_ok: РёРјРµРЅР° РєР»РёРµРЅС‚РѕРІ Р±С‹РІР°СЋС‚ РєРёСЂРёР»Р»РёС†РµР№/СЃ "+", РІР°Р¶РµРЅ С„Р°РєС‚ СЃСѓС‰РµСЃС‚РІРѕРІР°РЅРёСЏ РІ Р‘Р”
        if [[ -n "$em" ]] && client_exists "$em"; then
          E_EMAIL="$em"; ecard_close "$chat"; show_screen "$chat" "client"
        else
          tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ (РІ Р‘Р” РЅРµС‚ СЃС‚СЂРѕРєРё СЃ СЌС‚РёРј РЅРѕРјРµСЂРѕРј)."
        fi ;;
      csub:*)
        local e="${cbdata#csub:}" url
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        if url=$(sub_url_for "$e"); then
          tg_send_kb "$chat" "рџ”— ${e}"$'\n'"$url" "$KB_HIDE" >/dev/null
        else
          tg_send "$chat" "РЈ РєР»РёРµРЅС‚Р° ${e} РЅРµС‚ sub_id."
        fi ;;
      cqr:*)
        local e="${cbdata#cqr:}" url
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        if url=$(sub_url_for "$e"); then
          send_qr_msg "$chat" "$url"
        else
          tg_send "$chat" "РЈ РєР»РёРµРЅС‚Р° ${e} РЅРµС‚ sub_id."
        fi ;;
      cin:*)
        local e="${cbdata#cin:}"
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        E_EMAIL="$e"; NEW_STEP=""; E_STEP="in"; E_IN=$(client_in_csv "$e"); show_ecard "$chat" ;;
      cinb:*)
        local rest="${cbdata#cinb:}" e id
        e="${rest%:*}"; id="${rest##*:}"
        [[ "$id" =~ ^[0-9]+$ && "$e" == "$E_EMAIL" ]] || return 0
        if [[ ",$E_IN," == *",$id,"* ]]; then
          E_IN=$(printf '%s' "$E_IN" | tr ',' '\n' | grep -vx "$id" | paste -sd, -)
        else
          E_IN=$(printf '%s\n%s' "$E_IN" "$id" | sed '/^$/d' | paste -sd, -)
        fi
        E_STEP="in"; show_ecard "$chat" ;;
      cinok:*)
        local e="${cbdata#cinok:}" cur add rem r err=""
        client_exists "$e" || return 0
        if [[ "$e" != "$E_EMAIL" ]]; then tg_send "$chat" "вљ пёЏ РЎРµСЃСЃРёСЏ СѓСЃС‚Р°СЂРµР»Р° вЂ” РѕС‚РєСЂРѕР№ РєР»РёРµРЅС‚Р° Р·Р°РЅРѕРІРѕ."; return 0; fi
        cur=$(client_in_csv "$e")
        add=$(csv_diff "$E_IN" "$cur"); rem=$(csv_diff "$cur" "$E_IN")
        [[ -n "$rem" ]] && { r=$(api_client_ids "$e" detach "$rem"); [[ "$r" == "OK" ]] || err="detach: $r"; }
        [[ -z "$err" && -n "$add" ]] && { r=$(api_client_ids "$e" attach "$add"); [[ "$r" == "OK" ]] || err="attach: $r"; }
        if [[ -z "$err" ]]; then
          ecard_client_view "$chat"
        else
          ecard_close "$chat"; tg_send "$chat" "вќЊ $err"; show_screen "$chat" "client"
        fi ;;
      cgb:*)
        local e="${cbdata#cgb:}"
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        E_EMAIL="$e"; NEW_STEP=""; E_STEP="gb"; show_ecard "$chat" ;;
      cgbset:*)
        local rest="${cbdata#cgbset:}" e gb ch r
        e="${rest%:*}"; gb="${rest##*:}"
        [[ "$gb" =~ ^[0-9]{1,6}$ && "$e" == "$E_EMAIL" ]] || { tg_send "$chat" "вљ пёЏ РЎРµСЃСЃРёСЏ СѓСЃС‚Р°СЂРµР»Р° вЂ” РѕС‚РєСЂРѕР№ РєР»РёРµРЅС‚Р° Р·Р°РЅРѕРІРѕ."; return 0; }
        ch=$(jq -nc --argjson gb "$(( gb * 1024 * 1024 * 1024 ))" '{totalGB:$gb}')
        r=$(api_client_update "$e" "$ch")
        ecard_client_view "$chat"
        [[ "$r" == "OK" ]] || tg_send "$chat" "вќЊ $r" ;;
      cgbtxt:*)
        local e="${cbdata#cgbtxt:}"
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        E_EMAIL="$e"; NEW_STEP=""; E_STEP="gb_txt"; show_ecard "$chat" ;;
      cdays:*)
        local e="${cbdata#cdays:}"
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        E_EMAIL="$e"; NEW_STEP=""; E_STEP="days"; show_ecard "$chat" ;;
      cdset:*)
        local rest="${cbdata#cdset:}" e d ms ch r
        e="${rest%:*}"; d="${rest##*:}"
        [[ "$d" =~ ^[0-9]{1,5}$ && "$e" == "$E_EMAIL" ]] || { tg_send "$chat" "вљ пёЏ РЎРµСЃСЃРёСЏ СѓСЃС‚Р°СЂРµР»Р° вЂ” РѕС‚РєСЂРѕР№ РєР»РёРµРЅС‚Р° Р·Р°РЅРѕРІРѕ."; return 0; }
        ms=0; (( d > 0 )) && ms=$(( ($(date +%s) + d * 86400) * 1000 ))
        ch=$(jq -nc --argjson ms "$ms" '{expiryTime:$ms}')
        r=$(api_client_update "$e" "$ch")
        ecard_client_view "$chat"
        [[ "$r" == "OK" ]] || tg_send "$chat" "вќЊ $r" ;;
      cdtxt:*)
        local e="${cbdata#cdtxt:}"
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        E_EMAIL="$e"; NEW_STEP=""; E_STEP="days_txt"; show_ecard "$chat" ;;
      askdel:*)
        local e="${cbdata#askdel:}"
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        PENDING="cdel:$e"; PENDING_TS=$SECONDS
        tg_confirm "cdel:$e" "$chat" "РЈРґР°Р»РёС‚СЊ РєР»РёРµРЅС‚Р° ${e}? РџРѕРґРїРёСЃРєР° Рё QR РїРµСЂРµСЃС‚Р°РЅСѓС‚ СЂР°Р±РѕС‚Р°С‚СЊ." ;;
      ctgl:*)
        local e="${cbdata#ctgl:}" en r
        if ! client_exists "$e"; then tg_send "$chat" "РљР»РёРµРЅС‚ РЅРµ РЅР°Р№РґРµРЅ."; return 0; fi
        en=$(sqlite3 "$XUI_DB" "SELECT COALESCE(enable,0) FROM clients WHERE email='$e';" 2>/dev/null); en=${en:-0}
        if [[ "$en" == "1" ]]; then
          r=$(api_client_update "$e" '{"enable":false}')
        else
          r=$(api_client_update "$e" '{"enable":true}')
        fi
        show_screen "$chat" "client"
        [[ "$r" == "OK" ]] || tg_send "$chat" "вќЊ $r" ;;
      cback) ecard_client_view "$chat" ;;
      subsall)  tg_send_kb "$chat" "$(cmd_subs)" "$KB_HIDE" >/dev/null ;;
      doaudit)  tg_send_kb "$chat" "$(run_check)" "$KB_HIDE" >/dev/null ;;
      doinb)    tg_send_kb "$chat" "$(cmd_inbounds)" "$KB_HIDE" >/dev/null ;;
      askfix)   PENDING="fix"; PENDING_TS=$SECONDS; tg_confirm "fix" "$chat" "Р—Р°РїСѓСЃС‚РёС‚СЊ Р°РІС‚РѕРїРѕС‡РёРЅРєСѓ (вљЎ РїСЂРѕРІРµСЂРєР° Рё РїРѕС‡РёРЅРєР°)?" ;;
      askawg)   PENDING="awg"; PENDING_TS=$SECONDS; tg_confirm "awg" "$chat" "РџРµСЂРµР·Р°РїСѓСЃС‚РёС‚СЊ AWG-РёРЅС‚РµСЂС„РµР№СЃС‹ (РєР»РёРµРЅС‚С‹ РїРµСЂРµРїРѕРґРєР»СЋС‡Р°С‚СЃСЏ)?" ;;
      askbackup) PENDING="backup"; PENDING_TS=$SECONDS; tg_confirm "backup" "$chat" "РЎРґРµР»Р°С‚СЊ Р±СЌРєР°Рї x-ui.db Рё РїСЂРёСЃР»Р°С‚СЊ СЃСЋРґР° РґРѕРєСѓРјРµРЅС‚РѕРј?" ;;
      bkset:*)   tg_send "$chat" "$(bk_set_schedule "${cbdata#bkset:}")"; show_screen "$chat" "bksched" ;;
      mon:sw)    MON_ON=$(( 1 - MON_ON )); mon_save; show_screen "$chat" "bksched" ;;
      moniv:*)   MON_IV="${cbdata#moniv:}"; mon_save; show_screen "$chat" "bksched" ;;
      mon:*)
        local mk="${cbdata#mon:}"
        case "$mk" in
          out)    EV_OUT=$(( 1 - EV_OUT )); OUT_CNT=0; OUT_BAD=0 ;;
          outup)  EV_OUTUP=$(( 1 - EV_OUTUP )) ;;
          xray)   EV_XRAY=$(( 1 - EV_XRAY )) ;;
          node)   EV_NODE=$(( 1 - EV_NODE )); NODE_CNT=0; NODE_BAD=0 ;;
          nodeup) EV_NODEUP=$(( 1 - EV_NODEUP )) ;;
          login)  EV_LOGIN=$(( 1 - EV_LOGIN )) ;;
          cpu)    if (( EV_CPU == 0 )); then EV_CPU=1; CPU_TH=90
                  elif (( CPU_TH == 90 )); then CPU_TH=95
                  elif (( CPU_TH == 95 )); then CPU_TH=85
                  else EV_CPU=0; CPU_TH=90; fi ;;
          ram)    if (( EV_RAM == 0 )); then EV_RAM=1; RAM_TH=90
                  elif (( RAM_TH == 90 )); then RAM_TH=95
                  elif (( RAM_TH == 95 )); then RAM_TH=85
                  else EV_RAM=0; RAM_TH=90; fi ;;
          nginx)  EV_NGINX=$(( 1 - EV_NGINX )) ;;
          adg)    EV_ADG=$(( 1 - EV_ADG )) ;;
          disk)   if (( EV_DISK == 0 )); then EV_DISK=1; DISK_TH=85
                  elif (( DISK_TH == 85 )); then DISK_TH=90
                  elif (( DISK_TH == 90 )); then DISK_TH=95
                  else EV_DISK=0; DISK_TH=85; fi ;;
          cert)   EV_CERT=$(( 1 - EV_CERT )) ;;
          bkfail) EV_BKFAIL=$(( 1 - EV_BKFAIL )) ;;
        esac
        mon_save; show_screen "$chat" "bksched" ;;
      new:start)
        ecard_close "$chat"; E_EMAIL=""
        wiz_reset; NEW_STEP="wait_in"
        NEW_SUBID=$(tr -dc a-f0-9 </dev/urandom 2>/dev/null | head -c 16)
        show_wizard "$chat" ;;
      new:in:*)
        local iid="${cbdata#new:in:}"
        [[ "$iid" =~ ^[0-9]+$ ]] || return 0
        if sqlite3 "$XUI_DB" "SELECT 1 FROM inbounds WHERE id=$iid AND enable=1;" 2>/dev/null | grep -q 1; then
          if [[ ",$NEW_IN," == *",$iid,"* ]]; then
            NEW_IN=$(printf '%s' "$NEW_IN" | tr ',' '\n' | grep -vx "$iid" | paste -sd, -)
          else
            NEW_IN=$(printf '%s\n%s' "$NEW_IN" "$iid" | sed '/^$/d' | paste -sd, -)
          fi
          NEW_STEP="wait_in"; show_wizard "$chat"
        else
          tg_send "$chat" "вљ пёЏ РРЅР±Р°СѓРЅРґ #$iid РЅРµРґРѕСЃС‚СѓРїРµРЅ (РІС‹РєР»СЋС‡РµРЅ РёР»Рё СѓРґР°Р»С‘РЅ) вЂ” РІС‹Р±РµСЂРё Р·Р°РЅРѕРІРѕ."
          NEW_STEP="wait_in"; show_wizard "$chat"
        fi ;;
      new:indone) NEW_STEP="gb"; show_wizard "$chat" ;;
      new:gb:*)  NEW_GB="${cbdata#new:gb:}"; NEW_STEP="days"; show_wizard "$chat" ;;
      new:gbtxt) NEW_STEP="gb_txt"; show_wizard "$chat" ;;
      new:days:*) NEW_DAYS="${cbdata#new:days:}"; NEW_STEP="email"; show_wizard "$chat" ;;
      new:daystxt) NEW_STEP="days_txt"; show_wizard "$chat" ;;
      new:backgb)  NEW_STEP="wait_in"; show_wizard "$chat" ;;
      new:backdays) NEW_STEP="gb"; show_wizard "$chat" ;;
      new:emauto) NEW_EMAIL="tg-$(tr -dc a-z0-9 </dev/urandom 2>/dev/null | head -c 5)"; NEW_STEP="confirm"; show_wizard "$chat" ;;
      new:emtxt)  NEW_STEP="email_txt"; show_wizard "$chat" ;;
      new:go)
        local res em sub
        if [[ -z "$NEW_IN" || -z "$NEW_EMAIL" || -z "$NEW_SUBID" ]]; then
          # СЃРµСЃСЃРёСЏ РјР°СЃС‚РµСЂР° РїРѕС‚РµСЂСЏРЅР° (СЂРµСЃС‚Р°СЂС‚ Р±РѕС‚Р° / СЃС‚Р°СЂР°СЏ РєР°СЂС‚РѕС‡РєР°) вЂ” РЅР°С‡Р°С‚СЊ Р·Р°РЅРѕРІРѕ
          wiz_reset; WIZ_MID=""; NEW_STEP="wait_in"
          NEW_SUBID=$(tr -dc a-f0-9 </dev/urandom 2>/dev/null | head -c 16)
          show_wizard "$chat"
          tg_send "$chat" "вљ пёЏ РЎРµСЃСЃРёСЏ РјР°СЃС‚РµСЂР° СѓСЃС‚Р°СЂРµР»Р° (Р±РѕС‚ РїРµСЂРµР·Р°РїСѓСЃРєР°Р»СЃСЏ). РџСЂРѕР№РґРё С€Р°РіРё Р·Р°РЅРѕРІРѕ вЂ” РєР°СЂС‚РѕС‡РєР° РІС‹С€Рµ."
        else
          res=$(api_create_client)
          em="$NEW_EMAIL"; sub="$NEW_SUBID"
          NEW_STEP="done"
          if [[ "$res" == "OK" ]]; then
            wiz_done "$chat" "вњ… РљР»РёРµРЅС‚ <b>$(hesc "$em")</b> СЃРѕР·РґР°РЅ. РџРѕРґРїРёСЃРєР° Рё QR РЅРёР¶Рµ."
            new_client_send_links "$chat" "$em" "$sub"
          else
            wiz_done "$chat" "вќЊ РћС€РёР±РєР° СЃРѕР·РґР°РЅРёСЏ: $(hesc "$res")"
          fi
          wiz_reset
        fi ;;
      new:close) local wzm=$WIZ_MID; wiz_reset; NEW_STEP=""; [[ -n "$wzm" ]] && tg_del "$chat" "$wzm"; tg_send "$chat" "РњР°СЃС‚РµСЂ Р·Р°РєСЂС‹С‚." ;;
      new:abort) local wzm=$WIZ_MID; wiz_reset; [[ -n "$wzm" ]] && tg_del "$chat" "$wzm" ;;
      askrestart:*)
        local svc="${cbdata#askrestart:}"
        case "$svc" in
          x-ui)  PENDING="restart-xui" ;;
          nginx) PENDING="restart-nginx" ;;
          xray)  PENDING="restart-xray" ;;
          AdGuardHome) PENDING="restart-adg" ;;
        esac
        PENDING_TS=$SECONDS; tg_confirm "$PENDING" "$chat" "Р РµСЃС‚Р°СЂС‚ $svc?" ;;
      cancel) PENDING=""; tg_send "$chat" "РћС‚РјРµРЅРµРЅРѕ." ;;
      confirm:*)
        if [[ "$PENDING" == "cdel:"* && "$cbdata" == "confirm:$PENDING" && $(( SECONDS - PENDING_TS )) -le 300 ]]; then
          local de="${PENDING#cdel:}"; PENDING=""
          local dr; dr=$(api_client_del "$de")
          ecard_close "$chat"
          [[ "$E_EMAIL" == "$de" ]] && E_EMAIL=""
          if [[ "$dr" == "OK" ]]; then
            tg_send "$chat" "рџ—‘ РљР»РёРµРЅС‚ ${de} СѓРґР°Р»С‘РЅ."
            show_screen "$chat" "clients"
          else
            tg_send "$chat" "вќЊ $dr"
            show_screen "$chat" "client"
          fi
        elif [[ "$PENDING" =~ ^(fix|awg|restart-xui|restart-nginx|restart-adg|restart-xray|backup)$ && "$cbdata" == "confirm:$PENDING" && $(( SECONDS - PENDING_TS )) -le 300 ]]; then
          local act="$PENDING"; PENDING=""
          if [[ "$act" == "backup" ]]; then
            tg_send "$chat" "рџ’ѕ Р“РѕС‚РѕРІР»СЋ Р±СЌРєР°РївЂ¦"
            tg_send "$chat" "$(timeout 180 /usr/local/sbin/xui-db-backup.sh 2>&1 | tail -5)"
          else
            do_confirmed "$chat" "$act"
          fi
        fi ;;
    esac
    return 0
  fi
  [[ "$chat" != "$ADMIN_CHAT_ID" ]] && return 0   # С‡СѓР¶РёРµ вЂ” РјРѕР»С‡Р°

  # С‚РµРєСЃС‚РѕРІС‹Рµ С€Р°РіРё РїСЂР°РІРєРё РєР»РёРµРЅС‚Р° (Р»РёРјРёС‚ Р“Р‘ / СЃСЂРѕРє)
  if [[ "$E_STEP" == "gb_txt" ]]; then
    if [[ -z "$E_EMAIL" ]] || ! client_exists "$E_EMAIL"; then
      E_STEP=""; tg_send "$chat" "вљ пёЏ РЎРµСЃСЃРёСЏ СѓСЃС‚Р°СЂРµР»Р° вЂ” РѕС‚РєСЂРѕР№ РєР»РёРµРЅС‚Р° Р·Р°РЅРѕРІРѕ."
    elif [[ "$text" =~ ^[0-9]{1,6}$ ]]; then
      local egb r
      egb=$(jq -nc --argjson gb "$(( 10#$text * 1024 * 1024 * 1024 ))" '{totalGB:$gb}')
      r=$(api_client_update "$E_EMAIL" "$egb")
      if [[ "$r" == "OK" ]]; then ecard_client_view "$chat"; else E_STEP=""; tg_send "$chat" "вќЊ $r"; fi
    else
      tg_send "$chat" "РџСЂРёС€Р»Рё С†РµР»РѕРµ С‡РёСЃР»Рѕ Р“Р‘ (РЅР°РїСЂРёРјРµСЂ 200)."
    fi
    return 0
  fi
  if [[ "$E_STEP" == "days_txt" ]]; then
    if [[ -z "$E_EMAIL" ]] || ! client_exists "$E_EMAIL"; then
      E_STEP=""; tg_send "$chat" "вљ пёЏ РЎРµСЃСЃРёСЏ СѓСЃС‚Р°СЂРµР»Р° вЂ” РѕС‚РєСЂРѕР№ РєР»РёРµРЅС‚Р° Р·Р°РЅРѕРІРѕ."
    elif [[ "$text" =~ ^[0-9]{1,5}$ ]]; then
      local ems ed r
      ems=$(( ($(date +%s) + 10#$text * 86400) * 1000 ))
      ed=$(jq -nc --argjson ms "$ems" '{expiryTime:$ms}')
      r=$(api_client_update "$E_EMAIL" "$ed")
      if [[ "$r" == "OK" ]]; then ecard_client_view "$chat"; else E_STEP=""; tg_send "$chat" "вќЊ $r"; fi
    else
      tg_send "$chat" "РџСЂРёС€Р»Рё С†РµР»РѕРµ С‡РёСЃР»Рѕ РґРЅРµР№ (РЅР°РїСЂРёРјРµСЂ 30)."
    fi
    return 0
  fi

  # С‚РµРєСЃС‚РѕРІС‹Рµ С€Р°РіРё РјР°СЃС‚РµСЂР°
  if [[ "$NEW_STEP" == "gb_txt" ]]; then
    if [[ "$text" =~ ^[0-9]{1,5}$ ]]; then NEW_GB=$((10#$text)); NEW_STEP="days"; show_wizard "$chat"
    else tg_send "$chat" "РџСЂРёС€Р»Рё С†РµР»РѕРµ С‡РёСЃР»Рѕ Р“Р‘ (РЅР°РїСЂРёРјРµСЂ 200)."; fi
    return 0
  fi
  if [[ "$NEW_STEP" == "days_txt" ]]; then
    if [[ "$text" =~ ^[0-9]{1,4}$ ]]; then NEW_DAYS=$((10#$text)); NEW_STEP="email"; show_wizard "$chat"
    else tg_send "$chat" "РџСЂРёС€Р»Рё С†РµР»РѕРµ С‡РёСЃР»Рѕ РґРЅРµР№ (РЅР°РїСЂРёРјРµСЂ 30)."; fi
    return 0
  fi
  if [[ "$NEW_STEP" == "email_txt" ]]; then
    local em
    em=$(printf '%s' "$text" | tr -cd 'A-Za-z0-9_.-' | cut -c1-30)
    if [[ ${#em} -ge 3 ]]; then NEW_EMAIL="$em"; NEW_STEP="confirm"; show_wizard "$chat"
    else tg_send "$chat" "РРјСЏ: 3-30 СЃРёРјРІРѕР»РѕРІ, Р»Р°С‚РёРЅРёС†Р°/С†РёС„СЂС‹/._-"; fi
    return 0
  fi

  case "$text" in
    /start|/help|/menu)
      # Р·Р°РјРµС‚РєР° РїРµСЂРµРґ РѕРєРЅРѕРј вЂ” РѕР±С‹С‡РЅРѕРµ СЃРѕРѕР±С‰РµРЅРёРµ, СЃ РєРЅРѕРїРєРѕР№ В«рџ—‘ РЎРєСЂС‹С‚СЊВ»
      tg_send "$chat" "РџР°РЅРµР»СЊ СЃС‚РµРєР°. РЈРїСЂР°РІР»РµРЅРёРµ вЂ” РєРЅРѕРїРєР°РјРё РІ РѕРєРЅРµ РЅРёР¶Рµ."
      WINDOW_MID=""; show_screen "$chat" "main" ;;
    /status)  show_screen "$chat" "server" ;;
    /audit)   tg_send_kb "$chat" "$(run_check)" "$KB_HIDE" >/dev/null ;;
    /subs)    tg_send_kb "$chat" "$(cmd_subs)" "$KB_HIDE" >/dev/null ;;
    /fix)     PENDING="fix"; PENDING_TS=$SECONDS; tg_confirm "fix" "$chat" "Р—Р°РїСѓСЃС‚РёС‚СЊ Р°РІС‚РѕРїРѕС‡РёРЅРєСѓ (вљЎ РїСЂРѕРІРµСЂРєР° Рё РїРѕС‡РёРЅРєР°)?" ;;
    /cancel)  PENDING=""; wiz_reset; tg_send "$chat" "РћРє." ;;
    /err*)
      local ea eu
      ea=$(printf '%s' "$text" | awk '{print $2}')
      [[ -z "$ea" ]] && ea="xui"
      eu=$(err_unit "$ea") || eu=""
      if [[ -z "$eu" ]]; then tg_send "$chat" "РќРµ Р·РЅР°СЋ СЃРµСЂРІРёСЃ В«$(hesc "$ea")В». Р”РѕСЃС‚СѓРїРЅС‹: xui, nginx, adg, f2b, bot (РёР»Рё /err Р±РµР· Р°СЂРіСѓРјРµРЅС‚Р° = x-ui)."
      else tg_send_kb "$chat" "$(err_tail "$eu")" "$KB_HIDE" >/dev/null; fi ;;
    *)        tg_send "$chat" "РСЃРїРѕР»СЊР·СѓР№ РѕРєРЅРѕ РїР°РЅРµР»Рё РёР»Рё /start." ;;
  esac
}

# в”Ђв”Ђ РіР»Р°РІРЅС‹Р№ С†РёРєР» (long polling) в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
wiz_load
mon_load
out_load; tgout_cur_recalc
OUT_MTIME=$(stat -c %Y "$OUT_FILE" 2>/dev/null || printf '0')
main_loop() {
while :; do
  out_check_reload
  mon_tick
  mon_login_check
  resp=$(tgc -s --retry 2 --retry-delay 2 --max-time 25 "$API/getUpdates?timeout=15&offset=${OFFSET}")
  [[ -z "$resp" ]] && { sleep 3; continue; }   # СЃРµС‚СЊ РјРѕСЂРіРЅСѓР»Р° вЂ” РєРѕСЂРѕС‚РєР°СЏ РїР°СѓР·Р°, РЅРµ РіРѕСЂСЏС‡РёР№ С†РёРєР»
  ok=$(jq -r '.ok // false' <<<"$resp" 2>/dev/null) || ok=false
  if [[ "$ok" != "true" ]]; then
    ec=$(jq -r '.error_code // 0' <<<"$resp" 2>/dev/null)
    if [[ "$ec" == "409" ]]; then
      # 409 = СЃР»РѕС‚ getUpdates Р·Р°РЅСЏС‚ РґСЂСѓРіРёРј РїРѕР»Р»РµСЂРѕРј: СЃРїРёРј 1СЃ Рё С‚СѓС‚ Р¶Рµ РїРµСЂРµС…РІР°С‚С‹РІР°РµРј РѕРєРЅРѕ
      # (РґРѕР»РіРёР№ СЃРѕРЅ Р·РґРµСЃСЊ = Р±РѕС‚ РЅРµ РїРѕР»СѓС‡Р°РµС‚ РЅР°Р¶Р°С‚РёСЏ, РїРѕРєР° СЃРѕРїРµСЂРЅРёРє РґРµСЂР¶РёС‚ long-poll)
      (( C409LOG += 1 ))
      (( C409LOG % 10 == 1 )) && bot_log "409 Conflict вЂ” СЃР»РѕС‚ Р·Р°РЅСЏС‚ РґСЂСѓРіРёРј РїРѕР»Р»РµСЂРѕРј, РїРµСЂРµС…РІР°С‚С‹РІР°СЋ (РїРѕРґР°РІР». Р»РѕРі $(( C409LOG - 1 )) С€С‚)"
      sleep 1; continue
    fi
    bot_log "API: $(head -c 200 <<<"$resp")"; sleep 5; continue
  fi
  if (( OFFSET < 0 )); then   # РїРµСЂРІС‹Р№ СѓСЃРїРµС€РЅС‹Р№ РѕРїСЂРѕСЃ РїРѕСЃР»Рµ СЃС‚Р°СЂС‚Р°: РїСЂРѕРїСѓСЃРєР°РµРј РЅР°РєРѕРїР»РµРЅРЅРѕРµ, РЅРµ СЃРїР°РјРёРј СЃС‚Р°СЂС‹РјРё РєР°СЂС‚РѕС‡РєР°РјРё
    OFFSET=$(jq -r '[.result[]?.update_id] | if length>0 then (max+1) else 0 end' <<<"$resp" 2>/dev/null)
    [[ "$OFFSET" =~ ^[0-9]+$ ]] || OFFSET=0
    offset_save; continue
  fi
  while IFS= read -r upd; do
    [[ -z "$upd" ]] && continue
    uid=$(jq -r '.update_id' <<<"$upd")
    (( uid >= OFFSET )) && OFFSET=$((uid+1))
    chat=$(jq -r '.message.chat.id // .callback_query.message.chat.id // empty' <<<"$upd")
    text=$(jq -r '.message.text // empty' <<<"$upd")
    cbdata=$(jq -r '.callback_query.data // empty' <<<"$upd")
    cbid=$(jq -r '.callback_query.id // empty' <<<"$upd")
    cbmid=$(jq -r '.callback_query.message.message_id // empty' <<<"$upd")
    [[ -z "$chat" ]] && continue
    if [[ "$chat" != "$ADMIN_CHAT_ID" ]]; then
      if [[ -z "$ADMIN_CHAT_ID" && -n "$text" ]]; then
        bot_log "СЂРµР¶РёРј РѕР±СѓС‡РµРЅРёСЏ: chat_id=$chat РїСЂРёСЃР»Р°Р»: $text (РЅРµ РѕС‚РІРµС‡Р°СЋ; РІРїРёС€Рё id РІ /root/.tg-stack-bot.env)"
      fi
      continue
    fi
    dispatch "$chat" "$text" "$cbdata" "$cbid" "$cbmid"
  done < <(jq -c '.result[]?' <<<"$resp" 2>/dev/null)
  offset_save
done
}

run_bot() { # С‚РѕС‡РєР° РІС…РѕРґР° СЂРµР¶РёРјР° --bot: init в†’ РєСѓСЂСЃРѕСЂ Р°РїРґРµР№С‚РѕРІ в†’ СЃСѓРїРµСЂРІРёР·РѕСЂ
bot_init   # РєРѕРЅС„РёРі, РїСЂРѕРІРµСЂРєРё jq/flock, СЃРёРЅРіР»С‚РѕРЅ flock (РїСЂРё РѕС‚СЃСѓС‚СЃС‚РІРёРё С‚РѕРєРµРЅР° вЂ” exit)
OFFSET=$(cat "$OFFSET_FILE" 2>/dev/null || true)
[[ "$OFFSET" =~ ^[0-9]+$ ]] || OFFSET=-1   # -1 = РїРµСЂРІС‹Р№ РѕРїСЂРѕСЃ: РєСѓСЂСЃРѕСЂ СЃС‚Р°РІРёРј В«Р·Р° РїРѕСЃР»РµРґРЅРёР№В» Р°РїРґРµР№С‚, РЅР°РєРѕРїР»РµРЅРЅРѕРµ РЅРµ РїРµСЂРµРёРіСЂС‹РІР°РµРј
C409LOG=0                                  # СЃС‡С‘С‚С‡РёРє РїРѕРґР°РІР»РµРЅРЅС‹С… 409 (Р»РѕРі СЂР°Р· РІ 10)
bot_log "Р±РѕС‚ Р·Р°РїСѓС‰РµРЅ (admin=${ADMIN_CHAT_ID:-РќР• Р·Р°РґР°РЅ вЂ” СЂРµР¶РёРј РѕР±СѓС‡РµРЅРёСЏ}; tg-РІС‹С…РѕРґ=$( [[ -n "$TG_PROXY_CUR" ]] && printf '%s: %s' "$TG_OUT_MODE" "$TG_PROXY_CUR" || printf 'РїСЂСЏРјРѕР№' ))"
# в”Ђв”Ђ СЃСѓРїРµСЂРІРёР·РѕСЂ: РІРЅСѓС‚СЂРµРЅРЅРёР№ С†РёРєР» РЅРµ РґРѕР»Р¶РµРЅ РІРѕР·РІСЂР°С‰Р°С‚СЊСЃСЏ; РµСЃР»Рё РІРµСЂРЅСѓР»СЃСЏ вЂ” РїРѕРґРЅРёРјР°РµРј в”Ђв”Ђ
while :; do
  main_loop
  bot_log "РіР»Р°РІРЅС‹Р№ С†РёРєР» Р·Р°РІРµСЂС€РёР»СЃСЏ (РЅРµРѕР¶РёРґР°РЅРЅРѕ) вЂ” РїРµСЂРµР·Р°РїСѓСЃРє С‡РµСЂРµР· 3 СЃ"
  sleep 3
done
}
# PRE-INSTALL SNAPSHOT вЂ” СЃРЅРёРјРѕРє РІСЃРµРіРѕ, РІРѕ С‡С‚Рѕ СЃРєСЂРёРїС‚ РјРѕР¶РµС‚ РІРјРµС€Р°С‚СЊСЃСЏ.
# Р”РµР»Р°РµС‚СЃСЏ РїСЂРё РїРµСЂРІРѕРј Р·Р°РїСѓСЃРєРµ (РїРѕ СЃРѕРіР»Р°СЃРёСЋ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ) РёР»Рё С‡РµСЂРµР· СЂР°Р·РґРµР» 5 в†’ Pre-install snapshot.
# РҐСЂР°РЅРёС‚СЃСЏ РІ /root/stack-backups/pre-install-<timestamp>/
# =====================================================================
take_pre_install_snapshot() {
  local ts; ts=$(date +%Y%m%d-%H%M%S)
  local dir="$BACKUP_DIR/pre-install-$ts"
  mkdir -p "$dir" 2>/dev/null || { err "РќРµ РјРѕРіСѓ СЃРѕР·РґР°С‚СЊ $dir"; return 1; }

  log "РЎРЅРёРјРѕРє СЃРѕСЃС‚РѕСЏРЅРёСЏ: $dir"
  log "  (x-ui.db, nginx, UFW, iptables, fail2ban, systemd-units, letsencrypt-renewal, AdGuard)"

  # 1. x-ui.db + /etc/x-ui
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    # РљРѕРЅСЃРёСЃС‚РµРЅС‚РЅС‹Р№ SQLite-СЃРЅРёРјРѕРє: cp Р°РєС‚РёРІРЅРѕР№ Р‘Р” Р±РµР· WAL РјРѕРі СЃРѕС…СЂР°РЅРёС‚СЊ
    # РЅРµР·Р°РєРѕРјРјРёС‡РµРЅРЅС‹Рµ РЅР°СЃС‚СЂРѕР№РєРё Reality/hosts РЅРµ РїРѕР»РЅРѕСЃС‚СЊСЋ.
    local _snap_ok=false
    if command -v sqlite3 >/dev/null 2>&1; then
      sqlite3 "$XUI_DB" ".backup '$dir/x-ui.db'" >/dev/null 2>&1 && _snap_ok=true
    fi
    if [[ "$_snap_ok" != true ]]; then
      cp -a "$XUI_DB" "$dir/x-ui.db" 2>/dev/null || true
      [[ -f "${XUI_DB}-wal" ]] && cp -a "${XUI_DB}-wal" "$dir/x-ui.db-wal" 2>/dev/null || true
      [[ -f "${XUI_DB}-shm" ]] && cp -a "${XUI_DB}-shm" "$dir/x-ui.db-shm" 2>/dev/null || true
    fi
    [[ -d /etc/x-ui ]] && cp -a /etc/x-ui "$dir/etc-x-ui" 2>/dev/null || true
  fi

  # 2. nginx вЂ” РІРµСЃСЊ РєРѕРЅС„РёРі С†РµР»РёРєРѕРј
  mkdir -p "$dir/nginx"
  cp -a /etc/nginx/nginx.conf "$dir/nginx/" 2>/dev/null || true
  for d in sites-available sites-enabled streams-available streams-enabled snippets conf.d; do
    [[ -d "/etc/nginx/$d" ]] && cp -a "/etc/nginx/$d" "$dir/nginx/" 2>/dev/null || true
  done

  # 3. UFW + iptables + РјР°СЂС€СЂСѓС‚С‹
  mkdir -p "$dir/ufw"
  [[ -d /etc/ufw ]] && cp -a /etc/ufw "$dir/ufw/etc-ufw" 2>/dev/null || true
  [[ -f /etc/default/ufw ]] && cp -a /etc/default/ufw "$dir/ufw/" 2>/dev/null || true
  iptables-save   > "$dir/ufw/iptables.v4"  2>/dev/null || true
  ip6tables-save  > "$dir/ufw/iptables.v6"  2>/dev/null || true
  ip -4 route show > "$dir/ufw/routes.v4" 2>/dev/null || true
  ip -6 route show > "$dir/ufw/routes.v6" 2>/dev/null || true

  # 4. fail2ban
  if [[ -d /etc/fail2ban ]]; then
    mkdir -p "$dir/fail2ban"
    cp -a /etc/fail2ban "$dir/fail2ban/etc-fail2ban" 2>/dev/null || true
  fi

  # 5. systemd units СЃС‚РµРєР°
  mkdir -p "$dir/systemd"
  cp -a /etc/systemd/system/stack-heal.service /etc/systemd/system/stack-heal.timer "$dir/systemd/" 2>/dev/null || true
  cp -a /etc/systemd/system/x-ui.service "$dir/systemd/" 2>/dev/null || true

  # 6. letsencrypt renewal (Р±РµР· РєР»СЋС‡РµР№)
  if [[ -d /etc/letsencrypt ]]; then
    mkdir -p "$dir/letsencrypt"
    cp -a /etc/letsencrypt/renewal "$dir/letsencrypt/" 2>/dev/null || true
    cp -a /etc/letsencrypt/renewal-hooks "$dir/letsencrypt/" 2>/dev/null || true
    cp -a /etc/letsencrypt/cli.ini "$dir/letsencrypt/" 2>/dev/null || true
  fi

  # 7. logrotate СЃС‚РµРєР°
  [[ -f /etc/logrotate.d/stack-decoy ]] && cp -a /etc/logrotate.d/stack-decoy "$dir/" 2>/dev/null || true

  # 8. AdGuard Home config
  if [[ -n "$ADG_CONFIG" && -f "$ADG_CONFIG" ]]; then
    cp -a "$ADG_CONFIG" "$dir/AdGuardHome.yaml" 2>/dev/null || true
  fi

  # 9. РљРѕРЅС‚РµРєСЃС‚: РїР°РєРµС‚С‹ + РјРµС‚Р°
  dpkg --get-selections > "$dir/dpkg-selections.txt" 2>/dev/null || true
  apt-mark showmanual > "$dir/apt-manual.txt" 2>/dev/null || true
  {
    echo "Р”Р°С‚Р°: $(date '+%F %T')"
    echo "РҐРѕСЃС‚: $(hostname)"
    echo "РџР°РЅРµР»СЊ: ${PANEL_FLAVOR:-unknown}"
    echo "x-ui.db: $XUI_DB"
    echo "AdGuard: ${ADG_SERVICE:-вЂ”}"
    echo "nginx: $(nginx -v 2>&1 || echo вЂ”)"
    echo "fail2ban: $(fail2ban-client --version 2>/dev/null | head -1 || echo вЂ”)"
  } > "$dir/INFO.txt"

  # РђСЂС…РёРІ
  (cd "$BACKUP_DIR" && tar czf "pre-install-$ts.tar.gz" "pre-install-$ts" 2>/dev/null) || true

  log "РЎРЅРёРјРѕРє РіРѕС‚РѕРІ: $dir"
  log "  Р°СЂС…РёРІ: $BACKUP_DIR/pre-install-$ts.tar.gz"
  return 0
}

# Р¤Р°Р№Р» РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚ РІ СЃРїРёСЃРєРµ СЃРѕРґРµСЂР¶РёРјРѕРіРѕ Р°СЂС…РёРІР°? (0 = РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚)
absent_in_list() {  # $1 = СЃРїРёСЃРѕРє РїСѓС‚РµР№, $2 = РїСѓС‚СЊ
  local e
  while IFS= read -r e; do
    [[ "$e" == "$2" || "$e" == "./$2" || "$e" == "${2#/}" ]] && return 1
  done <<<"$1"
  return 0
}

# РђС‚РѕРјР°СЂРЅР°СЏ Р·Р°РјРµРЅР° РєР°С‚Р°Р»РѕРіР° РёР· СЃРЅРёРјРєР°: РєРѕРїРёСЂСѓРµРј РІРѕ РІСЂРµРјРµРЅРЅРѕРµ РјРµСЃС‚Рѕ, Р·Р°С‚РµРј mv РЅР°
# РјРµСЃС‚Рѕ СЃС‚Р°СЂРѕРіРѕ. РџСЂРµР¶РЅРёР№ РєР°С‚Р°Р»РѕРі СѓРґР°Р»СЏРµС‚СЃСЏ РўРћР›Р¬РљРћ РїРѕСЃР»Рµ СѓСЃРїРµС€РЅРѕР№ СѓСЃС‚Р°РЅРѕРІРєРё РЅРѕРІРѕРіРѕ;
# РµСЃР»Рё cp/mv РЅРµ СѓРґР°Р»СЃСЏ вЂ” С‚РµРєСѓС‰РёР№ РєРѕРЅС„РёРі РѕСЃС‚Р°С‘С‚СЃСЏ РЅРµС‚СЂРѕРЅСѓС‚С‹Рј (СЂР°РЅСЊС€Рµ Р±С‹Р»Рѕ
# В«rm -rf + cpВ», Рё РїСЂРѕРІР°Р» cp РѕСЃС‚Р°РІР»СЏР» СЃРёСЃС‚РµРјСѓ РІРѕРѕР±С‰Рµ Р±РµР· РєРѕРЅС„РёРіР°).
safe_swap_dir() {   # $1 = РёСЃС‚РѕС‡РЅРёРє (РёР· СЃРЅРёРјРєР°), $2 = С†РµР»РµРІРѕР№ РєР°С‚Р°Р»РѕРі
  local src="$1" dst="$2" t old
  [[ -d "$src" ]] || return 0
  t=$(mktemp -d "${dst}.restore.XXXXXX" 2>/dev/null) || { warn "mktemp РґР»СЏ $dst РЅРµ СѓРґР°Р»СЃСЏ вЂ” РїСЂРѕРїСѓСЃРєР°СЋ"; return 1; }
  if ! cp -a "$src" "$t/restore" 2>/dev/null; then
    rm -rf "$t" 2>/dev/null || true
    warn "РєРѕРїРёСЂРѕРІР°РЅРёРµ $src РЅРµ СѓРґР°Р»РѕСЃСЊ вЂ” $dst РЅРµ С‚СЂРѕРЅСѓС‚"
    return 1
  fi
  if [[ -e "$dst" ]]; then
    old="${dst}.old.$$"
    if ! mv "$dst" "$old" 2>/dev/null; then
      rm -rf "$t" 2>/dev/null || true
      warn "РЅРµ СѓРґР°Р»РѕСЃСЊ СѓР±СЂР°С‚СЊ СЃС‚Р°СЂС‹Р№ $dst вЂ” РѕСЃС‚Р°РІР»СЏСЋ РєР°Рє РµСЃС‚СЊ"
      return 1
    fi
    if mv "$t/restore" "$dst" 2>/dev/null; then
      rm -rf "$old" 2>/dev/null || true
    else
      mv "$old" "$dst" 2>/dev/null || true
      rm -rf "$t" 2>/dev/null || true
      warn "РЅРµ СѓРґР°Р»РѕСЃСЊ РїРѕСЃС‚Р°РІРёС‚СЊ РЅРѕРІС‹Р№ $dst вЂ” РѕС‚РєР°С‚ Рє РїСЂРµР¶РЅРµРјСѓ"
      return 1
    fi
  else
    mv "$t/restore" "$dst" 2>/dev/null || { rm -rf "$t" 2>/dev/null || true; return 1; }
  fi
  rm -rf "$t" 2>/dev/null || true
  return 0
}

restore_pre_install_snapshot() {
  line; echo -e "${B}   Р’РћРЎРЎРўРђРќРћР’Р›Р•РќРР• РР— PRE-INSTALL РЎРќРРњРљРђ${N}"; line
  local snaps
  snaps=$(ls -1dt "$BACKUP_DIR"/pre-install-* 2>/dev/null | grep -v "\.tar\.gz$" | head -20)
  if [[ -z "$snaps" ]]; then
    warn "РЎРЅРёРјРєРѕРІ РЅРµ РЅР°Р№РґРµРЅРѕ РІ $BACKUP_DIR/pre-install-*"; pause; return 0
  fi
  local i=1 d
  while IFS= read -r d; do
    [[ -z "$d" ]] && continue
    local info
    info=$(head -1 "$d/INFO.txt" 2>/dev/null || echo "вЂ”")
    printf "  %2d) %-40s %s
" "$i" "$(basename "$d")" "$info"
    i=$((i+1))
  done <<<"$snaps"
  echo
  local pick=""
  ask pick "РќРѕРјРµСЂ СЃРЅРёРјРєР° (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
  [[ "$pick" == "0" ]] && return 0
  local chosen=""
  chosen=$(printf '%s
' "$snaps" | sed -n "${pick}p")
  [[ -z "$chosen" || ! -d "$chosen" ]] && { err "РќРµ РЅР°Р№РґРµРЅ СЃРЅРёРјРѕРє #$pick"; pause; return 1; }

  echo
  echo -e "${R}Р’РќРРњРђРќРР•:${N} РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РїРµСЂРµР·Р°РїРёС€РµС‚ С‚РµРєСѓС‰РµРµ СЃРѕСЃС‚РѕСЏРЅРёРµ:"
  echo "  вЂў $XUI_DB (РёРЅР±Р°СѓРЅРґС‹ Рё РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё)"
  echo "  вЂў /etc/nginx (РІСЃРµ СЃР°Р№С‚С‹ Рё СЃС‚СЂРёРјС‹)"
  echo "  вЂў РїСЂР°РІРёР»Р° UFW/iptables"
  echo "  вЂў /etc/fail2ban (РµСЃР»Рё Р±С‹Р» РІ СЃРЅРёРјРєРµ)"
  echo "  вЂў systemd units СЃС‚РµРєР° (stack-heal, x-ui.service)"
  echo "  вЂў /etc/letsencrypt/renewal + renewal-hooks"
  echo
  local sure=""
  ask sure "Р”Р»СЏ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РІРІРµРґРё YES" "" '^YES$'
  [[ "$sure" == "YES" ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; pause; return 0; }
  audit "rollback: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РёР· pre-install snapshot $chosen"

  log "Р‘СЌРєР°Рї С‚РµРєСѓС‰РµРіРѕ СЃРѕСЃС‚РѕСЏРЅРёСЏ РїРµСЂРµРґ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµРјвЂ¦"
  take_pre_install_snapshot >/dev/null 2>&1 || true

  log "РћСЃС‚Р°РЅРѕРІРєР° СЃРµСЂРІРёСЃРѕРІвЂ¦"
  systemctl stop x-ui 2>/dev/null || true
  systemctl stop nginx 2>/dev/null || true
  [[ -n "$ADG_SERVICE" ]] && systemctl stop "$ADG_SERVICE" 2>/dev/null || true

  if [[ -f "$chosen/x-ui.db" && -n "$XUI_DB" ]]; then
    # WAL/SHM РѕС‚ С‚РµРєСѓС‰РµР№ Р‘Р” РЅРµР»СЊР·СЏ РѕСЃС‚Р°РІР»СЏС‚СЊ: SQLite РїСЂРёРјРµРЅРёС‚ РёС… РїРѕРІРµСЂС…
    # РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕРіРѕ СЃРЅРёРјРєР° Рё РІРµСЂРЅС‘С‚ СЃС‚Р°СЂС‹Рµ SNI/hosts.
    sqlite3 "$XUI_DB" "PRAGMA wal_checkpoint(TRUNCATE);" >/dev/null 2>&1 || true
    rm -f "${XUI_DB}-wal" "${XUI_DB}-shm" 2>/dev/null || true
    cp -a "$chosen/x-ui.db" "$XUI_DB" 2>/dev/null && log "  x-ui.db РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
  fi
  if [[ -d "$chosen/etc-x-ui" ]]; then
    cp -a "$chosen/etc-x-ui/." /etc/x-ui/ 2>/dev/null || true
  fi

  if [[ -d "$chosen/nginx" ]]; then
    [[ -f "$chosen/nginx/nginx.conf" ]] && cp -a "$chosen/nginx/nginx.conf" /etc/nginx/nginx.conf 2>/dev/null
    for d in sites-available sites-enabled streams-available streams-enabled snippets conf.d; do
      if [[ -d "$chosen/nginx/$d" ]]; then
        safe_swap_dir "$chosen/nginx/$d" "/etc/nginx/$d" \
          && log "  /etc/nginx/$d РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ" \
          || warn "  /etc/nginx/$d РќР• РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ (СЃРј. РІС‹С€Рµ)"
      fi
    done
    log "  /etc/nginx РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
  fi

  if [[ -d "$chosen/ufw" ]]; then
    [[ -f "$chosen/ufw/iptables.v4" ]] && iptables-restore  < "$chosen/ufw/iptables.v4" 2>/dev/null && log "  iptables v4 РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"
    [[ -f "$chosen/ufw/iptables.v6" ]] && ip6tables-restore < "$chosen/ufw/iptables.v6" 2>/dev/null || true
    if [[ -d "$chosen/ufw/etc-ufw" ]]; then
      safe_swap_dir "$chosen/ufw/etc-ufw" /etc/ufw || warn "  /etc/ufw РќР• РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
      [[ -f "$chosen/ufw/ufw" ]] && cp -a "$chosen/ufw/ufw" /etc/default/ufw 2>/dev/null || true
      log "  /etc/ufw РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
    fi
  fi

  if [[ -d "$chosen/fail2ban/etc-fail2ban" ]]; then
    safe_swap_dir "$chosen/fail2ban/etc-fail2ban" /etc/fail2ban || warn "  /etc/fail2ban РќР• РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
    log "  /etc/fail2ban РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
  fi

  if [[ -d "$chosen/systemd" ]]; then
    for u in stack-heal.service stack-heal.timer x-ui.service; do
      [[ -f "$chosen/systemd/$u" ]] && cp -a "$chosen/systemd/$u" /etc/systemd/system/ 2>/dev/null
    done
    systemctl daemon-reload 2>/dev/null || true
    log "  systemd units РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"
  fi

  if [[ -d "$chosen/letsencrypt" ]]; then
    safe_swap_dir "$chosen/letsencrypt/renewal" /etc/letsencrypt/renewal || warn "  letsencrypt/renewal РќР• РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
    safe_swap_dir "$chosen/letsencrypt/renewal-hooks" /etc/letsencrypt/renewal-hooks || warn "  letsencrypt/renewal-hooks РќР• РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
    [[ -f "$chosen/letsencrypt/cli.ini" ]] && cp -a "$chosen/letsencrypt/cli.ini" /etc/letsencrypt/ 2>/dev/null
    log "  letsencrypt renewal РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
  fi

  [[ -f "$chosen/stack-decoy" ]] && cp -a "$chosen/stack-decoy" /etc/logrotate.d/ 2>/dev/null || true

  if [[ -f "$chosen/AdGuardHome.yaml" && -n "$ADG_CONFIG" ]]; then
    cp -a "$chosen/AdGuardHome.yaml" "$ADG_CONFIG" 2>/dev/null && log "  AdGuardHome.yaml РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ"
  fi

  log "Р—Р°РїСѓСЃРє СЃРµСЂРІРёСЃРѕРІвЂ¦"
  systemctl start nginx 2>/dev/null || true
  systemctl start x-ui 2>/dev/null || true
  [[ -n "$ADG_SERVICE" ]] && systemctl start "$ADG_SERVICE" 2>/dev/null || true
  systemctl restart fail2ban 2>/dev/null || true
  nginx -t >/dev/null 2>&1 && log "  nginx -t OK" || warn "  nginx -t РїСЂРѕРІР°Р»РёР»СЃСЏ вЂ” РїСЂРѕРІРµСЂСЊ РєРѕРЅС„РёРі"

  line
  log "Р’РѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РёР· pre-install Р·Р°РІРµСЂС€РµРЅРѕ: $chosen"
  line
  pause
}

# =====================================================================
# Р‘Р­РљРђРџ
# =====================================================================
# Р”РѕРјРµРЅ РїР°РЅРµР»Рё РёР· РїРѕСЃР»РµРґРЅРµРіРѕ Р±СЌРєР°РїР° СЃС‚РµРєР° вЂ” РґР»СЏ РїРµСЂРµРµР·РґР° РЅР° РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ.
# РС‰РµРј stack-backup-*.tar.gz РІ $BACKUP_DIR Рё /root, РґРѕСЃС‚Р°С‘Рј РёР· Р°СЂС…РёРІР° x-ui.db
# Рё С‡РёС‚Р°РµРј webDomain/subDomain. РџРµС‡Р°С‚Р°РµС‚ РґРѕРјРµРЅ РёР»Рё РїСѓСЃС‚Рѕ (РѕС€РёР±РєРё вЂ” РјРѕР»С‡Р°).
backup_peek_panel_domain() {
  local f="" cand
  for cand in "$BACKUP_DIR"/stack-backup-*.tar.gz /root/stack-backup-*.tar.gz; do
    [[ -f "$cand" ]] || continue
    [[ -z "$f" || "$cand" -nt "$f" ]] && f="$cand"
  done
  [[ -z "$f" ]] && return 0
  # Р’РђР–РќРћ (pipefail): СЃРїРёСЃРѕРє С„Р°Р№Р»РѕРІ Р±РµСЂС‘Рј Р¦Р•Р›РРљРћРњ, Р·Р°С‚РµРј grep РїРѕ РїРµСЂРµРјРµРЅРЅРѕР№ вЂ”
  # `tar | grep -m1` СЂРѕРЅСЏРµС‚ tar РїРѕ SIGPIPE Рё Р·Р°С‚РёСЂР°РµС‚ СЂРµР·СѓР»СЊС‚Р°С‚.
  local tlist member=""
  tlist=$(tar tzf "$f" 2>/dev/null) || tlist=""
  member=$(printf '%s\n' "$tlist" | grep -m1 -E '(^|/)x-ui\.db$') || member=""
  [[ -z "$member" ]] && return 0
  local tmp
  tmp=$(mktemp -d 2>/dev/null) || return 0
  tar xzf "$f" -C "$tmp" "$member" 2>/dev/null || { rm -rf "$tmp"; return 0; }
  local dbf="$tmp/$member" d=""
  if command -v sqlite3 >/dev/null 2>&1; then
    d=$(sqlite3 "$dbf" "SELECT value FROM settings WHERE key='webDomain';" 2>/dev/null | tr -d '[:space:]')
    [[ -z "$d" || "$d" == "null" ]] && \
      d=$(sqlite3 "$dbf" "SELECT value FROM settings WHERE key='subDomain';" 2>/dev/null | tr -d '[:space:]')
  elif command -v python3 >/dev/null 2>&1; then
    d=$(python3 - "$dbf" <<'PYBK' 2>/dev/null
import sqlite3, sys
try:
    con = sqlite3.connect(sys.argv[1])
    for k in ("webDomain", "subDomain"):
        r = con.execute("SELECT value FROM settings WHERE key=?", (k,)).fetchone()
        if r and r[0] and str(r[0]).strip() not in ("", "null"):
            print(str(r[0]).strip()); break
except Exception:
    pass
PYBK
)
    d=$(printf '%s' "$d" | tr -d '[:space:]')
  fi
  rm -rf "$tmp"
  [[ "$d" =~ ^[a-zA-Z0-9.-]+$ ]] && printf '%s' "$d"
  return 0
}

backup_config() {
  line; echo -e "${B}   Р‘Р­РљРђРџ${N}"; line
  mkdir -p "$BACKUP_DIR" 2>/dev/null || true
  local ts file
  ts=$(date +%F_%H%M%S)
  file="$BACKUP_DIR/stack-backup-$ts.tar.gz"
  local -a files=(
    /etc/nginx/nginx.conf /etc/nginx/streams-enabled/ /etc/nginx/sites-enabled/
    "$XUI_DB" /etc/letsencrypt/renewal/
    /etc/fail2ban/jail.d/decoy-login.local
    /etc/fail2ban/filter.d/decoy-login.conf
  )
  [[ -n "$ADG_CONFIG" && -f "$ADG_CONFIG" ]] && files+=("$ADG_CONFIG")
  if ! tar czf "$file" "${files[@]}" 2>/dev/null; then
    rm -f "$file"
    err "Р‘СЌРєР°Рї РЅРµ СЃРѕР·РґР°РЅ: tar Р·Р°РІРµСЂС€РёР»СЃСЏ СЃ РѕС€РёР±РєРѕР№"
    pause
    return 1
  fi
  sha256sum "$file" > "$file.sha256" 2>/dev/null || true
  log "Р‘СЌРєР°Рї: $file"
  ls -lh "$file" 2>/dev/null || true
  pause
}

restore_config() {
  line; echo -e "${B}   Р’РћРЎРЎРўРђРќРћР’Р›Р•РќРР•${N}"; line
  mkdir -p "$BACKUP_DIR" 2>/dev/null || true
  ls -1t "$BACKUP_DIR"/stack-backup-*.tar.gz 2>/dev/null | nl -w2 -s') ' || { warn "РќРµС‚ Р±СЌРєР°РїРѕРІ"; pause; return 0; }
  local choice=""
  ask choice "РќРѕРјРµСЂ (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
  [[ "$choice" == 0 ]] && return 0
  local file=""
  file=$(ls -1t "$BACKUP_DIR"/stack-backup-*.tar.gz 2>/dev/null | sed -n "${choice}p" || true)
  [[ -z "$file" || ! -f "$file" ]] && { err "РќРµ РЅР°Р№РґРµРЅ"; return 1; }
  askyn confirm "Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ РёР· $file?" "n"
  [[ "$confirm" == true ]] || return 0
  audit "restore: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РєРѕРЅС„РёРіСѓСЂР°С†РёРё РёР· $(basename "$file")"
  backup_config >/dev/null 2>&1 || true
  systemctl stop nginx 2>/dev/null || true
  systemctl stop x-ui  2>/dev/null || true
  [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]] && systemctl stop "$ADG_SERVICE" 2>/dev/null || true
  tar xzf "$file" -C / 2>/dev/null && log "Р¤Р°Р№Р»С‹ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"
  # РџРѕР»РЅС‹Р№ РѕС‚РєР°С‚: СѓР±РёСЂР°РµРј Р°СЂС‚РµС„Р°РєС‚С‹ СЃС‚РµРєР°, РєРѕС‚РѕСЂС‹С… РІ Р±СЌРєР°РїРµ РЅРµС‚ вЂ” РёРЅР°С‡Рµ
  # РѕСЃС‚Р°С‘С‚СЃСЏ РїРѕР»Сѓ-РЅР°СЃС‚СЂРѕРµРЅРЅС‹Р№ СЃС‚РµРє Рё Рї.1 СЂРµС€Р°РµС‚, С‡С‚Рѕ В«СѓР¶Рµ РІСЃС‘ РЅР°СЃС‚СЂРѕРµРЅРѕВ».
  local tlist _a
  tlist=$(tar tzf "$file" 2>/dev/null) || tlist=""
  for _a in "$STACK_CONF" \
            /etc/nginx/streams-available/sni-router.conf \
            /etc/nginx/streams-enabled/sni-router.conf \
            /etc/systemd/system/stack-heal.timer \
            /etc/systemd/system/stack-heal.service \
            /etc/letsencrypt/stack-domains.txt \
            /root/stack-frozen.txt \
            /etc/x-ui/x-ui.db /usr/local/x-ui/x-ui.db /opt/x-ui/x-ui.db; do
    if [[ -e "$_a" ]] && absent_in_list "$tlist" "$_a"; then
      rm -f "$_a" 2>/dev/null && log "  СѓР±СЂР°РЅРѕ (РІ Р±СЌРєР°РїРµ РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚): $_a"
    fi
  done
  [[ -e /etc/systemd/system/stack-heal.timer ]] || { systemctl disable --now stack-heal.timer 2>/dev/null || true; systemctl daemon-reload 2>/dev/null || true; }
  nginx -t 2>/dev/null && systemctl start nginx && log "Nginx Р·Р°РїСѓС‰РµРЅ"
  systemctl start x-ui 2>/dev/null || true
  [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]] && systemctl start "$ADG_SERVICE" 2>/dev/null || true
  systemctl restart fail2ban 2>/dev/null || true
  # РџРµСЂРµРµР·Рґ РЅР° РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ: РІ Р±СЌРєР°РїРµ РІРѕР·СЏС‚СЃСЏ С‚РѕР»СЊРєРѕ renewal-РєРѕРЅС„РёРіРё, СЃР°РјРёС…
  # СЃРµСЂС‚РѕРІ (live/) РЅРµС‚ вЂ” РїР°РЅРµР»СЊ РѕСЃС‚Р°Р»Р°СЃСЊ Р±С‹ Р±РµР· TLS. РџСЂРµРґР»Р°РіР°РµРј СЃСЂР°Р·Сѓ
  # РїРµСЂРµСЃРѕР±СЂР°С‚СЊ РјСѓР»СЊС‚РёСЃРµСЂС‚ РёР· РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕРіРѕ РґРѕРјРµРЅР°/SNI-РєР°СЂС‚С‹.
  if ! ls /etc/letsencrypt/live/*/fullchain.pem >/dev/null 2>&1; then
    warn "РЎРµСЂС‚РёС„РёРєР°С‚С‹ РЅР° СЌС‚РѕРј СЃРµСЂРІРµСЂРµ РЅРµ РІС‹РїСѓС‰РµРЅС‹ (РІ Р±СЌРєР°РїРµ С‚РѕР»СЊРєРѕ renewal-РєРѕРЅС„РёРіРё)"
    local rcert=""
    askyn rcert "РџРµСЂРµСЃРѕР±СЂР°С‚СЊ РјСѓР»СЊС‚РёСЃРµСЂС‚ РёР· РґРѕРјРµРЅРѕРІ Р±СЌРєР°РїР° СЃРµР№С‡Р°СЃ? (DNS СѓР¶Рµ РґРѕР»Р¶РµРЅ СѓРєР°Р·С‹РІР°С‚СЊ РЅР° СЌС‚РѕС‚ СЃРµСЂРІРµСЂ)" "y"
    [[ "$rcert" == true ]] && { CERT_DEFER=0; cert_batch_flush; }
  fi
  pause
}

# =====================================================================
# РџР•Р Р•Р•Р—Р” Р”РћРњР•РќРђ РџРђРќР•Р›Р: СЃРµСЂС‚ + Р‘Р” (webDomain/hosts) + nginx (Р±Р»РѕРєРё/map)
# + decoy-РјР°СЂРєРµСЂ + credentials. РЎС‚Р°СЂС‹Р№ СЃРµСЂС‚ РѕРїС†РёРѕРЅР°Р»СЊРЅРѕ РѕС‚Р·С‹РІР°РµС‚СЃСЏ.
# =====================================================================
panel_domain_migrate() {
  line; echo -e "${B}   РџР•Р Р•Р•Р—Р” Р”РћРњР•РќРђ РџРђРќР•Р›Р${N}"; line
  [[ -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; pause; return 1; }
  local old=""; old=$(xui_get webDomain 2>/dev/null | tr -d '[:space:]')
  if [[ -z "$old" || "$old" == "null" ]]; then
    ask old "РўРµРєСѓС‰РёР№ РґРѕРјРµРЅ РїР°РЅРµР»Рё (РЅРµ РЅР°Р№РґРµРЅ РІ Р‘Р”)" "" '^[a-zA-Z0-9.-]+$'
  fi
  [[ -z "$old" ]] && { warn "РћС‚РјРµРЅР°"; pause; return 0; }
  local new=""
  ask new "РќРћР’Р«Р™ РґРѕРјРµРЅ РїР°РЅРµР»Рё" "" '^[a-zA-Z0-9.-]+$'
  [[ -z "$new" || "$new" == "$old" ]] && { warn "РћС‚РјРµРЅР°"; pause; return 0; }

  echo
  echo "  Р‘СѓРґРµС‚ СЃРґРµР»Р°РЅРѕ:"
  echo "   вЂў СЃРµСЂС‚ РґР»СЏ $new (certbot, СЃ С‚РµРєСѓС‰РёРј email LE)"
  echo "   вЂў РїР°РЅРµР»СЊ: webDomain в†’ $new (stop в†’ edit в†’ start)"
  echo "   вЂў hosts-Р·Р°РїРёСЃРё: address $old в†’ $new (СЃСЃС‹Р»РєРё РїРѕРґРїРёСЃРѕРє РѕР±РЅРѕРІСЏС‚СЃСЏ СЃР°РјРё)"
  echo "   вЂў nginx: stack.conf + SNI-map, РјР°СЂРєРµСЂ decoy РїР°РЅРµР»Рё, credentials-С„Р°Р№Р»"
  if check_domain_points_to_server "$new" >/dev/null 2>&1; then
    ok "DNS: $new СѓРєР°Р·С‹РІР°РµС‚ РЅР° СЌС‚РѕС‚ СЃРµСЂРІРµСЂ"
  else
    local go=""
    askyn go "DNS: $new РќР• СѓРєР°Р·С‹РІР°РµС‚ РЅР° СЃРµСЂРІРµСЂ (РёР»Рё РЅРµ СЂРµР·РѕР»РІРёС‚СЃСЏ). РџСЂРѕРґРѕР»Р¶РёС‚СЊ?" "n"
    [[ "$go" == true ]] || { pause; return 0; }
  fi
  local go=""
  askyn go "РќР°С‡Р°С‚СЊ РїРµСЂРµРµР·Рґ $old в†’ $new?" "n"
  [[ "$go" == true ]] || { pause; return 0; }
  auto_backup_stack >/dev/null 2>&1 || true

  # 1) СЃРµСЂС‚ РЅРѕРІРѕРіРѕ РґРѕРјРµРЅР° (СѓРІР°Р¶Р°РµС‚ Р·Р°РјРѕСЂРѕР·РєСѓ Рї.25 вЂ” СЃРЅСЏР» freeze, РµСЃР»Рё РЅР°РґРѕ)
  cert_issue "$new" || warn "РЎРµСЂС‚ $new РЅРµ РІС‹РїСѓС‰РµРЅ вЂ” РїР°РЅРµР»СЊ РІСЂРµРјРµРЅРЅРѕ РЅР° СЃС‚Р°СЂРѕРј СЃРµСЂС‚Рµ; РїРѕРІС‚РѕСЂРё Рї.10 РїРѕР·Р¶Рµ"

  # 2) Р‘Р” РїР°РЅРµР»Рё: webDomain + hosts
  systemctl stop x-ui 2>/dev/null || true
  sqlite3 "$XUI_DB" "UPDATE settings SET value='$new' WHERE key='webDomain';" 2>/dev/null || true
  sqlite3 "$XUI_DB" "UPDATE hosts SET address='$new' WHERE address='$old';" 2>/dev/null || true

  # 3) nginx: РїР°РЅРµР»СЊРЅС‹Рµ РІС…РѕР¶РґРµРЅРёСЏ old в†’ new (РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРёРіРґРµ Р±РѕР»СЊС€Рµ РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ)
  local oesc="${old//./\\.}"
  local confs=("$STACK_CONF" "$SNI_CONF")
  local cf
  for cf in "${confs[@]}"; do
    [[ -f "$cf" ]] && cp -a "$cf" "$cf.bak-migrate-$(date +%Y%m%d-%H%M%S)"
  done
  sed -i "s/$oesc/$new/g" "$STACK_CONF" 2>/dev/null || true
  [[ -f "$SNI_CONF" ]] && sed -i "s/$oesc/$new/g" "$SNI_CONF" 2>/dev/null || true
  [[ -f /root/panel-credentials.txt ]] && sed -i "s/$oesc/$new/g" /root/panel-credentials.txt 2>/dev/null || true

  if nginx -t >/dev/null 2>&1; then
    nginx_reload || true
  else
    err "nginx -t РЅРµ РїСЂРѕС€С‘Р» РїРѕСЃР»Рµ Р·Р°РјРµРЅС‹ вЂ” РѕС‚РєР°С‚С‹РІР°СЋ РєРѕРЅС„РёРіРё:"
    nginx -t 2>&1 | tail -4 | sed 's/^/    /'
    for cf in "${confs[@]}"; do
      local bak; bak=$(ls -t "$cf".bak-migrate-* 2>/dev/null | head -1)
      [[ -n "$bak" ]] && cp -a "$bak" "$cf"
    done
    systemctl start x-ui 2>/dev/null || true
    pause; return 1
  fi
  systemctl start x-ui 2>/dev/null || true

  # 4) СЃС‚Р°СЂС‹Р№ СЃРµСЂС‚ вЂ” РїСЂРµРґР»РѕР¶РёС‚СЊ СѓР±СЂР°С‚СЊ
  if cert_paths "$old" >/dev/null 2>&1; then
    local del=""
    askyn del "РћС‚РѕР·РІР°С‚СЊ Рё СѓРґР°Р»РёС‚СЊ СЃС‚Р°СЂС‹Р№ СЃРµСЂС‚ $old? (РєР»РёРµРЅС‚С‹ РґРѕР»Р¶РЅС‹ РїРµСЂРµР№С‚Рё РЅР° $new)" "n"
    if [[ "$del" == true ]]; then
      certbot delete --cert-name "$old" -n >/dev/null 2>&1 \
        && log "РЎС‚Р°СЂС‹Р№ СЃРµСЂС‚ $old СѓРґР°Р»С‘РЅ" \
        || warn "РќРµ СѓРґР°Р»РѕСЃСЊ СѓРґР°Р»РёС‚СЊ СЃРµСЂС‚ $old вЂ” СѓРґР°Р»Рё РІСЂСѓС‡РЅСѓСЋ: certbot delete --cert-name $old"
    fi
  fi

  echo
  ok "РџРµСЂРµРµР·Рґ Р·Р°РІРµСЂС€С‘РЅ: РїР°РЅРµР»СЊ Рё РїРѕРґРїРёСЃРєРё С‚РµРїРµСЂСЊ РЅР° $new"
  warn "  вЂў РїСЂРѕРІРµСЂСЊ РїР°РЅРµР»СЊ Рё РїРѕРґРїРёСЃРєСѓ РІ Р±СЂР°СѓР·РµСЂРµ (Ctrl+F5)"
  warn "  вЂў Сѓ РєР»РёРµРЅС‚РѕРІ РѕР±РЅРѕРІРё СЃСЃС‹Р»РєРё (РёР»Рё РїСЂРѕСЃС‚Рѕ РїРµСЂРµС‡РёС‚Р°Р№ РїРѕРґРїРёСЃРєСѓ вЂ” URL РјРµРЅСЏРµС‚СЃСЏ РЅР° $new)"
  warn "  вЂў РµСЃР»Рё decoy РїР°РЅРµР»Рё РїРѕРєР°Р·С‹РІР°Р» СЃС‚Р°СЂС‹Р№ РґРѕРјРµРЅ РІ С‚РµРєСЃС‚Рµ вЂ” СЃРјРµРЅРё С€Р°Р±Р»РѕРЅ Рї.4"
  audit "panel: РґРѕРјРµРЅ РїР°РЅРµР»Рё $old в†’ $new"
  pause
}

certs_menu() {
  while :; do
  clear
  line; echo -e "${B}   РЎР•Р РўРР¤РРљРђРўР«${N}"; line
  # Р°РєС‚РёРІРЅС‹Р№ СЃРµСЂС‚ РїР°РЅРµР»Рё РёР· РЅР°СЃС‚СЂРѕРµРє x-ui (РІ С‚.С‡. РІС‹РїСѓС‰РµРЅРЅС‹Р№ С‡РµСЂРµР· РјРµРЅСЋ x-ui)
  local db_line dc dk dd
  db_line=$(panel_cert_from_db) || true
  if [[ -n "$db_line" ]]; then
    dc="${db_line%% *}"; dk=$(echo "$db_line" | awk '{print $2}'); dd=$(echo "$db_line" | awk '{print $3}')
    echo -e "  ${G}в–ё РђРєС‚РёРІРЅС‹Р№ СЃРµСЂС‚ РїР°РЅРµР»Рё (РІРїРёСЃР°РЅ РІ x-ui):${N} ${dd:-РґРѕРјРµРЅ РЅРµ РѕРїСЂРµРґРµР»С‘РЅ}"
    echo "      cert: $dc"
    echo "      key:  $dk"
    echo "      РґРµР№СЃС‚РІСѓРµС‚ РґРѕ: $(openssl x509 -noout -enddate -in "$dc" 2>/dev/null | cut -d= -f2)"
  else
    echo "  в–ё РђРєС‚РёРІРЅС‹Р№ СЃРµСЂС‚ РїР°РЅРµР»Рё: РІ РЅР°СЃС‚СЂРѕР№РєР°С… x-ui РЅРµ РЅР°Р№РґРµРЅ"
  fi
  echo
  certbot certificates 2>/dev/null | grep -E 'Certificate Name|Domains|Expiry' | sed 's/^/  /' || true
  echo
  echo "  Wildcard Cloudflare: ${WILDCARD_DOMAIN:-РІС‹РєР»СЋС‡РµРЅ}  |  С‚РѕРєРµРЅ: ${CF_CREDS}"
  echo
  echo "  1) РћР±РЅРѕРІРёС‚СЊ РІСЃРµ СЃРµСЂС‚РёС„РёРєР°С‚С‹ (renew)"
  echo "  2) Dry-run РїСЂРѕРґР»РµРЅРёСЏ"
  echo "  3) Р’С‹РїСѓСЃС‚РёС‚СЊ wildcard (Cloudflare DNS-01)"
  echo "  4) Wildcard РІРєР»/РІС‹РєР»"
  echo "  5) Р’С‹РїСѓСЃРє СЃРµСЂС‚Р° С‡РµСЂРµР· РјРµРЅСЋ x-ui (РѕСЃРІРѕР±РѕРґРёС‚СЊ :80)"
  echo "  6) РџРѕРєР°Р·Р°С‚СЊ РґРѕРјРµРЅС‹ Рё СЃРµСЂС‚С‹ (РѕР±Р·РѕСЂ)"
  echo "  7) РЎР±СЂРѕСЃРёС‚СЊ email Let's Encrypt (СЃРїСЂРѕСЃРёС‚СЊ Р·Р°РЅРѕРІРѕ)"
  echo "  8) РџРµСЂРµРµР·Рґ РґРѕРјРµРЅР° РїР°РЅРµР»Рё (СЃРµСЂС‚/Р‘Р”/hosts/nginx)"
  echo "  9) РџРµСЂРµСЃРѕР±СЂР°С‚СЊ РјСѓР»СЊС‚РёСЃРµСЂС‚ РёР· РґРѕРјРµРЅРѕРІ РїР°РЅРµР»Рё/РёРЅР±Р°СѓРЅРґРѕРІ"
  echo "  10) Р”РѕР±Р°РІРёС‚СЊ РґРѕРјРµРЅ РІ РјСѓР»СЊС‚РёСЃРїРёСЃРѕРє"
  echo "  11) РЈРґР°Р»РёС‚СЊ РґРѕРјРµРЅ РёР· РјСѓР»СЊС‚РёСЃРїРёСЃРєР°"
  echo "  12) РђСѓРґРёС‚ СЃРµСЂС‚РѕРІ вЂ” РіРґРµ С‡С‚Рѕ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ"
  echo "  13) РЈРґР°Р»РёС‚СЊ СЃРµСЂС‚ РїРѕ РёРјРµРЅРё (СЃ РїСЂРµРґСѓРїСЂРµР¶РґРµРЅРёСЏРјРё)"
  echo "  14) Р›РѕРіРёРєР° РІС‹РїСѓСЃРєР° СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ (A/B)"
  echo "  15) РћС‡РёСЃС‚РєР° СЃРёСЂРѕС‚ (Р»РёРЅРёРё, РєРѕС‚РѕСЂС‹Рµ РЅРёРіРґРµ РЅРµ РёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ)"
  echo "  16) РћС‡РёСЃС‚РєР° РґСѓР±Р»РµР№ -0001"
  echo "  17) РђСѓРґРёС‚ Р»РёРЅРёР№ (SAN С„Р°Р№Р»Р° vs СЃРµСЂС‚)"
  echo "  18) РЈР±СЂР°С‚СЊ РґСѓР±Р»Рё РїРѕРєСЂС‹С‚РёСЏ (РґРѕРјРµРЅ РІ Р»РёРЅРёРё + РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚)"
  echo "  0) РќР°Р·Р°Рґ"
  line
  local action=""
  read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" action || action="0"
  [[ "$action" == "0" ]] && return 0
  case "$action" in
    1) certbot renew --quiet && log "OK" || true ;;
    2) certbot renew --dry-run 2>&1 | tail -20 || true ;;
    3) cert_wildcard_issue ;;
    4) wildcard_toggle ;;
    5) xui_cert_menu_helper ;;
    6) certs_view ;;
    7) le_email_forget; log "Email СЃР±СЂРѕС€РµРЅ вЂ” РїСЂРё СЃР»РµРґСѓСЋС‰РµРј РІС‹РїСѓСЃРєРµ СЃРїСЂРѕСЃРёС‚ Р·Р°РЅРѕРІРѕ"; pause ;;
    8) panel_domain_migrate ;;
    9) cert_domains_load; log "Р”РѕРјРµРЅРѕРІ РІ СЃРїРёСЃРєРµ: ${#CERT_DOMAINS[@]}"; CERT_DEFER=0; cert_batch_flush; pause ;;
    10) certs_domain_add_manual ;;
    11) certs_domain_remove_manual ;;
    12) cert_audit ;;
    13) cert_delete_menu ;;
    14) cert_mode_menu ;;
    15) cert_lines_cleanup ;;
    16) cert_dedup_0001 ;;
    17) cert_lines_audit ;;
    18) cert_cover_dedup ;;
    0) return 0 ;;
    *) sleep 1 ;;
  esac
  done
}
decoy_stats() {
  [[ -s "$DECOY_LOG_ACCESS" ]] || { warn "Р›РѕРі РґРµРєРѕ-РґРѕСЃС‚СѓРїРѕРІ РїСѓСЃС‚"; pause; return 0; }
  python3 - "$DECOY_LOG_ACCESS" <<'PY'
import sys, time, re, collections
cut = time.time() - 86400
hits = 0
ips = collections.Counter()
hosts = collections.Counter()
paths = collections.Counter()
for line in open(sys.argv[1], errors="replace"):
    m = re.match(r'(\S+) \[([^]]+)\] "([^"]*)" (\d+) "([^"]*)" host=(\S+)', line)
    if not m:
        continue
    try:
        t = time.mktime(time.strptime(m.group(2).split(" +")[0], "%d/%b/%Y:%H:%M:%S"))
    except Exception:
        continue
    if t < cut:
        continue
    hits += 1
    ips[m.group(1)] += 1
    hosts[m.group(6)] += 1
    p = m.group(3).split(" ")[1] if len(m.group(3).split(" ")) > 1 else "/"
    paths[p[:60]] += 1
print(f"  Р—Р°РїСЂРѕСЃРѕРІ Р·Р° 24С‡: {hits}")
print(f"  РЈРЅРёРєР°Р»СЊРЅС‹С… IP:   {len(ips)}")
if hosts:
    print("  РџРѕ РґРѕРјРµРЅР°Рј:")
    for h, c in hosts.most_common(10):
        print(f"    {h:40s} {c}")
if paths:
    print("  РўРѕРї РїСѓС‚РµР№:")
    for p, c in paths.most_common(8):
        print(f"    {p:42s} {c}")
if ips:
    print("  РўРѕРї IP:")
    for ip, c in ips.most_common(8):
        print(f"    {ip:42s} {c}")
PY
  pause
}

# Р·Р°Р±Р°РЅРёС‚СЊ РІСЃРµС…, РєС‚Рѕ РѕС‚РєСЂС‹РІР°Р» decoy Р·Р° N С‡Р°СЃРѕРІ
decoy_ban_watchers() {
  local hrs="" ips="" own_ip
  ask hrs "Р—Р° СЃРєРѕР»СЊРєРѕ С‡Р°СЃРѕРІ (1-168)" "24" '^[0-9]{1,3}$'
  ips=$(python3 - "$DECOY_LOG_ACCESS" "$hrs" <<'PY'
import sys, time, re
cut = time.time() - int(sys.argv[2]) * 3600
seen = []
for line in open(sys.argv[1], errors="replace"):
    m = re.match(r'(\S+) \[([^]]+)\] ', line)
    if not m:
        continue
    try:
        t = time.mktime(time.strptime(m.group(2).split(" +")[0], "%d/%b/%Y:%H:%M:%S"))
    except Exception:
        continue
    if t >= cut and m.group(1) not in seen:
        seen.append(m.group(1))
print(" ".join(seen))
PY
)
  [[ -z "$ips" ]] && { warn "РќРёРєРѕРіРѕ РЅРµ РЅР°С€Р»РѕСЃСЊ"; pause; return 0; }
  own_ip=$(curl -s --max-time 3 https://api.ipify.org 2>/dev/null || true)
  echo "  РќР°Р№РґРµРЅС‹ IP:"
  local ip banned=0 skipped=0
  for ip in $ips; do
    if [[ "$ip" == "$own_ip" ]]; then
      echo "    $ip  (С‚РІРѕР№ СЃРµСЂРІРµСЂ/РІС‹С…РѕРґ вЂ” РїСЂРѕРїСѓС‰РµРЅ)"; skipped=$((skipped+1))
    else
      echo "    $ip"
    fi
  done
  local conf="false"
  askyn conf "Р—Р°Р±Р°РЅРёС‚СЊ РІСЃРµ РќР•-СЃРµСЂРІРµСЂРЅС‹Рµ IP РІ jail decoy-login?" "n"
  if [[ "$conf" == true ]]; then
    for ip in $ips; do
      [[ "$ip" == "$own_ip" ]] && continue
      fail2ban-client set decoy-login banip "$ip" >/dev/null 2>&1 && banned=$((banned+1))
    done
    log "Р—Р°Р±Р°РЅРµРЅРѕ: $banned"
  fi
  pause
}

security_menu() {
  line; echo -e "${B}   Р‘Р•Р—РћРџРђРЎРќРћРЎРўР¬ вЂ” Р‘РђРќР«, DECOY-Р›РћР“РРќР«, FAIL2BAN${N}"; line

  # --- РґРµРєРѕ-Р»РѕРіРёРЅС‹ (jail decoy-login) ---
  echo -e "${B}в–ё Р”РµРєРѕРё (jail decoy-login)${N}"
  fail2ban-client status decoy-login 2>/dev/null | sed 's/^/  /' || echo "  jail РЅРµ Р°РєС‚РёРІРµРЅ"
  local ips=""
  ips=$(fail2ban-client get decoy-login banip 2>/dev/null || true)
  echo "  Р—Р°Р±Р°РЅРµРЅРЅС‹Рµ IP:"
  [[ -n "$ips" ]] && echo "$ips" | tr ' ' '\n' | sed 's/^/    /' || echo "    вЂ”"

  # --- РѕСЃС‚Р°Р»СЊРЅС‹Рµ jail (sshd Рё РїСЂ.) ---
  local jails j
  jails=$(fail2ban-client status 2>/dev/null | sed -n 's/^.*Jail list:\s*//p' | tr ',' ' ')
  for j in $jails; do
    [[ "$j" == "decoy-login" ]] && continue
    echo
    echo -e "${B}в–ё jail: $j${N}"
    fail2ban-client status "$j" 2>/dev/null | sed 's/^/  /'
  done

  echo
  echo "  1) Р Р°Р·Р±Р°РЅРёС‚СЊ IP"
  echo "  2) Р Р°Р·Р±Р°РЅРёС‚СЊ РІСЃРµ (РІРѕ РІСЃРµС… jail)"
  echo "  3) РћС‡РёСЃС‚РёС‚СЊ Р»РѕРі РґРµРєРѕ-РїРѕРїС‹С‚РѕРє"
  echo "  4) Р”РѕР±Р°РІРёС‚СЊ IP РІ whitelist (ignoreip)"
  echo "  5) РЎС‚Р°С‚РёСЃС‚РёРєР° decoy-РїРѕСЃРµС‰РµРЅРёР№ (24С‡)"
  echo "  6) Р—Р°Р±Р°РЅРёС‚СЊ РІСЃРµС…, РєС‚Рѕ РѕС‚РєСЂС‹РІР°Р» decoy"
  echo "  7) Р’РєР»СЋС‡РёС‚СЊ jail recidive (СЂРµС†РёРґРёРІРёСЃС‚С‹ вЂ” Р±Р°РЅ РЅР° РЅРµРґРµР»СЋ)"
  echo "  8) Р–РёРІРѕР№ Р»РѕРі fail2ban (tail -f)"
  echo "  0) РќР°Р·Р°Рґ"
  line
  local c=""
  read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
  case "$c" in
    5) decoy_stats ;;
    6) decoy_ban_watchers ;;
    7) f2b_recidive_setup; pause ;;
    8) f2b_tail ;;
    1)
      local jj="" ip=""
      ask jj "Jail (Enter вЂ” decoy-login)" "decoy-login" '^[A-Za-z0-9_-]*$'
      [[ -z "$jj" ]] && jj="decoy-login"
      ask ip "IP РґР»СЏ СЂР°Р·Р±Р°РЅР°" "" '^[0-9a-fA-F.:]+$'
      fail2ban-client set "$jj" unbanip "$ip" >/dev/null 2>&1 && { log "Р Р°Р·Р±Р°РЅРµРЅ: $ip (jail $jj)"; audit "f2b: unban $ip (jail $jj)"; } || err "РќРµ РїРѕР»СѓС‡РёР»РѕСЃСЊ вЂ” РїСЂРѕРІРµСЂСЊ jail Рё IP"
      pause
      ;;
    2)
      local ca=""
      askyn ca "РЎРЅСЏС‚СЊ Р’РЎР• Р±Р°РЅС‹ РІРѕ РІСЃРµС… jail?" "n"
      [[ "$ca" == true ]] && { fail2ban-client unban --all >/dev/null 2>&1 && { log "Р’СЃРµ Р±Р°РЅС‹ СЃРЅСЏС‚С‹"; audit "f2b: unban all"; } || err "РќРµ РІС‹С€Р»Рѕ (РїРѕС…РѕР¶Рµ, СЃС‚Р°СЂС‹Р№ fail2ban)"; }
      pause
      ;;
    3)
      : > "$DECOY_LOG_ACCESS" 2>/dev/null || true
      systemctl restart fail2ban 2>/dev/null || true
      log "Р›РѕРі РґРµРєРѕ-РїРѕРїС‹С‚РѕРє РѕС‡РёС‰РµРЅ, fail2ban РїРµСЂРµР·Р°РїСѓС‰РµРЅ"
      pause
      ;;
    4)
      local wip="" f="/etc/fail2ban/jail.local"
      ask wip "IP РёР»Рё РїРѕРґСЃРµС‚СЊ РґР»СЏ whitelist (РЅР°РїСЂ. 203.0.113.5)" "" '^[0-9a-fA-F.:/]{3,45}$'
      if [[ -f "$f" ]]; then
        if grep -qE "^ignoreip" "$f" 2>/dev/null; then
          if grep -E "^ignoreip" "$f" | grep -qw "$wip"; then
            warn "Р­С‚РѕС‚ IP СѓР¶Рµ РІ whitelist"
          else
            sed -i "s|^\(ignoreip.*\)$|\1 $wip|" "$f"
            systemctl restart fail2ban 2>/dev/null || true
            log "Whitelist РѕР±РЅРѕРІР»С‘РЅ (+$wip), fail2ban РїРµСЂРµР·Р°РїСѓС‰РµРЅ вЂ” СЌС‚РѕС‚ IP Р±РѕР»СЊС€Рµ РЅРµ Р·Р°Р±Р°РЅСЏС‚"
          fi
        else
          printf '\nignoreip = 127.0.0.1/8 %s\n' "$wip" >> "$f"
          systemctl restart fail2ban 2>/dev/null || true
          log "Whitelist СЃРѕР·РґР°РЅ (+$wip), fail2ban РїРµСЂРµР·Р°РїСѓС‰РµРЅ"
        fi
      else
        err "$f РЅРµ РЅР°Р№РґРµРЅ вЂ” fail2ban РЅР°СЃС‚СЂР°РёРІР°РµС‚СЃСЏ РІ Рї.1"
      fi
      pause
      ;;
  esac
}

# в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# DNS Xray/LucX вЂ” РіР»РѕР±Р°Р»СЊРЅС‹Р№ С€Р°Р±Р»РѕРЅ РїР°РЅРµР»Рё
# РЎРѕРІРјРµСЃС‚РёРјРѕ СЃ xrayTemplateConfig LucX/3x-ui. Р•СЃР»Рё СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅР°СЏ РїР°РЅРµР»СЊ
# РЅРµ С…СЂР°РЅРёС‚ С€Р°Р±Р»РѕРЅ РІ Р‘Р”, РёСЃРїРѕР»СЊР·СѓРµРј РµС‘ С„Р°РєС‚РёС‡РµСЃРєРёР№ config.json РєР°Рє fallback.
# в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# Р’Р°Р»РёРґР°С†РёСЏ РїРѕР»СЊР·РѕРІР°С‚РµР»СЊСЃРєРёС… Р·РЅР°С‡РµРЅРёР№ Рё СЂРµР°Р»СЊРЅР°СЏ РїСЂРѕРІРµСЂРєР° DoH.
# Regex РІ ask() РїСЂРѕРІРµСЂСЏРµС‚ С‚РѕР»СЊРєРѕ С„РѕСЂРјСѓ РІРІРѕРґР°; Р·РґРµСЃСЊ РїСЂРѕРІРµСЂСЏРµРј СЃРјС‹СЃР»:
# РґРёР°РїР°Р·РѕРЅС‹ IPv4, hostname, URL Рё РѕС‚РІРµС‚ DNS-СЃРµСЂРІРµСЂР°. РРЅР°С‡Рµ РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ
# РјРѕРі РІРІРµСЃС‚Рё С„РѕСЂРјР°Р»СЊРЅРѕ РїРѕРґС…РѕРґСЏС‰РµРµ, РЅРѕ Р·Р°РІРµРґРѕРјРѕ РЅРµСЂР°Р±РѕС‡РµРµ Р·РЅР°С‡РµРЅРёРµ.
dns_validate_ipv4() {
  local ip="$1" oct
  [[ "$ip" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
  IFS=. read -r -a octs <<< "$ip"
  for oct in "${octs[@]}"; do
    (( oct <= 255 )) || return 1
  done
  return 0
}
dns_validate_hostname() {
  local h="$1"
  [[ -n "$h" && "$h" != .* && "$h" != *.*. && "$h" != *..* ]] || return 1
  [[ "$h" =~ ^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$ ]] || return 1
  [[ ${#h} -le 253 ]] || return 1
  return 0
}
dns_validate_doh() {
  local url="$1" host="$2" ip="$3" parsed_host code body q endpoint_host
  dns_validate_ipv4 "$ip" || { err "IPv4 DoH РЅРµРєРѕСЂСЂРµРєС‚РµРЅ РёР»Рё СЃРѕРґРµСЂР¶РёС‚ РѕРєС‚РµС‚ >255: $ip"; return 1; }
  [[ -n "$host" ]] || { err "DoH host РЅРµ Р·Р°РґР°РЅ"; return 1; }
  for endpoint_host in $host; do
    dns_validate_hostname "$endpoint_host" || { err "DoH host РЅРµРєРѕСЂСЂРµРєС‚РµРЅ: $endpoint_host"; return 1; }
  done
  [[ "$url" =~ ^https://[^/[:space:]]+/[^[:space:]]+$ ]] || {
    err "URL DoH РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ HTTPS-Р°РґСЂРµСЃРѕРј СЃ РїСѓС‚С‘Рј, РЅР°РїСЂРёРјРµСЂ https://dns.example/dns-query"; return 1;
  }
  parsed_host="${url#https://}"; parsed_host="${parsed_host%%/*}"
  [[ " $host " == *" $parsed_host "* ]] || {
    err "Host ($host) РЅРµ СЃРѕРґРµСЂР¶РёС‚ host РёР· URL DoH ($parsed_host)"; return 1;
  }
  endpoint_host="$parsed_host"
  # Р—Р°РїСЂРѕСЃ A РґР»СЏ example.com: РїСЂРѕРІРµСЂСЏРµРј РёРјРµРЅРЅРѕ DNS-РѕС‚РІРµС‚, Р° РЅРµ РїСЂРѕСЃС‚Рѕ TCP/HTTP.
  q='q80BAAABAAAAAAAAA3d3dwZnb29nbGUDY29tAAABAAE'
  body=$(mktemp /tmp/stack-doh-test.XXXXXX) || return 1
  code=$(curl -4 -ksS --max-time 8 --retry 1 --resolve "${endpoint_host}:443:${ip}" \
    -H 'accept: application/dns-message' \
    -H 'content-type: application/dns-message' \
    -o "$body" -w '%{http_code}' "${url}?dns=${q}" 2>/dev/null || true)
  if [[ "$code" != "200" ]] || ! python3 - "$body" <<'PYDNSCHECK'
import sys
p=sys.argv[1]
data=open(p,'rb').read()
# DNS header: 12 bytes; QR=1, RCODE=0, РјРёРЅРёРјСѓРј РѕРґРёРЅ РѕС‚РІРµС‚.
ok=(len(data)>=12 and (data[2] & 0x80) and (data[3] & 0x0f)==0 and int.from_bytes(data[6:8],'big')>0)
raise SystemExit(0 if ok else 1)
PYDNSCHECK
  then
    rm -f "$body"
    err "DoH РЅРµ РїСЂРѕС€С‘Р» СЂРµР°Р»СЊРЅСѓСЋ DNS-РїСЂРѕРІРµСЂРєСѓ: $url С‡РµСЂРµР· $ip (HTTP $code, РѕС‚РІРµС‚ РЅРµ СЃРѕРґРµСЂР¶РёС‚ СѓСЃРїРµС€РЅС‹Р№ A-РѕС‚РІРµС‚)"
    return 1
  fi
  rm -f "$body"
  ok "DoH РѕС‚РІРµС‡Р°РµС‚ Рё СЂРµР°Р»СЊРЅРѕ СЂРµР·РѕР»РІРёС‚ DNS: $url в†’ $ip"
  return 0
}

xray_dns_apply() {
  local mode="$1" doh_url="${2:-}" doh_host="${3:-}" doh_ip="${4:-}"
  case "$mode" in
    1) doh_url=""; doh_host=""; doh_ip="" ;;
