# РћРїСЂРµРґРµР»РёС‚СЊ РІРЅРµС€РЅРёР№ РґРѕРјРµРЅ AdGuard Home РїРѕ С„Р°РєС‚РёС‡РµСЃРєРѕР№ РєРѕРЅС„РёРіСѓСЂР°С†РёРё.
# РџСЂРё РѕС‚РґРµР»СЊРЅРѕРј SNI DoH Р¶РёРІС‘С‚ РЅР° adguard.<Р·РѕРЅР°>, Р° РЅРµ РЅР° РґРѕРјРµРЅРµ РїР°РЅРµР»Рё.
xray_adguard_doh_endpoint() {
  local panel="${PANEL_DOMAIN:-}" dom="" block=""
  [[ -n "$panel" ]] || panel=$(xui_get webDomain 2>/dev/null || true)
  [[ "$panel" == "null" ]] && panel=""
  # РџСЂРёРѕСЂРёС‚РµС‚ вЂ” СЂРµР°Р»СЊРЅС‹Р№ SNI-map: РѕРЅ РїРѕРєР°Р·С‹РІР°РµС‚, РєСѓРґР° nginx РѕС‚РїСЂР°РІР»СЏРµС‚ DoH.
  if [[ -f "$SNI_CONF" ]]; then
    dom=$(awk '$2 == "agh_backend;" {print $1; exit}' "$SNI_CONF" 2>/dev/null || true)
  fi
  if [[ -n "$dom" ]]; then
    printf '%s' "$dom"
    return 0
  fi
  # Р•СЃР»Рё РѕС‚РґРµР»СЊРЅРѕРіРѕ SNI РЅРµС‚, РїСЂРѕРІРµСЂСЏРµРј proxy AdGuard РІ РєРѕСЂРЅРµРІРѕРј Р±Р»РѕРєРµ РїР°РЅРµР»Рё.
  if [[ -f "$STACK_CONF" ]] && grep -q "listen 127.0.0.1:4443" "$STACK_CONF" 2>/dev/null; then
    block=$(sed -n '/listen 127\.0\.0\.1:4443/,/^}/p' "$STACK_CONF" 2>/dev/null || true)
    if grep -q "proxy_pass https://127\.0\.0\.1:" <<< "$block"; then
      printf '%s' "$panel"
      return 0
    fi
  fi
  return 1
}

