  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” СЃРЅР°С‡Р°Р»Р° СѓСЃС‚Р°РЅРѕРІРёС‚Рµ РїР°РЅРµР»СЊ"; return 1; }
  line; echo -e "${B}   DNS Р’ РџРђРќР•Р›Р LUCX/3X-UI${N}"; line
  echo "  1) РЎРёСЃС‚РµРјРЅС‹Р№ DNS (СѓР±СЂР°С‚СЊ СѓРїСЂР°РІР»СЏРµРјС‹Р№ С€Р°Р±Р»РѕРЅ)"
  echo "  2) DoH Cloudflare (1.1.1.1)"
  echo "  3) DoH Google (8.8.8.8)"
  echo "  4) DoH Quad9 (9.9.9.9)"
  echo "  5) Self-hosted DoH AdGuard (РґРѕРјРµРЅ РёР· SNI, IP Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё)"
  echo "  6) РЎРІРѕР№ DoH (РІРІРµСЃС‚Рё URL, host Рё IP РІСЂСѓС‡РЅСѓСЋ)"
  local mode="" url="" host="" ip=""
  ask mode "РџСЂРѕС„РёР»СЊ DNS" "2" '^[1-6]$'
  case "$mode" in
    5)
      ip=$(server_ip4)
      host=$(xray_adguard_doh_endpoint 2>/dev/null || true)
      [[ -n "$host" && -n "$ip" ]] || {
        err "РќРµ РЅР°Р№РґРµРЅ РІРЅРµС€РЅРёР№ РґРѕРјРµРЅ AdGuard Home РІ SNI/nginx-РєРѕРЅС„РёРіСѓСЂР°С†РёРё вЂ” DNS РЅРµ РёР·РјРµРЅС‘РЅ"; return 1;
      }
      url="https://${host}/dns-query"
      echo "  Self-hosted AdGuard: $url"; echo "  hosts: $host в†’ $ip" ;;
    6)
      ask url "URL DoH (РЅР°РїСЂРёРјРµСЂ https://dns.example/dns-query)" "https://" '^https://[^[:space:]]+$'
      ask host "DoH host РґР»СЏ hosts" "" '^[a-zA-Z0-9.-]+$'
      ask ip "IPv4 DoH host" "" '^([0-9]{1,3}\.){3}[0-9]{1,3}$' ;;
  esac
  xray_dns_apply "$mode" "$url" "$host" "$ip"
  pause
}

# =====================================================================
# FIREWALL
# =====================================================================

fw_allow() {
  local port="$1" proto="$2" comment="${3:-}"
  [[ -z "$port" || "$port" == "0" ]] && return 0
  local args=(allow)
  [[ -n "$comment" ]] && args+=(comment "$comment")
  ufw "${args[@]}" "$port/$proto" >/dev/null 2>&1 || true
}

# SSH В«С‡РµСЂРµР· С‚СѓРЅРЅРµР»СЊВ»: sshd СЃР»СѓС€Р°РµС‚ С‚РѕР»СЊРєРѕ loopback в†’ РїРѕСЂС‚ РЅР°СЂСѓР¶Сѓ РЅРµ РѕС‚РєСЂС‹РІР°РµРј.
# РџРѕСЂС‚ Р±РµСЂС‘Рј РёР· SSH_PORT (sshd РјРѕРі РїРµСЂРµРµС…Р°С‚СЊ СЃ 22 вЂ” СЂР°РЅСЊС€Рµ РїСЂРѕРІРµСЂРєРё Р±С‹Р»Рё РЅР°
# С…Р°СЂРґРєРѕРґ 22 Рё РЅР° РєР°СЃС‚РѕРјРЅРѕРј РїРѕСЂС‚Сѓ РѕС€РёР±РѕС‡РЅРѕ РѕС‚РєСЂС‹РІР°Р»Рё SSH РЅР°СЂСѓР¶Сѓ).
ssh_loopback_only() {
  local sp="${SSH_PORT:-22}"
  ss -tln 2>/dev/null | grep -qE "127\.0\.0\.1:${sp}([[:space:]]|$)" && return 0
  ss -tln 2>/dev/null | grep -qE "\[::1\]:${sp}([[:space:]]|$)" && return 0
  return 1
}

# РџРµСЂРµРєР»СЋС‡РµРЅРёРµ web/sub-РїРѕСЂС‚РѕРІ x-ui РјРµР¶РґСѓ loopback Рё РІРЅРµС€РЅРёРј СЃР»СѓС€Р°С‚РµР»РµРј.
# РСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ TUI С„Р°Р№СЂРІРѕР»Р°: РёР·РјРµРЅРµРЅРёРµ РїСЂРёРІСЏР·РєРё Рё РїСЂР°РІРёР»Р° UFW РІС‹РїРѕР»РЅСЏСЋС‚СЃСЏ
# РѕРґРЅРѕР№ РѕРїРµСЂР°С†РёРµР№, С‡С‚РѕР±С‹ РёРЅС‚РµСЂС„РµР№СЃ РЅРµ РїРѕРєР°Р·С‹РІР°Р» СЂР°СЃСЃРёРЅС…СЂРѕРЅРёР·РёСЂРѕРІР°РЅРЅРѕРµ СЃРѕСЃС‚РѕСЏРЅРёРµ.
xui_set_listen() {
  # РЎРѕРІРјРµСЃС‚РёРјРѕСЃС‚СЊ СЃ TUI: xui_set_listen <port> <mode> Рё СЃС‚Р°СЂС‹Рј
  # РІРЅСѓС‚СЂРµРЅРЅРёРј РІС‹Р·РѕРІРѕРј xui_set_listen <mode>. РќР°СЃС‚СЂРѕР№РєРё web/sub РѕР±С‰РёРµ.
  local mode="$1" db=""
  [[ "$mode" =~ ^[0-9]+$ ]] && mode="${2:-}"
  [[ "$mode" == "0.0.0.0" || "$mode" == "127.0.0.1" ]] || return 1
  for db in /etc/x-ui/x-ui.db /usr/local/x-ui/x-ui.db /opt/x-ui/x-ui.db; do
    [[ -f "$db" ]] && break
  done
  [[ -f "$db" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  systemctl stop x-ui >/dev/null 2>&1 || true
  local ok=1
  # Р’РђР–РќРћ: РµСЃР»Рё РєР»СЋС‡РµР№ webListen/subListen РІ settings РµС‰С‘ РЅРµС‚, UPDATE РјРµРЅСЏРµС‚
  # 0 СЃС‚СЂРѕРє Рё В«СѓСЃРїРµС€РЅРѕВ» РЅРёС‡РµРіРѕ РЅРµ РґРµР»Р°РµС‚ вЂ” РїСЂРё СЃРєСЂС‹С‚РёРё РїР°РЅРµР»СЊ РѕСЃС‚Р°Р»Р°СЃСЊ Р±С‹ РЅР°
  # 0.0.0.0 РїСЂРё СЂР°РїРѕСЂС‚Рµ В«СЃРїСЂСЏС‚Р°РЅВ». РџРѕСЃР»Рµ UPDATE РїСЂРѕРІРµСЂСЏРµРј РЅР°Р»РёС‡РёРµ РѕР±РѕРёС… РєР»СЋС‡РµР№
  # Рё РІСЃС‚Р°РІР»СЏРµРј РЅРµРґРѕСЃС‚Р°СЋС‰РёРµ (upsert).
  if command -v sqlite3 >/dev/null 2>&1; then
    sqlite3 "$db" "UPDATE settings SET value='$mode' WHERE key IN ('webListen','subListen');" >/dev/null 2>&1 || ok=0
    if [[ "$ok" == 1 ]]; then
      local nkeys
      nkeys=$(sqlite3 "$db" "SELECT count(*) FROM settings WHERE key IN ('webListen','subListen');" 2>/dev/null || echo 0)
      if [[ "$nkeys" != "2" ]]; then
        sqlite3 "$db" "INSERT OR REPLACE INTO settings(key,value) VALUES('webListen','$mode'),('subListen','$mode');" >/dev/null 2>&1 || ok=0
      fi
    fi
  else
    ok=0
  fi
  if [[ "$ok" == 0 ]] && command -v python3 >/dev/null 2>&1; then
    python3 - "$db" "$mode" <<'PYX'
import sqlite3, sys
con = sqlite3.connect(sys.argv[1])
cur = con.cursor()
cur.execute("UPDATE settings SET value=? WHERE key IN ('webListen','subListen')", (sys.argv[2],))
n = con.execute("SELECT count(*) FROM settings WHERE key IN ('webListen','subListen')").fetchone()[0]
if n < 2:
    cur.execute("INSERT OR REPLACE INTO settings(key,value) VALUES('webListen',?),('subListen',?)",
                (sys.argv[2], sys.argv[2]))
con.commit(); con.close()
PYX
    ok=$?
  fi
  systemctl start x-ui >/dev/null 2>&1 || true
  [[ "$ok" == 0 ]] && return 1
  sleep 2
  return 0
}

# РџРѕСЂС‚С‹, РєРѕС‚РѕСЂС‹Рµ РќРРљРћР“Р”Рђ РЅРµ РѕС‚РєСЂС‹РІР°СЋС‚СЃСЏ РЅР°СЂСѓР¶Сѓ (СЃР»СѓР¶РµР±РЅС‹Рµ/СЃРёСЃС‚РµРјРЅС‹Рµ/Р°РјР»РёС„РёРєР°С†РёРё)
fw_port_locked() {
  local port="$1"
  case "$port" in
    53)          return 0;;  # DNS вЂ” С‚РѕР»СЊРєРѕ localhost (amplification)
    323)         return 0;;  # chrony cmdmon
    6010|6011|6012|6013|6014|6015|6016|6017|6018|6019)
                             return 0;;  # X11 forwarding sshd
    46002)       return 0;;  # СЃР»СѓР¶РµР±РЅС‹Р№ web csqtt (46000+2) вЂ” С‚РѕР»СЊРєРѕ localhost
    11443)       return 0;;  # tproxy (TG web-proxy): РЅР°СЂСѓР¶Сѓ РўРћР›Р¬РљРћ С‡РµСЂРµР· 443;
                             # UDP-СЃРѕРєРµС‚ Р·РґРµСЃСЊ вЂ” HTTP/3 caddy, СЃРІРµС‚РёС‚СЊ РЅРµР»СЊР·СЏ
  esac
  return 1
}

# РЇРІРЅРѕРµ Р·Р°РєСЂС‹С‚РёРµ РїРѕСЂС‚РѕРІ РїР°РЅРµР»Рё/РїРѕРґРїРёСЃРѕРє РЅР°СЂСѓР¶Сѓ (СЃС‚СЂР°С…РѕРІРєР° РїСЂРё default allow)
fw_deny_panel_ports() {
  command -v ufw >/dev/null 2>&1 || return 0
  # PANEL_PORT/SUB_PORT РёР·РІРµСЃС‚РЅС‹ РїРѕСЃР»Рµ initial_setup; РёРЅР°С‡Рµ Р±РµСЂС‘Рј РёР· Р‘Р” РїР°РЅРµР»Рё
  local pp="${PANEL_PORT:-}" sp="${SUB_PORT:-}"
  [[ -z "$pp" || "$pp" == "0" ]] && pp=$(xui_get webPort 2>/dev/null || true)
  [[ -z "$sp" || "$sp" == "0" ]] && sp=$(xui_get subPort 2>/dev/null || true)
  local p
  for p in "$pp" "$sp"; do
    [[ -z "$p" || "$p" == "0" ]] && continue
    ufw deny "$p/tcp" >/dev/null 2>&1 || true
  done
}

# РћСЃРЅРѕРІРЅРѕР№ РёРЅС‚РµСЂС„РµР№СЃ firewall вЂ” СЃСЂР°Р·Сѓ РєРѕРјРїР°РєС‚РЅС‹Р№ TUI РѕР±Р·РѕСЂР° СЃРѕРєРµС‚РѕРІ Рё РїСЂР°РІРёР».
# РџРѕР»РЅРѕРµ СЃС‚Р°СЂРѕРµ РјРµРЅСЋ РґРѕСЃС‚СѓРїРЅРѕ РєР»Р°РІРёС€РµР№ m РёР· РѕСЃРЅРѕРІРЅРѕРіРѕ TUI.
firewall_menu_legacy() {
  while :; do
    clear
    line; echo -e "${B}   Р¤РђР™Р Р’РћР› (UFW)${N}"; line
    echo "  РЎС‚Р°С‚СѓСЃ: $(ufw status 2>/dev/null | head -1 | awk '{print $2}' || echo unknown)"
    local pol="allowlist"
    [[ -f "$BACKUP_DIR/fw-policy" ]] && pol=$(head -n1 "$BACKUP_DIR/fw-policy" 2>/dev/null | tr -d '[:space:]')
    [[ "$pol" != "hideonly" ]] && pol="allowlist"
    local pol_desc="allowlist вЂ” В«РІСЃС‘ Р·Р°РєСЂС‹С‚СЊ, РєСЂРѕРјРµ СЃРїРёСЃРєР°В» (reset + С‚РѕР»СЊРєРѕ РЅСѓР¶РЅРѕРµ)"
    [[ "$pol" == "hideonly" ]] && pol_desc="hide-only вЂ” В«Р·Р°РєСЂС‹С‚СЊ С‚РѕР»СЊРєРѕ СЃРїСЂСЏС‚Р°РЅРЅРѕРµВ» (Р±РµР· reset, deny РґР»СЏ РїР°РЅРµР»СЊРЅС‹С…/11443)"
    echo "  РџРѕР»РёС‚РёРєР°: $pol_desc"
    echo
    declare -A REQ=()
    # SSH С‚РѕР»СЊРєРѕ С‡РµСЂРµР· С‚СѓРЅРЅРµР»СЊ? (sshd СЃР»СѓС€Р°РµС‚ loopback) вЂ” 22 РЅР°СЂСѓР¶Сѓ РЅРµ РѕС‚РєСЂС‹РІР°РµРј
    if ss -tln 2>/dev/null | grep -qE '127\.0\.0\.1:22([[:space:]]|$)'; then
      echo "  SSH: С‚РѕР»СЊРєРѕ С‡РµСЂРµР· С‚СѓРЅРЅРµР»СЊ (loopback) вЂ” 22 РЅР°СЂСѓР¶Сѓ РЅРµ РѕС‚РєСЂС‹РІР°РµРј"
    else
      REQ["tcp:$SSH_PORT"]="SSH"
    fi
    # tcp/80 РќР• РѕС‚РєСЂС‹РІР°РµРј: СЃРµСЂС‚РёС„РёРєР°С‚С‹ вЂ” wildcard С‡РµСЂРµР· DNS-С…СѓРє (DNS-01),
    # HTTP-01 РЅРµ РЅСѓР¶РµРЅ; РїСЂРё РЅРµРѕР±С…РѕРґРёРјРѕСЃС‚Рё РѕС‚РєСЂС‹С‚СЊ СЂР°Р·РѕРІРѕ: ufw allow 80/tcp
    systemctl is-active --quiet nginx 2>/dev/null && REQ["tcp:443"]="HTTPS/SNI"
    # UDP вЂ” С‚РѕР»СЊРєРѕ РёРЅР±Р°СѓРЅРґС‹ РёР· Р‘Р” РїР°РЅРµР»Рё (СЃРѕРєРµС‚С‹ С‡СЂРµР·РјРµСЂРЅРѕ С€СѓРјСЏС‚: ephemeral)
    local up
    for up in $(udp_inbound_ports); do
      fw_port_locked "$up" && continue
      REQ["udp:$up"]="udp-РёРЅР±Р°СѓРЅРґ (РїР°РЅРµР»СЊ)"
    done
    # РЎР’РћР РїРѕСЂС‚С‹ (Рї.9): С‚Рѕ, С‡С‚Рѕ Р·Р°РїСЂРµС‰РµРЅРѕ Р·Р°РєСЂС‹РІР°С‚СЊ Р»СЋР±РѕР№ РїРѕР»РёС‚РёРєРѕР№ (С„Р°Р№Р» РїСЂРѕС‚Рѕ/РїРѕСЂС‚)
    declare -A EXTRA=()
    if [[ -s "$BACKUP_DIR/fw-extra" ]]; then
      local ex_proto ex_port
      while IFS=/ read -r ex_proto ex_port; do
        [[ "$ex_proto" =~ ^(tcp|udp)$ && "$ex_port" =~ ^[0-9]+$ ]] || continue
        EXTRA["${ex_proto}:${ex_port}"]="СЃРІРѕР№ РїРѕСЂС‚ вЂ” РЅРµ Р·Р°РєСЂС‹РІР°С‚СЊ"
      done < "$BACKUP_DIR/fw-extra"
    fi

    echo "в–ё РћС‚РєСЂС‹С‚С‹РјРё Р‘РЈР”РЈРў:"
    local k
    for k in $(printf '%s\n' "${!REQ[@]}" | sort -t: -k1,1 -k2,2n); do
      printf "  %-6s %-6s %s\n" "${k%%:*}" "${k##*:}" "${REQ[$k]}"
    done
    if [[ ${#EXTRA[@]} -gt 0 ]]; then
      echo "в–ё РџР»СЋСЃ РЎР’РћР РїРѕСЂС‚С‹ (Рї.9 вЂ” РїРѕР»РёС‚РёРєР°РјРё РЅРµ Р·Р°РєСЂС‹РІР°СЋС‚СЃСЏ):"
      for k in $(printf '%s\n' "${!EXTRA[@]}" | sort -t: -k1,1 -k2,2n); do
        printf "  %-6s %-6s %s\n" "${k%%:*}" "${k##*:}" "${EXTRA[$k]}"
      done
    fi
    echo
    line
    echo "  1) РџР РРњР•РќРРўР¬"
    echo "  2) Р’РєР»СЋС‡РёС‚СЊ UFW"
    echo "  3) Р’С‹РєР»СЋС‡РёС‚СЊ UFW"
    echo "  4) РџРѕРєР°Р·Р°С‚СЊ РїСЂР°РІРёР»Р°"
    echo "  5) РЈРґР°Р»РёС‚СЊ РїСЂР°РІРёР»Рѕ РїРѕ РЅРѕРјРµСЂСѓ"
    echo "  6) РЎРјРµРЅРёС‚СЊ РїРѕР»РёС‚РёРєСѓ С„Р°Р№СЂРІРѕР»Р°"
    echo "  7) РЎРЅРёРјРѕРє СЃРѕСЃС‚РѕСЏРЅРёСЏ"
    echo "  8) Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ РёР· СЃРЅРёРјРєР°"
    echo "  9) РЎРІРѕРё РїРѕСЂС‚С‹ вЂ” РґРѕР±Р°РІРёС‚СЊ/СѓР±СЂР°С‚СЊ (РЅРµ Р·Р°РєСЂС‹РІР°СЋС‚СЃСЏ РїРѕР»РёС‚РёРєР°РјРё)"
    echo "  10) РћР±Р·РѕСЂ РїРѕСЂС‚РѕРІ: СЃРѕРєРµС‚ Г— РїСЂР°РІРёР»Рѕ UFW (Р±С‹СЃС‚СЂС‹Р№ СЃРїРёСЃРѕРє)"
    echo "  0) РќР°Р·Р°Рґ"
    line
    local c=""
    read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
    case "$c" in
      1)
        if [[ "$pol" == "hideonly" ]]; then
          askyn confirm "РџСЂРёРјРµРЅРёС‚СЊ hide-only? (РїСЂР°РІРёР»Р° РќР• СЃР±СЂР°СЃС‹РІР°СЋС‚СЃСЏ: РїР°РЅРµР»СЊРЅС‹Рµ/11443 Р·Р°РєСЂС‹РІР°СЋС‚СЃСЏ СЏРІРЅРѕ)" "n"
          [[ "$confirm" == true ]] || continue
          save_firewall_state
          if ! ssh_loopback_only; then
            fw_allow "$SSH_PORT" tcp "SSH"
          fi
          systemctl is-active --quiet nginx 2>/dev/null && fw_allow 443 tcp "HTTPS/SNI"
          # СЃРІРѕРё РїРѕСЂС‚С‹ РѕС‚РєСЂС‹РІР°РµРј СЏРІРЅРѕ (idempotent) вЂ” РїРѕР»РёС‚РёРєРѕР№ РЅРµ Р·Р°РєСЂС‹РІР°СЋС‚СЃСЏ
          local kk
          for kk in "${!EXTRA[@]}"; do
            fw_allow "${kk##*:}" "${kk%%:*}" "СЃРІРѕР№ РїРѕСЂС‚"
          done
          local hp
          for hp in "$(xui_get webPort 2>/dev/null)" "$(xui_get subPort 2>/dev/null)" 11443; do
            [[ -z "$hp" || "$hp" == "0" ]] && continue
            ufw delete allow "$hp/tcp" >/dev/null 2>&1 || true
            ufw delete allow "$hp/udp" >/dev/null 2>&1 || true
            ufw deny "$hp/tcp" >/dev/null 2>&1 || true
          done
          fw_deny_panel_ports
          ufw --force enable >/dev/null 2>&1 || true
          log "hide-only РїСЂРёРјРµРЅРµРЅРѕ: РїР°РЅРµР»СЊРЅС‹Рµ/СЃР»СѓР¶РµР±РЅС‹Рµ Р·Р°РєСЂС‹С‚С‹ СЏРІРЅРѕ, РѕСЃС‚Р°Р»СЊРЅРѕРµ РЅРµ С‚СЂРѕРЅСѓС‚Рѕ"
        else
          askyn confirm "РџСЂРёРјРµРЅРёС‚СЊ? (allowlist: reset + РѕС‚РєСЂС‹С‚СЊ С‚РѕР»СЊРєРѕ СЃРїРёСЃРѕРє РЅРёР¶Рµ)" "n"
          [[ "$confirm" == true ]] || continue
          save_firewall_state
          ufw --force reset >/dev/null 2>&1 || true
          ufw default deny incoming >/dev/null 2>&1 || true
          ufw default allow outgoing >/dev/null 2>&1 || true
          # SSH-С‚СѓРЅРЅРµР»СЊ: РµСЃР»Рё sshd СЃР»СѓС€Р°РµС‚ С‚РѕР»СЊРєРѕ loopback вЂ” РЅР°СЂСѓР¶Сѓ РЅРµ РѕС‚РєСЂС‹РІР°РµРј
          if ! ssh_loopback_only; then
            fw_allow "$SSH_PORT" tcp "SSH"
          else
            ufw delete allow "${SSH_PORT}/tcp" >/dev/null 2>&1 || true
          fi
          for k in "${!REQ[@]}"; do
            local pr="${k%%:*}" pt="${k##*:}"
            [[ "$pr:$pt" == "tcp:$SSH_PORT" ]] && continue
            fw_allow "$pt" "$pr" "${REQ[$k]}"
          done
          # СЃРІРѕРё РїРѕСЂС‚С‹ вЂ” РІСЃРµРіРґР° РѕС‚РєСЂС‹С‚С‹ (РїРѕСЃР»Рµ reset РёС… РЅСѓР¶РЅРѕ РІРµСЂРЅСѓС‚СЊ)
          local kk
          for kk in "${!EXTRA[@]}"; do
            fw_allow "${kk##*:}" "${kk%%:*}" "СЃРІРѕР№ РїРѕСЂС‚"
          done
          # РїРѕСЂС‚С‹ РїР°РЅРµР»Рё/РїРѕРґРїРёСЃРѕРє РЅР°СЂСѓР¶Сѓ Р·Р°РєСЂС‹С‚С‹ СЏРІРЅРѕ (РѕРЅРё Р¶РёРІСѓС‚ РЅР° 127.0.0.1)
          fw_deny_panel_ports
          ufw --force enable >/dev/null 2>&1 || true
          log "РџСЂРёРјРµРЅРµРЅРѕ (allowlist)"
        fi
        pause
        ;;
      6)
        echo "  РџРѕР»РёС‚РёРєРё:"
        echo "   1) allowlist вЂ” В«РІСЃС‘ Р·Р°РєСЂС‹С‚СЊ, РєСЂРѕРјРµ СЃРїРёСЃРєР°В»: reset, РЅР°СЂСѓР¶Сѓ С‚РѕР»СЊРєРѕ SSH/443/UDP-РёРЅР±Р°СѓРЅРґС‹ + СЃРІРѕРё РїРѕСЂС‚С‹ (Рї.9)"
        echo "   2) hide-only вЂ” В«Р·Р°РєСЂС‹С‚СЊ С‚РѕР»СЊРєРѕ СЃРїСЂСЏС‚Р°РЅРЅРѕРµВ»: Р±РµР· reset; deny РґР»СЏ РїР°РЅРµР»СЊРЅС‹С… РїРѕСЂС‚РѕРІ Рё 11443;"
        echo "      СЃРІРѕРё РїРѕСЂС‚С‹ (Рї.9) РѕС‚РєСЂС‹РІР°СЋС‚СЃСЏ СЏРІРЅРѕ, РѕСЃС‚Р°Р»СЊРЅРѕРµ РѕСЃС‚Р°С‘С‚СЃСЏ РєР°Рє РµСЃС‚СЊ"
        local pc=""; ask pc "РџРѕР»РёС‚РёРєР°" "$pol" '^[12]$'
        case "$pc" in
          1) printf 'allowlist\n' > "$BACKUP_DIR/fw-policy"; log "РџРѕР»РёС‚РёРєР°: allowlist" ;;
          2) mkdir -p "$BACKUP_DIR" 2>/dev/null; printf 'hideonly\n' > "$BACKUP_DIR/fw-policy"; log "РџРѕР»РёС‚РёРєР°: hide-only" ;;
        esac
        pause ;;
      2) ufw --force enable 2>&1 | sed 's/^/  /'; pause ;;
      3) ufw disable 2>&1 | sed 's/^/  /'; pause ;;
      4) ufw status numbered 2>&1 | sed 's/^/  /'; pause ;;
      5) ufw status numbered 2>&1 | sed 's/^/  /'
         local n=""; ask n "РќРѕРјРµСЂ" "0" '^[0-9]+$'
         [[ "$n" == 0 ]] && continue
         ufw --force delete "$n" 2>&1 | sed 's/^/  /'; pause ;;
      7) save_firewall_state; pause ;;
      8) restore_firewall_state ;;
      9)
        echo "  РЎРІРѕРё РїРѕСЂС‚С‹ (РІСЃРµРіРґР° РѕС‚РєСЂС‹С‚С‹; allowlist РёС… СЃРѕС…СЂР°РЅСЏРµС‚, hide-only вЂ” РѕС‚РєСЂС‹РІР°РµС‚ СЏРІРЅРѕ):"
        if [[ -s "$BACKUP_DIR/fw-extra" ]]; then
          nl -ba "$BACKUP_DIR/fw-extra" | sed 's/^/    /'
        else
          echo "    (РїСѓСЃС‚Рѕ)"
        fi
        echo "   1) Р”РѕР±Р°РІРёС‚СЊ РїРѕСЂС‚"
        echo "   2) РЈР±СЂР°С‚СЊ РїРѕСЂС‚"
        echo "   0) РќР°Р·Р°Рґ"
        local sc9=""; ask sc9 "Р’С‹Р±РѕСЂ" "0" '^[0-9]$'
        case "$sc9" in
          1)
            local ep=""; ask ep "РџРѕСЂС‚" "" '^[0-9]+$'
            [[ -z "$ep" ]] && continue
            if fw_port_locked "$ep"; then
              warn "  РџРѕСЂС‚ $ep вЂ” СЃР»СѓР¶РµР±РЅС‹Р№ (СЃРєСЂС‹С‚С‹Рµ РїР°РЅРµР»Рё/DNS/amplification), РЅР°СЂСѓР¶Сѓ РѕС‚РєСЂС‹РІР°С‚СЊ РЅРµР»СЊР·СЏ"
              pause; continue
            fi
            local epr=""; ask epr "РџСЂРѕС‚РѕРєРѕР» tcp/udp" "tcp" '^(tcp|udp)$'
            mkdir -p "$BACKUP_DIR" 2>/dev/null
            if grep -qxE "${epr}/${ep}" "$BACKUP_DIR/fw-extra" 2>/dev/null; then
              echo "  РЈР¶Рµ РІ СЃРїРёСЃРєРµ"; pause; continue
            fi
            printf '%s/%s\n' "$epr" "$ep" >> "$BACKUP_DIR/fw-extra"
            fw_allow "$ep" "$epr" "СЃРІРѕР№ РїРѕСЂС‚"
            log "РЎРІРѕР№ РїРѕСЂС‚ $epr/$ep: РґРѕР±Р°РІР»РµРЅ РІ РёСЃРєР»СЋС‡РµРЅРёСЏ С„Р°Р№СЂРІРѕР»Р° Рё РѕС‚РєСЂС‹С‚ СЃСЂР°Р·Сѓ"
            ;;
          2)
            [[ -s "$BACKUP_DIR/fw-extra" ]] || { echo "  РЎРїРёСЃРѕРє РїСѓСЃС‚"; pause; continue; }
            local en=""; ask en "РќРѕРјРµСЂ СЃС‚СЂРѕРєРё" "0" '^[0-9]+$'
            [[ -z "$en" || "$en" == 0 ]] && continue
            local dline
            dline=$(sed -n "${en}p" "$BACKUP_DIR/fw-extra")
            [[ -z "$dline" ]] && continue
            ufw delete allow "${dline##*/}/${dline%%/*}" >/dev/null 2>&1 || true
            sed -i "${en}d" "$BACKUP_DIR/fw-extra"
            log "РЎРІРѕР№ РїРѕСЂС‚ СѓР±СЂР°РЅ РёР· РёСЃРєР»СЋС‡РµРЅРёР№: $dline (РїСЂР°РІРёР»Рѕ UFW СЃРЅСЏС‚Рѕ)"
            ;;
        esac
        pause ;;
      10) firewall_apply_menu; pause ;;
      0) return 0 ;;
      *) sleep 1 ;;
    esac
  done
}

firewall_menu() {
  # РћСЃРЅРѕРІРЅРѕР№ СЌРєСЂР°РЅ вЂ” РєР»Р°СЃСЃРёС‡РµСЃРєРѕРµ РјРµРЅСЋ СѓРїСЂР°РІР»РµРЅРёСЏ UFW.
  # TUI СЃРѕРєРµС‚РѕРІ РѕСЃС‚Р°С‘С‚СЃСЏ РѕС‚РґРµР»СЊРЅС‹Рј РїСѓРЅРєС‚РѕРј 10 РІРЅСѓС‚СЂРё РЅРµРіРѕ.
  firewall_menu_legacy
}

# =====================================================================
# Р‘Р«РЎРўР Р«Р™ РћР‘Р—РћР  РџРћР РўРћР’ (Р·Р°РјРµРЅР° РјРµРґР»РµРЅРЅРѕРіРѕ TUI):
#   вЂ” РѕРґРёРЅ РІС‹Р·РѕРІ ufw status, РїРѕ РѕРґРЅРѕРјСѓ ss РЅР° РїСЂРѕС‚РѕРєРѕР», РѕРґРёРЅ Р·Р°РїСЂРѕСЃ udp-РїРѕСЂС‚РѕРІ
#   вЂ” РЅСѓРјРµСЂРѕРІР°РЅРЅС‹Р№ СЃРїРёСЃРѕРє В«СЃРѕРєРµС‚ Г— РїСЂР°РІРёР»РѕВ»; РїРµСЂРµРєР»СЋС‡РµРЅРёРµ РїРѕ РЅРѕРјРµСЂСѓ
#     РїСЂРёРјРµРЅСЏРµС‚СЃСЏ РЎР РђР—РЈ (allow/deny, Р±РµР· ufw reset)
# =====================================================================
firewall_apply_menu() {
  if [[ ! -t 0 ]]; then
    log "UFW (РЅРµРёРЅС‚РµСЂР°РєС‚РёРІРЅРѕ): SSH+443+UDP-РёРЅР±Р°СѓРЅРґС‹ РїР°РЅРµР»Рё"
    save_firewall_state >/dev/null 2>&1 || true
    ufw --force reset >/dev/null 2>&1 || true
    ufw default deny incoming >/dev/null 2>&1 || true
    ufw default allow outgoing >/dev/null 2>&1 || true
    if ! ssh_loopback_only; then
      fw_allow "${SSH_PORT:-22}" tcp "SSH"
    else
      ufw delete allow "${SSH_PORT:-22}/tcp" >/dev/null 2>&1 || true
    fi
    fw_allow 443 tcp "HTTPS/SNI"
    local up
    for up in $(udp_inbound_ports); do
      fw_port_locked "$up" && continue
      fw_allow "$up" udp "udp-РёРЅР±Р°СѓРЅРґ"
    done
    fw_deny_panel_ports
    ufw --force enable >/dev/null 2>&1 || true
    return 0
  fi

  local G Y R N
  if command -v tput >/dev/null 2>&1; then
    G=$(tput setaf 2); Y=$(tput setaf 3); R=$(tput setaf 1); N=$(tput sgr0)
  else
    G=''; Y=''; R=''; N=''
  fi

  # UDP-РїРѕСЂС‚С‹ РёРЅР±Р°СѓРЅРґРѕРІ вЂ” РћР”РРќ Р·Р°РїСЂРѕСЃ Рє Р‘Р” РЅР° РІРµСЃСЊ СЌРєСЂР°РЅ
  local -a UDP_PORTS=()
  local _u
  for _u in $(udp_inbound_ports); do UDP_PORTS+=("$_u"); done

  local -A UFW_ALLOW=() UFW_DENY=() SOCK_OUT=() SOCK_LOOP=() SOCK_PID=() LOOPGRP=()
  local UFW_ACTIVE=0

  # в”Ђв”Ђ РЎР±РѕСЂ СЃРѕСЃС‚РѕСЏРЅРёСЏ: 1Г—ufw status + 1Г—ss tcp + 1Г—ss udp (РїР°СЂСЃРёРЅРі РІ bash) в”Ђв”Ђ
  fw_load_state() {
    UFW_ALLOW=(); UFW_DENY=(); SOCK_OUT=(); SOCK_LOOP=(); SOCK_PID=(); LOOPGRP=()
    UFW_ACTIVE=0
    ufw_is_active && UFW_ACTIVE=1
    local _ln _pt _act
    if [[ "$UFW_ACTIVE" == 1 ]]; then
      while IFS= read -r _ln; do
        read -r _pt _act _ <<<"$_ln"
        [[ "$_pt" =~ ^[0-9]+/(tcp|udp)$ ]] || continue
        case "$_act" in
          ALLOW) UFW_ALLOW["$_pt"]=1 ;;
          DENY)  UFW_DENY["$_pt"]=1 ;;
        esac
      done < <(ufw status 2>/dev/null | awk '$1 ~ /^[0-9]+\/(tcp|udp)$/ && ($2 == "ALLOW" || $2 == "DENY") { print $1, $2 }')
    fi
    local _line _st _rq _sq _addr _peer _info _port _proc _pid
    while IFS= read -r _line; do
      read -r _st _rq _sq _addr _peer _info <<<"$_line"
      [[ -n "$_addr" ]] || continue
      _port="${_addr##*:}"
      [[ "$_port" =~ ^[0-9]+$ ]] || continue
      _proc="вЂ”"; _pid="вЂ”"
      if [[ "$_info" =~ \"([^\"]+)\".*pid=([0-9]+) ]]; then
        _proc="${BASH_REMATCH[1]}"; _pid="${BASH_REMATCH[2]}"
      fi
      [[ "$_proc" == xray-linux* ]] && _proc="xray"
      if [[ "$_addr" == 127.* || "$_addr" == \[::1\]:* || "$_addr" == ::1:* ]]; then
        SOCK_LOOP["${_port}/tcp"]="$_proc"; SOCK_PID["${_port}/tcp"]="$_pid"
      else
        SOCK_OUT["${_port}/tcp"]="$_proc"; SOCK_PID["${_port}/tcp"]="$_pid"
      fi
    done < <(ss -tlnpH 2>/dev/null)
    while IFS= read -r _line; do
      read -r _st _rq _sq _addr _peer _info <<<"$_line"
      [[ "$_peer" == "*:*" || "$_peer" == "0.0.0.0:*" || "$_peer" == "[::]:*" ]] || continue
      _port="${_addr##*:}"
      [[ "$_port" =~ ^[0-9]+$ ]] || continue
      _proc="вЂ”"; _pid="вЂ”"
      if [[ "$_info" =~ \"([^\"]+)\".*pid=([0-9]+) ]]; then
        _proc="${BASH_REMATCH[1]}"; _pid="${BASH_REMATCH[2]}"
      fi
      [[ "$_proc" == xray-linux* ]] && _proc="xray"
      if [[ "$_addr" == 127.* || "$_addr" == \[::1\]:* || "$_addr" == ::1:* ]]; then
        SOCK_LOOP["${_port}/udp"]="$_proc"; SOCK_PID["${_port}/udp"]="$_pid"
      else
        SOCK_OUT["${_port}/udp"]="$_proc"; SOCK_PID["${_port}/udp"]="$_pid"
      fi
    done < <(ss -ulnpH 2>/dev/null)
  }

  # в”Ђв”Ђ РџРѕСЃС‚СЂРѕРµРЅРёРµ СЃС‚СЂРѕРє СЃРїРёСЃРєР° (Р±С‹СЃС‚СЂРѕ: Р±РµР· fork РЅР° СЃС‚СЂРѕРєСѓ) в”Ђв”Ђ
  fw_build_items() {
    # NB: items вЂ” РїРµСЂРµРјРµРЅРЅР°СЏ РІС‹Р·С‹РІР°СЋС‰РµР№ С„СѓРЅРєС†РёРё (local items РІ firewall_apply_menu),
    # Р»РѕРєР°Р»СЊРЅРѕР№ РґРµРєР»Р°СЂР°С†РёРµР№ РµС‘ РќР• Р·Р°С‚РµРЅСЏС‚СЊ, РёРЅР°С‡Рµ СЃРїРёСЃРѕРє СѓРјСЂС‘С‚ РЅР° РІС‹С…РѕРґРµ.
    items=()
    LOOPGRP=()
    local seen="" key proto port proc pid state note ex _u2
    for key in "${!SOCK_LOOP[@]}"; do
      LOOPGRP[${SOCK_LOOP[$key]}]+=" ${key%/*}/${key#*/}"
    done
    # 1) СЃРѕРєРµС‚С‹ СЃРЅР°СЂСѓР¶Рё
    for key in "${!SOCK_OUT[@]}"; do
      proto="${key#*/}"; port="${key%/*}"
      proc="${SOCK_OUT[$key]}"; pid="${SOCK_PID[$key]:-вЂ”}"
      note=""
      if [[ "$UFW_ACTIVE" == 1 ]]; then
        if [[ -n "${UFW_ALLOW[$key]:-}" ]]; then
          state=1
        elif [[ -n "${UFW_DENY[$key]:-}" ]]; then
          state=0; note="DENY (РїСЂР°РІРёР»Рѕ UFW)"
        else
          state=0; note="UFW Р±Р»РѕРєРёСЂСѓРµС‚ (default deny)"
        fi
      else
        state=1; note="UFW РЅРµ Р°РєС‚РёРІРµРЅ"
      fi
      ex=""
      case "$port" in 22) ex="SSH" ;; 80) ex="ACME" ;; 443) ex="СЃС‚РµРє (SNI)" ;; esac
      if [[ "$proto" == "udp" ]]; then
        for _u2 in "${UDP_PORTS[@]}"; do
          [[ "$_u2" == "$port" ]] && { ex="${ex:+$ex В· }UDP-РёРЅР±Р°СѓРЅРґ"; break; }
        done
      fi
      [[ -n "$ex" ]] && note="${note:+$note В· }$ex"
      items+=("${proto}|${port}|${pid}|${proc}|${state}|${note}")
      seen+=" $key"
    done
    # 2) РїСЂР°РІРёР»Р° UFW Р±РµР· СЃР»СѓС€Р°С‚РµР»СЏ
    if [[ "$UFW_ACTIVE" == 1 ]]; then
      for key in "${!UFW_ALLOW[@]}"; do
        [[ -n "${SOCK_OUT[$key]:-}" || " $seen " == *" $key "* ]] && continue
        items+=("${key#*/}|${key%/*}|вЂ”|вЂ”|1|РїСЂР°РІРёР»Рѕ UFW, СЃР»СѓС€Р°С‚РµР»СЏ РЅРµС‚")
        seen+=" $key"
      done
      for key in "${!UFW_DENY[@]}"; do
        [[ -n "${SOCK_OUT[$key]:-}" || " $seen " == *" $key "* ]] && continue
        items+=("${key#*/}|${key%/*}|вЂ”|вЂ”|0|DENY (РїСЂР°РІРёР»Рѕ UFW), СЃР»СѓС€Р°С‚РµР»СЏ РЅРµС‚")
        seen+=" $key"
      done
    fi
    # 3) SSH-РїРѕСЂС‚ РїСЂРѕРµРєС‚Р°, РµСЃР»Рё РЅРµ РїРѕРїР°Р» РІ СЃРѕРєРµС‚С‹
    local ssh_port="${SSH_PORT:-22}" has=0 it
    for it in "${items[@]}"; do
      [[ "${it#*|}" == "${ssh_port}|"* ]] && has=1
    done
    [[ "$has" == 0 ]] && items=("tcp|${ssh_port}|вЂ”|sshd (РЅРµ СЃР»СѓС€Р°РµС‚ СЃРЅР°СЂСѓР¶Рё)|1|SSH" "${items[@]}")
    # 4) 443 вЂ” РѕР±СЏР·Р°С‚РµР»СЊРЅС‹Р№ РІС…РѕРґ СЃС‚РµРєР°
    has=0
    for it in "${items[@]}"; do
      [[ "${it#*|}" == "443|"* ]] && has=1
    done
    [[ "$has" == 0 ]] && items+=("tcp|443|вЂ”|nginx/SNI (РѕР±СЏР·Р°С‚РµР»СЊРЅС‹Р№)|1|HTTPS/SNI")
    # 5) РїР°РЅРµР»СЊРЅС‹Рµ РїРѕСЂС‚С‹, СЃР»СѓС€Р°СЋС‰РёРµ loopback
    local _pp _sp _px
    _pp=$(xui_get webPort 2>/dev/null || true)
    _sp=$(xui_get subPort 2>/dev/null || true)
    for _px in "$_pp" "$_sp"; do
      [[ -z "$_px" || "$_px" == "0" || ! "$_px" =~ ^[0-9]+$ ]] && continue
      [[ " $seen " == *" ${_px}/tcp "* ]] && continue
      seen+=" ${_px}/tcp"
      items+=("tcp|${_px}|вЂ”|x-ui (РїР°РЅРµР»СЊ, loopback)|0|РїР°РЅРµР»СЊ x-ui (127.0.0.1)")
    done
    # 11443 РЅР°СЂСѓР¶Сѓ РЅРµ РїСѓР±Р»РёРєСѓРµРј
    local _row _rp _rport _rest
    local -a _flt=()
    for _row in "${items[@]}"; do
      IFS='|' read -r _rp _rport _rest <<<"$_row"
      [[ "$_rport" == "11443" ]] && continue
      _flt+=("$_row")
    done
    items=("${_flt[@]}")
    # СЃРѕСЂС‚РёСЂРѕРІРєР° РїРѕ РїРѕСЂС‚Сѓ
    local -a _srt=()
    while IFS= read -r _row; do _srt+=("$_row"); done < <(
      printf '%s\n' "${items[@]}" | awk -F'|' '{printf "%06d %s\n", $2, $0}' | sort -n | cut -d' ' -f2-)
    items=("${_srt[@]}")
  }

  # в”Ђв”Ђ РћС‚СЂРёСЃРѕРІРєР° РїСЂРѕСЃС‚С‹Рј СЃРїРёСЃРєРѕРј (Р±РµР· cursor-TUI) в”Ђв”Ђ
  fw_render() {
    clear
    line
    echo -e "${B}   FIREWALL (UFW) вЂ” РџРћР РўР«: РЎРћРљР•Рў Г— РџР РђР’РР›Рћ${N}"
    line
    local st="inactive"
    [[ "$UFW_ACTIVE" == 1 ]] && st="active"
    echo "  РЎС‚Р°С‚СѓСЃ UFW: $st В· РїРµСЂРµРєР»СЋС‡РµРЅРёРµ РїРѕ РЅРѕРјРµСЂСѓ РїСЂРёРјРµРЅСЏРµС‚СЃСЏ СЃСЂР°Р·Сѓ (Р±РµР· ufw reset)"
    echo
    printf "   %-3s %-5s %-6s %-22s %s\n" "#" "РџСЂРѕС‚Рѕ" "РџРѕСЂС‚" "РџСЂРѕС†РµСЃСЃ" "РЎС‚Р°С‚СѓСЃ В· РїСЂРёРјРµС‡Р°РЅРёРµ"
    printf "   %s\n" "в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ"
    local i=0 it proto port pid proc state note mark
    for it in "${items[@]}"; do
      IFS='|' read -r proto port pid proc state note <<<"$it"
      if [[ "$state" == 1 ]]; then mark="${G}в—Џ РѕС‚РєСЂС‹С‚${N}"; else mark="${Y}в—‹ Р·Р°РєСЂС‹С‚${N}"; fi
      printf "   %-3s %-5s %-6s %-22s %b%s\n" "$((i+1))" "$proto" "$port" "$proc" "$mark" "${note:+ в†ђ $note}"
      i=$((i+1))
    done
    echo
    echo -e "${B}в–ё РЎРїСЂСЏС‚Р°РЅРѕ РЅР°СЃС‚СЂРѕР№РєР°РјРё (UFW РЅРµ РїСЂРё С‡С‘Рј вЂ” РїРѕСЂС‚С‹ РЅР° 127.0.0.1):${N}"
    if [[ ${#LOOPGRP[@]} -eq 0 ]]; then
      echo "  вЂ”"
    else
      local _pr _ports
      for _pr in x-ui nginx xray csqtt; do
        [[ -n "${LOOPGRP[$_pr]:-}" ]] || continue
        _ports=$(printf '%s\n' ${LOOPGRP[$_pr]} | sort -t/ -k1,1n | tr '\n' ',' | sed 's/,$//; s/,/, /g')
        printf "    %-18s %s\n" "${_pr}:" "$_ports"
      done
      for _pr in "${!LOOPGRP[@]}"; do
        case "$_pr" in x-ui|nginx|xray|csqtt) continue ;; esac
        _ports=$(printf '%s\n' ${LOOPGRP[$_pr]} | sort -t/ -k1,1n | tr '\n' ',' | sed 's/,$//; s/,/, /g')
        printf "    %-18s %s\n" "${_pr}:" "$_ports"
      done
    fi
    echo
    line
    echo "  N) РІРєР»/РІС‹РєР»: РЅРѕРјРµСЂ РЎРўР РћРљР СЃРїРёСЃРєР° РёР»Рё РЅРѕРјРµСЂ РџРћР РўРђ В· a) СЃРІРѕР№ РїРѕСЂС‚ В· r) РѕР±РЅРѕРІРёС‚СЊ В· 0) РЅР°Р·Р°Рґ"
    line
  }

  # в”Ђв”Ђ РџРµСЂРµРєР»СЋС‡РµРЅРёРµ РѕРґРЅРѕРіРѕ РїРѕСЂС‚Р° в”Ђв”Ђ
  fw_toggle() {
    local idx="$1" it proto port pid proc state note _a
    it="${items[$((idx-1))]}"
    IFS='|' read -r proto port pid proc state note <<<"$it"
    if [[ "$state" == 1 ]] && fw_port_locked "$port"; then
      warn "РџРѕСЂС‚ $port Р·Р°РєСЂРµРїР»С‘РЅ (Рї.9) вЂ” Р·Р°РєСЂС‹РІР°С‚СЊ РЅРµР»СЊР·СЏ"; sleep 1; return
    fi
    # РїР°РЅРµР»СЊРЅС‹Р№ loopback-РїРѕСЂС‚: РїРµСЂРµРєР»СЋС‡Р°РµРј РїСЂРёРІСЏР·РєСѓ + РїСЂР°РІРёР»Рѕ РѕРґРЅРѕР№ РѕРїРµСЂР°С†РёРµР№
    if [[ "${SOCK_LOOP[${port}/${proto}]:-}" == "x-ui" ]]; then
      echo "  вљ  x-ui РїРµСЂРµР·Р°РїСѓСЃС‚РёС‚СЃСЏ вЂ” С‚СѓРЅРЅРµР»Рё (xray/caddy/вЂ¦) РєСЂР°С‚РєРѕ РѕР±РѕСЂРІСѓС‚СЃСЏ"
      if [[ "$state" == 1 ]]; then
        read -rp "  Р’РµСЂРЅСѓС‚СЊ РїР°РЅРµР»СЊ РЅР° 127.0.0.1 Рё Р·Р°РєСЂС‹С‚СЊ РїРѕСЂС‚ $port? [y/N]: " _a || _a=""
        [[ "${_a,,}" == "y" ]] || return
        xui_set_listen "$port" "127.0.0.1" || { err "РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРјРµРЅРёС‚СЊ РїСЂРёРІСЏР·РєСѓ"; sleep 1; return; }
        ufw delete allow "$port/$proto" >/dev/null 2>&1 || true
        ufw deny "$port/$proto" >/dev/null 2>&1 || true
      else
        read -rp "  РћС‚РєСЂС‹С‚СЊ РїР°РЅРµР»СЊ РЅР°СЂСѓР¶Сѓ (0.0.0.0:$port)? [y/N]: " _a || _a=""
        [[ "${_a,,}" == "y" ]] || return
        xui_set_listen "$port" "0.0.0.0" || { err "РЅРµ СѓРґР°Р»РѕСЃСЊ СЃРјРµРЅРёС‚СЊ РїСЂРёРІСЏР·РєСѓ"; sleep 1; return; }
        ufw delete deny "$port/$proto" >/dev/null 2>&1 || true
        fw_allow "$port" "$proto" "x-ui"
      fi
    elif [[ "$port" == "${SSH_PORT:-22}" && "$state" == 1 ]]; then
      echo -e "${R}вљ  Р—Р°РєСЂС‹С‚РёРµ SSH (${SSH_PORT:-22}) РѕС‚СЂРµР¶РµС‚ РґРѕСЃС‚СѓРї СЃРЅР°СЂСѓР¶Рё.${N}"
      read -rp "  Р”Р»СЏ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РІРІРµРґРё YES: " _a || _a=""
      [[ "$_a" == "YES" ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; sleep 1; return; }
      ufw delete allow "$port/$proto" >/dev/null 2>&1 || true
      ufw deny "$port/$proto" >/dev/null 2>&1 || true
    elif [[ "$port" == "443" || "$port" == "80" ]] && [[ "$state" == 1 ]]; then
      read -rp "  вљ  РџРѕСЂС‚ $port вЂ” СЃР»СѓР¶РµР±РЅС‹Р№ РґР»СЏ СЃС‚РµРєР°. Р—Р°РєСЂС‹С‚СЊ? [y/N]: " _a || _a=""
      [[ "${_a,,}" == "y" ]] || return
      ufw delete allow "$port/$proto" >/dev/null 2>&1 || true
      ufw deny "$port/$proto" >/dev/null 2>&1 || true
    elif [[ "$state" == 1 ]]; then
      ufw delete allow "$port/$proto" >/dev/null 2>&1 || true
      ufw deny "$port/$proto" >/dev/null 2>&1 || true
      log "РџРѕСЂС‚ $port/$proto Р·Р°РєСЂС‹С‚ (deny)"
    else
      ufw delete deny "$port/$proto" >/dev/null 2>&1 || true
      fw_allow "$port" "$proto" "СЂСѓС‡РЅРѕРµ РѕС‚РєСЂС‹С‚РёРµ"
      log "РџРѕСЂС‚ $port/$proto РѕС‚РєСЂС‹С‚ (allow)"
    fi
  }

  # в”Ђв”Ђ Р”РѕР±Р°РІР»РµРЅРёРµ В«СЃРІРѕРµРіРѕВ» РїРѕСЂС‚Р° (Рї.9) в”Ђв”Ђ
  fw_add_extra() {
    local nport="" nproto="tcp" nnum=""
    read -rp "РќРѕРІС‹Р№ РїРѕСЂС‚ (8090 РёР»Рё 22000/udp): " nport || nport=""
    nport="${nport// /}"
    case "$nport" in
      */tcp) nnum="${nport%/*}" ;;
      */udp) nnum="${nport%/*}"; nproto="udp" ;;
      *)     nnum="$nport" ;;
    esac
    if [[ "$nnum" =~ ^[0-9]+$ ]] && (( nnum >= 1 && nnum <= 65535 )); then
      mkdir -p "$BACKUP_DIR" 2>/dev/null || true
      grep -qxF "${nproto}/${nnum}" "$BACKUP_DIR/fw-extra" 2>/dev/null || \
        printf '%s/%s\n' "$nproto" "$nnum" >> "$BACKUP_DIR/fw-extra"
      fw_allow "$nnum" "$nproto" "СЃРІРѕР№ РїРѕСЂС‚"
      log "РЎРІРѕР№ РїРѕСЂС‚ $nnum/$nproto РґРѕР±Р°РІР»РµРЅ Рё РѕС‚РєСЂС‹С‚"
      sleep 1
    else
      warn "РќРµРєРѕСЂСЂРµРєС‚РЅС‹Р№ РїРѕСЂС‚: $nport"; sleep 1
    fi
  }

  local items=()
  fw_load_state
  fw_build_items
  local c=""
  while :; do
    fw_render
    read -rp "  Р’С‹Р±РѕСЂ: " c || c="0"
    case "$c" in
      0|q|Q) return 0 ;;
      r|R)   fw_load_state; fw_build_items ;;
      a|A)   fw_add_extra ;;
      '') ;;
      *[!0-9]*) warn "РќРµС‚ С‚Р°РєРѕРіРѕ РїСѓРЅРєС‚Р°"; sleep 1 ;;
      *)
        # Р’РІРѕРґ: РЅРѕРјРµСЂ СЃС‚СЂРѕРєРё СЃРїРёСЃРєР° (1..N) РР›Р РЅРѕРјРµСЂ РїРѕСЂС‚Р° (РЅР°РїСЂ. 56000).
        local _idx=0 _row _hproto _hp _rest2 _match=-1 _count=0
        for _row in "${items[@]}"; do
          _idx=$((_idx+1))
          IFS='|' read -r _hproto _hp _rest2 <<<"$_row"
          if [[ "$_hp" == "$c" ]]; then _match=$_idx; _count=$((_count+1)); fi
        done
        if (( _count == 1 )); then
          fw_toggle "$_match"            # РїРѕ РїРѕСЂС‚Сѓ (РѕРґРЅРѕР·РЅР°С‡РЅРѕ)
        elif (( _count > 1 )); then
          warn "РџРѕСЂС‚ $c РµСЃС‚СЊ Рё РІ tcp, Рё РІ udp вЂ” РІРІРµРґРёС‚Рµ РЅРѕРјРµСЂ СЃС‚СЂРѕРєРё (1..${#items[@]})"; sleep 1
        elif (( c >= 1 && c <= ${#items[@]} )); then
          fw_toggle "$c"                  # РїРѕ РЅРѕРјРµСЂСѓ СЃС‚СЂРѕРєРё
        else
          warn "РќРµС‚ С‚Р°РєРѕРіРѕ РїСѓРЅРєС‚Р° (РЅРѕРјРµСЂ СЃС‚СЂРѕРєРё 1..${#items[@]} РёР»Рё РїРѕСЂС‚)"; sleep 1
        fi
        fw_load_state; fw_build_items
        ;;
    esac
  done
}

# =====================================================================
# Р—Р”РћР РћР’Р¬Р•: UFW-fallback, recidive, Р¶РёРІРѕР№ Р»РѕРі, С€Р°Р±Р»РѕРЅС‹ decoy
# СЃСЃС‹Р»РѕРє, СЃРјРµРЅР° РґРѕРјРµРЅР° РёРЅР±Р°СѓРЅРґР°
# =====================================================================

# РЎС‚Р°С‚СѓСЃ UFW СЃ Р·Р°РїР°СЃРЅС‹Рј РїСѓС‚С‘Рј: Р±РёРЅР°СЂСЊ РјРѕР¶РµС‚ РЅРµ РЅР°С…РѕРґРёС‚СЊСЃСЏ РІ PATH вЂ” С‚РѕРіРґР°
# СЃРјРѕС‚СЂРёРј СЃРµСЂРІРёСЃ (oneshot ufw.service РѕСЃС‚Р°С‘С‚СЃСЏ active РїРѕСЃР»Рµ РїСЂРёРјРµРЅРµРЅРёСЏ РїСЂР°РІРёР»).
# РїРµСЂРµСЃР±РѕСЂРєР° Р’РЎР•РҐ decoy-Р±Р»РѕРєРѕРІ: РїРѕРґС‚СЏРЅСѓС‚СЊ robots/honeypot/UA-404/Р»РѕРіРё СЃ РґРѕРјРµРЅРѕРј.
# РЁР°Р±Р»РѕРЅ Р±РµСЂС‘Рј РёР· РјР°СЂРєРµСЂР° (tpl=), РµСЃР»Рё РЅРµС‚ вЂ” СѓРіР°РґС‹РІР°РµРј РїРѕ md5 index.html.
decoy_rebuild_all() {
  [[ -f "$STACK_CONF" ]] || { err "stack.conf РЅРµ РЅР°Р№РґРµРЅ"; pause; return 1; }
  local mline mport mroot mcert mkey mdom mtpl muaf mus4 idx hash tf troot found
  local -A TPL_OF=()
  local -a ROWS=()
  while IFS= read -r mline; do
    [[ "$mline" != "# >>> decoy "* ]] && continue
    mport=$(grep -oE 'port=[0-9]+'   <<<"$mline" | head -1 | cut -d= -f2)
    mroot=$(grep -oE 'root=[^ ]+'    <<<"$mline" | head -1 | cut -d= -f2-)
    mcert=$(grep -oE 'cert=[^ ]+'    <<<"$mline" | head -1 | cut -d= -f2-)
    mkey=$(grep  -oE ' key=[^ ]+'    <<<"$mline" | head -1 | sed 's/^ key=//')
    mdom=$(grep  -oE 'domain=[^ ]+$' <<<"$mline" | head -1 | cut -d= -f2-)
    mtpl=$(grep -oE 'tpl=[^ ]+'      <<<"$mline" | head -1 | cut -d= -f2-)
    muaf=$(grep -oE 'ua404=[0-9]'    <<<"$mline" | head -1 | cut -d= -f2-)
    mus4=$(grep -oE 'status404=[0-9]' <<<"$mline" | head -1 | cut -d= -f2-)
    [[ -z "$mus4" ]] && mus4=0
    [[ -z "$mdom" || -z "$mport" || -z "$mroot" ]] && continue
    if [[ -z "$mtpl" && -f "$mroot/index.html" ]]; then
      hash=$(md5sum "$mroot/index.html" 2>/dev/null | awk '{print $1}')
      found=""
      for tf in "$DECOY_TPL_DIR"/*.html "$DECOY_LOGIN_DIR"/*.html; do
        [[ -f "$tf" ]] || continue
        [[ "$(md5sum "$tf" 2>/dev/null | awk '{print $1}')" == "$hash" ]] && { found=$(basename "$tf" .html); break; }
      done
      mtpl="${found:-corporate}"
    fi
    [[ -z "$mtpl" ]] && mtpl="corporate"
    [[ -z "$muaf" ]] && muaf=1
    ROWS+=("$mport|$mdom|$mcert|$mkey|$mroot|$mtpl|$muaf")
  done < "$STACK_CONF"
  [[ ${#ROWS[@]} -eq 0 ]] && { warn "Decoy-Р±Р»РѕРєРё РЅРµ РЅР°Р№РґРµРЅС‹"; pause; return 0; }
  local r
  for r in "${ROWS[@]}"; do
    IFS='|' read -r mport mdom mcert mkey mroot mtpl muaf <<<"$r"
    mk_decoy "$mport" "$mdom" "$mcert" "$mkey" "$mroot" "$mtpl" "ua404=$muaf status404=$mus4"
    log "  $mdom в†’ В«$mtplВ» (ua404=$muaf, robots+honeypot+Р»РѕРіРё)"
  done
  audit "decoy: РїРµСЂРµСЃР±РѕСЂРєР° РІСЃРµС… Р±Р»РѕРєРѕРІ"
  if nginx -t >/dev/null 2>&1; then
    nginx_reload || true
    log "Р’СЃРµ decoy-Р±Р»РѕРєРё РїРµСЂРµСЃРѕР±СЂР°РЅС‹ вњ“"
  else
    err "nginx -t РЅРµ РїСЂРѕС€С‘Р»:"; nginx -t 2>&1 | tail -5 | sed 's/^/    /'
  fi
  pause
}

# В«РїСЂРѕРІРµСЂРёС‚СЊ РєР°Рє РїРѕСЃС‚РѕСЂРѕРЅРЅРёР№В»: С‡С‚Рѕ СЂРµР°Р»СЊРЅРѕ СѓРІРёРґРёС‚ С‡РµР»РѕРІРµРє Рё СЃРєР°РЅРµСЂ
decoy_outsider_check() {
  local mline mport mdom
  local -a DOM_LIST=()
  local -A PORT_OF=()
  while IFS= read -r mline; do
    [[ "$mline" != "# >>> decoy "* ]] && continue
    mport=$(grep -oE 'port=[0-9]+'   <<<"$mline" | head -1 | cut -d= -f2)
    mdom=$(grep  -oE 'domain=[^ ]+$' <<<"$mline" | head -1 | cut -d= -f2-)
    [[ -n "$mdom" ]] && { DOM_LIST+=("$mdom"); PORT_OF[$mdom]="$mport"; }
  done < "$STACK_CONF"
  [[ ${#DOM_LIST[@]} -eq 0 ]] && { warn "Decoy-РґРѕРјРµРЅРѕРІ РЅРµС‚"; pause; return 0; }
  local i=1 d pick
  for d in "${DOM_LIST[@]}"; do printf "  %d) %s\n" "$i" "$d"; i=$((i+1)); done
  ask pick "РџСЂРѕРІРµСЂРёС‚СЊ РєР°РєРѕР№ РґРѕРјРµРЅ" "1" '^[0-9]+$'
  (( pick > ${#DOM_LIST[@]} )) && { err "РќРµС‚ С‚Р°РєРѕРіРѕ"; pause; return 1; }
  mdom="${DOM_LIST[$((pick-1))]}"
  mport="${PORT_OF[$mdom]}"
  local HUA="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36"
  local cb ch title
  cb=$(curl -sk -A "curl/8.5.0" -o /dev/null -w "%{http_code}" "https://127.0.0.1:$mport/" 2>/dev/null)
  curl -sk -A "$HUA" "https://127.0.0.1:$mport/" -o /tmp/smg_out.html 2>/dev/null
  ch=$(curl -sk -A "$HUA" -o /dev/null -w "%{http_code}" "https://127.0.0.1:$mport/" 2>/dev/null)
  title=$(grep -oE '<title>[^<]*' /tmp/smg_out.html 2>/dev/null | head -1 | sed 's/<title>//')
  echo
  echo "  Р”РѕРјРµРЅ: $mdom (Р»РѕРєР°Р»СЊРЅС‹Р№ РїРѕСЂС‚ $mport)"
  echo "  ---------------------------------------------"
  echo "  Р§РµР»РѕРІРµРє (Р±СЂР°СѓР·РµСЂ): HTTP $ch   title: ${title:-вЂ”}"
  echo "  РЎРєР°РЅРµСЂ (curl):     HTTP $cb   $( [[ "$cb" == 404 ]] && echo 'в†ђ Р±РѕС‚ РІРёРґРёС‚ РїСѓСЃС‚РѕС‚Сѓ вњ“' )"
  echo
  echo "  Р—Р°РіРѕР»РѕРІРєРё (РєР°Рє РґР»СЏ Р±СЂР°СѓР·РµСЂР°):"
  curl -skI -A "$HUA" "https://127.0.0.1:$mport/" 2>/dev/null | head -6 | sed 's/^/    /'
  rm -f /tmp/smg_out.html
  pause
}

view_decoy_templates() {
  line; echo -e "${B}   DECOY-РЁРђР‘Р›РћРќР«${N}"; line
  echo "в–ё РЎС‚Р°С‚РёС‡РµСЃРєРёРµ HTML:"
  local tpl name desc size
  for tpl in "${DECOY_TEMPLATES[@]}"; do
    name="${tpl%%|*}"; desc="${tpl##*|}"
    is_login_template "$name" && continue
    size=0
    [[ -f "$DECOY_TPL_DIR/$name.html" ]] && size=$(stat -c%s "$DECOY_TPL_DIR/$name.html" 2>/dev/null || echo 0)
    printf "  %-15s %6s B  %s\n" "$name" "$size" "$desc"
  done
  echo
  echo "в–ё Login-С€Р°Р±Р»РѕРЅС‹:"
  for tpl in "${DECOY_TEMPLATES[@]}"; do
    name="${tpl%%|*}"; desc="${tpl##*|}"
    is_login_template "$name" || continue
    size=0
    [[ -f "$DECOY_LOGIN_DIR/$name.html" ]] && size=$(stat -c%s "$DECOY_LOGIN_DIR/$name.html" 2>/dev/null || echo 0)
    printf "  %-15s %6s B  %s\n" "$name" "$size" "$desc"
  done
  echo
  echo -e "${B}в–ё РЎРІРѕР№ СЃР°Р№С‚ (custom):${N} РґРѕСЃС‚СѓРїРµРЅ РІ Р»СЋР±РѕРј РјРµРЅСЋ РІС‹Р±РѕСЂР° С€Р°Р±Р»РѕРЅР° вЂ”"
  echo "    РІС‹Р±СЂР°С‚СЊ РїСѓРЅРєС‚ В«customВ» Рё СѓРєР°Р·Р°С‚СЊ РїСѓС‚СЊ Рє РїР°РїРєРµ СЃ index.html (СЃС‚Р°С‚РёРєР°)."
  echo
  echo "  1) РџРµСЂРµСЃРѕР±СЂР°С‚СЊ РІСЃРµ decoy-Р±Р»РѕРєРё (РІРєР»СЋС‡РёС‚СЊ robots/honeypot/UA-404/Р»РѕРіРё)"
  echo "  2) РџСЂРѕРІРµСЂРёС‚СЊ РґРѕРјРµРЅ РєР°Рє РїРѕСЃС‚РѕСЂРѕРЅРЅРёР№ (С‡РµР»РѕРІРµРє vs СЃРєР°РЅРµСЂ)"
  echo "  0) РќР°Р·Р°Рґ"
  local c=""
  read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
  case "$c" in
    1) decoy_rebuild_all ;;
    2) decoy_outsider_check ;;
  esac
  pause
}

# =====================================================================
# Р“Р›РђР’РќРћР• РњР•РќР®
# =====================================================================
# =====================================================================
# РЈР”РђР›Р•РќРР• РљРћРњРџРћРќР•РќРўРћР’
# =====================================================================
# AdGuard Home: РѕСЃС‚Р°РЅРѕРІРєР°, СѓРґР°Р»РµРЅРёРµ С„Р°Р№Р»РѕРІ/СЃРµСЂРІРёСЃР°, Р·Р°РіР»СѓС€РєР° РІРјРµСЃС‚Рѕ
# РїСЂРѕРєСЃРё РЅР° AdGuard РІ stack.conf
uninstall_adguard() {
  detect_env
  if [[ "$ADG_PRESENT" != true ]]; then
    warn "AdGuard Home РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ."
    return 1
  fi
  line; echo -e "${B}   РЈР”РђР›Р•РќРР• ADGUARD HOME${N}"; line
  echo "  Р‘СѓРґСѓС‚ СѓРґР°Р»РµРЅС‹: СЃРµСЂРІРёСЃ, /opt/AdGuardHome, РєРѕРЅС„РёРіСѓСЂР°С†РёСЏ Рё СЃС‚Р°С‚РёСЃС‚РёРєР°."
  echo "  Р‘СЌРєР°Рї РєРѕРЅС„РёРіР°: /root/adguard-backup-<РґР°С‚Р°>.tar.gz"
  local sure=false
  askyn sure "РЈРґР°Р»РёС‚СЊ AdGuard Home?" "n"
  [[ "$sure" == true ]] || { log "РћС‚РјРµРЅРµРЅРѕ."; return 0; }

  tar -czf "/root/adguard-backup-$(date +%Y%m%d-%H%M%S).tar.gz" \
    -C / opt/AdGuardHome/AdGuardHome.yaml 2>/dev/null || true

  systemctl stop "$ADG_SERVICE" 2>/dev/null || true
  systemctl disable "$ADG_SERVICE" 2>/dev/null || true
  rm -f "/etc/systemd/system/$ADG_SERVICE.service" 2>/dev/null || true
  systemctl daemon-reload 2>/dev/null || true
  rm -rf /opt/AdGuardHome 2>/dev/null || true

  # stack.conf: С‚РѕР»СЊРєРѕ РїРѕР»РЅС‹Р№ location / (РїСЂРѕРєСЃРё РЅР° СѓРґР°Р»С‘РЅРЅС‹Р№ AdGuard)
  # Р·Р°РјРµРЅСЏРµРј Р±РµР·РѕРїР°СЃРЅРѕ: СЃС‚Р°СЂС‹Р№ awk РѕР±СЂС‹РІР°Р» РІР»РѕР¶РµРЅРЅС‹Р№ Р±Р»РѕРє Рё РјРѕРі РѕСЃС‚Р°РІРёС‚СЊ
  # stack.conf СЃ РЅРµР·Р°РєСЂС‹С‚РѕР№ С„РёРіСѓСЂРЅРѕР№ СЃРєРѕР±РєРѕР№.
  if [[ -f "$STACK_CONF" ]] && grep -q "proxy_pass https\?://127.0.0.1:[0-9]*;" "$STACK_CONF"; then
    local tmp=""
    tmp=$(mktemp) || true
    STACK_CONF_IN="$STACK_CONF" STACK_CONF_OUT="$tmp" python3 - <<'PYADG'
import os, sys
src = open(os.environ['STACK_CONF_IN'], encoding='utf-8').read().splitlines()
out=[]; i=0; replaced=False
while i < len(src):
    if src[i].strip() == 'location / {':
        j=i+1; depth=1
        while j < len(src):
            s=src[j].strip()
            if s.endswith('{'): depth += 1
            if s == '}':
                depth -= 1
                if depth == 0: break
            j += 1
        block='\n'.join(src[i:j+1]) if j < len(src) else ''
        if j < len(src) and 'proxy_pass https://127.0.0.1:' in block:
            out += ['    location / {', '        return 302 /404.html;', '    }']
            i=j+1; replaced=True; continue
    out.append(src[i]); i += 1
if replaced:
    open(os.environ['STACK_CONF_OUT'], 'w', encoding='utf-8').write('\n'.join(out)+'\n')
else:
    sys.exit(2)
PYADG
    if [[ -s "$tmp" ]] && mv "$tmp" "$STACK_CONF"; then
      nginx -t >/dev/null 2>&1 && nginx_reload || warn "nginx РєРѕРЅС„РёРіСѓСЂР°С†РёСЏ С‚СЂРµР±СѓРµС‚ РїСЂРѕРІРµСЂРєРё РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ AdGuard"
    else
      rm -f "$tmp" 2>/dev/null || true
    fi
  fi
  ADG_PRESENT=false
  log "AdGuard Home СѓРґР°Р»С‘РЅ. Р‘СЌРєР°Рї РєРѕРЅС„РёРіР°: /root/adguard-backup-*.tar.gz"
}

# РџР°РЅРµР»СЊ LucX UI (x-ui): РѕСЃС‚Р°РЅРѕРІРєР°, Р±СЌРєР°Рї Р‘Р”, СѓРґР°Р»РµРЅРёРµ С„Р°Р№Р»РѕРІ/СЃРµСЂРІРёСЃР°.
# РћРїС†РёРѕРЅР°Р»СЊРЅРѕ вЂ” РєРѕРЅС„РёРіРё nginx СЃС‚РµРєР° (SNI-СЂРѕСѓС‚РµСЂ + stack.conf).
uninstall_panel_lucx() {
  detect_env
  line; echo -e "${B}   РЈР”РђР›Р•РќРР• РџРђРќР•Р›Р LUCX UI (X-UI)${N}"; line
  if [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]]; then
    warn "РџР°РЅРµР»СЊ РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР° (x-ui.db РЅРµ РЅР°Р№РґРµРЅ)."
  else
    echo "  Р‘СѓРґСѓС‚ СѓРґР°Р»РµРЅС‹: СЃРµСЂРІРёСЃ x-ui, /usr/local/x-ui, /etc/x-ui (Р‘Р” + РёРЅР±Р°СѓРЅРґС‹!), /usr/bin/x-ui."
    echo "  Р‘СЌРєР°Рї: /root/x-ui-backup-<РґР°С‚Р°>.tar.gz (РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ СЂР°СЃРїР°РєРѕРІРєРѕР№ РІ /)."
  fi
  local sure=false
  askyn sure "РЈРґР°Р»РёС‚СЊ РїР°РЅРµР»СЊ LucX UI?" "n"
  [[ "$sure" == true ]] || { log "РћС‚РјРµРЅРµРЅРѕ."; return 0; }

  # С‚Р°Р№РјРµСЂ Р°РІС‚РѕРїРѕС‡РёРЅРєРё СЃСЃС‹Р»Р°РµС‚СЃСЏ РЅР° СЃРєСЂРёРїС‚ вЂ” СЃРЅРёРјР°РµРј РІРјРµСЃС‚Рµ СЃ РїР°РЅРµР»СЊСЋ
  uninstall_heal_timer

  if [[ -f "$XUI_DB" ]]; then
    tar -czf "/root/x-ui-backup-$(date +%Y%m%d-%H%M%S).tar.gz" -C / etc/x-ui 2>/dev/null || true
    log "Р‘СЌРєР°Рї Р‘Р”: /root/x-ui-backup-*.tar.gz"
  fi

  systemctl stop x-ui 2>/dev/null || true
  systemctl disable x-ui 2>/dev/null || true
  rm -f /etc/systemd/system/x-ui.service /etc/systemd/system/multi-user.target.wants/x-ui.service 2>/dev/null || true
  systemctl daemon-reload 2>/dev/null || true
  rm -rf /usr/local/x-ui /etc/x-ui 2>/dev/null || true
  rm -f /usr/bin/x-ui 2>/dev/null || true
  XUI_DB=""

  # РєРѕРЅС„РёРіРё nginx СЃС‚РµРєР°: Р±РµР· РїР°РЅРµР»Рё SNI-СЂРѕСѓС‚РµСЂ Рё stack.conf РЅРµ РёРјРµСЋС‚ СЃРјС‹СЃР»Р°
  local drop_nginx=false
  askyn drop_nginx "РЈРґР°Р»РёС‚СЊ Рё РєРѕРЅС„РёРіРё nginx СЃС‚РµРєР° (SNI-СЂРѕСѓС‚РµСЂ, stack.conf)?" "y"
  if [[ "$drop_nginx" == true ]]; then
    rm -f /etc/nginx/streams-enabled/sni-router.conf /etc/nginx/streams-available/sni-router.conf 2>/dev/null || true
    rm -f "$STACK_LINK" "$STACK_CONF" 2>/dev/null || true
    if command -v nginx >/dev/null 2>&1; then
      nginx_reload || warn "РљРѕРЅС„РёРіРё СѓРґР°Р»РµРЅС‹, РЅРѕ nginx РЅРµ СѓРґР°Р»РѕСЃСЊ РїСЂРѕРІРµСЂРёС‚СЊ/РїРµСЂРµР·Р°РіСЂСѓР·РёС‚СЊ"
    else
      log "РљРѕРЅС„РёРіРё nginx СЃС‚РµРєР° СѓРґР°Р»РµРЅС‹; nginx СѓР¶Рµ РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ."
    fi
    log "РљРѕРЅС„РёРіРё nginx СЃС‚РµРєР° СѓРґР°Р»РµРЅС‹."
  fi
  log "РџР°РЅРµР»СЊ LucX UI СѓРґР°Р»РµРЅР°. Р‘СЌРєР°Рї: /root/x-ui-backup-*.tar.gz"

  # Р‘РµР· РїР°РЅРµР»Рё СЃС‚РµРє РјС‘СЂС‚РІ вЂ” РїСЂРµРґР»Р°РіР°РµРј СЃСЂР°Р·Сѓ СѓСЃС‚Р°РЅРѕРІРёС‚СЊ РїР°РЅРµР»СЊ СЃ РёРЅР±Р°СѓРЅРґР°РјРё.
  local redeploy=false
  askyn redeploy "РџСЂРёСЃС‚СѓРїРёС‚СЊ Рє СѓСЃС‚Р°РЅРѕРІРєРµ РїР°РЅРµР»Рё СЃ РЅР°СЃС‚СЂРѕР№РєРѕР№ РёРЅР±Р°СѓРЅРґРѕРІ?" "y"
  if [[ "$redeploy" == true ]]; then
    initial_setup || err "РџРµСЂРІРѕРЅР°С‡Р°Р»СЊРЅР°СЏ СѓСЃС‚Р°РЅРѕРІРєР° Р·Р°РІРµСЂС€РёР»Р°СЃСЊ СЃ РѕС€РёР±РєРѕР№ вЂ” Р·Р°РїСѓСЃС‚Рё Рї.1 РІСЂСѓС‡РЅСѓСЋ"
  else
    log "Р’С‹С…РѕРґ РёР· СЃРєСЂРёРїС‚Р°."
    exit 0
  fi
}

# --- РћР±РЅРѕРІР»РµРЅРёРµ СЃРєСЂРёРїС‚Р° СЃ GitHub ---------------------------------------------
# Р’РµСЂСЃРёСЏ С…СЂР°РЅРёС‚СЃСЏ РІ STACK_MANAGER_VERSION Рё РїРѕРєР°Р·С‹РІР°РµС‚СЃСЏ РІ С€Р°РїРєРµ.
# URL Р±РµСЂС‘С‚СЃСЏ РёР· /root/.stack-src (СЃРѕС…СЂР°РЅСЏРµС‚СЃСЏ РїРѕСЃР»Рµ РїРµСЂРІРѕРіРѕ РѕР±РЅРѕРІР»РµРЅРёСЏ).
version_is_newer() {
  local old="$1" new="$2" oa ob oc na nb nc
  IFS=. read -r oa ob oc <<<"${old#v}"
  IFS=. read -r na nb nc <<<"${new#v}"
  oa=${oa:-0}; ob=${ob:-0}; oc=${oc:-0}; na=${na:-0}; nb=${nb:-0}; nc=${nc:-0}
  (( 10#$na > 10#$oa ||
     (10#$na == 10#$oa && 10#$nb > 10#$ob) ||
     (10#$na == 10#$oa && 10#$nb == 10#$ob && 10#$nc > 10#$oc) ))
}
STACK_SRC_URL="$(cat /root/.stack-src 2>/dev/null || echo 'https://raw.githubusercontent.com/vladufqaa/stack-manager/main/stack-manager.sh')"

update_self() {
  line; echo -e "${B}   РћР‘РќРћР’Р›Р•РќРР• РЎРљР РРџРўРђ РЎ GITHUB${N}"; line
  # РЎСЂР°РІРЅРёРІР°РµРј РёРјРµРЅРЅРѕ Р·Р°РїСѓС‰РµРЅРЅС‹Р№ С„Р°Р№Р», Р° РЅРµ Р±РµР·СѓСЃР»РѕРІРЅРѕ /root/stack-manager.sh:
  # РїСЂРё Р·Р°РїСѓСЃРєРµ РєРѕРїРёРё РёР· РґСЂСѓРіРѕРіРѕ РїСѓС‚Рё СЃС‚Р°СЂС‹Р№ РєРѕРґ РѕС€РёР±РѕС‡РЅРѕ СЃРѕРѕР±С‰Р°Р» В«РёРґРµРЅС‚РёС‡РµРЅВ».
  local cur="${BASH_SOURCE[0]}" src_url="$STACK_SRC_URL" tmp="" lock="" bakdir="" old_sha="" new_sha="" mode="" remote_version=""
  cur=$(readlink -f "$cur" 2>/dev/null || printf '%s' "$cur")
  [[ -f "$cur" && ! -L "$cur" ]] || cur="/root/stack-manager.sh"
  lock="${cur}.update.lock"
  exec 9>"$lock" || { err "РќРµ СѓРґР°Р»РѕСЃСЊ РѕС‚РєСЂС‹С‚СЊ lock-С„Р°Р№Р» РѕР±РЅРѕРІР»РµРЅРёСЏ"; return 1; }
  flock -n 9 || { err "РћР±РЅРѕРІР»РµРЅРёРµ СѓР¶Рµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ РґСЂСѓРіРёРј РїСЂРѕС†РµСЃСЃРѕРј"; return 1; }
  tmp=$(mktemp "$(dirname "$cur")/.stack-manager.update.XXXXXX") || { err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕР·РґР°С‚СЊ РІСЂРµРјРµРЅРЅС‹Р№ С„Р°Р№Р»"; return 1; }
  trap 'rm -f "$tmp" 2>/dev/null || true; flock -u 9 2>/dev/null || true' RETURN
  ask src_url "Raw-URL СЃРєСЂРёРїС‚Р° (Enter вЂ” СЃРѕС…СЂР°РЅС‘РЅРЅС‹Р№)" "$src_url" '^https?://'
  log "РљР°С‡Р°СЋ: $src_url"
  # raw.githubusercontent РєСЌС€РёСЂСѓРµС‚СЃСЏ ~5 РјРёРЅСѓС‚ (Fastly): СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ РїСѓС€Р° РјРѕР¶РЅРѕ
  # СЃРєР°С‡Р°С‚СЊ СЃС‚Р°СЂСѓСЋ РІРµСЂСЃРёСЋ Рё РїРѕР»СѓС‡РёС‚СЊ Р»РѕР¶РЅРѕРµ В«РѕР±РЅРѕРІР»РµРЅРёРµ РЅРµ С‚СЂРµР±СѓРµС‚СЃСЏВ».
  # ?ts=вЂ¦ РјРµРЅСЏРµС‚ РєР»СЋС‡ РєСЌС€Р° в†’ РІСЃРµРіРґР° СЃРІРµР¶РёР№ С„Р°Р№Р». Р’ /root/.stack-src РїРёС€РµРј
  # С‡РёСЃС‚С‹Р№ URL (Р±РµР· Р±Р°СЃС‚РµСЂР°).
  # РћР±С…РѕРґРёРј РєСЌС€ raw.githubusercontent РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ С‚РѕРіРѕ, РµСЃС‚СЊ Р»Рё РІ URL
  # СѓР¶Рµ query-РїР°СЂР°РјРµС‚СЂС‹. Р—Р°РіРѕР»РѕРІРєРё no-cache РґРѕРїРѕР»РЅСЏСЋС‚ СѓРЅРёРєР°Р»СЊРЅС‹Р№ nonce.
  local sep='?'; [[ "$src_url" == *\?* ]] && sep='&'
  local bust_url="${src_url}${sep}stack_nonce=$(date +%s%N)-$$"
  if ! curl -fsSL -H 'Cache-Control: no-cache, no-store' -H 'Pragma: no-cache' \
      --retry 3 --retry-delay 1 --max-time 45 "$bust_url" -o "$tmp" || [[ ! -s "$tmp" ]]; then
    err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРєР°С‡Р°С‚СЊ (РїСЂРѕРІРµСЂСЊ URL/РґРѕСЃС‚СѓРїРЅРѕСЃС‚СЊ СЂРµРїРѕР·РёС‚РѕСЂРёСЏ)"
    rm -f "$tmp"; return 1
  fi
  # GitHub/РїСЂРѕРєСЃРё РёРЅРѕРіРґР° РґРѕР±Р°РІР»СЏСЋС‚ CRLF РёР»Рё UTF-8 BOM. РќРѕСЂРјР°Р»РёР·СѓРµРј
  # Р·Р°РіСЂСѓР¶РµРЅРЅС‹Р№ С„Р°Р№Р» Р”Рћ bash -n Рё Р°С‚РѕРјР°СЂРЅРѕР№ СѓСЃС‚Р°РЅРѕРІРєРё, РёРЅР°С‡Рµ Bash СѓРІРёРґРёС‚
  # shebang СЃ CR Рё РїРѕСЃР»Рµ РїРµСЂРµР·Р°РїСѓСЃРєР° РІС‹РґР°СЃС‚ В«/usr/bin/env: No such fileВ».
  sed -i 's/\r$//' "$tmp"
  if [[ "$(LC_ALL=C od -An -t x1 -N3 "$tmp" 2>/dev/null | tr -d ' ')" == "efbbbf" ]]; then
    tail -c +4 "$tmp" > "${tmp}.nobom" && mv -f "${tmp}.nobom" "$tmp"
  fi
  local _shebang=""
  _shebang=$(head -n1 "$tmp")
  # Shebang РїСЂРѕРІРµСЂСЏРµРј РјСЏРіРєРѕ: РЅРµРєРѕС‚РѕСЂС‹Рµ РїСЂРѕРєСЃРё РјРµРЅСЏСЋС‚ BOM/РїСЂРѕР±РµР»С‹, РЅРѕ
  # РіР»Р°РІРЅС‹Рј РґРѕРєР°Р·Р°С‚РµР»СЊСЃС‚РІРѕРј РѕСЃС‚Р°С‘С‚СЃСЏ СЃС‚СЂРѕРіРёР№ СЃРёРЅС‚Р°РєСЃРёС‡РµСЃРєРёР№ bash -n.
  if [[ ! "$_shebang" =~ bash ]]; then
    warn "РџРµСЂРІР°СЏ СЃС‚СЂРѕРєР° РЅРµ СЂР°СЃРїРѕР·РЅР°РЅР° РєР°Рє shebang Bash вЂ” РїСЂРѕРґРѕР»Р¶Р°СЋ, bash -n РїСЂРѕРІРµСЂРёС‚ С„Р°Р№Р»"
  fi
  bash -n "$tmp" || { err "РќРѕРІС‹Р№ С„Р°Р№Р» РЅРµ РїСЂРѕС…РѕРґРёС‚ bash -n вЂ” РѕР±РЅРѕРІР»РµРЅРёРµ РѕС‚РјРµРЅРµРЅРѕ"; rm -f "$tmp"; return 1; }
  old_sha=$(sha256sum "$cur" | awk '{print $1}')
  new_sha=$(sha256sum "$tmp" | awk '{print $1}')
  # Р•СЃР»Рё СЃРµС‚СЊ/РїСЂРѕРєСЃРё РІРµСЂРЅСѓР»Рё СЃС‚Р°СЂСѓСЋ РєРѕРїРёСЋ GitHub, РЅРµ РѕР±СЉСЏРІР»СЏРµРј РµС‘ Р°РєС‚СѓР°Р»СЊРЅРѕР№:
  # СЃСЂР°РІРЅРёРІР°РµРј СЃРѕРґРµСЂР¶РёРјРѕРµ С‚Р°РєР¶Рµ СЃ РєРѕСЂРѕС‚РєРёРј commit API (РµСЃР»Рё РґРѕСЃС‚СѓРїРµРЅ).
  local remote_sha=""
  remote_version=$(grep -m1 -E '^STACK_MANAGER_VERSION="[^"]+"' "$tmp" | sed -E 's/^STACK_MANAGER_VERSION="([^"]+)"/\1/' || true)
  if [[ -z "$remote_version" ]]; then
    warn "Р’ Р·Р°РіСЂСѓР¶РµРЅРЅРѕРј С„Р°Р№Р»Рµ РЅРµ РЅР°Р№РґРµРЅР° STACK_MANAGER_VERSION вЂ” РѕР±РЅРѕРІР»РµРЅРёРµ РѕС‚РјРµРЅРµРЅРѕ"
    rm -f "$tmp"; return 1
  fi
  if [[ "$src_url" == https://raw.githubusercontent.com/*/*/main/* ]]; then
    local api_repo api_file
    api_repo=$(printf '%s' "$src_url" | sed -E 's#https://raw.githubusercontent.com/([^/]+/[^/]+)/main/.*#\1#')
    api_file=$(printf '%s' "$src_url" | sed -E 's#https://raw.githubusercontent.com/[^/]+/[^/]+/main/##')
    remote_sha=$(curl -fsSL -H 'Cache-Control: no-cache' \
      "https://api.github.com/repos/$api_repo/commits?path=$api_file&per_page=1" 2>/dev/null \
      | grep -m1 '"sha"' | sed -E 's/.*"sha"[[:space:]]*:[[:space:]]*"([0-9a-f]+)".*/\1/' || true)
  fi
  if [[ "$remote_version" == "$STACK_MANAGER_VERSION" ]]; then
    log "РћР±РЅРѕРІР»РµРЅРёРµ РЅРµ С‚СЂРµР±СѓРµС‚СЃСЏ вЂ” РІРµСЂСЃРёСЏ v$STACK_MANAGER_VERSION СѓР¶Рµ Р°РєС‚СѓР°Р»СЊРЅР° (sha256: $new_sha)"
    rm -f "$tmp"; return 0
  fi
  if ! version_is_newer "$STACK_MANAGER_VERSION" "$remote_version"; then
    warn "РћР±РЅРѕРІР»РµРЅРёРµ РѕС‚РјРµРЅРµРЅРѕ: СѓРґР°Р»С‘РЅРЅР°СЏ РІРµСЂСЃРёСЏ v$remote_version РЅРµ РЅРѕРІРµРµ Р»РѕРєР°Р»СЊРЅРѕР№ v$STACK_MANAGER_VERSION"
    rm -f "$tmp"; return 1
  fi
  echo "  РІРµСЂСЃРёСЏ: v$STACK_MANAGER_VERSION в†’ v$remote_version"
  echo "  sha256: $old_sha в†’ $new_sha"
  local yn=false
  askyn yn "РЎРѕС…СЂР°РЅРёС‚СЊ СЂРµР·РµСЂРІРЅСѓСЋ РєРѕРїРёСЋ Рё Р·Р°РјРµРЅРёС‚СЊ $cur?" "y"
  [[ "$yn" == true ]] || { rm -f "$tmp"; log "РћС‚РјРµРЅРµРЅРѕ"; return 0; }
  bakdir="$BACKUP_DIR/self-update-$(date +%Y%m%d-%H%M%S)"
  mkdir -p "$bakdir" || { err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕР·РґР°С‚СЊ РєР°С‚Р°Р»РѕРі РѕС‚РєР°С‚Р°"; return 1; }
  mode=$(stat -c '%a' "$cur" 2>/dev/null || echo 700)
  cp -p "$cur" "$bakdir/stack-manager.sh" || { err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕС…СЂР°РЅРёС‚СЊ СЃС‚Р°СЂСѓСЋ РІРµСЂСЃРёСЋ"; return 1; }
  printf 'old_sha=%s\nnew_sha=%s\nsource=%s\n' "$old_sha" "$new_sha" "$src_url" > "$bakdir/metadata"
  sha256sum "$bakdir/stack-manager.sh" > "$bakdir/stack-manager.sh.sha256"; sync
  mv -f "$tmp" "$cur" || { err "РќРµ СѓРґР°Р»РѕСЃСЊ Р°С‚РѕРјР°СЂРЅРѕ Р·Р°РјРµРЅРёС‚СЊ СЃРєСЂРёРїС‚"; return 1; }
  chmod "$mode" "$cur" 2>/dev/null || chmod 700 "$cur"; sync
  # РџРѕСЃР»Рµ Р·Р°РјРµРЅС‹ РїСЂРѕРІРµСЂСЏРµРј С‚РѕР»СЊРєРѕ СЃР°Рј С„Р°Р№Р». --check Р·Р°РїСѓСЃРєР°РµС‚ РїРѕР»РЅРѕС†РµРЅРЅС‹Р№ Р°СѓРґРёС‚
  # СЃРµСЂРІРµСЂР° Рё Р·Р°РєРѕРЅРѕРјРµСЂРЅРѕ РІРѕР·РІСЂР°С‰Р°РµС‚ РЅРµРЅСѓР»РµРІРѕР№ РєРѕРґ РїСЂРё СѓРґР°Р»С‘РЅРЅРѕР№ РїР°РЅРµР»Рё/nginx,
  # РїРѕСЌС‚РѕРјСѓ РµРіРѕ СЂРµР·СѓР»СЊС‚Р°С‚ РЅРµР»СЊР·СЏ РёСЃРїРѕР»СЊР·РѕРІР°С‚СЊ РєР°Рє РєСЂРёС‚РµСЂРёР№ РІР°Р»РёРґРЅРѕСЃС‚Рё РѕР±РЅРѕРІР»РµРЅРёСЏ.
  if ! bash -n "$cur" || [[ "$(sha256sum "$cur" | awk '{print $1}')" != "$new_sha" ]]; then
    err "РџСЂРѕРІРµСЂРєР° РЅРѕРІРѕРіРѕ С„Р°Р№Р»Р° РЅРµ РїСЂРѕР№РґРµРЅР° вЂ” РІС‹РїРѕР»РЅСЏСЋ РѕС‚РєР°С‚"
    cp -p "$bakdir/stack-manager.sh" "$cur"; chmod "$mode" "$cur" 2>/dev/null || true; sync; return 1
  fi
  printf '%s' "$src_url" > /root/.stack-src && chmod 600 /root/.stack-src
  # РћР±РЅРѕРІР»РµРЅРёРµ Р·Р°РїСѓСЃРєР°РµС‚СЃСЏ РїРѕРІРµСЂС… СѓР¶Рµ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РµР№ СЃРёСЃС‚РµРјС‹. РќРµ СЃС‡РёС‚Р°РµРј
  # РїРµСЂРµР·Р°РїСѓСЃРє РїРѕСЃР»Рµ self-update В«РїРµСЂРІС‹Рј Р·Р°РїСѓСЃРєРѕРјВ» Рё РЅРµ РїРѕРєР°Р·С‹РІР°РµРј РїРѕРІС‚РѕСЂРЅРѕ
  # pre-install-РІРѕРїСЂРѕСЃ С‚РѕР»СЊРєРѕ РёР·-Р·Р° РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РµРіРѕ СЃС‚Р°СЂРѕРіРѕ РјР°СЂРєРµСЂР°.
  mkdir -p "$BACKUP_DIR" 2>/dev/null || true
  touch "$BACKUP_DIR/.stack-ever-ran" 2>/dev/null || true
  log "РћР±РЅРѕРІР»РµРЅРѕ Р°С‚РѕРјР°СЂРЅРѕ вњ“ (backup: $bakdir) вЂ” РїРµСЂРµР·Р°РїСѓСЃРєР°СЋСЃСЊвЂ¦"
  trap - RETURN; flock -u 9 2>/dev/null || true
  exec bash "$cur"
}

# =====================================================================
# Р•Р”РРќР«Р• Р‘Р›РћРљР Р’РћРџР РћРЎРћР’ РЈРЎРўРђРќРћР’РљР вЂ” РѕР±С‰РёР№ РїСѓС‚СЊ РґР»СЏ Рї.1 (РїРµСЂРІРёС‡РЅР°СЏ
# РЅР°СЃС‚СЂРѕР№РєР°), Рї.17 (РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєР° РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ) Рё Р°РІС‚Рѕ-РїРѕРґСЉС‘РјР°.
# РџРѕСЂСЏРґРѕРє Р’РЎР•Р“Р”Рђ: РїР°РЅРµР»СЊ (РїР°СЂРѕР»СЊ+РїРѕСЂС‚С‹) в†’ AdGuard (РґР°/РЅРµС‚+РїР°СЂРѕР»СЊ+РіРґРµ) в†’
# Р·Р°РіР»СѓС€РєР° РїР°РЅРµР»Рё в†’ СЃРµСЂС‚С‹ (С‚РёРї 1/2, СѓР¶Рµ РІ cert_issue) в†’ РёРЅР±Р°СѓРЅРґС‹.
# =====================================================================
ask_panel_creds() {
  # РџРђРќР•Р›Р¬ РЈР–Р• РЈРЎРўРђРќРћР’Р›Р•РќРђ в†’ Р±РµСЂС‘Рј РµС‘ С‚РµРєСѓС‰РёРµ Р·РЅР°С‡РµРЅРёСЏ Рё РќРР§Р•Р“Рћ РЅРµ СЃРїСЂР°С€РёРІР°РµРј:
  # РїРѕСЂС‚С‹/РїСѓС‚Рё РѕСЃС‚Р°СЋС‚СЃСЏ РєР°Рє РµСЃС‚СЊ, РїР°СЂРѕР»СЊ РІ Р‘Р” РЅРµ С‚СЂРѕРіР°РµРј (РµРіРѕ РІСЃС‘ СЂР°РІРЅРѕ
  # РЅРµР»СЊР·СЏ В«РїСЂРѕС‡РёС‚Р°С‚СЊВ» вЂ” Р° СЃРїСЂР°С€РёРІР°С‚СЊ = РїСЂРµРґР»Р°РіР°С‚СЊ СЃРјРµРЅРёС‚СЊ, СЌС‚Рѕ Р»РѕРјР°РµС‚ РІС…РѕРґ).
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local _wp _ws _bp _sp
    _wp=$(xui_get webPort);     _ws=$(xui_get subPort)
    _bp=$(xui_get webBasePath); _sp=$(xui_get subPath)
    # РЎСѓС‰РµСЃС‚РІРµРЅРЅС‹Рµ вЂ” С‚РѕР»СЊРєРѕ РїРѕСЂС‚/РїСѓС‚СЊ РџРђРќР•Р›Р. РџРѕРґРїРёСЃРєРё Сѓ СЃРІРµР¶РµРіРѕ LucX РїСѓСЃС‚С‹Рµ
    # (СѓСЃС‚Р°РЅРѕРІС‰РёРє РёС… РЅРµ Р·Р°РґР°С‘С‚) вЂ” СЌС‚Рѕ РЅРµ РїРѕРІРѕРґ СѓС…РѕРґРёС‚СЊ РІ РїРµСЂРµСЃРїСЂР°С€РёРІР°РЅРёРµ.
    if [[ -n "$_wp" && -n "$_bp" ]]; then
      U_PANEL_PASS="${U_PANEL_PASS:-}"   # РїР°СЂРѕР»СЊ РЅРµ СЃРїСЂР°С€РёРІР°РµРј Рё РЅРµ РјРµРЅСЏРµРј
      # Р•СЃР»Рё РєСЂРµРґС‹/РїРѕСЂС‚С‹ СѓР¶Рµ СЃРѕР±СЂР°РЅС‹ РІ СЌС‚РѕР№ СЃРµСЃСЃРёРё (СЃРїСЂРѕСЃРёР»Рё Р”Рћ СѓСЃС‚Р°РЅРѕРІРєРё вЂ”
      # РµРґРёРЅС‹Р№ РїСѓС‚СЊ РїРµСЂРІРѕРіРѕ Р·Р°РїСѓСЃРєР°) вЂ” СЃРѕС…СЂР°РЅСЏРµРј РёС…; РёРЅР°С‡Рµ Р±РµСЂС‘Рј С„Р°РєС‚РёС‡РµСЃРєРёРµ
      # Р·РЅР°С‡РµРЅРёСЏ СѓСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕР№ РїР°РЅРµР»Рё (РїРѕРІС‚РѕСЂРЅС‹Р№ Рї.1 РЅР° Р¶РёРІРѕРј СЃС‚РµРєРµ).
      if [[ -n "${U_PANEL_PORT}${U_PANEL_PATH}${U_SUB_PORT}${U_SUB_PATH}" ]]; then
        log "РџР°РЅРµР»СЊ СѓСЃС‚Р°РЅРѕРІР»РµРЅР° вЂ” РїРѕСЂС‚С‹/РїСѓС‚Рё РёР· Р°РЅРєРµС‚С‹ СЌС‚РѕР№ СЃРµСЃСЃРёРё СЃРѕС…СЂР°РЅСЏСЋ:"
        log "  РїР°РЅРµР»СЊ   : $U_PANEL_PORT $U_PANEL_PATH"
        log "  РїРѕРґРїРёСЃРєРё : $U_SUB_PORT $U_SUB_PATH"
      else
        U_PANEL_PORT="$_wp"; U_PANEL_PATH="$_bp"
        U_SUB_PORT="$_ws";   U_SUB_PATH="$_sp"
        # РЎРІРµР¶РёР№ LucX: РїРѕРґРїРёСЃРѕС‡РЅС‹С… РЅР°СЃС‚СЂРѕРµРє РЅРµС‚ вЂ” РіРµРЅРµСЂРёСЂСѓРµРј СЃР»СѓС‡Р°Р№РЅС‹Рµ (С‚Р° Р¶Рµ
        # СЃРµРјР°РЅС‚РёРєР° В«Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№В»), РёРЅР°С‡Рµ initial_setup РїРѕР»СѓС‡РёС‚ РїСѓСЃС‚С‹Рµ
        # SUB_PORT/SUB_PATH Рё Р·Р°РїРёС€РµС‚ РїСѓСЃС‚РѕС‚Сѓ РІ РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё.
        [[ -z "$U_SUB_PORT" ]] && U_SUB_PORT=$(make_port)
        [[ -z "$U_SUB_PATH" ]] && U_SUB_PATH="/$(gen_random_string 10)/"
        log "РџР°РЅРµР»СЊ СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР° вЂ” Р±РµСЂСѓ РµС‘ РЅР°СЃС‚СЂРѕР№РєРё Р±РµР· РёР·РјРµРЅРµРЅРёР№:"
        log "  РїР°РЅРµР»СЊ   : $_wp $_bp"
        log "  РїРѕРґРїРёСЃРєРё : $U_SUB_PORT $U_SUB_PATH"
      fi
      return 0
    fi
  fi
  # СЃРІРµР¶Р°СЏ РїР°РЅРµР»СЊ (РёР»Рё Рї.17 СѓРґР°Р»РёР»): РѕР±С‹С‡РЅС‹Р№ РїСѓС‚СЊ вЂ” РІРѕРїСЂРѕСЃС‹.
  # РџР°СЂРѕР»СЊ СѓР¶Рµ Р·Р°РґР°РЅ (СЃРѕР±СЂР°РЅ СЂР°РЅСЊС€Рµ РІ СЌС‚РѕР№ СЃРµСЃСЃРёРё) в†’ РЅРµ РїРµСЂРµРіРµРЅРµСЂРёСЂСѓРµРј.
  if [[ -z "${U_PANEL_PASS:-}" ]]; then
    U_PANEL_USER="${U_PANEL_USER:-admin}"
    U_PANEL_PASS=$(openssl rand -base64 18 2>/dev/null | tr -dc 'a-zA-Z0-9' | head -c 16)
    if [[ -t 0 ]]; then
      ask U_PANEL_USER "Р›РѕРіРёРЅ РїР°РЅРµР»Рё (Enter вЂ” admin)" "$U_PANEL_USER" '^[a-zA-Z0-9._-]{3,32}$'
      ask U_PANEL_PASS "РџР°СЂРѕР»СЊ РїР°РЅРµР»Рё (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№)" "$U_PANEL_PASS" '^.{6,}$'
    fi
  fi
  # РЈР¶Рµ СЃРѕР±СЂР°РЅС‹ РІ СЌС‚РѕР№ СЃРµСЃСЃРёРё (РїРµСЂРІС‹Р№ ask_panel_creds РґРѕ СѓСЃС‚Р°РЅРѕРІРєРё РїР°РЅРµР»Рё вЂ”
  # РµРґРёРЅС‹Р№ РїСѓС‚СЊ РїРµСЂРІРѕРіРѕ Р·Р°РїСѓСЃРєР°) в†’ РІС‚РѕСЂРѕР№ СЂР°Р· РќР• СЃРїСЂР°С€РёРІР°РµРј Рё РќР• С‡РёСЃС‚РёРј.
  if [[ -n "${U_PANEL_PORT}${U_PANEL_PATH}${U_SUB_PORT}${U_SUB_PATH}" ]]; then
    log "РџРѕСЂС‚С‹/РїСѓС‚Рё СѓР¶Рµ СЃРѕР±СЂР°РЅС‹ РІ СЌС‚РѕР№ СЃРµСЃСЃРёРё вЂ” РїРѕРІС‚РѕСЂРЅРѕ РЅРµ СЃРїСЂР°С€РёРІР°СЋ:"
    log "  РїР°РЅРµР»СЊ   : ${U_PANEL_PORT:-СЃР»СѓС‡Р°Р№РЅС‹Р№} ${U_PANEL_PATH:-СЃР»СѓС‡Р°Р№РЅС‹Р№}"
    log "  РїРѕРґРїРёСЃРєРё : ${U_SUB_PORT:-СЃР»СѓС‡Р°Р№РЅС‹Р№} ${U_SUB_PATH:-СЃР»СѓС‡Р°Р№РЅС‹Р№}"
  else
    U_PANEL_PORT=""; U_SUB_PORT=""; U_PANEL_PATH=""; U_SUB_PATH=""
    ask U_PANEL_PORT "РџРѕСЂС‚ РїР°РЅРµР»Рё (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№)"       "" '^[0-9]*$'
    ask U_PANEL_PATH "РџСѓС‚СЊ РїР°РЅРµР»Рё (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№)"       "/$(gen_random_string 12)/" '^[a-zA-Z0-9/_-]*$'
    ask U_SUB_PORT  "РџРѕСЂС‚ РїРѕРґРїРёСЃРѕРє (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№)"     "" '^[0-9]*$'
    ask U_SUB_PATH  "РџСѓС‚СЊ РїРѕРґРїРёСЃРѕРє (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№)"     "/$(gen_random_string 10)/" '^[a-zA-Z0-9/_-]*$'
  fi
  [[ "$U_PANEL_PATH" != /* ]] && U_PANEL_PATH="/$U_PANEL_PATH"
  [[ "$U_PANEL_PATH" != */ ]] && U_PANEL_PATH="$U_PANEL_PATH/"
  [[ "$U_SUB_PATH"  != /* ]] && U_SUB_PATH="/$U_SUB_PATH"
  [[ "$U_SUB_PATH"  != */ ]] && U_SUB_PATH="$U_SUB_PATH/"
  [[ -n "$U_PANEL_PORT" && ( "$U_PANEL_PORT" -lt 1    || "$U_PANEL_PORT" -gt 65535 ) ]] && { err "РќРµРєРѕСЂСЂРµРєС‚РЅС‹Р№ РїРѕСЂС‚ РїР°РЅРµР»Рё"; return 1; }
  [[ -n "$U_SUB_PORT"   && ( "$U_SUB_PORT"   -lt 1    || "$U_SUB_PORT"   -gt 65535 ) ]] && { err "РќРµРєРѕСЂСЂРµРєС‚РЅС‹Р№ РїРѕСЂС‚ РїРѕРґРїРёСЃРѕРє"; return 1; }
  if [[ -n "$U_PANEL_PORT" && -n "$U_SUB_PORT" && "$U_PANEL_PORT" == "$U_SUB_PORT" ]]; then
    err "РџРѕСЂС‚ РїР°РЅРµР»Рё Рё РїРѕСЂС‚ РїРѕРґРїРёСЃРѕРє СЃРѕРІРїР°РґР°СЋС‚ ($U_PANEL_PORT) вЂ” СѓРєР°Р¶РёС‚Рµ СЂР°Р·РЅС‹Рµ."; return 1
  fi
  if [[ "$U_PANEL_PATH" == "$U_SUB_PATH" ]]; then
    err "РџСѓС‚СЊ РїР°РЅРµР»Рё Рё РїСѓС‚СЊ РїРѕРґРїРёСЃРѕРє СЃРѕРІРїР°РґР°СЋС‚ ($U_PANEL_PATH) вЂ” СѓРєР°Р¶РёС‚Рµ СЂР°Р·РЅС‹Рµ."; return 1
  fi
  return 0
}

ask_adguard_and_decoy() {
  # AdGuard: РґР°/РЅРµС‚ в†’ СѓСЃС‚Р°РЅРѕРІРєР° в†’ РїР°СЂРѕР»СЊ в†’ СЂР°Р·РјРµС‰РµРЅРёРµ
  if [[ "$ADG_PRESENT" != true ]]; then
    local adg_install=false
    [[ -t 0 ]] && askyn adg_install "РЈСЃС‚Р°РЅРѕРІРёС‚СЊ AdGuard Home?" "n"
    if [[ "$adg_install" == true ]]; then
      install_adguard_home || warn "AdGuard РЅРµ СѓСЃС‚Р°РЅРѕРІРёР»СЃСЏ вЂ” РїСЂРѕРґРѕР»Р¶Р°РµРј Р±РµР· РЅРµРіРѕ."
      detect_env
      [[ "$ADG_PRESENT" == true ]] && ADG_JUST_INSTALLED=true
    fi
  fi
  ADG_PLACEMENT=""
  local adg_installed_now=false
  if [[ "$ADG_PRESENT" == true ]]; then
    if [[ -t 0 ]]; then
      if [[ "${ADG_JUST_INSTALLED:-}" == true ]]; then
        # СѓСЃС‚Р°РЅРѕРІРёР»Рё РўРћР›Р¬РљРћ Р§РўРћ РІ СЌС‚РѕРј Р·Р°РїСѓСЃРєРµ вЂ” РєСЂРµРґС‹ СЃРїСЂР°С€РёРІР°РµРј
        adg_installed_now=true
        if [[ -z "${U_ADG_PASS:-}" ]]; then
          U_ADG_USER="${U_ADG_USER:-admin}"
          U_ADG_PASS=$(openssl rand -base64 18 2>/dev/null | tr -dc 'a-zA-Z0-9' | head -c 16)
          [[ -z "$U_ADG_PASS" ]] && U_ADG_PASS="AdG$(date +%s)"
          ask U_ADG_USER "Р›РѕРіРёРЅ AdGuard (Enter вЂ” admin)" "$U_ADG_USER" '^[a-zA-Z0-9._-]{3,32}$'
          ask U_ADG_PASS "РџР°СЂРѕР»СЊ AdGuard (Enter вЂ” СЃР»СѓС‡Р°Р№РЅС‹Р№)" "$U_ADG_PASS" '^.{6,}$'
        elif [[ -z "${U_ADG_USER_SET:-}" ]]; then
          # РїР°СЂРѕР»СЊ СѓР¶Рµ Р·Р°РґР°РЅ (СѓСЃС‚Р°РЅРѕРІРєРѕР№ РІС‹С€Рµ), Р»РѕРіРёРЅ СѓС‚РѕС‡РЅСЏРµРј РѕРґРёРЅ СЂР°Р·
          U_ADG_USER="${U_ADG_USER:-admin}"
          ask U_ADG_USER "Р›РѕРіРёРЅ AdGuard (Enter вЂ” admin)" "$U_ADG_USER" '^[a-zA-Z0-9._-]{3,32}$'
          U_ADG_USER_SET=1
        fi
      else
        # Р±С‹Р» СѓСЃС‚Р°РЅРѕРІР»РµРЅ Р РђРќР¬РЁР• вЂ” РєСЂРµРґС‹ РЅРµ С‚СЂРѕРіР°РµРј Рё РЅРµ СЃРїСЂР°С€РёРІР°РµРј (РєР°Рє СЃ РїР°РЅРµР»СЊСЋ)
        log "AdGuard Home СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” Р»РѕРіРёРЅ/РїР°СЂРѕР»СЊ РЅРµ С‚СЂРѕРіР°СЋ (РєСЂРµРґС‹: /root/adguard-credentials.txt РёР»Рё С‚РІРѕРё)"
      fi
      echo "  AdGuard Home вЂ” РіРґРµ РїРѕРєР°Р·С‹РІР°С‚СЊ РІРµР±-РёРЅС‚РµСЂС„РµР№СЃ?"
      echo "   1) Р—Р° РґРѕРјРµРЅРѕРј РїР°РЅРµР»Рё   (https://<РїР°РЅРµР»СЊ>/, DoH С‚Р°Рј Р¶Рµ)"
      echo "   2) РћС‚РґРµР»СЊРЅС‹Р№ SNI-РґРѕРјРµРЅ (adguard.<Р±Р°Р·Р°>)"
      echo "   3) РќРµ С‚СЂРѕРіР°С‚СЊ (С‚РѕР»СЊРєРѕ Р»РѕРєР°Р»СЊРЅРѕ)"
      local ap=""
      ask ap "Р Р°Р·РјРµС‰РµРЅРёРµ [1/2/3]" "1" '^[123]$'
      case "$ap" in 2) ADG_PLACEMENT="sni" ;; 3) ADG_PLACEMENT="local" ;; *) ADG_PLACEMENT="panel" ;; esac
    else
      ADG_PLACEMENT="${ADG_PLACEMENT:-panel}"   # РЅРµ-TTY: СЃРѕС…СЂР°РЅСЏРµРј РІС‹Р±РѕСЂ Р°РІС‚Рѕ-РїРѕС‚РѕРєР°
    fi
  fi
  # Р·Р°РіР»СѓС€РєР° РїР°РЅРµР»Рё вЂ” РџРћРЎР›Р• AdGuard (РµСЃР»Рё РєРѕСЂРµРЅСЊ РЅРµ Р·Р°РЅСЏС‚ СЃР°РјРёРј AdGuard)
  PDECOY="${PDECOY:-stub}"
  if [[ -t 0 && "$ADG_PLACEMENT" != "panel" ]]; then
    local pdc3=""
    decoy_panel_choose pdc3 "1"
    PDECOY="$pdc3"
  fi
  # РІС‹Р±РѕСЂ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ (tpl:РРњРЇ / tpl:custom:/РїСѓС‚СЊ) вЂ” РѕР±С‰РёР№ С€Р°Р±Р»РѕРЅ РґР»СЏ РІСЃРµС…
  # РґРѕРјРµРЅРѕРІ СЃС‚РµРєР°, Р° РЅРµ С‚РѕР»СЊРєРѕ РґР»СЏ РїР°РЅРµР»Рё
  decoy_selected_set "$PDECOY"
}

# РџСЂРѕРІРµСЂРєР° UDP-РёРЅР±Р°СѓРЅРґРѕРІ РїСЂРѕС‚РёРІ UFW Рё Р»РѕРєР°Р»СЊРЅРѕРіРѕ СЃР»СѓС€Р°С‚РµР»СЏ.
# РќРµ РѕС‚РєСЂС‹РІР°РµС‚ РїРѕСЂС‚С‹ РјРѕР»С‡Р°: С‚РѕР»СЊРєРѕ РїРѕРєР°Р·С‹РІР°РµС‚ Р·Р°РєСЂС‹С‚С‹Рµ Рё СЃРїСЂР°С€РёРІР°РµС‚ СЂР°Р·СЂРµС€РµРЅРёРµ.
udp_inbound_firewall_check() {
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || return 0
  local id proto port remark rule ask_open listen_state
  local -a closed=()
  while IFS='|' read -r id proto port remark; do
    [[ -n "$id" && -n "$port" && "$port" != 0 ]] || continue
    is_udp_proto "$proto" || continue
    rule=$(ufw status 2>/dev/null | awk -v p="$port" '$0 ~ ("[[:space:]]" p "/udp([[:space:]]|$)") || $0 ~ ("[[:space:]]" p "([[:space:]]|$)") {print; exit}')
    listen_state="РЅРµС‚"
    ss -Hlun "sport = :$port" 2>/dev/null | grep -q . && listen_state="РґР°"
    if [[ -z "$rule" ]]; then
      closed+=("#$id|$proto|$port|$remark|$listen_state")
    else
      : # СЂСѓС‚РёРЅР°: РїСЂР°РІРёР»Рѕ UFW РµСЃС‚СЊ вЂ” РјРѕР»С‡Р°
    fi
  done < <(sqlite3 "$XUI_DB" "SELECT id, protocol, port, COALESCE(remark,'') FROM inbounds WHERE enable=1 AND port>0 ORDER BY id;" 2>/dev/null || true)
  [[ ${#closed[@]} -gt 0 ]] || return 0
  echo
  warn "UDP-РёРЅР±Р°СѓРЅРґС‹ Р±РµР· СЂР°Р·СЂРµС€РµРЅРёСЏ UFW:"
  local row
  for row in "${closed[@]}"; do
    IFS='|' read -r id proto port remark listen_state <<<"$row"
    echo "  #$id ${remark:-$proto} вЂ” UDP/$port, СЃР»СѓС€Р°РµС‚: $listen_state"
  done
  if [[ -t 0 ]]; then
    askyn ask_open "РћС‚РєСЂС‹С‚СЊ СЌС‚Рё UDP-РїРѕСЂС‚С‹ РІ UFW?" "y"
    [[ "$ask_open" == true ]] || return 0
  else
    warn "РќРµРёРЅС‚РµСЂР°РєС‚РёРІРЅС‹Р№ СЂРµР¶РёРј: РїРѕСЂС‚С‹ РЅРµ РѕС‚РєСЂС‹С‚С‹ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё"
    return 0
  fi
  for row in "${closed[@]}"; do
    IFS='|' read -r id proto port remark listen_state <<<"$row"
    fw_allow "$port" udp "udp-РёРЅР±Р°СѓРЅРґ #$id"
    log "UDP/$port РѕС‚РєСЂС‹С‚ РІ UFW РґР»СЏ #$id"
  done
  ufw --force enable >/dev/null 2>&1 || true
}

# Р•РґРёРЅС‹Р№ С„Р°Р№СЂРІРѕР»: СЃР±СЂРѕСЃ в†’ SSH+443 (TCP) в†’ РЅСѓР¶РЅС‹Рµ UDP в†’ DENY РїР°РЅРµР»СЊРЅС‹С… РїРѕСЂС‚РѕРІ.
# Р’С‹Р·С‹РІР°РµС‚СЃСЏ Рё РёР· Р°РІС‚Рѕ-РїРѕРґСЉС‘РјР°, Рё РёР· Рї.1 (РїСЂРё РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєРµ СѓР±РёРІР°РµС‚ СЃС‚Р°СЂС‹Рµ
# РїСЂР°РІРёР»Р° РїСЂРѕС€Р»РѕР№ СѓСЃС‚Р°РЅРѕРІРєРё вЂ” В«РїРѕС‡РµРјСѓ РѕС‚РєСЂС‹С‚С‹ TCP-РїРѕСЂС‚С‹В» Р»РµС‡РёС‚СЃСЏ Р·РґРµСЃСЊ).
firewall_apply() {
  # РЎРЅРёРјРѕРє В«РґРѕ СЃС‚РµРєР°В» вЂ” РѕРґРёРЅ СЂР°Р·, С‡С‚РѕР±С‹ РѕС‚РєР°С‚ С‡РµСЂРµР· СЂР°Р·РґРµР» 5 РёРјРµР» Рє С‡РµРјСѓ РІРµСЂРЅСѓС‚СЊСЃСЏ.
  # save_firewall_state СЃР°Рј Р·Р°С‰РёС‰С‘РЅ РѕС‚ РїРµСЂРµР·Р°РїРёСЃРё: РµСЃР»Рё СЃРЅРёРјРѕРє СѓР¶Рµ РµСЃС‚СЊ вЂ” РјРѕР»С‡Р° РІС‹Р№РґРµС‚.
  save_firewall_state >/dev/null 2>&1 || true
  log "Р¤Р°Р№СЂРІРѕР»: СЃР±СЂРѕСЃ Рё С‚РѕР»СЊРєРѕ РЅРµРѕР±С…РѕРґРёРјРѕРµвЂ¦"
  ufw --force reset >/dev/null 2>&1 || true
  ufw default deny incoming >/dev/null 2>&1 || true
  ufw default allow outgoing >/dev/null 2>&1 || true
  # SSH: РµСЃР»Рё sshd СЃР»СѓС€Р°РµС‚ С‚РѕР»СЊРєРѕ loopback (В«С‡РµСЂРµР· С‚СѓРЅРЅРµР»СЊВ») вЂ” РЅР°СЂСѓР¶Сѓ РЅРµ
  # РѕС‚РєСЂС‹РІР°РµРј. Р Р°РЅСЊС€Рµ РїСЂРѕРІРµСЂРєР° Р±С‹Р»Р° РЅР° С…Р°СЂРґРєРѕРґ 22 Рё РЅР° РєР°СЃС‚РѕРјРЅРѕРј SSH-РїРѕСЂС‚Рµ
  # РѕС€РёР±РѕС‡РЅРѕ РѕС‚РєСЂС‹РІР°Р»Р° РµРіРѕ РЅР°СЂСѓР¶Сѓ.
  if ! ssh_loopback_only; then
    fw_allow "${SSH_PORT:-22}" tcp "SSH"
  else
    ufw delete allow "${SSH_PORT:-22}/tcp" >/dev/null 2>&1 || true
  fi
  fw_allow 443 tcp "HTTPS/SNI"
  # UDP вЂ” С‚РѕР»СЊРєРѕ РёРЅР±Р°СѓРЅРґС‹ РёР· Р‘Р” РїР°РЅРµР»Рё (СЃРєР°РЅ-СЃРѕРєРµС‚С‹ С€СѓРјСЏС‚ ephemeral-РјСѓСЃРѕСЂРѕРј)
  local up
  for up in $(udp_inbound_ports); do
    fw_port_locked "$up" && continue
    fw_allow "$up" udp "udp-РёРЅР±Р°СѓРЅРґ"
  done
  # РґРѕРєС‚СЂРёРЅР° 443: 11443 РЅР°СЂСѓР¶Сѓ РЅРёРєРѕРіРґР° (TCP С‚СѓРЅРЅРµР»СЏ РёРґС‘С‚ С‡РµСЂРµР· nginx:443,
  # UDP вЂ” СЌС‚Рѕ HTTP/3 caddy). Р“Р°СЃРёРј, РµСЃР»Рё РїСЂР°РІРёР»Рѕ РєРѕРіРґР°-С‚Рѕ Р·Р°СЃРµР»Рѕ.
  ufw delete allow 11443/tcp >/dev/null 2>&1 || true
  ufw delete allow 11443/udp >/dev/null 2>&1 || true
  fw_deny_panel_ports
  ufw --force enable >/dev/null 2>&1 || true
  sleep 1
}

# =====================================================================
# Р—Р”РћР РћР’Р¬Р•: UFW-fallback, recidive, Р¶РёРІРѕР№ Р»РѕРі, С€Р°Р±Р»РѕРЅС‹ decoy
# СЃСЃС‹Р»РѕРє, СЃРјРµРЅР° РґРѕРјРµРЅР° РёРЅР±Р°СѓРЅРґР°
# =====================================================================

# РЎС‚Р°С‚СѓСЃ UFW СЃ Р·Р°РїР°СЃРЅС‹Рј РїСѓС‚С‘Рј: Р±РёРЅР°СЂСЊ РјРѕР¶РµС‚ РЅРµ РЅР°С…РѕРґРёС‚СЊСЃСЏ РІ PATH вЂ” С‚РѕРіРґР°
# СЃРјРѕС‚СЂРёРј СЃРµСЂРІРёСЃ (oneshot ufw.service РѕСЃС‚Р°С‘С‚СЃСЏ active РїРѕСЃР»Рµ РїСЂРёРјРµРЅРµРЅРёСЏ РїСЂР°РІРёР»).
ufw_is_active() {
  local ub
  ub=$(command -v ufw 2>/dev/null || true)
  [[ -z "$ub" && -x /usr/sbin/ufw ]] && ub=/usr/sbin/ufw
  if [[ -n "$ub" ]]; then
    # awk С‡РёС‚Р°РµС‚ РІРµСЃСЊ РІС‹РІРѕРґ РґРѕ РєРѕРЅС†Р°: СЃРІСЏР·РєР° `ufw status | head -1 | grep`
    # РїРѕРґ РіР»РѕР±Р°Р»СЊРЅС‹Рј pipefail РјРѕР¶РµС‚ РІРµСЂРЅСѓС‚СЊ 141 (SIGPIPE) РЅР° Р±РѕР»СЊС€РѕРј РІС‹РІРѕРґРµ
    # Рё В«Р°РєС‚РёРІРЅС‹Р№В» UFW РѕС€РёР±РѕС‡РЅРѕ РїРѕСЃС‡РёС‚Р°С‚СЊ РЅРµР°РєС‚РёРІРЅС‹Рј.
    LC_ALL=C "$ub" status 2>/dev/null | awk 'NR==1 && $0 ~ /^Status:[[:space:]]*active/ {f=1} END {exit f?0:1}'
    return $?
  fi
  systemctl is-active --quiet ufw 2>/dev/null
}

# Jail recidive: СЂРµС†РёРґРёРІРёСЃС‚С‹ (3 Р±Р°РЅР° Р·Р° СЃСѓС‚РєРё) РїРѕР»СѓС‡Р°СЋС‚ Р±Р°РЅ РЅР° РЅРµРґРµР»СЋ,
# РєРѕС‚РѕСЂС‹Р№ РїРµСЂРµР¶РёРІР°РµС‚ СЂРµСЃС‚Р°СЂС‚С‹ fail2ban.
f2b_recidive_setup() {
  command -v fail2ban-client >/dev/null 2>&1 || { err "fail2ban РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ"; return 1; }
  local f=/etc/fail2ban/jail.d/recidive.local
  cat > "$f" <<'EOF'
[recidive]
enabled   = true
filter    = recidive
logpath   = /var/log/fail2ban.log
banaction = iptables-allports
bantime   = 1w
findtime  = 1d
maxretry  = 3
EOF
  systemctl restart fail2ban 2>/dev/null || fail2ban-client reload >/dev/null 2>&1 || true
  sleep 1
  if fail2ban-client status recidive >/dev/null 2>&1; then
    log "recidive РІРєР»СЋС‡С‘РЅ: 3 Р±Р°РЅР° Р·Р° СЃСѓС‚РєРё в†’ Р±Р°РЅ РЅР° РЅРµРґРµР»СЋ (РїРµСЂРµР¶РёРІР°РµС‚ СЂРµСЃС‚Р°СЂС‚С‹)"
    audit "f2b: recidive jail РІРєР»СЋС‡С‘РЅ"
  else
    err "recidive РЅРµ РїРѕРґРЅСЏР»СЃСЏ вЂ” СЃРјРѕС‚СЂРё /var/log/fail2ban.log (РІРѕР·РјРѕР¶РЅРѕ, РЅРµС‚ banaction iptables-allports)"
    return 1
  fi
}

f2b_tail() {
  local f=/var/log/fail2ban.log
  [[ -f "$f" ]] || { err "$f РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  line; echo -e "${B}   FAIL2BAN вЂ” Р–РР’РћР™ Р›РћР“ (Ctrl+C вЂ” РІС‹С…РѕРґ)${N}"; line
  tail -n 30 -f "$f"
}

# РЎРјРµРЅР° РґРѕРјРµРЅР° РёРЅР±Р°СѓРЅРґР° Р±РµР· РїРµСЂРµСЃРѕР·РґР°РЅРёСЏ: stop РїР°РЅРµР»Рё в†’ РїСЂР°РІРєР° JSON/hosts/
# SNI-РєР°СЂС‚С‹ в†’ start в†’ nginx reload. Reality: СЃРІРѕР№ decoy РїРµСЂРµРїСЂРёРІСЏР·С‹РІР°РµС‚СЃСЏ
# С‡РµСЂРµР· reality_set_dest, С‡СѓР¶Р°СЏ С†РµР»СЊ вЂ” С‡РµСЂРµР· Р·Р°РјРµРЅСѓ dest/serverNames.
inbound_change_domain() {
  line; echo -e "${B}   РЎРњР•РќРђ Р”РћРњР•РќРђ РРќР‘РђРЈРќР”Рђ (Р±РµР· РїРµСЂРµСЃРѕР·РґР°РЅРёСЏ)${N}"; line
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  db_protect_suspend
  inbounds_live
  local id=""
  ask id "ID РёРЅР±Р°СѓРЅРґР° (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
  [[ "$id" == 0 ]] && return 0
  # CDN-РёРЅР±Р°СѓРЅРґ: РґРѕРјРµРЅ Р¶РёРІС‘С‚ РІ CDN-РїСЂРѕС„РёР»Рµ (origin/cdn), РІ stream РµРіРѕ РЅРµС‚ вЂ”
  # СЃРјРµРЅР° РґРѕРјРµРЅР° = РїРµСЂРµРЅaСЃС‚СЂРѕР№РєР° РїСЂРѕС„РёР»СЏ (nginx-Р±Р»РѕРє, СЃРµСЂС‚, hosts, РїСѓС‚СЊ)
  if [[ -n "$(cdn_profile_get "$id" 2>/dev/null)" ]]; then
    line; echo -e "${B}   РЎРњР•РќРђ Р”РћРњР•РќРђ CDN-РРќР‘РђРЈРќР”Рђ #$id${N}"; line
    cdn_change_profile "$id"
    return 0
  fi
  local row
  row=$(python3 - "$XUI_DB" "$id" <<'PYROW' 2>/dev/null
import sqlite3, json, sys
con = sqlite3.connect(f"file:{sys.argv[1]}?mode=ro", uri=True, timeout=5)
r = con.execute("SELECT protocol,port,settings,stream_settings FROM inbounds WHERE id=?", (int(sys.argv[2]),)).fetchone()
if not r: sys.exit(1)
proto, port, s1, s2 = r
se = json.loads(s1 or "{}"); st = json.loads(s2 or "{}")
rs = st.get("realitySettings") or {}
dom = se.get("domain") or se.get("hostname") or se.get("sni") \
   or (st.get("tlsSettings") or {}).get("serverName") \
   or (rs.get("serverNames") or [""])[0] or ""
dest = rs.get("dest") or rs.get("target") or ""
cert = se.get("certFile") or ""
if not cert:
    c = (st.get("tlsSettings") or {}).get("certificates") or []
    if c: cert = c[0].get("certificateFile", "")
print(f"{proto}|{port}|{dom}|{(st.get('security') or '').lower()}|{dest}|{cert}")
PYROW
) || { err "РРЅР±Р°СѓРЅРґ #$id РЅРµ РЅР°Р№РґРµРЅ"; return 1; }
  local proto port old sec dest cert
  IFS='|' read -r proto port old sec dest cert <<<"$row"
  [[ -z "$old" ]] && { err "РЈ РёРЅР±Р°СѓРЅРґР° РЅРµ РЅР°Р№РґРµРЅ С‚РµРєСѓС‰РёР№ РґРѕРјРµРЅ вЂ” РјРµРЅСЏР№ РІСЂСѓС‡РЅСѓСЋ"; return 1; }
  echo "  #$id: $proto $port/tcp В· РґРѕРјРµРЅ: $old В· security: ${sec:-none} В· dest: ${dest:--}"
  local nd=""
  ask nd "РќРѕРІС‹Р№ РґРѕРјРµРЅ (A-Р·Р°РїРёСЃСЊ в†’ СЌС‚РѕС‚ СЃРµСЂРІРµСЂ)" "" '^[a-zA-Z0-9.-]+$'
  [[ -z "$nd" ]] && return 0
  [[ "$nd" == "$old" ]] && { warn "Р”РѕРјРµРЅ РЅРµ РёР·РјРµРЅРёР»СЃСЏ"; return 0; }
  local srv_ip dip
  srv_ip=$(server_ip4)
  dip=$(dig +short A "$nd" 2>/dev/null | tail -1)
  if [[ "$dip" != "$srv_ip" ]]; then
    warn "DNS: $nd в†’ ${dip:-РЅРµ СЂРµР·РѕР»РІРёС‚СЃСЏ}, Р° СЃРµСЂРІРµСЂ: $srv_ip"
    local go=""
    askyn go "РџСЂРѕРґРѕР»Р¶РёС‚СЊ РІСЃС‘ СЂР°РІРЅРѕ (РєР»РёРµРЅС‚С‹ РЅРµ РїРѕРґРєР»СЋС‡Р°С‚СЃСЏ, РїРѕРєР° DNS РЅРµ РїРѕРїСЂР°РІРёС€СЊ)?" "n"
    [[ "$go" == true ]] || return 0
  fi
  if [[ "$sec" == "tls" ]] && ! cert_paths "$nd" >/dev/null 2>&1; then
    if [[ -n "$WILDCARD_DOMAIN" && "$nd" == *."$WILDCARD_DOMAIN" ]]; then
      log "РЎС‘СЂС‚: wildcard *.$WILDCARD_DOMAIN РїРѕРєСЂС‹РІР°РµС‚ $nd"
    else
      log "РЎС‘СЂС‚Р° РґР»СЏ $nd РЅРµС‚ вЂ” РІС‹РїСѓСЃРєР°СЋ РЅР° РјРµСЃС‚Рµ (certbot)"
      cert_issue "$nd" || warn "РЎРµСЂС‚ РґР»СЏ $nd РЅРµ РІС‹РїСѓС‰РµРЅ вЂ” СЃРґРµР»Р°Р№ СЌС‚Рѕ С‡РµСЂРµР· Рї.10 Рё РїРѕРІС‚РѕСЂРё"
    fi
  fi
  echo "  РџР»Р°РЅ: JSON СЃС‚СЂРёРјР°/РЅР°СЃС‚СЂРѕРµРє ($oldв†’$nd), hosts, SNI-РєР°СЂС‚Р°, reality-dest РїСЂРё РЅРµРѕР±С…РѕРґРёРјРѕСЃС‚Рё."
  local go=""
  askyn go "РњРµРЅСЏС‚СЊ? (РїР°РЅРµР»СЊ Р±СѓРґРµС‚ РѕСЃС‚Р°РЅРѕРІР»РµРЅР° РЅР° РІСЂРµРјСЏ РїСЂР°РІРєРё)" "n"
  [[ "$go" == true ]] || return 0
  auto_backup_stack >/dev/null 2>&1 || true
  local xui_was=""
  if systemctl is-active --quiet x-ui 2>/dev/null; then
    xui_was=1; systemctl stop x-ui >/dev/null 2>&1 || true; sleep 1
  fi
  local pyok=1
  python3 - "$XUI_DB" "$id" "$old" "$nd" <<'PYSET' && pyok=0 || pyok=1
import sqlite3, json, sys
db, iid, old, new = sys.argv[1], int(sys.argv[2]), sys.argv[3], sys.argv[4]
def walk(v):
    if isinstance(v, str):
        return new if v == old else v
    if isinstance(v, list):
        return [walk(x) for x in v]
    if isinstance(v, dict):
        return {k: walk(x) for k, x in v.items()}
    return v
con = sqlite3.connect(db, timeout=10)
con.execute("PRAGMA busy_timeout=8000")
s1, s2 = con.execute("SELECT settings,stream_settings FROM inbounds WHERE id=?", (iid,)).fetchone()
se = json.loads(s1 or "{}"); st = json.loads(s2 or "{}")
se = walk(se); st = walk(st)
# reality: dest СЃ С‡СѓР¶РёРј РґРѕРјРµРЅРѕРј в†’ РЅРѕРІС‹Р№:443; Р»РѕРєР°Р»СЊРЅС‹Р№ decoy (127.*) РЅРµ С‚СЂРѕРіР°РµРј
rs = st.get("realitySettings") or {}
for k in ("dest", "target"):
    d = rs.get(k)
    if isinstance(d, str) and d.startswith(old + ":"):
        rs[k] = new + ":443"
if rs: st["realitySettings"] = rs
# tls: СЃРІРѕР№ СЃРµСЂС‚ РЅР° РЅРѕРІС‹Р№ РґРѕРјРµРЅ, РµСЃР»Рё РІС‹РїСѓС‰РµРЅ
if (st.get("security") or "").lower() == "tls":
    fc, fk = f"/etc/letsencrypt/live/{new}/fullchain.pem", f"/etc/letsencrypt/live/{new}/privkey.pem"
    import os
    if os.path.isfile(fc) and os.path.isfile(fk):
        for c in (st.get("tlsSettings") or {}).get("certificates") or []:
            if c.get("certificateFile"): c["certificateFile"] = fc
            if c.get("keyFile"):        c["keyFile"] = fk
con.execute("UPDATE inbounds SET settings=?, stream_settings=? WHERE id=?",
            (json.dumps(se, ensure_ascii=False), json.dumps(st, ensure_ascii=False), iid))
con.commit()
print("[+] JSON РѕР±РЅРѕРІР»С‘РЅ")
PYSET
  if [[ "$pyok" != 0 ]]; then
    err "РџСЂР°РІРєР° Р‘Р” РЅРµ РїСЂРѕС€Р»Р° вЂ” РїР°РЅРµР»СЊ РќР• С‚СЂРѕРіР°СЋ РґР°Р»СЊС€Рµ"; [[ "$xui_was" == 1 ]] && systemctl start x-ui; return 1
  fi
  hosts_upsert "$id" "$nd"
  # SNI-РєР°СЂС‚Р°: РїРµСЂРµРЅРѕСЃРёРј Р±СЌРєРµРЅРґ СЃС‚Р°СЂРѕРіРѕ РґРѕРјРµРЅР° РЅР° РЅРѕРІС‹Р№
  local backend
  backend=$(grep -E "^\s+$old\s+" "$SNI_CONF" 2>/dev/null | awk '{print $2}' | head -1)
  if [[ -n "$backend" ]]; then
    sni_map_remove "$old"; sni_map_add "$nd" "$backend"
    log "  SNI-РєР°СЂС‚Р°: $old в†’ $nd (Р±СЌРєРµРЅРґ $backend СЃРѕС…СЂР°РЅС‘РЅ)"
  else
    sni_upstream_add "inb_${id}_backend" "$port"
    sni_map_add "$nd" "inb_${id}_backend"
    log "  SNI-РєР°СЂС‚Р°: $nd в†’ inb_${id}_backend (СЃС‚Р°СЂРѕР№ Р·Р°РїРёСЃРё РЅРµ Р±С‹Р»Рѕ)"
  fi
  [[ "$xui_was" == 1 ]] && { systemctl start x-ui >/dev/null 2>&1 || true; sleep 2; }
  nginx_reload || true
  audit "inbound: СЃРјРµРЅР° РґРѕРјРµРЅР° #$id: $old в†’ $nd"
  echo
  log "Р“РѕС‚РѕРІРѕ: #$id С‚РµРїРµСЂСЊ $nd. РџСЂРѕРІРµСЂСЊ С‚Р°Р±Р»РёС†Сѓ РЅРёР¶Рµ вЂ” РїРѕСЂС‚ СЃР»СѓС€Р°РµС‚СЃСЏ, РґРѕРјРµРЅ РЅРѕРІС‹Р№."
  inbounds_live
}

# =====================================================================
# РЎРђРњРћР”РРђР“РќРћРЎРўРРљРђ (read-only health check): СЃРµСЂРІРёСЃС‹, РїРѕСЂС‚С‹, SNI, СЃРµСЂС‚С‹,
# UFW, DNS. РќРР§Р•Р“Рћ РЅРµ РјРµРЅСЏРµС‚ вЂ” С‚РѕР»СЊРєРѕ РїРѕРєР°Р·С‹РІР°РµС‚ РїСЂРѕР±Р»РµРјС‹ Рё РїРѕРґСЃРєР°Р·РєРё.
# =====================================================================
stack_doctor() {
  line; echo -e "${B}   РЎРђРњРћР”РРђР“РќРћРЎРўРРљРђ РЎРўР•РљРђ${N}"; line
  local problems=0
  ok()   { echo -e "  ${G}[вњ“]${N} $*"; }
  bad()  { echo -e "  ${R}[x]${N} $*"; problems=$((problems+1)); }
  warn2(){ echo -e "  ${Y}[!]${N} $*"; }
  hint() { echo -e "      ${Y}в†’${N} $*"; }

  echo -e "${B}вЂ” РЎРµСЂРІРёСЃС‹ вЂ”${N}"
  local s
  for s in nginx x-ui; do
    if systemctl is-active --quiet "$s" 2>/dev/null; then ok "$s: Р°РєС‚РёРІРµРЅ"; else bad "$s: РќР• Р°РєС‚РёРІРµРЅ"; hint "systemctl restart $s"; fi
  done
  if [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]]; then
    if systemctl is-active --quiet "$ADG_SERVICE" 2>/dev/null; then ok "AdGuard ($ADG_SERVICE): Р°РєС‚РёРІРµРЅ"; else bad "AdGuard: РќР• Р°РєС‚РёРІРµРЅ"; hint "systemctl restart $ADG_SERVICE"; fi
  else
    warn2 "AdGuard РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ (РЅРµРѕР±СЏР·Р°С‚РµР»СЊРЅРѕ)"
  fi

  echo -e "${B}вЂ” РЎР»СѓС€Р°СЋС‰РёРµ РїРѕСЂС‚С‹ вЂ”${N}"
  if ss -tlnH "sport = :443" 2>/dev/null | grep -q .; then ok "443/tcp СЃР»СѓС€Р°РµС‚ nginx"; else bad "443/tcp РќР• СЃР»СѓС€Р°РµС‚СЃСЏ"; hint "Рї.1 РїРµСЂРµСЃР±РѕСЂРєР° СЃС‚РµРєР° / systemctl restart nginx"; fi
  if ss -tlnH "sport = :80" 2>/dev/null | grep -q .; then ok "80/tcp СЃР»СѓС€Р°РµС‚СЃСЏ (ACME webroot)"; else warn2 "80/tcp РЅРµ СЃР»СѓС€Р°РµС‚СЃСЏ вЂ” HTTP-01 РІС‹РїСѓСЃРєР° РЅРµ Р±СѓРґРµС‚ (wildcard DNS-01 РЅРµ СЃС‚СЂР°РґР°РµС‚)"; fi
  local wp sp wl sl
  wp=$(xui_get webPort); sp=$(xui_get subPort); wl=$(xui_get webListen); sl=$(xui_get subListen)
  if [[ "$wl" == "127.0.0.1" ]]; then ok "РїР°РЅРµР»СЊ СЃР»СѓС€Р°РµС‚ 127.0.0.1:$wp (РЅР°СЂСѓР¶Сѓ РЅРµ С‚РѕСЂС‡РёС‚)"; else bad "РїР°РЅРµР»СЊ СЃР»СѓС€Р°РµС‚ ${wl:-?}:$wp вЂ” РґРѕРєС‚СЂРёРЅР° 443 РЅР°СЂСѓС€РµРЅР°"; hint "Рї.1 (Р·Р°РїРёС€РµС‚ 127.0.0.1)"; fi
  if [[ "$sl" == "127.0.0.1" || -z "$sl" ]]; then ok "РїРѕРґРїРёСЃРєРё СЃР»СѓС€Р°СЋС‚ 127.0.0.1:$sp"; else bad "РїРѕРґРїРёСЃРєРё СЃР»СѓС€Р°СЋС‚ ${sl:-?}:$sp вЂ” РЅР°СЂСѓР¶Сѓ С‚РѕСЂС‡Р°С‚"; fi
  # РёРЅР±Р°СѓРЅРґС‹: TCP РґРѕР»Р¶РµРЅ СЃР»СѓС€Р°С‚СЊ 127.0.0.1 (tproxy вЂ” 0.0.0.0)
  local iid iproto ilisten iport isec idest
  while IFS='|' read -r iid iproto iport ilisten isec idest; do
    [[ -z "$iid" ]] && continue
    if [[ "$iproto" == "tproxy" ]]; then
      [[ "$ilisten" == "0.0.0.0" || "$ilisten" == "::" ]] && ok "#$iid tproxy РЅР° 0.0.0.0:$iport" || warn2 "#$iid tproxy СЃР»СѓС€Р°РµС‚ $ilisten вЂ” РјР°СЂС€СЂСѓС‚Сѓ tg РЅСѓР¶РµРЅ 0.0.0.0"
      continue
    fi
    if is_udp_proto "$iproto"; then continue; fi   # UDP РЅР°СЂСѓР¶Сѓ РЅР°РїСЂСЏРјСѓСЋ вЂ” РЅРµ РїСЂРѕРІРµСЂСЏРµРј
    if [[ "$ilisten" != "127.0.0.1" && "$ilisten" != "" ]]; then
      bad "#$iid ($iproto:$iport) СЃР»СѓС€Р°РµС‚ $ilisten вЂ” РґРѕР»Р¶РµРЅ 127.0.0.1 (Р·Р° 443)"
      hint "Рї.4 в†’ РџРѕС‡РёРЅРёС‚СЊ РёРЅР±Р°СѓРЅРґ #$iid"
    fi
  done < <(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "SELECT id, protocol, port, COALESCE(listen,''), COALESCE(json_extract(stream_settings,'\$.security'),''), COALESCE(json_extract(stream_settings,'\$.realitySettings.dest'),'') FROM inbounds WHERE enable=1;" 2>/dev/null || true)

  echo -e "${B}вЂ” SNI-РјР°СЂС€СЂСѓС‚ вЂ”${N}"
  if [[ -f "$SNI_CONF" ]]; then
    ok "$SNI_CONF РЅР° РјРµСЃС‚Рµ ($(grep -c 'upstream ' "$SNI_CONF" 2>/dev/null || echo 0) upstream-РѕРІ)"
    grep -qE "panel_backend;" "$SNI_CONF" 2>/dev/null && ok "РґРѕРјРµРЅ РїР°РЅРµР»Рё Р·Р°РјР°РїР»РµРЅ (panel_backend)" || bad "panel_backend РЅРµ РЅР°Р№РґРµРЅ РІ $SNI_CONF"
  else
    bad "$SNI_CONF РЅРµ РЅР°Р№РґРµРЅ"; hint "Рї.1 вЂ” РїРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР°"
  fi
  if nginx -t >/dev/null 2>&1; then ok "nginx -t: РєРѕРЅС„РёРі РІР°Р»РёРґРµРЅ"; else bad "nginx -t РїСЂРѕРІР°Р»РµРЅ:"; nginx -t 2>&1 | tail -3 | sed 's/^/      /'; fi
  local wconn wno
  wconn=$(sed -nE 's/.*worker_connections[[:space:]]+([0-9]+).*/\1/p' /etc/nginx/nginx.conf 2>/dev/null | head -1)
  wno=$(sed -nE 's/^[[:space:]]*worker_rlimit_nofile[[:space:]]+([0-9]+).*/\1/p' /etc/nginx/nginx.conf 2>/dev/null | head -1)
  if [[ "${wconn:-0}" -ge 2048 ]]; then ok "nginx worker_connections=$wconn${wno:+, open files=$wno}"
  else warn2 "nginx worker_connections=${wconn:-РЅРµС‚} вЂ” РјР°Р»Рѕ (РґРµС„РѕР»С‚ 768 Р·Р°Р±РёРІР°РµС‚СЃСЏ РЅР° 443)"; hint "Рї.1 РёР»Рё СЃР°РјРѕРїРѕС‡РёРЅРєР° вЂ” РїРѕРґРЅРёРјРµС‚ РґРѕ 4096"; fi
  if grep -q 'worker_connections are not enough' /var/log/nginx/error.log 2>/dev/null; then
    warn2 "РІ error.log РµСЃС‚СЊ В«worker_connections are not enoughВ» вЂ” 443 СѓРїРёСЂР°РµС‚СЃСЏ РІ Р»РёРјРёС‚ СЃРѕРµРґРёРЅРµРЅРёР№"
  fi

  echo -e "${B}вЂ” РЎРµСЂС‚РёС„РёРєР°С‚С‹ (РёСЃС‚РµРєР°СЋС‚ < 14 РґРЅ вЂ” [!]) вЂ”${N}"
  local ldir crt end_left
  ldir="/etc/letsencrypt/live"
  if [[ -d "$ldir" ]] && ls -1 "$ldir" 2>/dev/null | grep -q .; then
    local d
    for d in "$ldir"/*/; do
      d=$(basename "$d"); crt="$ldir/$d/fullchain.pem"
      [[ -f "$crt" ]] || { warn2 "$d: fullchain.pem РЅРµС‚"; continue; }
      end_left=$(( ($(date -d "$(openssl x509 -enddate -noout -in "$crt" 2>/dev/null | cut -d= -f2)" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 ))
      if [[ "$end_left" -ge 14 ]]; then ok "$d: ~${end_left} РґРЅ"; elif [[ "$end_left" -ge 0 ]]; then warn2 "$d: РёСЃС‚РµРєР°РµС‚ С‡РµСЂРµР· ~${end_left} РґРЅ"; hint "Рї.10 в†’ РѕР±РЅРѕРІРёС‚СЊ"; else bad "$d: РџР РћРЎР РћР§Р•Рќ"; hint "Рї.10 в†’ РѕР±РЅРѕРІРёС‚СЊ"; fi
    done
  else
    warn2 "СЃРµСЂС‚РѕРІ РІ /etc/letsencrypt/live РЅРµС‚"
  fi

  echo -e "${B}вЂ” UFW вЂ”${N}"
  if ufw_is_active; then
    ok "UFW Р°РєС‚РёРІРµРЅ"
    ufw status 2>/dev/null | grep -qE "443/tcp\s+ALLOW" && ok "443/tcp СЂР°Р·СЂРµС€С‘РЅ" || bad "443/tcp РќР• СЂР°Р·СЂРµС€С‘РЅ"; hint "Рї.11"
    ufw status 2>/dev/null | grep -qE "${SSH_PORT:-22}/tcp\s+ALLOW" && ok "SSH (${SSH_PORT:-22}/tcp) СЂР°Р·СЂРµС€С‘РЅ" || warn2 "SSH-РїРѕСЂС‚ РЅРµ РїРѕРјРµС‡РµРЅ ALLOW вЂ” РїСЂРѕРІРµСЂСЊ, РєР°Рє РїРѕРґРєР»СЋС‡Р°РµС€СЊСЃСЏ"
    local extra
    extra=$(ufw status 2>/dev/null | grep -E "ALLOW" | grep -E "/tcp" | grep -vE "443/tcp|${SSH_PORT:-22}/tcp" | head -5)
    [[ -n "$extra" ]] && { warn2 "Р»РёС€РЅРёРµ TCP-СЂР°Р·СЂРµС€РµРЅРёСЏ:"; echo "$extra" | sed 's/^/        /'; hint "Рї.11 в†’ СЃР±СЂРѕСЃ (С‚РѕР»СЊРєРѕ SSH+443+UDP)"; }
  else
    bad "UFW РЅРµ Р°РєС‚РёРІРµРЅ (РёР»Рё Р±РёРЅР°СЂСЊ РЅРµ РЅР°Р№РґРµРЅ вЂ” РїСЂРѕРІРµСЂСЊ: systemctl is-active ufw)"; hint "Рї.11"
  fi

  echo -e "${B}вЂ” fail2ban вЂ”${N}"
  if systemctl is-active --quiet fail2ban 2>/dev/null; then
    ok "fail2ban Р°РєС‚РёРІРµРЅ"
    fail2ban-client status decoy-login >/dev/null 2>&1 && ok "jail decoy-login СЂР°Р±РѕС‚Р°РµС‚" || bad "jail decoy-login РќР• СЂР°Р±РѕС‚Р°РµС‚"; hint "Рї.1/Рї.7"
    fail2ban-client status recidive >/dev/null 2>&1 && ok "jail recidive СЂР°Р±РѕС‚Р°РµС‚ (СЂРµС†РёРґРёРІРёСЃС‚С‹ вЂ” Р±Р°РЅ РЅР° РЅРµРґРµР»СЋ)" || warn2 "recidive РІС‹РєР»СЋС‡РµРЅ (Рї.7 в†’ РІРєР».)"
  else
    bad "fail2ban РќР• Р°РєС‚РёРІРµРЅ"; hint "systemctl restart fail2ban"
  fi

  echo -e "${B}вЂ” Decoy-СЃС‚СЂР°РЅРёС†С‹ (С‡С‚Рѕ СЂРµР°Р»СЊРЅРѕ РѕС‚РІРµС‡Р°РµС‚ nginx) вЂ”${N}"
  if [[ -f "$STACK_CONF" ]] && grep -q "^# >>> decoy " "$STACK_CONF" 2>/dev/null; then
    local mline mport mdom mroot code body_md5 idx_md5 n_ok=0 n_bad=0
    while IFS= read -r mline; do
      mport=$(grep -oE 'port=[0-9]+'  <<<"$mline" | head -1 | cut -d= -f2)
      mdom=$(grep  -oE 'domain=[^ ]+$' <<<"$mline" | head -1 | cut -d= -f2-)
      mroot=$(grep -oE 'root=[^ ]+'   <<<"$mline" | head -1 | cut -d= -f2-)
      [[ -z "$mdom" || -z "$mport" ]] && continue
      # UA вЂ” Р±СЂР°СѓР·РµСЂРЅС‹Р№: decoy СЃ ua404=1 РѕС‚РґР°С‘С‚ curl'Сѓ 404, РґРѕРєС‚РѕСЂ РґРѕР»Р¶РµРЅ РІРёРґРµС‚СЊ
      # СЃС‚СЂР°РЅРёС†Сѓ РіР»Р°Р·Р°РјРё В«С‡РµР»РѕРІРµРєР°В»
      code=$(curl -sk --max-time 5 -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124 Safari/537.36" -o /tmp/.decoy_body -w '%{http_code}' -H "Host: $mdom" "https://127.0.0.1:$mport/" 2>/dev/null || echo 000)
      if [[ "$code" == "200" || "$code" == "302" || "$code" == "401" ]]; then
        if [[ "$code" == "200" && -f "$mroot/index.html" ]]; then
          body_md5=$(md5sum /tmp/.decoy_body 2>/dev/null | awk '{print $1}')
          idx_md5=$(md5sum "$mroot/index.html" 2>/dev/null | awk '{print $1}')
          if [[ "$body_md5" == "$idx_md5" ]]; then ok "$mdom (:$mport): 200, РєРѕРЅС‚РµРЅС‚ = С€Р°Р±Р»РѕРЅ"; n_ok=$((n_ok+1))
          else bad "$mdom (:$mport): 200, РЅРѕ РєРѕРЅС‚РµРЅС‚ РќР• СЃРѕРІРїР°РґР°РµС‚ СЃ $mroot/index.html"; n_bad=$((n_bad+1)); fi
        else
          ok "$mdom (:$mport): HTTP $code (РѕР¶РёРґР°РµРјРѕ РґР»СЏ redirect/locked)"; n_ok=$((n_ok+1))
        fi
      else
        bad "$mdom (:$mport): РѕС‚РІРµС‚ $code вЂ” decoy РќР• РѕС‚РІРµС‡Р°РµС‚"; hint "Рї.4/РїРµСЂРµСЃР±РѕСЂРєР° decoy, systemctl restart nginx"; n_bad=$((n_bad+1))
      fi
    done < <(grep "^# >>> decoy " "$STACK_CONF")
    rm -f /tmp/.decoy_body 2>/dev/null || true
    [[ "$n_bad" -gt 0 ]] && problems=$((problems+n_bad))
    [[ "$n_ok" -eq 0 && "$n_bad" -eq 0 ]] && warn2 "decoy-Р±Р»РѕРєРё РЅРµ СЂР°СЃРїР°СЂСЃРёР»РёСЃСЊ"
  else
    warn2 "decoy-Р±Р»РѕРєРѕРІ РІ stack.conf РЅРµС‚"
  fi

  echo -e "${B}вЂ” РџРѕСЂС‚С‹ РёРЅР±Р°СѓРЅРґРѕРІ (Р±С‹СЃС‚СЂРѕ; РїРѕРґСЂРѕР±РЅРѕ вЂ” Рї.19) вЂ”${N}"
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local dead
    dead=$(python3 - "$XUI_DB" <<'PYPORTS' 2>/dev/null
import sqlite3, json, sys, subprocess, re
UDP_PROTOS={"hysteria","hysteria2","qwdtt","csqtt","tuic","wireguard","amnezia","amneziawg","awg"}
try:
    con=sqlite3.connect(f"file:{sys.argv[1]}?mode=ro",uri=True,timeout=5)
    rows=con.execute("SELECT id,protocol,port,COALESCE(listen,''),settings,stream_settings FROM inbounds WHERE enable=1").fetchall()
except Exception: sys.exit(0)
def listening(net,p):
    if net=="tcp":
        out=subprocess.run(["ss","-tln"],capture_output=True,text=True,timeout=5).stdout
        return bool(re.search(rf":{p}(\s|$)",out))
    out=subprocess.run(["ss","-ulan"],capture_output=True,text=True,timeout=5).stdout
    if re.search(rf":{p}(\s|$)",out): return True
    return False
for iid,proto,port,listen,s1,s2 in rows:
    try: se=json.loads(s1 or "{}")
    except Exception: se={}
    try: st=json.loads(s2 or "{}")
    except Exception: st={}
    try: p=int(se.get("port") or port or 0)
    except Exception: p=int(port or 0)
    if p<=0: continue
    net="udp" if proto.lower() in UDP_PROTOS else (st.get("network") or "tcp")
    # xhttp/ws/grpc/httpupgrade вЂ” TCP-С‚СЂР°РЅСЃРїРѕСЂС‚С‹: РЅР°СЂСѓР¶Сѓ РїСЂРѕРІРµСЂСЏРµРј РєР°Рє tcp,
    # РёРЅР°С‡Рµ В«РЅРµ СЃР»СѓС€Р°РµС‚СЃСЏВ» РЅР° Р¶РёРІРѕРј РёРЅР±Р°СѓРЅРґРµ (РїР°РЅРµР»СЊ РїСЂРё СЌС‚РѕРј РїСЂР°РІР°)
    if net!="udp": net="tcp"
    if not listening(net,p): print(f"#{iid} {proto} {p}/{net}")
PYPORTS
)
    if [[ -z "$dead" ]]; then
      ok "РІСЃРµ РІРєР»СЋС‡С‘РЅРЅС‹Рµ РёРЅР±Р°СѓРЅРґС‹ СЃР»СѓС€Р°СЋС‚ СЃРІРѕРё РїРѕСЂС‚С‹"
    else
      local dl
      while IFS= read -r dl; do [[ -z "$dl" ]] && continue; bad "РЅРµ СЃР»СѓС€Р°РµС‚СЃСЏ: $dl"; done <<<"$dead"
      hint "systemctl restart x-ui; РµСЃР»Рё РЅРµ РїРѕРјРѕРіР»Рѕ вЂ” Рї.19/Р»РѕРіРё xray"
    fi
  fi

  echo -e "${B}вЂ” Р РµСЃСѓСЂСЃС‹ вЂ”${N}"
  local duse
  duse=$(df -Pm / 2>/dev/null | awk 'NR==2{print $5}' | tr -d '%')
  if [[ -n "$duse" ]]; then
    if (( duse >= 90 )); then bad "РґРёСЃРє: Р·Р°РЅСЏС‚Рѕ ${duse}% вЂ” РєСЂРёС‚РёС‡РЅРѕ"; hint "РїРѕС‡РёСЃС‚РёС‚СЊ /root/stack-backups, /var/log"
    elif (( duse >= 80 )); then warn2 "РґРёСЃРє: Р·Р°РЅСЏС‚Рѕ ${duse}%"; else ok "РґРёСЃРє: Р·Р°РЅСЏС‚Рѕ ${duse}%"; fi
  fi
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local dbsize nbak nauto nman fresh
    dbsize=$(du -h "$XUI_DB" 2>/dev/null | awk '{print $1}')
    nauto=$(ls -1dt "$BACKUP_DIR"/auto-* 2>/dev/null | wc -l)              # Р°РІС‚РѕР±СЌРєР°Рї (СЃС‚Р°СЂС‚ СЃРєСЂРёРїС‚Р°)
    nman=$(ls -1 "$BACKUP_DIR"/stack-backup-*.tar.gz 2>/dev/null | wc -l)
    local nself npre
    nself=$(ls -1d "$BACKUP_DIR"/self-update-* 2>/dev/null | wc -l)
    npre=$(ls -1d "$BACKUP_DIR"/pre-install-* 2>/dev/null | grep -v '\.tar\.gz$' | wc -l)
    nbak=$((nauto + nman + nself + npre))
    fresh=$(ls -1dt "$BACKUP_DIR"/auto-* "$BACKUP_DIR"/stack-backup-*.tar.gz "$BACKUP_DIR"/self-update-* "$BACKUP_DIR"/pre-install-* 2>/dev/null | head -1 | xargs -r basename)
    ok "x-ui.db: ${dbsize:-?} В· Р±СЌРєР°РїРѕРІ: $nbak (Р°РІС‚Рѕ:$nauto/СЂСѓС‡РЅС‹Рµ:$nman/self-update:$nself/pre-install:$npre; СЃРІРµР¶РёР№: $fresh)"
    (( nbak == 0 )) && warn2 "СЂРµР·РµСЂРІРЅС‹С… РєРѕРїРёР№ РЅРµС‚ вЂ” СЂР°Р·РґРµР» 5 в†’ Р‘СЌРєР°РїС‹ Рё РѕС‚РєР°С‚"
  fi
  if [[ -f /var/run/reboot-required ]]; then
    bad "СЃРёСЃС‚РµРјР° Р¶РґС‘С‚ РџР•Р Р•Р—РђР“Р РЈР—РљРЈ (РѕР±РЅРѕРІР»РµРЅРѕ СЏРґСЂРѕ/Р±РёР±Р»РёРѕС‚РµРєРё)"
    hint "reboot РІ СѓРґРѕР±РЅРѕРµ РѕРєРЅРѕ: СЃС‚РµРє РїРѕРґРЅРёРјРµС‚СЃСЏ СЃР°Рј (nginx/x-ui/AdGuard/fail2ban вЂ” systemd)"
  fi

  echo -e "${B}вЂ” DNS / РґРѕРјРµРЅС‹ СЃС‚РµРєР° вЂ”${N}"
  local srv_ip
  srv_ip=$(server_ip4)
  local doms pd
  pd="${PANEL_DOMAIN:-$(xui_get webDomain 2>/dev/null || true)}"
  doms=$(python3 - "$XUI_DB" "${REALITY_TARGETS[@]}" <<'PYDOMS' 2>/dev/null
import sqlite3, json, sys
skip=set(a.lower() for a in sys.argv[2:])
seen=set(); out=[]
def add(d):
    d=(d or "").strip().lower()
    if d and d not in skip and d not in seen:
        seen.add(d); out.append(d)
try:
    con=sqlite3.connect(f"file:{sys.argv[1]}?mode=ro",uri=True,timeout=5)
    for setts_s,stream_s in con.execute("SELECT settings,stream_settings FROM inbounds WHERE enable=1 AND port>0"):
        try: se=json.loads(setts_s or "{}")
        except Exception: se={}
        try: st=json.loads(stream_s or "{}")
        except Exception: st={}
        rs=st.get("realitySettings") or {}
        add(se.get("domain")); add(se.get("hostname")); add(se.get("sni"))
        add((st.get("tlsSettings") or {}).get("serverName"))
        add((rs.get("serverNames") or [None])[0])   # С‡СѓР¶РёРµ С†РµР»Рё РѕС‚СЃРµРµС‚ skip-СЃРїРёСЃРѕРє
except Exception:
    pass
print("\n".join(out))
PYDOMS
)
  [[ -n "$pd" ]] && doms="$pd"$'\n'"$doms"
  local d a_ip
  while IFS= read -r d; do
    [[ -z "$d" ]] && continue
    a_ip=$(dig +short A "$d" @1.1.1.1 2>/dev/null | tail -1)
    [[ -z "$a_ip" ]] && a_ip=$(dig +short A "$d" @8.8.8.8 2>/dev/null | tail -1)
    local aaaa_ip
    aaaa_ip=$(dig +short AAAA "$d" @1.1.1.1 2>/dev/null | tail -1)
    if [[ -n "$a_ip" && "$a_ip" == "$srv_ip" ]]; then
      [[ -n "$aaaa_ip" ]] && ok "$d в†’ A $a_ip вњ“; AAAA $aaaa_ip (dual-stack)" || ok "$d в†’ A $a_ip вњ“"
    elif [[ -z "$a_ip" ]]; then warn2 "$d: A-Р·Р°РїРёСЃСЊ РЅРµ СЂРµР·РѕР»РІРёС‚СЃСЏ"
    else warn2 "$d в†’ $a_ip, Р° СЃРµСЂРІРµСЂ: $srv_ip"; fi
  done <<<"$doms"

  echo
  line
  if [[ "$problems" -eq 0 ]]; then
    echo -e "${G}  РС‚РѕРі: РїСЂРѕР±Р»РµРј РЅРµ РЅР°Р№РґРµРЅРѕ вњ“${N}"
  else
    echo -e "${R}  РС‚РѕРі: РїСЂРѕР±Р»РµРј вЂ” $problems${N} (РїРѕРґСЃРєР°Р·РєРё [в†’] РІС‹С€Рµ)"
  fi
  line
  (( problems > 0 )) && return 1
  return 0
}

# Р•РґРёРЅС‹Р№ read-only Р°СѓРґРёС‚ РґР»СЏ CI/СЂСѓС‡РЅРѕР№ РїСЂРѕРІРµСЂРєРё. РќРµ РјРµРЅСЏРµС‚ Р‘Р”, nginx Рё СЃРµСЂРІРёСЃС‹.

# РќР°Р±Р»СЋРґРµРЅРёРµ Р·Р° СЃС‚РµРєРѕРј: РѕРґРёРЅРѕС‡РЅС‹Р№ РїСЂРѕРіРѕРЅ РёР»Рё РѕР±РЅРѕРІР»РµРЅРёРµ РєР°Р¶РґС‹Рµ 10 СЃРµРє
stack_doctor_menu() {
  stack_doctor
  local wm=""
  askyn wm "РќР°Р±Р»СЋРґР°С‚СЊ РЅРµРїСЂРµСЂС‹РІРЅРѕ (РѕР±РЅРѕРІР»РµРЅРёРµ РєР°Р¶РґС‹Рµ 10 СЃРµРє, Р»СЋР±Р°СЏ РєР»Р°РІРёС€Р° вЂ” РІС‹С…РѕРґ)?" "n"
  [[ "$wm" == true ]] || return 0
  while :; do
    local k=""
    read -t 10 -n 1 k 2>/dev/null && [[ -n "$k" ]] && break
    clear
    stack_doctor
  done
}

fmt_bytes() {   # <bytes> в†’ С‡РµР»РѕРІРµРєРѕС‡РёС‚Р°РµРјРѕ
  local b="${1:-0}"
  [[ -z "$b" || "$b" == "NULL" ]] && b=0
  if   (( b >= 1099511627776 )); then echo "$(( b / 1099511627776 )) РўР‘"
  elif (( b >= 1073741824 ));    then echo "$(( b / 1073741824 )) Р“Р‘"
  elif (( b >= 1048576 ));       then echo "$(( b / 1048576 )) РњР‘"
  elif (( b >= 1024 ));          then echo "$(( b / 1024 )) РљР‘"
  else echo "${b} Р‘"; fi
}

# Р•РґРёРЅС‹Р№ СЌРєСЂР°РЅ РґРёР°РіРЅРѕСЃС‚РёРєРё Рё СѓРїСЂР°РІР»РµРЅРёСЏ РёРЅР±Р°СѓРЅРґР°РјРё.
inbounds_manage_menu() {
  while :; do
    line; echo -e "${B}   РРќР‘РђРЈРќР”Р«: РџР РћР’Р•Р РљРђ Р РЈРџР РђР’Р›Р•РќРР•${N}"; line
    echo "  1) РџСЂРѕРІРµСЂРёС‚СЊ РІСЃРµ РёРЅР±Р°СѓРЅРґС‹ (live-С‚Р°Р±Р»РёС†Р°)"
    echo "  2) Р”РѕР±Р°РІРёС‚СЊ / РїСЂРѕРІРµСЂРёС‚СЊ inbound"
    echo "  3) РЈРґР°Р»РёС‚СЊ inbound РёР»Рё С‚РѕР»СЊРєРѕ РµРіРѕ SNI-РїСЂРёРІСЏР·РєСѓ"
    echo "  4) РЎРјРµРЅРёС‚СЊ РґРѕРјРµРЅ inbound"
    echo "  0) РќР°Р·Р°Рґ"
    local c=""
    ask c "Р’С‹Р±РѕСЂ" "1" '^[0-4]$'
    case "$c" in
      1) inbounds_live; pause ;;
      2) add_inbound; pause ;;
      3) remove_inbound; pause ;;
      4) inbound_change_domain ;;
      0) return 0 ;;
    esac
  done
}

# Рї.19: live-С‚Р°Р±Р»РёС†Р° РїРѕ РІСЃРµРј РёРЅР±Р°СѓРЅРґР°Рј вЂ” РїРѕСЂС‚ СЃР»СѓС€Р°РµС‚?, СЃРµСЂС‚ (РґРЅРµР№), РєР»РёРµРЅС‚С‹, С‚СЂР°С„РёРє
inbounds_live() {
  line; echo -e "${B}   РРќР‘РђРЈРќР”Р« вЂ” LIVE${N}"; line
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; return 1; }

  printf "  %-5s %-11s %-7s %-5s %-8s %-5s %-9s %s\n" "ID" "РџСЂРѕС‚Рѕ" "РџРѕСЂС‚" "РЎР»СѓС…" "РЎРµСЂС‚" "РљР»." "РўСЂР°С„РёРє" "Р”РѕРјРµРЅ"
  echo "  в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ"

  local out
  out=$(python3 - "$XUI_DB" <<'PYLIVE' 2>/dev/null
import sqlite3, json, sys
try:
    con=sqlite3.connect(f"file:{sys.argv[1]}?mode=ro",uri=True,timeout=5)
    # LIVE РїРѕРєР°Р·С‹РІР°РµС‚ С‚РѕР»СЊРєРѕ РІРєР»СЋС‡С‘РЅРЅС‹Рµ РёРЅР±Р°СѓРЅРґС‹. РћС‚РєР»СЋС‡С‘РЅРЅС‹Рµ Р·Р°РїРёСЃРё РѕСЃС‚Р°СЋС‚СЃСЏ
    # РІ Р‘Р” РґР»СЏ РёСЃС‚РѕСЂРёРё, РЅРѕ РЅРµ СЏРІР»СЏСЋС‚СЃСЏ СЂР°Р±РѕС‚Р°СЋС‰РёРјРё СЃРµСЂРІРёСЃР°РјРё Рё РЅРµ РґРѕР»Р¶РЅС‹
    # РїРѕРїР°РґР°С‚СЊ РІ С‚Р°Р±Р»РёС†Сѓ РєР°Рє Р±СѓРґС‚Рѕ РёС… РїРѕСЂС‚ РѕР±СЏР·Р°РЅ СЃР»СѓС€Р°С‚СЊСЃСЏ.
    rows=con.execute("SELECT id,protocol,port,COALESCE(listen,''),settings,stream_settings FROM inbounds WHERE enable=1 ORDER BY id").fetchall()
except Exception:
    sys.exit(0)
for iid,proto,port,listen,setts_s,stream_s in rows:
    try: se=json.loads(setts_s or "{}")
    except Exception: se={}
    try: st=json.loads(stream_s or "{}")
    except Exception: st={}
    rs=st.get("realitySettings") or {}
    dom=(se.get("domain") or se.get("hostname") or se.get("sni")
         or (st.get("tlsSettings") or {}).get("serverName")
         or (rs.get("serverNames") or [None])[0] or "")
    try: p=int(se.get("port") or port or 0)
    except Exception: p=int(port or 0)
    # UDP-РїСЂРѕС‚РѕРєРѕР»С‹ РєР»Р°СЃСЃРёС„РёС†РёСЂСѓРµРј РџРћ РРњР•РќР вЂ” РїРѕР»Рµ network РІ stream_settings
    # Р±С‹РІР°РµС‚ РёСЃРїРѕСЂС‡РµРЅРѕ/РЅР°СЃР»РµРґРѕРІР°РЅРѕ (hysteria СЃ network=tcp Р¶РёРІС‘С‚ Сѓ LucX)
    UDP_PROTOS={"hysteria","hysteria2","qwdtt","csqtt","tuic","wireguard","amnezia","amneziawg","awg"}
    net="udp" if proto.lower() in UDP_PROTOS else (st.get("network") or "tcp")
    cert=(se.get("certFile") or "")
    if not cert:
        certs=(st.get("tlsSettings") or {}).get("certificates") or []
        if certs: cert=certs[0].get("certificateFile","")
    if (st.get("security") or "").lower()=="reality": cert="REALITY"
    if (st.get("network") or "").lower()=="xhttp" and (st.get("security") or "none").lower() in ("none",""):
        # CDN-СЂРµР¶РёРј: TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx вЂ” СЃРµСЂС‚ РІ РёРЅР±Р°СѓРЅРґРµ РЅРµ РЅСѓР¶РµРЅ
        try:
            prof=[l.split("|") for l in open("/root/stack-backups/cdn-profiles.tsv") if l.strip()]
            if any(r[0]==str(iid) for r in prof): cert="CDN"
        except Exception: pass
    try: ncl=len(se.get("clients") or [])
    except Exception: ncl=0
    # С‚СЂР°С„РёРє: РїР°РЅРµР»СЊ РјРѕР¶РµС‚ РїРёСЃР°С‚СЊ РµРіРѕ Рё РІ client_traffics (РїРѕ РєР»РёРµРЅС‚Р°Рј),
    # Рё РІ inbounds.up/down (РїРѕ РёРЅР±Р°СѓРЅРґСѓ) вЂ” Р±РµСЂС‘Рј РјР°РєСЃРёРјСѓРј РёР· РѕР±РѕРёС… РёСЃС‚РѕС‡РЅРёРєРѕРІ
    t1=t2=0
    try:
        r=con.execute("SELECT COALESCE(SUM(up),0)+COALESCE(SUM(down),0) FROM client_traffics WHERE inbound_id=?", (iid,)).fetchone()
        t1=r[0] if r else 0
    except Exception: pass
    try:
        r=con.execute("SELECT COALESCE(up,0)+COALESCE(down,0) FROM inbounds WHERE id=?", (iid,)).fetchone()
        t2=r[0] if r else 0
    except Exception: pass
    tot=max(int(t1 or 0), int(t2 or 0))
    print(f"{iid}\x1f{proto}\x1f{p}\x1f{net}\x1f{cert}\x1f{ncl}\x1f{dom}\x1f{tot}")
PYLIVE
)
  local iid proto p net cert ncl dom tot st_us days traf e
  while IFS=$'\x1f' read -r iid proto p net cert ncl dom tot; do
    [[ -z "$iid" ]] && continue
    if [[ "$net" == "udp" ]]; then
      if ss -ulan 2>/dev/null | grep -qE ":${p}([[:space:]]|\$)"; then
        st_us="вњ“"
      elif command -v nft >/dev/null 2>&1 && nft list ruleset 2>/dev/null | grep -qw "$p"; then
        st_us="вњ“*"   # РїРѕСЂС‚ РѕС‚РєСЂС‹С‚ NAT-РїСЂР°РІРёР»РѕРј (port hopping) вЂ” СЃРѕРєРµС‚ СЃР»СѓС€Р°РµС‚ РґСЂСѓРіРѕР№ РїРѕСЂС‚
      elif iptables -t nat -S 2>/dev/null | grep -qE "dport[ =]$p([ :]|$)|:$p([ :]|$)"; then
        st_us="вњ“*"   # С‚Рѕ Р¶Рµ, РЅРѕ legacy-iptables
      elif grep -qiE ":$(printf '%04X' "$p" 2>/dev/null)([[:space:]]|\$)" /proc/net/udp /proc/net/udp6 2>/dev/null; then
        st_us="вњ“"    # РїСЂСЏРјРѕРµ С‡С‚РµРЅРёРµ /proc вЂ” СЂР°Р±РѕС‚Р°РµС‚ РґР°Р¶Рµ Р±РµР· ss
      else
        st_us="вњ—"
      fi
    else
      ss -tln 2>/dev/null | grep -qE ":${p}([[:space:]]|\$)" && st_us="вњ“" || st_us="вњ—"
    fi
    days="вЂ”"
    if [[ "$cert" == "REALITY" ]]; then
      days="RLTY"
    elif [[ "$cert" == "CDN" ]]; then
      days="CDN"
    elif [[ -n "$cert" && -f "$cert" ]]; then
      e=$(openssl x509 -enddate -noout -in "$cert" 2>/dev/null | cut -d= -f2)
      days="$(( ($(date -d "$e" +%s 2>/dev/null || echo 0) - $(date +%s)) / 86400 )) РґРЅ"
      [[ "$days" == "-1 РґРЅ" || "$days" == "0 РґРЅ" ]] && days="РџР РћРЎР РћР§Р•Рќ"
    fi
    traf=$(fmt_bytes "${tot:-0}")
    printf "  %-5s %-11s %-7s %-5s %-8s %-5s %-9s %s\n" "#$iid" "$proto" "$p" "$st_us" "$days" "$ncl" "$traf" "$dom"
  done <<<"$out"
  echo
  warn "вњ— вЂ” РїРѕСЂС‚ РќР• СЃР»СѓС€Р°РµС‚СЃСЏ (РёРЅР±Р°СѓРЅРґ РЅРµ СЂР°Р±РѕС‚Р°РµС‚) В· вњ“* вЂ” UDP РѕС‚РєСЂС‹С‚ С‡РµСЂРµР· NAT (port hopping) В· RLTY вЂ” reality: СЃРµСЂС‚ Сѓ decoy РІ nginx В· CDN вЂ” tls Сѓ nginx (CDN-СЂРµР¶РёРј) В· РљР». вЂ” С‡РёСЃР»Рѕ РєР»РёРµРЅС‚РѕРІ"
  line
  return 0
}

# РћР±РЅРѕРІР»РµРЅРёРµ РїР°РЅРµР»Рё РґРѕ LucX UI СЃ СЃРѕС…СЂР°РЅРµРЅРёРµРј РґР°РЅРЅС‹С… (РёРЅР±Р°СѓРЅРґС‹/РєР»РёРµРЅС‚С‹/РЅР°СЃС‚СЂРѕР№РєРё
# Р¶РёРІСѓС‚ РІ x-ui.db вЂ” СѓСЃС‚Р°РЅРѕРІС‰РёРє LucX РµС‘ РїРѕРґС…РІР°С‚С‹РІР°РµС‚). Р‘СЌРєР°Рї Р‘Р” РґРµР»Р°РµРј РґРѕ Р·Р°РїСѓСЃРєР°.
panel_upgrade_lucx() {
  [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]] && { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” РѕР±РЅРѕРІР»СЏС‚СЊ РЅРµС‡РµРіРѕ"; return 1; }
  local bak="${XUI_DB}.bak-$(date +%F-%H%M%S)"
  if ! sqlite3 "$XUI_DB" ".backup '$bak'" 2>/dev/null && ! cp -a "$XUI_DB" "$bak"; then
    err "РќРµ СѓРґР°Р»РѕСЃСЊ Р·Р°Р±СЌРєР°РїРёС‚СЊ $XUI_DB вЂ” РѕС‚РјРµРЅР°"
    return 1
  fi
  chmod 600 "$bak" 2>/dev/null || true
  log "Р‘СЌРєР°Рї Р‘Р”: $bak"
  local tmp_sh
  tmp_sh=$(mktemp /tmp/lucx-upgrade.XXXXXX.sh) || { err "mktemp failed"; return 1; }
  log "РЎРєР°С‡РёРІР°РЅРёРµ СѓСЃС‚Р°РЅРѕРІС‰РёРєР° LucX UI..."
  if ! curl -fSL --retry 3 "$LUCX_INSTALL_URL" -o "$tmp_sh" || [[ ! -s "$tmp_sh" ]]; then
    err "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРєР°С‡Р°С‚СЊ СѓСЃС‚Р°РЅРѕРІС‰РёРє ($LUCX_INSTALL_URL)"
    rm -f "$tmp_sh"
    return 1
  fi
  warn "РЈСЃС‚Р°РЅРѕРІС‰РёРє Р·Р°РґР°СЃС‚ РІРѕРїСЂРѕСЃС‹ РїРѕ РїР°РЅРµР»Рё вЂ” СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёРµ Р·РЅР°С‡РµРЅРёСЏ РѕСЃС‚Р°РІР»СЏР№ РєР°Рє РµСЃС‚СЊ (Enter), Р‘Р” СЃРѕС…СЂР°РЅРёС‚СЃСЏ."
  if ! bash "$tmp_sh"; then
    err "РЈСЃС‚Р°РЅРѕРІС‰РёРє Р·Р°РІРµСЂС€РёР»СЃСЏ СЃ РѕС€РёР±РєРѕР№ вЂ” РїСЂРѕРІРµСЂСЊ СЃРѕСЃС‚РѕСЏРЅРёРµ РїР°РЅРµР»Рё. Р‘СЌРєР°Рї Р‘Р”: $bak"
    rm -f "$tmp_sh"
    return 1
  fi
  rm -f "$tmp_sh"
  detect_env
  local nf
  nf=$(detect_panel_flavor)
  if [[ "$nf" == "lucx" ]]; then
    log "Р“РѕС‚РѕРІРѕ: РїР°РЅРµР»СЊ РѕР±РЅРѕРІР»РµРЅР° РґРѕ LucX UI (РёРЅР±Р°СѓРЅРґС‹/РєР»РёРµРЅС‚С‹ РЅР° РјРµСЃС‚Рµ)."
    warn "Р”Р°Р»СЊС€Рµ: РїСЂРѕРіРѕРЅРё Рї.1 Р·Р°РЅРѕРІРѕ вЂ” РѕРЅ РїРµСЂРµСЃС‚СЂРѕРёС‚ SNI/hosts/СЃРµСЂС‚С‹ РїРѕРґ LucX."
  else
    warn "РџРѕСЃР»Рµ СѓСЃС‚Р°РЅРѕРІРєРё РїР°РЅРµР»СЊ РѕРїСЂРµРґРµР»СЏРµС‚СЃСЏ РєР°Рє В«$nfВ» вЂ” РµСЃР»Рё СЌС‚Рѕ РЅРµ С‚Рѕ, С‡С‚Рѕ РѕР¶РёРґР°Р», СЂР°Р·Р±РёСЂР°Р№СЃСЏ РІСЂСѓС‡РЅСѓСЋ (Р±СЌРєР°Рї: $bak)."
  fi
  return 0
}

# Р•РґРёРЅС‹Р№ РїСѓРЅРєС‚ Рї.7: СЃРјРѕС‚СЂРёРј РєР°РєР°СЏ РїР°РЅРµР»СЊ СЃС‚РѕРёС‚ Рё РїСЂРµРґР»Р°РіР°РµРј РґРµР№СЃС‚РІРёСЏ.
panel_manage() {
  line; echo -e "${B}   РџРђРќР•Р›Р¬ вЂ” РЈРЎРўРђРќРћР’РљРђ / РћР‘РќРћР’Р›Р•РќРР• / РЈР”РђР›Р•РќРР•${N}"; line
  local flavor
  flavor=$(detect_panel_flavor)
  case "$flavor" in
    lucx)
      log "РЈСЃС‚Р°РЅРѕРІР»РµРЅР°: LucX UI (РЅР°Р№РґРµРЅС‹ schema-РјР°СЂРєРµСЂС‹; x-ui.db: ${XUI_DB:-?})"
      ;;
    3x-ui)
      log "РЈСЃС‚Р°РЅРѕРІР»РµРЅР°: РѕСЂРёРіРёРЅР°Р»СЊРЅС‹Р№ 3x-ui (LucX schema-РјР°СЂРєРµСЂС‹ РЅРµ РЅР°Р№РґРµРЅС‹; x-ui.db: ${XUI_DB:-?})"
      warn "РџСЂРѕС‚РѕРєРѕР»С‹ LucX (qwdtt/csqtt/tproxy/naive/anytls/trusttunnel/hysteria) РІ РЅРµР№ СЂР°Р±РѕС‚Р°С‚СЊ РЅРµ Р±СѓРґСѓС‚."
      ;;
    *)
      log "РџР°РЅРµР»СЊ РЅРµ РЅР°Р№РґРµРЅР° вЂ” СѓСЃС‚Р°РЅРѕРІРєР° LucX UI."
      install_lucx_panel
      return 0
      ;;
  esac
  echo
  if [[ "$flavor" == "3x-ui" ]]; then
    echo "  1) РњРёРіСЂРёСЂРѕРІР°С‚СЊ РѕСЂРёРіРёРЅР°Р»СЊРЅС‹Р№ 3x-ui в†’ LucX UI (Р±СЌРєР°Рї Р‘Р”; РёРЅР±Р°СѓРЅРґС‹ СЃРѕС…СЂР°РЅСЏС‚СЃСЏ)"
  else
    echo "  1) РџРµСЂРµСѓСЃС‚Р°РЅРѕРІРёС‚СЊ/РѕР±РЅРѕРІРёС‚СЊ LucX UI (Р±СЌРєР°Рї Р‘Р”; РёРЅР±Р°СѓРЅРґС‹ СЃРѕС…СЂР°РЅСЏС‚СЃСЏ)"
  fi
  echo "  2) РЈРґР°Р»РёС‚СЊ РїР°РЅРµР»СЊ СЃРѕ РІСЃРµРјРё РґР°РЅРЅС‹РјРё"
  echo "  0) РќР°Р·Р°Рґ"
  local act=""
  ask act "Р’С‹Р±РѕСЂ" "0" '^[0-2]$'
  case "$act" in
    1) panel_upgrade_lucx; pause ;;
    2)
      # РџРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ РІРЅСѓС‚СЂРё uninstall_panel_lucx РїРѕСЃР»Рµ РїРѕРєР°Р·Р°
      # С‚РѕС‡РЅРѕРіРѕ СЃРїРёСЃРєР° СѓРґР°Р»СЏРµРјС‹С… С„Р°Р№Р»РѕРІ Рё СЃРѕР·РґР°РЅРёСЏ Р±СЌРєР°РїР°.
      uninstall_panel_lucx
      pause
      ;;
  esac
  return 0
}

adguard_manage() {
  line; echo -e "${B}   ADGUARD HOME вЂ” РЈРЎРўРђРќРћР’РљРђ / РЈР”РђР›Р•РќРР•${N}"; line
  if [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]]; then
    log "AdGuard Home СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ (service: $ADG_SERVICE)"
    local go=""
    askyn go "РЈРґР°Р»РёС‚СЊ AdGuard Home?" "n"
    [[ "$go" == true ]] && uninstall_adguard
    return 0
  fi
  log "AdGuard Home РЅРµ РЅР°Р№РґРµРЅ вЂ” СѓСЃС‚Р°РЅРѕРІРєР°."
  install_adguard_home
}

# =====================================================================
# Р“РёРіРёРµРЅР° nginx Рё Р»РѕРіРѕРІ: server_tokens off, security-Р·Р°РіРѕР»РѕРІРєРё РЅР° decoy,
# СЂРѕС‚Р°С†РёСЏ decoy-Р»РѕРіРѕРІ (РµСЃР»Рё РЅРµ РїРѕРєСЂС‹С‚Р° СЃРёСЃС‚РµРјРЅС‹Рј logrotate).
# =====================================================================
nginx_hygiene() {
  line; echo -e "${B}   Р“РР“РР•РќРђ NGINX Р Р›РћР“РћР’${N}"; line
  mkdir -p "$BACKUP_DIR" 2>/dev/null || true
  local changed=0
  # 1) server_tokens off вЂ” РЅРµ РїРѕРєР°Р·С‹РІР°С‚СЊ РІРµСЂСЃРёСЋ nginx
  # (СЃРЅР°С‡Р°Р»Р° СЃРЅРёРјР°РµРј РІРѕР·РјРѕР¶РЅС‹Р№ РґСѓР±Р»СЊ РѕС‚ РїСЂРµР¶РЅРµРіРѕ Р·Р°РїСѓСЃРєР°; РґРёСЂРµРєС‚РёРІР°
  #  РјРѕР¶РµС‚ СѓР¶Рµ Р±С‹С‚СЊ Р·Р°РґР°РЅР° РІ Р»СЋР±РѕРј СЂРµРіРёСЃС‚СЂРµ вЂ” С‚РѕРіРґР° РЅРѕСЂРјР°Р»РёР·СѓРµРј Рє off)
  cp -a /etc/nginx/nginx.conf "$BACKUP_DIR/nginx.conf.bak-$(date +%Y%m%d-%H%M%S)" 2>/dev/null || true
  if grep -q 'server_tokens off; # stack-manager' /etc/nginx/nginx.conf 2>/dev/null; then
    sed -i '/server_tokens off; # stack-manager/d' /etc/nginx/nginx.conf
    log "server_tokens: СѓР±СЂР°РЅ РґСѓР±Р»СЊ РѕС‚ РїСЂРѕС€Р»РѕРіРѕ Р·Р°РїСѓСЃРєР°"; changed=1
  fi
  if grep -qiE '^[[:space:]]*server_tokens[[:space:]]+' /etc/nginx/nginx.conf 2>/dev/null; then
    sed -i -E 's/^([[:space:]]*server_tokens[[:space:]]+).*/\1off; # stack-manager/I' /etc/nginx/nginx.conf
    log "server_tokens: СѓР¶Рµ Р±С‹Р» Р·Р°РґР°РЅ РІ nginx.conf вЂ” РїСЂРёРІРµРґС‘РЅ Рє off"
  else
    sed -i 's/^http {/http {\n    server_tokens off; # stack-manager/' /etc/nginx/nginx.conf
    if grep -q 'server_tokens off' /etc/nginx/nginx.conf; then
      log "server_tokens off в†’ РІРєР»СЋС‡С‘РЅ (РІРµСЂСЃРёСЏ nginx Р±РѕР»СЊС€Рµ РЅРµ СЃРІРµС‚РёС‚СЃСЏ)"
    else
      err "РЅРµ РЅР°С€С‘Р» 'http {' РІ nginx.conf вЂ” РІСЃС‚Р°РІСЊ 'server_tokens off;' РІСЂСѓС‡РЅСѓСЋ"
    fi
  fi
  grep -qiE '^[[:space:]]*server_tokens[[:space:]]+off' /etc/nginx/nginx.conf 2>/dev/null && { audit "nginx: server_tokens off"; changed=1; }
  # 2) security-Р·Р°РіРѕР»РѕРІРєРё decoy: СЃРЅРёРїРїРµС‚ + РІР¶РёРІР»РµРЅРёРµ РІРѕ РІСЃРµ Р±Р»РѕРєРё stack.conf
  mkdir -p /etc/nginx/snippets
  cat > /etc/nginx/snippets/decoy-headers.conf <<'EOF'
add_header X-Content-Type-Options "nosniff" always;
add_header X-Frame-Options "SAMEORIGIN" always;
add_header Referrer-Policy "no-referrer-when-downgrade" always;
EOF
  if grep -q 'snippets/decoy-headers' "$STACK_CONF" 2>/dev/null; then
    log "Р·Р°РіРѕР»РѕРІРєРё decoy: СѓР¶Рµ РїРѕРґРєР»СЋС‡РµРЅС‹"
  elif [[ -f "$STACK_CONF" ]]; then
    cp -a "$STACK_CONF" "$BACKUP_DIR/stack.conf.bak-hygiene-$(date +%Y%m%d-%H%M%S)" 2>/dev/null || true
    sed -i '/^    ssl_certificate_key /a\    include /etc/nginx/snippets/decoy-headers.conf;' "$STACK_CONF"
    log "Р·Р°РіРѕР»РѕРІРєРё decoy: РїРѕРґРєР»СЋС‡РµРЅС‹ РєРѕ РІСЃРµРј Р±Р»РѕРєР°Рј stack.conf"; audit "nginx: decoy-Р·Р°РіРѕР»РѕРІРєРё (nosniff/SAMEORIGIN/referrer)"; changed=1
  fi
  # 3) СЂРѕС‚Р°С†РёСЏ decoy-Р»РѕРіРѕРІ (РµСЃР»Рё РЅРµ РїРѕРєСЂС‹С‚Р° РѕР±С‰РёРј logrotate nginx)
  if grep -rqs 'var/log/nginx' /etc/logrotate.d/ 2>/dev/null; then
    log "СЂРѕС‚Р°С†РёСЏ Р»РѕРіРѕРІ nginx: СѓР¶Рµ РЅР°СЃС‚СЂРѕРµРЅР° (/etc/logrotate.d)"
  else
    cat > /etc/logrotate.d/stack-decoy <<'EOF'
/var/log/nginx/decoy-access.log /var/log/nginx/decoy-error.log {
    daily
    rotate 14
    size 50M
    missingok
    notifempty
    compress
    delaycompress
    sharedscripts
    postrotate
        [ -f /var/run/nginx.pid ] && kill -USR1 $(cat /var/run/nginx.pid) 2>/dev/null || true
    endscript
}
EOF
    log "СЂРѕС‚Р°С†РёСЏ decoy-Р»РѕРіРѕРІ: СЃРѕР·РґР°РЅР° (РґРµРЅСЊ / 14 РєРѕРїРёР№ / СЃР¶Р°С‚РёРµ)"; audit "logrotate: stack-decoy СЃРѕР·РґР°РЅ"; changed=1
  fi
  # 4) РїСЂРѕРІРµСЂРєР° Рё РїРµСЂРµР·Р°РіСЂСѓР·РєР°
  if (( changed )); then
    if nginx -t >/dev/null 2>&1; then
      nginx_reload
      log "Р“РёРіРёРµРЅР° РїСЂРёРјРµРЅРµРЅР° вњ“"
    else
      err "nginx -t РЅРµ РїСЂРѕС€С‘Р» вЂ” РѕС‚РєР°С‚: $BACKUP_DIR/*.bak-hygiene-*"
      nginx -t 2>&1 | tail -3
      return 1
    fi
  else
    log "Р’СЃС‘ СѓР¶Рµ РІ РїРѕСЂСЏРґРєРµ вЂ” РјРµРЅСЏС‚СЊ РЅРµС‡РµРіРѕ вњ“"
  fi
  pause
}

# =====================================================================
# РЎРўР•Р›РЎ-РђРЈР”РРў: С‡С‚Рѕ Рѕ СЃРµСЂРІРµСЂРµ СѓРІРёРґРёС‚ Shodan/Censys/crt.sh.
# РўРѕР»СЊРєРѕ С‡С‚РµРЅРёРµ вЂ” РЅРёС‡РµРіРѕ РЅРµ РјРµРЅСЏРµС‚.
# =====================================================================
stealth_audit() {
  line; echo -e "${B}   РЎРўР•Р›РЎ-РђРЈР”РРў (РіР»Р°Р·Р°РјРё СЃРєР°РЅРµСЂР°)${N}"; line
  local base="${WILDCARD_DOMAIN:-${PANEL_DOMAIN:-}}"
  # РїРѕСЃР»РµРґРЅРёРµ РґРІР° Р»РµР№Р±Р»Р°: *.example.com / example.com / panel.example.com в†’ example.com
  local _p
  IFS='.' read -r -a _p <<<"$base"
  local _n=${#_p[@]}
  if (( _n >= 3 )); then base="${_p[_n-2]}.${_p[_n-1]}"; fi

  local ufw_on=0
  ufw_is_active && ufw_on=1
  local allowed=""
  if [[ "$ufw_on" == 1 ]]; then
    allowed=$(LC_ALL=C ufw status 2>/dev/null | awk '/ALLOW/ {print $1}' | sort -u)
  else
    warn "UFW РЅРµ Р°РєС‚РёРІРµРЅ вЂ” Р’РЎР• СЃР»СѓС€Р°СЋС‰РёРµ РїРѕСЂС‚С‹ РІРёРґРЅС‹ РёРЅС‚РµСЂРЅРµС‚Сѓ!"
  fi
  stealth_vis() {   # РїРѕСЂС‚/РїСЂРѕС‚РѕРєРѕР» РІРёРґРµРЅ РјРёСЂСѓ? (ufw off в†’ РІРёРґРµРЅ РІСЃС‘)
    [[ "$ufw_on" == 1 ]] || return 0
    grep -qE "^${1}/${2}([[:space:]]|$)" <<<"$allowed" \
      || grep -qE "^${1}([[:space:]]|$)" <<<"$allowed"
  }

  echo; echo -e "${B}вЂ” 1. РЎР»СѓС€Р°СЋС‰РёРµ TCP-РїРѕСЂС‚С‹ вЂ”${N}"
  local p
  for p in $(ss -tln 2>/dev/null | awk 'NR>1 { if ($4 ~ /^127\./ || $4 ~ /^\[::1\]/) next; split($4,a,":"); print a[length(a)] }' | sort -un); do
    if ! stealth_vis "$p" tcp; then
      ok "РїРѕСЂС‚ $p вЂ” СЃР»СѓС€Р°РµС‚СЃСЏ, РЅРѕ Р·Р°РєСЂС‹С‚ UFW (СЃРєР°РЅРµСЂР°Рј РЅРµРІРёРґРёРј)"
    elif [[ "$p" == "443" ]]; then
      ok "РїРѕСЂС‚ 443 вЂ” SNI-СЂРѕСѓС‚РµСЂ (decoy-РґРѕРєС‚СЂРёРЅР°)"
    elif [[ "$p" == "80" ]]; then
      log "РїРѕСЂС‚ 80 вЂ” HTTP (РѕР±С‹С‡РЅРѕ РґР»СЏ ACME); С‡С‚Рѕ РѕС‚РґР°С‘С‚ вЂ” СЃРј. СЂР°Р·РґРµР» 3"
    elif [[ "$p" == "22" ]]; then
      warn "РїРѕСЂС‚ 22 вЂ” SSH РѕС‚РєСЂС‹С‚ РјРёСЂСѓ: Р±Р°РЅРµСЂ + host key РїСЂРёРІСЏР·С‹РІР°СЋС‚ С‚РµР±СЏ РјРµР¶РґСѓ IP (СЃРј. СЂР°Р·РґРµР» 5)"
    else
      err "РїРѕСЂС‚ $p вЂ” РЅРµСЃС‚Р°РЅРґР°СЂС‚РЅС‹Р№ Рё РћРўРљР Р«Рў: СЃРєР°РЅРµСЂС‹ РµРіРѕ РёРЅРґРµРєСЃРёСЂСѓСЋС‚ (РёРЅР±Р°СѓРЅРґ?). Р›СѓС‡С€Рµ Р·Р° 443/SNI РёР»Рё reality"
      echo "      (РїСЂРѕРїСѓСЃС‚РёР»Рѕ РїСЂР°РІРёР»Рѕ UFW: $(grep -E "^${p}/" <<<"$allowed" | head -1))"
    fi
  done

  echo; echo -e "${B}вЂ” 2. РЎР»СѓС€Р°СЋС‰РёРµ UDP-РїРѕСЂС‚С‹ (QUIC/РєСЂР°СѓС‚С‹) вЂ”${N}"
  local any_udp=0
  for p in $(ss -uln 2>/dev/null | awk 'NR>1 { if ($4 ~ /^127\./ || $4 ~ /^\[::1\]/) next; if ($5 != "*:*") next; split($4,a,":"); print a[length(a)] }' | sort -un); do
    any_udp=1
    if ! stealth_vis "$p" udp; then
      ok "udp $p вЂ” Р·Р°РєСЂС‹С‚ UFW (РЅРµРІРёРґРёРј)"
    elif [[ "$p" == "53" ]]; then
      warn "udp 53 вЂ” DNS; РµСЃР»Рё РѕС‚РІРµС‡Р°РµС‚ РЅР°СЂСѓР¶Сѓ вЂ” open resolver (СЃРј. СЂР°Р·РґРµР» 5)"
    else
      err "udp $p вЂ” РѕС‚РєСЂС‹С‚ (hysteria/tuic?): QUIC-Р±Р°РЅРµСЂ С„РёРЅРіРµСЂРїСЂРёРЅС‚РёС‚СЃСЏ Censys"
      echo "      (РїСЂРѕРїСѓСЃС‚РёР»Рѕ РїСЂР°РІРёР»Рѕ UFW: $(grep -E "^${p}/" <<<"$allowed" | head -1))"
    fi
  done
  [[ "$any_udp" == 0 ]] && ok "РѕС‚РєСЂС‹С‚С‹С… UDP-СЃР»СѓС€Р°С‚РµР»РµР№ РЅРµС‚"

  echo; echo -e "${B}вЂ” 3. Р§С‚Рѕ РІРёРґРёС‚ СЃРєР°РЅРµСЂ РЅР° :443 Р‘Р•Р— SNI вЂ”${N}"
  local subj
  subj=$(echo | timeout 8 openssl s_client -connect 127.0.0.1:443 -noservername 2>/dev/null | openssl x509 -noout -subject 2>/dev/null)
  if [[ -z "$subj" ]]; then
    warn "СЃРµСЂС‚РёС„РёРєР°С‚ РЅРµ РїРѕР»СѓС‡РµРЅ вЂ” РїСЂРѕРІРµСЂСЊ СЂСѓРєР°РјРё: openssl s_client -connect $(hostname -I 2>/dev/null | awk '{print $1}'):443"
  else
    echo "    $subj"
    if [[ -n "$PANEL_DOMAIN" && "$subj" == *"$PANEL_DOMAIN"* ]]; then
      err "443 РѕС‚РґР°С‘С‚ СЃРµСЂС‚ РџРђРќР•Р›Р в†’ Shodan РїСЂРёРІСЏР¶РµС‚ В«$PANEL_DOMAINВ» Рє IP. РЎРјРµРЅРё default-Р±Р»РѕРє (decoy-СЃРµСЂС‚)."
    elif [[ -n "$base" && "$subj" == *"$base"* ]]; then
      ok "СЃРІРѕР№ wildcard/decoy-СЃРµСЂС‚ вЂ” РїСЂРёРµРјР»РµРјРѕ (РїР°РЅРµР»СЊ РЅРµ СЃРІРµС‚РёС‚СЃСЏ)"
    else
      ok "С‡СѓР¶РѕР№ СЃРµСЂС‚ вЂ” РёРґРµР°Р»СЊРЅРѕ (РІС‹РіР»СЏРґРёС€СЊ С‡СѓР¶РёРј СЃР°Р№С‚РѕРј)"
    fi
  fi

  echo; echo -e "${B}вЂ” 4. HTTP :80 вЂ”${N}"
  if ! stealth_vis "80" tcp; then
    ok "80 Р·Р°РєСЂС‹С‚ UFW вЂ” РЅРµРІРёРґРёРј (ACME Рї.4 РІСЂРµРјРµРЅРЅРѕ РѕС‚РєСЂС‹РІР°РµС‚ СЃР°Рј)"
  else
    local code; code=$(curl -s -o /dev/null -w '%{http_code}' -m 6 http://127.0.0.1/ 2>/dev/null)
    case "$code" in
      301|302|308) ok "СЂРµРґРёСЂРµРєС‚ РЅР° HTTPS ($code) вЂ” РЅРµР№С‚СЂР°Р»СЊРЅРѕ" ;;
      000) warn "80 РѕС‚РєСЂС‹С‚ РІ UFW, РЅРѕ РЅРµ РѕС‚РІРµС‡Р°РµС‚ вЂ” Р»СѓС‡С€Рµ Р·Р°РєСЂС‹С‚СЊ" ;;
      *) warn "РѕС‚РІРµС‚ $code вЂ” СЃРєР°РЅРµСЂ РёРЅРґРµРєСЃРёСЂСѓРµС‚ СЃРѕРґРµСЂР¶РёРјРѕРµ; РїСЂРѕРІРµСЂСЊ, С‡С‚Рѕ С‚Р°Рј decoy/Р·Р°РіР»СѓС€РєР°, Р° РЅРµ СЃР»СѓР¶РµР±РЅРѕРµ" ;;
    esac
  fi

  echo; echo -e "${B}вЂ” 5. SSH :22 вЂ”${N}"
  if ! stealth_vis "22" tcp; then
    ok "22 Р·Р°РєСЂС‹С‚ UFW РґР»СЏ РјРёСЂР° вЂ” СЃРєР°РЅРµСЂР°Рј РЅРµРІРёРґРµРЅ"
  else
    warn "22 РѕС‚РєСЂС‹С‚: host key Shodan СЃРІСЏР·С‹РІР°РµС‚ РІСЃРµ С‚РІРѕРё IP (РїРµСЂРµРµР·Рґ РЅРµ РїРѕРјРѕРіР°РµС‚)."
    echo "      РЎРјСЏРіС‡РµРЅРёРµ: UFW С‚РѕР»СЊРєРѕ РЅР° СЃРІРѕР№ IP, СЃРјРµРЅР° РїРѕСЂС‚Р° РёР»Рё knocking (РўРћР›Р¬РљРћ РЅР° 22, РЅРµ РЅР° 443!)."
  fi

  echo; echo -e "${B}вЂ” 6. DNS :53 РЅР°СЂСѓР¶Сѓ вЂ”${N}"
  local udp53; udp53=$(ss -uln 2>/dev/null | awk 'NR>1 && $4 ~ /:53$/ && $5 == "*:*" && $4 !~ /^127\./ && $4 !~ /^\[::1\]/ {c++} END {print c+0}')
  if [[ "$udp53" -eq 0 ]]; then
    ok "53 РЅР°СЂСѓР¶Сѓ РЅРµ СЃР»СѓС€Р°РµС‚СЃСЏ вњ“"
  elif ! stealth_vis "53" udp; then
    ok "53 СЃР»СѓС€Р°РµС‚СЃСЏ, РЅРѕ Р·Р°РєСЂС‹С‚ UFW вњ“"
  else
    err "53 РѕС‚РєСЂС‹С‚ РјРёСЂСѓ вЂ” open resolver (Р°Р±СЊСЋР· + РїР°Р»РµРІРѕ)! Р—Р°РєСЂРѕР№ РІ UFW (Рї.11)."
  fi

  echo; echo -e "${B}вЂ” 7. РџСѓР±Р»РёС‡РЅС‹Рµ РёРјРµРЅР° (Certificate Transparency) вЂ”${N}"
  if [[ -z "$base" ]]; then
    log "Р±Р°Р·РѕРІС‹Р№ РґРѕРјРµРЅ РЅРµ РѕРїСЂРµРґРµР»С‘РЅ вЂ” РїСЂРѕРїСѓСЃРє"
  else
    local ct
    ct=$(curl -s -m 25 --retry 2 --retry-delay 2 "https://crt.sh/?q=%25.${base}&output=json" 2>/dev/null | python3 -c '
import json, sys
try: d = json.load(sys.stdin)
except Exception: sys.exit(0)
names = set()
for r in d if isinstance(d, list) else []:
    for n in str(r.get("name_value", "")).split("\n"):
        n = n.strip().lstrip("*.")
        if n and "=" not in n: names.add(n)
for n in sorted(names)[:20]: print(n)' 2>/dev/null)
    if [[ -z "$ct" ]]; then
      log "crt.sh РЅРµ РѕС‚РІРµС‚РёР» вЂ” РїСЂРѕРІРµСЂСЊ СЂСѓРєР°РјРё: https://crt.sh/?q=%.${base}"
    else
      warn "СЌС‚Рё РёРјРµРЅР° СѓР¶Рµ РїСѓР±Р»РёС‡РЅС‹ (РєР°Р¶РґС‹Р№ РІС‹РїСѓСЃРє СЃРµСЂС‚Р° = Р·Р°РїРёСЃСЊ РІ CT-Р»РѕРіР°С…):"
      echo "$ct" | sed 's/^/      /'
      echo "      РџСЂР°РІРёР»Рѕ: С‡СѓРІСЃС‚РІРёС‚РµР»СЊРЅС‹Рј РёРјРµРЅР°Рј РЅРµ РІС‹РїСѓСЃРєР°С‚СЊ РѕС‚РґРµР»СЊРЅС‹С… СЃРµСЂС‚РѕРІ вЂ” С‚РѕР»СЊРєРѕ wildcard."
    fi
  fi

  echo; echo -e "${B}вЂ” 8. РћРїС‚-Р°СѓС‚ РёР· РїРѕРёСЃРєРѕРІРёРєРѕРІ вЂ”${N}"
  echo "      Shodan: Р°РєРєР°СѓРЅС‚ в†’ shodan.io в†’ В«Request IP RemovalВ» РґР»СЏ $(server_ip4 2>/dev/null)"
  echo "      Censys: search.censys.io в†’ РІР°С€ С…РѕСЃС‚ в†’ Opt-Out Host"
  echo "      РЎРЅР°С‡Р°Р»Р° Р·Р°РєСЂС‹С‚СЊ РґС‹СЂС‹ (РІС‹С€Рµ), РїРѕС‚РѕРј РѕРїС‚-Р°СѓС‚ вЂ” РёРЅР°С‡Рµ СЂРµ-СЃРєР°РЅ РІСЃС‘ РІРµСЂРЅС‘С‚."
  echo
  log "РђСѓРґРёС‚ С‚РѕР»СЊРєРѕ С‡РёС‚Р°Р» вЂ” РЅРёС‡РµРіРѕ РЅРµ РјРµРЅСЏР»."
  pause
}

# =====================================================================
# РћРўРљРђРў Р Р”Р•РњРћРќРўРђР– РЎРўР•РљРђ
#   РџРѕРґРјРµРЅСЋ РїРѕСЌС‚Р°РїРЅРѕРіРѕ РІРѕР·РІСЂР°С‚Р° Рє В«РїР»РѕСЃРєРѕРјСѓВ» СЃРѕСЃС‚РѕСЏРЅРёСЋ:
#     1) РѕС‚РєСЂС‹С‚СЊ РїРѕСЂС‚С‹ РЅР°СЂСѓР¶Сѓ (РїР°РЅРµР»СЊ/РїРѕРґРїРёСЃРєРё/РёРЅР±Р°СѓРЅРґС‹)
#     2) РїСЂР°РІРёР»Р° UFW (СЃРЅРёРјРѕРє / РїРѕ РѕРґРЅРѕРјСѓ / reset+open)
#     3) СЃР»СѓР¶Р±С‹ Рё РёРЅС‚РµРіСЂР°С†РёРё СЃС‚РµРєР°
#     4) РєРѕРЅС„РёРіРё Рё РєР°С‚Р°Р»РѕРіРё СЃС‚РµРєР°
#     5) СѓРґР°Р»РµРЅРёРµ nginx (РїР°РєРµС‚ + РєРѕРЅС„РёРіРё)
#     6) РїРѕР»РЅС‹Р№ РѕС‚РєР°С‚ (РІСЃС‘ РІС‹С€Рµ, С‚РёС…Рѕ, РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ YES)
#   AdGuard Home Рё СЃРµСЂС‚С‹ LE РќР• С‚СЂРѕРіР°СЋС‚СЃСЏ вЂ” Сѓ AdGuard СЃРІРѕР№ РїСѓРЅРєС‚ (Рї.14),
#   СЃРµСЂС‚С‹ РЅРµ РЅР°С€Рё, РјРѕРіСѓС‚ РёСЃРїРѕР»СЊР·РѕРІР°С‚СЊСЃСЏ РґСЂСѓРіРёРјРё СЃРµСЂРІРёСЃР°РјРё.
# =====================================================================

# РЎРїРёСЃРѕРє СЃР»СѓР¶Р±/РёРЅС‚РµРіСЂР°С†РёР№, РєРѕС‚РѕСЂС‹Рµ СЃРѕР·РґР°С‘С‚ stack-manager
rb_services_list() {
  printf '%s\n' \
    "stack-heal.timer|С‚Р°Р№РјРµСЂ Р°РІС‚РѕРїРѕС‡РёРЅРєРё РёРЅР±Р°СѓРЅРґРѕРІ (РєР°Р¶РґС‹Рµ 2 РјРёРЅ)|/etc/systemd/system/stack-heal.timer|systemd" \
    "stack-heal.service|СЃР»СѓР¶Р±Р° Р°РІС‚РѕРїРѕС‡РёРЅРєРё (oneshot, Р·Р°РїСѓСЃРєР°РµС‚СЃСЏ С‚Р°Р№РјРµСЂРѕРј)|/etc/systemd/system/stack-heal.service|systemd" \
    "fail2ban jail decoy-login|Р±Р°РЅ Р·Р° POST /login Рє decoy-СЃС‚СЂР°РЅРёС†Р°Рј|/etc/fail2ban/jail.d/decoy-login.local|f2b" \
    "fail2ban filter decoy-login|С„РёР»СЊС‚СЂ РґР»СЏ jail decoy-login|/etc/fail2ban/filter.d/decoy-login.conf|f2b" \
    "certbot deploy-hook|СЂРµСЃС‚Р°СЂС‚ x-ui/nginx/AdGuard РїРѕСЃР»Рµ renew СЃРµСЂС‚РѕРІ|/etc/letsencrypt/renewal-hooks/deploy/stack-cert-mirror.sh|file"
}

# РЎРїРёСЃРѕРє РєРѕРЅС„РёРіРѕРІ Рё РєР°С‚Р°Р»РѕРіРѕРІ СЃС‚РµРєР°
rb_configs_list() {
  printf '%s\n' \
    "/etc/nginx/sites-available/stack.conf|РѕСЃРЅРѕРІРЅРѕР№ http-РєРѕРЅС„РёРі СЃС‚РµРєР° (ACME :80 + РїР°РЅРµР»СЊ :4443 + decoy)|file" \
    "/etc/nginx/sites-enabled/stack.conf|СЃРёРјР»РёРЅРє РѕСЃРЅРѕРІРЅРѕРіРѕ РєРѕРЅС„РёРіР°|link" \
    "/etc/nginx/streams-available/sni-router.conf|SNI-СЂРѕСѓС‚РµСЂ 443 (map + upstream)|file" \
    "/etc/nginx/streams-enabled/sni-router.conf|СЃРёРјР»РёРЅРє SNI-СЂРѕСѓС‚РµСЂР°|link" \
    "/etc/nginx/snippets/decoy-headers.conf|security-Р·Р°РіРѕР»РѕРІРєРё decoy|file" \
    "/etc/logrotate.d/stack-decoy|СЂРѕС‚Р°С†РёСЏ decoy-Р»РѕРіРѕРІ|file" \
    "/var/www/panel-decoy|decoy-Р·Р°РіР»СѓС€РєР° РєРѕСЂРЅСЏ РґРѕРјРµРЅР° РїР°РЅРµР»Рё|dir" \
    "/var/www/decoy-templates|С€Р°Р±Р»РѕРЅС‹ decoy (corporate, blog, docsвЂ¦)|dir" \
    "/var/www/decoy-login|login-С€Р°Р±Р»РѕРЅС‹ (adguard, portainer, jellyfinвЂ¦)|dir"
}

# --- 23.1 РћС‚РєСЂС‹С‚СЊ РїРѕСЂС‚С‹ РЅР°СЂСѓР¶Сѓ (РїР°РЅРµР»СЊ/РїРѕРґРїРёСЃРєРё/РёРЅР±Р°СѓРЅРґС‹) --------------
rb_open_ports() {
  line; echo -e "${B}   РћРўРљР Р«РўР¬ РџРћР РўР« РќРђР РЈР–РЈ${N}"; line
  echo "  РЎРµР№С‡Р°СЃ РїР°РЅРµР»СЊ/РїРѕРґРїРёСЃРєРё/РёРЅР±Р°СѓРЅРґС‹ Р¶РёРІСѓС‚ Р·Р° SNI-СЂРѕСѓС‚РµСЂРѕРј (127.0.0.1)."
  echo "  Р—РґРµСЃСЊ вЂ” РѕС‚РєСЂС‹С‚СЊ РёС… РЅР°РїСЂСЏРјСѓСЋ РЅР° 0.0.0.0 (РїРѕ РєР°Р¶РґРѕРјСѓ РїСѓРЅРєС‚Сѓ СЃРїСЂРѕС€Сѓ)."
  echo
  [[ -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ"; pause; return 1; }
  auto_backup_stack >/dev/null 2>&1 || true

  local wp wl sp sl
  wp=$(xui_get webPort); wl=$(xui_get webListen)
  sp=$(xui_get subPort); sl=$(xui_get subListen)

  local need_restart=0
  systemctl stop x-ui 2>/dev/null || true

  echo "в–ё РџР°РЅРµР»СЊ: bind=${wl:-<РїСѓСЃС‚Рѕ>} port=${wp:-?}"
  if [[ -n "$wp" && ( "$wl" == "127.0.0.1" || "$wl" == "::1" || -z "$wl" ) ]]; then
    local go=""
    askyn go "  РћС‚РєСЂС‹С‚СЊ РїР°РЅРµР»СЊ ($wp) РЅР°СЂСѓР¶Сѓ (0.0.0.0)?" "n"
    if [[ "$go" == true ]]; then
      xui_set_setting webListen '0.0.0.0'
      log "  webListen в†’ 0.0.0.0 (РїР°РЅРµР»СЊ $wp)"; need_restart=1
      audit "rollback: webListen в†’ 0.0.0.0"
    fi
  else
    [[ -n "$wp" ]] && log "  РїР°РЅРµР»СЊ СѓР¶Рµ СЃР»СѓС€Р°РµС‚ ${wl:-0.0.0.0}:$wp" || warn "  webPort РЅРµ РЅР°Р№РґРµРЅ"
  fi

  echo
  echo "в–ё РџРѕРґРїРёСЃРєРё: bind=${sl:-<РїСѓСЃС‚Рѕ>} port=${sp:-?}"
  if [[ -n "$sp" && ( "$sl" == "127.0.0.1" || "$sl" == "::1" || -z "$sl" ) ]]; then
    local go=""
    askyn go "  РћС‚РєСЂС‹С‚СЊ РїРѕРґРїРёСЃРєРё ($sp) РЅР°СЂСѓР¶Сѓ (0.0.0.0)?" "n"
    if [[ "$go" == true ]]; then
      xui_set_setting subListen '0.0.0.0'
      log "  subListen в†’ 0.0.0.0 (РїРѕРґРїРёСЃРєРё $sp)"; need_restart=1
      audit "rollback: subListen в†’ 0.0.0.0"
    fi
  else
    [[ -n "$sp" ]] && log "  РїРѕРґРїРёСЃРєРё СѓР¶Рµ СЃР»СѓС€Р°СЋС‚ ${sl:-0.0.0.0}:$sp" || warn "  subPort РЅРµ РЅР°Р№РґРµРЅ"
  fi

  echo
  echo "в–ё РРЅР±Р°СѓРЅРґС‹:"
  # Р’РђР–РќРћ: СЃРЅР°С‡Р°Р»Р° СЃРѕР±СЂР°С‚СЊ СЃС‚СЂРѕРєРё, РїРѕС‚РѕРј СЃРїСЂР°С€РёРІР°С‚СЊ вЂ” РёРЅР°С‡Рµ read РІРЅСѓС‚СЂРё
  # while < <(...) СЃСЉРµСЃС‚ СЃР»РµРґСѓСЋС‰СѓСЋ СЃС‚СЂРѕРєСѓ sqlite РєР°Рє РѕС‚РІРµС‚ РЅР° askyn.
  local -a rows=()
  local _l
  while IFS= read -r _l; do rows+=("$_l"); done < <(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
    "SELECT id, protocol, port, COALESCE(listen,''), COALESCE(json_extract(stream_settings,'\$.security'),'') FROM inbounds ORDER BY id;" 2>/dev/null || true)

  if [[ ${#rows[@]} -eq 0 ]]; then
    warn "  РёРЅР±Р°СѓРЅРґРѕРІ РІ РїР°РЅРµР»Рё РЅРµС‚"
  else
    local row iid iproto iport ilisten isec note go
    for row in "${rows[@]}"; do
      IFS='|' read -r iid iproto iport ilisten isec <<<"$row"
      [[ -z "$iid" ]] && continue
      note=""
      case "$isec" in
        tls)     note=" [TLS вЂ” Р±РµР· nginx СЃРµСЂС‚-РїСѓС‚Рё РІ settings РјРѕРіСѓС‚ СЃС‚Р°С‚СЊ РЅРµРґРѕСЃС‚РёР¶РёРјС‹]" ;;
        reality) note=" [Reality вЂ” dest СѓРєР°Р·С‹РІР°РµС‚ РЅР° Р»РѕРєР°Р»СЊРЅС‹Р№ decoy nginx]" ;;
      esac
      echo "  #$iid $iproto :$iport (bind=${ilisten:-0.0.0.0})$note"
      if [[ "$ilisten" == "127.0.0.1" || "$ilisten" == "::1" ]]; then
        askyn go "    РћС‚РєСЂС‹С‚СЊ #$iid РЅР°СЂСѓР¶Сѓ?" "n"
        if [[ "$go" == true ]]; then
          sqlite3 -cmd ".timeout 3000" "$XUI_DB" "UPDATE inbounds SET listen='0.0.0.0' WHERE id=$iid;" 2>/dev/null || true
          log "    #$iid listen в†’ 0.0.0.0"; need_restart=1
          audit "rollback: inbound #$iid listen в†’ 0.0.0.0"
        fi
      else
        echo "    СѓР¶Рµ СЃР»СѓС€Р°РµС‚ РЅР°СЂСѓР¶Сѓ"
      fi
    done
  fi

  systemctl start x-ui 2>/dev/null || true
  [[ "$need_restart" == 1 ]] && log "x-ui РїРµСЂРµР·Р°РїСѓС‰РµРЅ вЂ” РЅРѕРІС‹Рµ bind'С‹ РїСЂРёРјРµРЅРµРЅС‹"
  pause
}

# --- 23.2 РџСЂР°РІРёР»Р° UFW -------------------------------------------------
rb_firewall() {
  line; echo -e "${B}   РџР РђР’РР›Рђ Р¤РђР™Р Р’РћР›Рђ (UFW)${N}"; line
  if ! command -v ufw >/dev/null 2>&1; then
    warn "UFW РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” С‡РёСЃС‚РёС‚СЊ РЅРµС‡РµРіРѕ"; pause; return 0
  fi
  echo "  РЎС‚Р°С‚СѓСЃ: $(ufw status 2>/dev/null | head -1)"
  echo
  ufw status numbered 2>/dev/null | sed 's/^/    /'
  echo

  if [[ -f "$FW_STATE_DIR/saved" ]]; then
    log "Р•СЃС‚СЊ СЃРЅРёРјРѕРє СЃРѕСЃС‚РѕСЏРЅРёСЏ UFW: $FW_STATE_DIR/saved"
    local rs=""
    askyn rs "Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ РёР· СЃРЅРёРјРєР° (РѕС‚РјРµРЅРёС‚ РІСЃРµ РїСЂР°РІРёР»Р°, РґРѕР±Р°РІР»РµРЅРЅС‹Рµ СЃС‚РµРєРѕРј)?" "y"
    if [[ "$rs" == true ]]; then
      restore_firewall_state
      audit "rollback: UFW РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ РёР· СЃРЅРёРјРєР°"
      return 0
    fi
  fi

  echo "  1) РџСЂРѕР№С‚Рё РїРѕ РєР°Р¶РґРѕРјСѓ РїСЂР°РІРёР»Сѓ (РѕСЃС‚Р°РІРёС‚СЊ/СѓРґР°Р»РёС‚СЊ)"
  echo "  2) Reset UFW (default deny) + РѕС‚РєСЂС‹С‚СЊ РІСЃС‘ СЃР»СѓС€Р°СЋС‰РµРµСЃСЏ"
  echo "  0) РћС‚РјРµРЅР°"
  line
  local c=""
  read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
  case "$c" in
    1)
      # РЎРѕР±РёСЂР°РµРј РЅРѕРјРµСЂР° РїСЂР°РІРёР», РїРѕС‚РѕРј СЃРїСЂР°С€РёРІР°РµРј вЂ” РёРЅР°С‡Рµ read РІРЅСѓС‚СЂРё
      # while < <(...) СЃСЉРµСЃС‚ СЃР»РµРґСѓСЋС‰СѓСЋ СЃС‚СЂРѕРєСѓ ufw РєР°Рє РѕС‚РІРµС‚.
      local -a nums=()
      local _n
      while IFS= read -r _n; do nums+=("$_n"); done < <(
        ufw status numbered 2>/dev/null | grep -oE '^\[[[:space:]]*[0-9]+\]' | grep -oE '[0-9]+' | sort -rn
      )
      local -a to_del=()
      local n rule del
      for n in "${nums[@]}"; do
        rule=$(ufw status numbered 2>/dev/null | grep -E "^\[[[:space:]]*$n\]" || true)
        [[ -z "$rule" ]] && continue
        echo "  $rule"
        askyn del "    РЈРґР°Р»РёС‚СЊ СЌС‚Рѕ РїСЂР°РІРёР»Рѕ?" "n"
        [[ "$del" == true ]] && to_del+=("$n")
      done
      local deleted=0
      for n in "${to_del[@]}"; do
        if ufw --force delete "$n" >/dev/null 2>&1; then
          log "  РїСЂР°РІРёР»Рѕ $n СѓРґР°Р»РµРЅРѕ"; deleted=$((deleted+1))
        else
          warn "  РїСЂР°РІРёР»Рѕ $n РЅРµ СѓРґР°Р»РёР»РѕСЃСЊ"
        fi
      done
      [[ "$deleted" -eq 0 ]] && log "РќРёС‡РµРіРѕ РЅРµ СѓРґР°Р»РµРЅРѕ."
      audit "rollback: UFW СѓРґР°Р»РµРЅРѕ РїСЂР°РІРёР»: $deleted"
      ;;
    2)
      local go=""
      askyn go "РЎР±СЂРѕСЃРёС‚СЊ UFW (default deny + РѕС‚РєСЂС‹С‚СЊ РІСЃС‘ СЃР»СѓС€Р°СЋС‰РµРµСЃСЏ)?" "n"
      [[ "$go" == true ]] || { pause; return 0; }
      save_firewall_state
      ufw --force reset >/dev/null 2>&1 || true
      ufw default deny incoming >/dev/null 2>&1 || true
      ufw default allow outgoing >/dev/null 2>&1 || true
      fw_allow "${SSH_PORT:-22}" tcp "SSH"
      local p
      for p in $(ss -tln 2>/dev/null | awk 'NR>1 { if ($4 ~ /^127\./ || $4 ~ /^\[::1\]/) next; split($4,a,":"); print a[length(a)] }' | sort -un); do
        [[ -n "$p" && "$p" != "${SSH_PORT:-22}" ]] && fw_allow "$p" tcp "rollback-open"
      done
      for p in $(ss -uln 2>/dev/null | awk 'NR>1 { if ($4 ~ /^127\./ || $4 ~ /^\[::1\]/) next; if ($5 != "*:*") next; split($4,a,":"); print a[length(a)] }' | sort -un); do
        [[ -n "$p" ]] && fw_allow "$p" udp "rollback-open"
      done
      ufw --force enable >/dev/null 2>&1 || true
      log "UFW: reset + РѕС‚РєСЂС‹С‚Рѕ РІСЃС‘ СЃР»СѓС€Р°СЋС‰РµРµСЃСЏ"
      audit "rollback: UFW reset + open listening"
      ;;
    *) pause; return 0 ;;
  esac
  pause
}

# --- 23.3 РЎР»СѓР¶Р±С‹ Рё РёРЅС‚РµРіСЂР°С†РёРё -----------------------------------------
rb_services() {
  line; echo -e "${B}   РЎР›РЈР–Р‘Р« Р РРќРўР•Р“Р РђР¦РР РЎРўР•РљРђ${N}"; line
  local -a items=()
  local _l
  while IFS= read -r _l; do items+=("$_l"); done < <(rb_services_list)

  local found=0 name desc path typ exists unit c
  local item
  for item in "${items[@]}"; do
    IFS='|' read -r name desc path typ <<<"$item"
    [[ -z "$name" ]] && continue
    exists=false
    [[ -e "$path" ]] && exists=true
    [[ "$exists" != true ]] && continue
    found=$((found+1))
    echo "  в”Ђ $name"
    echo "    $desc"
    echo "    С„Р°Р№Р»: $path"
    echo "      1) РЈРґР°Р»РёС‚СЊ   2) РћС‚РєР»СЋС‡РёС‚СЊ (С„Р°Р№Р» РѕСЃС‚Р°РІРёС‚СЊ)   3) РћС‚РјРµРЅР°"
    c=""
    ask c "    Р’С‹Р±РѕСЂ" "3" '^[123]$'
    case "$c" in
      1)
        case "$typ" in
          systemd)
            unit=$(basename "$path")
            systemctl disable --now "$unit" >/dev/null 2>&1 || true
            rm -f "$path" 2>/dev/null || true
            systemctl daemon-reload >/dev/null 2>&1 || true
            ;;
          f2b)
            rm -f "$path" 2>/dev/null || true
            systemctl restart fail2ban >/dev/null 2>&1 || true
            ;;
          file)
            rm -f "$path" 2>/dev/null || true
            ;;
        esac
        log "    СѓРґР°Р»РµРЅРѕ"; audit "rollback: СѓРґР°Р»РµРЅРѕ вЂ” $name"
        ;;
      2)
        case "$typ" in
          systemd)
            unit=$(basename "$path")
            systemctl disable --now "$unit" >/dev/null 2>&1 || true
            ;;
          f2b)
            sed -i -E 's/^enabled[[:space:]]*=.*/enabled  = false/' "$path" 2>/dev/null || true
            systemctl restart fail2ban >/dev/null 2>&1 || true
            ;;
          file)
            chmod -x "$path" 2>/dev/null || true
            ;;
        esac
        log "    РѕС‚РєР»СЋС‡РµРЅРѕ (С„Р°Р№Р» РЅР° РјРµСЃС‚Рµ)"; audit "rollback: РѕС‚РєР»СЋС‡РµРЅРѕ вЂ” $name"
        ;;
    esac
  done
  [[ "$found" -eq 0 ]] && log "РЎР»СѓР¶Р±/РёРЅС‚РµРіСЂР°С†РёР№ СЃС‚РµРєР° РЅРµ РЅР°Р№РґРµРЅРѕ вЂ” С‡РёСЃС‚РёС‚СЊ РЅРµС‡РµРіРѕ."
  pause
}

# --- 23.4 РљРѕРЅС„РёРіРё Рё РєР°С‚Р°Р»РѕРіРё ------------------------------------------
rb_configs() {
  line; echo -e "${B}   РљРћРќР¤РР“Р Р РљРђРўРђР›РћР“Р РЎРўР•РљРђ${N}"; line
  local -a items=()
  local _l
  while IFS= read -r _l; do items+=("$_l"); done < <(rb_configs_list)

  local found=0 path desc typ exists go
  local item
  for item in "${items[@]}"; do
    IFS='|' read -r path desc typ <<<"$item"
    [[ -z "$path" ]] && continue
    exists=false
    case "$typ" in
      file|link) [[ -e "$path" ]] && exists=true ;;
      dir)       [[ -d "$path" ]] && exists=true ;;
    esac
    [[ "$exists" != true ]] && continue
    found=$((found+1))
    echo "  в”Ђ $path"
    echo "    $desc"
    askyn go "    РЈРґР°Р»РёС‚СЊ?" "n"
    if [[ "$go" == true ]]; then
      case "$typ" in
        dir) rm -rf "$path" ;;
        *)   rm -f "$path" ;;
      esac
      log "    СѓРґР°Р»РµРЅРѕ"; audit "rollback: СѓРґР°Р»РµРЅРѕ вЂ” $path"
    fi
  done

  # per-inbound decoy-РєР°С‚Р°Р»РѕРіРё
  local -a decoy_dirs=()
  local d
  for d in /var/www/decoy-*; do
    [[ -d "$d" ]] && decoy_dirs+=("$d")
  done
  for d in "${decoy_dirs[@]}"; do
    found=$((found+1))
    echo "  в”Ђ $d"
    echo "    decoy-Р·Р°РіР»СѓС€РєР° РёРЅР±Р°СѓРЅРґР°"
    askyn go "    РЈРґР°Р»РёС‚СЊ?" "n"
    if [[ "$go" == true ]]; then
      rm -rf "$d"; log "    СѓРґР°Р»РµРЅРѕ"; audit "rollback: СѓРґР°Р»РµРЅРѕ вЂ” $d"
    fi
  done

  [[ "$found" -eq 0 ]] && log "РљРѕРЅС„РёРіРѕРІ/РєР°С‚Р°Р»РѕРіРѕРІ СЃС‚РµРєР° РЅРµ РЅР°Р№РґРµРЅРѕ."
  nginx -t >/dev/null 2>&1 && nginx_reload >/dev/null 2>&1 || true
  pause
}

# --- 23.5 РЈРґР°Р»РµРЅРёРµ nginx ----------------------------------------------
rb_remove_nginx() {
  line; echo -e "${B}   РЈР”РђР›Р•РќРР• NGINX${N}"; line
  command -v nginx >/dev/null 2>&1 || { warn "nginx РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅ вЂ” РЅРµС‡РµРіРѕ СѓРґР°Р»СЏС‚СЊ"; pause; return 0; }
  echo "  ${R}Р’РќРРњРђРќРР•:${N} Р±РµР· nginx СЃС‚РµРє СЂР°Р±РѕС‚Р°С‚СЊ РќР• Р‘РЈР”Р•Рў РєР°Рє SNI-СЂРѕСѓС‚РµСЂ."
  echo "  вЂў РџР°РЅРµР»СЊ/РїРѕРґРїРёСЃРєРё/РёРЅР±Р°СѓРЅРґС‹ СЃРµР№С‡Р°СЃ РЅР° 127.0.0.1 вЂ” СЃС‚Р°РЅСѓС‚ РЅРµРґРѕСЃС‚СѓРїРЅС‹ СЃРЅР°СЂСѓР¶Рё,"
  echo "    РїРѕРєР° РЅРµ РѕС‚РєСЂРѕРµС€СЊ РёС… С‡РµСЂРµР· СЂР°Р·РґРµР» 5 в†’ В«РћС‚РєР°С‚ Рё РґРµРјРѕРЅС‚Р°Р¶ СЃС‚РµРєР°В» в†’ 1 (РћС‚РєСЂС‹С‚СЊ РїРѕСЂС‚С‹ РЅР°СЂСѓР¶Сѓ)."
  echo "  вЂў РЎРµСЂС‚С‹ РЅР° :443 РїРµСЂРµСЃС‚Р°РЅСѓС‚ РѕС‚РґР°РІР°С‚СЊСЃСЏ; decoy-СЃС‚СЂР°РЅРёС†С‹; DoH AdGuard."
  echo "  вЂў РљРѕРЅС„РёРіРё /etc/nginx Р±СѓРґСѓС‚ СѓРґР°Р»РµРЅС‹ РїР°РєРµС‚РѕРј (СЌС‚Рѕ Р¶Рµ РґРµР»Р°РµС‚ apt purge)."
  echo
  local go=""
  askyn go "РЈРґР°Р»РёС‚СЊ nginx (РїР°РєРµС‚ + РєРѕРЅС„РёРіРё + СЃРµСЂРІРёСЃ)?" "n"
  [[ "$go" == true ]] || { pause; return 0; }
  local sure=""
  ask sure "Р”Р»СЏ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РІРІРµРґРё YES" "" '^YES$'
  [[ "$sure" == "YES" ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; pause; return 0; }
  audit "rollback: СѓРґР°Р»РµРЅРёРµ nginx (purge)"
  systemctl stop nginx 2>/dev/null || true
  systemctl disable nginx 2>/dev/null || true
  DEBIAN_FRONTEND=noninteractive apt-get purge -y nginx nginx-common nginx-full libnginx-mod-stream >/dev/null 2>&1 || true
  apt-get autoremove -y >/dev/null 2>&1 || true
  rm -rf /etc/nginx /var/log/nginx 2>/dev/null || true
  log "nginx СѓРґР°Р»С‘РЅ (РїР°РєРµС‚ + /etc/nginx + /var/log/nginx)"
  pause
}

# --- 23.6 РџРѕР»РЅС‹Р№ РѕС‚РєР°С‚ (С‚РёС…Рѕ) -----------------------------------------
stack_preinstall_db() {
  local d=""
  while IFS= read -r d; do
    [[ -z "$d" ]] && continue
    [[ -f "$d/x-ui.db" ]] && { printf '%s\n' "$d/x-ui.db"; return 0; }
  done < <(ls -1dt "$BACKUP_DIR"/pre-install-* 2>/dev/null | grep -v '\.tar\.gz$' || true)
  return 1
}

# Р’РѕР·РІСЂР°С‚ РќРђРЎРўР РћР•Рљ РџРђРќР•Р›Р (settings) Рє Р·РЅР°С‡РµРЅРёСЏРј РёР· СЃРЅРёРјРєР° В«РґРѕ СЃРєСЂРёРїС‚Р°В».
# РўСЂРѕРіР°СЋС‚СЃСЏ С‚РѕР»СЊРєРѕ РєР»СЋС‡Рё web*/sub* вЂ” РёРЅР±Р°СѓРЅРґС‹, РїРѕР»СЊР·РѕРІР°С‚РµР»Рё Рё РїСЂРѕС‡РµРµ РЅРµ С‡РёС‚Р°СЋС‚СЃСЏ
# Рё РЅРµ РїРёС€СѓС‚СЃСЏ. РҐРѕСЃС‚ РЅРµ РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј (РјР°С€РёРЅР° С‚Р° Р¶Рµ, Р° С‡СѓР¶РёРµ webListen/webPort
# СЃР»РѕРјР°Р»Рё Р±С‹ РґРѕСЃС‚СѓРї Рє РїР°РЅРµР»Рё).
stack_restore_panel_from_snapshot() {
  local snap_db="$1" sdb="$2"
  [[ -z "$snap_db" || ! -f "$snap_db" ]] && { warn "РЎРЅРёРјРѕРє x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РЅРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"; return 1; }
  [[ -z "$sdb" || ! -f "$sdb" ]] && { warn "x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РЅРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"; return 1; }
  command -v python3 >/dev/null 2>&1 || { warn "python3 РЅРµРґРѕСЃС‚СѓРїРµРЅ вЂ” РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РЅРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"; return 1; }
  command -v "$DB_BIN" >/dev/null 2>&1 || { warn "sqlite3 РЅРµРґРѕСЃС‚СѓРїРµРЅ вЂ” РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РЅРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"; return 1; }
  local res="" res_file=""
  res_file=$(mktemp /tmp/stack-rst.XXXXXX 2>/dev/null) || return 1
  python3 - "$snap_db" "$sdb" > /dev/null 2> "$res_file" <<'PYRST2'
import os, sqlite3, sys
snap_path, live_path = sys.argv[1], sys.argv[2]
KEYS = ("webDomain", "webListen", "webPort", "webBasePath", "subDomain", "subListen",
        "subPort", "subPath", "subURI", "webCertFile", "webKeyFile",
        "subCertFile", "subKeyFile")
def read(path):
    con = sqlite3.connect("file:%s?mode=ro" % path, uri=True, timeout=5)
    rows = dict(con.execute("SELECT key, value FROM settings").fetchall())
    con.close()
    return rows
try:
    snap = read(snap_path)
except Exception:
    sys.exit(0)
try:
    con = sqlite3.connect(live_path, timeout=10)
    cur = con.cursor()
    cur.execute("PRAGMA busy_timeout=5000")
    cur.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
    # РќР°СЃС‚СЂРѕР№РєРё, Р·РЅР°С‡РµРЅРёРµ РєРѕС‚РѕСЂС‹С… вЂ” РїСѓС‚СЊ Рє РЎРЈР©Р•РЎРўР’РЈР®Р©Р•РњРЈ С„Р°Р№Р»Сѓ. Р•СЃР»Рё РІ СЃРЅРёРјРєРµ
    # РїСѓС‚СЊ РјС‘СЂС‚РІС‹Р№, Р° РІ РїР°РЅРµР»Рё СЃРµР№С‡Р°СЃ СЂР°Р±РѕС‡РёР№ СЃРµСЂС‚ вЂ” РѕСЃС‚Р°РІР»СЏРµРј СЂР°Р±РѕС‡РёР№: РёРЅР°С‡Рµ
    # РѕС‚РєР°С‚ СЃРЅРёРјР°РµС‚ HTTPS СЃ РїР°РЅРµР»Рё (В«РїР°РЅРµР»СЊ СЂР°Р±РѕС‚Р°РµС‚ РїРѕ РѕР±С‹С‡РЅРѕРјСѓ HTTPВ»).
    FILE_KEYS = ("webCertFile", "webKeyFile", "subCertFile", "subKeyFile")

    def alive(v):
        if not v or not str(v).startswith("/"):
            return False
        return os.path.isfile(str(v))

    cur_keys = dict(cur.execute("SELECT key, value FROM settings").fetchall())
    applied, kept = [], []
    for k in KEYS:
        if k not in snap:
            continue
        old = snap[k]
        now = cur_keys.get(k)
        if k in FILE_KEYS and not alive(old) and alive(now):
            kept.append(k)            # РЅРµ Р»РѕРјР°РµРј СЂР°Р±РѕС‚Р°СЋС‰РёР№ СЃРµСЂС‚ РїР°РЅРµР»Рё
            continue
        if now == old and k in cur_keys:
            continue
        if k in cur_keys:
            cur.execute("UPDATE settings SET value=? WHERE key=?", (old, k))
        else:
            cur.execute("INSERT INTO settings (key, value) VALUES (?, ?)", (k, old))
        applied.append(k)
    con.commit()
    con.close()
except Exception:
    sys.exit(1)
sys.stderr.write("RESTORED:%d:%s\nKEPT:%d:%s\n" % (
    len(applied), ",".join(applied) if applied else "-",
    len(kept), ",".join(kept) if kept else "-"))
PYRST2
  res=$(cat "$res_file" 2>/dev/null || true)
  rm -f "$res_file" 2>/dev/null || true
  [[ -z "$res" ]] && { warn "РЅРµ СѓРґР°Р»РѕСЃСЊ РїСЂРѕС‡РёС‚Р°С‚СЊ СЃРЅРёРјРѕРє вЂ” РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РЅРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅС‹"; return 1; }
  local rline="" kline=""
  rline=$(grep -m1 '^RESTORED:' <<<"$res" || true)
  kline=$(grep -m1 '^KEPT:' <<<"$res" || true)
  if [[ -n "$rline" ]]; then
    log "РќР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РёР· СЃРЅРёРјРєР°: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРѕ РїРѕР»РµР№ ${rline#RESTORED:} "
  else
    warn "РќР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё: СЃРЅРёРјРѕРє РїСЂРѕС‡РёС‚Р°РЅ, РЅРѕ РїСЂРёРјРµРЅСЏС‚СЊ Р±С‹Р»Рѕ РЅРµС‡РµРіРѕ"
  fi
  if [[ -n "$kline" ]]; then
    local kn="${kline#KEPT:}"
    if [[ "${kn%%:*}" != "0" ]]; then
      # СЃРµСЂС‚ РїР°РЅРµР»Рё РЅРµ С‚СЂРѕРЅСѓР»Рё: РІ СЃРЅРёРјРєРµ РїСѓС‚СЊ РјС‘СЂС‚РІС‹Р№, Р° РІ РїР°РЅРµР»Рё СЂР°Р±РѕС‡РёР№
      log "  СЃРѕС…СЂР°РЅС‘РЅ СЂР°Р±РѕС‡РёР№ СЃРµСЂС‚ РїР°РЅРµР»Рё (РІ СЃРЅРёРјРєРµ РїСѓС‚СЊ РЅРµСЂР°Р±РѕС‡РёР№): ${kn#*:}"
    fi
  fi
  return 0
}

# Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ SNI/target Reality РёР· СЃРЅРёРјРєР°, РЅРµ Р·Р°РјРµРЅСЏСЏ РІСЃСЋ СЃС‚СЂРѕРєСѓ inbound:
# РєР»РёРµРЅС‚С‹, UUID, РїРѕСЂС‚С‹ Рё РѕСЃС‚Р°Р»СЊРЅС‹Рµ РЅР°СЃС‚СЂРѕР№РєРё РѕСЃС‚Р°СЋС‚СЃСЏ РІ С‚РµРєСѓС‰РµР№ Р‘Р”.
stack_restore_reality_sni_from_snapshot() {
  local snap_db="$1" live_db="$2"
  [[ -f "$snap_db" && -f "$live_db" ]] || return 1
  python3 - "$snap_db" "$live_db" <<'PYREALITY'
import json, sqlite3, sys
snap_path, live_path = sys.argv[1:]
def rows(path):
    con=sqlite3.connect('file:%s?mode=ro' % path, uri=True, timeout=10)
    out={r[0]: (r[1], r[2], r[3]) for r in con.execute(
        "SELECT id, protocol, port, stream_settings FROM inbounds")}
    con.close(); return out
try:
    old=rows(snap_path)
    con=sqlite3.connect(live_path, timeout=10); con.execute('PRAGMA busy_timeout=5000')
    changed=0
    for iid, (op, oport, os) in old.items():
        if not os: continue
        try: oj=json.loads(os)
        except Exception: continue
        ors=oj.get('realitySettings')
        if not isinstance(ors, dict): continue
        cur=con.execute('SELECT protocol, stream_settings FROM inbounds WHERE id=?', (iid,)).fetchone()
        if not cur: continue
        try: cj=json.loads(cur[1] or '')
        except Exception: continue
        crs=cj.get('realitySettings')
        if not isinstance(crs, dict): continue
        copied=False
        for key in ('target','dest','serverNames'):
            if key in ors and ors[key] != crs.get(key):
                crs[key]=ors[key]; copied=True
        if copied:
            cj['realitySettings']=crs
        # CDN-РїСЂРѕС„РёР»СЊ XHTTP+TLS РјРµРЅСЏРµС‚ origin SNI, host Рё path. Р’РѕР·РІСЂР°С‰Р°РµРј
        # С‚РѕР»СЊРєРѕ transport-РѕР±СЉРµРєС‚С‹ РёР· snapshot, РЅРµ Р·Р°РјРµРЅСЏСЏ inbound С†РµР»РёРєРѕРј.
        if (oj.get('network') == 'xhttp' and oj.get('security') == 'tls'):
            for key in ('tlsSettings','xhttpSettings'):
                if key in oj:
                    if cj.get(key) != oj[key]: copied=True
                    cj[key]=oj[key]
        if copied:
            con.execute('UPDATE inbounds SET stream_settings=? WHERE id=?',
                        (json.dumps(cj, ensure_ascii=False, separators=(',',':')), iid))
            changed += 1
    con.commit(); con.close()
    print('REALITY_RESTORED:%d' % changed)
except Exception:
    sys.exit(1)
PYREALITY
}

stack_restore_hosts_from_snapshot() {
  local snap_db="$1" live_db="$2"
  [[ -f "$snap_db" && -f "$live_db" ]] || return 1
  python3 - "$snap_db" "$live_db" <<'PYHOSTS'
import sqlite3, sys
snap_path, live_path = sys.argv[1:]
try:
    so=sqlite3.connect('file:%s?mode=ro' % snap_path, uri=True, timeout=10)
    lo=sqlite3.connect(live_path, timeout=10); lo.execute('PRAGMA busy_timeout=5000')
    st=so.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='hosts'").fetchone()
    lt=lo.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='hosts'").fetchone()
    if not st or not lt: raise SystemExit(0)
    sc=[r[1] for r in so.execute('PRAGMA table_info(hosts)')]
    lc=[r[1] for r in lo.execute('PRAGMA table_info(hosts)')]
    cols=[c for c in sc if c in lc and c != 'id']
    if not cols: raise SystemExit(0)
    q=','.join('"%s"'%c.replace('"','""') for c in cols)
    n=0
    # Р•СЃР»Рё СЃРєСЂРёРїС‚ РјРµРЅСЏР» SNI, С‚РµРєСѓС‰Р°СЏ hosts-СЃС‚СЂРѕРєР° СѓР¶Рµ СЃСѓС‰РµСЃС‚РІСѓРµС‚, РїРѕСЌС‚РѕРјСѓ
    # INSERT OR IGNORE РЅРµРґРѕСЃС‚Р°С‚РѕС‡РµРЅ. РЈРґР°Р»СЏРµРј С‚РѕР»СЊРєРѕ СЃС‚СЂРѕРєРё, РѕС‚РјРµС‡РµРЅРЅС‹Рµ РЅР°С€РёРј
    # СЂРµРµСЃС‚СЂРѕРј РІР»Р°РґРµРЅРёСЏ, Р·Р°С‚РµРј РІСЃС‚Р°РІР»СЏРµРј snapshot-Р·РЅР°С‡РµРЅРёРµ (РЅР°РїСЂРёРјРµСЂ google.com).
    owned = lo.execute("SELECT inbound_id,port,address,sni FROM sm_hosts_owned").fetchall() if lo.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='sm_hosts_owned'").fetchone() else []
    # Р’ СЃС‚Р°СЂС‹С… РІРµСЂСЃРёСЏС… СЂРµРµСЃС‚СЂ РјРѕРі Р±С‹С‚СЊ РїСѓСЃС‚С‹Рј. Р’РѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ hosts РґРѕР»Р¶РЅРѕ
    # РІСЃС‘ СЂР°РІРЅРѕ Р·Р°РјРµРЅРёС‚СЊ С‚РµРєСѓС‰СѓСЋ СЃС‚СЂРѕРєСѓ РґР»СЏ inbound, РµСЃР»Рё РІ snapshot РµСЃС‚СЊ
    # РёСЃС…РѕРґРЅР°СЏ СЃС‚СЂРѕРєР°; СЂСѓС‡РЅС‹Рµ hosts РѕСЃС‚Р°Р»СЊРЅС‹С… inbound РЅРµ Р·Р°С‚СЂР°РіРёРІР°РµРј.
    snap_keys = {(int(r[0]), int(r[2])) for r in so.execute('SELECT inbound_id, address, port FROM hosts')}
    owned_keys = {(int(a), int(b)) for a,b,_,_ in owned}
    for iid, port, addr, sni in owned:
        lo.execute("DELETE FROM hosts WHERE inbound_id=? AND port=? AND COALESCE(address,'')=? AND COALESCE(sni,'')=?", (iid,port,addr,sni))
    for iid, port in (snap_keys - owned_keys):
        lo.execute("DELETE FROM hosts WHERE inbound_id=? AND port=?", (iid,port))
    for row in so.execute('SELECT %s FROM hosts' % q):
        marks=','.join('?' for _ in cols)
        try:
            cur=lo.execute('INSERT OR IGNORE INTO hosts (%s) VALUES (%s)'%(q,marks), row)
            n += cur.rowcount if cur.rowcount > 0 else 0
        except Exception: pass
    # Р РµРµСЃС‚СЂ РґРѕР»Р¶РµРЅ СѓРєР°Р·С‹РІР°С‚СЊ СѓР¶Рµ РЅР° РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Р№ SNI, РёРЅР°С‡Рµ СЃР»РµРґСѓСЋС‰РёР№
    # РѕС‚РєР°С‚/СЃРјРµРЅР° decoy РЅРµ РЅР°Р№РґС‘С‚ СЃС‚СЂРѕРєСѓ google.com.
    if owned and all(x in cols for x in ('inbound_id','port','address','sni')):
        keys={(int(a),int(b)) for a,b,_,_ in owned}
        lo.execute('DELETE FROM sm_hosts_owned')
        for row in so.execute('SELECT %s FROM hosts' % q):
            d=dict(zip(cols,row)); k=(int(d['inbound_id']),int(d['port']))
            if k in keys:
                lo.execute('INSERT OR IGNORE INTO sm_hosts_owned(inbound_id,port,address,sni) VALUES(?,?,?,?)', (k[0],k[1],d.get('address') or '',d.get('sni') or ''))
    lo.commit(); so.close(); lo.close(); print('HOSTS_RESTORED:%d'%n)
except SystemExit: pass
except Exception: sys.exit(1)
PYHOSTS
}

# РЎРЅСЏС‚СЊ В«СЃРѕСЃС‚РѕСЏРЅРёРµ СЃС‚РµРєР°В»: РјР°СЂРєРµСЂС‹, С„Р»Р°РіРё, С‚СЂРёРіРіРµСЂС‹ Р·Р°С‰РёС‚С‹ Р‘Р”, Р¶СѓСЂРЅР°Р»С‹.
#   $1 = prompt вЂ” СЃРїСЂР°С€РёРІР°С‚СЊ РїРѕ РіСЂСѓРїРїР°Рј СЃ РЅРµРѕР±СЂР°С‚РёРјС‹РјРё РґР°РЅРЅС‹РјРё (1) РёР»Рё С‚РёС…Рѕ (0)
# РЎРµСЂС‚РёС„РёРєР°С‚С‹ Let's Encrypt Рё AdGuard Home РќР• С‚СЂРѕРіР°СЋС‚СЃСЏ вЂ” СЌС‚Рѕ Рё СЂР°РЅСЊС€Рµ Р±С‹Р»Рѕ СЏРІРЅРѕ.
rb_wipe_stack_state() {
  local prompt="${1:-0}" go="" n=0
  # 1) Р¶СѓСЂРЅР°Р» РёР·РјРµРЅРµРЅРёР№: РІРµСЂРЅСѓС‚СЊ С‚Рѕ, С‡С‚Рѕ СЃРєСЂРёРїС‚ РїСЂР°РІРёР» РІ РїР°РЅРµР»Рё (Рї.2/Рї.3)
  if panel_journal_started; then
    log "Р’РѕР·РІСЂР°С‚ РЅР°СЃС‚СЂРѕРµРє РїР°РЅРµР»Рё РїРѕ Р¶СѓСЂРЅР°Р»Сѓ РёР·РјРµРЅРµРЅРёР№ (Рї.2/Рї.3)вЂ¦"
    panel_journal_apply 1 || warn "  Р¶СѓСЂРЅР°Р» РїСЂРёРјРµРЅС‘РЅ С‡Р°СЃС‚РёС‡РЅРѕ (С„Р°Р№Р»С‹ СЃРјРѕС‚СЂРё РІ $BACKUP_DIR)"
  fi
  panel_journal_clear

  # 2) С‚РѕС‡РєР° РѕС‚СЃС‡С‘С‚Р° В«РїРµСЂРІРѕРіРѕ Р·Р°РїСѓСЃРєР°В»: Р±РµР· РЅРµС‘ СЃРєСЂРёРїС‚ СЃС‡РёС‚Р°РµС‚ СЃС‚РµРє СЃРѕР±СЂР°РЅРЅС‹Рј (Рї.1)
  local -a wipe=(
    "$BACKUP_DIR/.pre-install-done"
    "$BACKUP_DIR/.stack-ever-ran"
    /root/stack-frozen.txt
    "$CERT_MODE_FILE"
    "$CERT_LINES_FILE"
    "$WILDCARD_STATE"
    /root/panel-credentials.txt
    /root/adguard-credentials.txt
    /root/.stack-src
  )
  local f
  for f in "${wipe[@]}"; do
    rm -f "$f" 2>/dev/null && { n=$((n+1)); log "  СЃРЅСЏС‚Рѕ: $f"; }
  done
  rm -f "$CERT_LINE_FILE_PREFIX"*.domains 2>/dev/null || true

  # Р¤Р°Р№Р»С‹ Р»РёРЅРёР№ СЃРµСЂС‚РѕРІ: СѓРґР°Р»СЏРµРј РїРѕ РїСЂРµС„РёРєСЃСѓ, С‚.Рє. РёРјРµРЅР° Р»РёРЅРёР№ Р·Р°СЂР°РЅРµРµ РЅРµРёР·РІРµСЃС‚РЅС‹
  rm -f "$CERT_LINE_FILE_PREFIX"*.domains 2>/dev/null || true
  # РўСЂРёРіРіРµСЂС‹, РєРѕС‚РѕСЂС‹Рµ СЃС‚Р°РІРёС‚ ensure_shareonly_triggers: РїРµСЂРµСЃРѕР·РґР°СЋС‚СЃСЏ РїСЂРё
  # СЃР»РµРґСѓСЋС‰РµР№ СѓСЃС‚Р°РЅРѕРІРєРµ, Р·Р°С‚Рѕ РЅРѕРІР°СЏ СѓСЃС‚Р°РЅРѕРІРєР° РЅРµ РїРѕР»СѓС‡РёС‚ В«РЈР–Р• РЎРЈР©Р•РЎРўР’РЈР•РўВ»
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local _tg=""
    while IFS= read -r _tg; do
      [[ -n "$_tg" ]] && sqlite3 "$XUI_DB" "DROP TRIGGER IF EXISTS \"$_tg\";" 2>/dev/null || true
    done < <(sqlite3 "$XUI_DB" "SELECT name FROM sqlite_master WHERE type='trigger' AND name LIKE 'lucx_shareonly%';" 2>/dev/null || true)
  fi

  # 4) РєРѕРЅС„РёРіРё Рё РґР°РЅРЅС‹Рµ РїСЂРµР¶РЅРµР№ СѓСЃС‚Р°РЅРѕРІРєРё (С‚РѕР»СЊРєРѕ СЃРІРѕС‘)
  local -a data=(
    /etc/fail2ban/jail.d/decoy-login.local
    /etc/fail2ban/filter.d/decoy-login.conf
    /etc/logrotate.d/stack-decoy
  )
  [[ -n "${DECOY_LOG_ACCESS:-}" ]] && data+=("$DECOY_LOG_ACCESS")
  for f in "${data[@]}"; do
    rm -f "$f" 2>/dev/null || true
  done
  [[ -n "${DECOY_LOGIN_DIR:-}" && "$DECOY_LOGIN_DIR" == /var/www/* ]] && rm -rf "$DECOY_LOGIN_DIR" 2>/dev/null || true
  rm -rf /var/www/decoy-[0-9]* 2>/dev/null || true

  # 5) РґР°РЅРЅС‹Рµ, РєРѕС‚РѕСЂС‹Рµ РјРѕРі РїСЂР°РІРёС‚СЊ РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ вЂ” СЃРїСЂР°С€РёРІР°РµРј РѕС‚РґРµР»СЊРЅРѕ
  local cert_domains="/etc/letsencrypt/stack-domains.txt"
  if [[ -f "$cert_domains" ]]; then
    if [[ "$prompt" == "1" && -t 0 ]]; then
      askyn go "РЎРїРёСЃРєРё РґРѕРјРµРЅРѕРІ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ ($cert_domains Рё cert-lines*.domains) С‚РѕР¶Рµ СЃРЅСЏС‚СЊ?" "n"
    else
      go=false
    fi
    if [[ "$go" == true ]]; then
      rm -f "$cert_domains" 2>/dev/null || true
      log "  СЃРЅСЏС‚Рѕ: $cert_domains"
    else
      warn "  РѕСЃС‚Р°РІР»РµРЅРѕ: $cert_domains (СЃРїРёСЃРѕРє РґРѕРјРµРЅРѕРІ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ)"
    fi
  fi
  if [[ -d /root/stack-backups ]]; then
    local old_ans
    old_ans=$(find /root/stack-backups -maxdepth 1 -name 'ans-auto-*.txt' 2>/dev/null | wc -l)
    if [[ "${old_ans:-0}" -gt 0 ]]; then
      if [[ "$prompt" == "1" && -t 0 ]]; then
        askyn go "РЈРґР°Р»РёС‚СЊ СЃРѕС…СЂР°РЅС‘РЅРЅС‹Рµ С„Р°Р№Р»С‹ Р°РІС‚РѕРѕС‚РІРµС‚РѕРІ СѓСЃС‚Р°РЅРѕРІРєРё ($old_ans С€С‚.)?" "y"
      else
        go=true
      fi
      [[ "$go" == true ]] && rm -f /root/stack-backups/ans-auto-*.txt 2>/dev/null || true
    fi
  fi
  rm -f /root/ans-auto-*.txt 2>/dev/null || true
  log "РЎРѕСЃС‚РѕСЏРЅРёРµ СЃС‚РµРєР° СЃРЅСЏС‚Рѕ (С„Р°Р№Р»РѕРІ Рё Р·Р°РїРёСЃРµР№: $n + Р¶СѓСЂРЅР°Р»)"
  return 0
}

# РџРѕР»РЅС‹Р№ СЃР±СЂРѕСЃ В«СЃРѕСЃС‚РѕСЏРЅРёСЏ СЃС‚РµРєР°В» + РІРѕР·РІСЂР°С‚ РЅР°СЃС‚СЂРѕРµРє РїР°РЅРµР»Рё РёР· СЃРЅРёРјРєР°.
# $1 = 1 вЂ” СЃРїСЂР°С€РёРІР°С‚СЊ РїРѕ РіСЂСѓРїРїР°Рј (СЂСѓС‡РЅРѕР№ РїСѓРЅРєС‚ РјРµРЅСЋ), 0 вЂ” С‚РёС…Рѕ (РїРѕР»РЅС‹Р№ РѕС‚РєР°С‚)
stack_reset_state() {
  local prompt="${1:-1}"
  local snap_db="" sdb=""
  snap_db=$(stack_preinstall_db 2>/dev/null || true)
  sdb="${XUI_DB:-}"
  [[ -f "$sdb" ]] || sdb="/etc/x-ui/x-ui.db"
  if [[ -z "$snap_db" ]]; then
    warn "РЎРЅРёРјРѕРє В«РґРѕ СЃРєСЂРёРїС‚Р°В» РЅРµ РЅР°Р№РґРµРЅ:"
    warn "  вЂў В«РїРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° СѓР¶Рµ РІС‹РїРѕР»РЅРµРЅР°В» Р±РѕР»СЊС€Рµ РЅРµ РїРѕСЏРІРёС‚СЃСЏ, РјР°СЂРєРµСЂС‹ СЃРЅСЏС‚С‹;"
    warn "  вЂў РЅРѕ РёСЃС…РѕРґРЅС‹Рµ РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё (РґРѕРјРµРЅ, РїРѕСЂС‚С‹, РїСѓС‚Рё) РІРµСЂРЅСѓС‚СЊ РЅРµ РёР· С‡РµРіРѕ вЂ”"
    warn "    Р·Р°РґР°Р№С‚Рµ РёС… РІ Рї.1 РёР»Рё РІРѕСЃСЃС‚Р°РЅРѕРІРёС‚Рµ СЃРЅРёРјРѕРє РІСЂСѓС‡РЅСѓСЋ С‡РµСЂРµР· СЂР°Р·РґРµР» 5 в†’ Pre-install snapshot."
  fi
  local xui_was=""
  if systemctl is-active --quiet x-ui 2>/dev/null; then
    xui_was=1; stop_xui_for_edit
  fi
  # 1) РјР°СЂРєРµСЂС‹, С„Р»Р°РіРё, Р¶СѓСЂРЅР°Р» РёР·РјРµРЅРµРЅРёР№ Рё РґР°РЅРЅС‹Рµ РїСЂРµР¶РЅРµР№ СѓСЃС‚Р°РЅРѕРІРєРё
  rb_wipe_stack_state "$prompt"
  # 2) РёСЃС…РѕРґРЅС‹Рµ РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РёР· СЃРЅРёРјРєР° В«РґРѕ СЃРєСЂРёРїС‚Р°В»
  if [[ -n "$snap_db" ]]; then
    stack_restore_panel_from_snapshot "$snap_db" "$sdb"
    local _rr=""
    _rr=$(stack_restore_reality_sni_from_snapshot "$snap_db" "$sdb" 2>/dev/null || true)
    [[ -n "$_rr" ]] && log "  $_rr (SNI/target Reality РёР· backup)"
    local _rh=""
    _rh=$(stack_restore_hosts_from_snapshot "$snap_db" "$sdb" 2>/dev/null || true)
    [[ -n "$_rh" ]] && log "  $_rh (hosts РёР· backup)"
  fi
  if [[ -n "$xui_was" ]]; then
    # РџРѕСЃР»Рµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ Р‘Р” panel/xray РјРѕР¶РµС‚ РґРµСЂР¶Р°С‚СЊ СЃС‚Р°СЂСѓСЋ РєРѕРЅС„РёРіСѓСЂР°С†РёСЋ
    # Reality РІ РїР°РјСЏС‚Рё; РёРјРµРЅРЅРѕ РїРѕСЌС‚РѕРјСѓ СЂСѓС‡РЅРѕРµ РІРєР»/РІС‹РєР» РёРЅР±Р°СѓРЅРґР° В«Р»РµС‡РёС‚В» РµРіРѕ.
    systemctl restart x-ui >/dev/null 2>&1 || systemctl start x-ui >/dev/null 2>&1 || true
    sleep 3
  fi
  return 0
}

# --- 23.0 РЎРЅСЏС‚СЊ СЃРѕСЃС‚РѕСЏРЅРёРµ СЃС‚РµРєР° (Рї.1/Рї.2/Рї.3 РѕС‚РєР°С‚Р°, РѕС‚РґРµР»СЊРЅС‹Рј РїСѓРЅРєС‚РѕРј) --
rb_reset_state_menu() {
  line; echo -e "${B}   РЎРќРЇРўР¬ РЎРћРЎРўРћРЇРќРР• РЎРўР•РљРђ${N}"; line
  echo "  Р’РѕР·РІСЂР°С‰Р°РµС‚ РїР°РЅРµР»СЊ Рё СЃРёСЃС‚РµРјСѓ Рє СЃРѕСЃС‚РѕСЏРЅРёСЋ В«СЃРєСЂРёРїС‚ РµС‰С‘ РЅРµ Р·Р°РїСѓСЃРєР°Р»СЃСЏВ»:"
  echo "    вЂў listen РёРЅР±Р°СѓРЅРґРѕРІ вЂ” РєР°Рє Р±С‹Р»Рѕ РґРѕ РїСЂР°РІРѕРє СЃРєСЂРёРїС‚Р° (С‚РѕР»СЊРєРѕ С‚Рѕ, С‡С‚Рѕ РѕРЅ РјРµРЅСЏР»)"
  echo "    вЂў РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё (РґРѕРјРµРЅ, РїРѕСЂС‚С‹, РїСѓС‚Рё, СЃРµСЂС‚С‹ РїР°РЅРµР»Рё) вЂ” РёР· СЃРЅРёРјРєР° В«РґРѕ СЃРєСЂРёРїС‚Р°В»"
  echo "    вЂў РјР°СЂРєРµСЂС‹ СЃС‚РµРєР°: .pre-install-done, Р·Р°РјРѕСЂРѕР·РєР°, СЂРµР¶РёРј/Р»РёРЅРёРё СЃРµСЂС‚РѕРІ,"
  echo "      wildcard-С„Р»Р°Рі, РєСЂРµРґС‹ РїР°РЅРµР»Рё Рё AdGuard, URL СЃР°РјРѕРѕР±РЅРѕРІР»РµРЅРёСЏ"
  echo "    вЂў С‚СЂРёРіРіРµСЂС‹ Р·Р°С‰РёС‚С‹ Р‘Р” Рё СЃР»СѓР¶РµР±РЅС‹Рµ С‚Р°Р±Р»РёС†С‹ (hosts_shadow, sm_pending)"
  echo "    вЂў jail/filter decoy-login, decoy-Р»РѕРіРё, login-С€Р°Р±Р»РѕРЅС‹"
  echo
  echo -e "  ${G}РќР• С‚СЂРѕРіР°РµС‚СЃСЏ:${N} РёРЅР±Р°СѓРЅРґС‹ Рё РєР»РёРµРЅС‚С‹ РїР°РЅРµР»Рё, AdGuard Home,"
  echo "  СЃРµСЂС‚С‹ Let's Encrypt, СЃРЅРёРјРєРё РІ /root/stack-backups/pre-install-*."
  echo "  РљРѕРЅС„РёРіРё nginx (stack.conf, sni-router.conf) СЃРЅРёРјР°СЋС‚СЃСЏ РїСѓРЅРєС‚Р°РјРё 4вЂ“5."
  echo
  local snap_db=""
  snap_db=$(stack_preinstall_db 2>/dev/null || true)
  if [[ -n "$snap_db" ]]; then
    log "РЎРЅРёРјРѕРє В«РґРѕ СЃРєСЂРёРїС‚Р°В»: $snap_db"
  else
    warn "РЎРЅРёРјРѕРє В«РґРѕ СЃРєСЂРёРїС‚Р°В» РЅРµ РЅР°Р№РґРµРЅ вЂ” РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё РІРµСЂРЅСѓС‚СЊ РЅРµ РёР· С‡РµРіРѕ."
  fi
  local go=""
  askyn go "Р’С‹РїРѕР»РЅРёС‚СЊ?" "n"
  [[ "$go" == true ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; pause; return 0; }
  audit "rollback: СЃРЅСЏС‚РёРµ СЃРѕСЃС‚РѕСЏРЅРёСЏ СЃС‚РµРєР°"
  systemctl stop x-ui 2>/dev/null || true
  stack_reset_state 1
  systemctl start x-ui 2>/dev/null || true
  log "Р“РѕС‚РѕРІРѕ. РџР°РЅРµР»СЊ: РЅР°СЃС‚СЂРѕР№РєРё Рё listen РІРѕР·РІСЂР°С‰РµРЅС‹, РјР°СЂРєРµСЂС‹ СЃС‚РµРєР° СЃРЅСЏС‚С‹."
  log "  РџСЂРѕРІРµСЂРёС‚СЊ: Рї.1 РЅРµ РґРѕР»Р¶РµРЅ РїРёСЃР°С‚СЊ В«РїРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° СѓР¶Рµ РІС‹РїРѕР»РЅРµРЅР°В»."
  pause
}

rb_full_rollback() {
  line; echo -e "${R}   РџРћР›РќР«Р™ РћРўРљРђРў РЎРўР•РљРђ${N}"; line
  echo "  Р‘СѓРґРµС‚ РІС‹РїРѕР»РЅРµРЅРѕ (Р±РµР· РІРѕРїСЂРѕСЃРѕРІ, РїРѕ С€Р°РіР°Рј):"
  echo "    1) Р‘СЌРєР°Рї x-ui.db Рё nginx-РєРѕРЅС„РёРіРѕРІ СЃС‚РµРєР°"
  echo "    2) РЈРґР°Р»РµРЅРёРµ СЃР»СѓР¶Р± Рё РёРЅС‚РµРіСЂР°С†РёР№ (stack-heal, decoy-login jail, certbot hook)"
  echo "    3) РЈРґР°Р»РµРЅРёРµ РєРѕРЅС„РёРіРѕРІ Рё РєР°С‚Р°Р»РѕРіРѕРІ СЃС‚РµРєР°"
  echo "    4) РџРѕР»РЅРѕРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ x-ui.db РёР· pre-install СЃРЅРёРјРєР°"
  echo "       Reality, CDN/XHTTP, hosts, SNI-РїРѕР»СЏ, РёРЅР±Р°СѓРЅРґС‹ Рё РєР»РёРµРЅС‚С‹ вЂ” РєР°Рє РґРѕ СЃРєСЂРёРїС‚Р°"
  echo "    5) РЈРґР°Р»РµРЅРёРµ СЃР»СѓР¶РµР±РЅС‹С… РјР°СЂРєРµСЂРѕРІ СЃС‚РµРєР° Рё РёРЅС‚РµРіСЂР°С†РёР№"
  echo "    6) UFW: РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ РёР· СЃРЅРёРјРєР° (РµСЃР»Рё РµСЃС‚СЊ), РёРЅР°С‡Рµ reset + РѕС‚РєСЂС‹С‚РёРµ СЃР»СѓС€Р°СЋС‰РµРіРѕСЃСЏ"
  echo "    7) РЈРґР°Р»РµРЅРёРµ nginx (РїР°РєРµС‚ + РєРѕРЅС„РёРіРё)"
  echo
  echo -e "  ${G}РќР• С‚СЂРѕРіР°РµС‚СЃСЏ:${N} AdGuard Home Рё СЃРµСЂС‚С‹ Let's Encrypt РІ /etc/letsencrypt/live/."
  echo "  ${Y}Р’РќРРњРђРќРР•:${N} С‚РµРєСѓС‰РёРµ РёРЅР±Р°СѓРЅРґС‹, РєР»РёРµРЅС‚С‹ Рё РёР·РјРµРЅРµРЅРёСЏ РїР°РЅРµР»Рё РїРѕСЃР»Рµ pre-install СЃРЅРёРјРєР° Р±СѓРґСѓС‚ Р·Р°РјРµРЅРµРЅС‹ СЃРѕСЃС‚РѕСЏРЅРёРµРј РёР· СЃРЅРёРјРєР°."
  echo
  local sure=""
  ask sure "Р”Р»СЏ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РІРІРµРґРё YES" "" '^YES$'
  [[ "$sure" == "YES" ]] || { log "РћС‚РјРµРЅРµРЅРѕ"; pause; return 0; }
  audit "rollback: РџРћР›РќР«Р™ РћРўРљРђРў РЎРўР•РљРђ (silent)"

  log "[1/7] Р‘СЌРєР°РївЂ¦"
  auto_backup_stack >/dev/null 2>&1 || true

  log "[2/7] РЎР»СѓР¶Р±С‹ Рё РёРЅС‚РµРіСЂР°С†РёРёвЂ¦"
  uninstall_heal_timer >/dev/null 2>&1 || true
  rm -f /etc/fail2ban/jail.d/decoy-login.local /etc/fail2ban/filter.d/decoy-login.conf 2>/dev/null || true
  rm -f /etc/letsencrypt/renewal-hooks/deploy/stack-cert-mirror.sh 2>/dev/null || true
  systemctl restart fail2ban >/dev/null 2>&1 || true

  log "[3/7] РљРѕРЅС„РёРіРё Рё РєР°С‚Р°Р»РѕРіРё СЃС‚РµРєР°вЂ¦"
  rm -f /etc/nginx/sites-enabled/stack.conf /etc/nginx/sites-available/stack.conf 2>/dev/null || true
  rm -f /etc/nginx/streams-enabled/sni-router.conf /etc/nginx/streams-available/sni-router.conf 2>/dev/null || true
  rm -f /etc/nginx/snippets/decoy-headers.conf /etc/logrotate.d/stack-decoy 2>/dev/null || true
  rm -rf /var/www/panel-decoy /var/www/decoy-templates /var/www/decoy-login 2>/dev/null || true
  rm -rf /var/www/decoy-[0-9]* /var/www/decoy-login 2>/dev/null || true

  log "[4/7] РџРѕР»РЅРѕРµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёРµ x-ui.db РёР· pre-install snapshotвЂ¦"
  # Р’ СЂРµР¶РёРјРµ В«РїРѕР»РЅС‹Р№ РѕС‚РєР°С‚В» РІРѕР·РІСЂР°С‰Р°РµРј Р‘Р” С†РµР»РёРєРѕРј. Р­С‚Рѕ РіР°СЂР°РЅС‚РёСЂСѓРµС‚ РІРѕР·РІСЂР°С‚
  # Reality, CDN/XHTTP, hosts, SNI-РїРѕР»РµР№, РєР»РёРµРЅС‚РѕРІ Рё РЅР°СЃС‚СЂРѕРµРє СЂРѕРІРЅРѕ Рє РјРѕРјРµРЅС‚Сѓ
  # РґРѕ РІРјРµС€Р°С‚РµР»СЊСЃС‚РІР° СЃРєСЂРёРїС‚Р°. РџРµСЂРµРґ Р·Р°РјРµРЅРѕР№ Р°РєС‚СѓР°Р»СЊРЅР°СЏ Р‘Р” СѓР¶Рµ СЃРѕС…СЂР°РЅРµРЅР° С‡РµСЂРµР·
  # auto_backup_stack РЅР° С€Р°РіРµ [1/7].
  systemctl stop x-ui 2>/dev/null || true
  local _full_snap="" _db_restored=false
  _full_snap=$(stack_preinstall_db 2>/dev/null || true)
  if [[ -n "$_full_snap" && -f "$_full_snap" && -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    sqlite3 "$XUI_DB" "PRAGMA wal_checkpoint(TRUNCATE);" >/dev/null 2>&1 || true
    cp -a "$XUI_DB" "${XUI_DB}.pre-full-rollback-$(date +%Y%m%d-%H%M%S)" 2>/dev/null || true
    rm -f "${XUI_DB}-wal" "${XUI_DB}-shm" 2>/dev/null || true
    if cp -a "$_full_snap" "$XUI_DB" 2>/dev/null; then
      _db_restored=true
      log "  x-ui.db РїРѕР»РЅРѕСЃС‚СЊСЋ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅ: $_full_snap"
    else
      warn "  РЅРµ СѓРґР°Р»РѕСЃСЊ Р·Р°РјРµРЅРёС‚СЊ x-ui.db вЂ” РїСЂРёРјРµРЅСЏСЋ Р±РµР·РѕРїР°СЃРЅС‹Р№ РІС‹Р±РѕСЂРѕС‡РЅС‹Р№ РѕС‚РєР°С‚"
    fi
  else
    warn "  pre-install x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” РїСЂРёРјРµРЅСЏСЋ Р±РµР·РѕРїР°СЃРЅС‹Р№ РІС‹Р±РѕСЂРѕС‡РЅС‹Р№ РѕС‚РєР°С‚"
  fi
  if [[ "$_db_restored" != true ]]; then
    stack_reset_state 0 || warn "  РІС‹Р±РѕСЂРѕС‡РЅС‹Р№ РѕС‚РєР°С‚ РІС‹РїРѕР»РЅРµРЅ С‡Р°СЃС‚РёС‡РЅРѕ"
  else
    # РЎРЅРёРјР°РµРј СЃР»СѓР¶РµР±РЅС‹Рµ РјР°СЂРєРµСЂС‹/РёРЅС‚РµРіСЂР°С†РёРё, РЅРѕ РЅРµ РјРµРЅСЏРµРј РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРЅСѓСЋ Р‘Р”.
    rb_wipe_stack_state 0 || warn "  СЃР»СѓР¶РµР±РЅРѕРµ СЃРѕСЃС‚РѕСЏРЅРёРµ СЃС‚РµРєР° СЃРЅСЏС‚Рѕ С‡Р°СЃС‚РёС‡РЅРѕ"
  fi
  log "[5/7] РћС‚РєСЂС‹С‚РёРµ РїРѕСЂС‚РѕРІ РЅР°СЂСѓР¶Сѓ (Р·РЅР°С‡РµРЅРёРµ РёР· РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРЅРѕР№ РїР°РЅРµР»Рё)вЂ¦"
  if [[ "$_db_restored" != true ]]; then
    xui_set_setting webListen ''
    xui_set_setting subListen ''
    local _lid
    while IFS= read -r _lid; do
      [[ -n "$_lid" ]] && db_set_listen "$_lid" '' direct
    done < <(sqlite3 -cmd ".timeout 3000" "$XUI_DB" \
             "SELECT id FROM inbounds WHERE COALESCE(listen,'') IN ('127.0.0.1','::1');" 2>/dev/null || true)
  fi
  systemctl start x-ui 2>/dev/null || true

  log "[6/7] UFWвЂ¦"
  # РІ РїРѕР»РЅРѕРј РѕС‚РєР°С‚Рµ РґРµР№СЃС‚РІСѓРµРј С‚РёС…Рѕ: РµСЃР»Рё СЃРЅРёРјРѕРє РµСЃС‚СЊ вЂ” РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј РµРіРѕ Р»РѕРіРёРєСѓ
  # Р±РµР· РёРЅС‚РµСЂР°РєС‚РёРІРЅРѕРіРѕ Р·Р°РїСЂРѕСЃР° (restore_firewall_state СЃРїСЂР°С€РёРІР°РµС‚ вЂ” РѕР±С…РѕРґРёРј)
  if [[ -f "$FW_STATE_DIR/saved" ]]; then
    . "$FW_STATE_DIR/state" 2>/dev/null || true
    [[ -f "$FW_STATE_DIR/iptables.v4" ]] && iptables-restore  < "$FW_STATE_DIR/iptables.v4"  2>/dev/null || true
    [[ -f "$FW_STATE_DIR/iptables.v6" ]] && ip6tables-restore < "$FW_STATE_DIR/iptables.v6"  2>/dev/null || true
    if [[ "${UFW_WAS_INSTALLED:-0}" == "1" && -f "$FW_STATE_DIR/ufw-config.tar" ]]; then
      tar -xpf "$FW_STATE_DIR/ufw-config.tar" -C / 2>/dev/null || true
      if [[ "${UFW_WAS_ACTIVE:-0}" == "1" ]]; then
        ufw --force enable >/dev/null 2>&1 || warn "пїЅпїЅ пїЅпїЅпїЅпїЅпїЅпїЅпїЅ пїЅпїЅпїЅпїЅпїЅпїЅпїЅпїЅ UFW"
      else
        ufw --force disable >/dev/null 2>&1 || warn "пїЅпїЅ пїЅпїЅпїЅпїЅпїЅпїЅпїЅ пїЅпїЅпїЅпїЅпїЅпїЅпїЅпїЅпїЅ UFW"
      fi
    fi
    rm -f "$FW_STATE_DIR/saved"
    log "  РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРѕ РёР· СЃРЅРёРјРєР° $FW_STATE_DIR (С‚РёС…Рѕ)"
  else
    save_firewall_state >/dev/null 2>&1 || true
    ufw --force reset >/dev/null 2>&1 || true
    ufw default deny incoming >/dev/null 2>&1 || true
    ufw default allow outgoing >/dev/null 2>&1 || true
    fw_allow "${SSH_PORT:-22}" tcp "SSH"
    local p
    for p in $(ss -tln 2>/dev/null | awk 'NR>1 { if ($4 ~ /^127\./ || $4 ~ /^\[::1\]/) next; split($4,a,":"); print a[length(a)] }' | sort -un); do
      [[ -n "$p" && "$p" != "${SSH_PORT:-22}" ]] && fw_allow "$p" tcp "rollback-open"
    done
    for p in $(ss -uln 2>/dev/null | awk 'NR>1 { if ($4 ~ /^127\./ || $4 ~ /^\[::1\]/) next; if ($5 != "*:*") next; split($4,a,":"); print a[length(a)] }' | sort -un); do
      [[ -n "$p" ]] && fw_allow "$p" udp "rollback-open"
    done
    ufw --force enable >/dev/null 2>&1 || true
    log "  reset + РѕС‚РєСЂС‹С‚Рѕ РІСЃС‘ СЃР»СѓС€Р°СЋС‰РµРµСЃСЏ"
  fi
  # РџРѕР»РЅС‹Р№ РѕС‚РєР°С‚ СЃРЅРёРјР°РµС‚ firewall-СЂРµР¶РёРј СЃС‚РµРєР° РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ РЅР°Р»РёС‡РёСЏ СЃРЅРёРјРєР°.
  # РРЅР°С‡Рµ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹Р№ UFW РјРѕР¶РµС‚ РѕСЃС‚Р°РІРёС‚СЊ deny incoming РїРѕСЃР»Рµ СѓРґР°Р»РµРЅРёСЏ nginx.
  if command -v ufw >/dev/null 2>&1; then
    ufw --force disable >/dev/null 2>&1 || true
    log "  UFW РѕС‚РєР»СЋС‡С‘РЅ РїРѕСЃР»Рµ РїРѕР»РЅРѕРіРѕ РѕС‚РєР°С‚Р°"
  fi

  log "[7/7] РЈРґР°Р»РµРЅРёРµ nginxвЂ¦"
  systemctl stop nginx 2>/dev/null || true
  systemctl disable nginx 2>/dev/null || true
  DEBIAN_FRONTEND=noninteractive apt-get purge -y nginx nginx-common nginx-full libnginx-mod-stream >/dev/null 2>&1 || true
  apt-get autoremove -y >/dev/null 2>&1 || true
  rm -rf /etc/nginx /var/log/nginx 2>/dev/null || true
  # Р¤РёРЅР°Р»СЊРЅР°СЏ СЃС‚СЂР°С…РѕРІРєР°: РїРѕР»РЅС‹Р№ РѕС‚РєР°С‚ РЅРµ РґРѕР»Р¶РµРЅ РѕСЃС‚Р°РІР»СЏС‚СЊ РјР°СЂРєРµСЂС‹ stack/SNI,
  # РёРЅР°С‡Рµ СЃР»РµРґСѓСЋС‰РёР№ Р·Р°РїСѓСЃРє РѕС€РёР±РѕС‡РЅРѕ СЃС‡РёС‚Р°РµС‚ РїРµСЂРІРёС‡РЅСѓСЋ РЅР°СЃС‚СЂРѕР№РєСѓ РІС‹РїРѕР»РЅРµРЅРЅРѕР№.
  rm -f "$STACK_CONF" "$STACK_LINK" "$SNI_CONF" \
    /etc/nginx/streams-enabled/sni-router.conf \
    /etc/nginx/streams-available/sni-router.conf \
    /etc/nginx/snippets/decoy-headers.conf 2>/dev/null || true
  rm -f "$BACKUP_DIR/.pre-install-done" /root/stack-frozen.txt "$CERT_MODE_FILE" \
    "$CERT_LINES_FILE" "$WILDCARD_STATE" /root/.stack-src 2>/dev/null || true

  line
  log "РџРћР›РќР«Р™ РћРўРљРђРў Р—РђР’Р•Р РЁРЃРќ"
  line
  local wp
  wp=$(xui_get webPort 2>/dev/null || echo '?')
  local _pd _pp _host _scheme _cert
  _pd="${PANEL_DOMAIN:-$(xui_get webDomain 2>/dev/null || true)}"
  _pp="$(xui_get webBasePath 2>/dev/null || true)"
  _pp="/${_pp#/}"
  [[ "$_pp" != */ ]] && _pp="$_pp/"
  _host="${_pd:-$(server_ip4)}"; [[ -z "$_host" ]] && _host="127.0.0.1"
  _scheme="https"; _cert=""
  [[ -n "$_pd" ]] && _cert="/etc/letsencrypt/live/$_pd/fullchain.pem"
  [[ -n "$_cert" && ! -f "$_cert" ]] && _cert=""
  [[ -z "$_cert" ]] && _scheme="http"
  if [[ -n "$_pd" && "$_pd" != "panel.example.com" ]]; then
    echo "  РџР°РЅРµР»СЊ:  ${_scheme}://${_pd}:${wp:-?}${_pp}"
    [[ "$_scheme" == "https" ]] && echo "           (РґРѕСЃС‚СѓРї РїРѕ РґРѕРјРµРЅСѓ; IP РґР°СЃС‚ РѕС€РёР±РєСѓ СЃРµСЂС‚РёС„РёРєР°С‚Р° Common Name)"
  else
    echo "  РџР°РЅРµР»СЊ:  ${_scheme}://${_host}:${wp:-?}${_pp}"
    echo "           РґРѕРјРµРЅ РїР°РЅРµР»Рё РЅРµ РѕРїСЂРµРґРµР»С‘РЅ вЂ” РїСЂРѕРІРµСЂСЊ webDomain РІ LucX UI"
  fi
  echo "  РЎРµСЂС‚С‹:   СЃРѕС…СЂР°РЅРµРЅС‹ (/etc/letsencrypt/live/)"
  echo "  AdGuard: РЅРµ С‚СЂРѕРіР°Р»СЃСЏ"
  echo "  РРЅР±Р°СѓРЅРґС‹ Рё РєР»РёРµРЅС‚С‹ РїР°РЅРµР»Рё: СЃРѕС…СЂР°РЅРµРЅС‹"
  echo "  Р‘СЌРєР°Рї:   $BACKUP_DIR/auto-*"
  line
  pause
}

# --- РџРѕРґРјРµРЅСЋ РѕС‚РєР°С‚Р° ---------------------------------------------------
rollback_menu() {
  while :; do
    clear
    line; echo -e "${B}   РћРўРљРђРў Р Р”Р•РњРћРќРўРђР– РЎРўР•РљРђ${N}"; line
    local heal="РЅРµС‚" jail="РЅРµС‚" hook="РЅРµС‚" ngx="РЅРµС‚" sni="РЅРµС‚" snap="РЅРµС‚"
    # РџСЂРѕРІРµСЂСЏРµРј С„Р°РєС‚РёС‡РµСЃРєРёРµ С„Р°Р№Р»С‹/СЃРѕСЃС‚РѕСЏРЅРёРµ, Р° РЅРµ С‚РѕР»СЊРєРѕ СЃРїРёСЃРѕРє unit-С„Р°Р№Р»РѕРІ:
    # РїРѕСЃР»Рµ С‡Р°СЃС‚РёС‡РЅРѕРіРѕ РѕС‚РєР°С‚Р° unit РјРѕР¶РµС‚ РѕСЃС‚Р°С‚СЊСЃСЏ disabled, Р° SNI вЂ” РІ enabled.
    stack_heal_present && heal="РґР°"
    [[ -f /etc/fail2ban/jail.d/decoy-login.local ]] && jail="РґР°"
    [[ -x /etc/letsencrypt/renewal-hooks/deploy/stack-cert-mirror.sh ]] && hook="РґР°"
    nginx_ready && ngx="РґР°"
    sni_router_present && sni="РґР°"
    [[ -f "$FW_STATE_DIR/saved" ]] && snap="РґР°"
    echo "  РўРµРєСѓС‰РµРµ СЃРѕСЃС‚РѕСЏРЅРёРµ СЃС‚РµРєР°:"
    printf "    nginx:                 %s\n" "$ngx"
    printf "    SNI-СЂРѕСѓС‚РµСЂ (443):      %s\n" "$sni"
    printf "    stack-heal:            %s\n" "$heal"
    printf "    fail2ban decoy-jail:   %s\n" "$jail"
    printf "    certbot deploy-hook:   %s\n" "$hook"
    printf "    СЃРЅРёРјРѕРє UFW:            %s\n" "$snap"
    echo
    line
    echo "  1) рџЊђ РћС‚РєСЂС‹С‚СЊ РїРѕСЂС‚С‹ РЅР°СЂСѓР¶Сѓ (РїР°РЅРµР»СЊ / РїРѕРґРїРёСЃРєРё / РёРЅР±Р°СѓРЅРґС‹)"
    echo "  2) рџљ§ РџСЂР°РІРёР»Р° С„Р°Р№РµСЂРІРѕР»Р° (UFW)"
    echo "  3) рџ› пёЏ  РЎР»СѓР¶Р±С‹ Рё РёРЅС‚РµРіСЂР°С†РёРё СЃС‚РµРєР°"
    echo "  4) рџ“Ѓ РљРѕРЅС„РёРіРё Рё РєР°С‚Р°Р»РѕРіРё СЃС‚РµРєР°"
    echo "  5) рџ—‘пёЏ  РЈРґР°Р»РёС‚СЊ nginx (РїР°РєРµС‚ + РєРѕРЅС„РёРіРё)"
    echo "  6) рџ§Ё РЎРЅСЏС‚СЊ СЃРѕСЃС‚РѕСЏРЅРёРµ СЃС‚РµРєР° (РЅР°СЃС‚СЂРѕР№РєРё РїР°РЅРµР»Рё, listen, РјР°СЂРєРµСЂС‹)"
    echo "  7) рџ’Ј РџРћР›РќР«Р™ РћРўРљРђРў (РІСЃС‘ РІС‹С€Рµ, С‚РёС…Рѕ, РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ YES)"
    echo "  0) РќР°Р·Р°Рґ"
    line
    local c=""
    read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
    case "$c" in
      1) rb_open_ports ;;
      2) rb_firewall ;;
      3) rb_services ;;
      4) rb_configs ;;
      5) rb_remove_nginx ;;
      6) rb_reset_state_menu ;;
      7) rb_full_rollback ;;
      0) return 0 ;;
      *) sleep 1 ;;
    esac
  done
}


# --- РџРѕРґРјРµРЅСЋ: pre-install snapshot (СЂР°Р·РґРµР» 5 в†’ РїСѓРЅРєС‚ 4) ----------------
preinstall_menu() {
  while :; do
    clear
    line; echo -e "${B}   PRE-INSTALL РЎРќРРњРћРљ РЎРћРЎРўРћРЇРќРРЇ${N}"; line
    local cnt
    cnt=$(ls -1d "$BACKUP_DIR"/pre-install-* 2>/dev/null | grep -v "\.tar\.gz$" | wc -l)
    echo "  РЎРЅРёРјРєРѕРІ РІ $BACKUP_DIR/pre-install-*: $cnt"
    echo
    echo "  Р§С‚Рѕ СЃРѕС…СЂР°РЅСЏРµС‚СЃСЏ:"
    echo "    x-ui.db, /etc/x-ui, /etc/nginx/*, РїСЂР°РІРёР»Р° UFW/iptables, /etc/fail2ban,"
    echo "    systemd units СЃС‚РµРєР°, /etc/letsencrypt/renewal+hooks, logrotate, AdGuardHome.yaml"
    echo
    line
    echo "  1) рџ“ё РЎРґРµР»Р°С‚СЊ РЅРѕРІС‹Р№ СЃРЅРёРјРѕРє СЃРµР№С‡Р°СЃ"
    echo "  2) в™»пёЏ  Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ РёР· СЃРЅРёРјРєР° (РїРµСЂРµР·Р°РїРёС€РµС‚ С‚РµРєСѓС‰РµРµ СЃРѕСЃС‚РѕСЏРЅРёРµ)"
    echo "  3) рџ—‘пёЏ  РЈРґР°Р»РёС‚СЊ СЃС‚Р°СЂС‹Р№ СЃРЅРёРјРѕРє"
    echo "  0) РќР°Р·Р°Рґ"
    line
    local c=""
    read -rp "$(echo -e "${B}Р’С‹Р±РѕСЂ:${N} ")" c || c="0"
    case "$c" in
      1) take_pre_install_snapshot; pause ;;
      2) restore_pre_install_snapshot ;;
      3)
        local snaps
        snaps=$(ls -1dt "$BACKUP_DIR"/pre-install-* 2>/dev/null | grep -v "\.tar\.gz$" | head -20)
        [[ -z "$snaps" ]] && { warn "РЎРЅРёРјРєРѕРІ РЅРµС‚"; pause; continue; }
        local i=1 d
        while IFS= read -r d; do
          [[ -z "$d" ]] && continue
          printf "  %2d) %s\n" "$i" "$(basename "$d")"
          i=$((i+1))
        done <<<"$snaps"
        local pick=""; ask pick "РќРѕРјРµСЂ (0 вЂ” РѕС‚РјРµРЅР°)" "0" '^[0-9]+$'
        [[ "$pick" == "0" ]] && continue
        local ch
        ch=$(printf '%s\n' "$snaps" | sed -n "${pick}p")
        [[ -z "$ch" ]] && { err "РќРµС‚ С‚Р°РєРѕРіРѕ"; pause; continue; }
        local sure=""; askyn sure "РЈРґР°Р»РёС‚СЊ $(basename "$ch") Рё РµРіРѕ .tar.gz?" "n"
        [[ "$sure" == true ]] && { rm -rf "$ch" "$ch.tar.gz" 2>/dev/null; log "РЈРґР°Р»РµРЅРѕ"; }
        pause
        ;;
      0) return 0 ;;
      *) sleep 1 ;;
    esac
  done
}

routing_diagnostics_menu() {
  while :; do
    line; echo -e "${B}   РњРђР РЁР РЈРўРР—РђР¦РРЇ Р Р”РРђР“РќРћРЎРўРРљРђ${N}"; line
    echo "  1) Р”РёР°РіРЅРѕСЃС‚РёРєР° СЃС‚РµРєР°"
    echo "  2) РћС‡РёСЃС‚РёС‚СЊ СѓСЃС‚Р°СЂРµРІС€РёРµ SNI-Р·Р°РїРёСЃРё"
    echo "  3) РџРµСЂРµСЃРѕР±СЂР°С‚СЊ SNI РёР· С‚РµРєСѓС‰РµР№ Р‘Р”"
    echo "  4) Р“РёРіРёРµРЅР° nginx"
    echo "  5) РџСЂРѕРІРµСЂРєР°/РїРѕС‡РёРЅРєР° CDN-РјР°СЂС€СЂСѓС‚РёР·Р°С†РёРё"
    echo "  0) РќР°Р·Р°Рґ"
    local c=""
    ask c "Р’С‹Р±РѕСЂ" "1" '^[0-5]$'
    case "$c" in
      1)
        echo
        echo "  1) РџРѕР»РЅС‹Р№ read-only Р°СѓРґРёС‚"
        echo "  2) РќР°Р±Р»СЋРґРµРЅРёРµ Р·Р° СЃС‚РµРєРѕРј"
        echo "  3) РЎС‚РµР»СЃ-Р°СѓРґРёС‚"
        echo "  0) РќР°Р·Р°Рґ"
        local d=""
        ask d "Р”РёР°РіРЅРѕСЃС‚РёРєР°" "1" '^[0-3]$'
        case "$d" in
