      4) nginx_hygiene ;;
      5) cdn_repair; pause ;;
      0) return 0 ;;
    esac
  done
}

setup_routing_menu() {
  while :; do
    line; echo -e "${B}   РЈРЎРўРђРќРћР’РљРђ Р РњРђР РЁР РЈРўРР—РђР¦РРЇ${N}"; line
    echo "  1) РџРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° SNI-СЂРѕСѓС‚РµСЂР°"
    echo "  2) РРЅР±Р°СѓРЅРґС‹: РїСЂРѕРІРµСЂРєР°, РґРѕР±Р°РІР»РµРЅРёРµ, СѓРґР°Р»РµРЅРёРµ, РґРѕРјРµРЅС‹"
    echo "  0) РќР°Р·Р°Рґ"
    local c=""; ask c "Р’С‹Р±РѕСЂ" "1" '^[0-2]$'
    case "$c" in
      1)
        : > /tmp/stack-initial-setup.log 2>/dev/null || true
        initial_setup > >(tee -a /tmp/stack-initial-setup.log) 2>&1
        local _setup_rc=$?
        if [[ $_setup_rc -eq 0 ]]; then
          stack_mark_configured || warn "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕС…СЂР°РЅРёС‚СЊ РјР°СЂРєРµСЂ РЅР°СЃС‚СЂРѕР№РєРё; Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРёРµ РёСЃРїСЂР°РІР»РµРЅРёСЏ РѕСЃС‚Р°РЅСѓС‚СЃСЏ РѕС‚РєР»СЋС‡РµРЅС‹."
          echo
          echo -e "${G}РџРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° Р·Р°РІРµСЂС€РµРЅР°.${N}"
          pause
        else
          echo
          err "РџРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° Р·Р°РІРµСЂС€РёР»Р°СЃСЊ СЃ РѕС€РёР±РєРѕР№ (РєРѕРґ $_setup_rc)."
          echo "РџРѕРґСЂРѕР±РЅС‹Р№ Р»РѕРі: /tmp/stack-initial-setup.log"
          echo "РџРѕСЃР»РµРґРЅРёРµ СЃС‚СЂРѕРєРё Р»РѕРіР°:"
          tail -30 /tmp/stack-initial-setup.log 2>/dev/null || true
          pause
        fi
        return "$_setup_rc"
        ;;
      2) inbounds_manage_menu ;;
      0) return 0 ;;
    esac
  done
}
