    echo "  3) РњР°СЂС€СЂСѓС‚РёР·Р°С†РёСЏ Рё РґРёР°РіРЅРѕСЃС‚РёРєР°"
    echo "  4) РџРѕР»РЅС‹Р№ read-only Р°СѓРґРёС‚ СЃС‚РµРєР° (РІРєР». CDN Рё drift)"
    echo "  5) РЎРјРµРЅРёС‚СЊ РїР°СЂРѕР»Рё LucX UI / AdGuard Home"
    echo "  6) РћР±РЅРѕРІРёС‚СЊ СЃРєСЂРёРїС‚"
    echo "  0) РќР°Р·Р°Рґ"
    local c=""; ask c "Р’С‹Р±РѕСЂ" "1" '^[0-6]$'
    case "$c" in
      1) stack_check_fix; pause ;;
      2) show_status ;;
      3) routing_diagnostics_menu ;;
      4) stack_full_audit; pause ;;
      5) change_admin_passwords ;;
      6) update_self ;;
      0) return 0 ;;
    esac
  done
}
panel_adguard_menu() {
  while :; do
    line; echo -e "${B}   РџРђРќР•Р›Р¬ Р ADGUARD${N}"; line
    echo "  1) РЈРїСЂР°РІР»РµРЅРёРµ LucX/3x-ui"
    echo "  2) РЈРїСЂР°РІР»РµРЅРёРµ AdGuard Home"
    echo "  3) DNS Xray РІ РїР°РЅРµР»Рё LucX/3x-ui"
    echo "  4) рџ¤– TG-Р±РѕС‚: РІС‹С…РѕРґ РІ Telegram (Р°СѓС‚Р±Р°СѓРЅРґ/SOCKS/РЅР°РїСЂСЏРјСѓСЋ)"
    echo "  0) РќР°Р·Р°Рґ"
    local c=""; ask c "Р’С‹Р±РѕСЂ" "1" '^[0-4]$'
    case "$c" in 1) panel_manage; pause ;; 2) adguard_manage; pause ;; 3) xray_dns_menu ;; 4) bot_out_menu ;; 0) return 0 ;; esac
  done
}

# Р”РµР№СЃС‚РІРёРµ РїСѓРЅРєС‚Р° РјРµРЅСЋ вЂ” РІС‹Р·С‹РІР°РµС‚СЃСЏ РІ РџРћР”-РћР‘РћР›РћР§РљР•: exit 42 РІРЅСѓС‚СЂРё (С‚РѕРєРµРЅ В«qВ»
# РІ Р»СЋР±РѕРј РІРѕРїСЂРѕСЃРµ) РіР°СЃРёС‚ С‚РѕР»СЊРєРѕ РµС‘, Рё РјС‹ РѕРєР°Р·С‹РІР°РµРјСЃСЏ РЅР°Р·Р°Рґ РІ РјРµРЅСЋ.
run_menu_action() {
  # РџСѓРЅРєС‚С‹ РјРµРЅСЋ РґРѕСЃС‚СѓРїРЅС‹ РІСЃРµРіРґР°. Р‘РµР·РѕРїР°СЃРЅРѕСЃС‚СЊ РѕР±РµСЃРїРµС‡РёРІР°РµС‚СЃСЏ РІРЅСѓС‚СЂРё
  # РєРѕРЅРєСЂРµС‚РЅС‹С… Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРёС… РїСЂРѕС†РµРґСѓСЂ, Р° РЅРµ Р±Р»РѕРєРёСЂРѕРІРєРѕР№ РІСЃРµРіРѕ РјРµРЅСЋ.
  stack_is_configured && audit "menu:${1:-}"
  case "$1" in
    1) setup_routing_menu ;;
    2) decoy_domains_menu ;;
    3) certificates_menu ;;
    4) security_firewall_menu ;;
    5) backups_rollback_menu ;;
    6) diagnostics_maintenance_menu ;;
    7) panel_adguard_menu ;;
    8) migrate_menu ;;
    *) warn "РќРµС‚ С‚Р°РєРѕРіРѕ РїСѓРЅРєС‚Р°"; sleep 1 ;;
  esac
}

print_menu_actions() {
  echo
  echo -e "  ${B} 1)${N} рџ§­ РЈСЃС‚Р°РЅРѕРІРєР° Рё РјР°СЂС€СЂСѓС‚РёР·Р°С†РёСЏ"
  echo -e "  ${B} 2)${N} рџЋ­ Decoy Рё РґРѕРјРµРЅС‹"
  echo -e "  ${B} 3)${N} рџ”’ РЎРµСЂС‚РёС„РёРєР°С‚С‹"
  echo -e "  ${B} 4)${N} рџ›ЎпёЏ  Р‘РµР·РѕРїР°СЃРЅРѕСЃС‚СЊ Рё firewall"
  echo -e "  ${B} 5)${N} рџ’ѕ Р‘СЌРєР°РїС‹ Рё РѕС‚РєР°С‚"
  echo -e "  ${B} 6)${N} рџ©є Р”РёР°РіРЅРѕСЃС‚РёРєР° Рё РѕР±СЃР»СѓР¶РёРІР°РЅРёРµ"
  echo -e "  ${B} 7)${N} вљ™пёЏ  РџР°РЅРµР»СЊ Рё AdGuard"
  echo -e "  ${B} 8)${N} рџљљ РџРµСЂРµРµР·Рґ РЅР° РґСЂСѓРіРѕР№ СЃРµСЂРІРµСЂ"
}

fast_menu_header() {
  local nb=0 ufw_state="down" ngx xui adg f2b panel="вЂ”" panel_url="" adg_url=""
  local _pd="" _pp="" _pb="" _adg_dom="" _panel_port="" _public_port=""
  _pd="${PANEL_DOMAIN:-$(xui_get webDomain 2>/dev/null || true)}"
  _pp="$(xui_get webBasePath 2>/dev/null || true)"
  _panel_port="$(xui_get webPort 2>/dev/null || true)"
  # РџРѕСЃР»Рµ РѕС‚РєР°С‚Р° nginx/SNI-С„СЂРѕРЅС‚РµРЅРґ РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚, РїРѕСЌС‚РѕРјСѓ РїР°РЅРµР»СЊ РґРѕСЃС‚СѓРїРЅР°
  # РЅР°РїСЂСЏРјСѓСЋ РЅР° webPort. Р’ С€Р°РїРєРµ РїРѕРєР°Р·С‹РІР°РµРј С‚РѕС‚ Р¶Рµ С„Р°РєС‚РёС‡РµСЃРєРёР№ URL, С‡С‚Рѕ Рё
  # РІ РёС‚РѕРіРѕРІРѕРј СЃРѕРѕР±С‰РµРЅРёРё РѕС‚РєР°С‚Р°; РїСЂРё СЂР°Р±РѕС‚Р°СЋС‰РµРј С„СЂРѕРЅС‚РµРЅРґРµ РёСЃРїРѕР»СЊР·СѓРµРј 443.
  if [[ -f "$STACK_CONF" ]] && nginx_ready; then
    _public_port=""
  else
    [[ "$_panel_port" =~ ^[0-9]+$ ]] && _public_port="$_panel_port"
  fi
  if [[ -n "$_pd" && "$_pd" != "panel.example.com" ]]; then
    _pp="${_pp#/}"; _pp="${_pp%/}"   # РІРµРґСѓС‰РёР№ Рё С…РІРѕСЃС‚РѕРІРѕР№ СЃР»РµС€Рё вЂ” РґРѕР±Р°РІРёРј СЂРѕРІРЅРѕ РѕРґРёРЅ
    if [[ -n "$_public_port" ]]; then
      panel_url="https://$_pd:${_public_port}/"
    else
      panel_url="https://$_pd/"
    fi
    [[ -n "$_pp" ]] && panel_url="${panel_url}${_pp}/"
  fi
  if [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]] && systemctl is-active --quiet "$ADG_SERVICE" 2>/dev/null; then
    _adg_dom="$(xui_get webDomain 2>/dev/null || true)"
    if [[ "${ADG_PLACEMENT:-}" == separate && -n "${ADG_MODE_SNI_DOM:-}" ]]; then _adg_dom="$ADG_MODE_SNI_DOM"; fi
    [[ -n "$_adg_dom" ]] && adg_url="https://$_adg_dom/"
  fi
  [[ -f "$XUI_DB" ]] && nb=$(sqlite3 -cmd ".timeout 1000" "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE enable=1;" 2>/dev/null || echo 0)
  ufw_is_active && ufw_state="active"
  ngx=$(systemctl is-active nginx 2>/dev/null || echo unknown)
  xui=$(systemctl is-active x-ui 2>/dev/null || echo unknown)
  adg="вЂ”"; [[ "$ADG_PRESENT" == true && -n "$ADG_SERVICE" ]] && adg=$(systemctl is-active "$ADG_SERVICE" 2>/dev/null || echo unknown)
  f2b=$(systemctl is-active fail2ban 2>/dev/null || echo unknown)
  case "${PANEL_FLAVOR:-$(detect_panel_flavor)}" in
    lucx) panel="LucX UI" ;; 3x-ui) panel="3x-ui" ;; *) panel="РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°" ;;
  esac
  line
  local panel_line="" adg_line=""
  [[ -n "$panel_url" ]] && panel_line="рџ”— РџР°РЅРµР»СЊ: $panel_url"
  [[ -n "$adg_url" ]] && adg_line="рџ›Ў AdGuard: $adg_url"
  printf "  ${B}%-56s${N}\n" "в•”в•ђ STACK MANAGER В· РџР РћРљРЎР-РћР РљР•РЎРўР РђРўРћР  в•ђв•—"
  printf "  ${D}%-56s${N}\n" "Р’РµСЂСЃРёСЏ: v${STACK_MANAGER_VERSION} | РџР°РЅРµР»СЊ: $panel | nginx: 443 | SNI | CDN | decoy"
  # URL РЅРµР»СЊР·СЏ РѕР±СЂРµР·Р°С‚СЊ: РґР»РёРЅРЅР°СЏ СЃСЃС‹Р»РєР° РІС‹РІРѕРґРёС‚СЃСЏ С†РµР»РёРєРѕРј, РїСЂРё РЅРµРѕР±С…РѕРґРёРјРѕСЃС‚Рё вЂ” РІ РЅРµСЃРєРѕР»СЊРєРѕ СЃС‚СЂРѕРє.
  if [[ -n "$panel_line" ]]; then
    printf '%s\n' "$panel_line" | fold -w 54 | while IFS= read -r _url_line; do
      [[ -n "$_url_line" ]] && printf "  ${G}%s${N}\n" "$_url_line"
    done
  fi
  if [[ -n "$adg_line" ]]; then
    printf '%s\n' "$adg_line" | fold -w 54 | while IFS= read -r _url_line; do
      [[ -n "$_url_line" ]] && printf "  ${G}%s${N}\n" "$_url_line"
    done
  fi
  line
  printf "  %-18s %-12s | %-18s %-12s\n" "nginx" "$ngx" "x-ui" "$xui"
  printf "  %-18s %-12s | %-18s %-12s\n" "AdGuard" "$adg" "fail2ban" "$f2b"
  local inbound_label="вЂ”"
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && inbound_label="${nb:-0} active"
  printf "  %-18s %-12s | %-18s %-12s\n" "UFW" "$ufw_state" "inbounds" "$inbound_label"
  line
  printf "  ${D}%-56s${N}\n" "Р‘С‹СЃС‚СЂС‹Р№ РїРµСЂРµС…РѕРґ: 1вЂ“7 СЂР°Р·РґРµР»С‹ | 0 РІС‹С…РѕРґ | Р°СѓРґРёС‚: СЂР°Р·РґРµР»С‹ 6вЂ“7"
  line
}

main_menu() {
  # Р”Рѕ СЏРІРЅРѕР№ РЅР°СЃС‚СЂРѕР№РєРё РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ вЂ” С‚РѕР»СЊРєРѕ РјРµРЅСЋ Рё С‡С‚РµРЅРёРµ СЃРѕСЃС‚РѕСЏРЅРёСЏ.
  # РРЅРёС†РёР°Р»РёР·Р°С†РёСЏ decoy СЃР°РјР° РјРµРЅСЏРµС‚ nginx/С„Р°Р№Р»С‹, РїРѕСЌС‚РѕРјСѓ Р·РґРµСЃСЊ Р·Р°РїСЂРµС‰РµРЅР°.
  detect_env >/dev/null 2>&1 || true
  if stack_is_configured; then
    decoy_full_init || true
  else
    warn "Р‘РµР·РѕРїР°СЃРЅС‹Р№ СЂРµР¶РёРј: СЃС‚РµРє РµС‰С‘ РЅРµ РЅР°СЃС‚СЂРѕРµРЅ СЃРєСЂРёРїС‚РѕРј; Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРёРµ РёР·РјРµРЅРµРЅРёСЏ РѕС‚РєР»СЋС‡РµРЅС‹."
  fi
  while :; do
    clear
    fast_menu_header
    print_menu_actions
    echo
    echo -e "  ${B} 0)${N} рџљЄ Р’С‹С…РѕРґ   ${Y}(q РІ Р»СЋР±РѕРј РІРѕРїСЂРѕСЃРµ вЂ” РІС‹С…РѕРґ РІ РјРµРЅСЋ)${N}"
    line
    local c="" rc
    read -rp "$(echo -e "${Y}рџ‘‰${N} Р’Р°С€ РІС‹Р±РѕСЂ: ")" c || c="0"
    case "$c" in
      0) exit 0 ;;
      q|quit|exit|РІС‹С…РѕРґ) exit 0 ;;
      *) ( run_menu_action "$c" )
         rc=$?
         if [[ $rc -eq 42 ]]; then warn "Р’РѕР·РІСЂР°С‚ РІ РјРµРЅСЋ"; sleep 1
         elif [[ $rc -ne 0 ]]; then warn "РџСѓРЅРєС‚ Р·Р°РІРµСЂС€РёР»СЃСЏ СЃ РѕС€РёР±РєРѕР№ (РєРѕРґ $rc)"; sleep 1; fi ;;
    esac
  done
}

# =====================================================================
# =====================================================================
# РџР•Р Р•Р•Р—Р” РќРђ Р”Р РЈР“РћР™ РЎР•Р Р’Р•Р  (РїРѕР»РЅС‹Р№ РїРµСЂРµРЅРѕСЃ СЃС‚РµРєР°)
#
# РџРѕСЂСЏРґРѕРє Р¶С‘СЃС‚РєРёР№ Рё РѕР±СЂР°С‚РЅС‹Р№ РѕР±С‹С‡РЅРѕРјСѓ: СЃРЅР°С‡Р°Р»Р° РЅР° РќРћР’РћРњ СЃРµСЂРІРµСЂРµ СЃРєСЂРёРїС‚
# СЃС‚Р°РІРёС‚ РїР»Р°С‚С„РѕСЂРјСѓ (РїР°РєРµС‚С‹, nginx, РїР°РЅРµР»СЊ) вЂ” РїРѕС‚РѕРј СЂР°СЃРїР°РєРѕРІС‹РІР°РµС‚СЃСЏ Р°СЂС…РёРІ
# СЃРѕ СЃС‚Р°СЂРѕРіРѕ. РўР°Рє СЂР°СЃРїР°РєРѕРІР°РЅРЅС‹Рµ Р±РёРЅР°СЂРЅРёРєРё/СЋРЅРёС‚С‹ РІСЃРµРіРґР° Р»РѕР¶Р°С‚СЃСЏ РЅР° РіРѕС‚РѕРІСѓСЋ
# Р±Р°Р·Сѓ Рё РЅРµ РєРѕРЅС„Р»РёРєС‚СѓСЋС‚ СЃ СѓСЃС‚Р°РЅРѕРІС‰РёРєРѕРј РїР°РЅРµР»Рё.
#
# РЎС…РµРјР°:
#   1) СЃС‚Р°СЂС‹Р№ СЃРµСЂРІРµСЂ: migrate_export    в†’ Р°СЂС…РёРІ + sha256
#   2) РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ:  РїРµСЂРµРЅРѕСЃ С„Р°Р№Р»Р° (scp/rsync РІСЂСѓС‡РЅСѓСЋ РёР»Рё 8 в†’ 1 РЅР° РїСЂРёС‘РјРЅРёРєРµ)
#   3) РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ:  migrate_bootstrap в†’ РїР°РєРµС‚С‹, nginx, РїР°РЅРµР»СЊ
#   4) РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ:  migrate_unpack    в†’ СЂР°СЃРїР°РєРѕРІРєР° РїРѕРІРµСЂС… РїР»Р°С‚С„РѕСЂРјС‹
#   5) РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ:  migrate_dns_check в†’ РёРјРµРЅР° РґРѕР»Р¶РЅС‹ СѓРєР°Р·С‹РІР°С‚СЊ РЅР° РЅРѕРІС‹Р№ IP
#   6) РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ:  migrate_certs_reissue в†’ РїРµСЂРµРІС‹РїСѓСЃРє СЃРµСЂС‚РѕРІ
#   7) РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ:  migrate_postcheck в†’ СЃРјРѕСѓРє
# =====================================================================
MIGRATE_DIR="/root/stack-backups"
MIGRATE_PREFIX="migrate"
MIGRATE_EXTRA_PATHS=(
  /root/.config/torrserver
  /opt/torrserver
)

# в”Ђв”Ђв”Ђ РЎР±РѕСЂ РґРѕРјРµРЅРѕРІ СЃС‚РµРєР°: Р‘Р”, SNI-map, renewal, CDN-РїСЂРѕС„РёР»Рё, РјР°СЂРєРµСЂС‹ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# РџРµС‡Р°С‚Р°РµС‚ РїРѕ РѕРґРЅРѕРјСѓ РґРѕРјРµРЅСѓ РІ СЃС‚СЂРѕРєСѓ, Р±РµР· С‡СѓР¶РёС… reality-С†РµР»РµР№ Рё CDN-С…РѕСЃС‚РѕРІ.
migrate_collect_domains() {
  local d _rt_x skip_reality=false
  {
    [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || true
    if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
      sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT value FROM settings WHERE key='webDomain';" 2>/dev/null || true
      sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT address FROM hosts WHERE address IS NOT NULL AND address<>'';" 2>/dev/null || true
      sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT stream_settings FROM inbounds WHERE stream_settings IS NOT NULL;" 2>/dev/null \
        | grep -oE '"(serverName|sni|hostname|domain)"[[:space:]]*:[[:space:]]*"[A-Za-z0-9.-]+"' \
        | sed -E 's/.*"([A-Za-z0-9.-]+)"$/\1/' || true
      sqlite3 -cmd ".timeout 3000" "$XUI_DB" "SELECT stream_settings FROM inbounds WHERE stream_settings IS NOT NULL;" 2>/dev/null \
        | grep -oE '"(serverNames)"[[:space:]]*:[[:space:]]*\[[^]]*\]' \
        | grep -oE '"[A-Za-z0-9.-]+"' | tr -d '"' || true
    fi
    # SNI-РєР°СЂС‚Р°: С‚РѕР»СЊРєРѕ СЃС‚СЂРѕРєРё map (Р»РµРІР°СЏ РєРѕР»РѕРЅРєР°), upstream-РёРјРµРЅР° РЅРµ РґРѕРјРµРЅС‹
    sed -n 's/^[[:space:]]*\([A-Za-z0-9.-][A-Za-z0-9.-]*\)[[:space:]]\+[A-Za-z0-9_]*;.*/\1/p' "$SNI_CONF" 2>/dev/null || true
    # renewal-РєРѕРЅС„РёРіРё: РёРјРµРЅР° Р»РёРЅРёР№ Рё SAN
    if [[ -d /etc/letsencrypt/renewal ]]; then
      local f
      for f in /etc/letsencrypt/renewal/*.conf; do
        [[ -f "$f" ]] || continue
        basename "$f" .conf
        sed -n 's/^domains[[:space:]]*=[[:space:]]*//p' "$f" 2>/dev/null | tr ',' '\n' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//'
      done
    fi
    # РєР°Р¶РґС‹Р№ РїСЂРѕРёР·РІРѕРґРёС‚РµР»СЊ РѕР±СЏР·Р°РЅ Р·Р°РєР°РЅС‡РёРІР°С‚СЊСЃСЏ \n: С„Р°Р№Р»С‹ Р±РµР· РїРµСЂРµРІРѕРґР° СЃС‚СЂРѕРєРё
    # РЅР° РєРѕРЅС†Рµ СЃРєР»РµРёРІР°СЋС‚СЃСЏ СЃРѕ СЃР»РµРґСѓСЋС‰РёРј РІС‹РІРѕРґРѕРј (РїСѓСЃС‚С‹Рµ СЃС‚СЂРѕРєРё РѕС‚С„РёР»СЊС‚СЂСѓРµС‚ grep)
    [[ -f "$WILDCARD_STATE" ]] && { head -n 1 "$WILDCARD_STATE" 2>/dev/null; printf '\n'; }
    [[ -f "$CDN_PROFILES" ]] && { cut -d'|' -f3,4 "$CDN_PROFILES" 2>/dev/null | tr '|' '\n'; printf '\n'; }
    [[ -f /etc/letsencrypt/stack-domains.txt ]] && { cat /etc/letsencrypt/stack-domains.txt 2>/dev/null; printf '\n'; }
  } | tr -d '\r' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//' | sed 's/^\*\.//' \
    | grep -E '^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,}$' | sort -u \
    | while IFS= read -r d; do
      for _rt_x in "${REALITY_TARGETS[@]}"; do
        [[ "$d" == "$_rt_x" ]] && { skip_reality=true; break; }
        skip_reality=false
      done
      [[ "$skip_reality" == true ]] || printf '%s\n' "$d"
    done
}

# в”Ђв”Ђв”Ђ РСЃС‚РѕС‡РЅРёРєРё Р°СЂС…РёРІР° (С‚РѕР»СЊРєРѕ СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёРµ РїСѓС‚Рё) в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
migrate_sources() {
  local -a cand=(
    etc/x-ui
    etc/nginx
    etc/letsencrypt
    etc/fail2ban
    etc/systemd/system/x-ui.service
    etc/systemd/system/tg-stack-bot.service
    etc/systemd/system/stack-heal.service
    etc/systemd/system/stack-heal.timer
    etc/logrotate.d/stack-decoy
    etc/ufw
    etc/default/ufw
    var/www
    root/stack-manager.sh
    root/panel-credentials.txt
    root/adguard-credentials.txt
    root/.secrets
    root/stack-backups/wildcard-domain
    root/stack-backups/cert-mode
    root/stack-backups/cert-lines.txt
    root/stack-backups/le-email
    root/stack-backups/cdn-profiles.tsv
    root/stack-backups/.stack-configured
    root/stack-backups/cert-line-
  )
  local p
  for p in "${cand[@]}"; do
    if [[ "$p" == "root/stack-backups/cert-line-" ]]; then
      local f
      for f in /root/stack-backups/cert-line-*; do
        [[ -f "$f" ]] && printf '%s\n' "${f#/}"
      done
      continue
    fi
    [[ -e "/$p" ]] && printf '%s\n' "$p"
  done
  if [[ "${MIGRATE_WITH_EXTRA:-false}" == true ]]; then
    for p in "${MIGRATE_EXTRA_PATHS[@]}"; do
      [[ -e "$p" ]] && printf '%s\n' "${p#/}"
    done
  fi
}

# в”Ђв”Ђв”Ђ 1. Р­РљРЎРџРћР Рў РќРђ РЎРўРђР РћРњ РЎР•Р Р’Р•Р Р• в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
migrate_export() {
  line; echo -e "${B}   1) Р­РљРЎРџРћР Рў: РђР РҐРР’ Р”Р›РЇ РџР•Р Р•Р•Р—Р”Рђ${N}"; line
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || { err "x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” СЌС‚Рѕ РЅРµ РёСЃС‚РѕС‡РЅРёРє СЃС‚РµРєР°"; pause; return 1; }
  mkdir -p "$MIGRATE_DIR" 2>/dev/null || { err "РќРµ РјРѕРіСѓ СЃРѕР·РґР°С‚СЊ $MIGRATE_DIR"; pause; return 1; }

  local -a src=()
  mapfile -t src < <(migrate_sources)
  [[ ${#src[@]} -gt 0 ]] || { err "РќРµ РЅР°С€С‘Р», С‡С‚Рѕ Р°СЂС…РёРІРёСЂРѕРІР°С‚СЊ"; pause; return 1; }

  local extra=""
  if [[ "${MIGRATE_WITH_EXTRA:-false}" != true ]]; then
    askyn extra "Р’РєР»СЋС‡РёС‚СЊ TorrServer Рё РїСЂРѕС‡РёРµ РґРѕРї. РєР°С‚Р°Р»РѕРіРё, РµСЃР»Рё РµСЃС‚СЊ?" "n"
    MIGRATE_WITH_EXTRA="$extra"
    [[ "$extra" == true ]] && mapfile -t src < <(migrate_sources)
  fi

  echo
  echo "  Р’ Р°СЂС…РёРІ РІРѕР№РґС‘С‚:"
  printf '    %s\n' "${src[@]}" | head -30
  [[ ${#src[@]} -gt 30 ]] && echo "    вЂ¦ РІСЃРµРіРѕ ${#src[@]} РїСѓС‚РµР№"
  echo
  echo -e "  ${Y}Р’ Р°СЂС…РёРІРµ РїСЂРёРІР°С‚РЅС‹Рµ РєР»СЋС‡Рё TLS Рё Р‘Р” РїР°РЅРµР»Рё вЂ” РєРѕРїРёСЂРѕРІР°С‚СЊ С‚РѕР»СЊРєРѕ РїРѕ SSH/scp.${N}"

  # РњРµСЃС‚Рѕ: СЃР¶Р°С‚РёРµ РґР°С‘С‚ ~1/3, С‚СЂРµР±СѓРµРј С‚СЂС‘С…РєСЂР°С‚РЅС‹Р№ Р·Р°РїР°СЃ
  local need avail
  local -a full=()
  local p
  for p in "${src[@]}"; do full+=("/$p"); done
  need=$(du -sb --total "${full[@]}" 2>/dev/null | awk '/total/{print $1}')
  avail=$(df -B1 --output=avail / 2>/dev/null | tail -1 | tr -d ' ')
  if [[ -n "$need" && -n "$avail" ]] && (( need / 3 > avail )); then
    err "РњР°Р»Рѕ РјРµСЃС‚Р°: РЅСѓР¶РЅРѕ ~$((need/3/1048576))РњР‘, СЃРІРѕР±РѕРґРЅРѕ $((avail/1048576))РњР‘"
    local go=""
    askyn go "РџСЂРѕРґРѕР»Р¶РёС‚СЊ РІСЃС‘ СЂР°РІРЅРѕ?" "n"
    [[ "$go" == true ]] || { pause; return 1; }
  fi

  local go=""
  askyn go "РЎРѕР±СЂР°С‚СЊ Р°СЂС…РёРІ СЃРµР№С‡Р°СЃ? РџР°РЅРµР»СЊ Рё nginx Р±СѓРґСѓС‚ РєСЂР°С‚РєРѕ РѕСЃС‚Р°РЅРѕРІР»РµРЅС‹" "y"
  [[ "$go" == true ]] || { pause; return 0; }
  audit "migrate: СЌРєСЃРїРѕСЂС‚ СЃС‚РµРєР°"

  local ts file
  ts=$(date +%Y%m%d-%H%M%S)
  file="$MIGRATE_DIR/$MIGRATE_PREFIX-$ts.tar.gz"

  log "РћСЃС‚Р°РЅРѕРІРєР° x-ui (РєРѕРЅСЃРёСЃС‚РµРЅС‚РЅР°СЏ Р‘Р”)вЂ¦"
  sqlite3 "$XUI_DB" "PRAGMA wal_checkpoint(TRUNCATE);" >/dev/null 2>&1 || true
  systemctl stop x-ui 2>/dev/null || true

  log "РђСЂС…РёРІРёСЂРѕРІР°РЅРёРµвЂ¦"
  local rc=0
  tar czf "$file" -C / --warning=no-file-changed "${src[@]}" 2>/dev/null || rc=$?
  systemctl start x-ui 2>/dev/null || true
  # РєРѕРґ 1 = В«С„Р°Р№Р» РёР·РјРµРЅРёР»СЃСЏ РІРѕ РІСЂРµРјСЏ С‡С‚РµРЅРёСЏВ», Р°СЂС…РёРІ РїСЂРё СЌС‚РѕРј РІР°Р»РёРґРµРЅ
  if [[ $rc -ne 0 && $rc -ne 1 ]]; then
    err "tar Р·Р°РІРµСЂС€РёР»СЃСЏ СЃ РєРѕРґРѕРј $rc вЂ” Р°СЂС…РёРІ РЅРµ РіРѕС‚РѕРІ"
    rm -f "$file"
    pause; return 1
  fi
  [[ -s "$file" ]] || { err "РђСЂС…РёРІ РїСѓСЃС‚"; rm -f "$file"; pause; return 1; }
  chmod 600 "$file" 2>/dev/null || true
  sha256sum "$file" > "$file.sha256" 2>/dev/null || true

  local doms
  doms=$(migrate_collect_domains | tr '\n' ' ')
  {
    echo "Р”Р°С‚Р°:      $(date '+%F %T')"
    echo "РСЃС‚РѕС‡РЅРёРє:  $(hostname) / $(server_ip4 2>/dev/null || echo '?')"
    echo "РџР°РЅРµР»СЊ:    ${PANEL_FLAVOR:-unknown}"
    echo "Р”РѕРјРµРЅС‹:    $doms"
    echo "РџСѓС‚РµР№:     ${#src[@]}"
  } > "$file.INFO.txt" 2>/dev/null || true

  line
  ok "РђСЂС…РёРІ РіРѕС‚РѕРІ: $file"
  ls -lh "$file" 2>/dev/null | sed 's/^/  /'
  echo "  sha256: $(cut -d' ' -f1 "$file.sha256" 2>/dev/null)"
  echo
  echo "  Р”Р°Р»СЊС€Рµ:"
  echo "   1) СЃРєРѕРїРёСЂСѓР№ Р°СЂС…РёРІ Рё .sha256 РЅР° РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ:"
  echo "      scp $file* root@РќРћР’Р«Р™_IP:/root/stack-backups/"
  echo "   2) РЅР° РЅРѕРІРѕРј СЃРµСЂРІРµСЂРµ: СЌС‚РѕС‚ СЂР°Р·РґРµР» в†’ Рї.2 (СѓСЃС‚Р°РЅРѕРІРёС‚СЊ РїР»Р°С‚С„РѕСЂРјСѓ)"
  echo "   3) РІ РєРѕРЅС†Рµ вЂ” С€РµС„: РЅРё РѕРґРёРЅ РґРѕРјРµРЅ РЅРµ РґРѕР»Р¶РµРЅ РѕСЃС‚Р°С‚СЊСЃСЏ РЅР° СЃС‚Р°СЂРѕРј IP"
  line
  pause
}

# в”Ђв”Ђв”Ђ 2. РџР›РђРўР¤РћР РњРђ РќРђ РќРћР’РћРњ РЎР•Р Р’Р•Р Р• в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
# РЎРѕР·РЅР°С‚РµР»СЊРЅРѕ Р”Рћ СЂР°СЃРїР°РєРѕРІРєРё: СЂР°СЃРїР°РєРѕРІРєР° РєР»Р°РґС‘С‚ С„Р°Р№Р»С‹ РїРѕРІРµСЂС… РіРѕС‚РѕРІРѕР№ Р±Р°Р·С‹.
migrate_bootstrap() {
  line; echo -e "${B}   2) РЈРЎРўРђРќРћР’РљРђ РџР›РђРўР¤РћР РњР« РќРђ РќРћР’РћРњ РЎР•Р Р’Р•Р Р•${N}"; line
  echo "  РЎС‚Р°РІРёС‚СЃСЏ: РїР°РєРµС‚С‹ (nginx+certbot+ufw+fail2banвЂ¦), РєР°С‚Р°Р»РѕРіРё nginx,"
  echo "  СЃР°РјР° РїР°РЅРµР»СЊ LucX UI, Р±Р°Р·РѕРІР°СЏ Р·Р°С‰РёС‚Р° UFW (22/443/80)."
  echo "  Р”Р°РЅРЅС‹Рµ РїР°РЅРµР»Рё Р±СѓРґСѓС‚ Р·Р°РјРµРЅРµРЅС‹ РїСЂРё СЂР°СЃРїР°РєРѕРІРєРµ вЂ” СЌС‚Рѕ РЅРѕСЂРјР°Р»СЊРЅРѕ."
  echo
  if [[ -n "$XUI_DB" && -f "$XUI_DB" ]]; then
    local nb
    nb=$(sqlite3 -cmd ".timeout 1000" "$XUI_DB" "SELECT COUNT(*) FROM inbounds;" 2>/dev/null || echo 0)
    warn "РџР°РЅРµР»СЊ СѓР¶Рµ РµСЃС‚СЊ ($nb РёРЅР±Р°СѓРЅРґРѕРІ) вЂ” СѓСЃС‚Р°РЅРѕРІРєР° РїСЂРѕРїСѓСЃС‚РёС‚СЃСЏ, РЅРѕ РїР°РєРµС‚С‹ РѕР±РЅРѕРІСЏС‚СЃСЏ"
  fi
  local go=""
  askyn go "РќР°С‡Р°С‚СЊ СѓСЃС‚Р°РЅРѕРІРєСѓ РїР»Р°С‚С„РѕСЂРјС‹?" "y"
  [[ "$go" == true ]] || { pause; return 0; }
  audit "migrate: bootstrap РїР»Р°С‚С„РѕСЂРјС‹"

  if ! ensure_deps; then err "Р—Р°РІРёСЃРёРјРѕСЃС‚Рё РЅРµ СѓСЃС‚Р°РЅРѕРІРёР»РёСЃСЊ вЂ” РїР»Р°С‚С„РѕСЂРјР° РЅРµ РіРѕС‚РѕРІР°"; pause; return 1; fi

  mkdir -p /etc/nginx/{sites-available,sites-enabled,streams-available,streams-enabled,snippets,conf.d} \
           /var/www/html /etc/letsencrypt/renewal-hooks/deploy 2>/dev/null || true

  detect_env
  if [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]]; then
    install_lucx_panel || { err "РџР°РЅРµР»СЊ РЅРµ СѓСЃС‚Р°РЅРѕРІРёР»Р°СЃСЊ вЂ” СЂР°СЃРїР°РєРѕРІС‹РІР°С‚СЊ СЂР°РЅРѕ"; pause; return 1; }
    detect_env
  fi
  systemctl enable x-ui >/dev/null 2>&1 || true
  systemctl start x-ui 2>/dev/null || true

  # Р±Р°Р·РѕРІС‹Р№ firewall: SSH + 80 (ACME) + 443 (SNI). РџРѕР»РЅС‹Р№ РЅР°Р±РѕСЂ вЂ” РїРѕСЃР»Рµ СЂР°СЃРїР°РєРѕРІРєРё.
  if command -v ufw >/dev/null 2>&1; then
    ufw allow "$SSH_PORT"/tcp >/dev/null 2>&1 || true
    ufw allow 443/tcp >/dev/null 2>&1 || true
    ufw allow 80/tcp >/dev/null 2>&1 || true
    log "UFW: СЂР°Р·СЂРµС€РµРЅС‹ $SSH_PORT, 80, 443"
  fi

  line
  ok "РџР»Р°С‚С„РѕСЂРјР° СѓСЃС‚Р°РЅРѕРІР»РµРЅР°. Р”Р°Р»СЊС€Рµ вЂ” Рї.3 (СЂР°СЃРїР°РєРѕРІРєР° Р°СЂС…РёРІР°)."
  echo "  РџР°РЅРµР»СЊ СЃРµР№С‡Р°СЃ РЅР° РїСѓСЃС‚РѕР№ Р‘Р”: РїРѕСЃР»Рµ СЂР°СЃРїР°РєРѕРІРєРё РµС‘ Р·Р°РјРµРЅРёС‚ Р‘Р” СЃРѕ СЃС‚Р°СЂРѕРіРѕ СЃРµСЂРІРµСЂР°."
  line
  pause
}

# в”Ђв”Ђв”Ђ 3. Р РђРЎРџРђРљРћР’РљРђ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
migrate_unpack() {
  line; echo -e "${B}   3) Р РђРЎРџРђРљРћР’РљРђ РђР РҐРР’Рђ РџР•Р Р•Р•Р—Р”Рђ${N}"; line
  local file=""
  local -a found=()
  local f
  for f in "$MIGRATE_DIR/$MIGRATE_PREFIX"-*.tar.gz; do [[ -f "$f" ]] && found+=("$f"); done
  if [[ ${#found[@]} -gt 0 ]]; then
    echo "  РќР°Р№РґРµРЅРЅС‹Рµ Р°СЂС…РёРІС‹:"
    local i=1
    for f in "${found[@]}"; do
      printf "  %2d) %-46s %s\n" "$i" "$(basename "$f")" "$(du -h "$f" 2>/dev/null | cut -f1)"
      i=$((i+1))
    done
    echo
    local pick=""
    ask pick "РќРѕРјРµСЂ Р°СЂС…РёРІР° (0 вЂ” РѕС‚РјРµРЅР°)" "1" '^[0-9]+$'
    [[ "$pick" == "0" ]] && { pause; return 0; }
    file=$(printf '%s\n' "${found[@]}" | sed -n "${pick}p")
  else
    ask file "РџСѓС‚СЊ Рє Р°СЂС…РёРІСѓ" "$MIGRATE_DIR/$MIGRATE_PREFIX.tar.gz" '^/.+'
  fi
  [[ -f "$file" ]] || { err "РђСЂС…РёРІ РЅРµ РЅР°Р№РґРµРЅ: $file"; pause; return 1; }

  # С†РµР»РѕСЃС‚РЅРѕСЃС‚СЊ: РµСЃР»Рё СЂСЏРґРѕРј РµСЃС‚СЊ .sha256 вЂ” СЃРІРµСЂСЏРµРј РѕР±СЏР·Р°С‚РµР»СЊРЅРѕ
  local sha_file="$file.sha256"
  if [[ -f "$sha_file" ]]; then
    local want got
    want=$(cut -d' ' -f1 "$sha_file" 2>/dev/null)
    got=$(sha256sum "$file" 2>/dev/null | cut -d' ' -f1)
    if [[ "$want" != "$got" ]]; then
      err "sha256 РЅРµ СЃРѕРІРїР°Р» вЂ” Р°СЂС…РёРІ РїРѕРІСЂРµР¶РґС‘РЅ РёР»Рё РїРѕРґРјРµРЅС‘РЅ"
      echo "    РѕР¶РёРґР°Р»РѕСЃСЊ: $want"
      echo "    РїРѕР»СѓС‡РµРЅРѕ:  $got"
      pause; return 1
    fi
    log "sha256 СЃРѕРІРїР°Р»"
  else
    warn "Р¤Р°Р№Р» .sha256 СЂСЏРґРѕРј РѕС‚СЃСѓС‚СЃС‚РІСѓРµС‚ вЂ” С†РµР»РѕСЃС‚РЅРѕСЃС‚СЊ РЅРµ РїСЂРѕРІРµСЂРµРЅР°"
  fi

  # РЎРїРёСЃРѕРє Р±РµСЂС‘Рј Р¦Р•Р›РРљРћРњ Р±РµР· РїР°Р№РїР°: РїРѕРґ РіР»РѕР±Р°Р»СЊРЅС‹Рј pipefail
  # `tar tzf | head -5` РґР°С‘С‚ tar SIGPIPE (141) в†’ РїРѕРґСЃС‚Р°РЅРѕРІРєР° В«РїР°РґР°РµС‚В»,
  # С…РѕС‚СЏ Р°СЂС…РёРІ С†РµР»С‹Р№ (538 Р·Р°РїРёСЃРµР№ РІ С‚РµСЃС‚Рµ). head РґР»СЏ РїРѕРєР°Р·Р° вЂ” СѓР¶Рµ РїРѕ herestring.
  local tlist=""
  if ! tlist=$(tar tzf "$file" 2>/dev/null); then
    err "РђСЂС…РёРІ РЅРµ С‡РёС‚Р°РµС‚СЃСЏ"; pause; return 1
  fi
  log "РЎРѕРґРµСЂР¶РёРјРѕРµ (РїРµСЂРІС‹Рµ СЃС‚СЂРѕРєРё):"; head -5 <<<"$tlist" | sed 's/^/    /'

  local go=""
  askyn go "Р Р°СЃРїР°РєРѕРІР°С‚СЊ РІ / (С‚РµРєСѓС‰РёРµ РїР°РЅРµР»СЊ, nginx Рё СЃРµСЂС‚С‹ Р±СѓРґСѓС‚ Р·Р°РјРµРЅРµРЅС‹)?" "y"
  [[ "$go" == true ]] || { pause; return 0; }
  audit "migrate: СЂР°СЃРїР°РєРѕРІРєР° $(basename "$file")"

  auto_backup_stack >/dev/null 2>&1 || true
  log "РћСЃС‚Р°РЅРѕРІРєР° СЃР»СѓР¶Р±вЂ¦"
  systemctl stop x-ui 2>/dev/null || true
  systemctl stop nginx 2>/dev/null || true
  systemctl stop tg-stack-bot 2>/dev/null || true
  [[ -n "$ADG_SERVICE" ]] && systemctl stop "$ADG_SERVICE" 2>/dev/null || true

  local _pre_db=""
  if [[ -f "$XUI_DB" ]]; then
    sqlite3 "$XUI_DB" "PRAGMA wal_checkpoint(TRUNCATE);" >/dev/null 2>&1 || true
    rm -f "${XUI_DB}-wal" "${XUI_DB}-shm" 2>/dev/null || true
    _pre_db="$MIGRATE_DIR/pre-unpack-x-ui.db.$(date +%Y%m%d-%H%M%S)"
    cp -a "$XUI_DB" "$_pre_db" 2>/dev/null || _pre_db=""
  fi

  if ! tar xzf "$file" -C / -p 2>/dev/null; then
    err "Р Р°СЃРїР°РєРѕРІРєР° РЅРµ СѓРґР°Р»Р°СЃСЊ вЂ” СЃР»СѓР¶Р±С‹ РѕСЃС‚Р°СЋС‚СЃСЏ РѕСЃС‚Р°РЅРѕРІР»РµРЅРЅС‹РјРё, СЃРѕСЃС‚РѕСЏРЅРёРµ СЃРјРѕС‚СЂРё РІС‹С€Рµ"
    pause; return 1
  fi
  log "Р¤Р°Р№Р»С‹ СЂР°СЃРїР°РєРѕРІР°РЅС‹"

  # СЃРёРјР»РёРЅРєРё nginx: РІ Р°СЂС…РёРІРµ РјРѕРіР»Рё Р±С‹С‚СЊ, РЅРѕ РїРµСЂРµСЃРѕР±РµСЂС‘Рј РЅР° РІСЃСЏРєРёР№ СЃР»СѓС‡Р°Р№
  mkdir -p "$NGINX_SITES_DIR" "$NGINX_STREAM_DIR" 2>/dev/null || true
  if [[ -f "$STACK_CONF" ]]; then
    ln -sf "$STACK_CONF" "$STACK_LINK" 2>/dev/null || cp -f "$STACK_CONF" "$STACK_LINK" 2>/dev/null || true
  fi
  # РґРёСЃС‚СЂРёР±СѓС‚РёРІРЅС‹Р№ default-СЃР°Р№С‚ РєРѕРЅС„Р»РёРєС‚СѓРµС‚ СЃРѕ stack.conf (РѕР±Р° РѕР±СЉСЏРІР»СЏСЋС‚
  # default_server РЅР° :80): РїСЂРё РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєРµ РїР°РєРµС‚Р° nginx symlink В«defaultВ»
  # РІРѕР·РІСЂР°С‰Р°РµС‚СЃСЏ, Рё nginx -t РїРѕСЃР»Рµ СЂР°СЃРїР°РєРѕРІРєРё РїР°РґР°РµС‚. РЈР±РёСЂР°РµРј.
  if [[ -f "$STACK_CONF" && ( -e /etc/nginx/sites-enabled/default || -L /etc/nginx/sites-enabled/default ) ]]; then
    rm -f /etc/nginx/sites-enabled/default
    log "РЈР±СЂР°РЅ РґРёСЃС‚СЂРёР±СѓС‚РёРІРЅС‹Р№ sites-enabled/default вЂ” РєРѕРЅС„Р»РёРєС‚РѕРІР°Р» СЃРѕ stack.conf (default_server :80)"
  fi
  # sni-router: РµСЃР»Рё available-С„Р°Р№Р» РµСЃС‚СЊ, Р° enabled-СЃСЃС‹Р»РєРё РЅРµС‚ вЂ” РІРѕСЃСЃС‚Р°РЅР°РІР»РёРІР°РµРј
  if [[ -f /etc/nginx/streams-available/sni-router.conf && ! -e /etc/nginx/streams-enabled/sni-router.conf ]]; then
    ln -sf /etc/nginx/streams-available/sni-router.conf /etc/nginx/streams-enabled/sni-router.conf 2>/dev/null || true
  fi

  # РїСЂР°РІР°: РїСЂРёРІР°С‚РЅС‹Р№ РєР»СЋС‡ Рё Р‘Р” С‚РѕР»СЊРєРѕ root
  [[ -f "$XUI_DB" ]] && chown root:root "$XUI_DB" 2>/dev/null || true
  chmod 600 "$XUI_DB" 2>/dev/null || true
  chmod -R 600 /etc/letsencrypt/archive /etc/letsencrypt/keys 2>/dev/null || true

  migrate_db_verify "$_pre_db"

  systemctl daemon-reload 2>/dev/null || true
  systemctl enable x-ui >/dev/null 2>&1 || true

  if nginx -t >/dev/null 2>&1; then
    systemctl start nginx && log "nginx Р·Р°РїСѓС‰РµРЅ"
  else
    err "nginx -t РїРѕСЃР»Рµ СЂР°СЃРїР°РєРѕРІРєРё РЅРµ РїСЂРѕС€С‘Р»:"
    nginx -t 2>&1 | tail -6 | sed 's/^/    /'
    warn "  С‡Р°С‰Рµ РІСЃРµРіРѕ СЌС‚Рѕ РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РёР№ РјРѕРґСѓР»СЊ stream: apt-get install -y libnginx-mod-stream"
  fi
  systemctl start x-ui 2>/dev/null || true
  systemctl start fail2ban 2>/dev/null || true
  if [[ -f /etc/systemd/system/tg-stack-bot.service ]]; then
    systemctl enable tg-stack-bot >/dev/null 2>&1 || true
    systemctl start tg-stack-bot 2>/dev/null || true
  fi

  # UFW: Р°СЂС…РёРІ РІРµСЂРЅСѓР» РєРѕРЅС„РёРіРё (user.rules/ufw.conf), РЅРѕ С„РёР»СЊС‚СЂР°С†РёСЋ РІ СЏРґСЂРµ
  # РІРєР»СЋС‡Р°РµС‚ С‚РѕР»СЊРєРѕ СЏРІРЅРѕРµ СЂРµС€РµРЅРёРµ. Р’РєР»СЋС‡Р°РµРј Р±РµР·РѕРїР°СЃРЅРѕ: С‚РѕР»СЊРєРѕ РµСЃР»Рё РІ Р°СЂС…РёРІРµ
  # UFW Р±С‹Р» РІРєР»СЋС‡С‘РЅ (ENABLED=yes), РѕРЅ РµС‰С‘ РЅРµ Р°РєС‚РёРІРµРЅ Рё РІ РїСЂР°РІРёР»Р°С… РµСЃС‚СЊ allow
  # РґР»СЏ С‚РµРєСѓС‰РµРіРѕ SSH-РїРѕСЂС‚Р° вЂ” РёРЅР°С‡Рµ РїСЂРµРґСѓРїСЂРµР¶РґРµРЅРёРµ РІРјРµСЃС‚Рѕ РІРєР»СЋС‡РµРЅРёСЏ.
  if command -v ufw >/dev/null 2>&1 && grep -qs '^ENABLED=yes' /etc/ufw/ufw.conf; then
    if ufw status 2>/dev/null | grep -q 'Status: active'; then
      log "UFW СѓР¶Рµ Р°РєС‚РёРІРµРЅ"
    else
      local -a _ufw_ports=()
      [[ -n "${SSH_CONNECTION:-}" ]] && _ufw_ports+=("$(awk '{print $4}' <<<"$SSH_CONNECTION")")
      if ((${#_ufw_ports[@]} == 0)); then
        # Р·Р°РїСѓС‰РµРЅРѕ РЅРµ РїРѕ SSH (РєРѕРЅСЃРѕР»СЊ/VNC) вЂ” РІСЃРµ РІРЅРµС€РЅРёРµ СЃРѕРєРµС‚С‹ sshd
        # (loopback Рё X11-С„РѕСЂРІР°СЂРґРёРЅРі РЅРµ СЃС‡РёС‚Р°РµРј: ufw loopback РЅРµ С„РёР»СЊС‚СЂСѓРµС‚)
        local _up
        while IFS= read -r _up; do
          [[ -n "$_up" ]] || continue
          [[ " ${_ufw_ports[*]-} " == *" $_up "* ]] || _ufw_ports+=("$_up")
        done < <(ss -tlnp 2>/dev/null | awk '/sshd/ && $4 !~ /^(127\.|\[::1\]|::1)/ {n=split($4,a,":"); print a[n]}' | sort -un)
      fi
      local _added="" _ufw_bad=0
      _added=$(ufw show added 2>/dev/null) || _added=""
      for _up in "${_ufw_ports[@]}"; do
        if ! grep -qE "^ufw (allow|limit).*[^0-9:]${_up}(/tcp)?([[:space:]']|$)" <<<"$_added"; then
          warn "  РІ РїСЂР°РІРёР»Р°С… UFW РЅРµС‚ allow РґР»СЏ SSH-РїРѕСЂС‚Р° ${_up} вЂ” РЅРµ РІРєР»СЋС‡Р°СЋ, С‡С‚РѕР±С‹ РЅРµ РѕС‚СЂРµР·Р°С‚СЊ СЃРµСЃСЃРёСЋ"
          warn "  РІСЂСѓС‡РЅСѓСЋ: ufw allow ${_up}/tcp && ufw --force enable"
          _ufw_bad=1
        fi
      done
      if ((${#_ufw_ports[@]} == 0)); then
        warn "  SSH-РїРѕСЂС‚ РЅРµ РѕРїСЂРµРґРµР»С‘РЅ вЂ” UFW РЅРµ РІРєР»СЋС‡Р°СЋ (РІСЂСѓС‡РЅСѓСЋ: ufw --force enable)"
      elif ((_ufw_bad == 0)); then
        if ufw --force enable >/dev/null 2>&1; then
          log "UFW РІРєР»СЋС‡С‘РЅ (РїСЂР°РІРёР»Р° РёР· Р°СЂС…РёРІР°; SSH-РїРѕСЂС‚ РїСЂРѕРІРµСЂРµРЅ)"
        else
          warn "  РІРєР»СЋС‡РёС‚СЊ UFW РЅРµ СѓРґР°Р»РѕСЃСЊ вЂ” РІСЂСѓС‡РЅСѓСЋ: ufw --force enable"
        fi
      fi
    fi
  fi

  stack_mark_configured || true

  sleep 2
  line
  if systemctl is-active --quiet x-ui && systemctl is-active --quiet nginx; then
    ok "Р Р°СЃРїР°РєРѕРІРєР° Р·Р°РІРµСЂС€РµРЅР°, РїР°РЅРµР»СЊ Рё nginx РїРѕРґРЅСЏС‚С‹"
  else
    warn "Р Р°СЃРїР°РєРѕРІРєР° Р·Р°РІРµСЂС€РµРЅР°, РЅРѕ РЅРµ РІСЃРµ СЃР»СѓР¶Р±С‹ Р°РєС‚РёРІРЅС‹ вЂ” СЃРјРѕС‚СЂРё Рї.6 (РїСЂРѕРІРµСЂРєР°)"
  fi
  echo "  РћР±СЏР·Р°С‚РµР»СЊРЅС‹Р№ СЃР»РµРґСѓСЋС‰РёР№ С€Р°Рі: 8 в†’ 4 (DNS) Рё 8 в†’ 5 (РїРµСЂРµРІС‹РїСѓСЃРє СЃРµСЂС‚РѕРІ)."
  line
  pause
}

# РџСЂРѕРІРµСЂРєР° x-ui.db РїРѕСЃР»Рµ СЂР°СЃРїР°РєРѕРІРєРё: С†РµР»РѕСЃС‚РЅРѕСЃС‚СЊ (PRAGMA integrity_check) Рё
# СЃРІРµСЂРєР° С‡РёСЃР»Р° РёРЅР±Р°СѓРЅРґРѕРІ/РєР»РёРµРЅС‚РѕРІ СЃРѕ СЃРЅРёРјРєРѕРј РґРѕ СЂР°СЃРїР°РєРѕРІРєРё. РўРѕР»СЊРєРѕ РѕС‚С‡С‘С‚:
# Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРѕРіРѕ РІРѕСЃСЃС‚Р°РЅРѕРІР»РµРЅРёСЏ РЅРµС‚ вЂ” СЂРµС€РµРЅРёРµ Р·Р° С‡РµР»РѕРІРµРєРѕРј (РїСѓС‚Рё РїРµС‡Р°С‚Р°РµРј).
migrate_db_verify() { # $1 вЂ” РїСѓС‚СЊ Рє СЃРЅРёРјРєСѓ x-ui.db РґРѕ СЂР°СЃРїР°РєРѕРІРєРё (РјРѕР¶РµС‚ Р±С‹С‚СЊ РїСѓСЃС‚)
  local pre_db="${1:-}"
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] || return 0
  sqlite3 "$XUI_DB" "PRAGMA wal_checkpoint(TRUNCATE);" >/dev/null 2>&1 || true
  local ic db_in db_cl pre_in="" pre_cl=""
  ic=$(sqlite3 -readonly "$XUI_DB" "PRAGMA integrity_check;" 2>/dev/null) || ic=""
  db_in=$(sqlite3 -readonly "$XUI_DB" "SELECT COUNT(*) FROM inbounds;" 2>/dev/null) || db_in=""
  db_cl=$(sqlite3 -readonly "$XUI_DB" "SELECT COUNT(*) FROM client_traffics;" 2>/dev/null) || db_cl=""
  if [[ -n "$pre_db" && -f "$pre_db" ]]; then
    pre_in=$(sqlite3 -readonly "$pre_db" "SELECT COUNT(*) FROM inbounds;" 2>/dev/null) || pre_in=""
    pre_cl=$(sqlite3 -readonly "$pre_db" "SELECT COUNT(*) FROM client_traffics;" 2>/dev/null) || pre_cl=""
  fi
  if [[ "$ic" == "ok" ]]; then
    log "x-ui.db: С†РµР»РѕСЃС‚РЅРѕСЃС‚СЊ OK ($(du -h "$XUI_DB" 2>/dev/null | awk '{print $1}'))"
  else
    err "x-ui.db: integrity_check РќР• РїСЂРѕС€С‘Р»${ic:+: $ic}"
    warn "  СЃРЅРёРјРѕРє РґРѕ СЂР°СЃРїР°РєРѕРІРєРё: ${pre_db:-вЂ” РЅРµС‚}; СЃРјРѕС‚СЂРё Рї.8в†’6 Рё Р±СЌРєР°РїС‹ (СЂР°Р·РґРµР» 5)"
  fi
  if [[ -n "$pre_db" && -f "$pre_db" ]]; then
    log "x-ui.db: РёРЅР±Р°СѓРЅРґРѕРІ ${db_in:-?} (РґРѕ СЂР°СЃРїР°РєРѕРІРєРё: ${pre_in:-?}), РєР»РёРµРЅС‚РѕРІ ${db_cl:-?} (РґРѕ: ${pre_cl:-?})"
    if [[ -n "$pre_in" && -n "$db_in" && "$db_in" -lt "$pre_in" ]] \
       || [[ -n "$pre_cl" && -n "$db_cl" && "$db_cl" -lt "$pre_cl" ]]; then
      warn "  СЂР°СЃРїР°РєРѕРІР°РЅРЅР°СЏ Р‘Р” СЃРѕРґРµСЂР¶РёС‚ РњР•РќР¬РЁР• РґР°РЅРЅС‹С…, С‡РµРј Р±С‹Р»Рѕ РґРѕ СЂР°СЃРїР°РєРѕРІРєРё вЂ” РІРѕР·РјРѕР¶РЅРѕ, Р°СЂС…РёРІ СЃС‚Р°СЂРµРµ СЃРѕСЃС‚РѕСЏРЅРёСЏ"
    fi
  else
    log "x-ui.db: РёРЅР±Р°СѓРЅРґРѕРІ ${db_in:-?}, РєР»РёРµРЅС‚РѕРІ ${db_cl:-?} (СЃРЅРёРјРєР° РґРѕ СЂР°СЃРїР°РєРѕРІРєРё РЅРµС‚ вЂ” СЃРІРµСЂРёС‚СЊ РЅРµ СЃ С‡РµРј)"
  fi
}

# в”Ђв”Ђв”Ђ 4. РџР РћР’Р•Р РљРђ DNS в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
migrate_dns_check() {
  line; echo -e "${B}   4) РџР РћР’Р•Р РљРђ РџР РР’РЇР—РљР Р”РћРњР•РќРћР’ Рљ РќРћР’РћРњРЈ IP${N}"; line
  local my_ip=""
  my_ip=$(server_ip4 2>/dev/null || curl -4 -s --max-time 6 ifconfig.me 2>/dev/null | tr -d '[:space:]' || true)
  [[ -n "$my_ip" ]] || { err "РќРµ СѓРґР°Р»РѕСЃСЊ РѕРїСЂРµРґРµР»РёС‚СЊ РІРЅРµС€РЅРёР№ IP СЌС‚РѕРіРѕ СЃРµСЂРІРµСЂР°"; pause; return 1; }
  echo "  Р’РЅРµС€РЅРёР№ IP СЌС‚РѕРіРѕ СЃРµСЂРІРµСЂР°: ${B}$my_ip${N}"
  echo

  local -a doms=()
  mapfile -t doms < <(migrate_collect_domains)
  [[ ${#doms[@]} -gt 0 ]] || { warn "Р”РѕРјРµРЅС‹ РЅРµ РЅР°Р№РґРµРЅС‹ (Р‘Р” РїСѓСЃС‚Р°? СЂР°СЃРїР°РєРѕРІРєР° РЅРµ СЃРґРµР»Р°РЅР°?)"; pause; return 1; }

  local d resolved ok_cnt=0 bad=0
  local -a bad_list=()
  printf '  %-40s %s\n' "Р”РћРњР•Рќ" "Р Р•Р—РћР›Р’"
  for d in "${doms[@]}"; do
    resolved=$(dig +short A "$d" @1.1.1.1 2>/dev/null | grep -E '^[0-9.]+$' | tail -1 || true)
    [[ -z "$resolved" ]] && resolved=$(dig +short A "$d" @8.8.8.8 2>/dev/null | grep -E '^[0-9.]+$' | tail -1 || true)
    if [[ "$resolved" == "$my_ip" ]]; then
      printf '  %-40s %s %s\n' "$d" "${G}вњ“${N}" "$resolved"
      ok_cnt=$((ok_cnt+1))
    else
      printf '  %-40s %s %s\n' "$d" "${R}вњ—${N}" "${resolved:-РЅРµС‚ A-Р·Р°РїРёСЃРё}"
      bad=$((bad+1)); bad_list+=("$d")
    fi
  done
  echo
  if (( bad == 0 )); then
    ok "Р’СЃРµ РґРѕРјРµРЅС‹ (${#doms[@]}) СѓРєР°Р·С‹РІР°СЋС‚ РЅР° СЌС‚РѕС‚ СЃРµСЂРІРµСЂ вЂ” РјРѕР¶РЅРѕ РїРµСЂРµРІС‹РїСѓСЃРєР°С‚СЊ СЃРµСЂС‚С‹"
  else
    warn "РќРµ РїРµСЂРµРєР»СЋС‡РµРЅРѕ: $bad РёР· ${#doms[@]}"
    echo "  РџРѕРєР° A-Р·Р°РїРёСЃРё РЅРµ РїРµСЂРµРєР»СЋС‡РµРЅС‹ РЅР° $my_ip, HTTP-01 РЅРµ РїСЂРѕР№РґС‘С‚ Рё СЃРµСЂС‚ РЅРµ РІС‹РїСѓСЃС‚РёС‚СЃСЏ."
    echo "  РџРµСЂРµРєР»СЋС‡Рё Р·Р°РїРёСЃРё РІ РїР°РЅРµР»Рё DNS РґРѕРјРµРЅР° (TTL РјРёРЅРёРјР°Р»СЊРЅС‹Р№), РґРѕР¶РґРёСЃСЊ TTL Рё РїРѕРІС‚РѕСЂРё."
    echo
    echo "  РќРµ РїРµСЂРµРєР»СЋС‡РµРЅС‹:"; printf '    %s\n' "${bad_list[@]}"
    echo
    echo "  РџСЂРѕРІРµСЂРёС‚СЊ РїРѕРІС‚РѕСЂРЅРѕ: 8 в†’ 4. РџСЂРёРЅСѓРґРёС‚РµР»СЊРЅРѕ (СЃС‚Р°СЂС‹Рµ СЃРµСЂС‚С‹ СѓР¶Рµ Р»РµР¶Р°С‚ Рё СЂР°Р±РѕС‡РёРµ)"
    echo "  РїР°РЅРµР»СЊ РїРѕРґРЅРёРјРµС‚СЃСЏ Рё С‚Р°Рє вЂ” РЅРѕ РѕР±РЅРѕРІР»РµРЅРёРµ СЃРµСЂС‚РѕРІ Р±СѓРґРµС‚ РїР°РґР°С‚СЊ."
  fi
  echo
  echo "  ${Y}РќРµ Р·Р°Р±С‹С‚СЊ:${N} СЃС‚Р°СЂС‹Р№ СЃРµСЂРІРµСЂ РќР• РІС‹РєР»СЋС‡Р°С‚СЊ РґРѕ РїРѕР»РЅРѕРіРѕ РїРµСЂРµРЅРѕСЃР° РєР»РёРµРЅС‚РѕРІ."
  line
  pause
}

# в”Ђв”Ђв”Ђ 5. РџР•Р Р•Р’Р«РџРЈРЎРљ РЎР•Р РўРР¤РРљРђРўРћР’ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
migrate_certs_reissue() {
  line; echo -e "${B}   5) РџР•Р Р•Р’Р«РџРЈРЎРљ РЎР•Р РўРР¤РРљРђРўРћР’${N}"; line
  local -a doms=()
  mapfile -t doms < <(migrate_collect_domains)
  [[ ${#doms[@]} -gt 0 ]] || { warn "Р”РѕРјРµРЅС‹ РЅРµ РЅР°Р№РґРµРЅС‹"; pause; return 1; }

  local my_ip=""
  my_ip=$(server_ip4 2>/dev/null || true)
  echo "  Р”РѕРјРµРЅС‹ РґР»СЏ СЃРµСЂС‚РѕРІ: ${#doms[@]}"
  echo "  Р›РёРјРёС‚ Let's Encrypt: 5 СЃРµСЂС‚РѕРІ РЅР° 168 С‡ вЂ” РїСЂРёРЅСѓРґРёС‚РµР»СЊРЅРѕРµ РѕР±РЅРѕРІР»РµРЅРёРµ РІСЃРµС… РјРѕР¶РµС‚"
  echo "  СѓРїРµСЂРµС‚СЊСЃСЏ РІ Р»РёРјРёС‚. РќРёР¶Рµ РІС‹Р±РѕСЂ."
  echo
  echo "  1) РўРѕР»СЊРєРѕ РѕС‚СЃСѓС‚СЃС‚РІСѓСЋС‰РёРµ/РёСЃС‚РµРєР°СЋС‰РёРµ (certbot СЂРµС€Р°РµС‚ СЃР°Рј) вЂ” Р±РµР·РѕРїР°СЃРЅРѕ"
  echo "  2) РџСЂРёРЅСѓРґРёС‚РµР»СЊРЅРѕ Р’РЎР• (--force-renewal) вЂ” РЅСѓР¶РЅРѕ РїСЂРё СЃРјРµРЅРµ IP, РЅРѕ РµСЃС‚ Р»РёРјРёС‚"
  echo "  3) РўРѕР»СЊРєРѕ РІС‹Р±СЂР°РЅРЅС‹Рµ РґРѕРјРµРЅС‹"
  local mode=""; ask mode "Р РµР¶РёРј" "1" '^[1-3]$'
  [[ -n "$my_ip" ]] || warn "Р’РЅРµС€РЅРёР№ IP РЅРµ РѕРїСЂРµРґРµР»С‘РЅ вЂ” DNS-РїСЂРѕРІРµСЂРєР° РІРЅСѓС‚СЂРё certbot РјРѕР¶РµС‚ Р»РѕР¶РЅРѕ СЂСѓРіР°С‚СЊСЃСЏ"

  local -a targets=()
  case "$mode" in
    1) targets=("${doms[@]}") ;;
    2) targets=("${doms[@]}") ;;
    3)
      local pick=""
      local i=1 d
      for d in "${doms[@]}"; do printf '  %2d) %s\n' "$i" "$d"; i=$((i+1)); done
      ask pick "РќРѕРјРµСЂР° С‡РµСЂРµР· РїСЂРѕР±РµР»" "" '^[0-9 ]+$'
      local n
      for n in $pick; do
        (( n >= 1 && n <= ${#doms[@]} )) && targets+=("${doms[$((n-1))]}")
      done
      ;;
  esac
  [[ ${#targets[@]} -gt 0 ]] || { warn "РќРёС‡РµРіРѕ РЅРµ РІС‹Р±СЂР°РЅРѕ"; pause; return 0; }

  le_email_load || true
  if [[ -z "$EMAIL" ]] && [[ -t 0 ]]; then
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$'
    le_email_save "$EMAIL" || true
  fi
  [[ -n "$EMAIL" ]] || { err "Email Let's Encrypt РЅРµ Р·Р°РґР°РЅ"; pause; return 1; }

  local go=""
  askyn go "Р—Р°РїСѓСЃС‚РёС‚СЊ РїРµСЂРµРІС‹РїСѓСЃРє РґР»СЏ ${#targets[@]} РґРѕРјРµРЅ(РѕРІ)?" "y"
  [[ "$go" == true ]] || { pause; return 0; }
  audit "migrate: РїРµСЂРµРІС‹РїСѓСЃРє СЃРµСЂС‚РѕРІ (${#targets[@]})"

  local d rc okc=0 failc=0
  local nginx_was=false
  systemctl is-active --quiet nginx 2>/dev/null && nginx_was=true
  if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q "Status: active"; then
    ufw allow 80/tcp >/dev/null 2>&1 || true
  fi
  mkdir -p /var/www/html 2>/dev/null || true

  for d in "${targets[@]}"; do
    local resolved=""
    resolved=$(dig +short A "$d" @1.1.1.1 2>/dev/null | grep -E '^[0-9.]+$' | tail -1 || true)
    if [[ -n "$my_ip" && "$resolved" != "$my_ip" ]]; then
      err "  $d в†’ ${resolved:-РЅРµС‚ A-Р·Р°РїРёСЃРё}, Р° СЃРµСЂРІРµСЂ $my_ip вЂ” РІС‹РїСѓСЃРє РїРѕС‡С‚Рё РЅР°РІРµСЂРЅСЏРєР° СѓРїР°РґС‘С‚"
    fi
    local out=""
    if [[ "$mode" == "2" && -d "/etc/letsencrypt/live/$d" ]]; then
      log "  force-renew: $d"
      out=$(certbot renew --force-renewal --cert-name "$d" --non-interactive 2>&1 || true)
      grep -qE "Congratulations|Successfully renewed|not yet due" <<<"$out" && { okc=$((okc+1)); } || { failc=$((failc+1)); echo "$out" | tail -4 | sed 's/^/    /'; }
      continue
    fi
    if cert_issue "$d"; then
      okc=$((okc+1))
    else
      failc=$((failc+1))
    fi
  done

  [[ "$nginx_was" == true ]] || systemctl start nginx 2>/dev/null || true
  systemctl reload nginx 2>/dev/null || true
  line
  ok "РЈСЃРїРµС€РЅРѕ: $okc   РџСЂРѕРІР°Р»РѕРІ: $failc"
  [[ $failc -gt 0 ]] && warn "  РїРѕ РїСЂРѕРІР°Р»Р°Рј СЃРјРѕС‚СЂРё РїСЂРёС‡РёРЅСѓ РІС‹С€Рµ: С‡Р°С‰Рµ DNS РµС‰С‘ РЅРµ РїРµСЂРµРєР»СЋС‡С‘РЅ РёР»Рё Р»РёРјРёС‚ LE"
  [[ -d /etc/letsencrypt/renewal ]] && certbot renew --dry-run 2>&1 | tail -3 | sed 's/^/  dry-run: /'
  line
  pause
}

# в”Ђв”Ђв”Ђ 6. РџР РћР’Р•Р РљРђ РџРћРЎР›Р• РџР•Р Р•Р•Р—Р”Рђ в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
migrate_postcheck() {
  line; echo -e "${B}   6) РџР РћР’Р•Р РљРђ РџРћРЎР›Р• РџР•Р Р•Р•Р—Р”Рђ${N}"; line
  local fails=0
  check() {  # $1 = РѕРїРёСЃР°РЅРёРµ, $2 = РєРѕРјР°РЅРґР°-СЃС‚СЂРѕРєР°
    if eval "$2" >/dev/null 2>&1; then printf '  %s %s\n' "${G}вњ“${N}" "$1"
    else printf '  %s %s\n' "${R}вњ—${N}" "$1"; fails=$((fails+1)); fi
  }
  detect_env
  check "x-ui Р°РєС‚РёРІРµРЅ" "systemctl is-active --quiet x-ui"
  check "nginx Р°РєС‚РёРІРµРЅ" "systemctl is-active --quiet nginx"
  check "nginx -t РїСЂРѕС…РѕРґРёпїЅпїЅ" "nginx -t"
  check "x-ui.db С‡РёС‚Р°РµС‚СЃСЏ" "sqlite3 '$XUI_DB' 'SELECT COUNT(*) FROM inbounds;'"
  check "443 СЃР»СѓС€Р°РµС‚ nginx" "ss -tlnH 'sport = :443' | grep -q ."
  check "UFW Р°РєС‚РёРІРµРЅ" "ufw status | grep -q 'Status: active'"
  check "fail2ban Р°РєС‚РёРІРµРЅ" "systemctl is-active --quiet fail2ban"
  if [[ -f /etc/systemd/system/tg-stack-bot.service ]]; then
    if systemctl is-enabled --quiet tg-stack-bot 2>/dev/null; then
      check "Р±РѕС‚ Р°РєС‚РёРІРµРЅ" "systemctl is-active --quiet tg-stack-bot"
    else
      printf '  %s Р±РѕС‚ РІС‹РєР»СЋС‡РµРЅ (disabled) вЂ” РЅР°РјРµСЂРµРЅРЅРѕ, РЅРµ РїСЂРѕРІР°Р»\n' "${Y}вЂ“${N}"
    fi
  fi

  local d doms ip4
  mapfile -t doms < <(migrate_collect_domains)
  for d in "${doms[@]}"; do
    [[ -f "/etc/letsencrypt/live/$d/fullchain.pem" ]] || continue
    ip4=$(openssl x509 -noout -enddate -in "/etc/letsencrypt/live/$d/fullchain.pem" 2>/dev/null | cut -d= -f2)
    if openssl x509 -noout -checkend 604800 -in "/etc/letsencrypt/live/$d/fullchain.pem" >/dev/null 2>&1; then
      printf '  %s СЃРµСЂС‚ %s (РґРѕ %s)\n' "${G}вњ“${N}" "$d" "$ip4"
    else
      printf '  %s СЃРµСЂС‚ %s РРЎРўР•РљРђР•Рў/РёСЃС‚С‘Рє (%s)\n' "${R}вњ—${N}" "$d" "$ip4"; fails=$((fails+1))
    fi
  done

  # decoy-РїСЂРѕРІРµСЂРєР° РїРѕ РєР°Р¶РґРѕРјСѓ РґРѕРјРµРЅСѓ СЃ СЃРµСЂС‚РѕРј: 200 РґР»СЏ Р±СЂР°СѓР·РµСЂРЅРѕРіРѕ UA
  local ua="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124 Safari/537.36"
  for d in "${doms[@]}"; do
    local code
    code=$(curl -sk --max-time 8 --resolve "$d:443:127.0.0.1" -A "$ua" "https://$d/" -o /dev/null -w '%{http_code}' 2>/dev/null || true)
    if [[ "$code" =~ ^(2|3) ]]; then printf '  %s decoy %s (%s)\n' "${G}вњ“${N}" "$d" "$code"
    else printf '  %s decoy %s (%s)\n' "${Y}!${N}" "$d" "${code:-РЅРµС‚ РѕС‚РІРµС‚Р°}"; fi
  done

  line
  if (( fails == 0 )); then ok "РљСЂРёС‚РёС‡РЅС‹С… РїСЂРѕРІР°Р»РѕРІ РЅРµС‚"
  else err "РџСЂРѕРІР°Р»РѕРІ: $fails вЂ” СЃРјРѕС‚СЂРё СЃС‚СЂРѕРєРё СЃ вњ— РІС‹С€Рµ"; fi
  echo "  ${Y}РџСЂРѕРІРµСЂРєРё decoy СЃ В«!В» вЂ” РЅРµ РєСЂРёС‚РёС‡РЅС‹, РЅРѕ РїРѕСЃРјРѕС‚СЂРё РіР»Р°Р·Р°РјРё РІ Р±СЂР°СѓР·РµСЂРµ.${N}"
  line
  pause
}

# в”Ђв”Ђв”Ђ 7. Р§Р•Рљ-Р›РРЎРў в”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђв”Ђ
migrate_checklist() {
  line; echo -e "${B}   Р§Р•Рљ-Р›РРЎРў РџР•Р Р•Р•Р—Р”Рђ${N}"; line
  echo "  РџРѕСЂСЏРґРѕРє РѕР±СЏР·Р°С‚РµР»РµРЅ, С€Р°РіРё РЅРµ РїРµСЂРµСЃС‚Р°РІР»СЏС‚СЊ:"
  echo
  echo "   РЎРўРђР Р«Р™ СЃРµСЂРІРµСЂ:"
  echo "    1. 8 в†’ 1 вЂ” Р°СЂС…РёРІ. РЎРєРѕРїРёСЂРѕРІР°С‚СЊ Р°СЂС…РёРІ Рё .sha256 РЅР° РЅРѕРІС‹Р№ СЃРµСЂРІРµСЂ."
  echo
  echo "   РќРћР’Р«Р™ СЃРµСЂРІРµСЂ (РїРѕ SSH):"
  echo "    2. 8 в†’ 2 вЂ” РїР»Р°С‚С„РѕСЂРјР°: РїР°РєРµС‚С‹, nginx, РїР°РЅРµР»СЊ. Р”Рѕ СЂР°СЃРїР°РєРѕРІРєРё."
  echo "    3. 8 в†’ 3 вЂ” СЂР°СЃРїР°РєРѕРІРєР° (sha256 СЃРІРµСЂСЏРµС‚СЃСЏ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё)."
  echo "    4. 8 в†’ 4 вЂ” DNS: Р’РЎР• РґРѕРјРµРЅС‹ РѕР±СЏР·Р°РЅС‹ СѓРєР°Р·С‹РІР°С‚СЊ РЅР° РЅРѕРІС‹Р№ IP."
  echo "    5. 8 в†’ 5 вЂ” РїРµСЂРµРІС‹РїСѓСЃРє СЃРµСЂС‚РѕРІ (РїРѕСЃР»Рµ РїРµСЂРµРєР»СЋС‡РµРЅРёСЏ DNS)."
  echo "    6. 8 в†’ 6 вЂ” РїСЂРѕРІРµСЂРєР°: СЃР»СѓР¶Р±С‹, СЃРµСЂС‚С‹, decoy."
  echo
  echo "  ${Y}Р’Р°Р¶РЅРѕ:${N}"
  echo "   вЂў РґРѕРјРµРЅС‹ РїРµСЂРµРєР»СЋС‡Р°С‚СЊ РІ РїР°РЅРµР»Рё DNS РґРѕРјРµРЅР°, TTL Р·Р°СЂР°РЅРµРµ СѓРјРµРЅСЊС€РёС‚СЊ"
  echo "   вЂў СЃС‚Р°СЂС‹Р№ СЃРµСЂРІРµСЂ РЅРµ РІС‹РєР»СЋС‡Р°С‚СЊ, РїРѕРєР° РєР»РёРµРЅС‚С‹ РЅРµ РїРµСЂРµРµРґСѓС‚"
  echo "   вЂў РїСЂРёРІР°С‚РЅС‹Рµ РєР»СЋС‡Рё Рё Р‘Р” РІ Р°СЂС…РёРІРµ вЂ” РєРѕРїРёСЂРѕРІР°С‚СЊ С‚РѕР»СЊРєРѕ РїРѕ SSH"
  echo "   вЂў Р»РёРјРёС‚ Let's Encrypt 5 СЃРµСЂС‚РѕРІ/168С‡ вЂ” РїСЂРёРЅСѓРґРёС‚РµР»СЊРЅС‹Р№ РїРµСЂРµРІС‹РїСѓСЃРє РІСЃРµС… С‚СЂР°С‚РёС‚ РµРіРѕ"
  echo
  local n=0
  [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && n=$(sqlite3 -cmd ".timeout 1000" "$XUI_DB" "SELECT COUNT(*) FROM inbounds;" 2>/dev/null || echo 0)
  echo "  РЎРѕСЃС‚РѕСЏРЅРёРµ: РёРЅР±Р°СѓРЅРґРѕРІ РІ Р‘Р”: $n | РґРѕРјРµРЅРѕРІ: $(migrate_collect_domains | wc -l) | Р°СЂС…РёРІРѕРІ РІ $MIGRATE_DIR: $(ls -1 "$MIGRATE_DIR"/$MIGRATE_PREFIX-*.tar.gz 2>/dev/null | wc -l)"
  line
  pause
}

migrate_menu() {
  while :; do
    clear
    line; echo -e "${B}   РџР•Р Р•Р•Р—Р” РќРђ Р”Р РЈР“РћР™ РЎР•Р Р’Р•Р ${N}"; line
    echo "  1) рџ“¦ Р­РєСЃРїРѕСЂС‚: СЃРѕР±СЂР°С‚СЊ Р°СЂС…РёРІ (РЅР° РЎРўРђР РћРњ СЃРµСЂРІРµСЂРµ)"
    echo "  2) рџ§± РџР»Р°С‚С„РѕСЂРјР°: РїР°РєРµС‚С‹, nginx, РїР°РЅРµР»СЊ (РЅР° РќРћР’РћРњ)"
    echo "  3) рџ“‚ Р Р°СЃРїР°РєРѕРІР°С‚СЊ Р°СЂС…РёРІ (РЅР° РќРћР’РћРњ)"
    echo "  4) рџЊђ РџСЂРѕРІРµСЂРёС‚СЊ DNS: РґРѕРјРµРЅС‹ в†’ IP СЌС‚РѕРіРѕ СЃРµСЂРІРµСЂР°"
    echo "  5) рџ”ђ РџРµСЂРµРІС‹РїСѓСЃС‚РёС‚СЊ СЃРµСЂС‚РёС„РёРєР°С‚С‹"
    echo "  6) рџ©є РџСЂРѕРІРµСЂРєР° РїРѕСЃР»Рµ РїРµСЂРµРµР·РґР°"
    echo "  7) рџ“‹ Р§РµРє-Р»РёСЃС‚ РїРµСЂРµРµР·РґР°"
    echo "  0) РќР°Р·Р°Рґ"
    line
    local c=""
    read -rp "$(echo -e "${Y}рџ‘‰${N} Р’С‹Р±РѕСЂ: ")" c || c="0"
    case "$c" in
      1) migrate_export ;;
      2) migrate_bootstrap ;;
      3) migrate_unpack ;;
      4) migrate_dns_check ;;
      5) migrate_certs_reissue ;;
      6) migrate_postcheck ;;
      7) migrate_checklist ;;
      0) return 0 ;;
      *) sleep 1 ;;
    esac
  done
}

# =====================================================================
# РџРћР›РќР«Р™ РђР’РўРћРџРћР”РЄРЃРњ РџРћРЎР›Р• Р§РРЎРўРћР™ РЈРЎРўРђРќРћР’РљР РџРђРќР•Р›Р
# (РёРЅР±Р°СѓРЅРґС‹ в†’ initial_setup в†’ UFW в†’ РёС‚РѕРіРѕРІР°СЏ СЃРІРѕРґРєР°)
# =====================================================================
auto_full_setup() {
  local base="${PANEL_DOMAIN:-$(xui_get webDomain 2>/dev/null || true)}"
  [[ -z "$base" || "$base" == "panel.example.com" ]] && { err "Р”РѕРјРµРЅ РїР°РЅРµР»Рё РЅРµРёР·РІРµСЃС‚РµРЅ вЂ” Р°РІС‚РѕРїРѕРґСЉС‘Рј РїСЂРѕРїСѓС‰РµРЅ"; return 1; }
  detect_env
  line; echo -e "${B}   РђР’РўРћРџРћР”РЄРЃРњ РЎРўР•РљРђ (С‡РёСЃС‚Р°СЏ СѓСЃС‚Р°РЅРѕРІРєР°)${N}"; line

  # --- 1+2+3) Р•Р”РРќР«Р™ РїСѓС‚СЊ РІРѕРїСЂРѕСЃРѕРІ: РїР°РЅРµР»СЊ в†’ AdGuard в†’ Р·Р°РіР»СѓС€РєР° РїР°РЅРµР»Рё
  ask_panel_creds || return 1
  local u_port="$U_PANEL_PORT" u_subport="$U_SUB_PORT" u_path="$U_PANEL_PATH" u_subpath="$U_SUB_PATH"
  ask_adguard_and_decoy
  local pdecoy="$PDECOY"
  le_email_load || true
  [[ "$EMAIL" == "none" || ! "$EMAIL" =~ ^[^@]+@[^@]+\.[^@]+$ ]] && EMAIL=""
  if [[ -z "$EMAIL" ]]; then
    ask EMAIL "Email РґР»СЏ Let's Encrypt" "" '^[^@]+@[^@]+\.[^@]+$' || return 1
    le_email_save "$EMAIL" || return 1
  fi

  # РЎРЅР°С‡Р°Р»Р° РІС‹Р±РёСЂР°РµРј С‚РёРї СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ РґР»СЏ РґРѕРјРµРЅР° РїР°РЅРµР»Рё Рё РІС‹РїСѓСЃРєР°РµРј РµРіРѕ
  # РІ С€С‚Р°С‚РЅРѕРј initial_setup; РІС‹Р±РѕСЂ РЅРµ РґРѕР»Р¶РµРЅ РїРѕСЏРІР»СЏС‚СЊСЃСЏ РїРѕСЃСЂРµРґРё РјР°СЃС‚РµСЂР° РёРЅР±Р°СѓРЅРґРѕРІ.
  cert_type_ask force

  # --- 4) РРќР‘РђРЈРќР”Р«: РєР°РєРёРµ СЃС‚Р°РІРёС‚СЊ? (Enter вЂ” РІРµСЃСЊ РґРѕСЃС‚СѓРїРЅС‹Р№ РЅР°Р±РѕСЂ)
  echo -e "${B}Р’С‹Р±РµСЂРёС‚Рµ РґРѕСЃС‚СѓРїРЅС‹Рµ РґР»СЏ СЌС‚РѕР№ РїР°РЅРµР»Рё РёРЅР±Р°СѓРЅРґС‹:${N}"
  local i=1 entry entry_proto
  local -a CAND=()
  local _auto_flavor="${PANEL_FLAVOR:-$(detect_panel_flavor)}"
  for entry in "${RECOMMENDED_INBOUNDS[@]}"; do
    IFS='|' read -r _ entry_proto _ <<<"$entry"
    if [[ "$_auto_flavor" != "lucx" && "$entry_proto" != "vless" && "$entry_proto" != "hysteria" ]]; then
      continue
    fi
    printf "  %2d) %s\n" "$i" "${entry%%|*}"
    CAND+=("$entry"); i=$((i+1))
  done
  echo
  if [[ "$_auto_flavor" == "lucx" ]]; then
    echo "  Enter вЂ” СѓСЃС‚Р°РЅРѕРІРёС‚СЊ Р’РЎР• РґРѕСЃС‚СѓРїРЅС‹Рµ LucX-РёРЅР±Р°СѓРЅРґС‹"
  else
    echo "  Enter вЂ” СѓСЃС‚Р°РЅРѕРІРёС‚СЊ VLESS Рё Hysteria2"
  fi
  local choices=""
  ask choices "РќРѕРјРµСЂР° (С‡РµСЂРµР· РїСЂРѕР±РµР»)" "" '^[0-9 ]*$'
  local -a SEL=()
  local num
  if [[ -z "$choices" ]]; then
    SEL=("${CAND[@]}")
  else
    for num in $choices; do
      (( num >= 1 && num <= ${#CAND[@]} )) && SEL+=("${CAND[$((num-1))]}") || warn "РџСЂРѕРїСѓСЃРє: $num"
    done
  fi
  [[ ${#SEL[@]} -eq 0 ]] && { warn "РќРёС‡РµРіРѕ РЅРµ РІС‹Р±СЂР°РЅРѕ вЂ” РёРЅР±Р°СѓРЅРґС‹ РЅРµ СЃРѕР·РґР°СЋС‚СЃСЏ"; }
  # VK call hashes СЃРїСЂР°С€РёРІР°СЋС‚СЃСЏ РІ С†РёРєР»Рµ СЃРѕР·РґР°РЅРёСЏ вЂ” РѕС‚РґРµР»СЊРЅРѕ РґР»СЏ РєР°Р¶РґРѕРіРѕ
  # qwdtt/csqtt, СЂСЏРґРѕРј СЃ РµРіРѕ РїРѕСЂС‚РѕРј (СЃРј. С€Р°Рі 5 РЅРёР¶Рµ).

  # РўРёРї СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ СѓР¶Рµ РІС‹Р±СЂР°РЅ РґРѕ РјР°СЃС‚РµСЂР° РёРЅР±Р°СѓРЅРґРѕРІ вЂ” Р·РґРµСЃСЊ РїРѕРІС‚РѕСЂРЅРѕ РЅРµ СЃРїСЂР°С€РёРІР°РµРј.

  # --- 3) SNI-РґРѕРјРµРЅС‹ РґР»СЏ TLS-РёРЅР±Р°СѓРЅРґРѕРІ (Enter вЂ” РїСЂРµС„РёРєСЃ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ)
  local -A PREFIX=( [vless-tcp]="r" [vless-xhttp]="rx" [naive-naive]="n" [anytls-anytls]="at" [trusttunnel-trusttunnel]="tt" [hysteria-hysteria]="h" )
  local -A SELDOM=()
  # --- 4c) Reality-РІРѕРїСЂРѕСЃС‹ (СЂРµР¶РёРј в†’ С†РµР»СЊ/РґРѕРјРµРЅ в†’ РїРѕСЂС‚ в†’ Р·Р°РіР»СѓС€РєР°) Р·Р°РґР°СЋС‚СЃСЏ
  #         РІ С†РёРєР»Рµ СЃРѕР·РґР°РЅРёСЏ вЂ” РїРѕ РєР°Р¶РґРѕРјСѓ РёРЅР±Р°СѓРЅРґСѓ, РЅР° РµРіРѕ РјРµСЃС‚Рµ РІ РѕС‡РµСЂРµРґРё.
  REALITY_EXT=false
  local -A REALITY_MODE=() REALITY_TGT=() REALITY_DECOY_TPL_BYID=()

  # (tg-РґРѕРјРµРЅ СЃРїСЂР°С€РёРІР°РµС‚СЃСЏ РІ С†РёРєР»Рµ СЃРѕР·РґР°РЅРёСЏ вЂ” РЅР° РјРµСЃС‚Рµ СЃР°РјРѕРіРѕ tg-РёРЅР±Р°СѓРЅРґР°)

  # (РїР°СЂРѕР»СЊ РїР°РЅРµР»Рё Рё РїРѕСЂС‚С‹/РїСѓС‚Рё СЃРїСЂР°С€РёРІР°СЋС‚СЃСЏ РІ РЅР°С‡Р°Р»Рµ вЂ” С€Р°Рі 1)
  # (РѕС‚РґРµР»СЊРЅС‹Р№ С†РёРєР» РґРѕРјРµРЅРѕРІ СѓР±СЂР°РЅ: РґРѕРјРµРЅ СЃРїСЂР°С€РёРІР°РµС‚СЃСЏ РІ С†РёРєР»Рµ СЃРѕР·РґР°РЅРёСЏ
  #  РїРµСЂРµРґ РїРѕСЂС‚РѕРј вЂ” В«SNI в†’ РїРѕСЂС‚ в†’ СЃР»РµРґСѓСЋС‰РёР№ РёРЅР±Р°СѓРЅРґВ»)
  # (decoy-С€Р°Р±Р»РѕРЅ СЃРїСЂР°С€РёРІР°РµС‚СЃСЏ РџРћ РљРђР–Р”РћРњРЈ РёРЅР±Р°СѓРЅРґСѓ, РµСЃР»Рё РЅСѓР¶РµРЅ СЃРІРѕР№ SNI:
  #  Reality Рё VLESS TCP TLS; XHTTP TLS СЂР°Р±РѕС‚Р°РµС‚ Р±РµР· decoy)

  # --- 5) РЎРѕР·РґР°РЅРёРµ РІС‹Р±СЂР°РЅРЅС‹С… РёРЅР±Р°СѓРЅРґРѕРІ. РџРѕСЂСЏРґРѕРє РІРѕРїСЂРѕСЃРѕРІ РЅР° РљРђР–Р”Р«Р™ РёРЅР±Р°СѓРЅРґ:
  #        reality: СЃРІРѕР№/С‡СѓР¶РѕР№ в†’ (С†РµР»СЊ | SNI-РґРѕРјРµРЅ) в†’ РїРѕСЂС‚ в†’ Р·Р°РіР»СѓС€РєР° (СЃРІРѕР№ SNI)
  #        VLESS TCP TLS: SNI-РґРѕРјРµРЅ в†’ СЃРµСЂС‚ в†’ РїРѕСЂС‚ в†’ РІС‹Р±РѕСЂ decoy-Р·Р°РіР»СѓС€РєРё
  #        VLESS XHTTP TLS: SNI-РґРѕРјРµРЅ в†’ СЃРµСЂС‚ в†’ РїРѕСЂС‚, Р±РµР· decoy
  # Р’С‹РїСѓСЃРє СЃРµСЂС‚РѕРІ РћРўРљР›РђР”Р«Р’РђР•Рњ (CERT_DEFER=1): cert_issue Р»РёС€СЊ СЂРµРіРёСЃС‚СЂРёСЂСѓРµС‚
  # РґРѕРјРµРЅ РІ РµРіРѕ Р»РёРЅРёРё, Р° РІС‹РїСѓСЃРєР°РµС‚ Р»РёРЅРёРё РѕРґРЅРѕР№ РїР°С‡РєРѕР№ cert_batch_flush РІ
  # initial_setup. РРЅР°С‡Рµ РєР°Р¶РґС‹Р№ TLS-РёРЅР±Р°СѓРЅРґ РїРµСЂРµРёСЃРїСѓСЃРєР°Р» Р±С‹ Р»РёРЅРёСЋ РїР°РЅРµР»Рё
  # (SAN СЂР°СЃС‚С‘С‚) Рё СѓРїРёСЂР°Р»СЃСЏ РІ Р»РёРјРёС‚ Let's Encrypt 5 СЃРµСЂС‚РѕРІ/РЅРµРґРµР»СЋ РЅР° РґРѕРјРµРЅ.
  CERT_DEFER=1
  log "РЎРѕР·РґР°РЅРёРµ РёРЅР±Р°СѓРЅРґРѕРІвЂ¦"
  local -A A_DOM=()
  local -a used_ports=()
  local new_id=""
  for entry in "${SEL[@]}"; do
    IFS='|' read -r name proto transport security flow net <<<"$entry"
    INBOUND_CREATE_MODE="$security"
    local pfx="${PREFIX[$proto-$transport]:-}"
    local port sn="" dom="${SELDOM[$proto-$transport]:-}"
    # в”Ђв”Ђ CDN-РїСЂРѕС„РёР»СЊ С‚РѕР»СЊРєРѕ РґР»СЏ СЏРІРЅРѕ РІС‹Р±СЂР°РЅРЅРѕРіРѕ РїСѓРЅРєС‚Р° VLESS XHTTP (С‡РµСЂРµР· CDN):
    # СЃРѕР·РґР°С‘Рј СЃСЂР°Р·Сѓ Р±РµР· security, nginx С‚РµСЂРјРёРЅРёСЂСѓРµС‚ TLS. РћС‚РІРµС‚С‹ вЂ” РІ CDN_PRE_*,
    # РёС… РїРѕРґС…РІР°С‚РёС‚ xhttp_cdn_setup РїСЂРё configure_sni_for_inbound (РІ initial_setup).
    CDN_PRE_ANSWER=""; CDN_PRE_CDN=""; CDN_PRE_ORIGIN=""; CDN_PRE_PATH=""; CDN_PRE_TPL=""; CDN_PRE_PROVIDER=""
    local _is_cdn=false
    if [[ "$transport" == "xhttp" && "$security" != "reality" ]]; then
       if [[ "$name" == "VLESS XHTTP (С‡РµСЂРµР· CDN)" ]]; then
         # Р¤РёРєСЃРёСЂРѕРІР°РЅРЅС‹Р№ РїСѓРЅРєС‚ РѕР·РЅР°С‡Р°РµС‚ CDN Р±РµР· РґРѕРїРѕР»РЅРёС‚РµР»СЊРЅРѕРіРѕ y/n.
         _is_cdn=true
       elif [[ "$name" == "VLESS XHTTP TLS" ]]; then
         # РЇРІРЅС‹Р№ TLS-РїСѓРЅРєС‚: CDN РЅРµ СЃРїСЂР°С€РёРІР°РµРј.
         security="tls"
         _is_cdn=false
       elif [[ "$name" == "VLESS XHTTP" && "$proto" == "vless" && "$security" == "none" && -t 0 ]]; then
         local _cdn_ans=""
         echo
         askyn _cdn_ans "Р­С‚Рѕ СЃРѕРµРґРёРЅРµРЅРёРµ Р±СѓРґРµС‚ СЂР°Р±РѕС‚Р°С‚СЊ С‡РµСЂРµР· CDN (nginx TLS, РёРЅР±Р°СѓРЅРґ Р±РµР· security)?" "n"
         [[ "$_cdn_ans" == true ]] && _is_cdn=true
       fi
      if [[ "$_is_cdn" == true ]]; then
        cdn_ask_profile "0" "$proto"   # СЃРїСЂРѕСЃРёС‚ CDN/ORIGIN-РґРѕРјРµРЅС‹, РїСѓС‚СЊ, decoy
        CDN_PRE_ANSWER="true"
        CDN_PRE_CDN="$CDN_DOM"; CDN_PRE_ORIGIN="$CDN_ORIGIN"; CDN_PRE_PATH="$CDN_PATH"; CDN_PRE_TPL="$CDN_TPL"; CDN_PRE_PROVIDER="$CDN_PROVIDER"
        security="none"     # TLS С‚РµСЂРјРёРЅРёСЂСѓРµС‚ nginx вЂ” РёРЅР±Р°СѓРЅРґ СЃРѕР·РґР°С‘Рј РіРѕР»С‹Рј
        dom=""; sn=""       # SNI-РґРѕРјРµРЅ/СЃРµСЂС‚ РёРЅР±Р°СѓРЅРґСѓ РЅРµ РЅСѓР¶РЅС‹
        rdtpl=""
      fi
    fi
    # в”Ђв”Ђ Reality: СЂРµР¶РёРј + С†РµР»СЊ/РґРѕРјРµРЅ вЂ” РїСЂСЏРјРѕ Р·РґРµСЃСЊ, РїРµСЂРµРґ РїРѕСЂС‚РѕРј
    if [[ "$security" == "reality" ]]; then
      local e_key="$proto-$transport" rmode=""
      if [[ -t 0 ]]; then
        echo
        echo "  $name:"
        echo "   1) Р§СѓР¶РѕР№ СЂРµР°Р»РёС‚Рё В«РЅР°Р№С‚Рё С†РµР»РёВ» вЂ” Р·Р° 443 РїРѕ SNI С†РµР»Рё, СЃРµСЂС‚ РќР• РЅСѓР¶РµРЅ"
        echo "   2) РЎРІРѕР№ SNI-РґРѕРјРµРЅ вЂ” РЅСѓР¶РµРЅ СЃРµСЂС‚ + decoy"
        ask rmode "Р’С‹Р±РѕСЂ [1/2]" "1" '^[12]$'
      else
        rmode="1"
      fi
      REALITY_MODE["$e_key"]="$rmode"
      if [[ "$rmode" == "1" ]]; then
        REALITY_EXT=true
        local tgt=""
        reality_target_menu tgt "$name"
        REALITY_TGT["$e_key"]="$tgt"
        REALITY_EXT_TARGET="$tgt"
        printf '%s' "$tgt" > /tmp/.reality-found-target 2>/dev/null || true
        log "  $name: С†РµР»СЊ в†’ $tgt (dest+serverNames, Р·Р° 443 РїРѕ SNI С†РµР»Рё)"
      else
        local d=""
        if [[ -t 0 ]]; then
          ask d "Р”РѕРјРµРЅ РґР»СЏ $name (РЅСѓР¶РµРЅ СЃРµСЂС‚ + decoy)" "${pfx:-r}.$base" '^[a-zA-Z0-9.-]+$'
        else
          d="${pfx:-r}.$base"
        fi
        SELDOM["$e_key"]="$d"
        dom="$d"
      fi
    elif [[ -z "$dom" && -n "$pfx" && "${_is_cdn:-}" != true ]] && { [[ "$net" == "tcp" ]] || [[ "$proto" == "hysteria" ]]; }; then
      # в”Ђв”Ђ TLS: SNI-РґРѕРјРµРЅ (СЃРµСЂС‚ РїСЂРѕРІРµСЂРёРј СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ РїРѕСЂС‚Р°)
      if [[ -t 0 ]]; then
        local d=""
        ask d "Р”РѕРјРµРЅ РґР»СЏ $name (РЅСѓР¶РµРЅ СЃРµСЂС‚)" "$pfx.$base" '^[a-zA-Z0-9.-]+$'
        SELDOM["$proto-$transport"]="$d"
        dom="$d"
      else
        dom="$pfx.$base"
        SELDOM["$proto-$transport"]="$dom"
      fi
    fi
    # tg web proxy: РґРѕРјРµРЅ вЂ” Р·РґРµСЃСЊ Р¶Рµ, РїРµСЂРµРґ РµРіРѕ РїРѕСЂС‚РѕРј (РЅРµ В«РїРѕСЃР»Рµ РІСЃРµС… РёРЅР±Р°СѓРЅРґРѕРІВ»)
    if [[ "$proto" == "tproxy" && -t 0 ]]; then
      local tpd="${PANEL_DOMAIN:-$base}" base_dom="${PANEL_DOMAIN:-$base}" tdom_ask=""
      base_dom="${base_dom#*.}"
      [[ "$base_dom" != *.* ]] && base_dom="$tpd"
      ask tdom_ask "Р”РѕРјРµРЅ tg web proxy (Enter вЂ” tg.$base_dom)" "tg.$base_dom" '^[a-zA-Z0-9.-]+$'
      T_PROXY_DOMAIN="$tdom_ask"
    fi
    case "$proto" in
      tproxy) port=11443 ;;
      qwdtt)  port=56000 ;;
      csqtt)  port=46000 ;;
      *)      port=$(make_port) ;;
    esac
    # РїРѕСЂС‚: 443/80 РЅРµР»СЊР·СЏ (nginx), Р·Р°РЅСЏС‚С‹Рµ РґСЂСѓРіРёРјРё РёРЅР±Р°СѓРЅРґР°РјРё вЂ” РЅРµР»СЊР·СЏ
    if [[ -t 0 ]]; then
      local port_ok=false
      while [[ "$port_ok" != true ]]; do
        ask port "РџРѕСЂС‚ РґР»СЏ $name (Enter вЂ” $port)" "$port" '^[0-9]{2,5}$'
        if [[ "$port" == "443" ]]; then

          err "РџРѕСЂС‚ 443 Р·Р°РїСЂРµС‰С‘РЅ РґР»СЏ inbound вЂ” СЌС‚Рѕ С‚РѕР»СЊРєРѕ РІРЅРµС€РЅРёР№ SNI/nginx-РїРѕСЂС‚"

          continue

        fi

        if [[ "$port" == "80" ]]; then

          err "РџРѕСЂС‚ 80 Р·Р°РЅСЏС‚ ACME/nginx вЂ” РІС‹Р±РµСЂРё РґСЂСѓРіРѕР№"
          continue
        fi
        if [[ " ${used_ports[*]:-} " == *" $port "* ]]; then
          err "РџРѕСЂС‚ $port СѓР¶Рµ РЅР°Р·РЅР°С‡РµРЅ РґСЂСѓРіРѕРјСѓ РёРЅР±Р°СѓРЅРґСѓ РІ СЌС‚РѕР№ СѓСЃС‚Р°РЅРѕРІРєРµ"
          continue
        fi
        if [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && \
           [[ "$(sqlite3 "$XUI_DB" "SELECT COUNT(*) FROM inbounds WHERE port=$port;" 2>/dev/null || echo 0)" != "0" ]]; then
          err "РџРѕСЂС‚ $port СѓР¶Рµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ РёРЅР±Р°СѓРЅРґРѕРј РІ РїР°РЅРµР»Рё вЂ” РІС‹Р±РµСЂРё РґСЂСѓРіРѕР№"
          continue
        fi
        port_ok=true
      done
    fi
    used_ports+=("$port")
    # Р”Р»СЏ СЃРѕР±СЃС‚РІРµРЅРЅРѕРіРѕ Reality Рё VLESS TCP TLS СЃРїСЂР°С€РёРІР°РµРј РєРѕРЅРєСЂРµС‚РЅС‹Р№
    # decoy-С€Р°Р±Р»РѕРЅ. XHTTP TLS СЂР°Р±РѕС‚Р°РµС‚ РЅР°РїСЂСЏРјСѓСЋ С‡РµСЂРµР· SNI passthrough Рё
    # РЅР°РјРµСЂРµРЅРЅРѕ РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚ decoy.
    local rdtpl=""
    local _tpl_dom="${sni_domain:-${dom:-}}"
    local _needs_decoy_choice=false
    if [[ "$security" == "reality" && -n "$dom" ]]; then
      _needs_decoy_choice=true
    elif [[ "$proto" == "vless" && "$transport" != "xhttp" && "$security" == "tls" && -n "$_tpl_dom" ]]; then
      _needs_decoy_choice=true
    fi
    if [[ "$_needs_decoy_choice" == true ]]; then
      rdtpl="$(decoy_tpl_current "$_tpl_dom")"
      if [[ -t 0 ]]; then
        decoy_template_choose_impl rdtpl "Decoy-Р·Р°РіР»СѓС€РєР° РґР»СЏ ${_tpl_dom:-$name} (СЃС‚СЂР°РЅРёС†Р° РЅР° СЌС‚РѕРј РґРѕРјРµРЅРµ)" "$rdtpl"
      fi
    fi
    if [[ -n "$_tpl_dom" && -n "$rdtpl" ]]; then
      decoy_tpl_store_set "$_tpl_dom" "$rdtpl" >/dev/null 2>&1 || true
    fi
    # sn: TCP-РєР»Р°СЃСЃ TLS-РёРЅР±Р°СѓРЅРґС‹ Р hysteria (UDP, РЅРѕ TLS РѕР±СЏР·Р°С‚РµР»РµРЅ)
    if [[ -n "$dom" ]] && { [[ "$net" == "tcp" ]] || [[ "$proto" == "hysteria" ]]; }; then
      sn="$dom"
    fi
    local vkn=""
    if [[ "$proto" == "qwdtt" || "$proto" == "csqtt" ]]; then
      # VK call hashes: СЂР°РЅСЊС€Рµ РїРµСЂРµРјРµРЅРЅР°СЏ Р±С‹Р» РїСѓСЃС‚РѕР№, Р° РІРѕРїСЂРѕСЃ РѕС‚СЃСѓС‚СЃС‚РІРѕРІР°Р» вЂ”
      # РёРЅР±Р°СѓРЅРґС‹ СЃРѕР·РґР°РІР°Р»РёСЃСЊ СЃ РїСѓСЃС‚С‹РјРё hash. РЎРїСЂР°С€РёРІР°РµРј СЏРІРЅРѕ, РєР°Рє РІ Рї.2.
      if [[ -t 0 ]]; then
        ask vkn "VK call hashes РґР»СЏ $name (С‡РµСЂРµР· Р·Р°РїСЏС‚СѓСЋ, Р‘Р•Р— РїСЂРѕР±РµР»РѕРІ; Enter вЂ” РїСЂРѕРїСѓСЃС‚РёС‚СЊ)" "" '^[a-zA-Z0-9,_-]*$'
      fi
    fi
    # CDN-XHTTP РЅРµ РїРѕР»СѓС‡Р°РµС‚ РѕС‚РґРµР»СЊРЅС‹Р№ SNI/decoy: РµРіРѕ РґРѕРјРµРЅС‹ Рё decoy
    # Р·Р°РїСЂР°С€РёРІР°СЋС‚СЃСЏ С‚РѕР»СЊРєРѕ РІ CDN-РїСЂРѕС„РёР»Рµ РЅРёР¶Рµ.
    # РЎРµСЂС‚РёС„РёРєР°С‚ РЅСѓР¶РµРЅ TLS-РёРЅР±Р°СѓРЅРґР°Рј Рё СЃРѕР±СЃС‚РІРµРЅРЅРѕРјСѓ SNI Reality:
    # РґР»СЏ Reality-СЂРµР¶РёРјР° 2 nginx/decoy РѕР±СЃР»СѓР¶РёРІР°РµС‚ РґРѕРјРµРЅ, РїРѕСЌС‚РѕРјСѓ СЃРµСЂС‚РёС„РёРєР°С‚
    # РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ РІС‹РїСѓС‰РµРЅ РґРѕ РіРµРЅРµСЂР°С†РёРё РјР°СЂС€СЂСѓС‚Р°, РєР°Рє Рё РґР»СЏ РѕР±С‹С‡РЅРѕРіРѕ TLS.
    # РўРёРї (wildcard/РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№) СѓС‡С‚С‘РЅ РІРЅСѓС‚СЂРё cert_issue: РїСЂРё Р¶РёРІРѕРј wildcard
    # СЌС‚Рѕ no-op (РїРµСЂРµРёСЃРїРѕР»СЊР·СѓРµС‚ РµРіРѕ), РёРЅР°С‡Рµ РІС‹РїСѓСЃРєР°РµС‚СЃСЏ РїРµСЂСЃРѕРЅР°Р»СЊРЅС‹Р№ СЃРµСЂС‚РёС„РёРєР°С‚.
    local _own_reality=false
    [[ "$security" == "reality" && "${REALITY_MODE[$proto-$transport]:-}" == "2" ]] && _own_reality=true
    if [[ -n "$dom" ]] && { [[ "$net" == "tcp" && "$security" == "tls" ]] || [[ "$proto" == "hysteria" ]] || [[ "$_own_reality" == true ]]; }; then
      log "  РЎРµСЂС‚РёС„РёРєР°С‚ РґР»СЏ $dom: РїСЂРѕРІРµСЂРєР°/РІС‹РїСѓСЃРє РїРµСЂРµРґ РЅР°СЃС‚СЂРѕР№РєРѕР№ $name"
      cert_issue "$dom" || warn "  РРўРћР“: СЃРµСЂС‚ $dom РќР• РІС‹РїСѓС‰РµРЅ вЂ” $name (${proto}) РЅРµ РїРѕРґРЅРёРјРµС‚СЃСЏ; РґРѕРєР°С‚Рё РїРѕР·Р¶Рµ: РЎРµСЂС‚РёС„РёРєР°С‚С‹ в†’ РѕР±РЅРѕРІРёС‚СЊ (РїСЂРёС‡РёРЅР° РІС‹С€Рµ)"
    fi
    local remark
    remark=$(inbound_remark_next "$proto" "$transport" "$security")
    # С†РµР»СЊ В«С‡СѓР¶РѕРіРѕ СЂРµР°Р»РёС‚РёВ» СѓР¶Рµ РІ REALITY_EXT_TARGET (С€Р°Рі РІС‹С€Рµ)
    new_id=$(create_inbound_db "$proto" "$transport" "$security" "$flow" "$port" "$remark" "$net" "$sn" "$vkn") || true
    if [[ -n "$new_id" ]]; then
      if [[ "${_is_cdn:-false}" == true ]]; then
        CDN_FORCE_IDS="${CDN_FORCE_IDS:-} $new_id"
        # РџСЂРѕС„РёР»СЊ CDN РЅСѓР¶РЅРѕ РїСЂРёРјРµРЅРёС‚СЊ СЃСЂР°Р·Сѓ Рє СЃРѕР·РґР°РЅРЅРѕР№ СЃС‚СЂРѕРєРµ Р‘Р”:
        # initial_setup Р·Р°РїСѓСЃРєР°РµС‚СЃСЏ РїРѕР·Р¶Рµ Рё РЅРµ РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ РµРґРёРЅСЃС‚РІРµРЅРЅС‹Рј РјРµСЃС‚РѕРј,
        # РіРґРµ РїС‹С‚Р°РµРјСЃСЏ Р·Р°РїРѕР»РЅРёС‚СЊ stream_settings/hosts.
        xhttp_cdn_setup "$new_id" "$proto" "$port" || warn "  CDN-РїСЂРѕС„РёР»СЊ РґР»СЏ #$new_id РЅРµ РїСЂРёРјРµРЅС‘РЅ вЂ” РїРѕРІС‚РѕСЂРё РЅР°СЃС‚СЂРѕР№РєСѓ РёРЅР±Р°СѓРЅРґР°"
      fi
      log "  в†’ #$new_id $remark :$port${sn:+ (SNI $sn)}"
      [[ -n "$dom" ]] && A_DOM["$new_id"]="$dom"
      # СЃРІРѕСЏ Р·Р°РіР»СѓС€РєР° РЅР° СЌС‚РѕС‚ РёРЅР±Р°СѓРЅРґ (РґР»СЏ initial_setup)
      [[ -n "$rdtpl" ]] && REALITY_DECOY_TPL_BYID["$new_id"]="$rdtpl"
    else
      warn "$name РЅРµ СЃРѕР·РґР°РЅ"
    fi
  done
  systemctl restart x-ui 2>/dev/null || true
  sleep 5

  # --- 6) initial_setup СЃ РіРѕС‚РѕРІС‹РјРё РѕС‚РІРµС‚Р°РјРё (РїРѕСЂСЏРґРѕРє РІРѕРїСЂРѕСЃРѕРІ СЃС‚Р°Р±РёР»РµРЅ)
  local ansf="/root/ans-auto-$(date +%H%M%S).txt"
  {
    le_email_load || true
    if [[ -z "$EMAIL" ]]; then
      err "Email Let's Encrypt РЅРµ Р·Р°РґР°РЅ вЂ” Р°РІС‚РѕРїРѕРґСЉС‘Рј РѕСЃС‚Р°РЅРѕРІР»РµРЅ. РЈРєР°Р¶Рё email РІ Р°РЅРєРµС‚Рµ/РїРµСЂРµРјРµРЅРЅРѕР№ EMAIL."
      return 1
    fi
    echo "$EMAIL"                              # EMAIL
    # РћСЃС‚Р°Р»СЊРЅС‹Рµ РѕС‚РІРµС‚С‹ РќР• РїРѕР·РёС†РёРѕРЅРЅС‹Рµ Рё СЃСЋРґР° РЅРµ РїРёС€РµРј: initial_setup РІ РЅРµ-TTY
    # Р±РµСЂС‘С‚ РёС… РёР· РіР»РѕР±Р°Р»СЊРЅС‹С… РјР°СЃС‚РµСЂР° (A_DOM/REALITY_DECOY_TPL_BYID) Рё РґРµС„РѕР»С‚РѕРІ.
    # Р Р°РЅСЊС€Рµ Р·РґРµСЃСЊ РїРёСЃР°Р»РёСЃСЊ СЃС‚СЂРѕРєРё В«СЃРєСЂС‹С‚СЊ/РґРѕРјРµРЅ/С€Р°Р±Р»РѕРЅВ» РїРѕ РёРЅР±Р°СѓРЅРґР°Рј вЂ” Р±СЋРґР¶РµС‚
    # СЃС‚СЂРѕРє СЂР°Р·СЉРµР·Р¶Р°Р»СЃСЏ СЃ С„Р°РєС‚РёС‡РµСЃРєРёРјРё РІРѕРїСЂРѕСЃР°РјРё Рё СЂРІР°Р» РїРѕС‚РѕРє РЅР° EOF.
    # Р—Р°РІРµСЂС€Р°СЋС‰РёР№ Enter РЅРµ РґР°С‘С‚ EOF РїСЂРµРІСЂР°С‚РёС‚СЊ РїРѕСЃР»РµРґРЅРёР№ РІРѕРїСЂРѕСЃ РІ С†РёРєР».
    echo ""
  } > "$ansf"
  log "РџРµСЂРІРёС‡РЅР°СЏ РЅР°СЃС‚СЂРѕР№РєР° (Р°РІС‚РѕРѕС‚РІРµС‚С‹: $ansf)вЂ¦"
  initial_setup < "$ansf" > >(tee /tmp/stack-initial-setup.log /tmp/auto-setup.log) 2>&1 || warn "initial_setup РІРµСЂРЅСѓР» РѕС€РёР±РєСѓ вЂ” СЃРјРѕС‚СЂРё /tmp/stack-initial-setup.log"
  grep -E "\[\+\]|\[!\]|\[x\]" /tmp/stack-initial-setup.log 2>/dev/null | tail -12
  CERT_DEFER=0   # СЃС‚СЂР°С…РѕРІРєР°: РѕС‚Р»РѕР¶РµРЅРЅС‹Р№ РІС‹РїСѓСЃРє РЅРµ РґРѕР»Р¶РµРЅ В«РїСЂРѕС‚РµС‡СЊВ» РІ РјРµРЅСЋ

  # --- 2СЃ) Р›РѕРіРёРЅ/РїР°СЂРѕР»СЊ AdGuard, Р·Р°РґР°РЅРЅС‹Рµ РїСЂРё СѓСЃС‚Р°РЅРѕРІРєРµ: РїСЂРёРјРµРЅСЏРµРј Р’РЎР•Р“Р”Рђ
  #         (РґР°Р¶Рµ РµСЃР»Рё Сѓ AdGuard СѓР¶Рµ Р±С‹Р»Рё РїРѕР»СЊР·РѕРІР°С‚РµР»Рё вЂ” РІС‹Р±РѕСЂ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ РІР°Р¶РЅРµРµ)
  if [[ "$ADG_PRESENT" == true && -n "${U_ADG_PASS:-}" ]]; then
    U_ADG_USER="${U_ADG_USER:-admin}"
    if adg_set_admin "$U_ADG_USER" "$U_ADG_PASS"; then
      log "Р›РѕРіРёРЅ/РїР°СЂРѕР»СЊ AdGuard СѓСЃС‚Р°РЅРѕРІР»РµРЅС‹ ($U_ADG_USER) вЂ” Р·Р°РґР°РЅС‹ РїСЂРё СѓСЃС‚Р°РЅРѕРІРєРµ"
      printf 'AdGuard Home вЂ” %s\n  Р›РѕРіРёРЅ:  %s\n  РџР°СЂРѕР»СЊ: %s\n' "$(date "+%Y-%m-%d %H:%M:%S")" "$U_ADG_USER" "$U_ADG_PASS" > /root/adguard-credentials.txt
      chmod 600 /root/adguard-credentials.txt
    else
      warn "РќРµ СѓРґР°Р»РѕСЃСЊ СѓСЃС‚Р°РЅРѕРІРёС‚СЊ РєСЂРµРґС‹ AdGuard вЂ” РїСЂРёС‡РёРЅР° РІС‹С€Рµ"
    fi
  fi

  # --- 3) UFW: SSH + 443 + СЃР»СѓС€Р°СЋС‰РёРµ РїРѕСЂС‚С‹ С‚СѓРЅРЅРµР»РµР№; РїР°РЅРµР»СЊРЅС‹Рµ РїРѕСЂС‚С‹ РІ DENY
  firewall_apply

  # --- 3c) РђРІС‚РѕРїРѕС‡РёРЅРєР° РїСЂР°РІРѕРє РїР°РЅРµР»Рё (РєР°Р¶РґС‹Рµ 2 РјРёРЅ; С‚СЂРѕРіР°РµС‚ x-ui С‚РѕР»СЊРєРѕ РїСЂРё РЅР°С…РѕРґРєРµ)
  # --- 4) РРўРћР“
  local pp="" panel_pass adg_pass adg_user
  pp=$(xui_get webBasePath 2>/dev/null || true)
  pp="/${pp#/}"
  panel_pass=$(grep -i "РїР°СЂРѕР»СЊ" /root/panel-credentials.txt 2>/dev/null | awk '{print $NF}' | head -1)
  local panel_user=""
  panel_user=$(grep -i "Р»РѕРіРёРЅ" /root/panel-credentials.txt 2>/dev/null | awk '{print $NF}' | head -1)
  adg_pass=$(grep -i "РїР°СЂРѕР»СЊ" /root/adguard-credentials.txt 2>/dev/null | awk '{print $NF}' | head -1)
  adg_user=$(grep -i "Р»РѕРіРёРЅ"  /root/adguard-credentials.txt 2>/dev/null | awk '{print $NF}' | head -1)
  line
  echo -e "${G}   РРўРћР“ РЈРЎРўРђРќРћР’РљР${N}"
  line
  echo "  РџРђРќР•Р›Р¬:  https://$base$pp"
  echo "           Р»РѕРіРёРЅ: ${panel_user:-${U_PANEL_USER:-admin}}   РїР°СЂРѕР»СЊ: ${panel_pass:-СЃРј. /root/panel-credentials.txt}"
  if [[ "$ADG_PRESENT" == true ]]; then
    echo "  ADGUARD: https://$base/   (DoH: https://$base/dns-query)"
    echo "           Р»РѕРіРёРЅ: ${adg_user:-admin}   РїР°СЂРѕР»СЊ: ${adg_pass:-СЃРј. /root/adguard-credentials.txt}"
  fi
  echo "  РРќР‘РђРЈРќР”Р«:"
  sqlite3 "$XUI_DB" "SELECT id, protocol, port, remark FROM inbounds WHERE enable=1 ORDER BY id;" 2>/dev/null \
    | awk -F"|" '{printf "    #%s  %-12s :%-6s %s\n", $1, $2, $3, $4}'
  echo "  UFW:     Р°РєС‚РёРІРµРЅ (SSH+443+С‚СѓРЅРЅРµР»Рё; :80 Р·Р°РєСЂС‹С‚; РїР°РЅРµР»СЊРЅС‹Рµ РїРѕСЂС‚С‹ DENY)"
  line
  echo "  РЈСЃС‚Р°РЅРѕРІРєР° Р·Р°РІРµСЂС€РµРЅР°. РќР°Р¶РјРёС‚Рµ Enter РґР»СЏ РІРѕР·РІСЂР°С‚Р° РІ РіР»Р°РІРЅРѕРµ РјРµРЅСЋ."
  echo "  Р›РѕРіРёРЅС‹ Рё РїР°СЂРѕР»Рё РїСЂРѕРґСѓР±Р»РёСЂРѕРІР°РЅС‹:"
  echo "    РїР°РЅРµР»СЊ  в†’ /root/panel-credentials.txt"
  [[ "$ADG_PRESENT" == true ]] && echo "    adguard в†’ /root/adguard-credentials.txt"
  line
  stack_mark_configured || warn "РќРµ СѓРґР°Р»РѕСЃСЊ СЃРѕС…СЂР°РЅРёС‚СЊ РјР°СЂРєРµСЂ РЅР°СЃС‚СЂРѕР№РєРё; Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРёРµ РёСЃРїСЂР°РІР»РµРЅРёСЏ РѕСЃС‚Р°РЅСѓС‚СЃСЏ РѕС‚РєР»СЋС‡РµРЅС‹."
  pause
  return 0
}

# =====================================================================
# РўРћР§РљРђ Р’РҐРћР”Рђ (С‚РѕР»СЊРєРѕ РїСЂРё РїСЂСЏРјРѕРј Р·Р°РїСѓСЃРєРµ; РїСЂРё source С„СѓРЅРєС†РёРё РґРѕСЃС‚СѓРїРЅС‹ РґР»СЏ С‚РµСЃС‚Р°)
# =====================================================================
if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  # рџ¤– РІСЃС‚СЂРѕРµРЅРЅС‹Р№ TG-Р±РѕС‚: bash stack-manager.sh --bot (СЋРЅРёС‚ tg-stack-bot.service).
  # Р¤СѓРЅРєС†РёРё Р±РѕС‚Р° РѕРїСЂРµРґРµР»РµРЅС‹ РІ 196-bot.sh; run_bot СЃР°Рј РґРµР»Р°РµС‚ РІСЃРµ РїСЂРѕРІРµСЂРєРё.
  if [[ "${1:-}" == "--bot" ]]; then
    run_bot
    exit $?
  fi
  # рџ©є СЂР°Р·РѕРІР°СЏ read-only РїСЂРѕРІРµСЂРєР° Р·РґРѕСЂРѕРІСЊСЏ Р±РµР· РјРµРЅСЋ: bash stack-manager.sh --status
  # (С‚РѕС‚ Р¶Рµ РЅР°Р±РѕСЂ, С‡С‚Рѕ РІ СЃР°РјРѕРґРёР°РіРЅРѕСЃС‚РёРєРµ; exit-РєРѕРґ 1 вЂ” РµСЃС‚СЊ РїСЂРѕР±Р»РµРјС‹, СѓРґРѕР±РЅРѕ РґР»СЏ cron)
  if [[ "${1:-}" == "--status" ]]; then
    detect_env
    stack_doctor
    exit $?
  fi
  # СЃС‚СЂР°С…РѕРІРєР°: РµСЃР»Рё В«Р°СЂРµРЅРґР°В» СЃРЅСЏС‚РёСЏ Р·Р°С‰РёС‚С‹ Р‘Р” РѕСЃС‚Р°Р»Р°СЃСЊ РІРёСЃРµС‚СЊ вЂ” СЃРЅСЏС‚СЊ РЅР° РІС‹С…РѕРґРµ
  if [[ "${1:-}" == "--check" || "${1:-}" == "--self-test" ]]; then
    detect_env
    stack_full_audit
    exit $?
  fi
  # РЎРўР РћР“РР™ Р‘Р•Р—РћРџРђРЎРќР«Р™ РЎРўРђР Рў:
  # РїРѕРєР° РїРѕР»СЊР·РѕРІР°С‚РµР»СЊ СЏРІРЅРѕ РЅРµ Р·Р°РІРµСЂС€РёР» РїРµСЂРІРёС‡РЅСѓСЋ РЅР°СЃС‚СЂРѕР№РєСѓ, Р·Р°РїСѓСЃРє СЃРєСЂРёРїС‚Р°
  # РЅРёС‡РµРіРѕ РЅРµ РїРёС€РµС‚ Рё РЅРµ РїРµСЂРµР·Р°РїСѓСЃРєР°РµС‚. Р”Р°Р¶Рµ Р±СЌРєР°Рї, hook, nginx, x-ui Рё heal
  # Р·РґРµСЃСЊ Р·Р°РїСЂРµС‰РµРЅС‹ вЂ” СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ СЃС‚РµРє РїСЂРёРЅР°РґР»РµР¶РёС‚ РїРѕР»СЊР·РѕРІР°С‚РµР»СЋ.
  # check_os/ensure_deps РјРѕРіСѓС‚ РјРµРЅСЏС‚СЊ РїР°РєРµС‚С‹ Рё РєРѕРЅС„РёРіСѓСЂР°С†РёСЋ, РїРѕСЌС‚РѕРјСѓ РґРѕ
  # СЏРІРЅРѕР№ РЅР°СЃС‚СЂРѕР№РєРё РІС‹РїРѕР»РЅСЏРµРј С‚РѕР»СЊРєРѕ РѕРїСЂРµРґРµР»РµРЅРёРµ РѕРєСЂСѓР¶РµРЅРёСЏ.
  detect_env
  if stack_is_configured; then
    ensure_deps || { err "РќРµРІРѕР·РјРѕР¶РЅРѕ РїСЂРѕРґРѕР»Р¶РёС‚СЊ Р±РµР· РѕР±СЏР·Р°С‚РµР»СЊРЅС‹С… Р·Р°РІРёСЃРёРјРѕСЃС‚РµР№"; exit 1; }
    backfill_country_remarks
    if nginx_stream_module_enable && ensure_stream_include; then
      ss -tlnH 'sport = :443' 2>/dev/null | grep -q . || nginx_reload >/dev/null 2>&1 || true
    fi
    [[ -f /var/run/reboot-required ]] && warn "РЎРёСЃС‚РµРјР° Р¶РґС‘С‚ РџР•Р Р•Р—РђР“Р РЈР—РљРЈ (РѕР±РЅРѕРІР»РµРЅРѕ СЏРґСЂРѕ) вЂ” РѕС‚РєСЂРѕР№С‚Рµ СЂР°Р·РґРµР» 6 в†’ РґРёР°РіРЅРѕСЃС‚РёРєР°."
    mkdir -p "$BACKUP_DIR" 2>/dev/null || true
    touch "$BACKUP_DIR/.stack-ever-ran" 2>/dev/null || true
    auto_backup_stack
  else
    warn "Р‘РµР·РѕРїР°СЃРЅС‹Р№ РїРµСЂРІС‹Р№ Р·Р°РїСѓСЃРє: СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёР№ СЃРµСЂРІРµСЂ РЅРµ РёР·РјРµРЅСЏРµС‚СЃСЏ."
    warn "РћС‚РєСЂРѕР№С‚Рµ РјРµРЅСЋ Рё СЏРІРЅРѕ Р·Р°РїСѓСЃС‚РёС‚Рµ РїРµСЂРІРёС‡РЅСѓСЋ РЅР°СЃС‚СЂРѕР№РєСѓ, РєРѕРіРґР° Р±СѓРґРµС‚Рµ РіРѕС‚РѕРІС‹."
  fi
  [[ -f "$WILDCARD_STATE" ]] && WILDCARD_DOMAIN=$(head -n 1 "$WILDCARD_STATE" 2>/dev/null | tr -d '[:space:]' || true)
  # wildcard РІРёРґРµРЅ РІ РјРµРЅСЋ СЃРµСЂС‚РёС„РёРєР°С‚РѕРІ Рё РґРёР°РіРЅРѕСЃС‚РёРєРµ вЂ” РЅР° СЃС‚Р°СЂС‚Рµ РЅРµ С€СѓРјРёРј

  # РџРћР РЇР”РћРљ Р’РђР–Р•Рќ: СЃРЅР°С‡Р°Р»Р° РџРђРќР•Р›Р¬ + РµС‘ СЃРµСЂС‚РёС„РёРєР°С‚, РїРѕС‚РѕРј AdGuard
  # (AdGuard Р±РµСЂС‘С‚ СЃРµСЂС‚РёС„РёРєР°С‚ РїР°РЅРµР»Рё/wildcard РґР»СЏ СЃРІРѕРµРіРѕ https).
  auto_full=false   # РќР• local: С‚РѕС‡РєР° РІС…РѕРґР° вЂ” РІРЅРµ С„СѓРЅРєС†РёРё
  if [[ -z "$XUI_DB" || ! -f "$XUI_DB" ]]; then
    warn "x-ui.db РЅРµ РЅР°Р№РґРµРЅ вЂ” РїР°РЅРµР»СЊ (LucX UI / 3x-ui) РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°."
    echo "  РЈСЃС‚Р°РЅРѕРІРєР° РґРѕСЃС‚СѓРїРЅР° С‡РµСЂРµР· Рї.7 вЂ” РџР°РЅРµР»СЊ Рё AdGuard в†’ РЈРїСЂР°РІР»РµРЅРёРµ LucX/3x-ui."
    echo "  Р•СЃР»Рё СѓР¶Рµ СЃС‚РѕРёС‚ РѕСЂРёРіРёРЅР°Р»СЊРЅС‹Р№ 3x-ui вЂ” СѓР±РµРґРёСЃСЊ, С‡С‚Рѕ x-ui.db РІ /etc/x-ui/."
    install_now=""
    askyn install_now "РЈСЃС‚Р°РЅРѕРІРёС‚СЊ РїР°РЅРµР»СЊ LucX UI СЃРµР№С‡Р°СЃ?" "n"
    if [[ "$install_now" == true ]]; then
      # Р•Р”РРќР«Р™ РџРЈРўР¬: РєСЂРµРґС‹/РїРѕСЂС‚С‹ РїР°РЅРµР»Рё СЃРѕР±РёСЂР°РµРј Р”Рћ СѓСЃС‚Р°РЅРѕРІРєРё вЂ” С‚РµРј Р¶Рµ
      # ask_panel_creds, С‡С‚Рѕ Рё РїСЂРё РїРµСЂРµСѓСЃС‚Р°РЅРѕРІРєРµ (Рї.17). РРЅР°С‡Рµ РїР°РЅРµР»СЊ СЃС‚Р°РІРёС‚СЃСЏ
      # СЃ РїР°СЂРѕР»РµРј-РІ-РѕРґРёРЅ-РІРѕРїСЂРѕСЃ, Р° ask_panel_creds РїРѕСЃР»Рµ СѓСЃС‚Р°РЅРѕРІРєРё СѓС…РѕРґРёС‚ РІ
      # РІРµС‚РєСѓ В«СѓР¶Рµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР°В» Рё Р»РѕРіРёРЅ/РїРѕСЂС‚С‹ РЅРµ СЃРїСЂР°С€РёРІР°СЋС‚СЃСЏ РЅРёРєРѕРіРґР°.
      ask_panel_creds || warn "РљСЂРµРґС‹ РїР°РЅРµР»Рё РЅРµ СЃРѕР±СЂР°РЅС‹ вЂ” СЃС‚Р°РІР»СЋ СЃРѕ Р·РЅР°С‡РµРЅРёСЏРјРё РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ"
      install_lucx_panel || warn "РЈСЃС‚Р°РЅРѕРІРєР° РЅРµ СѓРґР°Р»Р°СЃСЊ вЂ” РјРѕР¶РЅРѕ РїРѕРІС‚РѕСЂРёС‚СЊ С‡РµСЂРµР· Рї.7."
      [[ -n "$XUI_DB" && -f "$XUI_DB" ]] && auto_full=true
    else
      warn "РџР°РЅРµР»СЊ РЅРµ СѓСЃС‚Р°РЅРѕРІР»РµРЅР° вЂ” РјРµРЅСЋ РѕС‚РєСЂРѕРµС‚СЃСЏ, СѓСЃС‚Р°РЅРѕРІРєР° РґРѕСЃС‚СѓРїРЅР° С‡РµСЂРµР· Рї.7."
    fi
  fi

  # С‡РёСЃС‚Р°СЏ СѓСЃС‚Р°РЅРѕРІРєР° в†’ Р°РІС‚Рѕ: РёРЅР±Р°СѓРЅРґС‹ + РЅР°СЃС‚СЂРѕР№РєР° + UFW + РёС‚РѕРіРѕРІР°СЏ СЃРІРѕРґРєР°
  if [[ "$auto_full" == true ]]; then
    auto_full_setup || warn "РђРІС‚РѕРїРѕРґСЉС‘Рј РїСЂРѕС€С‘Р» РЅРµ РїРѕР»РЅРѕСЃС‚СЊСЋ вЂ” РґРѕРґРµР»Р°Р№ РІ РјРµРЅСЋ (Рї.1 Рё Рї.10)."
  fi

  main_menu
fi











